/**
 * Electron module stub for IPC handler testing under Node.js/tsx.
 *
 * Intercepts `require('electron')` and `require('electron-log/main')` to
 * redirect them to real CJS mock files (__electron_mock.cjs, __electron_log_mock.cjs).
 * Using real files instead of in-memory mocks lets c8 properly track coverage
 * for modules loaded through the standard CJS pipeline.
 *
 * Usage:
 *   1. `import { setupElectronStub, getHandlers, ... } from './electron-stub'`
 *   2. `setupElectronStub()` — must be called BEFORE importing any IPC module
 *   3. `await import('../../ipc/foo.ipc')` — dynamic import after stub is active
 *   4. `registerFooIpc(mockMainWindow)` — call the register function
 *   5. `getHandlers().get('foo:list')` — access captured handler functions
 */
import Module from 'node:module'
import path from 'node:path'

// ── Resolved paths to CJS mock files ────────────────────────────────────────

const electronMockPath = path.resolve(__dirname, '__electron_mock.cjs')
const electronLogMockPath = path.resolve(__dirname, '__electron_log_mock.cjs')

// ── Lazy reference to the CJS mock's state ──────────────────────────────────

let _mockModule: any = null

function getMock(): any {
  if (!_mockModule) {
    _mockModule = require(electronMockPath)
  }
  return _mockModule
}

/** All handlers registered via `ipcMain.handle(channel, fn)` */
export function getHandlers(): Map<string, Function> {
  return getMock().__capturedHandlers
}

/**
 * capturedHandlers — legacy Map interface for backward compatibility.
 * After setupElectronStub() is called, this delegates to the CJS mock's map.
 */
export const capturedHandlers = {
  get(channel: string): Function | undefined {
    return getHandlers().get(channel)
  },
  set(channel: string, handler: Function): Map<string, Function> {
    return getHandlers().set(channel, handler)
  },
  has(channel: string): boolean {
    return getHandlers().has(channel)
  },
  keys(): IterableIterator<string> {
    return getHandlers().keys()
  },
  entries(): IterableIterator<[string, Function]> {
    return getHandlers().entries()
  },
  values(): IterableIterator<Function> {
    return getHandlers().values()
  },
  get size(): number {
    return getHandlers().size
  },
  clear(): void {
    getHandlers().clear()
  },
  forEach(fn: (value: Function, key: string) => void): void {
    getHandlers().forEach(fn)
  },
  [Symbol.iterator](): IterableIterator<[string, Function]> {
    return getHandlers().entries()
  },
} as unknown as Map<string, Function>

/** Events sent via BrowserWindow.webContents.send */
export const sentEvents: Array<{ channel: string; data: unknown }> = []

/** Mock event that passes validateSender */
export const mockEvent = {
  senderFrame: { url: 'file:///app/index.html' }
} as unknown as Electron.IpcMainInvokeEvent

/** Mock BrowserWindow instance */
export const mockMainWindow = {
  webContents: {
    send: (channel: string, data: unknown): void => {
      sentEvents.push({ channel, data })
    },
    on: () => {},
    removeListener: () => {},
    removeAllListeners: () => {},
    id: 1,
  },
  on: () => {},
  removeListener: () => {},
  isDestroyed: () => false,
  isVisible: () => true,
  show: () => {},
  hide: () => {},
  close: () => {},
  focus: () => {},
} as unknown as Electron.BrowserWindow

/** Reset all captured state */
export function resetStub(): void {
  getHandlers().clear()
  getMock().__capturedOnHandlers.clear()
  getMock().__sentEvents.length = 0
  sentEvents.length = 0
}

// ── Module interception ─────────────────────────────────────────────────────

let stubInstalled = false

/**
 * Install the electron module stub. Must be called BEFORE dynamically importing
 * any IPC module that does `import { ipcMain } from 'electron'`.
 *
 * Hooks both `_resolveFilename` and `_load` so c8 can track coverage properly.
 * Safe to call multiple times — only installs once.
 */
export function setupElectronStub(): void {
  if (stubInstalled) return
  stubInstalled = true

  // Pre-load the mock module to initialize its state
  _mockModule = require(electronMockPath)

  // Hook _resolveFilename — primary hook for c8 compatibility
  const origResolve = (Module as any)._resolveFilename
  ;(Module as any)._resolveFilename = function (request: string, ...args: any[]) {
    if (request === 'electron') {
      return electronMockPath
    }
    if (request === 'electron-log/main' || request === 'electron-log') {
      return electronLogMockPath
    }
    return origResolve.call(this, request, ...args)
  }

  // Hook _load — fallback for edge cases
  const origLoad = (Module as any)._load
  ;(Module as any)._load = function (request: string, parent: any, isMain: boolean) {
    if (request === 'electron') {
      return _mockModule
    }
    if (request === 'electron-log/main' || request === 'electron-log') {
      return require(electronLogMockPath)
    }
    // Handle Vite ?raw imports for .sql files — read as plain text string
    if (request.endsWith('.sql?raw') || (request.endsWith('.sql') && parent?.filename)) {
      const fs = require('node:fs') as typeof import('node:fs')
      const resolved = request.replace(/\?raw$/, '')
      const absPath = path.resolve(path.dirname(parent.filename), resolved)
      return fs.readFileSync(absPath, 'utf-8')
    }
    return origLoad.call(this, request, parent, isMain)
  }
}

/**
 * Invoke a captured IPC handler with mock event and args.
 * Returns the handler result or throws the handler error.
 */
export async function invokeHandler(
  channel: string,
  args?: unknown
): Promise<unknown> {
  const handlers = getHandlers()
  const handler = handlers.get(channel)
  if (!handler) {
    throw new Error(
      `No handler captured for channel: ${channel}. Available: ${[...handlers.keys()].join(', ')}`
    )
  }
  return handler(mockEvent, args)
}

/**
 * Try invoking a handler, catching expected errors (e.g. repository unavailable).
 * Returns { ok: true, result } on success, { ok: false, error } on failure.
 */
export async function tryInvokeHandler(
  channel: string,
  args?: unknown
): Promise<{ ok: true; result: unknown } | { ok: false; error: Error }> {
  try {
    const result = await invokeHandler(channel, args)
    return { ok: true, result }
  } catch (e) {
    return { ok: false, error: e as Error }
  }
}

/**
 * Shared test harness for Code Atelier's custom test runner.
 * Import `test`, `describe`, and `summary` / `summaryAsync` instead of defining them inline.
 *
 * Synchronous usage:
 *   import { test, describe, summary } from './test-harness'
 *   describe('MyModule', () => { test('does X', () => { ... }) })
 *   summary()  // call at end of file — exits with code 1 if any failures
 *
 * Async usage:
 *   describe('MyModule', () => {
 *     test('does X async', async () => { await doSomething() })
 *   })
 *   await summaryAsync()  // awaits pending async tests before exiting
 *
 * Lifecycle hooks (scoped to nearest describe):
 *   describe('MyModule', () => {
 *     beforeEach(() => { resetState() })
 *     afterEach(() => { cleanup() })
 *     test('does X', () => { ... })
 *   })
 *
 * Spies (for test doubles without external deps):
 *   const spy = createSpy((x: number) => x * 2)
 *   spy(5)
 *   assert.equal(spy.callCount, 1)
 *   assert.deepEqual(spy.calls[0], [5])
 */

export let passed = 0
export let failed = 0
export let skipped = 0

type Hook = () => void | Promise<void>

interface DescribeScope {
  name: string
  beforeEachHooks: Hook[]
  afterEachHooks: Hook[]
}

// Track nested describe scopes so hooks are scoped correctly.
const scopeStack: DescribeScope[] = []

// Track pending async tests so `summaryAsync()` can await them.
const pendingAsyncTests: Promise<void>[] = []

async function runHooks(hooks: Hook[]): Promise<void> {
  for (const hook of hooks) {
    await hook()
  }
}

function collectHooks(kind: 'beforeEach' | 'afterEach'): Hook[] {
  const key = kind === 'beforeEach' ? 'beforeEachHooks' : 'afterEachHooks'
  // beforeEach runs outer → inner; afterEach runs inner → outer.
  const scopes = kind === 'beforeEach' ? scopeStack : [...scopeStack].reverse()
  return scopes.flatMap((s) => s[key])
}

function reportSuccess(name: string): void {
  console.log(`  \u2713 ${name}`)
  passed++
}

function reportFailure(name: string, err: unknown): void {
  console.error(`  \u2717 ${name}`)
  const message = err instanceof Error ? err.stack || err.message : String(err)
  console.error(`    ${message}`)
  failed++
}

async function runTestAsync(
  name: string,
  fn: () => void | Promise<void>,
  beforeHooks: Hook[],
  afterHooks: Hook[]
): Promise<void> {
  try {
    await runHooks(beforeHooks)
    await fn()
    await runHooks(afterHooks)
    reportSuccess(name)
  } catch (err) {
    reportFailure(name, err)
    try {
      await runHooks(afterHooks)
    } catch (afterErr) {
      console.error(`    afterEach threw: ${(afterErr as Error).message}`)
    }
  }
}

export function test(
  name: string,
  fn: () => void | Promise<void>,
  options?: { skipReason?: string }
): void {
  if (options?.skipReason) {
    console.log(`  - ${name} (skipped: ${options.skipReason})`)
    skipped++
    return
  }

  const beforeHooks = collectHooks('beforeEach')
  const afterHooks = collectHooks('afterEach')

  // Always route through the async path when we have hooks — they may be async,
  // and sequencing is cleaner with awaits. For tests with no hooks we try the
  // synchronous fast path first and only fall back to async if the test returns
  // a promise.
  if (beforeHooks.length > 0 || afterHooks.length > 0) {
    pendingAsyncTests.push(runTestAsync(name, fn, beforeHooks, afterHooks))
    return
  }

  let result: unknown
  try {
    result = fn()
  } catch (err) {
    reportFailure(name, err)
    return
  }

  if (result && typeof (result as Promise<unknown>).then === 'function') {
    pendingAsyncTests.push(
      (async () => {
        try {
          await result
          reportSuccess(name)
        } catch (err) {
          reportFailure(name, err)
        }
      })()
    )
    return
  }

  reportSuccess(name)
}

export function describe(name: string, fn: () => void | Promise<void>): void {
  console.log(`\n${name}`)
  const scope: DescribeScope = { name, beforeEachHooks: [], afterEachHooks: [] }
  scopeStack.push(scope)
  try {
    const out = fn()
    if (out && typeof (out as Promise<void>).then === 'function') {
      // Async describe — pop the scope when it resolves.
      pendingAsyncTests.push(
        (async () => {
          try {
            await out
          } finally {
            if (scopeStack[scopeStack.length - 1] === scope) scopeStack.pop()
          }
        })()
      )
      return
    }
  } catch (err) {
    console.error(`  ✗ describe(${name}) threw: ${(err as Error).message}`)
    failed++
  }
  scopeStack.pop()
}

export function beforeEach(fn: Hook): void {
  const scope = scopeStack[scopeStack.length - 1]
  if (!scope) {
    throw new Error('beforeEach() must be called inside a describe() block')
  }
  scope.beforeEachHooks.push(fn)
}

export function afterEach(fn: Hook): void {
  const scope = scopeStack[scopeStack.length - 1]
  if (!scope) {
    throw new Error('afterEach() must be called inside a describe() block')
  }
  scope.afterEachHooks.push(fn)
}

/**
 * Synchronous summary — call at end of file for purely synchronous test suites.
 * Exits the process with code 1 if any tests failed.
 *
 * If your suite uses `async` tests or async lifecycle hooks, prefer `summaryAsync()`.
 */
export function summary(): void {
  if (pendingAsyncTests.length > 0) {
    console.warn(
      `[test-harness] ${pendingAsyncTests.length} async test(s) pending — use summaryAsync() instead.`
    )
  }
  console.log(`\n${passed} passed, ${failed} failed, ${skipped} skipped`)
  process.exit(failed > 0 || process.exitCode ? 1 : 0)
}

/**
 * Async summary — awaits every pending async test before printing totals.
 * Use this when your suite contains `async` tests.
 */
export async function summaryAsync(): Promise<void> {
  // Drain the queue — new tests may schedule more pending promises.
  while (pendingAsyncTests.length > 0) {
    const batch = pendingAsyncTests.splice(0, pendingAsyncTests.length)
    await Promise.all(batch)
  }
  console.log(`\n${passed} passed, ${failed} failed, ${skipped} skipped`)
  process.exit(failed > 0 || process.exitCode ? 1 : 0)
}

// ─────────────────────────────────────────────────────────────────────────────
// Async mutex — serialize tests that mutate a process-global (e.g. globalThis.fetch).
// The harness starts all async tests concurrently, so any two suites that swap a
// shared global will clobber each other across `await` points. Wrap their bodies
// in `runExclusive()` so they take turns on a single shared lock.
// ─────────────────────────────────────────────────────────────────────────────

let exclusiveChain: Promise<unknown> = Promise.resolve()

export function runExclusive<T>(fn: () => Promise<T>): Promise<T> {
  const run = exclusiveChain.then(fn, fn)
  // Keep the chain alive regardless of success/failure so the next waiter still runs.
  exclusiveChain = run.then(
    () => undefined,
    () => undefined
  )
  return run
}

/**
 * Reset counters — useful when running multiple test files in a single process.
 */
export function resetCounters(): void {
  passed = 0
  failed = 0
  skipped = 0
  pendingAsyncTests.length = 0
  scopeStack.length = 0
}

// ─────────────────────────────────────────────────────────────────────────────
// Spy utility — zero-dependency test double for tracking calls and stubbing.
// ─────────────────────────────────────────────────────────────────────────────

export interface Spy<TArgs extends unknown[] = unknown[], TReturn = unknown> {
  (...args: TArgs): TReturn
  readonly calls: TArgs[]
  readonly callCount: number
  readonly lastCall: TArgs | undefined
  reset(): void
  mockReturnValue(value: TReturn): void
  mockImplementation(impl: (...args: TArgs) => TReturn): void
}

/**
 * Create a spy that records every call. Optionally wraps a real implementation.
 *
 *   const spy = createSpy<[number], number>((x) => x * 2)
 *   spy(5)                 // returns 10
 *   spy.callCount          // 1
 *   spy.calls[0]           // [5]
 *   spy.mockReturnValue(0) // subsequent calls return 0
 */
export function createSpy<TArgs extends unknown[] = unknown[], TReturn = unknown>(
  impl?: (...args: TArgs) => TReturn
): Spy<TArgs, TReturn> {
  const calls: TArgs[] = []
  let currentImpl: ((...args: TArgs) => TReturn) | undefined = impl
  let fixedReturn: { value: TReturn } | undefined

  const spy = ((...args: TArgs): TReturn => {
    calls.push(args)
    if (fixedReturn) return fixedReturn.value
    if (currentImpl) return currentImpl(...args)
    return undefined as unknown as TReturn
  }) as Spy<TArgs, TReturn>

  Object.defineProperty(spy, 'calls', { get: () => calls })
  Object.defineProperty(spy, 'callCount', { get: () => calls.length })
  Object.defineProperty(spy, 'lastCall', {
    get: () => (calls.length === 0 ? undefined : calls[calls.length - 1])
  })
  spy.reset = (): void => {
    calls.length = 0
  }
  spy.mockReturnValue = (value: TReturn): void => {
    fixedReturn = { value }
  }
  spy.mockImplementation = (newImpl: (...args: TArgs) => TReturn): void => {
    currentImpl = newImpl
    fixedReturn = undefined
  }
  return spy
}

/**
 * Migration-era contract tests.
 *
 * Ensures DEFAULT_MODEL_CONFIG + DEFAULT_PROMPTS expose the expected keys for
 * the Da Vinci agent and DA_VINCI_AGENT_ID is stable.
 */
import assert from 'node:assert/strict'
import { createRequire } from 'node:module'

let passed = 0
let failed = 0
let skipped = 0

function test(name: string, fn: () => void, options?: { skipReason?: string }) {
  if (options?.skipReason) {
    console.log(`  - ${name} (skipped: ${options.skipReason})`)
    skipped++
    return
  }

  try {
    fn()
    console.log(`  ✓ ${name}`)
    passed++
  } catch (err) {
    console.error(`  ✗ ${name}`)
    console.error(`    ${(err as Error).message}`)
    failed++
  }
}

function describe(name: string, fn: () => void) {
  console.log(`\n${name}`)
  fn()
}

const require = createRequire(import.meta.url)

type RuntimeContracts = {
  DA_VINCI_AGENT_ID: string
  DEFAULT_MODEL_CONFIG: Record<string, string>
  DEFAULT_PROMPTS: Record<string, Record<string, string>>
}

let runtimeContracts: RuntimeContracts | null = null
let runtimeContractError: string | null = null

try {
  const constants = require('../../../shared/constants') as {
    DA_VINCI_AGENT_ID: string
    DEFAULT_MODEL_CONFIG: Record<string, string>
  }
  const prompts = require('../default-prompts') as {
    DEFAULT_PROMPTS: Record<string, Record<string, string>>
  }
  runtimeContracts = {
    DA_VINCI_AGENT_ID: constants.DA_VINCI_AGENT_ID,
    DEFAULT_MODEL_CONFIG: constants.DEFAULT_MODEL_CONFIG,
    DEFAULT_PROMPTS: prompts.DEFAULT_PROMPTS
  }
} catch (err) {
  runtimeContractError = (err as Error).message
}

describe('IPC contract compatibility', () => {
  const skipReason = runtimeContractError
    ? `runtime imports unavailable (${runtimeContractError})`
    : undefined

  test(
    'exposes DA_VINCI_AGENT_ID constant',
    () => {
      assert.ok(runtimeContracts)
      assert.equal(runtimeContracts.DA_VINCI_AGENT_ID, 'da-vinci')
    },
    { skipReason }
  )

  test(
    'exposes DEFAULT_MODEL_CONFIG["da-vinci"] as a string',
    () => {
      assert.ok(runtimeContracts)
      assert.equal(typeof runtimeContracts.DEFAULT_MODEL_CONFIG['specialist'], 'string')
      assert.ok(runtimeContracts.DEFAULT_MODEL_CONFIG['specialist'].length > 0)
    },
    { skipReason }
  )

  test(
    'exposes DEFAULT_PROMPTS["da-vinci"] plan/build prompts',
    () => {
      assert.ok(runtimeContracts)
      assert.equal(typeof runtimeContracts.DEFAULT_PROMPTS['da-vinci'].plan, 'string')
      assert.equal(typeof runtimeContracts.DEFAULT_PROMPTS['da-vinci'].build, 'string')
      assert.ok(runtimeContracts.DEFAULT_PROMPTS['da-vinci'].plan.length > 0)
      assert.ok(runtimeContracts.DEFAULT_PROMPTS['da-vinci'].build.length > 0)
    },
    { skipReason }
  )

  test(
    'does not require an orchestrator prompt contract after migration',
    () => {
      assert.ok(runtimeContracts)
      assert.equal('orchestrator' in runtimeContracts.DEFAULT_PROMPTS, false)
    },
    { skipReason }
  )
})

console.log(`\n${passed} passed, ${failed} failed, ${skipped} skipped`)

import assert from 'node:assert/strict'
import { EventEmitter } from 'node:events'
import { test, describe } from './test-harness'

/**
 * EventEmitter lifecycle patterns used by AgentSessionService + ChatStreamService.
 */
describe('Suite 9: Event sequence', () => {
  test('subAgentsComplete is emitted even after error path', () => {
    const emitter = new EventEmitter()
    const sequence: string[] = []

    emitter.on('chunk', (chunk: { type?: string }) => {
      if (chunk.type === 'error') {
        sequence.push('error')
      }
    })

    emitter.on('subAgentsComplete', () => {
      sequence.push('complete')
    })

    emitter.emit('chunk', { type: 'error', text: 'specialist failure' })
    emitter.emit('subAgentsComplete')

    assert.deepEqual(sequence, ['error', 'complete'])
  })

  test('chunk events accumulate text content', () => {
    const emitter = new EventEmitter()
    let accumulated = ''

    emitter.on('chunk', (chunk: { type?: string; text?: string }) => {
      if (chunk.type === 'text') {
        accumulated += chunk.text ?? ''
      }
    })

    emitter.emit('chunk', { type: 'text', text: 'Code' })
    emitter.emit('chunk', { type: 'text', text: ' Atelier' })
    emitter.emit('chunk', { type: 'text', text: ' pipeline' })

    assert.equal(accumulated, 'Code Atelier pipeline')
  })
})

describe('Suite 10: Listener lifecycle', () => {
  test('listeners are cleaned up after removal', () => {
    const emitter = new EventEmitter()
    const first = () => undefined
    const second = () => undefined

    emitter.on('complete', first)
    emitter.on('complete', second)
    assert.equal(emitter.listenerCount('complete'), 2)

    emitter.removeListener('complete', first)
    assert.equal(emitter.listenerCount('complete'), 1)
  })

  test('one-shot behavior via removeListener', () => {
    const emitter = new EventEmitter()
    let calls = 0

    const handler = () => {
      calls++
      emitter.removeListener('intent', handler)
    }

    emitter.on('intent', handler)
    emitter.emit('intent', { type: 'first' })
    emitter.emit('intent', { type: 'second' })

    assert.equal(calls, 1)
  })

  test('rapid event registration does not leak listeners', () => {
    const emitter = new EventEmitter()

    for (let i = 0; i < 10; i++) {
      const handler = () => undefined
      emitter.on('chunk', handler)
      emitter.removeListener('chunk', handler)
    }

    assert.equal(emitter.listenerCount('chunk'), 0)
  })
})

// Report handled by test runner

/**
 * Unit tests for agent service pure functions.
 * Tests summarizeToolInput, conclusive pattern detection, and topological sort logic.
 */
import assert from 'node:assert/strict'
import { test, describe } from './test-harness'

import { summarizeToolInput } from '../agent-base.service'

// ── summarizeToolInput ──────────────────────────────────────

describe('summarizeToolInput', () => {
  test('Bash — returns command (data-driven strategy ignores description)', () => {
    const result = summarizeToolInput('Bash', {
      command: 'ls -la',
      description: 'List files'
    })
    assert.equal(result, 'ls -la')
  })

  test('Bash — falls back to command when no description', () => {
    const result = summarizeToolInput('Bash', { command: 'npm run test' })
    assert.equal(result, 'npm run test')
  })

  test('Bash — returns empty string when no input', () => {
    const result = summarizeToolInput('Bash', {})
    assert.equal(result, '')
  })

  test('Read — returns relative path when workspace provided', () => {
    const result = summarizeToolInput(
      'Read',
      { file_path: '/home/user/project/src/index.ts' },
      '/home/user/project'
    )
    assert.equal(result, 'src/index.ts')
  })

  test('Read — includes line range when offset and limit provided', () => {
    const result = summarizeToolInput(
      'Read',
      { file_path: '/proj/src/index.ts', offset: 50, limit: 71 },
      '/proj'
    )
    assert.equal(result, 'src/index.ts (lines 50–120)')
  })

  test('Read — shows from line when only offset provided', () => {
    const result = summarizeToolInput(
      'Read',
      { file_path: '/proj/src/index.ts', offset: 100 },
      '/proj'
    )
    assert.equal(result, 'src/index.ts (from line 100)')
  })

  test('Read — returns absolute path when no workspace', () => {
    const result = summarizeToolInput('Read', {
      file_path: '/home/user/project/src/index.ts'
    })
    assert.equal(result, '/home/user/project/src/index.ts')
  })

  test('Read — returns empty for missing file_path', () => {
    const result = summarizeToolInput('Read', {})
    assert.equal(result, '')
  })

  test('Write — returns relative path with line count', () => {
    const result = summarizeToolInput(
      'Write',
      { file_path: '/proj/src/foo.ts', content: 'line1\nline2\nline3' },
      '/proj'
    )
    assert.equal(result, 'src/foo.ts (3 lines)')
  })

  test('Write — returns relative path without content', () => {
    const result = summarizeToolInput('Write', { file_path: '/proj/src/foo.ts' }, '/proj')
    assert.equal(result, 'src/foo.ts')
  })

  test('Edit — returns relative path with edit preview', () => {
    const result = summarizeToolInput(
      'Edit',
      { file_path: '/proj/src/bar.ts', edits: [{ old_string: 'const x = 1' }] },
      '/proj'
    )
    assert.equal(result, 'src/bar.ts → "const x = 1"')
  })

  test('Edit — shows edit count for multiple edits', () => {
    const result = summarizeToolInput(
      'Edit',
      {
        file_path: '/proj/src/bar.ts',
        edits: [{ old_string: 'a' }, { old_string: 'b' }, { old_string: 'c' }]
      },
      '/proj'
    )
    assert.equal(result, 'src/bar.ts (3 edits)')
  })

  test('Edit — returns plain path without edits', () => {
    const result = summarizeToolInput('Edit', { file_path: '/proj/src/bar.ts' }, '/proj')
    assert.equal(result, 'src/bar.ts')
  })

  test('Grep — returns pattern with path', () => {
    const result = summarizeToolInput('Grep', { pattern: 'TODO', path: '/proj/src' }, '/proj')
    assert.equal(result, '/TODO/ in src')
  })

  test('Grep — returns pattern without path', () => {
