export interface StreamChunk {
  type:
    | 'text'
    | 'thinking'
    | 'tool_use'
    | 'tool_result'
    | 'tool_progress'
    | 'error'
    | 'status'
    | 'turn_boundary'
    | 'subagent_start'
    | 'subagent_progress'
    | 'subagent_complete'
    | 'rate_limit'
    | 'compact_boundary'
    | 'api_retry'
    | 'prompt_suggestion'
    | 'files_persisted'
    | 'hook_lifecycle'
    | 'session_state'
    | 'auth_status'
    | 'tool_use_summary'
    | 'session_recovery'
    | 'context_usage_update'
    | 'permission_request'
    | 'structured_output'
    | 'lsp_diagnostics'
    | 'todo_update'
    | 'turn_limit'
    | 'phase_progress'
  content?: string
  toolName?: string
  toolInput?: string
  /**
   * Raw JSON tool input (unsummarized). `toolInput` on the CLI backend is a
   * human-readable display string ("src/a.ts (1 lines)") produced by
   * summarizeToolInput — it is NOT parseable JSON, so extractStructuredMeta
   * (tool-chunk-processor.ts) cannot recover file_path from it. This field
   * carries the actual tool input object (JSON.stringify'd) so structured
   * fields like file_path survive to consumers that need them (task-derived
   * progress tracking, in particular).
   */
  toolInputRaw?: string
  toolId?: string
  error?: string
  /** True when the CLI's tool_result had is_error: true (e.g. permission denied). */
  isError?: boolean
  /** Elapsed time in seconds for tool_progress */
  elapsedSeconds?: number
  /** Rate limit info for rate_limit type */
  rateLimit?: {
    status: 'allowed' | 'allowed_warning' | 'rejected'
    utilization?: number
    resetsAt?: number
    rateLimitType?: string
  }
  /** API retry info */
  retryInfo?: {
    attempt: number
    maxRetries: number
    retryDelayMs: number
    errorStatus: number | null
  }
  /** Files persisted list */
  persistedFiles?: Array<{ filename: string; fileId: string }>
  /** Session recovery phase */
  recoveryPhase?: 'started' | 'building_context' | 'resuming' | 'completed' | 'failed'
  /** Live context usage update — emitted each turn for real-time badge updates */
  contextUsageUpdate?: {
    inputTokens: number
    contextWindowSize: number
    percentage: number
    /** Prompt cache hit rate (0–100) — ratio of cache-read tokens to total input. */
    cacheHitRate?: number
  }
  /** Hook lifecycle info */
  hookInfo?: {
    hookId: string
    hookName: string
    hookEvent: string
    phase: 'started' | 'progress' | 'response'
    output?: string
    outcome?: 'success' | 'error' | 'cancelled'
  }
  /** Permission request info (plan mode) */
  permissionRequest?: {
    permissionId: string
    tool: string
    args?: Record<string, unknown>
    message: string
  }
  /** GAP-9: Structured output from agent response (JSON schema result) */
  structuredOutput?: {
    data: unknown
    schemaName?: string
  }
  /** GAP-14: LSP diagnostics from compiler/linter */
  lspDiagnostics?: Array<{
    file: string
    line: number
    severity: 'error' | 'warning' | 'info' | 'hint'
    message: string
    source?: string
  }>
  /** GAP-15: Todo list update from todowrite tool */
  todoUpdate?: {
    action: 'add' | 'complete' | 'remove' | 'update'
    text: string
    index?: number
  }
  /**
   * Full todo list snapshot from Claude Code's TodoWrite tool (CLI backend).
   * TodoWrite always ships the COMPLETE list on every call (not a delta), so
   * this is authoritative — consumers replace the entire per-conversation
   * todo list rather than applying it as an incremental patch.
   */
  todoSync?: Array<{ text: string; completed: boolean; index: number }>
  /** Phase progress update from plan execution */
  phaseProgress?: {
    planId: string | null
    phaseId: number
    phaseTitle: string
    status: 'started' | 'in_progress' | 'completed' | 'failed' | 'skipped'
    totalPhases: number
    message?: string
    // ── Task-level tracking ──
    taskId?: string
    taskTitle?: string
    taskStatus?: 'pending' | 'running' | 'complete' | 'failed' | 'skipped'
    totalTasks?: number
  }
  /** Turn limit reached — emitted when all auto-continuations are exhausted */
  turnLimit?: {
    /** Whether the user can click Continue to resume */
    continuable: boolean
    /** How many auto-continuations were used */
    continuationsUsed: number
    /** Max auto-continuations allowed */
    continuationsMax: number
  }
}

/**
 * Shared base class for agent services.
 *
 * N6: Dead SDK stream processing methods removed. The CLI and OpenCode
 * execution paths use stream-normalizer.ts and opencode-event-normalizer.ts
 * respectively — they no longer route through AgentBaseService stream methods.
 *
 * Retains: process lifecycle, DB session tracking, env building, stop().
 */
export abstract class AgentBaseService extends EventEmitter {
  protected process: ChildProcess | null = null
  protected currentStatus: AgentStatus['status'] = 'idle'
  protected tokenUsage: number = 0
  protected inputTokens: number = 0
  protected outputTokens: number = 0
  protected cacheReadTokens: number = 0
  protected cacheCreationTokens: number = 0
  protected startedAt: number = 0
  protected messageStartedAt: number = 0
  /** Workspace directory — used to relativize file paths in tool summaries */
  protected cwd: string | undefined

  /** Database session ID for token tracking */
  protected dbSessionId: string | null = null

  /** Scoped logger — each subclass provides its own scope */
  protected abstract readonly log: LogFunctions

  constructor() {
    super()
    this.on('error', (err) => {
      this.log.error('[AgentBase:unhandled-error]', err)
    })
  }

  abstract getStatus(): AgentStatus

  /**
   * Builds a process environment with PATH augmented for claude CLI discovery.
   * Delegates to shared env-utils for cross-platform PATH construction.
   */
  protected buildEnvWithPath(): NodeJS.ProcessEnv {
    return buildEnvWithPath()
  }

  /**
   * Creates a DB session record for token tracking.
   * Call from subclass start() after spawning the process.
   */
  protected createDbSession(
    agentType: string,
    opts: { pid?: number; conversationId?: string; workspaceId?: string } = {}
  ): void {
    try {
      const session = agentSessionRepository.create(agentType, opts)
      this.dbSessionId = session.id
    } catch (err) {
      this.log.error('Failed to create DB session:', err)
    }
  }

  /**
   * Links the DB session to a conversation after the conversation ID becomes known.
   * Use for long-lived agents (e.g. the chat agent) where conversationId is not available at start().
   */
  protected updateDbSessionConversation(conversationId: string): void {
    if (!this.dbSessionId) return
    try {
      agentSessionRepository.updateConversationId(this.dbSessionId, conversationId)
    } catch (err) {
      this.log.error('Failed to update DB session conversationId:', err)
    }
  }

  /**
   * Flushes current token usage to the DB session without completing it.
   * Use for long-lived agents (e.g. the chat agent) so the dashboard shows live data.
   */
  protected flushTokenUsage(): void {
    if (!this.dbSessionId) return
    try {
      agentSessionRepository.updateTokenUsage(this.dbSessionId, this.tokenUsage, {
        input: this.inputTokens,
        output: this.outputTokens,
        cacheRead: this.cacheReadTokens,
        cacheCreation: this.cacheCreationTokens
      })
    } catch (err) {
      this.log.error('Failed to flush token usage:', err)
    }
  }

  /**
   * Completes the DB session record with final status and token usage.
   */
  protected completeDbSession(status: 'completed' | 'failed' | 'terminated'): void {
    if (!this.dbSessionId) return
    try {
      agentSessionRepository.completeWithBreakdown(this.dbSessionId, status, {
        total: this.tokenUsage,
        input: this.inputTokens,
        output: this.outputTokens,
        cacheRead: this.cacheReadTokens,
        cacheCreation: this.cacheCreationTokens
      })
    } catch (err) {
      this.log.error('Failed to complete DB session:', err)
    }
    this.dbSessionId = null
  }

  /**
   * Gracefully stops the process.
   */
  async stop(): Promise<void> {
    if (this.process) {
      // Complete DB session before killing
      this.completeDbSession('terminated')

      this.process.kill('SIGTERM')

      await new Promise<void>((resolve) => {
        const timeout = setTimeout(() => {
          this.process?.kill('SIGKILL')
          resolve()
        }, 5000)

        this.process?.on('exit', () => {
          clearTimeout(timeout)
          resolve()
        })
      })

      this.process = null
    }
    this.currentStatus = 'idle'
    this.emit('statusUpdate', this.getStatus())
  }
}

import { delimiter } from 'node:path'

/**
 * Builds a process environment with PATH augmented for claude CLI discovery.
 * Removes CLAUDECODE env var to avoid nested session errors.
 *
 * Uses `path.delimiter` for cross-platform compatibility (`:` on Unix, `;` on Windows).
 */
export function buildEnvWithPath(): NodeJS.ProcessEnv {
  const env = { ...process.env }
  delete env.CLAUDECODE
  delete env.CLAUDE_CODE_ENTRYPOINT

  // Always prepend bin paths in priority order (highest last → lands first in PATH).
  // Duplicates in PATH are harmless; the `includes` guard was removed because it
  // caused a bug: when /usr/local/bin was already present but AFTER ~/.local/bin,
  // the guard skipped re-prepending it, so a stale ~/.local/bin/claude (v2.1.22)
  // was found before /usr/local/bin/claude (v2.1.101).
  const homeDir = process.env.HOME || process.env.USERPROFILE || ''
  if (homeDir && env.PATH) {
    env.PATH = `${homeDir}/.local/bin${delimiter}${env.PATH}`
  }

  if (env.PATH) {
    env.PATH = `/opt/homebrew/bin${delimiter}${env.PATH}`
    env.PATH = `/usr/local/bin${delimiter}${env.PATH}`
  }

  return env
}

import { BaseRepository } from '../base-repository'
import { safeParseJSON } from '../json-utils'
import type {
  CommunicationTone,
  Conversation,
  ConversationMode,
  ConversationModelSnapshot,
  ConversationType,
  LLMProvider,
  ThinkingEffort
} from '../../../shared/types'

interface ConversationRow {
  id: string
  workspace_id: string
  title: string
  mode: 'plan' | 'build' | 'danger'
  type: 'chat' | 'blueprint'
  created_at: string
  status: 'active' | 'archived'
  summary: string | null
  claude_session_id: string | null
  pr_number: number | null
  pr_url: string | null
  branch_name: string | null
  sort_order: number | null
  persona_specialist_id: string | null
  llm_provider: string | null
  mcp_overrides_json: string | null
  communication_tone: string | null
  effort: string | null
  preset_id: string | null
  handoff_context: string | null
  model_config_json: string | null
  source_audit_run_id: string | null
  source_branch: string | null
}

function parseMcpOverrides(json: string | null): Record<string, boolean> | undefined {
  if (!json || json === '{}') return undefined
  // DB-07: Use safeParseJSON for logged fallback on corrupted JSON
  const parsed = safeParseJSON<Record<string, boolean> | null>(json, null)
  if (!parsed) return undefined
  // Only return if there are any truthy entries
  return Object.values(parsed).some(Boolean) ? parsed : undefined
}

function mapRow(row: ConversationRow): Conversation {
  return {
    id: row.id,
    workspaceId: row.workspace_id,
    title: row.title,
    mode: row.mode,
    type: row.type ?? 'chat',
    createdAt: row.created_at,
    status: row.status,
    summary: row.summary ?? undefined,
    claudeSessionId: row.claude_session_id ?? undefined,
    prNumber: row.pr_number ?? undefined,
    prUrl: row.pr_url ?? undefined,
    branchName: row.branch_name ?? undefined,
    sortOrder: row.sort_order ?? undefined,
    personaSpecialistId: row.persona_specialist_id ?? null,
    llmProvider: (row.llm_provider as LLMProvider) ?? 'claude',
    mcpOverrides: parseMcpOverrides(row.mcp_overrides_json),
    communicationTone: (row.communication_tone as CommunicationTone) ?? null,
    effort: (row.effort as ThinkingEffort) ?? 'high',
    handoffContext: row.handoff_context ?? null,
    modelConfigSnapshot: row.model_config_json
      ? safeParseJSON<ConversationModelSnapshot | null>(row.model_config_json, null)
      : null,
    sourceAuditRunId: row.source_audit_run_id ?? null,
    sourceBranch: row.source_branch ?? undefined
  }
}

export class ConversationRepository extends BaseRepository<ConversationRow, Conversation> {
  protected readonly tableName = 'conversations'
  protected mapRow(row: ConversationRow): Conversation {
    return mapRow(row)
  }

  create(
    workspaceId: string,
    title?: string,
    mode?: ConversationMode,
    personaSpecialistId?: string,
    llmProvider?: LLMProvider,
    mcpOverrides?: Record<string, boolean>,
    communicationTone?: CommunicationTone | null,
    type?: ConversationType,
    modelConfigSnapshot?: ConversationModelSnapshot | null,
    sourceAuditRunId?: string
  ): Conversation {
    const row = this.db()
      .prepare(
        `INSERT INTO conversations (workspace_id, title, mode, persona_specialist_id, llm_provider, mcp_overrides_json, communication_tone, preset_id, type, model_config_json, source_audit_run_id)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
         RETURNING *`
      )
      .get(
        workspaceId,
        title ?? 'New Conversation',
        mode ?? 'plan',
        personaSpecialistId ?? null,
        llmProvider ?? 'claude',
        mcpOverrides ? JSON.stringify(mcpOverrides) : '{}',
        communicationTone ?? null,
        null, // preset_id — deprecated, always null
        type ?? 'chat',
        modelConfigSnapshot ? JSON.stringify(modelConfigSnapshot) : null,
        sourceAuditRunId ?? null
      ) as ConversationRow
    return mapRow(row)
  }

  findByWorkspace(workspaceId: string): Conversation[] {
    const rows = this.db()
      .prepare(
        `SELECT * FROM conversations WHERE workspace_id = ? AND type = 'chat' ORDER BY sort_order ASC, created_at DESC`
      )
      .all(workspaceId) as ConversationRow[]
    return rows.map(mapRow)
  }

  updateTitle(id: string, title: string): Conversation | undefined {
    const row = this.db()
      .prepare(`UPDATE conversations SET title = ? WHERE id = ? RETURNING *`)
      .get(title, id) as ConversationRow | undefined
    return row ? mapRow(row) : undefined
  }

  delete(id: string): void {
    this.runTransaction(() => {
      // Tables without FK cascade — clean explicitly to prevent orphaned rows
      this.db().prepare('DELETE FROM checkpoints WHERE conversation_id = ?').run(id)
      this.db().prepare('DELETE FROM turn_usage WHERE conversation_id = ?').run(id)
      // events are kept for audit (time-pruned separately via pruneOlderThan) — do NOT delete here

      // FK-cascaded tables (explicit delete for messages; attachments cascade from messages)
      this.db().prepare('DELETE FROM messages WHERE conversation_id = ?').run(id)
      this.db().prepare('DELETE FROM conversations WHERE id = ?').run(id)
    })
  }

  updateMode(id: string, mode: ConversationMode): Conversation | undefined {
    const row = this.db()
      .prepare(`UPDATE conversations SET mode = ? WHERE id = ? RETURNING *`)
      .get(mode, id) as ConversationRow | undefined
    return row ? mapRow(row) : undefined
  }

  archive(id: string): void {
    this.db().prepare("UPDATE conversations SET status = 'archived' WHERE id = ?").run(id)
  }

  updateSessionId(id: string, sessionId: string): void {
    this.db()
      .prepare('UPDATE conversations SET claude_session_id = ? WHERE id = ?')
      .run(sessionId, id)
  }

  getSessionId(id: string): string | undefined {
    const row = this.db()
      .prepare('SELECT claude_session_id FROM conversations WHERE id = ?')
      .get(id) as { claude_session_id: string | null } | undefined
    return row?.claude_session_id ?? undefined
  }

  getWorkspaceId(id: string): string | undefined {
    const row = this.db()
      .prepare('SELECT workspace_id FROM conversations WHERE id = ?')
      .get(id) as { workspace_id: string } | undefined
    return row?.workspace_id
  }

  updateBranchName(id: string, branchName: string): void {
    this.db().prepare('UPDATE conversations SET branch_name = ? WHERE id = ?').run(branchName, id)
  }

  updateSourceBranch(id: string, sourceBranch: string): void {
    this.db().prepare('UPDATE conversations SET source_branch = ? WHERE id = ?').run(sourceBranch, id)
  }

  updatePrInfo(id: string, prUrl: string, prNumber: number, branchName: string): void {
    this.db()
      .prepare('UPDATE conversations SET pr_url = ?, pr_number = ?, branch_name = ? WHERE id = ?')
      .run(prUrl, prNumber, branchName, id)
  }

  updateMcpOverrides(
    conversationId: string,
    overrides: Record<string, boolean>
  ): Conversation | undefined {
    const row = this.db()
      .prepare(`UPDATE conversations SET mcp_overrides_json = ? WHERE id = ? RETURNING *`)
      .get(JSON.stringify(overrides), conversationId) as ConversationRow | undefined
    return row ? mapRow(row) : undefined
  }

  /** Update per-conversation thinking effort level */
  updateEffort(conversationId: string, effort: ThinkingEffort): Conversation | undefined {
    const row = this.db()
      .prepare(`UPDATE conversations SET effort = ? WHERE id = ? RETURNING *`)
      .get(effort, conversationId) as ConversationRow | undefined
    return row ? mapRow(row) : undefined
  }

  /** Update per-conversation communication tone override (null = use workspace default) */
  updateTone(conversationId: string, tone: CommunicationTone | null): Conversation | undefined {
    const row = this.db()
      .prepare(`UPDATE conversations SET communication_tone = ? WHERE id = ? RETURNING *`)
      .get(tone, conversationId) as ConversationRow | undefined
    return row ? mapRow(row) : undefined
  }

  /**
   * S6: Update the conversation summary for cross-message context.
   * The `summary` column already exists in the schema.
   */
  updateSummary(id: string, summary: string): void {
    this.db().prepare('UPDATE conversations SET summary = ? WHERE id = ?').run(summary, id)
  }

  /**
   * S6: Get the stored conversation summary.
   * Returns undefined if no summary has been captured yet.
   */
  getSummary(id: string): string | undefined {
    const row = this.db().prepare('SELECT summary FROM conversations WHERE id = ?').get(id) as
      | { summary: string | null }
      | undefined
    return row?.summary ?? undefined
  }



  /** Update handoff context injected when switching providers mid-chat */
  updateHandoffContext(conversationId: string, handoffContext: string | null): void {
    this.db()
      .prepare('UPDATE conversations SET handoff_context = ? WHERE id = ?')
      .run(handoffContext, conversationId)
  }

  /**
   * Update the frozen model config snapshot for a conversation.
   * Used by per-chat model switching to re-route an existing conversation
   * without affecting other chats.
   */
  updateModelSnapshot(
    conversationId: string,
    snapshot: ConversationModelSnapshot,
    llmProvider: LLMProvider
  ): Conversation | undefined {
    const row = this.db()
      .prepare(
        `UPDATE conversations SET model_config_json = ?, llm_provider = ? WHERE id = ? RETURNING *`
      )
      .get(JSON.stringify(snapshot), llmProvider, conversationId) as ConversationRow | undefined
    return row ? mapRow(row) : undefined
  }

  /** Find all conversations sourced from a specific audit run. */
  findByAuditRunId(auditRunId: string): Conversation[] {
    const rows = this.db()
      .prepare('SELECT * FROM conversations WHERE source_audit_run_id = ? ORDER BY created_at DESC')
      .all(auditRunId) as ConversationRow[]
    return rows.map(mapRow)
  }

  reorderConversations(orderedIds: string[]): void {
    const stmt = this.db().prepare('UPDATE conversations SET sort_order = ? WHERE id = ?')
    this.runTransaction(() => {
      orderedIds.forEach((id, i) => stmt.run(i, id))
    })
  }

}

