/**
 * Migration 66 — Project Specialist architecture.
 *
 * Transforms the DB from "app-global specialists" to "one Project Specialist
 * per workspace" per the plan in
 * docs/architecture/project-specialist-refactor.md.
 *
 * What it does, in order:
 *
 *   1. Writes a JSON backup of all specialists + their skill assignments to
 *      userData/agent-studio-specialist-backup-<ISO>.json. This is non-
 *      destructive so it happens first. Idempotent: skipped if already
 *      performed for this migration.
 *   2. ALTERs the specialists table with new columns (workspace_id,
 *      build_status, stack_fingerprint, detected_techs, mcp_config,
 *      mcp_overrides, last_built_at) plus a partial unique index.
 *   3. ALTERs specialist_skills with is_enabled (default 0).
 *   4. Creates one "pending" Project Specialist per existing workspace.
 *   5. Rebinds conversation_specialists rows to the new workspace specialist.
 *      Deduplicates (multiple old specialists → one new).
 *   6. Drops the legacy app-global specialists (workspace_id IS NULL AND
 *      agent_id != 'generalist'). The Generalist row stays app-global.
 *
 * Everything below is idempotent within a single run (guarded on
 * PRAGMA user_version by the outer migration runner).
 */

import type Database from 'better-sqlite3'
import { join } from 'node:path'
import { writeFileSync, mkdirSync, existsSync } from 'node:fs'
import log from 'electron-log'

const migLog = log.scope('migration-066')

interface SpecialistBackup {
  id: string
  agent_id: string
  display_name: string
  icon: string
  color: string
  prompt: string
  priority: number
  is_active: number
  source_yaml: string | null
  alias: string | null
  avatar_url: string | null
  is_core: number
  created_at: string
  updated_at: string
  /** Skill IDs assigned to this specialist via specialist_skills. */
  skill_ids: string[]
}

interface BackupDocument {
  schemaVersion: 65
  exportedAt: string
  specialists: SpecialistBackup[]
}

function exportSpecialistsBackup(db: Database.Database): string | null {
  try {
    // Skip if the backup dir already contains a file for this migration.
    let userData: string
    try {
      // eslint-disable-next-line @typescript-eslint/no-var-requires
      userData = (require('electron') as typeof import('electron')).app.getPath('userData')
    } catch {
      // When running inside unit tests Electron's app is not available.
      return null
    }
    const backupDir = join(userData, 'backups')
    if (!existsSync(backupDir)) mkdirSync(backupDir, { recursive: true })

    const specialists = db
      .prepare(
        `SELECT id, agent_id, display_name, icon, color, prompt, priority, is_active,
                source_yaml, alias, avatar_url,
                is_core, created_at, updated_at FROM specialists`
      )
      .all() as Array<Omit<SpecialistBackup, 'skill_ids'>>

    const skillsStmt = db.prepare('SELECT skill_id FROM specialist_skills WHERE specialist_id = ?')

    const withSkills: SpecialistBackup[] = specialists.map((s) => ({
      ...s,
      skill_ids: (skillsStmt.all(s.id) as Array<{ skill_id: string }>).map((row) => row.skill_id)
    }))

    const isoSafe = new Date().toISOString().replace(/[:.]/g, '-')
    const filename = `code-atelier-specialist-backup-${isoSafe}.json`
    const filepath = join(backupDir, filename)
    const doc: BackupDocument = {
      schemaVersion: 65,
      exportedAt: new Date().toISOString(),
      specialists: withSkills
    }
    writeFileSync(filepath, JSON.stringify(doc, null, 2), 'utf8')
    migLog.info(`✓ Specialist backup written to ${filepath} (${withSkills.length} entries)`)
    return filepath
  } catch (err) {
    migLog.warn('Backup export failed (non-fatal):', err)
    return null
  }
}

function hasColumn(db: Database.Database, table: string, column: string): boolean {
  const rows = db.prepare(`PRAGMA table_info(${table})`).all() as Array<{ name: string }>
  return rows.some((r) => r.name === column)
}

export function runProjectSpecialistMigration(db: Database.Database): void {
  // Step 1 — Backup (non-destructive, best effort).
  exportSpecialistsBackup(db)

  // Step 2 — Add columns to specialists (idempotent via hasColumn).
  const specCols: Array<{ name: string; ddl: string }> = [
    {
      name: 'workspace_id',
      ddl: `ALTER TABLE specialists ADD COLUMN workspace_id TEXT REFERENCES workspaces(id) ON DELETE CASCADE`
    },
    {
      name: 'build_status',
      ddl: `ALTER TABLE specialists ADD COLUMN build_status TEXT NOT NULL DEFAULT 'ready' CHECK (build_status IN ('pending', 'building', 'ready', 'failed'))`
    },
    {
      name: 'stack_fingerprint',
      ddl: `ALTER TABLE specialists ADD COLUMN stack_fingerprint TEXT`
    },
    {
      name: 'detected_techs',
      ddl: `ALTER TABLE specialists ADD COLUMN detected_techs TEXT DEFAULT '[]' CHECK (json_valid(detected_techs))`
    },
    {
      name: 'mcp_config',
      ddl: `ALTER TABLE specialists ADD COLUMN mcp_config TEXT DEFAULT '{}' CHECK (json_valid(mcp_config))`
    },
    {
      name: 'mcp_overrides',
      ddl: `ALTER TABLE specialists ADD COLUMN mcp_overrides TEXT DEFAULT '{}' CHECK (json_valid(mcp_overrides))`
    },
    { name: 'last_built_at', ddl: `ALTER TABLE specialists ADD COLUMN last_built_at TEXT` }
  ]
  for (const col of specCols) {
    if (!hasColumn(db, 'specialists', col.name)) {
      db.exec(col.ddl)
    }
  }

  db.exec(
    `CREATE UNIQUE INDEX IF NOT EXISTS idx_specialists_workspace_unique
       ON specialists(workspace_id) WHERE workspace_id IS NOT NULL`
  )

  // Step 3 — Add is_enabled to specialist_skills.
  if (!hasColumn(db, 'specialist_skills', 'is_enabled')) {
    db.exec(`ALTER TABLE specialist_skills ADD COLUMN is_enabled INTEGER NOT NULL DEFAULT 0`)
  }

  // Step 4 — Create one pending Project Specialist per existing workspace.
  // Skip workspaces that already have one bound.
  const workspaces = db.prepare(`SELECT id, name FROM workspaces`).all() as Array<{
    id: string
    name: string
  }>

  const existingByWorkspace = new Map<string, string>()
  for (const row of db
    .prepare(`SELECT id, workspace_id FROM specialists WHERE workspace_id IS NOT NULL`)
    .all() as Array<{ id: string; workspace_id: string }>) {
    existingByWorkspace.set(row.workspace_id, row.id)
  }

  const insertSpecialist = db.prepare(
    `INSERT INTO specialists (workspace_id, agent_id, display_name, icon, color,
       prompt, priority, is_active, build_status, created_at, updated_at)
     VALUES (?, ?, ?, '🔧', '#6366F1', '', 1, 1, 'pending', datetime('now'), datetime('now'))`
  )

  for (const w of workspaces) {
    if (existingByWorkspace.has(w.id)) continue
    insertSpecialist.run(w.id, `workspace-specialist-${w.id}`, `${w.name} Specialist`)
  }

  // Step 5 — Rebind existing conversation_specialists rows onto the new
  // per-workspace specialist. Ordering matters: if a conversation has N
  // pre-migration specialist rows, rebinding them all to the same NEW id
  // would violate UNIQUE(conversation_id, specialist_id). So we
  //   5a. Pre-collapse: for each conversation that will be rebound, keep
  //       exactly one row (the oldest) and delete the rest.
  //   5b. Rebind the surviving rows to the workspace's new specialist.
  db.exec(
    `DELETE FROM conversation_specialists
       WHERE rowid NOT IN (
         SELECT MIN(rowid) FROM conversation_specialists
          WHERE conversation_id IN (
            SELECT c.id FROM conversations c
             WHERE c.workspace_id IS NOT NULL
               AND EXISTS (
                 SELECT 1 FROM specialists s
                  WHERE s.workspace_id = c.workspace_id
               )
          )
         GROUP BY conversation_id
       )
       AND conversation_id IN (
         SELECT c.id FROM conversations c
          WHERE c.workspace_id IS NOT NULL
            AND EXISTS (
              SELECT 1 FROM specialists s
               WHERE s.workspace_id = c.workspace_id
            )
       )`
  )

  db.exec(
    `UPDATE conversation_specialists
        SET specialist_id = (
          SELECT s.id FROM specialists s
           WHERE s.workspace_id = (
             SELECT c.workspace_id FROM conversations c
              WHERE c.id = conversation_specialists.conversation_id
           )
        )
      WHERE EXISTS (
        SELECT 1 FROM conversations c
         WHERE c.id = conversation_specialists.conversation_id
           AND c.workspace_id IS NOT NULL
      ) AND EXISTS (
        SELECT 1 FROM specialists s
         WHERE s.workspace_id = (
           SELECT c.workspace_id FROM conversations c
            WHERE c.id = conversation_specialists.conversation_id
         )
      )`
  )

  // Safety net: a second dedupe pass in case any stragglers remain from
  // a partial earlier migration attempt (e.g. one that advanced
  // user_version but failed between updates).
  db.exec(
    `DELETE FROM conversation_specialists
      WHERE rowid NOT IN (
        SELECT MIN(rowid) FROM conversation_specialists
          GROUP BY conversation_id, specialist_id
      )`
  )

  // Step 6 — Drop legacy app-global specialists EXCEPT the Generalist row,
  // which the app still relies on for the home-screen concierge.
  db.exec(
    `DELETE FROM specialists
       WHERE workspace_id IS NULL
         AND agent_id != 'generalist'`
  )

  migLog.info('✓ Migration 066 complete — project-specialist architecture applied.')
}

import {
  DEFAULT_MODEL_CONFIG,
  OLLAMA_DEFAULT_HOST,
  OLLAMA_DEFAULT_PORT,
  OMLX_DEFAULT_PORT
} from '../../shared/constants'
import type {
  ConversationModelSnapshot,
  ExecutorBackend,
  LLMProvider,
  LocalLLMBackend,
  LocalLLMConfig,
  LocalLLMStrategy,
  ModelAction,
  ModelOverrides,
  ModelRoleAssignment,
  ModelRoleMap,
  ResolvedAssignment
} from '../../shared/types'
import log from 'electron-log'
import { workspaceRepository } from '../db/repositories'
import { decryptSettingsKey } from '../ipc/encrypt-settings-keys'

/**
 * Multi-provider configuration — extends workspace settings for Phase 4C.
 *
 * Stored in workspace settings_json under openCode* keys.
 * These settings are only used when executorBackend === 'opencode'.
 */
export interface OpenCodeProviderSettings {
  /** Provider ID (e.g. 'anthropic', 'ollama', 'openai', 'google', 'custom') */
  openCodeProvider: string
  /** Model ID within the provider */
  openCodeModel: string
  /** Base URL for custom/local providers */
  openCodeBaseUrl?: string
  /** API key for the provider */
  openCodeApiKey?: string
}

/**
 * Centralized model resolution service.
 *
 * Resolves the Claude model ID for a given action in a workspace by checking
 * per-action overrides in `settings_json.modelOverrides`, falling back to
 * the hardcoded defaults in `DEFAULT_MODEL_CONFIG`.
 *
 * Also provides provider-awareness for local LLM support — resolves the active
 * LLM provider and backend (Ollama / oMLX) configuration for a workspace.
 */
class ModelConfigService {
  /**
   * Resolves the model ID for a given action.
   * Uses workspace override if set, otherwise returns the default.
   * Sub-actions (e.g. 'specialist:plan') fall back to their base action ('specialist').
   *
   * @param workspacePath - The workspace repo path (or undefined for default)
   * @param action - The model action to resolve
   */
  getModel(workspacePath: string | undefined, action: ModelAction): string {
    if (!workspacePath) return DEFAULT_MODEL_CONFIG[action] ?? this.fallbackAction(action)

    const settings = workspaceRepository.getSettingsByPath(workspacePath)

    // Check modelRoles (structured cross-provider path) — Claude only
    const roles = (settings?.modelRoles ?? {}) as ModelRoleMap
    const roleAssignment = roles[action]
    if (roleAssignment?.modelId && roleAssignment.provider !== 'local-llm') {
      return roleAssignment.modelId
    }

    // Legacy modelOverrides
    const overrides = (settings?.modelOverrides ?? {}) as ModelOverrides
    return overrides[action] ?? DEFAULT_MODEL_CONFIG[action] ?? this.fallbackAction(action)
  }

  /**
   * Resolves the model ID for a given action using workspace ID.
   * Uses workspace override if set, otherwise returns the default.
   * Sub-actions (e.g. 'specialist:plan') fall back to their base action ('specialist').
   *
   * @param workspaceId - The workspace ID (or undefined for default)
   * @param action - The model action to resolve
   */
  getModelById(workspaceId: string | undefined, action: ModelAction): string {
    if (!workspaceId) return DEFAULT_MODEL_CONFIG[action] ?? this.fallbackAction(action)

    const settings = workspaceRepository.getSettings(workspaceId)

    // Check modelRoles (structured cross-provider path) — Claude only
    const roles = (settings?.modelRoles ?? {}) as ModelRoleMap
    const roleAssignment = roles[action]
    if (roleAssignment?.modelId && roleAssignment.provider !== 'local-llm') {
      return roleAssignment.modelId
    }

    // Legacy modelOverrides
    const overrides = (settings?.modelOverrides ?? {}) as ModelOverrides
    return overrides[action] ?? DEFAULT_MODEL_CONFIG[action] ?? this.fallbackAction(action)
  }

  // ── Provider awareness ──

  /** Get the LLM provider for a workspace */
  getProvider(workspacePath: string | undefined): LLMProvider {
    if (!workspacePath) return 'claude'
    const settings = workspaceRepository.getSettingsByPath(workspacePath)
    return (settings?.llmProvider as LLMProvider) ?? 'claude'
  }

  /** Get full local LLM config for a workspace (supports both Ollama and oMLX backends) */
  getLocalLLMConfig(workspacePath: string): LocalLLMConfig {
    const settings = workspaceRepository.getSettingsByPath(workspacePath)
    const backend = (settings?.localLlmBackend as LocalLLMBackend) ?? 'ollama'
    const defaultPort = backend === 'omlx' ? OMLX_DEFAULT_PORT : OLLAMA_DEFAULT_PORT
    return {
      provider: (settings?.llmProvider as LLMProvider) ?? 'claude',
      backend,
      // New keys with backward-compat fallback from old Ollama-specific keys
      localModel:
        (settings?.localModel as string) ??
        (settings?.ollamaModel as string) ?? // backward compat
        'qwen3.6:35b-a3b-coding-nvfp4',
      localHost:
        (settings?.localHost as string) ??
        (settings?.ollamaHost as string) ?? // backward compat
        OLLAMA_DEFAULT_HOST,
      localPort:
        (settings?.localPort as number) ??
        (settings?.ollamaPort as number) ?? // backward compat
        defaultPort,
      strategy: (settings?.localLlmStrategy as LocalLLMStrategy) ?? 'default',
      // SEC-04: Decrypt localApiKey (handles both legacy plaintext and encrypted)
      localApiKey: decryptSettingsKey(
        settings?.localApiKey as string | undefined,
        !!settings?.localApiKeyEncrypted
      )
    }
  }

  /** Build the local LLM base URL from config (works for both Ollama and oMLX) */
  getLocalBaseUrl(config: LocalLLMConfig): string {
    // SVC-07: Validate host/port before constructing URL
    const host = config.localHost || 'localhost'
    const port = Number(config.localPort)
    if (!Number.isFinite(port) || port < 1 || port > 65535) {
      return `http://${host}:${OLLAMA_DEFAULT_PORT}`
    }
    return `http://${host}:${port}`
  }

  /**
   * @deprecated Use `getLocalBaseUrl()` instead. Kept for one release cycle.
   */
  getOllamaBaseUrl(config: LocalLLMConfig): string {
    return this.getLocalBaseUrl(config)
  }

  /** Check if workspace uses local LLM */
  isLocalProvider(workspacePath: string | undefined): boolean {
    return this.getProvider(workspacePath) === 'local-llm'
  }

  /**
   * S14: Get the local LLM backend for a workspace.
   * Returns 'omlx' | 'ollama' | undefined (undefined if not a local provider).
   */
  getBackend(workspacePath: string | undefined): LocalLLMBackend | undefined {
    if (!workspacePath || !this.isLocalProvider(workspacePath)) return undefined
    return this.getLocalLLMConfig(workspacePath).backend
  }

  /**
   * Derive the executor backend from the workspace's resolved LLM provider.
   * Rule: provider === 'claude' → 'cli'; everything else → 'opencode'.
   * No longer reads settings.executorBackend (was user-configurable, now derived).
   */
  getExecutorBackend(workspacePath: string | undefined): ExecutorBackend {
    if (!workspacePath) return 'cli'
    const settings = workspaceRepository.getSettingsByPath(workspacePath)
    const provider = settings?.llmProvider ?? 'claude'

    // Log when a stored executorBackend value is being ignored (behavior-change traceability)
    const storedBackend = settings?.executorBackend as string | undefined
    if (storedBackend && storedBackend !== (provider === 'claude' ? 'cli' : 'opencode')) {
      log.info(
        `[getExecutorBackend] Ignoring stored executorBackend='${storedBackend}' — ` +
        `now derived from provider='${provider}' → '${provider === 'claude' ? 'cli' : 'opencode'}'`
      )
    }

    return provider === 'claude' ? 'cli' : 'opencode'
  }

  /**
   * Get OpenCode provider configuration for a workspace.
   * Returns default Anthropic config if no OpenCode settings are configured.
   *
   * Phase 4C: Multi-provider support via OpenCode.
   */
  getOpenCodeConfig(workspacePath: string): OpenCodeProviderSettings {
    const settings = workspaceRepository.getSettingsByPath(workspacePath)

    // If workspace uses local LLM, auto-configure Ollama provider
    if (settings?.llmProvider === 'local-llm') {
      const localConfig = this.getLocalLLMConfig(workspacePath)
      return {
        openCodeProvider: localConfig.backend === 'omlx' ? 'omlx' : 'ollama',
        openCodeModel: localConfig.localModel,
        openCodeBaseUrl: this.getLocalBaseUrl(localConfig),
        openCodeApiKey: localConfig.localApiKey
      }
    }

    return {
      openCodeProvider: (settings?.openCodeProvider as string) ?? 'anthropic',
      openCodeModel: (settings?.openCodeModel as string) ?? 'claude-sonnet-5',
      openCodeBaseUrl: settings?.openCodeBaseUrl as string | undefined,
      // SEC-04: Decrypt openCodeApiKey (handles both legacy plaintext and encrypted)
      openCodeApiKey: decryptSettingsKey(
        settings?.openCodeApiKey as string | undefined,
        !!settings?.openCodeApiKeyEncrypted
      )
    }
  }

  /**
   * Fallback: 'specialist:plan' → 'specialist' → DEFAULT_MODEL_CONFIG.
   */
  private fallbackAction(action: ModelAction): string {
    // SVC-06: Validate that the base portion is a known ModelAction key
    const base = action.split(':')[0]
    if (base && base in DEFAULT_MODEL_CONFIG) {
      return DEFAULT_MODEL_CONFIG[base as ModelAction]
    }
    return DEFAULT_MODEL_CONFIG['specialist']
  }
}

export const modelConfigService = new ModelConfigService()

// ── Pure resolution function ────────────────────────────────────────

/**
 * Resolve the model assignment for a given action using the full fallback chain:
 *
 *   1. modelRoles[action]           → source: 'roles'
 *   2. modelOverrides[action] as Claude  → source: 'override'
 *   3. DEFAULT_MODEL_CONFIG[action]  → source: 'default'
 *   4. DEFAULT_MODEL_CONFIG[base]    → source: 'fallback'
 *   5. DEFAULT_MODEL_CONFIG['specialist'] → source: 'fallback'
 *
 * Pure function — all inputs are explicit. No side effects.
 */
export function resolveAssignment(opts: {
  action: ModelAction
  /** modelRoles from workspace settings_json (new structured path) */
  modelRoles?: ModelRoleMap
  /** Legacy modelOverrides from workspace settings_json */
  modelOverrides?: ModelOverrides
  /** Workspace-level provider (for legacy override interpretation) */
  workspaceProvider?: LLMProvider
  /** Workspace-level local backend */
  workspaceBackend?: LocalLLMBackend
}): ResolvedAssignment {
  const {
    action,
    modelRoles,
    modelOverrides,
    workspaceProvider = 'claude',
    workspaceBackend
  } = opts

  // 1. New structured model roles (highest priority)
  if (modelRoles?.[action]) {
    const role = modelRoles[action] as ModelRoleAssignment
    return {
      provider: role.provider,
      modelId: role.modelId,
      localBackend: role.localBackend,
      source: 'roles'
    }
  }

  // 2. Legacy per-action overrides (interpreted as the workspace's active provider)
  if (modelOverrides?.[action]) {
    return {
      provider: workspaceProvider,
      modelId: modelOverrides[action],
      localBackend: workspaceProvider === 'local-llm' ? workspaceBackend : undefined,
      source: 'override'
    }
  }

  // 3. Direct default
  if (action in DEFAULT_MODEL_CONFIG) {
    return {
      provider: 'claude',
      modelId: DEFAULT_MODEL_CONFIG[action],
      source: 'default'
    }
  }

  // 4. Base action fallback (e.g. 'specialist:plan' → 'specialist')
  const base = action.split(':')[0]
  if (base && base in DEFAULT_MODEL_CONFIG) {
    return {
      provider: 'claude',
      modelId: DEFAULT_MODEL_CONFIG[base as ModelAction],
      source: 'fallback'
    }
  }

  // 5. Ultimate fallback
  return {
    provider: 'claude',
    modelId: DEFAULT_MODEL_CONFIG['specialist'],
    source: 'fallback'
  }
}

/**
 * Build the resolve-options object from workspace settings.
 * Shared between buildConversationModelSnapshot and blueprint snapshot creation.
 */
export function buildResolveOpts(workspaceId: string): {
  modelRoles: ModelRoleMap | undefined
  modelOverrides: ModelOverrides | undefined
  workspaceProvider: LLMProvider
  workspaceBackend: LocalLLMBackend | undefined
} {
  const settings = workspaceRepository.getSettings(workspaceId)

  return {
    modelRoles: (settings.modelRoles ?? undefined) as ModelRoleMap | undefined,
    modelOverrides: (settings.modelOverrides ?? undefined) as ModelOverrides | undefined,
    workspaceProvider: (settings.llmProvider as LLMProvider) ?? 'claude',
    workspaceBackend: (settings.localLlmBackend as LocalLLMBackend) ?? undefined,
  }
}

/**
 * Build a frozen model config snapshot for a conversation.
 * Captures the current workspace model assignments at creation time.
 *
 * @param workspaceId - Workspace to snapshot settings from
 * @param explicitProvider - If provided, overrides the workspace-level provider
 * @param routingOverrides - Per-conversation routing overrides (merged on top of workspace roles)
 */
export function buildConversationModelSnapshot(
  workspaceId: string,
  explicitProvider?: LLMProvider,
  routingOverrides?: Partial<ModelRoleMap>
): ConversationModelSnapshot {
  const resolveOpts = buildResolveOpts(workspaceId)

  // If caller specified a provider override, use it
  if (explicitProvider) {
    resolveOpts.workspaceProvider = explicitProvider
  }

  // Merge per-conversation routing overrides on top of workspace roles
  if (routingOverrides && Object.keys(routingOverrides).length > 0) {
    resolveOpts.modelRoles = {
      ...(resolveOpts.modelRoles ?? {}),
      ...routingOverrides
    }
  }

  return {
    plan: resolveAssignment({ action: 'specialist:plan', ...resolveOpts }),
    build: resolveAssignment({ action: 'specialist:build', ...resolveOpts }),
    background: resolveAssignment({ action: 'haiku', ...resolveOpts }),
    snapshotAt: new Date().toISOString()
  }
}

/**
 * SEC-04: Shared utility for encrypting/decrypting API key settings fields.
 *
 * Uses Electron's safeStorage (OS keychain-backed) to encrypt API keys
 * before they are written to the SQLite settings_json column. Decryption
 * restores the original plaintext when the key is read back.
 *
 * Each key gets a companion `${key}Encrypted` boolean flag so the reader
 * can distinguish legacy plaintext values from encrypted ones.
 */
// Lazy Electron import — this module gets bundled into a shared chunk that
// MCP server child processes load transitively. `safeStorage` is only called
// from the Electron main process, never from standalone servers.
function getSafeStorage(): typeof import('electron').safeStorage {
  // eslint-disable-next-line @typescript-eslint/no-var-requires
  return require('electron').safeStorage
}

/** All settings keys that contain API secrets and must be encrypted at rest. */
const ENCRYPTED_SETTINGS_KEYS = ['anthropicApiKey', 'openCodeApiKey', 'localApiKey'] as const

/**
 * Encrypt any plaintext API key fields in a settings object before DB storage.
 * Mutates nothing — returns a new object with encrypted values.
 *
 * Fields that are already encrypted (have a truthy `${key}Encrypted` companion)
 * are left untouched to avoid double-encryption.
 */
export function encryptSettingsKeys(settings: Record<string, unknown>): Record<string, unknown> {
  const result = { ...settings }
  for (const key of ENCRYPTED_SETTINGS_KEYS) {
    const value = result[key]
    const alreadyEncrypted = result[`${key}Encrypted`]
    if (typeof value === 'string' && value.length > 0 && !alreadyEncrypted) {
      result[key] = getSafeStorage().encryptString(value).toString('base64')
      result[`${key}Encrypted`] = true
    }
  }
  return result
}

/**
 * Decrypt a single API key value using its companion encrypted flag.
 * Returns the plaintext key, handling both legacy (unencrypted) and
 * encrypted storage transparently.
 */
export function decryptSettingsKey(
  value: string | undefined | null,
  isEncrypted: boolean | undefined
): string | undefined {
  if (!value) return undefined
  if (isEncrypted) {
    try {
      return getSafeStorage().decryptString(Buffer.from(value, 'base64'))
    } catch (err) {
      // SEC-04b: Decryption failed — the flag/value pair is inconsistent.
      // This happens when:
      //   1. The value was stored as plaintext but the flag was set to true
      //   2. The OS keychain was re-keyed (password change, migration)
      //   3. The encrypted data is corrupt
      // Log the failure so it's diagnosable, and fall back to the raw value.
      // A short non-base64 string is likely plaintext that was flagged incorrectly.
      const looksLikePlaintext = value.length < 100 && !/^[A-Za-z0-9+/]+=*$/.test(value)
      if (looksLikePlaintext) {
        console.warn(
          `[SEC-04b] decryptSettingsKey: encrypted flag set but value appears to be plaintext ` +
          `(len=${value.length}). Returning raw value as fallback.`
        )
        return value
      }
      console.warn(
        `[SEC-04b] decryptSettingsKey: decryption failed for encrypted value (len=${value.length}). ` +
        `Key is lost — user must re-enter it.`
      )
      return undefined
    }
  }
  return value // Legacy plaintext — returned as-is
}

/**
 * Safe JSON parsing utility for database repository mapRow functions.
 *
 * SQLite stores JSON as TEXT columns. If the data is corrupted (partial write,
 * schema migration error, manual edit), a raw JSON.parse will crash the entire
 * query and brick the feature. This utility returns a typed fallback instead.
 */

import { dbLogger } from '../logger'

const log = dbLogger

/**
 * Parse a JSON string safely, returning `fallback` on null/undefined/malformed input.
 * Logs a warning on parse failure so corrupted rows surface in diagnostics
 * without crashing the application.
 */
export function safeParseJSON<T>(json: string | null | undefined, fallback: T): T {
  if (!json) return fallback
  try {
    return JSON.parse(json) as T
  } catch (err) {
    log.warn(`JSON parse failed for value: ${json.slice(0, 100)}…`, err)
    return fallback
  }
}

import { BaseRepository } from '../base-repository'
import { safeParseJSON } from '../json-utils'
import type { Message, ToolActivity } from '../../../shared/types'

interface MessageRow {
  id: string
  conversation_id: string
  role: 'user' | 'specialist'
  agent_id: string | null
  content_md: string
  attachments_json: string
  created_at: string
  parent_message_id: string | null
  tool_activities_json: string | null
  plan_action: string | null
  hidden: number
}

function mapRow(row: MessageRow): Message {
  return {
    id: row.id,
    conversationId: row.conversation_id,
    role: row.role,
    agentId: row.agent_id ?? undefined,
    contentMd: row.content_md,
    attachmentsJson: row.attachments_json,
    createdAt: row.created_at,
    parentMessageId: row.parent_message_id ?? undefined,
    // DB-01: Use safeParseJSON to prevent a corrupted row from crashing conversation load
    toolActivities: safeParseJSON<ToolActivity[] | undefined>(row.tool_activities_json, undefined),
    planAction: row.plan_action ?? undefined,
    hidden: row.hidden === 1
  }
}

export class MessageRepository extends BaseRepository<MessageRow, Message> {
  protected readonly tableName = 'messages'
  protected mapRow(row: MessageRow): Message {
    return mapRow(row)
  }

  create(
    conversationId: string,
    role: 'user' | 'specialist',
    contentMd: string,
    agentId?: string,
    attachmentsJson?: string,
    opts?: { hidden?: boolean }
  ): Message {
    const db = this.db()
    const stmt = db.prepare(`
      INSERT INTO messages (conversation_id, role, content_md, agent_id, attachments_json, hidden)
      VALUES (?, ?, ?, ?, ?, ?)
      RETURNING *
    `)
    const row = stmt.get(
      conversationId,
      role,
      contentMd,
      agentId ?? null,
      attachmentsJson ?? '[]',
      opts?.hidden ? 1 : 0
    ) as MessageRow
    return mapRow(row)
  }

  findByConversation(conversationId: string): Message[] {
    const db = this.db()
    const stmt = db.prepare(
      'SELECT * FROM messages WHERE conversation_id = ? ORDER BY created_at ASC'
    )
    const rows = stmt.all(conversationId) as MessageRow[]
    return rows.map(mapRow)
  }

  /**
   * F5: Fetch only the most recent N messages for a conversation.
   * Uses SQL LIMIT + DESC ordering to avoid loading the entire history,
   * then reverses to chronological order in code.
   */
  findRecentByConversation(conversationId: string, limit: number): Message[] {
    const db = this.db()
    const stmt = db.prepare(
      'SELECT * FROM messages WHERE conversation_id = ? ORDER BY created_at DESC LIMIT ?'
    )
    const rows = stmt.all(conversationId, limit) as MessageRow[]
    return rows.reverse().map(mapRow)
  }

  /**
   * Get the timestamp of the most recent message in a conversation.
   * Returns undefined if the conversation has no messages.
   * Used for session staleness detection — avoids loading full message objects.
   */
  getLastMessageTimestamp(conversationId: string): string | undefined {
    const row = this.db()
      .prepare('SELECT created_at FROM messages WHERE conversation_id = ? ORDER BY created_at DESC LIMIT 1')
      .get(conversationId) as { created_at: string } | undefined
    return row?.created_at
  }

  findById(id: string): Message | undefined {
    const db = this.db()
    const stmt = db.prepare('SELECT * FROM messages WHERE id = ?')
    const row = stmt.get(id) as MessageRow | undefined
    return row ? mapRow(row) : undefined
  }

  /**
   * Delete all messages in a conversation created after a given timestamp.
   * Used by /rewind to truncate conversation history at a checkpoint.
   * Returns the number of deleted rows.
   */
  truncateAfterTimestamp(conversationId: string, afterTimestamp: string): number {
    const db = this.db()
    const result = db
      .prepare('DELETE FROM messages WHERE conversation_id = ? AND created_at > ?')
      .run(conversationId, afterTimestamp)
    return result.changes
  }

  /**
   * Persist tool activities for a saved message.
   * Called after stream completion when tool activities have been accumulated.
   */
  updateToolActivities(messageId: string, activities: ToolActivity[]): void {
    if (activities.length === 0) return
    this.db()
      .prepare('UPDATE messages SET tool_activities_json = ? WHERE id = ?')
      .run(JSON.stringify(activities), messageId)
  }

  updatePlanAction(messageId: string, action: string): void {
    this.db()
      .prepare('UPDATE messages SET plan_action = ? WHERE id = ?')
      .run(action, messageId)
  }
}

