import { BaseRepository } from '../base-repository'

/**
 * MCP-06: Escape SQL LIKE wildcard characters in user-supplied path values.
 * Without this, a path containing '%' or '_' would match more broadly than intended.
 */
function escapeLikePattern(value: string): string {
  return value.replace(/[%_\\]/g, '\\$&')
}

export type EdgeType = 'calls' | 'imports' | 'extends' | 'implements' | 'references'

export interface CodeGraphEdge {
  id?: string
  workspaceId: string
  sourceFile: string
  sourceSymbol: string
  targetFile: string
  targetSymbol: string
  edgeType: EdgeType
  pageRank?: number
}

interface EdgeRow {
  id: string
  workspace_id: string
  source_file: string
  source_symbol: string
  target_file: string
  target_symbol: string
  edge_type: string
  page_rank: number | null
  created_at: string
}

function mapRow(row: EdgeRow): CodeGraphEdge {
  return {
    id: row.id,
    workspaceId: row.workspace_id,
    sourceFile: row.source_file,
    sourceSymbol: row.source_symbol,
    targetFile: row.target_file,
    targetSymbol: row.target_symbol,
    edgeType: row.edge_type as EdgeType,
    pageRank: row.page_rank ?? 0
  }
}

/**
 * Repository for the `code_graph_edges` table.
 * Caches symbol relationships computed by repomap / tree-sitter analysis.
 */
export class CodeGraphEdgeRepository extends BaseRepository<EdgeRow, CodeGraphEdge> {
  protected readonly tableName = 'code_graph_edges'
  protected mapRow(row: EdgeRow): CodeGraphEdge {
    return mapRow(row)
  }

  /**
   * Bulk upsert graph edges for a workspace.
   * Clears existing edges first, then inserts new ones in a single transaction.
   *
   * For large edge sets, prefer `upsertEdgesBatched()` which breaks the work
   * into chunks with event-loop yielding to keep the UI responsive.
   */
  upsertEdges(workspaceId: string, edges: CodeGraphEdge[]): void {
    const db = this.db()

    const transaction = db.transaction(() => {
      // Clear existing edges for workspace
      db.prepare('DELETE FROM code_graph_edges WHERE workspace_id = ?').run(workspaceId)

      const stmt = db.prepare(`
        INSERT INTO code_graph_edges
          (workspace_id, source_file, source_symbol, target_file, target_symbol, edge_type, page_rank)
        VALUES (?, ?, ?, ?, ?, ?, ?)
      `)

      for (const edge of edges) {
        stmt.run(
          workspaceId,
          edge.sourceFile,
          edge.sourceSymbol,
          edge.targetFile,
          edge.targetSymbol,
          edge.edgeType,
          edge.pageRank ?? 0
        )
      }
    })

    transaction()
  }

  /**
   * Batched upsert with event-loop yielding between chunks.
   * Prevents multi-second main-thread freezes for large workspaces
   * (e.g. 5.5M edges). DELETE runs in one fast statement, then INSERTs
   * are chunked into transactions of BATCH_SIZE rows with setImmediate()
   * yields between each batch to let the event loop pump the Windows
   * message queue and keep the UI responsive.
   */
  async upsertEdgesBatched(workspaceId: string, edges: CodeGraphEdge[]): Promise<void> {
    const BATCH_SIZE = 5000
    const db = this.db()

    const deleteStmt = db.prepare('DELETE FROM code_graph_edges WHERE workspace_id = ?')
    const insertStmt = db.prepare(`
      INSERT INTO code_graph_edges
        (workspace_id, source_file, source_symbol, target_file, target_symbol, edge_type, page_rank)
      VALUES (?, ?, ?, ?, ?, ?, ?)
    `)

    for (let i = 0; i < edges.length; i += BATCH_SIZE) {
      const batch = edges.slice(i, Math.min(i + BATCH_SIZE, edges.length))
      const txn = db.transaction(() => {
        // DELETE runs inside the first batch's transaction so that if the
        // process crashes mid-batch, we either keep the old edges (rolled
        // back) or have at least the first batch committed. Without this,
        // a crash after a standalone DELETE leaves zero edges.
        if (i === 0) {
          deleteStmt.run(workspaceId)
        }
        for (const edge of batch) {
          insertStmt.run(
            workspaceId,
            edge.sourceFile,
            edge.sourceSymbol,
            edge.targetFile,
            edge.targetSymbol,
            edge.edgeType,
            edge.pageRank ?? 0
          )
        }
      })
      txn()

      // Yield to the event loop between batches so the UI stays responsive.
      // setImmediate fires after I/O events, giving the message pump a chance.
      if (i + BATCH_SIZE < edges.length) {
        await new Promise<void>((resolve) => setImmediate(resolve))
      }
    }

    // Handle edge case: no edges to insert (empty graph).
    // Still need to clear old edges.
    if (edges.length === 0) {
      deleteStmt.run(workspaceId)
    }
  }

  /**
   * Get all edges for a workspace.
   */
  findByWorkspace(workspaceId: string): CodeGraphEdge[] {
    const db = this.db()
    const rows = db
      .prepare('SELECT * FROM code_graph_edges WHERE workspace_id = ?')
      .all(workspaceId) as EdgeRow[]
    return rows.map(mapRow)
  }

  /**
   * Find all edges where the given symbol is the target (i.e., who calls/references it).
   */
  findCallersOf(workspaceId: string, targetSymbol: string): CodeGraphEdge[] {
    const db = this.db()
    const rows = db
      .prepare('SELECT * FROM code_graph_edges WHERE workspace_id = ? AND target_symbol = ?')
      .all(workspaceId, targetSymbol) as EdgeRow[]
    return rows.map(mapRow)
  }

  /**
   * Find all edges where the given symbol is the source (i.e., what does it call/reference).
   */
  findCalleesOf(workspaceId: string, sourceSymbol: string): CodeGraphEdge[] {
    const db = this.db()
    const rows = db
      .prepare('SELECT * FROM code_graph_edges WHERE workspace_id = ? AND source_symbol = ?')
      .all(workspaceId, sourceSymbol) as EdgeRow[]
    return rows.map(mapRow)
  }

  /**
   * Delete all edges for a workspace.
   */
  deleteByWorkspace(workspaceId: string): number {
    const db = this.db()
    const result = db
      .prepare('DELETE FROM code_graph_edges WHERE workspace_id = ?')
      .run(workspaceId)
    return result.changes
  }

  /**
   * Find files that a given file depends on, grouped by edge type.
   * (SELECT DISTINCT target_file, edge_type WHERE source_file = ?)
   */
  findDependenciesOf(
    workspaceId: string,
    sourceFile: string
  ): { targetFile: string; edgeType: EdgeType }[] {
    const db = this.db()
    const rows = db
      .prepare(
        `SELECT DISTINCT target_file, edge_type
         FROM code_graph_edges
         WHERE workspace_id = ? AND source_file = ?
         ORDER BY edge_type, target_file`
      )
      .all(workspaceId, sourceFile) as { target_file: string; edge_type: string }[]
    return rows.map((r) => ({
      targetFile: r.target_file,
      edgeType: r.edge_type as EdgeType
    }))
  }

  /**
   * Find files that depend on a given file (blast radius), grouped by edge type.
   * (SELECT DISTINCT source_file, edge_type WHERE target_file = ?)
   */
  findDependentsOf(
    workspaceId: string,
    targetFile: string
  ): { sourceFile: string; edgeType: EdgeType }[] {
    const db = this.db()
    const rows = db
      .prepare(
        `SELECT DISTINCT source_file, edge_type
         FROM code_graph_edges
         WHERE workspace_id = ? AND target_file = ?
         ORDER BY edge_type, source_file`
      )
      .all(workspaceId, targetFile) as { source_file: string; edge_type: string }[]
    return rows.map((r) => ({
      sourceFile: r.source_file,
      edgeType: r.edge_type as EdgeType
    }))
  }

  /**
   * Count total edges for a workspace.
   */
  countByWorkspace(workspaceId: string): number {
    const db = this.db()
    const row = db
      .prepare('SELECT COUNT(*) as count FROM code_graph_edges WHERE workspace_id = ?')
      .get(workspaceId) as { count: number }
    return row.count
  }

  /**
   * Find file pairs ranked by coupling strength (number of cross-references).
   */
  findCoupledFiles(
    workspaceId: string,
    opts?: { minCoupling?: number; path?: string; maxResults?: number }
  ): { sourceFile: string; targetFile: string; edgeCount: number }[] {
    const db = this.db()
    const minCoupling = opts?.minCoupling ?? 2
    const maxResults = opts?.maxResults ?? 50
    // MCP-06: Escape LIKE wildcards in user-supplied path
    const pathFilter = opts?.path
      ? `AND (source_file LIKE ? || '%' ESCAPE '\\' OR target_file LIKE ? || '%' ESCAPE '\\')`
      : ''
    const params: (string | number)[] = [workspaceId]
    if (opts?.path) {
      const escapedPath = escapeLikePattern(opts.path)
      params.push(escapedPath, escapedPath)
    }
    params.push(minCoupling, maxResults)

    const rows = db
      .prepare(
        `SELECT source_file, target_file, COUNT(*) as edge_count
         FROM code_graph_edges
         WHERE workspace_id = ? AND source_file != target_file
         ${pathFilter}
         GROUP BY source_file, target_file
         HAVING edge_count >= ?
         ORDER BY edge_count DESC
         LIMIT ?`
      )
      .all(...params) as { source_file: string; target_file: string; edge_count: number }[]
    return rows.map((r) => ({
      sourceFile: r.source_file,
      targetFile: r.target_file,
      edgeCount: r.edge_count
    }))
  }

  /**
   * Get module boundary health metrics — counts intra-module vs cross-module edges.
   * Module boundaries determined by directory depth.
   */
  getModuleBoundaryMetrics(
    workspaceId: string,
    depth: number = 2
  ): { module: string; internal: number; external: number; ratio: number }[] {
    // Compute module prefixes in JS from the raw edges — simpler than complex SQL substr
    const edges = this.findByWorkspace(workspaceId)

    const getModule = (filePath: string): string => {
      const parts = filePath.split('/')
      return parts.slice(0, Math.min(depth, parts.length)).join('/')
    }

    // Count per-module internal and external edges
    const moduleCounts = new Map<string, { internal: number; external: number }>()

    for (const edge of edges) {
      const srcMod = getModule(edge.sourceFile)
      const tgtMod = getModule(edge.targetFile)
      const entry = moduleCounts.get(srcMod) ?? { internal: 0, external: 0 }
      if (srcMod === tgtMod) {
        entry.internal++
      } else {
        entry.external++
      }
      moduleCounts.set(srcMod, entry)
    }

    return Array.from(moduleCounts.entries())
      .map(([module, counts]) => ({
        module,
        internal: counts.internal,
        external: counts.external,
        ratio:
          counts.internal + counts.external > 0
            ? Math.round((counts.internal / (counts.internal + counts.external)) * 100) / 100
            : 0
      }))
      .sort((a, b) => a.ratio - b.ratio) // worst cohesion first
  }

  /**
   * BFS-based transitive blast radius — finds ALL files transitively affected
   * by changing the given file, with depth tracking.
   * Unlike findDependentsOf (direct only), this follows the reverse import graph
   * to the full transitive closure.
   */
  findTransitiveDependents(
    workspaceId: string,
    filePath: string,
    maxDepth: number = 5
  ): { file: string; depth: number }[] {
    const db = this.db()
    const stmt = db.prepare(
      `SELECT DISTINCT source_file
       FROM code_graph_edges
       WHERE workspace_id = ? AND target_file = ? AND source_file != target_file`
    )

    const visited = new Set<string>([filePath])
    const result: { file: string; depth: number }[] = []
    let frontier = [filePath]

    for (let depth = 1; depth <= maxDepth && frontier.length > 0; depth++) {
      const nextFrontier: string[] = []
      for (const file of frontier) {
        const rows = stmt.all(workspaceId, file) as { source_file: string }[]
        for (const row of rows) {
          if (!visited.has(row.source_file)) {
            visited.add(row.source_file)
            result.push({ file: row.source_file, depth })
            nextFrontier.push(row.source_file)
          }
        }
      }
      frontier = nextFrontier
    }

    return result
  }
}

export const codeGraphEdgeRepository = new CodeGraphEdgeRepository()

import { BaseRepository } from '../base-repository'

/**
 * MCP-06: Escape SQL LIKE wildcard characters in user-supplied path values.
 * Without this, a path containing '%' or '_' would match more broadly than intended.
 */
function escapeLikePattern(value: string): string {
  return value.replace(/[%_\\]/g, '\\$&')
}

interface CodeGraphTagRow {
  id: number
  workspace_id: string
  rel_fname: string
  fname: string
  line: number
  name: string
  kind: 'def' | 'ref'
  file_mtime: number
  indexed_at: string
}

export interface RepomapTag {
  relFname: string
  fname: string
  line: number
  name: string
  kind: 'def' | 'ref'
}

/**
 * Repository for the `code_graph_tags` table.
 * Stores raw Tree-sitter tags (definitions + references) for incremental re-indexing
 * and for `search_identifiers` queries against the persisted code graph.
 */
export class CodeGraphTagRepository extends BaseRepository<CodeGraphTagRow, RepomapTag> {
  protected readonly tableName = 'code_graph_tags'
  protected mapRow(row: CodeGraphTagRow): RepomapTag {
    return mapRowToTag(row)
  }

  /**
   * Bulk upsert tags for a workspace. Deletes stale files first,
   * then inserts/replaces tags grouped by file.
   */
  upsertTags(workspaceId: string, tags: RepomapTag[], fileMtimes: Map<string, number>): void {
    const db = this.db()

    const transaction = db.transaction(() => {
      // Group tags by file for batch delete + insert
      const fileSet = new Set(tags.map((t) => t.relFname))

      // Delete existing tags for files that have new tags
      const deleteStmt = db.prepare(
        'DELETE FROM code_graph_tags WHERE workspace_id = ? AND rel_fname = ?'
      )
      for (const relFname of fileSet) {
        deleteStmt.run(workspaceId, relFname)
      }

      // Insert all new tags
      const insertStmt = db.prepare(`
        INSERT INTO code_graph_tags (workspace_id, rel_fname, fname, line, name, kind, file_mtime)
        VALUES (?, ?, ?, ?, ?, ?, ?)
      `)

      for (const tag of tags) {
        const mtime = fileMtimes.get(tag.relFname) ?? 0
        insertStmt.run(workspaceId, tag.relFname, tag.fname, tag.line, tag.name, tag.kind, mtime)
      }
    })

    transaction()
  }

  /**
   * Get all definition tags for a workspace (used for edge graph building).
   */
  findDefsByWorkspace(workspaceId: string): RepomapTag[] {
    const db = this.db()
    const rows = db
      .prepare(
        `SELECT rel_fname, fname, line, name, kind FROM code_graph_tags
         WHERE workspace_id = ? AND kind = 'def'`
      )
      .all(workspaceId) as CodeGraphTagRow[]
    return rows.map(mapRowToTag)
  }

  /**
   * Get all tags for a specific file (used when loading cached tags for unchanged files).
   */
  findByFile(workspaceId: string, relFname: string): RepomapTag[] {
    const db = this.db()
    const rows = db
      .prepare(
        'SELECT rel_fname, fname, line, name, kind FROM code_graph_tags WHERE workspace_id = ? AND rel_fname = ?'
      )
      .all(workspaceId, relFname) as CodeGraphTagRow[]
    return rows.map(mapRowToTag)
  }

  /**
   * Search tags by identifier name (case-insensitive substring match).
   */
  searchByName(
    workspaceId: string,
    query: string,
    opts?: {
      maxResults?: number
      includeDefinitions?: boolean
      includeReferences?: boolean
    }
  ): RepomapTag[] {
    const db = this.db()
    const maxResults = opts?.maxResults ?? 50
    const includeDefs = opts?.includeDefinitions ?? true
    const includeRefs = opts?.includeReferences ?? true

    const kindFilter =
      includeDefs && includeRefs
        ? ''
        : includeDefs
          ? "AND kind = 'def'"
          : includeRefs
            ? "AND kind = 'ref'"
            : 'AND 1 = 0'

    const rows = db
      .prepare(
        `SELECT rel_fname, fname, line, name, kind FROM code_graph_tags
         WHERE workspace_id = ? AND name LIKE ? ${kindFilter}
         ORDER BY kind ASC, rel_fname ASC
         LIMIT ?`
      )
      .all(workspaceId, `%${query}%`, maxResults) as CodeGraphTagRow[]
    return rows.map(mapRowToTag)
  }

  /**
   * Get file mtimes for incremental indexing comparison.
   */
  getFileMtimes(workspaceId: string): Map<string, number> {
    const db = this.db()
    const rows = db
      .prepare('SELECT DISTINCT rel_fname, file_mtime FROM code_graph_tags WHERE workspace_id = ?')
      .all(workspaceId) as { rel_fname: string; file_mtime: number }[]

    const map = new Map<string, number>()
    for (const row of rows) {
      map.set(row.rel_fname, row.file_mtime)
    }
    return map
  }

  /**
   * Delete all tags for a specific file.
   */
  deleteByFile(workspaceId: string, relFname: string): number {
    const db = this.db()
    const result = db
      .prepare('DELETE FROM code_graph_tags WHERE workspace_id = ? AND rel_fname = ?')
      .run(workspaceId, relFname)
    return result.changes
  }

  /**
   * Delete all tags for a workspace.
   */
  deleteByWorkspace(workspaceId: string): number {
    const db = this.db()
    const result = db.prepare('DELETE FROM code_graph_tags WHERE workspace_id = ?').run(workspaceId)
    return result.changes
  }

  /**
   * Get ALL tags (def + ref) for a workspace — used for full edge graph rebuild
   * after incremental file re-parsing.
   */
  findAllByWorkspace(workspaceId: string): RepomapTag[] {
    const db = this.db()
    const rows = db
      .prepare(
        'SELECT rel_fname, fname, line, name, kind FROM code_graph_tags WHERE workspace_id = ?'
      )
      .all(workspaceId) as CodeGraphTagRow[]
    return rows.map(mapRowToTag)
  }

  /**
   * Find definitions with zero cross-file references in the workspace.
   * A "dead" symbol has a 'def' tag but no matching 'ref' tag by name
   * in any other file. Optional path filters results to a subdirectory.
   */
  findDeadCode(
    workspaceId: string,
    options?: { path?: string; maxResults?: number }
  ): RepomapTag[] {
    const db = this.db()
    const limit = options?.maxResults ?? 100
    // MCP-06: Escape LIKE wildcards in user-supplied path
    const pathFilter = options?.path ? `AND d.rel_fname LIKE ? || '%' ESCAPE '\\'` : ''
    const params: (string | number)[] = [workspaceId, workspaceId]
    if (options?.path) {
      params.push(escapeLikePattern(options.path))
    }
    params.push(limit)

    const rows = db
      .prepare(
        `SELECT d.rel_fname, d.fname, d.line, d.name, d.kind
         FROM code_graph_tags d
         WHERE d.workspace_id = ? AND d.kind = 'def'
         ${pathFilter}
         AND NOT EXISTS (
           SELECT 1 FROM code_graph_tags r
           WHERE r.workspace_id = ?
             AND r.kind = 'ref'
             AND r.name = d.name
             AND r.rel_fname != d.rel_fname
         )
         ORDER BY d.rel_fname, d.line
         LIMIT ?`
      )
      .all(...params) as CodeGraphTagRow[]
    return rows.map(mapRowToTag)
  }

  /**
   * Find the most-referenced symbols (hotspots) — symbols with the most cross-file references.
   */
  findSymbolHotspots(
    workspaceId: string,
    opts?: { maxResults?: number; path?: string }
  ): { name: string; refCount: number }[] {
    const db = this.db()
    const maxResults = opts?.maxResults ?? 30
    // MCP-06: Escape LIKE wildcards in user-supplied path
    const pathFilter = opts?.path ? `AND rel_fname LIKE ? || '%' ESCAPE '\\'` : ''
    const params: (string | number)[] = [workspaceId]
    if (opts?.path) params.push(escapeLikePattern(opts.path))
    params.push(maxResults)

    const rows = db
      .prepare(
        `SELECT name, COUNT(*) as ref_count
         FROM code_graph_tags
         WHERE workspace_id = ? AND kind = 'ref'
         ${pathFilter}
         GROUP BY name
         ORDER BY ref_count DESC
         LIMIT ?`
      )
      .all(...params) as { name: string; ref_count: number }[]
    return rows.map((r) => ({ name: r.name, refCount: r.ref_count }))
  }

  /**
   * Count total tags for a workspace.
   */
  countByWorkspace(workspaceId: string): number {
    const db = this.db()
    const row = db
      .prepare('SELECT COUNT(*) as count FROM code_graph_tags WHERE workspace_id = ?')
      .get(workspaceId) as { count: number }
    return row.count
  }
}

function mapRowToTag(row: CodeGraphTagRow): RepomapTag {
  return {
