// ── Repository ──────────────────────────────────────────────────────────────

export class GrillSessionRepository extends BaseRepository<GrillSessionRow, GrillSession> {
  protected readonly tableName = 'grill_sessions'
  protected mapRow(row: GrillSessionRow): GrillSession {
    return mapRow(row)
  }

  /** Find the latest grill session for an idea */
  findByIdeaId(ideaId: string): GrillSession | null {
    const row = this.db()
      .prepare(`SELECT * FROM grill_sessions WHERE idea_id = ? ORDER BY updated_at DESC LIMIT 1`)
      .get(ideaId) as GrillSessionRow | undefined
    return row ? mapRow(row) : null
  }

  /** Create a new session */
  create(ideaId: string, workspaceId: string, trackId?: GrillTrackId): GrillSession {
    const id = crypto.randomUUID().replace(/-/g, '').toLowerCase()
    this.db()
      .prepare(
        `INSERT INTO grill_sessions (id, idea_id, workspace_id, track_id) VALUES (?, ?, ?, ?)`
      )
      .run(id, ideaId, workspaceId, trackId ?? null)

    // GRILL-CREATE-NONNULL-ASSERTION-01: Explicit check instead of non-null assertion
    // to surface a clear error if the row is not immediately readable.
    const created = this.findById(id)
    if (!created) throw new Error(`GrillSessionRepository.create: row not found after INSERT (id=${id})`)
    return created
  }

  /** Find by primary key */
  override findById(id: string): GrillSession | undefined {
    return this.findOneBy('id', id)
  }

  /** Update session status */
  updateStatus(id: string, status: GrillSessionStatus): void {
    this.db()
      .prepare(`UPDATE grill_sessions SET status = ?, updated_at = datetime('now') WHERE id = ?`)
      .run(status, id)
  }

  /** Bulk-append messages — reads once, writes once. */
  appendMessages(id: string, messages: unknown[]): void {
    if (messages.length === 0) return
    // GRILL-APPENDMSGS-QUADRATIC-01: Build array in JS and write once
    // instead of N individual json_insert calls that each read/write the full column.
    const existing = this.db()
      .prepare(`SELECT messages FROM grill_sessions WHERE id = ?`)
      .get(id) as { messages: string } | undefined
    const parsed: unknown[] = existing?.messages ? safeParseJSON<unknown[]>(existing.messages, []) : []
    parsed.push(...messages)
    this.db()
      .prepare(
        `UPDATE grill_sessions SET messages = ?, updated_at = datetime('now') WHERE id = ?`
      )
      .run(JSON.stringify(parsed), id)
  }

  /** Update score, label, and feedback after evaluation */
  updateScore(id: string, score: number, scoreLabel: string, feedback: string): void {
    // GRILL-SCORE-NOCLAMP-01: Defensive clamping in case upstream validation is bypassed.
    const clampedScore = Math.min(10, Math.max(0, score))
    if (!Number.isFinite(clampedScore)) {
      throw new Error(`updateScore: score must be a finite number, got ${score}`)
    }
    // GRILL-ITERATION-01: Increment iteration_count so the DB tracks actual
    // re-evaluation count. Without this, iteration_count stays at 0 forever
    // and useGrillSessionRestore() shows stale progress after app restart.
    this.db()
      .prepare(
        `UPDATE grill_sessions
       SET current_score = ?, score_label = ?, feedback = ?,
           iteration_count = iteration_count + 1,
           updated_at = datetime('now')
       WHERE id = ?`
      )
      .run(clampedScore, scoreLabel, feedback, id)
  }

  /** Update question states and current iteration (after questions arrive or user answers) */
  updateQuestionStates(
    id: string,
    questionStates: Record<string, unknown> | null,
    currentIteration: unknown | null
  ): void {
    this.db()
      .prepare(
        `UPDATE grill_sessions
       SET question_states = ?, current_iteration = ?,
           updated_at = datetime('now')
       WHERE id = ?`
      )
      .run(
        questionStates ? JSON.stringify(questionStates) : null,
        currentIteration ? JSON.stringify(currentIteration) : null,
        id
      )
  }

  /** Update track ID */
  updateTrackId(id: string, trackId: GrillTrackId | null): void {
    this.db()
      .prepare(`UPDATE grill_sessions SET track_id = ?, updated_at = datetime('now') WHERE id = ?`)
      .run(trackId, id)
  }

  /** Link a temporary grill session to a newly created workspace */
  linkToWorkspace(sessionId: string, workspaceId: string): void {
    this.db()
      .prepare(
        `UPDATE grill_sessions SET workspace_id = ?, updated_at = datetime('now') WHERE id = ?`
      )
      .run(workspaceId, sessionId)
  }

  /** Save a structured plan to the session */
  savePlan(sessionId: string, plan: GrillStructuredPlan): void {
    this.db()
      .prepare(`UPDATE grill_sessions SET plan_json = ?, updated_at = datetime('now') WHERE id = ?`)
      .run(JSON.stringify(plan), sessionId)
  }

  /** Retrieve the structured plan from a session */
  getPlan(sessionId: string): GrillStructuredPlan | null {
    const row = this.db()
      .prepare(`SELECT plan_json FROM grill_sessions WHERE id = ?`)
      .get(sessionId) as { plan_json: string | null } | undefined
    if (!row || !row.plan_json) return null
    return safeParseJSON<GrillStructuredPlan | null>(row.plan_json, null)
  }

  /**
   * Mark a session completed and strip transient state, keeping the generated plan.
   * Used at the final handoff (Start Goal / Council Sweep / Convert Directly) so
   * re-entry shows a plan-only completed view instead of the full chat.
   */
  completeAndStrip(ideaId: string): void {
    this.db()
      .prepare(
        `UPDATE grill_sessions
       SET status = 'completed',
           messages = '[]',
           history = '[]',
           track_scores = '[]',
           question_states = NULL,
           current_iteration = NULL,
           updated_at = datetime('now')
       WHERE idea_id = ?`
      )
      .run(ideaId)
  }

  /** Delete every grill session row for an idea (explicit "Discard grill"). */
  deleteByIdeaId(ideaId: string): void {
    this.db().prepare(`DELETE FROM grill_sessions WHERE idea_id = ?`).run(ideaId)
  }

  /** Idea IDs in this workspace that have a generated (persisted) plan. */
  findIdeaIdsWithPlan(workspaceId: string): string[] {
    const rows = this.db()
      .prepare(
        `SELECT DISTINCT idea_id FROM grill_sessions
         WHERE workspace_id = ? AND plan_json IS NOT NULL`
      )
      .all(workspaceId) as { idea_id: string }[]
    return rows.map((r) => r.idea_id)
  }

  /**
   * Recover sessions left 'evaluating' by a previous crash/quit (no live
   * process can still be running them). Called on app startup. Sessions with a
   * prior score revert to 'awaiting_answers' (user can continue); otherwise
   * they are marked 'failed'.
   */
  terminateStale(): number {
    const result = this.db()
      .prepare(
        `UPDATE grill_sessions
           SET status = CASE WHEN current_score IS NOT NULL THEN 'awaiting_answers' ELSE 'failed' END,
               updated_at = datetime('now')
         WHERE status = 'evaluating'`
      )
      .run()
    return result.changes
  }

  /** Get active sessions for a workspace (evaluating or awaiting_answers) */
  getActiveForWorkspace(workspaceId: string): GrillSession[] {
    const rows = this.db()
      .prepare(
        `SELECT * FROM grill_sessions
         WHERE workspace_id = ? AND status IN ('evaluating', 'awaiting_answers')
         ORDER BY updated_at DESC`
      )
      .all(workspaceId) as GrillSessionRow[]
    return rows.map(mapRow)
  }
}

export const grillSessionRepository = new GrillSessionRepository()

/**
 * plan.repository — CRUD + lifecycle for the unified plans registry.
 *
 * The `plans` table is a write-alongside registry: plans are auto-registered
 * from Chat, Grill, Audit, Council, and MPA sources. Existing source tables
 * remain untouched — this table provides cross-modal visibility and lifecycle.
 */

import { BaseRepository } from '../base-repository'
import { safeParseJSON } from '../json-utils'
import type {
  StructuredPlan,
  PlanRecord,
  PlanSource,
  PlanStatus,
  PlanType,
  PlanFilters,
  PlanStatusHistoryEntry,
  PhaseProgress
} from '../../../shared/types'

// ── Row shape (snake_case from DB) ──

interface PlanRow {
  id: string
  workspace_id: string
  source: PlanSource
  source_id: string
  title: string
  summary: string
  plan_type: string | null
  structured_plan_json: string
  source_plan_json: string | null
  requirement_document: string | null
  status: PlanStatus
  linked_conversation_id: string | null
  linked_mpa_run_id: string | null
  linked_council_session_id: string | null
  file_count: number
  phase_count: number
  risk_count: number
  created_at: string
  updated_at: string
  completed_at: string | null
  previous_plan_id: string | null
}

interface StatusHistoryRow {
  id: string
  plan_id: string
  from_status: string | null
  to_status: string
  changed_at: string
  actor: string
}

function mapStatusHistoryRow(row: StatusHistoryRow): PlanStatusHistoryEntry {
  return {
    id: row.id,
    planId: row.plan_id,
    fromStatus: row.from_status as PlanStatus | null,
    toStatus: row.to_status as PlanStatus,
    changedAt: row.changed_at,
    actor: row.actor
  }
}

function mapRow(row: PlanRow): PlanRecord {
  return {
    id: row.id,
    workspaceId: row.workspace_id,
    source: row.source,
    sourceId: row.source_id,
    title: row.title,
    summary: row.summary ?? '',
    planType: (row.plan_type as PlanType) ?? null,
    structuredPlan: safeParseJSON<StructuredPlan>(row.structured_plan_json, {
      title: row.title,
      summary: row.summary ?? ''
    }),
    sourcePlanJson: row.source_plan_json,
    requirementDocument: row.requirement_document,
    status: row.status,
    linkedConversationId: row.linked_conversation_id,
    linkedMpaRunId: row.linked_mpa_run_id,
    linkedCouncilSessionId: row.linked_council_session_id,
    fileCount: row.file_count ?? 0,
    phaseCount: row.phase_count ?? 0,
    riskCount: row.risk_count ?? 0,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
    completedAt: row.completed_at,
    previousPlanId: row.previous_plan_id ?? null
  }
}

// ── Save params ──

export interface SavePlanParams {
  workspaceId: string
  source: PlanSource
  sourceId: string
  title: string
  summary: string
  planType?: PlanType | null
  structuredPlan: StructuredPlan
  sourcePlanJson?: string | null
  requirementDocument?: string | null
  linkedConversationId?: string | null
  linkedMpaRunId?: string | null
  linkedCouncilSessionId?: string | null
}

// ── Derived metrics ──

function deriveCounts(plan: StructuredPlan): {
  fileCount: number
  phaseCount: number
  riskCount: number
} {
  const files = new Set<string>()
  if (plan.files) plan.files.forEach((f) => files.add(f))
  if (plan.filesChanged) plan.filesChanged.forEach((f) => files.add(f.file))
  if (plan.phases) {
    for (const phase of plan.phases) {
      if (phase.files) phase.files.forEach((f) => files.add(f.file))
    }
  }
  return {
    fileCount: files.size,
    phaseCount: plan.phases?.length ?? 0,
    riskCount: plan.risks?.length ?? 0
  }
}

// ── Repository ──

const RETENTION_LIMIT = 50

export class PlanRepository extends BaseRepository<PlanRow, PlanRecord> {
  protected readonly tableName = 'plans'
  protected mapRow(row: PlanRow): PlanRecord {
    return mapRow(row)
  }

  /** Persist a plan to the registry. Returns the saved record. */
  savePlan(params: SavePlanParams): PlanRecord {
    const counts = deriveCounts(params.structuredPlan)

    const row = this.db()
      .prepare(
        `INSERT INTO plans (
          workspace_id, source, source_id, title, summary, plan_type,
          structured_plan_json, source_plan_json, requirement_document,
          linked_conversation_id, linked_mpa_run_id, linked_council_session_id,
          file_count, phase_count, risk_count
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        RETURNING *`
      )
      .get(
        params.workspaceId,
        params.source,
        params.sourceId,
        params.title,
        params.summary,
        params.planType ?? params.structuredPlan.type ?? null,
        JSON.stringify(params.structuredPlan),
        params.sourcePlanJson ?? null,
        params.requirementDocument ?? null,
        params.linkedConversationId ?? null,
        params.linkedMpaRunId ?? null,
        params.linkedCouncilSessionId ?? null,
        counts.fileCount,
        counts.phaseCount,
        counts.riskCount
      ) as PlanRow

    const savedPlan = mapRow(row)

    // ── Revision linking: auto-archive previous plan from same source ──
    // Scoped to the same linked conversation (when set) so two concurrent chat
    // conversations in one workspace don't archive each other's active plan —
    // sources without a linked conversation (blueprint/audit/council revisions)
    // keep the original workspace-wide "latest wins" behavior.
    if (params.source && params.sourceId) {
      const existing = this.db()
        .prepare(
          `SELECT id, status FROM plans
           WHERE workspace_id = ? AND source = ? AND id != ? AND status != 'archived'
             AND (linked_conversation_id IS NULL OR linked_conversation_id = ?)
           ORDER BY created_at DESC LIMIT 1`
        )
        .get(
          params.workspaceId,
          params.source,
          savedPlan.id,
          params.linkedConversationId ?? null
        ) as { id: string; status: string } | undefined
      if (existing) {
        this.updateStatus(existing.id, 'archived', undefined, 'system')
        this.db()
          .prepare('UPDATE plans SET previous_plan_id = ? WHERE id = ?')
          .run(existing.id, savedPlan.id)
        // Re-read to pick up the previous_plan_id
        const updated = this.getById(savedPlan.id)
        if (updated) {
          // Record initial status and enforce retention
          this.recordStatusChange(savedPlan.id, null, 'saved', 'system')
          this.enforceRetention(params.workspaceId)
          return updated
        }
      }
    }

    // Record initial status
    this.recordStatusChange(savedPlan.id, null, 'saved', 'system')

    // Enforce retention
    this.enforceRetention(params.workspaceId)

    return savedPlan
  }

  /** Get a single plan by ID. */
  getById(id: string): PlanRecord | null {
    const row = this.db().prepare('SELECT * FROM plans WHERE id = ?').get(id) as PlanRow | undefined
    return row ? mapRow(row) : null
  }

  /** Get plans for a workspace, newest first. Supports filtering. */
  getForWorkspace(workspaceId: string, filters?: PlanFilters): PlanRecord[] {
    const conditions = ['workspace_id = ?']
    const params: unknown[] = [workspaceId]

    if (filters?.status) {
      if (Array.isArray(filters.status)) {
        conditions.push(`status IN (${filters.status.map(() => '?').join(',')})`)
        params.push(...filters.status)
      } else {
        conditions.push('status = ?')
        params.push(filters.status)
      }
    }
    if (filters?.source) {
      conditions.push('source = ?')
      params.push(filters.source)
    }
    if (filters?.search) {
      conditions.push('(title LIKE ? OR summary LIKE ?)')
      const term = `%${filters.search}%`
      params.push(term, term)
    }

    const rows = this.db()
      .prepare(`SELECT * FROM plans WHERE ${conditions.join(' AND ')} ORDER BY updated_at DESC`)
      .all(...params) as PlanRow[]
    return rows.map(mapRow)
  }

  /** Find the most recent in-progress plan linked to a conversation. */
  findActiveByConversationId(conversationId: string): PlanRecord | null {
    const row = this.db()
      .prepare(
        `SELECT * FROM plans
         WHERE linked_conversation_id = ? AND status IN ('in_progress', 'saved')
         ORDER BY updated_at DESC LIMIT 1`
      )
      .get(conversationId) as PlanRow | undefined
    return row ? mapRow(row) : null
  }

  /** Check if a plan from this source already exists (prevents duplicates). */
  findBySource(source: PlanSource, sourceId: string): PlanRecord | null {
    const row = this.db()
      .prepare('SELECT * FROM plans WHERE source = ? AND source_id = ?')
      .get(source, sourceId) as PlanRow | undefined
    return row ? mapRow(row) : null
  }

  /** Update status + optional linked IDs. Also records status change in the timeline. */
  updateStatus(
    id: string,
    status: PlanStatus,
    links?: {
      conversationId?: string
      mpaRunId?: string
      councilSessionId?: string
    },
    actor: string = 'user'
  ): void {
    const current = this.getById(id)
    const fromStatus = current?.status ?? null

    const sets = ['status = ?', "updated_at = datetime('now')"]
    const params: unknown[] = [status]

    // Set completed_at for terminal statuses
    const isTerminal = status === 'completed' || status === 'archived'
    if (isTerminal) {
      sets.push("completed_at = datetime('now')")
    }

    if (links?.conversationId !== undefined) {
      sets.push('linked_conversation_id = ?')
      params.push(links.conversationId)
    }
    if (links?.mpaRunId !== undefined) {
      sets.push('linked_mpa_run_id = ?')
      params.push(links.mpaRunId)
    }
    if (links?.councilSessionId !== undefined) {
      sets.push('linked_council_session_id = ?')
      params.push(links.councilSessionId)
    }

    params.push(id)
    this.db()
      .prepare(`UPDATE plans SET ${sets.join(', ')} WHERE id = ?`)
      .run(...params)

    this.recordStatusChange(id, fromStatus, status, actor)
  }

  // ── Lifecycle convenience methods ──

  markHandedOff(id: string, conversationId: string): void {
    this.updateStatus(id, 'handed_off', { conversationId })
  }

  markInProgress(id: string): void {
    this.updateStatus(id, 'in_progress')
  }

  markCompleted(id: string): void {
    this.updateStatus(id, 'completed')
  }

  markArchived(id: string): void {
    this.updateStatus(id, 'archived')
  }

  /** Delete a plan by ID. Returns true if deleted. */
  deletePlan(id: string): boolean {
    const result = this.db().prepare('DELETE FROM plans WHERE id = ?').run(id)
    return result.changes > 0
  }

  /** Keep only the newest N plans per workspace. */
  enforceRetention(workspaceId: string, limit: number = RETENTION_LIMIT): void {
    this.db()
      .prepare(
        `DELETE FROM plans WHERE workspace_id = ? AND id NOT IN (
          SELECT id FROM plans WHERE workspace_id = ?
          ORDER BY updated_at DESC LIMIT ?
        )`
      )
      .run(workspaceId, workspaceId, limit)
  }

  // ── Status History ──

  /** Record a status transition in the timeline. */
  recordStatusChange(
    planId: string,
    fromStatus: PlanStatus | null,
    toStatus: PlanStatus,
    actor = 'user'
  ): void {
    this.db()
      .prepare(
        `INSERT INTO plan_status_history (plan_id, from_status, to_status, actor)
         VALUES (?, ?, ?, ?)`
      )
      .run(planId, fromStatus, toStatus, actor)
  }

  /** Fetch full status timeline for a plan, oldest-first. */
  getStatusHistory(planId: string): PlanStatusHistoryEntry[] {
    const rows = this.db()
      .prepare(
        `SELECT id, plan_id, from_status, to_status, changed_at, actor
         FROM plan_status_history WHERE plan_id = ? ORDER BY changed_at ASC`
      )
      .all(planId) as StatusHistoryRow[]
    return rows.map(mapStatusHistoryRow)
  }

  // ── Phase Progress ──

  /** Update a single phase's progress status. Merges into the existing JSON array. */
  updatePhaseProgress(
    planId: string,
    phaseId: number,
    status: string,
    completedAt?: string,
    touchedFiles?: string[],
    taskUpdate?: { taskId: string; title: string; status: string }
  ): void {
    const row = this.db()
      .prepare('SELECT phase_progress_json FROM plans WHERE id = ?')
      .get(planId) as { phase_progress_json: string | null } | undefined

    const progress: PhaseProgress[] = safeParseJSON(row?.phase_progress_json, [])
    const existing = progress.find((p) => p.phaseId === phaseId)

    if (existing) {
      existing.status = status
      if (status === 'completed' || status === 'failed') {
        existing.completedAt = completedAt ?? new Date().toISOString()
      }
      // Merge touchedFiles (deduped)
      if (touchedFiles && touchedFiles.length > 0) {
        const current = existing.touchedFiles ?? []
        const merged = [...new Set([...current, ...touchedFiles])]
        existing.touchedFiles = merged
      }
      // Merge task update
      if (taskUpdate) {
        const tasks = existing.tasks ?? []
        const taskIdx = tasks.findIndex((t) => t.taskId === taskUpdate.taskId)
        if (taskIdx >= 0) {
          tasks[taskIdx] = { ...tasks[taskIdx], ...taskUpdate }
        } else {
          tasks.push(taskUpdate)
        }
        existing.tasks = tasks
      }
    } else {
      progress.push({
        phaseId,
        status,
        startedAt: new Date().toISOString(),
        completedAt:
          status === 'completed' || status === 'failed'
            ? (completedAt ?? new Date().toISOString())
            : null,
        touchedFiles: touchedFiles ?? [],
        tasks: taskUpdate ? [taskUpdate] : undefined
      })
    }

    this.db()
      .prepare("UPDATE plans SET phase_progress_json = ?, updated_at = datetime('now') WHERE id = ?")
      .run(JSON.stringify(progress), planId)
  }

  /** Get phase progress for a plan. */
  getPhaseProgress(planId: string): PhaseProgress[] {
    const row = this.db()
      .prepare('SELECT phase_progress_json FROM plans WHERE id = ?')
      .get(planId) as { phase_progress_json: string | null } | undefined
    return safeParseJSON(row?.phase_progress_json, [])
  }

  // ── Revision Linking ──

  /** Get the plan that superseded this one (if any). */
  getSupersedingPlan(planId: string): PlanRecord | null {
    const row = this.db()
      .prepare('SELECT * FROM plans WHERE previous_plan_id = ?')
      .get(planId) as PlanRow | undefined
    return row ? mapRow(row) : null
  }

  /** Get the previous revision of this plan (if any). */
  getPreviousPlan(planId: string): PlanRecord | null {
    const current = this.getById(planId)
    if (!current?.previousPlanId) return null
    return this.getById(current.previousPlanId)
  }
}

export const planRepository = new PlanRepository()

/**
 * todo.repository — CRUD for persistent conversation todos.
 *
 * Todos are ephemeral in the Zustand store but persisted here so they
 * survive app restarts. Each mutation is called from the chunk-router
 * when a todo_update StreamChunk arrives.
 */

import { getDatabase } from '../index'

export interface TodoItem {
  id: number
  conversationId: string
  text: string
  completed: boolean
  itemIndex: number | null
  createdAt: string
  updatedAt: string
}

interface TodoRow {
  id: number
  conversation_id: string
  text: string
  completed: number
  item_index: number | null
  created_at: string
  updated_at: string
}

function db() {
  return getDatabase()
}

function mapRow(row: TodoRow): TodoItem {
  return {
    id: row.id,
    conversationId: row.conversation_id,
    text: row.text,
    completed: row.completed === 1,
    itemIndex: row.item_index,
    createdAt: row.created_at,
    updatedAt: row.updated_at
  }
}

export class TodoRepository {
  saveTodo(conversationId: string, text: string, index?: number): void {
    db()
      .prepare(
        `INSERT INTO conversation_todos (conversation_id, text, item_index)
         VALUES (?, ?, ?)`
      )
      .run(conversationId, text, index ?? null)
  }

  completeTodo(conversationId: string, text: string, index?: number): void {
    // Match by text (and optionally index) to handle cases where the todo
    // text is the unique identifier from the agent.
    if (index != null) {
      db()
        .prepare(
          `UPDATE conversation_todos
           SET completed = 1, updated_at = datetime('now')
           WHERE conversation_id = ? AND text = ? AND item_index = ?`
        )
        .run(conversationId, text, index)
    } else {
      db()
        .prepare(
          `UPDATE conversation_todos
           SET completed = 1, updated_at = datetime('now')
           WHERE conversation_id = ? AND text = ?`
        )
        .run(conversationId, text)
    }
  }

  removeTodo(conversationId: string, text: string, index?: number): void {
    if (index != null) {
      db()
        .prepare(
          'DELETE FROM conversation_todos WHERE conversation_id = ? AND text = ? AND item_index = ?'
        )
        .run(conversationId, text, index)
    } else {
      db()
        .prepare('DELETE FROM conversation_todos WHERE conversation_id = ? AND text = ?')
        .run(conversationId, text)
    }
  }

  /**
   * Replace the entire todo list for a conversation. Used for TodoWrite's
   * full-snapshot contract (CLI backend) — each call carries the complete
   * authoritative list, so a delete+reinsert reconcile is correct and avoids
   * the duplicate-row accumulation that per-item saveTodo() would produce
   * across separate CLI process spawns (one per turn).
   */
  syncTodos(
    conversationId: string,
    todos: Array<{ text: string; completed: boolean; index: number }>
  ): void {
    const run = db().transaction(() => {
      db().prepare('DELETE FROM conversation_todos WHERE conversation_id = ?').run(conversationId)
      const insert = db().prepare(
        `INSERT INTO conversation_todos (conversation_id, text, completed, item_index)
         VALUES (?, ?, ?, ?)`
      )
      for (const t of todos) {
        insert.run(conversationId, t.text, t.completed ? 1 : 0, t.index)
      }
    })
    run()
  }

  findByConversation(conversationId: string): TodoItem[] {
    const rows = db()
      .prepare(
        `SELECT id, conversation_id, text, completed, item_index, created_at, updated_at
         FROM conversation_todos
         WHERE conversation_id = ?
         ORDER BY created_at ASC`
      )
      .all(conversationId) as TodoRow[]
    return rows.map(mapRow)
  }

  clearByConversation(conversationId: string): void {
    db()
      .prepare('DELETE FROM conversation_todos WHERE conversation_id = ?')
      .run(conversationId)
  }
}

export const todoRepository = new TodoRepository()

/**
 * Library Documentation Repository — manages cached library docs
 * with FTS5 full-text search and three-tier source tracking.
 */
import { BaseRepository } from '../base-repository'

// ── Types ──

interface LibraryDocRow {
  id: number
  workspace_id: string
  package_name: string
  version: string
  section_index: number
  section_title: string
  section_content: string
  source: string
  indexed_at: string
}

export interface LibraryDoc {
  id: number
  workspaceId: string
  packageName: string
  version: string
  sectionIndex: number
  sectionTitle: string
  sectionContent: string
  source: string
  indexedAt: string
}

export interface PackageSummary {
  packageName: string
  version: string
  sectionCount: number
  source: string
}

// ── Repository ──

export class LibraryDocRepository extends BaseRepository<LibraryDocRow, LibraryDoc> {
  protected readonly tableName = 'library_docs'

  protected mapRow(row: LibraryDocRow): LibraryDoc {
    return {
      id: row.id,
      workspaceId: row.workspace_id,
      packageName: row.package_name,
      version: row.version,
      sectionIndex: row.section_index,
      sectionTitle: row.section_title,
      sectionContent: row.section_content,
      source: row.source,
      indexedAt: row.indexed_at
    }
  }

  /**
   * Upsert sections for a package — delete old sections, insert new ones in a transaction.
   * Also syncs FTS5 content triggers.
   */
  upsertSections(
    workspaceId: string,
    packageName: string,
    version: string,
    source: string,
    sections: { title: string; content: string }[]
  ): void {
    const db = this.db()
    this.runTransaction(() => {
      // Delete old sections (and their FTS entries)
      const oldRows = db
        .prepare('SELECT id FROM library_docs WHERE workspace_id = ? AND package_name = ?')
        .all(workspaceId, packageName) as { id: number }[]

      for (const row of oldRows) {
        db.prepare(
          "INSERT INTO library_docs_fts(library_docs_fts, rowid, package_name, section_title, section_content) VALUES('delete', ?, ?, ?, ?)"
        ).run(
          row.id,
          packageName,
          '', // will be replaced by actual values
          ''
        )
      }

      // Delete old rows using direct SQL for FTS sync
      db.prepare('DELETE FROM library_docs WHERE workspace_id = ? AND package_name = ?').run(
        workspaceId,
        packageName
      )

      // Insert new sections
      const insertStmt = db.prepare(`
        INSERT INTO library_docs (workspace_id, package_name, version, section_index, section_title, section_content, source)
        VALUES (?, ?, ?, ?, ?, ?, ?)
      `)

      for (let i = 0; i < sections.length; i++) {
        const section = sections[i]
        insertStmt.run(workspaceId, packageName, version, i, section.title, section.content, source)
      }

      // Sync FTS5 index with newly inserted rows
      const newRows = db
        .prepare(
          'SELECT id, package_name, section_title, section_content FROM library_docs WHERE workspace_id = ? AND package_name = ?'
        )
        .all(workspaceId, packageName) as {
        id: number
        package_name: string
        section_title: string
        section_content: string
      }[]

      for (const row of newRows) {
        db.prepare(
          'INSERT INTO library_docs_fts(rowid, package_name, section_title, section_content) VALUES(?, ?, ?, ?)'
        ).run(row.id, row.package_name, row.section_title, row.section_content)
      }
    })
  }

  /**
   * FTS5 search across cached docs, optionally scoped to a package.
   * Returns matching sections ranked by relevance.
   */
  searchDocs(
    workspaceId: string,
    query: string,
    opts?: { packageName?: string; maxResults?: number }
  ): LibraryDoc[] {
    const db = this.db()
    const maxResults = opts?.maxResults ?? 10

    // Sanitize query for FTS5 — escape special chars and use OR for multi-word
    const sanitized = query
      .replace(/[^\w\s-]/g, '') // remove FTS5 special chars
      .split(/\s+/)
      .filter(Boolean)
      .map((w) => `"${w}"`)
      .join(' OR ')

    if (!sanitized) return []

    let sql = `
      SELECT ld.* FROM library_docs ld
      JOIN library_docs_fts fts ON ld.id = fts.rowid
      WHERE library_docs_fts MATCH ?
        AND ld.workspace_id = ?
    `
    const params: unknown[] = [sanitized, workspaceId]

    if (opts?.packageName) {
      sql += ' AND ld.package_name = ?'
      params.push(opts.packageName)
    }

    sql += ' ORDER BY rank LIMIT ?'
    params.push(maxResults)

    const rows = db.prepare(sql).all(...params) as LibraryDocRow[]
    return rows.map((r) => this.mapRow(r))
  }

  /** List all cached packages for a workspace. */
  listPackages(workspaceId: string): PackageSummary[] {
    const db = this.db()
    const rows = db
      .prepare(
        `SELECT package_name, version, source, COUNT(*) as section_count
         FROM library_docs
         WHERE workspace_id = ?
         GROUP BY package_name
         ORDER BY package_name`
      )
      .all(workspaceId) as {
      package_name: string
      version: string
      source: string
      section_count: number
    }[]

    return rows.map((r) => ({
      packageName: r.package_name,
      version: r.version,
      sectionCount: r.section_count,
      source: r.source
    }))
  }

  /** Check if a package is cached and within TTL. */
  isCached(workspaceId: string, packageName: string, maxAgeMs = 7 * 24 * 60 * 60 * 1000): boolean {
    const db = this.db()
    const row = db
      .prepare(
        'SELECT indexed_at FROM library_docs WHERE workspace_id = ? AND package_name = ? LIMIT 1'
      )
      .get(workspaceId, packageName) as { indexed_at: string } | undefined

    if (!row) return false

    const indexedAt = new Date(row.indexed_at + 'Z').getTime()
    return Date.now() - indexedAt < maxAgeMs
  }

  /** Delete all docs for a workspace. */
  deleteByWorkspace(workspaceId: string): void {
    const db = this.db()
    this.runTransaction(() => {
      // Get all IDs to delete from FTS
      const rows = db
        .prepare(
          'SELECT id, package_name, section_title, section_content FROM library_docs WHERE workspace_id = ?'
        )
        .all(workspaceId) as LibraryDocRow[]

      for (const row of rows) {
        db.prepare(
          "INSERT INTO library_docs_fts(library_docs_fts, rowid, package_name, section_title, section_content) VALUES('delete', ?, ?, ?, ?)"
        ).run(row.id, row.package_name, row.section_title, row.section_content)
      }

      db.prepare('DELETE FROM library_docs WHERE workspace_id = ?').run(workspaceId)
    })
  }
}

export const libraryDocRepository = new LibraryDocRepository()

/**
 * Blueprint repository — CRUD for blueprints, blueprint_phases, and blueprint_tasks tables.
 *
 * Follows the BaseRepository pattern. Uses safeParseJSON for JSON TEXT columns
 * to prevent corrupted rows from crashing features.
 */

import log from 'electron-log'
import { BaseRepository } from '../base-repository'
import { safeParseJSON } from '../json-utils'
import type {
  Blueprint,
  BlueprintPhase,
  BlueprintTask,
  BlueprintArtifact,
  BlueprintStatus,
  BlueprintPhaseType,
  BlueprintPhaseStatus,
  BlueprintTaskStatus,
  BlueprintPriority
} from '../../../shared/blueprint-types'

// ── Row Interfaces (match SQLite schema) ──

interface BlueprintRow {
  id: string
  workspace_id: string
  title: string
  short_name: string
  description: string
  status: string
  current_phase: string
  priority: string
  source_idea_id: string | null
  constitution_snapshot: string | null
  settings_json: string | null
  created_at: string
  updated_at: string
  completed_at: string | null
}

interface BlueprintPhaseRow {
  id: string
  blueprint_id: string
  phase: string
  status: string
  conversation_id: string | null
  artifacts_json: string
  context_snapshot: string | null
  started_at: string | null
  completed_at: string | null
}

interface BlueprintTaskRow {
  id: string
  blueprint_id: string
  task_id: string
  wave: number
  user_story: string | null
  description: string
  file_paths_json: string
  is_parallel: number
  depends_on_json: string
  status: string
  executor_run_id: string | null
  started_at: string | null
  completed_at: string | null
  completion_json: string | null
}

// ── Row Mappers ──

function mapBlueprintRow(row: BlueprintRow): Blueprint {
  return {
    id: row.id,
    workspaceId: row.workspace_id,
    title: row.title,
    shortName: row.short_name,
    description: row.description,
    status: row.status as BlueprintStatus,
    currentPhase: row.current_phase as BlueprintPhaseType,
    priority: row.priority as BlueprintPriority,
    sourceIdeaId: row.source_idea_id,
    constitutionSnapshot: row.constitution_snapshot,
    settingsJson: safeParseJSON<Record<string, unknown>>(row.settings_json, {}),
    createdAt: row.created_at,
    updatedAt: row.updated_at,
    completedAt: row.completed_at
  }
}

function mapPhaseRow(row: BlueprintPhaseRow): BlueprintPhase {
  return {
    id: row.id,
    blueprintId: row.blueprint_id,
    phase: row.phase as BlueprintPhaseType,
    status: row.status as BlueprintPhaseStatus,
    conversationId: row.conversation_id,
    artifactsJson: safeParseJSON<BlueprintArtifact[]>(row.artifacts_json, []),
    contextSnapshot: row.context_snapshot,
    startedAt: row.started_at,
    completedAt: row.completed_at
  }
}

function mapTaskRow(row: BlueprintTaskRow): BlueprintTask {
  return {
    id: row.id,
    blueprintId: row.blueprint_id,
    taskId: row.task_id,
    wave: row.wave,
    userStory: row.user_story,
    description: row.description,
    filePathsJson: safeParseJSON<string[]>(row.file_paths_json, []),
    isParallel: row.is_parallel === 1,
    dependsOnJson: safeParseJSON<string[]>(row.depends_on_json, []),
    status: row.status as BlueprintTaskStatus,
    executorRunId: row.executor_run_id,
    startedAt: row.started_at,
    completedAt: row.completed_at,
    completionJson: safeParseJSON<{ filesCreated: string[]; filesModified: string[] } | null>(
      row.completion_json, null
    )
  }
}

// ── Blueprint Repository ──

export class BlueprintRepository extends BaseRepository<BlueprintRow, Blueprint> {
  protected readonly tableName = 'blueprints'
  protected mapRow(row: BlueprintRow): Blueprint {
    return mapBlueprintRow(row)
  }

  // ── Create ──

  create(params: {
    workspaceId: string
    title: string
    description?: string
    priority?: BlueprintPriority
    sourceIdeaId?: string
    constitutionSnapshot?: string
    settingsJson?: Record<string, unknown>
  }): Blueprint {
    const row = this.db()
      .prepare(
        `INSERT INTO blueprints (workspace_id, title, description, priority, source_idea_id, constitution_snapshot, settings_json)
         VALUES (?, ?, ?, ?, ?, ?, ?)
         RETURNING *`
      )
      .get(
        params.workspaceId,
        params.title,
        params.description ?? '',
        params.priority ?? 'P1',
        params.sourceIdeaId ?? null,
        params.constitutionSnapshot ?? null,
        JSON.stringify(params.settingsJson ?? {})
      ) as BlueprintRow
    return mapBlueprintRow(row)
  }

  // ── Read ──

  findByWorkspace(workspaceId: string, limit = 50): Blueprint[] {
    return this.findManyBy('workspace_id', workspaceId, {
      orderBy: 'created_at DESC',
      limit
    })
  }

  findByStatus(workspaceId: string, status: BlueprintStatus): Blueprint[] {
    const rows = this.db()
      .prepare(
        `SELECT * FROM blueprints WHERE workspace_id = ? AND status = ? ORDER BY created_at DESC`
      )
      .all(workspaceId, status) as BlueprintRow[]
    return rows.map(mapBlueprintRow)
  }

  // ── Update ──

  updateStatus(id: string, status: BlueprintStatus): Blueprint | undefined {
    const isTerminal = status === 'complete' || status === 'failed' || status === 'cancelled'
    const sql = isTerminal
      ? `UPDATE blueprints SET status = ?, completed_at = datetime('now'), updated_at = datetime('now') WHERE id = ? RETURNING *`
      : `UPDATE blueprints SET status = ?, updated_at = datetime('now') WHERE id = ? RETURNING *`
    const row = this.db().prepare(sql).get(status, id) as BlueprintRow | undefined
    return row ? mapBlueprintRow(row) : undefined
  }

  updatePhase(id: string, phase: BlueprintPhaseType): Blueprint | undefined {
    const row = this.db()
      .prepare(
        `UPDATE blueprints SET current_phase = ?, updated_at = datetime('now') WHERE id = ? RETURNING *`
      )
      .get(phase, id) as BlueprintRow | undefined
    return row ? mapBlueprintRow(row) : undefined
  }

  updateShortName(id: string, shortName: string): Blueprint | undefined {
    const row = this.db()
      .prepare(
        `UPDATE blueprints SET short_name = ?, updated_at = datetime('now') WHERE id = ? RETURNING *`
      )
      .get(shortName, id) as BlueprintRow | undefined
    return row ? mapBlueprintRow(row) : undefined
  }

  update(
    id: string,
    data: {
      title?: string
      description?: string
      shortName?: string
      status?: BlueprintStatus
      currentPhase?: BlueprintPhaseType
      priority?: BlueprintPriority
      constitutionSnapshot?: string
      settingsJson?: Record<string, unknown>
    }
  ): Blueprint | undefined {
    const sets: string[] = []
    const values: unknown[] = []

    if (data.title !== undefined) {
      sets.push('title = ?')
      values.push(data.title)
    }
    if (data.description !== undefined) {
      sets.push('description = ?')
      values.push(data.description)
    }
    if (data.shortName !== undefined) {
      sets.push('short_name = ?')
      values.push(data.shortName)
    }
    if (data.status !== undefined) {
      sets.push('status = ?')
      values.push(data.status)
      // Sync completed_at with terminal status transitions
      const isTerminal = data.status === 'complete' || data.status === 'failed' || data.status === 'cancelled'
      if (isTerminal) {
        sets.push("completed_at = datetime('now')")
      } else {
        sets.push('completed_at = NULL')
      }
    }
    if (data.currentPhase !== undefined) {
      sets.push('current_phase = ?')
      values.push(data.currentPhase)
    }
    if (data.priority !== undefined) {
      sets.push('priority = ?')
      values.push(data.priority)
    }
    if (data.constitutionSnapshot !== undefined) {
      sets.push('constitution_snapshot = ?')
      values.push(data.constitutionSnapshot)
    }
    if (data.settingsJson !== undefined) {
      sets.push('settings_json = ?')
      values.push(JSON.stringify(data.settingsJson))
    }

    if (sets.length === 0) return this.findById(id)

    sets.push("updated_at = datetime('now')")
    values.push(id)

    const row = this.db()
      .prepare(`UPDATE blueprints SET ${sets.join(', ')} WHERE id = ? RETURNING *`)
      .get(...values) as BlueprintRow | undefined
    return row ? mapBlueprintRow(row) : undefined
  }

  // ── Delete ──

  delete(id: string): void {
    this.deleteById(id)
  }

  // ── Stale detection ──

  markStaleAsFailed(excludeIds: string[] = []): number {
    const db = this.db()
    let query = `UPDATE blueprints SET status = 'failed', completed_at = datetime('now'), updated_at = datetime('now')
         WHERE status IN ('specifying', 'clarifying', 'planning', 'tasking', 'reviewing', 'building', 'verifying')`
    const params: string[] = []
    if (excludeIds.length > 0) {
      const placeholders = excludeIds.map(() => '?').join(', ')
      query += ` AND id NOT IN (${placeholders})`
      params.push(...excludeIds)
    }
    const changes = db.prepare(query).run(...params).changes

    // BP-STALE-RECONCILE-01: Cascade cleanup to phases and tasks stuck in
    // active/running states. Without this, the UI shows permanently stuck
    // tasks and phases after an app crash during a BUILD phase.
    if (changes > 0) {
      db.prepare(
        `UPDATE blueprint_phases SET status = 'failed', completed_at = datetime('now')
         WHERE status = 'active'
           AND blueprint_id IN (
             SELECT id FROM blueprints WHERE status = 'failed'
           )`
      ).run()

      db.prepare(
        `UPDATE blueprint_tasks SET status = 'failed', completed_at = datetime('now')
         WHERE status = 'running'
           AND blueprint_id IN (
             SELECT id FROM blueprints WHERE status = 'failed'
           )`
      ).run()
    }

    return changes
  }
}

// ── Blueprint Phase Repository ──

export class BlueprintPhaseRepository extends BaseRepository<BlueprintPhaseRow, BlueprintPhase> {
  protected readonly tableName = 'blueprint_phases'
  protected mapRow(row: BlueprintPhaseRow): BlueprintPhase {
    return mapPhaseRow(row)
  }

  // ── Create ──

  create(params: {
    blueprintId: string
    phase: BlueprintPhaseType
    conversationId?: string
  }): BlueprintPhase {
    const row = this.db()
      .prepare(
        `INSERT INTO blueprint_phases (blueprint_id, phase, conversation_id)
         VALUES (?, ?, ?)
         RETURNING *`
      )
      .get(params.blueprintId, params.phase, params.conversationId ?? null) as BlueprintPhaseRow
    return mapPhaseRow(row)
  }

  /** Create all 7 phase records for a new blueprint (bulk insert). */
  createAllPhases(blueprintId: string): BlueprintPhase[] {
    const phases: BlueprintPhaseType[] = [
      'specify',
      'clarify',
      'plan',
      'tasks',
      'review',
      'build',
      'verify'
    ]
    const stmt = this.db().prepare(
      `INSERT INTO blueprint_phases (blueprint_id, phase) VALUES (?, ?) RETURNING *`
    )
    return this.runTransaction(() =>
      phases.map((phase) => mapPhaseRow(stmt.get(blueprintId, phase) as BlueprintPhaseRow))
    )
  }

  // ── Read ──

  findByBlueprint(blueprintId: string): BlueprintPhase[] {
    const rows = this.db()
      .prepare(
        `SELECT * FROM blueprint_phases WHERE blueprint_id = ?
         ORDER BY CASE phase
           WHEN 'specify' THEN 1
           WHEN 'clarify' THEN 2
           WHEN 'plan' THEN 3
           WHEN 'tasks' THEN 4
           WHEN 'review' THEN 5
           WHEN 'build' THEN 6
           WHEN 'verify' THEN 7
         END`
      )
      .all(blueprintId) as BlueprintPhaseRow[]
    return rows.map(mapPhaseRow)
  }

  findByBlueprintAndPhase(
    blueprintId: string,
    phase: BlueprintPhaseType
  ): BlueprintPhase | undefined {
    const row = this.db()
      .prepare(`SELECT * FROM blueprint_phases WHERE blueprint_id = ? AND phase = ?`)
      .get(blueprintId, phase) as BlueprintPhaseRow | undefined
    return row ? mapPhaseRow(row) : undefined
  }

  // ── Update ──

  updateStatus(id: string, status: BlueprintPhaseStatus): BlueprintPhase | undefined {
    const timestampCol =
      status === 'active'
        ? 'started_at'
        : status === 'complete' || status === 'failed'
          ? 'completed_at'
          : null

    let sql = `UPDATE blueprint_phases SET status = ?`
    if (timestampCol) sql += `, ${timestampCol} = datetime('now')`
    sql += ` WHERE id = ? RETURNING *`

    const row = this.db().prepare(sql).get(status, id) as BlueprintPhaseRow | undefined
    return row ? mapPhaseRow(row) : undefined
  }

  setConversation(id: string, conversationId: string): BlueprintPhase | undefined {
    // FK guard: conversation_id REFERENCES conversations(id). If the conversation
    // was never persisted (e.g. CLI exited before streaming any messages), the
    // UPDATE would throw SqliteError: FOREIGN KEY constraint failed. Skip instead.
    const conversationExists = this.db()
      .prepare(`SELECT 1 FROM conversations WHERE id = ?`)
      .get(conversationId)
    if (!conversationExists) {
      log.warn(
        `[blueprint-repo:setConversation] Conversation ${conversationId} not found — skipping FK link for phase ${id}`
      )
      return this.findById(id)
    }

    const row = this.db()
      .prepare(`UPDATE blueprint_phases SET conversation_id = ? WHERE id = ? RETURNING *`)
      .get(conversationId, id) as BlueprintPhaseRow | undefined
    return row ? mapPhaseRow(row) : undefined
  }

  saveArtifacts(id: string, artifacts: BlueprintArtifact[]): BlueprintPhase | undefined {
    const row = this.db()
      .prepare(`UPDATE blueprint_phases SET artifacts_json = ? WHERE id = ? RETURNING *`)
      .get(JSON.stringify(artifacts), id) as BlueprintPhaseRow | undefined
    return row ? mapPhaseRow(row) : undefined
  }

  appendArtifact(id: string, artifact: BlueprintArtifact): BlueprintPhase | undefined {
    const existing = this.findById(id)
    if (!existing) return undefined
    const artifacts = [...existing.artifactsJson, artifact]
    return this.saveArtifacts(id, artifacts)
  }

  /**
   * R2-2 fix: Atomically replace all artifacts of a given type with a single
   * new artifact. Does a fresh read inside the repo so callers never operate
   * on stale artifact lists. Returns the updated phase, or undefined if the
   * phase doesn't exist.
   */
  replaceArtifactOfType(id: string, type: string, artifact: BlueprintArtifact): BlueprintPhase | undefined {
    const existing = this.findById(id)          // fresh read inside the repo
    if (!existing) return undefined
    const filtered = existing.artifactsJson.filter((a) => a.type !== type)
    return this.saveArtifacts(id, [...filtered, artifact])
  }

  saveContextSnapshot(id: string, snapshot: string | null): BlueprintPhase | undefined {
    const row = this.db()
      .prepare(`UPDATE blueprint_phases SET context_snapshot = ? WHERE id = ? RETURNING *`)
      .get(snapshot, id) as BlueprintPhaseRow | undefined
    return row ? mapPhaseRow(row) : undefined
  }
}

// ── Blueprint Task Repository ──

export class BlueprintTaskRepository extends BaseRepository<BlueprintTaskRow, BlueprintTask> {
  protected readonly tableName = 'blueprint_tasks'
  protected mapRow(row: BlueprintTaskRow): BlueprintTask {
    return mapTaskRow(row)
  }

  // ── Create ──

  create(params: {
    blueprintId: string
    taskId: string
    wave: number
    description: string
    userStory?: string
    filePathsJson?: string[]
    isParallel?: boolean
    dependsOnJson?: string[]
  }): BlueprintTask {
    const row = this.db()
      .prepare(
        `INSERT INTO blueprint_tasks (blueprint_id, task_id, wave, description, user_story, file_paths_json, is_parallel, depends_on_json)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?)
         RETURNING *`
      )
      .get(
        params.blueprintId,
        params.taskId,
        params.wave,
        params.description,
        params.userStory ?? null,
        JSON.stringify(params.filePathsJson ?? []),
        params.isParallel ? 1 : 0,
        JSON.stringify(params.dependsOnJson ?? [])
      ) as BlueprintTaskRow
    return mapTaskRow(row)
  }

  /** Bulk-create tasks from parsed blueprint-tasks JSON. */
  createBulk(
    blueprintId: string,
    tasks: Array<{
      taskId: string
      wave: number
      description: string
      userStory?: string
      filePathsJson?: string[]
      isParallel?: boolean
      dependsOnJson?: string[]
    }>
  ): BlueprintTask[] {
    const stmt = this.db().prepare(
      `INSERT INTO blueprint_tasks (blueprint_id, task_id, wave, description, user_story, file_paths_json, is_parallel, depends_on_json)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?)
       RETURNING *`
    )
    return this.runTransaction(() =>
      tasks.map((t) =>
        mapTaskRow(
          stmt.get(
            blueprintId,
            t.taskId,
            t.wave,
            t.description,
            t.userStory ?? null,
            JSON.stringify(t.filePathsJson ?? []),
            t.isParallel ? 1 : 0,
            JSON.stringify(t.dependsOnJson ?? [])
          ) as BlueprintTaskRow
        )
      )
    )
  }

  // ── Read ──

  findByBlueprint(blueprintId: string): BlueprintTask[] {
    return this.findManyBy('blueprint_id', blueprintId, { orderBy: 'wave ASC, task_id ASC' })
  }

  findByWave(blueprintId: string, wave: number): BlueprintTask[] {
    const rows = this.db()
      .prepare(
        `SELECT * FROM blueprint_tasks WHERE blueprint_id = ? AND wave = ? ORDER BY task_id ASC`
      )
      .all(blueprintId, wave) as BlueprintTaskRow[]
    return rows.map(mapTaskRow)
  }

  getWaveCount(blueprintId: string): number {
    const result = this.db()
      .prepare(`SELECT MAX(wave) as max_wave FROM blueprint_tasks WHERE blueprint_id = ?`)
      .get(blueprintId) as { max_wave: number | null } | undefined
    return result?.max_wave ?? 0
  }

  // ── Update ──

  updateStatus(id: string, status: BlueprintTaskStatus): BlueprintTask | undefined {
    const timestampCol =
      status === 'running'
        ? 'started_at'
        : status === 'complete' || status === 'failed'
          ? 'completed_at'
          : null

    let sql = `UPDATE blueprint_tasks SET status = ?`
    if (timestampCol) sql += `, ${timestampCol} = datetime('now')`
    sql += ` WHERE id = ? RETURNING *`

    const row = this.db().prepare(sql).get(status, id) as BlueprintTaskRow | undefined
    return row ? mapTaskRow(row) : undefined
  }

  setExecutorRun(id: string, executorRunId: string): BlueprintTask | undefined {
    const row = this.db()
      .prepare(`UPDATE blueprint_tasks SET executor_run_id = ? WHERE id = ? RETURNING *`)
      .get(executorRunId, id) as BlueprintTaskRow | undefined
    return row ? mapTaskRow(row) : undefined
  }

  // ── Delete (bulk, for re-generating tasks) ──

  deleteByBlueprint(blueprintId: string): number {
    return this.deleteBy('blueprint_id', blueprintId)
  }

  /**
   * Delete all remediation tasks (R-prefixed taskIds) for a blueprint.
   * Used when retrying verify to clean up stale remediation from prior rounds.
   */
  deleteRemediationTasks(blueprintId: string): number {
    return this.db()
      .prepare(`DELETE FROM blueprint_tasks WHERE blueprint_id = ? AND task_id LIKE 'R%'`)
      .run(blueprintId).changes
  }

  /** Persist per-task completion data (filesCreated/filesModified) for verify-phase disk checks. */
  setCompletion(
    id: string,
    completion: { filesCreated: string[]; filesModified: string[] }
  ): BlueprintTask | undefined {
    const row = this.db()
      .prepare(`UPDATE blueprint_tasks SET completion_json = ? WHERE id = ? RETURNING *`)
      .get(JSON.stringify(completion), id) as BlueprintTaskRow | undefined
    return row ? mapTaskRow(row) : undefined
  }
}

