  parentClassImports: string[]
  siblingMethodSignatures: string[]
}

export interface ChunkMetadata {
  filePath: string
  fileName: string
  directory: string
  projectName: string
  symbolName: string
  symbolKind: string
  className: string | null
  signature: string
  startLine: number
