// matchesSkipPattern now lives in ../code-graph-exclusions (single source of
// truth shared with the code graph indexer) and is re-exported above.

/**
 * Stage 1: Determine if a file should be skipped from indexing.
 * Checks path-based patterns and content-based heuristics.
 */
export function shouldSkipFile(
  filePath: string,
  content: string,
  extraPatterns: string[] = []
): boolean {
  // Path-based filtering
  const allPatterns = [...SKIP_PATTERNS, ...extraPatterns]
  if (matchesSkipPattern(filePath, allPatterns)) {
    return true
  }

  // Content-based filtering: auto-generated files
  const firstLines = content.slice(0, 500).toLowerCase()
  if (
    firstLines.includes('auto-generated') ||
    firstLines.includes('this file is automatically generated') ||
    firstLines.includes('do not edit') ||
    firstLines.includes('generated by') ||
    firstLines.includes('@generated') ||
    firstLines.includes('<auto-generated>')
  ) {
    return true
  }

  // Skip minified files (very long lines, no newlines)
  const lines = content.split('\n')
  const avgLineLength = content.length / Math.max(lines.length, 1)
  if (avgLineLength > 500) {
    return true
  }

  // Skip files with almost no alphanumeric content (binary-ish)
  const alphanumCount = (content.match(/[a-zA-Z0-9]/g) ?? []).length
  const alphanumRatio = alphanumCount / Math.max(content.length, 1)
  if (alphanumRatio < 0.3) {
    return true
  }

  return false
}

/**
 * Single source of truth for path exclusion logic shared by BOTH indexers:
 * the code graph (code-graph.service.ts) and the embedding preprocessing
 * pipeline (preprocessing/file-validation.ts).
 *
 * Pure utility — no db/repository imports — so it can be unit tested without
 * triggering the heavy import chain (which requires Vite ?raw transforms).
 */

import path from 'node:path'

/**
 * A Set wrapper whose has() check is case-insensitive.
 *
 * Required for Windows compatibility: NTFS/ReFS are case-insensitive,
 * so a directory named "Packages" must match the exclusion "packages".
 * macOS HFS+ is also case-insensitive by default.
 */
export class CaseInsensitiveSet {
  private readonly lower: Set<string>
  constructor(values: Iterable<string>) {
    this.lower = new Set([...values].map((v) => v.toLowerCase()))
  }
  has(value: string): boolean {
    return this.lower.has(value.toLowerCase())
  }
  [Symbol.iterator](): IterableIterator<string> {
    return this.lower[Symbol.iterator]()
  }
}

/**
 * Additional directories to exclude from indexing.
 * Supplements repomap-mcp's EXCLUDED_DIRS with platform-specific build
 * artifacts and vendored dependency trees that aren't reliably in .gitignore.
 *
 * Primarily benefits .NET and C++ repos where bin/obj/packages/Tools dirs
 * contain thousands of compiled or vendored files. Vendored copies are
 * especially damaging because buildEdgesFromTags() emits defs x refs per
 * symbol name — N duplicate copies of a library multiply every common symbol
 * by N, which is how a workspace reached 5.5M edges.
 *
 * Deliberately NOT included: generic names like `lib`, `libs`, `docs`, `src`,
 * `test` — those are commonly first-party and excluding them would hide real
 * code. Use .atelierignore for workspace-specific cases.
 *
 * Case-insensitive: "Packages", "PACKAGES", "packages" all match.
 */
export const ADDITIONAL_EXCLUDED_DIRS = new CaseInsensitiveSet([
  // .NET — NuGet often creates "Packages" (capital P) on disk;
  // the CaseInsensitiveSet ensures all casing variants match.
  'bin',
  'obj',
  'packages',
  '.vs',
  'TestResults',
  'artifacts',
  'publish',
  // C++ / CMake
  'Debug',
  'Release',
  'x64',
  'x86',
  'ARM',
  'ARM64',
  'out',
  // IDE
  '.idea',
  // CI / deploy
  'BuildSystem',
  'Deploy',
  // Vendored third-party trees (NUnit, NuGet caches, bundled tooling)
  'Tools',
  'ThirdParty',
  'third_party',
  'thirdparty',
  'Externals',
  'externals',
  'NuGet',
  '.nuget',
  'Setup'
])

/**
 * Convert an absolute path to a workspace-relative POSIX path.
 *
 * REQUIRED for Windows correctness. The previous implementation used
 * `abs.replace(workspacePath + '/', '')`, which never matches native Windows
 * backslash paths — so tags and PageRank nodes were silently keyed by ABSOLUTE
 * paths, breaking edge resolution and duplicating nodes across re-index runs.
 */
export function toPosixRel(absPath: string, workspacePath: string): string {
  const rel = path.relative(workspacePath, absPath)
  return rel.split(path.sep).join('/')
}

/**
 * Returns true if the file path contains a directory segment that should
 * be excluded from indexing. Uses path separators to avoid false positives
 * (e.g. a file named "binary-utils.ts" should NOT be excluded by "bin").
 * Handles both forward and backslash separators for Windows compatibility
 * (fs.watch and path.relative use native separators on Windows).
 */
export function isExcludedPath(relPath: string): boolean {
  const segments = relPath.split(/[/\\]/)
  // Check all directory segments (not the filename)
  for (let i = 0; i < segments.length - 1; i++) {
    if (ADDITIONAL_EXCLUDED_DIRS.has(segments[i])) return true
  }
  return false
}

/**
 * Returns true if a single directory NAME should never be descended into.
 * Used by the pruning walker so excluded trees are never traversed at all,
 * rather than walked and then filtered out afterwards.
 */
export function isExcludedDirName(name: string): boolean {
  return ADDITIONAL_EXCLUDED_DIRS.has(name)
}

/**
 * Directory exclusions expressed as globs, for consumers that match on
 * glob patterns rather than path segments (the preprocessing pipeline).
 * Derived from ADDITIONAL_EXCLUDED_DIRS so the two can never drift.
 */
export function excludedDirGlobs(): string[] {
  return [...ADDITIONAL_EXCLUDED_DIRS].map((dir) => `**/${dir}/**`)
}

/**
 * Check if a file path matches any of the skip patterns using simple glob
 * matching. Patterns use ** for any path segment(s) and * for any non-/ chars.
 *
 * Moved here from preprocessing/file-validation.ts so both indexers and the
 * .atelierignore loader share one matcher implementation.
 */
export function matchesSkipPattern(filePath: string, patterns: string[]): boolean {
  const normalized = filePath.replace(/\\/g, '/')
  for (const pattern of patterns) {
    // Convert glob to regex using placeholder to avoid double-replacement
    const regexStr = pattern
      .replace(/\*\*/g, '\0GLOBSTAR\0') // placeholder for **
      .replace(/\*/g, '[^/]*') // * → non-slash chars
      .replace(/\./g, '\\.') // escape dots
      .replace(/\0GLOBSTAR\0\//g, '(?:.+/)?') // **/ → optional prefix ending in /
      .replace(/\/\0GLOBSTAR\0/g, '(?:/.+)?') // /** → optional suffix starting with /
      .replace(/\0GLOBSTAR\0/g, '.*') // ** standalone → anything
    if (new RegExp(`^${regexStr}$`).test(normalized)) {
      return true
    }
  }
  return false
}

/**
 * Hard intake guards. There was previously NO file-size cap at all, so
 * multi-megabyte generated files were read and handed to tree-sitter.
 */
export const MAX_INDEXABLE_FILE_BYTES = 1_000_000 // 1 MB

/**
 * Generated documentation (NUnit's HTML output, doxygen, javadoc) is the
 * dominant bloat source in vendored .NET trees: thousands of files that yield
 * ~0 tags. Markup is indexed only under this much smaller cap, and files that
 * parse to zero tags are dropped entirely (see code-graph.service.ts).
 */
export const MAX_INDEXABLE_MARKUP_BYTES = 100_000 // 100 KB
const MARKUP_EXTENSIONS = new Set(['.html', '.htm', '.xml', '.svg'])

/** Returns the size cap that applies to a given file path. */
export function sizeCapForFile(filePath: string): number {
  const ext = path.extname(filePath).toLowerCase()
  return MARKUP_EXTENSIONS.has(ext) ? MAX_INDEXABLE_MARKUP_BYTES : MAX_INDEXABLE_FILE_BYTES
}

/** True when a file is markup whose tags should be discarded if empty. */
export function isMarkupFile(filePath: string): boolean {
  return MARKUP_EXTENSIONS.has(path.extname(filePath).toLowerCase())
}

/**
 * Stage 2: Import extraction utilities for the preprocessing pipeline.
 *
 * Extracted from preprocessing.service.ts — purely functional,
 * no class dependencies.
 */

import type { RawChunk } from '../preprocessing.service'

/**
 * Extract relevant import names from file content that are used in a chunk.
 * Uses regex-based extraction (not AST — good enough for headers).
 */
export function extractRelevantImports(fileContent: string, chunk: RawChunk): string[] {
  const imports: string[] = []

  // Match ES import statements: import { X, Y } from 'module'
  const esImportRegex = /import\s+(?:type\s+)?{([^}]+)}\s+from\s+['"]([^'"]+)['"]/g
  // Match default imports: import X from 'module'
  const defaultImportRegex = /import\s+(?:type\s+)?(\w+)\s+from\s+['"]([^'"]+)['"]/g
  // Match C# using: using Namespace.Type;
  const csharpUsingRegex = /using\s+([\w.]+)\s*;/g

  const allImportedNames: { name: string; module: string }[] = []

  let match: RegExpExecArray | null
  while ((match = esImportRegex.exec(fileContent)) !== null) {
    const names = match[1].split(',').map((n) =>
      n
        .trim()
        .split(/\s+as\s+/)
        .pop()!
        .trim()
    )
    const module = match[2]
    for (const name of names) {
      if (name) allImportedNames.push({ name, module })
    }
  }

  while ((match = defaultImportRegex.exec(fileContent)) !== null) {
    allImportedNames.push({ name: match[1], module: match[2] })
  }

  while ((match = csharpUsingRegex.exec(fileContent)) !== null) {
    const parts = match[1].split('.')
    allImportedNames.push({ name: parts[parts.length - 1], module: match[1] })
  }

  // Filter to imports actually referenced in the chunk body
  for (const imp of allImportedNames) {
    if (chunk.body.includes(imp.name)) {
      imports.push(imp.name)
    }
  }

  return [...new Set(imports)].slice(0, 8)
}

/**
 * Stage 6: Chunk splitting utilities for the preprocessing pipeline.
 *
 * Extracted from preprocessing.service.ts — purely functional,
 * no class dependencies.
 */

import type { ProcessedChunk } from '../preprocessing.service'

/**
 * Stage 6: Split a chunk that exceeds maxLines with overlapping boundaries.
 */
export function splitLongChunk(
  chunk: ProcessedChunk,
  maxLines: number,
  overlapLines: number
): ProcessedChunk[] {
  const lines = chunk.body.split('\n')
  if (lines.length <= maxLines) return [chunk]

  const parts: ProcessedChunk[] = []
  let start = 0
  let partIndex = 0
  const totalParts = Math.ceil(lines.length / maxLines)

  while (start < lines.length) {
    const end = Math.min(start + maxLines, lines.length)
    const overlap = start > 0 ? lines.slice(start - overlapLines, start) : []
    const partBody = [...overlap, ...lines.slice(start, end)].join('\n')

    const partSymbolName = `${chunk.metadata.symbolName} (part ${partIndex + 1}/${totalParts})`

    parts.push({
      id: `${chunk.id}::part${partIndex}`,
      embedText: chunk.embedText, // Will be rebuilt with updated body
      body: partBody,
      metadata: {
        ...chunk.metadata,
        symbolName: partSymbolName,
        startLine: chunk.metadata.startLine + start - (start > 0 ? overlapLines : 0),
        endLine: chunk.metadata.startLine + end,
        lineCount: partBody.split('\n').length
      }
    })

    start = end
    partIndex++
  }

  return parts
}

/**
 * Unit tests for the description-cache.service.ts pure functions.
 * Tests key generation, get/set round-trip, and invalidation.
 *
 * Note: These tests use an in-memory mock since the real service
 * depends on Electron's app.getPath which is unavailable in test context.
 */
import assert from 'node:assert/strict'
import { createHash } from 'node:crypto'
import { test, describe } from './test-harness'

// ── Key generation (pure function — testable without Electron) ──

function makeKey(filePath: string, symbolName: string, body: string): string {
  return createHash('sha256')
    .update(filePath + symbolName + body)
    .digest('hex')
}

describe('makeKey', () => {
  test('produces deterministic key', () => {
    const key1 = makeKey('src/auth.ts', 'validate', 'code body')
    const key2 = makeKey('src/auth.ts', 'validate', 'code body')
    assert.equal(key1, key2)
  })

  test('different bodies produce different keys', () => {
    const key1 = makeKey('src/auth.ts', 'validate', 'code body v1')
    const key2 = makeKey('src/auth.ts', 'validate', 'code body v2')
    assert.notEqual(key1, key2)
  })

  test('different files produce different keys', () => {
    const key1 = makeKey('src/auth.ts', 'validate', 'code')
    const key2 = makeKey('src/user.ts', 'validate', 'code')
    assert.notEqual(key1, key2)
  })

  test('different symbols produce different keys', () => {
    const key1 = makeKey('src/auth.ts', 'validate', 'code')
    const key2 = makeKey('src/auth.ts', 'login', 'code')
    assert.notEqual(key1, key2)
  })

  test('key is a valid hex string', () => {
    const key = makeKey('file.ts', 'symbol', 'body')
    assert.ok(/^[a-f0-9]{64}$/.test(key), `Expected 64-char hex, got: ${key}`)
  })
})

// ── In-memory cache simulation (tests cache logic without SQLite) ──

class MockDescriptionCache {
  private store = new Map<
    string,
    { description: string; model: string; filePath: string; symbolName: string }
  >()

  makeKey(filePath: string, symbolName: string, body: string): string {
    return createHash('sha256')
      .update(filePath + symbolName + body)
      .digest('hex')
  }

  get(key: string): string | null {
    return this.store.get(key)?.description ?? null
  }

  set(key: string, description: string, model: string, filePath: string, symbolName: string): void {
    this.store.set(key, { description, model, filePath, symbolName })
  }

  invalidateFile(filePath: string): number {
    let count = 0
    for (const [key, entry] of this.store) {
      if (entry.filePath === filePath) {
        this.store.delete(key)
        count++
      }
    }
    return count
  }

  getCount(): number {
    return this.store.size
  }
}

describe('DescriptionCache (mock)', () => {
  test('get returns null for missing key', () => {
    const cache = new MockDescriptionCache()
    assert.equal(cache.get('nonexistent'), null)
  })

  test('get/set round-trip', () => {
    const cache = new MockDescriptionCache()
    const key = cache.makeKey('src/auth.ts', 'validate', 'code body')
    cache.set(key, 'Validates JWT tokens', 'haiku', 'src/auth.ts', 'validate')

    const result = cache.get(key)
    assert.equal(result, 'Validates JWT tokens')
  })

  test('set overwrites existing entry', () => {
    const cache = new MockDescriptionCache()
    const key = cache.makeKey('src/auth.ts', 'validate', 'code body')
    cache.set(key, 'Old description', 'haiku', 'src/auth.ts', 'validate')
    cache.set(key, 'New description', 'haiku', 'src/auth.ts', 'validate')

    assert.equal(cache.get(key), 'New description')
    assert.equal(cache.getCount(), 1)
  })

  test('invalidateFile removes correct entries', () => {
    const cache = new MockDescriptionCache()
    const key1 = cache.makeKey('src/auth.ts', 'validate', 'body1')
    const key2 = cache.makeKey('src/auth.ts', 'login', 'body2')
    const key3 = cache.makeKey('src/user.ts', 'getUser', 'body3')

    cache.set(key1, 'desc1', 'haiku', 'src/auth.ts', 'validate')
    cache.set(key2, 'desc2', 'haiku', 'src/auth.ts', 'login')
    cache.set(key3, 'desc3', 'haiku', 'src/user.ts', 'getUser')

    const removed = cache.invalidateFile('src/auth.ts')
    assert.equal(removed, 2)
    assert.equal(cache.getCount(), 1)
    assert.equal(cache.get(key3), 'desc3')
    assert.equal(cache.get(key1), null)
  })

  test('invalidateFile returns 0 for unknown file', () => {
    const cache = new MockDescriptionCache()
    assert.equal(cache.invalidateFile('nonexistent.ts'), 0)
  })

  test('getCount tracks entries', () => {
    const cache = new MockDescriptionCache()
    assert.equal(cache.getCount(), 0)

    cache.set('k1', 'd1', 'm', 'f', 's')
    assert.equal(cache.getCount(), 1)

    cache.set('k2', 'd2', 'm', 'f', 's')
    assert.equal(cache.getCount(), 2)
  })
})

