import { EventEmitter } from 'node:events'
import { statSync, readFileSync, readdirSync } from 'node:fs'
import type { Dirent } from 'node:fs'
import { join } from 'node:path'
import { execSync } from 'node:child_process'
import { createHash } from 'node:crypto'
import log from 'electron-log/main'
import { codeGraphTagRepository } from '../db/repositories'
import { codeGraphEdgeRepository } from '../db/repositories'
import { codeGraphRankRepository } from '../db/repositories'
import type { RepomapTag } from '../db/repositories/code-graph-tag.repository'
import type { CodeGraphIndexingState } from '../../shared/types'
import {
  CaseInsensitiveSet,
  isExcludedPath,
  isExcludedDirName,
  isMarkupFile,
  sizeCapForFile,
  toPosixRel,
  matchesSkipPattern
} from './code-graph-exclusions'
import { loadAllIgnorePatterns } from './workspace-ignore'
import { memoryCheckpoint } from './indexing-diagnostics'

/**
 * Directories repomap-mcp prunes internally — mirrored so our walker matches.
 * Uses CaseInsensitiveSet so "Build", "Dist", "Vendor" etc. are excluded on
 * case-insensitive filesystems (Windows NTFS, macOS HFS+).
 */
const REPOMAP_EXCLUDED_DIRS = new CaseInsensitiveSet([
  'node_modules', '__pycache__', 'venv', 'env', '.venv', '.env', 'dist', 'build',
  '.next', '.nuxt', 'target', 'vendor', '.bundle', 'coverage', '.nyc_output', '.tox', 'egg-info'
])

export interface DiscoveryResult {
  files: string[]
  prunedDirs: number
  oversizeSkipped: number
}

/**
 * Pruning file walker.
 *
 * Replaces `findSrcFiles(...).filter(...)`, which walked the ENTIRE tree —
 * including vendored NUnit and generated-doc directories — and only then
 * discarded the results. On a 280K-file tree that traversal alone was the
 * bulk of the scan cost. Here an excluded directory is never descended into.
 *
 * Also enforces the per-file size caps, which previously did not exist.
 */
export function discoverSrcFiles(
  workspacePath: string,
  isSupportedFile: (f: string) => boolean
): DiscoveryResult {
  const ignorePatterns = loadAllIgnorePatterns(workspacePath)
  const files: string[] = []
  let prunedDirs = 0
  let oversizeSkipped = 0

  const walk = (dir: string): void => {
    let entries: Dirent[]
    try {
      entries = readdirSync(dir, { withFileTypes: true })
    } catch {
      return
    }

    for (const entry of entries) {
      const fullPath = join(dir, entry.name)
      const relPath = toPosixRel(fullPath, workspacePath)

      if (entry.name.startsWith('.')) continue

      if (entry.isDirectory()) {
        if (REPOMAP_EXCLUDED_DIRS.has(entry.name) || isExcludedDirName(entry.name)) {
          prunedDirs++
          continue
        }
        if (
          ignorePatterns.length > 0 &&
          (matchesSkipPattern(relPath, ignorePatterns) ||
            matchesSkipPattern(`${relPath}/`, ignorePatterns))
        ) {
          prunedDirs++
          continue
        }
        walk(fullPath)
      } else if (entry.isFile()) {
        if (!isSupportedFile(fullPath)) continue
        if (ignorePatterns.length > 0 && matchesSkipPattern(relPath, ignorePatterns)) continue
        try {
          if (statSync(fullPath).size > sizeCapForFile(fullPath)) {
            oversizeSkipped++
            continue
          }
        } catch {
          continue
        }
        files.push(fullPath)
      }
    }
  }

  walk(workspacePath)
  return { files, prunedDirs, oversizeSkipped }
}

// ── Race-condition guard for tree-sitter initialization ──

let initParserPromise: Promise<void> | null = null

/**
 * Serialized initParser — prevents the race condition in repomap-mcp's
 * initializeBinding() where concurrent calls both see Module3 === null
 * and create duplicate Emscripten instances.
 */
async function safeInitParser(initParser: () => Promise<void>): Promise<void> {
  if (!initParserPromise) {
    initParserPromise = initParser()
  }
  return initParserPromise
}

/**
 * Core service for persisted code graph indexing and queries.
 *
 * Replaces the `repomap-mcp` RepoMap class orchestration with our own
 * DB-backed implementation. Still uses repomap-mcp for Tree-sitter parsing,
 * PageRank algorithm, file discovery, and tree context rendering.
 *
 * Key differences from the old approach:
 * - Indexes once, persists to SQLite → agent tool calls read from DB (instant)
 * - Incremental re-indexing via file mtime comparison
 * - Progress events streamed to renderer via IPC
 */
/** Edge in the code graph: a reference from one file to a definition in another. */
interface GraphEdge {
  from: string
  to: string
  name: string
}

/**
 * Build edge list from defines/references tag maps.
 * Pure function: takes tags, returns edge list.
 * An edge is created from each reference file to each definition file for the same symbol,
 * excluding self-references (ref and def in same file).
 */
export function buildEdgesFromTags(tags: RepomapTag[]): GraphEdge[] {
  const defines = new Map<string, Set<string>>()
  const references = new Map<string, Set<string>>()
  for (const tag of tags) {
    const map = tag.kind === 'def' ? defines : references
    let set = map.get(tag.name)
    if (!set) {
      set = new Set()
      map.set(tag.name, set)
    }
    set.add(tag.relFname)
  }

  const edges: GraphEdge[] = []
  for (const [name, refFiles] of references) {
    const defFiles = defines.get(name)
    if (!defFiles) continue
    for (const refFile of refFiles) {
      for (const defFile of defFiles) {
        if (refFile !== defFile) edges.push({ from: refFile, to: defFile, name })
      }
    }
  }
  return edges
}

/**
 * Apply focus/priority boosts to pre-computed PageRank scores.
 * Pure function: takes ranks + boost config, returns new boosted Map.
 *
 * Boost multipliers:
 * - Focus files: 20x
 * - Priority files: 5x
 * - Files containing priority identifiers: 3x (matched case-insensitively against tag names)
 */
export function applyRankBoosts(
  ranks: Map<string, number>,
  focusFiles: string[],
  priorityFiles: string[],
  priorityIdentifiers: string[],
  tags: RepomapTag[]
): Map<string, number> {
  const boostedRanks = new Map(ranks)

  for (const file of focusFiles) {
    const current = boostedRanks.get(file) ?? 0
    boostedRanks.set(file, current * 20)
  }
  for (const file of priorityFiles) {
    const current = boostedRanks.get(file) ?? 0
    boostedRanks.set(file, current * 5)
  }

  if (priorityIdentifiers.length > 0) {
    const identifierSet = new Set(priorityIdentifiers.map((id) => id.toLowerCase()))
    for (const tag of tags) {
      if (identifierSet.has(tag.name.toLowerCase())) {
        const current = boostedRanks.get(tag.relFname) ?? 0
        boostedRanks.set(tag.relFname, current * 3)
      }
    }
  }

  return boostedRanks
}

/**
 * Filter and sort files by boosted rank descending.
 * When excludeUnranked is true, files with rank === 0 are removed.
 */
export function sortAndFilterByRank(
  boostedRanks: Map<string, number>,
  excludeUnranked: boolean
): Array<[string, number]> {
  return [...boostedRanks.entries()]
    .filter(([, rank]) => !excludeUnranked || rank > 0)
    .sort((a, b) => b[1] - a[1])
}

// ADDITIONAL_EXCLUDED_DIRS and isExcludedPath imported from ./code-graph-exclusions
// (extracted to a dependency-free module for testability)

class CodeGraphService extends EventEmitter {
  private indexingStates = new Map<string, CodeGraphIndexingState>()

  /** Track whether we've logged a diagnostic for this session */
  private diagnosticLogged = false

  /**
   * Wrap getTags with diagnostic logging on first failure.
   * getTagsRaw in repomap-mcp has 4 silent return-[] paths:
   *   1. filenameToLang(fname) → null
   *   2. loadLanguage(lang) throws → caught, returns []
   *   3. loadQuery(language, lang) → null
   *   4. readFileSync(fname) throws → caught, returns []
   * Plus parser.setLanguage() is NOT in a try/catch — throws propagate.
   */
  private async getTagsWithDiagnostics(
    getTags: typeof import('repomap-mcp/dist/tags.js').getTags,
    fname: string,
    relFname: string,
    filenameToLang: (f: string) => string | null
  ): Promise<RepomapTag[]> {
    try {
      const tags = await getTags(fname, relFname, null, false)
      if (tags.length > 0 && this.diagnosticLogged) {
        log.info(`[CodeGraph] ✓ Parsing recovered — got ${tags.length} tags from ${relFname}`)
        this.diagnosticLogged = false
      }
      return tags
    } catch (error) {
      // getTags threw — this means parser.setLanguage() or query.captures() failed
      if (!this.diagnosticLogged) {
        const lang = filenameToLang(fname)
        log.error(
          `[CodeGraph] getTags threw for ${relFname} (lang=${lang}): ${(error as Error).message}`
        )
        log.error(
          `[CodeGraph] Stack: ${(error as Error).stack?.split('\n').slice(0, 3).join('\n')}`
        )
        this.diagnosticLogged = true
      }
      return []
    }
  }

  /**
   * Full workspace indexing — called when toggle is enabled or "Re-index" clicked.
   * Phases: discover files → parse tags → build edges → PageRank → persist
   */
  async indexWorkspace(workspaceId: string, workspacePath: string): Promise<void> {
    const { getTags, initParser } =
      (await import('repomap-mcp/dist/tags.js')) as typeof import('repomap-mcp/dist/tags.js')
    const { isSupportedFile, filenameToLang } =
      (await import('repomap-mcp/dist/languages.js')) as typeof import('repomap-mcp/dist/languages.js')

    const state: CodeGraphIndexingState = {
      workspaceId,
      status: 'scanning',
      totalFiles: 0,
      processedFiles: 0,
      totalTags: 0,
      totalEdges: 0,
      currentFile: ''
    }
    this.indexingStates.set(workspaceId, state)
    this.emitProgress(state)

    try {
      await safeInitParser(initParser)

      // Phase 1: Discover files with a PRUNING walker.
      // Excluded directories (bin, obj, packages, BuildSystem, Tools,
      // ThirdParty, ...) plus .gitignore/.atelierignore rules are applied at
      // the directory level, so vendored trees are never traversed at all.
      const discovery = discoverSrcFiles(workspacePath, isSupportedFile)
      const allFiles = discovery.files
      log.info(
        `[CodeGraph] Discovery: ${allFiles.length} files, ${discovery.prunedDirs} directories pruned, ` +
          `${discovery.oversizeSkipped} oversize files skipped`
      )

      // ── Health check: verify tree-sitter parsing works ──
      // getTagsRaw silently returns [] on failure. Test with a known file
      // to catch Electron-specific WASM issues before processing all files.
      try {
        const testFile = allFiles[0]
        if (testFile) {
          const testRelFname = toPosixRel(testFile, workspacePath)
          const testTags = await getTags(testFile, testRelFname, null, false)
          if (testTags.length === 0) {
            const lang = filenameToLang(testFile)
            log.warn(
              `[CodeGraph] ⚠ Health check: 0 tags from ${testRelFname} (lang=${lang}). ` +
                `Tree-sitter parsing may be broken in this runtime.`
            )

            // Try a step-by-step diagnostic
            try {
              const tagsModule = (await import('repomap-mcp/dist/tags.js')) as Record<
                string,
                unknown
              >
              if (typeof tagsModule.getTagsRaw === 'function') {
                const rawTags = await (
                  tagsModule.getTagsRaw as (f: string, r: string) => Promise<RepomapTag[]>
                )(testFile, testRelFname)
                log.warn(`[CodeGraph] ⚠ getTagsRaw returned ${rawTags.length} tags`)
              } else {
                log.warn('[CodeGraph] ⚠ getTagsRaw not exported — cannot run deeper diagnostic')
              }
            } catch (rawErr) {
              log.error(`[CodeGraph] ⚠ getTagsRaw threw: ${(rawErr as Error).message}`)
            }
          } else {
            log.info(
              `[CodeGraph] ✓ Health check passed: ${testTags.length} tags from ${testRelFname}`
            )
          }
        }
      } catch (healthErr) {
        log.error(`[CodeGraph] ⚠ Health check failed: ${(healthErr as Error).message}`)
      }
      state.totalFiles = allFiles.length
      state.status = 'parsing'
      this.emitProgress(state)

      // Phase 2: Parse tags (with incremental support via mtime comparison)
      const existingMtimes = codeGraphTagRepository.getFileMtimes(workspaceId)
      const allTags: RepomapTag[] = []
      const fileMtimes = new Map<string, number>()

      let markupDropped = 0
      for (const fname of allFiles) {
        const relFname = toPosixRel(fname, workspacePath)
        state.currentFile = relFname

        try {
          const stat = statSync(fname)
          const existingMtime = existingMtimes.get(relFname)
          fileMtimes.set(relFname, stat.mtimeMs)

          if (existingMtime && stat.mtimeMs === existingMtime) {
            // File unchanged — load cached tags from DB
            const cachedTags = codeGraphTagRepository.findByFile(workspaceId, relFname)
            allTags.push(...cachedTags)
          } else {
            // File changed or new — parse with Tree-sitter
            const tags = await this.getTagsWithDiagnostics(getTags, fname, relFname, filenameToLang)
            // Generated markup (NUnit HTML docs, doxygen output) parses to zero
            // tags but still costs a node + mtime row per file. Drop it: it can
            // never contribute an edge, only bloat.
            if (tags.length === 0 && isMarkupFile(fname)) {
              markupDropped++
              fileMtimes.delete(relFname)
            } else {
              allTags.push(...tags)
            }
          }
        } catch (error) {
          if (!this.diagnosticLogged) {
            log.warn(`[CodeGraph] Failed to parse ${relFname}: ${(error as Error).message}`)
            this.diagnosticLogged = true
          }
        }

        state.processedFiles++
        // Emit every 25 files to avoid flooding IPC
        if (state.processedFiles % 25 === 0) this.emitProgress(state)
      }

      state.totalTags = allTags.length
      this.emitProgress(state)

      // Phase 3-5: Build edge graph, PageRank, persist
      state.status = 'ranking'
      this.emitProgress(state)

      codeGraphTagRepository.upsertTags(workspaceId, allTags, fileMtimes)

      // Node set comes from the files we actually kept (POSIX-relative keys),
      // NOT from the raw discovery list — dropped markup must not become a
      // PageRank node it can never earn rank for.
      const allNodes = new Set(fileMtimes.keys())
      if (markupDropped > 0) {
        log.info(`[CodeGraph] Dropped ${markupDropped} zero-tag markup file(s)`)
      }
      const { totalEdges } = await this.buildAndPersistGraph(workspaceId, allTags, allNodes)
      state.totalEdges = totalEdges

      // ── Memory release ──
      // Capture counts before releasing for the log and diagnostics
      const fileCount = allFiles.length
      const tagCount = allTags.length
      memoryCheckpoint('PRE_CLEANUP', {
        tags: tagCount,
        edges: totalEdges,
        files: fileCount
      })
      // Truncate arrays to release backing storage immediately
      // (setting .length = 0 is faster than reassignment for GC)
      allTags.length = 0
      allFiles.length = 0
      fileMtimes.clear()

      state.status = 'complete'
      // A completed full rebuild clears any prior degradation.
      state.degraded = false
      state.degradedReason = undefined
      log.info(
        `[CodeGraph] Indexing complete: ${fileCount} files, ${tagCount} tags, ${totalEdges} edges`
      )
      this.emitProgress(state)
      this.postIndexCleanup(workspaceId)
    } catch (error) {
      state.status = 'error'
      state.error = (error as Error).message
      log.error('[CodeGraph] Indexing failed:', error)
      this.emitProgress(state)
      this.postIndexCleanup(workspaceId)
    }
  }

  /**
   * Build edge graph from all tags, compute PageRank, persist everything.
   * Shared by both indexWorkspace() and reindexFiles().
   */
  private async buildAndPersistGraph(
    workspaceId: string,
    allTags: RepomapTag[],
    allNodes?: Set<string>
  ): Promise<{ totalEdges: number }> {
    const { pagerank } =
      (await import('repomap-mcp/dist/pagerank.js')) as typeof import('repomap-mcp/dist/pagerank.js')

    // Build edges using extracted pure function
    const edges = buildEdgesFromTags(allTags)

    // PageRank — use provided nodes or derive from tags
    const nodes = allNodes ?? new Set(allTags.map((t) => t.relFname))
    const ranks = pagerank(nodes, edges)

    // Persist edges and ranks.
    // Use batched upsert to keep the UI responsive — inserts in chunks of 5K
    // with setImmediate() yields between batches. For large repos (5.5M edges),
    // a single synchronous transaction would freeze the main thread for seconds.
    const mappedEdges = edges.map((e) => ({
      workspaceId,
      sourceFile: e.from,
      sourceSymbol: e.name,
      targetFile: e.to,
      targetSymbol: e.name,
      edgeType: 'references' as const,
      pageRank: ranks.get(e.to) ?? 0
    }))
    await codeGraphEdgeRepository.upsertEdgesBatched(workspaceId, mappedEdges)
    codeGraphRankRepository.upsertRanks(workspaceId, ranks)

    // Capture count before releasing, then release large intermediate arrays.
    // At this point edges, mappedEdges, and ranks are fully persisted to SQLite.
    const totalEdges = edges.length
    mappedEdges.length = 0
    edges.length = 0
    ranks.clear()

    // Truncate the WAL after the largest write in the app. Without this the
    // journal stays saturated at journal_size_limit (256 MB), which is exactly
    // the 268 MB WAL observed during the freeze — checkpoint starvation under
    // continuous batched writes.
    try {
      const { getDatabase } = await import('../db')
      getDatabase().pragma('wal_checkpoint(TRUNCATE)')
    } catch (err) {
      log.warn(`[CodeGraph] WAL checkpoint after graph build failed: ${(err as Error).message}`)
    }

    return { totalEdges }
  }

  /**
   * Large-workspace threshold: when a workspace has more than this many tags,
   * skip the full graph rebuild on incremental file changes. The full rebuild
   * (DELETE + INSERT all edges) is O(tags²) and blocks the main thread for
   * seconds at 50K+ tags. Users can still trigger a full rebuild via "Re-index".
   */
  private static readonly LARGE_WORKSPACE_TAG_THRESHOLD = 50_000

  /**
   * Incremental re-index: re-parse only specified files, then rebuild
   * the full edge graph + PageRank from ALL persisted tags.
   * ~100ms for a few files vs ~3-8s for full workspace.
   *
   * For large workspaces (>50K tags), skips the full graph rebuild to avoid
   * multi-second main-thread freezes on every file save. The existing edge
   * graph remains valid enough for queries; a full rebuild is deferred to
   * the explicit "Re-index" button.
   */
  async reindexFiles(
    workspaceId: string,
    workspacePath: string,
    changedRelPaths: string[]
  ): Promise<void> {
    const { getTags, initParser } =
      (await import('repomap-mcp/dist/tags.js')) as typeof import('repomap-mcp/dist/tags.js')
    const { isSupportedFile, filenameToLang } =
      (await import('repomap-mcp/dist/languages.js')) as typeof import('repomap-mcp/dist/languages.js')
    await safeInitParser(initParser)

    // 1. Re-parse only changed files
    const newTags: RepomapTag[] = []
    const fileMtimes = new Map<string, number>()

    for (const relPath of changedRelPaths) {
      if (isExcludedPath(relPath)) continue
      const absPath = join(workspacePath, relPath)
      if (!isSupportedFile(absPath)) continue
      try {
        const stat = statSync(absPath)
        fileMtimes.set(relPath, stat.mtimeMs)
        const tags = await this.getTagsWithDiagnostics(getTags, absPath, relPath, filenameToLang)
        newTags.push(...tags)
      } catch (error) {
        const msg = (error as Error).message
        if (msg.includes('ENOENT') || msg.includes('no such file')) {
          // File deleted — remove its tags
          codeGraphTagRepository.deleteByFile(workspaceId, relPath)
        } else {
          log.warn(`[CodeGraph] reindexFiles: parse failed for ${relPath}: ${msg}`)
        }
      }
    }

    // 2. Upsert changed file tags
    if (newTags.length > 0) {
      codeGraphTagRepository.upsertTags(workspaceId, newTags, fileMtimes)
    }

    // 3. Check workspace size before full graph rebuild
    const totalTags = codeGraphTagRepository.countByWorkspace(workspaceId)
    if (totalTags > CodeGraphService.LARGE_WORKSPACE_TAG_THRESHOLD) {
      // Large workspace: skip full graph rebuild on incremental changes.
      // The DELETE + INSERT of millions of edges would freeze the main thread.
      // Tags are up-to-date; edge graph uses the prior full index.
      // User can trigger a full rebuild via the "Re-index" button.
      log.warn(
        `[CodeGraph] Large workspace (${totalTags} tags) — skipping full graph rebuild. ` +
          `Use Re-index for a complete refresh.`
      )
      // Surface the degradation instead of failing silently. A frozen graph
      // that still reports "healthy" is what made the last incident so hard
      // to diagnose.
      const degradedState: CodeGraphIndexingState = {
        ...(this.indexingStates.get(workspaceId) ?? {
          workspaceId,
          status: 'complete',
          totalFiles: 0,
          processedFiles: 0,
          totalTags,
          totalEdges: 0,
          currentFile: ''
        }),
        status: 'complete',
        totalTags,
        degraded: true,
        degradedReason:
          `Workspace has ${totalTags.toLocaleString()} tags (limit ` +
          `${CodeGraphService.LARGE_WORKSPACE_TAG_THRESHOLD.toLocaleString()}). ` +
          `The dependency graph is frozen at its last full build. ` +
          `Add vendored/generated directories to .atelierignore, then Re-index.`
      }
      this.indexingStates.set(workspaceId, degradedState)
      this.emitProgress(degradedState)
      return
    }

    // Small/medium workspace: full rebuild is fast enough
    const allTags = codeGraphTagRepository.findAllByWorkspace(workspaceId)
    await this.buildAndPersistGraph(workspaceId, allTags)
    allTags.length = 0  // release after persist

    log.info(`[CodeGraph] Incremental: ${changedRelPaths.length} files, ${newTags.length} new tags`)

    // Clean up after incremental reindex too
    this.postIndexCleanup(workspaceId)
  }

  /**
   * Generate a repo map from persisted data — NO filesystem walk, NO PageRank recomputation.
   * This is what the MCP tool calls instead of RepoMap.getRepoMap().
   */
  async getRepoMap(
    workspaceId: string,
    workspacePath: string,
    options: {
      focusFiles?: string[]
      priorityFiles?: string[]
      priorityIdentifiers?: string[]
      mapTokens?: number
      excludeUnranked?: boolean
    }
  ): Promise<{ map: string; report: object }> {
    const { renderTreeContext } =
      (await import('repomap-mcp/dist/tree-context.js')) as typeof import('repomap-mcp/dist/tree-context.js')
    const { countTokens } =
      (await import('repomap-mcp/dist/token-counter.js')) as typeof import('repomap-mcp/dist/token-counter.js')

    const mapTokens = options.mapTokens ?? 8192
    const focusFiles = options.focusFiles ?? []
    const priorityFiles = options.priorityFiles ?? []
    const priorityIdentifiers = options.priorityIdentifiers ?? []

    // Load pre-computed ranks from DB
    const ranks = codeGraphRankRepository.findByWorkspace(workspaceId)
    const tags = codeGraphTagRepository.findDefsByWorkspace(workspaceId)

    // Apply focus/priority boosts using extracted pure function
    const boostedRanks = applyRankBoosts(
      ranks,
      focusFiles,
      priorityFiles,
      priorityIdentifiers,
      tags
    )

    // Sort and filter using extracted pure function
    const rankedFiles = sortAndFilterByRank(boostedRanks, options.excludeUnranked ?? false)

    // Group definition tags by file
    const tagsByFile = new Map<string, RepomapTag[]>()
    for (const tag of tags) {
      let arr = tagsByFile.get(tag.relFname)
      if (!arr) {
        arr = []
        tagsByFile.set(tag.relFname, arr)
      }
      arr.push(tag)
    }

    // Render tree context for top-ranked files, fitting within token budget
    const lines: string[] = []
    let totalTokens = 0
    let filesIncluded = 0

    for (const [relFname] of rankedFiles) {
      const fileTags = tagsByFile.get(relFname)
      if (!fileTags || fileTags.length === 0) continue

      const absPath = `${workspacePath}/${relFname}`
      let code: string
      try {
        code = readFileSync(absPath, 'utf-8')
      } catch {
        continue // File may have been deleted since indexing
      }

      // Guard stale line refs — tags may reference lines beyond current file length
      const totalLines = code.split('\n').length
      const linesOfInterest = fileTags
        .map((t) => t.line)
        .filter((line) => line >= 1 && line <= totalLines)

      if (linesOfInterest.length === 0) continue // All tags were stale — skip file

      let rendered: string
      try {
        rendered = renderTreeContext(code, linesOfInterest)
      } catch (err) {
        log.warn(`[CodeGraph] renderTreeContext failed for ${relFname}:`, err)
        continue // Skip this file, don't crash the whole map
      }
      const entry = `${relFname}:\n${rendered}\n`
      const entryTokens = countTokens(entry)

      if (totalTokens + entryTokens > mapTokens && filesIncluded > 0) break

      lines.push(entry)
      totalTokens += entryTokens
      filesIncluded++
    }

    return {
      map: lines.join('\n'),
      report: {
        totalFilesConsidered: rankedFiles.length,
        filesIncluded,
        totalTokens,
        definitionTags: tags.length
      }
    }
  }

  /**
   * Search identifiers from DB — NO filesystem walk. Instant.
   */
  async searchIdentifiers(
    workspaceId: string,
    workspacePath: string,
    query: string,
    options?: {
      maxResults?: number
      includeDefinitions?: boolean
      includeReferences?: boolean
    }
  ): Promise<
    Array<{
      file: string
      line: number
      name: string
      kind: 'def' | 'ref'
      context: string
    }>
  > {
    const { renderTreeContext } =
      (await import('repomap-mcp/dist/tree-context.js')) as typeof import('repomap-mcp/dist/tree-context.js')

    const matchingTags = codeGraphTagRepository.searchByName(workspaceId, query, {
      maxResults: options?.maxResults ?? 50,
      includeDefinitions: options?.includeDefinitions ?? true,
      includeReferences: options?.includeReferences ?? true
    })

    const results: Array<{
      file: string
      line: number
      name: string
      kind: 'def' | 'ref'
      context: string
    }> = []

    for (const tag of matchingTags) {
      const absPath = `${workspacePath}/${tag.relFname}`
      let context = ''
      try {
        const code = readFileSync(absPath, 'utf-8')
        context = renderTreeContext(code, [tag.line])
      } catch {
        // File may have been deleted — still return the match without context
      }

      results.push({
        file: tag.relFname,
        line: tag.line,
        name: tag.name,
        kind: tag.kind,
        context
      })
    }

    return results
  }

  /**
   * Find potentially dead code — definitions with no cross-file references.
   * Wraps repository query with workspace validation and formatting.
   */
  async findDeadCode(
    workspaceId: string,
    workspacePath: string,
    options?: { path?: string; maxResults?: number }
  ): Promise<Array<{ file: string; line: number; name: string; context: string }>> {
    const { renderTreeContext } =
      (await import('repomap-mcp/dist/tree-context.js')) as typeof import('repomap-mcp/dist/tree-context.js')

    const deadDefs = codeGraphTagRepository.findDeadCode(workspaceId, options)

    const results: Array<{ file: string; line: number; name: string; context: string }> = []

    for (const tag of deadDefs) {
      const absPath = `${workspacePath}/${tag.relFname}`
      let context = ''
      try {
        const code = readFileSync(absPath, 'utf-8')
        context = renderTreeContext(code, [tag.line])
      } catch {
        // File may have been deleted
      }

      results.push({
        file: tag.relFname,
        line: tag.line,
        name: tag.name,
        context
      })
    }

    return results
  }

  /**
   * Get top-ranked files for decompose() — replaces prefetchRankedFiles().
   * Optionally boosts focus files by placing them first.
   */
  async getTopRankedFiles(
    workspaceId: string,
    focusFiles: string[],
    limit: number
  ): Promise<string[]> {
    const topFiles = codeGraphRankRepository.getTopRanked(workspaceId, limit + focusFiles.length)

    // Merge: focus files first, then top-ranked (deduplicated)
    const seen = new Set<string>()
    const result: string[] = []

    for (const file of focusFiles) {
      if (!seen.has(file)) {
        result.push(file)
        seen.add(file)
      }
    }

    for (const file of topFiles) {
      if (result.length >= limit) break
      if (!seen.has(file)) {
        result.push(file)
        seen.add(file)
      }
    }

    return result
  }

  /**
   * Check whether a persisted index exists for a workspace.
   */
  hasPersistedIndex(workspaceId: string): boolean {
    return codeGraphTagRepository.countByWorkspace(workspaceId) > 0
  }

  /**
   * Get current indexing state for a workspace.
   *
   * After an app restart the in-memory map is empty, but the DB may still
   * hold a fully-indexed graph from a previous session. When that's the case
   * we return a synthetic 'complete' state with real counts so the UI can
   * display stats immediately without requiring a re-index.
   */
  getIndexingState(workspaceId: string): CodeGraphIndexingState {
    const inMemory = this.indexingStates.get(workspaceId)
    if (inMemory) return inMemory

    // No in-memory state (e.g. after app restart) — check persisted DB
    const tagCount = codeGraphTagRepository.countByWorkspace(workspaceId)
    if (tagCount > 0) {
      const edgeCount = codeGraphEdgeRepository.countByWorkspace(workspaceId)
      // Use rank count for totalFiles — PageRank is computed over ALL discovered
      // source files (not just files with tags), so this matches what indexWorkspace
      // reports during indexing. fileMtimes.size would only count files with tags.
      const fileCount = codeGraphRankRepository.countByWorkspace(workspaceId)
      return {
        workspaceId,
        status: 'complete',
        totalFiles: fileCount,
        processedFiles: fileCount,
        totalTags: tagCount,
        totalEdges: edgeCount,
        currentFile: ''
      }
    }

    return {
      workspaceId,
      status: 'idle',
      totalFiles: 0,
      processedFiles: 0,
      totalTags: 0,
      totalEdges: 0,
      currentFile: ''
    }
  }

  /**
   * Detect circular file-level dependencies via DFS cycle detection.
   * Returns an array of cycles, each being an array of file paths forming the cycle.
   */
  findCircularDependencies(
    workspaceId: string,
    opts?: { path?: string; maxCycles?: number }
  ): string[][] {
    const edges = codeGraphEdgeRepository.findByWorkspace(workspaceId)
    const maxCycles = opts?.maxCycles ?? 20

    // Build adjacency list at file level
    const adj = new Map<string, Set<string>>()
    for (const edge of edges) {
      if (edge.sourceFile === edge.targetFile) continue
      if (opts?.path) {
        if (!edge.sourceFile.startsWith(opts.path) && !edge.targetFile.startsWith(opts.path))
          continue
      }
      const targets = adj.get(edge.sourceFile) ?? new Set()
      targets.add(edge.targetFile)
      adj.set(edge.sourceFile, targets)
    }

    // DFS-based cycle detection
    const visited = new Set<string>()
    const inStack = new Set<string>()
    const cycles: string[][] = []

    const dfs = (node: string, path: string[]): void => {
      if (cycles.length >= maxCycles) return
      visited.add(node)
      inStack.add(node)
      path.push(node)

      for (const neighbor of adj.get(node) ?? []) {
        if (cycles.length >= maxCycles) return
        if (inStack.has(neighbor)) {
          // Found a cycle — extract it from the path
          const cycleStart = path.indexOf(neighbor)
          if (cycleStart !== -1) {
            const cycle = path.slice(cycleStart)
            cycle.push(neighbor) // close the cycle
            // Normalize: start from lexicographically smallest path
            const minIdx = cycle
              .slice(0, -1)
              .reduce((mi, _v, i, arr) => (arr[i] < arr[mi] ? i : mi), 0)
            const normalized = [
              ...cycle.slice(minIdx, -1),
              ...cycle.slice(0, minIdx),
              cycle[minIdx]
            ]
            // Deduplicate by key
            const key = normalized.join(' → ')
            if (!cycles.some((c) => c.join(' → ') === key)) {
              cycles.push(normalized)
            }
          }
        } else if (!visited.has(neighbor)) {
          dfs(neighbor, path)
        }
      }

      path.pop()
      inStack.delete(node)
    }

    for (const node of adj.keys()) {
      if (!visited.has(node) && cycles.length < maxCycles) {
        dfs(node, [])
      }
    }

    return cycles
  }

  // ── Co-Change Mining ──────────────────────────────────────────────────────

  /**
   * Mine git history to find files that are frequently committed together.
   * Reveals logical coupling invisible to the import graph.
   */
  findCoChangePairs(
    workspacePath: string,
    options: {
      maxCommits?: number
      minCoChanges?: number
      path?: string
      filePath?: string
      maxResults?: number
    } = {}
  ): { fileA: string; fileB: string; coChangeCount: number; commitsAnalyzed: number }[] {
    const maxCommits = Math.min(options.maxCommits ?? 200, 500)
    const minCoChanges = options.minCoChanges ?? 3
    const maxResults = options.maxResults ?? 30

    let gitOutput: string
    try {
      gitOutput = execSync(`git log --name-only --format=%H -n ${maxCommits}`, {
        cwd: workspacePath,
        encoding: 'utf-8',
        timeout: 15_000,
        maxBuffer: 5 * 1024 * 1024
      }).trim()
    } catch {
      return []
    }

    // Parse commits: split on blank lines, each block = hash + file list
    const commitBlocks = gitOutput.split(/\n\n+/)
    const pairCounts = new Map<string, number>()
    let commitCount = 0

    for (const block of commitBlocks) {
      const lines = block.split('\n').filter(Boolean)
      if (lines.length < 2) continue
      commitCount++

      let files = lines.slice(1)

      if (options.path) {
        files = files.filter((f) => f.startsWith(options.path!))
      }

      // Skip commits with too many files (merges) or too few
      if (files.length < 2 || files.length > 30) continue

      for (let i = 0; i < files.length; i++) {
        for (let j = i + 1; j < files.length; j++) {
          const key = files[i] < files[j] ? `${files[i]}\0${files[j]}` : `${files[j]}\0${files[i]}`
          pairCounts.set(key, (pairCounts.get(key) ?? 0) + 1)
        }
      }
    }

    let pairs = Array.from(pairCounts.entries())
      .filter(([, count]) => count >= minCoChanges)
      .map(([key, count]) => {
        const [fileA, fileB] = key.split('\0')
        return { fileA, fileB, coChangeCount: count, commitsAnalyzed: commitCount }
      })

    if (options.filePath) {
      pairs = pairs.filter(
        (p) => p.fileA === options.filePath || p.fileB === options.filePath
      )
    }

    return pairs
      .sort((a, b) => b.coChangeCount - a.coChangeCount)
      .slice(0, maxResults)
  }

  // ── Hotspot Scoring ────────────────────────────────────────────────────────

  /**
   * Composite risk ranking: coupling (reference count) × git churn.
   * Surfaces the most dangerous files to touch during refactoring.
   */
  findHotspots(
    workspaceId: string,
    workspacePath: string,
    options: { maxResults?: number; path?: string } = {}
  ): {
    file: string
    referenceCount: number
    gitChurn: number
    hotspotScore: number
  }[] {
    const maxResults = options.maxResults ?? 20

    // 1. Get per-file reference counts from symbol hotspots
    const symbolHotspots = codeGraphTagRepository.findSymbolHotspots(workspaceId, {
      maxResults: 500,
      path: options.path
    })

    const fileRefCounts = new Map<string, number>()
    for (const h of symbolHotspots) {
      const file = (h as { file?: string }).file ?? ''
      if (!file) continue
      fileRefCounts.set(file, (fileRefCounts.get(file) ?? 0) + ((h as { refCount?: number }).refCount ?? 1))
    }

    // 2. Get git churn per file
    const churnMap = new Map<string, number>()
    try {
      const churnOutput = execSync(
        `git log --format= --name-only -n 500 | sort | uniq -c | sort -rn | head -200`,
        { cwd: workspacePath, encoding: 'utf-8', timeout: 15_000, maxBuffer: 2 * 1024 * 1024 }
      ).trim()

      for (const line of churnOutput.split('\n')) {
        const match = line.trim().match(/^(\d+)\s+(.+)$/)
        if (match) {
          churnMap.set(match[2], parseInt(match[1], 10))
        }
      }
    } catch {
      // Git not available — churn stays at 0
    }

    // 3. Compute hotspot score
    const allFiles = new Set([...fileRefCounts.keys(), ...churnMap.keys()])
    const hotspots: {
      file: string
      referenceCount: number
      gitChurn: number
      hotspotScore: number
    }[] = []

    for (const file of allFiles) {
      if (options.path && !file.startsWith(options.path)) continue
      const refCount = fileRefCounts.get(file) ?? 0
      const churn = churnMap.get(file) ?? 0
      const score = refCount * (1 + Math.log2(churn + 1))
      if (score > 0) {
        hotspots.push({
          file,
          referenceCount: refCount,
          gitChurn: churn,
          hotspotScore: Math.round(score * 100) / 100
        })
      }
    }

    return hotspots
      .sort((a, b) => b.hotspotScore - a.hotspotScore)
      .slice(0, maxResults)
  }

  // ── Code Clone Detection ──────────────────────────────────────────────────

  /**
   * Detect structurally duplicated code via normalized source hashing.
   * Uses the code_chunks table (requires semantic search indexing).
   * Normalizes identifiers, literals, and comments, then groups by SHA-256.
   */
  findCodeClones(
    workspaceId: string,
    _workspacePath: string,
    options: { minBodyLines?: number; path?: string; maxResults?: number } = {}
  ): { hash: string; clones: { file: string; symbol: string; line: number; lines: number }[] }[] {
    const minBodyLines = options.minBodyLines ?? 5
    const maxResults = options.maxResults ?? 20

    // Use code_chunks table which has body text + line ranges
    let chunks: { filePath: string; symbolName: string; startLine: number; endLine: number; body: string }[]
    try {
      // eslint-disable-next-line @typescript-eslint/no-require-imports
      const { codeChunkRepository } = require('../db/repositories') as {
        codeChunkRepository: { db: () => import('better-sqlite3').Database }
      }
      const db = codeChunkRepository.db()
      const rows = db
        .prepare(
          `SELECT file_path, symbol_name, start_line, end_line, body
           FROM code_chunks
           WHERE workspace_id = ? AND (end_line - start_line) >= ?`
        )
        .all(workspaceId, minBodyLines) as {
          file_path: string; symbol_name: string; start_line: number; end_line: number; body: string
        }[]
      chunks = rows.map((r) => ({
        filePath: r.file_path,
        symbolName: r.symbol_name,
        startLine: r.start_line,
        endLine: r.end_line,
        body: r.body
      }))
    } catch {
      return [] // code_chunks table not available or empty
    }

    if (options.path) {
      chunks = chunks.filter((c) => c.filePath.startsWith(options.path!))
    }

    const hashGroups = new Map<string, { file: string; symbol: string; line: number; lines: number }[]>()

    for (const chunk of chunks) {
      const lineCount = chunk.endLine - chunk.startLine + 1
      if (lineCount < minBodyLines) continue

      const normalized = this.normalizeForCloneDetection(chunk.body)
      if (normalized.length < 20) continue

      const hash = createHash('sha256').update(normalized).digest('hex').slice(0, 16)

      const entry = hashGroups.get(hash) ?? []
      entry.push({
        file: chunk.filePath,
        symbol: chunk.symbolName,
        line: chunk.startLine,
        lines: lineCount
      })
      hashGroups.set(hash, entry)
    }

    return Array.from(hashGroups.entries())
      .filter(([, group]) => group.length >= 2)
      .map(([hash, clones]) => ({ hash, clones }))
      .sort((a, b) => b.clones.length - a.clones.length)
      .slice(0, maxResults)
  }

  /**
   * Normalize source code for structural clone detection.
   * Strips comments, replaces literals and identifiers, collapses whitespace.
   */
  private normalizeForCloneDetection(source: string): string {
    return source
      .replace(/\/\*[\s\S]*?\*\//g, '')
      .replace(/\/\/.*$/gm, '')
      .replace(/`[^`]*`/g, 'STR')
      .replace(/"(?:[^"\\]|\\.)*"/g, 'STR')
      .replace(/'(?:[^'\\]|\\.)*'/g, 'STR')
      .replace(/\b0x[0-9a-fA-F]+\b/g, 'NUM')
      .replace(/\b\d+\.\d+\b/g, 'NUM')
      .replace(/\b\d+\b/g, 'NUM')
      .replace(/\b[a-zA-Z_$][a-zA-Z0-9_$]*\b/g, 'IDENT')
      .replace(/\s+/g, ' ')
      .trim()
  }

  /**
   * Release memory after indexing. V8 on Windows doesn't aggressively GC
   * large allocations when system RAM is plentiful — we need to nudge it.
   */
  private postIndexCleanup(workspaceId: string): void {
    // 1. Clear the completed indexing state after a delay
    //    (keep it briefly so the UI can read the final status)
    setTimeout(() => {
      const state = this.indexingStates.get(workspaceId)
      if (state?.status === 'complete' || state?.status === 'error') {
        this.indexingStates.delete(workspaceId)
      }
    }, 30_000)

    // 2. Release the tree-sitter WASM parser — it allocated memory outside
    //    V8's heap that the GC cannot see. Will be re-initialized on next index.
    initParserPromise = null

    // 3. Shrink SQLite page cache after the heavy write burst
    try {
      const { getDatabase } = require('../db')
      getDatabase().pragma('shrink_memory')
    } catch { /* best-effort */ }

    // 4. Nudge V8 GC (available when Electron runs with --expose-gc,
    //    already used by vector-search.service.ts)
    if (typeof global.gc === 'function') {
      global.gc()
    }

    memoryCheckpoint('POST_INDEX_CLEANUP')
  }

  private emitProgress(state: CodeGraphIndexingState): void {
    this.emit('progress', state)
  }
}

export const codeGraphService = new CodeGraphService()

/**
 * Workspace-scoped index exclusions loaded from `.atelierignore`.
 *
 * Why a file and not a setting: exclusions are a property of the REPOSITORY,
 * not of one developer's machine. A committed .atelierignore means the team
 * fixes index bloat once and every clone inherits it — which is precisely the
 * failure mode we hit when one Windows checkout indexed a vendored NUnit tree
 * to 279,882 tags while other machines were fine.
 *
 * Syntax: gitignore-style, evaluated with the shared matchesSkipPattern glob
 * matcher (NOT the `ignore` npm package — that package requires POSIX
 * separators and silently no-ops on Windows backslash paths, which is one of
 * the root causes this module exists to work around).
 *
 * Rules are ADDITIVE to the hardcoded defaults in code-graph-exclusions.ts.
 */

import { existsSync, readFileSync, statSync } from 'node:fs'
import path from 'node:path'
import log from 'electron-log/main'
import { matchesSkipPattern } from './code-graph-exclusions'

export const ATELIERIGNORE_FILENAME = '.atelierignore'

/** Template written into the docs / shown in the UI for new workspaces. */
export const ATELIERIGNORE_TEMPLATE = `# Code Atelier index exclusions.
# Gitignore-style syntax. Additive to Code Atelier's built-in defaults
# (node_modules, bin, obj, packages, BuildSystem, Tools, ThirdParty, ...).
#
# Exclude vendored dependency trees — duplicate copies of a library multiply
# every symbol's edge count and are the #1 cause of index bloat.
# BuildSystem/Tools/
# packages/

# Exclude generated documentation — thousands of files, ~0 indexable symbols.
# **/*.generated.html
# docs/api/
`

interface CachedRules {
  patterns: string[]
  mtimeMs: number
}

const cache = new Map<string, CachedRules>()

/**
 * Parse gitignore-style text into glob patterns understood by
 * matchesSkipPattern. Comments and blank lines are dropped.
 *
 * Normalization rules:
 *   `foo/`       → `**\/foo/**`   (directory anywhere)
 *   `/foo`       → `foo`, `foo/**` (anchored at workspace root)
 *   `*.html`     → `**\/*.html`   (bare pattern matches at any depth)
 *   `a/b.ts`     → `a/b.ts`       (already path-shaped, left alone)
 *
 * Negation (`!`) is intentionally unsupported: exclusions here only ever
 * shrink the index, so a rule that re-includes files would be a footgun that
 * silently reintroduces bloat.
 */
export function parseIgnoreRules(content: string): string[] {
  const patterns: string[] = []

  for (const rawLine of content.split(/\r?\n/)) {
    const line = rawLine.trim()
    if (!line || line.startsWith('#')) continue
    if (line.startsWith('!')) {
      log.warn(`[WorkspaceIgnore] Negation is not supported, ignoring rule: ${line}`)
      continue
    }

    const isDirRule = line.endsWith('/')
    const isAnchored = line.startsWith('/')
    const body = line.replace(/^\//, '').replace(/\/$/, '')
    if (!body) continue

    if (isDirRule) {
      patterns.push(isAnchored ? `${body}/**` : `**/${body}/**`)
      continue
    }

    if (isAnchored) {
      patterns.push(body, `${body}/**`)
      continue
    }

    // Unanchored: match at any depth, and treat it as a directory too so
    // `packages` behaves like `packages/` the way gitignore does.
    patterns.push(body.includes('/') ? body : `**/${body}`)
    patterns.push(`**/${body}/**`)
  }

  return patterns
}

/**
 * Load (and cache) the .atelierignore rules for a workspace.
 * Cache is keyed by workspace path and validated against the file mtime, so
 * an edit is picked up without an app restart even if the watcher misses it.
 */
export function loadIgnoreRules(workspacePath: string): string[] {
  const filePath = path.join(workspacePath, ATELIERIGNORE_FILENAME)

  try {
    if (!existsSync(filePath)) {
      cache.delete(workspacePath)
      return []
    }

    const mtimeMs = statSync(filePath).mtimeMs
    const cached = cache.get(workspacePath)
    if (cached && cached.mtimeMs === mtimeMs) return cached.patterns

    const patterns = parseIgnoreRules(readFileSync(filePath, 'utf-8'))
    cache.set(workspacePath, { patterns, mtimeMs })
    log.info(
      `[WorkspaceIgnore] Loaded ${patterns.length} pattern(s) from ${ATELIERIGNORE_FILENAME}`
    )
    return patterns
  } catch (error) {
    // A malformed or unreadable ignore file must never block indexing.
    log.warn(`[WorkspaceIgnore] Failed to read ${filePath}: ${(error as Error).message}`)
    return []
  }
}

/**
 * Merged exclusion rules: `.gitignore` + `.atelierignore`.
 *
 * We parse .gitignore ourselves rather than relying on repomap-mcp's walker,
 * which feeds native (backslash) Windows paths into the `ignore` package —
 * that package requires POSIX separators, so .gitignore was silently inert on
 * Windows and every ignored directory got walked and indexed.
 */
export function loadAllIgnorePatterns(workspacePath: string): string[] {
  const patterns = [...loadIgnoreRules(workspacePath)]

  const gitignorePath = path.join(workspacePath, '.gitignore')
  try {
    if (existsSync(gitignorePath)) {
      const mtimeMs = statSync(gitignorePath).mtimeMs
      const key = `${workspacePath}::gitignore`
      const cached = cache.get(key)
      if (cached && cached.mtimeMs === mtimeMs) {
        patterns.push(...cached.patterns)
      } else {
        const parsed = parseIgnoreRules(readFileSync(gitignorePath, 'utf-8'))
        cache.set(key, { patterns: parsed, mtimeMs })
        patterns.push(...parsed)
      }
    }
  } catch (error) {
    log.warn(`[WorkspaceIgnore] Failed to read .gitignore: ${(error as Error).message}`)
  }

  return patterns
}

/**
 * True when a workspace-relative POSIX path is excluded by .atelierignore.
 * Callers should ALSO apply isExcludedPath() for the built-in defaults.
 */
export function isIgnoredByWorkspace(workspacePath: string, relPath: string): boolean {
  const patterns = loadIgnoreRules(workspacePath)
  if (patterns.length === 0) return false
  return matchesSkipPattern(relPath, patterns)
}

/** True when a single directory name/relative dir is pruned by workspace rules. */
export function isDirIgnoredByWorkspace(workspacePath: string, relDirPath: string): boolean {
  const patterns = loadIgnoreRules(workspacePath)
  if (patterns.length === 0) return false
  // Match the directory itself and a representative child, so `**/foo/**`
  // style rules prune the tree rather than only matching files inside it.
  return matchesSkipPattern(relDirPath, patterns) || matchesSkipPattern(`${relDirPath}/.`, patterns)
}

/** Drop cached rules for a workspace (called by the file watcher). */
export function invalidateIgnoreCache(workspacePath?: string): void {
  if (workspacePath) cache.delete(workspacePath)
  else cache.clear()
}

/**
 * Unit tests for isExcludedPath() — Windows path separator handling and
 * directory-segment matching to prevent false positives.
 * Zero DB dependencies — pure function tests.
 */
import assert from 'node:assert/strict'
import { join, sep } from 'node:path'
import { test, describe } from './test-harness'
import { isExcludedPath, isExcludedDirName, toPosixRel, matchesSkipPattern } from '../code-graph-exclusions'
import { parseIgnoreRules } from '../workspace-ignore'

describe('isExcludedPath', () => {
  // ── Forward slash paths (Unix/macOS) ──

  test('excludes path with "bin" directory segment (forward slash)', () => {
    assert.equal(isExcludedPath('src/bin/output.dll'), true)
  })

  test('excludes path with "obj" directory segment', () => {
    assert.equal(isExcludedPath('MyProject/obj/Debug/app.dll'), true)
  })

  test('excludes path with ".vs" directory segment', () => {
    assert.equal(isExcludedPath('.vs/config/applicationhost.config'), true)
  })

  test('excludes path with "Debug" directory segment', () => {
    assert.equal(isExcludedPath('build/Debug/main.o'), true)
  })

  test('excludes path with "Release" directory segment', () => {
    assert.equal(isExcludedPath('build/Release/main.o'), true)
  })

  test('excludes path with ".idea" directory segment', () => {
    assert.equal(isExcludedPath('.idea/workspace.xml'), true)
  })

  test('excludes path with "out" directory segment', () => {
    assert.equal(isExcludedPath('out/compiled.js'), true)
  })

  // ── Backslash paths (Windows) ──

  test('excludes path with backslash separators (Windows)', () => {
    assert.equal(isExcludedPath('src\\bin\\output.dll'), true)
  })

  test('excludes path with backslash "obj" directory (Windows)', () => {
    assert.equal(isExcludedPath('MyProject\\obj\\Debug\\app.dll'), true)
  })

  test('excludes path with backslash ".idea" directory (Windows)', () => {
    assert.equal(isExcludedPath('.idea\\workspace.xml'), true)
  })

  // ── Mixed separators ──

  test('handles mixed forward and backslash separators', () => {
    assert.equal(isExcludedPath('src/bin\\output.dll'), true)
  })

  // ── False-positive prevention ──

  test('does NOT exclude filename containing excluded dir name', () => {
    // "binary-utils.ts" contains "bin" but is a filename, not a directory segment
    assert.equal(isExcludedPath('src/binary-utils.ts'), false)
  })

  test('does NOT exclude file named "bin.ts" (it is the last segment = filename)', () => {
    // "bin.ts" as last segment is treated as a filename, not a directory
    assert.equal(isExcludedPath('src/bin.ts'), false)
  })

  test('does NOT exclude file named "debug-helper.ts"', () => {
    assert.equal(isExcludedPath('src/debug-helper.ts'), false)
  })

  test('does NOT exclude regular source paths', () => {
    assert.equal(isExcludedPath('src/services/my-service.ts'), false)
  })

  test('does NOT exclude file with "out" in filename', () => {
    assert.equal(isExcludedPath('src/layout.tsx'), false)
  })

  // ── Edge cases ──

  test('handles path with no directory segments (bare filename)', () => {
    assert.equal(isExcludedPath('index.ts'), false)
  })

  test('handles empty string', () => {
    assert.equal(isExcludedPath(''), false)
  })

  test('excludes when excluded dir is the first segment', () => {
    assert.equal(isExcludedPath('packages/lib/index.ts'), true)
  })

  test('excludes deeply nested excluded directory', () => {
    assert.equal(isExcludedPath('a/b/c/artifacts/d/e.ts'), true)
  })
})

// ─────────────────────────────────────────────────────────────────────────────
// Case-insensitive exclusion — Windows NTFS / macOS HFS+ compatibility.
// A directory named "Packages" (capital P) must match the "packages" exclusion.
// ─────────────────────────────────────────────────────────────────────────────
describe('isExcludedPath — case-insensitive matching', () => {
  test('excludes PascalCase variants (Windows/NuGet)', () => {
    assert.equal(isExcludedPath('Packages/Angularjs.1.8.2/angular.js'), true)
    assert.equal(isExcludedPath('Bin/Debug/app.exe'), true)
    assert.equal(isExcludedPath('OBJ/Release/net8.0/app.dll'), true)
  })

  test('excludes UPPER CASE directory names', () => {
    assert.equal(isExcludedPath('BIN/output.dll'), true)
    assert.equal(isExcludedPath('PACKAGES/lib/index.js'), true)
    assert.equal(isExcludedPath('ARTIFACTS/build/app.js'), true)
  })

  test('excludes mixed-case with backslash (Windows paths)', () => {
    assert.equal(isExcludedPath('MyProject\\Bin\\Debug\\app.dll'), true)
    assert.equal(isExcludedPath('src\\OBJ\\Release\\output.dll'), true)
  })
})

describe('isExcludedDirName — case-insensitive', () => {
  test('matches lowercase', () => {
    assert.equal(isExcludedDirName('packages'), true)
    assert.equal(isExcludedDirName('bin'), true)
    assert.equal(isExcludedDirName('obj'), true)
  })

  test('matches PascalCase', () => {
    assert.equal(isExcludedDirName('Packages'), true)
    assert.equal(isExcludedDirName('Bin'), true)
    assert.equal(isExcludedDirName('TestResults'), true)
    assert.equal(isExcludedDirName('BuildSystem'), true)
  })

  test('matches UPPER CASE', () => {
    assert.equal(isExcludedDirName('PACKAGES'), true)
    assert.equal(isExcludedDirName('BIN'), true)
    assert.equal(isExcludedDirName('OBJ'), true)
  })

  test('does NOT match non-excluded dirs regardless of case', () => {
    assert.equal(isExcludedDirName('src'), false)
    assert.equal(isExcludedDirName('SRC'), false)
    assert.equal(isExcludedDirName('lib'), false)
  })
})

// ─────────────────────────────────────────────────────────────────────────────
// Vendored dependency trees — the MULLIGAN index-bloat regression.
// A vendored NUnit copy multiplies every common symbol's edge count, which is
// how one workspace reached 279,882 tags / 5.5M edges.
// ─────────────────────────────────────────────────────────────────────────────
describe('isExcludedPath — vendored trees', () => {
  test('excludes BuildSystem/Tools/NUnit (POSIX)', () => {
    assert.equal(isExcludedPath('BuildSystem/Tools/NUnit.2.5.7/bin/nunit.core.dll'), true)
  })

  test('excludes BuildSystem\\Tools\\NUnit (Windows)', () => {
    assert.equal(isExcludedPath('BuildSystem\\Tools\\NUnit.2.5.7\\doc\\index.html'), true)
  })

  test('excludes a bare Tools/ directory', () => {
    assert.equal(isExcludedPath('Tools/nuget/NuGet.exe'), true)
  })

  test('excludes ThirdParty and NuGet caches', () => {
    assert.equal(isExcludedPath('ThirdParty/log4net/log4net.cs'), true)
    assert.equal(isExcludedPath('src/NuGet/packages.config'), true)
  })

  test('does NOT exclude first-party names that merely contain a keyword', () => {
    assert.equal(isExcludedPath('src/Toolset/Builder.cs'), false)
    assert.equal(isExcludedPath('src/tools.ts'), false)
  })
})

// ─────────────────────────────────────────────────────────────────────────────
// toPosixRel — the Windows keying bug. The old code used
// `abs.replace(workspacePath + '/', '')`, which never matched backslash paths,
// so tags were silently keyed by ABSOLUTE paths.
// ─────────────────────────────────────────────────────────────────────────────
describe('toPosixRel', () => {
  const isWindows = sep === '\\'

  test('produces a relative POSIX path on the host platform', () => {
    const ws = join('tmp', 'MULLIGAN')
    const file = join(ws, 'src', 'Foo.cs')
    assert.equal(toPosixRel(file, ws), 'src/Foo.cs')
  })

  test('never returns an absolute path for a file inside the workspace', () => {
    const ws = join('tmp', 'MULLIGAN')
    const rel = toPosixRel(join(ws, 'a', 'b', 'c.ts'), ws)
    assert.equal(rel.startsWith('/'), false)
    assert.equal(/^[A-Za-z]:/.test(rel), false)
  })

  test('output never contains backslashes', () => {
    const ws = join('tmp', 'MULLIGAN')
    const rel = toPosixRel(join(ws, 'BuildSystem', 'Tools', 'x.dll'), ws)
    assert.equal(rel.includes('\\'), false)
    assert.equal(rel, 'BuildSystem/Tools/x.dll')
  })

  test('result feeds isExcludedPath correctly', () => {
    const ws = join('tmp', 'MULLIGAN')
    const rel = toPosixRel(join(ws, 'BuildSystem', 'Tools', 'NUnit.2.5.7', 'a.html'), ws)
    assert.equal(isExcludedPath(rel), true)
  })

  test('Windows drive-letter paths normalize (Windows only)', () => {
    if (!isWindows) return
    assert.equal(toPosixRel('C:\\repos\\MULLIGAN\\src\\Foo.cs', 'C:\\repos\\MULLIGAN'), 'src/Foo.cs')
  })
})

// ─────────────────────────────────────────────────────────────────────────────
// .atelierignore rule parsing
// ─────────────────────────────────────────────────────────────────────────────
describe('parseIgnoreRules + matchesSkipPattern', () => {
  const match = (rules: string, p: string): boolean =>
    matchesSkipPattern(p, parseIgnoreRules(rules))

  test('directory rule prunes the whole subtree', () => {
    assert.equal(match('BuildSystem/Tools/\n', 'BuildSystem/Tools/NUnit.2.5.7/a.dll'), true)
  })

  test('bare glob matches at any depth', () => {
    assert.equal(match('*.generated.html\n', 'docs/api/report.generated.html'), true)
  })

  test('comments and blank lines are ignored', () => {
    assert.deepEqual(parseIgnoreRules('# comment\n\n   \n'), [])
  })

  test('negation rules are rejected, not silently honored', () => {
    assert.deepEqual(parseIgnoreRules('!keep.ts\n'), [])
  })

  test('unrelated paths are not matched', () => {
    assert.equal(match('packages/\n', 'src/services/packager.ts'), false)
  })
})

/**
 * Unit tests for vector-search.service.ts pure functions and InMemoryCollection.
 * Tests cosine similarity, upsert, query with filtering, and collection lifecycle.
 */
import assert from 'node:assert/strict'
import { cosineSimilarity, InMemoryCollection } from '../vector-search.service'
import type { ProcessedChunk } from '../preprocessing.service'

let passed = 0
let failed = 0

function test(name: string, fn: () => void): void {
  try {
    fn()
    console.log(`  \u2713 ${name}`)
    passed++
  } catch (err) {
    console.error(`  \u2717 ${name}`)
    console.error(`    ${(err as Error).message}`)
    failed++
  }
}

function describe(name: string, fn: () => void): void {
  console.log(`\n${name}`)
  fn()
}

/** Helper to create a minimal ProcessedChunk for testing */
function makeProcessedChunk(overrides: Partial<ProcessedChunk['metadata']> = {}): ProcessedChunk {
  return {
    id: `chunk-${Math.random().toString(36).slice(2, 8)}`,
    body: 'validateJwt(token: string): boolean { return true }',
    embedText: '# File: auth.service.ts\nvalidateJwt(token: string): boolean { return true }',
    metadata: {
      filePath: 'src/auth/auth.service.ts',
      fileName: 'auth.service.ts',
      directory: 'src/auth',
      symbolName: 'validateJwt',
      symbolKind: 'method',
      className: 'AuthService',
      signature: 'validateJwt(token: string): boolean',
      startLine: 10,
      endLine: 15,
      language: 'typescript',
      isPublic: true,
      isAsync: false,
      isStatic: false,
      isAbstract: false,
      hasDocstring: false,
      lineCount: 5,
      hasDescription: false,
      lastModified: 0,
      indexedAt: Date.now(),
      projectName: '',
      hasTests: false,
      importedBy: [],
      pageRank: 0,
      ...overrides
    }
  }
}

// ── cosineSimilarity ──

describe('cosineSimilarity', () => {
  test('identical vectors return 1.0', () => {
    const v = [1, 2, 3]
    const result = cosineSimilarity(v, v)
    assert.ok(Math.abs(result - 1.0) < 1e-10, `Expected ~1.0, got ${result}`)
  })

  test('orthogonal vectors return 0.0', () => {
    const a = [1, 0, 0]
    const b = [0, 1, 0]
    const result = cosineSimilarity(a, b)
    assert.ok(Math.abs(result) < 1e-10, `Expected ~0.0, got ${result}`)
  })

  test('opposite vectors return -1.0', () => {
    const a = [1, 0, 0]
    const b = [-1, 0, 0]
    const result = cosineSimilarity(a, b)
    assert.ok(Math.abs(result - -1.0) < 1e-10, `Expected ~-1.0, got ${result}`)
  })

  test('different lengths return 0.0', () => {
    const a = [1, 2, 3]
    const b = [1, 2]
    const result = cosineSimilarity(a, b)
    assert.equal(result, 0, 'Mismatched lengths should return 0')
  })

  test('zero vectors return 0.0', () => {
    const a = [0, 0, 0]
    const b = [1, 2, 3]
    const result = cosineSimilarity(a, b)
    assert.equal(result, 0, 'Zero vector should return 0')
  })
})

// ── InMemoryCollection ──

describe('InMemoryCollection.upsert', () => {
  test('adds entries', () => {
    const collection = new InMemoryCollection()
    const chunk = makeProcessedChunk()
    collection.upsert(['id-1'], [[1, 0, 0]], [chunk])
    assert.equal(collection.size, 1)
  })

  test('updates existing entry by id', () => {
    const collection = new InMemoryCollection()
    const chunk1 = makeProcessedChunk({ symbolName: 'original' })
    const chunk2 = makeProcessedChunk({ symbolName: 'updated' })

    collection.upsert(['id-1'], [[1, 0, 0]], [chunk1])
    assert.equal(collection.size, 1)

    collection.upsert(['id-1'], [[0, 1, 0]], [chunk2])
    assert.equal(collection.size, 1, 'Should still be 1 entry after upsert')

    // Query with the updated embedding to verify it was replaced
    const results = collection.query([0, 1, 0], 1)
    assert.equal(results[0].symbolName, 'updated')
  })
})

describe('InMemoryCollection.query', () => {
  test('returns top N by similarity', () => {
    const collection = new InMemoryCollection()

    const chunkA = makeProcessedChunk({ symbolName: 'close' })
    const chunkB = makeProcessedChunk({ symbolName: 'far' })
    const chunkC = makeProcessedChunk({ symbolName: 'medium' })

    // Query vector is [1, 0, 0]
    // chunkA embedding [1, 0, 0] — identical (similarity ~1.0)
    // chunkC embedding [0.7, 0.7, 0] — medium similarity
    // chunkB embedding [0, 0, 1] — orthogonal (similarity ~0.0)
    collection.upsert(
      ['a', 'b', 'c'],
      [
        [1, 0, 0],
        [0, 0, 1],
        [0.7, 0.7, 0]
      ],
      [chunkA, chunkB, chunkC]
    )

    const results = collection.query([1, 0, 0], 2)
    assert.equal(results.length, 2)
    assert.equal(results[0].symbolName, 'close', 'Most similar should be first')
    assert.equal(results[1].symbolName, 'medium', 'Second most similar should be second')
  })

  test('filters by metadata where clause', () => {
    const collection = new InMemoryCollection()

    const tsChunk = makeProcessedChunk({ language: 'typescript', symbolName: 'tsFunc' })
    const pyChunk = makeProcessedChunk({ language: 'python', symbolName: 'pyFunc' })

    collection.upsert(
      ['ts-1', 'py-1'],
      [
        [1, 0, 0],
        [0.9, 0.1, 0]
      ],
      [tsChunk, pyChunk]
    )

    const results = collection.query([1, 0, 0], 10, { language: 'python' })
    assert.equal(results.length, 1)
    assert.equal(results[0].symbolName, 'pyFunc')
  })

  test('returns empty array when no entries match filter', () => {
    const collection = new InMemoryCollection()

    const chunk = makeProcessedChunk({ language: 'typescript' })
    collection.upsert(['id-1'], [[1, 0, 0]], [chunk])

    const results = collection.query([1, 0, 0], 10, { language: 'rust' })
    assert.equal(results.length, 0)
  })
})

describe('InMemoryCollection.clear', () => {
  test('resets size to 0', () => {
    const collection = new InMemoryCollection()
    const chunk = makeProcessedChunk()
    collection.upsert(
      ['id-1', 'id-2'],
      [
        [1, 0, 0],
        [0, 1, 0]
      ],
      [chunk, chunk]
    )
    assert.equal(collection.size, 2)

    collection.clear()
    assert.equal(collection.size, 0)
  })
})

describe('InMemoryCollection.size', () => {
  test('tracks entry count correctly', () => {
    const collection = new InMemoryCollection()
    assert.equal(collection.size, 0)

    const chunk = makeProcessedChunk()
    collection.upsert(['a'], [[1, 0, 0]], [chunk])
    assert.equal(collection.size, 1)

    collection.upsert(['b'], [[0, 1, 0]], [chunk])
    assert.equal(collection.size, 2)

    collection.upsert(['c'], [[0, 0, 1]], [chunk])
    assert.equal(collection.size, 3)
  })
})

// ── Search edge cases ──

describe('InMemoryCollection.query edge cases', () => {
  test('empty collection returns empty results', () => {
    const collection = new InMemoryCollection()
    const results = collection.query([1, 0, 0], 10)
    assert.equal(results.length, 0)
  })

  test('caps nResults to available entries', () => {
    const collection = new InMemoryCollection()
    const chunk = makeProcessedChunk()
    collection.upsert(['only-one'], [[1, 0, 0]], [chunk])

    // Ask for 100 results but only 1 exists
    const results = collection.query([1, 0, 0], 100)
    assert.equal(results.length, 1)
  })

  test('nResults=0 returns empty array', () => {
    const collection = new InMemoryCollection()
    const chunk = makeProcessedChunk()
    collection.upsert(['id-1'], [[1, 0, 0]], [chunk])

    const results = collection.query([1, 0, 0], 0)
    assert.equal(results.length, 0)
  })

  test('query with all-zero embedding returns results (sorted by default)', () => {
    const collection = new InMemoryCollection()
    const chunk = makeProcessedChunk()
    collection.upsert(['id-1'], [[1, 0, 0]], [chunk])

    // Zero query vector → cosine similarity = 0 for all entries, but should not throw
    const results = collection.query([0, 0, 0], 10)
    assert.equal(results.length, 1)
  })

  test('getEntries returns all stored entries', () => {
    const collection = new InMemoryCollection()
    const chunkA = makeProcessedChunk({ symbolName: 'first' })
    const chunkB = makeProcessedChunk({ symbolName: 'second' })
    collection.upsert(
      ['a', 'b'],
      [
        [1, 0, 0],
        [0, 1, 0]
      ],
      [chunkA, chunkB]
    )

    const entries = collection.getEntries()
    assert.equal(entries.length, 2)
  })
})

// ── Indexing pipeline structural verification ──
// These tests verify critical structural invariants of the indexing pipeline
// by reading the source code, ensuring guards and phases remain in the correct order.

import { readFileSync } from 'node:fs'
import path from 'node:path'

describe('VectorSearchService.indexProject — phase transitions', () => {
  const source = readFileSync(
    path.join(process.cwd(), 'src/main/services/vector-search.service.ts'),
    'utf-8'
  )

  test('EMBEDDING_BATCH_SIZE constant is 32', () => {
    assert.ok(
      source.includes('EMBEDDING_BATCH_SIZE = 32'),
      'Batch size should be 32 for WASM backend (adaptive retry halves on OOM)'
    )
  })

  test('embedding init is deferred until after preprocessing (not before)', () => {
    // The WASM model init must come AFTER preprocessing (which spawns CLI processes)
    // to avoid memory pressure from concurrent CLI + WASM allocation.
    // After decomposition, embedding init is in embedChunksWithCheckpoints.
    const preprocessIdx = source.indexOf('preprocessChunks')
    const initIdx = source.indexOf('Embedding model init')
    const batchLoopIdx = source.indexOf('for (let i = startOffset; i < processedChunks.length')
    assert.ok(preprocessIdx > 0, 'preprocessChunks method should exist')
    assert.ok(initIdx > 0, 'Deferred embedding init comment should exist')
    assert.ok(batchLoopIdx > 0, 'Batch loop should exist')
    assert.ok(initIdx > preprocessIdx, 'Embedding init should come after preprocessing')
    assert.ok(initIdx < batchLoopIdx, 'Embedding init should come before batch loop')
  })

  test('GC hint exists between preprocessing and embedding batch loop', () => {
    const preprocessEndIdx = source.indexOf('preprocessOpts.cancelled')
    const gcIdx = source.indexOf('global.gc()')
    const batchLoopIdx = source.indexOf('for (let i = 0; i < processedChunks.length')
    assert.ok(gcIdx > 0, 'GC hint should exist')
    assert.ok(batchLoopIdx > 0, 'Batch loop should exist')
    assert.ok(preprocessEndIdx > 0, 'Preprocessing cancellation check should exist')
    // GC comes after preprocessing cancellation check, before the batch embed loop
    assert.ok(gcIdx > preprocessEndIdx, 'GC hint should come after preprocessing')
    assert.ok(gcIdx < batchLoopIdx, 'GC hint should come before batch embed loop')
  })
})

// ── Summary ──

console.log(`\n${'─'.repeat(40)}`)
console.log(`vector-search: ${passed} passed, ${failed} failed`)
if (failed > 0) process.exitCode = 1

import { EventEmitter } from 'node:events'
import log from 'electron-log/main'
import { memoryCheckpoint } from './indexing-diagnostics'
import { localEmbeddingProvider } from './local-embedding.provider'
import { descriptionCache } from './description-cache.service'
import { generateHeuristicDescription } from './heuristic-description.service'
import {
  runPreprocessingPipeline,
  DEFAULT_PREPROCESSING_OPTIONS,
  type RawChunk,
  type ProcessedChunk,
  type PreprocessingOptions
} from './preprocessing.service'
import { codeChunkRepository } from '../db/repositories/code-chunk.repository'
import {
  chunkEmbeddingRepository,
  type EmbeddingEntry
} from '../db/repositories/chunk-embedding.repository'
import { getDatabase } from '../db/index'
import type { IndexingState, SemanticSearchResult } from '../../shared/types'

/**
 * Embedding model name — stored in indexing_state for provenance. Changing this
 * value invalidates persisted embeddings (see loadPersistedIndex) and triggers
 * a full re-index, which transparently handles the vector-dimension change.
 *
 * Returns null when the provider isn't initialized yet — callers
 * that need provenance MUST ensure the provider is ready first.
 */
function getEmbeddingModelName(): string | null {
  return localEmbeddingProvider.activeModelName || null
}

/**
 * Max batch size for embedding calls.
 *
 * Texts are POSTed to the oMLX server's /v1/embeddings endpoint in batches
 * of 32. The adaptive retry in embed() halves the batch on error as a safety
 * net for oversized requests.
 */
const EMBEDDING_BATCH_SIZE = 32

/**
 * Checkpoint interval: persist embeddings + chunks to SQLite every N batches.
 * At batch size 32, 50 batches = 1,600 chunks ≈ every ~5 minutes of embedding.
 * Crash recovery restarts from the last checkpoint instead of from zero.
 */
const CHECKPOINT_INTERVAL_BATCHES = 50

/**
 * In-memory vector store entry.
 * Runtime cosine similarity search stays in RAM for speed.
 */
interface VectorEntry {
  id: string
  embedding: number[]
  chunk: ProcessedChunk
}

/**
 * Simple in-memory vector collection.
 * Loaded from SQLite on startup, kept in RAM for fast queries.
 */
export class InMemoryCollection {
  private entries: VectorEntry[] = []

  upsert(ids: string[], embeddings: number[][], chunks: ProcessedChunk[]): void {
    for (let i = 0; i < ids.length; i++) {
      const existing = this.entries.findIndex((e) => e.id === ids[i])
      const entry: VectorEntry = {
        id: ids[i],
        embedding: embeddings[i],
        chunk: chunks[i]
      }
      if (existing >= 0) {
        this.entries[existing] = entry
      } else {
        this.entries.push(entry)
      }
    }
  }

  query(
    queryEmbedding: number[],
    nResults: number,
    where?: Record<string, unknown>
  ): SemanticSearchResult[] {
    // Compute cosine similarity for all entries
    let candidates = this.entries

    // Apply metadata filters
    if (where) {
      candidates = candidates.filter((entry) => {
        const meta = entry.chunk.metadata
        for (const [key, value] of Object.entries(where)) {
          const metaValue = meta[key as keyof typeof meta]
          if (metaValue !== value) return false
        }
        return true
      })
    }

    const scored = candidates.map((entry) => ({
      entry,
      score: cosineSimilarity(queryEmbedding, entry.embedding)
    }))

    // Sort by similarity descending
    scored.sort((a, b) => b.score - a.score)

    return scored.slice(0, nResults).map((s) => ({
      filePath: s.entry.chunk.metadata.filePath,
      symbolName: s.entry.chunk.metadata.symbolName,
      body: s.entry.chunk.body,
      score: s.score,
      metadata: s.entry.chunk.metadata as unknown as Record<string, unknown>
    }))
  }

  get size(): number {
    return this.entries.length
  }

  clear(): void {
    this.entries = []
  }

  /**
   * Get all entries (for persistence).
   */
  getEntries(): VectorEntry[] {
    return this.entries
  }
}

/**
 * Cosine similarity between two vectors.
 */
export function cosineSimilarity(a: number[], b: number[]): number {
  if (a.length !== b.length) return 0

  let dotProduct = 0
  let normA = 0
  let normB = 0

  for (let i = 0; i < a.length; i++) {
    dotProduct += a[i] * b[i]
    normA += a[i] * a[i]
    normB += b[i] * b[i]
  }

  const denominator = Math.sqrt(normA) * Math.sqrt(normB)
  return denominator === 0 ? 0 : dotProduct / denominator
}

/**
 * Format milliseconds into a human-readable ETA string.
 * Examples: "~2 min", "~45 min", "~1.5 hrs"
 */
function formatEta(ms: number): string {
  const seconds = Math.ceil(ms / 1000)
  if (seconds < 60) return '< 1 min'
  const minutes = Math.round(seconds / 60)
  if (minutes < 60) return `~${minutes} min`
  const hours = (minutes / 60).toFixed(1)
  return `~${hours} hrs`
}

/**
 * Service for semantic vector search over indexed codebases.
 * Manages per-workspace vector collections, indexing pipeline, and search.
 *
 * Persistence: After indexing, chunks + embeddings are saved to SQLite.
 * On workspace open, the persisted index is loaded from SQLite into RAM.
 *
 * Events:
 * - 'progress': IndexingState — progress updates during indexing
 */
class VectorSearchService extends EventEmitter {
  private collections = new Map<string, InMemoryCollection>()
  private indexingStates = new Map<string, IndexingState>()
  private preprocessingOptions = new Map<string, PreprocessingOptions>()
  /** Tracks when the embedding phase started (per-workspace) for ETA calculation */
  private embeddingStartTimes = new Map<string, number>()
  /** Tracks when the AI-description preprocessing phase started (per-workspace) for ETA calculation */
  private descriptionStartTimes = new Map<string, number>()
  /** Throttle bookkeeping for progress emission (per-workspace) */
  private lastEmitAt = new Map<string, number>()
  private lastEmitStatus = new Map<string, IndexingState['status']>()
  private pendingEmit = new Map<string, ReturnType<typeof setTimeout>>()
  private static readonly EMIT_THROTTLE_MS = 150

  private makeDefaultState(): IndexingState {
    return {
      status: 'idle',
      totalFiles: 0,
      processedFiles: 0,
      totalChunks: 0,
      processedChunks: 0,
      preprocessTotal: 0,
      preprocessComplete: 0,
      preprocessSkipped: 0,
      descriptionsGenerated: 0,
      descriptionsCached: 0,
      descriptionsTotal: 0,
      descriptionsProcessed: 0,
      descriptionSource: 'none'
    }
  }

  // ── Persistence Methods ──────────────────────────────────────────────────

  /**
   * Check if a workspace has persisted embeddings in SQLite.
   */
  hasPersistedIndex(workspaceId: string): boolean {
    return chunkEmbeddingRepository.hasEmbeddings(workspaceId)
  }

  /**
   * Load persisted chunks + embeddings from SQLite into the in-memory collection.
   * Called on workspace open for instant search readiness (<1s for 10k vectors).
   */
  async loadPersistedIndex(workspaceId: string): Promise<{ symbolCount: number }> {
    const start = Date.now()

    // Load chunks from DB
    const chunks = codeChunkRepository.findByWorkspace(workspaceId)
    if (chunks.length === 0) {
      log.info(`[VectorSearch] No persisted chunks for workspace ${workspaceId}`)
      return { symbolCount: 0 }
    }

    // Check if persisted embeddings were generated with a different model
    const dbForModelCheck = getDatabase()
    const modelRow = dbForModelCheck
      .prepare('SELECT embedding_model FROM indexing_state WHERE workspace_id = ?')
      .get(workspaceId) as { embedding_model?: string } | undefined

    const currentModelName = getEmbeddingModelName()
    // Skip model-change check if embedding provider hasn't initialized yet —
    // we can't know the actual model name until the user's oMLX server is queried.
    // The check will happen later in initializeEmbeddingModel() → reindexFiles().
    if (currentModelName && modelRow?.embedding_model && modelRow.embedding_model !== currentModelName) {
      log.info(
        `[VectorSearch] Model changed (${modelRow.embedding_model} → ${currentModelName}), ` +
          `invalidating persisted index for ${workspaceId}`
      )
      chunkEmbeddingRepository.deleteByWorkspace(workspaceId)
      return { symbolCount: 0 }
    }

    // Load embeddings from DB
    const embeddings = chunkEmbeddingRepository.loadAllForWorkspace(workspaceId)
    if (embeddings.length === 0) {
      log.info(`[VectorSearch] No persisted embeddings for workspace ${workspaceId}`)
      return { symbolCount: 0 }
    }

    // Build a map from chunkId -> embedding for fast lookup
    const embeddingMap = new Map<string, number[]>()
    for (const entry of embeddings) {
      embeddingMap.set(entry.chunkId, entry.embedding)
    }

    // Create/get in-memory collection and populate it
    let collection = this.collections.get(workspaceId)
    if (!collection) {
      collection = new InMemoryCollection()
      this.collections.set(workspaceId, collection)
    }

    // Only load chunks that have matching embeddings
    const matchedChunks: ProcessedChunk[] = []
    const matchedEmbeddings: number[][] = []
    const matchedIds: string[] = []

    for (const chunk of chunks) {
      const embedding = embeddingMap.get(chunk.id)
      if (embedding) {
        matchedChunks.push(chunk)
        matchedEmbeddings.push(embedding)
        matchedIds.push(chunk.id)
      }
    }

    collection.upsert(matchedIds, matchedEmbeddings, matchedChunks)

    const elapsed = Date.now() - start
    log.info(
      `[VectorSearch] Loaded persisted index for ${workspaceId}: ${matchedIds.length} vectors in ${elapsed}ms`
    )

    // Update indexing state to reflect loaded index
    const state = this.makeDefaultState()
    state.workspaceId = workspaceId
    state.status = 'complete'
    state.totalChunks = matchedIds.length
    state.processedChunks = matchedIds.length
    this.indexingStates.set(workspaceId, state)

    return { symbolCount: matchedIds.length }
  }

  /**
   * Persist all in-memory chunks + embeddings to SQLite.
   * Called after indexing completes successfully.
   */
  private saveToDb(
    workspaceId: string,
    processedChunks: ProcessedChunk[],
    fileMtimes: Map<string, number>,
    embeddingModel: string
  ): void {
    const start = Date.now()
    const collection = this.collections.get(workspaceId)
    if (!collection) return

    const entries = collection.getEntries()
    if (entries.length === 0) return

    const db = getDatabase()
    const transaction = db.transaction(() => {
      // Persist chunks
      codeChunkRepository.upsertChunks(workspaceId, processedChunks, fileMtimes)

      // Persist embeddings
      const embeddingEntries: EmbeddingEntry[] = entries.map((entry) => ({
        chunkId: entry.id,
        embedding: entry.embedding,
        model: embeddingModel
      }))
      chunkEmbeddingRepository.upsertEmbeddings(workspaceId, embeddingEntries)

      // Update indexing_state
      db.prepare(
        `
        INSERT OR REPLACE INTO indexing_state
          (workspace_id, status, total_files, processed_files, total_chunks, processed_chunks,
           embedding_model, checkpoint_offset, last_completed_at, updated_at)
        VALUES (?, 'complete', ?, ?, ?, ?, ?, ?, datetime('now'), datetime('now'))
      `
      ).run(
        workspaceId,
        0, // total_files — not tracked at this level
        0,
        processedChunks.length,
        processedChunks.length,
        embeddingModel,
        processedChunks.length // checkpoint_offset = total on complete
      )
    })

    transaction()

    const elapsed = Date.now() - start
    log.info(
      `[VectorSearch] Persisted ${entries.length} vectors for ${workspaceId} in ${elapsed}ms`
    )
  }

  /**
   * Checkpoint: persist partial progress to SQLite during embedding.
   * Saves all chunks + embeddings that have been processed so far, and
   * records the checkpoint offset in indexing_state for resume-after-crash.
   */
  private checkpointToDb(
    workspaceId: string,
    processedChunks: ProcessedChunk[],
    embeddedUpTo: number,
    fileMtimes: Map<string, number>,
    embeddingModel: string
  ): void {
    const start = Date.now()
    const collection = this.collections.get(workspaceId)
    if (!collection) return

    const entries = collection.getEntries()
    if (entries.length === 0) return

    const db = getDatabase()
    const transaction = db.transaction(() => {
      // Persist all chunks (needed for resume to map IDs to embeddings)
      codeChunkRepository.upsertChunks(workspaceId, processedChunks, fileMtimes)

      // Persist embeddings accumulated so far
      const embeddingEntries: EmbeddingEntry[] = entries.map((entry) => ({
        chunkId: entry.id,
        embedding: entry.embedding,
        model: embeddingModel
      }))
      chunkEmbeddingRepository.upsertEmbeddings(workspaceId, embeddingEntries)

      // Update checkpoint offset in indexing_state
      db.prepare(
        `
        INSERT OR REPLACE INTO indexing_state
          (workspace_id, status, total_chunks, processed_chunks,
           embedding_model, checkpoint_offset, updated_at)
        VALUES (?, 'indexing', ?, ?, ?, ?, datetime('now'))
      `
      ).run(workspaceId, processedChunks.length, embeddedUpTo, embeddingModel, embeddedUpTo)
    })

    transaction()

    const elapsed = Date.now() - start
    log.info(
      `[VectorSearch] Checkpoint at ${embeddedUpTo}/${processedChunks.length} chunks in ${elapsed}ms`
    )
  }

  /**
   * Get the checkpoint offset from indexing_state for resume support.
   * Returns 0 if no checkpoint exists or status is not 'indexing'.
   */
  getCheckpointOffset(workspaceId: string): number {
    try {
      const db = getDatabase()
      const row = db
        .prepare(`SELECT checkpoint_offset, status FROM indexing_state WHERE workspace_id = ?`)
        .get(workspaceId) as { checkpoint_offset: number; status: string } | undefined

      if (row && row.status === 'indexing' && row.checkpoint_offset > 0) {
        return row.checkpoint_offset
      }
    } catch (e) {
      log.warn('[VectorSearch] Failed to get checkpoint offset:', e)
    }
    return 0
  }

  // ── Indexing Pipeline ────────────────────────────────────────────────────

  /**
   * Index a project: scan files, preprocess chunks, embed, and store vectors.
   * After completion, persists everything to SQLite for fast reload on restart.
   *
   * Orchestrator that delegates to three phases:
   *   1. preprocessChunks() — description strategy, preprocessing pipeline
   *   2. embedChunksWithCheckpoints() — embedding init, checkpoint resume, batch loop
   *   3. persistIndex() — final SQLite persistence
   */
  async indexProject(
    workspaceId: string,
    workspacePath: string,
    tags: RawChunk[],
    fileContents: Map<string, string>,
    options?: Partial<PreprocessingOptions>
  ): Promise<void> {
    const state = this.makeDefaultState()
    state.workspaceId = workspaceId
    state.status = 'scanning'
    state.totalChunks = tags.length
    this.indexingStates.set(workspaceId, state)

    memoryCheckpoint('INDEX_START', {
      tags: tags.length,
      files: fileContents.size,
      descriptions: !!options?.generateDescriptions
    })

    descriptionCache.setWorkspaceId(workspaceId)

    const preprocessOpts: PreprocessingOptions = {
      ...DEFAULT_PREPROCESSING_OPTIONS,
      ...options
    }
    this.preprocessingOptions.set(workspaceId, preprocessOpts)

    this.emitProgress(workspaceId)
    this.updateIndexingStateDb(workspaceId, 'scanning')

    try {
      let collection = this.collections.get(workspaceId)
      if (!collection) {
        collection = new InMemoryCollection()
        this.collections.set(workspaceId, collection)
      }

      // Phase 1: Preprocess chunks
      const processedChunks = await this.preprocessChunks(
        workspaceId,
        workspacePath,
        tags,
        fileContents,
        preprocessOpts,
        state
      )

      if (preprocessOpts.cancelled) {
        state.status = 'idle'
        this.emitProgress(workspaceId)
        this.updateIndexingStateDb(workspaceId, 'idle')
        return
      }

      // Phase 2: Embed chunks with checkpoint support
      const result = await this.embedChunksWithCheckpoints(
        workspaceId,
        workspacePath,
        processedChunks,
        fileContents,
        preprocessOpts,
        state,
        collection
      )

      // Phase 3: Persist (only on success)
      if (result === 'completed') {
        this.persistIndex(
          workspaceId,
          processedChunks,
          fileContents,
          workspacePath,
          state,
          collection
        )
      } else if (result === 'cancelled') {
        state.status = 'idle'
        this.updateIndexingStateDb(workspaceId, 'idle')
      }

      this.emitProgress(workspaceId)
    } catch (error) {
      state.status = 'error'
      state.error = (error as Error).message
      memoryCheckpoint('INDEX_FATAL_ERROR', { error: (error as Error).message })
      log.error(`[VectorSearch] Indexing failed for ${workspaceId}:`, error)
      this.emitProgress(workspaceId)
      this.updateIndexingStateDb(workspaceId, 'error', (error as Error).message)
    }
  }

  /**
   * Phase 1: Preprocess raw chunks — select description strategy, run preprocessing pipeline.
   */
  private async preprocessChunks(
    workspaceId: string,
    workspacePath: string,
    tags: RawChunk[],
    fileContents: Map<string, string>,
    preprocessOpts: PreprocessingOptions,
    state: IndexingState
  ): Promise<ProcessedChunk[]> {
    state.status = 'preprocessing'
    state.preprocessTotal = tags.length
    this.emitProgress(workspaceId)
    this.updateIndexingStateDb(workspaceId, 'preprocessing')

    memoryCheckpoint('PREPROCESS_START', { totalTags: tags.length })

    const projectName = workspacePath.split('/').pop() ?? 'unknown'
    state.descriptionSource = preprocessOpts.generateDescriptions ? 'ai' : 'heuristic'

    // Shared description strategy (also used by reindexFiles)
    const { getDescription, getBatchDescriptions } = this.setupDescriptionStrategy(
      preprocessOpts,
      workspacePath,
      state
    )

    memoryCheckpoint('PREPROCESS_PIPELINE_ENTER', {
      generateDescriptions: !!preprocessOpts.generateDescriptions
    })

    const processedChunks = await runPreprocessingPipeline(
      tags,
      fileContents,
      projectName,
      preprocessOpts,
      (update) => {
        state.processedFiles = update.processedFiles
        state.totalFiles = update.totalFiles
        state.processedChunks = update.processedChunks
        state.preprocessComplete = update.processedChunks
        state.preprocessSkipped = update.skippedFiles
        state.currentFile = update.currentFile
        this.emitProgress(workspaceId)
      },
      getDescription,
      getBatchDescriptions,
      (descUpdate) => {
        state.descriptionsTotal = descUpdate.descriptionsTotal
        state.descriptionsProcessed = descUpdate.descriptionsProcessed
        state.descriptionsCached = descUpdate.descriptionsCached
        state.descriptionsGenerated = descUpdate.descriptionsGenerated
        this.emitProgress(workspaceId)
      }
    )

    memoryCheckpoint('PREPROCESS_PIPELINE_EXIT', {
      processedChunks: processedChunks.length,
      cancelled: !!preprocessOpts.cancelled
    })
    return processedChunks
  }

  /**
   * Phase 2: Embed preprocessed chunks with checkpoint resume, pause/cancel, periodic checkpointing.
   * Returns 'completed' | 'cancelled' | 'error'.
   */
  private async embedChunksWithCheckpoints(
    workspaceId: string,
    workspacePath: string,
    processedChunks: ProcessedChunk[],
    fileContents: Map<string, string>,
    preprocessOpts: PreprocessingOptions,
    state: IndexingState,
    collection: InMemoryCollection
  ): Promise<'completed' | 'cancelled' | 'error'> {
    state.status = 'indexing-chunks'
    state.totalChunks = processedChunks.length
    state.processedChunks = 0
    this.emitProgress(workspaceId)
    this.updateIndexingStateDb(workspaceId, 'indexing')

    // Nudge GC between preprocessing and embedding phases
    memoryCheckpoint('GC_BEFORE')
    if (global.gc) {
      log.info('[VectorSearch] Running GC hint between preprocessing and embedding phases')
      global.gc()
    }
    memoryCheckpoint('GC_AFTER')

    // Embedding model init — delegated to sub-method (worker or WASM fallback)
    const embedFn = await this.initializeEmbeddingModel()

    // Sub-method 2: Resume from checkpoint if available
    const startOffset = this.resumeFromCheckpoint(workspaceId, processedChunks, collection)
    if (startOffset > 0) {
      state.processedChunks = startOffset
      this.emitProgress(workspaceId)
    }

    const fileMtimes = this.buildFileMtimeMap(workspacePath, fileContents)
    this.embeddingStartTimes.set(workspaceId, Date.now())

    const totalBatches = Math.ceil((processedChunks.length - startOffset) / EMBEDDING_BATCH_SIZE)
    memoryCheckpoint('EMBED_LOOP_START', {
      chunks: processedChunks.length,
      batchSize: EMBEDDING_BATCH_SIZE,
      totalBatches,
      startOffset
    })

    // Sub-method 3: Core batch embedding loop with checkpointing
    return this.embedBatchLoop(
      workspaceId,
      processedChunks,
      startOffset,
      collection,
      state,
      preprocessOpts,
      fileMtimes,
      embedFn
    )
  }

  /**
   * Phase 3: Persist completed index to SQLite and finalize state.
   */
  private persistIndex(
    workspaceId: string,
    processedChunks: ProcessedChunk[],
    fileContents: Map<string, string>,
    workspacePath: string,
    state: IndexingState,
    collection: InMemoryCollection
  ): void {
    state.status = 'complete'
    state.processedChunks = processedChunks.length
    memoryCheckpoint('INDEX_COMPLETE', { vectors: collection.size })
    log.info(`[VectorSearch] Indexing complete for ${workspaceId}: ${collection.size} vectors`)

    const fileMtimes = this.buildFileMtimeMap(workspacePath, fileContents)
    try {
      this.saveToDb(workspaceId, processedChunks, fileMtimes, getEmbeddingModelName() ?? 'unknown')
    } catch (persistError) {
      log.warn('[VectorSearch] Failed to persist index to SQLite:', persistError)
    }
  }

  /**
   * Build a map of relative file path → mtime for persistence.
   */
  private buildFileMtimeMap(
    workspacePath: string,
    fileContents: Map<string, string>
  ): Map<string, number> {
    const fileMtimes = new Map<string, number>()
    // eslint-disable-next-line @typescript-eslint/no-require-imports -- dynamic native module import for persistence
    const { statSync } = require('node:fs') as typeof import('node:fs')
    // eslint-disable-next-line @typescript-eslint/no-require-imports -- dynamic native module import for persistence
    const { join } = require('node:path') as typeof import('node:path')
    for (const relPath of fileContents.keys()) {
      try {
        const absPath = join(workspacePath, relPath)
        const stat = statSync(absPath)
        fileMtimes.set(relPath, stat.mtimeMs)
      } catch {
        fileMtimes.set(relPath, 0)
      }
    }
    return fileMtimes
  }

  // ── Incremental Re-indexing ──────────────────────────────────────────────

  /**
   * Incrementally re-index specific files — preprocess + embed only the
   * provided chunks, then upsert into the existing in-memory collection.
   * Does NOT reset progress counters or clear the collection.
   *
   * This fixes the "resume doesn't skip already-indexed files" bug:
   * instead of re-running indexProject() with ALL chunks, callers pass only
   * the chunks for changed files. The collection uses upsert semantics so
   * existing chunk IDs are updated, new ones are added.
   */
  async reindexFiles(
    workspaceId: string,
    workspacePath: string,
    chunks: RawChunk[],
    fileContents: Map<string, string>,
    options?: Partial<PreprocessingOptions>
  ): Promise<void> {
    const collection = this.collections.get(workspaceId)
    if (!collection) {
      log.warn(`[VectorSearch] No collection for workspace ${workspaceId}, skipping incremental`)
      return
    }

    const preprocessOpts: PreprocessingOptions = {
      ...DEFAULT_PREPROCESSING_OPTIONS,
      ...options
    }

    descriptionCache.setWorkspaceId(workspaceId)
    const projectName = workspacePath.split('/').pop() ?? 'unknown'

    // Shared description strategy (also used by preprocessChunks)
    const { getDescription, getBatchDescriptions } = this.setupDescriptionStrategy(
      preprocessOpts,
      workspacePath
    )

    // Preprocess only the changed chunks
    const processedChunks = await runPreprocessingPipeline(
      chunks,
      fileContents,
      projectName,
      preprocessOpts,
      () => {},
      getDescription,
      getBatchDescriptions
    )

    if (processedChunks.length === 0) return

    // Ensure embedding model is loaded before first use
    if (!localEmbeddingProvider.isReady) {
      await localEmbeddingProvider.initialize()
    }

    // Embed and upsert in batches
    for (let i = 0; i < processedChunks.length; i += EMBEDDING_BATCH_SIZE) {
      const batch = processedChunks.slice(i, i + EMBEDDING_BATCH_SIZE)
      const texts = batch.map((c) => c.embedText)

      try {
        const embeddings = await localEmbeddingProvider.embed(texts)
        const ids = batch.map((c) => c.id)
        collection.upsert(ids, embeddings, batch)
      } catch (error) {
        log.error(`[VectorSearch] Incremental embedding failed:`, error)
        return
      }
    }

    // Persist updated collection to DB
    const { statSync } = await import('node:fs')
    const { join } = await import('node:path')
    const fileMtimes = new Map<string, number>()
    for (const relPath of fileContents.keys()) {
      try {
        const stat = statSync(join(workspacePath, relPath))
        fileMtimes.set(relPath, stat.mtimeMs)
      } catch {
        fileMtimes.set(relPath, 0)
      }
    }
    this.saveToDb(workspaceId, processedChunks, fileMtimes, getEmbeddingModelName() ?? 'unknown')

    log.info(`[VectorSearch] Incremental: upserted ${processedChunks.length} chunks`)
  }

  // ── Search ───────────────────────────────────────────────────────────────

  /**
   * Search the indexed codebase with a natural language query.
   */
  async search(
    workspaceId: string,
    query: string,
    options?: { nResults?: number; where?: Record<string, unknown> }
  ): Promise<SemanticSearchResult[]> {
    const collection = this.collections.get(workspaceId)
    if (!collection || collection.size === 0) {
      log.warn(`[VectorSearch] No index for workspace ${workspaceId}`)
      return []
    }

    try {
      // Ensure embedding model is loaded before first use
      if (!localEmbeddingProvider.isReady) {
        await localEmbeddingProvider.initialize()
      }
      const [queryEmbedding] = await localEmbeddingProvider.embed([query])
      return collection.query(queryEmbedding, options?.nResults ?? 5, options?.where)
    } catch (error) {
      log.error(`[VectorSearch] Search failed for workspace ${workspaceId}:`, error)
      return []
    }
  }

  /**
   * Search by raw code snippet — embed the snippet and find nearest neighbors.
   * Used by the `similar_code` MCP tool.
   */
  async searchByCode(
    workspaceId: string,
    code: string,
    opts?: { nResults?: number; language?: string }
  ): Promise<SemanticSearchResult[]> {
    const collection = this.collections.get(workspaceId)
    if (!collection || collection.size === 0) {
      log.warn(`[VectorSearch] No index for workspace ${workspaceId}`)
      return []
    }

    try {
      // Ensure embedding model is loaded before first use
      if (!localEmbeddingProvider.isReady) {
        await localEmbeddingProvider.initialize()
      }
      const [codeEmbedding] = await localEmbeddingProvider.embed([code])
      const where = opts?.language ? { language: opts.language } : undefined
      return collection.query(codeEmbedding, opts?.nResults ?? 10, where)
    } catch (error) {
      log.error(`[VectorSearch] searchByCode failed for workspace ${workspaceId}:`, error)
      return []
    }
  }

  /**
   * Cluster code chunks by embedding similarity to identify conceptual groupings.
   * Uses a greedy approach: pick highest-reference chunks as cluster centers,
   * then group remaining chunks by nearest center.
   */
  getConceptClusters(
    workspaceId: string,
    opts?: { maxClusters?: number }
  ): {
    clusterId: number
    representative: { filePath: string; symbolName: string }
    members: { filePath: string; symbolName: string; similarity: number }[]
  }[] {
    const collection = this.collections.get(workspaceId)
    if (!collection || collection.size === 0) return []

    const maxClusters = opts?.maxClusters ?? 10
    const entries = collection.getEntries()
    if (entries.length === 0) return []

    // Phase 1: Select diverse cluster centers via maximin initialization
    const centers = this.selectClusterCenters(entries, maxClusters)

    // Phase 2: Assign entries to nearest center
    const clusters = this.assignClustersToMembers(entries, centers)

    // Sort clusters by size descending, limit member list
    return clusters
      .sort((a, b) => b.members.length - a.members.length)
      .map(({ clusterId, representative, members }) => ({
        clusterId,
        representative,
        members: members.slice(0, 15) // cap per-cluster members
      }))
  }

  // ── Control Methods ──────────────────────────────────────────────────────

  /**
   * Pause indexing for a workspace.
   */
  pauseIndexing(workspaceId: string): void {
    const opts = this.preprocessingOptions.get(workspaceId)
    if (opts) {
      opts.paused = true
      const state = this.indexingStates.get(workspaceId)
      if (state) {
        state.status = 'paused'
        this.emitProgress(workspaceId)
      }
    }
  }

  /**
   * Resume indexing for a workspace.
   */
  resumeIndexing(workspaceId: string): void {
    const opts = this.preprocessingOptions.get(workspaceId)
    if (opts) {
      opts.paused = false
    }
  }

  /**
   * Cancel indexing for a workspace.
   */
  cancelIndexing(workspaceId: string): void {
    const opts = this.preprocessingOptions.get(workspaceId)
    if (opts) {
      opts.cancelled = true
      opts.paused = false
    }
  }

  /**
   * Get the current indexing state for a workspace.
   */
  getIndexingState(workspaceId: string): IndexingState {
    return this.indexingStates.get(workspaceId) ?? this.makeDefaultState()
  }

  /**
   * Clean up a workspace's vector collection.
   */
  async dispose(workspaceId: string): Promise<void> {
    this.cancelIndexing(workspaceId)
    const collection = this.collections.get(workspaceId)
    if (collection) {
      collection.clear()
      this.collections.delete(workspaceId)
    }
    this.indexingStates.delete(workspaceId)
    this.preprocessingOptions.delete(workspaceId)
    this.embeddingStartTimes.delete(workspaceId)
    this.descriptionStartTimes.delete(workspaceId)
    const pending = this.pendingEmit.get(workspaceId)
    if (pending) clearTimeout(pending)
    this.pendingEmit.delete(workspaceId)
    this.lastEmitAt.delete(workspaceId)
    this.lastEmitStatus.delete(workspaceId)
    log.info(`[VectorSearch] Disposed workspace ${workspaceId}`)
  }

  /**
   * Check if a workspace has an active in-memory index.
   */
  hasIndex(workspaceId: string): boolean {
    const collection = this.collections.get(workspaceId)
    return !!collection && collection.size > 0
  }

  // ── Private Helpers ──────────────────────────────────────────────────────

  /**
   * Build the description strategy callbacks (getDescription + getBatchDescriptions)
   * shared by preprocessChunks() and reindexFiles(). Returns the callback pair
   * based on whether AI or heuristic descriptions are configured.
   */
  private setupDescriptionStrategy(
    preprocessOpts: PreprocessingOptions,
    workspacePath: string,
    state?: IndexingState
  ): {
    getDescription: (chunk: RawChunk, embedText: string) => Promise<string | undefined>
    getBatchDescriptions?: (
      chunks: Array<{ chunk: RawChunk; embedText: string }>
    ) => Promise<{ descriptions: Map<number, string>; cached: number; generated: number }>
  } {
    const useAiDescriptions = preprocessOpts.generateDescriptions

    const getBatchDescriptions = useAiDescriptions
      ? async (
          chunks: Array<{ chunk: RawChunk; embedText: string }>
        ): Promise<{ descriptions: Map<number, string>; cached: number; generated: number }> => {
          return descriptionCache.getOrGenerateBatch(
            chunks,
            preprocessOpts.descriptionModel,
            workspacePath
          )
        }
      : undefined

    const getDescription = useAiDescriptions
      ? async (chunk: RawChunk, embedText: string): Promise<string | undefined> => {
          const desc = await descriptionCache.getOrGenerate(
            chunk,
            embedText,
            preprocessOpts.descriptionModel,
            workspacePath
          )
          // Track cache stats for indexing state when available
          if (desc && state) {
            const key = descriptionCache.makeKey(chunk.filePath, chunk.symbolName, chunk.body)
            const cached = descriptionCache.get(key)
            if (cached === desc) {
              state.descriptionsCached++
            } else {
              state.descriptionsGenerated++
            }
          }
          return desc
        }
      : async (chunk: RawChunk, _embedText: string): Promise<string | undefined> => {
          return generateHeuristicDescription(chunk)
        }

    return { getDescription, getBatchDescriptions }
  }

  /**
   * Select k diverse cluster centers using maximin initialization.
   * Picks entries that maximize minimum distance from all existing centers.
   */
  private selectClusterCenters(entries: { embedding: number[] }[], k: number): number[] {
    const centers: number[] = [0] // start with first entry
    while (centers.length < Math.min(k, entries.length)) {
      let bestIdx = -1
      let bestMinDist = -1
      for (let i = 0; i < entries.length; i++) {
        if (centers.includes(i)) continue
        let minDist = Infinity
        for (const ci of centers) {
          const sim = cosineSimilarity(entries[i].embedding, entries[ci].embedding)
          const dist = 1 - sim
          if (dist < minDist) minDist = dist
        }
        if (minDist > bestMinDist) {
          bestMinDist = minDist
          bestIdx = i
        }
      }
      if (bestIdx === -1) break
      centers.push(bestIdx)
    }
    return centers
  }

  /**
   * Assign each entry to the nearest cluster center by cosine similarity.
   * Returns cluster objects with representative and member lists.
   */
  private assignClustersToMembers(
    entries: {
      embedding: number[]
      chunk: { metadata: { filePath: string; symbolName: string } }
    }[],
    centers: number[]
  ): {
    clusterId: number
    representative: { filePath: string; symbolName: string }
    members: { filePath: string; symbolName: string; similarity: number }[]
  }[] {
    const clusters = centers.map((ci, idx) => ({
      clusterId: idx,
      representative: {
        filePath: entries[ci].chunk.metadata.filePath,
        symbolName: entries[ci].chunk.metadata.symbolName
      },
      members: [] as { filePath: string; symbolName: string; similarity: number }[]
    }))

    for (let i = 0; i < entries.length; i++) {
      if (centers.includes(i)) continue
      let bestCluster = 0
      let bestSim = -1
      for (let c = 0; c < centers.length; c++) {
        const sim = cosineSimilarity(entries[i].embedding, entries[centers[c]].embedding)
        if (sim > bestSim) {
          bestSim = sim
          bestCluster = c
        }
      }
      clusters[bestCluster].members.push({
        filePath: entries[i].chunk.metadata.filePath,
        symbolName: entries[i].chunk.metadata.symbolName,
        similarity: Math.round(bestSim * 1000) / 1000
      })
    }

    return clusters
  }

  /**
   * Initialize the embedding model via the oMLX server (the only backend).
   * Returns the embed function to use for batch embedding. Rejects if oMLX
   * is not running or no embedding model is loaded.
   */
  private async initializeEmbeddingModel(): Promise<(texts: string[]) => Promise<number[][]>> {
    if (!localEmbeddingProvider.isReady) {
      memoryCheckpoint('EMBEDDING_OMLX_INIT_START')
      log.info('[VectorSearch] Initializing oMLX embedding provider...')
      await localEmbeddingProvider.initialize()
      memoryCheckpoint('EMBEDDING_OMLX_INIT_DONE')
    } else {
      memoryCheckpoint('EMBEDDING_OMLX_ALREADY_READY')
    }

    return (texts: string[]) => localEmbeddingProvider.embed(texts)
  }

  /**
   * Resume from a checkpoint: load previously-embedded chunks from DB
   * into the in-memory collection, returning the offset to continue from.
   */
  private resumeFromCheckpoint(
    workspaceId: string,
    processedChunks: ProcessedChunk[],
    collection: InMemoryCollection
  ): number {
    const checkpointOffset = this.getCheckpointOffset(workspaceId)
    if (checkpointOffset <= 0 || checkpointOffset >= processedChunks.length) {
      return 0
    }

    log.info(
      `[VectorSearch] Resuming from checkpoint offset ${checkpointOffset}/${processedChunks.length}`
    )
    memoryCheckpoint('RESUME_FROM_CHECKPOINT', {
      offset: checkpointOffset,
      total: processedChunks.length
    })

    const existingEmbeddings = chunkEmbeddingRepository.loadAllForWorkspace(workspaceId)
    const embeddingMap = new Map<string, number[]>()
    for (const entry of existingEmbeddings) {
      embeddingMap.set(entry.chunkId, entry.embedding)
    }

    for (let i = 0; i < checkpointOffset && i < processedChunks.length; i++) {
      const chunk = processedChunks[i]
      const embedding = embeddingMap.get(chunk.id)
      if (embedding) {
        collection.upsert([chunk.id], [embedding], [chunk])
      }
    }

    return checkpointOffset
  }

  /**
   * Core batch embedding loop with pause/cancel polling and periodic
   * checkpointing. Returns 'completed', 'cancelled', or 'error'.
   */
  private async embedBatchLoop(
    workspaceId: string,
    processedChunks: ProcessedChunk[],
    startOffset: number,
    collection: InMemoryCollection,
    state: IndexingState,
    preprocessOpts: PreprocessingOptions,
    fileMtimes: Map<string, number>,
    embedFn: (texts: string[]) => Promise<number[][]>
  ): Promise<'completed' | 'cancelled' | 'error'> {
    const totalBatches = Math.ceil((processedChunks.length - startOffset) / EMBEDDING_BATCH_SIZE)
    let batchesSinceCheckpoint = 0

    for (let i = startOffset; i < processedChunks.length; i += EMBEDDING_BATCH_SIZE) {
      if (preprocessOpts.cancelled) break

      while (preprocessOpts.paused && !preprocessOpts.cancelled) {
        state.status = 'paused'
        this.emitProgress(workspaceId)
        await new Promise((resolve) => setTimeout(resolve, 500))
      }
      if (preprocessOpts.cancelled) break

      state.status = 'indexing-chunks'
      const batchNum = Math.floor((i - startOffset) / EMBEDDING_BATCH_SIZE) + 1
      const batch = processedChunks.slice(i, i + EMBEDDING_BATCH_SIZE)
      const texts = batch.map((c) => c.embedText)

      const isLogBatch = batchNum === 1 || batchNum % 10 === 0 || batchNum === totalBatches
      if (isLogBatch) {
        memoryCheckpoint(`EMBED_BATCH_${batchNum}/${totalBatches}`, {
          offset: i,
          batchTextsChars: texts.reduce((s, t) => s + t.length, 0)
        })
      }

      try {
        const embeddings = await embedFn(texts)
        const ids = batch.map((c) => c.id)
        collection.upsert(ids, embeddings, batch)

        state.processedChunks = Math.min(i + EMBEDDING_BATCH_SIZE, processedChunks.length)
        state.currentFile = batch[batch.length - 1].metadata.filePath
        this.emitProgress(workspaceId)

        batchesSinceCheckpoint++
        if (batchesSinceCheckpoint >= CHECKPOINT_INTERVAL_BATCHES) {
          const embeddedUpTo = Math.min(i + EMBEDDING_BATCH_SIZE, processedChunks.length)
          try {
            this.checkpointToDb(
              workspaceId,
              processedChunks,
              embeddedUpTo,
              fileMtimes,
              getEmbeddingModelName() ?? 'unknown'
            )
            memoryCheckpoint('CHECKPOINT_SAVED', {
              embeddedUpTo,
              total: processedChunks.length
            })
          } catch (checkpointError) {
            log.warn('[VectorSearch] Checkpoint save failed:', checkpointError)
          }
          batchesSinceCheckpoint = 0
        }
      } catch (error) {
        log.error(`[VectorSearch] Embedding batch failed at offset ${i}:`, error)
        memoryCheckpoint('EMBED_BATCH_ERROR', {
          offset: i,
          error: (error as Error).message
        })

        try {
          const embeddedUpTo = Math.max(i, startOffset)
          if (embeddedUpTo > startOffset) {
            this.checkpointToDb(
              workspaceId,
              processedChunks,
              embeddedUpTo,
              fileMtimes,
              getEmbeddingModelName() ?? 'unknown'
            )
            log.info(`[VectorSearch] Error checkpoint saved at offset ${embeddedUpTo}`)
          }
        } catch {
          /* Ignore checkpoint errors during error handling */
        }

        state.status = 'error'
        state.error = (error as Error).message
        this.emitProgress(workspaceId)
        this.updateIndexingStateDb(workspaceId, 'error', (error as Error).message)
        return 'error'
      }
    }

    return preprocessOpts.cancelled ? 'cancelled' : 'completed'
  }

  private emitProgress(workspaceId: string): void {
    const state = this.indexingStates.get(workspaceId)
    if (!state) return

    // Compute ETA during embedding phase
    if (
      (state.status === 'indexing-chunks' || state.status === 'embedding') &&
      state.totalChunks > 0 &&
      state.processedChunks > 0
    ) {
      const startTime = this.embeddingStartTimes.get(workspaceId)
      if (startTime) {
        const elapsed = Date.now() - startTime
        const rate = state.processedChunks / elapsed // chunks per ms
        const remaining = state.totalChunks - state.processedChunks
        const etaMs = remaining / rate
        state.estimatedRemaining = formatEta(etaMs)
      }
    } else if (state.status === 'preprocessing') {
      // Compute ETA for the AI-description sub-phase here (rather than in the
      // renderer) so the panel stays a pure read of state.estimatedRemaining —
      // the renderer's lint rules forbid Date.now()/ref-writes during render.
      let startTime = this.descriptionStartTimes.get(workspaceId)
      if (!startTime) {
        startTime = Date.now()
        this.descriptionStartTimes.set(workspaceId, startTime)
      }
      if (state.descriptionsTotal > 0 && state.descriptionsProcessed > 0) {
        const elapsed = Date.now() - startTime
        const rate = state.descriptionsProcessed / elapsed // descriptions per ms
        const remaining = state.descriptionsTotal - state.descriptionsProcessed
        state.estimatedRemaining = rate > 0 ? formatEta(remaining / rate) : undefined
      } else {
        state.estimatedRemaining = undefined
      }
    } else {
      // Reset the description-phase start once we leave preprocessing.
      this.descriptionStartTimes.delete(workspaceId)
    }

    // Throttle high-frequency progress (preprocessing/embedding fires once per
    // file/batch) to at most ~1 emit / EMIT_THROTTLE_MS. This caps renderer
    // update frequency regardless of repo size — without this, an emit storm
    // drives setState faster than React can commit and trips the
    // "Maximum update depth exceeded" guard. Status transitions and terminal
    // states always emit immediately so no important update is dropped.
    const now = Date.now()
    const statusChanged = state.status !== this.lastEmitStatus.get(workspaceId)
    const isTerminal =
      state.status === 'complete' ||
      state.status === 'error' ||
      state.status === 'paused' ||
      state.status === 'idle'
    const lastAt = this.lastEmitAt.get(workspaceId) ?? 0

    if (statusChanged || isTerminal || now - lastAt >= VectorSearchService.EMIT_THROTTLE_MS) {
      this.flushEmit(workspaceId, state, now)
      // Reset throttle bookkeeping once indexing settles so the next run is clean.
      if (isTerminal) {
        this.lastEmitAt.delete(workspaceId)
        this.lastEmitStatus.delete(workspaceId)
      }
      return
    }

    // Otherwise schedule a single trailing-edge emit so the latest mutated
    // state in this throttle window is not lost.
    if (!this.pendingEmit.has(workspaceId)) {
      const delay = VectorSearchService.EMIT_THROTTLE_MS - (now - lastAt)
      const timer = setTimeout(() => {
        this.pendingEmit.delete(workspaceId)
        const latest = this.indexingStates.get(workspaceId)
        if (latest) this.flushEmit(workspaceId, latest, Date.now())
      }, delay)
      this.pendingEmit.set(workspaceId, timer)
    }
  }

  /** Perform the actual progress emit and record throttle bookkeeping. */
  private flushEmit(workspaceId: string, state: IndexingState, now: number): void {
    const pending = this.pendingEmit.get(workspaceId)
    if (pending) {
      clearTimeout(pending)
      this.pendingEmit.delete(workspaceId)
    }
    this.lastEmitAt.set(workspaceId, now)
    this.lastEmitStatus.set(workspaceId, state.status)
    this.emit('progress', state)
  }

  /**
   * Update the persistent indexing_state table in SQLite.
   */
  private updateIndexingStateDb(workspaceId: string, status: string, error?: string): void {
    try {
      const db = getDatabase()
      db.prepare(
        `
        INSERT OR REPLACE INTO indexing_state (workspace_id, status, last_error, updated_at)
        VALUES (?, ?, ?, datetime('now'))
      `
      ).run(workspaceId, status, error ?? null)
    } catch (e) {
      log.warn('[VectorSearch] Failed to update indexing_state:', e)
    }
  }
}

export const vectorSearchService = new VectorSearchService()

/**
 * LocalEmbeddingProvider — facade that routes embedding operations to the
 * active local backend (oMLX or Ollama).
 *
 * Same public surface as OmlxEmbeddingProvider:
 *   `isReady`, `activeModelName`, `initialize()`, `embed()`, `dispose()`,
 *   `ensureEmbeddingReady()`, `reinitialize()`, `configureForWorkspace()`
 *   Events: `modelReady`, `modelError`
 *
 * NOTE: This is a global singleton.  If two workspaces use different
 * backends, the last-configured workspace wins.  This mirrors the
 * existing oMLX baseUrl behavior and is acceptable for single-active-
 * workspace usage.
 *
 * The backend is configured per-workspace via `settings.localLlmBackend`
 * ('omlx' | 'ollama'). When oMLX, delegates everything to the existing
 * omlxEmbeddingProvider singleton. When Ollama, uses ollamaManager.embed()
 * with a user-selected embedding model.
 *
 * Windows support: Ollama is the only embedding backend available on Windows
 * (oMLX requires Apple Silicon). This facade makes the switch transparent to
 * consumers (vector-search, memory-retrieval).
 */

import { EventEmitter } from 'node:events'
import log from 'electron-log/main'
import { omlxEmbeddingProvider } from './omlx-embedding.service'
import { ollamaManager } from './ollama-manager.service'
import { workspaceRepository } from '../db/repositories'
import { OLLAMA_DEFAULT_PORT } from '../../shared/constants'
import type { LocalLLMBackend } from '../../shared/types'

const embLog = log.scope('LocalEmbedding')

class LocalEmbeddingProvider extends EventEmitter {
  private backend: LocalLLMBackend = 'omlx'
  private ollamaModel = ''
  private ollamaBaseUrl = 'http://127.0.0.1:11434'
  private _ollamaReady = false

  constructor() {
    super()
    // Forward oMLX-side events through the facade so consumers (embedding.ipc,
    // memory-engine) that listen on localEmbeddingProvider hear them regardless
    // of which backend is active.  Gated on `this.backend` to prevent
    // cross-backend noise (e.g. oMLX init noise while Ollama is selected).
    omlxEmbeddingProvider.on('modelReady', () => {
      if (this.backend === 'omlx') this.emit('modelReady')
    })
    omlxEmbeddingProvider.on('modelError', (e: string) => {
      if (this.backend === 'omlx') this.emit('modelError', e)
    })
  }

  // ── Getters ──

  get isReady(): boolean {
    return this.backend === 'omlx'
      ? omlxEmbeddingProvider.isReady
      : this._ollamaReady
  }

  get activeModelName(): string {
    return this.backend === 'omlx'
      ? omlxEmbeddingProvider.activeModelName
      : this.ollamaModel
  }

  // ── Configuration ──

  /**
   * Switch the active embedding backend. Called when workspace settings change.
   * Does NOT auto-initialize — callers should follow with `initialize()`.
   */
  setBackend(backend: LocalLLMBackend): void {
    if (backend === this.backend) return
    embLog.info(`[setBackend] Switching embedding backend: ${this.backend} → ${backend}`)
    this.backend = backend
  }

  /**
   * Set the Ollama embedding model name (e.g. 'bge-m3', 'nomic-embed-text').
   */
  setOllamaEmbeddingModel(model: string): void {
    if (model && model !== this.ollamaModel) {
      embLog.info(`[setOllamaModel] Embedding model changed: ${this.ollamaModel || '(none)'} → ${model}`)
      this.ollamaModel = model
      // Mark not-ready so next call triggers re-initialization
      this._ollamaReady = false
    }
  }

  /**
   * Set the Ollama base URL (defaults to http://127.0.0.1:11434).
   */
  setOllamaBaseUrl(baseUrl: string): void {
    this.ollamaBaseUrl = baseUrl || 'http://127.0.0.1:11434'
  }

  /**
   * Read workspace settings and configure backend + Ollama model/URL.
   * Called before embedding operations to align the facade with the
   * active workspace's persisted preferences.  The facade is a global
   * singleton, so the last-configured workspace wins — this mirrors
   * the existing oMLX baseUrl pattern and is acceptable for single-
   * active-workspace usage.
   */
  configureForWorkspace(workspaceId: string): void {
    try {
      const settings = workspaceRepository.getSettings(workspaceId)
      const backend = (settings?.localLlmBackend as LocalLLMBackend) ?? 'omlx'
      this.setBackend(backend)

      if (backend === 'ollama') {
        const host = (settings?.localHost as string) ?? '127.0.0.1'
        const port = (settings?.localPort as number) ?? OLLAMA_DEFAULT_PORT
        this.setOllamaBaseUrl(`http://${host}:${port}`)
        const embModel = (settings?.ollamaEmbeddingModel as string) ?? ''
        if (embModel) this.setOllamaEmbeddingModel(embModel)
      }
    } catch (err) {
      embLog.warn('[configureForWorkspace] Failed to read workspace settings:', err)
    }
  }

  // ── Core interface (matches OmlxEmbeddingProvider) ──

  async initialize(baseUrl?: string, apiKey?: string): Promise<void> {
    if (this.backend === 'omlx') {
      return omlxEmbeddingProvider.initialize(baseUrl, apiKey)
    }
    // Ollama: apply baseUrl if provided (EMBEDDING_INITIALIZE passes the
    // workspace-resolved URL), then verify server + model availability.
    if (baseUrl) this.setOllamaBaseUrl(baseUrl)
    await this._initOllama()
  }

  async embed(texts: string[]): Promise<number[][]> {
    if (this.backend === 'omlx') {
      return omlxEmbeddingProvider.embed(texts)
    }
    return this._embedOllama(texts)
  }

  async ensureEmbeddingReady(baseUrl?: string, apiKey?: string): Promise<boolean> {
    if (this.backend === 'omlx') {
      return omlxEmbeddingProvider.ensureEmbeddingReady(baseUrl, apiKey)
    }
    try {
      await this._initOllama()
      return this._ollamaReady
    } catch {
      return false
    }
  }

  async reinitialize(): Promise<void> {
    if (this.backend === 'omlx') {
      return omlxEmbeddingProvider.reinitialize()
    }
    this._ollamaReady = false
    await this._initOllama()
  }

  dispose(): void {
    // Always dispose oMLX state (prevents leak when switching away from oMLX)
    omlxEmbeddingProvider.dispose()
    this._ollamaReady = false
    this.ollamaModel = ''
  }

  // ── Ollama internals ──

  private async _initOllama(): Promise<void> {
    if (this._ollamaReady) return

    if (!this.ollamaModel) {
      const msg = 'No Ollama embedding model configured. Select one in Model Configuration → Local Models.'
      embLog.warn(`[initOllama] ${msg}`)
      this.emit('modelError', msg)
      throw new Error(msg)
    }

    try {
      const status = await ollamaManager.checkStatus(this.ollamaBaseUrl)
      if (!status.running) {
        const msg = 'Ollama is not running. Start Ollama to enable embeddings.'
        embLog.warn(`[initOllama] ${msg}`)
        this.emit('modelError', msg)
        throw new Error(msg)
      }

      // Check if model is available
      const modelAvailable = status.models.some((m) =>
        m === this.ollamaModel || m.startsWith(`${this.ollamaModel}:`)
      )
      if (!modelAvailable) {
        const msg = `Embedding model '${this.ollamaModel}' not found in Ollama. Pull it with: ollama pull ${this.ollamaModel}`
        embLog.warn(`[initOllama] ${msg}`)
        this.emit('modelError', msg)
        throw new Error(msg)
      }

      // Test a small embed to confirm the model works
      await ollamaManager.embed(this.ollamaModel, ['test'], this.ollamaBaseUrl)

      this._ollamaReady = true
      embLog.info(`[initOllama] Ollama embedding ready: model=${this.ollamaModel}`)
      this.emit('modelReady')
    } catch (err) {
      this._ollamaReady = false
      const msg = err instanceof Error ? err.message : String(err)
      if (!msg.includes('not running') && !msg.includes('not found')) {
        embLog.error(`[initOllama] Initialization failed: ${msg}`)
        this.emit('modelError', msg)
      }
      throw err
    }
  }

  private async _embedOllama(texts: string[]): Promise<number[][]> {
    if (!this._ollamaReady) {
      await this._initOllama()
    }

    try {
      return await ollamaManager.embed(this.ollamaModel, texts, this.ollamaBaseUrl)
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err)
      // Detect connection loss
      if (msg.includes('fetch failed') || msg.includes('ECONNREFUSED') || msg.includes('TimeoutError')) {
        this._ollamaReady = false
        this.emit('modelError', 'Ollama connection lost. Will attempt to reconnect on next use.')
      }
      throw err
    }
  }
}

/** Singleton facade — import this instead of omlxEmbeddingProvider directly. */
export const localEmbeddingProvider = new LocalEmbeddingProvider()

import { EventEmitter } from 'node:events'
import log from 'electron-log/main'
import { omlxManager } from './omlx-manager.service'
import { OMLX_EMBEDDING } from '../../shared/constants'

/** Shape of an OpenAI-compatible /v1/embeddings response item. */
interface EmbeddingItem {
  index: number
  embedding: number[]
}

/**
 * Embedding provider backed by the user's local **oMLX** server.
 *
 * oMLX exposes an OpenAI-compatible `POST /v1/embeddings` endpoint, so the
 * `embed()` method body is nearly identical to the old llamafile provider.
 * The key difference: oMLX is user-managed (no auto-download, no child
 * process). The user must have oMLX installed and running with a compatible
 * embedding model loaded.
 *
 * Same public surface as the old provider (`initialize` / `isReady` / `embed` /
 * `dispose`) and the same two events, so `vector-search.service.ts` and the
 * embedding IPC layer consume it unchanged.
 *
 * Events:
 * - `modelReady`  — oMLX is reachable + an embedding model is loaded
 * - `modelError`  — `string` error message (connection/model failure)
 */
class OmlxEmbeddingProvider extends EventEmitter {
  private _isReady = false
  private baseUrl = ''
  private modelName = ''
  private apiKey: string | undefined
  private initPromise: Promise<void> | null = null

  get isReady(): boolean {
    return this._isReady
  }

  /** The loaded embedding model's name — used as provenance for index invalidation. */
  get activeModelName(): string {
    return this.modelName
  }

  /** Ensure oMLX is running and an embedding model is loaded. */
  async initialize(baseUrl?: string, apiKey?: string): Promise<void> {
    if (this._isReady) return
    if (this.initPromise) return this.initPromise
    this.initPromise = this._doInit(baseUrl, apiKey)
    return this.initPromise
  }

  private async _doInit(baseUrl?: string, apiKey?: string): Promise<void> {
    try {
      if (apiKey !== undefined) this.apiKey = apiKey
      const url = baseUrl ?? (this.baseUrl || 'http://127.0.0.1:8000')

      // 1. Check oMLX status (reuse existing omlxManager)
      const status = await omlxManager.checkStatus(url, apiKey)
      if (!status.running) {
        throw new Error('oMLX server is not running. Please start oMLX first.')
      }

      // 2. Find a loaded embedding model
      const embeddingModel = status.allModels?.find(
        (m) => m.loaded && m.modelType === 'embedding'
      )
      if (!embeddingModel) {
        throw new Error(
          'No embedding model loaded in oMLX. Please download and load an embedding model ' +
            `(recommended: ${OMLX_EMBEDDING.recommendedModel.id}) from the oMLX admin dashboard.`
        )
      }

      this.baseUrl = url
      this.modelName = embeddingModel.id
      this._isReady = true
      this.initPromise = null
      this.emit('modelReady')
      log.info(`[OmlxEmbedding] Ready — model: ${this.modelName} at ${this.baseUrl}`)
    } catch (error) {
      const message = (error as Error).message
      log.error(`[OmlxEmbedding] Init failed: ${message}`)
      this._isReady = false
      this.initPromise = null
      this.emit('modelError', message)
      throw error
    }
  }

  /**
   * Embed a batch of texts via POST /v1/embeddings.
   *
   * Mirrors the prior safety net: if a batch fails and contains more than
   * one text, split it in half and retry each sub-batch independently before
   * giving up.
   */
  async embed(texts: string[]): Promise<number[][]> {
    // Auto-reinitialize if connection was previously lost
    if (!this._isReady && this.baseUrl) {
      log.info('[OmlxEmbedding] Attempting automatic reconnection...')
      try {
        await this.initialize()
      } catch {
        // Will throw below from the !_isReady check
      }
    }

    if (!this._isReady || !this.baseUrl) {
      throw new Error('oMLX embedding not ready — call initialize() first')
    }
    if (texts.length === 0) return []

    // Defensively cap each input to avoid exceeding model context
    const { maxInputChars, requestTimeoutMs } = OMLX_EMBEDDING.server
    const input = texts.map((t) => (t.length > maxInputChars ? t.slice(0, maxInputChars) : t))

    const headers: Record<string, string> = { 'Content-Type': 'application/json' }
    if (this.apiKey) headers['Authorization'] = `Bearer ${this.apiKey}`

    try {
      const res = await fetch(`${this.baseUrl}/v1/embeddings`, {
        method: 'POST',
        headers,
        body: JSON.stringify({ input, model: this.modelName }),
        signal: AbortSignal.timeout(requestTimeoutMs)
      })
      if (!res.ok) {
        const detail = await res.text().catch(() => '')
        throw new Error(`/v1/embeddings ${res.status} ${res.statusText} ${detail}`.trim())
      }
      const json = (await res.json()) as { data?: EmbeddingItem[] }
      const data = json.data ?? []
      // Order by `index` so output aligns with the input order regardless of
      // server-side reordering.
      const ordered = [...data].sort((a, b) => a.index - b.index)
      const result = ordered.map((d) => d.embedding)

      // Guard against a 200 with a short/empty `data` array: vector-search zips
      // ids[i] ↔ embeddings[i] by index, so a count mismatch (or a non-numeric
      // vector) would silently corrupt the index.
      if (
        result.length !== texts.length ||
        result.some((e) => !Array.isArray(e) || e.length === 0 || typeof e[0] !== 'number')
      ) {
        throw new Error(
          `/v1/embeddings returned ${result.length} valid embeddings for ${texts.length} inputs`
        )
      }
      return result
    } catch (error) {
      // Batch-halving retry (same safety net as old provider)
      if (texts.length > 1) {
        log.warn(
          `[OmlxEmbedding] Embed failed for batch of ${texts.length} — splitting and retrying`
        )
        const mid = Math.ceil(texts.length / 2)
        const [first, second] = await Promise.all([
          this.embed(texts.slice(0, mid)),
          this.embed(texts.slice(mid))
        ])
        return [...first, ...second]
      }
      // Detect connection loss — mark not-ready so next call re-initializes
      const msg = (error as Error).message ?? ''
      if (msg.includes('fetch failed') || msg.includes('ECONNREFUSED') || msg.includes('TimeoutError')) {
        log.warn('[OmlxEmbedding] Connection lost — marking not ready for re-initialization')
        this._isReady = false
        this.initPromise = null
        this.emit('modelError', 'oMLX connection lost. Will attempt to reconnect on next use.')
      }
      throw error
    }
  }

  /**
   * Ensure embedding is ready — auto-loads the model if downloaded but not loaded,
   * auto-starts oMLX if installed but not running (macOS only).
   *
   * Called at app startup (delayed, non-fatal) and by the backfill handler.
   * Returns true if the provider is ready to embed.
   */
  async ensureEmbeddingReady(baseUrl?: string, apiKey?: string): Promise<boolean> {
    if (this._isReady) return true

    const url = baseUrl ?? (this.baseUrl || 'http://127.0.0.1:8000')
    if (apiKey !== undefined) this.apiKey = apiKey

    try {
      // 1. Check if oMLX is running
      let status = await omlxManager.checkStatus(url, this.apiKey)

      // 2. If not running, attempt auto-start (macOS)
      if (!status.running) {
        if (process.platform === 'darwin') {
          log.info('[OmlxEmbedding] oMLX not running — attempting auto-start…')
          const started = await omlxManager.startOmlx()
          if (!started) {
            log.info('[OmlxEmbedding] Auto-start failed or oMLX not installed')
            return false
          }
          // Re-check status after start
          status = await omlxManager.checkStatus(url, this.apiKey)
          if (!status.running) return false
        } else {
          return false
        }
      }

      // 3. Find an embedding model
      const embeddingModel = status.allModels?.find(
        (m) => m.modelType === 'embedding'
      )
      if (!embeddingModel) {
        // No embedding model downloaded at all
        return false
      }

      // 4. If downloaded but not loaded, auto-load it
      if (!embeddingModel.loaded) {
        log.info(`[OmlxEmbedding] Model ${embeddingModel.id} downloaded but not loaded — loading…`)
        try {
          await omlxManager.loadModel(embeddingModel.id, url, this.apiKey)
        } catch (loadErr) {
          log.warn(`[OmlxEmbedding] Auto-load failed: ${(loadErr as Error).message}`)
          return false
        }
      }

      // 5. Initialize the provider
      await this.initialize(url, this.apiKey)
      return true
    } catch (err) {
      log.info(`[OmlxEmbedding] ensureEmbeddingReady failed: ${(err as Error).message}`)
      return false
    }
  }

  /** Force a re-check of oMLX status — use after user restarts oMLX. */
  async reinitialize(): Promise<void> {
    this._isReady = false
    this.initPromise = null
    await this.initialize(this.baseUrl || undefined, this.apiKey)
  }

  /** Reset state. No child process to kill — oMLX is user-managed. */
  dispose(): void {
    this._isReady = false
    this.initPromise = null
    this.baseUrl = ''
    this.modelName = ''
    this.apiKey = undefined
    log.info('[OmlxEmbedding] Disposed')
  }
}

export const omlxEmbeddingProvider = new OmlxEmbeddingProvider()

import log from 'electron-log/main'
import type { OmlxModelDetail, OmlxExtendedStatus } from '../../shared/types'

/**
 * Service for checking oMLX server status and listing models.
 * oMLX uses OpenAI-compatible endpoints:
 *   - GET /v1/models → list loaded models
 *   - POST /v1/messages → Anthropic Messages API (used by SDK passthrough)
 *
 * Admin API (available since oMLX ~0.2):
 *   - GET /admin/api/models → list ALL models (downloaded + loaded)
 *   - POST /admin/api/models/{id}/load → load a model into memory
 *   - POST /admin/api/models/{id}/unload → unload a model from memory
 *
 * The admin API may require a Bearer token if the user has configured an API key.
 * We try admin API first and fall back to /v1/models on 401/503 for graceful degradation.
 */
class OmlxManagerService {
  private defaultBaseUrl = 'http://127.0.0.1:8000'

  private resolveBaseUrl(baseUrl?: string): string {
    return baseUrl ?? this.defaultBaseUrl
  }

  /**
   * Login to oMLX admin API and get session cookie for authenticated requests.
   * Returns the Set-Cookie header value, or undefined if login fails.
   */
  private async adminLogin(baseUrl: string, apiKey: string): Promise<string | undefined> {
    try {
      const res = await fetch(`${baseUrl}/admin/api/login`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ api_key: apiKey }),
        signal: AbortSignal.timeout(5000),
        redirect: 'manual' // Don't follow redirects — we need the Set-Cookie
      })
      if (res.ok || res.status === 302) {
        const setCookie = res.headers.get('set-cookie')
        if (setCookie) {
          log.info('[OmlxManager] Admin login successful — session cookie obtained')
          return setCookie.split(';')[0] // e.g. "session=abc123"
        }
      }
      log.warn(`[OmlxManager] Admin login returned ${res.status}`)
    } catch (err) {
      log.warn('[OmlxManager] Admin login failed:', err)
    }
    return undefined
  }

  /**
   * Check oMLX server status — tries admin API first for richer model info,
   * falls back to /v1/models when admin API is unavailable (auth required, older version).
   * Returns OmlxExtendedStatus which extends OllamaStatus with optional allModels[].
   *
   * @param baseUrl — oMLX server URL (default http://127.0.0.1:8000)
   * @param apiKey — optional API key for authenticated oMLX instances
   */
  async checkStatus(baseUrl?: string, apiKey?: string): Promise<OmlxExtendedStatus> {
    const url = this.resolveBaseUrl(baseUrl)
    const status: OmlxExtendedStatus = {
      installed: false,
      running: false,
      models: []
    }

    try {
      // Build auth headers for admin API
      const adminHeaders: Record<string, string> = {}
      if (apiKey) {
        // Try cookie-based session auth first
        const sessionCookie = await this.adminLogin(url, apiKey)
        if (sessionCookie) {
          adminHeaders['Cookie'] = sessionCookie
        }
      }

      // Try admin API — returns ALL models (downloaded + loaded)
      const adminRes = await fetch(`${url}/admin/api/models`, {
        headers: adminHeaders,
        signal: AbortSignal.timeout(5000)
      })

      if (adminRes.ok) {
        status.installed = true
        status.running = true
        const data = (await adminRes.json()) as {
          models?: Array<{
            id: string
            loaded: boolean
            is_loading: boolean
            estimated_size_formatted: string
            pinned: boolean
            is_default: boolean
            model_type: string
          }>
        }
        const allModels = data.models ?? []
        // `models` field = loaded models only (backward compat with OllamaStatus)
        status.models = allModels.filter((m) => m.loaded).map((m) => m.id)
        // `allModels` = full list with loaded/downloading status
        status.allModels = allModels.map(
          (m): OmlxModelDetail => ({
            id: m.id,
            loaded: m.loaded,
            isLoading: m.is_loading,
            estimatedSize: m.estimated_size_formatted,
            pinned: m.pinned,
            isDefault: m.is_default,
            modelType: m.model_type
          })
        )
        log.info(
          `[OmlxManager] Admin API: ${allModels.length} total, ` +
          `types: ${[...new Set(allModels.map((m) => m.model_type))].join(', ')}`
        )
        return status
      }

      // Admin API returned non-OK (401 auth required, 404 old version, etc.)
      // Fall back to /v1/models — but capture diagnostics for the UI
      log.warn(
        `[OmlxManager] Admin API ${adminRes.status} — ` +
        `${adminRes.status === 401 ? 'auth required (missing API key?)' : 'falling back to /v1/models'}`
      )
      status.diagnostics = {
        adminAuthRequired: adminRes.status === 401,
        adminHttpStatus: adminRes.status,
        timedOut: false,
        errorDetail: adminRes.status === 401
          ? (apiKey
            ? 'API key rejected — check it in oMLX admin → Settings'
            : 'API key required — set it below to access model management')
          : undefined
      }
    } catch (err) {
      // Admin API not reachable — detect timeout vs connection refused
      const isTimeout = err instanceof Error && err.name === 'AbortError'
      status.diagnostics = {
        adminAuthRequired: false,
        timedOut: isTimeout,
        errorDetail: isTimeout
          ? 'Admin API timed out — server may be overloaded or unreachable'
          : undefined
      }
    }

    try {
      // Bearer token auth for OpenAI-compatible endpoint
      const v1Headers: Record<string, string> = {}
      if (apiKey) {
        v1Headers['Authorization'] = `Bearer ${apiKey}`
      }

      const res = await fetch(`${url}/v1/models`, {
        headers: v1Headers,
        signal: AbortSignal.timeout(3000)
      })
      // Any HTTP response means the server is reachable
      status.installed = true
      status.running = true
      if (res.ok) {
        const data = (await res.json()) as {
          data?: { id: string }[]
        }
        status.models = (data.data ?? []).map((m) => m.id)

        // Synthesize allModels from /v1/models when admin API was unavailable
        // Use name-based heuristics to infer model type
        const EMBEDDING_PATTERN = /\b(bge|e5[-_]|gte[-_]|ember|embedding|nomic[-_]embed|mxbai[-_]embed|snowflake|modernbert)/i
        status.allModels = status.models.map((id) => ({
          id,
          loaded: true, // /v1/models only returns loaded models
          isLoading: false,
          estimatedSize: '',
          pinned: false,
          isDefault: false,
          modelType: EMBEDDING_PATTERN.test(id) ? 'embedding' : 'llm'
        }))
        log.info(
          `[OmlxManager] /v1/models fallback: ${status.models.length} loaded, ` +
          `synthesized types: ${status.allModels.map((m) => `${m.id}=${m.modelType}`).join(', ')}`
        )
      } else {
        log.warn(
          `[OmlxManager] /v1/models returned ${res.status} — server running but models unavailable`
        )
      }
    } catch (err) {
      // Not running — detect timeout vs connection refused for diagnostics
      const isTimeout = err instanceof Error && err.name === 'AbortError'
      if (isTimeout) {
        status.diagnostics = {
          ...status.diagnostics,
          timedOut: true,
          errorDetail: `Server at ${url} timed out — check network connectivity`
        }
      }
      // Try to detect installation via PATH/app check
      try {
        const { execSync } = await import('node:child_process')
        // Check for oMLX CLI or .app bundle
        const result = execSync(
          'which omlx 2>/dev/null || (test -d "/Applications/oMLX.app" && echo "/Applications/oMLX.app")',
          { encoding: 'utf8', timeout: 3000 }
        ).trim()
        if (result) {
          status.installed = true
        }
      } catch {
        // Not installed
      }
    }

    return status
  }

  /**
   * Load a downloaded model into memory via the admin API.
   * Model loading can take 10-30s for large models, so we use a 60s timeout.
   */
  async loadModel(modelId: string, baseUrl?: string, apiKey?: string): Promise<void> {
    const url = this.resolveBaseUrl(baseUrl)
    log.info(`[OmlxManager] Loading model: ${modelId}`)

    // Authenticate for admin API
    const headers: Record<string, string> = {}
    if (apiKey) {
      const sessionCookie = await this.adminLogin(url, apiKey)
      if (sessionCookie) {
        headers['Cookie'] = sessionCookie
      }
    }

    const res = await fetch(`${url}/admin/api/models/${encodeURIComponent(modelId)}/load`, {
      method: 'POST',
      headers,
      signal: AbortSignal.timeout(60_000)
    })
    if (!res.ok) {
      const text = await res.text().catch(() => '')
      throw new Error(`Failed to load model: ${res.status} ${text}`)
    }
    log.info(`[OmlxManager] Model loaded successfully: ${modelId}`)
  }

  /**
   * Unload a model from memory via the admin API.
   */
  async unloadModel(modelId: string, baseUrl?: string, apiKey?: string): Promise<void> {
    const url = this.resolveBaseUrl(baseUrl)
    log.info(`[OmlxManager] Unloading model: ${modelId}`)

    // Authenticate for admin API
    const headers: Record<string, string> = {}
    if (apiKey) {
      const sessionCookie = await this.adminLogin(url, apiKey)
      if (sessionCookie) {
        headers['Cookie'] = sessionCookie
      }
    }

    const res = await fetch(`${url}/admin/api/models/${encodeURIComponent(modelId)}/unload`, {
      method: 'POST',
      headers,
      signal: AbortSignal.timeout(10_000)
    })
    if (!res.ok) {
      const text = await res.text().catch(() => '')
      throw new Error(`Failed to unload model: ${res.status} ${text}`)
    }
    log.info(`[OmlxManager] Model unloaded successfully: ${modelId}`)
  }

  /**
   * Attempt to start oMLX automatically (macOS only).
   * Returns true if oMLX becomes responsive within ~8 seconds.
   */
  async startOmlx(): Promise<boolean> {
    const { exec } = await import('node:child_process')
    const { promisify } = await import('node:util')
    const execAsync = promisify(exec)

    try {
      await execAsync('open -a oMLX')

      // Wait up to 8 seconds for oMLX to become responsive
      for (let i = 0; i < 16; i++) {
        await new Promise((r) => setTimeout(r, 500))
        try {
          const res = await fetch(`${this.defaultBaseUrl}/v1/models`, {
            signal: AbortSignal.timeout(1000)
          })
          if (res.ok) return true
        } catch {
          // Not ready yet
        }
      }
      return false
    } catch (error) {
      log.warn('[OmlxManager] Failed to start oMLX:', error)
      return false
    }
  }

  /** Get the admin dashboard URL for model management */
  getAdminUrl(baseUrl?: string): string {
    return `${this.resolveBaseUrl(baseUrl)}/admin`
  }
}

export const omlxManager = new OmlxManagerService()

import { EventEmitter } from 'node:events'
import log from 'electron-log/main'
import type { OllamaStatus, PullProgress } from '../../shared/types'

/**
 * Singleton service for managing Ollama — detect installation, pull models
 * with streaming progress, generate embeddings, and health-check.
 *
 * Uses native fetch() (Node 24 built-in) — no extra dependencies.
 *
 * Events:
 * - 'pullProgress': PullProgress — streaming download progress
 * - 'pullComplete': string — model name when pull finishes
 * - 'pullError': string — error message on pull failure
 */
class OllamaManagerService extends EventEmitter {
  private defaultBaseUrl = 'http://127.0.0.1:11434'
  // SVC-13: Per-model abort controllers to prevent concurrent pulls from cancelling the wrong model
  private readonly pullControllers = new Map<string, AbortController>()

  /** Build the base URL from host:port or use provided URL */
  private resolveBaseUrl(baseUrl?: string): string {
    return baseUrl ?? this.defaultBaseUrl
  }

  /** Check if an address is a remote (non-localhost) Ollama */
  isRemote(host: string): boolean {
    return host !== '127.0.0.1' && host !== 'localhost' && host !== '::1'
  }

  /**
   * Check the current status of the Ollama installation.
   * Detects whether Ollama is installed, running, its version, and available models.
   *
   * @param baseUrl - Optional Ollama server URL (e.g. 'http://192.168.1.50:11434')
   */
  async checkStatus(baseUrl?: string): Promise<OllamaStatus> {
    const url = this.resolveBaseUrl(baseUrl)
    const status: OllamaStatus = {
      installed: false,
      running: false,
      models: []
    }

    try {
      // Check if Ollama is running by hitting the version endpoint
      const versionRes = await fetch(`${url}/api/version`, {
        signal: AbortSignal.timeout(3000)
      })
      if (versionRes.ok) {
        const data = (await versionRes.json()) as { version?: string }
        status.installed = true
        status.running = true
        status.version = data.version
      }
    } catch {
      // Ollama is not running or not installed
      // Try to detect installation via PATH check (only for local servers)
      if (!this.isRemote(new URL(url).hostname)) {
        try {
          const { execSync } = await import('node:child_process')
          const result = execSync('which ollama 2>/dev/null || where ollama 2>NUL', {
            encoding: 'utf8',
            timeout: 3000
          }).trim()
          if (result) {
            status.installed = true
          }
        } catch {
          // Not installed
        }
      }
      return status
    }

    // If running, also get the list of available models
    try {
      const tagsRes = await fetch(`${url}/api/tags`, {
        signal: AbortSignal.timeout(5000)
      })
      if (tagsRes.ok) {
        const data = (await tagsRes.json()) as { models?: { name: string }[] }
        status.models = (data.models ?? []).map((m) => m.name)
      }
    } catch (error) {
      log.warn('[OllamaManager] Failed to fetch model tags:', error)
    }

    return status
  }

  /**
   * Pull (download) a model from the Ollama registry.
   * Streams NDJSON progress events and emits 'pullProgress' for each update.
   *
   * @param model - The model tag to pull
   * @param baseUrl - Optional Ollama server URL for remote servers
   */
  async pullModel(model: string, baseUrl?: string): Promise<void> {
    const url = this.resolveBaseUrl(baseUrl)
    const controller = new AbortController()
    this.pullControllers.set(model, controller)

    log.info(`[OllamaManager] Pulling model: ${model} from ${url}`)

    try {
      const res = await fetch(`${url}/api/pull`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name: model, stream: true }),
        signal: controller.signal
      })

      if (!res.ok) {
        const errorText = await res.text()
        throw new Error(`Pull failed (${res.status}): ${errorText}`)
      }

      if (!res.body) {
        throw new Error('No response body for pull stream')
      }

      // Stream NDJSON response
      const reader = res.body.getReader()
      const decoder = new TextDecoder()
      let buffer = ''

      while (true) {
        const { done, value } = await reader.read()
        if (done) break

        buffer += decoder.decode(value, { stream: true })
        const lines = buffer.split('\n')
        // Keep the last incomplete line in the buffer
        buffer = lines.pop() ?? ''

        for (const line of lines) {
          if (!line.trim()) continue
          try {
            const data = JSON.parse(line) as {
              status?: string
              completed?: number
              total?: number
              error?: string
            }

            if (data.error) {
              this.emit('pullError', data.error)
              log.error(`[OllamaManager] Pull error: ${data.error}`)
              return
            }

            const progress: PullProgress = {
              model,
              status: data.status ?? '',
              completed: data.completed ?? 0,
              total: data.total ?? 0,
              percent: data.total ? Math.round(((data.completed ?? 0) / data.total) * 100) : 0
            }
            this.emit('pullProgress', progress)
          } catch {
            // Skip malformed JSON lines
          }
        }
      }

      this.emit('pullComplete', model)
      log.info(`[OllamaManager] Pull complete: ${model}`)
    } catch (error) {
      if ((error as Error).name === 'AbortError') {
        log.info(`[OllamaManager] Pull cancelled: ${model}`)
        this.emit('pullError', 'Pull cancelled')
        return
      }
      const message = (error as Error).message
      log.error(`[OllamaManager] Pull failed: ${message}`)
      this.emit('pullError', message)
      throw error
    } finally {
      this.pullControllers.delete(model)
    }
  }

  /**
   * Cancel an in-progress model pull.
   * @param model - Optional: cancel a specific model pull. If omitted, cancels all.
   */
  cancelPull(model?: string): void {
    if (model) {
      const controller = this.pullControllers.get(model)
      if (controller) {
        controller.abort()
        this.pullControllers.delete(model)
        log.info(`[OllamaManager] Pull cancelled for model: ${model}`)
      }
    } else {
      for (const [m, c] of this.pullControllers) {
        c.abort()
        log.info(`[OllamaManager] Pull cancelled for model: ${m}`)
      }
      this.pullControllers.clear()
    }
  }

  /**
   * Remove a model from Ollama.
   *
   * @param model - The model tag to remove
   * @param baseUrl - Optional Ollama server URL for remote servers
   */
  async removeModel(model: string, baseUrl?: string): Promise<void> {
    const url = this.resolveBaseUrl(baseUrl)
    log.info(`[OllamaManager] Removing model: ${model} from ${url}`)

    // OC-06: Add timeout to prevent indefinite hang (matches embed() pattern)
    const res = await fetch(`${url}/api/delete`, {
      method: 'DELETE',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ name: model }),
      signal: AbortSignal.timeout(30_000)
    })

    if (!res.ok) {
      const errorText = await res.text()
      throw new Error(`Failed to remove model (${res.status}): ${errorText}`)
    }

    log.info(`[OllamaManager] Model removed: ${model}`)
  }

  /**
   * Generate embeddings for a batch of inputs.
   * Ollama supports batch embedding natively.
   *
   * @param model - The embedding model to use
   * @param input - Array of strings to embed
   * @param baseUrl - Optional Ollama server URL for remote servers
   */
  async embed(model: string, input: string[], baseUrl?: string): Promise<number[][]> {
    const url = this.resolveBaseUrl(baseUrl)
    // SVC-14: Add timeout to prevent indefinite hangs if Ollama is unresponsive
    const res = await fetch(`${url}/api/embed`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ model, input }),
      signal: AbortSignal.timeout(30_000) // 30s for embedding operations
    })

    if (!res.ok) {
      const errorText = await res.text()
      throw new Error(`Embed failed (${res.status}): ${errorText}`)
    }

    const data = (await res.json()) as { embeddings: number[][] }
    return data.embeddings
  }

  /**
   * Attempt to start Ollama automatically (platform-aware).
   * Returns true if Ollama becomes responsive within ~8 seconds.
   */
  async startOllama(): Promise<boolean> {
    const { spawn } = await import('node:child_process')
    const { promisify } = await import('node:util')
    const { exec } = await import('node:child_process')
    const execAsync = promisify(exec)

    try {
      if (process.platform === 'darwin') {
        // macOS: open the Ollama app (which starts the server)
        await execAsync('open -a Ollama')
      } else if (process.platform === 'win32') {
        // SVC-17: Use spawn with error handler instead of fire-and-forget exec
        const child = spawn('ollama', ['serve'], {
          detached: true,
          stdio: 'ignore',
          windowsHide: true
        })
        child.on('error', (err) => {
          log.warn('[OllamaManager] Failed to spawn ollama serve (Windows):', err)
        })
        child.unref()
      } else {
        // SVC-17: Use spawn with error handler instead of fire-and-forget exec
        const child = spawn('ollama', ['serve'], {
          detached: true,
          stdio: 'ignore'
        })
        child.on('error', (err) => {
          log.warn('[OllamaManager] Failed to spawn ollama serve (Linux):', err)
        })
        child.unref()
      }

      // Wait up to 8 seconds for Ollama to become responsive
      for (let i = 0; i < 16; i++) {
        await new Promise((r) => setTimeout(r, 500))
        try {
          const res = await fetch(`${this.defaultBaseUrl}/api/version`, {
            signal: AbortSignal.timeout(1000)
          })
          if (res.ok) return true
        } catch {
          // Not ready yet
        }
      }
      return false
    } catch (error) {
      log.warn('[OllamaManager] Failed to start Ollama:', error)
      return false
    }
  }
}

export const ollamaManager = new OllamaManagerService()

import { createHash } from 'node:crypto'
import log from 'electron-log/main'
import { getDatabase } from '../db/index'
import type { RawChunk } from './preprocessing.service'
import { buildEnvWithPath } from './env-utils'
import { modelConfigService } from './model-config.service'

const DESCRIPTION_PROMPT = `You are analyzing source code for a search index.
Write ONE sentence describing what this code does in plain English.
Focus on: what it does, what it returns, when it's used.
Do NOT include the function name or file path.
Keep it under 20 words.

Code:
{code}

One-sentence description:`

const BATCH_DESCRIPTION_PROMPT = `You are analyzing source code for a search index.
For EACH symbol below, write ONE sentence (under 20 words) describing what it does.
Focus on: what it does, what it returns, when it's used.
Do NOT include the function name or file path.
Format: one line per symbol, prefixed with the symbol number.

{symbols}

Descriptions (one per line, format "N: description"):`

/**
 * Service for caching AI-generated code descriptions.
 * Descriptions are keyed by sha256(filePath + symbolName + body) so they
 * are only regenerated when the code actually changes.
 *
 * Uses the main code-atelier.db `chunk_descriptions` table (unified storage).
 */
class DescriptionCacheService {
  /** Active workspace ID for scoping description writes */
  private activeWorkspaceId: string = 'default'

  /**
   * Set the active workspace ID for new description writes.
   */
  setWorkspaceId(workspaceId: string): void {
    this.activeWorkspaceId = workspaceId
  }

  /**
   * Generate a deterministic cache key from the chunk's identity + content.
   */
  makeKey(filePath: string, symbolName: string, body: string): string {
    return createHash('sha256')
      .update(filePath + symbolName + body)
      .digest('hex')
  }

  /**
   * Get a cached description by key. Returns null if not found.
   */
  get(key: string): string | null {
    const db = getDatabase()
    const row = db.prepare('SELECT description FROM chunk_descriptions WHERE key = ?').get(key) as
      | { description: string }
      | undefined
    return row?.description ?? null
  }

  /**
   * Store a description in the cache.
   * @param source — 'ai' for Claude-generated, 'heuristic' for pattern-based
   */
  set(
    key: string,
    description: string,
    model: string,
    filePath: string,
    symbolName: string,
    source: 'ai' | 'heuristic' = 'ai'
  ): void {
    const db = getDatabase()
    db.prepare(
      `INSERT OR REPLACE INTO chunk_descriptions (key, workspace_id, description, model, file_path, symbol_name, source)
       VALUES (?, ?, ?, ?, ?, ?, ?)`
    ).run(key, this.activeWorkspaceId, description, model, filePath, symbolName, source)
  }

  /**
   * Invalidate all cached descriptions for a given file path.
   * Called when a file is modified to force re-generation on next index.
   */
  invalidateFile(filePath: string): number {
    const db = getDatabase()
    const result = db.prepare('DELETE FROM chunk_descriptions WHERE file_path = ?').run(filePath)
    return result.changes
  }

  /**
   * Get a cached description or generate a new one.
   * Returns the description string or undefined if generation fails.
   */
  async getOrGenerate(
    chunk: RawChunk,
    embedText: string,
    model: string,
    workspacePath?: string
  ): Promise<string | undefined> {
    const key = this.makeKey(chunk.filePath, chunk.symbolName, chunk.body)
    const cached = this.get(key)
    if (cached) return cached

    try {
      const description = await this.generateDescription(embedText, model, workspacePath)
      if (description) {
        this.set(key, description, model, chunk.filePath, chunk.symbolName)
        return description
      }
    } catch (error) {
      log.warn(`[DescriptionCache] Failed to generate description for ${chunk.symbolName}:`, error)
    }

    return undefined
  }

  /**
   * Generate a code description using Claude CLI one-shot.
   * Uses the same pattern as specialist execution: `claude -p` for one-shot.
   */
  private async generateDescription(
    code: string,
    model: string,
    workspacePath?: string
  ): Promise<string> {
    const { spawn } = await import('node:child_process')

    const prompt = DESCRIPTION_PROMPT.replace('{code}', code.slice(0, 800))
    const resolvedModel = model || modelConfigService.getModel(workspacePath ?? '.', 'haiku')

    return new Promise<string>((resolve, reject) => {
      const env = buildEnvWithPath()
      const args = ['-p', prompt, '--model', resolvedModel]

      const proc = spawn('claude', args, {
        env,
        stdio: ['pipe', 'pipe', 'pipe'],
        timeout: 30_000
      })

      let stdout = ''
      let stderr = ''

      proc.stdout?.on('data', (data: Buffer) => {
        stdout += data.toString()
      })
      proc.stderr?.on('data', (data: Buffer) => {
        stderr += data.toString()
      })

      proc.on('close', (code) => {
        if (code === 0 && stdout.trim()) {
          resolve(stdout.trim())
        } else {
          reject(new Error(`Description generation failed (code ${code}): ${stderr}`))
        }
      })

      proc.on('error', reject)
    })
  }

  /**
   * Generate descriptions for multiple chunks in a single CLI call.
   * Returns a Map<batchIndex, description>.
   * ~10-20x faster than one call per chunk.
   */
  async generateBatch(
    chunks: Array<{ chunk: RawChunk; embedText: string }>,
    model: string,
    workspacePath?: string
  ): Promise<Map<number, string>> {
    const symbolBlocks = chunks
      .map((c, i) => `### Symbol ${i + 1}: ${c.chunk.symbolName}\n${c.embedText.slice(0, 400)}`)
      .join('\n\n')

    const prompt = BATCH_DESCRIPTION_PROMPT.replace('{symbols}', symbolBlocks)
    const output = await this.generateDescription(prompt, model, workspacePath)

    const results = new Map<number, string>()
    for (const line of output.split('\n')) {
      const match = line.match(/^(\d+):\s*(.+)/)
      if (match) {
        const idx = parseInt(match[1]) - 1
        if (idx >= 0 && idx < chunks.length) {
          results.set(idx, match[2].trim())
        }
      }
    }
    return results
  }

  /**
   * Get or generate descriptions for a batch of chunks.
   * Checks cache first, only generates for uncached chunks.
   * Returns descriptions keyed by original chunk index.
   * Also returns counts of cached vs generated for progress tracking.
   */
  async getOrGenerateBatch(
    chunks: Array<{ chunk: RawChunk; embedText: string }>,
    model: string,
    workspacePath?: string
  ): Promise<{ descriptions: Map<number, string>; cached: number; generated: number }> {
    const descriptions = new Map<number, string>()
    const uncached: Array<{ originalIndex: number; chunk: RawChunk; embedText: string }> = []
    let cached = 0

    // Check cache for each chunk
    for (let i = 0; i < chunks.length; i++) {
      const { chunk } = chunks[i]
      const key = this.makeKey(chunk.filePath, chunk.symbolName, chunk.body)
      const cachedDesc = this.get(key)
      if (cachedDesc) {
        descriptions.set(i, cachedDesc)
        cached++
      } else {
        uncached.push({ originalIndex: i, ...chunks[i] })
      }
    }

    if (uncached.length === 0) return { descriptions, cached, generated: 0 }

    // Batch generate uncached descriptions
    let generated = 0
    try {
      const batchResults = await this.generateBatch(
        uncached.map((u) => ({ chunk: u.chunk, embedText: u.embedText })),
        model,
        workspacePath
      )

      // Cache and map back to original indices
      for (const [batchIdx, desc] of batchResults) {
        const item = uncached[batchIdx]
        const key = this.makeKey(item.chunk.filePath, item.chunk.symbolName, item.chunk.body)
        this.set(key, desc, model, item.chunk.filePath, item.chunk.symbolName, 'ai')
        descriptions.set(item.originalIndex, desc)
        generated++
      }
    } catch (error) {
      log.warn('[DescriptionCache] Batch generation failed:', error)
    }

    return { descriptions, cached, generated }
  }

  /**
   * Get the total count of cached descriptions.
   */
  getCount(): number {
    const db = getDatabase()
    const row = db.prepare('SELECT COUNT(*) as count FROM chunk_descriptions').get() as {
      count: number
    }
    return row.count
  }

  /**
   * Count descriptions by source type for a workspace.
   */
  getCountBySource(workspaceId: string): { ai: number; heuristic: number; total: number } {
    const db = getDatabase()
    const rows = db
      .prepare(
        `SELECT source, COUNT(*) as count FROM chunk_descriptions
         WHERE workspace_id = ? GROUP BY source`
      )
      .all(workspaceId) as Array<{ source: string; count: number }>

    let ai = 0
    let heuristic = 0
    for (const row of rows) {
      if (row.source === 'ai') ai = row.count
      else if (row.source === 'heuristic') heuristic = row.count
    }
    return { ai, heuristic, total: ai + heuristic }
  }

  /**
   * Get all heuristic-only description keys for a workspace.
   * Used by the background AI enrichment phase to selectively upgrade.
   */
  getHeuristicKeys(
    workspaceId: string,
    limit: number = 100
  ): Array<{ key: string; filePath: string; symbolName: string }> {
    const db = getDatabase()
    return db
      .prepare(
        `SELECT key, file_path as filePath, symbol_name as symbolName
         FROM chunk_descriptions
         WHERE workspace_id = ? AND source = 'heuristic'
         LIMIT ?`
      )
      .all(workspaceId, limit) as Array<{
      key: string
      filePath: string
      symbolName: string
    }>
  }

  /**
   * Clean up — no-op since we use the shared main database.
   */
  dispose(): void {
    // No separate connection to close — uses the shared getDatabase()
  }
}

