export function commitTask(
   message: string[],
   files: string[],
   customArgs: string[]
): StringTask<CommitResult> {
   const commands: string[] = [
      '-c',
      'core.abbrev=40',
      'commit',
      ...prefixedArray(message, '-m'),
      ...files,
