    assert.deepEqual(result, [], 'malformed JSON should not crash, returns empty')
  })

  test('combines_multiple_intents_in_one_turn', () => {
    const { detector } = createIntentDetector()
    const planIntent: AgentIntent & { type: 'plan' } = {
      type: 'plan',
      plan: { rawContent: 'plan content', structuredPlan: null, beforePlan: '', afterPlan: '' }
    }
    const controlState: ControlToolState = {
      ...emptyControlState(),
      plan: true,
      planIntent
    }
    const text =
      '```grill-question\n{"questions": [{"id": "q1", "question": "Confirm?", "options": []}]}\n```'

    const result = detector.detectAll(text, controlState, 'plan')
    assert.equal(result.length, 2, 'should have plan + grillQuestion')
    const types = result.map((i) => i.type)
    assert.ok(types.includes('plan'), 'should include plan')
    assert.ok(types.includes('grillQuestion'), 'should include grillQuestion')
  })

  test('detects_multiple_grill_evaluation_blocks', () => {
    const { detector } = createIntentDetector()
    const block1 =
      '```grill-evaluation\n{"score": 5, "scoreLabel": "OK", "feedback": "Decent", "questions": [{"id": "q1", "question": "A?", "options": []}]}\n```'
    const block2 =
      '```grill-evaluation\n{"score": 9, "scoreLabel": "Excellent", "feedback": "Perfect", "questions": [{"id": "q2", "question": "B?", "options": []}]}\n```'
    const text = `First block:\n${block1}\nSecond block:\n${block2}`

    const result = detector.detectAll(text, emptyControlState(), 'plan')
    const evals = result.filter((i) => i.type === 'grillEvaluation')
    assert.equal(evals.length, 2, 'should detect both grill-evaluation blocks')
    const eval1 = (evals[0] as AgentIntent & { type: 'grillEvaluation' }).evaluation
    const eval2 = (evals[1] as AgentIntent & { type: 'grillEvaluation' }).evaluation
    assert.equal(eval1.score, 5)
    assert.equal(eval2.score, 9)
  })
})

import type {
  ConversationMode,
  ControlToolState,
  AgentIntent,
  GrillEvaluation,
  GrillQuestion
} from '../../shared/types'
import { chatAgentLogger } from '../logger'

const log = chatAgentLogger

/** Regex to detect grill-summary blocks emitted by the agent. */
const GRILL_SUMMARY_REGEX = /```grill-summary\n([\s\S]*?)```/

/** Regex to detect grill-question blocks emitted by the agent. */
const GRILL_QUESTION_REGEX = /```grill-question\n([\s\S]*?)```/g

/** Regex to detect grill-evaluation blocks (new structured format with score + questions). */
const GRILL_EVAL_REGEX = /```grill-evaluation\n([\s\S]*?)```/g

/**
 * Stateless intent detector — extracts intents from control tool state.
 *
 * MCP tools are the single source of truth for all action-type intents (plan, askUser).
 * Regex detection for these intents has been eliminated — no dual-path, no races.
 * Grill events remain regex-based (no MCP tool equivalent).
 */
export class IntentDetector {
  /**
   * Detect all intents from the completed response.
   *
   * Returns an array because the agent can produce multiple intents in one turn
   * (e.g., grill questions + a plan). The caller should process them in order.
   */
  detectAll(
    accumulatedText: string,
    controlToolState: ControlToolState,
    _mode: ConversationMode
  ): AgentIntent[] {
    const intents: AgentIntent[] = []

    // ── MCP tool intents (single source of truth for action types) ──

    if (controlToolState.plan && controlToolState.planIntent) {
      intents.push(controlToolState.planIntent)
    }

    if (controlToolState.askUser && controlToolState.askUserIntent) {
      intents.push(controlToolState.askUserIntent)
    }

    // ── Grill events (always regex-based — no MCP tool equivalent) ──

    const grillSummary = this.detectGrillSummary(accumulatedText)
    if (grillSummary) intents.push(grillSummary)

    const grillEvaluations = this.detectGrillEvaluation(accumulatedText)
    intents.push(...grillEvaluations)

    const grillQuestions = this.detectGrillQuestion(accumulatedText)
    if (grillQuestions) intents.push(grillQuestions)

    return intents
  }

  // ── Private detection methods (grill events only) ──

  private detectGrillSummary(accumulatedText: string): AgentIntent | null {
    const match = accumulatedText.match(GRILL_SUMMARY_REGEX)
    if (!match) return null

    try {
      const data = JSON.parse(match[1].trim())
      if (data.summary) {
        log.info('Grill summary detected:', data.summary)
        return {
          type: 'grillComplete',
          summary: data.summary,
          proposedTasks: Array.isArray(data.proposedTasks) ? data.proposedTasks : []
        }
      }
    } catch (error) {
      log.error('Failed to parse grill-summary block:', error)
    }

    return null
  }

  private detectGrillQuestion(accumulatedText: string): AgentIntent | null {
    const matches = [...accumulatedText.matchAll(GRILL_QUESTION_REGEX)]
    if (matches.length === 0) return null

    const allQuestions: GrillQuestion[] = []
    for (const match of matches) {
      try {
        const data = JSON.parse(match[1].trim())
        if (data.questions && Array.isArray(data.questions)) {
          allQuestions.push(
            ...data.questions.map((q: Record<string, unknown>) => ({
              ...q,
              id: q.id ?? `grill-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
              options: Array.isArray(q.options) ? q.options : []
            }))
          )
        }
      } catch (error) {
        log.error('Failed to parse grill-question block:', error)
      }
    }

    if (allQuestions.length === 0) return null

    log.info(`Grill questions detected: ${allQuestions.length} questions`)
    return { type: 'grillQuestion', questions: allQuestions }
  }

  private detectGrillEvaluation(accumulatedText: string): AgentIntent[] {
    const matches = [...accumulatedText.matchAll(GRILL_EVAL_REGEX)]
    if (matches.length === 0) return []

    const intents: AgentIntent[] = []
    for (const match of matches) {
      try {
        const data = JSON.parse(match[1].trim())
        if (typeof data.score === 'number' && Array.isArray(data.questions)) {
          log.info(
            `Grill evaluation detected: score=${data.score}, questions=${data.questions.length}`
          )
          intents.push({
            type: 'grillEvaluation',
            evaluation: {
              trackId: data.trackId ?? undefined,
              score: data.score,
              scoreLabel: data.scoreLabel ?? '',
              feedback: data.feedback ?? '',
              questions: data.questions,
              suggestedNextTrack: data.suggestedNextTrack ?? undefined
            } as GrillEvaluation
          })
        }
      } catch (error) {
        log.error('Failed to parse grill-evaluation block:', error)
      }
    }

    return intents
  }
}

/** Singleton instance */
export const intentDetector = new IntentDetector()

/**
 * Unit tests for IntentRouter — routes AgentIntent values to IPC channels.
 *
 * Pure logic: uses mock BrowserWindow to capture IPC sends.
 */
import assert from 'node:assert/strict'
import { test, describe } from './test-harness'
import { createIntentRouter } from './helpers/agent-factory'
import type { AgentIntent } from '../../../shared/types'

describe('IntentRouter', () => {
  test('plan_intent_logs_but_does_not_send_IPC', () => {
