    router.route('conv-5', {
      type: 'grillEvaluation',
      evaluation: {
        score: 7,
        scoreLabel: 'Good',
        feedback: 'Solid answers',
        questions: [{ id: 'eq1', question: 'Anything else?', options: [] }]
      }
    })

    assert.equal(
      sentMessages.length,
      0,
      'grill intents should not send IPC — handled by dedicated grill system'
    )
  })

  test('does_not_send_IPC_for_response_intent', () => {
    const { router, sentMessages } = createIntentRouter()
    const intent: AgentIntent = { type: 'response', content: 'Hello world' }

    router.route('conv-6', intent)

    assert.equal(sentMessages.length, 0, 'response intent should not send IPC')
  })
})

import type { BrowserWindow } from 'electron'
import { IPC_CHANNELS } from '../../shared/constants'
import type { AgentIntent } from '../../shared/types'
import { eventLoggerService } from './event-logger.service'
import { chatAgentLogger } from '../logger'

const log = chatAgentLogger

/**
 * Routes AgentIntent values to the appropriate IPC channel.
 *
 * This replaces the inline event listeners in ChatStreamService.registerEventForwarders()
 * that previously forwarded 5+ string-based EventEmitter events to the renderer.
 *
 * Each intent type maps to exactly one IPC send — trivially testable without EventEmitter,
 * closures, or shared mutable state.
 */
export class IntentRouter {
  constructor(private mainWindow: BrowserWindow) {}

  /**
   * Route a single agent intent to the appropriate IPC channel.
   */
  route(conversationId: string, intent: AgentIntent): void {
    switch (intent.type) {
      case 'response':
        // Response intents are a no-op here — text is already streamed chunk-by-chunk
        // during the streaming phase. The 'response' type exists for completeness
        // in the intent union but doesn't need routing.
        break

      case 'plan':
        log.info(`[IntentRouter:plan] conversationId=${conversationId}`)
        eventLoggerService.logPlanDetected({
          conversationId,
          detectionPath: intent.plan.structuredPlan ? 'tool' : 'regex',
          structured: !!intent.plan.structuredPlan,
          contentLength: intent.plan.rawContent.length
        })
        // Plan data reaches the renderer through the streaming pipeline (TaskPlanCard);
        // no dedicated IPC channel is needed.
        break

      case 'askUser':
        log.info(
          `[IntentRouter:askUser] conversationId=${conversationId} questions=${intent.questions.length} action=${intent.action ?? 'none'}`
        )
        if (!this.mainWindow.isDestroyed()) {
          try {
            this.mainWindow.webContents.send(IPC_CHANNELS.CHAT_ASK_QUESTION, {
              conversationId,
              questions: intent.questions,
              action: intent.action,
              requestId: intent.requestId
            })
          } catch {
            // Window destroyed between check and send — harmless
          }
        }
        break

      case 'grillQuestion':
      case 'grillComplete':
      case 'grillEvaluation':
        // Legacy chat-integrated grill flow — now handled by the dedicated grill system (grill.ipc.ts).
        // Intent detection still runs for logging but no IPC forwarding is needed.
        break

      case 'error':
        log.error(`[IntentRouter:error] conversationId=${conversationId} message=${intent.message}`)
        // Errors are handled in the streaming phase via chunk emission — no separate IPC channel.
        break
    }
  }
}

import log from 'electron-log/main'
import { eventRepository } from '../db/repositories/event.repository'
import type { EventCategory } from '../db/repositories/event.repository'
import type { QualityGateResult } from './quality-gate-runner.service'

const eventLog = log.scope('EventLogger')

/**
 * Structured event logging service.
 *
 * All agent lifecycle events, quality gates, escalations, budget alerts,
 * and hook actions are logged to the events DB table for analysis and debugging.
 */
class EventLoggerService {
  /** Monotonic sequence counters per session — enables total ordering of events within a session */
  private sequenceCounters = new Map<string, number>()

  /** Get the next monotonic sequence number for a session */
  private nextSequence(sessionId: string): number {
    const current = this.sequenceCounters.get(sessionId) ?? 0
    this.sequenceCounters.set(sessionId, current + 1)
    return current + 1
  }

  private log(
    eventType: string,
    category: EventCategory,
    message: string,
    opts: {
      sessionId?: string
      conversationId?: string
      workspaceId?: string
      data?: Record<string, unknown>
      agentId?: string
      model?: string
    } = {}
  ): void {
    try {
      const sequenceNumber = opts.sessionId ? this.nextSequence(opts.sessionId) : undefined
      eventRepository.create({
        eventType,
        category,
        message,
        sequenceNumber,
        ...opts
      })
    } catch (err) {
      eventLog.error(`Failed to log event [${eventType}]:`, err)
    }
  }

  // ── Session Events ──

  logSessionStarted(opts: {
    sessionId?: string
    conversationId?: string
    workspaceId?: string
    agentId: string
    model?: string
  }): void {
    this.log('session.started', 'session', `Agent ${opts.agentId} session started`, opts)
  }

  logSessionFailed(opts: {
    sessionId?: string
    conversationId?: string
    workspaceId?: string
    agentId: string
    error: string
  }): void {
    this.log('session.failed', 'session', `Agent ${opts.agentId} session failed: ${opts.error}`, {
      ...opts,
      data: { error: opts.error }
    })
  }

  // ── Agent Events ──

  logAgentStarted(opts: {
    conversationId?: string
    workspaceId?: string
    agentId: string
    taskId?: string
    model?: string
    complexityTier?: string
  }): void {
    this.log(
      'agent.started',
      'agent',
      `Specialist ${opts.agentId} started task ${opts.taskId ?? 'unknown'}`,
      {
        ...opts,
        data: { taskId: opts.taskId, complexityTier: opts.complexityTier }
      }
    )
  }

  logAgentCompleted(opts: {
    conversationId?: string
    workspaceId?: string
    agentId: string
    taskId?: string
    tokenUsage?: number
  }): void {
    this.log(
      'agent.completed',
      'agent',
      `Specialist ${opts.agentId} completed task ${opts.taskId ?? 'unknown'}`,
      {
        ...opts,
        data: { taskId: opts.taskId, tokenUsage: opts.tokenUsage }
      }
    )
  }

  logAgentFailed(opts: {
    conversationId?: string
    workspaceId?: string
    agentId: string
    taskId?: string
    error: string
    attempt?: number
  }): void {
    this.log(
      'agent.failed',
      'agent',
      `Specialist ${opts.agentId} failed task ${opts.taskId ?? 'unknown'}: ${opts.error}`,
      { ...opts, data: { taskId: opts.taskId, error: opts.error, attempt: opts.attempt } }
    )
  }

  // ── Task Retry Events ──

  logTaskRetry(opts: {
    conversationId?: string
    agentId: string
    taskId: string
    attempt: number
    maxRetries: number
    escalation?: { fromModel: string; toModel: string }
    reason: string
  }): void {
    this.log(
      'agent.retry',
      'agent',
      `Specialist ${opts.agentId} retrying task ${opts.taskId} (attempt ${opts.attempt}/${opts.maxRetries}): ${opts.reason}`,
      {
        ...opts,
        data: {
          taskId: opts.taskId,
          attempt: opts.attempt,
          maxRetries: opts.maxRetries,
          escalation: opts.escalation,
          reason: opts.reason
        }
      }
    )
  }

  // ── Escalation Events ──

  logModelEscalation(opts: {
    conversationId?: string
    workspaceId?: string
    agentId: string
    taskId: string
    fromModel: string
    toModel: string
    reason: string
    attempt: number
  }): void {
    this.log(
      'escalation.model',
      'escalation',
      `Escalated ${opts.agentId} from ${opts.fromModel} to ${opts.toModel}: ${opts.reason}`,
      {
        ...opts,
        data: {
          taskId: opts.taskId,
          fromModel: opts.fromModel,
          toModel: opts.toModel,
          reason: opts.reason,
          attempt: opts.attempt
        }
      }
    )
  }

  // ── Quality Gate Events ──

  logGateResult(opts: {
    conversationId?: string
    workspaceId?: string
    agentId: string
    taskId: string
    gate: QualityGateResult
  }): void {
    const status = opts.gate.passed ? 'PASSED' : 'FAILED'
    this.log(
      `gate.${opts.gate.type}.${opts.gate.passed ? 'pass' : 'fail'}`,
      'gate',
      `[${status}] ${opts.gate.type}: ${opts.gate.summary}`,
      {
        ...opts,
        data: {
          taskId: opts.taskId,
          gateType: opts.gate.type,
          passed: opts.gate.passed,
          summary: opts.gate.summary
        }
      }
    )
  }

  // ── Abandonment Events ──

  logAbandonmentDetected(opts: {
    conversationId?: string
    workspaceId?: string
    agentId: string
    taskId: string
    pattern: string
    context?: string
  }): void {
    this.log(
      'abandonment.detected',
      'abandonment',
      `Specialist ${opts.agentId} may have abandoned task ${opts.taskId}: "${opts.pattern}"`,
      {
        ...opts,
        data: { taskId: opts.taskId, pattern: opts.pattern, context: opts.context }
      }
    )
  }

  // ── Checkpoint Events ──

  logCheckpointCreated(opts: {
    conversationId: string
    workspaceId?: string
    checkpointId: string
    label: string
  }): void {
    this.log('checkpoint.created', 'checkpoint', `Checkpoint "${opts.label}" created`, {
      ...opts,
      data: { checkpointId: opts.checkpointId, label: opts.label }
    })
  }

  logCheckpointRestored(opts: {
    conversationId: string
    workspaceId?: string
    checkpointId: string
    label: string
  }): void {
    this.log('checkpoint.restored', 'checkpoint', `Restored checkpoint "${opts.label}"`, {
      ...opts,
      data: { checkpointId: opts.checkpointId, label: opts.label }
    })
  }

  // ── Budget Events ──

  logBudgetWarning(opts: {
    conversationId?: string
    workspaceId?: string
    currentCostCents: number
    budgetCents: number
    percentUsed: number
  }): void {
    this.log(
      'budget.warning',
      'budget',
      `Budget ${opts.percentUsed.toFixed(0)}% used ($${(opts.currentCostCents / 100).toFixed(2)} / $${(opts.budgetCents / 100).toFixed(2)})`,
      {
        ...opts,
        data: {
          currentCostCents: opts.currentCostCents,
          budgetCents: opts.budgetCents,
          percentUsed: opts.percentUsed
        }
      }
    )
  }

  logBudgetExceeded(opts: {
    conversationId?: string
    workspaceId?: string
    currentCostCents: number
    budgetCents: number
  }): void {
    this.log(
      'budget.exceeded',
      'budget',
      `Budget exceeded: $${(opts.currentCostCents / 100).toFixed(2)} > $${(opts.budgetCents / 100).toFixed(2)}`,
      {
        ...opts,
        data: {
          currentCostCents: opts.currentCostCents,
          budgetCents: opts.budgetCents
        }
      }
    )
  }

  // ── Agent Events ──

  logPlanDetected(opts: {
    conversationId: string
    workspaceId?: string
    detectionPath: 'tool' | 'regex'
    structured: boolean
    contentLength: number
  }): void {
    this.log(
      'plan.detected',
      'agent',
      `Plan detected via ${opts.detectionPath} (structured=${opts.structured}, ${opts.contentLength} chars)`,
      {
        ...opts,
        agentId: 'specialist',
        data: {
          detectionPath: opts.detectionPath,
          structured: opts.structured,
          contentLength: opts.contentLength
        }
      }
    )
  }

  // ── Tool Call Events ──

  logAgentToolCall(opts: {
    agentId: string
    conversationId?: string
    toolName: string
    toolCallNumber: number
  }): void {
    this.log(
      'agent.tool_call',
      'agent',
      `${opts.agentId} → ${opts.toolName} (call #${opts.toolCallNumber})`,
      {
        conversationId: opts.conversationId,
        agentId: opts.agentId,
        data: {
          toolName: opts.toolName,
          toolCallNumber: opts.toolCallNumber
        }
      }
    )
  }

  // ── Error Events ──

  logAgentTimeout(opts: {
    agentId: string
    conversationId?: string
    elapsedMs: number
    toolCallCount: number
  }): void {
    this.log(
      'agent.timeout',
      'error',
      `${opts.agentId} timed out after ${Math.round(opts.elapsedMs / 1000)}s (${opts.toolCallCount} tool calls)`,
      {
        conversationId: opts.conversationId,
        agentId: opts.agentId,
        data: {
          elapsedMs: opts.elapsedMs,
          toolCallCount: opts.toolCallCount
        }
      }
    )
  }

  logCircuitBreakerTripped(opts: {
    conversationId?: string
    workspaceId?: string
    failures: number
  }): void {
    this.log(
      'error.circuit_breaker',
      'error',
      `Circuit breaker tripped after ${opts.failures} consecutive failures`,
      { ...opts, data: { failures: opts.failures } }
    )
  }

  // ── Merge Events ──

  logMergeRejected(opts: {
    conversationId?: string
    agentId: string
    taskId: string
    reason: string
  }): void {
    this.log(
      'merge.rejected',
      'agent',
      `Merge rejected for ${opts.agentId}/${opts.taskId}: ${opts.reason}`,
      {
        conversationId: opts.conversationId,
        agentId: opts.agentId,
        data: { taskId: opts.taskId, reason: opts.reason }
      }
    )
  }

  // ── Utility ──

  /** Prune events older than N days */
  prune(days: number = 30): number {
    const count = eventRepository.pruneOlderThan(days)
    if (count > 0) {
      eventLog.info(`Pruned ${count} events older than ${days} days`)
    }
    return count
  }
}

export const eventLoggerService = new EventLoggerService()

/**
 * Unit tests for AgentCircuitBreaker — tracks tool call count per interaction,
 * detects gratuitous tool use, and breaks the circuit at configurable limits.
 *
 * Pure logic: no filesystem, no network, no real Electron dependencies.
 */
import assert from 'node:assert/strict'
import { test, describe } from './test-harness'
import { createCircuitBreaker } from './helpers/agent-factory'

/** Helper: pump N tool calls through the breaker */
function pumpToolCalls(
  breaker: ReturnType<typeof createCircuitBreaker>['breaker'],
  n: number,
  opts?: { isBuildMode?: boolean; accumulatedTextLength?: number; conversationId?: string }
): void {
  for (let i = 0; i < n; i++) {
    breaker.onToolUse({
      isBuildMode: opts?.isBuildMode ?? false,
      accumulatedTextLength: opts?.accumulatedTextLength ?? 0,
      conversationId: opts?.conversationId ?? 'conv-test'
    })
  }
}

describe('AgentCircuitBreaker', () => {
  test('starts_with_zero_count_and_not_broken', () => {
    const { breaker } = createCircuitBreaker()
    assert.equal(breaker.count, 0)
    assert.equal(breaker.isBroken, false)
  })

  test('increments_count_on_each_onToolUse', () => {
    const { breaker } = createCircuitBreaker()
    breaker.onToolUse({ isBuildMode: false, accumulatedTextLength: 0, conversationId: 'c1' })
    assert.equal(breaker.count, 1)
    breaker.onToolUse({ isBuildMode: false, accumulatedTextLength: 0, conversationId: 'c1' })
    assert.equal(breaker.count, 2)
    breaker.onToolUse({ isBuildMode: false, accumulatedTextLength: 0, conversationId: 'c1' })
    assert.equal(breaker.count, 3)
  })

  test('returns_not_broken_for_normal_tool_use', () => {
    const { breaker } = createCircuitBreaker()
    const result = breaker.onToolUse({
      isBuildMode: false,
      accumulatedTextLength: 0,
      conversationId: 'c1'
    })
    assert.equal(result.broken, false)
    assert.equal(result.shouldTerminate, false)
  })

  test('detects_gratuitous_tool_use_when_500_chars_accumulated', () => {
    const { breaker } = createCircuitBreaker()
    // First tool call after 500+ chars of accumulated text → gratuitous detection
    const result = breaker.onToolUse({
      isBuildMode: false,
      accumulatedTextLength: 600,
      conversationId: 'c1'
    })
    assert.equal(result.shouldTerminate, true)
    assert.equal(result.broken, false, 'broken should be false for soft stop')
    assert.equal(breaker.isBroken, true, 'circuit should be marked broken internally')
  })

  test('does_not_trigger_gratuitous_on_second_tool_call', () => {
    const { breaker } = createCircuitBreaker()
    // First tool call with low text
    breaker.onToolUse({ isBuildMode: false, accumulatedTextLength: 0, conversationId: 'c1' })
    // Second tool call with high text — should NOT trigger gratuitous
    const result = breaker.onToolUse({
      isBuildMode: false,
      accumulatedTextLength: 600,
      conversationId: 'c1'
    })
    assert.equal(result.shouldTerminate, false)
    assert.equal(result.broken, false)
  })

  test('breaks_circuit_at_plan_mode_limit_100_with_continuable_break', () => {
    const { breaker } = createCircuitBreaker()
    pumpToolCalls(breaker, 99, { isBuildMode: false })
    assert.equal(breaker.isBroken, false)
    // 100th call triggers the break
    const result = breaker.onToolUse({
      isBuildMode: false,
      accumulatedTextLength: 0,
      conversationId: 'c1'
    })
    assert.equal(result.broken, true)
    assert.equal(result.shouldTerminate, true)
    assert.equal(result.isContinuableBreak, true, 'should be a continuable break, not a hard error')
    assert.equal(breaker.isBroken, true)
  })

  test('breaks_circuit_at_build_mode_limit_150_with_continuable_break', () => {
    const { breaker } = createCircuitBreaker()
    pumpToolCalls(breaker, 149, { isBuildMode: true })
    assert.equal(breaker.isBroken, false)
    // 150th call triggers the break
    const result = breaker.onToolUse({
      isBuildMode: true,
      accumulatedTextLength: 0,
      conversationId: 'c1'
    })
    assert.equal(result.broken, true)
    assert.equal(result.shouldTerminate, true)
    assert.equal(result.isContinuableBreak, true, 'should be a continuable break, not a hard error')
    assert.equal(breaker.isBroken, true)
  })

  test('all_circuit_breaks_are_continuable_no_error_chunks', () => {
    // Plan mode break
    const { breaker: planBreaker } = createCircuitBreaker()
    pumpToolCalls(planBreaker, 99, { isBuildMode: false })
    const planResult = planBreaker.onToolUse({
      isBuildMode: false,
      accumulatedTextLength: 0,
      conversationId: 'c1'
    })
    assert.equal(planResult.isContinuableBreak, true)

    // Build mode break
    const { breaker: buildBreaker } = createCircuitBreaker()
    pumpToolCalls(buildBreaker, 149, { isBuildMode: true })
    const buildResult = buildBreaker.onToolUse({
      isBuildMode: true,
      accumulatedTextLength: 0,
      conversationId: 'c1'
    })
    assert.equal(buildResult.isContinuableBreak, true)
  })

  test('reset_clears_count_and_broken_state', () => {
    const { breaker } = createCircuitBreaker()
    pumpToolCalls(breaker, 100, { isBuildMode: false })
    assert.equal(breaker.isBroken, true)
    assert.equal(breaker.count, 100)
    breaker.reset()
    assert.equal(breaker.count, 0)
    assert.equal(breaker.isBroken, false)
  })

  test('does_not_break_at_limit_minus_one', () => {
    // Plan mode: 99 calls should NOT break
    const { breaker: planBreaker } = createCircuitBreaker()
    pumpToolCalls(planBreaker, 99, { isBuildMode: false })
    assert.equal(planBreaker.isBroken, false)
    assert.equal(planBreaker.count, 99)

    // Build mode: 149 calls should NOT break
    const { breaker: buildBreaker } = createCircuitBreaker()
    pumpToolCalls(buildBreaker, 149, { isBuildMode: true })
    assert.equal(buildBreaker.isBroken, false)
    assert.equal(buildBreaker.count, 149)
  })
})

import type { ContextWindowTier } from './context-management'
import { chatAgentLogger } from '../logger'
import { eventLoggerService } from './event-logger.service'

/**
 * Tool call limits — runaway-loop guards, NOT productivity walls.
 *
 * These are intentionally high ceilings (2–3× the old values). A legitimate
 * long task that reaches them will auto-continue via the recovery manager
 * (up to MAX_TURN_CONTINUATIONS), then show a "Continue" button.
 * Only a pathological loop should hit these limits meaningfully.
 *
 * Reference: Neither Claude Code nor OpenCode impose tool-call caps;
 * they rely on auto-compaction + cost ceilings. Our budget guard
 * (AgentExecutorFactory.checkPreFlightBudget → BudgetExceededError)
 * is the real spend ceiling.
 */
const MAX_PLAN_TOOL_CALLS = 100
const MAX_BUILD_TOOL_CALLS = 150

/**
 * S1: Tier-aware limits for local LLMs.
 * Raised proportionally from the old values to serve as runaway guards.
 * With auto-continue (up to 3×), effective ceilings are 3× these values.
 */
const LOCAL_PLAN_LIMITS: Record<ContextWindowTier, number> = {
  small: 50, // was 30
  medium: 75, // was 38
  large: 100 // was 50, now matches Claude MAX_PLAN_TOOL_CALLS
}
const LOCAL_BUILD_LIMITS: Record<ContextWindowTier, number> = {
  small: 60, // was 30
  medium: 100, // was 50
  large: 150 // was 80, now matches Claude MAX_BUILD_TOOL_CALLS
}

/**
 * Result of evaluating a tool use against the circuit breaker.
 * When `broken` is true, the caller should stop the stream.
 */
export interface CircuitBreakerResult {
  /** Whether the circuit was just broken (caller should stop) */
  broken: boolean
  /** Whether the stream should terminate after current tool completes (soft stop) */
  shouldTerminate: boolean
  /** S1: Optional additional context to inject into the conversation (e.g. early warnings) */
  additionalContext?: string
  /**
   * When true, the breaker fired as a continuable condition.
   * The recovery manager should treat this as a max_turns event
   * (save plan state + auto-continue) rather than a hard error.
   * This is the default for all breaker trips — both Claude and local,
   * both plan and build mode.
   */
  isContinuableBreak?: boolean
}

/**
 * Extracts tool call limiting and gratuitous tool detection from ChatAgentService.
 *
 * Responsibilities:
 * - Track tool call count per interaction
 * - Detect gratuitous tool use (first tool after 500+ chars of text)
 * - S1: Tier-aware limits for local LLMs with 60% early warning
 * - Soft warning at 5/8 tool calls in build mode
 * - Hard circuit break at MAX_PLAN/BUILD_TOOL_CALLS
 * - Generate error messages for circuit break
 */
export class AgentCircuitBreaker {
  private readonly log = chatAgentLogger
  private _toolCallCount = 0
  private _circuitBroken = false
  private _earlyWarningEmitted = false

  /**
   * Evaluate a tool use event against the circuit breaker policy.
   * Returns whether the circuit was broken and any error chunk to emit.
   *
   * S1: When `isLocalProvider` and `contextTier` are provided, uses tier-aware
   * limits instead of the flat MAX_PLAN/BUILD_TOOL_CALLS. Emits a 60% early
   * warning nudge to steer the model toward writing its plan/summary.
   */
  onToolUse(opts: {
    isBuildMode: boolean
    accumulatedTextLength: number
    conversationId: string
    /** S1: Whether this is a local LLM provider (enables tier-aware limits) */
    isLocalProvider?: boolean
    /** S1: Context window tier — drives the tool call limit for local LLMs */
    contextTier?: ContextWindowTier
  }): CircuitBreakerResult {
    this._toolCallCount++

    // Gratuitous tool detection — if model already wrote a substantial answer
    // (500+ chars) and is now making its FIRST tool call, it's a post-answer
    // verification pattern. Soft-stop via circuit breaker to prevent further turns.
    if (this._toolCallCount === 1 && opts.accumulatedTextLength >= 500) {
      this.log.warn(
        `[PIPELINE:gratuitous-tool-soft-stop] conversationId=${opts.conversationId} textLen=${opts.accumulatedTextLength} — already answered, stopping after this tool`
      )
      this._circuitBroken = true
      return { broken: false, shouldTerminate: true }
    }

    // Soft warning at 5 tool calls — approaching prompt-stated target
    if (this._toolCallCount === 5 && opts.isBuildMode) {
      this.log.warn(
        `[PIPELINE:tool-limit-warning] conversationId=${opts.conversationId} — 5 tool calls reached, approaching limit`
      )
    }
    // Hard limit warning at 8 — prompt-stated HARD LIMIT exceeded
    if (this._toolCallCount === 8 && opts.isBuildMode) {
      this.log.warn(
        `[PIPELINE:tool-limit-reached] conversationId=${opts.conversationId} — 8 tool calls, prompt hard limit exceeded`
      )
    }

    // S1: Resolve tier-aware limit for local LLMs
    const toolCallLimit = this.resolveToolCallLimit(
      opts.isBuildMode,
      opts.isLocalProvider,
      opts.contextTier
    )

    // S1: 60% early warning for local LLMs — nudge the model to start writing
    // C4: 80% early warning for Claude build mode — prevent hard circuit break
    if (!this._earlyWarningEmitted) {
      const isLocal = !!opts.isLocalProvider
      const earlyWarningPct = isLocal ? 0.6 : 0.8
      const shouldNudge = isLocal || (!isLocal && opts.isBuildMode)

      if (shouldNudge) {
        const earlyWarningThreshold = Math.floor(toolCallLimit * earlyWarningPct)
        if (this._toolCallCount >= earlyWarningThreshold) {
          this._earlyWarningEmitted = true
          this.log.info(
            `[PIPELINE:early-warning] conversationId=${opts.conversationId} ` +
              `provider=${isLocal ? 'local' : 'claude'} ` +
              `count=${this._toolCallCount}/${toolCallLimit} (${Math.round(earlyWarningPct * 100)}% threshold=${earlyWarningThreshold})`
          )
          return {
            broken: false,
            shouldTerminate: false,
            additionalContext: isLocal
              ? `You've used ${this._toolCallCount}/${toolCallLimit} tool calls. ` +
                `Start writing your plan/summary now. ` +
                `Use remaining calls only if absolutely essential.`
              : `You've used ${this._toolCallCount}/${toolCallLimit} tool calls. ` +
                `Start wrapping up your current task. ` +
                `Complete what you're doing and summarize any remaining work.`
          }
        }
      }
    }

    if (this._toolCallCount >= toolCallLimit) {
      this._circuitBroken = true
      this.log.warn(
        `[PIPELINE:circuit-breaker] ${this._toolCallCount} tool calls reached ` +
          `${opts.isBuildMode ? 'build' : 'plan'} limit of ${toolCallLimit} — ` +
          `continuable break (recovery manager will auto-continue)`
      )
      eventLoggerService.logAgentToolCall({
        agentId: 'specialist',
        conversationId: opts.conversationId,
        toolName: '__circuit_breaker__',
        toolCallNumber: this._toolCallCount
      })

      // All breaker trips are continuable — the recovery manager will
      // save progress and auto-continue (up to MAX_TURN_CONTINUATIONS),
      // then show a "Continue" button when exhausted. No hard error.
      return {
        broken: true,
        shouldTerminate: true,
        isContinuableBreak: true
      }
    }

    return { broken: false, shouldTerminate: false }
  }

  /**
   * S1: Resolve the tool call limit based on provider and tier.
   * Local LLMs get tier-aware limits; Claude gets flat limits.
   */
  private resolveToolCallLimit(
    isBuildMode: boolean,
    isLocal?: boolean,
    tier?: ContextWindowTier
  ): number {
    if (isLocal && tier) {
      return isBuildMode ? LOCAL_BUILD_LIMITS[tier] : LOCAL_PLAN_LIMITS[tier]
    }
    return isBuildMode ? MAX_BUILD_TOOL_CALLS : MAX_PLAN_TOOL_CALLS
  }

  /** Log a tool call to event log (for non-control tools) */
  logToolCall(conversationId: string, toolName: string): void {
    eventLoggerService.logAgentToolCall({
      agentId: 'specialist',
      conversationId,
      toolName,
      toolCallNumber: this._toolCallCount
    })
  }

  get isBroken(): boolean {
    return this._circuitBroken
  }

  get count(): number {
    return this._toolCallCount
  }

  /** Reset state for a new interaction */
  reset(): void {
    this._toolCallCount = 0
    this._circuitBroken = false
    this._earlyWarningEmitted = false
  }
}

