    this.recoveryManager.saveCurrentPlanState(conversationId)
  }

  // ── Compaction ────────────────────────────────────────────────────

  private applyCompactionThresholds(settings: Record<string, unknown>): void {
    this.streamProcessor.applyCompactionThresholds(settings)
  }

  /**
   * Resolve OpenCode provider configuration — snapshot-first.
   *
   * Reads provider identity (providerId + modelId) from the conversation's frozen
   * snapshot to prevent config bleed between chats. Infrastructure settings
   * (baseUrl, apiKey) always come from live workspace settings.
   *
   * Falls back to live workspace settings when no snapshot exists (legacy chats).
   */
  private resolveOpenCodeProviderConfig(_llmProvider?: LLMProvider): {
    providerId: string
    modelId: string
    baseUrl: string | undefined
    apiKey: string | undefined
  } {
    if (!this.workspacePath) {
      return {
        providerId: 'anthropic',
        modelId: 'claude-sonnet-4-6',
        baseUrl: undefined,
        apiKey: undefined
      }
    }

    return resolveOpenCodeProviderFromSnapshot(
      this.currentConversationId,
      this.workspacePath,
      this.currentMode !== 'plan'
    )
  }
}

/**
 * CLIExecutor — replaces SDKExecutor for interactive Claude CLI sessions.
 *
 * Spawns `claude` (WITHOUT `-p`) in interactive mode with `--output-format stream-json
 * --input-format stream-json --verbose`. This uses the Claude Max subscription for
 * billing (not the Agent SDK credit pool). The process stays alive for the entire
 * conversation lifetime. User messages are written to stdin as NDJSON lines; NDJSON
 * events are read from stdout and normalized via the same stream-normalizer pipeline.
 *
 * Key design points:
 * - Uses `child_process.spawn('claude', args)` directly — no SDK dependency
 * - Session ID captured from `system/init` event (same NDJSON shape)
 * - Resume via `--resume <sessionId>` CLI flag
 * - Slash commands (/compact, /clear) supported via stdin writes
 * - MCP servers configured via `--mcp-config <path>` (external stdio processes)
 *
 * Introduced for the Agent SDK → CLI migration (June 2026) to avoid
 * Agent SDK credit consumption under the new billing model.
 */

import { spawn, type ChildProcess } from 'node:child_process'
import { writeFileSync, mkdirSync, existsSync, unlinkSync, readdirSync, statSync } from 'node:fs'
import { createHash, randomUUID } from 'node:crypto'
import { app } from 'electron'
import { join } from 'node:path'
import { tmpdir } from 'node:os'
import type { StreamChunk } from './agent-base.service'
import {
  parseNdjsonStream,
  writeNdjsonMessage,
  buildUserMessage
} from './cli-executor/ndjson-parser'
import {
  HeartbeatMonitor,
  TokenAccountant,
  TelemetryRecorder,
  ToolTracker,
  normalizeMessage,
  executorLog
} from './executor-utils/index'
import { buildEnvWithPath } from './env-utils'
import type { StreamState } from './executor-utils/index'

// ── Re-export types for external consumers ──
export type { TelemetryEntry } from './executor-utils/telemetry-recorder'
export type { TokenUsage } from './executor-utils/token-accountant'

/**
 * Terminal reason — why a CLI session stopped.
 * Matches the same values the SDK emits in result.terminal_reason.
 */
export type TerminalReason =
  | 'blocking_limit'
  | 'rapid_refill_breaker'
  | 'prompt_too_long'
  | 'image_error'
  | 'model_error'
  | 'aborted_streaming'
  | 'aborted_tools'
  | 'stop_hook_prevented'
  | 'hook_stopped'
  | 'tool_deferred'
  | 'max_turns'
  | 'completed'

// ── CLI Execute Options ──

export interface CLIExecuteOptions {
  /** User message or prompt to send — string for text, array for content blocks (images) */
  prompt: string | Array<Record<string, unknown>>
  /** System prompt (injected via --system-prompt flag on first launch) */
  systemPrompt: string
  /** Model identifier (e.g. 'claude-sonnet-4-6') */
  model: string
  /** Working directory for the CLI process */
  cwd: string
  /** Permission mode (mapped to --permission-mode flag) */
  permissionMode: 'default' | 'plan' | 'bypassPermissions' | 'acceptEdits' | 'auto' | 'dontAsk'
  /** Tools to allow (passed via --allowedTools) */
  allowedTools?: string[]
  /** Tools to disallow (passed via --disallowedTools) */
  disallowedTools?: string[]
  /** MCP tool name to use for permission prompts (--permission-prompt-tool flag).
   *  When set, the CLI invokes this tool instead of auto-denying permission-gated operations. */
  permissionPromptTool?: string
  /** Session ID for resuming an existing conversation */
  resume?: string
  /** AbortController for cancelling the CLI process */
  abortController?: AbortController
  /** Heartbeat interval in ms (default: 5000) */
  heartbeatIntervalMs?: number
  /** Agent ID for logging attribution */
  agentId?: string
  /** Max agentic turns */
  maxTurns?: number
  /** Path to MCP config JSON file (generated by mcp-config-writer) */
  mcpConfigPath?: string
  /** Additional directories for monorepo support */
  additionalDirectories?: string[]
  /** Additional env vars to inject into the CLI subprocess */
  envOverrides?: Record<string, string>
  /** Enable auto-compact */
  autoCompactEnabled?: boolean
  /** Context window size for auto-compact threshold */
  contextWindowSize?: number
  /** Continue an existing session — used for multi-turn interactions within the same process */
  continueSession?: boolean
  /** Effort level — Claude Code 2.1+ supports all 5 levels natively: low, medium, high, xhigh, max */
  effort?: 'low' | 'medium' | 'high' | 'xhigh' | 'max'
  /** Completion goal — Claude works autonomously until this condition is met.
   *  Dual delivery: (1) appended to system prompt as ## Completion Goal for persistent
   *  visibility, and (2) queued as a `/goal` slash command via stdin for native enforcement
   *  (Haiku-based stop-hook evaluator). */
  goal?: string
  /**
   * Goal delivery mode:
   * - `'advisory'` (default): goal only in system prompt (## Completion Goal section).
   * - `'enforce'`: additionally queues `/goal <condition>` via stdin for native
   *   stop-hook enforcement (Haiku evaluator). Use for phases where structured
   *   output MUST be produced (plan, tasks, review, build, verify).
   */
  goalMode?: 'advisory' | 'enforce'
  /** Enable 1M context beta */
  betas?: string[]
  /** Fallback model when primary unavailable */
  fallbackModel?: string
  /** Resume at a specific message point (undo support) */
  resumeSessionAt?: string
  /** Max thinking tokens per turn — advisory only.
   *  Dropped silently (no CLI equivalent; effort level caps reasoning). */
  thinkingBudget?: number
}

export interface CLIExecuteResult {
  sessionId?: string
  result?: string
  terminalReason?: TerminalReason
  sessionTitle?: string
  resultOrigin?: string
  tokenUsage: {
    input: number
    output: number
    cacheReadInputTokens: number
    cacheCreationInputTokens: number
    /** Current context occupancy (latest round-trip prompt size, not the sum). */
    contextWindowTokens?: number
  }
}

// ── CLIExecutor class ──

/**
 * Per-message timeout for iterator.next() — prevents indefinite hangs when
 * the CLI stalls with no tool call pending. Disabled during pending tool
 * calls (e.g., ask_user waiting for human interaction).
 */
const MESSAGE_TIMEOUT_MS = 5 * 60_000 // 5 minutes

/**
 * Generous timeout for MCP tool execution results. Applied when tools are
 * pending BUT none of them are ask_user-type (which legitimately wait for
 * human input). Prevents zombie CLI processes when MCP tools deadlock.
 * The 5-min main-process safety timer provides a second layer, but this
 * timeout addresses the root cause at the executor level.
 */
const TOOL_RESULT_TIMEOUT_MS = 10 * 60_000 // 10 minutes

/** Maximum character length for a /goal condition sent to the CLI. */
const GOAL_MAX_CHARS = 4_000

/** Words that, when a goal condition starts with them, collide with /goal subcommands. */
const GOAL_CLEAR_ALIASES = /^(clear|stop|off|reset|none|cancel)\b/i

/** Regex for stderr patterns that indicate real errors (not progress info). */
const STDERR_ERROR_PATTERN = /error|fatal|panic|ENOENT|EACCES|permission denied|segfault|SIGABRT/i

export class CLIExecutor {
  private cliProcess: ChildProcess | null = null
  private sessionId: string | undefined = undefined
  /** Temp file path for the current system prompt (cleaned up on process kill) */
  private systemPromptFile: string | null = null
  /** Hash of last written system prompt — avoids rewriting identical content to disk. */
  private lastSystemPromptHash: string | null = null
  /** Persisted NDJSON iterator — survives across turns so multi-turn stdin/stdout works */
  private ndjsonIterator: AsyncGenerator<Record<string, unknown>> | null = null
  /**
   * Ready-state flag for multi-turn stdin writes.
   * Set to true after receiving a `result` event (end-of-turn),
   * set to false immediately after writing a new message.
   * Prevents writing while the CLI is still processing a previous turn.
   */
  private cliReadyForInput = false
  /** Last captured stderr error lines — used to provide context when CLI exits with non-zero code */
  private lastStderrError: string | null = null
  /** Exit code from the most recent process exit — checked after stream exhausts */
  private lastExitCode: number | null = null
  /** Whether a /goal command was queued for the current turn — enables trailing-result drain */
  private goalQueuedForTurn = false

  /** Get the captured session ID */
  getSessionId(): string | undefined {
    return this.sessionId
  }

  /**
   * Check if the CLI process is still alive.
   * Used by AgentSessionService to determine if a send() can reuse the process.
   */
  isAlive(): boolean {
    return this.cliProcess !== null && !this.cliProcess.killed && this.cliProcess.exitCode === null
  }

  /**
   * Execute a query via the interactive Claude CLI.
   *
   * If `continueSession` is true and a process is already alive, writes
   * the prompt to stdin (multi-turn mode). Otherwise spawns a new process.
   *
   * Returns an async generator of StreamChunks — same interface as SDKExecutor.
   */
  async *execute(
    options: CLIExecuteOptions
  ): AsyncGenerator<StreamChunk & { _meta?: CLIExecuteResult }> {
    const telemetry = new TelemetryRecorder(options.model)
    const heartbeat = new HeartbeatMonitor(options.heartbeatIntervalMs ?? 5000)
    const tokens = new TokenAccountant()
    const tools = new ToolTracker()
    const state: StreamState = { streamedTextLength: 0 }

    // Reset per-execution error state
    this.lastStderrError = null
    this.lastExitCode = null

    heartbeat.start()

    try {
      // If continuing an existing session, write the prompt to stdin
      if (options.continueSession && this.isAlive() && this.cliProcess?.stdin) {
        if (!this.cliReadyForInput) {
          executorLog.warn(
            '[CLI:send] CLI not ready for input — previous turn may still be processing'
          )
        }
        executorLog.info('[CLI:send] Continuing existing session — writing message to stdin')
        await this.writeToStdin(buildUserMessage(options.prompt))

        // Queue /goal as a second stdin message (continue-session path) — enforce mode only
        const effectiveGoalMode = options.goalMode ?? 'advisory'
        const goalCmd =
          options.goal && effectiveGoalMode === 'enforce' ? buildGoalCommand(options.goal) : null
        if (goalCmd && this.cliProcess?.stdin) {
          await this.writeToStdin(buildUserMessage(goalCmd))
          this.goalQueuedForTurn = true
          executorLog.info(`[CLI:goal] queued condition (${goalCmd.length} chars)`)
        } else {
          this.goalQueuedForTurn = false
        }
      } else {
        await this.spawnCLIProcess(options)
      }

      // Read NDJSON from stdout — reuse the iterator across turns so the
      // underlying stream stays open for multi-turn interactive mode.
      if (!this.ndjsonIterator) {
        if (!this.cliProcess?.stdout) {
          yield { type: 'error', error: 'CLI process stdout not available' }
          return
        }
        this.ndjsonIterator = parseNdjsonStream(this.cliProcess.stdout, executorLog)
      }

      // Manual .next() loop instead of `for await...of` — breaking out of
      // `for await` calls iterator.return() which permanently closes the
      // generator, making it unusable for subsequent turns. By calling .next()
      // directly we can stop consuming on a `result` event without destroying
      // the iterator, so multi-turn stdin/stdout works.
      let msgCount = 0
      let lastLoggedPendingTools = 0 // throttle: only log on transitions (0→N or N→0)
      const goalWasQueued = this.goalQueuedForTurn
      try {
        while (true) {
          // Per-message timeout prevents indefinite hangs when CLI stalls
          // (e.g., MCP tool deadlock). When tool calls are pending:
          //   • ask_user/elicitation tools: timeout fully disabled (human input)
          //   • other MCP tools: TOOL_RESULT_TIMEOUT_MS (10 min) prevents zombie processes
          // The process exit (stream close) is a fallback termination signal.
          let iterResult: IteratorResult<Record<string, unknown>>
          if (tools.pendingToolCount > 0) {
            // Tool call in flight — use generous timeout unless waiting for
            // human input (ask_user / elicitation), which has no timeout.
            if (tools.hasAskUserPending()) {
              // Human input has no meaningful timeout — user decides when to respond
              // Log only on 0→N transition (not per message)
              if (lastLoggedPendingTools === 0) {
                executorLog.debug(
                  `[CLI:await] Waiting for human input (${tools.pendingToolCount} pending) — timeout suspended`
                )
              }
              lastLoggedPendingTools = tools.pendingToolCount
              iterResult = await this.ndjsonIterator.next()
            } else {
              // MCP tool execution: generous timeout prevents indefinite hangs
              // Log only on 0→N transition (not per message)
              if (lastLoggedPendingTools === 0) {
                executorLog.debug(
                  `[CLI:await] Waiting for tool result (${tools.pendingToolCount} pending) — ${TOOL_RESULT_TIMEOUT_MS / 1000}s timeout`
                )
              }
              lastLoggedPendingTools = tools.pendingToolCount
              let toolTimeoutHandle: ReturnType<typeof setTimeout> | undefined
              iterResult = await Promise.race([
                this.ndjsonIterator.next(),
                new Promise<never>((_, reject) => {
                  toolTimeoutHandle = setTimeout(
                    () =>
                      reject(
                        new Error(
                          `CLI tool result timeout — no response from MCP tool for ${TOOL_RESULT_TIMEOUT_MS / 60_000} minutes`
                        )
                      ),
                    TOOL_RESULT_TIMEOUT_MS
                  )
                })
              ]).finally(() => clearTimeout(toolTimeoutHandle))
            }
          } else {
            // Log tool-complete transition (N→0) once
            if (lastLoggedPendingTools > 0) {
              executorLog.debug(
                `[CLI:await] Tool calls resolved (was ${lastLoggedPendingTools} pending)`
              )
              lastLoggedPendingTools = 0
            }
            // No tools pending — use normal timeout to detect CLI stalls
            let timeoutHandle: ReturnType<typeof setTimeout> | undefined
            iterResult = await Promise.race([
              this.ndjsonIterator.next(),
              new Promise<never>((_, reject) => {
                timeoutHandle = setTimeout(
                  () =>
                    reject(
                      new Error(
                        `CLI message timeout — no NDJSON received for ${MESSAGE_TIMEOUT_MS / 1000}s`
                      )
                    ),
                  MESSAGE_TIMEOUT_MS
                )
              })
            ]).finally(() => clearTimeout(timeoutHandle))
          }
          if (iterResult.done) {
            executorLog.info('[CLI:stream] Iterator exhausted (process ended)')
            this.ndjsonIterator = null
            break
          }

          const msg = iterResult.value
          heartbeat.touch()
          msgCount++

          // Log first 5 messages for diagnostics — helps verify CLI is producing expected types
          if (msgCount <= 5) {
            executorLog.info(
              `[CLI:msg#${msgCount}] type=${msg.type} subtype=${(msg as Record<string, unknown>).subtype ?? 'none'}`
            )
          }

          // Emit pending heartbeat if timer fired between iterations
          if (heartbeat.consumeHeartbeat()) {
            yield { type: 'status', content: 'heartbeat' }
          }

          // Capture session ID from system/init (identical field to SDK)
          if (msg.type === 'system' && msg.subtype === 'init') {
            this.sessionId = msg.session_id as string | undefined
            state.sessionId = this.sessionId
          }

          // Delegate to existing stream normalizer — same NDJSON format
          yield* normalizeMessage(msg, tools, tokens, state, options.cwd)

          // In interactive mode (no -p), the CLI stays alive after responding.
          // Finalize on the FIRST result event — always. When a /goal was queued,
          // the CLI may emit a trailing second result for the /goal command.
          // We drain it defensively (1.5s race) so it can't poison the next turn.
          if (msg.type === 'result') {
            this.cliReadyForInput = true
            this.goalQueuedForTurn = false
            // Stop heartbeat immediately — the stream is pausing between turns
            // and no more activity is expected until the next send().  Without
            // this, the timer keeps firing stall warnings during the idle gap.
            heartbeat.stop()
            executorLog.info(
              '[CLI:result-received] Turn complete — pausing stream read (ready for input)'
            )

            // Defensive drain: when a /goal was queued, race iterator.next() vs
            // 1.5s timer. If a trailing result arrives, consume + discard it.
            // If the timer wins, the pending .next() resolves on the next turn's
            // first message and is handled by the existing loop.
            if (goalWasQueued && this.ndjsonIterator) {
              const drainIterator = this.ndjsonIterator
              const drainTimer = new Promise<'timeout'>((resolve) =>
                setTimeout(() => resolve('timeout'), 1500)
              )
              const drainNext = drainIterator.next().then((r) => ({ ...r, _source: 'iter' as const }))
              const drainResult = await Promise.race([drainNext, drainTimer])
              if (drainResult !== 'timeout' && !drainResult.done) {
                const trailingMsg = drainResult.value as Record<string, unknown>
                if (trailingMsg.type === 'result') {
                  executorLog.info('[CLI:goal] drained trailing goal result')
                } else {
                  // Not a result — unexpected. Log but don't re-process.
                  executorLog.warn(
                    `[CLI:goal] drained non-result message (type=${trailingMsg.type}) — discarded`
                  )
                }
              } else if (drainResult === 'timeout') {
                executorLog.debug(
                  '[CLI:goal] drain timer expired — no trailing result (will resolve on next turn)'
                )
              }
            }
            break
          }
        }
      } catch (error) {
        // Stream interrupted (abort, process kill, etc.)
        if ((error as NodeJS.ErrnoException).code !== 'ERR_STREAM_PREMATURE_CLOSE') {
          throw error
        }
        executorLog.info('[CLI:stream] Stream closed (process ended or aborted)')
        this.ndjsonIterator = null
      }
      executorLog.info(`[CLI:stream-end] Total NDJSON messages received: ${msgCount}`)

      // Detect CLI crash: process exited with non-zero code and produced no messages
      if (msgCount === 0 && this.lastExitCode !== null && this.lastExitCode !== 0) {
        const stderrHint = this.lastStderrError ? ` — ${this.lastStderrError}` : ''
        executorLog.error(
          `[CLI:crash-detected] CLI exited with code ${this.lastExitCode} before producing any output${stderrHint}`
        )
        const errorMsg = `CLI failed to start (exit code ${this.lastExitCode})${stderrHint}`
        telemetry.recordFailure(new Error(errorMsg))
        yield { type: 'error', error: errorMsg }
      }
    } catch (error) {
      executorLog.error('CLI execution error:', error)
      telemetry.recordFailure(error as Error)
      yield {
        type: 'error',
        error: `CLI execution failed: ${(error as Error).message}`
      }
    } finally {
      heartbeat.stop()
    }

    // Telemetry: finalize() is a no-op when recordFailure() was already called
    // (finalize only transitions from 'started' → 'succeeded').
    const tokenSummary = tokens.getSummary()
    telemetry.finalize(tokenSummary)

    // Zero-token detection: CLI produced text but reported 0 tokens (possible crash mid-stream)
    if (tokenSummary.input === 0 && tokenSummary.output === 0 && state.streamedTextLength > 0) {
      executorLog.warn(
        `[PIPELINE:zero-token-warning] CLI produced ${state.streamedTextLength} chars of text but reported 0 tokens — possible crash before result event`
      )
    }

    // Yield final metadata chunk (callers check for _meta)
    yield {
      type: 'status',
      content: 'complete',
      _meta: {
        sessionId: state.sessionId,
        result: state.resultText,
        terminalReason: state.terminalReason,
        sessionTitle: state.sessionTitle,
        resultOrigin: state.resultOrigin,
        tokenUsage: tokenSummary
      }
    } as StreamChunk & { _meta: CLIExecuteResult }
  }

  /**
   * Execute a single prompt and collect the full text result (non-streaming).
   * Used for decomposition and other one-shot queries.
   */
  async executeAndCollect(options: CLIExecuteOptions): Promise<{
    result: string
    sessionId?: string
    tokenUsage: { input: number; output: number }
  }> {
    let result = ''
    let sessionId: string | undefined
    const totalUsage = { input: 0, output: 0 }

    for await (const chunk of this.execute(options)) {
      if (chunk.type === 'text' && chunk.content) {
        result += chunk.content
      }
      if ('_meta' in chunk && chunk._meta) {
        const meta = chunk._meta as CLIExecuteResult
        sessionId = meta.sessionId
        totalUsage.input = meta.tokenUsage.input
        totalUsage.output = meta.tokenUsage.output
        if (!result && meta.result) {
          result = typeof meta.result === 'string' ? meta.result : JSON.stringify(meta.result)
        }
      }
    }

    return { result, sessionId, tokenUsage: totalUsage }
  }

  /**
   * Send a slash command to the interactive CLI (e.g. /compact, /clear).
   * Only works when a process is alive.
   */
  sendSlashCommand(command: string): void {
    if (!this.isAlive() || !this.cliProcess?.stdin) {
      executorLog.warn(`[CLI:slash] Cannot send "${command}" — no active process`)
      return
    }
    // EXEC-04: Reject embedded newlines to prevent command injection;
    // only accept /command [args] format on a single line
    const sanitized = command.split('\n')[0].trim()
    if (!/^\/[a-z_]+(\s+\S.*)?$/i.test(sanitized)) {
      executorLog.error(`[CLI:slash] Invalid command format: ${command.slice(0, 80)}`)
      return
    }
    executorLog.info(`[CLI:slash] Sending: ${sanitized}`)
    // EXEC-10: Wrap stdin.write in try-catch — throws if pipe is already closed
    try {
      this.cliProcess.stdin.write(sanitized + '\n')
    } catch (err) {
      executorLog.error(`[CLI:slash] stdin.write failed:`, err)
    }
  }

  /**
   * Send /compact to trigger context compaction via the interactive CLI.
   */
  compact(): void {
    this.sendSlashCommand('/compact')
  }

  /**
   * Change the CLI's permission mode mid-session via the control protocol.
   * Sends a set_permission_mode control_request to stdin.
   * Requires `--allow-dangerously-skip-permissions` to be present in the CLI args
   * for runtime elevation to 'bypassPermissions'.
   */
  setPermissionMode(
    mode: 'plan' | 'auto' | 'bypassPermissions' | 'default' | 'acceptEdits' | 'dontAsk'
  ): void {
    if (!this.isAlive() || !this.cliProcess?.stdin) {
      executorLog.warn('[CLI:setPermissionMode] Cannot set mode — no active process')
      return
    }
    const controlRequest = {
      type: 'control_request',
      request_id: `perm_${Date.now()}_${Math.random().toString(36).slice(2, 6)}`,
      request: {
        subtype: 'set_permission_mode',
        mode
      }
    }
    executorLog.info(`[CLI:setPermissionMode] Sending: ${mode}`)
    writeNdjsonMessage(this.cliProcess.stdin, controlRequest)
  }

  /**
   * Kill the active CLI process. SIGTERM first (closes stdout so any pending
   * iterator `.next()` settles), then close the async generator, then wait for
   * exit with a 5s SIGKILL escalation.
   *
   * DEADLOCK-FIX: Previously `iter.return()` was called BEFORE `proc.kill()`.
   * Async-generator semantics queue `.return()` behind a pending `.next()`,
   * which only settles when stdout closes — but `proc.kill()` (the thing that
   * closes stdout) was sequenced AFTER the await. This caused a permanent
   * deadlock when the CLI was idle after emitting a result.
   */
  async killProcess(): Promise<void> {
    if (!this.cliProcess) return

    const proc = this.cliProcess
    const iter = this.ndjsonIterator
    this.cliProcess = null
    this.ndjsonIterator = null
    this.cliReadyForInput = false

    // Step 1: Send SIGTERM first — this closes stdout, which lets any pending
    // iterator .next() settle so .return() can proceed.
    try {
      proc.kill('SIGTERM')
    } catch {
      // Already dead — fall through to cleanup
    }

    // Step 2: Close the async generator with a 2s timeout race.
    // After SIGTERM, stdout should close promptly letting .return() complete.
    if (iter) {
      try {
        const iterTimeout = new Promise<void>((r) => setTimeout(r, 2000))
        await Promise.race([iter.return?.(undefined), iterTimeout])
      } catch {
        /* ignore — process is dying */
      }
    }

    // Step 3: Wait for process exit with 5s SIGKILL escalation.
    return new Promise<void>((resolve) => {
      const forceKillTimer = setTimeout(() => {
        try {
          proc.kill('SIGKILL')
        } catch {
          // Already dead
        }
        this.cleanupSystemPromptFile()
        resolve()
      }, 5000)

      proc.once('exit', () => {
        clearTimeout(forceKillTimer)
        this.cleanupSystemPromptFile()
        resolve()
      })

      // If process already exited from SIGTERM, 'exit' fires immediately.
      // If not, forceKillTimer will escalate.
    })
  }

  // ── Private helpers ──

  /**
   * Spawn a fresh CLI process, wire abort/stderr/exit handlers, and write
   * the initial user message to stdin.
   * Extracted from execute() — cohesive process lifecycle setup concern.
   */
  private async spawnCLIProcess(options: CLIExecuteOptions): Promise<void> {
    // Kill any existing process BEFORE building args — killProcess() calls
    // cleanupSystemPromptFile() which deletes this.systemPromptFile.
    // If buildCLIArgs runs first, it writes a new prompt file that
    // killProcess then immediately deletes (race condition).
    await this.killProcess()

    const args = this.buildCLIArgs(options)
    const env = this.buildProcessEnv(options)

    executorLog.info(
      `[CLI:spawn] claude ${args.join(' ').replace(/--system-prompt ".*?"/, '--system-prompt "..."')}`
    )
    executorLog.info(`[CLI:args] ${args.join(' ')}`)

    // MCP diagnostic — surface config path and tool counts for debugging
    const mcpConfigIdx = args.indexOf('--mcp-config')
    const allowedToolsIdx = args.indexOf('--allowedTools')
    executorLog.info(
      `[CLI:mcp-diag] mcp-config=${mcpConfigIdx >= 0 ? args[mcpConfigIdx + 1] : 'NONE'} ` +
        `allowedToolsCount=${allowedToolsIdx >= 0 ? args[allowedToolsIdx + 1]?.split(',').length : 0} ` +
        `permissionMode=${args[args.indexOf('--permission-mode') + 1] ?? 'unset'}`
    )

    // EXEC-02: Guard spawn() — throws synchronously (ENOENT/ENOEXEC) if 'claude'
    // is not in PATH or is not a valid executable.
    try {
      this.cliProcess = spawn('claude', args, {
        cwd: options.cwd,
        env,
        stdio: ['pipe', 'pipe', 'pipe'],
        detached: false
      })
    } catch (err) {
      this.cliProcess = null
      const code = (err as NodeJS.ErrnoException).code
      const message = (err as Error).message
      this.lastStderrError = `Failed to spawn claude CLI: ${message}`
      if (code === 'ENOEXEC') {
        throw new Error(
          `Resolved 'claude' is not executable (wrong arch/format or missing shebang). Details: ${message}`
        )
      }
      throw new Error(
        `Claude CLI not found — ensure 'claude' is installed and in PATH. Details: ${message}`
      )
    }

    // Wire abort controller to process kill
    if (options.abortController) {
      const signal = options.abortController.signal
      if (signal.aborted) {
        this.cliProcess.kill('SIGTERM')
      } else {
        signal.addEventListener(
          'abort',
          () => {
            this.killProcess()
          },
          { once: true }
        )
      }
    }

    // Log stderr — upgrade to ERROR level for patterns that indicate real failures
    this.cliProcess.stderr?.on('data', (data: Buffer) => {
      const text = data.toString('utf-8').trim()
      if (!text) return
      if (STDERR_ERROR_PATTERN.test(text)) {
        executorLog.error(`[CLI:stderr-ERROR] ${text.slice(0, 500)}`)
        this.lastStderrError = text.slice(0, 500)
      } else {
        executorLog.info(`[CLI:stderr] ${text.slice(0, 500)}`)
      }
    })

    // Handle process exit
    this.cliProcess.on('exit', (code, signal) => {
      executorLog.info(`[CLI:exit] code=${code} signal=${signal}`)
      this.lastExitCode = code
      // EXEC-03: Clean up temp system prompt file on natural exit/crash
      this.cleanupSystemPromptFile()
      this.cliProcess = null
    })

    this.cliProcess.on('error', (err) => {
      executorLog.error('[CLI:error]', err)
      // EXEC-03: Clean up temp system prompt file on spawn error
      this.cleanupSystemPromptFile()
      this.cliProcess = null
    })

    // Write the initial user message to stdin
    if (this.cliProcess.stdin) {
      await this.writeToStdin(buildUserMessage(options.prompt))

      // Queue /goal as a second stdin message (spawn path) — enforce mode only
      const spawnGoalMode = options.goalMode ?? 'advisory'
      const goalCmd =
        options.goal && spawnGoalMode === 'enforce' ? buildGoalCommand(options.goal) : null
      if (goalCmd) {
        await this.writeToStdin(buildUserMessage(goalCmd))
        this.goalQueuedForTurn = true
        executorLog.info(`[CLI:goal] queued condition (${goalCmd.length} chars)`)
      } else {
        this.goalQueuedForTurn = false
      }
    }
  }

  /**
   * Write a message to stdin with backpressure handling.
   * If the kernel buffer is full, waits for 'drain' before resolving.
   * Ensures messages aren't silently dropped under heavy load.
   */
  private async writeToStdin(message: Record<string, unknown>): Promise<void> {
    if (!this.cliProcess?.stdin) {
      throw new Error('CLI stdin unavailable — process may have exited')
    }
    const accepted = writeNdjsonMessage(this.cliProcess.stdin, message)
    if (!accepted) {
      // stdin buffer is full — wait for it to drain before continuing
      await new Promise<void>((resolve) => {
        this.cliProcess?.stdin?.once('drain', resolve)
        // Safety: resolve after 10s if drain never fires (process may have died)
        setTimeout(resolve, 10_000)
      })
    }
    this.cliReadyForInput = false
  }

  /**
   * Build CLI arguments from execute options.
   * Maps SDK-style options to their `claude` CLI flag equivalents.
   */
  private buildCLIArgs(options: CLIExecuteOptions): string[] {
    const args: string[] = [
      // Core interactive mode flags — stream-json enables NDJSON on stdout/stdin
      '--output-format',
      'stream-json',
      '--input-format',
      'stream-json',
      '--verbose',
      // Include partial messages for real-time streaming (same as SDK's includePartialMessages)
      '--include-partial-messages',
      // Allow runtime switch to bypassPermissions via set_permission_mode control request.
      // Without this flag, the CLI rejects mid-session elevation to bypassPermissions.
      '--allow-dangerously-skip-permissions'
    ]

    // Model
    if (options.model) {
      args.push('--model', options.model)
    }

    // Permission mode
    if (options.permissionMode) {
      // Map SDK permission modes to CLI equivalents.
      // The CLI's --permission-mode flag accepts the literal mode name.
      // Note: 'bypassPermissions' is the correct value (not 'dangerously-skip-permissions',
      // which is a standalone flag, not a --permission-mode value).
      const modeMap: Record<string, string> = {
        default: 'default',
        plan: 'plan',
        bypassPermissions: 'bypassPermissions',
        acceptEdits: 'acceptEdits',
        auto: 'auto',
        dontAsk: 'dontAsk'
      }
      const cliMode = modeMap[options.permissionMode] ?? 'default'
      args.push('--permission-mode', cliMode)
    }

    // System prompt — written to a temp file to avoid shell escaping issues
    // and OS arg-length limits (system prompts can be 15K-25K chars).
    if (options.systemPrompt) {
      let fullPrompt = options.systemPrompt

      // Goal — delivered via system prompt since the CLI has no --goal flag.
      // (/goal is a session-only slash command, not a CLI argument.)
      if (options.goal) {
        fullPrompt += `\n\n## Completion Goal\n\nWork autonomously until the following condition is met, then emit the completion block:\n\n${options.goal}`
      }

      const promptFilePath = this.writeSystemPromptFile(fullPrompt)
      args.push('--system-prompt-file', promptFilePath)
    }

    // Session resume — validate format before passing to CLI
    if (options.resume) {
      if (/^[a-zA-Z0-9_-]{8,}$/.test(options.resume)) {
        args.push('--resume', options.resume)
      } else {
        executorLog.warn(
          `[CLI:invalid-resume] Malformed session ID (skipping --resume): ${options.resume.slice(0, 30)}`
        )
      }
    }

    // Resume at specific message (undo support)
    if (options.resumeSessionAt) {
      args.push('--resume-session-at', options.resumeSessionAt)
    }

    // Max turns
    if (options.maxTurns) {
      args.push('--max-turns', String(options.maxTurns))
    }

    // MCP config path (external servers)
    if (options.mcpConfigPath) {
      args.push('--mcp-config', options.mcpConfigPath)
    }

    // Allowed tools
    if (options.allowedTools?.length) {
      args.push('--allowedTools', options.allowedTools.join(','))
    }

    // Disallowed tools
    if (options.disallowedTools?.length) {
      args.push('--disallowedTools', options.disallowedTools.join(','))
    }

    // Permission prompt tool — routes CLI permission requests to our MCP tool
    // instead of auto-denying. The control-actions server surfaces these in the UI.
    if (options.permissionPromptTool) {
      args.push('--permission-prompt-tool', options.permissionPromptTool)
    }

    // Additional directories
    if (options.additionalDirectories?.length) {
      for (const dir of options.additionalDirectories) {
        args.push('--add-dir', dir)
      }
    }

    // Effort level — Claude Code 2.1+ supports all 5 levels natively
    if (options.effort) {
      args.push('--effort', options.effort)
    }

    // Betas (1M context)
    if (options.betas?.length) {
      for (const beta of options.betas) {
        args.push('--betas', beta)
      }
    }

    // Fallback model
    if (options.fallbackModel) {
      args.push('--fallback-model', options.fallbackModel)
    }

    // Goal is delivered via system prompt (see above) for persistent visibility.
    // The /goal slash command is queued separately via stdin in spawnCLIProcess().
    // thinkingBudget is dropped silently (no CLI equivalent).

    return args
  }

  /**
   * Write a system prompt to a temp file. Uses content hashing to avoid
   * rewriting identical prompts (common on cache-hit turns via Strategy ζ).
   * Returns the absolute path to the file. The file is cleaned up when
   * the CLI process exits (via killProcess) or on the next call.
   */
  private writeSystemPromptFile(prompt: string): string {
    // Hash-based dedup: skip write if content hasn't changed and file still exists
    const hash = createHash('md5').update(prompt).digest('hex').slice(0, 12)
    if (
      hash === this.lastSystemPromptHash &&
      this.systemPromptFile &&
      existsSync(this.systemPromptFile)
    ) {
      return this.systemPromptFile
    }

    // Clean up previous file if content changed
    this.cleanupSystemPromptFile()

    const dir = join(tmpdir(), 'code-atelier-prompts')
    if (!existsSync(dir)) {
      mkdirSync(dir, { recursive: true })
    }
    const filePath = join(dir, `system-prompt-${Date.now()}-${randomUUID().slice(0, 8)}.md`)
    writeFileSync(filePath, prompt, 'utf-8')
    this.systemPromptFile = filePath
    this.lastSystemPromptHash = hash
    return filePath
  }

  /**
   * Remove the current system prompt temp file.
   */
  private cleanupSystemPromptFile(): void {
    if (this.systemPromptFile) {
      try {
        unlinkSync(this.systemPromptFile)
      } catch {
        // Non-fatal — file may already be gone
      }
      this.systemPromptFile = null
      this.lastSystemPromptHash = null
    }
  }

  /**
   * Build the process environment.
   * Includes current env + any user-provided overrides + app identification.
   */
  private buildProcessEnv(options: CLIExecuteOptions): Record<string, string | undefined> {
    return {
      ...buildEnvWithPath(),
      ...(options.envOverrides ?? {}),
      CLAUDE_AGENT_SDK_CLIENT_APP: `code-atelier/${app.getVersion()}`,
      CLAUDE_CODE_SUPPRESS_SESSION_ATTRIBUTION: '1'
    }
  }
}

// ── Goal command builder ──

/**
 * Build a sanitized `/goal` slash command string from a raw condition.
 *
 * - Collapses newlines/whitespace to single spaces, trims.
 * - Returns `null` for empty/whitespace-only input.
 * - Prefix-guards against clear-alias words that the CLI interprets as
 *   subcommands (`/goal clear`, `/goal stop`, etc.) by wrapping with
 *   "Condition: " prefix.
 * - Caps at `GOAL_MAX_CHARS` (4,000) — truncates with a log warning.
 *
 * Exported for testing.
 */
export function buildGoalCommand(goal: string): string | null {
  // Collapse newlines and whitespace to single spaces
  const sanitized = goal.replace(/\s+/g, ' ').trim()
  if (!sanitized) return null

  // Prefix-guard: if the condition text starts with a word the CLI would
  // interpret as a clear/cancel subcommand, wrap it so it's unambiguous.
  let conditionText = sanitized
  if (GOAL_CLEAR_ALIASES.test(conditionText)) {
    conditionText = `Condition: ${conditionText}`
  }

  // Truncate if over the cap
  if (conditionText.length > GOAL_MAX_CHARS) {
    executorLog.warn(
      `[CLI:goal] condition truncated from ${conditionText.length} to ${GOAL_MAX_CHARS} chars`
    )
    conditionText = conditionText.slice(0, GOAL_MAX_CHARS)
  }

  return `/goal ${conditionText}`
}

/**
 * Sweep stale system-prompt temp files from /tmp/code-atelier-prompts/.
 * Removes files older than 24 hours. Call on app startup to prevent
 * accumulation from crashes that skip normal cleanup.
 */
export function cleanupStalePromptFiles(): void {
  const dir = join(tmpdir(), 'code-atelier-prompts')
  if (!existsSync(dir)) return

  const MAX_AGE_MS = 24 * 60 * 60_000 // 24 hours
  const now = Date.now()
  let removed = 0

  try {
    for (const file of readdirSync(dir)) {
      const filePath = join(dir, file)
      try {
        const stat = statSync(filePath)
        if (now - stat.mtimeMs > MAX_AGE_MS) {
          unlinkSync(filePath)
          removed++
        }
      } catch {
        // Non-fatal — skip individual files that can't be stat'd/removed
      }
    }
    if (removed > 0) {
      executorLog.info(`[CLI:cleanup] Removed ${removed} stale prompt file(s) from ${dir}`)
    }
  } catch {
    // Non-fatal — directory access issues
  }
}

/**
 * NDJSON (Newline-Delimited JSON) parser for Claude CLI interactive mode.
 *
 * Reads raw bytes from a readable stream (stdout) and yields parsed JSON objects.
 * Handles partial lines across chunk boundaries by buffering until a newline.
 *
 * The Claude CLI with `--output-format stream-json` emits one JSON object per line.
 * Each object has a `type` field matching the same NDJSON event types the Agent SDK
 * uses internally (system, assistant, stream_event, user, result, tool_progress, etc.)
 * so the existing stream-normalizer can consume them unchanged.
 */

import { Readable } from 'node:stream'
import log from 'electron-log'

/**
 * Async generator that reads from a Node Readable stream and yields
 * parsed JSON objects, one per NDJSON line.
 *
 * Handles:
 * - Partial lines split across chunks (buffered until newline)
 * - Empty lines (skipped)
 * - Malformed JSON lines (logged + skipped, never throws)
 * - Stream end (flushes any remaining buffer)
 */
export async function* parseNdjsonStream(
  stream: Readable,
  log?: { warn: (msg: string) => void }
): AsyncGenerator<Record<string, unknown>> {
  let buffer = ''

  for await (const chunk of stream) {
    buffer += typeof chunk === 'string' ? chunk : (chunk as Buffer).toString('utf-8')

    // Process all complete lines in the buffer
    let newlineIdx: number
    while ((newlineIdx = buffer.indexOf('\n')) !== -1) {
      const line = buffer.slice(0, newlineIdx).trim()
      buffer = buffer.slice(newlineIdx + 1)

      if (!line) continue // skip empty lines

      try {
        yield JSON.parse(line) as Record<string, unknown>
      } catch (err) {
        log?.warn(
          `[ndjson-parser] Malformed JSON line (${line.length} chars): ${line.slice(0, 120)}`
        )
        // Emit structured parse error so downstream can display it
        yield {
          type: 'parse_error',
          raw: line.slice(0, 200),
          error: (err as Error).message
        }
      }
    }
  }

  // Flush any remaining buffer (partial line at stream end)
  const remaining = buffer.trim()
  if (remaining) {
    try {
      yield JSON.parse(remaining) as Record<string, unknown>
    } catch (err) {
      log?.warn(`[ndjson-parser] Malformed final line: ${remaining.slice(0, 120)}`)
      yield {
        type: 'parse_error',
        raw: remaining.slice(0, 200),
        error: (err as Error).message
      }
    }
  }
}

const ndjsonLog = log.scope('ndjson-parser')

/**
 * Write a JSON message to a writable stream as an NDJSON line.
 * Used for writing user messages to the CLI's stdin.
 *
 * Returns true if the write was accepted by the kernel buffer.
 * Returns false if the buffer is full (backpressure) or the stream errored.
 * Callers should check the return value for critical messages.
 */
export function writeNdjsonMessage(
  stream: NodeJS.WritableStream,
  message: Record<string, unknown>
): boolean {
  try {
    const json = JSON.stringify(message) + '\n'
    const accepted = stream.write(json)
    if (!accepted) {
      ndjsonLog.warn(
        `[ndjson:backpressure] stdin buffer full — message queued (type=${message.type ?? 'unknown'}, len=${json.length})`
      )
    }
    return accepted
  } catch (err) {
    ndjsonLog.error(
      `[ndjson:write-error] Failed to write to stdin: ${(err as Error).message} (type=${message.type ?? 'unknown'})`
    )
    return false
  }
}

/**
 * Build a CLI-protocol user message for `--input-format stream-json`.
 *
 * Accepts either a plain text string or pre-built content blocks (for images).
 *
 * The Claude CLI expects:
 * ```json
 * {"type":"user","message":{"role":"user","content":[{"type":"text","text":"..."}]}}
 * ```
 *
 * For images, content blocks include `{ type: 'image', source: { type: 'base64', ... } }`
 * alongside text blocks — same structure as the Anthropic API.
 */
export function buildUserMessage(
  textOrBlocks: string | Array<Record<string, unknown>>
): Record<string, unknown> {
  const content =
    typeof textOrBlocks === 'string' ? [{ type: 'text', text: textOrBlocks }] : textOrBlocks

  return {
    type: 'user',
    message: {
      role: 'user',
      content
    }
  }
}

import { executorLog } from './index'

/** Options for HeartbeatMonitor constructor. */
export interface HeartbeatMonitorOptions {
  /** Heartbeat interval in milliseconds. */
  intervalMs: number
  /**
   * Optional escalation hook — fired once when the stall threshold is first
   * crossed (60s of no activity). Reset by `touch()`. Lets callers react to
   * stalls without hand-rolling their own watchdog.
   *
   * The CLI executor passes nothing (behavior unchanged), but blueprint phase
   * services and recovery helpers can use it for automatic failure detection.
   */
  onStall?: (stalledMs: number) => void
}

/**
 * Heartbeat / stall detection for executor queries.
 *
 * Sets a periodic timer that checks for activity. When the timer fires
 * and no activity has been recorded, it logs a stall warning.
 * Callers should call `touch()` on each message to reset the activity timer.
 */
export class HeartbeatMonitor {
  private heartbeatTimer: ReturnType<typeof setInterval> | null = null
  private lastActivityAt: number = Date.now()
  private _pendingHeartbeat = false
  private readonly stallThresholdMs = 60_000
  private readonly onStall?: (stalledMs: number) => void
  private stallCallbackFired = false

  /** Whether a heartbeat event is pending (timer fired between generator iterations) */
  get pendingHeartbeat(): boolean {
    return this._pendingHeartbeat
  }

  constructor(intervalMsOrOpts: number | HeartbeatMonitorOptions) {
    if (typeof intervalMsOrOpts === 'number') {
      this.intervalMs = intervalMsOrOpts
    } else {
      this.intervalMs = intervalMsOrOpts.intervalMs
      this.onStall = intervalMsOrOpts.onStall
    }
  }

  private intervalMs: number

  /**
   * Start the heartbeat timer. Must be called before the message loop.
   */
  start(): void {
    if (this.intervalMs <= 0) return

    this.lastActivityAt = Date.now()
    this.stallCallbackFired = false
    this.heartbeatTimer = setInterval(() => {
      const stalledMs = Date.now() - this.lastActivityAt
      if (stalledMs > this.stallThresholdMs) {
        // Fire onStall escalation hook once per stall episode
        if (this.onStall && !this.stallCallbackFired) {
          this.stallCallbackFired = true
          try {
            this.onStall(stalledMs)
          } catch (err) {
            executorLog.error('[HeartbeatMonitor] onStall callback threw:', err)
          }
        }

        // Log only every ~60s to reduce noise during expected long waits (MCP tools like Maestro).
        // The stall warning is informational — the keepalive timer keeps the UI alive independently.
        const stalledSec = Math.round(stalledMs / 1000)
        if (stalledSec % 60 < this.intervalMs / 1000) {
          executorLog.warn(`Query appears stalled — no activity for ${stalledSec}s`)
        }
      }
      this._pendingHeartbeat = true
    }, this.intervalMs)
  }

  /**
   * Record activity — call on each message to reset stall detection.
   */
  touch(): void {
    this.lastActivityAt = Date.now()
    this.stallCallbackFired = false
  }

  /**
   * Consume the pending heartbeat flag. Returns true if a heartbeat was pending.
   */
  consumeHeartbeat(): boolean {
    if (this._pendingHeartbeat) {
      this._pendingHeartbeat = false
      return true
    }
    return false
  }

  /**
   * Stop the heartbeat timer. Call in finally block.
   */
  stop(): void {
    if (this.heartbeatTimer) {
      clearInterval(this.heartbeatTimer)
      this.heartbeatTimer = null
    }
  }
}

/**
 * Accumulates token usage from messages across the lifecycle of a query.
 *
 * Handles the multi-source nature of token usage:
 * - `stream_event` message_start/message_delta for incremental usage
 * - `result` message for authoritative final usage
 * - Generic `usage` field on any message type
 */
export interface TokenUsage {
  input: number
  output: number
  cacheReadInputTokens: number
  cacheCreationInputTokens: number
  /**
   * Current context-window occupancy — the prompt size of the MOST RECENT API
   * round-trip (input + cache_read + cache_creation of the latest message_start),
   * NOT the per-turn accumulated sum.
   *
   * A single user message triggers an agentic loop with many API round-trips,
   * each of which re-reads the entire cached context. Summing cache_read across
   * those round-trips massively over-counts window occupancy (e.g. a plan turn
   * with 10 tool calls reports ~400K "used" on a 1M window when the real
   * occupancy is ~60K). This snapshot reflects the true current context size.
   */
  contextWindowTokens: number
}

export class TokenAccountant {
  private usage: TokenUsage = {
    input: 0,
    output: 0,
    cacheReadInputTokens: 0,
    cacheCreationInputTokens: 0,
    contextWindowTokens: 0
  }

  /**
   * Accumulate token usage from a stream_event message_start.
   */
  accumulateFromMessageStart(startUsage: Record<string, number> | undefined): void {
    if (!startUsage) return
    this.usage.input += startUsage.input_tokens ?? 0
    this.usage.cacheReadInputTokens += startUsage.cache_read_input_tokens ?? 0
    this.usage.cacheCreationInputTokens += startUsage.cache_creation_input_tokens ?? 0

    // Snapshot current context occupancy = this call's full prompt size.
    // Overwrite (not accumulate) so we track the latest round-trip, not the sum.
    const callContext =
      (startUsage.input_tokens ?? 0) +
      (startUsage.cache_read_input_tokens ?? 0) +
      (startUsage.cache_creation_input_tokens ?? 0)
    if (callContext > 0) this.usage.contextWindowTokens = callContext
  }

  /**
   * Accumulate output tokens from a stream_event message_delta.
   */
  accumulateFromMessageDelta(deltaUsage: Record<string, number> | undefined): void {
    if (!deltaUsage) return
    this.usage.output += deltaUsage.output_tokens ?? 0
  }

  /**
   * Replace totals with authoritative result usage (result message).
   * The result message contains the final, definitive token counts.
   */
  setFromResult(resultUsage: Record<string, number> | undefined): void {
    if (!resultUsage) return
    this.usage.input = resultUsage.input_tokens ?? resultUsage.inputTokens ?? this.usage.input
    this.usage.output = resultUsage.output_tokens ?? resultUsage.outputTokens ?? this.usage.output
    this.usage.cacheReadInputTokens =
      resultUsage.cache_read_input_tokens ??
      resultUsage.cacheReadInputTokens ??
      this.usage.cacheReadInputTokens
    this.usage.cacheCreationInputTokens =
      resultUsage.cache_creation_input_tokens ??
      resultUsage.cacheCreationInputTokens ??
      this.usage.cacheCreationInputTokens

    // Only fall back to the result usage for context occupancy when no
    // message_start snapshot was captured. The CLI's result usage reports the
    // CUMULATIVE (billed) totals for the turn, which would re-introduce the
    // over-count — so we never overwrite an existing message_start snapshot.
    if (this.usage.contextWindowTokens === 0) {
      const resultContext =
        (resultUsage.input_tokens ?? resultUsage.inputTokens ?? 0) +
        (resultUsage.cache_read_input_tokens ?? resultUsage.cacheReadInputTokens ?? 0) +
        (resultUsage.cache_creation_input_tokens ?? resultUsage.cacheCreationInputTokens ?? 0)
      if (resultContext > 0) this.usage.contextWindowTokens = resultContext
    }
  }

  /**
   * Accumulate generic usage from any message type (non-result).
   */
  accumulateGeneric(msgUsage: Record<string, number> | undefined): void {
    if (!msgUsage) return
    this.usage.input += msgUsage.input_tokens ?? 0
    this.usage.output += msgUsage.output_tokens ?? 0
    this.usage.cacheReadInputTokens += msgUsage.cache_read_input_tokens ?? 0
    this.usage.cacheCreationInputTokens += msgUsage.cache_creation_input_tokens ?? 0
  }

  /**
   * Get the current accumulated token usage (copy).
   */
  getSummary(): TokenUsage {
    return { ...this.usage }
  }
}

import type { TokenUsage } from './token-accountant'
import { executorLog } from './index'

let requestCounter = 0

/** Internal telemetry tracking for executor request lifecycle logging */
export interface TelemetryEntry {
  requestId: string
  startedAt: number
  completedAt?: number
  durationMs?: number
  model: string
  status: 'started' | 'succeeded' | 'failed'
  error?: string
  tokenUsage?: TokenUsage
}

/**
 * Records telemetry for an executor query lifecycle.
 * Tracks start/success/failure with timing and token usage.
 */
export class TelemetryRecorder {
  private entry: TelemetryEntry

  /** The telemetry request ID */
  get requestId(): string {
    return this.entry.requestId
  }

  constructor(model: string) {
    const id = `exec-${++requestCounter}-${Date.now()}`
    this.entry = {
      requestId: id,
      startedAt: Date.now(),
      model,
      status: 'started'
    }
    executorLog.info(`[TELEMETRY:request-started] id=${id} model=${model}`)
  }

  /**
   * Record a failure. Should be called in the catch block.
   */
  recordFailure(error: Error): void {
    this.entry.status = 'failed'
    this.entry.completedAt = Date.now()
    this.entry.durationMs = this.entry.completedAt - this.entry.startedAt
    this.entry.error = error.message
    executorLog.info(
      `[TELEMETRY:request-failed] id=${this.entry.requestId} duration=${this.entry.durationMs}ms error=${this.entry.error}`
    )
  }

  /**
   * Finalize telemetry with success. Returns the completed entry.
   * Should be called after the message loop completes successfully.
   */
  finalize(tokens: TokenUsage): TelemetryEntry {
    if (this.entry.status === 'started') {
      this.entry.status = 'succeeded'
      this.entry.completedAt = Date.now()
      this.entry.durationMs = this.entry.completedAt - this.entry.startedAt
      this.entry.tokenUsage = { ...tokens }
      executorLog.info(
        `[TELEMETRY:request-succeeded] id=${this.entry.requestId} duration=${this.entry.durationMs}ms input=${tokens.input} output=${tokens.output}`
      )
    }
    return { ...this.entry }
  }
}

/**
 * Maps tool use IDs to tool names, enabling tool_result events to include
 * the correct tool name (tool_result only provides the tool_use_id).
 *
 * Also tracks content state for turn boundary detection.
 */
export class ToolTracker {
  private toolIdToName = new Map<string, string>()
  /** Stores summarized tool input for inclusion in tool_result chunks */
  private toolIdToInput = new Map<string, string>()
  /** Stores RAW (unsummarized) JSON tool input — see StreamChunk.toolInputRaw */
  private toolIdToRawInput = new Map<string, string>()

  /** Whether any content has been emitted this turn (text or tools) */
  hasPriorContent = false

  /**
   * Whether *visible text* has been emitted in the current turn (not just
   * tools). Used to suppress turn_boundary for tool-only iterations so a
   * single user prompt produces a single bubble with all its tool activity
   * attached, instead of one bubble per internal Claude tool-loop iteration.
   *
   * Reset to false at every turn_boundary emission.
   */
  hasPriorText = false

  /** Track the last content block type for thinking→text transition detection */
  lastBlockType: 'thinking' | 'text' | 'tool_use' | null = null

  /** Current structured output schema name (set during json_delta streaming) */
  currentSchemaName: string | null = null

  /** Number of tool calls that have been registered but not yet consumed (pending results). */
  get pendingToolCount(): number {
    return this.toolIdToName.size
  }

  /**
   * Whether any pending tool is an ask_user-type tool that legitimately waits
   * for human input. These tools have no meaningful timeout — the user decides
   * when to respond.
   */
  hasAskUserPending(): boolean {
    for (const name of this.toolIdToName.values()) {
      if (name === 'ask_user' || name === 'elicitation') return true
    }
    return false
  }

  /**
   * Register a tool use mapping (id → name).
   */
  register(toolId: string, toolName: string, inputSummary?: string, rawInputJson?: string): void {
    this.toolIdToName.set(toolId, toolName)
    if (inputSummary) {
      this.toolIdToInput.set(toolId, inputSummary)
    }
    if (rawInputJson) {
      this.toolIdToRawInput.set(toolId, rawInputJson)
    }
  }

  /**
   * Resolve a tool use ID to its name. Returns 'Unknown' if not tracked.
   */
  resolve(toolUseId: string | undefined): string {
    if (!toolUseId) return 'Unknown'
    return this.toolIdToName.get(toolUseId) ?? 'Unknown'
  }

  /**
   * Resolve a tool use ID to its stored input summary.
   */
  resolveInput(toolUseId: string | undefined): string | undefined {
    if (!toolUseId) return undefined
    return this.toolIdToInput.get(toolUseId)
  }

  /**
   * Resolve a tool use ID to its stored RAW (unsummarized) JSON input.
   */
  resolveRawInput(toolUseId: string | undefined): string | undefined {
    if (!toolUseId) return undefined
    return this.toolIdToRawInput.get(toolUseId)
  }

  /**
   * Remove a tool mapping after result processing (free memory for long sessions).
   */
  consume(toolUseId: string | undefined): void {
    if (toolUseId) {
      this.toolIdToName.delete(toolUseId)
      this.toolIdToInput.delete(toolUseId)
      this.toolIdToRawInput.delete(toolUseId)
    }
  }

  /**
   * Register tool mappings from an assistant message (complete replay).
   * Only registers tools not already tracked.
   */
  registerFromAssistantMessage(contentBlocks: Record<string, unknown>[]): void {
    for (const block of contentBlocks) {
      if (block.type === 'tool_use') {
        const toolId = block.id as string | undefined
        const toolName = block.name as string
        if (toolId && !this.toolIdToName.has(toolId)) {
          this.toolIdToName.set(toolId, toolName)
        }
      }
    }
  }
}

/**
 * Stream normalizer — converts raw NDJSON messages into StreamChunk events.
 *
 * Handles the mapping of NDJSON message types (system, assistant, stream_event,
 * user, result, tool_progress, rate_limit_event, etc.) to the unified
 * StreamChunk interface that the rest of the application consumes.
 *
 * Backend-agnostic: works identically with both the CLI (spawn + stream-json)
 * and OpenCode. Both emit the same NDJSON format.
 *
 * Extracted from SDKExecutor.execute() to reduce cyclomatic complexity.
 */

import type { StreamChunk } from '../agent-base.service'
import { summarizeToolInput } from '../agent-base.service'
import type { ExecutorResult, TerminalReason } from '../executor-types'
import type { ToolTracker } from './tool-tracker'
import type { TokenAccountant } from './token-accountant'
import { executorLog } from './index'

/** Mutable state that accumulates across the stream */
export interface StreamState {
  sessionId?: string
  resultText?: string
  terminalReason?: TerminalReason
  sessionTitle?: string
  /** Origin of the result — distinguishes user-prompted vs task-notification */
  resultOrigin?: string
  /**
   * Total length (chars) of text already streamed to the renderer via
   * text_delta events. Used to compute the "missed delta" when the final
   * result text exceeds what was actually streamed (interrupted / partial streams).
   */
  streamedTextLength: number
}

/**
 * Normalize a single message into zero or more StreamChunks.
 *
 * This is a pure-ish function: it reads from tools/tokens state and may mutate
 * the ToolTracker's hasPriorContent/lastBlockType, but produces no side effects
 * beyond yielded chunks.
 */
export function* normalizeMessage(
  msg: Record<string, unknown>,
  tools: ToolTracker,
  tokens: TokenAccountant,
  state: StreamState,
  cwd: string
): Generator<StreamChunk & { _meta?: ExecutorResult }> {
  // ── parse_error — structured error from NDJSON parser on malformed JSON ──
  if (msg.type === 'parse_error') {
    executorLog.warn(
      `[normalizer] NDJSON parse error: ${msg.error} — raw: ${(msg.raw as string)?.slice(0, 100)}`
    )
    yield {
      type: 'error',
      error: `Stream parse error: ${msg.error}`
    }
    return
  }

  // ── system.init — capture session ID + log MCP server status + tool counts ──
  if (msg.type === 'system' && msg.subtype === 'init') {
    state.sessionId = msg.session_id as string | undefined

    // Log MCP server connection status (helps diagnose silent failures)
    const mcpServers = msg.mcp_servers as Array<{ name: string; status: string }> | undefined
    if (mcpServers?.length) {
      // Separate CLI built-in servers (claude.ai Google Drive, Gmail, etc.) from our local servers
      const failed = mcpServers.filter((s) => s.status !== 'connected')
      const ourFailed = failed.filter((s) => !s.name.startsWith('claude.ai '))
      const builtInFailed = failed.filter((s) => s.name.startsWith('claude.ai '))

      if (ourFailed.length > 0) {
        executorLog.warn(
          `[init] MCP server(s) failed to connect: ${ourFailed.map((s) => `${s.name}=${s.status}`).join(', ')}`
        )
      }
      if (builtInFailed.length > 0) {
        executorLog.debug(
          `[init] CLI built-in MCP servers not authenticated (harmless): ${builtInFailed.map((s) => s.name).join(', ')}`
        )
      }
      if (failed.length === 0) {
        executorLog.info(`[init] All ${mcpServers.length} MCP server(s) connected`)
      }
    }

    // Log tool availability — makes "model had N custom tools this session" greppable.
    // The tools array is provided by newer CLI versions on system.init.
    const initTools = msg.tools as Array<{ name: string }> | undefined
    if (initTools?.length) {
      const mcpToolCount = initTools.filter((t) => t.name?.startsWith('mcp__')).length
      executorLog.info(
        `[init:tools] totalTools=${initTools.length} mcpTools=${mcpToolCount}`
      )
    }

    return
  }

  // ── SubAgent lifecycle events ──
  if (msg.type === 'system' && msg.subtype === 'task_started') {
    yield {
      type: 'subagent_start',
      content: msg.description as string,
      toolId: msg.task_id as string,
      toolName: (msg.task_type as string) || 'Agent'
    }
    return
  }

  if (msg.type === 'system' && msg.subtype === 'task_progress') {
    yield {
      type: 'subagent_progress',
      content: (msg.summary as string) || (msg.description as string),
      toolId: msg.task_id as string,
      toolName: msg.last_tool_name as string | undefined
    }
    return
  }

  if (msg.type === 'system' && msg.subtype === 'task_notification') {
    yield {
      type: 'subagent_complete',
      content: msg.summary as string,
      toolId: msg.task_id as string,
      toolInput: msg.status as string
    }
    return
  }

  // ── assistant — complete replay, only used for tool ID mapping ──
  if (msg.type === 'assistant') {
    const assistantMsg = msg.message as Record<string, unknown> | undefined
    if (assistantMsg?.content && Array.isArray(assistantMsg.content)) {
      tools.registerFromAssistantMessage(assistantMsg.content as Record<string, unknown>[])
    }
    return
  }

  const msgType = `${msg.type}${(msg as Record<string, unknown>).subtype ? ':' + (msg as Record<string, unknown>).subtype : ''}`

  // ── stream_event — real-time streaming content ──
  if (msg.type === 'stream_event') {
    const streamEvent = (msg as Record<string, unknown>).event as Record<string, unknown>
    if (!streamEvent) return

    // Real-time text streaming
    if (streamEvent.type === 'content_block_delta') {
      const delta = streamEvent.delta as Record<string, unknown> | undefined
      if (delta?.type === 'text_delta' && delta.text) {
        tools.hasPriorContent = true
        tools.hasPriorText = true
        const text = delta.text as string
        state.streamedTextLength += text.length
        executorLog.debug(
          `[normalizer:text] ${text.length} chars (totalStreamed=${state.streamedTextLength})`
        )
        yield { type: 'text', content: text }
      }
      // Progressive extended thinking streaming (Opus 4.8+)
      if (delta?.type === 'thinking_delta' && delta.thinking) {
        const thinking = delta.thinking as string
        yield { type: 'thinking', content: thinking }
      }
      if (delta?.type === 'json_delta' && delta.json) {
        tools.hasPriorContent = true
        tools.hasPriorText = true
        const text = delta.json as string
        state.streamedTextLength += text.length
        // Emit as structured_output when a schema context is active,
        // enabling progressive rendering in the UI (plan cards, audit findings, etc.)
        if (tools.currentSchemaName) {
          yield {
            type: 'structured_output',
            content: text,
            structuredOutput: {
              data: text,
              schemaName: tools.currentSchemaName
            }
          }
        } else {
          yield { type: 'text', content: text }
        }
      }
    }

    // Tool use start + thinking→text boundary detection
    if (streamEvent.type === 'content_block_start') {
      const cb = streamEvent.content_block as Record<string, unknown> | undefined

      // Detect thinking→text transition within the same turn.
      // Only split when there was already visible text — tool-only prior
      // iterations should stay attached to the same bubble.
      if (cb?.type === 'text' && tools.lastBlockType === 'thinking' && tools.hasPriorText) {
        yield { type: 'turn_boundary' as const, content: `thinking-split-${Date.now()}` }
        tools.hasPriorText = false
      }

      // Track block type transitions
      if (cb?.type === 'thinking') {
        tools.lastBlockType = 'thinking'
        tools.currentSchemaName = null
      } else if (cb?.type === 'tool_use') {
        tools.lastBlockType = 'tool_use'
        // Structured output blocks carry a schema name from the tool definition
        tools.currentSchemaName = (cb.name as string) || null
      } else if (cb?.type === 'text') {
        tools.lastBlockType = 'text'
        tools.currentSchemaName = null
      }

      if (cb?.type === 'tool_use') {
        const toolId = cb.id as string | undefined
        const toolName = cb.name as string
        const toolInput = cb.input as Record<string, unknown> | undefined
        const hasInput = toolInput && Object.keys(toolInput).length > 0

        const inputSummary = hasInput ? summarizeToolInput(toolName, toolInput, cwd) : undefined
        // Raw (unsummarized) JSON — inputSummary is a human-readable display
        // string ("src/a.ts (1 lines)"), not parseable JSON, so it can't be
        // used to recover structured fields like file_path downstream.
        const rawInputJson = hasInput ? JSON.stringify(toolInput) : undefined
        if (toolId) {
          tools.register(toolId, toolName, inputSummary, rawInputJson)
        }

        tools.hasPriorContent = true

        // TodoWrite always ships the COMPLETE todo list on every call (not a
        // delta) — surface it as an authoritative sync so the Todos tab (and
        // DB) reconcile against the model's actual state instead of trying
        // to reconstruct incremental add/complete/remove events from a tool
        // whose contract doesn't provide them.
        if (toolName === 'TodoWrite' && Array.isArray(toolInput?.todos)) {
          const todos = (toolInput.todos as Array<Record<string, unknown>>)
            .map((t, i) => ({
              text: String(t.content ?? t.text ?? '').trim(),
              completed: t.status === 'completed',
              index: i
            }))
            .filter((t) => t.text.length > 0)
          // Emit even when todos is empty — TodoWrite({ todos: [] }) is how
          // the model clears the list. Filtering on length > 0 silently
          // dropped clears, leaving stale rows in the UI and DB forever.
          yield { type: 'todo_update', todoSync: todos }
        }

        yield {
          type: 'tool_use',
          toolName,
          toolId,
          toolInput: inputSummary,
          toolInputRaw: rawInputJson
        }
      }
    }

    // Token usage from message_start + turn boundary detection.
    //
    // Only split into a new bubble when the prior turn had visible *text*.
    // Tool-only iterations (Claude's internal "call tool → read result → call
    // next tool" loop) should stay attached to the same bubble — otherwise
    // every tool call produces a separate (mostly empty) specialist bubble.
    if (streamEvent.type === 'message_start') {
      executorLog.debug(
        `[normalizer:message_start] hasPriorText=${tools.hasPriorText} ` +
          `hasPriorContent=${tools.hasPriorContent} lastBlockType=${tools.lastBlockType}`
      )
      if (tools.hasPriorText) {
        executorLog.info(
          '[normalizer:turn_boundary] Emitting turn_boundary (text→new message transition)'
        )
        yield { type: 'turn_boundary' as const, content: `turn-${Date.now()}` }
        // Next turn starts clean — only further text_deltas re-arm the flag.
        tools.hasPriorText = false
      }
      const startMsg = streamEvent.message as Record<string, unknown> | undefined
      tokens.accumulateFromMessageStart(startMsg?.usage as Record<string, number> | undefined)
    }

    // Token usage from message_delta
    if (streamEvent.type === 'message_delta') {
      tokens.accumulateFromMessageDelta(streamEvent.usage as Record<string, number> | undefined)
    }
    return
  }

  // ── user — tool results ──
  if (msg.type === 'user') {
    const userMsg = msg.message as Record<string, unknown> | undefined
    if (userMsg?.content && Array.isArray(userMsg.content)) {
      for (const block of userMsg.content as Record<string, unknown>[]) {
        if (block.type === 'tool_result') {
          const toolUseId = block.tool_use_id as string | undefined
          const toolName = tools.resolve(toolUseId)
          // Retrieve stored input summary + raw JSON before consuming the tracker entry
          const storedInput = tools.resolveInput(toolUseId)
          const storedRawInput = tools.resolveRawInput(toolUseId)
          tools.consume(toolUseId)

          let resultContent: string | undefined
          if (typeof block.content === 'string') {
            resultContent = block.content
          } else if (Array.isArray(block.content)) {
            resultContent = (block.content as Record<string, unknown>[])
              .filter((c) => c.type === 'text')
              .map((c) => c.text as string)
              .join('\n')
          }

          yield {
            type: 'tool_result',
            toolName,
            toolId: toolUseId,
            toolInput: storedInput,
            toolInputRaw: storedRawInput,
            content: resultContent,
            // Propagate the is_error flag from the CLI's tool_result block
            // so downstream consumers (tool-chunk-processor) can detect denials.
            ...(block.is_error ? { isError: true } : {})
          }
        }
      }
    }
    return
  }

  // ── result — final query result ──
  if (msg.type === 'result') {
    const subtype = msg.subtype as string | undefined
    const isError = msg.is_error as boolean | undefined

    if (isError && subtype && subtype !== 'success') {
      const errorDetail =
        subtype === 'error_max_budget_usd'
          ? 'budget cap exceeded'
          : subtype === 'error_max_turns'
            ? 'max turns reached'
            : subtype === 'error_max_structured_output_retries'
              ? 'structured output schema validation failed after retries'
              : subtype
      executorLog.warn(`[TELEMETRY:result-error] subtype=${subtype} detail=${errorDetail}`)
      yield { type: 'error', error: `Execution stopped: ${errorDetail}` }
    }

    state.resultText = msg.result as string | undefined
    executorLog.info(
      `[normalizer:result] msgType=${msgType} resultTextLen=${state.resultText?.length ?? 0} ` +
        `hasPriorContent=${tools.hasPriorContent} streamedLen=${state.streamedTextLength}`
    )

    // Capture origin for distinguishing user-prompted vs task-notification results
    const origin = msg.origin as string | undefined
    if (origin) {
      state.resultOrigin = origin
      executorLog.info(`[TELEMETRY:result-origin] origin=${origin}`)
    }

    // Extract terminal reason
    const rawTerminalReason = msg.terminal_reason as string | undefined
    if (rawTerminalReason) {
      state.terminalReason = rawTerminalReason as TerminalReason
      executorLog.info(`[TELEMETRY:terminal-reason] ${state.terminalReason}`)
    }

    // Extract session title
    const rawSessionTitle = msg.session_title ?? msg.sessionTitle
    if (rawSessionTitle && typeof rawSessionTitle === 'string') {
      state.sessionTitle = rawSessionTitle
      executorLog.info(`[TELEMETRY:session-title] "${state.sessionTitle}"`)
    }

    // For structured output, the JSON is in structured_output
    if (!state.resultText) {
      const structuredOutput = msg.structured_output
      if (structuredOutput) {
        state.resultText =
          typeof structuredOutput === 'string' ? structuredOutput : JSON.stringify(structuredOutput)
      }
    }

    if (state.resultText && !tools.hasPriorContent) {
      yield { type: 'text', content: state.resultText }
      state.streamedTextLength += state.resultText.length
    } else if (
      state.resultText &&
      tools.hasPriorContent &&
      state.resultText.length > state.streamedTextLength
    ) {
      // Streaming was partial — text_deltas didn't cover the entire final
      // result text (can happen when the model emits a final text block after
      // tool use without per-delta events, or when the stream was
      // interrupted). Emit only the missing tail to avoid blank bubbles.
      const missingTail = state.resultText.slice(state.streamedTextLength)
      executorLog.warn(
        `[normalizer:result-tail-recovery] Recovered ${missingTail.length} chars of missed result text (resultLen=${state.resultText.length} streamedLen=${state.streamedTextLength})`
      )
      yield { type: 'text', content: missingTail }
      state.streamedTextLength = state.resultText.length
    }

    // Detect the "blank bubble" case — model ran tools but produced no text at all.
    // This happens when the model ends a turn with a tool call rather than a text response,
    // causing result.result to be null/empty. Log prominently so we can diagnose.
    if (!state.resultText && tools.hasPriorContent && state.streamedTextLength === 0) {
      executorLog.warn(
        `[PIPELINE:no-result-text] Model completed with tool activity but no text output. ` +
          `This produces a blank bubble. hasPriorContent=${tools.hasPriorContent} ` +
          `streamedLen=${state.streamedTextLength}`
      )
    }

    executorLog.info(
      `[PIPELINE:turn-text] streamedLen=${state.streamedTextLength} resultLen=${state.resultText?.length ?? 0} hasPriorContent=${tools.hasPriorContent}`
    )

    // Result has authoritative usage
    tokens.setFromResult(msg.usage as Record<string, number> | undefined)
    return
  }

  // ── tool_progress — elapsed time updates ──
  if (msg.type === 'tool_progress') {
    yield {
      type: 'tool_progress',
      toolId: msg.tool_use_id as string,
      toolName: msg.tool_name as string,
      elapsedSeconds: msg.elapsed_time_seconds as number,
      content: `${msg.elapsed_time_seconds}s`
    }
    return
  }

  // ── rate_limit_event ──
  if (msg.type === 'rate_limit_event') {
    const info = msg.rate_limit_info as Record<string, unknown>
    if (info) {
      yield {
        type: 'rate_limit',
        rateLimit: {
          status: info.status as 'allowed' | 'allowed_warning' | 'rejected',
          utilization: info.utilization as number | undefined,
          resetsAt: info.resetsAt as number | undefined,
          rateLimitType: info.rateLimitType as string | undefined
        }
      }
    }
    return
  }

  // ── system/api_retry ──
  if (msg.type === 'system' && msg.subtype === 'api_retry') {
    yield {
      type: 'api_retry',
      retryInfo: {
        attempt: msg.attempt as number,
        maxRetries: msg.max_retries as number,
        retryDelayMs: msg.retry_delay_ms as number,
        errorStatus: msg.error_status as number | null
      }
    }
    return
  }

  // ── system/compact_boundary ──
  if (msg.type === 'system' && msg.subtype === 'compact_boundary') {
    const meta = msg.compact_metadata as Record<string, unknown> | undefined
    // Instrumentation: confirm the CLI's auto-compact actually fired and at what size.
    executorLog.info(
      `[compaction:boundary] SDK/CLI auto-compact fired — trigger=${meta?.trigger ?? 'auto'} ` +
        `preTokens=${meta?.pre_tokens ?? '?'}`
    )
    yield {
      type: 'compact_boundary',
      content: `Context compacted (trigger: ${meta?.trigger ?? 'auto'}, pre-tokens: ${meta?.pre_tokens ?? '?'})`
    }
    return
  }

  // ── system/status ──
  if (msg.type === 'system' && msg.subtype === 'status') {
    yield { type: 'session_state', content: (msg.status as string | null) ?? 'idle' }
    return
  }

  // ── prompt_suggestion ──
  if (msg.type === 'prompt_suggestion') {
    yield { type: 'prompt_suggestion', content: msg.suggestion as string }
    return
  }

  // ── system/files_persisted ──
  if (msg.type === 'system' && msg.subtype === 'files_persisted') {
    yield {
      type: 'files_persisted',
      persistedFiles: (msg.files as Array<{ filename: string; file_id: string }> | undefined)?.map(
        (f) => ({
          filename: f.filename,
          fileId: f.file_id
        })
      )
    }
    return
  }

  // ── tool_use_summary ──
  if (msg.type === 'tool_use_summary') {
    yield { type: 'tool_use_summary', content: msg.summary as string }
    return
  }

  // ── system/hook lifecycle ──
  if (
    msg.type === 'system' &&
    ['hook_started', 'hook_progress', 'hook_response'].includes(msg.subtype as string)
  ) {
    yield {
      type: 'hook_lifecycle',
      hookInfo: {
        hookId: msg.hook_id as string,
        hookName: msg.hook_name as string,
        hookEvent: msg.hook_event as string,
        phase: (msg.subtype === 'hook_started'
          ? 'started'
          : msg.subtype === 'hook_progress'
            ? 'progress'
            : 'response') as 'started' | 'progress' | 'response',
        output: msg.output as string | undefined,
        outcome: msg.outcome as 'success' | 'error' | 'cancelled' | undefined
      }
    }
    return
  }

  // ── system/session_state_changed ──
  if (msg.type === 'system' && msg.subtype === 'session_state_changed') {
    yield { type: 'session_state', content: msg.state as string }
    return
  }

  // ── auth_status ──
  if (msg.type === 'auth_status') {
    yield {
      type: 'auth_status',
      content: msg.error ? `Auth error: ${msg.error}` : 'Authenticating...'
    }
    return
  }

  // ── system/elicitation_complete ──
  if (msg.type === 'system' && msg.subtype === 'elicitation_complete') {
    yield {
      type: 'session_state',
      content: `MCP auth completed for ${msg.mcp_server_name as string}`
    }
    return
  }

  // ── system/local_command_output ──
  if (msg.type === 'system' && msg.subtype === 'local_command_output') {
    const output = msg.content as string | undefined
    if (output) {
      yield { type: 'text', content: output }
    }
    return
  }

  // ── Generic usage accumulation (non-result messages) ──
  if (msg.usage && msg.type !== 'result') {
    tokens.accumulateGeneric(msg.usage as Record<string, number>)
  }

  // ── Default: warn on unrecognized message types ──
  // Prevents silent data loss if CLI emits new event types in future versions.
  if (
    msg.type !== 'stream_event' &&
    msg.type !== 'result' &&
    msg.type !== 'user' &&
    msg.type !== 'assistant' &&
    msg.type !== 'system' &&
    msg.type !== 'tool_progress' &&
    msg.type !== 'rate_limit_event' &&
    msg.type !== 'prompt_suggestion' &&
    msg.type !== 'tool_use_summary' &&
    msg.type !== 'auth_status' &&
    msg.type !== 'parse_error'
  ) {
    executorLog.warn(
      `[normalizer] Unknown message type: ${msg.type} ` +
        `(subtype: ${(msg as Record<string, unknown>).subtype ?? 'none'}) — silently dropped`
    )
  }
}

/**
 * Context management configuration for Claude sessions.
 *
 * Implements a three-tier cascade (cheapest first):
 *   Tier 1 — PREVENTIVE: SDK hooks (ReadLimit, BashOutputCap, ToolResultBudget)
 *   Tier 2 — SDK AUTO-COMPACT: autoCompactEnabled + autoCompactWindow via Settings
 *   Tier 3 — APP-LEVEL NUDGE: compactSuggestThreshold / compactAutoThreshold → UI modal
 *
 * ⚠️ IMPORTANT: The clearToolResults*, clearThinking*, and serverCompaction*
 * fields in ContextManagementConfig are NOT forwarded to the SDK. The Claude
 * Agent SDK's Settings type only accepts autoCompactEnabled, autoCompactWindow,
 * and compactInstructions. These fields serve as:
 *   - Tier metadata for hook parameterization (_tierLimits, _tier)
 *   - App-level diagnostics and UI threshold configuration
 *   - Future-proofing for when the SDK adds server-side clearing APIs
 *   - Documentation of the intended compaction strategy
 *
 * The `claude` CLI handles the compaction pipeline internally. Note the CLI
 * does NOT read `contextWindowSize`/`autoCompactEnabled` from argv — those are
 * not forwarded as flags. The compaction window is controlled purely via
 * process env vars, wired in agent-executor-factory.ts (resolveClaudeCompactionEnv):
 *   - CLAUDE_CODE_AUTO_COMPACT_WINDOW = effective window. 1M models MUST set
 *     1000000 here or the CLI falls back to its smaller model-default window
 *     (which inflates the context badge and triggers premature auto-compact).
 *   - CLAUDE_AUTOCOMPACT_PCT_OVERRIDE=80 for 200K models (Opus<=4.7/Haiku), so
 *     auto-compact fires at ~80% of the usable window (~128-152K) instead of
 *     the usable-13K default. Honoured by claude-code >= 2.1.x.
 */

// ── Context Window Tiers ─────────────────────────────────────────────

/** Context window tier — drives tool selection, budgets, and turn limits. */
export type ContextWindowTier = 'small' | 'medium' | 'large'

/** Resolve tier from context window size in tokens */
export function resolveContextTier(contextWindow: number): ContextWindowTier {
  if (contextWindow <= 65_536) return 'small' // 32K models (Qwen 3B/7B/14B)
  if (contextWindow <= 131_072) return 'medium' // 128K models (Gemma 4)
  return 'large' // 262K models (Qwen 3.6 MoE, Qwen 3 Coder)
}

/** Per-tier operational limits */
export interface ContextTierLimits {
  /** Max agentic turns (tool-use rounds) before SDK stops the loop */
  maxTurnsPlan: number
  maxTurnsBuild: number
  /** Read hook default line limit */
  readLineLimit: number
  /** Tool result budget (characters per agentic turn) */
  toolResultBudgetChars: number
  /** Compaction thresholds for app-level UI */
  compactSuggestThreshold: number
  compactAutoThreshold: number
  /**
   * S11: SDK built-in tools allowed in plan mode (local LLM only).
   * Restricts the tool schema overhead for small/medium context windows.
   * Omit or empty array = no restriction (all builtins available).
   */
  planBuiltinAllowlist?: string[]
}

/**
 * S11: SDK built-in tools allowed in local LLM plan mode.
 * Small tier: read-only exploration only (saves ~8-10K tokens in tool schemas).
 * Medium tier: adds Bash for running type-checks / grep commands.
 * Large tier: no restriction (all builtins available).
 */
const LOCAL_PLAN_BUILTIN_SMALL = ['Read', 'Glob', 'Grep'] as const
const LOCAL_PLAN_BUILTIN_MEDIUM = ['Read', 'Glob', 'Grep', 'Bash'] as const

export const TIER_LIMITS: Record<ContextWindowTier, ContextTierLimits> = {
  small: {
    maxTurnsPlan: 12, // Increased from 8 — simple plans need ~6 exploration + ~4 writing turns
    maxTurnsBuild: 15, // Increased from 12 — matched to plan+buffer
    readLineLimit: 100, // 100 lines ≈ 1.2K tokens (vs 300 = 3.6K for Claude)
    toolResultBudgetChars: 30_000, // ~8.5K tokens — leaves room in 32K
    compactSuggestThreshold: 16_000,
    compactAutoThreshold: 24_000,
    planBuiltinAllowlist: [...LOCAL_PLAN_BUILTIN_SMALL]
  },
  medium: {
    maxTurnsPlan: 15,
    maxTurnsBuild: 25,
    readLineLimit: 200,
    toolResultBudgetChars: 100_000, // ~28K tokens — comfortable in 128K
    compactSuggestThreshold: 60_000,
    compactAutoThreshold: 80_000,
    planBuiltinAllowlist: [...LOCAL_PLAN_BUILTIN_MEDIUM]
  },
  large: {
    maxTurnsPlan: 30,
    maxTurnsBuild: 50,
    readLineLimit: 300,
    toolResultBudgetChars: 200_000, // Same as Claude — 262K is roomy
    compactSuggestThreshold: 120_000,
    compactAutoThreshold: 160_000
    // No planBuiltinAllowlist — large tier gets all built-in tools
  }
} as const

// ── Context Management Config ────────────────────────────────────────

/**
 * App-level context management config. Passed as `contextManagement` to the SDK
 * but the SDK only reads `compactionInstructions` from it — all other fields are
 * consumed by app-level hooks and UI logic, NOT by the SDK's compaction engine.
 */
export interface ContextManagementConfig {
  // ── App-level: Tool result clearing (not SDK-forwarded) ──
  /** Enable tool result clearing */
  clearToolResults: boolean
  /** Token threshold to trigger tool clearing */
  clearToolResultsTrigger: number
  /** Number of recent tool uses to keep */
  clearToolResultsKeep: number
  /** Minimum tokens to clear per firing (amortizes cache invalidation) */
  clearToolResultsMinClear: number
  /** Tool names excluded from clearing (e.g. memory tools) */
  clearToolResultsExclude: string[]

  // ── Tier 2b: Thinking block clearing ──
  /** Enable thinking block clearing */
  clearThinking: boolean
  /** Number of recent turns whose thinking to keep */
  clearThinkingKeepTurns: number

  // ── Tier 3: Server-side compaction ──
  /** Enable server-side compaction */
  serverCompaction: boolean
  /** Token threshold to trigger compaction */
  serverCompactionTrigger: number
  /** Custom compaction instructions */
  compactionInstructions?: string

  // ── Local LLM tier metadata (only set for local LLM configs) ──
  /** Tier-specific operational limits */
  _tierLimits?: ContextTierLimits
  /** Resolved context tier */
  _tier?: ContextWindowTier
}

/** Default config for Claude sessions with 1M context window */
export const CLAUDE_1M_CONTEXT_CONFIG: ContextManagementConfig = {
  clearToolResults: true,
  clearToolResultsTrigger: 300_000, // 30% of 1M — fire early
  clearToolResultsKeep: 5, // keep last 5 tool results
  clearToolResultsMinClear: 50_000, // clear at least 50K (amortize cache invalidation)
  clearToolResultsExclude: [
    'mcp__memory-control__SearchMemories',
    'mcp__memory-control__GetMemory',
    'mcp__plan-control__ExitPlanMode',
    'mcp__plan-control__AskUserQuestion'
  ],

  clearThinking: true,
  clearThinkingKeepTurns: 2, // keep last 2 turns of thinking

  serverCompaction: true,
  serverCompactionTrigger: 600_000, // 60% of 1M — fire after clearing is insufficient
  compactionInstructions: [
    'Preserve: file paths modified, key decisions made, current plan state,',
    'error patterns encountered, workspace conventions learned.',
    'Discard: verbatim file contents (re-readable), intermediate search results,',
    'tool outputs already acted upon, exploratory dead ends.',
    'Wrap in <summary></summary>.'
  ].join(' ')
} as const

/** Economy mode — lower thresholds for 200K effective window */
export const CLAUDE_ECONOMY_CONTEXT_CONFIG: ContextManagementConfig = {
  ...CLAUDE_1M_CONTEXT_CONFIG,
  clearToolResultsTrigger: 80_000,
  clearToolResultsKeep: 3,
  clearToolResultsMinClear: 20_000,
  serverCompactionTrigger: 150_000,
  clearThinkingKeepTurns: 1
} as const

/**
 * Config for Claude sessions using the default 200K context window (Opus, Haiku).
 * The context-1m beta is NOT active — thresholds scaled proportionally to 200K.
 */
export const CLAUDE_200K_CONTEXT_CONFIG: ContextManagementConfig = {
  clearToolResults: true,
  clearToolResultsTrigger: 60_000, // 30% of 200K
  clearToolResultsKeep: 3,
  clearToolResultsMinClear: 10_000,
