/**
 * S13: Structured compaction instructions for local LLMs.
 *
 * Used by both SDK auto-compact (oMLX, S14) and app-level compaction (S7).
 * The structured template ensures the model produces useful summaries that
 * preserve file paths and plan progress while discarding raw tool output.
 */
export const LOCAL_COMPACTION_INSTRUCTIONS = [
  'Summarize using this exact structure:',
  '## Goal: [what the user wants to accomplish]',
  '## Files Found: [exact file paths explored, one per line]',
  '## Key Findings: [important code patterns, component locations, line ranges]',
  '## Plan So Far: [numbered list of changes identified]',
  '## Next Steps: [what remains to be done]',
  'Keep file paths exact. Omit file contents (they can be re-read).',
  'Do NOT include tool call details or conversation meta-data.'
].join('\n')

/**
 * Local LLM mode — tier-aware configuration for context management.
 *
 * @param contextWindow - The context window size in tokens
 * @param isOmlx - Whether the backend is oMLX (enables compaction instructions)
 */
export function getLocalLlmContextConfig(
  contextWindow: number,
  isOmlx = false
): ContextManagementConfig {
  const tier = resolveContextTier(contextWindow)
  const limits = TIER_LIMITS[tier]
  return {
    clearToolResults: true,
    clearToolResultsTrigger: Math.round(contextWindow * 0.3),
    clearToolResultsKeep: tier === 'small' ? 2 : 3,
    clearToolResultsMinClear: Math.round(contextWindow * 0.05),
    clearToolResultsExclude: [], // Local has no memory MCP tools to protect
    clearThinking: false, // Local LLMs don't use extended thinking
    clearThinkingKeepTurns: 0,
    serverCompaction: isOmlx, // S14: oMLX supports server-side compaction via auto-compact
    serverCompactionTrigger: isOmlx ? Math.round(contextWindow * 0.6) : 0,
    // S13: Structured compaction instructions for auto-compact quality
    compactionInstructions: isOmlx ? LOCAL_COMPACTION_INSTRUCTIONS : undefined,
    // Attach tier limits for downstream consumers (hooks, maxTurns, diagnostics)
    _tierLimits: limits,
    _tier: tier
  }
}

/**
 * S9: Context Budget Auditor — pre-flight check before sending requests to local LLMs.
 *
 * Estimates context consumption BEFORE the SDK call to catch the insidious
 * "system prompt ate the whole window" bug early. Runs only for local LLM
 * providers where context is scarce (32K–262K).
 *
 * Token estimation uses chars / 3.5 (conservative for English + code).
 */

import type { ContextWindowTier } from './context-management'
import { chatAgentLogger } from '../logger'

const log = chatAgentLogger

// ── Types ──

export interface ContextBudget {
  /** Total context window size in tokens */
  contextWindow: number
  /** Estimated system prompt consumption (chars / 3.5) */
  estimatedSystemPromptTokens: number
  /** Estimated tool schema consumption (toolCount × 450) */
  estimatedToolSchemaTokens: number
  /** Reserved for model output (varies by tier) */
  reservedForOutput: number
  /** Remaining tokens available for conversation messages */
  availableForConversation: number
  /** Ratio of available / contextWindow — below 0.3 is critical */
  warningRatio: number
  /** Human-readable breakdown for diagnostic logging */
  breakdown: string
}

/** Output token reserves by tier — smaller tiers need proportionally more headroom */
const OUTPUT_RESERVES: Record<ContextWindowTier, number> = {
  small: 4_000, // 32K → 4K for output
  medium: 8_000, // 128K → 8K for output
  large: 16_000 // 262K → 16K for output
}

// ── Auditor ──

/**
 * Audit the context budget for a local LLM request.
 *
 * Call this from `buildSdkExecuteOptions()` before sending the request.
 * If `warningRatio < 0.3`, the system prompt + tools consume >70% of the
 * context window, leaving dangerously little room for the conversation.
 */
export function auditContextBudget(params: {
  systemPrompt: string
  toolCount: number
  contextWindow: number
  tier: ContextWindowTier
}): ContextBudget {
  const { systemPrompt, toolCount, contextWindow, tier } = params

  const estimatedSystemPromptTokens = Math.ceil(systemPrompt.length / 3.5)
  const estimatedToolSchemaTokens = toolCount * 450 // ~400-500 tokens per tool schema
  const reservedForOutput = OUTPUT_RESERVES[tier]

  const consumed = estimatedSystemPromptTokens + estimatedToolSchemaTokens + reservedForOutput
  const availableForConversation = Math.max(0, contextWindow - consumed)
  const warningRatio = contextWindow > 0 ? availableForConversation / contextWindow : 0

  const fmt = (n: number): string => (n >= 1000 ? `${Math.round(n / 1000)}K` : String(n))

  const breakdown =
    `system=${fmt(estimatedSystemPromptTokens)} + tools(${toolCount})=${fmt(estimatedToolSchemaTokens)} ` +
    `+ outputReserve=${fmt(reservedForOutput)} = ${fmt(consumed)} consumed / ${fmt(contextWindow)} window ` +
    `→ ${fmt(availableForConversation)} available (${Math.round(warningRatio * 100)}%)`

  const budget: ContextBudget = {
    contextWindow,
    estimatedSystemPromptTokens,
    estimatedToolSchemaTokens,
    reservedForOutput,
    availableForConversation,
    warningRatio,
    breakdown
  }

  // Log diagnostics
  if (warningRatio < 0.2) {
    log.error(
      `[S9:context-budget-CRITICAL] ${breakdown} — less than 20% available! ` +
        `Consider trimming system prompt or reducing tool count.`
    )
  } else if (warningRatio < 0.3) {
    log.warn(`[S9:context-budget-WARNING] ${breakdown} — tight budget, may hit overflow`)
  } else {
    log.info(`[S9:context-budget] ${breakdown}`)
  }

  return budget
}

/**
 * Estimate the number of tools that will be mounted based on MCP config result.
 * Counts MCP tools from allowed tools list + SDK built-in tools not disallowed.
 */
export function estimateToolCount(params: {
  allowedTools?: string[]
  disallowedTools: string[]
  isLocalProvider: boolean
}): number {
  const { allowedTools, disallowedTools } = params

  // If we have an explicit allowed list, that's the tool count
  if (allowedTools) {
    return allowedTools.length
  }

  // SDK has ~11 built-in tools + whatever MCP tools are mounted
  const defaultBuiltinCount = 11
  const disallowedBuiltins = disallowedTools.filter((t) =>
    [
      'Read',
      'Write',
      'Edit',
      'MultiEdit',
      'Bash',
      'Glob',
      'Grep',
      'TodoRead',
      'TodoWrite',
      'NotebookRead',
      'NotebookEdit'
    ].includes(t)
  )
  return defaultBuiltinCount - disallowedBuiltins.length
}

import log from 'electron-log/main'
import { workspaceRepository } from '../db/repositories'
import { decryptSettingsKey } from '../ipc/encrypt-settings-keys'

type AuthMode = 'claude-max' | 'api-key'

export interface AuthProvider {
  mode: AuthMode
  getApiKey(): string | undefined
  supportsSDK(): boolean
}

class AuthProviderService implements AuthProvider {
  private _mode: AuthMode = 'claude-max'
  private _apiKey: string | undefined

  get mode(): AuthMode {
    return this._mode
  }

  getApiKey(): string | undefined {
    return this._apiKey
  }

  supportsSDK(): boolean {
    // SDK is now the only execution path — works with both claude-max (CLI auth) and api-key
    return true
  }

  /** Load auth settings from workspace settings or environment */
  loadFromWorkspace(workspacePath: string): void {
    const settings = workspaceRepository.getSettingsByPath(workspacePath)
    const authMode = (settings?.authMode as AuthMode) ?? 'claude-max'
    this._mode = authMode

    if (authMode === 'api-key') {
      // Prefer workspace-level setting, fall back to env var
      // SEC-04: Decrypt API key (handles both legacy plaintext and encrypted)
      const storedKey = decryptSettingsKey(
        settings?.anthropicApiKey as string | undefined,
        !!settings?.anthropicApiKeyEncrypted
      )
      this._apiKey = storedKey ?? process.env.ANTHROPIC_API_KEY
    } else {
      this._apiKey = undefined
    }

    log.scope('AuthProvider').info(`Auth mode: ${this._mode}, SDK supported: ${this.supportsSDK()}`)
  }

  /** Update auth mode programmatically */
  setAuthMode(mode: AuthMode, apiKey?: string): void {
    this._mode = mode
    this._apiKey = apiKey
  }
}

export const authProvider = new AuthProviderService()

import type { StreamChunk } from './agent-base.service'
import type { ExecutorResult } from './executor-types'
import type { CLIExecutor } from './cli-executor'
import { MCP_TOOLS } from '../../shared/constants'
import { chatAgentLogger } from '../logger'
import { conversationRepository } from '../db/repositories'
import { usageTrackerService } from './usage-tracker.service'

export interface RecoveryNudgeOptions {
  /** CLI executor to perform the 1-turn text-only recovery call */
  cliExecutor: CLIExecutor
  /** System prompt for the recovery query context */
  systemPrompt: string
  /** Workspace path for model resolution */
  workspacePath: string
  /** Model identifier for the recovery query */
  model: string
  /** Whether the agent is in build mode (affects permissionMode) */
  isBuildMode: boolean
  /** Current session ID for resume */
  sessionId: string | undefined
  /** Conversation ID for session tracking */
  conversationId: string
  /** Workspace id for unified usage logging (nullable). */
  workspaceId?: string | null
  /** Number of tool calls made (for fallback message) */
  toolCallCount: number
  /** Names of the last tool(s) called (for context-specific recovery prompt) */
  lastToolNames?: string[]
  /**
   * When true, skip the CLI executor turn entirely and fall through to the
   * fallback message. Used for local-LLM sessions that must never spawn the
   * Claude CLI.
   */
  skipCliTurn?: boolean
  /** Callback to capture new session ID from recovery response */
  onSessionCapture: (sessionId: string) => void
  /** Callback to emit stream chunks to the renderer */
  onChunk: (chunk: StreamChunk) => void
  /** Callback to track token usage from recovery response */
  onTokens: (tokens: number) => void
}

export interface RecoveryNudgeResult {
  /** Whether the recovery nudge produced text output */
  recovered: boolean
  /** Accumulated recovery text (or fallback message if not recovered) */
  text: string
}

export interface PlanToolRecoveryOptions {
  /** CLI executor to perform the recovery call */
  cliExecutor: CLIExecutor
  /** System prompt for the recovery query context */
  systemPrompt: string
  /** Workspace path for model resolution */
  workspacePath: string
  /** Model identifier for the recovery query */
  model: string
  /** Current session ID for resume */
  sessionId: string | undefined
  /** Conversation ID for session tracking */
  conversationId: string
  /** Workspace id for unified usage logging (nullable). */
  workspaceId?: string | null
  /**
   * MCP config path that mounts the control-actions server (emit_plan). Without
   * it the recovery turn cannot call emit_plan. When undefined, recovery is skipped.
   */
  mcpConfigPath: string | undefined
  /** Callback to capture new session ID from recovery response */
  onSessionCapture: (sessionId: string) => void
  /** Callback to emit stream chunks to the renderer */
  onChunk: (chunk: StreamChunk) => void
  /** Callback to track token usage from recovery response */
  onTokens: (tokens: number) => void
}

export interface PlanToolRecoveryResult {
  /** Whether the recovery turn ran to completion (does not guarantee a plan was emitted). */
  attempted: boolean
}

/**
 * Handles the "silent tool completion" recovery strategy.
 *
 * When the stream ends after tool calls without producing a text summary,
 * this service fires a 1-turn text-only nudge to extract a summary from the model.
 * If the nudge also fails, it produces a user-facing fallback message.
 *
 * This is a complete sub-interaction with its own executor call, session handling,
 * and fallback logic — isolated from the main stream loop.
 */
export class RecoveryNudgeService {
  private readonly log = chatAgentLogger

  // ── Shared watchdog helper ──

  /**
   * Wraps an async generator with a per-chunk inactivity timeout.
   * If no chunk arrives within `timeoutMs`, the iterator is force-closed
   * and the generator returns — callers see a normal `done: true`.
   *
   * Used by both `attemptRecovery` and `attemptPlanToolRecovery` to prevent
   * an unbounded `for await` from wedging the session.
   */
  private async *withChunkTimeout<T>(
    iter: AsyncGenerator<T>,
    timeoutMs: number,
    label: string
  ): AsyncGenerator<T> {
    let timedOut = false
    try {
      while (true) {
        const timeoutPromise = new Promise<{ done: true; value: undefined }>((resolve) =>
          setTimeout(() => resolve({ done: true, value: undefined }), timeoutMs)
        )
        const raceStart = Date.now()
        const next = iter.next()
        const result = await Promise.race([next, timeoutPromise])

        if (result.done) {
          // Distinguish normal completion from timeout by elapsed time
          if (Date.now() - raceStart >= timeoutMs - 50) {
            this.log.warn(
              `[${label}-timeout] No chunk for ${timeoutMs / 1000}s — force-closing iterator`
            )
            timedOut = true
            iter.return?.(undefined as never).catch(() => { /* ignore */ })
          }
          break
        }

        yield result.value
      }
    } finally {
      if (timedOut) {
        this.log.info(`[${label}-timeout] Iterator cleanup complete`)
      }
    }
  }

  /**
   * Attempt a 1-turn text-only recovery when tools completed without summary.
   * Returns whether recovery succeeded and the text produced (or fallback).
   */
  async attemptRecovery(opts: RecoveryNudgeOptions): Promise<RecoveryNudgeResult> {
    this.log.warn(
      `[PIPELINE:silent-tool-completion] conversationId=${opts.conversationId} toolCalls=${opts.toolCallCount} — attempting recovery nudge`
    )

    let recovered = false
    let recoveredText = ''

    // Local-LLM sessions must never spawn the Claude CLI — skip the executor
    // turn entirely and fall straight through to the fallback message.
    if (opts.skipCliTurn) {
      this.log.info(
        `[PIPELINE:recovery-nudge-skip-cli] local provider — bypassing CLI turn for conversationId=${opts.conversationId}`
      )
    } else {
      // Build context-specific recovery prompt when tool names are available
      const toolContext = opts.lastToolNames?.length
        ? ` Your previous call(s) used ${opts.lastToolNames.join(', ')}.`
        : ''

      // Defence-in-depth: 2-minute per-chunk watchdog prevents an unbounded
      // recovery turn from wedging the session (same timeout as plan-tool-recovery).
      const RECOVERY_TIMEOUT_MS = 120_000

      try {
        const rawIter = opts.cliExecutor.execute({
          prompt: (() => {
            const action = opts.isBuildMode ? 'found or executed' : 'found'
            const source = opts.isBuildMode ? 'read or ran' : 'read'
            return `[System: Your previous response ended after tool calls without providing a summary to the user.${toolContext} Please summarize what you ${action} in 2-5 sentences. Do NOT use any tools — just summarize from what you already ${source}.]`
          })(),
          systemPrompt: opts.systemPrompt,
          model: opts.model,
          cwd: opts.workspacePath,
          permissionMode: opts.isBuildMode ? 'bypassPermissions' : 'plan',
          allowedTools: [], // No tools — text summary only
          disallowedTools: [
            'Agent',
            'Task',
            'local_agent',
            'ToolSearch',
            'ExitPlanMode',
            'AskUserQuestion'
          ],
          maxTurns: 1,
          resume: opts.sessionId,
          agentId: 'specialist',
          // Recovery is lightweight summarization — omit thinking entirely.
          effort: 'low'
        })

        for await (const chunk of this.withChunkTimeout(rawIter, RECOVERY_TIMEOUT_MS, 'recovery-nudge')) {
          if ('_meta' in chunk && chunk._meta) {
            const meta = chunk._meta as ExecutorResult
            if (meta.sessionId && opts.conversationId) {
              opts.onSessionCapture(meta.sessionId)
              try {
                conversationRepository.updateSessionId(opts.conversationId, meta.sessionId)
              } catch {
                /* ignore */
              }
            }
            opts.onTokens(meta.tokenUsage.input + meta.tokenUsage.output)
            usageTrackerService.recordUsage({
              feature: 'recovery_nudge',
              model: opts.model,
              workspaceId: opts.workspaceId ?? null,
              conversationId: opts.conversationId,
              tokens: {
                input: meta.tokenUsage.input,
                output: meta.tokenUsage.output,
                cacheRead: meta.tokenUsage.cacheReadInputTokens,
                cacheCreation: meta.tokenUsage.cacheCreationInputTokens
              }
            })
          } else if (chunk.type === 'text' && chunk.content) {
            recovered = true
            recoveredText += chunk.content
            opts.onChunk(chunk)
          }
        }

        if (recovered) {
          this.log.info(
            `[PIPELINE:silent-tool-recovery] Successfully recovered summary for conversationId=${opts.conversationId}`
          )
        }
      } catch (err) {
        this.log.error('[PIPELINE:recovery-nudge-failed]', err)
      }
    }

    if (!recovered) {
      const fallbackMessage =
        opts.toolCallCount === 1
          ? '\n\n_I read a file but my response was cut short. Could you repeat your question?_'
          : `\n\n_I used ${opts.toolCallCount} tools but didn't produce a summary. Try asking "what did you find?" and I'll summarize._`
      recoveredText = fallbackMessage
      this.log.warn(
        `[PIPELINE:recovery-nudge-fallback] Emitting fallback for conversationId=${opts.conversationId} toolCalls=${opts.toolCallCount}`
      )
      opts.onChunk({
        type: 'text',
        content: fallbackMessage
      } as StreamChunk)
    }

    return { recovered, text: recoveredText }
  }

  /**
   * Plan-mode recovery: the model tried a blocked Write/Edit to author a plan.
   * Fire a short follow-up turn that allows ONLY the control-actions tools
   * (emit_plan) and instruct the model to re-deliver its plan via emit_plan.
   *
   * This guarantees the user still gets a plan card even when the model slips,
   * complementing the prompt steering (Layer 1) and bug-report suppression (Layer 3).
   */
  async attemptPlanToolRecovery(opts: PlanToolRecoveryOptions): Promise<PlanToolRecoveryResult> {
    if (!opts.mcpConfigPath) {
      this.log.warn(
        `[PIPELINE:plan-tool-recovery-skipped] No MCP config path — cannot mount emit_plan for conversationId=${opts.conversationId}`
      )
      return { attempted: false }
    }

    this.log.warn(
      `[PIPELINE:plan-tool-recovery] conversationId=${opts.conversationId} — re-issuing plan via emit_plan after a blocked Write/Edit`
    )

    const prompt =
      '[System: Your last action tried to Write/Edit a file, which is blocked in Plan mode ' +
      '("No such tool available"). Re-deliver that plan NOW by calling the emit_plan tool with ' +
      'type, title, and phases (referencing the real file paths you already identified). ' +
      'Do NOT use Write or Edit — emit_plan is the only way to deliver a plan. Do not write any other text.]'

    // Defence-in-depth: 2-minute per-chunk watchdog prevents an unbounded
    // recovery turn from wedging the session.
    const RECOVERY_TIMEOUT_MS = 120_000

    try {
      const rawIter = opts.cliExecutor.execute({
        prompt,
        systemPrompt: opts.systemPrompt,
        model: opts.model,
        cwd: opts.workspacePath,
        permissionMode: 'plan',
        // Only the control-actions tools (emit_plan / ask_user) — no Read/Write/etc.
        allowedTools: [...MCP_TOOLS.CONTROL_ACTIONS._ALL_NAMES],
        disallowedTools: [
          'Write',
          'Edit',
          'MultiEdit',
          'Agent',
          'Task',
          'local_agent',
          'ToolSearch',
          'ExitPlanMode',
          'AskUserQuestion'
        ],
        mcpConfigPath: opts.mcpConfigPath,
        maxTurns: 2,
        resume: opts.sessionId,
        agentId: 'specialist',
        effort: 'low'
      })

      for await (const chunk of this.withChunkTimeout(rawIter, RECOVERY_TIMEOUT_MS, 'plan-tool-recovery')) {
        if ('_meta' in chunk && chunk._meta) {
          const meta = chunk._meta as ExecutorResult
          if (meta.sessionId && opts.conversationId) {
            opts.onSessionCapture(meta.sessionId)
            try {
              conversationRepository.updateSessionId(opts.conversationId, meta.sessionId)
            } catch {
              /* ignore */
            }
          }
          opts.onTokens(meta.tokenUsage.input + meta.tokenUsage.output)
          usageTrackerService.recordUsage({
            feature: 'plan_recovery',
            model: opts.model,
            workspaceId: opts.workspaceId ?? null,
            conversationId: opts.conversationId,
            tokens: {
              input: meta.tokenUsage.input,
              output: meta.tokenUsage.output,
              cacheRead: meta.tokenUsage.cacheReadInputTokens,
              cacheCreation: meta.tokenUsage.cacheCreationInputTokens
            }
          })
        } else {
          // Forward all chunks (the emit_plan tool fires via the control-actions
          // MCP callbacks wired into the cached config; tool chunks are filtered
          // by the chunk router, plan delivery flows through the control path).
          opts.onChunk(chunk)
        }
      }
      this.log.info(`[PIPELINE:plan-tool-recovery-done] conversationId=${opts.conversationId}`)
      return { attempted: true }
    } catch (err) {
      this.log.error('[PIPELINE:plan-tool-recovery-failed]', err)
      return { attempted: false }
    }
  }
}

/**
 * S8: Tool Activity Accumulator — tracks what the local LLM discovers during a session.
 *
 * Runs at the AgentSessionService level (not inside the SDK executor) where we
 * have access to full chunk data. Records tool calls with their targets and
 * output sizes so other strategies can build structured summaries (S6),
 * plan state (S3), auto-continue context (S4), and compaction decisions (S7).
 *
 * The existing ToolTracker (sdk-executor/tool-tracker.ts) only maps IDs→names.
 * This accumulator provides richer tracking at the application level.
 */

export interface ToolActivityEntry {
  toolName: string
  filePath?: string
  /** Approximate output length in characters */
  outputLen: number
  timestamp: number
}

/**
 * Accumulates tool activity for a single message exchange.
 * Reset between messages via `reset()`.
 */
export class ToolActivityAccumulator {
  private entries: ToolActivityEntry[] = []

  /**
   * Record a tool use event with its output metadata.
   * Called from processContentChunk() for tool_use and tool_result events.
   */
  record(entry: { toolName: string; input?: unknown; outputLength: number }): void {
    const filePath = this.extractFilePath(entry.toolName, entry.input)
    this.entries.push({
      toolName: entry.toolName,
      filePath,
      outputLen: entry.outputLength,
      timestamp: Date.now()
    })
  }

  /**
   * Get deduplicated list of file paths explored during this session.
   * Useful for S6 (summary) and S4 (auto-continue context).
   */
  getExploredFiles(): string[] {
    const paths = new Set<string>()
    for (const entry of this.entries) {
      if (entry.filePath) paths.add(entry.filePath)
    }
    return [...paths]
  }

  /**
   * Build a condensed discovery summary for context injection.
   * Used by S4 (auto-continue) and S6 (conversation summary).
   *
   * @param maxChars Maximum output size in characters
   */
  buildDiscoverySummary(maxChars: number): string {
    if (this.entries.length === 0) return ''

    const parts: string[] = []
    let charCount = 0

    // Tool call count
    const toolLine = `Tool calls: ${this.entries.length}`
    parts.push(toolLine)
    charCount += toolLine.length

    // Files explored (deduplicated)
    const files = this.getExploredFiles()
    if (files.length > 0) {
      const filesLine = `Files explored: ${files.join(', ')}`
      if (charCount + filesLine.length + 1 <= maxChars) {
        parts.push(filesLine)
        charCount += filesLine.length + 1
      } else {
        // Truncate file list
        const truncated = `Files explored: ${files.slice(0, 5).join(', ')}${files.length > 5 ? ` (+${files.length - 5} more)` : ''}`
        parts.push(truncated)
        charCount += truncated.length + 1
      }
    }

    // Tool breakdown (most-used tools)
    const toolCounts = new Map<string, number>()
    for (const entry of this.entries) {
      toolCounts.set(entry.toolName, (toolCounts.get(entry.toolName) ?? 0) + 1)
    }
    const topTools = [...toolCounts.entries()]
      .sort((a, b) => b[1] - a[1])
      .slice(0, 5)
      .map(([name, count]) => `${name}(${count})`)
      .join(', ')
    if (topTools) {
      const toolsLine = `Tools used: ${topTools}`
      if (charCount + toolsLine.length + 1 <= maxChars) {
        parts.push(toolsLine)
      }
    }

    return parts.join('\n')
  }

  /**
   * Estimate total tokens consumed by tool results so far.
   * Uses chars / 3.5 approximation.
   */
  getEstimatedTokensConsumed(): number {
    let totalChars = 0
    for (const entry of this.entries) {
      totalChars += entry.outputLen
    }
    return Math.ceil(totalChars / 3.5)
  }

  /** Get the raw entry count */
  get count(): number {
    return this.entries.length
  }

  /** Get all entries (for plan state persistence) */
  getEntries(): readonly ToolActivityEntry[] {
    return this.entries
  }

  /** Reset state for a new message exchange */
  reset(): void {
    this.entries = []
  }

  /**
   * Extract a file path from tool input, if present.
   * Handles both raw object inputs (from SDK) and summarized string inputs
   * produced by `summarizeToolInput()` in agent-base.service.ts.
   */
  private extractFilePath(toolName: string, input: unknown): string | undefined {
    // F1: Handle string input from summarizeToolInput().
    // Read/Write/Edit summaries are just the file path (e.g. "src/main/foo.ts").
    // Grep summaries look like "/pattern/ in src/..." — extract path after " in ".
    if (typeof input === 'string') {
      if (input.includes('/') && !input.includes(' ')) return input
      const inMatch = input.match(/ in (.+)$/)
      if (inMatch) return inMatch[1]
      return undefined
    }

    if (!input || typeof input !== 'object') return undefined
    const inp = input as Record<string, unknown>

    // Direct file_path parameter (Read, Edit, Write, FileOutline, etc.)
    if (typeof inp.file_path === 'string') return inp.file_path
    if (typeof inp.filePath === 'string') return inp.filePath

    // Glob pattern can hint at directory
    if (toolName === 'Glob' && typeof inp.path === 'string') return inp.path

    // Grep path parameter
    if (toolName === 'Grep' && typeof inp.path === 'string') return inp.path

    return undefined
  }
}

/**
 * S3: Local Plan State Persistence — saves plan progress across sessions for local LLMs.
 *
 * Stores discovered context, partial plans, and continuation state in SQLite
 * so that when a local LLM session is interrupted (context overflow, max_turns,
 * error), the next attempt can resume from where it left off.
 *
 * The `local_plan_state` table is created by migration 87.
 */

import { getDatabase } from '../db/index'
import { chatAgentLogger } from '../logger'

const log = chatAgentLogger

// ── Types ──

export interface DiscoveredContext {
  filesExplored: string[]
  keyFindings: string[]
  planItems: string[]
  nextSteps: string[]
}

export interface LocalPlanState {
  id: string
  conversationId: string
  workspaceId: string
  originalRequest: string
  discoveredContext: DiscoveredContext
  planText: string
  status: 'in_progress' | 'completed' | 'abandoned'
  continuationCount: number
  createdAt: string
  updatedAt: string
}

interface PlanStateRow {
  id: string
  conversation_id: string
  workspace_id: string
  original_request: string
  discovered_context: string
  plan_text: string | null
  status: string
  continuation_count: number
  created_at: string
  updated_at: string
}

function mapRow(row: PlanStateRow): LocalPlanState {
  let discoveredContext: DiscoveredContext
  try {
    discoveredContext = JSON.parse(row.discovered_context) as DiscoveredContext
  } catch {
    discoveredContext = { filesExplored: [], keyFindings: [], planItems: [], nextSteps: [] }
  }
  return {
    id: row.id,
    conversationId: row.conversation_id,
    workspaceId: row.workspace_id,
    originalRequest: row.original_request,
    discoveredContext,
    planText: row.plan_text ?? '',
    status: row.status as LocalPlanState['status'],
    continuationCount: row.continuation_count,
    createdAt: row.created_at,
    updatedAt: row.updated_at
  }
}

// ── Service ──

export class LocalPlanStateService {
  /**
   * Create or update plan state for a conversation.
   * Uses INSERT OR REPLACE (upsert) keyed on conversation_id.
   */
  upsert(params: {
    conversationId: string
    workspaceId: string
    originalRequest: string
    discoveredContext: DiscoveredContext
    planText?: string
  }): void {
    const db = getDatabase()
    const { conversationId, workspaceId, originalRequest, discoveredContext, planText } = params

    // Guard: skip save when the conversation doesn't exist in the DB.
    // Grill/audit sessions use synthetic conversation IDs (e.g. "grill-requirements-*")
    // that are never inserted into the conversations table — attempting an INSERT here
    // would violate the FOREIGN KEY constraint on local_plan_state.conversation_id.
    const convExists = db.prepare('SELECT 1 FROM conversations WHERE id = ?').get(conversationId)
    if (!convExists) {
      log.debug(`[plan-state] conversation ${conversationId} not persisted — skipping plan-state save`)
      return
    }

    // Check if state already exists for this conversation
    const existing = db
      .prepare('SELECT id, continuation_count FROM local_plan_state WHERE conversation_id = ?')
      .get(conversationId) as { id: string; continuation_count: number } | undefined

    if (existing) {
      db.prepare(
        `UPDATE local_plan_state
         SET discovered_context = ?, plan_text = ?, continuation_count = ?,
             updated_at = datetime('now')
         WHERE id = ?`
      ).run(
        JSON.stringify(discoveredContext),
        planText ?? '',
        existing.continuation_count + 1,
        existing.id
      )
      log.info(
        `[S3:plan-state-updated] conversationId=${conversationId} continuations=${existing.continuation_count + 1}`
      )
    } else {
      db.prepare(
        `INSERT INTO local_plan_state
           (conversation_id, workspace_id, original_request, discovered_context, plan_text)
         VALUES (?, ?, ?, ?, ?)`
      ).run(
        conversationId,
        workspaceId,
        originalRequest,
        JSON.stringify(discoveredContext),
        planText ?? ''
      )
      log.info(`[S3:plan-state-created] conversationId=${conversationId}`)
    }
  }

  /** Get plan state for a specific conversation */
  getForConversation(conversationId: string): LocalPlanState | null {
    const db = getDatabase()
    const row = db
      .prepare('SELECT * FROM local_plan_state WHERE conversation_id = ?')
      .get(conversationId) as PlanStateRow | undefined
    return row ? mapRow(row) : null
  }

  /** Get the latest in-progress plan state for a workspace */
  getLatestForWorkspace(workspaceId: string): LocalPlanState | null {
    const db = getDatabase()
    const row = db
      .prepare(
        `SELECT * FROM local_plan_state
         WHERE workspace_id = ? AND status = 'in_progress'
         ORDER BY updated_at DESC LIMIT 1`
      )
      .get(workspaceId) as PlanStateRow | undefined
    return row ? mapRow(row) : null
  }

  /** Mark a plan as completed */
  markCompleted(conversationId: string): void {
    const db = getDatabase()
    db.prepare(
      `UPDATE local_plan_state
       SET status = 'completed', updated_at = datetime('now')
       WHERE conversation_id = ?`
    ).run(conversationId)
  }

  /** Mark a plan as abandoned (e.g. new conversation started in same workspace) */
  markAbandoned(conversationId: string): void {
    const db = getDatabase()
    db.prepare(
      `UPDATE local_plan_state
       SET status = 'abandoned', updated_at = datetime('now')
       WHERE conversation_id = ?`
    ).run(conversationId)
  }

  /**
   * F6: Mark all in-progress plans for a workspace as abandoned,
   * except for the current conversation. Called on conversation switch
   * to prevent stale plans from polluting getLatestForWorkspace().
   */
  markAbandonedForWorkspace(workspaceId: string, excludeConversationId?: string): void {
    const db = getDatabase()
    if (excludeConversationId) {
      db.prepare(
        `UPDATE local_plan_state
         SET status = 'abandoned', updated_at = datetime('now')
         WHERE workspace_id = ? AND status = 'in_progress' AND conversation_id != ?`
      ).run(workspaceId, excludeConversationId)
    } else {
      db.prepare(
        `UPDATE local_plan_state
         SET status = 'abandoned', updated_at = datetime('now')
         WHERE workspace_id = ? AND status = 'in_progress'`
      ).run(workspaceId)
    }
  }
}

export const localPlanStateService = new LocalPlanStateService()

/**
 * S12: Message-Based Context Reconstruction — rebuilds context from stored messages.
 *
 * When session resume isn't available (local LLMs have no SDK sessions),
 * this reconstructor builds a condensed context from the conversation's
 * stored messages + plan state. No LLM call needed — just DB reads and
 * string concatenation.
 *
 * If the system prompt prefix is byte-identical across turns (S5 produces
 * a stable prompt), oMLX's SSD KV cache restores it instantly (~<5s TTFT
 * instead of 30-90s on long contexts).
 */

import type { ContextWindowTier } from './context-management'
import { messageRepository, conversationRepository } from '../db/repositories'
import { localPlanStateService } from './local-plan-state.service'
import { chatAgentLogger } from '../logger'
import { sanitizePromptInput } from './sanitize-prompt-input'

const log = chatAgentLogger

/**
 * Reconstruct context from stored messages and plan state.
 * Returns null if there's no useful context to reconstruct.
 */
export class LocalContextReconstructor {
  /**
   * Build a context summary from stored conversation history.
   *
   * @param conversationId - The conversation to reconstruct context from
   * @param maxTokenBudget - Maximum tokens to spend on context (typically 25% of window)
   * @param tier - Context window tier for budget scaling
   * @returns A structured context string, or null if no useful context exists
   */
  buildContextFromHistory(params: {
    conversationId: string
    maxTokenBudget: number
    tier: ContextWindowTier
  }): string | null {
    const { conversationId, maxTokenBudget } = params
    const maxChars = Math.floor(maxTokenBudget * 3.5) // Convert tokens → chars

    const parts: string[] = []
    let charCount = 0

    // 1. Load plan state (S3) — most structured, highest priority
    try {
      const planState = localPlanStateService.getForConversation(conversationId)
      if (planState) {
        const planSection = this.buildPlanStateSection(planState)
        if (planSection && charCount + planSection.length <= maxChars) {
          parts.push(planSection)
          charCount += planSection.length
        }
      }
    } catch {
      /* plan state table may not exist yet */
    }

    // 2. Load conversation summary (S6) — if plan state wasn't available
    if (parts.length === 0) {
      try {
        const summary = conversationRepository.getSummary(conversationId)
        if (summary && charCount + summary.length <= maxChars) {
          parts.push(`## Previous Summary\n${summary}`)
          charCount += summary.length

          // Warn when injecting a potentially stale summary — helps diagnose
          // cases where the model receives outdated context.
          try {
            const lastMsgTime = messageRepository.getLastMessageTimestamp(conversationId)
            if (lastMsgTime) {
              const ageDays = (Date.now() - new Date(lastMsgTime).getTime()) / 86400000
              if (ageDays > 3) {
                log.warn(
                  `[S12:stale-summary] conversationId=${conversationId} — injecting summary from ${Math.round(ageDays)}d-old conversation`
                )
              }
            }
          } catch { /* non-fatal */ }
        }
      } catch {
        /* non-fatal */
      }
    }

    // 3. Load recent messages — user messages verbatim, assistant truncated
    // F5: Use findRecentByConversation with SQL LIMIT to avoid loading
    // entire conversation history (wasteful for 50+ message conversations).
    try {
      const messages = messageRepository.findRecentByConversation(conversationId, 10)
      if (messages.length > 0) {
        const messageSection = this.buildMessageSection(messages, maxChars - charCount)
        if (messageSection) {
          parts.push(messageSection)
        }
      }
    } catch {
      /* non-fatal */
    }

    if (parts.length === 0) return null

    let result = parts.join('\n\n')
    // PROMPT-06: Enforce total budget — join separators add chars not tracked by charCount
    if (result.length > maxChars) {
      result = result.slice(0, maxChars)
    }
    log.info(
      `[S12:context-reconstructed] conversationId=${conversationId} ` +
        `parts=${parts.length} chars=${result.length}`
    )
    return result
  }

  /**
   * Build a section from plan state data.
   */
  private buildPlanStateSection(planState: {
    originalRequest: string
    discoveredContext: {
      filesExplored: string[]
      keyFindings: string[]
      planItems: string[]
      nextSteps: string[]
    }
    planText: string
    continuationCount: number
  }): string | null {
    const parts: string[] = []

    if (planState.originalRequest) {
      parts.push(`### Original Request\n${sanitizePromptInput(planState.originalRequest).slice(0, 500)}`)
    }

    const ctx = planState.discoveredContext
    if (ctx.filesExplored.length > 0) {
      parts.push(`### Files Explored\n${ctx.filesExplored.map((f) => `- ${f}`).join('\n')}`)
    }
    if (ctx.planItems.length > 0) {
      parts.push(`### Plan Items\n${ctx.planItems.map((p) => sanitizePromptInput(p)).join('\n')}`)
    }
    if (ctx.keyFindings.length > 0) {
      parts.push(`### Key Findings\n${ctx.keyFindings.map((f) => sanitizePromptInput(f)).join('\n')}`)
    }

    if (planState.planText && planState.planText.length > 50) {
      parts.push(`### Partial Plan\n${sanitizePromptInput(planState.planText).slice(0, 1000)}`)
    }

    if (parts.length === 0) return null
    return `## Saved Plan State (continuation #${planState.continuationCount})\n\n${parts.join('\n\n')}`
  }

  /**
   * Build a section from recent messages.
   * User messages included verbatim (usually short).
   * Assistant messages truncated to first 300 chars.
   */
  private buildMessageSection(
    messages: { role: string; contentMd: string }[],
    maxChars: number
  ): string | null {
    // Take last N messages that fit in budget
    const recent = messages.slice(-10) // At most last 10
    const lines: string[] = []
    let charCount = 0

    for (const msg of recent) {
      const role = msg.role === 'user' ? 'User' : 'Assistant'
      const content = sanitizePromptInput(
        msg.role === 'user'
          ? msg.contentMd.slice(0, 500) // User messages are usually short
          : msg.contentMd.slice(0, 300) // Truncate assistant messages
      )

      const line = `**${role}:** ${content}${content.length < msg.contentMd.length ? '...' : ''}`
      if (charCount + line.length > maxChars) break

      lines.push(line)
      charCount += line.length
    }

    if (lines.length === 0) return null
    return `## Recent Messages\n${lines.join('\n\n')}`
  }
}

export const localContextReconstructor = new LocalContextReconstructor()

/**
 * Sanitizes user-provided values before interpolation into prompt template literals.
 *
 * Defense-in-depth against prompt injection via user-facing fields
 * (idea titles, descriptions, project names, workspace names, goals).
 * The actual threat model is low (desktop app, user is the prompt author),
 * but this prevents accidental markdown heading patterns from being
 * interpreted as structural prompt elements.
 *
 * Strips:
 * - Markdown heading patterns (`#+ `) that could override prompt sections
 * - Code fence markers (```) that could inject fake structured blocks
 * - XML-like system tags that could mimic system-level instructions
 */
export function sanitizePromptInput(value: string): string {
  return (
    value
      // Strip markdown headings (## System Override, etc.)
      .replace(/^#{1,6}\s+/gm, '')
      // Strip code fence openers/closers that could inject fake structured blocks
      // (e.g., ```grill-evaluation or ```goal-plan)
      .replace(/^`{3,}[\w-]*$/gm, '')
      // Strip XML-like system tags that could mimic internal instructions
      .replace(/<\/?(?:system|mode-context|instructions)[^>]*>/gi, '')
  )
}

/**
 * IPC Bridge — Unix domain socket server for MCP server ↔ Electron communication.
 *
 * When using the CLI executor, MCP servers run as external stdio processes (spawned
 * by Claude CLI). They can't directly call Electron IPC. This bridge provides a
 * Unix domain socket that externalized MCP servers connect to for event delivery.
 *
 * Events:
 *   plan     → control-actions server emitted a structured plan
 *   askUser  → control-actions server emitted clarifying questions
 *   memory   → control-actions server emitted a memory
 *
 * The main process creates the socket server before spawning the CLI. The socket
 * path is passed to MCP servers via IPC_SOCKET_PATH environment variable.
 */

import { createServer, type Server as NetServer, type Socket } from 'node:net'
import { unlinkSync, existsSync } from 'node:fs'
import { join } from 'node:path'
import { tmpdir } from 'node:os'
import { randomUUID } from 'node:crypto'
import { EventEmitter } from 'node:events'
import log from 'electron-log/main'

const bridgeLog = log.scope('IPCBridge')

/**
 * Event types emitted by externalized MCP servers.
 */
export interface IpcBridgeEvent {
  type:
    | 'plan'
    | 'askUser'
    | 'memory'
    | 'askUserResponse'
    | 'permission'
    | 'permissionResponse'
    | 'fileEdited'
    | 'memoryResponse'
    | 'phaseProgress'
  payload: unknown
  /** For request-response patterns: correlates response to request. */
  requestId?: string
  timestamp: number
}

/**
 * IPC Bridge server — listens on a Unix domain socket for events from
 * externalized MCP servers.
 *
 * Usage:
 *   const bridge = new IpcBridge()
 *   const socketPath = await bridge.start()
 *   // Pass socketPath to MCP server as IPC_SOCKET_PATH env var
 *   bridge.on('plan', (payload) => { ... })
 *   bridge.on('askUser', (payload) => { ... })
 *   bridge.on('memory', (payload) => { ... })
 */
export class IpcBridge extends EventEmitter {
  private server: NetServer | null = null
  private socketPath: string | null = null
  private clients: Set<Socket> = new Set()
  private _isListening = false

  /**
   * Start the Unix domain socket server.
   * Returns the socket path for passing to MCP servers.
   */
  async start(): Promise<string> {
    if (this._isListening && this.socketPath) {
      return this.socketPath
    }

    // Generate unique socket path in temp directory
    const id = randomUUID().slice(0, 8)
    this.socketPath = join(tmpdir(), `code-atelier-ipc-${id}.sock`)

    // Clean up any stale socket file
    if (existsSync(this.socketPath)) {
      try {
        unlinkSync(this.socketPath)
      } catch {
        // Non-fatal — socket may be in use
      }
    }

    return new Promise<string>((resolve, reject) => {
      this.server = createServer((client: Socket) => {
        this.clients.add(client)
        bridgeLog.info(`[ipc-bridge] Client connected (total: ${this.clients.size})`)

        let buffer = ''

        client.on('data', (data: Buffer) => {
          buffer += data.toString('utf-8')

          // Process complete NDJSON lines
          let newlineIdx: number
          while ((newlineIdx = buffer.indexOf('\n')) !== -1) {
            const line = buffer.slice(0, newlineIdx).trim()
            buffer = buffer.slice(newlineIdx + 1)

            if (!line) continue

            try {
              const event = JSON.parse(line) as IpcBridgeEvent
              this.handleEvent(event)
            } catch {
              bridgeLog.warn(`[ipc-bridge] Malformed event: ${line.slice(0, 120)}`)
            }
          }
        })

        client.on('close', () => {
          this.clients.delete(client)
          bridgeLog.info(`[ipc-bridge] Client disconnected (total: ${this.clients.size})`)
        })

        client.on('error', (err) => {
          bridgeLog.warn(`[ipc-bridge] Client error: ${err.message}`)
          this.clients.delete(client)
        })
      })

      this.server.on('error', (err) => {
        bridgeLog.error(`[ipc-bridge] Server error: ${err.message}`)
        reject(err)
      })

      this.server.listen(this.socketPath!, () => {
        this._isListening = true
        bridgeLog.info(`[ipc-bridge] Listening on ${this.socketPath}`)
        resolve(this.socketPath!)
      })
    })
  }

  /**
   * Get the socket path (for passing as IPC_SOCKET_PATH to MCP servers).
   */
  getSocketPath(): string | null {
    return this.socketPath
  }

  /**
   * Check if the bridge is actively listening.
   */
  isListening(): boolean {
    return this._isListening
  }

  /**
   * Send data to all connected clients (MCP servers).
   * Used for request-response patterns like ask_user — the Electron main
   * process sends the user's response back to the control-actions MCP server.
   */
  sendToClients(data: IpcBridgeEvent): void {
    const payload = JSON.stringify(data) + '\n'
    for (const client of this.clients) {
      if (!client.destroyed) {
        try {
          client.write(payload)
        } catch (err) {
          bridgeLog.warn(`[ipc-bridge] Failed to write to client: ${(err as Error).message}`)
        }
      }
    }
  }

  /**
   * Send a response to an ask_user request.
   * Convenience wrapper around sendToClients for the common ask_user pattern.
   */
  sendAskUserResponse(requestId: string, response: string): void {
    this.sendToClients({
      type: 'askUserResponse',
      requestId,
      payload: { response },
      timestamp: Date.now()
    })
    bridgeLog.info(`[ipc-bridge] Sent askUserResponse for requestId=${requestId}`)
  }

  /**
   * B-8: Send a memory response back to the requesting plugin/tool.
   * Used when a memory read request returns results from the main process.
   */
  sendMemoryResponse(
    requestId: string,
    result: { memories?: Array<{ content: string; category?: string; tier?: number }> }
  ): void {
    this.sendToClients({
      type: 'memoryResponse',
      requestId,
      payload: result,
      timestamp: Date.now()
    })
    bridgeLog.info(
      `[ipc-bridge] Sent memoryResponse for requestId=${requestId} ` +
        `(${result.memories?.length ?? 0} entries)`
    )
  }

  /**
   * Send a response to a permission_prompt request.
   * Routes the user's approve/deny decision back to the control-actions MCP server.
   */
  sendPermissionResponse(requestId: string, approved: boolean, input?: unknown): void {
    this.sendToClients({
      type: 'permissionResponse',
      requestId,
      payload: { approved, input },
      timestamp: Date.now()
    })
    bridgeLog.info(
      `[ipc-bridge] Sent permissionResponse for requestId=${requestId} approved=${approved}`
    )
  }

  /**
   * Stop the socket server and clean up.
   */
  async stop(): Promise<void> {
    if (!this.server) return

    // Close all client connections
    for (const client of this.clients) {
      client.destroy()
    }
    this.clients.clear()

    return new Promise<void>((resolve) => {
      this.server!.close(() => {
        this._isListening = false

        // Clean up socket file
        if (this.socketPath && existsSync(this.socketPath)) {
          try {
            unlinkSync(this.socketPath)
          } catch {
            // Non-fatal
          }
        }

        this.server = null
        bridgeLog.info('[ipc-bridge] Stopped')
        resolve()
      })
    })
  }

  // ── Private ──

  private handleEvent(event: IpcBridgeEvent): void {
    bridgeLog.info(`[ipc-bridge] Event: ${event.type}`)

    switch (event.type) {
      case 'plan':
        this.emit('plan', event.payload)
        break
      case 'askUser':
        // Pass requestId so the session can correlate the response
        this.emit('askUser', event.payload, event.requestId)
        break
      case 'memory':
        // B-8: Pass requestId so the handler can send a response back
        this.emit('memory', event.payload, event.requestId)
        break
      case 'memoryResponse':
        // Response flowing back to plugin — already handled via sendToClients
        break
      case 'askUserResponse':
        // Response from Electron → MCP server (handled via sendToClients, not events)
        break
      case 'permission':
        // Permission request from plugin — surface in Electron UI for approval
        this.emit('permission', event.payload, event.requestId)
        break
      case 'permissionResponse':
        // Response from Electron → MCP server (handled via sendToClients, not events)
        break
      case 'fileEdited':
        // File edited notification from plugin — trigger re-indexing
        this.emit('fileEdited', event.payload)
        break
      case 'phaseProgress':
        // Plan phase progress from control-actions server
        this.emit('phaseProgress', event.payload)
        break
      default:
        bridgeLog.warn(`[ipc-bridge] Unknown event type: ${event.type}`)
    }
  }
}

/**
 * AgentStreamProcessor — handles stream chunk processing, token tracking,
 * context pressure evaluation, and compaction threshold management.
 *
 * Extracted from AgentSessionService to reduce god-class complexity.
 * Holds a back-reference to the session for state access.
 *
 * @internal Not for use outside the agent-session module.
 */

import type {
  AgentSessionHost,
  StreamLoopState,
  StreamChunk,
  ExecutorResult
} from './agent-session-host'
import type { ContextWindowTier } from './context-management'
import {
  CLAUDE_DEFAULT_CONTEXT_WINDOW,
  CLAUDE_1M_CONTEXT_WINDOW,
  MCP_TOOLS,
  resolveModelAction
} from '../../shared/constants'
import { resolveContextTier } from './context-management'
import {
  classifyCompaction,
  resolveCompactionThresholds as resolveCompactionThresholdsPolicy,
  resolveAppliedThresholds
} from './compaction-policy'
import { resolveModelFromSnapshot } from './snapshot-model-resolver'
import { featureForAgentRole } from './usage-tracker.service'
import { supportsContext1M } from '../../shared/constants'
import { conversationRepository, turnUsageRepository } from '../db/repositories'

export class AgentStreamProcessor {
  private readonly s: AgentSessionHost

  constructor(session: unknown) {
    this.s = session as AgentSessionHost
  }

  // ── processMetaChunk ──────────────────────────────────────────────────

  async processMetaChunk(
    meta: ExecutorResult,
    ctx: {
      conversationId: string
      turnCount: number
      streamState: StreamLoopState
    }
  ): Promise<void> {
    const { conversationId, turnCount, streamState } = ctx
    streamState.messageStopReceived = true

    if (meta.sessionId && conversationId) {
      // Detect silent resume failure: if we passed --resume with a
      // specific session ID and the CLI returned a DIFFERENT one,
      // the server created a new session instead of resuming.
      const expectedSessionId = this.s.sessionMap.get(conversationId)
      if (expectedSessionId && meta.sessionId !== expectedSessionId) {
        this.s.log.warn(
          `[PIPELINE:resume-mismatch] Expected session ${expectedSessionId}, got ${meta.sessionId} — resume failed silently`
        )
      }

      this.s.sessionMap.set(conversationId, meta.sessionId)
      this.s.log.info('Session captured for conversation:', conversationId)
      try {
        conversationRepository.updateSessionId(conversationId, meta.sessionId)
      } catch (err) {
        this.s.log.error('Failed to persist session ID:', err)
      }
    }

    if (meta.sessionTitle && conversationId) {
      try {
        const conv = conversationRepository.findById(conversationId)
        if (conv && (conv.title === 'New Conversation' || conv.title === '')) {
          conversationRepository.updateTitle(conversationId, meta.sessionTitle)
          this.s.log.info(`[PIPELINE:auto-title] "${meta.sessionTitle}" for ${conversationId}`)
        }
      } catch (err) {
        this.s.log.warn('Failed to auto-name conversation from session_title:', err)
      }
    }

    if (meta.terminalReason) {
      streamState.lastTerminalReason = meta.terminalReason
      this.s.log.info(`[PIPELINE:terminal-reason] ${meta.terminalReason} for ${conversationId}`)
    }

    const isBuild = this.s.currentMode !== 'plan'
    const modelAction = resolveModelAction(this.s.adapter.role, isBuild)
    const resolvedModel = resolveModelFromSnapshot(
      conversationId,
      this.s.workspacePath!,
      modelAction,
      isBuild
    )
    const { totalTokens } = this.s.tokenTracker.recordTurn(meta, {
      turnCount,
      conversationId,
      dbSessionId: this.s.dbSessionId,
      workspacePath: this.s.workspacePath!,
      feature: featureForAgentRole(this.s.adapter.role),
      agentType: this.s.adapter.agentId,
      model: resolvedModel,
      workspaceId: this.s.workspaceId
    })
    // TOKEN-OVERFLOW-01: Guard against NaN/negative/undefined values from malformed
    // executor reports. A single corrupt value would silently poison all downstream
    // budget calculations (NaN + number = NaN propagates through compaction checks).
    const safeToken = (v: unknown): number => {
      const n = Number(v)
      return Number.isFinite(n) && n >= 0 ? n : 0
    }

    this.s.tokenUsage += safeToken(totalTokens)
    this.s.inputTokens += safeToken(meta.tokenUsage.input)
    this.s.outputTokens += safeToken(meta.tokenUsage.output)
    this.s.cacheReadTokens += safeToken(meta.tokenUsage.cacheReadInputTokens)
    this.s.cacheCreationTokens += safeToken(meta.tokenUsage.cacheCreationInputTokens)

    // Context-window occupancy = the prompt size of the LATEST API round-trip
    // (input + cache_read + cache_creation of the most recent message_start),
    // exposed by the executor as contextWindowTokens.
    //
    // We deliberately do NOT sum these fields across the turn: a single user
    // message drives an agentic loop with many round-trips, each re-reading the
    // full cached context. Summing cache_read across round-trips over-counts
    // occupancy ~5-10x (a plan turn would report ~42% of a 1M window after one
    // message). The snapshot reflects true current occupancy.
    //
    // Fallback to the summed totals only when the backend doesn't report a
    // per-call snapshot (e.g. OpenCode, or a stream with no message_start usage).
    const summedContextTokens =
      safeToken(meta.tokenUsage.input) +
      safeToken(meta.tokenUsage.cacheReadInputTokens) +
      safeToken(meta.tokenUsage.cacheCreationInputTokens)
    const contextWindowTokens = safeToken(meta.tokenUsage.contextWindowTokens)
    const totalContextTokens = contextWindowTokens > 0 ? contextWindowTokens : summedContextTokens
    const consumedContextTokens = totalContextTokens

    // Update lastContextTokens for all backends (badge, compact modal, etc.)
    this.s.lastContextTokens = totalContextTokens

    // Push live context update to the renderer
    if (consumedContextTokens > 0) {
      const effectiveWindow = this.s.effectiveContextWindow ?? CLAUDE_DEFAULT_CONTEXT_WINDOW
      // F11: Reuse token tracker's cache efficiency calculation (single source of truth)
      // instead of duplicating the cacheRead / (input + cacheRead) formula here.
      const cacheReport = this.s.tokenTracker.getCacheEfficiency()
      const cacheHitRate = Math.round(cacheReport.hitRate)
      this.s.emit('chunk', {
        type: 'context_usage_update',
        content: '',
        contextUsageUpdate: {
          inputTokens: consumedContextTokens,
          contextWindowSize: effectiveWindow,
          percentage: Math.round((consumedContextTokens / effectiveWindow) * 100),
          cacheHitRate
        }
      } as StreamChunk)
    }

    this.checkCompaction(totalContextTokens)

    // Evaluate context pressure for local LLMs AND Claude 200K models.
    const isLocal = this.s.llmProvider === 'local-llm'
    const effectiveWindow = this.s.effectiveContextWindow
    const is200KClaude = !isLocal && effectiveWindow != null && effectiveWindow <= 200_000
    if (isLocal || is200KClaude) {
      const ctxWindow = isLocal
        ? (effectiveWindow ?? this.s.resolveLocalContextWindow())
        : effectiveWindow!
      const pressureRatio = consumedContextTokens / ctxWindow
      if (pressureRatio > 0.85) {
        this.s.emit('chunk', {
          type: 'text',
          content: `\n\n> ⚠️ Context window is ${Math.round(pressureRatio * 100)}% full — consider compacting.\n\n`
        } as StreamChunk)
      }
    }

    // F3: Persist per-turn context tokens to DB for dashboard analytics.
    // Previously referenced undefined `sdkContextData` — now uses the
    // `totalContextTokens` already computed above from CLI token usage fields.
    if (this.s.dbSessionId && conversationId && totalContextTokens > 0) {
      try {
        turnUsageRepository.updateLastTurnContextTokens(conversationId, totalContextTokens)
      } catch (err) {
        this.s.log.warn('Failed to persist context tokens:', err)
      }
    }
  }

  // ── processContentChunk ───────────────────────────────────────────────

  processContentChunk(
    chunk: StreamChunk & { type?: string; content?: string; error?: string; toolName?: string },
    ctx: {
      conversationId: string
      isBuildMode: boolean
      streamState: StreamLoopState
      contextTier?: ContextWindowTier
    }
  ): 'next' | 'break' | 'continue' {
    const { conversationId, streamState } = ctx

    // Error handling (stale session, unexpected abort, budget cap)
    if (chunk.type === 'error') {
      const result = this.handleErrorChunk(chunk, conversationId, streamState)
      if (result !== 'next') return result
    }

    if (chunk.type === 'text' && chunk.content) {
      // Phase-2: Accumulate text on per-conversation context for multi-stream safety
      const streamCtx = this.s.activeStreams?.get(conversationId)
      if (streamCtx) {
        streamCtx.accumulatedText += chunk.content
      } else {
        // Fallback for test doubles without activeStreams
        this.s.accumulatedText += chunk.content
      }
      streamState.hasTextAfterLastTool = true
    }

    // Detect a blocked Write/Edit attempt in Plan mode. Write/Edit aren't on the
    // plan-mode allow-list, so the SDK returns "No such tool available". This is
    // expected (not a bug — see tool-chunk-processor.isExpectedPlanModeBlock), but
    // it means the model tried to author a plan as a file. Flag it so finalizeStream
    // can fire a deterministic emit_plan recovery and the user still gets a plan card.
    if (
      chunk.type === 'tool_result' &&
      this.s.currentMode === 'plan' &&
      typeof chunk.content === 'string' &&
      chunk.content.includes('<tool_use_error>') &&
      chunk.content.includes('No such tool available') &&
      /\b(Write|Edit|MultiEdit)\b/.test(`${chunk.toolName ?? ''} ${chunk.content}`)
    ) {
      streamState.planModeToolBlock = true
      this.s.log.warn(
        `[PIPELINE:plan-mode-tool-block] Blocked Write/Edit in plan mode for conversationId=${conversationId} — will attempt emit_plan recovery`
      )
    }

    if (chunk.type === 'tool_use') {
      const result = this.handleToolUseChunk(chunk, ctx)
      if (result !== 'next') return result
    }

    if (chunk.type === 'subagent_start') {
      const result = this.handleSubagentStartChunk(ctx)
      if (result !== 'next') return result
    }

    // F12: Removed dead `promptSuggestion` event emission — no listener exists.
    // The chunk is already forwarded to the renderer via emit('chunk', chunk) below,
    // which the chunk-router routes through handlePromptSuggestion.

    if (chunk.type === 'api_retry') {
      this.handleApiRetryChunk(chunk, conversationId, streamState)
    }

    if (chunk.type === 'text') this.s.currentStatus = 'writing'
    if (chunk.type === 'tool_use') this.s.currentStatus = 'reviewing'
    this.s.emit('statusUpdate', this.s.getStatus())
    this.s.emit('chunk', chunk)
    return 'next'
  }

  // ── Content chunk handlers ──────────────────────────────────────────────

  private handleErrorChunk(
    chunk: StreamChunk & { error?: string },
    conversationId: string,
    streamState: StreamLoopState
  ): 'next' | 'break' {
    const error = typeof chunk.error === 'string' ? chunk.error : String(chunk.error ?? '')

    if (error.includes('No conversation found with session ID')) {
      this.s.log.warn(
        `[PIPELINE:session-recovery] Stale session detected for conversationId=${conversationId} — initiating recovery`
      )
      this.s.emit('chunk', {
        type: 'session_recovery',
        recoveryPhase: 'started',
        content: 'Session expired — recovering conversation context...'
      } as StreamChunk)
      this.s.clearSession(conversationId)
      try {
        conversationRepository.updateSessionId(conversationId, '')
      } catch (err) {
        this.s.log.error('[PIPELINE:session-recovery] Failed to clear DB session:', err)
      }
      this.s.emit('chunk', {
        type: 'session_recovery',
        recoveryPhase: 'building_context',
        content: 'Rebuilding conversation context from history...'
      } as StreamChunk)
      streamState.sessionRecoveryNeeded = true
      return 'break'
    }

    if (error.includes('Claude Code process aborted by user') && this.s.currentStatus !== 'idle') {
      this.s.log.warn(
        `[PIPELINE:unexpected-abort] Session was aborted without user action — ` +
          `status=${this.s.currentStatus} conversationId=${conversationId}`
      )
      this.s.emit('chunk', {
        type: 'error',
        error:
          'The agent session was interrupted unexpectedly. This can happen during app reloads. Please resend your message to continue.'
      } as StreamChunk)
      return 'break'
    }

    if (error.includes('budget cap exceeded')) {
      this.s.log.warn(
        `[PIPELINE:budget-cap-reached] conversationId=${conversationId} — offering continuation`
      )
      this.s.emit('budgetCapReached', { conversationId, message: error })
      return 'break'
    }

    return 'next'
  }

  private handleToolUseChunk(
    chunk: StreamChunk & { toolName?: string; content?: string },
    ctx: {
      conversationId: string
      isBuildMode: boolean
      streamState: StreamLoopState
      contextTier?: ContextWindowTier
    }
  ): 'next' | 'break' | 'continue' {
    const { conversationId, isBuildMode, streamState } = ctx

    if (chunk.toolName?.startsWith(MCP_TOOLS.CONTROL_ACTIONS._PREFIX)) {
      this.s.log.debug(`[PIPELINE:control-tool-use] ${chunk.toolName}`)
      return 'continue'
    }

    this.s.toolActivityAccumulator.record({
      toolName: chunk.toolName ?? 'unknown',
      input: (chunk as unknown as Record<string, unknown>).toolInput,
      outputLength: chunk.content?.length ?? 0
    })

    streamState.hasTextAfterLastTool = false
    const cbResult = this.s.circuitBreaker.onToolUse({
      isBuildMode,
      accumulatedTextLength: (this.s.activeStreams?.get(conversationId)?.accumulatedText ?? this.s.accumulatedText ?? '').length,
      conversationId,
      isLocalProvider: this.s.llmProvider === 'local-llm',
      contextTier: ctx.contextTier
    })

    if (cbResult.additionalContext) {
      this.s.emit('chunk', {
        type: 'text',
        content: `\n\n> ⚠️ ${cbResult.additionalContext}\n\n`
      } as StreamChunk)
    }

    if (cbResult.broken) {
      return this.applyCircuitBreakerResult(cbResult, conversationId, streamState)
    }

    this.s.circuitBreaker.logToolCall(conversationId, chunk.toolName ?? 'unknown')
    return 'next'
  }

  private applyCircuitBreakerResult(
    _cbResult: { isContinuableBreak?: boolean },
    conversationId: string,
    streamState: StreamLoopState
  ): 'break' {
    // All circuit breaker trips are continuable — we set lastTerminalReason
    // to 'max_turns' so the recovery manager's auto-continue logic picks it up.
    // This replaces the old hard-error path that dead-ended the session.
    this.s.log.info(
      `[PIPELINE:continuable-break] Circuit breaker fired — ` +
        `saving progress and allowing auto-continuation for conversationId=${conversationId}`
    )
    streamState.lastTerminalReason = 'max_turns'
    if (conversationId) {
      this.s.saveCurrentPlanState(conversationId)
    }
    return 'break'
  }

  private handleSubagentStartChunk(ctx: {
    isBuildMode: boolean
    conversationId: string
    streamState: StreamLoopState
    contextTier?: ContextWindowTier
  }): 'next' | 'break' {
    const { isBuildMode, conversationId, streamState } = ctx
    for (let i = 0; i < 10; i++) {
      const cbResult = this.s.circuitBreaker.onToolUse({
        isBuildMode,
        accumulatedTextLength: (this.s.activeStreams?.get(conversationId)?.accumulatedText ?? this.s.accumulatedText ?? '').length,
        conversationId,
        isLocalProvider: this.s.llmProvider === 'local-llm',
        contextTier: ctx.contextTier
      })
      if (cbResult.broken) {
        this.s.log.warn(
          `[PIPELINE:subagent-circuit-break] Sub-agent spawn tripped circuit breaker at ${this.s.circuitBreaker.count} tool calls`
        )
        // Route through same continuable break path as regular tool calls
        return this.applyCircuitBreakerResult(cbResult, conversationId, streamState)
      }
    }
    return 'next'
  }

  private handleApiRetryChunk(
    chunk: StreamChunk & { retryInfo?: { errorStatus?: number | null }; content?: string },
    conversationId: string,
    streamState: StreamLoopState
  ): void {
    const errorStatus = chunk.retryInfo?.errorStatus
    const content = chunk.content ?? ''
    if (
      errorStatus === 529 ||
      errorStatus === 503 ||
      /overloaded|server_is_overloaded/i.test(content)
    ) {
      streamState.overloadDetected = true
      this.s.log.warn(
        `[PIPELINE:overload-detected] API overload detected (status=${errorStatus}) for conversationId=${conversationId}`
      )
    }
  }

  // ── Compaction ────────────────────────────────────────────────────────

  checkCompaction(
    inputTokens: number,
    breakdown?: import('../../shared/types').ContextUsageBreakdown
  ): void {
    const autoThreshold = this.s.compactAutoThreshold
    const suggestThreshold = this.s.compactSuggestThreshold
    const isLocal = this.s.llmProvider === 'local-llm'
    const isAutoCompactEnabled = breakdown?.isAutoCompactEnabled === true

    // Instrumentation: surface the resolved thresholds with every band decision
    // so live runs are observable (Part 3 of the compaction-verification plan).
    this.s.log.info(
      `[compaction:thresholds] inputTokens=${inputTokens} suggest=${suggestThreshold} ` +
        `auto=${autoThreshold} isAutoCompactEnabled=${isAutoCompactEnabled} isLocal=${isLocal}`
    )

    // Pure band classification — all emit/log/state below is side-effect only.
    const decision = classifyCompaction({
      inputTokens,
      suggestThreshold,
      autoThreshold,
      isAutoCompactEnabled,
      compactSuggested: this.s.compactSuggested,
      turnsSinceCompactSuggestion: this.s.turnsSinceCompactSuggestion
    })

    // F15: commit debounce state (reset below warning, advance on debounced suggest).
    this.s.compactSuggested = decision.nextSuggested
    this.s.turnsSinceCompactSuggestion = decision.nextTurns

    if (!decision.level) return

    if (decision.level === 'auto-compact-pending' || decision.level === 'critical') {
      this.s.log.warn(
        `[PIPELINE:compact-critical] Context at ${inputTokens} tokens ` +
          `(threshold=${autoThreshold}) — ${decision.level === 'auto-compact-pending' ? 'SDK auto-compact will handle' : 'critical notification'}`
      )
      this.s.emit('compactNeeded', {
        level: decision.level,
        inputTokens,
        breakdown,
        isLocalProvider: isLocal
      })
      return
    }

    if (decision.level === 'suggest') {
      this.s.log.info(`Context growing large (${inputTokens} input tokens) — suggesting compact`)
      this.s.emit('compactNeeded', {
        level: 'suggest',
        inputTokens,
        breakdown,
        isLocalProvider: isLocal
      })
      return
    }

    // warning
    this.s.log.info(
      `[PIPELINE:compact-warning] Context approaching threshold (${inputTokens}/${suggestThreshold} tokens)`
    )
    this.s.emit('compactNeeded', {
      level: 'warning',
      inputTokens,
      estimatedNextCost: Math.round(inputTokens * 0.05),
      breakdown,
      isLocalProvider: isLocal
    })
  }

  applyCompactionThresholds(settings: Record<string, unknown>): void {
    const isLocal = (settings.llmProvider as string) === 'local-llm'

    if (isLocal) {
      const ctx = this.s.resolveLocalContextWindow()
      const tier = resolveContextTier(ctx)
      const { suggest, auto } = resolveAppliedThresholds({ isLocal: true, localTier: tier })
      this.s.compactSuggestThreshold = suggest
      this.s.compactAutoThreshold = auto
    } else {
      const isBuildCompact = this.s.currentMode !== 'plan'
      const modelAction = resolveModelAction(this.s.adapter.role, isBuildCompact)
      const model = resolveModelFromSnapshot(
        this.s.currentConversationId,
        this.s.workspacePath!,
        modelAction,
        isBuildCompact
      )
      const supports1M = supportsContext1M(model)
      const effectiveWindow = supports1M ? CLAUDE_1M_CONTEXT_WINDOW : CLAUDE_DEFAULT_CONTEXT_WINDOW
      const { suggest, auto } = resolveAppliedThresholds({
        isLocal: false,
        effectiveContextWindow: effectiveWindow,
        userSuggestThreshold: settings.compactSuggestThreshold as number | undefined,
        userAutoThreshold: settings.compactAutoThreshold as number | undefined
      })
      this.s.compactSuggestThreshold = suggest
      this.s.compactAutoThreshold = auto
    }
  }

  resolveCompactionThresholds(effectiveContextWindow: number): {
    suggest: number
    auto: number
  } {
    return resolveCompactionThresholdsPolicy(effectiveContextWindow)
  }
}

/**
 * Compaction policy — pure, side-effect-free decision helpers for context
 * compaction. Extracted from AgentStreamProcessor / AgentExecutorFactory so the
 * band-classification and threshold math can be unit-tested deterministically
 * (mirrors the `resolveContextLevel` pattern in ipc/context-usage-level.ts).
 *
 * Nothing here touches state, the DB, the SDK, or emits events. The stateful
 * callers gather inputs, call these functions, then do the emit/log/assignment.
 */

import type { ContextWindowTier } from './context-management'
import { TIER_LIMITS } from './context-management'

// ── Compaction band classification ──────────────────────────────────────

/** UI-facing compaction bands emitted via the `compactNeeded` event. */
export type CompactionLevel = 'warning' | 'suggest' | 'critical' | 'auto-compact-pending'

export interface ClassifyCompactionInput {
  /** Current context-window occupancy in tokens. */
  inputTokens: number
  /** Token threshold at which we start suggesting a compact. */
  suggestThreshold: number
  /** Token threshold at which compaction is forced / SDK auto-compact fires. */
  autoThreshold: number
  /** Whether SDK auto-compact is active (drives critical → auto-compact-pending). */
  isAutoCompactEnabled: boolean
  /** Whether a `suggest` was already emitted (debounce state). */
  compactSuggested: boolean
  /** Turns elapsed since the last `suggest` (debounce counter). */
  turnsSinceCompactSuggestion: number
}

export interface ClassifyCompactionResult {
  /** Band to emit, or null when nothing should be emitted this turn. */
  level: CompactionLevel | null
  /** Next value for `compactSuggested` state. */
  nextSuggested: boolean
  /** Next value for `turnsSinceCompactSuggestion` state. */
  nextTurns: number
}

/**
 * Classify the current context usage into a compaction band.
 *
 * Band layout (relative to suggestThreshold S and autoThreshold A):
 *   [0, 0.8·S)   → no event (resets debounce state)
 *   [0.8·S, S)   → `warning` (only while not already suggesting)
 *   [S, A)       → `suggest`, debounced: re-fires at most once every 3 turns
 *   [A, ∞)       → `auto-compact-pending` if auto-compact on, else `critical`
 */
export function classifyCompaction(input: ClassifyCompactionInput): ClassifyCompactionResult {
  const {
    inputTokens,
    suggestThreshold,
    autoThreshold,
    isAutoCompactEnabled,
    compactSuggested,
    turnsSinceCompactSuggestion
  } = input

  const warningThreshold = Math.floor(suggestThreshold * 0.8)

  // Default: leave debounce state untouched.
  const unchanged: ClassifyCompactionResult = {
    level: null,
    nextSuggested: compactSuggested,
    nextTurns: turnsSinceCompactSuggestion
  }

  if (inputTokens >= autoThreshold) {
    return {
      level: isAutoCompactEnabled ? 'auto-compact-pending' : 'critical',
      nextSuggested: compactSuggested,
      nextTurns: turnsSinceCompactSuggestion
    }
  }

  if (inputTokens >= suggestThreshold) {
    if (!compactSuggested || turnsSinceCompactSuggestion >= 3) {
      return { level: 'suggest', nextSuggested: true, nextTurns: 0 }
    }
    return {
      level: null,
      nextSuggested: compactSuggested,
      nextTurns: turnsSinceCompactSuggestion + 1
    }
  }

  if (inputTokens >= warningThreshold && !compactSuggested) {
    return {
      level: 'warning',
      nextSuggested: compactSuggested,
      nextTurns: turnsSinceCompactSuggestion
    }
  }

  if (inputTokens < warningThreshold) {
    // Dropped below the warning zone (e.g. after a compact) — reset debounce.
    return { level: null, nextSuggested: false, nextTurns: 0 }
  }

  return unchanged
}

// ── Threshold resolution ─────────────────────────────────────────────────

export interface CompactionThresholds {
  suggest: number
  auto: number
}

/**
 * Default app-level nudge thresholds derived from a Claude effective window.
 * 1M windows get later thresholds (0.7 / 0.85); ≤200K windows fire earlier
 * (0.6 / 0.75) since the absolute headroom is smaller.
 */
export function resolveCompactionThresholds(effectiveContextWindow: number): CompactionThresholds {
  const isSmallWindow = effectiveContextWindow <= 200_000
  return {
    suggest: Math.round(effectiveContextWindow * (isSmallWindow ? 0.6 : 0.7)),
    auto: Math.round(effectiveContextWindow * (isSmallWindow ? 0.75 : 0.85))
  }
}

export interface ResolveAppliedThresholdsInput {
  /** Local LLM provider — thresholds come from the per-tier table. */
  isLocal: boolean
  /** Tier for local providers (required when isLocal). */
  localTier?: ContextWindowTier
  /** Claude effective window (required when !isLocal). */
  effectiveContextWindow?: number
  /** User-configured override for the suggest threshold (wins when set). */
  userSuggestThreshold?: number
  /** User-configured override for the auto threshold (wins when set). */
  userAutoThreshold?: number
}

/**
 * Resolve the suggest/auto thresholds actually applied to a session.
 *   - Local providers use the fixed per-tier limits (TIER_LIMITS).
 *   - Claude sessions derive defaults from the effective window, with optional
 *     user overrides taking precedence.
 */
export function resolveAppliedThresholds(
  input: ResolveAppliedThresholdsInput
): CompactionThresholds {
  if (input.isLocal) {
    const tier = input.localTier ?? 'small'
    const limits = TIER_LIMITS[tier]
    return { suggest: limits.compactSuggestThreshold, auto: limits.compactAutoThreshold }
  }

  const defaults = resolveCompactionThresholds(input.effectiveContextWindow ?? 200_000)
  return {
    suggest: input.userSuggestThreshold ?? defaults.suggest,
    auto: input.userAutoThreshold ?? defaults.auto
  }
}

// ── Claude CLI compaction env wiring ───────────────────────────────────────

/**
 * The `claude` CLI controls its auto-compact window via env vars, NOT via any
 * argv flag (`contextWindowSize`/`autoCompactEnabled` options are not forwarded
 * to the CLI). To make the documented compaction behaviour real we set:
 *   - CLAUDE_CODE_AUTO_COMPACT_WINDOW = the effective window. 1M-capable models
 *     MUST set 1000000 here or the CLI uses its (smaller) model-default window,
 *     which inflates the context badge and triggers premature compaction.
 *   - CLAUDE_AUTOCOMPACT_PCT_OVERRIDE = 80 for ≤200K models, so auto-compact
 *     fires at ~80% of the usable window (~128-152K) rather than the
 *     usable-13K default. Honoured by claude-code ≥ 2.1.x.
 *
 * Env vars only take effect at process spawn; on continueSession turns the
 * process is already running, so they're a no-op there (still returned for a
 * consistent option shape and testability).
 */
export function resolveClaudeCompactionEnv(
  supports1M: boolean,
  effectiveContextWindow: number
): Record<string, string> {
  const env: Record<string, string> = {
    CLAUDE_CODE_AUTO_COMPACT_WINDOW: String(effectiveContextWindow)
  }
  if (!supports1M) {
    env.CLAUDE_AUTOCOMPACT_PCT_OVERRIDE = '80'
  }
  return env
}

/**
 * Resolve the `contextWindowSize` option for the executor. 1M models pass the
 * full window; ≤200K models pass 80% of the window. (Kept for option-shape
 * compatibility — the CLI itself reads the env vars above, not this value.)
 */
export function resolveSdkContextWindowSize(
  supports1M: boolean,
  effectiveContextWindow: number
): number {
  return supports1M ? effectiveContextWindow : Math.round(effectiveContextWindow * 0.8)
}

/**
 * Snapshot Model Resolver — reads frozen model config from conversation snapshots.
 *
 * Consumers call resolveModelFromSnapshot() instead of modelConfigService.getModel().
 * If the conversation has a snapshot, it returns the frozen model. Otherwise, falls
 * back to live resolution via modelConfigService.
 *
 * This ensures:
 * - Cost attribution matches the model that was active at conversation creation
 * - Recovery restarts don't flip providers
 * - Settings changes don't affect existing conversations
 */

import type { ConversationModelSnapshot, ModelAction, ResolvedAssignment } from '../../shared/types'
import { conversationRepository, blueprintRepository, workspaceRepository } from '../db/repositories'
import { modelConfigService } from './model-config.service'
import { decryptSettingsKey } from '../ipc/encrypt-settings-keys'
import log from 'electron-log'

/**
 * Resolve the model for a conversation, preferring the frozen snapshot.
 *
 * Falls back to live resolution when:
 * - conversationId is null (e.g., blueprint synthetic IDs)
 * - conversation has no snapshot (legacy conversations, pre-migration 111)
 * - snapshot doesn't cover the requested mode
 */
/**
 * Regex matching blueprint synthetic conversation IDs.
 * Format: `blueprint-{phase}-{blueprintId}-{timestamp}`
 * Groups: [1] = phase, [2] = blueprintId
 */
export const BLUEPRINT_CONV_RE = /^blueprint-(specify|clarify|plan|tasks|review|build|verify)-(.+)-\d+$/

export function resolveModelFromSnapshot(
  conversationId: string | null,
  workspacePath: string,
  modelAction: ModelAction,
  isBuildMode: boolean
): string {
  if (!conversationId) {
    return modelConfigService.getModel(workspacePath, modelAction)
  }

  // G6: Blueprint synthetic IDs — read frozen snapshot from blueprint.settings_json
  const bpMatch = BLUEPRINT_CONV_RE.exec(conversationId)
  if (bpMatch) {
    const [, phase, blueprintId] = bpMatch
    try {
      const bp = blueprintRepository.findById(blueprintId)
      const snap = bp?.settingsJson?.modelSnapshot as Record<string, ResolvedAssignment> | undefined
      if (snap?.[phase]?.modelId) return snap[phase].modelId
    } catch {
      // Non-fatal — fall through to live resolution for legacy blueprints
    }
    return modelConfigService.getModel(workspacePath, modelAction)
  }

  // Regular conversations — read snapshot from conversation.model_config_json
  try {
    const conversation = conversationRepository.findById(conversationId)
    const snapshot = conversation?.modelConfigSnapshot
    if (snapshot) {
      return resolveFromSnapshot(snapshot, isBuildMode, modelAction)
    }
  } catch {
    // Non-fatal — fall through to live resolution
  }

  return modelConfigService.getModel(workspacePath, modelAction)
}

/**
 * Extract the model ID from a snapshot based on the mode and action.
 *
 * Background actions (haiku, memoryFeed, activation) use the background assignment.
 * Build mode uses the build assignment.
 * Everything else uses the plan assignment.
 */
function resolveFromSnapshot(
  snapshot: ConversationModelSnapshot,
  isBuildMode: boolean,
  modelAction: ModelAction
): string {
  // Background task actions always use the background assignment
  const backgroundActions: ModelAction[] = ['haiku', 'memoryFeed', 'activation']
  if (backgroundActions.includes(modelAction)) {
    return snapshot.background.modelId
  }

  // Build mode → build assignment, plan mode → plan assignment
  return isBuildMode ? snapshot.build.modelId : snapshot.plan.modelId
}

// ── OpenCode provider resolution from snapshot ────────────────────────

export interface OpenCodeProviderConfig {
  providerId: string
  modelId: string
  baseUrl: string | undefined
  apiKey: string | undefined
}

/**
 * Resolve OpenCode provider configuration from a conversation's frozen snapshot.
 *
 * Provider identity (providerId + modelId) comes from the snapshot to prevent
 * config bleed between chats. Infrastructure settings (baseUrl, apiKey) always
 * come from live workspace settings — they're connection details, not identity.
 *
 * Falls back to live resolution via modelConfigService.getOpenCodeConfig() when:
 * - conversationId is null
 * - conversation has no snapshot (legacy conversations, pre-migration 111)
 */
export function resolveOpenCodeProviderFromSnapshot(
  conversationId: string | null,
  workspacePath: string,
  isBuildMode: boolean
): OpenCodeProviderConfig {
  const fallback = (): OpenCodeProviderConfig => {
    const config = modelConfigService.getOpenCodeConfig(workspacePath)
    return {
      providerId: config.openCodeProvider,
      modelId: config.openCodeModel,
      baseUrl: config.openCodeBaseUrl,
      apiKey: config.openCodeApiKey
    }
  }

  if (!conversationId) {
    return fallback()
  }

  // Blueprint synthetic IDs never have conversation rows — fall back quietly
  if (BLUEPRINT_CONV_RE.test(conversationId)) {
    return fallback()
  }

  try {
    const conversation = conversationRepository.findById(conversationId)
    const snapshot = conversation?.modelConfigSnapshot
    if (!snapshot) {
      log.warn(
        `[snapshot-resolver] No snapshot for conversation ${conversationId} — using live OpenCode config`
      )
      return fallback()
    }

    const assignment = isBuildMode ? snapshot.build : snapshot.plan
    return mapAssignmentToOpenCodeConfig(assignment, workspacePath)
  } catch {
    // Non-fatal — fall through to live resolution
    return fallback()
  }
}

/**
 * Map a ResolvedAssignment to OpenCode provider config.
 * Provider identity comes from the assignment; infrastructure from workspace.
 */
function mapAssignmentToOpenCodeConfig(
  assignment: ResolvedAssignment,
  workspacePath: string
): OpenCodeProviderConfig {
  if (assignment.provider === 'local-llm') {
    // Local LLM — derive providerId from localBackend, infrastructure from local config
    const providerId = assignment.localBackend === 'omlx' ? 'omlx' : 'ollama'
    const localConfig = modelConfigService.getLocalLLMConfig(workspacePath)
    return {
      providerId,
      modelId: assignment.modelId,
      baseUrl: modelConfigService.getLocalBaseUrl(localConfig),
      apiKey: localConfig.localApiKey
    }
  }

  // Claude / other — use 'anthropic' provider, infrastructure from workspace settings
  const settings = workspaceRepository.getSettingsByPath(workspacePath)
  return {
    providerId: 'anthropic',
    modelId: assignment.modelId,
    baseUrl: settings?.openCodeBaseUrl as string | undefined,
    apiKey: decryptSettingsKey(
      settings?.openCodeApiKey as string | undefined,
      !!settings?.openCodeApiKeyEncrypted
    )
  }
}

/**
 * AgentRecoveryManager — handles session recovery, stream finalization,
 * error handling, plan state persistence, and structured summary extraction.
 *
 * Extracted from AgentSessionService to reduce god-class complexity.
 * Holds a back-reference to the session for state access.
 *
 * @internal Not for use outside the agent-session module.
 */

import type { AgentSessionHost, StreamLoopState, StreamChunk } from './agent-session-host'
import { SESSION_CONSTANTS } from './agent-session-host'
import type { AgentIntent, LLMProvider } from '../../shared/types'
import type { AdapterMcpResult } from './agent-session.types'
import { resolveModelAction } from '../../shared/constants'
import { resolveModelFromSnapshot } from './snapshot-model-resolver'
import { conversationRepository } from '../db/repositories'
import { localPlanStateService } from './local-plan-state.service'
import type { DiscoveredContext } from './local-plan-state.service'

// N8: Single source of truth for the turn-limit-exhausted message (text fallback)
const TURN_LIMIT_EXHAUSTED_MSG =
  '\n\n---\n\n' +
  "⏱️ **Turn limit reached** — I've used all available turns for this interaction. " +
  'The session is preserved and you can send another message to continue where I left off.\n\n' +
  '_Send "continue" or describe what you\'d like me to do next._'

export class AgentRecoveryManager {
  private readonly s: AgentSessionHost

  constructor(session: unknown) {
    this.s = session as AgentSessionHost
  }

  // ── N7: Shared auto-continue logic ──────────────────────────────────────

  /**
   * Build a continuation prompt and execute a new stream turn.
   * Used by both finalizeStream (happy path) and handleStreamError (error path)
   * when max_turns is reached and continuations remain.
   */
  private async continueTurnLimit(params: {
    conversationId: string
    systemPrompt: string
    isBuildMode: boolean
    mcpResult: AdapterMcpResult
    llmProvider: LLMProvider
    recoveryDepth: number
  }): Promise<void> {
    const { conversationId, systemPrompt, isBuildMode, mcpResult, llmProvider, recoveryDepth } =
      params

    this.s.maxTurnsContinuations++
    this.s.circuitBreaker.reset()
    this.s.log.info(
      `[PIPELINE:max-turns-continue] continuation=${this.s.maxTurnsContinuations}/${SESSION_CONSTANTS.MAX_TURN_CONTINUATIONS} ` +
        `conversationId=${conversationId}`
    )

    this.s.emit('chunk', {
      type: 'text',
      content: `\n\n_Continuing... (turn limit reached, auto-resuming ${this.s.maxTurnsContinuations}/${SESSION_CONSTANTS.MAX_TURN_CONTINUATIONS})_\n\n`
    } as StreamChunk)

    const isLocal = llmProvider === 'local-llm'
    let continuationPrompt: string

    if (isLocal) {
      const discoveries = this.s.toolActivityAccumulator.buildDiscoverySummary(2000)
      const planState = localPlanStateService.getForConversation(conversationId)
      const partialPlan = (this.s.activeStreams?.get(conversationId)?.accumulatedText ?? this.s.accumulatedText ?? '').slice(-1000)

      continuationPrompt = [
        '## Continuation — Complete the Plan',
        '',
        '### Original Request',
        planState?.originalRequest ??
          (typeof this.s.lastStreamOpts?.sdkPrompt === 'string'
            ? (this.s.lastStreamOpts.sdkPrompt as string).slice(0, 500)
            : ''),
        '',
        '### What You Found',
        discoveries || '(no tool results recorded)',
        '',
        '### Partial Plan',
        partialPlan || '(none yet)',
        '',
        '### Instructions',
        'Complete the plan NOW. Do NOT re-read files you already explored.',
        'Write the remaining plan items. Use at most 2 more tool calls if essential.'
      ].join('\n')
    } else {
      continuationPrompt = isBuildMode
        ? 'Continue implementing from where you left off. Do not repeat completed work.'
        : 'Continue your analysis from where you left off. Do not repeat completed work.'
    }

    // AUTOCONT-TURN-DUP-01: Increment turn counter before continuation to avoid
    // duplicate turn_usage rows. Without this, the same turn_number is reused,
    // causing inflated token counts and impossible cache hit rates (>100%).
    const nextTurnCount = (this.s.turnCounts.get(conversationId) ?? 0) + 1
    this.s.turnCounts.set(conversationId, nextTurnCount)

    await this.s.executeStream({
      sdkPrompt: continuationPrompt,
      systemPrompt,
      sessionId: isLocal ? undefined : this.s.sessionMap.get(conversationId),
      conversationId,
      turnCount: nextTurnCount,
      isBuildMode,
      mcpResult,
      llmProvider,
      recoveryDepth // Preserve depth so recovery can't restart on continuations
    })
  }

  // ── handleSessionRecovery ─────────────────────────────────────────────

  async handleSessionRecovery(params: {
    sessionRecoveryNeeded: boolean
    recoveryDepth: number
    maxRecoveryDepth: number
    sdkPrompt: string | AsyncIterable<unknown>
    systemPrompt: string
    conversationId: string
    turnCount: number
    isBuildMode: boolean
    mcpResult: AdapterMcpResult
    llmProvider: LLMProvider
  }): Promise<'continue' | 'returned'> {
    if (!params.sessionRecoveryNeeded) return 'continue'

    if (params.recoveryDepth >= params.maxRecoveryDepth) {
      this.s.log.error('[PIPELINE:session-recovery-depth-exceeded] Max recovery depth reached')
      this.s.emit('chunk', {
        type: 'session_recovery',
        recoveryPhase: 'failed',
        content: 'Session recovery failed (max retries). Please start a new conversation.'
      } as StreamChunk)
      this.s.currentStatus = 'failed'
      this.s.flushTokenUsage()
      this.s.emit('statusUpdate', this.s.getStatus())
      this.s.emit('complete')
      return 'returned'
    }

    try {
      // Enrich recovery prompt with saved summary
      let recoveryPrompt = params.sdkPrompt
      if (typeof recoveryPrompt === 'string') {
        try {
          const summary = conversationRepository.getSummary(params.conversationId)
          if (summary) {
            recoveryPrompt = `## Session Recovery Context\n${summary}\n\n## Original Request\n${recoveryPrompt}`
            this.s.log.info(
              `[C3:recovery-summary-injected] conversationId=${params.conversationId} summaryLen=${summary.length}`
            )
          }
        } catch {
          /* non-fatal — proceed with original prompt */
        }
      }

      await this.s.executeStream({
        sdkPrompt: recoveryPrompt,
        systemPrompt: params.systemPrompt,
        sessionId: undefined,
        conversationId: params.conversationId,
        turnCount: params.turnCount,
        isBuildMode: params.isBuildMode,
        mcpResult: params.mcpResult,
        llmProvider: params.llmProvider,
        recoveryDepth: params.recoveryDepth + 1
      })
      return 'returned'
    } catch (retryError) {
      this.s.log.error('[PIPELINE:session-recovery-failed]', retryError)
      this.s.currentStatus = 'failed'
      this.s.flushTokenUsage()
      this.s.emit('statusUpdate', this.s.getStatus())
      this.s.emit('complete')
      return 'returned'
    }
  }

  // ── finalizeStream sub-methods ──────────────────────────────────────

  /**
   * Handle overload detection and max_turns auto-continue.
   * Returns 'handled' when the method emits complete, 'continue' when
   * finalization should proceed to recovery/summary.
   */
  private async handleOverloadOrMaxTurns(params: {
    streamState: StreamLoopState
    conversationId: string
    systemPrompt: string
    isBuildMode: boolean
    mcpResult: AdapterMcpResult
    llmProvider: LLMProvider
    recoveryDepth: number
  }): Promise<'handled' | 'continue'> {
    const { streamState, conversationId, systemPrompt, isBuildMode, mcpResult, llmProvider, recoveryDepth } = params

    // Skip if the underlying cause was API overload
    if (streamState.overloadDetected && streamState.lastTerminalReason === 'max_turns') {
      this.s.log.warn(
        `[PIPELINE:overload-skip-continue] Skipping auto-continue — API overload detected for conversationId=${conversationId}`
      )
      this.s.emit('chunk', {
        type: 'text',
        content:
          '\n\n---\n\n' +
          '⚠️ **Claude is temporarily overloaded** — the API returned 529 errors during this session. ' +
          'This is a server-side issue and not a problem with your request.\n\n' +
          'Try again in a few minutes. If it persists, check [status.claude.com](https://status.claude.com).'
      } as StreamChunk)
      this.s.currentStatus = 'idle'
      this.s.flushTokenUsage()
      this.s.emit('statusUpdate', this.s.getStatus())
      this.s.emit('complete')
      return 'handled'
    }

    if (
      streamState.lastTerminalReason === 'max_turns' &&
      this.s.maxTurnsContinuations < SESSION_CONSTANTS.MAX_TURN_CONTINUATIONS
    ) {
      await this.continueTurnLimit({
        conversationId, systemPrompt, isBuildMode, mcpResult, llmProvider, recoveryDepth
      })
      return 'handled'
    }

    // All auto-continuations exhausted — emit a structured turn_limit chunk
    // so the renderer can show a one-click Continue button.
    if (
      streamState.lastTerminalReason === 'max_turns' &&
      this.s.maxTurnsContinuations >= SESSION_CONSTANTS.MAX_TURN_CONTINUATIONS
    ) {
      this.s.log.info(
        `[PIPELINE:max-turns-exhausted] All ${SESSION_CONSTANTS.MAX_TURN_CONTINUATIONS} ` +
          `continuations used — emitting turn_limit chunk for conversationId=${conversationId}`
      )
      // Emit structured chunk for the renderer's Continue button
      this.s.emit('chunk', {
        type: 'turn_limit',
        content: TURN_LIMIT_EXHAUSTED_MSG,
        turnLimit: {
          continuable: true,
          continuationsUsed: this.s.maxTurnsContinuations,
          continuationsMax: SESSION_CONSTANTS.MAX_TURN_CONTINUATIONS
        }
      } as StreamChunk)
    }

    return 'continue'
  }

  /**
   * Plan-mode tool-block recovery + nudge attempt.
   */
  private async attemptStreamRecovery(params: {
    streamState: StreamLoopState
    conversationId: string
    systemPrompt: string
    isBuildMode: boolean
    timedOut: boolean
  }): Promise<void> {
    const { streamState, conversationId, systemPrompt, isBuildMode, timedOut } = params

    // Plan-mode tool-block recovery: fire a deterministic emit_plan recovery
    // so the user still gets a plan card.  Gated by adapter capability so
    // blueprint / grill / audit / council sessions (which also run in plan
    // mode) are never hijacked by a pointless recovery turn.
    // Also skipped for local-LLM — there is no emit_plan-via-Claude path for local.
    let planRecoveryAttempted = false
    if (
      this.s.adapter.supportsEmitPlanRecovery &&
      streamState.planModeToolBlock &&
      this.s.currentMode === 'plan' &&
      !this.s.controlToolState.plan &&
      !timedOut &&
      this.s.llmProvider !== 'local-llm'
    ) {
      try {
        const result = await this.s.recoveryNudge.attemptPlanToolRecovery({
          cliExecutor: this.s.getOrCreateCliExecutor(conversationId),
          systemPrompt,
          workspacePath: this.s.workspacePath!,
          model: resolveModelFromSnapshot(
            conversationId,
            this.s.workspacePath!,
            resolveModelAction(this.s.adapter.role, false),
            false
          ),
          sessionId: this.s.sessionMap.get(conversationId),
          conversationId,
          workspaceId: this.s.workspaceId,
          mcpConfigPath: this.s.getCliMcpConfigPath(),
          onSessionCapture: (sid) => this.s.sessionMap.set(conversationId, sid),
          onChunk: (chunk) => this.s.emit('chunk', chunk),
          onTokens: (tokens) => {
            this.s.tokenUsage += tokens
          }
        })
        planRecoveryAttempted = result.attempted
      } catch (err) {
        this.s.log.warn('[PIPELINE:plan-recovery-failed] Non-critical:', err)
      }
    } else if (
      this.s.adapter.supportsEmitPlanRecovery &&
      streamState.planModeToolBlock &&
      this.s.llmProvider === 'local-llm'
    ) {
      this.s.log.info('[PIPELINE:plan-tool-recovery-skipped] local provider')
    }

    // Nudge: attempt recovery if tool calls occurred without trailing text
    const skipNudgeReasons = new Set([
      'max_turns',
      'hook_stopped',
      'aborted_tools',
      'aborted_streaming'
    ])
    const shouldSkipNudge =
      (streamState.lastTerminalReason && skipNudgeReasons.has(streamState.lastTerminalReason)) ||
      planRecoveryAttempted
    if (
      this.s.circuitBreaker.count > 0 &&
      !streamState.hasTextAfterLastTool &&
      !shouldSkipNudge &&
      !timedOut
    ) {
      this.s.log.warn(
        `[PIPELINE:recovery-nudge-triggered] conversationId=${conversationId} ` +
          `toolCalls=${this.s.circuitBreaker.count} accumulatedTextLen=${(this.s.activeStreams?.get(conversationId)?.accumulatedText ?? this.s.accumulatedText ?? '').length}`
      )
      const recoveryResult = await this.s.recoveryNudge.attemptRecovery({
        cliExecutor: this.s.getOrCreateCliExecutor(conversationId),
        systemPrompt,
        workspacePath: this.s.workspacePath!,
        model: resolveModelFromSnapshot(
          conversationId,
          this.s.workspacePath!,
          resolveModelAction(this.s.adapter.role, isBuildMode),
          isBuildMode
        ),
        isBuildMode,
        skipCliTurn: this.s.llmProvider === 'local-llm',
        sessionId: this.s.sessionMap.get(conversationId),
        conversationId,
        workspaceId: this.s.workspaceId,
        toolCallCount: this.s.circuitBreaker.count,
        onSessionCapture: (sid) => this.s.sessionMap.set(conversationId, sid),
        onChunk: (chunk) => this.s.emit('chunk', chunk),
        onTokens: (tokens) => {
          this.s.tokenUsage += tokens
        }
      })
      this.s.log.info(
        `[PIPELINE:recovery-nudge-result] recovered=${recoveryResult.recovered} textLen=${recoveryResult.text.length}`
      )
      const recovCtx = this.s.activeStreams?.get(conversationId)
      if (recovCtx) {
        recovCtx.accumulatedText += recoveryResult.text
      } else {
        this.s.accumulatedText += recoveryResult.text
      }
    }
  }

  /**
   * Capture summary, detect intents, mark plan completed, emit baseline response.
   */
  private captureSummaryAndIntents(
    conversationId: string,
    llmProvider: LLMProvider,
    recoveryDepth: number
  ): void {
    // Auto-capture conversation summary for ALL providers
    const convAccText = this.s.activeStreams?.get(conversationId)?.accumulatedText ?? this.s.accumulatedText ?? ''
    if (convAccText.length > 100) {
      try {
        const summary = this.extractStructuredSummary(conversationId)
        if (summary) {
          conversationRepository.updateSummary(conversationId, summary)
          this.s.log.info(
            `[S6:summary-captured] conversationId=${conversationId} provider=${llmProvider} len=${summary.length}`
          )
        }
      } catch (err) {
        this.s.log.warn('[S6:summary-capture-failed]', err)
      }

      // Save plan state for cross-session continuity (all providers).
      // saveCurrentPlanState returns early when mode !== 'plan' or no workspaceId.
      this.saveCurrentPlanState(conversationId)
    }

    // Delegate intent detection to the adapter
    this.s.adapter.emitDetectedIntents({
      accumulatedText: convAccText,
      controlToolState: this.s.controlToolState,
      mode: this.s.currentMode,
      conversationId,
      emit: (evt: string, payload: unknown) => this.s.emitAdapterEvent(evt, payload)
    })

    // Mark plan state as completed when a plan intent was detected
    if (this.s.controlToolState.plan) {
      try {
        localPlanStateService.markCompleted(conversationId)
        this.s.log.info(`[F6:plan-completed] conversationId=${conversationId}`)
      } catch (err) {
        this.s.log.warn('[F6:plan-complete-failed]', err)
      }
    }

    // Baseline "response" intent if adapter emitted nothing interesting
    if (!this.s.controlToolState.plan && !this.s.controlToolState.askUser) {
      this.s.emit('intent', {
        type: 'response',
        content: convAccText
      } as AgentIntent)
    }

    this.s.currentStatus = 'idle'
    this.s.flushTokenUsage()
    this.s.emit('statusUpdate', this.s.getStatus())

    if (recoveryDepth > 0) {
      this.s.emit('chunk', {
        type: 'session_recovery',
        recoveryPhase: 'completed',
        content: 'Session recovered successfully.'
      } as StreamChunk)
    }

    this.s.emit('complete')
  }

  // ── finalizeStream ────────────────────────────────────────────────────

  async finalizeStream(params: {
    conversationId: string
    systemPrompt: string
    isBuildMode: boolean
    recoveryDepth: number
    timedOut: boolean
    streamState: StreamLoopState
    mcpResult: AdapterMcpResult
    llmProvider: LLMProvider
  }): Promise<void> {
    const {
      conversationId,
      systemPrompt,
      isBuildMode,
      recoveryDepth,
      timedOut,
      streamState,
      mcpResult,
      llmProvider
    } = params

    if (!streamState.messageStopReceived && !this.s.circuitBreaker.isBroken && !timedOut) {
      this.s.log.warn(
        `[PIPELINE:stream-incomplete] Stream ended without MessageStop event for conversationId=${conversationId}`
      )
    }

    this.s.log.info(
      `[PIPELINE:response-complete] conversationId=${conversationId} textLen=${(this.s.activeStreams?.get(conversationId)?.accumulatedText ?? this.s.accumulatedText ?? '').length}`
    )

    // Step 1: Handle overload / max_turns auto-continue
    const overloadResult = await this.handleOverloadOrMaxTurns({
      streamState, conversationId, systemPrompt, isBuildMode, mcpResult, llmProvider, recoveryDepth
    })
    if (overloadResult === 'handled') return

    // Step 2: Plan-mode tool-block recovery + nudge
    await this.attemptStreamRecovery({
      streamState, conversationId, systemPrompt, isBuildMode, timedOut
    })

    // Step 3: Summary capture, intent detection, completion
    this.captureSummaryAndIntents(conversationId, llmProvider, recoveryDepth)
  }

  // ── handleStreamError helpers ──────────────────────────────────────────

  /** Save partial progress on error (all providers). */
  private saveErrorProgress(): void {
    const errConvId = this.s.lastStreamOpts?.conversationId ?? (this.s as any).lastActiveConversationId ?? this.s.currentConversationId
    const errAccText = errConvId ? (this.s.activeStreams?.get(errConvId)?.accumulatedText ?? this.s.accumulatedText ?? '') : ''
    if (errAccText.length <= 50 || !errConvId) {
      return
    }
    try {
      const summary = this.extractStructuredSummary(errConvId)
      if (summary) {
        // Guard: don't overwrite a richer prior summary with a sparse error-path one.
        // A brief error turn can produce near-empty output that would clobber
        // detailed context from a prior successful turn.
        const existingSummary = conversationRepository.getSummary(errConvId)
        if (existingSummary && summary.length < existingSummary.length) {
          this.s.log.info(
            `[S6:error-summary-skipped] existing=${existingSummary.length} new=${summary.length} — keeping richer summary`
          )
        } else {
          conversationRepository.updateSummary(errConvId, summary)
          this.s.log.info(
            `[S6:error-summary-saved] conversationId=${errConvId} provider=${this.s.llmProvider} len=${summary.length}`
          )
        }
      }
    } catch {
      /* non-fatal */
    }
    this.saveCurrentPlanState(errConvId)
  }

  /** Classify a stream error into one of the known categories. */
  private classifyStreamError(
    error: Error,
    timedOut: boolean
  ): {
    isOverload: boolean
    isMaxTurns: boolean
    isContextOverflow: boolean
    isAbort: boolean
  } {
    const isAbort = error.name === 'AbortError'
    const isOverload =
      !timedOut &&
      !isAbort &&
      /529|overloaded|server_is_overloaded|503 Service/i.test(error.message)
    const isMaxTurns =
      !timedOut && !isAbort && error.message?.includes('maximum number of turns')
    const isContextOverflow =
      !timedOut &&
      !isAbort &&
      this.s.llmProvider === 'local-llm' &&
      (error.message?.includes('context length') ||
        error.message?.includes('maximum context') ||
        error.message?.includes('too many tokens') ||
        error.message?.includes('exceeds max context') ||
        error.message?.includes('context window') ||
        error.message?.includes('token limit'))
    return { isOverload, isMaxTurns, isContextOverflow, isAbort }
  }

  /** Handle AbortError — either timeout or user cancellation. */
  private handleAbortOrTimeout(
    _error: Error,
    timedOut: boolean,
    effectiveTimeoutMs?: number
  ): void {
    if (timedOut) {
      const actualTimeoutMin = Math.round(
        (effectiveTimeoutMs ?? SESSION_CONSTANTS.MAX_INTERACTION_TIMEOUT_MS) / 60_000
      )
      this.s.log.error('SDK query timed out')
      this.s.emit('chunk', {
        type: 'text',
        content:
          '\n\n---\n\n' +
          `⏱️ **Session timed out** after ${actualTimeoutMin} minutes ` +
          `(${this.s.circuitBreaker.count} tool calls made). ` +
          'This usually means the task is taking longer than expected, not that something is broken.\n\n' +
          'The session is preserved — send another message to continue where I left off, ' +
          'or try breaking the task into smaller steps.'
      } as StreamChunk)
    } else {
      this.s.log.info('SDK query cancelled by user')
    }
  }

  /** Emit idle status + complete for graceful early-return paths. */
  private emitIdleComplete(): void {
    this.s.currentStatus = 'idle'
    this.s.flushTokenUsage()
    this.s.emit('statusUpdate', this.s.getStatus())
    this.s.emit('complete')
  }

  // ── handleStreamError ─────────────────────────────────────────────────

  async handleStreamError(
    error: Error,
    timedOut: boolean,
    recoveryDepth = 0,
    effectiveTimeoutMs?: number
  ): Promise<void> {
    // Clear abort controller for the errored conversation (from lastStreamOpts if available)
    const errorConvId = this.s.lastStreamOpts?.conversationId ?? (this.s as any).lastActiveConversationId ?? null
    if (errorConvId) {
      const ctx = this.s.activeStreams?.get(errorConvId)
      if (ctx) {
        ctx.abortController = null
      } else {
        // Fallback: clear via property (handles test doubles + _directAbortController)
        this.s.sdkAbortController = null
      }
    } else {
      this.s.sdkAbortController = null
    }
    this.saveErrorProgress()

    const { isOverload, isMaxTurns, isContextOverflow, isAbort } =
      this.classifyStreamError(error, timedOut)

    // API overload — don't auto-continue
    if (isOverload) {
      this.s.lastSendOutcome = 'overload'
      this.s.log.warn(`[PIPELINE:overload-error] API overload error: ${error.message}`)
      this.s.emit('chunk', {
        type: 'text',
        content:
          '\n\n---\n\n' +
          '⚠️ **Claude is temporarily overloaded** — the API returned server errors during this session. ' +
          'This is a server-side issue and not a problem with your request.\n\n' +
          'Try again in a few minutes. If it persists, check [status.claude.com](https://status.claude.com).'
      } as StreamChunk)
      this.emitIdleComplete()
      return
    }

    // Auto-continue on max_turns error
    if (
      isMaxTurns &&
      this.s.lastStreamOpts &&
      this.s.maxTurnsContinuations < SESSION_CONSTANTS.MAX_TURN_CONTINUATIONS
    ) {
      const { conversationId, systemPrompt, isBuildMode, llmProvider } =
        this.s.lastStreamOpts
      // AUTOCONT-STALE-MCP-01: Rebuild mcpResult from adapter to pick up any
      // MCP config changes made since the stream started. lastStreamOpts captured
      // mcpResult at executeStream() entry — using it directly risks invoking
      // disabled tools or missing newly-enabled ones.
      let freshMcpResult = this.s.lastStreamOpts.mcpResult
      try {
        const controlCallbacks = this.s.adapter.buildControlCallbacks({
          conversationId,
          emit: (evt, payload) => this.s.emitAdapterEvent(evt, payload),
          getAccumulatedText: () => this.s.activeStreams?.get(conversationId)?.accumulatedText ?? this.s.accumulatedText ?? ''
        })
        freshMcpResult = this.s.adapter.buildMcpConfig({
          mode: this.s.currentMode,
          workspacePath: this.s.workspacePath!,
          workspaceId: this.s.workspaceId,
          conversationId,
          controlCallbacks,
          contextTier: this.s.lastStreamOpts.contextTier
        })
      } catch {
        // Non-fatal: fall back to stale mcpResult from lastStreamOpts
        this.s.log.warn('[PIPELINE:error-autocont] Failed to rebuild mcpResult — using stale config')
      }
      await this.continueTurnLimit({
        conversationId, systemPrompt, isBuildMode, mcpResult: freshMcpResult, llmProvider, recoveryDepth
      })
      return
    }

    // Max turns — all continuations exhausted
    if (isMaxTurns) {
      this.s.lastSendOutcome = 'turn_limit_exhausted'
      this.s.log.info(
        `[PIPELINE:max-turns-exhausted-error] All ${SESSION_CONSTANTS.MAX_TURN_CONTINUATIONS} ` +
          'continuations used (error path) — emitting turn_limit chunk'
      )
      this.s.emit('chunk', {
        type: 'turn_limit',
        content: TURN_LIMIT_EXHAUSTED_MSG,
        turnLimit: {
          continuable: true,
          continuationsUsed: this.s.maxTurnsContinuations,
          continuationsMax: SESSION_CONSTANTS.MAX_TURN_CONTINUATIONS
        }
      } as StreamChunk)
      this.emitIdleComplete()
      return
    }

    // Context overflow — graceful handling for local LLMs
    if (isContextOverflow && this.s.currentConversationId) {
      this.s.lastSendOutcome = 'context_overflow'
      this.s.log.warn(
        `[S10:context-overflow] conversationId=${this.s.currentConversationId} — ` +
          `saving progress and emitting recovery message. Error: ${error.message}`
      )
      this.saveCurrentPlanState(this.s.currentConversationId)
      this.s.emit('chunk', {
        type: 'text',
        content:
          '\n\n---\n' +
          '⚠️ **Context limit reached.** Your progress has been saved.\n\n' +
          'Send a follow-up message to continue from where I left off. ' +
          "I'll pick up the plan from the saved context.\n\n" +
          '_Tip: Try breaking complex requests into smaller, focused steps._'
      } as StreamChunk)
      this.emitIdleComplete()
      return
    }

    // Abort / timeout / generic error
    if (isAbort) {
      this.s.lastSendOutcome = 'aborted'
      this.handleAbortOrTimeout(error, timedOut, effectiveTimeoutMs)
    } else {
      this.s.lastSendOutcome = 'error'
      this.s.log.error('SDK send failed:', error)
      this.s.emit('chunk', {
        type: 'error',
        error: `${this.s.adapter.role} SDK error: ${error.message}`
      } as StreamChunk)
    }

    this.s.currentStatus = 'failed'
    this.s.flushTokenUsage()
    this.s.emit('statusUpdate', this.s.getStatus())

    if (recoveryDepth > 0) {
      this.s.emit('chunk', {
        type: 'session_recovery',
        recoveryPhase: 'failed',
        content: 'Session recovery failed. Please start a new conversation.'
      } as StreamChunk)
    }

    this.s.emit('complete')
  }

  // ── Plan State Persistence ────────────────────────────────────────────

  saveCurrentPlanState(conversationId: string): void {
    if (!this.s.workspaceId || this.s.currentMode !== 'plan') return
    try {
      const filesExplored = this.s.toolActivityAccumulator.getExploredFiles()
      const text = this.s.activeStreams?.get(conversationId)?.accumulatedText ?? this.s.accumulatedText ?? ''

      const planLineRegex =
        /^\s*(?:\d+[.)]\s|[-*]\s|#{2,4}\s(?:Step|Phase|Change|Modify|Add|Remove|Update|Create|Fix|Implement)|\*{1,2}\d+[.)]\*{0,2}\s)/i
      const planItems = text
        .split('\n')
        .filter((line) => planLineRegex.test(line))
        .slice(0, 30)
        .map((line) => line.trim())

      const discoveredContext: DiscoveredContext = {
        filesExplored,
        keyFindings: [],
        planItems,
        nextSteps: []
      }

      const originalRequest =
        typeof this.s.lastStreamOpts?.sdkPrompt === 'string'
          ? (this.s.lastStreamOpts.sdkPrompt as string).slice(0, 2000)
          : ''

      localPlanStateService.upsert({
        conversationId,
        workspaceId: this.s.workspaceId,
        originalRequest,
        discoveredContext,
        planText: text.slice(0, 10_000)
      })
    } catch (err) {
      this.s.log.warn('[S3:plan-state-save-failed]', err)
    }
  }

  // ── Structured Summary Extraction ─────────────────────────────────────

  extractStructuredSummary(_conversationId: string): string | null {
    const text = this.s.activeStreams?.get(_conversationId)?.accumulatedText ?? this.s.accumulatedText
    if (!text || text.length < 50) return null

    const filesExplored = this.s.toolActivityAccumulator.getExploredFiles()
    const toolCount = this.s.toolActivityAccumulator.count

    const planLineRegex =
      /^\s*(?:\d+[.)]\s|[-*]\s|#{2,4}\s(?:Step|Phase|Change|Modify|Add|Remove|Update|Create|Fix|Implement)|\*{1,2}\d+[.)]\*{0,2}\s)/i
    const planItems = text
      .split('\n')
      .filter((line) => planLineRegex.test(line))
      .slice(0, 20)
      .map((line) => line.trim())

    const parts: string[] = []

    const originalRequest = this.s.lastStreamOpts?.sdkPrompt
    if (typeof originalRequest === 'string') {
      parts.push(`## Goal\n${originalRequest.slice(0, 300)}`)
    }

    if (filesExplored.length > 0) {
      parts.push(`## Files Found\n${filesExplored.map((f) => `- ${f}`).join('\n')}`)
    }

    const nonPlanText = text
      .split('\n')
      .filter((line) => !planLineRegex.test(line))
      .join('\n')
      .trim()
    if (nonPlanText.length > 50) {
      parts.push(`## Key Findings\n${nonPlanText.slice(0, 500)}`)
    }

    if (planItems.length > 0) {
      parts.push(`## Plan So Far\n${planItems.join('\n')}`)
    }

    if (toolCount > 0) {
      parts.push(`## Session Stats\nTool calls: ${toolCount}`)
    }

    if (parts.length === 0) return null
    return parts.join('\n\n')
  }
}

/**
 * AgentExecutorFactory — builds executor options for CLI and OpenCode
 * backends (derived from LLM provider). Resolves MCP feature flags, hook
 * paths, budget caps, and local LLM context windows.
 *
 * Extracted from AgentSessionService to reduce god-class complexity.
 * Holds a back-reference to the session for state access.
 *
 * @internal Not for use outside the agent-session module.
 */

import type { AgentSessionHost, CLIExecuteOptions } from './agent-session-host'
import type { AdapterMcpResult } from './agent-session.types'
import type { McpFeatureFlags } from './workspace-mcp-config'
import { deriveSkipServers } from './mcp-skip-servers'

import type { ConversationMode } from '../../shared/types'
import {
  BUDGET_CAP_MODE_MULTIPLIERS,
  CLAUDE_1M_CONTEXT_WINDOW,
  CLAUDE_DEFAULT_CONTEXT_WINDOW,
  EXTERNAL_MCP_INTEGRATIONS,
  MCP_TOOLS,
  RECOMMENDED_LOCAL_MODELS,
  resolveModelAction,
  supportsContext1M
} from '../../shared/constants'

import { modelConfigService } from './model-config.service'
import { resolveModelFromSnapshot } from './snapshot-model-resolver'
import { contextWindowResolver } from './context-window-resolver'
import { resolveClaudeCompactionEnv, resolveSdkContextWindowSize } from './compaction-policy'
import { conversationRepository, workspaceRepository } from '../db/repositories'
import { join } from 'node:path'
import { app } from 'electron'
import { existsSync } from 'node:fs'

export class AgentExecutorFactory {
  private readonly s: AgentSessionHost
  /** Cached MCP config path — reused on continueSession turns to avoid rebuild. */
  private cachedMcpConfigPath: string | undefined
  /** Whether control-actions server was mounted in the last MCP config (for permission prompt gating). */
  private cachedControlActionsMounted = false
  /** Cached async-resolved context window + confidence flag. */
  private cachedContextWindow: number | null = null
  private cachedContextWindowConfident = false
  /** F18: 1M context beta header — extracted from magic string for maintainability. */
  private static readonly CONTEXT_1M_BETA = 'context-1m-2025-08-07'

  constructor(session: unknown) {
    this.s = session as AgentSessionHost
  }

  // F6: Invalidate the cached MCP config so the next turn rebuilds it.
  // Called on mode switch to ensure permission changes take effect immediately.
  invalidateMcpConfigCache(): void {
    this.cachedMcpConfigPath = undefined
  }

  /** Expose the cached MCP config path so recovery turns can re-mount control-actions/emit_plan. */
  getCachedMcpConfigPath(): string | undefined {
    return this.cachedMcpConfigPath
  }

  // ── resolveLocalContextWindow ─────────────────────────────────────────

  /** Sync fallback — checks static RECOMMENDED_LOCAL_MODELS only. */
  resolveLocalContextWindow(): number {
    if (!this.s.workspacePath) return 131_072
    try {
      const localConfig = modelConfigService.getLocalLLMConfig(this.s.workspacePath)
      const model = localConfig.localModel
      const recommended = RECOMMENDED_LOCAL_MODELS.find(
        (m) => m.ollamaId === model || m.omlxId === model
      )
      return recommended?.contextWindow ?? 131_072
    } catch {
      return 131_072
    }
  }

  /**
   * Async resolver — uses the full ContextWindowResolver chain:
   *   user override → backend API query → known models → 128K fallback.
   *
   * Caches the result for the session lifetime so subsequent calls are free.
   * Returns `confident: true` when the value came from a user override or
   * backend API (not the static table fallback), which gates whether we
   * write `models.*.limit` into opencode.json.
   */
  async resolveLocalContextWindowAsync(): Promise<{ contextWindow: number; confident: boolean }> {
    if (this.cachedContextWindow !== null) {
      return { contextWindow: this.cachedContextWindow, confident: this.cachedContextWindowConfident }
    }

    if (!this.s.workspacePath) {
      return { contextWindow: 131_072, confident: false }
    }

    try {
      const localConfig = modelConfigService.getLocalLLMConfig(this.s.workspacePath)
      const settings = workspaceRepository.getSettingsByPath(this.s.workspacePath)
      const userOverride =
        typeof settings?.localContextWindow === 'number' ? settings.localContextWindow : undefined

      const resolved = await contextWindowResolver.resolve(localConfig, userOverride)

      // Confident if user explicitly set a value, or the resolver got a
      // non-fallback answer (i.e. backend API or known model table hit).
      const confident = userOverride != null || resolved !== 131_072

      this.cachedContextWindow = resolved
      this.cachedContextWindowConfident = confident
      return { contextWindow: resolved, confident }
    } catch {
      return { contextWindow: 131_072, confident: false }
    }
  }

  // ── resolveWorkspaceMcpFlags ──────────────────────────────────────────

  resolveWorkspaceMcpFlags(): McpFeatureFlags {
    const defaults: McpFeatureFlags = {
      repomapEnabled: true,
      semanticSearchEnabled: true,
      githubConfigured: false,
      localMcpActive: {}
    }
    try {
      if (!this.s.workspaceId) return defaults
      const ws = workspaceRepository.findById(this.s.workspaceId)
      if (!ws) return defaults
      const settings = workspaceRepository.getSettings(ws.id)
      return {
        repomapEnabled: settings.repomapEnabled !== false,
        semanticSearchEnabled: settings.semanticSearchEnabled !== false,
        githubConfigured: !!settings.githubToken,
        externalMcpActive: this.resolveExternalMcpFlags(),
        localMcpActive: {}
      }
    } catch {
      return defaults
    }
  }

  // ── resolveExternalMcpFlags ───────────────────────────────────────────

  resolveExternalMcpFlags(): Record<string, boolean> {
    const flags: Record<string, boolean> = {}
    try {
      if (this.s.currentConversationId) {
        const conv = conversationRepository.findById(this.s.currentConversationId)
        if (conv?.mcpOverrides) {
          const overrides = conv.mcpOverrides
          if (this.s.workspaceId) {
            const wsSettings = workspaceRepository.getSettings(this.s.workspaceId)
            for (const integration of EXTERNAL_MCP_INTEGRATIONS) {
              const wsAvailable = !!wsSettings[`${integration.id}Available`]
              const chatActive = !!overrides[integration.id]
              flags[integration.id] = wsAvailable && chatActive
            }
          }
        }
      }
    } catch {
      /* non-fatal */
    }
    return flags
  }

  // ── resolveHookPaths ──────────────────────────────────────────────────

  resolveHookPaths(): { pre?: string; post?: string } {
    const hooksDir = app.isPackaged
      ? join(process.resourcesPath, 'hooks')
      : join(__dirname, '..', '..', 'src', 'main', 'hooks')

    const pre = join(hooksDir, 'pre-tool-use-hook.sh')
    const post = join(hooksDir, 'post-tool-use-hook.sh')

    const result: { pre?: string; post?: string } = {}
    if (existsSync(pre)) result.pre = pre
    if (existsSync(post)) result.post = post

    if (result.pre || result.post) {
      this.s.log.info(
        `[resolveHookPaths] pre=${result.pre ?? 'none'} post=${result.post ?? 'none'}`
      )
    }
    return result
  }

  // ── resolveBudgetCap ──────────────────────────────────────────────────

  resolveBudgetCap(isLocal: boolean, isBuildMode: boolean): number | undefined {
    if (isLocal) return undefined
    if (!this.s.workspacePath) return undefined
    try {
      const workspace = workspaceRepository
        .findAll()
        .find((w) => w.repoPath === this.s.workspacePath)
      if (!workspace) return undefined
      const settings = workspaceRepository.getSettings(workspace.id)
      const baseCap = settings.budgetCapUsd
      if (!baseCap || baseCap <= 0) return undefined

      const multiplier = isBuildMode
        ? BUDGET_CAP_MODE_MULTIPLIERS.build
        : BUDGET_CAP_MODE_MULTIPLIERS.plan
      return baseCap * multiplier
    } catch {
      return undefined
    }
  }

  /**
   * Resolve thinking effort: user's per-conversation choice overrides the model default.
   * Model-aware defaults: Haiku → 'medium' (saves thinking tokens without quality loss),
   * Opus/Sonnet → 'high' (Opus 4.8 at high ≥ 4.7 at xhigh).
   */
  private resolveEffort(resolvedModel: string): 'low' | 'medium' | 'high' | 'xhigh' | 'max' {
    // Check per-conversation override first
    if (this.s.currentConversationId) {
      try {
        const conv = conversationRepository.findById(this.s.currentConversationId)
        if (conv?.effort) {
          return conv.effort
        }
      } catch {
        /* non-fatal — use model default */
      }
    }
    // Model-aware defaults: Haiku uses fewer thinking tokens at 'medium'
    // without quality loss. Opus and Sonnet benefit from 'high'.
    if (resolvedModel.includes('haiku')) return 'medium'
    return 'high'
  }

  /**
   * Resolve per-conversation thinking budget cap.
   * Returns undefined if no cap is set (unlimited thinking).
   */
  private resolveThinkingBudget(): number | undefined {
    if (this.s.currentConversationId) {
      try {
        const conv = conversationRepository.findById(this.s.currentConversationId)
        if (conv?.thinkingBudget && conv.thinkingBudget > 0) {
          return conv.thinkingBudget
        }
      } catch {
        /* non-fatal */
      }
    }
    return undefined
  }

  // ── buildCLIExecuteOptions ────────────────────────────────────────────

  buildCLIExecuteOptions(params: {
    prompt: string | Array<Record<string, unknown>>
    systemPrompt: string
    sessionId: string | undefined
    isBuildMode: boolean
    mode?: ConversationMode
    resumeAt: string | undefined
    abortController: AbortController
    mcpResult: AdapterMcpResult
    // F14: localContextWindow removed — was accepted as a parameter but never
    // referenced. Context window is resolved internally from the model config.
    /** Completion goal — Claude works autonomously until this condition is met */
    goal?: string
    /** Goal delivery mode: 'advisory' (system prompt only) or 'enforce' (/goal stdin) */
    goalMode?: 'advisory' | 'enforce'
  }, resolvedExecutor?: { isAlive(): boolean }): CLIExecuteOptions {
    const { prompt, systemPrompt, sessionId, isBuildMode, resumeAt, abortController, mcpResult } =
      params
    const { allowedTools, disallowedTools } = mcpResult

    const modelAction = resolveModelAction(this.s.adapter.role, isBuildMode)
    const resolvedModel = resolveModelFromSnapshot(
      this.s.currentConversationId,
      this.s.workspacePath!,
      modelAction,
      isBuildMode
    )

    const supports1M = supportsContext1M(resolvedModel)
    const effectiveContextWindow = supports1M
      ? CLAUDE_1M_CONTEXT_WINDOW
      : CLAUDE_DEFAULT_CONTEXT_WINDOW
    this.s.effectiveContextWindow = effectiveContextWindow

    const sdkContextWindowSize = resolveSdkContextWindowSize(supports1M, effectiveContextWindow)
    // The `claude` CLI controls its auto-compact window via env vars, not argv
    // flags. Without this, 1M models use the (smaller) model-default window —
    // inflating the context badge and triggering premature auto-compact.
    const compactionEnv = resolveClaudeCompactionEnv(supports1M, effectiveContextWindow)

    // WRONG-EXECUTOR-03: Use the resolved per-conversation executor when provided,
    // not the cliExecutor getter which goes through _lastActiveConversationId.
    const canContinue = (resolvedExecutor ?? this.s.cliExecutor).isAlive() && !!sessionId

    // C2: Log tool availability on EVERY turn (not just first spawn)
    this.s.log.info(
      `[CLI:tools] turn=every allowedTools=${allowedTools?.length ?? 'all'} ` +
        `disallowed=[${disallowedTools?.join(',') ?? ''}] ` +
        `hasEmitPlan=${allowedTools === undefined || allowedTools.includes('mcp__control-actions__emit_plan')} ` +
        `hasCodeGraph=${allowedTools === undefined || allowedTools.some((t: string) => t.includes('code-graph'))} ` +
        `canContinue=${canContinue}`
    )

    // ── Fast path: continueSession — skip expensive work ────────────────
    // When the CLI process is alive and we're continuing the same session,
    // only prompt, model, cwd, abortController, and continueSession are used
    // by CLIExecutor.execute() (it writes the user message to stdin and reads
    // stdout — no args are rebuilt, no files are spawned). Skip MCP config
    // rebuild, system prompt file write, additional directories lookup, etc.
    if (canContinue) {
      return {
        prompt,
        systemPrompt,
        permissionMode: this.resolveCliPermissionMode(params.mode ?? this.s.currentMode),
        model: resolvedModel,
        cwd: this.s.workspacePath!,
        abortController,
        agentId: this.s.adapter.agentId,
        effort: this.resolveEffort(resolvedModel),
        continueSession: true,
        // Reuse cached MCP config — process already has MCP servers connected
        mcpConfigPath: this.cachedMcpConfigPath,
        contextWindowSize: sdkContextWindowSize,
        autoCompactEnabled: true,
        // No-op on a live process (env only applies at spawn) — included for a
        // consistent option shape with the new-spawn path.
        envOverrides: compactionEnv,
        // F1: thinkingBudget must persist across continueSession turns to
        // enforce user cost control on every turn, not just the first.
        thinkingBudget: this.resolveThinkingBudget(),
        // Permission prompt tool — only present when control-actions server is mounted.
        // When the adapter's allowedTools exclude all control-actions tools, the server
        // is skipped and referencing the tool would crash every tool call.
        permissionPromptTool: this.cachedControlActionsMounted
          ? MCP_TOOLS.CONTROL_ACTIONS.PERMISSION_PROMPT.name
          : undefined,
        // F2: goal must persist so MPA autonomous completion conditions
        // are evaluated on every turn, not just the initial spawn.
        goal: params.goal,
        goalMode: params.goalMode
      }
    }

    // ── Full path: new process spawn — build all options ─────────────────
    let additionalDirectories: string[] | undefined
    try {
      if (this.s.workspaceId) {
        const settings = workspaceRepository.getSettings(this.s.workspaceId)
        additionalDirectories = settings.additionalDirectories
      }
    } catch {
      /* non-fatal */
    }

    // Derive skip-servers BEFORE building the MCP config — we need to know
    // whether control-actions is mounted to gate the permissionPromptTool flag.
    const skipServers = deriveSkipServers(params.mcpResult.allowedTools)
    const controlActionsMounted = !skipServers?.includes('control-actions')
    this.cachedControlActionsMounted = controlActionsMounted

    // Build and cache MCP config for reuse on subsequent continueSession turns
    const mcpConfigPath = this.buildCLIMcpConfigPath(params, skipServers)
    this.cachedMcpConfigPath = mcpConfigPath

    // Instrumentation: one-line snapshot of the resolved compaction config on spawn.
    this.s.log.info(
      `[compaction:config] model=${resolvedModel} supports1M=${supports1M} ` +
        `contextWindowSize=${sdkContextWindowSize} autoCompactEnabled=true ` +
        `autoCompactWindow=${compactionEnv.CLAUDE_CODE_AUTO_COMPACT_WINDOW} ` +
        `pctOverride=${compactionEnv.CLAUDE_AUTOCOMPACT_PCT_OVERRIDE ?? 'none'}`
    )

    return {
      prompt,
      systemPrompt,
      model: resolvedModel,
      cwd: this.s.workspacePath!,
      permissionMode: this.resolveCliPermissionMode(params.mode ?? this.s.currentMode),
      allowedTools,
      disallowedTools,
      maxTurns: isBuildMode ? 200 : 50,
      resume: sessionId,
      resumeSessionAt: resumeAt,
      abortController,
      agentId: this.s.adapter.agentId,
      effort: this.resolveEffort(resolvedModel),
      // Fable 5 has native 1M context — no beta header needed. Sonnet/Opus use the beta.
      betas: supports1M && !resolvedModel.includes('fable')
        ? [AgentExecutorFactory.CONTEXT_1M_BETA]
        : undefined,
      // F19: Tier-aware fallback — only fall back to a model of equal or higher capability.
      // Fable → Opus fallback (refusal/availability per Anthropic docs).
      // Opus → Sonnet fallback (appropriate cost reduction).
      // Sonnet/Haiku → no fallback.
      fallbackModel: resolvedModel.includes('fable')
        ? 'claude-opus-4-8'
        : resolvedModel.includes('opus') ? 'claude-sonnet-5' : undefined,
      additionalDirectories,
      contextWindowSize: sdkContextWindowSize,
      autoCompactEnabled: true,
      // Wire compaction window + MCP timeout into the CLI's process env.
      // Blueprint sessions get an extended MCP server startup timeout (30s vs
      // the default ~10s) because they spawn 4-5 MCP servers simultaneously and
      // the packaged-app cold start is slower than dev.
      envOverrides: {
        ...compactionEnv,
        ...(this.s.adapter.role.startsWith('blueprint-')
          ? { MCP_TIMEOUT: '30000' }
          : {})
      },
      continueSession: false,
      mcpConfigPath,
      // Permission prompt tool — only set when control-actions server is mounted.
      // Blueprint sessions with restricted allowedTools skip control-actions; passing
      // the tool reference when the server isn't present crashes every tool call with
      // "MCP tool mcp__control-actions__permission_prompt not found".
      permissionPromptTool: controlActionsMounted
        ? MCP_TOOLS.CONTROL_ACTIONS.PERMISSION_PROMPT.name
        : undefined,
      goal: params.goal,
      goalMode: params.goalMode,
      thinkingBudget: this.resolveThinkingBudget()
    }
  }

  // ── buildCLIMcpConfigPath ─────────────────────────────────────────────

  buildCLIMcpConfigPath(
    _params: {
      isBuildMode: boolean
      mcpResult: AdapterMcpResult
    },
    precomputedSkipServers?: string[]
  ): string | undefined {
    try {
      const featureFlags = this.resolveWorkspaceMcpFlags()

      const controlCallbacks = this.s.adapter.buildControlCallbacks({
        conversationId: this.s.currentConversationId ?? '',
        emit: (evt: string, payload: unknown) => this.s.emitAdapterEvent(evt, payload),
        getAccumulatedText: () => this.s.accumulatedText
      })

      let socketPath: string | undefined
      if (this.s.ipcBridge) {
        socketPath = this.s.ipcBridge.getSocketPath() ?? undefined
      }

      // Use pre-computed skip servers when available (caller already derived them
      // to gate the permissionPromptTool flag). Fall back to computing here for
      // callers that don't pre-compute.
      const skipServers = precomputedSkipServers ?? deriveSkipServers(_params.mcpResult.allowedTools)

      const configPath = this.s.mcpConfigWriter.writeConfig({
        workspacePath: this.s.workspacePath!,
        workspaceId: this.s.workspaceId,
        conversationId: this.s.currentConversationId,
        mode: this.s.currentMode,
        featureFlags,
        controlCallbacks,
        ipcSocketPath: socketPath,
        skipServers,
        instanceId: this.s.instanceId
      })

      this.s.log.info(`[buildCLIMcpConfigPath] MCP config written: ${configPath}`)
      return configPath
    } catch (error) {
      this.s.log.error('[buildCLIMcpConfigPath] CRITICAL: MCP config write failed:', error)
      throw error // Don't swallow — agent needs control tools
    }
  }

  // ── Permission mode resolution ──────────────────────────────────────

  /**
   * Map app-level ConversationMode to CLI --permission-mode values.
   *   plan   → 'plan'              (read-only + read-only shell)
   *   build  → 'acceptEdits'       (auto-approves working-dir file edits + common fs Bash)
   *   danger → 'bypassPermissions' (unrestricted)
   *
   * `acceptEdits` is preferred over `auto` for build mode because `auto`
   * requires account/model/provider support and silently falls back to
   * `default` (interactive prompts → blocked in our stream-json session)
   * when unavailable. `acceptEdits` is deterministic and needs no gating.
   */
  private resolveCliPermissionMode(mode: ConversationMode): 'plan' | 'acceptEdits' | 'bypassPermissions' {
    switch (mode) {
      case 'danger':
        return 'bypassPermissions'
      case 'build':
        return 'acceptEdits'
      default:
        return 'plan'
    }
  }

}

/**
 * Derive which MCP servers can be skipped from the CLI config based on the
 * adapter's allowedTools list.
 *
 * When an adapter defines an explicit allowedTools array (e.g. blueprint phases),
 * any MCP server whose tools are entirely absent from that list is unnecessary —
 * spawning it wastes a cold-start `node` process and increases the likelihood of
 * the MCP connection race (Root Cause A in the blueprint-tools diagnosis).
 *
 * Returns an array of server IDs (e.g. ['checkpoint-context', 'control-actions'])
 * suitable for CliMcpConfigWriterOptions.skipServers.
 */

import { MCP_TOOLS } from '../../shared/constants'

/**
 * MCP server groups that can be skipped if their tools aren't in allowedTools.
 * Maps server ID → prefix used in tool names (e.g. 'mcp__control-actions__').
 *
 * Servers NOT listed here are never skipped (e.g. git-context is always useful
 * since the CLI may expose it as a built-in tool).
 */
const SKIPPABLE_SERVERS: Array<{ id: string; prefix: string }> = [
  { id: 'checkpoint-context', prefix: MCP_TOOLS.CHECKPOINT_CONTEXT._PREFIX },
  { id: 'control-actions', prefix: MCP_TOOLS.CONTROL_ACTIONS._PREFIX },
  { id: 'github-context', prefix: MCP_TOOLS.GITHUB_CONTEXT._PREFIX },
  // Phase 1.3: Allow lean MCP config to skip these when their tools aren't in allowedTools
  { id: 'semantic-search', prefix: MCP_TOOLS.SEMANTIC_SEARCH._PREFIX },
  { id: 'code-analysis', prefix: MCP_TOOLS.CODE_ANALYSIS._PREFIX }
]

/**
 * Given an adapter's allowedTools list, return server IDs that should be
 * omitted from the MCP config because none of their tools are allowed.
 *
 * Returns an empty array when allowedTools is undefined (= all tools allowed).
 */
export function deriveSkipServers(allowedTools: string[] | undefined): string[] | undefined {
  // undefined means "all tools allowed" — don't skip anything
  if (!allowedTools) return undefined

  const skip: string[] = []
  for (const { id, prefix } of SKIPPABLE_SERVERS) {
    const hasToolFromServer = allowedTools.some((t) => t.startsWith(prefix))
    if (!hasToolFromServer) {
      skip.push(id)
    }
  }
  return skip.length > 0 ? skip : undefined
}

/**
 * ContextWindowResolver — determines the real context window for a local LLM.
 *
 * The SDK's `maxTokens` reports whatever the backend (oMLX / Ollama) advertises,
 * which can be significantly smaller than the model's actual capability:
 *   - oMLX: deliberately scales down the context window to trigger auto-compact at
 *     a safe threshold (e.g. reports 32K for a 131K model).
 *   - Ollama: defaults to VRAM-based sizing (32K for 24-48GB Macs).
 *
 * Resolution chain (first non-null wins):
 *   1. User override (workspace setting `localContextWindow`)
 *   2. Backend API query (oMLX admin or Ollama ps)
 *   3. Known model table (`RECOMMENDED_LOCAL_MODELS`)
 *   4. Hardcoded fallback (32768)
 */

import { RECOMMENDED_LOCAL_MODELS } from '../../shared/constants'
import type { LocalLLMConfig } from '../../shared/types'
import log from 'electron-log/main'

export class ContextWindowResolver {
  /**
   * Query oMLX for the actual model context window.
   * Tries `/admin/api/models` which may expose context info.
   */
  async queryOmlxContext(config: LocalLLMConfig): Promise<number | null> {
    const baseUrl = `http://${config.localHost}:${config.localPort}`
    try {
      const res = await fetch(`${baseUrl}/admin/api/models`, {
        signal: AbortSignal.timeout(3000)
      })
      if (res.ok) {
        const data = (await res.json()) as {
          models?: { id: string; context_window?: number; max_context_window?: number }[]
        }
        const model = data.models?.find(
          (m) => m.id === config.localModel || config.localModel.includes(m.id)
        )
        // oMLX may expose context_window or max_context_window in model metadata
        if (model?.context_window) return model.context_window
        if (model?.max_context_window) return model.max_context_window
      }
    } catch {
      /* not available — fall through */
    }
    return null
  }

  /**
   * Query Ollama for the actual allocated context window via `/api/ps`.
   */
  async queryOllamaContext(config: LocalLLMConfig): Promise<number | null> {
    const baseUrl = `http://${config.localHost}:${config.localPort}`
    try {
      const res = await fetch(`${baseUrl}/api/ps`, {
        signal: AbortSignal.timeout(3000)
      })
      if (res.ok) {
        const data = (await res.json()) as {
          models?: { name?: string; details?: { context_length?: number } }[]
        }
        const model = data.models?.find((m) => m.name?.includes(config.localModel))
        if (model?.details?.context_length) return model.details.context_length
      }
    } catch {
      /* not available — fall through */
    }
    return null
  }

  /**
   * Look up context window from the known model table.
   */
  fromKnownModels(modelId: string): number | null {
    const match = RECOMMENDED_LOCAL_MODELS.find(
      (m) => m.ollamaId === modelId || m.omlxId === modelId
    )
    return match?.contextWindow ?? null
  }

  /**
   * Full resolution chain.
   *
   * @param config  - Local LLM configuration (backend, host, port, model)
   * @param userOverride - Optional user-specified context window from workspace settings
   * @returns Resolved context window size in tokens
   */
  async resolve(config: LocalLLMConfig, userOverride?: number): Promise<number> {
    // 1. User override wins — user knows best
    if (userOverride && userOverride > 0) {
      log.info(`[ContextWindow] Using user override: ${userOverride}`)
      return userOverride
    }

    // 2. Query backend API
    const backendValue =
      config.backend === 'omlx'
        ? await this.queryOmlxContext(config)
        : await this.queryOllamaContext(config)
    if (backendValue) {
      log.info(`[ContextWindow] From ${config.backend} API: ${backendValue}`)
      return backendValue
    }

    // 3. Known model table (RECOMMENDED_LOCAL_MODELS)
    const knownValue = this.fromKnownModels(config.localModel)
    if (knownValue) {
      log.info(`[ContextWindow] From RECOMMENDED_LOCAL_MODELS: ${knownValue}`)
      return knownValue
    }

    // 4. Fallback — 128K is a safer default for modern models (2025+).
    // Most Qwen/Gemma/Llama class models support at least 128K context.
    // This classifies unknown models as 'medium' tier instead of 'small',
    // avoiding the critical issue where 8K context limit truncates the system prompt.
    log.warn(`[ContextWindow] Unknown model "${config.localModel}", defaulting to 131072`)
    return 131072
  }
}

export const contextWindowResolver = new ContextWindowResolver()

/**
 * OpenCode Executor — multi-provider runtime via @opencode-ai/sdk.
 *
 * Uses OpenCode's client-server model to provide access to 75+ AI providers
 * through a single executor. OpenCode handles:
 *   - Provider routing (Anthropic, Ollama, oMLX, OpenAI, Gemini, etc.)
 *   - Agent loop (tool calling, reasoning, multi-turn)
 *   - MCP server connections (configure in opencode.json)
 *   - Session management (create, prompt, stream)
 *   - Structured output (JSON schema via `format` parameter)
 *
 * Architecture:
 *   Electron Main → OpenCodeExecutor → OpenCode Server (in-process) → Provider
 *   Same pattern OpenCode Desktop uses — proven Electron-compatible.
 *
 * Phase 4B — OpenCode Evaluation: Prototype executor backend.
 */

import type { StreamChunk } from './agent-base.service'
import type { ExecutorResult, ExecutorTokenUsage } from './executor-types'
import type { OpencodeClient, SessionPromptData } from '@opencode-ai/sdk'
import type { ImageAttachment } from '../../shared/types'
import { normalizeOpenCodeEvent, type NormalizerState } from './opencode-event-normalizer'
import { ensureOpencodePathInEnv, getOpencodePath } from '../../shared/opencode-cli-path'
import log from 'electron-log/main'

const openCodeLog = log.scope('OpenCodeExecutor')

// ── Types ──

/**
 * Provider configuration for OpenCode.
 * Maps to opencode.json "provider" section.
 */
export interface OpenCodeProviderConfig {
  /** Provider ID (e.g. 'anthropic', 'ollama', 'openai', 'custom') */
  providerId: string
  /** Model ID within the provider (e.g. 'claude-sonnet-4-6', 'qwen3-coder:30b') */
  modelId: string
  /** Base URL for custom/local providers */
  baseUrl?: string
  /** API key (if required by the provider) */
  apiKey?: string
}

/**
 * MCP server configuration for OpenCode.
 * Maps to opencode.json "mcp" section.
 */
export interface OpenCodeMcpConfig {
  /** Server name → stdio command config */
  servers: Record<
    string,
    {
      type: 'local'
      command: string[]
      env?: Record<string, string>
    }
  >
}

/**
 * Execute options for the OpenCode executor.
 */
export interface OpenCodeExecuteOptions {
  prompt: string
  /** Image attachments to include with the prompt (vision) */
  images?: ImageAttachment[]
  systemPrompt: string
  provider: OpenCodeProviderConfig
  /** MCP servers to connect */
  mcpServers?: OpenCodeMcpConfig
  /** Working directory for the session */
  cwd: string
  /** Max turns for the agent loop */
  maxTurns?: number
  /** AbortController for cancellation */
  abortController?: AbortController
  /** JSON schema for structured output */
  outputSchema?: Record<string, unknown>
  /** Conversation ID for multi-turn session reuse */
  conversationId?: string
  /** A-1: Context parts to inject before the first prompt (priming). */
  primingContext?: Array<{ type: 'text'; text: string }>
}

/** Result metadata from OpenCode execution */
export interface OpenCodeExecuteResult extends ExecutorResult {
  /** OpenCode session ID */
  openCodeSessionId?: string
  /** Provider used for the response */
  providerId?: string
}

// ── Executor ──

/**
 * OpenCode executor — communicates with an in-process OpenCode server.
 *
 * Lifecycle:
 *   1. start() — initialize the OpenCode server + client
 *   2. execute() — stream a prompt through OpenCode's agent loop
 *   3. stop() — shut down the server
 *
 * The executor manages a single OpenCode server instance. Multiple
 * sessions can run concurrently through the same server.
 */
/** Transient error patterns that warrant retry with backoff */
const TRANSIENT_ERROR_PATTERNS = [
  /rate.?limit/i,
  /overloaded/i,
  /server_is_overloaded/i,
  /too many requests/i,
  /503/,
  /429/,
  /ECONNRESET/,
  /ETIMEDOUT/,
  /ECONNREFUSED/,
  /network/i,
  /timeout/i
]

/** Max retry attempts for transient errors */
const MAX_TRANSIENT_RETRIES = 3

/** Base delay for exponential backoff (ms) */
const BASE_RETRY_DELAY_MS = 2000

/** Default port used by the OpenCode SDK server */
const OPENCODE_SERVER_PORT = 4096

export class OpenCodeExecutor {
  // Store dynamic imports to handle ESM-only package
  private client: OpencodeClient | null = null
  /** Reference to the OpenCode server child process — needed for clean shutdown */
  private server: { url: string; close(): void } | null = null
  private isStarted = false
  /** Map of conversationId → OpenCode session ID for multi-turn reuse */
  private readonly sessionMap = new Map<string, string>()
  /** Consecutive error count for circuit breaker integration */
  private consecutiveErrors = 0
  /** In-flight transient-retry backoffs — a rising value signals a retry storm. */
  private retriesInFlight = 0
  /** Max consecutive errors before circuit breaker trips */
  private static readonly CIRCUIT_BREAKER_THRESHOLD = 5
  /** Health check polling interval (ms) */
  private static readonly HEALTH_CHECK_INTERVAL = 30_000
  /** Health check timer */
  private healthCheckTimer: ReturnType<typeof setInterval> | null = null
  /** Callback for health status changes */
  private onHealthChange?: (healthy: boolean, version?: string) => void
  /** MISS-2: Track child/subagent sessions — parent session ID → Set<child session IDs> */
  private readonly childSessions = new Map<string, Set<string>>()
  /** Last known cwd for auto-restart */
  private lastCwd?: string
  /** Last known config for auto-restart */
  private lastConfig?: Parameters<typeof this.start>[1]
  /** C-4: Promise that resolves when server.connected fires (MCP handshakes complete) */
  private serverReadyResolve?: () => void
  private serverReadyPromise?: Promise<void>
  /** EXEC-05: Track the serverReady fallback timeout so it can be cancelled */
  private serverReadyTimeout: ReturnType<typeof setTimeout> | null = null
  /** R6-A1: Persistent normalizer state — survives across events so dedupe sets,
   *  F16 lastPartType, and context-delta gating are preserved within a session. */
  private normalizerState: NormalizerState = {
    childSessions: this.childSessions,
    sessionMap: this.sessionMap
  }

   /**
    * Check if the OpenCode CLI is installed and available in PATH.
    * Returns an error message if CLI is not found, null if available.
    */
   async checkCliAvailable(): Promise<string | null> {
     try {
       const { execSync } = await import('node:child_process')

      // Use the cached resolved path (set at startup via resolveOpencodePath)
      const opencodePath = getOpencodePath()

      if (!opencodePath) {
        return (
          'OpenCode CLI not found. Install it by running:\n' +
          '  npm install -g @opencode-ai/cli\n' +
          'Or download from: https://opencode.ai/getting-started'
        )
      }

      // Try to get version
      const versionOutput = execSync('opencode --version', {
        encoding: 'utf-8',
        timeout: 5000,
      }).trim()

      openCodeLog.info(
        `[opencode] checkCliAvailable: path=${opencodePath}, version=${versionOutput}`
      )

      // Non-empty version output confirms the binary is installed and executable.
      // (The output format varies across versions — e.g. "1.17.9" vs "opencode v1.x")
      if (versionOutput) {
        openCodeLog.info(`[opencode] CLI available at: ${opencodePath}, version: ${versionOutput}`)
        ensureOpencodePathInEnv()
        return null
      }

      return (
        'OpenCode CLI found but returned empty version output.\n' +
        'Try reinstalling: npm install -g @opencode-ai/cli'
      )
    } catch (err) {
      const errorMsg = `Failed to check OpenCode CLI availability: ${(err as Error).message}`
      openCodeLog.error('[opencode]', errorMsg)
      return errorMsg
    }
  }

  /**
   * Start the OpenCode server in-process.
   *
   * This mirrors what OpenCode Desktop does — runs the server within
   * Electron's Node.js process for low-latency communication.
   */
  /** A-2: AbortController for cancelling startup if it hangs */
  private startupAbortController: AbortController | null = null

  async start(
    cwd: string,
    config?: {
      providers?: Record<string, { baseUrl?: string; apiKey?: string }>
      mcpServers?: OpenCodeMcpConfig
      /** Path to the opencode.json config file (now in temp dir) */
      configPath?: string
      /** Whether this is a local LLM provider (longer timeout) */
      isLocal?: boolean
    }
  ): Promise<void> {
    if (this.isStarted) {
      openCodeLog.info('[opencode] Server already running')
      return
    }

    // Pre-check: Validate OpenCode CLI is installed
    const cliError = await this.checkCliAvailable()
    if (cliError) {
      const cliErr = new Error(cliError)
      openCodeLog.error('[opencode]', cliErr.message)
      throw cliErr
    }

    try {
      // T-1: Ensure opencode path is in PATH (uses cached value from startup)
      // The SDK uses cross-spawn which relies on PATH.
      ensureOpencodePathInEnv()
      openCodeLog.info(`[opencode] Starting server in ${cwd}`)
      openCodeLog.info(`[opencode] Current env.PATH: ${process.env.PATH?.slice(0, 600)}...`)

      // OC-01: Clear stale env vars from any prior workspace to prevent
      // cross-workspace contamination when start() is called without stop()
      delete process.env.OPENCODE_CONFIG
      delete process.env.OPENCODE_EXPERIMENTAL_LSP_TOOL
      delete process.env.OPENCODE_ENABLE_EXA

      // OC-02: Read config content to pass inline via the SDK.
      // The SDK sets OPENCODE_CONFIG_CONTENT from options.config — if we don't pass it,
      // it defaults to "{}" which overrides any file-based OPENCODE_CONFIG.
      let configContent: Record<string, unknown> | undefined
      if (config?.configPath) {
        try {
          const { readFileSync } = await import('node:fs')
          configContent = JSON.parse(readFileSync(config.configPath, 'utf-8'))
          openCodeLog.info(`[opencode] Loaded config inline from ${config.configPath}`)
        } catch (err) {
          openCodeLog.warn(`[opencode] Failed to read config at ${config.configPath}:`, err)
        }
      }

      // OC-08: Log provider config summary for diagnostics (mask apiKey)
      if (configContent) {
        const providers = (configContent as any).provider ?? {}
        for (const [provId, provConfig] of Object.entries(providers)) {
          const opts = (provConfig as any)?.options ?? {}
          openCodeLog.info(
            `[opencode] Config provider [${provId}]: ` +
            `baseURL=${opts.baseURL ?? '(none)'}, ` +
            `apiKey=${opts.apiKey ? '***' + String(opts.apiKey).slice(-3) : '(none)'}, ` +
            `npm=${(provConfig as any)?.npm ?? '(builtin)'}`
          )
        }
      }

      // ENH-3: Enable experimental LSP tool (goToDefinition, findReferences, etc.)
      process.env.OPENCODE_EXPERIMENTAL_LSP_TOOL = 'true'

      // E-9: Enable web search/fetch tools when configured
      // The actual tool availability is controlled by the tools config in opencode.json;
      // this env var is the global gate required by OpenCode's privacy model.
      if (process.env.CODE_ATELIER_WEB_SEARCH === 'true') {
        process.env.OPENCODE_ENABLE_EXA = 'true'
      }

      // A-2: Pass timeout and signal for startup cancellation.
      // Local models (Ollama/oMLX) may need 30s+ to cold-start.
      this.startupAbortController = new AbortController()
      const startupTimeout = config?.isLocal ? 30_000 : 10_000

      // PORT-FIX: Kill any stale opencode server process that may hold the port
      // from a prior crash / ungraceful shutdown. Without this, createOpencode fails
      // with "ServeError" because port 4096 is already in use.
      await this.killStaleServer()

      // OC-05: Pre-install provider npm package if needed.
      // OpenCode auto-installs on first run, but this takes time and can cause
      // server.connected timeout. Pre-installing avoids the cold-start delay.
      // IMPORTANT: The .opencode/ directory is managed by the OpenCode server.
      // We must not create a conflicting package.json — just install into the
      // existing node_modules if the package is missing.
      if (configContent) {
        const providers = (configContent as any).provider ?? {}
        for (const [provId, provConfig] of Object.entries(providers)) {
          const npmPkg = (provConfig as any)?.npm
          if (npmPkg) {
            const { join } = await import('node:path')
            const { existsSync } = await import('node:fs')
            const { execSync } = await import('node:child_process')
            const opencodeDir = join(cwd, '.opencode')
            const pkgDir = join(opencodeDir, 'node_modules', ...npmPkg.split('/'))
            if (!existsSync(pkgDir)) {
              openCodeLog.info(`[opencode] Pre-installing ${npmPkg} for provider ${provId}...`)
              try {
                // Install into the existing .opencode/ dir managed by the OpenCode server.
                // Use --save so the package persists in the existing package.json dependency tree.
                execSync(`npm install ${npmPkg} --prefix "${opencodeDir}"`, {
                  timeout: 30_000,
                  stdio: 'pipe',
                  cwd: opencodeDir
                })
                openCodeLog.info(`[opencode] Pre-installed ${npmPkg} successfully`)
              } catch (err) {
                openCodeLog.warn(`[opencode] Failed to pre-install ${npmPkg}:`, err)
                // Non-fatal — server may still auto-install
              }
            } else {
              openCodeLog.info(`[opencode] ${npmPkg} already installed for provider ${provId}`)
            }
          }
        }
      }

      openCodeLog.info(`[opencode] Calling createOpencode with port ${OPENCODE_SERVER_PORT}, timeout ${startupTimeout}ms`)

      // Import the SDK to get createOpencode function
      const { createOpencode } = await import('@opencode-ai/sdk')

      // OC-04: Set CWD to workspace so opencode serve inherits the correct project directory.
      // The SDK's createOpencodeServer() doesn't support a `cwd` option, and `opencode serve`
      // doesn't support `--project`. The child process CWD is determined at spawn time.
      const originalCwd = process.cwd()
      process.chdir(cwd)
      openCodeLog.info(`[opencode] Set CWD to workspace: ${cwd}`)

      // OC-09: Isolate from global opencode config to prevent personal MCP servers
      // (e.g. ~/.config/opencode/opencode.json registering a "pencil" MCP) from
      // leaking into sessions. Point XDG_CONFIG_HOME at an empty app-controlled
      // directory so the opencode binary's global config resolves clean.
      const { tmpdir } = await import('node:os')
      const { join } = await import('node:path')
      const { mkdirSync } = await import('node:fs')
      const isolatedConfigHome = join(tmpdir(), 'agentstudio-opencode-xdg')
      mkdirSync(join(isolatedConfigHome, 'opencode'), { recursive: true })
      const savedXdgConfigHome = process.env.XDG_CONFIG_HOME
      process.env.XDG_CONFIG_HOME = isolatedConfigHome
      openCodeLog.info(`[opencode] Set XDG_CONFIG_HOME=${isolatedConfigHome} (was ${savedXdgConfigHome ?? 'unset'})`)

      // OC-10: Force XDG_DATA_HOME to temp dir so the opencode SQLite database
      // lives alongside the config — e2e-runner can reliably clean it.
      const savedXdgDataHome = process.env.XDG_DATA_HOME
      process.env.XDG_DATA_HOME = isolatedConfigHome
      openCodeLog.info(`[opencode] Set XDG_DATA_HOME=${isolatedConfigHome} (was ${savedXdgDataHome ?? 'unset'})`)

      let result: Awaited<ReturnType<typeof createOpencode>>
      try {
        result = await createOpencode({
          port: OPENCODE_SERVER_PORT,
          timeout: startupTimeout,
          signal: this.startupAbortController.signal,
          // OC-02: Pass config inline so the SDK sets OPENCODE_CONFIG_CONTENT correctly.
          // Without this, the SDK defaults to "{}" which the server prioritizes over file-based config.
          ...(configContent ? { config: configContent as any } : {})
        })
      } finally {
        process.chdir(originalCwd)
        // Restore XDG_CONFIG_HOME so the Electron main process is unaffected
        if (savedXdgConfigHome !== undefined) {
          process.env.XDG_CONFIG_HOME = savedXdgConfigHome
        } else {
          delete process.env.XDG_CONFIG_HOME
        }
        if (savedXdgDataHome !== undefined) {
          process.env.XDG_DATA_HOME = savedXdgDataHome
        } else {
          delete process.env.XDG_DATA_HOME
        }
        openCodeLog.info(`[opencode] Restored CWD and XDG_*_HOME`)
      }

      // EXEC-06: Validate client exists before marking as started
      if (!result?.client) {
        throw new Error('OpenCode SDK initialization failed: no client returned')
      }
      this.client = result.client
      this.server = result.server ?? null
      this.isStarted = true

      // C-4: Set up serverReady promise — resolved when server.connected event fires.
      // This gates the first prompt to ensure MCP handshakes are complete.
      // EXEC-05: Cancel any prior timeout before creating a new promise
      if (this.serverReadyTimeout) {
        clearTimeout(this.serverReadyTimeout)
        this.serverReadyTimeout = null
      }
      this.serverReadyPromise = new Promise<void>((resolve) => {
        this.serverReadyResolve = resolve
        // Timeout fallback — don't block forever if event never fires
        // OC-06: Local providers need more time for npm installs + MCP handshakes
        const serverReadyTimeoutMs = config?.isLocal ? 30_000 : 10_000
        this.serverReadyTimeout = setTimeout(() => {
          if (this.serverReadyResolve) {
            openCodeLog.warn(
              `[opencode] server.connected not received within ${serverReadyTimeoutMs / 1000}s — proceeding anyway`
            )
            this.serverReadyResolve()
            this.serverReadyResolve = undefined
          }
          this.serverReadyTimeout = null
        }, serverReadyTimeoutMs)
      })

      // Store restart context for auto-recovery
      this.lastCwd = cwd
      this.lastConfig = config

      openCodeLog.info('[opencode] Server started successfully')
    } catch (error) {
      openCodeLog.error('[opencode] Failed to start server:', error)
      throw error
    }
  }

  // ── Event stream processing ────────────────────────────────────────────────

  /**
   * Handle a transient error chunk: yield recovery events, wait, resend.
   * Returns the updated retry count, or -1 if max retries are exhausted.
   */
  private async *handleTransientRetry(
    chunk: StreamChunk,
    retryCount: number,
    sessionId: string,
    promptBody: SessionPromptData['body']
  ): AsyncGenerator<StreamChunk, number> {
    const retry = this.computeTransientRetry(retryCount, chunk.error!)
    if (!retry) {
      // Max retries exhausted
      this.consecutiveErrors++
      openCodeLog.warn(
        `[opencode] Max transient retries exhausted (${this.consecutiveErrors} consecutive errors)`
      )
      return -1
    }

    yield {
      type: 'session_recovery',
      recoveryPhase: 'started',
      content: retry.startedMessage
    } as StreamChunk

    this.retriesInFlight++
    try {
      await new Promise((r) => setTimeout(r, retry.delayMs))
    } finally {
      this.retriesInFlight--
    }
    this.resendPrompt(sessionId, promptBody)

    yield {
      type: 'session_recovery',
      recoveryPhase: 'resuming',
      content: retry.resumingMessage
    } as StreamChunk

    return retry.attemptNumber
  }

  /**
   * Process the event stream, handling transient retries and turn counting.
   * Yields StreamChunks and collects resultText + maxTurnsReached status.
   */
  private async *processEventStream(params: {
    events: { stream: AsyncIterable<unknown> }
    openCodeSessionId: string
    promptBody: SessionPromptData['body']
    tokenUsage: ExecutorTokenUsage
    maxTurns: number
    abortController?: AbortController
  }): AsyncGenerator<StreamChunk, { resultText: string; maxTurnsReached: boolean }> {
    const { events, openCodeSessionId, promptBody, tokenUsage, maxTurns, abortController } = params
    let resultText = ''
    let turnCount = 0
    let maxTurnsReached = false
    let transientRetryCount = 0

    for await (const event of events.stream) {
      if (abortController?.signal.aborted) break

      let retryInitiatedThisEvent = false
      const chunks = this.normalizeEvent(event, openCodeSessionId, tokenUsage)
      for (const chunk of chunks) {
        if (chunk.type === 'text' && chunk.content) {
          resultText += chunk.content
        }

        // Handle transient errors with retry
        if (chunk.type === 'error' && chunk.error && this.isTransientError(chunk.error)) {
          const retryGen = this.handleTransientRetry(
            chunk, transientRetryCount, openCodeSessionId, promptBody
          )
          let retryResult = await retryGen.next()
          while (!retryResult.done) {
            yield retryResult.value
            retryResult = await retryGen.next()
          }
          const newRetryCount = retryResult.value
          if (newRetryCount >= 0) {
            transientRetryCount = newRetryCount
            retryInitiatedThisEvent = true
            continue
          }
          // Max retries exhausted — fall through to emit the error
        }

        // Count tool invocations as turns
        if (chunk.type === 'tool_use') {
          turnCount++
          if (maxTurns > 0 && turnCount >= maxTurns) {
            openCodeLog.info(
              `[opencode] maxTurns reached (${turnCount}/${maxTurns}) — aborting session`
            )
            maxTurnsReached = true
            if (this.client) {
              this.client.session
                .abort({ path: { id: openCodeSessionId } })
                .catch(() => {}) /* non-fatal: best-effort abort after maxTurns */
            }
          }
        }

        yield chunk
      }

      if (maxTurnsReached) break

      // Only suppress session.error when a retry was actually initiated for THIS event.
      // Without this, the first non-retried error gets suppressed forever (deadlock).
      const retriesAvailable = retryInitiatedThisEvent
      if (this.isSessionComplete(event, openCodeSessionId, retriesAvailable)) {
        break
      }
    }

    return { resultText, maxTurnsReached }
  }

  // ── execute ──────────────────────────────────────────────────────────

  /**
   * Execute a prompt through OpenCode's agent loop.
   * Streams events as StreamChunks for UI display.
   */
  async *execute(
    options: OpenCodeExecuteOptions
  ): AsyncGenerator<StreamChunk & { _meta?: OpenCodeExecuteResult }> {
    if (!this.client || !this.isStarted) {
      yield { type: 'error', error: 'OpenCode server not started — call start() first' }
      return
    }

    // Circuit breaker check
    if (this.consecutiveErrors >= OpenCodeExecutor.CIRCUIT_BREAKER_THRESHOLD) {
      yield {
        type: 'error',
        error:
          `OpenCode circuit breaker open: ${this.consecutiveErrors} consecutive errors. ` +
          `The provider may be down. Please try again later or switch providers.`
      }
      return
    }

    const { prompt, images, systemPrompt, provider, abortController, outputSchema } = options

    const tokenUsage: ExecutorTokenUsage = {
      input: 0,
      output: 0,
      cacheReadInputTokens: 0,
      cacheCreationInputTokens: 0
    }

    let openCodeSessionId: string | undefined

    try {
      // C-4: Wait for server.connected before first prompt to ensure MCP handshakes complete
      if (this.serverReadyPromise) {
        await this.serverReadyPromise
        this.serverReadyPromise = undefined
      }

      // Get or create session for multi-turn reuse
      openCodeSessionId = await this.getOrCreateSession(options)
      if (!openCodeSessionId) {
        yield { type: 'error', error: 'Failed to create OpenCode session' }
        return
      }

      // Subscribe to events for streaming
      const events = await this.client.event.subscribe()

      // Build the prompt body (parts + model config + output schema)
      const promptBody = this.buildPromptBody(prompt, systemPrompt, provider, outputSchema, images)

      // ENH-13: Update session title with meaningful content from the user's prompt
      const titleText = prompt.slice(0, 80).replace(/\n/g, ' ').trim()
      const sessionTitle = titleText.length < prompt.length ? `${titleText}…` : titleText
      this.client.session
        .update?.({
          path: { id: openCodeSessionId },
          body: { title: sessionTitle }
        })
        ?.catch(() => {
          /* non-fatal: session title is cosmetic */
        })

      // OC-04: Fire-and-forget prompt via the async endpoint.
      // promptAsync → POST /session/{id}/prompt_async → returns 204 immediately.
      // Events arrive via SSE (event.subscribe). The synchronous session.prompt()
      // blocks until the full AI response completes, which holds an HTTP connection
      // open for the entire agent loop — wrong pattern for streaming.
      let promptSendError: Error | null = null
      this.client.session
        .promptAsync({
          path: { id: openCodeSessionId },
          body: promptBody
        })
        .then((response) => {
          // OC-07: Check the error field — HTTP 4xx/5xx errors land here.
          // promptAsync returns 204 (void) on success, so data is undefined.
          const errorData = (response as any)?.error
          if (errorData) {
            const errorMsg =
              errorData?.data?.message ?? errorData?.message ?? JSON.stringify(errorData)
            openCodeLog.error(`[opencode] Prompt REJECTED by server: ${errorMsg}`)
            promptSendError = new Error(`OpenCode server error: ${errorMsg}`)
            return
          }

          // 204 accepted — the server is processing via the agent loop.
          // Events will arrive on the SSE stream.
          openCodeLog.info('[opencode] Prompt accepted (204)')
        })
        .catch((err) => {
          openCodeLog.error('[opencode] Prompt send error:', err)
          promptSendError = err instanceof Error ? err : new Error(String(err))
        })

      // OC-07: Start a watcher that breaks the stream if the prompt send fails.
      // The prompt is fire-and-forget — if the server returns 500, the stream
      // will hang forever because no events will be emitted.
      const promptErrorWatcher = setInterval(() => {
        if (promptSendError && abortController && !abortController.signal.aborted) {
          openCodeLog.warn('[opencode] Prompt send failed — aborting event stream')
          abortController.abort(promptSendError)
        }
      }, 500)

      // Process event stream
      let resultText = ''
      let maxTurnsReached = false

      if (events.stream) {
        const streamGen = this.processEventStream({
          events: events as { stream: AsyncIterable<unknown> },
          openCodeSessionId,
          promptBody,
          tokenUsage,
          maxTurns: options.maxTurns ?? 0,
          abortController
        })
        let streamResult = await streamGen.next()
        while (!streamResult.done) {
          yield streamResult.value
          streamResult = await streamGen.next()
        }
        ;({ resultText, maxTurnsReached } = streamResult.value)
      }

      clearInterval(promptErrorWatcher)

      // OC-04: If prompt send failed before/during streaming, surface the error
      if (promptSendError) {
        yield { type: 'error', error: `Prompt send failed: ${(promptSendError as Error).message}` }
        return
      }

      // Success — reset consecutive error counter
      this.consecutiveErrors = 0

      // Final status
      yield {
        type: 'status',
        content: 'complete',
        _meta: {
          result: resultText || undefined,
          tokenUsage,
          openCodeSessionId,
          providerId: provider.providerId,
          terminalReason: maxTurnsReached ? 'max_turns' : 'completed'
        }
      } as StreamChunk & { _meta: OpenCodeExecuteResult }
    } catch (error) {
      if ((error as Error).name === 'AbortError') {
        openCodeLog.info('[opencode] Request aborted')
        if (openCodeSessionId && this.client) {
          this.client.session
            .abort({ path: { id: openCodeSessionId } })
            .catch(() => {}) /* non-fatal: best-effort abort on user cancellation */
        }
      } else {
        this.consecutiveErrors++
        const errorDetails = {
          message: (error as Error).message,
          name: (error as Error).name,
          stack: (error as Error).stack,
          code: (error as any)?.code,
          syscall: (error as any)?.syscall,
          path: (error as any)?.path,
          spawnargs: (error as any)?.spawnargs,
          platform: process.platform,
          envPATH: process.env.PATH?.slice(0, 600),
        }
        openCodeLog.error(
          `[opencode] Execution error (consecutive=${this.consecutiveErrors}):`,
          errorDetails
        )
        openCodeLog.error(
          `[opencode] Current PATH: ${process.env.PATH || 'not set'}`
        )

        // Provide helpful troubleshooting info in the error message
        const helpMessage = `OpenCode error: ${(error as Error).message}

Troubleshooting:
- Check that opencode is installed: npm install -g @opencode-ai/cli
- Check the opencode path: which opencode
- Ensure the opencode directory is in PATH: echo $PATH
- Current PATH: ${process.env.PATH?.slice(0, 300) || 'not set'}`

        yield { type: 'error', error: helpMessage }
      }
    }
  }

  /**
   * Stop the OpenCode server and clean up resources.
   */
  async stop(): Promise<void> {
    if (!this.isStarted) return

    // A-2: Cancel any in-progress startup
    if (this.startupAbortController) {
      this.startupAbortController.abort()
      this.startupAbortController = null
    }

    this.stopHealthCheck()
    openCodeLog.info('[opencode] Stopping server')

    // PORT-FIX: Close the server child process so the port is released.
    // Previously this reference was never stored, leaving orphaned processes.
    if (this.server) {
      try {
        this.server.close()
      } catch (err) {
        openCodeLog.warn('[opencode] Error closing server:', err)
      }
      this.server = null
    }

    this.client = null
    this.isStarted = false
    this.sessionMap.clear()
    this.consecutiveErrors = 0

    // EXEC-05: Cancel the serverReady fallback timeout
    if (this.serverReadyTimeout) {
      clearTimeout(this.serverReadyTimeout)
      this.serverReadyTimeout = null
    }
    this.serverReadyResolve = undefined
    this.serverReadyPromise = undefined

    // EXEC-01: Clean up global env vars set during start() to prevent
    // cross-session contamination when switching workspaces
    delete process.env.OPENCODE_CONFIG
    delete process.env.OPENCODE_EXPERIMENTAL_LSP_TOOL
    delete process.env.OPENCODE_ENABLE_EXA
  }

  /**
   * MISS-14: Check if the OpenCode server is healthy.
   * The SDK exposes no dedicated health endpoint, so we issue a lightweight,
   * non-destructive session.list() call — success implies the server responds.
   */
  async checkHealth(): Promise<{ healthy: boolean; version?: string }> {
    if (!this.client || !this.isStarted) {
      return { healthy: false }
    }
    try {
      await this.client.session.list()
      return { healthy: true }
    } catch (err) {
      openCodeLog.warn(`[opencode] Health check failed: ${(err as Error).message}`)
      return { healthy: false }
    }
  }

  /**
   * MISS-14: Start periodic health monitoring.
   * Polls global.health() and attempts auto-restart on failure.
   *
   * @param onHealthChange - Callback when health state transitions
   */
  startHealthCheck(onHealthChange?: (healthy: boolean, version?: string) => void): void {
    this.stopHealthCheck()
    this.onHealthChange = onHealthChange

    let wasHealthy = true
    let consecutiveFailures = 0

    this.healthCheckTimer = setInterval(async () => {
      const { healthy, version } = await this.checkHealth()

      if (healthy) {
        if (!wasHealthy) {
          openCodeLog.info(`[opencode] Server recovered (version: ${version ?? 'unknown'})`)
          this.onHealthChange?.(true, version)
        }
        wasHealthy = true
        consecutiveFailures = 0
      } else {
        consecutiveFailures++
        openCodeLog.warn(`[opencode] Health check failed (${consecutiveFailures} consecutive)`)

        if (wasHealthy) {
          this.onHealthChange?.(false)
          wasHealthy = false
        }

        // Attempt auto-restart after 3 consecutive failures
        if (consecutiveFailures >= 3 && this.lastCwd) {
          openCodeLog.info('[opencode] Attempting auto-restart after 3 health check failures')
          try {
            await this.stop()
            await this.start(this.lastCwd, this.lastConfig)
            this.onHealthChange?.(true)
            consecutiveFailures = 0
            wasHealthy = true
          } catch (err) {
            openCodeLog.error('[opencode] Auto-restart failed:', err)
          }
        }
      }
    }, OpenCodeExecutor.HEALTH_CHECK_INTERVAL)
  }

  /**
   * Stop the health check polling.
   */
  stopHealthCheck(): void {
    if (this.healthCheckTimer) {
      clearInterval(this.healthCheckTimer)
      this.healthCheckTimer = null
    }
  }

  /**
   * MISS-2: Get tracked child session IDs for a parent session.
   */
  getChildSessions(parentSessionId: string): string[] {
    return Array.from(this.childSessions.get(parentSessionId) ?? [])
  }

  /**
   * MISS-2: Query the server for child sessions (may include sessions
   * created before we started tracking).
   */
  async fetchChildSessions(sessionId: string): Promise<Array<{ id: string; status?: string }>> {
    if (!this.client) return []
    try {
      const result = await this.client.session.children({
        path: { id: sessionId }
      })
      const children =
        ((result as Record<string, unknown>)?.data as Array<Record<string, unknown>>) ?? []
      return children.map((c) => ({
        id: c.id as string,
        status: c.status as string | undefined
      }))
    } catch (err) {
      openCodeLog.warn(`[opencode] Failed to fetch child sessions: ${(err as Error).message}`)
      return []
    }
  }

  /**
   * MISS-7: Validate that our agent definitions loaded correctly in OpenCode.
   * Returns the list of available agents and flags any that failed to load.
   */
  async validateAgents(): Promise<{
    agents: Array<{ name: string; model?: string; mode?: string }>
    missingExpected: string[]
  }> {
    if (!this.client) return { agents: [], missingExpected: ['DaVinci'] }
    try {
      const result = await (
        this.client as Record<string, unknown> & typeof this.client
      ).app?.agents?.()
      const agentList =
        ((result as Record<string, unknown>)?.data as Array<Record<string, unknown>>) ?? []
      const agents = agentList.map((a) => ({
        name: a.name as string,
        model: a.model as string | undefined,
        mode: a.mode as string | undefined
      }))

      // Check that our expected agents are present
      const agentNames = new Set(agents.map((a) => a.name))
      // B-1: Include Grill and Audit subagents in expected list
      const expectedAgents = ['DaVinci', 'Grill', 'Audit']
      const missingExpected = expectedAgents.filter((name) => !agentNames.has(name))

      if (missingExpected.length > 0) {
        openCodeLog.warn(`[opencode] Missing expected agents: ${missingExpected.join(', ')}`)
      } else {
        openCodeLog.info(
          `[opencode] Agent validation passed: ${agents.map((a) => a.name).join(', ')}`
        )
      }

      return { agents, missingExpected }
    } catch (err) {
      openCodeLog.warn(`[opencode] Agent validation failed: ${(err as Error).message}`)
      return { agents: [], missingExpected: ['DaVinci'] }
    }
  }

  /**
   * Clear a specific session mapping (e.g. on conversation switch or error).
   */
  clearSession(conversationId: string): void {
    this.sessionMap.delete(conversationId)
  }

  /**
   * Get the OpenCode session ID for a conversation (if any).
   */
  getSessionId(conversationId: string): string | undefined {
    return this.sessionMap.get(conversationId)
  }

  /**
   * Check if the server is running.
   */
  isRunning(): boolean {
    return this.isStarted
  }

  /**
   * E-4/B-4: Prime a session with context using noReply: true.
   *
   * Injects workspace context (git changes, plan state, memory context) into
   * the session without triggering an AI response. This is cleaner than
   * prepending context as text parts in the actual prompt.
   *
   * B-4: Also uses session.shell() to gather git context within the session
   * context naturally, without consuming a tool turn.
   *
   * Call this after session creation but before the first real prompt.
   */
  async primeSession(
    sessionId: string,
    contextParts: Array<{ type: 'text'; text: string }>
  ): Promise<void> {
    if (!this.client || !contextParts.length) return

    // Wrap in a timeout — priming is best-effort and must never block the real prompt.
    // enrichGitContext and session.prompt (synchronous) can hang if MCP handshakes are incomplete.
    const PRIMING_TIMEOUT_MS = 8_000
    const timeoutPromise = new Promise<'timeout'>((resolve) =>
      setTimeout(() => resolve('timeout'), PRIMING_TIMEOUT_MS)
    )

    const primingWork = (async () => {
      // 6E-2/B-4: Enrich git context via file.status() or session.shell() fallback
      await this.enrichGitContext(sessionId, contextParts)

      await this.client!.session.prompt({
        path: { id: sessionId },
        body: {
          parts: contextParts,
          noReply: true
        }
      })
      return 'done' as const
    })()

    try {
      const result = await Promise.race([primingWork, timeoutPromise])
      if (result === 'timeout') {
        openCodeLog.warn(
          `[opencode] Session priming timed out after ${PRIMING_TIMEOUT_MS}ms — proceeding without priming`
        )
      } else {
        openCodeLog.info(
          `[opencode] Session ${sessionId} primed with ${contextParts.length} context parts`
        )
      }
    } catch (err) {
      // Non-fatal — priming failure shouldn't block the real prompt
      openCodeLog.warn(`[opencode] Session priming failed: ${(err as Error).message}`)
    }
  }

  /**
   * 6E-2/B-4: Enrich git context in priming parts via dual-fallback.
   * Uses file.status() for structured uncommitted changes.
   * Mutates the matching contextParts entry in place.
   */
  private async enrichGitContext(
    _sessionId: string,
    contextParts: Array<{ type: 'text'; text: string }>
  ): Promise<void> {
    if (!this.client) return

    const gitIdx = contextParts.findIndex((p) =>
      p.text.includes('[Workspace Context: Recent Changes]')
    )
    if (gitIdx < 0) return

    // Try file.status() first for structured uncommitted changes
    try {
      const fileStatus = await this.client.file.status({})
      if (fileStatus.data && fileStatus.data.length > 0) {
        const statusLines = fileStatus.data
          .map((f: { status: string; path: string }) => `  ${f.status} ${f.path}`)
          .join('\n')
        contextParts[gitIdx] = {
          type: 'text',
          text: `[Workspace Context: Uncommitted Changes]\n${statusLines}`
        }
        return
      }
    } catch {
      // file.status() not available — keep the static context parts.
      // (A session.shell() git-diff fallback was removed: the SDK's shell
      // response is an AssistantMessage with no stdout field to read.)
    }
  }

  /**
   * #2: Abort a running session. Called from cancelCurrentQuery().
   */
  async abortSession(sessionId: string): Promise<void> {
    if (!this.client) return
    await this.client.session.abort({ path: { id: sessionId } })

    // 6E-3: Cascade cancellation to child/subagent sessions.
    // Prevents orphaned sessions from burning tokens after parent abort.
    const children = this.childSessions.get(sessionId)
    if (children && children.size > 0) {
      for (const childId of children) {
        try {
          await this.client.session.abort({ path: { id: childId } })
          openCodeLog.info(`[opencode] Cascaded abort to child session ${childId}`)
        } catch {
          // Child may already be done or deleted — non-fatal
        }
      }
    }

    openCodeLog.info(`[opencode] Session ${sessionId} aborted`)
  }

  /**
   * #1: Revert a session to a specific message (undo support).
   * Uses OpenCode's native session.revert() which preserves session history
   * and restores file snapshots — more reliable than creating a fresh session.
   */
  async revertSession(sessionId: string, messageId: string): Promise<void> {
    if (!this.client) throw new Error('OpenCode server not started')
    await this.client.session.revert({
      path: { id: sessionId },
      body: { messageID: messageId }
    })
    openCodeLog.info(`[opencode] Session ${sessionId} reverted to message ${messageId}`)
  }

  /**
   * #1: Cancel a revert operation.
   */
  async unrevertSession(sessionId: string): Promise<void> {
    if (!this.client) throw new Error('OpenCode server not started')
    await this.client.session.unrevert({ path: { id: sessionId } })
    openCodeLog.info(`[opencode] Session ${sessionId} unrevert applied`)
  }

  /**
   * #11: Generate a human-readable summary of a session.
   */
  async summarizeSession(sessionId: string): Promise<string | undefined> {
    if (!this.client) throw new Error('OpenCode server not started')
    const result = await this.client.session.summarize({ path: { id: sessionId } })
    return (result as Record<string, unknown>)?.data as string | undefined
  }

  /**
   * MISS-1: Execute a slash command within a session.
   * Wraps session.command() for commands like /compact, /share, /init, /undo, /redo.
   */
  async executeCommand(
    sessionId: string,
    command: string,
    args?: string
  ): Promise<{ success: boolean; data?: unknown; error?: string }> {
    if (!this.client) return { success: false, error: 'OpenCode server not started' }
    try {
      const result = await this.client.session.command({
        path: { id: sessionId },
        body: { command, arguments: args ?? '' }
      })
      openCodeLog.info(`[opencode] Command /${command} executed on session ${sessionId}`)
      return { success: true, data: (result as Record<string, unknown>)?.data }
    } catch (err) {
      openCodeLog.error(`[opencode] Command /${command} failed:`, err)
      return { success: false, error: (err as Error).message }
    }
  }

  /**
   * MISS-1: Convenience wrappers for common commands.
   */
  async compactSession(sessionId: string): Promise<{ success: boolean; error?: string }> {
    return this.executeCommand(sessionId, 'compact')
  }

  async shareSession(
    sessionId: string
  ): Promise<{ success: boolean; data?: unknown; error?: string }> {
    return this.executeCommand(sessionId, 'share')
  }

  async initProject(sessionId: string): Promise<{ success: boolean; error?: string }> {
    return this.executeCommand(sessionId, 'init')
  }

  /**
   * GAP-17: Auto-compact when context usage exceeds a threshold.
   * Called by the normalizer when context_usage_update shows high usage.
   */
  async autoCompactIfNeeded(
    sessionId: string,
    percentage: number,
    threshold = 80
  ): Promise<boolean> {
    if (percentage < threshold) return false
    openCodeLog.info(
      `[opencode] Context usage ${percentage}% >= ${threshold}% — triggering auto-compact`
    )
    const result = await this.compactSession(sessionId)
    return result.success
  }

  /**
   * GAP-17: Switch the active agent via /agent command.
   * Useful for task-type-based agent switching (review → Grill, health → Audit).
   */
  async switchAgent(
    sessionId: string,
    agentName: string
  ): Promise<{ success: boolean; error?: string }> {
    return this.executeCommand(sessionId, 'agent', agentName)
  }

  /**
   * GAP-17: Switch mode via /mode command.
   * Called when the user switches modes in our UI.
   */
  async switchMode(
    sessionId: string,
    mode: 'plan' | 'build' | 'danger'
  ): Promise<{ success: boolean; error?: string }> {
    return this.executeCommand(sessionId, 'mode', mode)
  }

  /**
   * GAP-24: Verify that the configured provider is available before the first prompt.
   * For local LLMs (Ollama), pings the health endpoint. For cloud providers, checks
   * that the provider appears in config.providers().
   * Returns a descriptive error string if the provider is down, or null if OK.
   */
  async verifyProvider(providerId: string, baseUrl?: string): Promise<string | null> {
    // For local providers, ping the health endpoint directly
    const localCheck = await this.checkLocalProviderHealth(providerId, baseUrl)
    if (localCheck) return localCheck

    // For all providers, verify via SDK if available
    if (this.client) {
      try {
        const providers = await this.getProviders()
        const found = providers.find((p) => p.id === providerId)
        if (!found) {
          return `Provider "${providerId}" not found. Available: ${providers.map((p) => p.id).join(', ') || 'none'}`
        }
      } catch {
        // Non-fatal — SDK may not be ready yet
      }
    }

    return null
  }

  /**
   * GAP-20: Pin a session for quick-switch access.
   * Keeps the active workspace session accessible even with many sessions.
   */
  async pinSession(sessionId: string): Promise<{ success: boolean; error?: string }> {
    if (!this.client) return { success: false, error: 'OpenCode server not started' }
    // The OpenCode SDK exposes no session-pin API (session.update only accepts
    // `title`). Pinning is a local-only UI affordance, so this is a no-op stub
    // that reports success without a server round-trip.
    openCodeLog.info(`[opencode] pinSession is a local-only no-op for session ${sessionId}`)
    return { success: true }
  }

  /**
   * MISS-8: Query available providers and their default models.
   * Can be used to auto-populate the model picker UI.
   */
  async getProviders(): Promise<Array<{ id: string; name?: string; defaultModel?: string }>> {
    if (!this.client) return []
    try {
      const result = await (
        this.client as Record<string, unknown> & typeof this.client
      ).config?.providers?.()
      const providers =
        ((result as Record<string, unknown>)?.data as Array<Record<string, unknown>>) ?? []
      return providers.map((p) => ({
        id: p.id as string,
        name: p.name as string | undefined,
        defaultModel: p.defaultModel as string | undefined
      }))
    } catch (err) {
      openCodeLog.warn(`[opencode] Failed to fetch providers: ${(err as Error).message}`)
      return []
    }
  }

  /**
   * MISS-9: Retrieve all messages in a session for state reconciliation.
   */
  async getSessionMessages(
    sessionId: string
  ): Promise<Array<{ id: string; role: string; content?: string }>> {
    if (!this.client) return []
    try {
      const result = await this.client.session.messages({
        path: { id: sessionId }
      })
      const messages =
        ((result as Record<string, unknown>)?.data as Array<Record<string, unknown>>) ?? []
      return messages.map((m) => ({
        id: m.id as string,
        role: m.role as string,
        content: m.content as string | undefined
      }))
    } catch (err) {
      openCodeLog.warn(`[opencode] Failed to fetch session messages: ${(err as Error).message}`)
      return []
    }
  }

  /**
   * MISS-12: Respond to a permission request from the agent.
   * Called when the user approves/denies a tool use in the Electron UI.
   */
  async respondToPermission(
    sessionId: string,
    permissionId: string,
    allowed: boolean
  ): Promise<void> {
    if (!this.client) throw new Error('OpenCode server not started')
    try {
      await this.client.postSessionIdPermissionsPermissionId({
        path: { id: sessionId, permissionID: permissionId },
        body: { response: allowed ? 'always' : 'reject' }
      })
      openCodeLog.info(
        `[opencode] Permission ${allowed ? 'granted' : 'denied'} for ${permissionId}`
      )
    } catch (err) {
      openCodeLog.error(`[opencode] Failed to respond to permission ${permissionId}:`, err)
      throw err
    }
  }

  /**
   * Expose the client instance for direct SDK calls (used by error recovery).
   */
  getClient(): typeof this.client {
    return this.client
  }

  // ── Private helpers ──

  /**
   * GAP-24: Check local provider health by pinging their HTTP endpoint.
   * Returns a descriptive error string if unreachable, or null if healthy/not-local.
   */
  private async checkLocalProviderHealth(
    providerId: string,
    baseUrl?: string
  ): Promise<string | null> {
    const LOCAL_PROVIDERS: Record<
      string,
      { defaultUrl: string; healthPath: string; hint?: string }
    > = {
      ollama: {
        defaultUrl: 'http://localhost:11434',
        healthPath: '/api/tags',
        hint: 'Try: ollama serve'
      },
      omlx: { defaultUrl: 'http://localhost:8000', healthPath: '/v1/models' }
    }

    const provider = LOCAL_PROVIDERS[providerId]
    if (!provider) return null

    const url = baseUrl ?? provider.defaultUrl
    try {
      const response = await fetch(`${url}${provider.healthPath}`, {
        signal: AbortSignal.timeout(5000)
      })
      if (!response.ok) {
        return `${providerId} is not responding (HTTP ${response.status}). Ensure ${providerId} is running at ${url}`
      }
    } catch {
      const hint = provider.hint ? ` ${provider.hint}` : ''
      return `Cannot reach ${providerId} at ${url}. Is it running?${hint}`
    }

    return null
  }

  /**
   * #3: Check if an error message indicates a transient/retriable condition.
   */
  private isTransientError(errorMessage: string): boolean {
    return TRANSIENT_ERROR_PATTERNS.some((pattern) => pattern.test(errorMessage))
  }

  /**
   * Compute retry state for a transient error. Returns null when retries exhausted.
   */
  private computeTransientRetry(
    currentRetryCount: number,
    errorMessage: string
  ): {
    attemptNumber: number
    delayMs: number
    startedMessage: string
    resumingMessage: string
  } | null {
    if (currentRetryCount >= MAX_TRANSIENT_RETRIES) return null

    const attemptNumber = currentRetryCount + 1
    const delayMs = BASE_RETRY_DELAY_MS * Math.pow(2, attemptNumber - 1)
    openCodeLog.info(
      `[opencode] Transient error detected, retrying in ${delayMs}ms ` +
        `(attempt ${attemptNumber}/${MAX_TRANSIENT_RETRIES}): ${errorMessage}`
    )

    return {
      attemptNumber,
      delayMs,
      startedMessage: `Transient error detected — retrying in ${Math.round(delayMs / 1000)}s (attempt ${attemptNumber}/${MAX_TRANSIENT_RETRIES})`,
      resumingMessage: `Retry ${attemptNumber} in progress...`
    }
  }

  /**
   * Re-send a prompt to the OpenCode session (fire-and-forget for retries).
   */
  private resendPrompt(sessionId: string, promptBody: SessionPromptData['body']): void {
    this.client!.session.promptAsync({
      path: { id: sessionId },
      body: promptBody
    }).catch((err) => {
      openCodeLog.error('[opencode] Retry prompt error:', err)
    })
  }

  /**
   * Get or create an OpenCode session for the given options.
   * Handles session reuse for multi-turn conversations and priming.
   */
  private async getOrCreateSession(options: OpenCodeExecuteOptions): Promise<string | undefined> {
    const { conversationId, provider } = options
    let sessionId: string | undefined

    if (conversationId) {
      sessionId = this.sessionMap.get(conversationId)
    }

    if (!sessionId) {
      const session = await this.client!.session.create({
        body: { title: `Code Atelier: ${new Date().toISOString()}` }
      })
      sessionId = session.data?.id
      if (!sessionId) {
        // Log the full response so config/provider errors are diagnosable
        openCodeLog.error(
          '[opencode] session.create returned no ID — response:',
          JSON.stringify(session.data ?? session, null, 2)
        )
        return undefined
      }

      if (conversationId) {
        this.sessionMap.set(conversationId, sessionId)
      }

      openCodeLog.info(
        `[opencode] Session ${sessionId} created — provider=${provider.providerId}/${provider.modelId}`
      )

      // A-1: Prime the session with workspace context before the first real prompt
      if (options.primingContext && options.primingContext.length > 0) {
        await this.primeSession(sessionId, options.primingContext)
      }
    } else {
      openCodeLog.info(`[opencode] Reusing session ${sessionId} for conversation=${conversationId}`)
    }

    return sessionId
  }

  /**
   * Build the prompt body with parts, model config, and optional output schema.
   * D-1: System prompt uses the SDK `system` field (proper channel for model instructions).
   * When the plugin hook is active, it injects system prompt via its own mechanism.
   */
  private buildPromptBody(
    prompt: string,
    systemPrompt: string,
    provider: OpenCodeProviderConfig,
    outputSchema?: Record<string, unknown>,
    images?: ImageAttachment[]
  ): SessionPromptData['body'] {
    const hasPluginSystemPromptHook = !!process.env.CODE_ATELIER_SYSTEM_PROMPT_FILE
    const body: Record<string, unknown> = {
      parts: [
        { type: 'text', text: prompt },
        // Vision: include image attachments as file parts with data URLs
        ...(images ?? []).map((img) => ({
          type: 'file',
          mime: img.mimeType,
          filename: img.fileName,
          url: `data:${img.mimeType};base64,${img.base64}`
        }))
      ],
      model: {
        providerID: provider.providerId,
        modelID: provider.modelId
      },
      // Use the SDK's system field for system prompts — proper channel for model instructions.
      // This gives the system prompt higher priority, enables provider-specific routing,
      // and supports prefix caching. Skip when the plugin hook injects its own system prompt.
      ...(systemPrompt && !hasPluginSystemPromptHook ? { system: systemPrompt } : {})
    }

    // ENH-10: Include retry config so OpenCode auto-retries on invalid JSON
    if (outputSchema) {
      body.format = { type: 'json_schema', schema: outputSchema, retryCount: 2 }
    }

    return body as SessionPromptData['body']
  }

  /**
   * Reset the consecutive error counter (e.g. after a successful interaction).
   */
  resetCircuitBreaker(): void {
    this.consecutiveErrors = 0
  }

  /**
   * PORT-FIX: Kill any stale `opencode serve` process holding the server port.
   * This handles ungraceful shutdowns where stop() wasn't called or failed.
   */
  private async killStaleServer(): Promise<void> {
    try {
      const { execSync } = await import('node:child_process')
      // lsof finds PIDs listening on our port; awk extracts the PID column
      const output = execSync(
        `lsof -ti :${OPENCODE_SERVER_PORT} 2>/dev/null`,
        { encoding: 'utf-8', timeout: 3000 }
      ).trim()
      if (output) {
        const pids = output.split('\n').filter(Boolean)
        for (const pid of pids) {
          openCodeLog.warn(`[opencode] Killing stale server process on port ${OPENCODE_SERVER_PORT} (PID ${pid})`)
          try {
            process.kill(Number(pid), 'SIGTERM')
          } catch {
            // Process may have already exited
          }
        }
        // Brief wait for the port to be released
        await new Promise((r) => setTimeout(r, 500))
      }
    } catch {
      // lsof not found or no process on port — safe to proceed
    }
  }

  /**
   * Normalize an OpenCode SSE event into StreamChunks.
   * Delegates to the OpenCodeEventNormalizer dispatch table.
   */
  private normalizeEvent(
    event: unknown,
    sessionId: string,
    tokenUsage: ExecutorTokenUsage
  ): StreamChunk[] {
    // R6-A1: Keep serverReadyResolve in sync (it's set/cleared outside the state)
    this.normalizerState.serverReadyResolve = this.serverReadyResolve
    return normalizeOpenCodeEvent(event, sessionId, tokenUsage, this.normalizerState)
  }

  /**
   * Check if an event indicates the session has completed.
   *
   * @param retriesAvailable - When true, `session.error` events are NOT treated as
   *   terminal because a retry was actually initiated for this event. This flag
   *   should only be true when handleTransientRetry fired successfully — NOT simply
   *   because the retry budget hasn't been exhausted (which caused the suppression
   *   deadlock: errors were suppressed but no retry ever fired).
   */
  /** Diagnostic gauges for the vitals heartbeat (see main-vitals.ts). */
  public getVitals(): { activeSessions: number; retriesInFlight: number } {
    return { activeSessions: this.sessionMap.size, retriesInFlight: this.retriesInFlight }
  }

  private isSessionComplete(event: unknown, sessionId: string, retriesAvailable = false): boolean {
    const evt = event as Record<string, unknown>
    const type = evt.type as string | undefined
    const properties = evt.properties as Record<string, unknown> | undefined

    if (!properties) return false
    const eventSessionId = properties.sessionID as string | undefined
    if (eventSessionId && eventSessionId !== sessionId) return false

    // session.idle means the agent loop is done
    if (type === 'session.idle') return true

    // session.error terminates only when no retries are available.
    // During active retries the error is handled by the retry logic above
    // and a new prompt is fired — we must NOT break the event loop.
    if (type === 'session.error') {
      if (retriesAvailable) {
        openCodeLog.info('[opencode] session.error suppressed — retries still available')
        return false
      }
      return true
    }

    // Check for status changes indicating completion
    if (type === 'session.status') {
      const status = properties.status as string | undefined
      if (status === 'idle') return true
      if (status === 'error' && !retriesAvailable) return true
    }

    // NOTE: session.next.step.ended with finish="stop" is NOT treated as terminal.
    // It marks the end of a single generation *step*, not the agent loop. Reasoning
    // models emit a step.ended(stop) for the thinking step before the final answer
    // step streams in — breaking here truncated the last text (e.g. the JSON answer),
    // left the server session running as a zombie, and stalled the UI with no loading
    // state. `session.idle` / `session.status:idle` is the authoritative completion
    // signal (see handleSessionIdle in opencode-event-normalizer.ts); the outer
    // streamPrompt timeout is the backstop if idle never arrives.

    // V2 event bus: session.next.step.failed is a terminal signal
    if (type === 'session.next.step.failed') {
      if (retriesAvailable) {
        openCodeLog.info('[opencode] session.next.step.failed suppressed — retries still available')
        return false
      }
      return true
    }

    return false
  }
}

/** Singleton instance */
export const openCodeExecutor = new OpenCodeExecutor()

/**
 * OpenCodeEventNormalizer — maps OpenCode SSE events to StreamChunks.
 * Extracted from the 438-line normalizeEvent switch statement in opencode-executor.ts.
 *
 * Each handler method is focused on a single event type (5-30 lines each).
 */

import type { StreamChunk } from './agent-base.service'
import { summarizeToolInput } from './index'
import { extractResultSummary } from '../ipc/tool-result-summarizer'
import log from 'electron-log/main'

const openCodeLog = log.scope('OpenCode')

/**
 * Matches raw JSON control signals from local LLM backends that leak
 * into text deltas. These should never reach the chunk-router as text.
 */
const LOCAL_CONTROL_SIGNAL_RE = /^\s*\{\s*"type"\s*:\s*"(?:busy|idle|ready|processing)"\s*\}\s*$/

/** GAP-11: Transient error patterns — mirrors TRANSIENT_ERROR_PATTERNS from executor */
const TRANSIENT_PATTERNS = [
  /rate.?limit/i,
  /overloaded/i,
  /server_is_overloaded/i,
  /too many requests/i,
  /503/,
  /429/,
  /ECONNRESET/,
  /ETIMEDOUT/,
  /ECONNREFUSED/,
  /network/i,
  /timeout/i
]

/**
 * R7: Route inline <think>...</think> blocks to thinking chunks.
 * Local LLMs (Qwen, DeepSeek) emit chain-of-thought wrapped in <think> tags
 * inside regular text deltas. This function splits text on tag boundaries,
 * routing content inside tags to 'thinking' chunks and content outside to 'text'.
 *
 * Handles: whole-tag-per-delta, tag split across deltas, mixed content.
 */
function routeThinkTags(text: string, state: NormalizerState): StreamChunk[] {
  const chunks: StreamChunk[] = []
  let remaining = text

  while (remaining.length > 0) {
    if (state.inThinkBlock) {
      // Currently inside a <think> block — look for </think>
      const closeIdx = remaining.indexOf('</think>')
      if (closeIdx === -1) {
        // Entire remaining text is thinking content
        chunks.push({ type: 'thinking', content: remaining })
        state.lastPartType = 'thinking'
        remaining = ''
      } else {
        // Emit thinking content before the close tag
        const thinkContent = remaining.slice(0, closeIdx)
        if (thinkContent) {
          chunks.push({ type: 'thinking', content: thinkContent })
          state.lastPartType = 'thinking'
        }
        state.inThinkBlock = false
        remaining = remaining.slice(closeIdx + '</think>'.length)
      }
    } else {
      // Not in a think block — look for <think>
      const openIdx = remaining.indexOf('<think>')
      if (openIdx === -1) {
        // No think tag — emit as regular text with boundary detection
        if (state.lastPartType === 'thinking' && state.hasPriorText) {
          chunks.push({ type: 'turn_boundary', content: `thinking-split-${Date.now()}` })
        }
        chunks.push({ type: 'text', content: remaining })
        state.lastPartType = 'text'
        state.hasPriorText = true
        remaining = ''
      } else {
        // Emit text before the open tag
        const beforeThink = remaining.slice(0, openIdx)
        if (beforeThink) {
          if (state.lastPartType === 'thinking' && state.hasPriorText) {
            chunks.push({ type: 'turn_boundary', content: `thinking-split-${Date.now()}` })
          }
          chunks.push({ type: 'text', content: beforeThink })
          state.lastPartType = 'text'
          state.hasPriorText = true
        }
        state.inThinkBlock = true
        remaining = remaining.slice(openIdx + '<think>'.length)
      }
    }
  }

  return chunks
}

/** Token usage tracker passed into normalizeEvent */
export interface ExecutorTokenUsage {
  input: number
  output: number
  cacheReadInputTokens: number
  cacheCreationInputTokens: number
}

/** State references from the OpenCodeExecutor that handlers may need */
export interface NormalizerState {
  childSessions: Map<string, Set<string>>
  sessionMap: Map<string, string>
  serverReadyResolve?: () => void
  /** 6C-2: Last known finish reason from session.updated events */
  lastFinishReason?: string
  /** GAP-12: Last emitted context usage percentage — avoids flooding UI with micro-updates */
  lastContextPercentage?: number
  /** F16: Track last part type for turn boundary detection */
  lastPartType?: 'text' | 'thinking' | 'tool'
  /** F16: Whether we've seen text content before (for thinking→text boundary) */
  hasPriorText?: boolean
  /** R5: Dedupe — callIDs for which we already emitted tool_use */
  emittedToolUse?: Set<string>
  /** R5: Dedupe — callIDs for which we already emitted tool_result */
  emittedToolResult?: Set<string>
  /** R7: Whether we're inside an inline <think>...</think> block (local LLM reasoning) */
  inThinkBlock?: boolean
}

type EventProperties = Record<string, unknown>

type EventHandler = (
  properties: EventProperties,
  sessionId: string,
  tokenUsage: ExecutorTokenUsage,
  state: NormalizerState
) => StreamChunk[]

// ── Per-part-type sub-handlers for message.part.updated ──

/** Handle text part — includes thinking→text turn boundary detection (F16) + inline <think> routing (R7). */
function handleTextPart(part: Record<string, unknown>, state: NormalizerState): StreamChunk[] {
  const text = part.content as string | undefined
  if (!text) return []

  // CONTROL-SIGNAL-FILTER-02: Drop raw JSON control signals from local backends
  if (LOCAL_CONTROL_SIGNAL_RE.test(text)) {
    openCodeLog.debug('[opencode] Filtered control signal in text part: %s', text.slice(0, 60))
    return []
  }

  // R7: Route inline <think> blocks to thinking chunks (local LLMs like Qwen)
  return routeThinkTags(text, state)
}

/** Handle tool-invocation part — call, partial (streaming args), and result sub-states. */
function handleToolInvocationPart(
  part: Record<string, unknown>,
  state: NormalizerState
): StreamChunk[] {
  const chunks: StreamChunk[] = []
  const toolName = part.toolName as string | undefined
  const toolId = part.toolCallId as string | undefined
  // N1: Renamed from `state` to avoid shadowing the NormalizerState parameter
  const invocationState = part.state as string | undefined

  if (invocationState === 'call' && toolName) {
    state.lastPartType = 'tool'
    chunks.push({ type: 'tool_use', toolName, toolId })
  }

  if (invocationState === 'partial' && toolName) {
    const partialArgs = part.args as Record<string, unknown> | undefined
    if (partialArgs) {
      const inputPreview = summarizeToolInput(toolName, partialArgs)
      if (inputPreview) {
        chunks.push({
          type: 'tool_progress',
          toolName,
          toolId,
          toolInput: inputPreview,
          content: `${toolName}: ${inputPreview}`
        })
      }
    }
  }

  if (invocationState === 'result') {
    const result = part.result as string | undefined
    const resultStr = typeof result === 'string' ? result : JSON.stringify(result)
    chunks.push({
      type: 'tool_result',
      toolName: toolName ?? 'unknown',
      toolId,
      content: resultStr
    })

    // Generate a human-readable tool_use_summary
    const toolNameStr = toolName ?? 'unknown'
    const resultSummaryObj = extractResultSummary(toolNameStr, resultStr)
    let inputSummary: string | undefined
    const toolInput = part.args as Record<string, unknown> | undefined
    if (toolInput) inputSummary = summarizeToolInput(toolNameStr, toolInput)

    if (resultSummaryObj?.result || inputSummary) {
      chunks.push({
        type: 'tool_use_summary',
        toolName: toolNameStr,
        toolId,
        content: [
          inputSummary ? `Input: ${inputSummary}` : '',
          resultSummaryObj?.result ? `Result: ${resultSummaryObj.result}` : ''
        ]
          .filter(Boolean)
          .join(' — ')
      })
    }
  }

  return chunks
}

/**
 * Handle thinking / reasoning part — both map to the 'thinking' chunk type.
 * 6C-1: 'reasoning' / 'reasoning-delta' treated identically to 'thinking'.
 */
function handleThinkingPart(part: Record<string, unknown>, state: NormalizerState): StreamChunk[] {
  const content = part.content as string | undefined
  if (!content) return []
  state.lastPartType = 'thinking'
  return [{ type: 'thinking', content }]
}

/**
 * R5: Handle modern SDK ToolPart shape:
 *   { type: 'tool', tool: string, callID: string, state: { status, input, output, error } }
 *
 * message.part.updated fires a full snapshot on every status transition
 * (pending → running → completed). We dedupe via emittedToolUse / emittedToolResult
 * sets so each callID emits exactly one tool_use and one tool_result.
 */
function handleToolPart(part: Record<string, unknown>, state: NormalizerState): StreamChunk[] {
  const toolName = part.tool as string | undefined
  const callID = part.callID as string | undefined
  const toolState = part.state as Record<string, unknown> | undefined
  if (!toolName || !callID || !toolState) return []

  const status = (toolState.status ?? toolState) as string
  const chunks: StreamChunk[] = []

  // Lazily initialise dedupe sets
  if (!state.emittedToolUse) state.emittedToolUse = new Set()
  if (!state.emittedToolResult) state.emittedToolResult = new Set()

  // ── tool_use (first sighting with input) ──
  // R6-A2: Only emit on 'running', 'completed', or 'error'. 'pending' snapshots have
  // incomplete/empty args that would permanently capture {} as the tool input.
  if (!state.emittedToolUse.has(callID) && status !== 'pending') {
    const input = toolState.input as Record<string, unknown> | string | undefined
    const hasInput = input !== undefined && input !== null
    state.emittedToolUse.add(callID)
    state.lastPartType = 'tool'
    chunks.push({
      type: 'tool_use',
      toolName,
      toolId: callID,
      toolInput: hasInput
        ? (typeof input === 'string' ? input : JSON.stringify(input))
        : undefined
    })
  }

  // ── tool_result (on completed / error) ──
  if ((status === 'completed' || status === 'error') && !state.emittedToolResult.has(callID)) {
    state.emittedToolResult.add(callID)

    const output = (status === 'error' ? toolState.error : toolState.output) as string | undefined
    const resultStr = typeof output === 'string' ? output : JSON.stringify(output ?? '')

    chunks.push({
      type: 'tool_result',
      toolName,
      toolId: callID,
      content: resultStr
    })

    // Generate a human-readable tool_use_summary (mirrors legacy tool-invocation logic)
    const resultSummaryObj = extractResultSummary(toolName, resultStr)
    let inputSummary: string | undefined
    const rawInput = toolState.input as Record<string, unknown> | undefined
    if (rawInput && typeof rawInput === 'object') {
      inputSummary = summarizeToolInput(toolName, rawInput)
    }

    if (resultSummaryObj?.result || inputSummary) {
      chunks.push({
        type: 'tool_use_summary',
        toolName,
        toolId: callID,
        content: [
          inputSummary ? `Input: ${inputSummary}` : '',
          resultSummaryObj?.result ? `Result: ${resultSummaryObj.result}` : ''
        ]
          .filter(Boolean)
          .join(' — ')
      })
    }
  }

  return chunks
}

/** GAP-9: Handle structured_output / structured-output part. */
function handleStructuredOutputPart(part: Record<string, unknown>): StreamChunk[] {
  const data = part.content ?? part.data ?? part.result
  if (!data) return []
  return [
    {
      type: 'structured_output',
      structuredOutput: {
        data,
        schemaName: part.schemaName as string | undefined
      },
      content: typeof data === 'string' ? data : JSON.stringify(data, null, 2)
    }
  ]
}

// ── Per-event-type handler functions ──

/**
 * Handle message.part.delta — lightweight text/reasoning streaming deltas.
 * Replaces full message.part.updated snapshots for incremental text in OpenCode ≥1.17.
 */
function handleMessagePartDelta(
  properties: EventProperties,
  _sessionId: string,
  _tokenUsage: ExecutorTokenUsage,
  state: NormalizerState
): StreamChunk[] {
  const field = properties.field as string | undefined
  const delta = properties.delta as string | undefined
  if (!delta) return []

  if (field === 'text') {
    // CONTROL-SIGNAL-FILTER-02: Drop raw JSON control signals from local backends
    if (LOCAL_CONTROL_SIGNAL_RE.test(delta)) {
      openCodeLog.debug('[opencode] Filtered control signal in text delta: %s', delta.slice(0, 60))
      return []
    }
    // R7: Route inline <think> blocks to thinking chunks (local LLMs like Qwen)
    return routeThinkTags(delta, state)
  }

  if (field === 'reasoning' || field === 'thinking') {
    state.lastPartType = 'thinking'
    return [{ type: 'thinking', content: delta }]
  }

  // Unknown field — log but don't drop
  openCodeLog.info(`[opencode] message.part.delta field="${field}" (not text/reasoning)`)
  return []
}

/** Dispatcher for message.part.updated — delegates to per-part-type sub-handlers. */
function handleMessagePartUpdated(
  properties: EventProperties,
  _sessionId: string,
  _tokenUsage: ExecutorTokenUsage,
  state: NormalizerState
): StreamChunk[] {
  const part = properties.part as Record<string, unknown> | undefined
  if (!part?.type) return []

  switch (part.type) {
    case 'text':
      return handleTextPart(part, state)
    case 'tool-invocation':
      return handleToolInvocationPart(part, state)
    case 'tool':
      return handleToolPart(part, state)
    case 'thinking':
    case 'reasoning':
    case 'reasoning-delta':
      return handleThinkingPart(part, state)
    case 'structured_output':
    case 'structured-output':
      return handleStructuredOutputPart(part)
    default:
      return []
  }
}

function handleSessionUpdated(
  properties: EventProperties,
  _sessionId: string,
  tokenUsage: ExecutorTokenUsage,
  state: NormalizerState
): StreamChunk[] {
  const chunks: StreamChunk[] = []
  const usage = properties.usage as Record<string, number> | undefined
  if (usage) {
    tokenUsage.input = usage.inputTokens ?? tokenUsage.input
    tokenUsage.output = usage.outputTokens ?? tokenUsage.output
    tokenUsage.cacheReadInputTokens = usage.cacheReadInputTokens ?? tokenUsage.cacheReadInputTokens
    tokenUsage.cacheCreationInputTokens =
      usage.cacheCreationInputTokens ?? tokenUsage.cacheCreationInputTokens
  }

  // GAP-12: Emit per-turn context usage updates.
  // Context consumption = fresh input + cache reads + cache writes, matching
  // Claude Code / agent-stream-processor. Using usage.inputTokens alone misses
  // cached tokens (often the bulk of the window) and under-reported usage.
  const contextTokens =
    (usage?.inputTokens ?? 0) +
    (usage?.cacheReadInputTokens ?? 0) +
    (usage?.cacheCreationInputTokens ?? 0)
  if (contextTokens > 0 && usage?.contextWindowSize) {
    const percentage = Math.round((contextTokens / usage.contextWindowSize) * 100)
    state.lastContextPercentage = percentage
    chunks.push({
      type: 'context_usage_update',
      contextUsageUpdate: {
        inputTokens: contextTokens,
        contextWindowSize: usage.contextWindowSize,
        percentage
      }
    })
  }

  // 6C-2: Track finishReason for terminal status mapping
  const finishReason = properties.finishReason as string | undefined
  if (finishReason) {
    state.lastFinishReason = finishReason
    openCodeLog.info(`[opencode] Session finishReason: ${finishReason}`)

    // Emit context_exhausted signal when context window is full
    if (finishReason === 'length') {
      chunks.push({
        type: 'compact_boundary',
        content: 'Context window exhausted — compaction needed'
      })
    }
  }

  return chunks
}

function handleSessionError(properties: EventProperties): StreamChunk[] {
  const rawError = properties.error
  if (!rawError) return []

  // The SDK sends error as an object: { name: string, data: { message: string, ... } }.
  // Coerce to a string for downstream consumers that pattern-match on error messages.
  // R8: If the coerced string is empty/whitespace, fall back to JSON.stringify(rawError)
  // then a descriptive placeholder. This surfaces real provider errors (e.g. OpenCode
  // omlx vision rejection) that previously produced '' ?? fallback → empty error text.
  let error: string =
    typeof rawError === 'string'
      ? rawError
      : (rawError as any)?.data?.message ??
        (rawError as any)?.message ??
        ''
  if (!error || !error.trim()) {
    error = JSON.stringify(rawError)
    if (!error || error === '{}' || error === '""') {
      error = 'OpenCode session error (no message)'
    }
  }

  // GAP-11: Classify transient vs permanent errors. Transient errors emit
  // api_retry instead of error, giving the UI a more accurate status indicator.
  const isTransient = TRANSIENT_PATTERNS.some((p) => p.test(error))
  if (isTransient) {
    openCodeLog.info(`[opencode] Transient error detected — UI will show retry status: ${error}`)
    const chunks: StreamChunk[] = [
      {
        type: 'api_retry',
        content: `Transient error: ${error}`,
        retryInfo: {
          attempt: 1,
          maxRetries: 3,
          retryDelayMs: 2000,
          errorStatus: null
        }
      }
    ]
    // F17: Additionally emit rate_limit for rate-limit-specific errors so the
    // UI rate limit indicator works for OpenCode sessions (parity with CLI).
    const isRateLimit = /rate.?limit|429|too many requests/i.test(error)
    if (isRateLimit) {
      chunks.push({
        type: 'rate_limit',
        rateLimit: { status: 'rejected', utilization: 100, rateLimitType: 'api' }
      })
    }
    return chunks
  }

  return [{ type: 'error', error }]
}

function handleSessionCompacted(properties: EventProperties): StreamChunk[] {
  const chunks: StreamChunk[] = [{ type: 'compact_boundary', content: 'OpenCode compaction' }]

  // 6C-4: Emit context usage reset so the UI badge refreshes post-compaction
  const usage = properties.usage as Record<string, number> | undefined
  const contextTokens =
    (usage?.inputTokens ?? 0) +
    (usage?.cacheReadInputTokens ?? 0) +
    (usage?.cacheCreationInputTokens ?? 0)
  if (contextTokens > 0 && usage?.contextWindowSize) {
    chunks.push({
      type: 'context_usage_update',
      contextUsageUpdate: {
        inputTokens: contextTokens,
        contextWindowSize: usage.contextWindowSize,
        percentage: Math.round((contextTokens / usage.contextWindowSize) * 100)
      }
    })
  } else {
    // N12: Estimate compaction reduces to ~30% usage. Use a sane default
    // context window to avoid 0/0 = NaN in the renderer's qualityPct calculation.
    const estimatedWindow = 200_000
    const estimatedTokens = Math.round(estimatedWindow * 0.3)
    chunks.push({
      type: 'context_usage_update',
      contextUsageUpdate: {
        inputTokens: estimatedTokens,
        contextWindowSize: estimatedWindow,
        percentage: 30
      }
    })
  }

  return chunks
}

function handleSessionIdle(
  _properties: EventProperties,
  _sessionId: string,
  _tokenUsage: ExecutorTokenUsage,
  state: NormalizerState
): StreamChunk[] {
  // R6-A1: Clear dedupe sets on idle for bounded memory. A new agent turn will
  // produce fresh callIDs, so stale entries never match and just waste memory.
  if (state.emittedToolUse) state.emittedToolUse.clear()
  if (state.emittedToolResult) state.emittedToolResult.clear()

  const chunks: StreamChunk[] = [{ type: 'status', content: 'idle' }]

  // Note: 'idle' status is suppressed by SUPPRESSED_STATUS_VALUES in chunk-router.ts.
  // The 'finishReason:' prefix is suppressed by SUPPRESSED_STATUS_PREFIXES.
  if (state.lastFinishReason) {
    const reasonMap: Record<string, string> = {
      stop: 'completed',
      length: 'context_exhausted',
      'tool-calls': 'tool_pending',
      error: 'failed'
    }
    const terminalReason = reasonMap[state.lastFinishReason] ?? state.lastFinishReason
    chunks.push({ type: 'status', content: `finishReason:${terminalReason}` })
    state.lastFinishReason = undefined
  }

  return chunks
}

function handleFileEdited(properties: EventProperties): StreamChunk[] {
  const filePath = properties.path as string | undefined
  return [
    {
      type: 'hook_lifecycle',
      hookInfo: {
        hookId: 'file-edited',
        hookName: 'OpenCode file.edited',
        hookEvent: 'file.edited',
        phase: 'response',
        output: filePath ?? 'unknown file',
        outcome: 'success'
      }
    }
  ]
}

// Cap diff content before allocating a chunk string. The chunk-router has a
// separate 1MB guard, but capping here avoids a transient multi-MB allocation
// in the main process when OpenCode emits very large diffs.
const MAX_SESSION_DIFF_CHARS = 2_000_000 // 2MB — generous for recovery metadata

function handleSessionDiff(properties: EventProperties): StreamChunk[] {
  const diff = properties.diff as string | undefined
  if (!diff) return []
  // Session diffs are internal recovery metadata — route to session_state,
  // not text, to prevent rendering in the chat bubble.
  const safeDiff = diff.length > MAX_SESSION_DIFF_CHARS
    ? diff.slice(0, MAX_SESSION_DIFF_CHARS)
    : diff
  return [{ type: 'session_state', content: `session_diff:${safeDiff}` }]
}

/**
 * session.status — maps OpenCode session statuses to internal status labels.
 * These labels are suppressed from chat rendering by SUPPRESSED_STATUS_VALUES
 * in src/main/ipc/chunk-router.ts. If you add a new mapping here, update
 * the suppression list there.
 */
function handleSessionStatus(properties: EventProperties): StreamChunk[] {
  const rawStatus = properties.status
  if (!rawStatus) return []
  let status: string
  if (typeof rawStatus === 'string') {
    status = rawStatus
  } else if (
    typeof rawStatus === 'object' &&
    typeof (rawStatus as Record<string, unknown>).type === 'string'
  ) {
    // OpenCode local backends emit object statuses like {type:'busy'}
    status = (rawStatus as { type: string }).type
  } else {
    status = JSON.stringify(rawStatus)
  }
  const statusMap: Record<string, string> = {
    thinking: 'thinking',
    tool_use: 'reviewing',
    idle: 'idle',
    busy: 'thinking',  // local LLM backend status → map to 'thinking' (already suppressed)
    error: 'failed',
    compacting: 'thinking',
    generating: 'writing'
  }
  return [{ type: 'status', content: statusMap[status] ?? status }]
}

function handleSessionCreated(
  properties: EventProperties,
  sessionId: string,
  _tokenUsage: ExecutorTokenUsage,
  state: NormalizerState
): StreamChunk[] {
  const childId = properties.id as string | undefined
  const parentId = properties.parentID as string | undefined
  if (!childId) return []

  const trackParent = parentId ?? sessionId
  if (!state.childSessions.has(trackParent)) {
    state.childSessions.set(trackParent, new Set())
  }
  state.childSessions.get(trackParent)!.add(childId)
  openCodeLog.info(
    `[opencode] Child session ${childId} created (parent: ${trackParent}, ` +
      `total children: ${state.childSessions.get(trackParent)!.size})`
  )
  return [{ type: 'subagent_start', content: `Subagent session started: ${childId}` }]
}

function handleMessageRemoved(properties: EventProperties): StreamChunk[] {
  const removedId = properties.messageID as string | undefined
  return removedId ? [{ type: 'session_state', content: `message_removed:${removedId}` }] : []
}

function handleMessageUpdated(properties: EventProperties): StreamChunk[] {
  const msgPart = properties.part as Record<string, unknown> | undefined
  if (msgPart?.type === 'text') {
    const text = msgPart.content as string | undefined
    if (text) return [{ type: 'text', content: text }]
  }
  return []
}

function handlePermissionAsked(properties: EventProperties): StreamChunk[] {
  const tool = properties.tool as string | undefined
  const permissionId = properties.permissionId as string | undefined
  const args = properties.args as Record<string, unknown> | undefined
  if (!tool || !permissionId) return []

  openCodeLog.info(`[opencode] Permission requested for tool: ${tool} (id: ${permissionId})`)
  return [
    {
      type: 'permission_request',
      toolName: tool,
      permissionRequest: { permissionId, tool, args, message: `Agent wants to use ${tool}` }
    }
  ]
}

function handlePermissionReplied(properties: EventProperties): StreamChunk[] {
  const tool = properties.tool as string | undefined
  const allowed = properties.allowed as boolean | undefined
  if (tool) openCodeLog.info(`[opencode] Permission ${allowed ? 'granted' : 'denied'} for: ${tool}`)
  return []
}

function handleInstallationUpdated(): StreamChunk[] {
  openCodeLog.info('[opencode] Installation updated — dependency change detected')
  return []
}

function handleLspDiagnostics(properties: EventProperties): StreamChunk[] {
  const diagnostics = properties.diagnostics as Array<Record<string, unknown>> | undefined
  if (!diagnostics || diagnostics.length === 0) return []

  openCodeLog.info(`[opencode] LSP diagnostics: ${diagnostics.length} issues`)

  // GAP-14: Surface LSP diagnostics to the UI as a structured chunk
  const severityMap: Record<string, 'error' | 'warning' | 'info' | 'hint'> = {
    error: 'error',
    warning: 'warning',
    information: 'info',
    hint: 'hint',
    '1': 'error',
    '2': 'warning',
    '3': 'info',
    '4': 'hint'
  }

  const parsed = diagnostics.slice(0, 20).map((d) => ({
    file: (d.file ?? d.path ?? d.uri ?? 'unknown') as string,
    line: (d.line ?? (d.range as Record<string, unknown>)?.start ?? 0) as number,
    severity: severityMap[String(d.severity ?? 'warning')] ?? 'warning',
    message: (d.message ?? String(d)) as string,
    source: d.source as string | undefined
  }))

  // Build a human-readable summary for content
  const errorCount = parsed.filter((d) => d.severity === 'error').length
  const warnCount = parsed.filter((d) => d.severity === 'warning').length
  const summary =
    [errorCount > 0 ? `${errorCount} error(s)` : '', warnCount > 0 ? `${warnCount} warning(s)` : '']
      .filter(Boolean)
      .join(', ') || `${parsed.length} diagnostic(s)`

  return [
    {
      type: 'lsp_diagnostics',
      lspDiagnostics: parsed,
      content: `LSP: ${summary}`
    }
  ]
}

function handleTodoUpdated(properties: EventProperties): StreamChunk[] {
  const todoAction = properties.action as string | undefined
  const todoText = properties.text as string | undefined
  const todoIndex = properties.index as number | undefined
  openCodeLog.info(`[opencode] Todo ${todoAction ?? 'updated'}: ${todoText ?? '(no text)'}`)
  if (!todoText) return []

  // GAP-15: Bridge todo updates to the UI as a dedicated chunk type
  const actionMap: Record<string, 'add' | 'complete' | 'remove' | 'update'> = {
    add: 'add',
    create: 'add',
    complete: 'complete',
    done: 'complete',
    remove: 'remove',
    delete: 'remove',
    update: 'update',
    edit: 'update'
  }
  const normalizedAction = actionMap[todoAction ?? 'update'] ?? 'update'

  return [
    {
      type: 'todo_update',
      todoUpdate: {
        action: normalizedAction,
        text: todoText,
        index: todoIndex
      },
      content: `Todo ${normalizedAction}: ${todoText}`
    }
  ]
}

function handleCommandExecuted(properties: EventProperties): StreamChunk[] {
  const command = properties.command as string | undefined
  if (command) openCodeLog.info(`[opencode] Command executed: ${command}`)
  return []
}

function handleMessagePartRemoved(properties: EventProperties): StreamChunk[] {
  const removedMsgId = properties.messageID as string | undefined
  const removedPartId = properties.partID as string | undefined
  if (!removedMsgId || !removedPartId) return []
  return [{ type: 'session_state', content: `part_removed:${removedMsgId}:${removedPartId}` }]
}

function handleSessionDeleted(
  properties: EventProperties,
  _sessionId: string,
  _tokenUsage: ExecutorTokenUsage,
  state: NormalizerState
): StreamChunk[] {
  const deletedId = properties.id as string | undefined
  if (!deletedId) return []

  openCodeLog.info(`[opencode] Session ${deletedId} deleted — cleaning up references`)
  for (const [convId, sessId] of state.sessionMap.entries()) {
    if (sessId === deletedId) {
      state.sessionMap.delete(convId)
      break
    }
  }
  state.childSessions.delete(deletedId)
  for (const children of state.childSessions.values()) {
    children.delete(deletedId)
  }
  return [{ type: 'session_state', content: `session_deleted:${deletedId}` }]
}

function handleFileWatcherUpdated(properties: EventProperties): StreamChunk[] {
  const watchedPath = properties.path as string | undefined
  const watchedEvent = properties.event as string | undefined
  if (!watchedPath) return []
  openCodeLog.info(`[opencode] File watcher: ${watchedEvent ?? 'changed'} ${watchedPath}`)
  return [
    {
      type: 'hook_lifecycle',
      hookInfo: {
        hookId: 'file-watcher',
        hookName: 'OpenCode file.watcher.updated',
        hookEvent: 'file.watcher.updated',
        phase: 'response',
        output: `${watchedEvent ?? 'changed'}: ${watchedPath}`,
        outcome: 'success'
      }
    }
  ]
}

function handleLspUpdated(properties: EventProperties): StreamChunk[] {
  const lspStatus = properties.status as string | undefined
  const lspLanguage = properties.language as string | undefined
  openCodeLog.info(`[opencode] LSP ${lspLanguage ?? 'unknown'}: ${lspStatus ?? 'updated'}`)
  if (lspStatus === 'error' || lspStatus === 'disconnected') {
    return [{ type: 'status', content: `lsp_${lspStatus}:${lspLanguage ?? 'unknown'}` }]
  }
  return []
}

function handleServerConnected(
  _properties: EventProperties,
  _sessionId: string,
  _tokenUsage: ExecutorTokenUsage,
  state: NormalizerState
): StreamChunk[] {
  openCodeLog.info('[opencode] Server fully initialized — all subsystems ready')
  if (state.serverReadyResolve) {
    state.serverReadyResolve()
    state.serverReadyResolve = undefined
  }
  return []
}

// ── session.next.* V2 event bus handlers ──

/** No-op handler — suppresses "Unhandled event type" log for known V2 events. */
function noopHandler(): StreamChunk[] {
  return []
}

/** Track whether we've logged the first-sighting raw shape for each V2 tool event type. */
const v2ToolFirstSighting = { called: false, success: false, failed: false }

/**
 * session.next.tool.called — V2 event bus.
 * Emits `tool_use`, deduped via `state.emittedToolUse` (shared with handleToolPart
 * so V1+V2 double-fire never duplicates).
 *
 * Property names are parsed defensively — exact V2 payload shape may vary.
 */
function handleV2ToolCalled(
  properties: EventProperties,
  _sessionId: string,
  _tokenUsage: ExecutorTokenUsage,
  state: NormalizerState
): StreamChunk[] {
  if (!v2ToolFirstSighting.called) {
    v2ToolFirstSighting.called = true
    openCodeLog.info('[opencode] V2 tool.called first sighting — raw properties:', JSON.stringify(properties).slice(0, 500))
  }

  const toolName = (properties.tool ?? properties.name ?? properties.toolName ?? 'unknown') as string
  const callID = (properties.callID ?? properties.id ?? properties.toolCallId) as string | undefined
  if (!callID) return []

  // Lazily initialise dedupe sets
  if (!state.emittedToolUse) state.emittedToolUse = new Set()
  if (state.emittedToolUse.has(callID)) return []
  state.emittedToolUse.add(callID)
  state.lastPartType = 'tool'

  const rawInput = (properties.input ?? properties.args) as Record<string, unknown> | string | undefined
  let toolInput: string | undefined
  if (rawInput != null) {
    toolInput = typeof rawInput === 'string' ? rawInput : JSON.stringify(rawInput)
  }

  return [{ type: 'tool_use', toolName, toolId: callID, toolInput }]
}

/**
 * session.next.tool.success — V2 event bus.
 * Emits `tool_result` + `tool_use_summary`, deduped via `state.emittedToolResult`.
 */
function handleV2ToolSuccess(
  properties: EventProperties,
  _sessionId: string,
  _tokenUsage: ExecutorTokenUsage,
  state: NormalizerState
): StreamChunk[] {
  if (!v2ToolFirstSighting.success) {
    v2ToolFirstSighting.success = true
    openCodeLog.info('[opencode] V2 tool.success first sighting — raw properties:', JSON.stringify(properties).slice(0, 500))
  }

  const toolName = (properties.tool ?? properties.name ?? properties.toolName ?? 'unknown') as string
  const callID = (properties.callID ?? properties.id ?? properties.toolCallId) as string | undefined
  if (!callID) return []

  if (!state.emittedToolResult) state.emittedToolResult = new Set()
  if (state.emittedToolResult.has(callID)) return []
  state.emittedToolResult.add(callID)

  // Also ensure tool_use was emitted (V2-only path — V1 may not have fired)
  if (!state.emittedToolUse) state.emittedToolUse = new Set()
  const chunks: StreamChunk[] = []
  if (!state.emittedToolUse.has(callID)) {
    state.emittedToolUse.add(callID)
    state.lastPartType = 'tool'
    const rawInput = (properties.input ?? properties.args) as Record<string, unknown> | string | undefined
    let toolInput: string | undefined
    if (rawInput != null) {
      toolInput = typeof rawInput === 'string' ? rawInput : JSON.stringify(rawInput)
    }
    chunks.push({ type: 'tool_use', toolName, toolId: callID, toolInput })
  }

  const output = (properties.output ?? properties.result) as string | unknown | undefined
  const resultStr = typeof output === 'string' ? output : JSON.stringify(output ?? '')

  chunks.push({ type: 'tool_result', toolName, toolId: callID, content: resultStr })

  // Generate a human-readable summary
  const resultSummaryObj = extractResultSummary(toolName, resultStr)
  let inputSummary: string | undefined
  const rawInput = (properties.input ?? properties.args) as Record<string, unknown> | undefined
  if (rawInput && typeof rawInput === 'object') {
    inputSummary = summarizeToolInput(toolName, rawInput)
  }
  if (resultSummaryObj?.result || inputSummary) {
    chunks.push({
      type: 'tool_use_summary',
      toolName,
      toolId: callID,
      content: [
        inputSummary ? `Input: ${inputSummary}` : '',
        resultSummaryObj?.result ? `Result: ${resultSummaryObj.result}` : ''
      ].filter(Boolean).join(' — ')
    })
  }

  return chunks
}

/**
 * session.next.tool.failed — V2 event bus.
 * Emits `tool_result` with error payload, deduped via `state.emittedToolResult`.
 */
function handleV2ToolFailed(
  properties: EventProperties,
  _sessionId: string,
  _tokenUsage: ExecutorTokenUsage,
  state: NormalizerState
): StreamChunk[] {
  if (!v2ToolFirstSighting.failed) {
    v2ToolFirstSighting.failed = true
    openCodeLog.info('[opencode] V2 tool.failed first sighting — raw properties:', JSON.stringify(properties).slice(0, 500))
  }

  const toolName = (properties.tool ?? properties.name ?? properties.toolName ?? 'unknown') as string
  const callID = (properties.callID ?? properties.id ?? properties.toolCallId) as string | undefined
  if (!callID) return []

  if (!state.emittedToolResult) state.emittedToolResult = new Set()
  if (state.emittedToolResult.has(callID)) return []
  state.emittedToolResult.add(callID)

  // Also ensure tool_use was emitted
  if (!state.emittedToolUse) state.emittedToolUse = new Set()
  const chunks: StreamChunk[] = []
  if (!state.emittedToolUse.has(callID)) {
    state.emittedToolUse.add(callID)
    state.lastPartType = 'tool'
    chunks.push({ type: 'tool_use', toolName, toolId: callID })
  }

  const errorMsg = (properties.error ?? properties.message ?? 'Tool execution failed') as string
  const resultStr = typeof errorMsg === 'string' ? errorMsg : JSON.stringify(errorMsg)

  chunks.push({ type: 'tool_result', toolName, toolId: callID, content: resultStr })

  return chunks
}

/**
 * session.next.agent.switched — emits status chunk with agent name.
 * The 'agent_switched:' prefix is suppressed from chat rendering by
 * SUPPRESSED_STATUS_PREFIXES in src/main/ipc/chunk-router.ts.
 */
function handleAgentSwitched(properties: EventProperties): StreamChunk[] {
  const raw = properties.agent ?? properties.name ?? 'unknown'
  const name = typeof raw === 'string' ? raw : (raw as Record<string, unknown>)?.name ?? (raw as Record<string, unknown>)?.id ?? JSON.stringify(raw)
  return [{ type: 'status', content: `agent_switched:${name}` }]
}

/**
 * session.next.model.switched — emits status chunk with model id.
 * The 'model_switched:' prefix is suppressed from chat rendering by
 * SUPPRESSED_STATUS_PREFIXES in src/main/ipc/chunk-router.ts.
 */
function handleModelSwitched(properties: EventProperties): StreamChunk[] {
  const raw = properties.model ?? properties.modelID ?? properties.id ?? 'unknown'
  const modelId = typeof raw === 'string' ? raw : (raw as Record<string, unknown>)?.id ?? (raw as Record<string, unknown>)?.modelID ?? JSON.stringify(raw)
  return [{ type: 'status', content: `model_switched:${modelId}` }]
}

/** session.next.step.ended — extracts per-step token usage when available. */
function handleStepEnded(
  properties: EventProperties,
  _sessionId: string,
  tokenUsage: ExecutorTokenUsage
): StreamChunk[] {
  const usage = properties.usage as Record<string, number> | undefined
  if (usage) {
    tokenUsage.input = usage.inputTokens ?? usage.input ?? tokenUsage.input
    tokenUsage.output = usage.outputTokens ?? usage.output ?? tokenUsage.output
    tokenUsage.cacheReadInputTokens =
      usage.cacheReadInputTokens ?? tokenUsage.cacheReadInputTokens
    tokenUsage.cacheCreationInputTokens =
      usage.cacheCreationInputTokens ?? tokenUsage.cacheCreationInputTokens
  }
  return []
}

// ── Dispatch table ──

const EVENT_HANDLERS: Record<string, EventHandler> = {
  'message.part.updated': handleMessagePartUpdated,
  'message.part.delta': handleMessagePartDelta,
  'session.updated': handleSessionUpdated,
  'session.error': handleSessionError as EventHandler,
  'session.compacted': handleSessionCompacted as EventHandler, // 6C-4: now emits context_usage_update
  'session.idle': handleSessionIdle,
  'file.edited': handleFileEdited as EventHandler,
  'session.diff': handleSessionDiff as EventHandler,
  'session.status': handleSessionStatus as EventHandler,
  'session.created': handleSessionCreated,
  'message.removed': handleMessageRemoved as EventHandler,
  'message.updated': handleMessageUpdated as EventHandler,
  'permission.asked': handlePermissionAsked as EventHandler,
  'permission.replied': handlePermissionReplied as EventHandler,
  'installation.updated': handleInstallationUpdated as EventHandler,
  'lsp.client.diagnostics': handleLspDiagnostics as EventHandler,
  'todo.updated': handleTodoUpdated as EventHandler,
  'command.executed': handleCommandExecuted as EventHandler,
  'message.part.removed': handleMessagePartRemoved as EventHandler,
  'session.deleted': handleSessionDeleted,
  'file.watcher.updated': handleFileWatcherUpdated as EventHandler,
  'lsp.updated': handleLspUpdated as EventHandler,
  'server.connected': handleServerConnected,

  // session.next.* — V2 event bus. Currently fires alongside V1 events.
  // Registered to suppress "Unhandled event type" log spam.
  'session.next.agent.switched': handleAgentSwitched as EventHandler,
  'session.next.model.switched': handleModelSwitched as EventHandler,
  'session.next.text.started': noopHandler as EventHandler,
  'session.next.text.delta': noopHandler as EventHandler,
  'session.next.text.ended': noopHandler as EventHandler,
  'session.next.reasoning.started': noopHandler as EventHandler,
  'session.next.reasoning.delta': noopHandler as EventHandler,
  'session.next.reasoning.ended': noopHandler as EventHandler,
  'session.next.tool.input.started': noopHandler as EventHandler,
  'session.next.tool.input.delta': noopHandler as EventHandler,
  'session.next.tool.input.ended': noopHandler as EventHandler,
  'session.next.tool.called': handleV2ToolCalled,
  'session.next.tool.progress': noopHandler as EventHandler,
  'session.next.tool.success': handleV2ToolSuccess,
  'session.next.tool.failed': handleV2ToolFailed,
  'session.next.step.started': noopHandler as EventHandler,
  'session.next.step.ended': handleStepEnded as EventHandler,
  'session.next.step.failed': noopHandler as EventHandler,
  'session.next.compaction.started': noopHandler as EventHandler,
  'session.next.compaction.delta': noopHandler as EventHandler,
  'session.next.compaction.ended': noopHandler as EventHandler,
  'session.next.retried': noopHandler as EventHandler,
  'session.next.prompted': noopHandler as EventHandler,
  'session.next.prompt.admitted': noopHandler as EventHandler,
  'session.next.context.updated': noopHandler as EventHandler,
  'session.next.synthetic': noopHandler as EventHandler,
  'session.next.shell.started': noopHandler as EventHandler,
  'session.next.shell.ended': noopHandler as EventHandler,
  'session.next.moved': noopHandler as EventHandler,

  // Server lifecycle — suppress heartbeat noise (~6x/minute).
  'server.heartbeat': noopHandler as EventHandler,

  // Plugin/catalog/integration lifecycle — informational, no UI action needed.
  'plugin.added': noopHandler as EventHandler,
  'plugin.removed': noopHandler as EventHandler,
  'catalog.updated': noopHandler as EventHandler,
  'integration.updated': noopHandler as EventHandler,
  'reference.updated': noopHandler as EventHandler
}

/**
 * Normalize an OpenCode SSE event into StreamChunks.
 * Drop-in replacement for the old switch statement in OpenCodeExecutor.normalizeEvent().
 */
export function normalizeOpenCodeEvent(
  event: unknown,
  sessionId: string,
  tokenUsage: ExecutorTokenUsage,
  state: NormalizerState
): StreamChunk[] {
  const evt = event as Record<string, unknown>
  const type = evt.type as string | undefined
  const properties = evt.properties as EventProperties | undefined

  if (!type || !properties) return []

  // Filter events for this session — but allow child session events through
  const eventSessionId = properties.sessionID as string | undefined
  if (eventSessionId && eventSessionId !== sessionId) {
    // GAP-13: Check if this event belongs to a known child/subagent session
    const isChildSession =
      state.childSessions.has(sessionId) && state.childSessions.get(sessionId)!.has(eventSessionId)

    if (isChildSession) {
      // Process child session events but tag them as subagent progress
      if (type === 'session.idle' || type === 'session.deleted') {
        return [
          { type: 'subagent_complete', content: `Subagent session completed: ${eventSessionId}` }
        ]
      }

      // For text and tool events from child sessions, emit as subagent_progress
      const handler = EVENT_HANDLERS[type]
      if (handler) {
        const childChunks = handler(properties, sessionId, tokenUsage, state)
        // Wrap text chunks as subagent_progress
        return childChunks.map((chunk) => {
          if (chunk.type === 'text' || chunk.type === 'tool_use' || chunk.type === 'tool_result') {
            return {
              ...chunk,
              type: 'subagent_progress' as const,
              content: chunk.content
                ? `[subagent:${eventSessionId.slice(0, 8)}] ${chunk.content}`
                : chunk.content
            }
          }
          return chunk
        })
      }
    }

    return []
  }

  const handler = EVENT_HANDLERS[type]
  if (handler) return handler(properties, sessionId, tokenUsage, state)

  // 6C-5: Log unknown event types for forward-compatibility awareness
  openCodeLog.info(`[opencode] Unhandled event type: ${type}`)
  return []
}

/**
 * ChatAgentService — multi-workspace chat session manager.
 *
 * Maintains a Map<workspaceId, SessionEntry> so multiple workspace sessions can
 * run concurrently. Switching workspaces in the UI is now a view swap only —
 * background sessions continue executing.
 *
 * Every workspace uses ProjectSpecialistRoleAdapter. When a specialist row
 * exists with build_status='ready', the adapter uses the tailored prompt;
 * otherwise it falls back to DEFAULT_ARCHITECT_PROMPT.
 *
 * All existing consumers (chat-stream.service.ts, agent.ipc.ts, etc.) continue
 * working through backward-compatible accessors that delegate to the active
 * workspace session.
 */

import { EventEmitter } from 'node:events'
import type { AgentRole, AgentStatus, ConversationMode, ImageAttachment } from '../../shared/types'
import { chatAgentLogger } from '../logger'
import { AgentSessionService } from './agent-session.service'
import { ProjectSpecialistRoleAdapter } from './role-adapters/project-specialist.adapter'
import type { AgentRoleAdapter } from './agent-session.types'
import type { CacheEfficiencyReport } from './agent-token-tracker'
import { workspaceRepository } from '../db/repositories'
import { modelConfigService } from './model-config.service'
import { memoryDocWatcherService } from './memory-doc-watcher.service'

/** Events forwarded session → this facade. */
const FORWARDED_EVENTS = [
  'chunk',
  'statusUpdate',
  'complete',
  'intent',
  'plan',
  'askQuestion',
  'permissionRequest',
  'promptSuggestion',
  'compactNeeded',
  'elicitation',
  'budgetCapReached'
] as const

/** Internal state for a single workspace's session. */
interface SessionEntry {
  adapter: AgentRoleAdapter
  session: AgentSessionService
  forwarderCleanups: Array<() => void>
  workspacePath: string
}

export class ChatAgentService extends EventEmitter {
  private readonly log = chatAgentLogger

  /** Active sessions indexed by workspaceId. */
  private sessions = new Map<string, SessionEntry>()

  /** Currently active (visible in UI) workspace. */
  private _activeWorkspaceId: string | null = null

  constructor() {
    super()
    this.setMaxListeners(100)

    // ELICIT-ROUTES-ACTIVE-01: Route elicitationResponse to the correct workspace
    // session when a workspaceId is provided, falling back to the active session.
    // The permission.ipc handler already routes correctly per-workspace; this
    // catch-all is only hit from sdk-control.ipc which always targets the active UI.
    this.on('elicitationResponse', (payload: unknown) => {
      const wsId = (payload as Record<string, unknown> | null)?.workspaceId as string | undefined
      const session = wsId
        ? this.getSessionForWorkspace(wsId)
        : this.getActiveSession()
      if (session) {
        session.emit('elicitationResponse', payload)
      } else {
        this.log.warn('[elicitationResponse] No session for routing — response dropped')
      }
    })
  }

  // ── Multi-Session Management ──────────────────────────────────────

  /**
   * Start (or re-activate) a session for a workspace. If the workspace already
   * has a running session, this is a no-op — the session keeps running.
   * Does NOT stop other workspace sessions.
   */
  async startForWorkspace(
    workspaceId: string,
    workspacePath: string,
    mode?: ConversationMode,
    resumeSessionId?: string
  ): Promise<void> {
    const existing = this.sessions.get(workspaceId)
    if (existing) {
      this.log.info(`[multi-session] Workspace ${workspaceId} already has a session — activating`)
      // Adapter may have changed (e.g., specialist build_status changed)
      const nextAdapter = this.resolveAdapter(workspacePath)
      // ADAPTER-IDENTITY-01: Compare by adapter type, not object identity —
      // resolveAdapter() creates fresh instances, so identity always differs.
      if (nextAdapter.constructor !== existing.adapter.constructor) {
        this.log.info(
          `[multi-session] Adapter changed for workspace ${workspaceId} — rebuilding session`
        )
        await this.stopForWorkspace(workspaceId)
        // Fall through to create a new session below
      } else {
        this._activeWorkspaceId = workspaceId
        // C2-FIX: Ensure the doc watcher follows the active workspace.
        // Without this, switching back to a previously-started workspace
        // leaves the watcher pointed at the last-started workspace.
        if (memoryDocWatcherService.activeWorkspace !== workspaceId) {
          try {
            const settings = workspaceRepository.getSettings(workspaceId) as Record<string, unknown>
            if (settings.memoryDocCapture !== false) {
              memoryDocWatcherService.start(workspaceId, workspacePath)
            } else {
              // N3-FIX: Target workspace has docCapture off — stop the old watcher
              // so it doesn't keep watching the previous workspace.
              memoryDocWatcherService.stop()
            }
          } catch (err) {
            this.log.debug('[doc-watcher] Failed to restart doc watcher on switch-back:', err)
          }
        }
        return // Session already running with correct adapter
      }
    }

    const adapter = this.resolveAdapter(workspacePath)
    const session = new AgentSessionService(adapter)
    const forwarderCleanups: Array<() => void> = []

    const entry: SessionEntry = { adapter, session, forwarderCleanups, workspacePath }

    // SVC-01: Wire forwarders and start BEFORE adding to map.
    // If start() throws, the entry never enters the map — prevents
    // dead-session ghost entries that block future startForWorkspace calls.
    this.wireSessionForwarders(workspaceId, entry)
    try {
      await session.start(workspacePath, mode, resumeSessionId)
    } catch (err) {
      // Cleanup on failure — don't leave partial forwarders
      this.teardownSessionForwarders(entry)
      throw err
    }

    // Only add to map and set active AFTER successful start
    this.sessions.set(workspaceId, entry)
    this._activeWorkspaceId = workspaceId

    // Start doc watcher if capture is enabled
    try {
      const settings = workspaceRepository.getSettings(workspaceId) as Record<string, unknown>
      if (settings.memoryDocCapture !== false) {
        memoryDocWatcherService.start(workspaceId, workspacePath)
      } else {
        // N3-FIX: New session's workspace has docCapture off — stop any
        // watcher left over from the previous workspace.
        memoryDocWatcherService.stop()
      }
    } catch (err) {
      this.log.debug('[doc-watcher] Failed to start doc watcher:', err)
    }
  }

  /**
   * Stop and remove a workspace session. Does NOT affect other sessions.
   */
  async stopForWorkspace(workspaceId: string): Promise<void> {
    const entry = this.sessions.get(workspaceId)
    if (!entry) return

    this.log.info(`[multi-session] Stopping session for workspace ${workspaceId}`)
    // C1-FIX: Only stop the doc watcher if it belongs to THIS workspace —
    // stopping a background session must not kill the active workspace's watcher.
    if (memoryDocWatcherService.activeWorkspace === workspaceId) {
      memoryDocWatcherService.stop()
    }
    this.teardownSessionForwarders(entry)

    try {
      await entry.session.stop()
    } catch {
      /* ignore — session may not have been fully started */
    }

    this.sessions.delete(workspaceId)

    if (this._activeWorkspaceId === workspaceId) {
      this._activeWorkspaceId = null
    }
  }

  /** Stop all running sessions (e.g., app quit). */
  async stopAll(): Promise<void> {
    const workspaceIds = [...this.sessions.keys()]
    this.log.info(`[multi-session] Stopping all ${workspaceIds.length} sessions`)
    await Promise.allSettled(workspaceIds.map((id) => this.stopForWorkspace(id)))
  }

  /** Send a message to a specific workspace session. */
  async sendForWorkspace(
    workspaceId: string,
    message: string,
    conversationId: string,
    images?: ImageAttachment[]
  ): Promise<void> {
    const entry = this.sessions.get(workspaceId)
    if (!entry) throw new Error(`No session for workspace ${workspaceId}`)
    return entry.session.send(message, conversationId, images)
  }

  /** Get the session for a specific workspace (or undefined). */
  getSessionForWorkspace(workspaceId: string): AgentSessionService | undefined {
    return this.sessions.get(workspaceId)?.session
  }

  /** Get the adapter for a specific workspace (or undefined). */
  getAdapterForWorkspace(workspaceId: string): AgentRoleAdapter | undefined {
    return this.sessions.get(workspaceId)?.adapter
  }

  /** Get statuses for all running workspace sessions. */
  getAllStatuses(): Map<string, AgentStatus> {
    const statuses = new Map<string, AgentStatus>()
    for (const [wsId, entry] of this.sessions) {
      const status = entry.session.getStatus()
      statuses.set(wsId, { ...status, workspaceId: wsId })
    }
    return statuses
  }

  /** Set the currently active (visible) workspace. */
  setActiveWorkspace(workspaceId: string | null): void {
    this._activeWorkspaceId = workspaceId
  }

  /** Get the active workspace ID. */
  get activeWorkspaceId(): string | null {
    return this._activeWorkspaceId
  }

  /** Check if a given workspace has a running session. */
  hasSessionForWorkspace(workspaceId: string): boolean {
    return this.sessions.has(workspaceId)
  }

  /** Get the number of active sessions. */
  get activeSessionCount(): number {
    return this.sessions.size
  }

  // ── Event Forwarding (workspace-tagged) ───────────────────────────

  private wireSessionForwarders(workspaceId: string, entry: SessionEntry): void {
    for (const evt of FORWARDED_EVENTS) {
      const handler = (...args: unknown[]): void => {
        // Emit with workspaceId as the first argument for new consumers
        this.emit(evt, ...args)
        // Also emit a workspace-tagged version for multi-session-aware consumers
        this.emit(`${evt}:ws`, workspaceId, ...args)
      }
      entry.session.on(evt, handler)
      entry.forwarderCleanups.push(() => entry.session.off(evt, handler))
    }
  }

  private teardownSessionForwarders(entry: SessionEntry): void {
    for (const off of entry.forwarderCleanups) off()
    entry.forwarderCleanups = []
  }

  // ── Adapter Resolution ────────────────────────────────────────────

  /**
   * Always returns a ProjectSpecialistRoleAdapter. When a specialist row
   * exists with build_status='ready', the adapter uses the tailored prompt;
   * otherwise it falls back to DEFAULT_ARCHITECT_PROMPT.
   */
  private resolveAdapter(workspacePath: string): AgentRoleAdapter {
    const workspace = workspaceRepository.findByPath(workspacePath)
    const workspaceId = workspace?.id ?? workspacePath
    return new ProjectSpecialistRoleAdapter({ workspaceId })
  }

  // ── Active Session Helper ─────────────────────────────────────────

  private getActiveSession(): AgentSessionService | undefined {
    if (!this._activeWorkspaceId) return undefined
    return this.sessions.get(this._activeWorkspaceId)?.session
  }

  private getActiveEntry(): SessionEntry | undefined {
    if (!this._activeWorkspaceId) return undefined
    return this.sessions.get(this._activeWorkspaceId)
  }

  private getActiveAdapter(): AgentRoleAdapter | undefined {
    return this.getActiveEntry()?.adapter
  }

  /**
   * Ensure a live session exists & is active for a workspace; lazily starts
   * it if missing. Self-heals the fire-and-forget startAgent race.
   */
  async ensureStarted(workspaceId: string, workspacePath: string): Promise<void> {
    if (!this.hasSessionForWorkspace(workspaceId)) {
      await this.startForWorkspace(workspaceId, workspacePath)
    }
    if (this._activeWorkspaceId !== workspaceId) {
      this.setActiveWorkspace(workspaceId)
    }
  }

  // ── Backward-Compatible Lifecycle (delegates to active workspace) ─

  /**
   * Start a session for a workspace path. Resolves workspaceId from the path.
   * Backward-compatible with the old single-session API.
   */
  async start(
    workspacePath: string,
    mode?: ConversationMode,
    resumeSessionId?: string
  ): Promise<void> {
    const workspace = workspaceRepository.findByPath(workspacePath)
    const workspaceId = workspace?.id ?? workspacePath // Fallback to path if no workspace found
    return this.startForWorkspace(workspaceId, workspacePath, mode, resumeSessionId)
  }

  async send(message: string, conversationId: string, images?: ImageAttachment[]): Promise<void> {
    const session = this.getActiveSession()
    if (!session) throw new Error('No active session — call start() first')
    return session.send(message, conversationId, images)
  }

  async stop(): Promise<void> {
    if (this._activeWorkspaceId) {
      return this.stopForWorkspace(this._activeWorkspaceId)
    }
  }

  cancelCurrentQuery(conversationId?: string): void {
    this.getActiveSession()?.cancelCurrentQuery(conversationId)
  }

  async switchMode(mode: ConversationMode): Promise<void> {
    const session = this.getActiveSession()
    if (!session) return

    if (mode === session.getMode()) return
    const adapter = this.getActiveAdapter()
    adapter?.setPendingModeSwitch?.(session.getMode(), mode)
    return session.switchMode(mode)
  }

  /** @deprecated Persona system removed — no-op. */
  async switchPersona(_personaSpecialistId: string | null, _conversationId: string): Promise<void> {
    this.log.warn('[persona-switch] Persona system removed — no-op')
  }

  async injectContext(context: string, conversationId: string): Promise<void> {
    const session = this.getActiveSession()
    if (!session?.getWorkspacePath()) {
      this.log.warn('Cannot inject context — agent not started')
      return
    }
    const adapter = this.getActiveAdapter()
    if (!adapter?.addPendingContext) return

    const existingSize = adapter.getPendingContextSize?.(conversationId) ?? 0
    adapter.addPendingContext(conversationId, context)
    if (existingSize > 0) {
      this.log.info(
        `Appended to pending context injection for conversation ${conversationId} (${context.length} chars added, total: ${existingSize + context.length + 2} chars)`
      )
    } else {
      this.log.info(
        `Stored pending context injection for conversation ${conversationId} (${context.length} chars — will prepend to next send())`
      )
    }
  }

  async compact(extractNuance = false): Promise<void> {
    const session = this.getActiveSession()
    if (!session) throw new Error('Agent not running — nothing to compact')

    const workspacePath = session.getWorkspacePath()
    const conversationId = session.getCurrentConversationId()
    if (!workspacePath || !conversationId) {
      throw new Error('Agent not running — nothing to compact')
    }

    // Local LLMs: delegate directly to session.compact() which emits
    // 'compactNeeded' with level='local-unsupported' — no sessionId needed.
    if (modelConfigService.isLocalProvider(workspacePath)) {
      await session.compact()
      return
    }

    const sessionId = session.getSessionId(conversationId)
    if (!sessionId) {
      throw new Error('No session to compact')
    }

    this.log.info(`Starting native SDK compaction (nuance=${extractNuance})`)

    const adapter = this.getActiveAdapter()
    if (adapter?.setPendingCompaction) {
      if (extractNuance) {
        adapter.setPendingCompaction(
          conversationId,
          '/compact Extract nuance: preserve ALL decisions, preferences, file paths, specialist reports verbatim. Keep recent 3-4 turns verbatim.'
        )
      } else {
        adapter.setPendingCompaction(conversationId, '/compact')
      }
    }
    await session.compact()
  }

  async resumeAt(messageId: string): Promise<void> {
    const session = this.getActiveSession()
    if (!session) throw new Error('No active session for resumeAt')
    return session.resumeAt(messageId)
  }

  // ── Accessors (backward-compat — delegate to active workspace) ────

  getStatus(): AgentStatus {
    const session = this.getActiveSession()
    if (!session) {
      return {
        agentId: 'specialist',
        agentType: 'specialist',
        status: 'idle',
        elapsedMs: 0,
        tokenUsage: 0,
        workspaceId: this._activeWorkspaceId ?? undefined
      }
    }
    return { ...session.getStatus(), workspaceId: this._activeWorkspaceId ?? undefined }
  }

  isRunning(): boolean {
    return this.getActiveSession()?.isRunning() ?? false
  }

  /**
   * Route the renderer's answer to an ask_user question back through the IPC bridge
   * to the control-actions MCP server's pending askUserAndWaitForResponse promise.
   */
  respondToAskUser(requestId: string, response: string): void {
    this.getActiveSession()?.respondToAskUser(requestId, response)
  }

  /**
   * Route respondToAskUser to a specific workspace (for cross-workspace permission flow).
   */
  respondToAskUserForWorkspace(workspaceId: string, requestId: string, response: string): void {
    this.sessions.get(workspaceId)?.session.respondToAskUser(requestId, response)
  }

  /**
   * Route respondToPermission to a specific workspace (for cross-workspace permission flow).
   */
  respondToPermissionForWorkspace(workspaceId: string, requestId: string, approved: boolean): void {
    this.sessions.get(workspaceId)?.session.respondToPermission(requestId, approved)
  }

  getWorkspacePath(): string | null {
    return this.getActiveSession()?.getWorkspacePath() ?? null
  }

  getCurrentConversationId(): string | null {
    return this.getActiveSession()?.getCurrentConversationId() ?? null
  }

  getStreamedContent(conversationId?: string): string {
    return this.getActiveSession()?.getStreamedContent(conversationId) ?? ''
  }

  getMode(): ConversationMode {
    return this.getActiveSession()?.getMode() ?? 'plan'
  }

  getCacheEfficiency(): CacheEfficiencyReport {
    const session = this.getActiveSession()
    if (!session) {
      return { hitRate: 0, savedTokens: 0, totalInput: 0, turns: 0, turnBreakdown: [] }
    }
    return session.getCacheEfficiency()
  }

  getSessionId(conversationId: string): string | undefined {
    return this.getActiveSession()?.getSessionId(conversationId)
  }

  clearSession(conversationId: string): void {
    this.getActiveSession()?.clearSession(conversationId)
    this.clearConversationPendingState(conversationId)
  }

  /**
   * COMPACT-ABORT-01: Clear only the adapter's per-conversation pending state
   * (compaction, context injection) without touching the session map.
   * Safe to call on abort — the conversation remains resumable.
   */
  clearConversationPendingState(conversationId: string): void {
    this.getActiveAdapter()?.clearConversation?.(conversationId)
  }

  /** Which executor backend is active for the current workspace (cli | local-direct | unknown). */
  getExecutorBackend(): string {
    const wp = this.getActiveSession()?.getWorkspacePath() ?? undefined
    return modelConfigService.getExecutorBackend(wp)
  }

  /** Which role is currently driving the session. */
  getActiveRole(): AgentRole {
    return this.getActiveAdapter()?.role ?? 'specialist'
  }

  /** The agent_id of the currently active adapter. */
  getActiveAgentId(): string {
    return this.getActiveAdapter()?.agentId ?? 'specialist'
  }

  /** The DB role tag for the active adapter. Always 'specialist'. */
  getActiveMessageRole(): 'specialist' {
    return 'specialist'
  }

  /** @deprecated Persona system removed — always returns null. */
  getActivePersona(): { id: string; agentId: string; alias: string | null } | null {
    return null
  }
}

export const chatAgentService = new ChatAgentService()

/**
 * ProjectSpecialistRoleAdapter — the **only** chat adapter for workspace
 * sessions. Drives AgentSessionService for every workspace.
 *
 * When a specialist row exists with build_status='ready', uses the
 * LLM-tailored prompt from specialists.prompt. Otherwise falls back to
 * DEFAULT_ARCHITECT_PROMPT — a competent generic identity so the agent
 * works immediately, even before specialist generation completes.
 *
 * Also owns all pending-state management (mode switch, compaction,
 * context injection) previously in the legacy DaVinci adapter.
 */

import type { ConversationMode, ModelAction } from '../../../shared/types'
import { RECOMMENDED_LOCAL_MODELS } from '../../../shared/constants'
import type {
  AdapterPromptContext,
  AdapterPromptResult,
  AdapterSessionLifecycleCtx
} from '../agent-session.types'
import { getDatabase } from '../../db/index'
import {
  appendMcpToolGuidance,
  buildConditionalPrefix,
  buildModeContextPrefix
} from '../prompt-assembly-helpers'
import {
  DEFAULT_ARCHITECT_PROMPT,
  UNIFIED_MODE_SECTION,
  TONE_STYLE_DIRECTIVES,
  TOOL_PRIORITY_DIRECTIVE
} from '../default-prompts'
import { modelConfigService } from '../model-config.service'
import { promptBuilder } from '../prompt-builder'
import { resolveContextTier } from '../context-management'
import { SystemPromptCache } from '../system-prompt-cache'
import { BaseRoleAdapter } from './base.adapter'

interface SpecialistSnapshot {
  id: string
  agentId: string
  displayName: string
  prompt: string
  buildStatus: string
}

export class ProjectSpecialistRoleAdapter extends BaseRoleAdapter {
  readonly role = 'specialist' as const
  readonly agentId: string
  override readonly supportsEmitPlanRecovery = true

  private readonly workspaceId: string
  private snapshot: SpecialistSnapshot | null = null

  /** Pattern 7: Extracted system-prompt snapshot cache. */
  private readonly promptCache = new SystemPromptCache()

  // ── Pending State ──────────

  /** Pending mode switch — next buildPrompts() prefixes the user message */
  private pendingModeSwitch: { from: ConversationMode; to: ConversationMode } | null = null

  /** Strategy A: Pending context injection per conversation (capped at 8K chars) */
  private static readonly MAX_PENDING_CONTEXT_CHARS = 8000
  private pendingContextInjection: Map<string, string> = new Map()

  /** Strategy B: Pending compaction per conversation */
  private pendingCompaction: Map<string, string> = new Map()

  // ── Goal State (per-conversation, consumed on next send) ────────
  private pendingGoals = new Map<string, { goal: string; mode: 'advisory' | 'enforce' }>()

  constructor(params: { workspaceId: string; agentId?: string }) {
    super()
    this.workspaceId = params.workspaceId
    this.agentId = params.agentId ?? `workspace-specialist-${params.workspaceId}`
  }

  override async onSessionStart(ctx: AdapterSessionLifecycleCtx): Promise<void> {
    this.loadSnapshot()

    // Pattern 2: Centralized workspace feature flag refresh
    this.refreshWorkspaceFeatureFlags(ctx.workspaceId, ctx.workspacePath)

    // Pattern 6 / Strategy Λ: Lock MCP flags at session start
    this.lockMcpFlags()
  }

  override refreshFeatureFlags(ctx: AdapterSessionLifecycleCtx): void {
    // Re-read the snapshot — the builder may have updated prompt between sends
    // (skills toggled, prompt rebuilt). Also refresh workspace feature flags.
    this.loadSnapshot()
    // Pattern 2: Centralized workspace feature flag refresh
    this.refreshWorkspaceFeatureFlags(ctx.workspaceId, ctx.workspacePath)
  }

  override onConversationSwitch(_conversationId: string): void {
    // Drop the cached system-prompt — the next buildPrompts() will rebuild
    // with the new conversation context (and re-read CLAUDE.md if it changed).
    this.invalidateSnapshot()
  }

  /**
   * Drop the cached system-prompt assembly. Called by onConversationSwitch
   * and exposed publicly so the session layer can force a rebuild on
   * mode switches or other lifecycle events.
   */
  invalidateSnapshot(): void {
    this.promptCache.invalidate()
    this.invalidateToneCache()
  }

  buildPrompts(ctx: AdapterPromptContext): AdapterPromptResult {
    if (!this.snapshot) this.loadSnapshot()

    // Resolve the identity prompt: use the specialist's tailored prompt if
    // ready, otherwise fall back to the generic architect prompt.
    const identityPrompt = this.resolveIdentityPrompt()

    // Pattern 5: Centralized communication tone resolution
    const communicationTone = this.resolveCommunicationTone(
      ctx.conversationId,
      this.workspaceId,
      ctx.turnCount
    )

    // Local LLM: condensed prompt — skip skills, memory, caching strategies.
    // S5: Inject plan-focused directive with context tier for local plan mode.
    if (modelConfigService.isLocalProvider(ctx.workspacePath)) {
      const localConfig = modelConfigService.getLocalLLMConfig(ctx.workspacePath)
      // F2: Resolve actual context window from RECOMMENDED_LOCAL_MODELS
      const match = RECOMMENDED_LOCAL_MODELS.find(
        (m) => m.ollamaId === localConfig.localModel || m.omlxId === localConfig.localModel
      )
      const contextTier = resolveContextTier(match?.contextWindow ?? 32_768)
      const systemPrompt = promptBuilder.buildLocalPrompt({
        role: 'specialist',
        mode: ctx.mode,
        workspacePath: ctx.workspacePath,
        budgetTier: 'minimal',
        contextTier,
        communicationTone
      })
      return { systemPrompt, effectiveMessage: ctx.message }
    }

    // ── System-prompt assembly with snapshot cache ─────────────────
    // Pattern 1: Centralized model resolution
    const isBuildMode = ctx.mode === 'build' || ctx.mode === 'danger'
    const resolvedModel = this.resolveModel(
      ctx.workspacePath,
      `${this.role}:${isBuildMode ? 'build' : 'plan'}` as ModelAction
    )

    // Pattern 7: SystemPromptCache for snapshot reuse
    const cacheKeys = {
      mode: ctx.mode,
      conversationId: ctx.conversationId,
      tone: communicationTone,
      model: resolvedModel ?? null
    }

    let systemPrompt: string
    if (this.promptCache.isValid(cacheKeys, ctx.turnCount)) {
      systemPrompt = this.promptCache.get()!
    } else {
      const modeSection = UNIFIED_MODE_SECTION
      const claudeMdLayer = ctx.workspacePath
        ? promptBuilder.buildClaudeMdLayer(ctx.workspacePath, ctx.mode)
        : ''
      const layers = [modeSection, identityPrompt]
      const baselineSkills = promptBuilder.skills.buildBaselineSkillsLayer()
      if (baselineSkills) layers.push(baselineSkills)
      if (claudeMdLayer) layers.push(claudeMdLayer)
      // Append communication tone overlay for non-default tones.
      if (communicationTone !== 'default') {
        layers.push(`## Communication Tone Override\n${TONE_STYLE_DIRECTIVES[communicationTone]}`)
      }
      const basePrompt = layers.join('\n\n')
      // Strategy Λ: Use locked flags so MCP guidance matches the mounted tool set.
      const mcpFlags = this.getLockedMcpFlags()
      // Resolve which external MCPs are active — drives prompt guidance injection
      const externalMcpActive = this.resolveExternalMcpActive(
        ctx.workspaceId ?? this.workspaceId,
        ctx.conversationId
      )
      systemPrompt = appendMcpToolGuidance(
        basePrompt,
        ctx.turnCount,
        {
          ...mcpFlags,
          externalMcpActive,
          codeAnalysisEnabled: this.codeAnalysisEnabled
        },
        resolvedModel
      )

      // Ensure Tool Priority directive is present
      if (!systemPrompt.includes('## Tool Priority')) {
        systemPrompt += '\n' + TOOL_PRIORITY_DIRECTIVE
      }
      this.promptCache.set(systemPrompt, cacheKeys)
    }

    // ── Effective message assembly with pending state ─────────────
    let effectiveMessage = `${buildModeContextPrefix(ctx.mode, resolvedModel)}\n\n${ctx.message}`

    // Strategy A: Prepend pending context injection.
    // COMPACT-LOST-01: Read but don't delete — deferred to onSendSuccess().
    const pendingContext = ctx.conversationId
      ? this.pendingContextInjection.get(ctx.conversationId)
      : undefined
    if (pendingContext) {
      effectiveMessage = `[Context from prior specialist execution — use this to answer follow-up questions without re-delegating]\n\n${pendingContext}\n\n---\n\n${effectiveMessage}`
      this.log.info(
        `[PIPELINE:lazy-inject] Prepended ${pendingContext.length} chars of specialist context (pending confirmation)`
      )
    }

    // Strategy B: Prepend pending compaction.
    // COMPACT-LOST-01: Read but don't delete — see onSendSuccess().
    const pendingCompact = ctx.conversationId
      ? this.pendingCompaction.get(ctx.conversationId)
      : undefined
    if (pendingCompact) {
      effectiveMessage = `${pendingCompact}\n\n---\n\n${effectiveMessage}`
      this.log.info('[PIPELINE:lazy-compact] Prepended compaction instruction (pending confirmation)')
    }

    // Mode switch context
    if (this.pendingModeSwitch) {
      const { from, to } = this.pendingModeSwitch
      effectiveMessage = `[Mode switched from ${from} to ${to}. Follow the <mode-context> instructions above.]\n\n${effectiveMessage}`
      this.log.info(`Mode switch context injected: ${from} → ${to}`)
      this.pendingModeSwitch = null
    }

    // User-turn prefix (ASK + MEMORY + IMAGE + DIRECT + plan reminder).
    const conditionalPrefix = buildConditionalPrefix({
      message: ctx.message,
      hasImages: ctx.hasImages,
      mode: ctx.mode,
      turnCount: ctx.turnCount,
      model: resolvedModel
    })
    if (conditionalPrefix) {
      effectiveMessage = `${conditionalPrefix}\n\n---\n\n${effectiveMessage}`
    }

    return { systemPrompt, effectiveMessage }
  }

  protected override resolveWorkspaceId(): string | null {
    return this.workspaceId
  }

  override onSessionStop(): void {
    this.snapshot = null
    this.repomapEnabled = true
    this.semanticSearchEnabled = true
    this.githubConfigured = false
    this.unlockMcpFlags()
    this.invalidateSnapshot()
    this.pendingModeSwitch = null
    this.pendingContextInjection.clear()
    this.pendingCompaction.clear()
    this.pendingGoals.clear()
  }

  /** Refresh the cached specialist row from the DB. */
  private loadSnapshot(): void {
    try {
      const db = getDatabase()
      const row = db
        .prepare(
          `SELECT id, agent_id, display_name, prompt, build_status
             FROM specialists WHERE workspace_id = ?`
        )
        .get(this.workspaceId) as
        | {
            id: string
            agent_id: string
            display_name: string
            prompt: string
            build_status: string
          }
        | undefined
      if (!row) {
        this.snapshot = null
        return
      }
      this.snapshot = {
        id: row.id,
        agentId: row.agent_id,
        displayName: row.display_name,
        prompt: row.prompt ?? '',
        buildStatus: row.build_status
      }
    } catch (err) {
      this.log.warn('Failed to load Project Specialist snapshot:', err)
      this.snapshot = null
    }
  }

  /** The workspace this adapter is bound to. */
  getWorkspaceId(): string {
    return this.workspaceId
  }

  /** For debugging / UI: who is this adapter bound to? */
  getSpecialistId(): string | null {
    return this.snapshot?.id ?? null
  }

  getDisplayName(): string | null {
    return this.snapshot?.displayName ?? null
  }

  getBuildStatus(): string | null {
    return this.snapshot?.buildStatus ?? null
  }

  getMode(): ConversationMode {
    return 'plan'
  }

  // ── Goal Condition Methods ──

  /**
   * Queue a /goal condition for the next send on this conversation.
   * Consumed (auto-cleared) by consumeGoalForConversation() during _doSend().
   */
  setGoalCondition(conversationId: string, goal: string, mode: 'advisory' | 'enforce' = 'enforce'): void {
    this.pendingGoals.set(conversationId, { goal, mode })
  }

  /**
   * Read and consume the pending goal for a conversation.
   * Returns null if no goal was queued. One-shot: clears after read.
   */
  consumeGoalForConversation(conversationId: string): { goal: string; mode: 'advisory' | 'enforce' } | null {
    const pending = this.pendingGoals.get(conversationId)
    if (pending) {
      this.pendingGoals.delete(conversationId)
      return pending
    }
    return null
  }

  /**
   * Duck-type compat: getGoalCondition() returns null for ProjectSpecialist.
   * Chat goals are consumed via consumeGoalForConversation() in _doSend,
   * NOT via this method. Blueprint/MPA adapters use getGoalCondition() directly.
   */
  getGoalCondition(): string | null {
    return null
  }

  getGoalMode(): 'advisory' | 'enforce' {
    return 'advisory'
  }

  // ── Pending State Management ──

  /** Queue a mode-switch prefix for the next buildPrompts() call. */
  setPendingModeSwitch(from: ConversationMode, to: ConversationMode): void {
    this.pendingModeSwitch = { from, to }
    this.invalidateSnapshot()
  }

  /** Queue a compaction instruction for the next send(). */
  setPendingCompaction(conversationId: string, prompt: string): void {
    this.pendingCompaction.set(conversationId, prompt)
  }

  /**
   * COMPACT-LOST-01: Confirm pending injections were sent successfully.
   * Called AFTER executeStream() succeeds. If it threw, pending state is preserved.
   */
  onSendSuccess(conversationId: string): void {
    if (this.pendingContextInjection.has(conversationId)) {
      this.pendingContextInjection.delete(conversationId)
      this.log.info('[PIPELINE:lazy-inject] Context injection confirmed consumed')
    }
    if (this.pendingCompaction.has(conversationId)) {
      this.pendingCompaction.delete(conversationId)
      this.log.info('[PIPELINE:lazy-compact] Compaction instruction confirmed consumed')
    }
  }

  /** Store pending context injection (Strategy A). Accumulates with 8K cap. */
  addPendingContext(conversationId: string, context: string): void {
    const existing = this.pendingContextInjection.get(conversationId)
    if (existing) {
      const combined = `${existing}\n\n${context}`
      if (combined.length > ProjectSpecialistRoleAdapter.MAX_PENDING_CONTEXT_CHARS) {
        this.pendingContextInjection.set(
          conversationId,
          combined.slice(-ProjectSpecialistRoleAdapter.MAX_PENDING_CONTEXT_CHARS)
        )
        this.log.warn(
          `[PIPELINE:pending-context-cap] Truncated accumulated context from ${combined.length} to ${ProjectSpecialistRoleAdapter.MAX_PENDING_CONTEXT_CHARS} chars`
        )
      } else {
        this.pendingContextInjection.set(conversationId, combined)
      }
    } else {
      this.pendingContextInjection.set(conversationId, context)
    }
  }

  /** Get pending context size for logging. */
  getPendingContextSize(conversationId: string): number {
    return this.pendingContextInjection.get(conversationId)?.length ?? 0
  }

  /** Clear all per-conversation pending state. */
  clearConversation(conversationId: string): void {
    this.pendingContextInjection.delete(conversationId)
    this.pendingCompaction.delete(conversationId)
    this.pendingGoals.delete(conversationId)
  }

  // ── Private Helpers ──

  /**
   * Resolve the identity prompt to use in the system prompt.
   * - If a specialist row exists and is ready → use its tailored prompt
   * - Otherwise → use DEFAULT_ARCHITECT_PROMPT
   */
  private resolveIdentityPrompt(): string {
    if (this.snapshot?.buildStatus === 'ready' && this.snapshot.prompt) {
      return this.snapshot.prompt
    }
    return DEFAULT_ARCHITECT_PROMPT
  }
}

/**
 * Stateless prompt-assembly helpers shared by ProjectSpecialistRoleAdapter.
 * These provide MCP-guidance blocks and conditional user-turn prefixes.
 *
 * These helpers do not touch DB or filesystem directly (memory/CLAUDE.md
 * layering lives in PromptBuilder). They only operate on the values passed in.
 */
import type { ConversationMode } from '../../shared/types'
import {
  // Unified guidance blocks (full === lean after W2 unification)
  ASK_QUESTION_PROMPT,
  CHECKPOINT_CONTEXT_GUIDANCE_PROMPT,
  CODE_ANALYSIS_GUIDANCE_PROMPT,
  GIT_CONTEXT_GUIDANCE_PROMPT,
  GITHUB_CONTEXT_GUIDANCE_PROMPT,
  IMAGE_ATTACHMENTS_PROMPT,
  LIBRARY_DOCS_GUIDANCE_PROMPT,
  MAESTRO_GUIDANCE_PROMPT,
  MEMORY_PROTOCOL_PROMPT,
  PROCESS_MANAGER_GUIDANCE_PROMPT,
  REPOMAP_GUIDANCE_PROMPT,
  SEMANTIC_SEARCH_GUIDANCE_PROMPT,
  // Guidance blocks that still differ between full/lean
  ESLINT_GUIDANCE_PROMPT,
  ESLINT_GUIDANCE_PROMPT_LEAN,
  DIRECT_ANSWER_BOOST_PROMPT,
  DIRECT_ANSWER_BOOST_PROMPT_LEAN,
  DIRECT_ANSWER_PLAN_MODE_EARLY,
  // Mode & plan constants
  MODE_CONTEXT_SECTIONS,
  MODE_CONTEXT_SECTIONS_LEAN,
  PLAN_REMINDER_FULL,
  PLAN_REMINDER_LEAN,
  TOOL_PRIORITY_DIRECTIVE
} from './default-prompts'
import { resolvePromptVerbosity } from '../../shared/constants'
import { promptBuilder } from './prompt-builder'
import { chatAgentLogger } from '../logger'

const log = chatAgentLogger

/** Feature flags that affect prompt assembly (same shape used by both roles). */
export interface PromptFeatureFlags {
  repomapEnabled: boolean
  semanticSearchEnabled: boolean
  githubConfigured: boolean
  /** Whether git-context tools are mounted (default true). Set false for local-LLM adapters that skip git tools. */
  includeGitContext?: boolean
  /** Whether checkpoint-context tools are mounted (default true). Set false for evaluation adapters that skip checkpoints. */
  includeCheckpoint?: boolean
  /** External MCPs active for this chat (e.g. { maestro: true }) — drives prompt guidance injection */
  externalMcpActive?: Record<string, boolean>
  /** Whether code-analysis tools are mounted (default true). Set false for small-tier local LLMs. */
  codeAnalysisEnabled?: boolean
  /** Whether process-manager tools are available (false in plan mode). */
  processManagerEnabled?: boolean
}

// ── Data-driven guidance configuration ──

/**
 * W3-F1: Simplified GuidanceSection — single `prompt` field with optional
 * `leanVariant` override. Only ESLint uses `leanVariant` (8/9 entries
 * were identical between lean/full after W2 unification).
 */
interface GuidanceSection {
  marker: string
  flag: (f: PromptFeatureFlags) => boolean
  prompt: string
  /** Overrides `prompt` when lean verbosity is active. Only set when lean differs. */
  leanVariant?: string
  /** When set, skip the lean variant if basePrompt already contains this marker. */
  skipLeanWhen?: string
}

const GUIDANCE_SECTIONS: GuidanceSection[] = [
  { marker: '## Code Graph', flag: (f) => f.repomapEnabled, prompt: REPOMAP_GUIDANCE_PROMPT, skipLeanWhen: '## Code Exploration' },
  { marker: '## Semantic Search', flag: (f) => f.semanticSearchEnabled, prompt: SEMANTIC_SEARCH_GUIDANCE_PROMPT },
  { marker: '## Git Context', flag: (f) => f.includeGitContext !== false, prompt: GIT_CONTEXT_GUIDANCE_PROMPT },
  { marker: '## Checkpoint Tools', flag: (f) => f.includeCheckpoint !== false, prompt: CHECKPOINT_CONTEXT_GUIDANCE_PROMPT },
  { marker: '## GitHub Tools', flag: (f) => f.githubConfigured, prompt: GITHUB_CONTEXT_GUIDANCE_PROMPT },
  { marker: '## Code Analysis', flag: (f) => f.codeAnalysisEnabled !== false, prompt: CODE_ANALYSIS_GUIDANCE_PROMPT },
  { marker: '## Library Doc', flag: (f) => f.codeAnalysisEnabled !== false, prompt: LIBRARY_DOCS_GUIDANCE_PROMPT },
  { marker: '## Maestro', flag: (f) => !!f.externalMcpActive?.['maestro'], prompt: MAESTRO_GUIDANCE_PROMPT },
  // ESLint: only entry where lean differs (full includes "Warnings OK; errors are NOT")
  { marker: '## ESLint', flag: () => true, prompt: ESLINT_GUIDANCE_PROMPT, leanVariant: ESLINT_GUIDANCE_PROMPT_LEAN },
  { marker: '## Background Processes', flag: (f) => f.processManagerEnabled !== false, prompt: PROCESS_MANAGER_GUIDANCE_PROMPT }
]

/**
 * Strategy δ: Append MCP tool guidance sections to a system prompt — turn 1 only.
 * These blocks are workspace-stable (don't toggle between turns) so they live
 * in the system prompt. They are idempotent: if a block is already present
 * (e.g. the base prompt already embeds it) we skip it.
 */
export function appendMcpToolGuidance(
  basePrompt: string,
  turnCount: number,
  featureFlags: PromptFeatureFlags,
  model?: string
): string {
  // W3-F3: Turn 2+ — tool priority reminder only (~20 tokens).
  // PLAN_OUTPUT_GUIDANCE_LEAN removed: mode-context already carries the full emit_plan workflow.
  // Lean models already have tool priority in their identity prompt every turn.
  if (turnCount > 1) {
    const verbosity2 = resolvePromptVerbosity(model ?? '')
    if (verbosity2 !== 'lean' && featureFlags.repomapEnabled) {
      return basePrompt + TOOL_PRIORITY_DIRECTIVE
    }
    return basePrompt
  }

  const verbosity = resolvePromptVerbosity(model ?? '')
  const appendSections: string[] = []

  for (const section of GUIDANCE_SECTIONS) {
    if (!section.flag(featureFlags) || basePrompt.includes(section.marker)) continue
    if (verbosity === 'lean' && section.skipLeanWhen && basePrompt.includes(section.skipLeanWhen)) continue
    const text = (verbosity === 'lean' && section.leanVariant) ? section.leanVariant : section.prompt
    appendSections.push(text)
  }

  if (appendSections.length === 0) return basePrompt
  return `${basePrompt}\n\n---\n\n${appendSections.join('\n\n---\n\n')}`
}

/**
 * Strategy α: Build the conditional prefix injected into the user message.
 * The prefix toggles based on the user's message content and turn count.
 * Keeping it OUT of the system prompt lets Claude cache the system prompt.
 */
export function buildConditionalPrefix(opts: {
  message: string
  hasImages: boolean
  mode: ConversationMode
  turnCount: number
  model?: string
}): string {
  const { message, hasImages, mode, turnCount } = opts
  const verbosity = resolvePromptVerbosity(opts.model ?? '')
  const conditionalSections = promptBuilder.getGeneralistConditionalSections(
    message,
    hasImages,
    verbosity
  )
  const sections: string[] = []

  // Skip ask_user prompt on turns 2+ — already in history from turn 1.
  if (conditionalSections.includeAskQuestionPrompt && turnCount <= 1) {
    sections.push(ASK_QUESTION_PROMPT) // unified: full === lean
  }

  // Skip memory-protocol prompt on turns 2+ — already in history from turn 1.
  if (conditionalSections.includeMemoryProtocolPrompt && turnCount <= 1) {
    sections.push(MEMORY_PROTOCOL_PROMPT) // unified: full === lean
  }

  if (conditionalSections.includeImageAttachmentsPrompt) {
    sections.push(IMAGE_ATTACHMENTS_PROMPT) // unified: full === lean
  }

  // ── isPlanGenerationRequest — moved up to suppress contradictory direct-answer signal ──
  const isPlanGenerationRequest =
    /\b(create a plan|draft a plan|propose a plan|make a plan|write a plan|design a plan|plan for|plan to (implement|build|add|create|fix|refactor)|how (would|should|can) (I|we|you)|what('s| is) the (best|right) (way|approach)|investigate|diagnose|audit|analyze|review|examine|what.*(wrong|broken|failing|issue)|assess|evaluate|improve|optimize|migrate|migration|refactor|rewrite|overhaul|rearchitect|port\b(?!folio)|cut\s+over|transition\s+(to|from))\b/i.test(
      message
    )

  // Strategy N: Direct Answer Boost
  if (conditionalSections.includeDirectAnswerBoost) {
    if (turnCount >= 3) {
      sections.push(
        verbosity === 'lean' ? DIRECT_ANSWER_BOOST_PROMPT_LEAN : DIRECT_ANSWER_BOOST_PROMPT
      )
    } else if (mode === 'plan' && !isPlanGenerationRequest) {
      // Suppressed when isPlanGenerationRequest is true — plan intent overrides "don't use emit_plan"
      sections.push(DIRECT_ANSWER_PLAN_MODE_EARLY)
    }
  }

  // Strategy ζ: Plan Output Reinforcement (isPlanGenerationRequest already computed above)
  const isSimpleQuestion = conditionalSections.includeDirectAnswerBoost
  const planReminderInjected = isPlanGenerationRequest || (mode === 'plan' && !isSimpleQuestion)

  if (planReminderInjected) {
    // Turn 1 + full-verbosity model: full reminder. All other cases: lean.
    const planReminder = turnCount <= 1 && verbosity !== 'lean' ? PLAN_REMINDER_FULL : PLAN_REMINDER_LEAN
    sections.push(planReminder)
  }

  log.info(
    `[PIPELINE:conditional-prefix] ask=${conditionalSections.includeAskQuestionPrompt} memory=${conditionalSections.includeMemoryProtocolPrompt} image=${conditionalSections.includeImageAttachmentsPrompt} directBoost=${conditionalSections.includeDirectAnswerBoost} planReminder=${planReminderInjected}`
  )

  return sections.length > 0
    ? `[Contextual guidelines for this message]\n\n${sections.join('\n\n')}`
    : ''
}

/**
 * Pattern 8: Build the `<mode-context>` block injected per-message.
 * Shared by ProjectSpecialistRoleAdapter.
 */
export function buildModeContextPrefix(mode: ConversationMode, model?: string): string {
  const verbosity = resolvePromptVerbosity(model ?? '')
  const sections = verbosity === 'lean' ? MODE_CONTEXT_SECTIONS_LEAN : MODE_CONTEXT_SECTIONS
  const block = sections[mode] ?? sections.plan
  return `<mode-context>\n${block.trim()}\n</mode-context>`
}

import { readFileSync, statSync } from 'node:fs'
import { join } from 'node:path'
import type {
  BudgetTier,
  CommunicationTone,
  ConversationMode,
  PromptVerbosity,
  Skill
} from '../../shared/types'
import type { ContextWindowTier } from './context-management'
import { promptBuilderLogger } from '../logger'
import { coreAgentPromptRepository } from '../db/repositories/core-agent-prompt.repository'
import {
  DEFAULT_PROMPTS,
  TONE_STYLE_DIRECTIVES,
  buildSpecialistIdentityPrompt,
  buildSpecialistIdentityPromptLean,
  UNIFIED_MODE_SECTION
} from './default-prompts'
import { resolvePromptVerbosity } from '../../shared/constants'
import { SkillPromptComposer } from './skill-prompt-composer'
import { sanitizePromptInput } from './sanitize-prompt-input'

// ── Prompt Builder Types ──

type PromptRole = 'specialist'

interface PromptBuildOptions {
  /** Which agent role is this prompt for (always 'specialist') */
  role: PromptRole
  /** Conversation mode (plan or build) */
  mode: ConversationMode
  /** Workspace path for CLAUDE.md project context injection */
  workspacePath?: string
  /** Budget tier — controls context size for model-aware prompt budgeting (Strategy 4) */
  budgetTier?: BudgetTier
  /** Persona specialist ID for generalist impersonation (null = no persona) */
  personaSpecialistId?: string | null
  /** Persona specialist prompt content (from specialist.prompt field) */
  personaPrompt?: string
  /** Skills assigned to the persona specialist */
  personaSkills?: Skill[]
  /** Per-conversation skill overrides for the persona specialist */
  personaSkillOverrides?: string[]
  /** Communication tone for AI responses (affects ## Style section) */
  communicationTone?: CommunicationTone
  /** Resolved model ID — used for prompt verbosity gating (Opus 4.8+ gets lean prompts) */
  model?: string
}

export interface GeneralistConditionalSections {
  includeAskQuestionPrompt: boolean
  includeMemoryProtocolPrompt: boolean
  includeImageAttachmentsPrompt: boolean
  /** Strategy 3: Nudge generalist to answer directly for simple questions */
  includeDirectAnswerBoost: boolean
}

// ── Prompt Builder ──

const log = promptBuilderLogger

/**
 * Centralized prompt assembly for the default specialist.
 *
 * Assembles: optional persona overlay (when impersonating a specialist) + base role prompt
 * + CLAUDE.md project context + auto memory context.
 *
 * Note: Project Specialists use their own dedicated adapter (project-specialist.adapter.ts)
 * that reads `specialists.prompt` directly — they do not go through this builder.
 */
export class PromptBuilder {
  /**
   * Strategy G: In-memory CLAUDE.md cache with mtime invalidation.
   * Eliminates disk I/O on every turn — reads once and re-reads only when the file changes.
   */
  private claudeMdCache: Map<string, { content: string; mtimeMs: number }> = new Map()

  /** Delegated skill composition (extracted for testability + reduced complexity) */
  private skillComposer = new SkillPromptComposer()

  /** Turn-based budget profile for generalist prompt assembly (S17 adaptive prompt). */
  getGeneralistBudgetTierForTurn(turnCount: number): BudgetTier {
    if (turnCount <= 1) return 'full'
    if (turnCount <= 4) return 'standard'
    return 'minimal'
  }

  /**
   * Lightweight heuristics to decide which optional generalist prompt sections
   * should be injected for the current user turn (S12 conditional injection).
   */
  getGeneralistConditionalSections(
    message: string,
    hasImages: boolean,
    verbosity: PromptVerbosity = 'full'
  ): GeneralistConditionalSections {
    const normalized = message.toLowerCase()

    // Lean: tighter regex — require explicit option-signal phrasing.
    // Full: broader triggers for models that need more guidance.
    const includeAskQuestionPrompt =
      verbosity === 'lean'
        ? /\b(choose between|give me options|what are my options|which (one|option) should)\b/i.test(
            normalized
          )
        : /\b(which|choose|choice|option|pick|select|either|vs|versus|should i|what do you prefer)\b/i.test(
            normalized
          )

    const includeMemoryProtocolPrompt =
      /\b(remember|preference|prefer|i like|i dislike|always|never|for future|from now on|note this|keep in mind)\b/i.test(
        normalized
      )

    // Strategy 3: Direct Answer Boost — classify simple questions that can be answered directly.
    // Simple questions are short, use interrogative verbs, and DON'T request code mutations.
    // Analysis verbs (investigate, diagnose, audit, review) do NOT suppress the boost —
    // they're questions the generalist can often answer directly from context.
    const isQuestionPattern =
      /\b(what|why|how|where|which|explain|show me|list|describe|tell me|is there)\b/i.test(
        normalized
      )
    const isMutationRequest =
      /\b(fix|implement|build|create|add|refactor|update|change|modify|delete|remove|write|migrate|deploy|scaffold|generate)\b/i.test(
        normalized
      )
    const includeDirectAnswerBoost = isQuestionPattern && !isMutationRequest && message.length < 300

    return {
      includeAskQuestionPrompt,
      includeMemoryProtocolPrompt,
      includeImageAttachmentsPrompt: hasImages,
      includeDirectAnswerBoost
    }
  }

  /**
   * Build a complete system prompt for the default specialist role.
   * Composes prompt from layers (persona overlay, role, project context, memory).
   */
  build(options: PromptBuildOptions): string {
    const layers: string[] = []
    const budgetTier = options.budgetTier ?? 'standard'

    this.appendPersonaLayer(layers, options, budgetTier)
    this.appendRoleAndIdentityLayers(layers, options)
    // Always-on behavioral guidelines (coding discipline)
    const baselineSkills = this.skillComposer.buildBaselineSkillsLayer(budgetTier)
    if (baselineSkills) layers.push(baselineSkills)
    this.appendProjectContextLayer(layers, options, budgetTier)

    return layers.join('\n\n---\n\n')
  }

  /**
   * Build the CLAUDE.md project-context layer as a standalone string.
   *
   * Used by ProjectSpecialistRoleAdapter — specialists assemble their own
   * system prompt (mode + identity + CLAUDE.md + MCP guidance) instead of
   * going through `build()`. The mtime-based `claudeMdCache` shared with
   * the generalist path keeps disk reads cheap.
   *
   * Returns the formatted block (`## Workspace Project Context (from CLAUDE.md)\n\n<extracted>`)
   * or an empty string when no CLAUDE.md exists or the workspace is unset.
   */
  buildClaudeMdLayer(
    workspacePath: string,
    mode: ConversationMode,
    budgetTier: BudgetTier = 'standard'
  ): string {
    if (!workspacePath) return ''
    const projectContext = this.readProjectContext(workspacePath, mode, budgetTier)
    if (!projectContext) return ''
    return `## Workspace Project Context (from CLAUDE.md)\n\n${sanitizePromptInput(projectContext)}`
  }

  /**
   * Layer 0: Persona specialist identity + skills.
   * Injected BEFORE the specialist role prompt so the LLM sees itself as the specialist first.
   */
  private appendPersonaLayer(
    layers: string[],
    options: PromptBuildOptions,
    budgetTier: BudgetTier
  ): void {
    if (!options.personaSpecialistId || !options.personaPrompt) {
      return
    }
    layers.push(
      `## Your Specialized Identity\n\n` +
        `You are operating with the following domain expertise. ` +
        `Apply it to all conversations and analyses.\n\n` +
        sanitizePromptInput(options.personaPrompt)
    )
    if (options.personaSkills && options.personaSkills.length > 0) {
      const filtered = this.skillComposer.filterAssignedSkills(
        options.personaSkills,
        options.personaSkillOverrides
      )
      if (filtered.length > 0) {
        const content = this.skillComposer.buildSkillContent(filtered, budgetTier)
        if (content) layers.push(`## Domain Skills\n\n${content}`)
      }
    }
  }

  /**
   * Layer 1: Base role prompt (from DB, user-editable).
   */
  private appendRoleAndIdentityLayers(layers: string[], options: PromptBuildOptions): void {
    layers.push(
      this.getRolePrompt(options.role, options.mode, options.communicationTone, options.model)
    )
  }

  /**
   * Layer 4: Workspace project context (CLAUDE.md — project sections only).
   * Progressive by mode: build slim, plan ultra-light.
   */
  private appendProjectContextLayer(
    layers: string[],
    options: PromptBuildOptions,
    budgetTier: BudgetTier
  ): void {
    if (!options.workspacePath) return

    const projectContext = this.readProjectContext(
      options.workspacePath,
      options.mode,
      budgetTier
    )
    if (projectContext) {
      layers.push(`## Workspace Project Context (from CLAUDE.md)\n\n${sanitizePromptInput(projectContext)}`)
    }
  }

  // ── Private layer builders ──

  private getRolePrompt(
    role: PromptRole,
    mode: ConversationMode,
    tone?: CommunicationTone,
    model?: string
  ): string {
    // Read from DB (user-editable). Falls back to defaults if DB is empty.
    const dbPrompt = coreAgentPromptRepository.findByRoleAndMode(role, mode)
    if (dbPrompt) {
      // Apply tone overlay when user has a non-default tone selected.
      // If the DB prompt has a ## Style section, replace it inline to avoid
      // duplicate/conflicting style guidance. Otherwise append as a new section.
      if (tone && tone !== 'default') {
        const directive = TONE_STYLE_DIRECTIVES[tone]
        const styleSectionRe = /## Style\n[\s\S]*?(?=\n##|\n$)/
        if (styleSectionRe.test(dbPrompt.promptText)) {
          return dbPrompt.promptText.replace(styleSectionRe, `## Style\n${directive}`)
        }
        return dbPrompt.promptText + `\n\n## Communication Tone Override\n${directive}`
      }
      return dbPrompt.promptText
    }
    // Fallback to defaults — build identity prompt with tone baked in
    if (role === 'specialist') {
      const verbosity = resolvePromptVerbosity(model ?? '')
      const identity =
        verbosity === 'lean'
          ? buildSpecialistIdentityPromptLean(tone)
          : buildSpecialistIdentityPrompt(tone)
      // Lean mode: skip UNIFIED_MODE_SECTION since per-message <mode-context>
      // block already provides detailed mode instructions every turn.
      // Saves ~80 tokens from the system prompt.
      //
      // CONTRACT: Lean mode REQUIRES the caller (ProjectSpecialistRoleAdapter.buildEffectiveMessage)
      // to inject a <mode-context> block in every user message. Without it, the model
      // has NO mode instructions. If adding a new lean-mode caller, ensure it also
      // injects MODE_CONTEXT_SECTIONS_LEAN per message.
      if (verbosity === 'lean') return identity
      return UNIFIED_MODE_SECTION + '\n' + identity
    }
    return DEFAULT_PROMPTS[role]?.[mode] ?? ''
  }

  /**
   * Public accessor for skill composition — used by external adapters
   * (e.g., ProjectSpecialistRoleAdapter) that need direct skill assembly.
   */
  get skills(): SkillPromptComposer {
    return this.skillComposer
  }

  /**
   * Read workspace CLAUDE.md as project context for the generalist.
   *
   * Strategy 1: Progressive CLAUDE.md injection
   * - Build mode: slim core project sections only
   * - Plan mode: ultra-light context for investigation/Q&A
   */
  private readProjectContext(
    workspacePath: string,
    mode: ConversationMode = 'build',
    budgetTier: BudgetTier = 'standard'
  ): string {
    // Strategy 5: Minimal-budget generalist (turn 5+) already has CLAUDE.md in history —
    // send a micro-summary instead of re-extracting sections (~600 tokens saved per turn)
    if (budgetTier === 'minimal') {
      return 'Tech: Electron 42, React 19, TS 5.9, Tailwind 4, SQLite, Zustand 5. See CLAUDE.md in prior context for conventions/structure.'
    }

    try {
      const claudeMdPath = join(workspacePath, 'CLAUDE.md')

      // Strategy G: Check in-memory cache first — only re-read from disk when mtime changes.
      // Eliminates readFileSync() on every generalist turn (saves ~1-5ms disk I/O per turn).
      const cached = this.claudeMdCache.get(claudeMdPath)
      let content: string

      try {
        const stat = statSync(claudeMdPath)
        if (cached && cached.mtimeMs === stat.mtimeMs) {
          content = cached.content
        } else {
          content = readFileSync(claudeMdPath, 'utf-8')
          this.claudeMdCache.set(claudeMdPath, { content, mtimeMs: stat.mtimeMs })
          if (cached) {
            log.info(`[PIPELINE:claude-md-cache] Invalidated — file changed (${claudeMdPath})`)
          }
        }
      } catch {
        // stat failed — fall back to direct read
        content = readFileSync(claudeMdPath, 'utf-8')
      }

      return this.extractGeneralistClaudeMdSections(content, mode)
    } catch {
      return ''
    }
  }

  /**
   * Extracts a slim CLAUDE.md slice for generalist context.
   * - Build mode: broader project context for execution planning.
   * - Plan mode: ultra-light context for investigation/Q&A.
   */
  private extractGeneralistClaudeMdSections(content: string, mode: ConversationMode): string {
    const essentialHeadings =
      mode === 'plan'
        ? ['tech stack', 'key commands', 'conventions', 'what not to do']
        : [
            'overview',
            'project structure',
            'tech stack',
            'key commands',
            'conventions',
            'what not to do',
            'error handling'
          ]

    const skipHeadings = [
      'skills',
      'available skills',
      'electron skill trigger',
      'deprecation notes',
      'electron documentation reference',
      'electron documentation',
      'architecture notes',
      'agents',
      'design system'
    ]

    const extracted = this.extractClaudeMdSections(content, essentialHeadings, skipHeadings, false)
    const profile = mode === 'plan' ? 'generalist-plan (ultra-light)' : 'generalist-build (slim)'
    log.info(
      `CLAUDE.md progressive injection: ${content.length} → ${extracted.length} chars for ${profile}`
    )
    return extracted
  }

  /**
   * Shared CLAUDE.md section extractor.
   */
  private extractClaudeMdSections(
    content: string,
    essentialHeadings: string[],
    skipHeadings: string[],
    keepUnmatchedSections: boolean
  ): string {
    const lines = content.split('\n')
    const result: string[] = []
    let currentSection = ''
    let isKeeping = true // Keep preamble (before first heading)

    for (const line of lines) {
      const headingMatch = line.match(/^##\s+(.+)$/)
      if (headingMatch) {
        currentSection = headingMatch[1].trim().toLowerCase()
        const isEssential = essentialHeadings.some((h) => currentSection.includes(h))
        const isSkipped = skipHeadings.some((h) => currentSection.includes(h))

        // Explicit keep > explicit skip > default behavior by profile
        isKeeping = isEssential || (!isSkipped && keepUnmatchedSections)
      }

      if (isKeeping) {
        result.push(line)
      }
    }

    return result.join('\n').trim()
  }

  // ── Local LLM Prompt Assembly ──

  /**
   * Build a condensed system prompt for local LLM providers.
   * Strips skills, reduces memory, keeps essential instructions.
   * Target: ~4K tokens for 32K models, ~8K for 128K+ models.
   *
   * When `contextTier` is provided and mode is 'plan', a focused plan-mode
   * directive is prepended (S5) that constrains the model to a strict
   * tool-budget and ordered workflow to prevent aimless exploration.
   */
  buildLocalPrompt(options: PromptBuildOptions & { contextTier?: ContextWindowTier }): string {
    const layers: string[] = []

    // Layer 0 (S5): Plan-focused directive for local LLMs — must come FIRST
    // so it anchors the model before any other content.
    if (options.mode === 'plan' && options.contextTier) {
      layers.push(this.buildLocalPlanDirective(options.contextTier))
    }

    // Layer 1: Condensed role identity (no skills, no persona)
    // Note: model is intentionally NOT threaded here — local LLMs are never Claude
    // models (they're Ollama IDs like qwen2.5-coder:32b), so resolvePromptVerbosity()
    // would always return 'full'. Local prompt compression uses contextTier instead.
    const rolePrompt = this.getRolePrompt(options.role, options.mode, options.communicationTone)
    const condensed = this.extractEssentialSections(rolePrompt)
    if (condensed) layers.push(condensed)

    // Layer 1.5: Baseline behavioral guidelines (always-on, condensed for local LLMs)
    const baselineSkills = this.skillComposer.buildBaselineSkillsLayer('minimal')
    if (baselineSkills) layers.push(baselineSkills)

    // Layer 2: Minimal project context (tech stack + key commands only)
    if (options.workspacePath) {
      const claudeMd = this.readProjectContext(
        options.workspacePath,
        options.mode,
        'minimal'
      )
      if (claudeMd) {
        layers.push(`## Project Context\n\n${claudeMd}`)
      }
    }

    return layers.join('\n\n---\n\n')
  }

  /**
   * S5: Plan-focused directive prompt for local LLMs.
   *
   * Constrains the model to a strict workflow with a hard tool budget to
   * prevent the aimless exploration that burns all turns on small contexts.
   * The directive is placed at the TOP of the system prompt so it anchors
   * the model's behavior before any role/project context.
   */
  buildLocalPlanDirective(tier: ContextWindowTier): string {
    const toolBudgets: Record<ContextWindowTier, number> = {
      small: 5,
      medium: 8,
      large: 15
    }
    const budget = toolBudgets[tier]

    return `## Plan Mode — Strict Workflow

You are in PLAN mode. Your job: produce a WRITTEN PLAN, not execute changes.

### Steps (follow IN ORDER):
1. PARSE the request — identify what the user wants (0 tools)
2. LOCATE files — use Glob/Grep/FindSymbol (2-3 calls max)
3. READ key sections — use Read with offset+limit (2-3 calls max)
4. EMIT THE PLAN — call **emit_plan** with your findings and proposed file changes.
   If emit_plan is unavailable, output a numbered list of specific file changes.

### Rules:
- Maximum ${budget} tool calls total. Then EMIT.
- After reading 2-3 files, you have enough context. STOP exploring.
- A partial plan is ALWAYS better than no plan.
- NEVER explore "just in case."

### Output Format:
Call **emit_plan** with type, title, and phases listing specific file changes.
Fallback (if emit_plan unavailable):
1. **\`path/to/file.tsx\`** — Description of change
2. **\`path/to/other.ts\`** — Description of change
`
  }

  /**
   * Extract identity + mode rules + conventions from a role prompt.
   * Strips: skills, design system, architecture deep-dives, etc.
   */
  private extractEssentialSections(prompt: string): string {
    const essentialHeaders = [
      'identity',
      'mode',
      'conventions',
      'key commands',
      'what not to do',
      'error handling'
    ]

    const sections = prompt.split(/^## /m)
    const kept = sections.filter((s) => {
      const header = s.split('\n')[0].trim().toLowerCase()
      return essentialHeaders.some((h) => header.startsWith(h))
    })

    return kept.map((s) => `## ${s}`).join('\n\n')
  }

  // ── Prompt Size Estimation (Strategy: prevent context overflow) ──

  /**
   * Estimate token count from character length.
   * Rule of thumb: ~4 characters per token for English text / code.
   * Returns a conservative (high) estimate.
   */
  static estimateTokens(text: string): number {
    return Math.ceil(text.length / 3.5) // Slightly conservative — 3.5 chars/token
  }

  /** Token budget thresholds per model tier */
  static readonly TOKEN_BUDGETS: Record<string, { warn: number; max: number }> = {
    haiku: { warn: 30_000, max: 50_000 },
    sonnet: { warn: 60_000, max: 100_000 },
    opus: { warn: 100_000, max: 180_000 }
  } as const

  /**
   * Check if a prompt exceeds safe size for the target model.
   * Returns warning/error info if the prompt is too large.
   */
  static checkPromptSize(
    systemPrompt: string,
    userPrompt: string,
    modelTier: string
  ): { ok: boolean; estimatedTokens: number; warning?: string } {
    const totalChars = systemPrompt.length + userPrompt.length
    const estimatedTokens = PromptBuilder.estimateTokens(systemPrompt + userPrompt)
    const budget = PromptBuilder.TOKEN_BUDGETS[modelTier] ?? PromptBuilder.TOKEN_BUDGETS.sonnet

    if (estimatedTokens > budget.max) {
      return {
        ok: false,
        estimatedTokens,
        warning: `Prompt exceeds ${modelTier} max budget: ~${estimatedTokens} tokens > ${budget.max} limit (${totalChars} chars). Context will be truncated by the model.`
      }
    }

    if (estimatedTokens > budget.warn) {
      return {
        ok: true,
        estimatedTokens,
        warning: `Prompt approaching ${modelTier} budget: ~${estimatedTokens} tokens > ${budget.warn} warning threshold (${totalChars} chars)`
      }
    }

    return { ok: true, estimatedTokens }
  }
}

/** Singleton instance */
export const promptBuilder = new PromptBuilder()

import { readFileSync, statSync } from 'node:fs'
import { join } from 'node:path'
import type { BudgetTier, Skill } from '../../shared/types'
import { promptBuilderLogger } from '../logger'
import { skillRepository } from '../db/repositories/skill.repository'
import { BASELINE_SKILL_FILENAMES } from '../../shared/constants'

const log = promptBuilderLogger

/**
 * Encapsulates all skill-related prompt composition logic.
 *
 * Extracted from PromptBuilder to reduce complexity and enable independent testing.
 * Handles tiered skill loading, relevance scoring, section extraction,
 * and baseline skill assembly with an mtime-based file cache.
 */
export class SkillPromptComposer {
  /**
   * Strategy O: In-memory skill file cache with mtime invalidation.
   * SKILL.md files rarely change during a session — cache them to eliminate
   * per-turn readFileSync() calls and truncation overhead.
   */
  private skillFileCache: Map<string, { content: string; mtimeMs: number }> = new Map()

  /**
   * Applies optional per-conversation skill overrides to the assigned skill list.
   * When no overrides are provided, preserves the original list.
   */
  filterAssignedSkills(skills: Skill[], skillOverrides?: string[]): Skill[] {
    if (!skillOverrides) return skills

    const overrideSet = new Set(
      skillOverrides.map((value) => value.trim().toLowerCase()).filter((value) => value.length > 0)
    )

    return skills.filter((skill) => {
      const id = skill.id.toLowerCase()
      const name = skill.name.toLowerCase()
      const filename = skill.filename.toLowerCase()
      return overrideSet.has(id) || overrideSet.has(name) || overrideSet.has(filename)
    })
  }

  /**
   * Build deduplicated skill content for a specialist.
   *
   * Strategy 3: Tiered skill loading — intelligently selects content:
   * - Tier 1 (core principles, first ~1000 chars) — always included
   * - Tier 2 (remaining content up to budget) — included for standard/full budgets
   * Budget per skill scales with tier: minimal=500, standard=2000, full=4000
   *
   * Strategy 8 (Selective Skill Loading): When multiple skills are assigned,
   * the most relevant skill (by keyword match against task context) gets the
   * full budget; remaining skills get a condensed summary (~200 chars).
   */
  buildSkillContent(
    skills: Skill[],
    budgetTier: BudgetTier = 'standard',
    taskContext?: string
  ): string {
    const activeSkills = skills.filter((s) => s.isActive)
    if (activeSkills.length === 0) return ''
    const normalizedTaskContext = taskContext?.trim().toLowerCase()
    if (normalizedTaskContext) {
      const hasRelevantSkill = activeSkills.some(
        (skill) => this.skillRelevanceScore(skill, normalizedTaskContext) > 0
      )
      if (!hasRelevantSkill) {
        log.info('Skipping skill content: no active skill matches task context relevance')
        return ''
      }
    }

    const baseBudget = budgetTier === 'minimal' ? 500 : budgetTier === 'full' ? 4000 : 2000
    const rankedSkills = this.rankSkillsByRelevance(activeSkills, normalizedTaskContext, budgetTier)
    const sections: string[] = []

    for (let i = 0; i < rankedSkills.length; i++) {
      const skill = rankedSkills[i]
      const isPrimary = i === 0
      // Strategy 6: Skip secondary skills entirely for non-full budget
      if (!isPrimary && budgetTier !== 'full') continue
      const budget = isPrimary ? baseBudget : Math.min(200, baseBudget)

      const selected = this.resolveSkillContent(skill, isPrimary, budgetTier, budget)
      if (selected) {
        sections.push(`## Skill: ${skill.name}\n${selected}`)
      }
    }

    return this.applySkillHardCap(sections, 4000)
  }

  /**
   * Build the always-on baseline skills layer.
   *
   * Reads SKILL.md files listed in BASELINE_SKILL_FILENAMES from .claude/skills/.
   * These are behavioral guidelines (not domain skills) injected into every
   * prompt path — specialist and local LLM.
   */
  buildBaselineSkillsLayer(budgetTier: BudgetTier = 'standard'): string {
    const sections: string[] = []
    const baseBudget = budgetTier === 'minimal' ? 2500 : budgetTier === 'full' ? 4000 : 2000

    for (const filename of BASELINE_SKILL_FILENAMES) {
      const filePath = join(this.getBaselineSkillsDir(), filename, 'SKILL.md')
      try {
        const content = this.readSkillFile(filePath)
        const trimmed =
          content.length > baseBudget
            ? content.substring(0, baseBudget) + '\n\n[... truncated]'
            : content
        sections.push(trimmed)
      } catch {
        log.warn(`Baseline skill not found: ${filePath}`)
      }
    }

    if (sections.length === 0) return ''
    return `## Coding Principles\n\n${sections.join('\n\n')}`
  }

  // ── Private helpers ──

  /**
   * Strategy 8: Rank skills by relevance when >1 skill and task context is available.
   * Returns the original array unmodified when selective loading isn't needed.
   */
  private rankSkillsByRelevance(
    skills: Skill[],
    taskContext: string | undefined,
    budgetTier: BudgetTier
  ): Skill[] {
    if (skills.length <= 1 || !taskContext || budgetTier === 'full') return skills
    return [...skills].sort((a, b) => {
      const scoreA = this.skillRelevanceScore(a, taskContext)
      const scoreB = this.skillRelevanceScore(b, taskContext)
      return scoreB - scoreA
    })
  }

  /**
   * Resolve content for a single skill through the 4-level cascade:
   * tier2+minimal → summary → tier2+standard → disk fallback.
   */
  private resolveSkillContent(
    skill: Skill,
    isPrimary: boolean,
    budgetTier: BudgetTier,
    budget: number
  ): string | null {
    try {
      // Try tier2_instructions for minimal budgets (fast path, no disk I/O)
      if (skill.tier2Instructions && budgetTier === 'minimal') {
        const selected = skill.tier2Instructions.substring(0, budget)
        log.info(
          `Skill "${skill.name}" using tier2 instructions (${selected.length} chars, budget: minimal)`
        )
        return selected
      }

      // Try pre-computed semantic summary (token-optimized, ~50-60% savings)
      const summaryTier = isPrimary ? budgetTier : 'minimal'
      const summary = skillRepository.getSummary(skill.id, summaryTier)
      if (summary) {
        log.info(
          `Skill "${skill.name}" using pre-computed ${summaryTier} summary (${summary.length} chars)`
        )
        return summary
      }

      // For standard budget with tier2: use tier2 + summary blend
      if (skill.tier2Instructions && budgetTier === 'standard') {
        const selected = skill.tier2Instructions.substring(0, budget)
        log.info(
          `Skill "${skill.name}" using tier2 instructions (${selected.length} chars, budget: standard)`
        )
        return selected
      }

      // Fallback: read from disk if no pre-computed data available
      const content = this.readSkillFile(skill.filePath)
      let selected: string
      if (content.length <= budget) {
        selected = content
      } else if (!isPrimary || budgetTier === 'minimal') {
        selected = content.substring(0, budget) + '\n\n[... see full skill file for details]'
      } else {
        selected = this.extractSkillSections(content, budget)
      }

      if (content.length > budget) {
        log.info(
          `Skill "${skill.name}" ${isPrimary ? 'trimmed' : 'condensed'} from ${content.length} to ~${budget} chars (budget: ${budgetTier}, fallback — no summary)`
        )
      }
      return selected
    } catch {
      log.warn(`Could not read skill file: ${skill.filePath}`)
      return null
    }
  }

  /**
   * Strategy 6: Apply 4K hard cap on total skill content.
   * Accumulates sections until the cap is reached, dropping the rest.
   */
  private applySkillHardCap(sections: string[], hardCap: number): string {
    const totalContent = sections.join('\n\n')
    if (totalContent.length <= hardCap) return totalContent

    let accumulated = ''
    const capped: string[] = []
    for (const section of sections) {
      if (accumulated.length + section.length + 2 > hardCap) break
      capped.push(section)
      accumulated += section + '\n\n'
    }
    log.info(
      `Skill content hard-capped: ${totalContent.length} → ${accumulated.length} chars (${hardCap} limit)`
    )
    return capped.join('\n\n')
  }

  /**
   * Strategy O: Read a skill file with in-memory caching and mtime invalidation.
   */
  private readSkillFile(filePath: string): string {
    const cached = this.skillFileCache.get(filePath)
    try {
      const stat = statSync(filePath)
      if (cached && cached.mtimeMs === stat.mtimeMs) {
        return cached.content
      }
      const content = readFileSync(filePath, 'utf-8')
      this.skillFileCache.set(filePath, { content, mtimeMs: stat.mtimeMs })
      return content
    } catch {
      const content = readFileSync(filePath, 'utf-8')
      return content
    }
  }

  /**
   * Scores a skill's relevance to the given task context by keyword matching.
   * Uses Tier 1 keywords (from structured tier1_json) for fast matching.
   */
  private skillRelevanceScore(skill: Skill, contextLower: string): number {
    let keywords: string[]

    if (skill.tier1Json) {
      try {
        const tier1 = JSON.parse(skill.tier1Json) as { keywords?: string[] }
        keywords = tier1.keywords ?? []
      } catch {
        keywords = []
      }
    } else {
      keywords = skill.name
        .toLowerCase()
        .replace(/[^a-z0-9\s-]/g, '')
        .split(/[\s-]+/)
        .filter((w) => w.length > 2)
    }

    return keywords.reduce((score, kw) => score + (contextLower.includes(kw) ? 1 : 0), 0)
  }

  /**
   * Extracts skill content intelligently by preserving complete markdown sections
   * up to the budget limit, rather than cutting mid-sentence.
   */
  private extractSkillSections(content: string, budget: number): string {
    const sectionRegex = /^## .+$/gm
    const sections: { start: number; header: string }[] = []
    let match: RegExpExecArray | null

    while ((match = sectionRegex.exec(content)) !== null) {
      sections.push({ start: match.index, header: match[0] })
    }

    if (sections.length === 0) {
      return content.substring(0, budget) + '\n\n[... truncated]'
    }

    let result = ''
    const preamble = content.substring(0, sections[0].start).trim()
    if (preamble) {
      result = preamble + '\n\n'
    }

    for (let i = 0; i < sections.length; i++) {
      const sectionEnd = i + 1 < sections.length ? sections[i + 1].start : content.length
      const sectionContent = content.substring(sections[i].start, sectionEnd)

      if (result.length + sectionContent.length <= budget) {
        result += sectionContent
      } else {
        const remaining = budget - result.length - 30
        if (remaining > 100) {
          result += sectionContent.substring(0, remaining) + '\n\n[... truncated]'
        } else {
          result += '\n\n[... additional sections omitted]'
        }
        break
      }
    }

    return result.trim()
  }

  /** Returns the .claude/skills/ directory path */
  private getBaselineSkillsDir(): string {
    try {
      // eslint-disable-next-line @typescript-eslint/no-require-imports -- defensive lazy load; electron may be unavailable in non-app contexts
      const { app } = require('electron')
      return app.isPackaged
        ? join(app.getPath('userData'), '.claude', 'skills')
        : join(process.cwd(), '.claude', 'skills')
    } catch {
      return join(process.cwd(), '.claude', 'skills')
    }
  }
}

/** Singleton instance */
export const skillPromptComposer = new SkillPromptComposer()

/**
 * SystemPromptCache — extracted cache for assembled system prompts.
 *
 * Pattern 7 centralization: the legacy prompt assembler and
 * ProjectSpecialistRoleAdapter maintained identical 5-field caches with
 * matching invalidation logic. This class provides a single implementation.
 *
 * Cache keys: mode, conversationId, tone, model.
 * Always rebuilds on turn 1 to pick up latest settings (CLAUDE.md, skills).
 */

import type { CommunicationTone, ConversationMode } from '../../shared/types'

export interface SystemPromptCacheKeys {
  mode: ConversationMode
  conversationId: string | null
  tone: CommunicationTone
  model: string | null
}

export class SystemPromptCache {
  private snapshot: string | null = null
  private keys: SystemPromptCacheKeys = {
    mode: 'plan',
    conversationId: null,
    tone: 'default',
    model: null
  }

  /**
   * Check if the cached prompt is still valid for the given turn.
   * Returns false on turn 1 (always rebuild) or when any key changed.
   */
  isValid(currentKeys: SystemPromptCacheKeys, turnCount: number): boolean {
    return (
      turnCount > 1 &&
      this.snapshot !== null &&
      this.keys.mode === currentKeys.mode &&
      this.keys.conversationId === currentKeys.conversationId &&
      this.keys.tone === currentKeys.tone &&
      this.keys.model === currentKeys.model
    )
  }

  /** Store a new prompt and its cache keys. */
  set(prompt: string, keys: SystemPromptCacheKeys): void {
    this.snapshot = prompt
    this.keys = { ...keys }
  }

  /** Get the cached prompt (null if not cached). */
  get(): string | null {
    return this.snapshot
  }

  /** Invalidate the cache — forces rebuild on next turn. */
  invalidate(): void {
    this.snapshot = null
    this.keys = {
      mode: 'plan',
      conversationId: null,
      tone: 'default',
      model: null
    }
  }
}

/**
 * BaseRoleAdapter — abstract base class providing centralized default implementations
 * for the AgentRoleAdapter interface.
 *
 * ONE change → ONE place → EVERY adapter inherits.
 *
 * Subclasses only override what differs:
 *   - `buildPrompts()` (always — identity/prompt differs per role)
 *   - `getMcpStrategy()` (if not 'full')
 *   - `resolveWorkspaceId()` (for workspace-scoped adapters)
 *   - `emitDetectedIntents()` (override with no-op for audit/MPA)
 *
 * The interface `AgentRoleAdapter` remains the public contract consumed by
 * AgentSessionService. This base class is the default implementation path.
 */

import type {
  AgentIntent,
  AgentRole,
  CommunicationTone,
  LLMProvider,
  ModelAction
} from '../../../shared/types'
import { EXTERNAL_MCP_INTEGRATIONS, LOCAL_MCP_INTEGRATIONS } from '../../../shared/constants'
import type {
  AdapterIntentContext,
  AdapterMcpContext,
  AdapterMcpResult,
  AdapterPromptContext,
  AdapterPromptResult,
  AdapterSessionLifecycleCtx,
  AgentRoleAdapter,
  AgentSessionEventName
} from '../agent-session.types'
import type { ControlActionCallbacks } from '../control-actions.tool'
import { intentDetector } from '../intent-detector'
import {
  conversationRepository,
  workspaceRepository
} from '../../db/repositories'
import { githubService } from '../github.service'
import { chatAgentLogger } from '../../logger'
import { buildWorkspaceMcpConfig } from '../workspace-mcp-config'
import { buildReadOnlyToolConfig, buildNoToolsConfig } from './evaluation-mcp-config'
import { modelConfigService } from '../model-config.service'
import { TOOL_PRIORITY_DIRECTIVE } from '../default-prompts'
import { appendMcpToolGuidance, type PromptFeatureFlags } from '../prompt-assembly-helpers'

// ── Types ────────────────────────────────────────────────────────────────

export type McpStrategy = 'full' | 'readonly' | 'none' | 'custom'

// ── Base Class ───────────────────────────────────────────────────────────

export abstract class BaseRoleAdapter implements AgentRoleAdapter {
  abstract readonly role: AgentRole
  abstract readonly agentId: string
  interactionTimeoutMs?: number

  protected readonly log = chatAgentLogger

  // ── Capability flags ───────────────────────────────────────────────
  // Adapters that support the plan-card recovery flow (emit_plan re-issue
  // after a blocked Write/Edit) set this to true.  Blueprint / grill /
  // audit / council adapters inherit false — recovery never fires for them.

  readonly supportsEmitPlanRecovery: boolean = false

  // ── Feature flags (shared across all adapters) ──────────────────────

  protected repomapEnabled = true
  protected semanticSearchEnabled = true
  protected githubConfigured = false
  protected codeAnalysisEnabled = true
  protected processManagerEnabled = true

  // ── Strategy Λ: Locked MCP flags ──────────────────────────────────
  // Snapshotted at onSessionStart() — tool set stays stable for the entire
  // session, ensuring Claude's prompt cache prefix is never broken by a
  // mid-session settings toggle.

  private lockedFlags: {
    repomapEnabled: boolean
    semanticSearchEnabled: boolean
    githubConfigured: boolean
  } | null = null

  // ── Communication tone cache ──────────────────────────────────────

  private cachedTone: CommunicationTone | null = null
  private cachedToneConversationId: string | null = null

  // ── Lifecycle (overridable, sensible defaults) ──────────────────────

  async onSessionStart(_ctx: AdapterSessionLifecycleCtx): Promise<void> {
    /* no-op — subclasses override */
  }

  refreshFeatureFlags(_ctx: AdapterSessionLifecycleCtx): void {
    /* no-op — subclasses override */
  }

  onConversationSwitch(_conversationId: string): void {
    /* no-op — subclasses override */
  }

  onSessionStop(): void {
    /* no-op — subclasses override */
  }

  // ── Prompts (MUST be implemented per-adapter — identity differs) ────

  abstract buildPrompts(ctx: AdapterPromptContext): AdapterPromptResult

  // ── MCP Config (centralized, strategy-driven) ──────────────────────

  /** Override to change MCP strategy. Default: 'full'. */
  protected getMcpStrategy(_ctx?: AdapterMcpContext): McpStrategy {
    return 'full'
  }

  buildMcpConfig(ctx: AdapterMcpContext): AdapterMcpResult {
    switch (this.getMcpStrategy(ctx)) {
      case 'full':
        return this.buildFullMcpConfig(ctx)
      case 'readonly':
        return this.buildReadOnlyMcpConfig(ctx)
      case 'none':
        return buildNoToolsConfig()
      case 'custom':
        return this.buildCustomMcpConfig(ctx)
    }
  }

  /**
   * Full MCP config — shared by all specialist adapters.
   * Handles: locked flags, external MCP resolution, local MCP overrides.
   */
  protected buildFullMcpConfig(ctx: AdapterMcpContext): AdapterMcpResult {
    const baseMcpFlags = this.getLockedMcpFlags()

    // Resolve external MCP active states (per-conversation toggling)
    const externalMcpActive = this.resolveExternalMcpActive(ctx.workspaceId, ctx.conversationId)

    // Resolve per-chat local MCP active state from conversation overrides
    const localMcpActive = this.resolveLocalMcpActive(ctx.conversationId)

    const result = buildWorkspaceMcpConfig({
      mode: ctx.mode,
      workspacePath: ctx.workspacePath,
      workspaceId: ctx.workspaceId,
      conversationId: ctx.conversationId,
      featureFlags: { ...baseMcpFlags, externalMcpActive, localMcpActive },
      controlCallbacks: ctx.controlCallbacks,
      isLocalProvider: modelConfigService.isLocalProvider(ctx.workspacePath),
      contextTier: ctx.contextTier
    })

    // Propagate code-analysis availability to prompt guidance gating
    this.codeAnalysisEnabled = result.codeAnalysisEnabled
    // Process manager: excluded in plan mode (read-only)
    this.processManagerEnabled = ctx.mode !== 'plan'

    return result
  }

  /**
   * Read-only MCP config — shared by Grill, Council, Audit.
   * Override `getIncludeGitContext()` for local LLM gating.
   */
  protected buildReadOnlyMcpConfig(ctx: AdapterMcpContext): AdapterMcpResult {
    return buildReadOnlyToolConfig({
      repomapEnabled: this.repomapEnabled,
      semanticSearchEnabled: this.semanticSearchEnabled,
      hasWorkspace: !!ctx.workspaceId,
      includeGitContext: this.getIncludeGitContext()
    })
  }

  /** Override for MPA or other custom tool lists. */
  protected buildCustomMcpConfig(_ctx: AdapterMcpContext): AdapterMcpResult {
    return buildNoToolsConfig()
  }

  /** Whether to include git-context tools. Default: true. Override for local LLMs. */
  protected getIncludeGitContext(): boolean {
    return true
  }

  // ── Control Callbacks (centralized, parameterized) ─────────────────

  buildControlCallbacks(_params: {
    conversationId: string | null
    emit: (event: AgentSessionEventName, payload: unknown) => void
    getAccumulatedText: () => string
  }): ControlActionCallbacks {
    return {
      onPlan: () => {
        /* session wraps + emits */
      },
      onAskUser: () => {
        /* session wraps + emits */
      }
    }
  }

  /**
   * Override per adapter: each specialist adapter determines its workspace binding.
   * Returns null for adapters without workspace binding.
   */
  protected resolveWorkspaceId(): string | null {
    return null
  }

  // ── Intent Detection (universal — identical in 6 adapters) ─────────

  emitDetectedIntents(ctx: AdapterIntentContext): void {
    const detectedIntents = intentDetector.detectAll(
      ctx.accumulatedText,
      ctx.controlToolState,
      ctx.mode
    )

    for (const intent of detectedIntents) {
      ctx.emit('intent', intent)
    }

    if (detectedIntents.length === 0) {
      this.log.info(`[PIPELINE:response-path] no-action textLen=${ctx.accumulatedText.length}`)
      ctx.emit('intent', {
        type: 'response',
        content: ctx.accumulatedText
      } as AgentIntent)
    }
  }

  // ── Shared Prompt Helpers ──────────────────────────────────────────

  /**
   * Append Tool Priority + MCP guidance to a base prompt. Single call site.
   * Ensures `## Tool Priority` is present for all tool-equipped adapters.
   */
  protected appendToolGuidance(basePrompt: string, turnCount: number, model?: string): string {
    const flags = this.buildPromptFeatureFlags()
    // Tool Priority is always injected for adapters with tools
    const withPriority =
      this.getMcpStrategy() !== 'none' && !basePrompt.includes('## Tool Priority')
        ? basePrompt + '\n' + TOOL_PRIORITY_DIRECTIVE
        : basePrompt
    return appendMcpToolGuidance(withPriority, turnCount, flags, model)
  }

  /**
   * Build feature flags from current state — ONE place, not 7 copy-pastes.
   * Override in subclasses that need variations (e.g., includeGitContext).
   */
  protected buildPromptFeatureFlags(): PromptFeatureFlags {
    return {
      repomapEnabled: this.repomapEnabled,
      semanticSearchEnabled: this.semanticSearchEnabled,
      githubConfigured: this.githubConfigured,
      includeGitContext: this.getIncludeGitContext(),
      includeCheckpoint: false,
      codeAnalysisEnabled: this.codeAnalysisEnabled,
      processManagerEnabled: this.processManagerEnabled
    }
  }

  // ── Centralized Helpers (Patterns 1-7) ─────────────────────────────

  /**
   * Pattern 1: Resolve the model for prompt verbosity gating.
   * Returns undefined for local LLM providers (local models don't use
   * prompt verbosity — they get condensed prompts unconditionally).
   */
  protected resolveModel(
    workspacePath: string,
    action: ModelAction
  ): string | undefined {
    const isLocal = modelConfigService.isLocalProvider(workspacePath)
    return isLocal ? undefined : modelConfigService.getModel(workspacePath, action)
  }

  /**
   * Pattern 2: Read workspace settings for repomap / semantic-search / github flags.
   * Called by onSessionStart() and refreshFeatureFlags() in every adapter.
   */
  protected refreshWorkspaceFeatureFlags(workspaceId: string | null, workspacePath?: string): void {
    if (!workspaceId) return
    try {
      const settings = workspaceRepository.getSettings(workspaceId)
      this.repomapEnabled = settings.repomapEnabled !== false
      this.semanticSearchEnabled = settings.semanticSearchEnabled !== false
      if (workspacePath) {
        this.githubConfigured = githubService.isConfigured(workspaceId)
      }
    } catch {
      /* non-fatal — keep defaults */
    }
  }

  /**
   * Pattern 3: Extend interaction timeout for local LLM providers.
   * Local models are much slower but still productive.
   */
  protected applyLocalLlmTimeout(llmProvider: LLMProvider, extendedMinutes = 45): void {
    if (llmProvider === 'local-llm') {
      this.interactionTimeoutMs = extendedMinutes * 60_000
      this.log.info(`[${this.role}] Using extended timeout (${extendedMinutes} min) for local LLM`)
    }
  }

  /**
   * Pattern 5: Resolve the effective communication tone.
   * Resolution chain: conversation override → workspace default → 'default'.
   * Cached per conversation to avoid DB queries on every turn.
   */
  protected resolveCommunicationTone(
    conversationId: string | null,
    workspaceId: string | null,
    turnCount: number
  ): CommunicationTone {
    if (this.cachedTone && this.cachedToneConversationId === conversationId && turnCount > 1) {
      return this.cachedTone
    }
    let tone: CommunicationTone = 'default'
    try {
      if (conversationId) {
        const conv = conversationRepository.findById(conversationId)
        if (conv?.communicationTone) {
          tone = conv.communicationTone
        }
      }
      if (tone === 'default' && workspaceId) {
        const settings = workspaceRepository.getSettings(workspaceId)
        const wsTone = settings.communicationTone as CommunicationTone | undefined
        if (wsTone && wsTone !== 'default') tone = wsTone
      }
    } catch {
      /* non-fatal — fallback to default tone */
    }
    this.cachedTone = tone
    this.cachedToneConversationId = conversationId
    return tone
  }

  /** Invalidate the cached communication tone (on conversation switch / session stop). */
  protected invalidateToneCache(): void {
    this.cachedTone = null
    this.cachedToneConversationId = null
  }

  /**
   * Pattern 6 — Strategy Λ: Lock MCP flags at session start.
   * Tool set stays stable for the entire session, ensuring Claude's prompt
   * cache prefix is never broken by a mid-session settings toggle.
   */
  protected lockMcpFlags(): void {
    this.lockedFlags = {
      repomapEnabled: this.repomapEnabled,
      semanticSearchEnabled: this.semanticSearchEnabled,
      githubConfigured: this.githubConfigured
    }
    this.log.info(
      `[adapter:lock-mcp-flags] repomap=${this.lockedFlags.repomapEnabled} semantic=${this.lockedFlags.semanticSearchEnabled} github=${this.lockedFlags.githubConfigured}`
    )
  }

  /** Strategy Λ: Unlock MCP flags (on session stop). */
  protected unlockMcpFlags(): void {
    this.lockedFlags = null
  }

  /**
   * Get the locked MCP flags (Strategy Λ). Returns the locked snapshot if
   * available, otherwise falls back to live feature flags.
   */
  protected getLockedMcpFlags(): {
    repomapEnabled: boolean
    semanticSearchEnabled: boolean
    githubConfigured: boolean
  } {
    return (
      this.lockedFlags ?? {
        repomapEnabled: this.repomapEnabled,
        semanticSearchEnabled: this.semanticSearchEnabled,
        githubConfigured: this.githubConfigured
      }
    )
  }

  /**
   * Resolve which external MCPs are active for this chat.
   * Used by both buildPrompts (prompt guidance injection) and buildMcpConfig (tool mounting).
   */
  protected resolveExternalMcpActive(
    workspaceId: string | null,
    conversationId: string | null
  ): Record<string, boolean> {
    const result: Record<string, boolean> = {}
    try {
      const wsSettings = workspaceId ? workspaceRepository.getSettings(workspaceId) : {}
      const conv = conversationId ? conversationRepository.findById(conversationId) : null
      const chatOverrides = conv?.mcpOverrides ?? {}

      this.log.info(
        `[adapter:resolve-external-mcp] workspaceId=${workspaceId} conversationId=${conversationId} ` +
          `wsFound=${!!workspaceId} wsSettingsKeys=${Object.keys(wsSettings)
            .filter((k) => k.includes('Available'))
            .join(',')} ` +
          `convFound=${!!conv} chatOverrides=${JSON.stringify(chatOverrides)}`
      )

      for (const integration of EXTERNAL_MCP_INTEGRATIONS) {
        const wsAvailable = !!wsSettings[`${integration.id}Available`]
        const chatActive = !!chatOverrides[integration.id]
        result[integration.id] = wsAvailable && chatActive
        this.log.info(
          `[adapter:resolve-external-mcp] ${integration.id}: wsAvailable=${wsAvailable} chatActive=${chatActive} → mounted=${result[integration.id]}`
        )
      }
    } catch (err) {
      this.log.error('[adapter:external-mcp] Failed to resolve MCP state:', err)
    }
    return result
  }

  /**
   * Resolve per-chat local MCP active state from conversation overrides.
   */
  protected resolveLocalMcpActive(conversationId: string | null): Record<string, boolean> {
    const localMcpActive: Record<string, boolean> = {}
    try {
      const conv = conversationId ? conversationRepository.findById(conversationId) : null
      const chatOverrides = conv?.mcpOverrides ?? {}
      for (const lm of LOCAL_MCP_INTEGRATIONS) {
        localMcpActive[lm.id] = chatOverrides[lm.id] !== false
      }
    } catch (err) {
      this.log.error('[adapter:local-mcp] Failed to resolve local MCP overrides:', err)
    }
    return localMcpActive
  }
}

import { Octokit } from '@octokit/rest'
import { safeStorage } from 'electron'
import simpleGit from 'simple-git'
import { workspaceRepository } from '../db/repositories'
import log from 'electron-log'
import type { GitHubTokenType } from '../../shared/types'

const logger = log.scope('GitHub')

// ── Token type detection ──────────────────────────────────────────

function detectTokenType(token: string): GitHubTokenType {
  if (token.startsWith('ghp_')) return 'classic'
  if (token.startsWith('github_pat_')) return 'fine-grained'
  return 'unknown'
}

export class GitHubService {
  /**
   * Validate a GitHub PAT: check it authenticates and detect its type.
   * Classic tokens return scopes via x-oauth-scopes header.
   * Fine-grained tokens return an empty header — scopes will be [].
   */
  async validateToken(
    token: string
  ): Promise<{ valid: boolean; login: string; scopes: string[]; tokenType: GitHubTokenType }> {
    const tokenType = detectTokenType(token)
    try {
      const octokit = new Octokit({ auth: token })
      const response = await octokit.rest.users.getAuthenticated()
      const rawScopes = response.headers['x-oauth-scopes'] ?? ''
      const scopes = rawScopes ? rawScopes.split(',').map((s) => s.trim()) : []
      return { valid: true, login: response.data.login, scopes, tokenType }
    } catch (e) {
      logger.debug('[GitHub] Token validation failed:', e)
      return { valid: false, login: '', scopes: [], tokenType }
    }
  }

  /**
   * Validate, encrypt, and persist a GitHub PAT for a workspace.
   * Classic tokens are validated via x-oauth-scopes header (must include "repo").
   * Fine-grained tokens are validated by probing the workspace repo's API endpoints.
   * Token is encrypted using Electron safeStorage (OS keychain) then stored as base64 in settingsJson.
   */
  async saveToken(
    workspaceId: string,
    token: string
  ): Promise<{ login: string; tokenType: GitHubTokenType }> {
    const result = await this.validateToken(token)
    if (!result.valid) {
      throw new Error('Invalid GitHub token')
    }

    if (result.tokenType === 'classic') {
      if (!result.scopes.includes('repo')) {
        throw new Error(
          'Token missing required "repo" scope. Generate a classic token with the "repo" scope.'
        )
      }
    } else if (result.tokenType === 'fine-grained') {
      await this.probeFineGrainedPermissions(workspaceId, token)
    } else {
      // Unknown prefix — allow if authenticated, log a warning
      logger.warn('Unknown token prefix format — skipping scope validation')
    }

    // Encrypt and store
    const encrypted = safeStorage.encryptString(token)
    const base64 = encrypted.toString('base64')

    const settings = workspaceRepository.getSettings(workspaceId)
    settings.githubTokenEncrypted = base64
    settings.githubLogin = result.login
    settings.githubTokenType = result.tokenType
    workspaceRepository.updateSettings(workspaceId, settings)

    logger.info(
      `GitHub ${result.tokenType} token saved for workspace ${workspaceId} (user: ${result.login})`
    )
    return { login: result.login, tokenType: result.tokenType }
  }

  /**
   * Get the GitHub connection status for a workspace.
   */
  getStatus(workspaceId: string): {
    configured: boolean
    login?: string
    tokenType?: GitHubTokenType
  } {
    const settings = workspaceRepository.getSettings(workspaceId)
    if (!settings.githubTokenEncrypted) {
      return { configured: false }
    }
    return {
      configured: true,
      login: settings.githubLogin as string | undefined,
      tokenType: (settings.githubTokenType as GitHubTokenType | undefined) ?? 'classic'
    }
  }

  /**
   * Remove stored GitHub token for a workspace.
   */
  removeToken(workspaceId: string): void {
    const settings = workspaceRepository.getSettings(workspaceId)
    delete settings.githubTokenEncrypted
    delete settings.githubLogin
    delete settings.githubTokenType
    workspaceRepository.updateSettings(workspaceId, settings)
    logger.info(`GitHub token removed for workspace ${workspaceId}`)
  }

  /**
   * Check whether a workspace has a GitHub token configured.
   */
  isConfigured(workspaceId: string): boolean {
    const settings = workspaceRepository.getSettings(workspaceId)
    return !!settings.githubTokenEncrypted
  }

  /**
   * Create a pull request on GitHub.
   */
  async createPullRequest(params: {
    workspaceId: string
    repoPath: string
    head: string
    base: string
    title: string
    body: string
  }): Promise<{ prUrl: string; prNumber: number }> {
    const octokit = this.getOctokit(params.workspaceId)
    const { owner, repo } = await this.parseRemoteUrl(params.repoPath)

    const response = await octokit.rest.pulls.create({
      owner,
      repo,
      head: params.head,
      base: params.base,
      title: params.title,
      body: params.body
    })

    logger.info(`PR #${response.data.number} created: ${response.data.html_url}`)
    return { prUrl: response.data.html_url, prNumber: response.data.number }
  }

  /**
   * Get the status of a pull request (open, closed, merged).
   */
  async getPullRequestStatus(
    workspaceId: string,
    repoPath: string,
    prNumber: number
  ): Promise<string> {
    const octokit = this.getOctokit(workspaceId)
    const { owner, repo } = await this.parseRemoteUrl(repoPath)

    const response = await octokit.rest.pulls.get({ owner, repo, pull_number: prNumber })
    if (response.data.merged) return 'merged'
    return response.data.state // 'open' | 'closed'
  }

  /**
   * Delete a remote branch on GitHub.
   */
  async deleteRemoteBranch(workspaceId: string, repoPath: string, branch: string): Promise<void> {
    const octokit = this.getOctokit(workspaceId)
    const { owner, repo } = await this.parseRemoteUrl(repoPath)

    try {
      await octokit.rest.git.deleteRef({ owner, repo, ref: `heads/${branch}` })
      logger.info(`Deleted remote branch ${branch} from ${owner}/${repo}`)
    } catch (e) {
      logger.warn(`Failed to delete remote branch ${branch}:`, e)
    }
  }

  /**
   * List review comments on a pull request.
   */
  async listPullRequestComments(
    workspaceId: string,
    repoPath: string,
    prNumber: number,
    perPage: number = 10
  ): Promise<
    Array<{
      id: number
      author: string
      body: string
      path: string
      line: number | null
      createdAt: string
    }>
  > {
    const octokit = this.getOctokit(workspaceId)
    const { owner, repo } = await this.parseRemoteUrl(repoPath)

    const response = await octokit.rest.pulls.listReviewComments({
      owner,
      repo,
      pull_number: prNumber,
      per_page: perPage,
      sort: 'created',
      direction: 'desc'
    })

    return response.data.map((c) => ({
      id: c.id,
      author: c.user?.login ?? 'unknown',
      body: c.body.slice(0, 500),
      path: c.path,
      line: c.line ?? null,
      createdAt: c.created_at
    }))
  }

  /**
   * List issues for the repository.
   */
  async listIssues(
    workspaceId: string,
    repoPath: string,
    opts: { state?: 'open' | 'closed' | 'all'; perPage?: number; labels?: string } = {}
  ): Promise<
    Array<{
      number: number
      title: string
      author: string
      state: string
      labels: string[]
      createdAt: string
      body: string | null
    }>
  > {
    const octokit = this.getOctokit(workspaceId)
    const { owner, repo } = await this.parseRemoteUrl(repoPath)

    type ListForRepoParams = Parameters<typeof octokit.rest.issues.listForRepo>[0]
    const params: ListForRepoParams = {
      owner,
      repo,
      state: opts.state ?? 'open',
      per_page: opts.perPage ?? 10,
      sort: 'created',
      direction: 'desc'
    }
    if (opts.labels) params.labels = opts.labels

    const response = await octokit.rest.issues.listForRepo(params)

    // Filter out pull requests (GitHub API returns PRs as issues too)
    return response.data
      .filter((i) => !i.pull_request)
      .map((i) => ({
        number: i.number,
        title: i.title,
        author: i.user?.login ?? 'unknown',
        state: i.state ?? 'unknown',
        labels: (i.labels ?? []).map((l) => (typeof l === 'string' ? l : (l.name ?? ''))),
        createdAt: i.created_at,
        body: i.body ? i.body.slice(0, 300) : null
      }))
  }

  /**
   * Probe the workspace repo to verify a fine-grained token has the required permissions.
   * Fine-grained PATs don't expose their permissions via headers, so we test
   * lightweight read-only API calls against the actual repo.
   * Skipped when the workspace has no remote configured yet.
   */
  private async probeFineGrainedPermissions(workspaceId: string, token: string): Promise<void> {
    const workspace = workspaceRepository.findById(workspaceId)
    if (!workspace?.repoPath) return

    let owner: string, repo: string
    try {
      const parsed = await this.parseRemoteUrl(workspace.repoPath)
      owner = parsed.owner
      repo = parsed.repo
    } catch {
      // No remote configured yet — can't probe, accept the token
      logger.info('No remote configured — skipping fine-grained permission probe')
      return
    }

    const octokit = new Octokit({ auth: token })

    // Probe: Can we read the repo? (Metadata + Contents)
    try {
      await octokit.rest.repos.get({ owner, repo })
    } catch (e: unknown) {
      const status = (e as { status?: number }).status
      if (status === 403 || status === 404) {
        throw new Error(
          `Token cannot access ${owner}/${repo}. Ensure the fine-grained token grants repository access for this repo.`
        )
      }
      throw e
    }

    // Probe: Can we list PRs? (Pull requests: Read)
    try {
      await octokit.rest.pulls.list({ owner, repo, per_page: 1 })
    } catch (e: unknown) {
      const status = (e as { status?: number }).status
      if (status === 403) {
        throw new Error(
          'Token missing "Pull requests: Read" permission. Update your fine-grained token permissions.'
        )
      }
    }

    // Probe: Can we list issues? (Issues: Read)
    try {
      await octokit.rest.issues.listForRepo({ owner, repo, per_page: 1 })
    } catch (e: unknown) {
      const status = (e as { status?: number }).status
      if (status === 403) {
        throw new Error(
          'Token missing "Issues: Read" permission. Update your fine-grained token permissions.'
        )
      }
    }

    // Note: Write permissions (PR create, branch delete) are not probed to avoid side effects.
    // Those will surface clear errors from the GitHub API at usage time.
  }

  /**
   * Get an authenticated Octokit instance for a workspace.
   */
  private getOctokit(workspaceId: string): Octokit {
    const settings = workspaceRepository.getSettings(workspaceId)
    const encrypted = settings.githubTokenEncrypted as string | undefined
    if (!encrypted) {
      throw new Error('GitHub token not configured for this workspace')
    }

    const buffer = Buffer.from(encrypted, 'base64')
    const token = safeStorage.decryptString(buffer)
    return new Octokit({ auth: token })
  }

  /**
   * Parse owner/repo from the git remote URL.
   */
  private async parseRemoteUrl(repoPath: string): Promise<{ owner: string; repo: string }> {
    const git = simpleGit(repoPath)
    const remotes = await git.getRemotes(true)
    const origin = remotes.find((r) => r.name === 'origin')
    if (!origin?.refs?.fetch) {
      throw new Error('No origin remote configured')
    }

    const url = origin.refs.fetch
    // Handle HTTPS: https://github.com/owner/repo.git
    const httpsMatch = url.match(/github\.com\/([^/]+)\/([^/.]+)/)
    if (httpsMatch) {
      return { owner: httpsMatch[1], repo: httpsMatch[2] }
    }

    // Handle SSH: git@github.com:owner/repo.git
    const sshMatch = url.match(/github\.com:([^/]+)\/([^/.]+)/)
    if (sshMatch) {
      return { owner: sshMatch[1], repo: sshMatch[2] }
    }

    throw new Error(`Cannot parse GitHub owner/repo from remote URL: ${url}`)
  }
}

export const githubService = new GitHubService()

