export interface McpConfigResult {
  mcpServers?: Record<string, McpServerConfig>
  allowedTools?: string[]
  disallowedTools: string[]
  /** Whether code-analysis tools are available — drives prompt guidance gating */
  codeAnalysisEnabled: boolean
}

/**
 * Check whether a local MCP server is enabled for this chat.
 * Missing key → enabled (backward-compatible default).
 */
function isLocalMcpEnabled(
  serverId: string,
  localMcpActive: Record<string, boolean> | undefined
): boolean {
  if (!localMcpActive) return true
  return localMcpActive[serverId] !== false
}

/**
 * Resolve a stdio command to an absolute path.
 * Checks known install paths first (handles packaged macOS apps where
 * GUI PATH is minimal). Falls back to the bare command name for PATH lookup.
 */
function resolveStdioCommand(command: string, knownPaths?: readonly string[]): string {
  if (knownPaths) {
    for (const p of knownPaths) {
      const resolved = p.replace(/^~/, homedir())
      const found = existsSync(resolved)
      chatAgentLogger.info(
        `[mcp:resolve-command] Checking ${resolved} → ${found ? 'EXISTS' : 'NOT FOUND'}`
      )
      if (found) return resolved
    }
  }
  // SVC-04: In packaged apps, don't fall back to bare command — the minimal
  // GUI PATH (/usr/bin:/bin:/usr/sbin:/sbin) could resolve a trojan binary.
  if (app.isPackaged) {
    chatAgentLogger.error(
      `[mcp:resolve-command] Command "${command}" not found at any known path — refusing bare fallback in packaged mode`
    )
    throw new Error(`MCP command not found: ${command}`)
  }
  chatAgentLogger.info(`[mcp:resolve-command] Falling back to bare command: ${command}`)
  return command
}

/**
 * Known Homebrew Java installation paths (macOS arm64 + x86_64).
 * Checked in order — first existing directory wins.
 */
const KNOWN_JAVA_PATHS = [
  '/opt/homebrew/opt/openjdk@21', // Homebrew arm64 — Java 21
  '/opt/homebrew/opt/openjdk@17', // Homebrew arm64 — Java 17
  '/opt/homebrew/opt/openjdk', // Homebrew arm64 — latest
  '/usr/local/opt/openjdk@21', // Homebrew x86_64 — Java 21
  '/usr/local/opt/openjdk@17', // Homebrew x86_64 — Java 17
  '/usr/local/opt/openjdk' // Homebrew x86_64 — latest
] as const

/**
 * Resolve JAVA_HOME for packaged macOS apps where the shell profile
 * isn't loaded and Homebrew isn't on PATH.
 *
 * Strategy:
 * 1. Return `process.env.JAVA_HOME` if already set
 * 2. Probe known Homebrew install paths (fastest — no subprocess)
 * 3. Try `/usr/libexec/java_home -v 17+` as a last resort
 */
function resolveJavaHome(): string | undefined {
  // Already set — use it
  if (process.env.JAVA_HOME) {
    // SVC-05: Validate that JAVA_HOME actually contains bin/java
    const javaBin = join(process.env.JAVA_HOME, 'bin', 'java')
    if (existsSync(javaBin)) {
      return process.env.JAVA_HOME
    }
    chatAgentLogger.warn(
      `[mcp:java-resolve] JAVA_HOME=${process.env.JAVA_HOME} has no bin/java — ignoring`
    )
  }

  // Probe known Homebrew paths
  for (const p of KNOWN_JAVA_PATHS) {
    // SVC-05: Verify bin/java exists, not just the directory
    const javaBin = join(p, 'bin', 'java')
    if (existsSync(javaBin)) {
      chatAgentLogger.info(`[mcp:java-resolve] Found Java at ${p}`)
      return p
    }
  }

  // Fallback: ask macOS for any Java 17+
  try {
    const result = execFileSync('/usr/libexec/java_home', ['-v', '17+'], {
      encoding: 'utf-8',
      timeout: 3000
    }).trim()
    if (result && existsSync(result)) {
      chatAgentLogger.info(`[mcp:java-resolve] Found Java via java_home: ${result}`)
      return result
    }
  } catch (e) {
    chatAgentLogger.debug('[mcp:java-resolve] java_home lookup failed (non-fatal):', e)
  }

  chatAgentLogger.warn('[mcp:java-resolve] No Java 17+ found — Maestro may fail to start')
  return undefined
}

/**
 * Build the environment for an external MCP stdio process.
 *
 * In packaged macOS apps, the GUI process inherits only a minimal PATH
 * (/usr/bin:/bin:/usr/sbin:/sbin). This helper:
 * 1. Forwards any explicitly-set env vars from process.env
 * 2. Auto-resolves JAVA_HOME from Homebrew / macOS java_home
 * 3. Injects Homebrew bin directories and JAVA_HOME/bin into PATH
 *    so child processes can find `java`, `npx`, `node`, etc.
 */
function buildStdioEnv(envKeys: readonly string[] | undefined): Record<string, string> | undefined {
  if (!envKeys?.length && !app.isPackaged) return undefined

  const env: Record<string, string> = {}

  // Forward explicitly-set env vars
  if (envKeys) {
    for (const k of envKeys) {
      if (process.env[k]) env[k] = process.env[k]!
    }
  }

  // Auto-resolve JAVA_HOME if requested but not set
  if (envKeys?.includes('JAVA_HOME') && !env.JAVA_HOME) {
    const javaHome = resolveJavaHome()
    if (javaHome) env.JAVA_HOME = javaHome
  }

  // In packaged apps, enrich PATH with common tool directories
  if (app.isPackaged) {
    const extraPaths: string[] = []

    // Add JAVA_HOME/bin if resolved
    if (env.JAVA_HOME) {
      extraPaths.push(`${env.JAVA_HOME}/bin`)
    }

    // Add common Homebrew paths
    // SEC-01: Removed ~/.maestro/bin — user-writable directory enables executable
    // hijacking. Maestro users should have it in their system PATH.
    extraPaths.push(
      '/opt/homebrew/bin', // Homebrew arm64
      '/usr/local/bin' // Homebrew x86_64 + system tools
    )

    const basePath = process.env.PATH || '/usr/bin:/bin:/usr/sbin:/sbin'
    env.PATH = [...extraPaths, basePath].join(':')

    chatAgentLogger.info(`[mcp:stdio-env] Enriched PATH for packaged app: ${env.PATH}`)
  }

  return Object.keys(env).length > 0 ? env : undefined
}

/**
 * Mount external MCP stdio servers based on per-message activation flags.
 * Shared between local LLM and Claude code paths.
 *
 * Key behaviors:
 * - `alwaysLoad: true` forces tools into the prompt (not deferred behind ToolSearch,
 *   which is globally blocked in this app).
 * - `env` is built by {@link buildStdioEnv} which auto-resolves JAVA_HOME and enriches
 *   PATH for packaged macOS apps where the GUI shell is minimal.
 */
function mountExternalMcps(
  servers: Record<string, McpServerConfig>,
  allowedTools: string[] | undefined,
  mode: ConversationMode,
  externalMcpActive: Record<string, boolean>
): void {
  chatAgentLogger.info(
    `[mcp:mount-external] Active flags: ${JSON.stringify(externalMcpActive)} mode=${mode}`
  )
  for (const integration of EXTERNAL_MCP_INTEGRATIONS) {
    if (externalMcpActive[integration.id]) {
      const env = buildStdioEnv(integration.envKeys)

      // Merge performance env vars (always injected, not user-supplied)
      const mergedEnv = {
        ...(env ?? {}),
        ...(integration.performanceEnv ?? {})
      }
      const finalEnv = Object.keys(mergedEnv).length > 0 ? mergedEnv : undefined

      const stdioConfig: McpServerConfig = {
        type: 'stdio',
        command: resolveStdioCommand(integration.command, integration.commandPaths),
        args: [...integration.args],
        alwaysLoad: true,
        ...(finalEnv ? { env: finalEnv } : {})
      }
      servers[integration.id] = stdioConfig

      // Plan mode: only read-only tools. Build mode: all tools.
      if (allowedTools !== undefined) {
        const modeTools = mode === 'plan' ? integration.planModeToolNames : integration.toolNames
        allowedTools.push(...modeTools)
      }

      chatAgentLogger.info(
        `[mcp:mount-external] ✓ Mounted ${integration.id}: command=${stdioConfig.command} args=${integration.args.join(' ')} tools=${(mode === 'plan' ? integration.planModeToolNames : integration.toolNames).length}`
      )
    } else {
      chatAgentLogger.info(`[mcp:mount-external] ✗ Skipped ${integration.id} (not active)`)
    }
  }
}

/**
 * Merge additional tool names into a base allowlist.
 * Returns undefined when the base is undefined (= "all tools allowed").
 */
function resolveToolAllowlist(
  baseAllowed: string[] | undefined,
  additionalTools: string[]
): string[] | undefined {
  if (baseAllowed === undefined) return undefined
  return [...baseAllowed, ...additionalTools]
}

/**
 * Build MCP config for local LLM providers.
 * Tool gating by context window tier:
 *   small (≤64K): 6 essential code-graph + 3 control-actions — saves ~50% schema overhead
 *   medium (≤128K): full code-graph + semantic-search + control-actions
 *   large (>128K): everything (same as Claude)
 */
function buildLocalProviderMcpConfig(opts: {
  tier: ContextWindowTier
  mode: ConversationMode
  featureFlags: McpFeatureFlags
  workspaceId: string | null
  baseAllowed: string[] | undefined
  disallowed: string[]
}): McpConfigResult & { planBuiltinDisallowed?: string[] } {
  const { tier, mode, featureFlags, workspaceId, baseAllowed, disallowed } = opts
  const { repomapEnabled, semanticSearchEnabled } = featureFlags
  const localActive = featureFlags.localMcpActive
  const servers: Record<string, McpServerConfig> = {}

  const codeGraphEnabled =
    repomapEnabled && !!workspaceId && isLocalMcpEnabled('code-graph', localActive)

  // Semantic search: skip for 'small' tier (saves ~3 tool schemas ≈ 1-2K tokens)
  const semanticSearchEnabled_ =
    tier !== 'small' &&
    semanticSearchEnabled &&
    !!workspaceId &&
    isLocalMcpEnabled('semantic-search', localActive)

  // Code analysis: skip for 'small' tier (saves ~3 tool schemas)
  const codeAnalysisEnabled = tier !== 'small' && isLocalMcpEnabled('code-analysis', localActive)

  // Process manager: skip for 'small' tier and plan mode (read-only)
  const processManagerEnabled =
    tier !== 'small' && mode !== 'plan' && isLocalMcpEnabled('process-manager', localActive)

  // Build allowed tools list — tier-gated subset for code-graph
  const conditionalTools = [
    // Code graph: small tier → 6 essential tools; medium/large → full 13
    ...(codeGraphEnabled
      ? tier === 'small'
        ? [...ESSENTIAL_CODE_GRAPH_TOOLS]
        : MCP_TOOLS.CODE_GRAPH._ALL_NAMES
      : []),
    // Semantic search (tier-gated above)
    ...(semanticSearchEnabled_ ? MCP_TOOLS.SEMANTIC_SEARCH._ALL_NAMES : []),
    // Code analysis (tier-gated above)
    ...(codeAnalysisEnabled ? MCP_TOOLS.CODE_ANALYSIS._ALL_NAMES : []),
    // Process manager (tier-gated + mode-gated above)
    ...(processManagerEnabled ? MCP_TOOLS.PROCESS_MANAGER._ALL_NAMES : []),
    // Control actions — always on
    MCP_TOOLS.CONTROL_ACTIONS.EMIT_PLAN.name,
    MCP_TOOLS.CONTROL_ACTIONS.ASK_USER.name,
    MCP_TOOLS.CONTROL_ACTIONS.EMIT_PHASE_PROGRESS.name,
    // Memory tools — always on (all tiers, ~1-2K tokens of schemas)
    ...MCP_TOOLS.MEMORY._ALL_NAMES
  ]
  const localAllowed = resolveToolAllowlist(baseAllowed, conditionalTools)

  // ── External MCP Servers (stdio) — also available for local LLMs ──
  const externalActive = featureFlags.externalMcpActive ?? {}
  mountExternalMcps(servers, localAllowed, mode, externalActive)

  chatAgentLogger.info(
    `[mcp:config-result] servers=[${Object.keys(servers).join(',')}] allowedToolCount=${localAllowed?.length ?? 'all'} disallowedCount=${disallowed.length} provider=local tier=${tier}`
  )

  // For small tier: explicitly disallow the tools we didn't allow — defense-in-depth
  const smallTierDisallowed =
    tier === 'small'
      ? [
          // Redundant code-graph tools not in ESSENTIAL_CODE_GRAPH_TOOLS
          ...(codeGraphEnabled
            ? MCP_TOOLS.CODE_GRAPH._ALL_NAMES.filter(
                (t) => !(ESSENTIAL_CODE_GRAPH_TOOLS as readonly string[]).includes(t)
              )
            : []),
          // All semantic-search tools (server not mounted)
          ...MCP_TOOLS.SEMANTIC_SEARCH._ALL_NAMES,
          // All code-analysis tools (server not mounted)
          ...MCP_TOOLS.CODE_ANALYSIS._ALL_NAMES
        ]
      : []

  // Plan-mode built-in tool gating — restrict write tools in plan mode
  // to reduce tool schema overhead (each tool schema costs ~400-500 tokens).
  const tierLimits = TIER_LIMITS[tier]
  let planBuiltinDisallowed: string[] | undefined
  if (mode === 'plan' && tierLimits.planBuiltinAllowlist) {
    const allBuiltins = [
      'Read',
      'Write',
      'Edit',
      'MultiEdit',
      'Bash',
      'Glob',
      'Grep',
      'TodoRead',
      'TodoWrite',
      'NotebookRead',
      'NotebookEdit'
    ]
    planBuiltinDisallowed = allBuiltins.filter(
      (t) => !tierLimits.planBuiltinAllowlist!.includes(t)
    )
    chatAgentLogger.info(
      `[mcp:plan-builtin-gating] tier=${tier} allowed=[${tierLimits.planBuiltinAllowlist.join(',')}] ` +
        `disallowed=[${planBuiltinDisallowed.join(',')}] — saves ~${planBuiltinDisallowed.length * 450} tokens`
    )
  }

  const mcpServers = Object.keys(servers).length > 0 ? servers : undefined
  return {
    ...(mcpServers ? { mcpServers } : {}),
    allowedTools: localAllowed,
    disallowedTools: [...disallowed, ...smallTierDisallowed, ...(planBuiltinDisallowed ?? [])],
    codeAnalysisEnabled,
    planBuiltinDisallowed
  }
}

/**
 * Build MCP config for Claude providers.
 * Full MCP suite with feature-flag gating.
 */
function buildClaudeProviderMcpConfig(opts: {
  mode: ConversationMode
  featureFlags: McpFeatureFlags
  workspaceId: string | null
  baseAllowed: string[] | undefined
  disallowed: string[]
}): McpConfigResult {
  const { mode, featureFlags, workspaceId, baseAllowed, disallowed } = opts
  const { repomapEnabled, semanticSearchEnabled, githubConfigured } = featureFlags
  const localActive = featureFlags.localMcpActive

  // ── Claude Write/Edit exposure ──
  // Claude Code gates plan-mode writes via --permission-mode plan (read-only at
  // runtime), so we keep Write/Edit EXPOSED in every mode. This lets the live
  // set_permission_mode(plan→auto/acceptEdits) switch unlock edits without a
  // respawn — matching Claude Code's native "approve plan → start editing" flow.
  // The local-LLM path is unaffected (uses buildLocalProviderMcpConfig instead).
  const claudeDisallowed = disallowed.filter((t) => t !== 'Write' && t !== 'Edit')
  const claudeBaseAllowed =
    baseAllowed === undefined ? undefined : [...baseAllowed, 'Write', 'Edit']

  // ── Allowed Tools ──
  // Build-mode has no allow-list (claudeBaseAllowed=undefined). Plan-mode appends
  // conditional MCP tool names to the base allow-list (now including Write/Edit).
  const conditionalTools = [
    // Code graph MCP tools (workspace flag AND per-chat toggle)
    ...(repomapEnabled && workspaceId && isLocalMcpEnabled('code-graph', localActive)
      ? [
          MCP_TOOLS.CODE_GRAPH.GRAPH_MAP.name,
          MCP_TOOLS.CODE_GRAPH.SEARCH_IDENTIFIERS.name,
          MCP_TOOLS.CODE_GRAPH.FIND_DEAD_CODE.name,
          MCP_TOOLS.CODE_GRAPH.FILE_OUTLINE.name,
          MCP_TOOLS.CODE_GRAPH.FIND_CALLERS.name,
          MCP_TOOLS.CODE_GRAPH.FIND_CALLEES.name,
          MCP_TOOLS.CODE_GRAPH.FIND_REFERENCES.name,
          MCP_TOOLS.CODE_GRAPH.FILE_DEPENDENCIES.name,
          MCP_TOOLS.CODE_GRAPH.FILE_DEPENDENTS.name,
          MCP_TOOLS.CODE_GRAPH.SYMBOL_HOTSPOTS.name,
          MCP_TOOLS.CODE_GRAPH.COUPLING_ANALYSIS.name,
          MCP_TOOLS.CODE_GRAPH.CIRCULAR_DEPENDENCIES.name,
          MCP_TOOLS.CODE_GRAPH.MODULE_BOUNDARY_HEALTH.name
        ]
      : []),
    // Semantic search (workspace flag AND per-chat toggle)
    ...(semanticSearchEnabled &&
    workspaceId &&
    isLocalMcpEnabled('semantic-search', localActive)
      ? [
          MCP_TOOLS.SEMANTIC_SEARCH.SEMANTIC_SEARCH.name,
          MCP_TOOLS.SEMANTIC_SEARCH.SIMILAR_CODE.name,
          MCP_TOOLS.SEMANTIC_SEARCH.CODEBASE_CONCEPTS.name
        ]
      : []),
    // Git context (per-chat gated)
    ...(isLocalMcpEnabled('git-context', localActive)
      ? MCP_TOOLS.GIT_CONTEXT._ALL_NAMES
      : []),
    // Checkpoint context (per-chat gated)
    ...(isLocalMcpEnabled('checkpoint-context', localActive)
      ? MCP_TOOLS.CHECKPOINT_CONTEXT._ALL_NAMES
      : []),
    // GitHub context (workspace flag AND per-chat toggle)
    ...(githubConfigured && isLocalMcpEnabled('github-context', localActive)
      ? MCP_TOOLS.GITHUB_CONTEXT._ALL_NAMES
      : []),
    // Code analysis (per-chat gated)
    ...(isLocalMcpEnabled('code-analysis', localActive)
      ? MCP_TOOLS.CODE_ANALYSIS._ALL_NAMES
      : []),
    // Process manager — build/danger mode only (not plan)
    ...(mode !== 'plan' && isLocalMcpEnabled('process-manager', localActive)
      ? MCP_TOOLS.PROCESS_MANAGER._ALL_NAMES
      : []),
    // Control actions — always on (plan + ask + phase progress)
    MCP_TOOLS.CONTROL_ACTIONS.EMIT_PLAN.name,
    MCP_TOOLS.CONTROL_ACTIONS.ASK_USER.name,
    MCP_TOOLS.CONTROL_ACTIONS.EMIT_PHASE_PROGRESS.name,
    // Memory tools — always on (all tiers)
    ...MCP_TOOLS.MEMORY._ALL_NAMES
  ]
  const allowedTools = resolveToolAllowlist(claudeBaseAllowed, conditionalTools)

  // ── External MCP Servers (stdio) ──
  // Conditionally mounted based on per-message flags from the conversation MCP overrides.
  const servers: Record<string, McpServerConfig> = {}
  const externalActive = featureFlags.externalMcpActive ?? {}
  mountExternalMcps(servers, allowedTools, mode, externalActive)

  chatAgentLogger.info(
    `[mcp:config-result] servers=[${Object.keys(servers).join(',')}] allowedToolCount=${allowedTools?.length ?? 'all'} disallowedCount=${disallowed.length} provider=claude`
  )

  const mcpServers = Object.keys(servers).length > 0 ? servers : undefined

  return {
    ...(mcpServers ? { mcpServers } : {}),
    allowedTools,
    disallowedTools: claudeDisallowed,
    codeAnalysisEnabled: true
  }
}

/**
 * Builds MCP tool allow/disallow lists and mounts external MCP servers.
 * Dispatches to provider-specific builders for local LLM vs Claude paths.
 */
export function buildWorkspaceMcpConfig(opts: {
  mode: ConversationMode
  workspacePath: string
  workspaceId: string | null
  conversationId: string | null
  featureFlags: McpFeatureFlags
  controlCallbacks: ControlActionCallbacks
  /** When true, mounts only control-actions MCP (3 tools vs 30+) to save ~12-16K tokens. */
  isLocalProvider?: boolean
  /** Context window tier — gates MCP tools for small-window models */
  contextTier?: ContextWindowTier
}): McpConfigResult & {
  /** SDK built-in tools to disallow in local plan mode (saves tool schema tokens) */
  planBuiltinDisallowed?: string[]
} {
  const { baseAllowed, disallowed } = buildModePermissions(opts.mode)

  if (opts.isLocalProvider) {
    return buildLocalProviderMcpConfig({
      tier: opts.contextTier ?? 'large',
      mode: opts.mode,
      featureFlags: opts.featureFlags,
      workspaceId: opts.workspaceId,
      baseAllowed,
      disallowed
    })
  }

  return buildClaudeProviderMcpConfig({
    mode: opts.mode,
    featureFlags: opts.featureFlags,
    workspaceId: opts.workspaceId,
    baseAllowed,
    disallowed
  })
}

/**
 * MemoryDocWatcherService — watches configured file globs for changes,
 * routes through extraction → write pipeline.
 *
 * Gates:
 *   1. 60s debounce per file
 *   2. Content-hash comparison (skip if unchanged)
 *   3. 1h cooldown per file (even if hash changed)
 *
 * Globs are user-editable via capture settings. Defaults:
 *   docs/** /*.md, README.md, CLAUDE.md
 */

import { watch, existsSync, readFileSync, statSync, readdirSync } from 'node:fs'
import { createHash } from 'node:crypto'
import { join, relative } from 'node:path'
import { dbLogger } from '../logger'
import { memoryExtractionService } from './memory-extraction.service'
import { memoryFactRepository } from '../db/repositories/memory-fact.repository'

const log = dbLogger

const DEFAULT_WATCHER_GLOBS = ['docs/**/*.md', 'README.md', 'CLAUDE.md']
const DEBOUNCE_MS = 60_000 // 60 seconds
const COOLDOWN_MS = 60 * 60 * 1000 // 1 hour

class MemoryDocWatcherService {
  private watchers: Array<ReturnType<typeof watch>> = []
  private debounceTimers = new Map<string, NodeJS.Timeout>()
  private lastProcessed = new Map<string, number>() // filePath → timestamp
  private activeWorkspaceId: string | null = null
  private activeWorkspacePath: string | null = null

  /** The workspace currently being watched (null if idle). */
  get activeWorkspace(): string | null {
    return this.activeWorkspaceId
  }

  /**
   * Start watching docs in a workspace directory.
   * Call stop() before starting a new workspace.
   */
  start(workspaceId: string, workspacePath: string, globs?: string[]): void {
    this.stop()
    this.activeWorkspaceId = workspaceId
    this.activeWorkspacePath = workspacePath

    const patterns = globs ?? DEFAULT_WATCHER_GLOBS

    // Collect all directories that contain files matching our patterns
    const dirsToWatch = new Set<string>()
    for (const pattern of patterns) {
      try {
        const files = this.resolvePattern(workspacePath, pattern)
        for (const relFile of files) {
          const dir = join(workspacePath, relFile).replace(/\/[^/]+$/, '')
          dirsToWatch.add(dir)
        }
        // Top-level patterns (README.md, CLAUDE.md) → watch root
        if (!pattern.includes('/')) dirsToWatch.add(workspacePath)
      } catch (err) {
        log.debug(`[DocWatcher] Failed to resolve pattern ${pattern}:`, err)
      }
    }

    for (const dir of dirsToWatch) {
      if (!existsSync(dir)) continue
      try {
        const watcher = watch(dir, { recursive: false }, (_event, filename) => {
          if (!filename) return
          const fullPath = join(dir, filename)
          const relPath = relative(workspacePath, fullPath)
          if (this.matchesGlob(relPath, patterns)) {
            this.scheduleExtraction(relPath, fullPath)
          }
        })
        this.watchers.push(watcher)
      } catch (err) {
        log.debug(`[DocWatcher] Failed to watch ${dir}:`, err)
      }
    }

    if (this.watchers.length > 0) {
      log.info(`[DocWatcher] Watching ${this.watchers.length} directories for ${patterns.join(', ')}`)
    }
  }

  /** Stop all watchers and clear state. */
  stop(): void {
    for (const w of this.watchers) {
      try { w.close() } catch { /* ignore */ }
    }
    this.watchers = []
    for (const timer of this.debounceTimers.values()) {
      clearTimeout(timer)
    }
    this.debounceTimers.clear()
    this.activeWorkspaceId = null
    this.activeWorkspacePath = null
  }

  /**
   * Resolve a simple glob pattern to matching file paths relative to cwd.
   * Supports: direct names (README.md), dir/** /*.ext patterns, *.ext.
   * Uses readdirSync to avoid the external `glob` dependency.
   */
  private resolvePattern(cwd: string, pattern: string): string[] {
    const IGNORE = new Set(['node_modules', '.git'])

    // Direct file name (no wildcards)
    if (!pattern.includes('*')) {
      const full = join(cwd, pattern)
      return existsSync(full) ? [pattern] : []
    }

    // docs/**/*.md → prefix = 'docs/', ext = '.md'
    if (pattern.includes('**')) {
      const prefix = pattern.split('**')[0] // 'docs/' or ''
      const suffixPart = pattern.split('**').pop() ?? ''
      const ext = suffixPart.replace(/^\/\*/, '') // '/*.md' → '.md'
      const baseDir = join(cwd, prefix)
      if (!existsSync(baseDir)) return []
      return this.walkDir(baseDir, IGNORE)
        .filter((f) => f.endsWith(ext))
        .map((f) => relative(cwd, f))
    }

    // *.md → top-level files with extension
    if (pattern.startsWith('*.')) {
      const ext = pattern.slice(1)
      try {
        return readdirSync(cwd, { withFileTypes: true })
          .filter((d) => d.isFile() && d.name.endsWith(ext) && !IGNORE.has(d.name))
          .map((d) => d.name)
      } catch { return [] }
    }

    return []
  }

  /** Recursively walk a directory, skipping ignored dirs. */
  private walkDir(dir: string, ignore: Set<string>): string[] {
    const results: string[] = []
    try {
      for (const entry of readdirSync(dir, { withFileTypes: true })) {
        if (ignore.has(entry.name)) continue
        const full = join(dir, entry.name)
        if (entry.isDirectory()) {
          results.push(...this.walkDir(full, ignore))
        } else if (entry.isFile()) {
          results.push(full)
        }
      }
    } catch { /* permission error, etc. */ }
    return results
  }

  /** Simple glob matching — supports *, **, and direct name matches. */
  private matchesGlob(relPath: string, patterns: string[]): boolean {
    for (const pattern of patterns) {
      // Direct name match
      if (pattern === relPath) return true

      // Simple pattern: docs/**/*.md → match any .md in docs/
      if (pattern.includes('**')) {
        const prefix = pattern.split('**')[0]
        const suffixPart = pattern.split('**').pop() ?? ''
        const ext = suffixPart.replace(/^\/\*/, '') // '/*.md' → '.md'
        if (relPath.startsWith(prefix) && relPath.endsWith(ext)) return true
      }

      // Extension wildcard: *.md → match any .md at the right level
      if (pattern.startsWith('*.')) {
        const ext = pattern.slice(1)
        if (relPath.endsWith(ext) && !relPath.includes('/')) return true
      }
    }
    return false
  }

  /** Schedule an extraction with debounce and cooldown gates. */
  private scheduleExtraction(relPath: string, fullPath: string): void {
    // Clear any existing debounce for this file
    const existing = this.debounceTimers.get(relPath)
    if (existing) clearTimeout(existing)

    // Set debounce timer
    const timer = setTimeout(() => {
      this.debounceTimers.delete(relPath)
      this.processFileChange(relPath, fullPath).catch((err) =>
        log.warn(`[DocWatcher] Failed to process ${relPath}:`, err)
      )
    }, DEBOUNCE_MS)

    this.debounceTimers.set(relPath, timer)
  }

  /** Process a file change: check cooldown, hash gate, then extract. */
  private async processFileChange(relPath: string, fullPath: string): Promise<void> {
    if (!this.activeWorkspaceId || !this.activeWorkspacePath) return

    // 1. Cooldown check
    const lastTime = this.lastProcessed.get(relPath) ?? 0
    if (Date.now() - lastTime < COOLDOWN_MS) {
      log.debug(`[DocWatcher] Cooldown active for ${relPath}, skipping`)
      return
    }

    // 2. Check file exists and is readable
    if (!existsSync(fullPath)) return
    try {
      const stat = statSync(fullPath)
      if (!stat.isFile() || stat.size === 0) return
    } catch {
      return
    }

    // 3. Content-hash gate
    const content = readFileSync(fullPath, 'utf-8')
    const hash = createHash('sha256').update(content).digest('hex')

    const existing = memoryFactRepository.getDocState(this.activeWorkspaceId, relPath)
    if (existing && existing.contentHash === hash) {
      log.debug(`[DocWatcher] Content unchanged for ${relPath}, skipping`)
      return
    }

    // 4. Extract facts
    log.info(`[DocWatcher] Processing changed doc: ${relPath}`)
    this.lastProcessed.set(relPath, Date.now())

    const created = await memoryExtractionService.extractFromDocument(
      this.activeWorkspaceId,
      this.activeWorkspacePath,
      fullPath
    )

    // 5. Update doc state
    memoryFactRepository.upsertDocState(this.activeWorkspaceId, relPath, hash)

    if (created > 0) {
      log.info(`[DocWatcher] Extracted ${created} facts from ${relPath}`)
    }
  }
}

export const memoryDocWatcherService = new MemoryDocWatcherService()

/**
 * MemoryExtractionService — Extracts structured facts from transcripts,
 * commits, and documents via Haiku.
 *
 * Replaces `memory-feed.service.ts`. Uses the proven `spawnSummarizer` pattern
 * with model from `modelConfigService.getModel(path, 'memoryFeed')`.
 * Serialized single-in-flight queue prevents concurrent Haiku calls.
 *
 * Retained: `regenerateClaudeMd` for CLAUDE.md generation.
 */

import { spawn } from 'node:child_process'
import { readFileSync, existsSync, readdirSync, statSync } from 'node:fs'
import { join } from 'node:path'
import { execSync } from 'node:child_process'
import { buildEnvWithPath } from './env-utils'
import { dbLogger } from '../logger'
import { memoryEngineService } from './memory-engine.service'
import { modelConfigService, resolveAssignment, buildResolveOpts } from './model-config.service'
import { runOneShotLocal, buildMemoryFeedFallbackArgs } from './one-shot-local'
import { DEFAULT_MODEL_CONFIG, MCP_TOOLS } from '../../shared/constants'
import { runAgenticClaude, parseSentinelBlock, SENTINELS } from './agentic-claude-runner'
import type {
  MemoryFactCategory,
  MemoryFeedProgress,
  DiscoveredAgent,
  DiscoveredSkill
} from '../../shared/types'

const log = dbLogger

/** Minimum transcript length to bother extracting from. */
const MIN_TRANSCRIPT_CHARS = 200

/** Structured fact from Haiku extraction. */
interface ExtractedFact {
  category: MemoryFactCategory
  title: string
  content: string
  tags?: string[]
  scopePaths?: string[]
}

type ProgressCallback = (event: MemoryFeedProgress) => void

class MemoryExtractionService {
  private currentAbortController: AbortController | null = null
  private isBusy = false
  private queue: Array<() => Promise<void>> = []
  private processing = false

  // ── Queue ───────────────────────────────────────────────────────────────

  /** Enqueue an extraction job. Only one runs at a time. */
  enqueue(job: () => Promise<void>): void {
    this.queue.push(job)
    this.processQueue()
  }

  private async processQueue(): Promise<void> {
    if (this.processing) return
    this.processing = true

    while (this.queue.length > 0) {
      const job = this.queue.shift()!
      try {
        await job()
      } catch (err) {
        log.warn('[MemoryExtraction] Queued job failed:', err)
      }
    }

    this.processing = false
  }

  // ── Session-end extraction ──────────────────────────────────────────────

  /**
   * Extract facts from a completed session transcript + git changes.
   * Called at stream finalization.
   */
  enqueueSessionExtraction(params: {
    workspaceId: string
    workspacePath: string | null
    transcript: string
    startSha?: string | null
    conversationId: string
  }): void {
    if (params.transcript.length < MIN_TRANSCRIPT_CHARS) {
      log.debug('[MemoryExtraction] Transcript too short, skipping extraction')
      return
    }

    this.enqueue(async () => {
      await this.extractFromSession(params)
    })
  }

  private async extractFromSession(params: {
    workspaceId: string
    workspacePath: string | null
    transcript: string
    startSha?: string | null
    conversationId: string
  }): Promise<void> {
    const { workspaceId, workspacePath, transcript, startSha, conversationId } = params

    // Build context: transcript tail + git changes
    const parts: string[] = []

    // Transcript (tail — last 8000 chars to stay within Haiku budget)
    const tail = transcript.length > 8000 ? transcript.slice(-8000) : transcript
    parts.push(`## Session Transcript (tail)\n${tail}`)

    // Git changes since session start
    if (workspacePath && startSha) {
      try {
        const gitLog = execSync(
          `git log --stat ${startSha}..HEAD 2>/dev/null || true`,
          { cwd: workspacePath, timeout: 5000, encoding: 'utf-8', maxBuffer: 10_000 }
        ).trim()
        if (gitLog) {
          parts.push(`## Git Changes Since Session Start\n${gitLog.slice(0, 3000)}`)
        }
      } catch {
        // No git or no commits — fine
      }
    }

    const combined = parts.join('\n\n')
    const prompt = buildExtractionPrompt(combined)

    try {
      const result = await this.spawnSummarizer(prompt, workspacePath ?? undefined, workspaceId)
      const facts = parseExtractedFacts(result)

      let created = 0
      for (const fact of facts) {
        try {
          await memoryEngineService.writeFact({
            workspaceId,
            category: fact.category,
            title: fact.title,
            content: fact.content,
            tags: fact.tags,
            scopePaths: fact.scopePaths,
            sourceType: 'session',
            sourceRef: conversationId,
            workspacePath
          })
          created++
        } catch (err) {
          log.warn('[MemoryExtraction] Failed to write session fact:', err)
        }
      }

      if (created > 0) {
        log.info(`[MemoryExtraction] Session extraction: ${created} facts from conversation ${conversationId}`)
      }
    } catch (err) {
      log.warn('[MemoryExtraction] Session extraction failed:', err)
    }
  }

  // ── Document extraction ─────────────────────────────────────────────────

  /**
   * Core content-based extraction — works with any text, no file on disk needed.
   * Used by extractFromDocument (file wrapper) and direct content extraction
   * (e.g. URL reference docs, blueprint artifacts).
   */
  async extractFromContent(
    workspaceId: string,
    workspacePath: string,
    sourceRef: string,
    content: string,
    onProgress?: ProgressCallback,
    opts?: { sourceType?: import('../../shared/types').MemorySourceType; tags?: string[] }
  ): Promise<number> {
    const sourceType = opts?.sourceType ?? 'document'
    const emit = (msg: string, status: MemoryFeedProgress['status'] = 'running'): void => {
      onProgress?.({ status, message: msg, source: sourceType, timestamp: Date.now() })
    }

    if (content.length < 20) {
      emit('Content too short for extraction', 'error')
      return 0
    }

    emit(`Extracting facts from ${sourceRef}...`)

    const prompt = buildExtractionPrompt(
      `## Document: ${sourceRef}\n${content.substring(0, 50000)}`
    )

    try {
      const result = await this.spawnSummarizer(prompt, workspacePath, workspaceId)
      const facts = parseExtractedFacts(result)

      let created = 0
      for (const fact of facts) {
        try {
          const written = await memoryEngineService.writeFact({
            workspaceId,
            category: fact.category,
            title: fact.title,
            content: fact.content,
            tags: [...(fact.tags ?? []), ...(opts?.tags ?? [])],
            scopePaths: fact.scopePaths ?? [sourceRef],
            sourceType,
            sourceRef,
            workspacePath
          })
          if (written) created++
        } catch (err) {
          log.warn('[MemoryExtraction] Failed to write content fact:', err)
        }
      }

      emit(`Created ${created} facts from ${sourceRef}`, 'done')
      return created
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err)
      emit(`Extraction failed: ${msg}`, 'error')
      return 0
    }
  }

  /**
   * Extract facts from a document file (used by doc watcher and manual feed).
   * Thin wrapper over extractFromContent that reads the file from disk.
   */
  async extractFromDocument(
    workspaceId: string,
    workspacePath: string,
    filePath: string,
    onProgress?: ProgressCallback
  ): Promise<number> {
    if (!existsSync(filePath)) {
      onProgress?.({ status: 'error', message: 'File not found', source: 'document', timestamp: Date.now() })
      return 0
    }

    const content = readFileSync(filePath, 'utf-8')
    return this.extractFromContent(workspaceId, workspacePath, filePath, content, onProgress)
  }

  // ── Commit extraction ───────────────────────────────────────────────────

  /**
   * Extract facts from a commit diff. Stores touched paths in scopePaths.
   */
  enqueueCommitExtraction(params: {
    workspaceId: string
    workspacePath: string
    startSha: string
    endSha: string
  }): void {
    this.enqueue(async () => {
      await this.extractFromCommit(params)
    })
  }

  private async extractFromCommit(params: {
    workspaceId: string
    workspacePath: string
    startSha: string
    endSha: string
  }): Promise<void> {
    const { workspaceId, workspacePath, startSha, endSha } = params

    try {
      const diffStat = execSync(
        `git diff --stat ${startSha}..${endSha} 2>/dev/null || true`,
        { cwd: workspacePath, timeout: 5000, encoding: 'utf-8', maxBuffer: 20_000 }
      ).trim()

      if (!diffStat || diffStat.length < 20) return

      const logOutput = execSync(
        `git log --oneline ${startSha}..${endSha} 2>/dev/null || true`,
        { cwd: workspacePath, timeout: 5000, encoding: 'utf-8', maxBuffer: 10_000 }
      ).trim()

      // Extract touched file paths from diff stat
      const touchedPaths = diffStat
        .split('\n')
        .map((line) => line.trim().split(/\s+/)[0])
        .filter((p) => p && !p.includes('changed') && !p.includes('insertion') && !p.includes('deletion'))

      const prompt = buildExtractionPrompt(
        `## Commit Changes (${startSha.slice(0, 7)}..${endSha.slice(0, 7)})\n\n### Commits\n${logOutput.slice(0, 2000)}\n\n### Files Changed\n${diffStat.slice(0, 3000)}`
      )

      const result = await this.spawnSummarizer(prompt, workspacePath, workspaceId)
      const facts = parseExtractedFacts(result)

      let created = 0
      for (const fact of facts) {
        try {
          await memoryEngineService.writeFact({
            workspaceId,
            category: fact.category,
            title: fact.title,
            content: fact.content,
            tags: fact.tags,
            scopePaths: fact.scopePaths ?? touchedPaths.slice(0, 10),
            sourceType: 'commit',
            sourceRef: endSha,
            workspacePath
          })
          created++
        } catch (err) {
          log.warn('[MemoryExtraction] Failed to write commit fact:', err)
        }
      }

      if (created > 0) {
        log.info(`[MemoryExtraction] Commit extraction: ${created} facts from ${startSha.slice(0, 7)}..${endSha.slice(0, 7)}`)
      }
    } catch (err) {
      log.warn('[MemoryExtraction] Commit extraction failed:', err)
    }
  }

  // ── Blueprint completion extraction ──────────────────────────────────────

  /**
   * Extract facts from a completed/failed blueprint. Assembles a context block
   * from spec+plan artifacts, clarify Q&A, and task outcomes, then runs LLM
   * extraction. Enqueued (non-blocking).
   *
   * MEM-BP-COMPLETE-01: Deliberately NOT per-task or per-phase hooks — per-task
   * facts would flood memory. Task outcomes are summarized at completion where
   * failures become 'gotcha' facts.
   */
  enqueueBlueprintExtraction(params: {
    blueprintId: string
    workspaceId: string
    workspacePath: string
    title: string
    status: 'complete' | 'failed'
    phases: Array<{ phase: string; artifacts?: Array<{ type: string; contentMd?: string; contentJson?: any }> }>
    tasks: Array<{ taskId: string; description: string; status: string }>
    clarifyQA?: Array<{ question: string; answer: string }>
  }): void {
    this.enqueue(async () => {
      await this.extractFromBlueprint(params)
    })
  }

  private async extractFromBlueprint(params: {
    blueprintId: string
    workspaceId: string
    workspacePath: string
    title: string
    status: 'complete' | 'failed'
    phases: Array<{ phase: string; artifacts?: Array<{ type: string; contentMd?: string; contentJson?: any }> }>
    tasks: Array<{ taskId: string; description: string; status: string }>
    clarifyQA?: Array<{ question: string; answer: string }>
  }): Promise<void> {
    const { blueprintId, workspaceId, workspacePath, title, status, phases, tasks, clarifyQA } = params

    const parts: string[] = []
    parts.push(`## Blueprint: ${title}\nFinal status: ${status}\n`)

    // Spec artifact
    const specPhase = phases.find((p) => p.phase === 'specify')
    const specArtifact = specPhase?.artifacts?.find((a) => a.type === 'spec')
    if (specArtifact?.contentMd) {
      parts.push(`### Specification\n${specArtifact.contentMd.substring(0, 5000)}`)
    }

    // Plan artifact (decisions, risks, constraints)
    const planPhase = phases.find((p) => p.phase === 'plan')
    const planArtifact = planPhase?.artifacts?.find((a) => a.type === 'plan')
    if (planArtifact?.contentMd) {
      parts.push(`### Plan\n${planArtifact.contentMd.substring(0, 5000)}`)
    }

    // Clarify Q&A
    if (clarifyQA && clarifyQA.length > 0) {
      const qaLines = clarifyQA.map((qa) => `Q: ${qa.question}\nA: ${qa.answer}`).join('\n\n')
      parts.push(`### Clarification Q&A\n${qaLines.substring(0, 3000)}`)
    }

    // Task outcomes summary
    const completed = tasks.filter((t) => t.status === 'complete')
    const failed = tasks.filter((t) => t.status === 'failed')
    const skipped = tasks.filter((t) => t.status === 'skipped')
    parts.push(`### Task Outcomes\nCompleted: ${completed.length}, Failed: ${failed.length}, Skipped: ${skipped.length}`)
    if (failed.length > 0) {
      parts.push('#### Failed Tasks')
      for (const t of failed.slice(0, 10)) {
        parts.push(`- ${t.taskId}: ${t.description.substring(0, 200)}`)
      }
    }

    const combined = parts.join('\n\n')
    const prompt = buildExtractionPrompt(combined)

    try {
      const result = await this.spawnSummarizer(prompt, workspacePath, workspaceId)
      const facts = parseExtractedFacts(result)

      let created = 0
      for (const fact of facts) {
        try {
          await memoryEngineService.writeFact({
            workspaceId,
            category: fact.category,
            title: fact.title,
            content: fact.content,
            tags: [...(fact.tags ?? []), 'blueprint', `blueprint:${blueprintId}`],
            scopePaths: fact.scopePaths,
            sourceType: 'blueprint',
            sourceRef: blueprintId,
            workspacePath
          })
          created++
        } catch (err) {
          log.warn('[MemoryExtraction] Failed to write blueprint fact:', err)
        }
      }

      if (created > 0) {
        log.info(`[MemoryExtraction] Blueprint extraction: ${created} facts from "${title}" (${status})`)
      }
    } catch (err) {
      log.warn('[MemoryExtraction] Blueprint extraction failed:', err)
    }
  }

  // ── Plan execution completion extraction ────────────────────────────────

  /**
   * Extract facts from a completed chat plan execution. Assembles a context
   * block from phases, tasks, touched files, and timing, then runs LLM
   * extraction. Enqueued (non-blocking).
   *
   * Follows MEM-BP-COMPLETE-01 philosophy: one extraction per completion,
   * not per-task — task outcomes are summarized holistically.
   */
  enqueuePlanExecutionExtraction(params: {
    workspaceId: string
    workspacePath: string
    conversationId: string
    planTitle: string
    planGoal?: string
    status: 'completed' | 'partial' | 'failed'
    phases: Array<{
      phaseTitle: string
      status: string
      touchedFiles: string[]
      tasks: Array<{ title: string; status: string }>
    }>
    durationMs: number
  }): void {
    this.enqueue(async () => {
      await this.extractFromPlanExecution(params)
    })
  }

  private async extractFromPlanExecution(params: {
    workspaceId: string
    workspacePath: string
    conversationId: string
    planTitle: string
    planGoal?: string
    status: 'completed' | 'partial' | 'failed'
    phases: Array<{
      phaseTitle: string
      status: string
      touchedFiles: string[]
      tasks: Array<{ title: string; status: string }>
    }>
    durationMs: number
  }): Promise<void> {
    const { workspaceId, workspacePath, conversationId, planTitle, planGoal, status, phases, durationMs } = params

    const parts: string[] = []
    parts.push(`## Chat Plan Execution: ${planTitle}\nFinal status: ${status}\nDuration: ${Math.round(durationMs / 1000)}s\n`)

    if (planGoal) {
      parts.push(`### Goal\n${planGoal}`)
    }

    // Phase summary
    parts.push('### Phases')
    for (const phase of phases) {
      const taskSummary = phase.tasks.length > 0
        ? phase.tasks.map(t => `  - [${t.status}] ${t.title}`).join('\n')
        : '  (no tasks)'
      const filesSummary = phase.touchedFiles.length > 0
        ? `  Files: ${phase.touchedFiles.join(', ')}`
        : ''
      parts.push(`- **${phase.phaseTitle}** (${phase.status})\n${taskSummary}${filesSummary ? '\n' + filesSummary : ''}`)
    }

    // All touched files (deduped)
    const allFiles = [...new Set(phases.flatMap(p => p.touchedFiles))]
    if (allFiles.length > 0) {
      parts.push(`### Files Modified\n${allFiles.slice(0, 30).join('\n')}`)
    }

    // Failed phases/tasks for gotcha extraction
    const failedPhases = phases.filter(p => p.status === 'failed')
    const failedTasks = phases.flatMap(p => p.tasks.filter(t => t.status === 'failed'))
    if (failedPhases.length > 0 || failedTasks.length > 0) {
      parts.push('### Failures')
      for (const fp of failedPhases) {
        parts.push(`- Phase "${fp.phaseTitle}" failed`)
      }
      for (const ft of failedTasks.slice(0, 10)) {
        parts.push(`- Task "${ft.title}" failed`)
      }
    }

    const combined = parts.join('\n\n')
    const prompt = buildExtractionPrompt(combined)

    try {
      const result = await this.spawnSummarizer(prompt, workspacePath, workspaceId)
      const facts = parseExtractedFacts(result)

      let created = 0
      for (const fact of facts) {
        try {
          await memoryEngineService.writeFact({
            workspaceId,
            category: fact.category,
            title: fact.title,
            content: fact.content,
            tags: [...(fact.tags ?? []), 'plan-execution', `plan:${conversationId}`],
            scopePaths: fact.scopePaths ?? allFiles.slice(0, 10),
            sourceType: 'session',
            sourceRef: conversationId,
            workspacePath
          })
          created++
        } catch (err) {
          log.warn('[MemoryExtraction] Failed to write plan execution fact:', err)
        }
      }

      if (created > 0) {
        log.info(`[MemoryExtraction] Plan execution extraction: ${created} facts from "${planTitle}" (${status})`)
      }
    } catch (err) {
      log.warn('[MemoryExtraction] Plan execution extraction failed:', err)
    }
  }

  // ── Single-message extraction (for "Save to memory" hover action) ──────

  /**
   * Extract facts from a single message (deterministic fallback: creates
   * one fact verbatim if Haiku is unavailable).
   */
  async extractFromMessage(
    workspaceId: string,
    messageContent: string,
    workspacePath?: string | null
  ): Promise<number> {
    if (messageContent.length < 20) return 0

    // Try Haiku extraction first
    try {
      const prompt = buildExtractionPrompt(
        `## Chat Message\n${messageContent.substring(0, 8000)}`
      )
      const result = await this.spawnSummarizer(prompt, workspacePath ?? undefined, workspaceId)
      const facts = parseExtractedFacts(result)

      let created = 0
      for (const fact of facts) {
        await memoryEngineService.writeFact({
          workspaceId,
          category: fact.category,
          title: fact.title,
          content: fact.content,
          tags: fact.tags,
          scopePaths: fact.scopePaths,
          sourceType: 'manual',
          sourceRef: null,
          workspacePath
        })
        created++
      }
      return created
    } catch {
      // Deterministic fallback: save as-is
      const title = messageContent.slice(0, 100).replace(/\n/g, ' ').trim()
      await memoryEngineService.writeFact({
        workspaceId,
        category: 'reference',
        title,
        content: messageContent.slice(0, 2000),
        sourceType: 'manual',
        sourceRef: null,
        workspacePath
      })
      return 1
    }
  }

  // ── CLAUDE.md regeneration (retained from memory-feed.service.ts) ──────

  async regenerateClaudeMd(
    workspacePath: string,
    onProgress?: ProgressCallback
  ): Promise<{ success: boolean; content: string; error?: string }> {
    if (this.isBusy) {
      return { success: false, content: '', error: 'An extraction is already in progress' }
    }

    this.isBusy = true
    try {
      onProgress?.({ source: 'document', status: 'running', message: 'Gathering project sources...' })

      const keyFiles = this.readKeyFiles(workspacePath)
      const treeListing = this.getTreeListing(workspacePath)

      let agents: DiscoveredAgent[] = []
      let skills: DiscoveredSkill[] = []
      try {
        const { workspaceDeployService } = await import('./workspace-deploy.service')
        agents = workspaceDeployService.scanWorkspaceAgents(workspacePath)
        skills = workspaceDeployService.scanWorkspaceSkills(workspacePath)
      } catch (err) {
        log.warn('Failed to scan agents/skills for CLAUDE.md:', err)
      }

      let existingClaudeMd: string | null = null
      try {
        existingClaudeMd = readFileSync(join(workspacePath, 'CLAUDE.md'), 'utf-8')
      } catch { /* none */ }

      let schemaContent: string | null = null
      try {
        schemaContent = readFileSync(join(workspacePath, 'src/main/db/schema.sql'), 'utf-8')?.substring(0, 5000)
      } catch { /* none */ }

      onProgress?.({ source: 'document', status: 'running', message: 'Generating CLAUDE.md...' })

      const prompt = buildRegeneratePrompt({ keyFiles, treeListing, agents, skills, existingClaudeMd, schemaContent })
      // B2: Intentionally passes only workspacePath (no workspaceId) — regenerateClaudeMd
      // always uses the Claude CLI path because CLAUDE.md generation is a large-context task
      // ill-suited to the 10s local one-shot timeout.
      const content = await this.spawnSummarizer(prompt, workspacePath)

      onProgress?.({ source: 'document', status: 'done', message: 'CLAUDE.md generated' })
      return { success: true, content }
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err)
      log.error('Failed to regenerate CLAUDE.md:', msg)
      onProgress?.({ source: 'document', status: 'error', message: msg })
      return { success: false, content: '', error: msg }
    } finally {
      this.isBusy = false
    }
  }

  // ── CLAUDE.md agentic regeneration ─────────────────────────────────────

  /**
   * Regenerate CLAUDE.md using an agentic Claude session that explores
   * the project with read-only tools + code-graph MCP.
   *
   * The agent reads the existing CLAUDE.md (if any), explores the codebase,
   * and emits the complete CLAUDE.md between sentinel markers.
   */
  async regenerateClaudeMdAgentic(
    workspacePath: string,
    workspaceId: string,
    onProgress?: ProgressCallback
  ): Promise<{ success: boolean; content: string; error?: string }> {
    if (this.isBusy) {
      return { success: false, content: '', error: 'An extraction is already in progress' }
    }

    this.isBusy = true
    try {
      onProgress?.({ source: 'document', status: 'running', message: 'Starting agentic CLAUDE.md generation...' })

      // Read existing CLAUDE.md for context
      let existingClaudeMd = ''
      try {
        existingClaudeMd = readFileSync(join(workspacePath, 'CLAUDE.md'), 'utf-8')
      } catch { /* none */ }

      const prompt = buildAgenticClaudeMdPrompt(existingClaudeMd)

      onProgress?.({ source: 'document', status: 'running', message: 'Agent exploring project...' })

      const allowedTools = [
        'Read', 'Grep', 'Glob',
        ...MCP_TOOLS.CODE_GRAPH._ALL_NAMES
      ]

      const result = await runAgenticClaude({
        workspaceId,
        workspacePath,
        prompt,
        allowedTools,
        model: 'claude-sonnet-4-6',
        maxTurns: 25,
        timeoutMs: 8 * 60 * 1000, // 8 minutes
        mcpServers: ['code-graph'], // No memory tools for CLAUDE.md gen
        onLine: (line) => {
          // Surface progress to the UI
          if (line.length > 10 && !line.startsWith(SENTINELS.BEGIN) && !line.startsWith(SENTINELS.END)) {
            onProgress?.({ source: 'document', status: 'running', message: `Agent: ${line.substring(0, 100)}` })
          }
        }
      })

      // Parse sentinel block
      const sentinelContent = parseSentinelBlock(result.stdout)
      if (sentinelContent && sentinelContent.length > 50) {
        onProgress?.({ source: 'document', status: 'done', message: 'CLAUDE.md generated' })
        return { success: true, content: sentinelContent }
      }

      // Fallback: use trimmed stdout if sentinels are missing
      const trimmed = result.stdout.trim()
      if (trimmed.length > 50) {
        log.warn('[regenerateClaudeMdAgentic] Sentinels missing — falling back to full stdout')
        onProgress?.({ source: 'document', status: 'done', message: 'CLAUDE.md generated (no sentinels)' })
        return { success: true, content: trimmed }
      }

      // Empty output
      const errorMsg = result.exitCode !== 0
        ? `Claude CLI exited with code ${result.exitCode}`
        : 'Agent produced no output'
      log.error(`[regenerateClaudeMdAgentic] Failed: ${errorMsg}`)
      onProgress?.({ source: 'document', status: 'error', message: errorMsg })
      return { success: false, content: '', error: errorMsg }
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err)
      log.error('[regenerateClaudeMdAgentic] Error:', msg)
      onProgress?.({ source: 'document', status: 'error', message: msg })
      return { success: false, content: '', error: msg }
    } finally {
      this.isBusy = false
    }
  }

  // ── Internals ───────────────────────────────────────────────────────────

  private async spawnSummarizer(prompt: string, workspacePath?: string, workspaceId?: string): Promise<string> {
    // G5: Gate memoryFeed through resolveAssignment — route to local LLM when assigned
    // A2: Guard workspacePath — null paths fall through to the Claude CLI path below
    if (workspaceId && workspacePath) {
      const assignment = resolveAssignment({ action: 'memoryFeed', ...buildResolveOpts(workspaceId) })
      if (assignment.provider === 'local-llm') {
        // A3: Local path does not wire this.currentAbortController — bounded by
        // runOneShotLocal's internal 10s timeout (LOCAL_REQUEST_TIMEOUT_MS).
        const localCfg = modelConfigService.getLocalLLMConfig(workspacePath)
        const result = await runOneShotLocal({
          systemPrompt: 'You are a knowledge extraction engine. Follow the instructions exactly.',
          userMessage: prompt,
          baseUrl: modelConfigService.getLocalBaseUrl(localCfg),
          model: assignment.modelId,
          apiKey: localCfg.localApiKey,
          feature: 'memory_feed',
          workspaceId,
          maxTokens: 4096,
          claudeFallbackArgs: buildMemoryFeedFallbackArgs(prompt),
          claudeFallbackModel: DEFAULT_MODEL_CONFIG.memoryFeed
        })
        return result.text
      }
    }

    return new Promise((resolve, reject) => {
      this.currentAbortController = new AbortController()
      const { signal } = this.currentAbortController

      const TIMEOUT_MS = 5 * 60 * 1000
      const timer = setTimeout(() => {
        log.warn('Extraction summarizer timed out after 5 minutes')
        this.currentAbortController?.abort()
      }, TIMEOUT_MS)

      const env = buildEnvWithPath()

      const model = modelConfigService.getModel(workspacePath ?? undefined, 'memoryFeed')

      const child = spawn(
        'claude',
        ['-p', prompt, '--model', model, '--output-format', 'text', '--permission-mode', 'plan'],
        { stdio: ['ignore', 'pipe', 'pipe'], env, signal }
      )

      log.info(`Extraction summarizer spawned (prompt length: ${prompt.length} chars)`)

      let stdout = ''
      let stderr = ''
      const MAX_OUTPUT = 2 * 1024 * 1024

      child.stdout?.on('data', (data: Buffer) => {
        if (stdout.length < MAX_OUTPUT) stdout += data.toString().slice(0, MAX_OUTPUT - stdout.length)
      })
      child.stderr?.on('data', (data: Buffer) => {
        const chunk = data.toString()
        if (stderr.length < MAX_OUTPUT) stderr += chunk.slice(0, MAX_OUTPUT - stderr.length)
        log.debug(`Extraction stderr: ${chunk.slice(0, 200)}`)
      })

      child.on('exit', (code) => {
        clearTimeout(timer)
        this.currentAbortController = null
        if (code === 0 && stdout.trim()) {
          resolve(stdout.trim())
        } else {
          const details = stderr.trim() || (stdout.trim() ? `Unexpected: ${stdout.slice(0, 200)}` : 'No output')
          reject(new Error(`Extraction failed (exit ${code}): ${details}`))
        }
      })

      child.on('error', (err) => {
        clearTimeout(timer)
        this.currentAbortController = null
        reject(new Error(`Failed to spawn extraction summarizer: ${err.message}`))
      })
    })
  }

  private readKeyFiles(workspacePath: string): string {
    const keyFileNames = ['package.json', 'tsconfig.json', 'electron-builder.yml', 'CLAUDE.md']
    const sections: string[] = []
    for (const name of keyFileNames) {
      const filePath = join(workspacePath, name)
      try {
        if (existsSync(filePath)) {
          const content = readFileSync(filePath, 'utf-8')
          sections.push(`### ${name}\n\`\`\`\n${content.substring(0, 5000)}\n\`\`\``)
        }
      } catch { /* skip */ }
    }
    return sections.join('\n\n')
  }

  private getTreeListing(workspacePath: string, depth = 3): string {
    const lines: string[] = []
    const ignored = new Set(['node_modules', '.git', 'dist', 'out', 'build', '.next', '.cache', 'coverage', '.idea', '.vscode', '__pycache__', '.DS_Store'])

    const walk = (dir: string, prefix: string, currentDepth: number): void => {
      if (currentDepth > depth) return
      try {
        const entries = readdirSync(dir).filter((e) => !ignored.has(e)).sort()
        for (const entry of entries) {
          const fullPath = join(dir, entry)
          try {
            const stat = statSync(fullPath)
            if (stat.isDirectory()) {
              lines.push(`${prefix}${entry}/`)
              walk(fullPath, prefix + '  ', currentDepth + 1)
            } else {
              lines.push(`${prefix}${entry}`)
            }
          } catch { /* skip */ }
        }
      } catch { /* skip */ }
    }

    walk(workspacePath, '', 0)
    return lines.slice(0, 200).join('\n')
  }

  shutdown(): void {
    if (this.currentAbortController) {
      this.currentAbortController.abort()
      this.currentAbortController = null
    }
    this.isBusy = false
  }
}

// ── Extraction prompt ─────────────────────────────────────────────────────────

const VALID_CATEGORIES: MemoryFactCategory[] = ['decision', 'convention', 'gotcha', 'preference', 'reference']

/** Max facts to accept from a single extraction call. */
const MAX_EXTRACTED_FACTS = 3

function buildExtractionPrompt(source: string): string {
  return `You are a knowledge extraction engine. Analyze the following source material and extract ONLY the most durable, high-value facts.

For each fact, output a JSON object on its own line:
- "category": one of "decision", "convention", "gotcha", "preference", "reference"
  - decision: architectural choices, tech stack selections, design patterns chosen
  - convention: coding style rules, naming patterns, file organization rules
  - gotcha: surprising behaviors, known bugs, non-obvious constraints
  - preference: user preferences, workflow choices, tool configurations
  - reference: documentation links, API endpoints, configuration values
- "title": short descriptive title (5-15 words)
- "content": the extracted knowledge (1-3 sentences, precise and actionable)
- "tags": array of relevant tags
- "scopePaths": array of file/directory paths this fact relates to (optional)

Strictness rules:
- Output ONLY valid JSON objects, one per line. No markdown, no explanation.
- MAXIMUM 3 facts. Fewer is better — only extract what’s genuinely durable.
- Skip version numbers, schema versions, dependency versions — these change frequently.
- Skip things trivially discoverable from a single file read (imports, file structure).
- Skip facts that restate what the code already says ("X uses Y" when X imports Y).
- Focus on WHY decisions were made, non-obvious constraints, and cross-cutting patterns.
- Each fact must be self-contained — useful without reading the source material.
- Prefer conventions that span multiple files over single-file observations.

Source material:
${source}`
}

/** Parse Haiku output: one JSON fact per line. */
function parseExtractedFacts(text: string): ExtractedFact[] {
  const facts: ExtractedFact[] = []
  const lines = text.split('\n').filter((l) => l.trim().startsWith('{'))

  for (const line of lines) {
    try {
      const data = JSON.parse(line.trim())
      if (!data.category || !data.title || !data.content) continue
      if (!VALID_CATEGORIES.includes(data.category)) continue

      facts.push({
        category: data.category,
        title: String(data.title).slice(0, 200),
        content: String(data.content).slice(0, 2000),
        tags: Array.isArray(data.tags) ? data.tags.map(String).slice(0, 10) : [],
        scopePaths: Array.isArray(data.scopePaths) ? data.scopePaths.map(String).slice(0, 10) : []
      })
    } catch {
      // Skip malformed lines
    }
  }

  // Enforce cap: take only the first MAX_EXTRACTED_FACTS
  return facts.slice(0, MAX_EXTRACTED_FACTS)
}

