/**
 * one-shot-local — OpenAI-compatible HTTP call to a local LLM (oMLX) with
 * automatic Claude fallback on failure.
 *
 * Used for background tasks (memory feed, activation, haiku) when the user
 * configures local models for those roles. Falls back silently to Claude
 * with a warning log when the local server is unreachable or errors.
 *
 * Records usage to the unified usage_log sink.
 */

import log from 'electron-log/main'
import { usageTrackerService } from './usage-tracker.service'
import { runOneShotClaude, type OneShotClaudeOptions } from './one-shot-claude'
import { DEFAULT_MODEL_CONFIG } from '../../shared/constants'

const localLog = log.scope('OneShotLocal')

/** Default timeout for local LLM requests (10s) */
const LOCAL_REQUEST_TIMEOUT_MS = 10_000

/**
 * Build the Claude CLI fallback args for memory-feed one-shot calls.
 * Single source of truth — consumed by spawnSummarizer, spawnClassifier, and tests.
 */
export function buildMemoryFeedFallbackArgs(prompt: string): string[] {
  return [
    '-p', prompt,
    '--model', DEFAULT_MODEL_CONFIG.memoryFeed,
    '--output-format', 'text',
    '--permission-mode', 'plan'
  ]
}

export interface OneShotLocalOptions {
  /** System prompt */
  systemPrompt: string
  /** User message */
  userMessage: string
  /** oMLX/local LLM base URL (e.g., http://127.0.0.1:10434) */
  baseUrl: string
  /** Model name/ID on the local server */
  model: string
  /** Optional API key for authenticated oMLX instances */
  apiKey?: string
  /** Feature bucket for usage_log */
  feature: string
  workspaceId?: string | null
  conversationId?: string | null
  /** Maximum tokens in response */
  maxTokens?: number
  /** Request timeout in ms (default: 10s) */
  timeoutMs?: number
  /** Claude fallback args — used when local call fails */
  claudeFallbackArgs?: string[]
  /** Claude fallback model */
  claudeFallbackModel?: string
}

export interface OneShotLocalResult {
  /** Response text */
  text: string
  /** Which provider actually served the response */
  provider: 'local' | 'claude'
  /** Model used */
  model: string
  /** Whether this was a fallback from a failed local call */
  wasFallback: boolean
}

/**
 * Make an OpenAI-compatible chat completion request to a local LLM.
 * Falls back to Claude on any failure.
 */
export async function runOneShotLocal(opts: OneShotLocalOptions): Promise<OneShotLocalResult> {
  const timeout = opts.timeoutMs ?? LOCAL_REQUEST_TIMEOUT_MS

  try {
    const controller = new AbortController()
    const timer = setTimeout(() => controller.abort(), timeout)

    const headers: Record<string, string> = {
      'Content-Type': 'application/json'
    }
    if (opts.apiKey) {
      headers['Authorization'] = `Bearer ${opts.apiKey}`
    }

    const body = JSON.stringify({
      model: opts.model,
      messages: [
        { role: 'system', content: opts.systemPrompt },
        { role: 'user', content: opts.userMessage }
      ],
      max_tokens: opts.maxTokens ?? 2048,
      stream: false
    })

    const response = await fetch(`${opts.baseUrl}/v1/chat/completions`, {
      method: 'POST',
      headers,
      body,
      signal: controller.signal
    })

    clearTimeout(timer)

    if (!response.ok) {
      throw new Error(`Local LLM returned ${response.status}: ${response.statusText}`)
    }

    const data = (await response.json()) as {
      choices?: Array<{ message?: { content?: string } }>
      usage?: { prompt_tokens?: number; completion_tokens?: number }
    }

    const text = data.choices?.[0]?.message?.content ?? ''
    const inputTokens = data.usage?.prompt_tokens ?? 0
    const outputTokens = data.usage?.completion_tokens ?? 0

    // Record usage
    usageTrackerService.recordUsage({
      feature: opts.feature,
      model: opts.model,
      workspaceId: opts.workspaceId ?? null,
      conversationId: opts.conversationId ?? null,
      tokens: {
        input: inputTokens,
        output: outputTokens,
        cacheRead: 0,
        cacheCreation: 0
      }
    })

    localLog.info(
      `[${opts.feature}] Local LLM success — model=${opts.model} in=${inputTokens} out=${outputTokens}`
    )

    return { text, provider: 'local', model: opts.model, wasFallback: false }
  } catch (err) {
    localLog.warn(
      `[${opts.feature}] Local LLM failed — falling back to Claude:`,
      err instanceof Error ? err.message : String(err)
    )

    // Fall back to Claude
    if (opts.claudeFallbackArgs && opts.claudeFallbackArgs.length > 0) {
      const claudeOpts: OneShotClaudeOptions = {
        args: opts.claudeFallbackArgs,
        feature: opts.feature,
        model: opts.claudeFallbackModel ?? null,
        workspaceId: opts.workspaceId,
        conversationId: opts.conversationId
      }

      const result = await runOneShotClaude(claudeOpts)
      return {
        text: result.text,
        provider: 'claude',
        model: result.model ?? 'claude-haiku-4-5-20251001',
        wasFallback: true
      }
    }

    // No fallback configured — return empty with warning
    return {
      text: '',
      provider: 'local',
      model: opts.model,
      wasFallback: false
    }
  }
}

/**
 * one-shot-claude — unified wrapper around a single `claude -p` CLI call that
 * captures token usage into the unified `usage_log` sink.
 *
 * It runs the CLI with `--output-format json` (instead of `text`), parses the
 * single JSON result object for the response text + token usage + model + cost,
 * records the usage via usageTrackerService, and returns the text so existing
 * callers keep working with a one-line change.
 */

import log from 'electron-log/main'
import { runClaudeCliOneShot, type ClaudeOneShotOptions } from './claude-cli-oneshot'
import { usageTrackerService } from './usage-tracker.service'
import { estimateCostCents } from './cost-tracker.service'

const oneShotLog = log.scope('OneShotClaude')

export interface OneShotUsage {
  input: number
  output: number
  cacheRead: number
  cacheCreation: number
}

export interface OneShotClaudeResult {
  /** The response text (the CLI's `result` field, or raw stdout on parse failure). */
  text: string
  /** Token usage extracted from the JSON result (zeros when unavailable). */
  usage: OneShotUsage
  /** Resolved model (caller-provided, else parsed from JSON, else null). */
  model: string | null
  /** Estimated cost in cents. */
  costCents: number
}

export interface OneShotClaudeOptions {
  /** CLI args (caller-built). Any existing `--output-format <val>` is replaced with json. */
  args: string[]
  /** Feature bucket for usage_log (condense|goal_decompose|grill_plan|...). */
  feature: string
  /** ACTUAL resolved model. Recorded with usage and used for cost estimation. */
  model?: string | null
  workspaceId?: string | null
  conversationId?: string | null
  /** execFile options (timeout/cwd/maxBuffer). */
  cli?: ClaudeOneShotOptions
  /** Test seam — overrides the CLI runner. Defaults to runClaudeCliOneShot. */
  _runner?: (args: string[], opts?: ClaudeOneShotOptions) => Promise<string>
}

/** Force `--output-format json`, replacing any caller-supplied output format. */
function withJsonOutputFormat(args: string[]): string[] {
  const out: string[] = []
  for (let i = 0; i < args.length; i++) {
    if (args[i] === '--output-format') {
      i++ // skip the format value too
      continue
    }
    out.push(args[i])
  }
  out.push('--output-format', 'json')
  return out
}

interface ParsedOneShot {
  text: string
  usage: OneShotUsage
  model: string | null
  totalCostUsd: number | null
}

/**
 * Parse the JSON produced by `claude -p --output-format json`. The result is a
 * single object: `{ result, usage: { input_tokens, output_tokens,
 * cache_read_input_tokens, cache_creation_input_tokens }, total_cost_usd,
 * modelUsage }`. Returns null when stdout is not valid JSON.
 */
export function parseOneShotResult(stdout: string): ParsedOneShot | null {
  let parsed: Record<string, unknown>
  try {
    parsed = JSON.parse(stdout.trim()) as Record<string, unknown>
  } catch {
    return null
  }

  const result = typeof parsed.result === 'string' ? parsed.result : ''
  const usageObj = (parsed.usage ?? {}) as Record<string, unknown>
  const num = (v: unknown): number => (typeof v === 'number' && Number.isFinite(v) ? v : 0)

  const usage: OneShotUsage = {
    input: num(usageObj.input_tokens),
    output: num(usageObj.output_tokens),
    cacheRead: num(usageObj.cache_read_input_tokens),
    cacheCreation: num(usageObj.cache_creation_input_tokens)
  }

  // Model: top-level `model`, else the first key of `modelUsage`.
  let model: string | null = typeof parsed.model === 'string' ? parsed.model : null
  if (!model && parsed.modelUsage && typeof parsed.modelUsage === 'object') {
    const keys = Object.keys(parsed.modelUsage as Record<string, unknown>)
    if (keys.length > 0) model = keys[0]
  }

  const totalCostUsd =
    typeof parsed.total_cost_usd === 'number' && Number.isFinite(parsed.total_cost_usd)
      ? parsed.total_cost_usd
      : null

  return { text: result, usage, model, totalCostUsd }
}

/**
 * Run a one-shot `claude` call, record its token usage to the unified
 * usage_log, and return the response text + usage.
 *
 * Usage logging never breaks the call — recording failures are swallowed by
 * usageTrackerService, and a JSON parse failure falls back to returning the raw
 * stdout (no usage recorded).
 */
export async function runOneShotClaude(opts: OneShotClaudeOptions): Promise<OneShotClaudeResult> {
  const runner = opts._runner ?? runClaudeCliOneShot
  const stdout = await runner(withJsonOutputFormat(opts.args), opts.cli)

  const parsed = parseOneShotResult(stdout)

  if (!parsed) {
    oneShotLog.warn(
      `[${opts.feature}] Could not parse JSON result — returning raw stdout, usage not recorded`
    )
    return {
      text: stdout,
      usage: { input: 0, output: 0, cacheRead: 0, cacheCreation: 0 },
      model: opts.model ?? null,
      costCents: 0
    }
  }

  const model = opts.model ?? parsed.model
  const costCents =
    parsed.totalCostUsd != null
      ? Math.round(parsed.totalCostUsd * 100)
      : estimateCostCents(parsed.usage.input, parsed.usage.output, model ?? undefined)

  usageTrackerService.recordUsage({
    feature: opts.feature,
    model: model ?? null,
    workspaceId: opts.workspaceId ?? null,
    conversationId: opts.conversationId ?? null,
    tokens: parsed.usage
  })

  return { text: parsed.text, usage: parsed.usage, model: model ?? null, costCents }
}

import { execFile } from 'node:child_process'
import { buildEnvWithPath } from './env-utils'

export interface ClaudeOneShotOptions {
  timeout?: number
  maxBuffer?: number
  cwd?: string
}

const DEFAULT_TIMEOUT = 180_000
const DEFAULT_MAX_BUFFER = 1024 * 1024 * 10 // 10MB

/**
 * Run a binary in one-shot mode and resolve stdout. Closes the child's stdin
 * immediately (EOF, equivalent to `< /dev/null`) so the Claude CLI does not
 * block ~3s on its empty stdin pipe and intermittently exit non-zero. Surfaces
 * stderr in the rejection message for diagnostics. `binary` param exists for
 * testability; production calls use runClaudeCliOneShot.
 */
export function runCliOneShot(
  binary: string,
  args: string[],
  opts: ClaudeOneShotOptions = {}
): Promise<string> {
  return new Promise((resolve, reject) => {
    const child = execFile(
      binary,
      args,
      {
        encoding: 'utf-8',
        timeout: opts.timeout ?? DEFAULT_TIMEOUT,
        maxBuffer: opts.maxBuffer ?? DEFAULT_MAX_BUFFER,
        cwd: opts.cwd,
        env: buildEnvWithPath()
      },
      (err, stdout, stderr) => {
        if (err) {
          const sErr = stderr?.trim() || ''
          if ((err as NodeJS.ErrnoException & { killed?: boolean }).killed) {
            const secs = Math.round((opts.timeout ?? DEFAULT_TIMEOUT) / 1000)
            reject(new Error(`CLI timed out after ${secs}s${sErr ? `\n${sErr}` : ''}`))
            return
          }
          reject(new Error(`${err.message}${sErr ? `\n${sErr}` : ''}`))
          return
        }
        resolve(stdout)
      }
    )
    child.stdin?.end() // EOF — eliminates the CLI's 3s stdin wait
  })
}

export function runClaudeCliOneShot(args: string[], opts?: ClaudeOneShotOptions): Promise<string> {
  return runCliOneShot('claude', args, opts)
}

/**
 * agentic-claude-runner.ts — Shared helper to spawn Claude CLI as an agentic sub-process.
 *
 * Used by:
 *   - Deep Scan (memory-bootstrap.service.ts) — agent-driven codebase exploration
 *   - CLAUDE.md regeneration (memory-extraction.service.ts) — agentic file generation
 *
 * Responsibilities:
 *   1. Write a minimal MCP config (memory + code-graph servers only) to a temp file
 *   2. Spawn `claude` CLI with --mcp-config, --permission-mode bypassPermissions,
 *      and a strict --allowedTools whitelist (read + MCP only; no Write/Edit)
 *   3. Stream stdout lines to an optional callback; honor AbortSignal
 *   4. Clean up the temp config in a `finally` block
 */

import { spawn, type ChildProcess } from 'node:child_process'
import { writeFileSync, unlinkSync, mkdirSync, existsSync } from 'node:fs'
import { join } from 'node:path'
import { tmpdir } from 'node:os'
import { app } from 'electron'
import log from 'electron-log'
import { buildEnvWithPath } from './env-utils'

const runnerLog = log.scope('agentic-runner')

// ── Constants ────────────────────────────────────────────────────────────────

/** Sentinel markers for structured output extraction. */
export const SENTINELS = {
  BEGIN: '===CLAUDE_MD_BEGIN===',
  END: '===CLAUDE_MD_END==='
} as const

// ── Types ────────────────────────────────────────────────────────────────────

export interface AgenticRunnerOptions {
  /** Workspace ID — used in MCP server env vars. */
  workspaceId: string
  /** Absolute path to the workspace root. */
  workspacePath: string
  /** The prompt to pass to `claude -p`. */
  prompt: string
  /** Allowed tool names (Claude CLI --allowedTools format). */
  allowedTools: string[]
  /** Claude model to use. */
  model: string
  /** Max agentic turns (default 30). */
  maxTurns?: number
  /** Overall timeout in ms (default 10 min). */
  timeoutMs?: number
  /** AbortSignal for external cancellation. */
  signal?: AbortSignal
  /** Optional callback for stdout line streaming. */
  onLine?: (line: string) => void
  /**
   * Which MCP servers to include (default: ['memory', 'code-graph']).
   * Pass a subset to omit servers the task doesn't need.
   */
  mcpServers?: Array<'memory' | 'code-graph'>
}

export interface AgenticRunnerResult {
  stdout: string
  exitCode: number | null
}

// ── MCP Config Builder ───────────────────────────────────────────────────────

interface McpServerEntry {
  command: string
  args: string[]
  env: Record<string, string>
}

/**
 * Build a minimal MCP config object with only the servers the agentic task needs.
 * Reuses the same packaged-vs-dev `serverBasePath` logic from cli-mcp-config-writer.ts.
 */
export function buildMinimalMcpConfig(
  workspaceId: string,
  workspacePath: string,
  servers: Array<'memory' | 'code-graph'> = ['memory', 'code-graph']
): { mcpServers: Record<string, McpServerEntry> } {
  const serverBasePath = app.isPackaged
    ? join(
        app.getAppPath().replace('app.asar', 'app.asar.unpacked'),
        'out',
        'main',
        'mcp-servers'
      )
    : join(__dirname, 'mcp-servers')

  const dbDir = app.getPath('userData')
  const mcpServers: Record<string, McpServerEntry> = {}

  if (servers.includes('code-graph')) {
    mcpServers['code-graph'] = {
      command: 'node',
      args: [join(serverBasePath, 'code-graph-server.js')],
      env: {
        WORKSPACE_ID: workspaceId,
        WORKSPACE_PATH: workspacePath,
        DB_PATH: dbDir
      }
    }
  }

  if (servers.includes('memory')) {
    mcpServers['memory'] = {
      command: 'node',
      args: [join(serverBasePath, 'memory-server.js')],
      env: {
        WORKSPACE_ID: workspaceId,
        DB_PATH: dbDir
      }
    }
  }

  return { mcpServers }
}

// ── Sentinel Parsing ─────────────────────────────────────────────────────────

/**
 * Extract content between sentinel markers from stdout.
 * Returns the inner content if found, or null if sentinels are missing.
 */
export function parseSentinelBlock(stdout: string): string | null {
  const beginIdx = stdout.indexOf(SENTINELS.BEGIN)
  const endIdx = stdout.indexOf(SENTINELS.END)

  if (beginIdx === -1 || endIdx === -1 || endIdx <= beginIdx) {
    return null
  }

  return stdout.substring(beginIdx + SENTINELS.BEGIN.length, endIdx).trim()
}

// ── Runner ───────────────────────────────────────────────────────────────────

/**
 * Spawn Claude CLI as an agentic sub-process with a minimal MCP config
 * and a strict read-only tool whitelist.
 */
export async function runAgenticClaude(opts: AgenticRunnerOptions): Promise<AgenticRunnerResult> {
  const {
    workspaceId,
    workspacePath,
    prompt,
    allowedTools,
    model,
    maxTurns = 30,
    timeoutMs = 10 * 60 * 1000,
    signal,
    onLine,
    mcpServers = ['memory', 'code-graph']
  } = opts

  // ── Write temp MCP config ──
  const tempDir = join(tmpdir(), 'agent-studio-agentic', workspaceId.slice(0, 16))
  if (!existsSync(tempDir)) {
    mkdirSync(tempDir, { recursive: true })
  }
  const configPath = join(tempDir, `mcp-config-${Date.now()}.json`)
  const mcpConfig = buildMinimalMcpConfig(workspaceId, workspacePath, mcpServers)

  writeFileSync(configPath, JSON.stringify(mcpConfig, null, 2), 'utf-8')
  runnerLog.info(`[runAgenticClaude] MCP config written: ${configPath} (servers: ${Object.keys(mcpConfig.mcpServers).join(', ')})`)

  try {
    return await spawnClaudeProcess({
      configPath,
      prompt,
      allowedTools,
      model,
      maxTurns,
      timeoutMs,
      workspacePath,
      signal,
      onLine
    })
  } finally {
    // Clean up temp config
    try {
      unlinkSync(configPath)
    } catch {
      /* file may already be gone */
    }
  }
}

// ── Internal spawn ───────────────────────────────────────────────────────────

interface SpawnOptions {
  configPath: string
  prompt: string
  allowedTools: string[]
  model: string
  maxTurns: number
  timeoutMs: number
  workspacePath: string
  signal?: AbortSignal
  onLine?: (line: string) => void
}

function spawnClaudeProcess(opts: SpawnOptions): Promise<AgenticRunnerResult> {
  const { configPath, prompt, allowedTools, model, maxTurns, timeoutMs, workspacePath, signal, onLine } = opts

  return new Promise<AgenticRunnerResult>((resolve, reject) => {
    // Check abort before spawning
    if (signal?.aborted) {
      reject(new Error('Agentic run cancelled before start'))
      return
    }

    const args = buildClaudeArgs({ configPath, prompt, allowedTools, model, maxTurns })

    const env = {
      ...buildEnvWithPath(),
      MCP_TIMEOUT: '30000'
    }

    const child: ChildProcess = spawn('claude', args, {
      cwd: workspacePath,
      stdio: ['pipe', 'pipe', 'pipe'],
      env
    })

    runnerLog.info(`[runAgenticClaude] Spawned claude (model=${model}, maxTurns=${maxTurns}, allowedTools=${allowedTools.length})`)

    let stdout = ''
    let lineBuffer = ''

    child.stdout?.on('data', (chunk: Buffer) => {
      const text = chunk.toString()
      stdout += text

      // Stream lines to callback
      if (onLine) {
        lineBuffer += text
        const lines = lineBuffer.split('\n')
        // Keep the last partial line in the buffer
        lineBuffer = lines.pop() ?? ''
        for (const line of lines) {
          const trimmed = line.trim()
          if (trimmed.length > 0) {
            onLine(trimmed)
          }
        }
      }
    })

    child.stderr?.on('data', (chunk: Buffer) => {
      const text = chunk.toString().trim()
      if (text) {
        runnerLog.info(`[agentic:stderr] ${text.substring(0, 300)}`)
      }
    })

    // ── Timeout ──
    const timer = setTimeout(() => {
      runnerLog.warn(`[runAgenticClaude] Timed out after ${timeoutMs}ms — killing process`)
      child.kill('SIGTERM')
    }, timeoutMs)

    // ── Abort handling ──
    const onAbort = (): void => {
      child.kill('SIGTERM')
    }
    if (signal) {
      signal.addEventListener('abort', onAbort, { once: true })
    }

    child.on('close', (code) => {
      clearTimeout(timer)
      signal?.removeEventListener('abort', onAbort)

      // Flush remaining buffer
      if (onLine && lineBuffer.trim()) {
        onLine(lineBuffer.trim())
      }

      if (signal?.aborted) {
        reject(new Error('Agentic run cancelled'))
        return
      }

      resolve({ stdout, exitCode: code })
    })

    child.on('error', (err) => {
      clearTimeout(timer)
      signal?.removeEventListener('abort', onAbort)
      reject(new Error(`Failed to spawn claude CLI: ${err.message}`))
    })
  })
}

