interface QueueItem {
  operation: () => Promise<void>
  resolve: () => void
  reject: (err: Error) => void
}

/**
 * Tier 1/2/3 structure for progressive skill loading.
 * - Tier 1: ~50 tokens — name, description, activation keywords (JSON)
 * - Tier 2: ~500 tokens — core instructions, decision rules, approach guidance
 * - Tier 3: Full content — stored as-is in the skill file
 */
export interface SkillTiers {
  /** JSON-serialized: { name, description, keywords } */
  tier1Json: string
  /** Core instructions extracted from first meaningful section */
  tier2Instructions: string
}

/**
 * Parses a SKILL.md file into 3 tiers for progressive loading.
 *
 * Tier 1 (metadata): name + description + activation keywords (~50 tokens)
 * Tier 2 (core instructions): first section after the title (~500 tokens)
 * Tier 3 (full content): the entire file (stored on disk, not duplicated in DB)
 *
 * Keywords are extracted from:
 * 1. Explicit "Keywords:" or "Trigger terms:" lines in the file
 * 2. Heading text (## sections)
 * 3. Bold terms in the first section
 */
export function parseSkillTiers(name: string, description: string, content: string): SkillTiers {
  // ── Extract keywords ──
  const keywords = new Set<string>()

  // From explicit keyword/trigger lines
  const keywordLineMatch = content.match(
    /(?:keywords?|trigger\s*terms?|activation\s*(?:keywords?|terms?)):\s*([^\n]+)/i
  )
  if (keywordLineMatch) {
    keywordLineMatch[1]
      .split(/[,;]+/)
      .map((k) => k.trim().toLowerCase())
      .filter((k) => k.length > 2)
      .forEach((k) => keywords.add(k))
  }

  // From name (split on spaces/hyphens)
  name
    .toLowerCase()
    .replace(/[^a-z0-9\s-]/g, '')
    .split(/[\s-]+/)
    .filter((w) => w.length > 2)
    .forEach((w) => keywords.add(w))

  // From ## headings
  const headings = content.match(/^## .+$/gm) || []
  for (const heading of headings) {
    heading
      .replace(/^## /, '')
      .toLowerCase()
      .replace(/[^a-z0-9\s-]/g, '')
      .split(/[\s-]+/)
      .filter(
        (w) =>
          w.length > 2 && !['the', 'and', 'for', 'not', 'with', 'how', 'what', 'when'].includes(w)
      )
      .forEach((w) => keywords.add(w))
  }

  // From **bold** terms in first 2000 chars
  const boldMatches = content.substring(0, 2000).match(/\*\*([^*]+)\*\*/g) || []
  for (const bold of boldMatches) {
    bold
      .replace(/\*\*/g, '')
      .toLowerCase()
      .split(/[\s-]+/)
      .filter((w) => w.length > 2)
      .forEach((w) => keywords.add(w))
  }

  const tier1 = JSON.stringify({
    name,
    description: description.substring(0, 200),
    keywords: Array.from(keywords).slice(0, 30) // cap at 30 keywords
  })

  // ── Extract Tier 2: core instructions ──
  // Strategy: Take content between the title/preamble and the second ## heading,
  // capped at ~2000 chars. This captures the "core instructions" section.
  const lines = content.split('\n')
  let tier2Start = 0
  let tier2End = lines.length
  let foundFirstHeading = false

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i]
    if (line.startsWith('# ') && !foundFirstHeading) {
      tier2Start = i + 1
      foundFirstHeading = true
      continue
    }
    if (line.startsWith('## ') && foundFirstHeading) {
      // Include content up to the SECOND ## heading (first real section)
      // Find the NEXT ## heading after this one
      for (let j = i + 1; j < lines.length; j++) {
        if (lines[j].startsWith('## ')) {
          tier2End = j
          break
        }
      }
      // If we found a section, include up to the next heading
      if (tier2End === lines.length) {
        tier2End = Math.min(lines.length, i + 40) // cap at ~40 lines for the section
      }
      break
    }
  }

  let tier2 = lines.slice(tier2Start, tier2End).join('\n').trim()

  // Cap Tier 2 at ~2000 chars
  if (tier2.length > 2000) {
    tier2 = tier2.substring(0, 2000) + '\n\n[... see full skill for details]'
  }

  // If tier2 is empty, use description
  if (!tier2) {
    tier2 = description
  }

  return { tier1Json: tier1, tier2Instructions: tier2 }
}

export class SkillService {
  private queue: QueueItem[] = []
  private processing = false
  private currentAbortController: AbortController | null = null

  /** Returns the .claude/skills/ folder path (Claude Code standard location) */
  private getSkillsDir(): string {
    // In development, use the project root; in production, use app resources
    const isDev = !app.isPackaged
    if (isDev) {
      return join(process.cwd(), '.claude', 'skills')
    }
    return join(app.getPath('userData'), '.claude', 'skills')
  }

  /** Returns the CLAUDE.md path at the project root */
  private getClaudeMdPath(): string {
    const isDev = !app.isPackaged
    if (isDev) {
      return join(process.cwd(), 'CLAUDE.md')
    }
    return join(app.getPath('userData'), 'CLAUDE.md')
  }

  // ── File Validation ──
  validateSkillFile(filePath: string): { valid: boolean; error?: string; lastUpdated?: string } {
    if (!existsSync(filePath)) {
      return { valid: false, error: 'File not found' }
    }

    try {
      const stats = statSync(filePath)
      if (stats.size > SKILL_MAX_FILE_SIZE_BYTES) {
        return {
          valid: false,
          error: `File too large: ${(stats.size / 1024).toFixed(1)} KB (max ${SKILL_MAX_FILE_SIZE_BYTES / 1024} KB)`
        }
      }
    } catch {
      return { valid: false, error: 'Cannot access file' }
    }

    const content = readFileSync(filePath, 'utf-8')

    // Check for required "Last updated: YYYY-MM-DD" field
    const dateMatch = content.match(/Last updated:\s*(\d{4}-\d{2}-\d{2})/i)
    if (!dateMatch) {
      return {
        valid: false,
        error:
          'Missing required "Last updated: YYYY-MM-DD" field. Skill files must include this date for staleness tracking.'
      }
    }

    // Check for duplicate filename in .claude/skills/ folder
    const filename = basename(filePath)
    const targetPath = join(this.getSkillsDir(), filename)
    if (existsSync(targetPath) && targetPath !== filePath) {
      const existingInDb = skillRepository.findByFilename(filename)
      if (existingInDb) {
        return {
          valid: false,
          error: `A skill file named "${filename}" already exists. Please rename the file before importing.`
        }
      }
    }

    return { valid: true, lastUpdated: dateMatch[1] }
  }

  // ── Import (atomic: copy + DB + Opus) ──
  async importSkill(sourcePath: string): Promise<Skill> {
    const validation = this.validateSkillFile(sourcePath)
    if (!validation.valid) {
      throw new Error(validation.error)
    }

    const filename = basename(sourcePath)
    const skillsDir = this.getSkillsDir()
    const targetPath = join(skillsDir, filename)
    const relPath = `.claude/skills/${filename}`

    // Derive name from filename (remove .md extension, replace hyphens with spaces, title case)
    const name = filename
      .replace(/\.md$/i, '')
      .replace(/[-_]/g, ' ')
      .replace(/\b\w/g, (c) => c.toUpperCase())

    // Read description from file (first paragraph or first 200 chars)
    const content = readFileSync(sourcePath, 'utf-8')
    const descriptionMatch = content.match(/^#[^\n]*\n+([^\n#]+)/)
    const description = descriptionMatch ? descriptionMatch[1].trim().substring(0, 200) : ''

    // Parse skill into tiers for progressive loading
    const tiers = parseSkillTiers(name, description, content)

    let skill: Skill | null = null
    let fileCopied = false

    try {
      // 1. Copy file to .claude/skills/ folder
      copyFileSync(sourcePath, targetPath)
      fileCopied = true

      // 2. Create DB record (active by default) with tier data
      skill = skillRepository.create({
        name,
        description,
        filename,
        filePath: relPath,
        isActive: true,
        lastUpdatedDate: validation.lastUpdated,
        tier1Json: tiers.tier1Json,
        tier2Instructions: tiers.tier2Instructions
      })

      // 3. Trigger Haiku enrichment (non-blocking — skill is usable without it)
      const skillId = skill.id
      void skillEnrichmentService
        .enrichSkill(content, name)
        .then((enrichment) => {
          skillRepository.updateEnrichment(skillId, JSON.stringify(enrichment))
          skillLogger.info(`✓ Skill ${name} enriched with ${enrichment.keywords.length} keywords`)
        })
        .catch((err) => {
          skillLogger.warn(
            `Skill enrichment failed for ${name} — will work without enrichment:`,
            err
          )
        })

      // 4. Trigger Opus CLAUDE.md update for activation
      await this.enqueueAndWait(async () => {
        await this.updateClaudeMd(targetPath, 'activate')
      })

      return skill
    } catch (error) {
      // Rollback: delete copied file and DB record
      if (fileCopied && existsSync(targetPath)) {
        try {
          unlinkSync(targetPath)
        } catch {
          /* ignore cleanup error */
        }
      }
      if (skill) {
        try {
          skillRepository.delete(skill.id)
        } catch {
          /* ignore cleanup error */
        }
      }
      throw error
    }
  }

  // ── Activate ──
  async activateSkill(id: string): Promise<Skill> {
    const skill = skillRepository.findById(id)
    if (!skill) throw new Error(`Skill not found: ${id}`)
    if (skill.isActive) return skill

    const skillsDir = this.getSkillsDir()
    const skillFilePath = join(skillsDir, skill.filename)

    try {
      // Re-parse tiers from disk content (may have changed since initial import)
      try {
        const content = readFileSync(skillFilePath, 'utf-8')
        const tiers = parseSkillTiers(skill.name, skill.description ?? '', content)
        skillRepository.updateTiers(id, tiers.tier1Json, tiers.tier2Instructions)
      } catch (tierErr) {
        skillLogger.warn(`Failed to re-parse tiers for skill ${id}:`, tierErr)
      }

      // Update DB first
      const updated = skillRepository.setActive(id, true)

      // Queue Opus CLAUDE.md update
      await this.enqueueAndWait(async () => {
        await this.updateClaudeMd(skillFilePath, 'activate')
      })

      return updated
    } catch (error) {
      // Rollback: revert to inactive
      try {
        skillRepository.setActive(id, false)
      } catch {
        /* ignore */
      }
      throw error
    }
  }

  // ── Deactivate ──
  async deactivateSkill(id: string): Promise<Skill> {
    const skill = skillRepository.findById(id)
    if (!skill) throw new Error(`Skill not found: ${id}`)
    if (!skill.isActive) return skill

    const skillsDir = this.getSkillsDir()
    const skillFilePath = join(skillsDir, skill.filename)

    try {
      // Update DB first
      const updated = skillRepository.setActive(id, false)

      // Queue Opus CLAUDE.md update
      await this.enqueueAndWait(async () => {
        await this.updateClaudeMd(skillFilePath, 'deactivate')
      })

      return updated
    } catch (error) {
      // Rollback: revert to active
      try {
        skillRepository.setActive(id, true)
      } catch {
        /* ignore */
      }
      throw error
    }
  }

  // ── Opus CLAUDE.md Update ──
  private async updateClaudeMd(
    skillFilePath: string,
    operation: 'activate' | 'deactivate'
  ): Promise<void> {
    const claudeMdPath = this.getClaudeMdPath()

    if (!existsSync(claudeMdPath)) {
      skillLogger.warn('CLAUDE.md not found, skipping update')
      return
    }

    if (!existsSync(skillFilePath)) {
      skillLogger.warn('Skill file not found, skipping CLAUDE.md update:', skillFilePath)
      return
    }

    const claudeMdContent = readFileSync(claudeMdPath, 'utf-8')
    const skillContent = readFileSync(skillFilePath, 'utf-8')
    const skillFilename = basename(skillFilePath)

    const prompt =
      operation === 'activate'
        ? `You are updating a CLAUDE.md file to add references to a newly activated skill file.

Current CLAUDE.md content:
---
${claudeMdContent}
---

New skill file (${skillFilename}):
---
${skillContent}
---

Instructions:
1. Add appropriate references to the skill file in the CLAUDE.md "Skills" section
2. Follow the same format and style as existing skill references in the file
3. Return ONLY the complete updated CLAUDE.md content — no explanations, no code fences
4. Do not remove or modify any existing content unless necessary for the integration`
        : `You are updating a CLAUDE.md file to remove references to a deactivated skill file.

Current CLAUDE.md content:
---
${claudeMdContent}
---

Skill file being deactivated (${skillFilename}):
---
${skillContent}
---

Instructions:
1. Remove all references to the skill file "${skillFilename}" from the CLAUDE.md
2. Remove any skill-specific sections, keywords, or trigger descriptions related to this skill
3. Return ONLY the complete updated CLAUDE.md content — no explanations, no code fences
4. Keep all other content intact`

    const result = await this.spawnOpusCall(prompt)

    // Write atomically
    const tmpPath = claudeMdPath + '.tmp'
    writeFileSync(tmpPath, result, 'utf-8')
    renameSync(tmpPath, claudeMdPath)
  }

  private spawnOpusCall(prompt: string): Promise<string> {
    return new Promise((resolve, reject) => {
      this.currentAbortController = new AbortController()
      const { signal } = this.currentAbortController

      const env = buildEnvWithPath()

      const child = spawn(
        'claude',
        [
          '-p',
          prompt,
          '--model',
          modelConfigService.getModel(undefined, 'activation'),
          '--output-format',
          'text',
          '--permission-mode',
          'plan'
        ],
        {
          stdio: ['ignore', 'pipe', 'pipe'],
          env,
          signal
        }
      )

      skillLogger.info(
        `Opus CLAUDE.md update spawned (no timeout, prompt length: ${prompt.length} chars)`
      )

      let stdout = ''
      let stderr = ''

      child.stdout?.on('data', (data: Buffer) => {
        stdout += data.toString()
      })

      child.stderr?.on('data', (data: Buffer) => {
        stderr += data.toString()
        skillLogger.debug(`Opus stderr: ${data.toString().slice(0, 200)}`)
      })

      // NO TIMEOUT — user can cancel manually via shutdown()

      child.on('exit', (code) => {
        this.currentAbortController = null
        skillLogger.info(
          `Opus exited with code ${code} (stdout: ${stdout.length} chars, stderr: ${stderr.length} chars)`
        )

        if (code === 0 && stdout.trim()) {
          resolve(stdout.trim())
        } else {
          reject(
            new Error(
              `Opus call failed (exit code ${code}): ${stderr.trim() || 'No output received'}`
            )
          )
        }
      })

      child.on('error', (err) => {
        this.currentAbortController = null
        reject(new Error(`Failed to spawn Opus call: ${err.message}`))
      })
    })
  }

  // ── Queue Management ──
  private enqueueAndWait(operation: () => Promise<void>): Promise<void> {
    return new Promise<void>((resolve, reject) => {
      this.queue.push({ operation, resolve, reject })
      this.processQueue()
    })
  }

  private async processQueue(): Promise<void> {
    if (this.processing) return
    this.processing = true

    while (this.queue.length > 0) {
      const item = this.queue.shift()!
      try {
        await item.operation()
        item.resolve()
      } catch (error) {
        item.reject(error instanceof Error ? error : new Error(String(error)))
      }
    }

    this.processing = false
  }

  // ── Shutdown ──
  async shutdown(): Promise<void> {
    // Cancel in-progress Opus call
    if (this.currentAbortController) {
      this.currentAbortController.abort()
      this.currentAbortController = null
    }

    // Discard pending queue
    for (const item of this.queue) {
      item.reject(new Error('Skill service shutting down'))
    }
    this.queue = []
    this.processing = false
  }
}

export const skillService = new SkillService()

/**
 * Skill Enrichment Service — two-stage Haiku enrichment pipeline.
 *
 * **Stage 1 — Import-time enrichment** (runs once per skill, on import):
 * Haiku reads SKILL.md content and produces structured enrichment metadata
 * (keywords, applicableTo, complexity). Stored in `skills.enrichment_json`.
 *
 * **Stage 2 — Build-time recommendations** (runs per specialist when skills change):
 * Haiku receives the project's detected techs, CLAUDE.md excerpt, and all
 * skills' enrichment data → returns a ranked list of skill relevance scores.
 * Stored in `specialists.skill_recommendations_json` alongside a staleness hash.
 */

import { createHash } from 'node:crypto'
import log from 'electron-log'
import { modelConfigService } from './model-config.service'
import { runOneShotClaude } from './one-shot-claude'

const enrichLog = log.scope('skill-enrichment')

// ── Types ────────────────────────────────────────────────────────────────────

export interface SkillEnrichment {
  keywords: string[]
  applicableTo: string
  complexity: 'foundational' | 'intermediate' | 'advanced'
}

export interface SkillRecommendation {
  skillId: string
  relevance: number // 0.0–1.0
  rationale: string // one-line explanation
}

export interface SkillRecommendationsResult {
  reviewedAt: string
  recommendations: SkillRecommendation[]
}

// ── Service ──────────────────────────────────────────────────────────────────

class SkillEnrichmentService {
  /**
   * Stage 1: Generate enrichment for a single skill.
   * Called on import. Uses Haiku via `claude -p`.
   */
  async enrichSkill(skillContent: string, skillName: string): Promise<SkillEnrichment> {
    const truncatedContent = skillContent.slice(0, 3000)
    const prompt = [
      'You are analyzing a development skill file to extract structured metadata.',
      '',
      `SKILL NAME: ${skillName}`,
      'SKILL CONTENT (first 3000 chars):',
      '---',
      truncatedContent,
      '---',
      '',
      'Return ONLY a JSON object with these fields:',
      '- "keywords": array of 3-10 lowercase tech/domain tags this skill covers (e.g. "electron", "ipc", "security", "sqlite", "testing", "react", "css")',
      '- "applicableTo": one sentence describing when this skill should be used (max 120 chars)',
      '- "complexity": one of "foundational", "intermediate", or "advanced"',
      '',
      'JSON only, no fences, no commentary.'
    ].join('\n')

    const raw = await this.invokeHaiku(prompt, 'skill_enrich')
    return this.parseEnrichment(raw)
  }

  /**
   * Stage 2: Generate recommendations for a specialist.
   * Compares all skills' enrichment against the project's detected techs
   * and CLAUDE.md excerpt. Only runs if skills have changed since last review.
   */
  async generateRecommendations(params: {
    specialistId: string
    detectedTechs: string[]
    claudeMdExcerpt: string
    skills: Array<{ id: string; name: string; enrichment: SkillEnrichment | null }>
  }): Promise<SkillRecommendationsResult> {
    const techList =
      params.detectedTechs.length > 0 ? params.detectedTechs.join(', ') : '(none detected)'

    const skillLines = params.skills
      .map((s) => {
        const kw = s.enrichment?.keywords?.join(', ') ?? '(no keywords)'
        const ap = s.enrichment?.applicableTo ?? '(no description)'
        return `- id: "${s.id}", name: "${s.name}", keywords: [${kw}], applicableTo: "${ap}"`
      })
      .join('\n')

    const prompt = [
      'You are selecting which development skills are relevant for a specific project.',
      '',
      `PROJECT STACK: ${techList}`,
      'PROJECT CONTEXT (from CLAUDE.md):',
      '---',
      params.claudeMdExcerpt.slice(0, 2000),
      '---',
      '',
      'AVAILABLE SKILLS:',
      skillLines,
      '',
      'For each skill, assess relevance (0.0-1.0) to THIS project.',
      'Return ONLY a JSON object:',
      '{',
      '  "recommendations": [',
      '    { "skillId": "...", "relevance": 0.95, "rationale": "one sentence why" }',
      '  ]',
      '}',
      '',
      'Only include skills with relevance >= 0.3. Sort by relevance descending.',
      'JSON only, no fences, no commentary.'
    ].join('\n')

    const raw = await this.invokeHaiku(prompt, 'skill_recommend')
    const parsed = this.parseRecommendations(raw)

    return {
      reviewedAt: new Date().toISOString(),
      recommendations: parsed
    }
  }

  /**
   * Check if recommendations are stale (new skills added since last review).
   */
  isStale(currentHash: string, storedHash: string | null): boolean {
    return currentHash !== storedHash
  }

  /**
   * Compute a hash of all skill IDs + their enrichment state for staleness detection.
   */
  computeSkillsHash(skills: Array<{ id: string; enrichmentJson: string | null }>): string {
    const sorted = [...skills].sort((a, b) => a.id.localeCompare(b.id))
    const payload = sorted.map((s) => `${s.id}:${s.enrichmentJson ?? ''}`).join('|')
    return createHash('sha256').update(payload).digest('hex').slice(0, 16)
  }

  // ── Private ──────────────────────────────────────────────────────────────

  private async invokeHaiku(prompt: string, feature: string): Promise<string> {
    const resolvedModel = modelConfigService.getModel(undefined, 'haiku')

    const { text } = await runOneShotClaude({
      feature,
      model: resolvedModel,
      args: ['-p', prompt, '--model', resolvedModel],
      cli: {
        timeout: 30_000
      }
    })
    return text.trim()
  }

  private parseEnrichment(raw: string): SkillEnrichment {
    try {
      // Strip markdown fences if present
      const cleaned = raw.replace(/^```(?:json)?\s*\n?/m, '').replace(/\n?```\s*$/m, '')
      const parsed = JSON.parse(cleaned)

      // Validate + normalise
      const keywords = Array.isArray(parsed.keywords)
        ? parsed.keywords.filter((k: unknown) => typeof k === 'string').slice(0, 10)
        : []

      const applicableTo =
        typeof parsed.applicableTo === 'string'
          ? parsed.applicableTo.slice(0, 120)
          : 'General development skill'

      const validComplexities = ['foundational', 'intermediate', 'advanced'] as const
      const complexity = validComplexities.includes(parsed.complexity)
        ? (parsed.complexity as SkillEnrichment['complexity'])
        : 'intermediate'

      return { keywords, applicableTo, complexity }
    } catch (err) {
      enrichLog.warn('Failed to parse enrichment JSON — returning defaults:', err)
      return {
        keywords: [],
        applicableTo: 'Development skill',
        complexity: 'intermediate'
      }
    }
  }

  private parseRecommendations(raw: string): SkillRecommendation[] {
    try {
      const cleaned = raw.replace(/^```(?:json)?\s*\n?/m, '').replace(/\n?```\s*$/m, '')
      const parsed = JSON.parse(cleaned)
      const recs = Array.isArray(parsed.recommendations) ? parsed.recommendations : []

      return recs
        .filter(
          (r: Record<string, unknown>) =>
            typeof r.skillId === 'string' && typeof r.relevance === 'number' && r.relevance >= 0.3
        )
        .map((r: Record<string, unknown>) => ({
          skillId: r.skillId as string,
          relevance: Math.min(1, Math.max(0, r.relevance as number)),
          rationale: typeof r.rationale === 'string' ? r.rationale : ''
        }))
        .sort((a: SkillRecommendation, b: SkillRecommendation) => b.relevance - a.relevance)
    } catch (err) {
      enrichLog.warn('Failed to parse recommendations JSON — returning empty:', err)
      return []
    }
  }
}

export const skillEnrichmentService = new SkillEnrichmentService()

import {
  readFileSync,
  writeFileSync,
  copyFileSync,
  mkdirSync,
  existsSync,
  readdirSync,
  unlinkSync,
  rmSync,
  renameSync,
  symlinkSync,
  lstatSync
} from 'node:fs'
import { join } from 'node:path'
import { deployLogger } from '../logger'
import { specialistRepository } from '../db/repositories/specialist.repository'
import { skillRepository } from '../db/repositories/skill.repository'
import {
  parseAgentYaml,
  parseSkillMdFrontmatter,
  extractLastUpdated
} from './workspace-deploy/parsing-utils'
import type {
  DiscoveredSkill,
  DiscoveredAgent,
  WorkspaceClaudeStatus,
  ActivationResult,
  ActivationProgressEvent
} from '../../shared/types'

export class WorkspaceDeployService {
  // currentAbortController removed — activation is now deterministic (no LLM process to abort)

  /** Get Code Atelier's master .claude/ directory */
  private getMasterClaudeDir(): string {
    return join(process.cwd(), '.claude')
  }

  // ── Scanning ──

  /** Scan workspace's .claude/ directory status */
  scanWorkspaceClaude(workspacePath: string): WorkspaceClaudeStatus {
    const claudeDir = join(workspacePath, '.claude')
    const claudeMdPath = join(workspacePath, 'CLAUDE.md')
    const agentsDir = join(claudeDir, 'agents')
    const skillsDir = join(claudeDir, 'skills')

    const hasClaudeDir = existsSync(claudeDir)
    const hasClaudeMd = existsSync(claudeMdPath)
    const hasAgentsDir = existsSync(agentsDir)
    const hasSkillsDir = existsSync(skillsDir)

    const deployedAgents: string[] = []
    if (hasAgentsDir) {
      try {
        const files = readdirSync(agentsDir)
        for (const f of files) {
          if (f.endsWith('.yml') || f.endsWith('.yaml')) {
            deployedAgents.push(f)
          }
        }
      } catch {
        /* ignore read error */
      }
    }

    const deployedSkills: string[] = []
    if (hasSkillsDir) {
      try {
        const entries = readdirSync(skillsDir, { withFileTypes: true })
        for (const e of entries) {
          if (e.isDirectory()) {
            deployedSkills.push(e.name)
          }
        }
      } catch {
        /* ignore read error */
      }
    }

    let claudeMdPreview: string | null = null
    if (hasClaudeMd) {
      try {
        const content = readFileSync(claudeMdPath, 'utf-8')
        claudeMdPreview = content.substring(0, 500)
      } catch {
        /* ignore */
      }
    }

    return {
      hasClaudeDir,
      hasClaudeMd,
      hasAgentsDir,
      hasSkillsDir,
      deployedAgents,
      deployedSkills,
      claudeMdPreview
    }
  }

  /**
   * Scan Code Atelier's master .claude/skills/ directory.
   * Skills still live as files in .claude/skills/ — this remains functional.
   */
  scanMasterSkills(): DiscoveredSkill[] {
    const skillsDir = join(this.getMasterClaudeDir(), 'skills')
    if (!existsSync(skillsDir)) return []

    return this.scanSkillsDirectory(skillsDir, 'master')
  }

  /** Scan target workspace's deployed agents */
  scanWorkspaceAgents(workspacePath: string): DiscoveredAgent[] {
    const agentsDir = join(workspacePath, '.claude', 'agents')
    if (!existsSync(agentsDir)) return []

    const agents: DiscoveredAgent[] = []
    try {
      const files = readdirSync(agentsDir)
      for (const f of files) {
        if (!f.endsWith('.yml') && !f.endsWith('.yaml')) continue

        const filePath = join(agentsDir, f)
        try {
          const content = readFileSync(filePath, 'utf-8')
          const { frontmatter, body } = parseAgentYaml(content)

          agents.push({
            filename: f,
            filePath,
            parsed: {
              name: (frontmatter.name as string) ?? f.replace(/\.ya?ml$/, ''),
              description: (frontmatter.description as string) ?? '',
              model: (frontmatter.model as string) ?? 'sonnet',
              tools: Array.isArray(frontmatter.tools) ? (frontmatter.tools as string[]) : [],
              skills: Array.isArray(frontmatter.skills) ? (frontmatter.skills as string[]) : []
            },
            bodyContent: body,
            isActive: true,
            isDeployed: true,
            source: 'workspace'
          })
        } catch {
          /* skip */
        }
      }
    } catch {
      /* ignore */
    }

    // Enrich with DB specialist info (accurate isActive + specialistId)
    try {
      for (const agent of agents) {
        const specialist = specialistRepository.findByAgentId(agent.parsed.name)
        if (specialist) {
          agent.specialistId = specialist.id
          agent.isActive = specialist.isActive
        } else {
          agent.isActive = false
        }
      }
    } catch {
      // DB not ready — leave isActive as-is
    }

    // Filter out deprecated orchestrator agent
    return agents.filter((a) => a.parsed.name !== 'orchestrator')
  }

  /** Scan target workspace's deployed skills */
  scanWorkspaceSkills(workspacePath: string): DiscoveredSkill[] {
    const skillsDir = join(workspacePath, '.claude', 'skills')
    if (!existsSync(skillsDir)) return []

    const workspaceSkills = this.scanSkillsDirectory(skillsDir, 'workspace')

    // Also include master skills that are NOT deployed
    const masterSkills = this.scanMasterSkills()
    const deployedNames = new Set(workspaceSkills.map((s) => s.name))
    for (const master of masterSkills) {
      if (!deployedNames.has(master.name)) {
        workspaceSkills.push({
          ...master,
          isActive: false,
          source: 'master'
        })
      }
    }

    return workspaceSkills
  }

  /** Common skill directory scanner */
  private scanSkillsDirectory(
    skillsDir: string,
    source: 'master' | 'workspace'
  ): DiscoveredSkill[] {
    const skills: DiscoveredSkill[] = []

    try {
      const entries = readdirSync(skillsDir, { withFileTypes: true })
      for (const entry of entries) {
        if (!entry.isDirectory()) continue

        const dirPath = join(skillsDir, entry.name)
        const skillMdPath = join(dirPath, 'SKILL.md')
        const hasSkillMd = existsSync(skillMdPath)

        let frontmatter: { name?: string; description?: string } | null = null
        let lastUpdated: string | null = null

        if (hasSkillMd) {
          try {
            const content = readFileSync(skillMdPath, 'utf-8')
            frontmatter = parseSkillMdFrontmatter(content)
            lastUpdated = extractLastUpdated(content)
          } catch {
            /* ignore */
          }
        }

        // Scan references/ subdirectory
        const referenceFiles: string[] = []
        const refsDir = join(dirPath, 'references')
        if (existsSync(refsDir)) {
          try {
            const refs = readdirSync(refsDir)
            referenceFiles.push(...refs.filter((r) => !r.startsWith('.')))
          } catch {
            /* ignore */
          }
        }

        skills.push({
          name: entry.name,
          dirPath,
          hasSkillMd,
          referenceFiles,
          frontmatter,
          isActive: source === 'workspace',
          lastUpdated,
          source
        })
      }
    } catch {
      /* ignore */
    }

    return skills
  }

  // ── File Operations ──

  /** Read any file from workspace (for the content viewer) */
  readWorkspaceFile(filePath: string): string {
    if (!existsSync(filePath)) {
      throw new Error(`File not found: ${filePath}`)
    }
    return readFileSync(filePath, 'utf-8')
  }

  /** Write file back to workspace (for the editor) */
  writeWorkspaceFile(filePath: string, content: string): void {
    writeFileSync(filePath, content, 'utf-8')
  }

  // ── Deployment ──

  /** Remove a single agent YAML from workspace */
  undeployAgent(workspacePath: string, agentFilename: string): void {
    const targetPath = join(workspacePath, '.claude', 'agents', agentFilename)
    if (existsSync(targetPath)) {
      unlinkSync(targetPath)
    }
  }

  /** Copy a skill directory (with references/) to workspace */
  deploySkill(workspacePath: string, skillName: string): void {
    const masterDir = join(this.getMasterClaudeDir(), 'skills', skillName)
    const targetDir = join(workspacePath, '.claude', 'skills', skillName)

    if (!existsSync(masterDir)) {
      throw new Error(`Skill not found in master: ${skillName}`)
    }

    // Use symlink instead of recursive copy — edits to master are reflected instantly
    try {
      // Remove existing target (could be a stale symlink, old copy, or broken link)
      if (existsSync(targetDir) || this.isSymlink(targetDir)) {
        rmSync(targetDir, { recursive: true, force: true })
      }
      symlinkSync(masterDir, targetDir, 'dir')
      deployLogger.debug(`Symlinked skill: ${masterDir} → ${targetDir}`)
    } catch (symlinkErr) {
      // Fallback to copy if symlink fails (e.g. cross-device, permissions)
      deployLogger.warn(
        `Symlink failed for skill "${skillName}", falling back to copy: ${(symlinkErr as Error).message}`
      )
      this.copyDirRecursive(masterDir, targetDir)
    }
  }

  /** Check if a path is a symlink (even if broken) */
  private isSymlink(targetPath: string): boolean {
    try {
      const stats = lstatSync(targetPath)
      return stats.isSymbolicLink()
    } catch {
      return false
    }
  }

  /** Remove a skill directory (or symlink) from workspace */
  undeploySkill(workspacePath: string, skillName: string): void {
    const targetDir = join(workspacePath, '.claude', 'skills', skillName)
    if (existsSync(targetDir) || this.isSymlink(targetDir)) {
      rmSync(targetDir, { recursive: true, force: true })
    }
  }

  // ── Individual Agent/Skill Delete & Sync ──

  /** Delete a single agent from workspace: remove YAML, clean CLAUDE.md references, remove DB record */
  deleteAgentFromWorkspace(workspacePath: string, filename: string): void {
    // 1. Remove agent YAML from workspace
    this.undeployAgent(workspacePath, filename)

    // 2. Remove agent references from workspace CLAUDE.md
    this.removeFromClaudeMd(workspacePath, filename.replace(/\.ya?ml$/, ''))

    deployLogger.info(`Deleted agent from workspace: ${filename} in ${workspacePath}`)
  }

  /** Sync a single agent to workspace: update CLAUDE.md, upsert DB record */
  syncAgentToWorkspace(workspacePath: string, filename: string): void {
    // 1. Add agent reference to workspace CLAUDE.md
    const agentName = filename.replace(/\.ya?ml$/, '')
    this.addToClaudeMd(workspacePath, 'agent', agentName)

    deployLogger.info(`Synced agent to workspace: ${filename} in ${workspacePath}`)
  }

  /** Delete a single skill from workspace: remove skill dir, clean CLAUDE.md references, remove DB record */
  deleteSkillFromWorkspace(workspacePath: string, skillName: string): void {
    // 1. Remove skill directory from workspace
    this.undeploySkill(workspacePath, skillName)

    // 2. Remove skill references from workspace CLAUDE.md
    this.removeFromClaudeMd(workspacePath, skillName)

    deployLogger.info(`Deleted skill from workspace: ${skillName} in ${workspacePath}`)
  }

  /** Sync a single skill to workspace: copy skill dir from master, update CLAUDE.md, upsert DB record */
  syncSkillToWorkspace(workspacePath: string, skillName: string): void {
    // 1. Copy skill directory from master to workspace
    this.deploySkill(workspacePath, skillName)

    // 2. Add skill reference to workspace CLAUDE.md
    this.addToClaudeMd(workspacePath, 'skill', skillName)

    deployLogger.info(`Synced skill to workspace: ${skillName} in ${workspacePath}`)
  }

  /** Remove references to an agent or skill name from workspace CLAUDE.md */
  private removeFromClaudeMd(workspacePath: string, name: string): void {
    const claudeMdPath = join(workspacePath, 'CLAUDE.md')
    if (!existsSync(claudeMdPath)) return

    try {
      let content = readFileSync(claudeMdPath, 'utf-8')
      const original = content

      // Remove lines containing the agent/skill name (common patterns in CLAUDE.md)
      // e.g. references like "| `skill-name` | ..." or "- skill-name" or agent YAML references
      const escapedName = name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
      const patterns = [
        // Table row: | `name` | ... |
        new RegExp(`^\\|[^|]*\`${escapedName}\`[^|]*\\|.*$\\n?`, 'gm'),
        // List item: - name or * name
        new RegExp(`^\\s*[-*]\\s+\`?${escapedName}\`?\\s*.*$\\n?`, 'gm')
      ]

      for (const pattern of patterns) {
        content = content.replace(pattern, '')
      }

      if (content !== original) {
        // Clean up any double blank lines left behind
        content = content.replace(/\n{3,}/g, '\n\n')
        writeFileSync(claudeMdPath, content, 'utf-8')
        deployLogger.info(`Removed references to "${name}" from CLAUDE.md`)
      }
    } catch (err) {
      deployLogger.warn(`Failed to clean CLAUDE.md for "${name}": ${(err as Error).message}`)
    }
  }

  /** Add a reference to an agent or skill in workspace CLAUDE.md */
  private addToClaudeMd(workspacePath: string, type: 'agent' | 'skill', name: string): void {
    const claudeMdPath = join(workspacePath, 'CLAUDE.md')
    if (!existsSync(claudeMdPath)) return

    try {
      const content = readFileSync(claudeMdPath, 'utf-8')

      // Check if already referenced
      if (content.includes(name)) {
        return // Already referenced
      }

      // Determine the section to append to
      const sectionHeader = type === 'agent' ? '### Available agents' : '### Available skills'
      const sectionIndex = content.indexOf(sectionHeader)

      if (sectionIndex === -1) {
        // No dedicated section found — append a note at the end
        const reference =
          type === 'agent'
            ? `\n\n### Available agents\n\n| Agent | Path |\n|-------|------|\n| \`${name}\` | \`.claude/agents/${name}.yml\` |\n`
            : `\n\n### Available skills\n\n| Skill | Path |\n|-------|------|\n| \`${name}\` | \`.claude/skills/${name}/SKILL.md\` |\n`
        writeFileSync(claudeMdPath, content + reference, 'utf-8')
      } else {
        // Find the end of the table in that section and append a row
        const afterSection = content.substring(sectionIndex)
        // Find the last table row in the section (before the next heading or EOF)
        const nextHeading = afterSection.search(/\n##[^#]/)
        const sectionEnd = nextHeading === -1 ? content.length : sectionIndex + nextHeading

        const newRow =
          type === 'agent'
            ? `| \`${name}\` | \`.claude/agents/${name}.yml\` | — |\n`
            : `| \`${name}\` | \`.claude/skills/${name}/SKILL.md\` | — |\n`

        const updated = content.substring(0, sectionEnd) + newRow + content.substring(sectionEnd)
        writeFileSync(claudeMdPath, updated, 'utf-8')
      }

      deployLogger.info(`Added ${type} "${name}" reference to CLAUDE.md`)
    } catch (err) {
      deployLogger.warn(
        `Failed to update CLAUDE.md for ${type} "${name}": ${(err as Error).message}`
      )
    }
  }

  /** Remove all deployed agents, skills, and optionally CLAUDE.md from the workspace */
  cleanActivation(workspacePath: string, removeClaudeMd = false): void {
    const agentsDir = join(workspacePath, '.claude', 'agents')
    const skillsDir = join(workspacePath, '.claude', 'skills')

    if (existsSync(agentsDir)) {
      rmSync(agentsDir, { recursive: true, force: true })
    }
    if (existsSync(skillsDir)) {
      rmSync(skillsDir, { recursive: true, force: true })
    }
    if (removeClaudeMd) {
      const claudeMdPath = join(workspacePath, 'CLAUDE.md')
      if (existsSync(claudeMdPath)) {
        unlinkSync(claudeMdPath)
      }
    }

    deployLogger.info(
      `Cleaned activation for workspace: ${workspacePath} (removeClaudeMd: ${removeClaudeMd})`
    )
  }

  /** Recursive directory copy */
  private copyDirRecursive(src: string, dest: string): void {
    mkdirSync(dest, { recursive: true })
    const entries = readdirSync(src, { withFileTypes: true })

    for (const entry of entries) {
      const srcPath = join(src, entry.name)
      const destPath = join(dest, entry.name)

      if (entry.isDirectory()) {
        this.copyDirRecursive(srcPath, destPath)
      } else {
        copyFileSync(srcPath, destPath)
      }
    }
  }

  // ── Activation Flow ──

  /**
   * Full activation: activate all DB specialists, sync workspace, generate CLAUDE.md.
   * Skills are NOT deployed during activation — users opt-in later.
   */
  async activateAgents(
    workspacePath: string,
    onProgress?: (event: ActivationProgressEvent) => void
  ): Promise<ActivationResult> {
    const emit = (type: ActivationProgressEvent['type'], message: string): void => {
      onProgress?.({ type, message, timestamp: Date.now() })
    }

    // Ensure .claude/ directories exist
    const agentsDir = join(workspacePath, '.claude', 'agents')
    const skillsDir = join(workspacePath, '.claude', 'skills')
    mkdirSync(agentsDir, { recursive: true })
    mkdirSync(skillsDir, { recursive: true })

    // ── STEP 1: Auto-sync workspace entries into DB ──
    emit('status', 'Syncing workspace entries...')
    try {
      const { agentSyncService } = await import('./agent-sync.service')
      const syncResult = agentSyncService.autoSyncNewEntries(workspacePath)
      if (syncResult.imported > 0 || syncResult.skillsImported > 0) {
        emit(
          'status',
          `Synced ${syncResult.imported} specialists and ${syncResult.skillsImported} skills to database`
        )
      }
    } catch (e) {
      deployLogger.warn('Auto-sync after activation failed:', e)
    }

    // Scan workspace agents/skills for CLAUDE.md generation
    const workspaceAgents = this.scanWorkspaceAgents(workspacePath)
    const masterSkills = this.scanMasterSkills()

    // Collect referenced skills from workspace agents
    const referencedSkills = new Set<string>()
    for (const agent of workspaceAgents) {
      for (const skillRef of agent.parsed.skills) {
        referencedSkills.add(skillRef)
      }
    }

    // ── STEP 2: Generate merged CLAUDE.md deterministically (no LLM call) ──
    emit('status', 'Generating CLAUDE.md...')
    const claudeMdPath = join(workspacePath, 'CLAUDE.md')
    let existingClaudeMd: string | null = null
    if (existsSync(claudeMdPath)) {
      try {
        existingClaudeMd = readFileSync(claudeMdPath, 'utf-8')
      } catch {
        /* ignore */
      }
    }

    const mergedClaudeMd = this.generateClaudeMdDeterministic(
      existingClaudeMd,
      workspaceAgents,
      masterSkills,
      referencedSkills
    )

    // ── STEP 3: Detect tech stack ──
    emit('status', 'Detecting tech stack...')
    let detectedTechs: string[] | undefined
    try {
      const { detectTechStack } = await import('./tech-stack-detector.service')
      const techResult = detectTechStack(workspacePath)
      detectedTechs = techResult.detectedTechs
      if (detectedTechs.length > 0) {
        emit('status', `Detected: ${detectedTechs.join(', ')}`)
      }
    } catch (e) {
      deployLogger.warn('Tech-stack detection failed:', e)
    }

    emit('status', 'Activation complete!')
    return {
      success: true,
      selectedAgents: workspaceAgents.map((a) => a.filename),
      selectedSkills: [],
      existingClaudeMd,
      proposedClaudeMd: mergedClaudeMd,
      claudeMdWritten: false,
      detectedTechs
    }
  }

  /**
   * Generate CLAUDE.md content deterministically from templates.
   * No LLM call needed — assembles from existing content + agent/skill listings.
   */
  private generateClaudeMdDeterministic(
    existingContent: string | null,
    agents: DiscoveredAgent[],
    allSkills: DiscoveredSkill[],
    referencedSkills: Set<string>
  ): string {
    const sections: string[] = []

    // Preserve existing project content (strip old agent/skill sections if present)
    if (existingContent) {
      const cleaned = this.stripGeneratedSections(existingContent)
      if (cleaned.trim()) {
        sections.push(cleaned.trim())
      }
    }

    // Build agents table
    const agentRows = agents
      .map((a) => {
        const skills = a.parsed.skills.length > 0 ? a.parsed.skills.join(', ') : 'none'
        return `| \`${a.parsed.name}\` | ${a.parsed.description || a.parsed.name} | ${skills} |`
      })
      .join('\n')

    sections.push(`## Agents

<!-- AUTO-GENERATED by Code Atelier — do not edit manually -->

| Agent | Description | Skills |
|-------|-------------|--------|
${agentRows}`)

    // Build skills table
    const skillRows = [...referencedSkills]
      .map((name) => {
        const skill = allSkills.find((s) => s.name === name)
        const description = skill?.frontmatter?.description || 'No description'
        return `| \`${name}\` | ${description} | \`.claude/skills/${name}/SKILL.md\` |`
      })
      .join('\n')

    sections.push(`## Skills

<!-- AUTO-GENERATED by Code Atelier — do not edit manually -->

| Skill | Description | Path |
|-------|-------------|------|
${skillRows}`)

    return sections.join('\n\n')
  }

  /**
   * Strip auto-generated ## Agents and ## Skills sections from existing CLAUDE.md content.
   * Preserves all user-written sections.
   */
  private stripGeneratedSections(content: string): string {
    // Remove ## Agents section (from header to next ## or EOF)
    let result = content.replace(
      /\n*## Agents\s*\n<!-- AUTO-GENERATED[^]*?(?=\n## (?!Agents|Skills)|\n*$)/,
      ''
    )
    // Remove ## Skills section
    result = result.replace(
      /\n*## Skills\s*\n<!-- AUTO-GENERATED[^]*?(?=\n## (?!Agents|Skills)|\n*$)/,
      ''
    )
    return result
  }

  /** Write approved CLAUDE.md content to disk atomically */
  confirmClaudeMd(workspacePath: string, content: string): void {
    const claudeMdPath = join(workspacePath, 'CLAUDE.md')
    const tmpPath = claudeMdPath + '.tmp'
    writeFileSync(tmpPath, content, 'utf-8')
    renameSync(tmpPath, claudeMdPath)
  }

  // ── Activate / Deactivate / Delete All / Deploy All ──

  /** Activate agent: set DB is_active=true, add to CLAUDE.md */
  activateAgent(workspacePath: string, agentName: string): void {
    const specialist = specialistRepository.findByAgentId(agentName)
    if (specialist) {
      specialistRepository.update(specialist.id, { isActive: true })
    }
    this.addToClaudeMd(workspacePath, 'agent', agentName)
    deployLogger.info(`Activated agent: ${agentName}`)
  }

  /** Deactivate agent: set DB is_active=false, remove from CLAUDE.md */
  deactivateAgent(workspacePath: string, agentName: string): void {
    const specialist = specialistRepository.findByAgentId(agentName)
    if (specialist) {
      specialistRepository.update(specialist.id, { isActive: false })
    }
    this.removeFromClaudeMd(workspacePath, agentName)
    deployLogger.info(`Deactivated agent: ${agentName}`)
  }

  /** Delete all agents from workspace: rm .claude/agents/, delete all DB specialist records */
  deleteAllAgents(workspacePath: string): void {
    const agentsDir = join(workspacePath, '.claude', 'agents')
    if (existsSync(agentsDir)) {
      rmSync(agentsDir, { recursive: true, force: true })
    }
    specialistRepository.deleteAll()
    deployLogger.info(`Deleted all agents from workspace: ${workspacePath}`)
  }

  /** Delete all skills from workspace: rm .claude/skills/, delete all DB skill records */
  deleteAllSkills(workspacePath: string): void {
    const skillsDir = join(workspacePath, '.claude', 'skills')
    if (existsSync(skillsDir)) {
      rmSync(skillsDir, { recursive: true, force: true })
    }
    skillRepository.deleteAll()
    deployLogger.info(`Deleted all skills from workspace: ${workspacePath}`)
  }

  /**
   * Activate all specialists in the DB for a workspace.
   * Skills are NOT deployed during bulk activation — users opt-in to skills later.
   * Agent YAMLs are no longer copied (DB is source of truth).
   */
  async deployAllInactive(workspacePath: string): Promise<{ agents: number; skills: number }> {
    // Ensure .claude/ directories exist for workspace compatibility
    mkdirSync(join(workspacePath, '.claude', 'agents'), { recursive: true })
    mkdirSync(join(workspacePath, '.claude', 'skills'), { recursive: true })

    // Remove deprecated orchestrator YAML if present
    const orchestratorPath = join(workspacePath, '.claude', 'agents', 'orchestrator.yml')
    if (existsSync(orchestratorPath)) {
      unlinkSync(orchestratorPath)
    }

    // Auto-sync any new entries from workspace to DB
    const { agentSyncService } = await import('./agent-sync.service')
    agentSyncService.autoSyncNewEntries(workspacePath)

    // Post-migration-66: specialist deployment to YAML files is no longer a thing —
    // every workspace has a single Project Specialist managed via SpecialistBuilder.
    // Return a count of the workspace's specialists purely for UI feedback.
    const { specialistRepository: specRepo } =
      await import('../db/repositories/specialist.repository')
    const allSpecialists = specRepo.findAll()
    const agentCount = allSpecialists.filter((s) => s.isActive).length

    return { agents: agentCount, skills: 0 }
  }

  /** Shutdown — no-op (activation is now deterministic, no background process to cancel) */
  shutdown(): void {
    // Intentionally empty — kept for API compatibility
  }
}

export const workspaceDeployService = new WorkspaceDeployService()

/**
 * parsing-utils.ts — Pure parsing functions extracted from workspace-deploy.service.ts.
 *
 * These are stateless string/YAML parsers with zero class dependencies,
 * ideal for independent unit testing.
 */

/**
 * Simple YAML frontmatter parser for agent YAML files.
 * Handles key-value pairs, multiline values (| and >), and inline arrays.
 */
export function parseAgentYaml(content: string): {
  frontmatter: Record<string, unknown>
  body: string
} {
  const match = content.match(/^---\n([\s\S]*?)\n---\n?([\s\S]*)$/)
  if (!match) {
    return { frontmatter: {}, body: content }
  }

  const frontmatterRaw = match[1]
  const body = match[2].trim()
  const frontmatter: Record<string, unknown> = {}

  // Parse simple YAML key-value pairs
  let currentKey = ''
  let currentValue = ''
  let isMultiline = false

  for (const line of frontmatterRaw.split('\n')) {
    if (isMultiline) {
      if (line.startsWith('  ') || line.startsWith('\t')) {
        currentValue += ' ' + line.trim()
        continue
      } else {
        frontmatter[currentKey] = currentValue.trim()
        isMultiline = false
      }
    }

    const kvMatch = line.match(/^(\w[\w-]*):\s*(.*)$/)
    if (kvMatch) {
      currentKey = kvMatch[1]
      const val = kvMatch[2].trim()

      if (val === '>' || val === '|') {
        isMultiline = true
        currentValue = ''
      } else if (val.startsWith('[') && val.endsWith(']')) {
        // Parse inline array: [item1, item2, ...]
        frontmatter[currentKey] = val
          .slice(1, -1)
          .split(',')
          .map((s) => s.trim())
          .filter(Boolean)
      } else {
        frontmatter[currentKey] = val
      }
    }
  }

  if (isMultiline) {
    frontmatter[currentKey] = currentValue.trim()
  }

  return { frontmatter, body }
}

/**
 * Parse SKILL.md frontmatter for name/description.
 * Returns null if no frontmatter block is found.
 */
export function parseSkillMdFrontmatter(
  content: string
): { name?: string; description?: string } | null {
  const match = content.match(/^---\n([\s\S]*?)\n---/)
  if (!match) return null

  const result: { name?: string; description?: string } = {}
  let currentKey = ''
  let currentValue = ''
  let isMultiline = false

  for (const line of match[1].split('\n')) {
    if (isMultiline) {
      if (line.startsWith('  ') || line.startsWith('\t')) {
        currentValue += ' ' + line.trim()
        continue
      } else {
        if (currentKey === 'name') result.name = currentValue.trim()
        if (currentKey === 'description') result.description = currentValue.trim()
        isMultiline = false
      }
    }

    const kvMatch = line.match(/^(\w[\w-]*):\s*(.*)$/)
    if (kvMatch) {
      currentKey = kvMatch[1]
      const val = kvMatch[2].trim()
      if (val === '>' || val === '|') {
        isMultiline = true
        currentValue = ''
      } else {
        if (currentKey === 'name') result.name = val
        if (currentKey === 'description') result.description = val
      }
    }
  }

  if (isMultiline) {
    if (currentKey === 'name') result.name = currentValue.trim()
    if (currentKey === 'description') result.description = currentValue.trim()
  }

  return result
}

/**
 * Extract "Last updated: YYYY-MM-DD" from SKILL.md content.
 * Returns null if no match is found.
 */
export function extractLastUpdated(content: string): string | null {
  const match = content.match(/Last updated:\s*(\d{4}-\d{2}-\d{2})/i)
  return match ? match[1] : null
}

/**
 * MemoryRetrievalService — Hybrid retrieval for per-turn injection and search.
 *
 * Scoring: cosine similarity + keyword overlap + tier bonus + recency +
 * scope_paths boost. Relevance floor filters out irrelevant facts.
 * Keyword-only fallback when embeddings are offline.
 */

import { dbLogger } from '../logger'
import { memoryFactRepository } from '../db/repositories/memory-fact.repository'
import { localEmbeddingProvider } from './local-embedding.provider'
import { sanitizePromptInput } from './sanitize-prompt-input'
import { cosineSimilarity } from './memory-engine.service'
import type {
  MemoryFact,
  MemoryFactCategory,
  MemoryRetrievalResult
} from '../../shared/types'

const log = dbLogger

// ── Retrieval configuration ─────────────────────────────────────────────────

/** Minimum combined score to include in results. */
const RELEVANCE_FLOOR = 0.40

/** Cosine similarity floor — below this, cosine doesn't count. */
const COSINE_FLOOR = 0.55

/** Score weights */
const WEIGHT_COSINE = 0.50
const WEIGHT_KEYWORD = 0.25
const WEIGHT_TIER = 0.10
const WEIGHT_RECENCY = 0.10
const WEIGHT_SCOPE = 0.05

/** Tier-aware character budgets for per-turn injection. */
const TIER_BUDGETS = {
  small: 1500, // ≤64K context window
  medium: 3000, // ≤128K context window
  large: 5000 // >128K context window
} as const

type ContextTier = keyof typeof TIER_BUDGETS

class MemoryRetrievalService {
  // ── Per-turn injection ──────────────────────────────────────────────────

  /**
   * Get relevant facts for a turn, formatted for prompt injection.
   * Returns empty string when nothing is relevant (the common case).
   *
   * @param workspaceId — workspace to search
   * @param promptText — the user's prompt to match against
   * @param contextTier — controls character budget
   * @param injectedIds — set of fact IDs already injected this session (mutated in place)
   */
  async getContextForTurn(
    workspaceId: string,
    promptText: string,
    contextTier: ContextTier = 'medium',
    injectedIds?: Set<string>
  ): Promise<string> {
    try {
      const results = await this.retrieve(workspaceId, promptText, 10)
      if (results.length === 0) return ''

      // Filter out already-injected facts (session dedupe)
      const fresh = injectedIds
        ? results.filter((r) => !injectedIds.has(r.fact.id))
        : results

      if (fresh.length === 0) return ''

      // Budget-cap the output
      const budget = TIER_BUDGETS[contextTier]
      const formatted = this.formatForInjection(fresh, budget)
      if (!formatted) return ''

      // Track which facts were injected
      if (injectedIds) {
        for (const r of fresh) {
          injectedIds.add(r.fact.id)
        }
      }

      // Touch accessed facts
      memoryFactRepository.touchFacts(fresh.map((r) => r.fact.id))

      return formatted
    } catch (err) {
      log.warn('[MemoryRetrieval] getContextForTurn failed:', err)
      return ''
    }
  }

  // ── Hybrid retrieval ────────────────────────────────────────────────────

  /**
   * Retrieve facts by hybrid scoring: cosine + keyword + tier + recency + scope.
   * Falls back to keyword-only when embeddings are offline.
   */
  async retrieve(
    workspaceId: string,
    query: string,
    limit = 20,
    category?: MemoryFactCategory
  ): Promise<MemoryRetrievalResult[]> {
    const queryTokens = tokenize(query)
    if (queryTokens.length === 0) return []

    const { candidateMap, queryVec } = await this.gatherCandidates(
      workspaceId,
      query,
      category
    )
    if (candidateMap.size === 0) return []

    // Score each candidate
    const now = Date.now()
    const scored: MemoryRetrievalResult[] = []

    for (const { fact, embeddingVec } of candidateMap.values()) {
      const result = scoreCandidate(fact, embeddingVec, queryVec, queryTokens, query, now)
      if (result) scored.push(result)
    }

    // Sort by score descending, take top N
    scored.sort((a, b) => b.score - a.score)
    return scored.slice(0, limit)
  }

  // ── Candidate gathering (extracted for complexity) ─────────────────────

  /**
   * Embed a query string via the OMLX provider.
   * Returns null when embeddings are offline or the provider errors.
   */
  private async embedQuery(query: string): Promise<Float32Array | null> {
    try {
      if (localEmbeddingProvider.isReady) {
        const vectors = await localEmbeddingProvider.embed([query])
        if (vectors.length > 0 && vectors[0].length > 0) {
          return new Float32Array(vectors[0])
        }
      }
    } catch (err) {
      log.debug('[MemoryRetrieval] Embedding failed, using keyword fallback:', err)
    }
    return null
  }

  /**
   * Build a merged candidate map from embedding + keyword retrieval.
   * Falls back to keyword-only when embeddings are offline.
   */
  private async gatherCandidates(
    workspaceId: string,
    query: string,
    category?: MemoryFactCategory
  ): Promise<{
    candidateMap: Map<string, { fact: MemoryFact; embeddingVec?: Float32Array }>
    queryVec: Float32Array | null
  }> {
    const queryVec = await this.embedQuery(query)

    // Get candidate facts
    const allWithEmbeddings = queryVec
      ? memoryFactRepository.findWithEmbeddings(workspaceId)
      : []
    const keywordCandidates = memoryFactRepository.search(workspaceId, query, 50)

    // Merge candidates by ID (union of both sets)
    const candidateMap = new Map<string, { fact: MemoryFact; embeddingVec?: Float32Array }>()

    for (const { fact, embedding } of allWithEmbeddings) {
      if (category && fact.category !== category) continue
      candidateMap.set(fact.id, { fact, embeddingVec: embedding })
    }
    for (const fact of keywordCandidates) {
      if (category && fact.category !== category) continue
      if (!candidateMap.has(fact.id)) {
        candidateMap.set(fact.id, { fact })
      }
    }

    return { candidateMap, queryVec }
  }

  // ── Formatting ──────────────────────────────────────────────────────────

  /** Format retrieved facts for prompt injection within a character budget. */
  private formatForInjection(results: MemoryRetrievalResult[], budget: number): string | null {
    const lines: string[] = []
    let totalChars = 0

    for (const { fact } of results) {
      const tierLabel = ['T0', 'T1', 'T2', 'T3'][fact.tier] || 'T0'
      const catLabel = fact.category.charAt(0).toUpperCase() + fact.category.slice(1)
      const line = `- [${tierLabel}/${catLabel}] **${sanitizePromptInput(fact.title)}**: ${sanitizePromptInput(fact.content)}`

      if (totalChars + line.length > budget) break
      lines.push(line)
      totalChars += line.length
    }

    if (lines.length === 0) return null
    return lines.join('\n')
  }

  /** Format for MCP tool search response (more detail than injection). */
  formatForToolResponse(results: MemoryRetrievalResult[]): string {
    if (results.length === 0) return 'No relevant facts found.'

    return results
      .map(({ fact, score }) => {
        const tierLabel = ['Observed', 'Confirmed', 'Established', 'Wisdom'][fact.tier]
        return [
          `## ${fact.title}`,
          `**Category**: ${fact.category} | **Tier**: ${tierLabel} (${fact.tier}) | **Confidence**: ${(fact.confidence * 100).toFixed(0)}%`,
          fact.scopePaths.length > 0 ? `**Scope**: ${fact.scopePaths.join(', ')}` : null,
          `**Source**: ${fact.sourceType}${fact.sourceRef ? ` (${fact.sourceRef})` : ''}`,
          '',
          fact.content,
          `\n_Relevance: ${(score * 100).toFixed(0)}% | ID: ${fact.id}_`
        ]
          .filter(Boolean)
          .join('\n')
      })
      .join('\n\n---\n\n')
  }
}

// ── Scoring helpers ─────────────────────────────────────────────────────────

/** Score a single candidate fact. Returns null if below relevance threshold. */
function scoreCandidate(
  fact: MemoryFact,
  embeddingVec: Float32Array | undefined,
  queryVec: Float32Array | null,
  queryTokens: string[],
  query: string,
  now: number
): MemoryRetrievalResult | null {
  const cosineScore =
    queryVec && embeddingVec ? cosineSimilarity(queryVec, embeddingVec) : 0
  const cosineContrib = cosineScore >= COSINE_FLOOR ? cosineScore : 0
  const keywordScore = computeKeywordOverlap(queryTokens, fact)
  const tierBonus = fact.tier / 3
  const recencyScore = computeRecency(fact, now)
  const scopeBonus = computeScopeBoost(query, fact.scopePaths)

  const finalScore =
    cosineContrib * WEIGHT_COSINE +
    keywordScore * WEIGHT_KEYWORD +
    tierBonus * WEIGHT_TIER +
    recencyScore * WEIGHT_RECENCY +
    scopeBonus * WEIGHT_SCOPE

  // Inclusion gate: combined score, cosine alone, or keyword alone
  if (finalScore < RELEVANCE_FLOOR && cosineScore < COSINE_FLOOR && keywordScore <= 0.5) {
    return null
  }

  const matchType = resolveMatchType(cosineContrib, keywordScore)
  return { fact, score: finalScore, matchType }
}

/** Determine how a candidate matched (cosine, keyword, or hybrid). */
function resolveMatchType(
  cosineContrib: number,
  keywordScore: number
): MemoryRetrievalResult['matchType'] {
  if (cosineContrib > 0 && keywordScore > 0) return 'hybrid'
  if (cosineContrib > 0) return 'cosine'
  return 'keyword'
}

/** Tokenize text into lowercase words for keyword matching. */
function tokenize(text: string): string[] {
  return text
    .toLowerCase()
    .replace(/[^a-z0-9_\-/.]/g, ' ')
    .split(/\s+/)
    .filter((t) => t.length > 2) // skip tiny tokens
}

/** Compute keyword overlap score (0–1). */
function computeKeywordOverlap(queryTokens: string[], fact: MemoryFact): number {
  if (queryTokens.length === 0) return 0

  const factText = `${fact.title} ${fact.content} ${fact.tags.join(' ')}`.toLowerCase()
  let hits = 0
  for (const token of queryTokens) {
    if (factText.includes(token)) hits++
  }
  return hits / queryTokens.length
}

/** Compute recency score (0–1): more recent = higher score. */
function computeRecency(fact: MemoryFact, now: number): number {
  const dateStr = fact.lastAccessedAt || fact.updatedAt || fact.createdAt
  if (!dateStr) return 0.5

  const age = now - new Date(dateStr).getTime()
  const daysOld = age / (1000 * 60 * 60 * 24)

  // Within 7 days: 1.0; 30 days: ~0.75; 90 days: ~0.5; 365 days: ~0.2
  return Math.max(0, 1 - daysOld / 400)
}

/** Compute scope path boost: higher if query mentions paths in fact.scopePaths. */
function computeScopeBoost(query: string, scopePaths: string[]): number {
  if (scopePaths.length === 0) return 0.5 // neutral for unscoped facts
  const queryLower = query.toLowerCase()
  for (const p of scopePaths) {
    if (queryLower.includes(p.toLowerCase())) return 1.0
  }
  return 0
}

export const memoryRetrievalService = new MemoryRetrievalService()

import { spawnSync } from 'node:child_process'
import { BrowserWindow } from 'electron'
import log from 'electron-log/main'
import { checkpointRepository } from '../db/repositories/checkpoint.repository'
import { eventLoggerService } from './event-logger.service'
import { IPC_CHANNELS } from '../../shared/constants'

const checkpointLogger = log.scope('Checkpoint')

export interface CheckpointApprovalRequest {
  id: string
  type: 'phase_gate' | 'merge_approval' | 'destructive_action'
  title: string
  summary: string
  details: {
    what: string
    why: string
    risk: string
    changedFiles?: string[]
    testResults?: string
  }
  createdAt: string
}

interface PendingCheckpointApproval {
  resolve: (approved: boolean) => void
  checkpoint: CheckpointApprovalRequest
}

/**
 * Shape of a checkpoint's saved state as read by checkpoint-context.tool.ts.
 * Checkpoints are now produced by the destructive-action confirmation flow only —
 * the old pre-execution multi-specialist snapshot path was removed.
 */
interface CheckpointState {
  activeTaskIds: string[]
  completedTaskIds: string[]
  taskResults: Record<string, string>
  taskStatuses: Record<string, 'pending' | 'running' | 'completed' | 'failed' | 'skipped'>
  metadata?: Record<string, unknown>
}

/**
 * Checkpoint service — exposes read-only access to previously-saved checkpoint
 * snapshots (see checkpoint-context.tool.ts) and a destructive `restoreGitState`
 * action driven from the UI. Write-path checkpoint creation lives with the
 * callers that still need it (currently: none in the live code path).
 */
class CheckpointService {
  private pendingApprovals = new Map<string, PendingCheckpointApproval>()

  /**
   * Requests user approval before proceeding with a critical operation.
   * Pauses execution and sends a request to the renderer; resolves when the user responds.
   * Auto-approves after 5 minutes to prevent indefinite blocking.
   */
  async requestApproval(
    request: Omit<CheckpointApprovalRequest, 'id' | 'createdAt'>
  ): Promise<boolean> {
    const id = `chk-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`
    const checkpoint: CheckpointApprovalRequest = {
      ...request,
      id,
      createdAt: new Date().toISOString()
    }

    return new Promise<boolean>((resolve) => {
      this.pendingApprovals.set(id, { resolve, checkpoint })

      // Send to renderer via focused window
      const win = BrowserWindow.getFocusedWindow() ?? BrowserWindow.getAllWindows()[0]
      if (win) {
        win.webContents.send(IPC_CHANNELS.CHECKPOINT_APPROVAL_REQUEST, checkpoint)
      } else {
        // No window — auto-approve to avoid blocking
        this.pendingApprovals.delete(id)
        resolve(true)
      }

      // Safety timeout — auto-approve after 5 minutes
      setTimeout(
        () => {
          if (this.pendingApprovals.has(id)) {
            checkpointLogger.warn(`Checkpoint approval timed out — auto-approving: ${id}`)
            this.resolveApproval(id, true)
          }
        },
        5 * 60 * 1000
      )
    })
  }

  /**
   * Resolves a pending approval — called from the IPC handler when the user responds.
   * Also fires the appropriate declarative hook (checkpoint_approved/rejected).
   */
  resolveApproval(checkpointId: string, approved: boolean): void {
    const pending = this.pendingApprovals.get(checkpointId)
    if (!pending) return
    this.pendingApprovals.delete(checkpointId)
    checkpointLogger.info(
      `Checkpoint ${approved ? 'approved' : 'rejected'}: ${checkpointId} (${pending.checkpoint.type})`
    )

    // Fire declarative hook
    import('./hook-engine.service')
      .then(({ hookEngine }) => {
        const event = approved ? 'checkpoint_approved' : 'checkpoint_rejected'
        hookEngine
          .executeHooks(event as import('./hook-engine.service').HookEvent, {
            checkpointId,
            type: pending.checkpoint.type
          })
          .catch((err) => checkpointLogger.warn(`Hook error (${event}):`, err))
      })
      .catch(() => {
        /* non-fatal: hook engine not available — checkpoint proceeds without hooks */
      })

    pending.resolve(approved)
  }

  /**
   * Retrieves a checkpoint and its saved state.
   */
  getCheckpoint(
    checkpointId: string
  ): { state: CheckpointState; gitBranch?: string; gitCommitSha?: string } | null {
    const record = checkpointRepository.findById(checkpointId)
    if (!record) return null

    try {
      const state = JSON.parse(record.stateJson) as CheckpointState
      return {
        state,
        gitBranch: record.gitBranch ?? undefined,
        gitCommitSha: record.gitCommitSha ?? undefined
      }
    } catch {
      checkpointLogger.error(`Failed to parse checkpoint state: ${checkpointId}`)
      return null
    }
  }

  /**
   * Lists all checkpoints for a conversation (metadata only, no parsed state).
   */
  listCheckpoints(conversationId: string): {
    id: string
    label: string
    gitBranch?: string
    gitCommitSha?: string
    createdAt: string
  }[] {
    return checkpointRepository.findByConversation(conversationId).map((r) => ({
      id: r.id,
      label: r.label,
      gitBranch: r.gitBranch ?? undefined,
      gitCommitSha: r.gitCommitSha ?? undefined,
      createdAt: r.createdAt
    }))
  }

  /**
   * Attempts to restore git state from a checkpoint.
   * Returns true if git reset succeeded, false if skipped/failed.
   *
   * NOTE: This only resets git state. Task re-execution must be handled
   * by the caller using the checkpoint's task plan.
   */
  restoreGitState(
    checkpointId: string,
    workspacePath: string
  ): { success: boolean; message: string } {
    const checkpoint = this.getCheckpoint(checkpointId)
    if (!checkpoint) {
      return { success: false, message: 'Checkpoint not found' }
    }

    if (!checkpoint.gitCommitSha) {
      return { success: false, message: 'Checkpoint has no git state to restore' }
    }

    // MCP-02: Validate SHA format before passing to git — prevents command injection
    // if the DB value is corrupted or tampered with.
    const SHA_REGEX = /^[0-9a-f]{7,40}$/i
    if (!SHA_REGEX.test(checkpoint.gitCommitSha)) {
      return { success: false, message: 'Invalid checkpoint commit SHA format' }
    }

    try {
      // Check for uncommitted changes first
      // CHKPT-01: Use spawnSync (array args, no shell) for all git commands
      const statusResult = spawnSync('git', ['status', '--porcelain'], {
        cwd: workspacePath,
        encoding: 'utf-8',
        timeout: 5000
      })
      const status = statusResult.stdout?.trim() ?? ''

      if (status) {
        checkpointLogger.warn(`Uncommitted changes detected — stashing before restore`)
        const stashResult = spawnSync(
          'git',
          ['stash', 'push', '-m', 'checkpoint-restore-auto-stash'],
          { cwd: workspacePath, encoding: 'utf-8', timeout: 10000 }
        )
        if (stashResult.status !== 0) {
          throw new Error(stashResult.stderr || 'git stash failed')
        }
      }

      // Reset to the checkpoint commit
      const resetResult = spawnSync('git', ['reset', '--hard', checkpoint.gitCommitSha], {
        cwd: workspacePath,
        encoding: 'utf-8',
        timeout: 10000
      })
      if (resetResult.status !== 0) {
        throw new Error(resetResult.stderr || `git reset failed with code ${resetResult.status}`)
      }

      const record = checkpointRepository.findById(checkpointId)
      if (record) {
        eventLoggerService.logCheckpointRestored({
          conversationId: record.conversationId,
          workspaceId: record.workspaceId ?? undefined,
          checkpointId,
          label: record.label
        })
      }

      checkpointLogger.info(
        `Git state restored to ${checkpoint.gitCommitSha.slice(0, 7)} from checkpoint ${checkpointId}`
      )

      return {
        success: true,
        message: `Restored to commit ${checkpoint.gitCommitSha.slice(0, 7)}`
      }
    } catch (err) {
      const errorMsg = err instanceof Error ? err.message : String(err)
      checkpointLogger.error(`Failed to restore git state: ${errorMsg}`)
      return { success: false, message: `Git restore failed: ${errorMsg}` }
    }
  }
}

