const log = chatIpcLogger

/**
 * Maximum number of concurrent cross-conversation streams.
 * Phase 2 complete — per-conversation execution isolation in place:
 *   - activeStreams Map (accumulatedText + abortController per conversation)
 *   - per-conversation CLIExecutors
 *   - per-conversation ACK tracking
 *   - per-conversation cancel + getStreamedContent
 * Start with 3 as a resource safety valve (each stream spawns a claude CLI process).
 */
const MAX_CONCURRENT_STREAMS = 3

// ── StreamContext — explicit per-stream state bag ──

/** Immutable per-stream context — replaces the ad-hoc closure state bag. */
interface StreamContext {
  readonly conversationId: string
  readonly requestId: string
  readonly streamingRole: 'specialist'
  readonly phase: ConversationPhase
  readonly specialistMeta: { specialist: string; taskId?: string } | undefined
  readonly adapterAgentId: string
  readonly workspacePath: string | undefined
  /** HEAD sha captured at stream start — for memory extraction git delta. */
  readonly startSha: string | undefined
  /** Accumulated streamed content — mutable, shared across listeners. */
  streamedContent: string
  /** Guards against duplicate plan injection within a single stream. */
  planInjected: boolean
}

// ── Pipeline Callbacks (strategy object) ──
//
// The pipeline callbacks interface is kept to satisfy the legacy
// initChatStream(mainWindow, callbacks) signature but is effectively empty.
// Remove in a future cleanup if no new lifecycle callbacks are added.

export interface PipelineCallbacks {
  onStopPipeline: () => Promise<void>
}

/**
 * Handle returned from stream() — makes the IPC handler lifecycle-aware.
 * Callers can optionally await `done` to know when the entire pipeline
 * the streaming pipeline completes, or call `abort()` to cancel.
 */
export interface StreamHandle {
  /** Resolves when the entire streaming pipeline completes */
  done: Promise<void>
  /** Abort the stream and all sub-operations */
  abort: () => void
  /** The request ID for this stream */
  requestId: string
}

// ── Stream Service ──

export class ChatStreamService {
  private mainWindow: BrowserWindow
  private callbacks: PipelineCallbacks
  private intentRouter: IntentRouter

  /** Per-conversation stop flags — prevents duplicate message saves when stop is called mid-stream */
  private stoppedConversations = new Set<string>()

  /** Per-conversation streaming locks — rejects if that conversation is already streaming */
  private streamingLocks = new Set<string>()
  /** Per-conversation active request IDs */
  private activeRequestIds = new Map<string, string>()

  /** Per-conversation set of already-injected memory fact IDs (prevents re-injection). */
  private injectedFactIds = new Map<string, Set<string>>()

  /** Per-stream identity — set at stream() start, cleared on cleanup. */
  private currentStreamingRole: 'specialist' = 'specialist'

  /**
   * Keepalive timer — sends periodic IPC events to the renderer during streaming.
   * MCP tools (e.g. Maestro run_flow_files) can block the SDK message loop for
   * minutes. Without this, the renderer's 2-minute safety timer fires and
   * disconnects the UI while the backend is still working.
   */
  private keepaliveTimers = new Map<string, ReturnType<typeof setInterval>>()

  /** Per-conversation safety-timer reset functions — called on chunk activity. */
  private safetyTimerResets = new Map<string, () => void>()

  /** Cleanup functions for all persistent event listeners registered in registerEventForwarders(). */
  private eventCleanups: Array<() => void> = []

  // CHAT-LEAK-01: Guard against callbacks firing after service disposal.
  // If dispose() runs while a queued callback is in the event loop, the
  // callback would execute against stale state without this flag.
  private isDisposed = false

  // N14: Track hook lifecycle listener for cleanup
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  private hookLifecycleHandler?: ((...args: any[]) => void) | undefined

  constructor(mainWindow: BrowserWindow, callbacks: PipelineCallbacks) {
    this.mainWindow = mainWindow
    this.callbacks = callbacks
    this.intentRouter = new IntentRouter(mainWindow)
    this.registerEventForwarders()
  }

  /**
   * Guard all IPC sends against destroyed windows.
   * During streaming the user may close the window — without this guard
   * every webContents.send() throws an unhandled exception.
   * The keepalive timer (30s interval) is particularly dangerous as it
   * fires repeatedly after window destruction.
   */
  private safeWindowSend(channel: string, ...args: unknown[]): void {
    try {
      if (!this.mainWindow.isDestroyed()) {
        this.mainWindow.webContents.send(channel, ...args)
      }
    } catch (error) {
      log.warn(`Failed to send IPC ${channel}:`, error)
    }
  }

  // ── Persistent Event Forwarders ──

  /**
   * Register once-at-startup event forwarders from agent → renderer.
   *
   * The typed 'intent' event handles all control actions (plan, askUser,
   * grill events) via IntentRouter. Legacy events (plan, grillQuestion,
   * grillComplete, grillEvaluation) are still emitted by the MCP control callbacks
   * for backward compat — their forwarders remain to handle the immediate MCP path.
   *
   * The IntentRouter handles post-stream regex-fallback intents + grill events
   * (which have no MCP tool equivalent and are always regex-detected).
   */
  /** Resolve a workspace name from its ID (for permission toast labels). */
  private resolveWorkspaceName(workspaceId: string): string {
    try {
      // eslint-disable-next-line @typescript-eslint/no-require-imports -- lazy load avoids db/repositories circular dependency
      const { workspaceRepository } = require('../db/repositories')
      const workspace = workspaceRepository.findById(workspaceId)
      return workspace?.name ?? workspaceId.slice(0, 8)
    } catch {
      return workspaceId.slice(0, 8)
    }
  }

  /**
   * Resolve the conversation ID that is currently streaming.
   *
   * Phase 2 note: Uses chatAgentService.getCurrentConversationId() as the
   * primary source — bridge events (plan, askUser, elicitation) are inherently
   * tied to the lastActiveConversationId. Falls back to the most recently
   * acquired streaming lock, then empty string.
   */
  private resolveStreamingConversationId(): string {
    // WRONG-STREAM-01: Use getCurrentConversationId() as the primary source.
    // Bridge events (plan, askUser, elicitation) from chatAgentService are inherently
    // tied to the lastActiveConversationId's stream processing. With multiple
    // concurrent streams, the first streamingLocks entry (Set insertion order) is
    // arbitrary and may attribute events to the wrong conversation.
    return chatAgentService.getCurrentConversationId()
      ?? [...this.streamingLocks].pop()
      ?? ''
  }

  private registerEventForwarders(): void {
    // compactNeeded is not an intent — keep as direct forwarder
    const onCompactNeeded = (data: CompactNeededMessage['compactNeeded']): void => {
      if (this.isDisposed) return
      const convId = this.resolveStreamingConversationId()
      this.safeWindowSend(
        IPC_CHANNELS.CHAT_MESSAGE_CHUNK,
        createCompactNeeded({
          conversationId: convId,
          requestId: this.activeRequestIds.get(convId) ?? undefined,
          role: this.currentStreamingRole,
          compactNeeded: data
        })
      )
    }
    chatAgentService.on('compactNeeded', onCompactNeeded)
    this.eventCleanups.push(() => chatAgentService.off('compactNeeded', onCompactNeeded))

    // Legacy forwarders for MCP-triggered events (fire during streaming)
    // These handle the immediate path when control tools fire via MCP callbacks.
    const onAskQuestion = (data: {
      questions: GrillQuestion[]
      action?: string
      requestId?: string
    }): void => {
      if (this.isDisposed) return
      this.safeWindowSend(IPC_CHANNELS.CHAT_ASK_QUESTION, {
        conversationId: this.resolveStreamingConversationId(),
        questions: data.questions,
        action: data.action,
        requestId: data.requestId
      })
    }
    chatAgentService.on('askQuestion', onAskQuestion)
    this.eventCleanups.push(() => chatAgentService.off('askQuestion', onAskQuestion))

    // Elicitation — MCP server user input requests forwarded to renderer
    const onElicitation = (data: ElicitationEvent): void => {
      if (this.isDisposed) return
      this.safeWindowSend(IPC_CHANNELS.ELICITATION_REQUEST, {
        conversationId: this.resolveStreamingConversationId(),
        ...data
      })
    }
    chatAgentService.on('elicitation', onElicitation)
    this.eventCleanups.push(() => chatAgentService.off('elicitation', onElicitation))

    // Budget cap reached — forward as a CHAT_MESSAGE_CHUNK with budgetCapReached field
    const onBudgetCapReached = (data: { conversationId: string; message: string }): void => {
      if (this.isDisposed) return
      this.safeWindowSend(IPC_CHANNELS.CHAT_MESSAGE_CHUNK, {
        conversationId: data.conversationId,
        requestId: this.activeRequestIds.get(data.conversationId) ?? undefined,
        budgetCapReached: {
          message: 'Turn budget reached — your work is safe.',
          canContinue: true
        }
      })
    }
    chatAgentService.on('budgetCapReached', onBudgetCapReached)
    this.eventCleanups.push(() => chatAgentService.off('budgetCapReached', onBudgetCapReached))

    // NOTE: The persistent 'plan' listener was removed to prevent duplicate delivery.
    // Plan events are now handled exclusively by the per-message onPlanEvent listener
    // in stream(), which both forwards to the renderer AND injects into streamedContent
    // for DB persistence. The CHAT_PLAN IPC is still sent by the IntentRouter below
    // for regex-fallback detected plans.

    // Multi-workspace permission routing for background workspaces
    this.registerMultiWorkspaceForwarders()

    // Typed intent handler — routes post-stream intents (regex fallback + grill events)
    // via IntentRouter. Skips plan/askUser if they were already sent by MCP forwarders above.
    const onIntent = (intent: AgentIntent): void => {
      if (this.isDisposed) return
      const conversationId = this.resolveStreamingConversationId()

      // Skip types that were already forwarded by MCP legacy listeners
      // (plan, askUser are emitted both by MCP callbacks and post-stream detection,
      // but IntentDetector.detectAll() already filters out MCP-fired types, so these
      // intents only arrive here when they're regex-fallback detected)
      this.intentRouter.route(conversationId, intent)
    }
    chatAgentService.on('intent', onIntent)
    this.eventCleanups.push(() => chatAgentService.off('intent', onIntent))

    // F7: Wire hook lifecycle events to the stream pipeline.
    // The HookEngine emits 'hookLifecycle' events when hooks start/complete/fail.
    // Forward these as StreamChunks so the renderer can show hook execution status.
    // N14: Store handler reference for cleanup in dispose().
    this.hookLifecycleHandler = (event: {
      hookId: string
      hookName: string
      hookEvent: string
      phase: 'started' | 'response'
      output?: string
      outcome?: string
    }) => {
      // HOOK-LIFECYCLE-NOISOL-01: Wrap in try-catch to prevent listener errors
      // from propagating through EventEmitter.emit() and crashing the hook
      // execution pipeline.
      try {
        const conversationId = this.resolveStreamingConversationId()
        if (!conversationId) return
        const chunk: StreamChunk = {
          type: 'hook_lifecycle',
          content: '',
          hookInfo: {
            hookId: event.hookId,
            hookName: event.hookName,
            hookEvent: event.hookEvent,
            phase: event.phase as 'started' | 'progress' | 'response',
            output: event.output,
            outcome: event.outcome as 'success' | 'error' | 'cancelled' | undefined
          }
        }
        forwardChunkToRenderer(
          this.mainWindow,
          conversationId,
          this.currentStreamingRole,
          chunk,
          { value: '' }, // hook chunks don't accumulate content
          chatAgentService.getWorkspacePath() ?? undefined,
          undefined,
          'specialist-responding',
          this.activeRequestIds.get(conversationId) ?? undefined,
          chatAgentService.getMode()
        )
      } catch (error) {
        log.warn('[STREAM:hook-lifecycle-handler] Error forwarding hook event:', error)
      }
    }
    hookEngine.on('hookLifecycle', this.hookLifecycleHandler)
  }

  /**
   * Register event forwarders for multi-workspace permission routing.
   * When a non-active workspace emits elicitation/askQuestion, routes through
   * SessionEventRouter so the NotificationStack can show a permission toast.
   * Extracted from registerEventForwarders() — structurally identical pair.
   */
  private registerMultiWorkspaceForwarders(): void {
    const onElicitationWs = (workspaceId: string, data: ElicitationEvent): void => {
      if (workspaceId !== chatAgentService.activeWorkspaceId) {
        try {
          const router = getSessionEventRouter()
          router.sendPermissionRequest({
            id: `elicit-${data.elicitationId ?? Date.now()}`,
            workspaceId,
            workspaceName: this.resolveWorkspaceName(workspaceId),
            type: 'elicitation',
            summary: data.message || 'Permission request from MCP server',
            isSimple: data.mode !== 'form',
            payload: data,
            receivedAt: Date.now()
          })
        } catch {
          // SessionEventRouter not yet initialized — fall through to legacy path
        }
      }
    }
    chatAgentService.on('elicitation:ws', onElicitationWs)
    this.eventCleanups.push(() => chatAgentService.off('elicitation:ws', onElicitationWs))

    const onAskQuestionWs = (
      workspaceId: string,
      data: { questions: GrillQuestion[]; action?: string; requestId?: string }
    ): void => {
      if (workspaceId !== chatAgentService.activeWorkspaceId) {
        try {
          const router = getSessionEventRouter()
          router.sendPermissionRequest({
            id: `ask-${data.requestId ?? Date.now()}`,
            workspaceId,
            workspaceName: this.resolveWorkspaceName(workspaceId),
            type: 'askQuestion',
            summary: data.questions?.[0]?.question || 'Question from agent',
            isSimple: false,
            payload: data,
            receivedAt: Date.now()
          })
        } catch {
          // SessionEventRouter not yet initialized — fall through to legacy path
        }
      }
    }
    chatAgentService.on('askQuestion:ws', onAskQuestionWs)
    this.eventCleanups.push(() => chatAgentService.off('askQuestion:ws', onAskQuestionWs))

    // Tool permission requests — route to toast UI for all workspaces.
    // Unlike askQuestion (inline for active workspace), tool permissions always
    // use the toast flow because they need explicit approve/deny, not free-text.
    const onPermissionRequestWs = (
      workspaceId: string,
      data: { toolName?: string; inputSummary?: string; requestId?: string; input?: Record<string, unknown> }
    ): void => {
      try {
        const router = getSessionEventRouter()
        const toolName = data.toolName ?? 'Unknown tool'

        // Resolve conversation context for the permission modal
        const session = chatAgentService.getSessionForWorkspace(workspaceId)
        const conversationId = session?.getCurrentConversationId()
        let conversationTitle: string | undefined
        if (conversationId) {
          try {
            const conv = conversationRepository.findById(conversationId)
            conversationTitle = conv?.title
          } catch { /* non-critical */ }
        }
        const mode = session?.getMode()

        router.sendPermissionRequest({
          id: `perm-${data.requestId ?? Date.now()}`,
          workspaceId,
          workspaceName: this.resolveWorkspaceName(workspaceId),
          type: 'toolPermission',
          toolName,
          toolInput: data.input,
          conversationTitle,
          mode,
          summary: `Agent wants to use ${toolName}${data.inputSummary ? `: ${data.inputSummary}` : ''}`,
          isSimple: true,
          payload: data,
          receivedAt: Date.now()
        })
      } catch {
        // SessionEventRouter not yet initialized
      }
    }
    chatAgentService.on('permissionRequest:ws', onPermissionRequestWs)
    this.eventCleanups.push(() => chatAgentService.off('permissionRequest:ws', onPermissionRequestWs))
  }

  // ── Extracted Lifecycle Methods ──

  /**
   * Acquire the streaming lock, transition the state machine, and begin
   * the conversation lifecycle. Throws if already streaming.
   */
  private acquireStreamLock(conversationId: string): {
    requestId: string
    signal: AbortSignal
    lifecycle: ConversationLifecycle
    resolveDone: () => void
    rejectDone: (err: Error) => void
    done: Promise<void>
  } {
    // Per-conversation lock: only reject if THIS conversation is already streaming
    if (this.streamingLocks.has(conversationId) || !conversationStateMachine.isIdle(conversationId)) {
      log.warn(`[STREAM:concurrent-rejected] Conversation ${conversationId} is already streaming`)
      throw new Error(
        'A message is already being processed in this chat. Please wait for it to complete or stop it first.'
      )
    }

    // Phase-2: Resource limit gate — reject when at max concurrent streams.
    // Each stream spawns a separate claude CLI process (CPU + memory cost).
    const activeStreams = lifecycleRegistry.active()
    if (
      activeStreams.length >= MAX_CONCURRENT_STREAMS &&
      !activeStreams.some((s) => s.conversationId === conversationId)
    ) {
      const busyConvId = activeStreams[0]?.conversationId ?? 'unknown'
      log.warn(
        `[STREAM:resource-limit] conversationId=${conversationId} ` +
          `blocked — ${activeStreams.length} active streams (MAX_CONCURRENT_STREAMS=${MAX_CONCURRENT_STREAMS})`
      )
      throw new Error(
        `Too many chats are processing simultaneously (max ${MAX_CONCURRENT_STREAMS}). ` +
        `Please wait for one to complete or stop it first. (blockedBy:${busyConvId})`
      )
    }

    // A5-FIX: Begin lifecycle BEFORE the state-machine transition.
    // If a stale-active registry entry exists for this conversation,
    // begin()'s supersede path calls existing.abort() → forceReset(convId).
    // If the SM transition ran first, that forceReset would wipe the
    // fresh 'chat-agent-streaming' state — leaving lock held + SM idle.
    const lifecycle = lifecycleRegistry.begin(conversationId)
    const requestId = lifecycle.requestId!

    this.streamingLocks.add(conversationId)
    // CHAT-SM-TRANSITION-UNCHECKED-01: If state machine rejects the transition,
    // release the lock immediately and abort the just-begun lifecycle.
    if (!conversationStateMachine.transition('sendMessage', conversationId)) {
      this.streamingLocks.delete(conversationId)
      lifecycle.abort('sm-rejected')
      throw new Error(
        `State machine rejected sendMessage — current state: ${conversationStateMachine.getState(conversationId)}`
      )
    }

    this.activeRequestIds.set(conversationId, requestId)
    this.stoppedConversations.delete(conversationId)

    // C3-FIX: Register lock-release disposer immediately at acquisition time.
    // This guarantees Stop (abort) during Stage 6.5's async optimization
    // releases the lock — even though registerStreamDisposers runs later (Stage 8).
    lifecycle.onDispose(() => {
      this.streamingLocks.delete(conversationId)
      this.activeRequestIds.delete(conversationId)
    })

    let settled = false
    let resolveDone!: () => void
    let rejectDone!: (err: Error) => void
    const done = new Promise<void>((resolve, reject) => {
      resolveDone = () => {
        if (settled) return
        settled = true
        resolve()
      }
      rejectDone = (err: Error) => {
        if (settled) return
        settled = true
        reject(err)
      }
    })

    return { requestId, signal: lifecycle.signal!, lifecycle, resolveDone, rejectDone, done }
  }

  /**
   * Snapshot the adapter identity for this stream turn.
   * Returns role, phase, and specialist metadata.
   */
  private resolveStreamIdentity(): {
    streamingRole: 'specialist'
    phase: ConversationPhase
    specialistMeta: { specialist: string; taskId?: string } | undefined
    adapterAgentId: string
  } {
    const messageRole = chatAgentService.getActiveMessageRole()
    const adapterAgentId = chatAgentService.getActiveAgentId()

    // Persona overlay (specialist impersonating a named specialist) — when active, the
    // adapter uses the base specialist internally, but both streaming chunks AND the
    // persisted DB message use the specialist's identity (role + agentId) so
    // the avatar is consistent across streaming, finalization, and DB reload.
    const persona = chatAgentService.getActivePersona()
    const streamingRole: 'specialist' = persona ? 'specialist' : messageRole
    const phase: ConversationPhase =
      streamingRole === 'specialist' ? 'specialist-executing' : 'specialist-responding'
    const specialistMeta = persona
      ? { specialist: persona.agentId, taskId: '' }
      : messageRole === 'specialist'
        ? { specialist: adapterAgentId }
        : undefined

    return { streamingRole, phase, specialistMeta, adapterAgentId }
  }

  /**
   * Start keepalive and safety timers for a stream.
   * Registers dispose handlers on the lifecycle — no manual cleanup needed.
   */
  private setupStreamTimers(
    conversationId: string,
    requestId: string,
    lifecycle: ConversationLifecycle,
    rejectDone: (err: Error) => void
  ): void {
    // Keepalive — prevents renderer's 2-min safety timer from firing.
    // Checks isDestroyed() to self-clear after window close — without this
    // the timer fires every 30s throwing unhandled exceptions.
    const keepaliveTimer = setInterval(() => {
      if (this.mainWindow.isDestroyed()) {
        clearInterval(keepaliveTimer)
        this.keepaliveTimers.delete(conversationId)
        return
      }
      // CHAT-KEEPALIVE-STALE-01: Validate the timer still references the current
      // lifecycle. If the lifecycle completed and a new stream started before this
      // interval fires, the captured conversationId/requestId are stale.
      if (!lifecycle.isActive || lifecycle.requestId !== requestId) {
        clearInterval(keepaliveTimer)
        this.keepaliveTimers.delete(conversationId)
        return
      }

      // KEEPALIVE-SAFETY-RESET: Reset backend safety timer on keepalive tick.
      // The keepalive proves the lifecycle is alive and a tool may be running
      // (e.g. a long bash command) — don't let the defense-in-depth 5-min timer
      // kill a legitimate long-running operation. The executor's own
      // TOOL_RESULT_TIMEOUT_MS (10 min) is the primary stall detector for
      // blocked tools; this safety timer is the backstop after keepalive stops.
      resetSafety()

      this.safeWindowSend(IPC_CHANNELS.CHAT_MESSAGE_CHUNK, {
        conversationId,
        requestId,
        keepalive: true
      })
    }, 30_000)
    this.keepaliveTimers.set(conversationId, keepaliveTimer)

    // Main-process safety timeout — last-resort recovery when no chunk/tool
    // activity arrives for 5 minutes. Unlike the old wall-clock timer, this
    // resets on every onChunk call (mirroring the renderer's resetSafetyTimer).
    // The CLI executor's own MESSAGE_TIMEOUT_MS (5 min) and TOOL_RESULT_TIMEOUT_MS
    // (10 min) are the primary stall detectors; this is defense-in-depth.
    const MAIN_PROCESS_SAFETY_TIMEOUT_MS = 5 * 60 * 1000
    let safetyCleared = false
    let safetyTimer: ReturnType<typeof setTimeout>

    const startSafetyTimer = (): void => {
      safetyTimer = setTimeout(() => {
        if (!safetyCleared && this.streamingLocks.has(conversationId)) {
          // SAFETY-LOG-LEVEL: Downgraded from error to warn. If the stream already
          // completed (resolveDone fired) the double-settle guard makes rejectDone
          // a no-op — this log would be a scary-looking no-op error. Using warn
          // preserves visibility without false alarm noise in production logs.
          log.warn(
            '[STREAM:main-safety-timeout] No chunk activity for 5 minutes — force-resetting. ' +
              `conversationId=${conversationId} requestId=${requestId}`
          )
          completeStreamMetrics(conversationId, 'timeout')
          lifecycleRegistry.abort(conversationId, 'safety-timeout')

          // SAFETY-COMPLETE-SIGNAL: Send a synthetic CHAT_MESSAGE_COMPLETE so the
          // renderer's handleMessageComplete fires and cleans up streamingConversationIds,
          // stashed state, and stall timers. Without this, the conversation can remain
          // stuck in streamingConversationIds if handleStateChange's idle-guard
          // (prevState === 'idle' → skip) prevents the forceReset cleanup path.
          this.safeWindowSend(
            IPC_CHANNELS.CHAT_MESSAGE_COMPLETE,
            createCompleteMessage({
              conversationId,
              messageId: `timeout-${conversationId}`,
              requestId
            })
          )

          rejectDone(new Error('Streaming timed out — safety recovery triggered'))
        }
      }, MAIN_PROCESS_SAFETY_TIMEOUT_MS)
    }

    const resetSafety = (): void => {
      if (safetyCleared) return
      clearTimeout(safetyTimer)
      startSafetyTimer()
    }

    startSafetyTimer()
    this.safetyTimerResets.set(conversationId, resetSafety)

    // MAX-LIFETIME: Absolute hard cap — independent of activity. Prevents truly
    // zombie streams where the executor hangs, lifecycle stays active, and
    // keepalive resets the safety timer indefinitely. Configurable via
    // maxStreamLifetimeMin preference (default 30, clamped 10–120).
    const lifetimeMin = appPreferenceRepository.getAppPreferences().maxStreamLifetimeMin
    const MAX_STREAM_LIFETIME_MS = lifetimeMin * 60 * 1000
    const lifetimeTimer = setTimeout(() => {
      if (!safetyCleared && this.streamingLocks.has(conversationId)) {
        log.warn(
          `[STREAM:max-lifetime] Stream exceeded ${lifetimeMin}-minute hard cap — force-aborting. ` +
            `conversationId=${conversationId} requestId=${requestId}`
        )
        completeStreamMetrics(conversationId, 'max-lifetime')
        lifecycleRegistry.abort(conversationId, 'max-lifetime')
        this.safeWindowSend(
          IPC_CHANNELS.CHAT_MESSAGE_COMPLETE,
          createCompleteMessage({
            conversationId,
            messageId: `max-lifetime-${conversationId}`,
            requestId
          })
        )
        rejectDone(new Error(`Stream exceeded maximum lifetime (${lifetimeMin} min) — force-aborted`))
      }
    }, MAX_STREAM_LIFETIME_MS)

    lifecycle.onDispose(() => {
      safetyCleared = true
      clearTimeout(safetyTimer)
      clearTimeout(lifetimeTimer)
      this.safetyTimerResets.delete(conversationId)
      const kt = this.keepaliveTimers.get(conversationId)
      if (kt) {
        clearInterval(kt)
        this.keepaliveTimers.delete(conversationId)
      }
    })
  }

  /**
   * Run prompt optimization if guards pass.
   * Returns the (possibly optimized) dispatch text, or null if aborted during the async call.
   */
  private async runPromptOptimization(params: {
    text: string
    conversationId: string
    requestId: string
    signal: AbortSignal
    streamingRole: 'specialist'
    workspaceId: string
    mode: 'plan' | 'build'
    attachments?: string[]
  }): Promise<string | null> {
    const { text, conversationId, requestId, signal, streamingRole, workspaceId, mode, attachments } = params

    const guardReason = promptOptimizerService.checkGuards({ text, workspaceId })
    if (guardReason) return text // guarded — use original

    const optimizerToolId = `prompt-optimizer-${Date.now()}`
    const inputPreview = text.length > 500 ? text.slice(0, 500) + '…' : text
    const startedAt = Date.now()

    /** Emit + record a tool-activity card to the renderer. */
    const emitCard = (card: {
      status: 'running' | 'completed' | 'error'
      result?: string
      resultDetail?: string
    }): void => {
      const activity = {
        id: optimizerToolId,
        toolName: 'Prompt Optimizer',
        status: card.status,
        input: inputPreview,
        ...(card.result != null ? { result: card.result } : {}),
        ...(card.resultDetail != null ? { resultDetail: card.resultDetail } : {}),
        startedAt,
        ...(card.status !== 'running' ? { completedAt: Date.now() } : {}),
        operationType: 'other' as const
      }
      this.safeWindowSend(
        IPC_CHANNELS.CHAT_MESSAGE_CHUNK,
        createToolActivityChunk({ conversationId, requestId, role: streamingRole, toolActivity: activity })
      )
      recordExternalToolActivity(conversationId, activity)
    }

    emitCard({ status: 'running' })

    // R6-B2: Notify chunk taps so E2E transcripts capture the optimizer run
    notifyChunkTaps(requestId, {
      type: 'tool_use',
      toolName: 'Prompt Optimizer',
      toolId: optimizerToolId,
      toolInput: inputPreview
    })

    const optimizeResult = await promptOptimizerService.optimize({
      text, workspaceId, conversationId, mode
    })

    if (signal.aborted) {
      log.info('[PIPELINE:prompt-optimizer] Aborted after optimization')
      return null
    }

    if (optimizeResult.changed) {
      const attachNote = attachments?.length
        ? `\n\n(${attachments.length} file attachment${attachments.length > 1 ? 's' : ''} appended after optimization)`
        : ''
      emitCard({
        status: 'completed',
        result: 'Prompt optimized for clarity',
        resultDetail: optimizeResult.optimizedText + attachNote
      })
      // R6-B2: Emit tool_result tap so transcripts show the rewritten prompt
      notifyChunkTaps(requestId, {
        type: 'tool_result',
        toolName: 'Prompt Optimizer',
        toolId: optimizerToolId,
        content: optimizeResult.optimizedText
      })
      log.info('[PIPELINE:prompt-optimizer] Prompt optimized')
      return optimizeResult.optimizedText
    }

    if (optimizeResult.skippedReason === 'error') {
      const detail = optimizeResult.errorDetail || 'unknown error'
      emitCard({ status: 'error', result: `Optimization skipped — ${detail}` })
      notifyChunkTaps(requestId, {
        type: 'tool_result',
        toolName: 'Prompt Optimizer',
        toolId: optimizerToolId,
        content: `Error: ${detail} — original prompt sent`
      })
      log.warn('[PIPELINE:prompt-optimizer] Error — using original prompt')
    } else if (optimizeResult.skippedReason) {
      // parse-error | empty-output | oversize — surface the real failure
      const reason = optimizeResult.skippedReason
      emitCard({ status: 'error', result: `Optimization failed (${reason}) — original prompt sent` })
      notifyChunkTaps(requestId, {
        type: 'tool_result',
        toolName: 'Prompt Optimizer',
        toolId: optimizerToolId,
        content: `Optimization failed (${reason}) — original prompt sent`
      })
      log.warn(`[PIPELINE:prompt-optimizer] Failed (${reason}) — using original prompt`)
    } else {
      emitCard({ status: 'completed', result: 'No changes needed' })
      notifyChunkTaps(requestId, {
        type: 'tool_result',
        toolName: 'Prompt Optimizer',
        toolId: optimizerToolId,
        content: 'No changes needed'
      })
    }

    return text // unchanged — use original
  }

  /**
   * Register centralized cleanup disposers — runs on both complete() and abort().
   */
  private registerStreamDisposers(
    lifecycle: ConversationLifecycle,
    conversationId: string,
    onChunk: (chunk: StreamChunk) => void,
    onComplete: () => void,
    onIntent: (intent: AgentIntent) => Promise<void>,
    onPlanEvent: (data: PlanDetectedEvent) => void
  ): void {
    // NOTE: Lock release (streamingLocks + activeRequestIds) is registered in
    // acquireStreamLock() so it's active before any async stages. Do not
    // duplicate it here.

    // COMPACT-ABORT-01: Clear per-conversation adapter state (pending compaction,
    // pending context injection) on lifecycle abort. Without this, stale state
    // from an aborted stream is consumed by the next message.
    // Only clears adapter pending state — not the session map (conversation should
    // still be resumable after stop).
    lifecycle.onDispose(() => {
      chatAgentService.clearConversationPendingState(conversationId)
    })

    // CHAT-TEXTBATCHER-ORPHAN-01: Flush/drain the text delta batcher on lifecycle
    // abort. Without this, buffered text fires 33ms later into an aborted
    // conversation — stale text appears in UI after the "stopped" indicator.
    lifecycle.onDispose(() => {
      flushTextBatcher(conversationId)
    })

    // F-19: Clear accumulated tool activities on lifecycle abort.
    // Without this, tool activities from an aborted stream sit in memory
    // until the next stream() call clears them. Defense-in-depth cleanup.
    // CHAT-TOOLACTIVITY-DOUBLECLEAR-01: Only clear if stop() hasn't
    // already cleared (stoppedConversations means stop() handled it).
    lifecycle.onDispose(() => {
      if (!this.stoppedConversations.has(conversationId)) {
        getAndClearToolActivities(conversationId)
      }
    })

    // N1-FIX: The C3 disposer was removed because lifecycle.complete()
    // fires at the end of every stream (not just on conversation end), which wiped
    // the dedupe set every turn. Cleanup now happens in dispose() and
    // clearConversationMemoryState().

    // Remove per-stream listeners
    lifecycle.onDispose(() => {
      chatAgentService.removeListener('chunk', onChunk)
      chatAgentService.removeListener('complete', onComplete)
      chatAgentService.removeListener('intent', onIntent)
      chatAgentService.removeListener('plan', onPlanEvent)
    })

    // Invoke caller-supplied stop pipeline hook on lifecycle dispose.
    // onStopPipeline is required to be idempotent — the duplicate call is harmless.
    lifecycle.onDispose(() => {
      this.callbacks.onStopPipeline().catch((e) => {
        log.warn('[STREAM] Lifecycle dispose: onStopPipeline failed:', e)
      })
    })

    // ORPHAN-EXECUTOR-FIX: Kill the CLI process on lifecycle abort.
    // Without this, safety-timeout and workspace-switch abort paths only
    // release locks and remove listeners — the executor keeps running.
    // cancelCurrentQuery() is idempotent; the duplicate call from stop()'s
    // finally block is harmless.
    // Phase-2: Per-conversation cancel — only kills THIS conversation's query,
    // not any sibling streams.
    lifecycle.onDispose(() => {
      try {
        chatAgentService.cancelCurrentQuery(conversationId)
      } catch (e) {
        log.warn('[STREAM] Lifecycle dispose: cancelCurrentQuery failed:', e)
      }
    })
  }

  /**
   * Send the empty identity chunk to renderer so the avatar matches from frame one.
   */
  private announceStreamStart(
    conversationId: string,
    requestId: string,
    streamingRole: 'specialist',
    phase: ConversationPhase,
    specialistMeta: { specialist: string; taskId?: string } | undefined
  ): void {
    this.safeWindowSend(
      IPC_CHANNELS.CHAT_MESSAGE_CHUNK,
      createTextChunk({
        conversationId,
        requestId,
        text: '',
        role: streamingRole,
        phase,
        specialist: specialistMeta?.specialist,
        taskId: specialistMeta?.taskId
      })
    )
  }

  /**
   * Process attachments and return text content + image data.
   */
  private prepareUserMessage(
    text: string,
    attachments?: string[]
  ): { fullContent: string; imageAttachments: ImageAttachment[] } {
    let fullContent = text
    let imageAttachments: ImageAttachment[] = []

    if (attachments && attachments.length > 0) {
      const result = this.processAttachments(attachments)
      fullContent += result.textContent
      imageAttachments = result.images
    }

    return { fullContent, imageAttachments }
  }

  /**
   * Wire listeners, do mode switch, call chatAgentService.send(), handle catch.
   */
  private async dispatchToAgent(
    conversationId: string,
    fullContent: string,
    imageAttachments: ImageAttachment[],
    listeners: {
      onChunk: (chunk: StreamChunk) => void
      onComplete: () => void
      onIntent: (intent: AgentIntent) => Promise<void>
      onPlanEvent: (data: PlanDetectedEvent) => void
    },
    ctx: StreamContext,
    requestId: string,
    rejectDone: (err: Error) => void
  ): Promise<void> {
    try {
      const conversation = conversationRepository.findById(conversationId)
      if (conversation && conversation.mode !== chatAgentService.getMode()) {
        log.info(`Deferred mode switch: ${chatAgentService.getMode()} → ${conversation.mode}`)
        await chatAgentService.switchMode(conversation.mode as ConversationMode)
      }

      chatAgentService.on('chunk', listeners.onChunk)
      chatAgentService.on('complete', listeners.onComplete)
      chatAgentService.on('intent', listeners.onIntent)
      chatAgentService.on('plan', listeners.onPlanEvent)

      // Per-turn memory injection: prepend relevant facts to the user message
      let enrichedContent = fullContent
      try {
        const workspace = ctx.workspacePath ? workspaceRepository.findByPath(ctx.workspacePath) : undefined
        if (workspace) {
          // Get or create the dedupe set for this conversation
          if (!this.injectedFactIds.has(conversationId)) {
            // N1-FIX: LRU cap — evict oldest entry when the map exceeds 50
            // conversations. Backstop against unbounded growth when dispose()
            // doesn't run (e.g. long-lived singleton).
            if (this.injectedFactIds.size >= 50) {
              const oldest = this.injectedFactIds.keys().next().value
              if (oldest) this.injectedFactIds.delete(oldest)
            }
            this.injectedFactIds.set(conversationId, new Set())
          } else {
            // L1-FIX: True LRU — refresh Map insertion order so the most
            // recently accessed conversation is evicted last.
            const existing = this.injectedFactIds.get(conversationId)!
            this.injectedFactIds.delete(conversationId)
            this.injectedFactIds.set(conversationId, existing)
          }
          const dedupeSet = this.injectedFactIds.get(conversationId)!
          const memoryContext = await memoryRetrievalService.getContextForTurn(
            workspace.id,
            fullContent,
            'medium',
            dedupeSet
          )
          if (memoryContext) {
            enrichedContent = `[Relevant Workspace Knowledge]\n${memoryContext}\n\n---\n\n${fullContent}`
          }
        }
      } catch (memErr) {
        log.debug('Per-turn memory retrieval failed (non-fatal):', memErr)
      }

      await chatAgentService.send(
        enrichedContent,
        conversationId,
        imageAttachments.length > 0 ? imageAttachments : undefined
      )
    } catch (error) {
      // Lifecycle abort handles: streamingLock, listener removal, state machine force-reset
      lifecycleRegistry.abort(conversationId, 'streamError')
      completeStreamMetrics(conversationId, 'error')

      eventLoggerService.logSessionFailed({
        conversationId,
        agentId: ctx.adapterAgentId,
        error: (error as Error).message
      })

      const roleLabel = 'Specialist'
      log.error(`${roleLabel} send failed:`, (error as Error).message)
      const errorMsg = `**${roleLabel} Error:** ${(error as Error).message}\n\nMake sure Claude CLI is installed and a workspace is open.`
      const savedMessage = messageRepository.create(
        conversationId,
        ctx.streamingRole,
        errorMsg,
        ctx.specialistMeta?.specialist ?? ctx.adapterAgentId
      )

      // Persist any tool activities accumulated before the error
      const errorToolActivities = getAndClearToolActivities(conversationId)
      if (errorToolActivities.length > 0) {
        try {
          messageRepository.updateToolActivities(savedMessage.id, errorToolActivities)
        } catch (toolErr) {
          log.error(
            `[PIPELINE:tool-activities-lost] messageId=${savedMessage.id} count=${errorToolActivities.length}:`,
            toolErr
          )
        }
      }

      this.safeWindowSend(
        IPC_CHANNELS.CHAT_MESSAGE_CHUNK,
        createTextChunk({
          conversationId,
          requestId,
          text: errorMsg,
          role: ctx.streamingRole
        })
      )
      this.safeWindowSend(
        IPC_CHANNELS.CHAT_MESSAGE_COMPLETE,
        createCompleteMessage({
          conversationId,
          messageId: savedMessage.id,
          requestId
        })
      )
      // Note: lifecycle.abort('streamError') already force-reset the state machine to idle
      rejectDone(error instanceof Error ? error : new Error(String(error)))
    }
  }

  /**
   * Persist the streamed message to DB, process memory blocks, and notify renderer.
   * Extracted from the onComplete closure — all error paths transition the state machine.
   */
  private async finalizeStreamMessage(ctx: StreamContext, lifecycle: ConversationLifecycle): Promise<void> {
    // CHAT-STOP-COMPLETE-RACE-01: Re-check after the async gap between onComplete's
    // guard and this method's DB write. If stop() ran between the guard passing and
    // this point, it already saved a "stopped" message — skip to avoid duplicates.
    if (this.stoppedConversations.has(ctx.conversationId)) {
      log.info('[PIPELINE:finalize-skipped] Stream was stopped during finalization')
      return
    }

    // CHAT-FINALIZE-ORPHAN-01: Verify this finalization still belongs to the
    // current lifecycle. If a new stream started (superseding this one), the
    // lifecycle's requestId will have changed. Skip to avoid corrupting the
    // new stream's state machine.
    if (lifecycle.requestId !== ctx.requestId) {
      log.info(
        `[PIPELINE:finalize-orphaned] requestId mismatch ` +
        `(lifecycle=${lifecycle.requestId} ctx=${ctx.requestId}) — skipping`
      )
      return
    }

    try {
      log.info('Agent complete — saving to DB:', { contentLen: ctx.streamedContent.length })
      const cleanedContent = ctx.streamedContent.trim()

      if (!cleanedContent) {
        const accumulatedText = chatAgentService.getStreamedContent(ctx.conversationId)
        log.error(
          `[PIPELINE:silent-failure] Agent completed with no streamed content. ` +
            `streamedLen=${ctx.streamedContent.length} ` +
            `accumulatedLen=${accumulatedText?.length ?? 0} ` +
            `executorBackend=${chatAgentService.getExecutorBackend()} ` +
            `role=${ctx.streamingRole} specialist=${ctx.specialistMeta?.specialist ?? 'none'} ` +
            `accumulatedPreview=${(accumulatedText ?? '').slice(0, 200).replace(/\n/g, ' ')}`
        )

        // Surface the failure to the user instead of saving an empty message
        this.safeWindowSend(
          IPC_CHANNELS.CHAT_MESSAGE_CHUNK,
          createTextChunk({
            conversationId: ctx.conversationId,
            requestId: ctx.requestId,
            text: '\n\n**Error:** Agent produced no response. Check the app logs for details.',
            role: ctx.streamingRole
          })
        )
      }

      // FINALIZE-ATOM-01: Wrap message creation + tool activity persistence in a
      // transaction. If the conversation is cascade-deleted between the two calls,
      // both operations roll back together instead of leaving orphaned data.
      const toolActivities = getAndClearToolActivities(ctx.conversationId)
      const contentToSave =
        cleanedContent || '**Error:** Agent produced no response. Check the app logs for details.'
      const agentId = ctx.specialistMeta?.specialist ?? ctx.adapterAgentId

      let savedMessage: { id: string }
      try {
        const { getDatabase } = await import('../db/index')

        // CHAT-STOP-FINALIZE-DOUBLESAVE-01: Re-check after async gap.
        // stop() may have run during the await, saving its own "stopped" message.
        // Without this guard, both stop()'s message AND this finalization's message
        // are saved — creating a duplicate in the conversation.
        if (this.stoppedConversations.has(ctx.conversationId)) {
          log.info('[PIPELINE:finalize-skipped-post-await] Stopped during DB import await')
          return
        }

        const db = getDatabase()
        savedMessage = db.transaction(() => {
          const msg = messageRepository.create(
            ctx.conversationId,
            ctx.streamingRole,
            contentToSave,
            agentId
          )
          if (toolActivities.length > 0) {
            messageRepository.updateToolActivities(msg.id, toolActivities)
            log.info(
              `[PIPELINE:tool-activities-persisted] messageId=${msg.id} count=${toolActivities.length}`
            )
          }
          return msg
        })()
      } catch (txErr) {
        // CHAT-FINALIZE-FALLBACK-01: Distinguish test environment (no DB) from
        // real DB errors. Only fall back to non-transactional insert for expected
        // test/no-DB scenarios. Real errors (disk full, FK violation) should surface.
        // Deterministic check: process.versions.electron is set in packaged Electron
        // but absent under tsx/node test runners — no string-matching needed.
        const isTestEnv = !process.versions.electron
        if (!isTestEnv) {
          log.error('[PIPELINE:finalize-tx-failed] Transaction failed with real DB error:', txErr)
          throw txErr
        }
        // Fallback: non-transactional (test environment without DB)
        savedMessage = messageRepository.create(
          ctx.conversationId,
          ctx.streamingRole,
          contentToSave,
          agentId
        )
        if (toolActivities.length > 0) {
          try {
            messageRepository.updateToolActivities(savedMessage.id, toolActivities)
            log.info(
              `[PIPELINE:tool-activities-persisted] messageId=${savedMessage.id} count=${toolActivities.length}`
            )
          } catch (toolErr) {
            log.error(
              `[PIPELINE:tool-activities-lost] messageId=${savedMessage.id} count=${toolActivities.length}:`,
              toolErr
            )
          }
        }
      }
      log.info('Agent message saved, id:', savedMessage.id)

      // Enqueue memory extraction from transcript + git delta
      this.enqueueMemoryExtraction(ctx)

      log.info(
        `[PIPELINE:agent-message-saved] messageId=${savedMessage.id} contentLen=${cleanedContent.length}`
      )
      this.safeWindowSend(
        IPC_CHANNELS.CHAT_MESSAGE_COMPLETE,
        createCompleteMessage({
          conversationId: ctx.conversationId,
          messageId: savedMessage.id,
          requestId: ctx.requestId
        })
      )
    } catch (error) {
      log.error('Failed to save agent message:', error)
      this.safeWindowSend(
        IPC_CHANNELS.CHAT_MESSAGE_CHUNK,
        createTextChunk({
          conversationId: ctx.conversationId,
          requestId: ctx.requestId,
          text: `\n\n**Error saving response:** ${(error as Error).message}`,
          role: ctx.streamingRole
        })
      )
      this.safeWindowSend(
        IPC_CHANNELS.CHAT_MESSAGE_COMPLETE,
        createCompleteMessage({
          conversationId: ctx.conversationId,
          messageId: `error-${Date.now()}`,
          requestId: ctx.requestId
        })
      )
    }

    // ALWAYS transition state machine — regardless of success or failure.
    // This is the single point where streaming → idle happens on the happy path.
    // CHAT-FINALIZE-ORPHAN-01: Re-check before transitioning — the async gap in
    // the try block above may have allowed a new stream to start.
    if (lifecycle.requestId === ctx.requestId) {
      conversationStateMachine.transition('chatAgentComplete', ctx.conversationId)
    } else {
      log.info(
        `[PIPELINE:finalize-orphaned-transition] requestId mismatch after DB write ` +
        `(lifecycle=${lifecycle.requestId} ctx=${ctx.requestId}) — skipping transition`
      )
    }

    // Log stream completion metrics (TTFT, duration, chunk count, chars)
    completeStreamMetrics(ctx.conversationId, 'complete')
  }

  /**
   * Enqueue fact extraction from the completed stream transcript + git delta.
   * Replaces the old processMemoryBlocks regex-based extraction.
   */
  private enqueueMemoryExtraction(ctx: StreamContext): void {
    try {
      const wpPath = ctx.workspacePath
      const workspace = wpPath ? workspaceRepository.findByPath(wpPath) : undefined
      if (workspace && ctx.streamedContent.length > 200) {
        // Gate on sessionCapture setting
        const settings = workspaceRepository.getSettings(workspace.id) as Record<string, unknown>
        if (settings.memorySessionCapture === false) return
        memoryExtractionService.enqueueSessionExtraction({
          workspaceId: workspace.id,
          workspacePath: wpPath ?? null,
          transcript: ctx.streamedContent,
          startSha: ctx.startSha ?? null,
          conversationId: ctx.conversationId
        })
      }
    } catch (err) {
      log.warn('Memory extraction enqueue failed:', err)
    }
  }

  // ── Stream Listener Factory ──

  /**
   * Builds the per-stream event listeners as a cohesive object.
   * Extracted from stream() to reduce its cyclomatic complexity.
   */
  private buildStreamListeners(
    ctx: StreamContext,
    lifecycle: ConversationLifecycle,
    resolveDone: () => void,
    rejectDone: (err: Error) => void
  ): {
    onChunk: (chunk: StreamChunk) => void
    onComplete: () => void
    onIntent: (intent: AgentIntent) => Promise<void>
    onPlanEvent: (data: PlanDetectedEvent) => void
  } {
    // Adapter for forwardChunkToRenderer which still expects { value: string }
    const streamedContentRef = {
      get value() {
        return ctx.streamedContent
      },
      set value(v: string) {
        ctx.streamedContent = v
      }
    }

    const onChunk = (chunk: StreamChunk): void => {
      // CHAT-ONCHUNK-NO-LIFECYCLE-GUARD: Skip chunks after lifecycle abort
      // or supersession. Matches the guard in onComplete.
      if (!lifecycle.isActive || lifecycle.requestId !== ctx.requestId) {
        return
      }
      // SAFETY-TIMER-RESET: Reset the main-process safety timer on every
      // chunk (text, tool_use, tool_result). Prevents the timer from killing
      // active-but-long-running build sessions with heavy tool use.
      this.safetyTimerResets.get(ctx.conversationId)?.()

      try {
        log.info(
          `[STREAM:chunk] type=${chunk.type} len=${chunk.content?.length ?? 0} convId=${ctx.conversationId.slice(0, 8)}`
        )
        forwardChunkToRenderer(
          this.mainWindow,
          ctx.conversationId,
          ctx.streamingRole,
          chunk,
          streamedContentRef,
          ctx.workspacePath,
          ctx.specialistMeta,
          ctx.phase,
          ctx.requestId,
          chatAgentService.getMode()
        )
      } catch (error) {
        log.error('Failed to forward chunk to renderer:', error)
      }
    }

    const cleanupListeners = (): void => {
      if (lifecycle.isActive) {
        lifecycle.complete()
      }
    }

    const onComplete = (): void => {
      // Flush any pending batched text deltas before finalizing
      flushTextBatcher(ctx.conversationId)

      // CHAT-FINALIZE-DELETE-01: After lifecycle.abort(), the abortController is set
      // to null, making signal null and signal?.aborted undefined (falsy). Using
      // !lifecycle.isActive correctly catches both abort-then-complete
      // and delete-then-complete scenarios. isActive is false when abortController
      // is null — which happens after both abort() and complete().
      if (this.stoppedConversations.has(ctx.conversationId) || !lifecycle.isActive) {
        // CHAT-METRICS-ABORT-ORPHAN-01: Clean up metrics on abort-triggered completion.
        // Idempotent if stop() already called completeStreamMetrics.
        completeStreamMetrics(ctx.conversationId, 'aborted')
        cleanupListeners()
        resolveDone()
        return
      }

      this.finalizeStreamMessage(ctx, lifecycle)
        .then(() => {
          cleanupListeners()
          resolveDone()
        })
        .catch((err) => {
          log.error('[PIPELINE:complete] Finalize failed:', err)
          // STREAM-METRICS-STORE-LEAK-01: If finalizeStreamMessage crashed before
          // calling completeStreamMetrics, clean up the orphaned metrics entry.
          // Idempotent — harmless if already called inside finalizeStreamMessage.
          completeStreamMetrics(ctx.conversationId, 'error')
          // Safety net: if finalizeStreamMessage's inner catch block threw before
          // reaching the transition (e.g. mainWindow destroyed), ensure the state
          // machine still moves to idle. Idempotent when already idle.
          // CHAT-FINALIZE-ORPHAN-01: Only transition if lifecycle is still ours —
          // a new stream may have started during the failed finalization.
          if (lifecycle.requestId === ctx.requestId) {
            conversationStateMachine.transition('chatAgentComplete', ctx.conversationId)
          }
          cleanupListeners()
          rejectDone(err instanceof Error ? err : new Error(String(err)))
        })
    }

    const onIntent = async (_intent: AgentIntent): Promise<void> => {
      // No-op — handled by IntentRouter's persistent listener
    }

    const onPlanEvent = (data: PlanDetectedEvent): void => {
      if (ctx.planInjected) {
        log.warn('[PIPELINE:plan-skipped] Plan already injected this stream — skipping duplicate')
        return
      }
      ctx.planInjected = true

      const planBlock = `\n\n\`\`\`plan\n${data.rawContent}\n\`\`\`\n\n`
      ctx.streamedContent += planBlock
      this.safeWindowSend(
        IPC_CHANNELS.CHAT_MESSAGE_CHUNK,
        createTextChunk({
          conversationId: ctx.conversationId,
          requestId: ctx.requestId,
          text: planBlock,
          role: ctx.streamingRole
        })
      )
      // Dual-write: register plan in Plan Hub registry (non-critical)
      try {
        const workspaceId = chatAgentService.activeWorkspaceId
        if (workspaceId && data.structuredPlan) {
          planRegistryService.registerChatPlan({
            workspaceId,
            conversationId: ctx.conversationId,
            messageId: ctx.requestId,
            plan: data.structuredPlan,
            rawContent: data.rawContent
          })
        }
      } catch (err) {
        log.warn('[PIPELINE:plan-registry-failed] Non-critical:', err)
      }

      log.info(
        '[PIPELINE:plan-injected] Plan block injected into streamed content and forwarded to renderer'
      )
    }

    return { onChunk, onComplete, onIntent, onPlanEvent }
  }

  // ── Stream Lifecycle ──

  /**
   * Full streaming lifecycle — orchestrates the decomposed stages.
   */
  async stream(
    conversationId: string,
    text: string,
    attachments?: string[],
    opts?: { optimizePrompt?: boolean; hidden?: boolean }
  ): Promise<StreamHandle> {
    // Stage 1: Acquire lock + lifecycle
    const { requestId, signal, lifecycle, resolveDone, rejectDone, done } =
      this.acquireStreamLock(conversationId)

    // Stage 2: Ensure workspace session is live
    const conv = conversationRepository.findById(conversationId)
    try {
      const ws = conv ? workspaceRepository.findById(conv.workspaceId) : undefined
      if (ws?.repoPath) await chatAgentService.ensureStarted(ws.id, ws.repoPath)
    } catch (error) {
      lifecycleRegistry.abort(conversationId, 'streamError')
      throw error
    }

    // Stage 3: Resolve identity
    const { streamingRole, phase, specialistMeta, adapterAgentId } = this.resolveStreamIdentity()
    this.currentStreamingRole = streamingRole

    // Stage 4: Announce streaming identity to renderer
    this.announceStreamStart(conversationId, requestId, streamingRole, phase, specialistMeta)

    // Stage 5: Setup timers (keepalive + safety)
    this.setupStreamTimers(conversationId, requestId, lifecycle, rejectDone)

    // Clear any stale tool activities from a previous crashed stream
    getAndClearToolActivities(conversationId)

    // Start stream metrics tracking (TTFT, chunk count, total chars, duration)
    startStreamMetrics(conversationId)

    // Stage 6: Save original user message + run prompt optimization
    const attachmentsJson = attachments ? JSON.stringify(attachments) : '[]'
    messageRepository.create(conversationId, 'user', text, undefined, attachmentsJson, { hidden: opts?.hidden })
    log.info('User message saved to DB')

    // Stage 6.5: Prompt Optimization (chat plan/build only — skipped for programmatic callers)
    let dispatchText = text
    const convMode = (conv?.mode ?? chatAgentService.getMode()) as 'plan' | 'build'
    if (opts?.optimizePrompt !== false && conv && (convMode === 'plan' || convMode === 'build')) {
      const result = await this.runPromptOptimization({
        text, conversationId, requestId, signal, streamingRole,
        workspaceId: conv.workspaceId, mode: convMode, attachments
      })
      if (result === null) {
        // H1-FIX: settle the done promise before returning
        resolveDone()
        return { done, abort: () => lifecycleRegistry.abort(conversationId, 'external'), requestId }
      }
      dispatchText = result
    }

    // Stage 6.9: Prepare dispatch content (uses optimized text if changed)
    const { fullContent, imageAttachments } = this.prepareUserMessage(dispatchText, attachments)

    // Stage 7: Build context + listeners
    // Capture HEAD sha for memory extraction (async to avoid blocking main thread)
    let startSha: string | undefined
    const wpPath = chatAgentService.getWorkspacePath()
    if (wpPath) {
      try {
        const { exec } = require('node:child_process')
        startSha = await new Promise<string | undefined>((resolve) => {
          exec('git rev-parse HEAD 2>/dev/null || true', {
            cwd: wpPath, encoding: 'utf-8', timeout: 2000
          }, (err: Error | null, stdout: string) => {
            resolve(err ? undefined : (stdout?.trim() || undefined))
          })
        })
      } catch { /* no git — fine */ }
    }

    const ctx: StreamContext = {
      conversationId,
      requestId,
      streamingRole,
      phase,
      specialistMeta,
      adapterAgentId,
      workspacePath: wpPath ?? undefined,
      startSha,
      streamedContent: '',
      planInjected: false
    }

    const { onChunk, onComplete, onIntent, onPlanEvent } = this.buildStreamListeners(
      ctx,
      lifecycle,
      resolveDone,
      rejectDone
    )

    // Stage 8: Register disposers (needs listener refs)
    this.registerStreamDisposers(lifecycle, conversationId, onChunk, onComplete, onIntent, onPlanEvent)

    // Stage 9: Dispatch to agent
    await this.dispatchToAgent(
      conversationId,
      fullContent,
      imageAttachments,
      { onChunk, onComplete, onIntent, onPlanEvent },
      ctx,
      requestId,
      rejectDone
    )

    // Return StreamHandle — callers can optionally await `done` for full pipeline completion
    return { done, abort: () => lifecycleRegistry.abort(conversationId, 'external'), requestId }
  }

  /**
   * Process file attachments into text content and image data.
   * Detects images vs text files, reads content, estimates tokens.
   * Extracted from stream() — pure data-transformation concern.
   */
  private processAttachments(attachments: string[]): {
    textContent: string
    images: ImageAttachment[]
  } {
    const images: ImageAttachment[] = []
    const parts: string[] = []

    for (const filePath of attachments) {
      try {
        if (fileService.isImageFile(filePath)) {
          const { base64, mimeType } = fileService.readImageAsBase64(filePath)
          const fileName = filePath.split('/').pop() || filePath.split('\\').pop() || 'image'
          images.push({ base64, mimeType, fileName })
          parts.push(
            `\n---\n**Attached image: ${fileName}** (${mimeType}) — visible in the conversation\n`
          )
        } else {
          const content = fileService.readFileContent(filePath)
          const tokens = fileService.estimateTokens(content)
          parts.push(
            `\n---\n**Attached file: ${filePath}** (${tokens} tokens)\n\`\`\`\n${content}\n\`\`\`\n`
          )
        }
      } catch (error) {
        parts.push(`\n---\n**Failed to read: ${filePath}**: ${(error as Error).message}\n`)
      }
    }

    return { textContent: parts.join(''), images }
  }

  // ── Stop ──

  /**
   * Stop streaming for a specific conversation, or all conversations if no ID given.
   * Passing no conversationId preserves backward compat with e2e helpers (fixes P6).
   */
  async stop(targetConversationId?: string): Promise<void> {
    // F3-FIX: Wrap in try/finally so cancelCurrentQuery() always runs.
    // onStopPipeline() (inside stopSingleConversation) can throw — without
    // the finally, the CLI query would never be cancelled → orphaned generation.
    try {
      if (!targetConversationId) {
        // Stop ALL active streams (backward compat / e2e)
        const activeStreams = lifecycleRegistry.active()
        if (activeStreams.length === 0) {
          // Nothing streaming — fall through to legacy single-stop path
          await this.stopSingleConversation(chatAgentService.getCurrentConversationId())
        } else {
          // R1-FIX: Wrap each stopSingleConversation in try/catch so one
          // failing stop (e.g. onStopPipeline throws) doesn't strand sibling
          // streams' lifecycles — their locks stay held and gate 1 rejects
          // all subsequent sends until forceResetIfStuck runs.
          for (const stream of activeStreams) {
            try {
              await this.stopSingleConversation(stream.conversationId)
            } catch (stopErr) {
              log.error(
                `[STREAM:stop-partial-failure] Failed to stop conversation=${stream.conversationId}:`,
                stopErr
              )
            }
          }
        }
      } else {
        await this.stopSingleConversation(targetConversationId)
      }
    } finally {
      // Phase-2: Cancel per-conversation or ALL depending on whether a target was given.
      try {
        chatAgentService.cancelCurrentQuery(targetConversationId)
      } catch (cancelErr) {
        log.error('[STREAM:stop-cancel-failed] cancelCurrentQuery threw:', cancelErr)
      }
    }
  }

  private async stopSingleConversation(conversationId: string | null): Promise<void> {
    if (conversationId) {
      this.stoppedConversations.add(conversationId)
    }

    // Stop keepalive timer for this conversation
    if (conversationId) {
      const kt = this.keepaliveTimers.get(conversationId)
      if (kt) {
        clearInterval(kt)
        this.keepaliveTimers.delete(conversationId)
      }
    }

    const lifecycle = conversationId ? lifecycleRegistry.get(conversationId) : undefined
    const requestId = conversationId
      ? (this.activeRequestIds.get(conversationId) ?? lifecycle?.requestId ?? `req-stop-${Date.now()}`)
      : `req-stop-${Date.now()}`

    try {
      // P2-FIX: onStopPipeline() moved INSIDE the try block so that if it
      // throws, the finally still runs completeStreamMetrics + lifecycleRegistry.abort.
      // Previously it sat above try — a throw would strand this conversation's
      // lock (gate 1 rejects sends until forceResetIfStuck's 5-min timer).
      // The R1 loop catch in stop() protects siblings; this protects the self.
      await this.callbacks.onStopPipeline()

      // Save partial content
      if (conversationId) {
        try {
          // Phase-2: Always use per-conversation getStreamedContent — each
          // conversation has its own accumulator now.
          const partialContent = chatAgentService.getStreamedContent(conversationId)
          const contentToSave = partialContent
            ? partialContent + '\n\n---\n\n⏹ *Generation stopped by user.*'
            : '⏹ *Generation stopped by user.*'

          // Snapshot the active adapter for the stop path — runs from a different
          // IPC entry point and has no per-turn snapshot in scope.
          // A3-FIX: Only read persona/role from chatAgentService when this
          // conversation owns the active session, otherwise use defaults.
          const stopPersona = isActiveSession
            ? chatAgentService.getActivePersona()
            : undefined
          const stopRole = stopPersona ? 'specialist' : (
            isActiveSession ? chatAgentService.getActiveMessageRole() : 'specialist'
          )
          const stopAgentId = stopPersona?.agentId ?? (
            isActiveSession ? chatAgentService.getActiveAgentId() : 'specialist'
          )
          const savedMessage = messageRepository.create(
            conversationId,
            stopRole,
            contentToSave,
            stopAgentId
          )
          log.info('Stopped message saved to DB, id:', savedMessage.id)

          // Persist tool activities accumulated before user stopped
          const stopToolActivities = getAndClearToolActivities(conversationId)
          if (stopToolActivities.length > 0) {
            try {
              messageRepository.updateToolActivities(savedMessage.id, stopToolActivities)
              log.info(
                `[PIPELINE:tool-activities-persisted-on-stop] count=${stopToolActivities.length}`
              )
            } catch (toolErr) {
              log.error(
                `[PIPELINE:tool-activities-lost] messageId=${savedMessage.id} count=${stopToolActivities.length}:`,
                toolErr
              )
            }
          }

          this.safeWindowSend(
            IPC_CHANNELS.CHAT_MESSAGE_COMPLETE,
            createCompleteMessage({
              conversationId,
              messageId: savedMessage.id,
              requestId
            })
          )
        } catch (error) {
          log.error('Failed to save stopped message:', error)
        }
      }
    } finally {
      // ALWAYS abort lifecycle — even if save/send fails.
      // Prevents orphaned CLI processes and stuck streaming locks.
      // A3-FIX: cancelCurrentQuery() moved to stop() caller — called once
      // after all per-conversation stops instead of per-iteration.
      if (conversationId) {
        completeStreamMetrics(conversationId, 'stopped')
        lifecycleRegistry.abort(conversationId, 'userStop')
      }
    }
  }

  // ── Compact ──

  async compact(extractNuance = false): Promise<void> {
    log.info(`Compact requested (nuance=${extractNuance})`)
    await chatAgentService.compact(extractNuance)
  }

  /**
   * Force-reset streaming state if switching away from a workspace with a stuck stream.
   * Called by the workspace switch IPC handler to prevent cross-workspace lock contamination.
   */
  forceResetIfStuck(): void {
    const activeStreams = lifecycleRegistry.active()
    const smStuck = !conversationStateMachine.isIdle()
    if (activeStreams.length > 0 || this.streamingLocks.size > 0 || smStuck) {
      log.warn(
        `[STREAM:force-reset] activeStreams=${activeStreams.length} locks=${this.streamingLocks.size} ` +
        `smStuck=${smStuck} — aborting all (fixes P12)`
      )
      // CHAT-METRICS-ABORT-ORPHAN-01: Clean up metrics before abort to prevent leak.
      for (const stream of activeStreams) {
        completeStreamMetrics(stream.conversationId, 'aborted')
      }
      lifecycleRegistry.abortAll('workspace-switch')
      // F2-FIX (replaces A9-FIX): After abortAll, re-check whether the SM
      // is still stuck. The old condition (smStuck && activeStreams.length === 0)
      // missed the mixed state: SM stuck for conv-B while the registry only
      // held conv-A. abortAll clears conv-A's SM entry via forceReset(convId),
      // but conv-B stays stuck. Unconditional re-check catches both cases.
      if (!conversationStateMachine.isIdle()) {
        log.warn('[STREAM:force-reset] SM still not idle after abortAll — forcing SM global reset')
        conversationStateMachine.forceReset()
      }
      // Belt-and-suspenders: clear any orphaned locks
      this.streamingLocks.clear()
      this.activeRequestIds.clear()
    }
  }

  /**
   * N1-FIX: Clear injected-fact dedupe state for a conversation.
   * Called from conversation-delete IPC paths so facts can be re-injected
   * if the user starts a new conversation about the same topics.
   */
  clearConversationMemoryState(conversationId: string): void {
    this.injectedFactIds.delete(conversationId)
    // A10-FIX: Clear stoppedConversations entry for this conversation.
    // Without this, entries from conversations that are never re-streamed
    // accumulate in the Set forever.
    this.stoppedConversations.delete(conversationId)
  }

  // N14: Clean up all persistent listeners when the service is replaced
  dispose(): void {
    this.isDisposed = true

    // Dispose the warm prompt-optimizer CLI session
    backgroundCliSession.dispose()

    // Abort all active streams before disposal
    lifecycleRegistry.abortAll('service-disposed')
    this.streamingLocks.clear()
    this.activeRequestIds.clear()
    this.stoppedConversations.clear()
    this.safetyTimerResets.clear()

    // Clear all keepalive timers
    for (const timer of this.keepaliveTimers.values()) {
      clearInterval(timer)
    }
    this.keepaliveTimers.clear()

    // N1-FIX: Clear all per-conversation memory dedupe state on service replacement
    this.injectedFactIds.clear()

    // Clean up all persistent event forwarders registered in registerEventForwarders()
    for (const cleanup of this.eventCleanups) {
      cleanup()
    }
    this.eventCleanups = []

    // hookLifecycle cleanup (stored separately as named handler)
    if (this.hookLifecycleHandler) {
      hookEngine.off('hookLifecycle', this.hookLifecycleHandler)
      this.hookLifecycleHandler = undefined
    }
  }
}

// ── Singleton with lazy initialization ──

let _instance: ChatStreamService | null = null

export function initChatStream(
  mainWindow: BrowserWindow,
  callbacks: PipelineCallbacks
): ChatStreamService {
  // N14: Dispose previous instance to remove stale listeners
  _instance?.dispose()
  _instance = new ChatStreamService(mainWindow, callbacks)
  return _instance
}

export const chatStreamService = new Proxy({} as ChatStreamService, {
  get(_target, prop) {
    if (!_instance)
      throw new Error(
        'ChatStreamService not initialized — call initChatStream(mainWindow, callbacks) first'
      )
    return (_instance as unknown as Record<string, unknown>)[prop as string]
  }
})

import type { BrowserWindow } from 'electron'
import type { StreamChunk } from '../services'
import type { ConversationMode, ConversationPhase } from '../../shared/types'
import { routeChunk } from './chunk-router'

// ── Chunk Tap Registry (E2E testing) ──
// Allows the E2E runner to capture transcript chunks without
// altering renderer behavior. Listeners are called synchronously
// before the chunk is routed to handlers.

type ChunkTapCallback = (requestId: string | undefined, chunk: StreamChunk) => void
const chunkTapListeners = new Map<string, ChunkTapCallback>()

export function registerChunkTap(key: string, cb: ChunkTapCallback): void {
  chunkTapListeners.set(key, cb)
}

export function unregisterChunkTap(key: string): void {
  chunkTapListeners.delete(key)
}

/**
 * R6-B2: Notify chunk-tap listeners directly (bypasses renderer routing).
 * Used by prompt optimizer to make optimization visible in E2E transcripts.
 * No-op when no taps are registered (normal app operation).
 */
export function notifyChunkTaps(requestId: string | undefined, chunk: StreamChunk): void {
  if (chunkTapListeners.size === 0) return
  for (const cb of chunkTapListeners.values()) {
    try {
      cb(requestId, chunk)
    } catch { /* tap errors must not break streaming */ }
  }
}

/**
 * Shared helper to forward a StreamChunk to the renderer.
 * Delegates to the ChunkRouter dispatch table (see chunk-router.ts).
 */
export function forwardChunkToRenderer(
  mainWindow: BrowserWindow,
  conversationId: string,
  role: 'specialist',
  chunk: StreamChunk,
  contentAccumulator: { value: string },
  workspacePath?: string,
  specialistMeta?: { specialist: string; taskId?: string },
  phase?: ConversationPhase,
  requestId?: string,
  mode?: ConversationMode
): void {
  // Notify chunk-tap listeners (E2E testing) before routing
  if (chunkTapListeners.size > 0) {
    for (const cb of chunkTapListeners.values()) {
      try {
        cb(requestId, chunk)
      } catch { /* tap errors must not break streaming */ }
    }
  }

  routeChunk(
    {
      mainWindow,
      conversationId,
      role,
      contentAccumulator,
      workspacePath,
      specialistMeta,
      phase,
      requestId,
      mode
    },
    chunk
  )
}

/**
 * ChunkRouter — dispatches StreamChunk types to focused handler functions.
 * Replaces the 264-line if/else chain in forwardChunkToRenderer.
 */

import { ipcMain, type BrowserWindow } from 'electron'
import type { StreamChunk } from '../services'
import { IPC_CHANNELS } from '../../shared/constants'
import type { ConversationMode, ConversationPhase, ToolActivity, PlanRecord } from '../../shared/types'
import { createTextChunk, createToolActivityChunk, createTurnBoundary } from './chat-protocol'
import { processToolChunk } from './tool-chunk-processor'
import { TextDeltaBatcher } from './text-delta-batcher'
import { chatIpcLogger } from '../logger'
import { chunkAckTracker } from './chunk-ack-tracker'
import { todoRepository } from '../db/repositories/todo.repository'
import { planRepository } from '../db/repositories/plan.repository'
import { matchPlanTaskForFile, isPhaseTaskSetComplete } from '../../shared/plan-tasks'

// ── Tool Activity Persistence Accumulator ──────────────────────────────
// Collects completed ToolActivity objects during streaming, keyed by
// conversationId → toolId. Merges tool_use (running) and tool_result
// (completed) by ID so the persisted entry has both startedAt and result.
// Retrieved and cleared by getAndClearToolActivities() during finalize.

const toolActivityStore = new Map<string, Map<string, ToolActivity>>()

// TOOLACTIVITY-STORE-RECREATED-01: Track recently cleared conversations so
// late-arriving chunks don't re-create orphaned Map entries after clear.
const clearedConversations = new Set<string>()

function accumulateToolActivity(
  conversationId: string,
  partial: Partial<ToolActivity> & { id: string; toolName: string }
): void {
  // TOOLACTIVITY-STORE-RECREATED-01: Don't re-create after clear
  if (clearedConversations.has(conversationId)) return

  let convMap = toolActivityStore.get(conversationId)
  if (!convMap) {
    convMap = new Map<string, ToolActivity>()
    toolActivityStore.set(conversationId, convMap)
  }
  const existing = convMap.get(partial.id)
  if (existing) {
    // Merge: preserve earlier startedAt, overlay new fields
    convMap.set(partial.id, {
      ...existing,
      ...partial,
      startedAt: existing.startedAt || partial.startedAt || 0
    })
  } else {
    convMap.set(partial.id, {
      status: 'running',
      startedAt: Date.now(),
      ...partial
    } as ToolActivity)
  }
}

/**
 * Record an externally-created tool activity (e.g. Prompt Optimizer) into the
 * accumulator so it persists with the assistant message via the existing
 * getAndClearToolActivities → DB finalize path.
 *
 * Clears the conversation from `clearedConversations` first so the synthetic
 * activity is not silently dropped by the 10s tombstone guard.
 */
export function recordExternalToolActivity(
  conversationId: string,
  activity: Partial<ToolActivity> & { id: string; toolName: string }
): void {
  clearedConversations.delete(conversationId)
  accumulateToolActivity(conversationId, activity)
}

/**
 * Retrieve and clear accumulated tool activities for a conversation.
 * Called during finalize to persist tool activities to the DB.
 * Returns all activities including 'running' ones (e.g. subagents interrupted mid-execution).
 */
export function getAndClearToolActivities(conversationId: string): ToolActivity[] {
  // TOOLACTIVITY-STORE-RECREATED-01: Block re-creation for 10s after clear
  clearedConversations.add(conversationId)
  setTimeout(() => clearedConversations.delete(conversationId), 10_000)

  const convMap = toolActivityStore.get(conversationId)
  toolActivityStore.delete(conversationId)
  if (!convMap) return []
  return [...convMap.values()]
}

// ── Shared context passed to all handlers ──

export interface ChunkRouterContext {
  mainWindow: BrowserWindow
  conversationId: string
  role: 'specialist'
  contentAccumulator: { value: string }
  workspacePath?: string
  specialistMeta?: { specialist: string; taskId?: string }
  phase?: ConversationPhase
  requestId?: string
  /** Active conversation mode — forwarded to processToolChunk to suppress expected plan-mode blocks. */
  mode?: ConversationMode
}

// ── Per-stream metrics ──────────────────────────────────────────────
// Tracks TTFT, chunk count, total chars, and duration per stream.
// Logged as [METRIC:STREAM_COMPLETE] on finalization for observability.
// The StreamMetricsAggregator keeps a sliding window of recent streams
// for completion-rate and TTFT p95 aggregation.

/**
 * How a stream ended. Used for metrics aggregation.
 *
 *   complete   — LLM finished naturally (message_stop received)
 *   completed  — User/system marked the conversation as done
 *   stopped    — User manually stopped the response mid-stream
 *   swapped    — Specialist swap interrupted the stream
 *   aborted    — System abort (workspace switch, conversation deleted, safety timeout cleanup)
 *   error      — Unrecoverable stream error
 *   timeout       — Safety timeout fired before LLM responded
 *   max-lifetime  — Stream exceeded absolute hard cap (MAX_STREAM_LIFETIME_MS)
 */
type StreamOutcome = 'complete' | 'stopped' | 'error' | 'timeout' | 'aborted' | 'completed' | 'swapped' | 'max-lifetime'

interface StreamMetrics {
  startedAt: number
  firstTokenAt: number | null
  lastChunkAt: number | null
  chunkCount: number
  totalChars: number
  maxITL: number // max inter-token latency (ms)
}

interface AggregatedStreamRecord {
  outcome: StreamOutcome
  ttft: number | null
  duration: number
}

/**
 * Sliding-window aggregator for stream health metrics.
 * Keeps the last `windowSize` stream outcomes and computes
 * completion rate + TTFT percentiles on demand.
 */
export class StreamMetricsAggregator {
  private records: AggregatedStreamRecord[] = []
  private readonly windowSize: number

  constructor(windowSize: number = 100) {
    this.windowSize = windowSize
  }

  /** Record a completed stream's outcome and timing. */
  record(outcome: StreamOutcome, ttft: number | null, duration: number): void {
    this.records.push({ outcome, ttft, duration })
    if (this.records.length > this.windowSize) this.records.shift()
  }

  /**
   * Fraction of streams that ended successfully (0–1).
   * Counts 'complete' (natural finish) and 'completed' (user-finished) as success.
   * User-initiated interruptions (stopped, swapped, aborted) are neutral — not failures.
   */
  get completionRate(): number {
    if (this.records.length === 0) return 1
    return this.records.filter(
      (r) => r.outcome === 'complete' || r.outcome === 'completed'
    ).length / this.records.length
  }

  /** TTFT at the given percentile (0–1). Returns null when no TTFT data exists. */
  ttftPercentile(p: number): number | null {
    const ttfts = this.records
      .map((r) => r.ttft)
      .filter((t): t is number => t !== null)
      .sort((a, b) => a - b)
    if (ttfts.length === 0) return null
    return ttfts[Math.min(Math.floor(ttfts.length * p), ttfts.length - 1)]
  }

  /** Convenience: TTFT p95. */
  get ttftP95(): number | null {
    return this.ttftPercentile(0.95)
  }

  /** Number of streams in the current window. */
  get sampleSize(): number {
    return this.records.length
  }

  /** Distribution of outcomes in the current window. */
  get outcomeCounts(): Record<StreamOutcome, number> {
    const counts: Record<StreamOutcome, number> = { complete: 0, stopped: 0, error: 0, timeout: 0, completed: 0, aborted: 0, swapped: 0, 'max-lifetime': 0 }
    for (const r of this.records) counts[r.outcome]++
    return counts
  }

  /**
   * Fraction of streams that ended with 'error' or 'timeout' outcome (0–1).
   * Per Zylos Research recommendation: track connection reset rate with < 0.5% target.
   * Streams interrupted without a message_stop event are classified as resets.
   */
  get connectionResetRate(): number {
    if (this.records.length === 0) return 0
    const resets = this.records.filter(
      (r) => r.outcome === 'error' || r.outcome === 'timeout'
    ).length
    return resets / this.records.length
  }
}

const streamMetricsStore = new Map<string, StreamMetrics>()
const streamAggregator = new StreamMetricsAggregator()

/** Begin tracking metrics for a new stream. */
export function startStreamMetrics(conversationId: string): void {
  streamMetricsStore.set(conversationId, {
    startedAt: Date.now(),
    firstTokenAt: null,
    lastChunkAt: null,
    chunkCount: 0,
    totalChars: 0,
    maxITL: 0
  })
}

/**
 * Log final stream metrics, record into the sliding-window aggregator, and clean up.
 * @param outcome - How the stream ended: 'complete' | 'stopped' | 'error' | 'timeout'
 */
export function completeStreamMetrics(
  conversationId: string,
  outcome: StreamOutcome
): void {
  const metrics = streamMetricsStore.get(conversationId)
  streamMetricsStore.delete(conversationId)
  if (!metrics) return

  const duration = Date.now() - metrics.startedAt
  const ttft = metrics.firstTokenAt ? metrics.firstTokenAt - metrics.startedAt : null

  // Record into sliding-window aggregator
  streamAggregator.record(outcome, ttft, duration)

  // IPC-BACKPRESSURE: Collect backpressure metrics for this stream
  const bp = chunkAckTracker.getMetrics(conversationId)

  chatIpcLogger.info(
    `[METRIC:STREAM_COMPLETE] ` +
      `outcome=${outcome} duration=${duration}ms ttft=${ttft}ms ` +
      `maxITL=${metrics.maxITL}ms chunks=${metrics.chunkCount} chars=${metrics.totalChars} ` +
      `conversationId=${conversationId.slice(0, 8)} ` +
      `completionRate=${(streamAggregator.completionRate * 100).toFixed(1)}% ` +
      `ttftP95=${streamAggregator.ttftP95}ms ` +
      `sampleSize=${streamAggregator.sampleSize} ` +
      `backpressureActivations=${bp.backpressureActivations} ` +
      `avgAckLatency=${bp.avgAckLatency}ms ` +
      `maxPending=${bp.maxPendingChunks}`
  )

  // Clean up backpressure tracking for this stream
  chunkAckTracker.cleanup(conversationId)
  chunkAckTracker.clearMetrics(conversationId)
}

/** Expose the aggregator for diagnostic IPC or health checks. */
export function getStreamMetricsAggregator(): StreamMetricsAggregator {
  return streamAggregator
}

// ── Text delta batching (~30fps) ────────────────────────────────────
// Reduces IPC calls from ~15/sec to ~3-5/sec during fast streaming.
// Text deltas are buffered and flushed every 33ms (1 frame at 30fps).
// Keyed by conversationId to prevent cross-conversation text mixing when
// concurrent streams are active (e.g. multi-session or parallel agents).
// The shared TextDeltaBatcher owns timing; the flush closure does the IPC send.

const textBatcher = new TextDeltaBatcher()

/** Queue text for batched delivery to the renderer for this conversation. */
function pushText(ctx: ChunkRouterContext, text: string): void {
  // IPC-BACKPRESSURE: Pass the adaptive interval to the batcher. When the
  // renderer is under pressure (pending > HWM), the interval widens from
  // 33ms (~30fps) to 100ms (~10fps), giving React more breathing room.
  const interval = chunkAckTracker.getRecommendedInterval(ctx.conversationId)
  textBatcher.push(ctx.conversationId, text, (buffer) => {
    safeSend(
      ctx,
      IPC_CHANNELS.CHAT_MESSAGE_CHUNK,
      createTextChunk({ ...basePayload(ctx), text: buffer, phase: ctx.phase })
    )
    // Record send for backpressure tracking
    chunkAckTracker.recordSend(ctx.conversationId)
  }, interval)
}

/**
 * Send an IPC message to the renderer, guarding against destroyed windows.
 * During streaming the user may close the window — without this guard every
 * webContents.send() would throw an unhandled exception.
 */
function safeSend(ctx: ChunkRouterContext, channel: string, ...args: unknown[]): void {
  try {
    if (!ctx.mainWindow.isDestroyed()) {
      ctx.mainWindow.webContents.send(channel, ...args)
    }
  } catch (err) {
    chatIpcLogger.warn('Failed to send IPC chunk:', err)
  }
}

/** Base payload fields shared by all IPC messages */
interface BasePayload {
  conversationId: string
  role: 'specialist'
  requestId?: string
  specialist?: string
  taskId?: string
}

function basePayload(ctx: ChunkRouterContext): BasePayload {
  return {
    conversationId: ctx.conversationId,
    ...(ctx.requestId ? { requestId: ctx.requestId } : {}),
    role: ctx.role,
    ...(ctx.specialistMeta?.specialist ? { specialist: ctx.specialistMeta.specialist } : {}),
    ...(ctx.specialistMeta?.taskId ? { taskId: ctx.specialistMeta.taskId } : {})
  }
}

// ── Per-type handler functions ──

/**
 * Regex matching raw JSON control signals that local LLM backends
 * (Ollama/oMLX) emit as text deltas instead of structured events.
 * Only matches when the ENTIRE chunk content is the JSON object.
 */
const LOCAL_CONTROL_SIGNAL_RE = /^\s*\{\s*"type"\s*:\s*"(?:busy|idle|ready|processing)"\s*\}\s*$/

function handleText(ctx: ChunkRouterContext, chunk: StreamChunk): void {
  if (!chunk.content) return

  // CONTROL-SIGNAL-FILTER-01: Local LLM backends may leak raw JSON control
  // signals (e.g. {"type":"busy"}) as text deltas. Drop them silently.
  if (LOCAL_CONTROL_SIGNAL_RE.test(chunk.content)) {
    chatIpcLogger.debug('[chunk-router] Filtered control signal in text: %s', chunk.content)
    return
  }
  chatIpcLogger.debug(
    `[chunk-router:text] ${chunk.content.length} chars → ${ctx.conversationId.slice(0, 8)}`
  )

  // Track stream metrics (TTFT, chunk count, total chars)
  const metrics = streamMetricsStore.get(ctx.conversationId)
  if (metrics) {
    if (metrics.firstTokenAt === null) {
      metrics.firstTokenAt = Date.now()
      const ttft = metrics.firstTokenAt - metrics.startedAt
      chatIpcLogger.info(`[METRIC:TTFT] ${ttft}ms conversationId=${ctx.conversationId.slice(0, 8)}`)
    }
    if (metrics.lastChunkAt !== null) {
      const itl = Date.now() - metrics.lastChunkAt
      metrics.maxITL = Math.max(metrics.maxITL, itl)
    }
    metrics.lastChunkAt = Date.now()
    metrics.chunkCount++
    metrics.totalChars += chunk.content.length
  }

  // Accumulate immediately for backend consumers (prompt caching, etc.)
  ctx.contentAccumulator.value += chunk.content
  // Batch IPC sends at ~30fps to reduce renderer pressure during fast streaming
  pushText(ctx, chunk.content)
}

function handleThinking(ctx: ChunkRouterContext, chunk: StreamChunk): void {
  if (!chunk.content) return
  // F-20: Flush pending batched text before thinking IPC send.
  // Prevents minor reorder if thinking and text chunks interleave.
  // Consistent with handleToolChunk, handleError, and handleStatus.
  textBatcher.flush(ctx.conversationId)
  const thinkingText = `\n\n<details>\n<summary>💭 Reasoning</summary>\n\n${chunk.content}\n\n</details>\n\n`
  ctx.contentAccumulator.value += thinkingText
  safeSend(
    ctx,
    IPC_CHANNELS.CHAT_MESSAGE_CHUNK,
    createTextChunk({ ...basePayload(ctx), text: thinkingText, phase: ctx.phase })
  )
}

function handleToolChunk(ctx: ChunkRouterContext, chunk: StreamChunk): void {
  // Flush pending text before tool activity (tool_use and tool_result start/end a visual block)
  if (chunk.type === 'tool_use' || chunk.type === 'tool_result') textBatcher.flush(ctx.conversationId)

  const result = processToolChunk(chunk, {
    workspacePath: ctx.workspacePath,
    agentType: ctx.specialistMeta?.specialist ?? ctx.role,
    workspaceId: ctx.conversationId,
    agentId: ctx.specialistMeta?.taskId,
    mode: ctx.mode
  })
  if (!result) return

  // Accumulate for DB persistence (merge tool_use → tool_result by id)
  accumulateToolActivity(ctx.conversationId, result.toolActivity)

  safeSend(
    ctx,
    IPC_CHANNELS.CHAT_MESSAGE_CHUNK,
    createToolActivityChunk({ ...basePayload(ctx), toolActivity: result.toolActivity })
  )

  // TASK-DERIVE-01: Derive task completion from OBSERVED write/edit activity
  // (main-owned, DB-backed) instead of relying solely on the model
  // self-reporting via emit_phase_progress. Fires only on tool_result (the
  // operation actually completed, not just started) for successful write/edit
  // ops — this is what lets a phase the model never reported on still show
  // accurate progress, mirroring how BlueprintBuildService derives task
  // status from its own wave loop rather than trusting the model.
  if (
    chunk.type === 'tool_result' &&
    result.toolActivity.status !== 'error' &&
    result.toolActivity.filePath &&
    (result.toolActivity.operationType === 'write' || result.toolActivity.operationType === 'edit')
  ) {
    try {
      derivePlanTaskFromFileActivity(ctx, result.toolActivity.filePath)
    } catch (err) {
      chatIpcLogger.warn(`[chunk-router] Task derivation failed: ${(err as Error).message}`)
    }
  }
}

// ── Active-plan lookup cache (per conversation) ──────────────────────
// A file-heavy build fires derivePlanTaskFromFileActivity once per
// write/edit tool_result — findActiveByConversationId on every single one
// is wasted work, since the plan's structuredPlan (title/phases/files) is
// immutable for the life of a build; only its phase_progress_json changes,
// which is still always read fresh (never cached) for correctness. Short
// TTL bounds staleness if the user starts a brand-new plan mid-conversation
// without needing cross-module cache invalidation wiring.
const ACTIVE_PLAN_CACHE_TTL_MS = 5000
const activePlanCache = new Map<string, { plan: PlanRecord; cachedAt: number }>()

function getCachedActivePlan(conversationId: string): PlanRecord | null {
  const cached = activePlanCache.get(conversationId)
  if (cached && Date.now() - cached.cachedAt < ACTIVE_PLAN_CACHE_TTL_MS) {
    return cached.plan
  }
  const plan = planRepository.findActiveByConversationId(conversationId)
  if (plan) {
    activePlanCache.set(conversationId, { plan, cachedAt: Date.now() })
  } else {
    activePlanCache.delete(conversationId)
  }
  return plan
}

/**
 * Match a touched file against the conversation's persisted plan and, on a
 * unique match, promote that task to 'complete' and its phase to
 * 'in_progress' (never regressing a phase past 'pending'). Emits a synthetic
 * phaseProgress chunk so the renderer converges on the same state the DB now
 * holds, whether or not the model itself called emit_phase_progress.
 */
function derivePlanTaskFromFileActivity(ctx: ChunkRouterContext, filePath: string): void {
  const plan = getCachedActivePlan(ctx.conversationId)
  if (!plan) return

  const match = matchPlanTaskForFile(plan.structuredPlan, filePath)
  if (!match) return

  const existingProgress = planRepository.getPhaseProgress(plan.id)
  const currentPhase = existingProgress.find((p) => p.phaseId === match.phaseId)
  let nextPhaseStatus: 'started' | 'in_progress' | 'completed' | 'failed' | 'skipped' =
    !currentPhase || currentPhase.status === 'pending'
      ? 'in_progress'
      : (currentPhase.status as 'started' | 'in_progress' | 'completed' | 'failed' | 'skipped')

  planRepository.updatePhaseProgress(
    plan.id,
    match.phaseId,
    nextPhaseStatus,
    undefined,
    [match.touchedFile],
    { taskId: match.taskId, title: match.taskTitle, status: 'complete' }
  )

  // Auto-finalize the phase once every DECLARED task in it (the full
  // manifest, not just whatever's been recorded so far) has reached a
  // terminal status. Without this, an execution the model never explicitly
  // completed stays "in progress" forever — handleMessageComplete's allDone
  // check requires every phase to reach completed/skipped/failed before the
  // panel goes read-only and memory extraction fires. 'failed' phases are
  // never auto-promoted — a task landing after a failure doesn't undo it.
  if (nextPhaseStatus !== 'completed' && nextPhaseStatus !== 'failed') {
    const refreshedPhase = planRepository
      .getPhaseProgress(plan.id)
      .find((p) => p.phaseId === match.phaseId)
    if (isPhaseTaskSetComplete(plan.structuredPlan, match.phaseId, refreshedPhase?.tasks ?? [])) {
      nextPhaseStatus = 'completed'
      planRepository.updatePhaseProgress(plan.id, match.phaseId, 'completed')
    }
  }

  safeSend(ctx, IPC_CHANNELS.CHAT_MESSAGE_CHUNK, {
    ...basePayload(ctx),
    chunk: '',
    phaseProgress: {
      planId: plan.id,
      phaseId: match.phaseId,
      phaseTitle: match.phaseTitle,
      status: nextPhaseStatus,
      totalPhases: plan.structuredPlan.phases?.length ?? 0,
      taskId: match.taskId,
      taskTitle: match.taskTitle,
      taskStatus: 'complete',
      totalTasks: match.totalTasksInPhase
    }
  })
}

function handleTurnBoundary(ctx: ChunkRouterContext, chunk: StreamChunk): void {
  // Flush any pending text before emitting boundary
  textBatcher.flush(ctx.conversationId)
  safeSend(
    ctx,
    IPC_CHANNELS.CHAT_MESSAGE_CHUNK,
    createTurnBoundary({
      ...basePayload(ctx),
      turnId: chunk.content ?? `turn-${Date.now()}`
    })
  )
}

/** Patterns indicating server-side overload/outage */
const OVERLOAD_PATTERNS = [/529/i, /overloaded/i, /server_is_overloaded/i, /503 Service/i]

function handleError(ctx: ChunkRouterContext, chunk: StreamChunk): void {
  // Flush pending text before error
  textBatcher.flush(ctx.conversationId)

  // Detect server overload errors and format with friendly message
  const isOverload = chunk.error && OVERLOAD_PATTERNS.some((p) => p.test(chunk.error!))
  const errorText = isOverload
    ? '\n\n**API Error: 529 Overloaded.** This is a server-side issue, usually temporary — try again in a moment. If it persists, check [status.claude.com](https://status.claude.com).'
    : `\n\n**Error:** ${chunk.error}`

  ctx.contentAccumulator.value += errorText
  safeSend(
    ctx,
    IPC_CHANNELS.CHAT_MESSAGE_CHUNK,
    createTextChunk({ ...basePayload(ctx), text: errorText })
  )
}

/**
 * Status content patterns that are internal metadata — never rendered in chat.
 * These are operational lifecycle events emitted by the OpenCode event normalizer.
 *
 * MAINTENANCE: Keep in sync with status-emitting handlers in
 * src/main/services/opencode-event-normalizer.ts:
 *
 *   Prefix               Emitter
 *   ───────────────────   ──────────────────────────────
 *   agent_switched:       handleAgentSwitched()
 *   model_switched:       handleModelSwitched()
 *   finishReason:         handleSessionIdle()
 *
 *   Value                 Emitter
 *   ───────────────────   ──────────────────────────────
 *   idle                  handleSessionStatus() → statusMap
 *   thinking              handleSessionStatus() → statusMap
 *   reviewing             handleSessionStatus() → statusMap
 *   writing               handleSessionStatus() → statusMap
 *   failed                handleSessionStatus() → statusMap
 */
const SUPPRESSED_STATUS_PREFIXES = [
  'agent_switched:',
  'model_switched:',
  'finishReason:',
] as const

const SUPPRESSED_STATUS_VALUES: ReadonlySet<string> = new Set([
  'idle',
  'busy',     // local LLM backend status signal
  'thinking',
  'reviewing',
  'writing',
  'failed',
])

function handleStatus(ctx: ChunkRouterContext, chunk: StreamChunk): void {
  // Flush pending text before status messages
  textBatcher.flush(ctx.conversationId)
  if (!chunk.content || chunk.content === 'heartbeat') return

  // Guard: non-string content (e.g., object coerced via template literal)
  if (typeof chunk.content !== 'string') return

  // Suppress internal metadata status — these are operational signals,
  // not conversational content. They come from the OpenCode event normalizer.
  if (
    SUPPRESSED_STATUS_VALUES.has(chunk.content) ||
    SUPPRESSED_STATUS_PREFIXES.some((p) => chunk.content!.startsWith(p)) ||
    LOCAL_CONTROL_SIGNAL_RE.test(chunk.content)
  ) {
    chatIpcLogger.debug('[chunk-router] Suppressed metadata status: %s', chunk.content)
    return
  }

  const statusText = `\n\n_${chunk.content}_\n\n`
  ctx.contentAccumulator.value += statusText
  safeSend(
    ctx,
    IPC_CHANNELS.CHAT_MESSAGE_CHUNK,
    createTextChunk({ ...basePayload(ctx), text: statusText })
  )
}

