function handleLspDiagnostics(ctx: ChunkRouterContext, chunk: StreamChunk): void {
  if (!chunk.lspDiagnostics) return
  safeSend(ctx, IPC_CHANNELS.SDK_LSP_DIAGNOSTICS, {
    ...basePayload(ctx),
    diagnostics: chunk.lspDiagnostics
  })
}

// ── SubAgent helpers ──

/** Truncate a string to `maxLen` with an ellipsis */
function truncate(str: string, maxLen: number): string {
  return str.length > maxLen ? str.slice(0, maxLen - 1) + '…' : str
}

/** Returns true if the content is a short status label, not prose text */
function isStatusLabel(content: string): boolean {
  const lower = content.trim().toLowerCase()
  return (
    lower.length < 30 &&
    (lower.startsWith('running') ||
      lower.startsWith('starting') ||
      lower.startsWith('completed') ||
      lower.startsWith('failed') ||
      lower.startsWith('waiting'))
  )
}

/** Generate a unique ID for sub-agent tool activities (not part of processToolChunk pipeline) */
function generateSubagentId(prefix: string, existingId?: string | null): string {
  if (existingId) return existingId
  return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`
}

// ── SubAgent lifecycle handlers ──
// These map the subagent_* chunks from stream-normalizer into tool activity
// events so sub-agent work appears in the tool activity panel.
// Text content is dual-emitted: as a chat bubble text chunk AND a truncated
// tool activity entry, so prose is readable while the accordion shows a summary.

function handleSubagentStart(ctx: ChunkRouterContext, chunk: StreamChunk): void {
  const activity = {
    id: generateSubagentId('subagent', chunk.toolId),
    toolName: chunk.toolName ?? 'Agent',
    status: 'running' as const,
    input: chunk.content ? truncate(chunk.content, 80) : undefined,
    startedAt: Date.now()
  }
  accumulateToolActivity(ctx.conversationId, activity)

  // Emit tool activity for the accordion (short summary only)
  safeSend(
    ctx,
    IPC_CHANNELS.CHAT_MESSAGE_CHUNK,
    createToolActivityChunk({ ...basePayload(ctx), toolActivity: activity })
  )
}

function handleSubagentProgress(ctx: ChunkRouterContext, chunk: StreamChunk): void {
  const content = chunk.content ?? ''

  // If the progress content looks like actual text output (not just a status label),
  // emit it as chat text so it renders in the message bubble, not just the tool accordion.
  if (content.length > 20 && !isStatusLabel(content)) {
    ctx.contentAccumulator.value += content
    safeSend(
      ctx,
      IPC_CHANNELS.CHAT_MESSAGE_CHUNK,
      createTextChunk({
        ...basePayload(ctx),
        text: content,
        phase: ctx.phase
      })
    )
  }

  // Accumulate for DB persistence (captures intermediate result text)
  const activity = {
    id: generateSubagentId('subagent', chunk.toolId),
    toolName: chunk.toolName ?? 'Agent',
    status: 'running' as const,
    result: truncate(content, 80)
  }
  accumulateToolActivity(ctx.conversationId, activity)

  safeSend(
    ctx,
    IPC_CHANNELS.CHAT_MESSAGE_CHUNK,
    createToolActivityChunk({ ...basePayload(ctx), toolActivity: activity })
  )
}

function handleSubagentComplete(ctx: ChunkRouterContext, chunk: StreamChunk): void {
  const content = chunk.content ?? ''

  // Emit long completion text as bubble content
  if (content.length > 20 && !isStatusLabel(content)) {
    ctx.contentAccumulator.value += content
    safeSend(
      ctx,
      IPC_CHANNELS.CHAT_MESSAGE_CHUNK,
      createTextChunk({
        ...basePayload(ctx),
        text: content,
        phase: ctx.phase
      })
    )
  }

  // Tool activity: mark as complete with short summary
  const activity = {
    id: generateSubagentId('subagent', chunk.toolId),
    toolName: 'Agent',
    status: (chunk.toolInput === 'completed' ? 'completed' : 'error') as 'completed' | 'error',
    result: truncate(content, 80),
    completedAt: Date.now()
  }
  accumulateToolActivity(ctx.conversationId, activity)

  safeSend(
    ctx,
    IPC_CHANNELS.CHAT_MESSAGE_CHUNK,
    createToolActivityChunk({ ...basePayload(ctx), toolActivity: activity })
  )
}

// ── Permission request handler ──

// N4: handleToolUseSummary removed — tool summaries already flow through tool_result
// in the tool activity accordion. The dedicated SDK_TOOL_USE_SUMMARY IPC channel was vestigial.

function handlePermissionRequest(ctx: ChunkRouterContext, chunk: StreamChunk): void {
  if (!chunk.permissionRequest) return
  safeSend(ctx, IPC_CHANNELS.PERMISSION_REQUEST, {
    ...basePayload(ctx),
    ...chunk.permissionRequest
  })
}

function handleTurnLimit(ctx: ChunkRouterContext, chunk: StreamChunk): void {
  // Flush pending text before the turn-limit card
  textBatcher.flush(ctx.conversationId)

  // Emit text fallback (the markdown message) for content accumulation
  const text = chunk.content ?? ''
  if (text) {
    ctx.contentAccumulator.value += text
    safeSend(
      ctx,
      IPC_CHANNELS.CHAT_MESSAGE_CHUNK,
      createTextChunk({ ...basePayload(ctx), text, phase: ctx.phase })
    )
  }

  // Emit the structured turnLimit payload so the renderer can show a Continue button
  if (chunk.turnLimit) {
    safeSend(ctx, IPC_CHANNELS.CHAT_MESSAGE_CHUNK, {
      ...basePayload(ctx),
      chunk: '',
      turnLimit: chunk.turnLimit
    })
  }
}

// ── Dispatch table ──

function handleStructuredOutput(ctx: ChunkRouterContext, chunk: StreamChunk): void {
  if (!chunk.content) return
  // Accumulate as text for backend consumers
  ctx.contentAccumulator.value += chunk.content
  // Forward as text (batched) — the structured_output data rides along
  // in the chunk for renderers that support progressive schema rendering.
  pushText(ctx, chunk.content)
}

type ChunkHandler = (ctx: ChunkRouterContext, chunk: StreamChunk) => void

const CHUNK_HANDLERS: Record<string, ChunkHandler> = {
  text: handleText,
  thinking: handleThinking,
  tool_use: handleToolChunk,
  tool_result: handleToolChunk,
  turn_boundary: handleTurnBoundary,
  error: handleError,
  status: handleStatus,
  tool_progress: handleToolChunk,
  rate_limit: handleRateLimit,
  api_retry: handleApiRetry,
  compact_boundary: handleCompactBoundary,
  prompt_suggestion: handlePromptSuggestion,
  files_persisted: handleFilesPersisted,
  hook_lifecycle: handleHookLifecycle,
  session_state: handleSessionState,
  auth_status: handleAuthStatus,
  session_recovery: handleSessionRecovery,
  context_usage_update: handleContextUsageUpdate,
  todo_update: handleTodoUpdate,
  phase_progress: handlePhaseProgress,
  subagent_start: handleSubagentStart,
  subagent_progress: handleSubagentProgress,
  subagent_complete: handleSubagentComplete,
  structured_output: handleStructuredOutput,
  // N4: tool_use_summary handler removed — summaries flow via tool_result
  permission_request: handlePermissionRequest,
  lsp_diagnostics: handleLspDiagnostics,
  turn_limit: handleTurnLimit
}

/**
 * Route a StreamChunk to the appropriate handler.
 * Drop-in replacement for forwardChunkToRenderer.
 */
export function routeChunk(ctx: ChunkRouterContext, chunk: StreamChunk): void {
  const handler = CHUNK_HANDLERS[chunk.type]
  if (handler) {
    handler(ctx, chunk)
  } else {
    chatIpcLogger.warn(
      `[chunk-router] Unhandled chunk type: ${chunk.type} ` +
        `(contentLen=${chunk.content?.length ?? 0})`
    )
  }
}

/**
 * Flush any pending batched text deltas immediately.
 * When `conversationId` is provided, only that conversation's buffer is flushed
 * and its flusher callback is cleared. Without it, ALL keys are flushed — which
 * is safe today (single-stream lock) but would leak across conversations if
 * concurrent streams were ever allowed.
 */
export function flushTextBatcher(conversationId?: string): void {
  textBatcher.reset(conversationId)
}

// ── Stream Diagnostics IPC ────────────────────────────────────────────
// Exposes the StreamMetricsAggregator data via IPC so the renderer
// (future Performance tab, dev tools) can read streaming SLO metrics.

import { validateSender } from './validate-sender'

export function registerStreamDiagnosticsIpc(): void {
  ipcMain.handle(IPC_CHANNELS.STREAM_METRICS_GET, (event) => {
    validateSender(event)
    return {
      completionRate: streamAggregator.completionRate,
      connectionResetRate: streamAggregator.connectionResetRate,
      ttftP50: streamAggregator.ttftPercentile(0.50),
      ttftP95: streamAggregator.ttftP95,
      ttftP99: streamAggregator.ttftPercentile(0.99),
      sampleSize: streamAggregator.sampleSize,
      outcomeCounts: streamAggregator.outcomeCounts
    }
  })

  // IPC-BACKPRESSURE: Renderer sends ACK after processing a batch of chunks.
  // This feeds the adaptive batcher interval adjustment.
  ipcMain.on(IPC_CHANNELS.CHAT_CHUNK_ACK, (_event, data: { processed: number; timestamp: number; perConversation?: Record<string, number> }) => {
    if (data.perConversation) {
      // Phase-2: Per-conversation ACK routing — backpressure tracked independently
      for (const [convId, count] of Object.entries(data.perConversation)) {
        chunkAckTracker.recordAck(convId, count)
      }
    } else {
      // Backward compat fallback for old renderers
      chunkAckTracker.recordAck('__global__', data.processed)
    }
  })
}

/**
 * Type-safe IPC protocol for chat messages.
 *
 * Replaces stringly-typed message objects with compile-time enforced builders.
 * All IPC sends for CHAT_MESSAGE_CHUNK, CHAT_MESSAGE_COMPLETE, and related
 * channels should use these builders instead of inline object literals.
 *
 * This ensures: requestId is never accidentally omitted, phase is always included,
 * and message shapes are consistent across all agent paths.
 */

import type { ConversationPhase, ContextUsageBreakdown, ToolActivity } from '../../shared/types'

// ── Message Interfaces ──

/** Base fields present on every chunk message */
export interface BaseChunkMessage {
  conversationId: string
  requestId?: string
  role: 'specialist'
  phase?: ConversationPhase
}

/** Text content chunk */
export interface TextChunkMessage extends BaseChunkMessage {
  chunk: string
  specialist?: string
  taskId?: string
}

/** Tool activity chunk (tool_use / tool_result / tool_progress) */
export interface ToolActivityChunkMessage extends BaseChunkMessage {
  chunk: ''
  toolActivity: Partial<ToolActivity> & { id: string; toolName: string }
  specialist?: string
  taskId?: string
}

/** Turn boundary signal */
export interface TurnBoundaryMessage extends BaseChunkMessage {
  chunk: ''
  turnBoundary: true
  turnId: string
}

/** Compact needed suggestion */
export interface CompactNeededMessage extends BaseChunkMessage {
  chunk: ''
  compactNeeded: {
    level: string
    inputTokens: number
    /** Optional Claude Code-style breakdown for the modal */
    breakdown?: ContextUsageBreakdown
    /** When true, SDK compaction is unavailable — UI should offer "new conversation" instead */
    isLocalProvider?: boolean
  }
}

/** Message complete signal */
export interface CompleteMessage {
  conversationId: string
  requestId?: string
  messageId: string
  taskId?: string
  phase?: ConversationPhase
}

// ── Builder Functions ──

/**
 * Create a text chunk message. Enforces required fields at compile time.
 */
export function createTextChunk(opts: {
  conversationId: string
  requestId?: string
  text: string
  role: 'specialist'
  phase?: ConversationPhase
  specialist?: string
  taskId?: string
}): TextChunkMessage {
  return {
    conversationId: opts.conversationId,
    chunk: opts.text,
    role: opts.role,
    ...(opts.requestId ? { requestId: opts.requestId } : {}),
    ...(opts.phase ? { phase: opts.phase } : {}),
    ...(opts.specialist ? { specialist: opts.specialist } : {}),
    ...(opts.taskId ? { taskId: opts.taskId } : {})
  }
}

/**
 * Create a tool activity chunk message.
 */
export function createToolActivityChunk(opts: {
  conversationId: string
  requestId?: string
  role: 'specialist'
  toolActivity: Partial<ToolActivity> & { id: string; toolName: string }
  specialist?: string
  taskId?: string
}): ToolActivityChunkMessage {
  return {
    conversationId: opts.conversationId,
    chunk: '' as const,
    role: opts.role,
    toolActivity: opts.toolActivity,
    ...(opts.requestId ? { requestId: opts.requestId } : {}),
    ...(opts.specialist ? { specialist: opts.specialist } : {}),
    ...(opts.taskId ? { taskId: opts.taskId } : {})
  }
}

/**
 * Create a turn boundary message.
 */
export function createTurnBoundary(opts: {
  conversationId: string
  requestId?: string
  role: 'specialist'
  turnId: string
  specialist?: string
  taskId?: string
}): TurnBoundaryMessage {
  return {
    conversationId: opts.conversationId,
    chunk: '' as const,
    role: opts.role,
    turnBoundary: true as const,
    turnId: opts.turnId,
    ...(opts.requestId ? { requestId: opts.requestId } : {}),
    ...(opts.specialist ? { specialist: opts.specialist } : {}),
    ...(opts.taskId ? { taskId: opts.taskId } : {})
  } as TurnBoundaryMessage
}

/**
 * Create a compact needed message.
 */
export function createCompactNeeded(opts: {
  conversationId: string
  requestId?: string
  role: 'specialist'
  compactNeeded: {
    level: string
    inputTokens: number
    breakdown?: ContextUsageBreakdown
    isLocalProvider?: boolean
  }
}): CompactNeededMessage {
  return {
    conversationId: opts.conversationId,
    chunk: '' as const,
    role: opts.role,
    compactNeeded: opts.compactNeeded,
    ...(opts.requestId ? { requestId: opts.requestId } : {})
  }
}

/**
 * Create a message complete signal. Enforces required fields.
 */
export function createCompleteMessage(opts: {
  conversationId: string
  requestId?: string
  messageId: string
  phase?: ConversationPhase
  taskId?: string
}): CompleteMessage {
  return {
    conversationId: opts.conversationId,
    messageId: opts.messageId,
    ...(opts.requestId ? { requestId: opts.requestId } : {}),
    ...(opts.phase ? { phase: opts.phase } : {}),
    ...(opts.taskId ? { taskId: opts.taskId } : {})
  }
}

/**
 * Tool Chunk Processor — single source of truth for tool_use / tool_result / tool_progress handling.
 *
 * All consumers (chunk-router, grill, audit, council) call processToolChunk() from here.
 * To add a new field to ToolActivity, change error detection, or handle a new composable tool,
 * edit this file only — no consumer changes needed.
 */

import type { StreamChunk } from '../services'
import { summarizeToolInput } from '../services'
import type { ConversationMode, ToolActivity, ToolOperationType } from '../../shared/types'
import { MCP_TOOLS } from '../../shared/constants'
import { extractResultSummary } from './tool-result-summarizer'
import { reportToolError } from './tool-error-reporter'

// ── Public types ──

export interface ProcessedToolChunk {
  type: 'tool_activity'
  toolActivity: ToolActivity
}

export interface ToolChunkOptions {
  workspacePath?: string
  agentType: string
  workspaceId?: string
  agentId?: string
  /** Format tags to skip for error reporting. e.g. ['grill-evaluation'], ['audit-finding', 'audit-score'] */
  formatTagsToSkip?: string[]
  /** Active conversation mode — used to suppress expected plan-mode permission blocks. */
  mode?: ConversationMode
}

// ── Expected plan-mode permission blocks ──
// In Plan mode, Write/Edit are intentionally not on the allow-list, so the SDK
// returns "No such tool available: Write/Edit". This is expected behavior, not a
// bug — we must not auto-report it to the bug tracker (it pollutes the tracker
// with false positives every time a model reaches for Write to author a plan).
const PLAN_BLOCKED_TOOLS = new Set(['Write', 'Edit', 'MultiEdit'])

// ── Conditionally-loaded MCP tools ──
// These tools belong to MCP servers that may not be running (e.g., memory server
// when no workspace is configured). "No such tool available" for these is expected,
// not a bug — suppress from the bug tracker.
const CONDITIONAL_MCP_TOOLS = new Set(MCP_TOOLS.MEMORY._ALL_NAMES)

/**
 * True when a tool_use_error is a transient LLM JSON generation error —
 * Claude occasionally drops key names or generates invalid JSON for tool
 * parameters. The CLI rejects these with InputValidationError. These are
 * self-correcting (the error goes back to Claude, which retries) and
 * should not pollute the bug tracker.
 */
export function isTransientLlmJsonError(content: string | undefined): boolean {
  if (!content) return false
  return content.includes('could not be parsed as JSON') || content.includes('InputValidationError')
}

/**
 * True when a tool_use_error is a self-correcting agent mistake —
 * the error goes back to Claude which retries with corrected parameters.
 * These should not pollute the bug tracker.
 */
export function isAgentToolMistake(content: string | undefined): boolean {
  if (!content) return false
  return (
    /replace_all is false/i.test(content) ||
    /has not been read yet/i.test(content) ||
    /old_string and new_string are exactly the same/i.test(content) ||
    /Path does not exist/i.test(content)
  )
}

/**
 * True when a tool_use_error is the expected outcome of calling a conditionally-loaded
 * MCP tool that isn't currently available — not a real failure to report.
 */
export function isExpectedToolUnavailable(
  toolName: string | undefined,
  content: string | undefined
): boolean {
  if (!toolName || !content) return false
  if (!content.includes('No such tool available')) return false
  return CONDITIONAL_MCP_TOOLS.has(toolName)
}

/**
 * True when a tool_use_error is the expected "blocked in Plan mode" outcome of a
 * Write/Edit attempt — i.e. a permission gate, not a real failure to report.
 */
export function isExpectedPlanModeBlock(
  toolName: string | undefined,
  content: string | undefined,
  mode: ConversationMode | undefined
): boolean {
  if (mode !== 'plan') return false
  if (!toolName || !PLAN_BLOCKED_TOOLS.has(toolName)) return false
  if (!content) return false
  return content.includes('No such tool available')
}

// ── Composable tools: input is composed into result so file/pattern is visible without expanding ──

const COMPOSABLE_TOOLS = new Set(['Read', 'Grep', 'Glob'])

// ── Structured metadata extraction ──

function extractStructuredMeta(
  toolName: string | undefined,
  toolInput: string | undefined,
  toolInputRaw?: string
): { filePath?: string; lineRange?: string; operationType: ToolOperationType } {
  const name = (toolName ?? '').toLowerCase()

  // Determine operation type from tool name
  const operationType: ToolOperationType =
    name === 'read'
      ? 'read'
      : name === 'write'
        ? 'write'
        : name === 'edit' || name === 'multiedit'
          ? 'edit'
          : name === 'grep' || name === 'glob'
            ? 'search'
            : name === 'bash'
              ? 'shell'
              : name.startsWith('mcp__code') || name.startsWith('mcp__semantic')
                ? 'codegraph'
                : 'other'

  // Prefer toolInputRaw — actual JSON tool input. `toolInput` on the CLI
  // backend is a human-readable display string ("src/a.ts (1 lines)"), not
  // parseable JSON; JSON.parse on it always throws. toolInputRaw carries the
  // real object (see StreamChunk.toolInputRaw). OpenCode's toolInput has
  // historically already been raw JSON, so this falls back correctly there.
  const rawSource = toolInputRaw ?? toolInput
  if (!rawSource) return { operationType }

  let input: Record<string, unknown> = {}
  try {
    input = JSON.parse(rawSource) as Record<string, unknown>
  } catch {
    return { operationType }
  }

  // Extract file path
  const filePath = (input.file_path ?? input.filePath ?? input.path) as string | undefined

  // Extract line range from offset + limit
  const offset = input.offset as number | undefined
  const limit = input.limit as number | undefined
  const lineRange = offset ? `${offset}${limit ? `-${offset + limit - 1}` : '+'}` : undefined

  return { filePath: filePath || undefined, lineRange, operationType }
}

// ── Core processor ──

/**
 * Process a single tool-related StreamChunk and return a normalized ToolActivity.
 * Returns null for non-tool chunks or internal control tools.
 */
export function processToolChunk(
  chunk: StreamChunk,
  options: ToolChunkOptions
): ProcessedToolChunk | null {
  if (chunk.type !== 'tool_use' && chunk.type !== 'tool_result' && chunk.type !== 'tool_progress') {
    return null
  }

  // Control tools are internal — never surface in UI
  if (chunk.toolName?.startsWith(MCP_TOOLS.CONTROL_ACTIONS._PREFIX)) return null

  if (chunk.type === 'tool_use') {
    const meta = extractStructuredMeta(chunk.toolName, chunk.toolInput, chunk.toolInputRaw)
    return {
      type: 'tool_activity',
      toolActivity: {
        id: generateToolId(chunk.toolId),
        toolName: chunk.toolName ?? 'Unknown',
        status: 'running',
        input: safelySummarizeInput(chunk.toolInput, chunk.toolName, options.workspacePath),
        startedAt: Date.now(),
        filePath: meta.filePath,
        lineRange: meta.lineRange,
        operationType: meta.operationType
      }
    }
  }

  if (chunk.type === 'tool_result') {
    // Use the pre-computed input summary from the normalizer (stored during tool_use processing).
    // Falls back to parsing result content for backward compatibility.
    let toolInputSummary: string | undefined = chunk.toolInput
    if (!toolInputSummary && chunk.content) {
      try {
        const parsed = JSON.parse(chunk.content) as Record<string, unknown>
        toolInputSummary = summarizeToolInput(chunk.toolName ?? '', parsed, options.workspacePath)
      } catch {
        // Result content isn't JSON — no input summary available
      }
    }

    const resultObj = extractResultSummary(chunk.toolName ?? '', chunk.content)
    let resultSummary = resultObj?.result
    const resultDetail = resultObj?.resultDetail

    // Compose file path / pattern into result so it's always visible without expanding
    if (toolInputSummary && resultSummary && COMPOSABLE_TOOLS.has(chunk.toolName ?? '')) {
      resultSummary = `${resultSummary} — ${toolInputSummary}`
    }

    // Tag the activity as 'error' when the SDK returned a tool_use_error,
    // the stream-normalizer propagated is_error, or the content indicates a
    // permission denial from the CLI.
    const contentStr = typeof chunk.content === 'string' ? chunk.content : ''
    const isPermissionDenial = /Claude requested permissions/.test(contentStr)
    const isToolError =
      contentStr.includes('<tool_use_error>') || chunk.isError === true || isPermissionDenial

    // Auto-capture tool errors to the bug tracker (skip known format tags,
    // expected plan-mode Write/Edit permission blocks, and permission denials
    // which are user-initiated and not bugs).
    const skipTags = new Set(options.formatTagsToSkip ?? [])
    const isPlanModeBlock = isExpectedPlanModeBlock(chunk.toolName, chunk.content, options.mode)
    const isConditionalToolMissing = isExpectedToolUnavailable(chunk.toolName, chunk.content)
    const isTransientJson = isTransientLlmJsonError(chunk.content)
    const isAgentMistake = isAgentToolMistake(chunk.content)
    if (
      isToolError &&
      chunk.content &&
      !skipTags.has(chunk.toolName ?? '') &&
      !isPlanModeBlock &&
      !isConditionalToolMissing &&
      !isTransientJson &&
      !isAgentMistake &&
      !isPermissionDenial
    ) {
      reportToolError(chunk.toolName ?? 'Unknown', chunk.content, {
        agentType: options.agentType,
        workspaceId: options.workspaceId,
        agentId: options.agentId
      })
    }

    // Extract structured metadata from the original tool input
    const meta = extractStructuredMeta(chunk.toolName, chunk.toolInput, chunk.toolInputRaw)

    const toolActivity: ToolActivity = {
      id: generateToolId(chunk.toolId),
      toolName: chunk.toolName ?? 'Unknown',
      status: isToolError ? 'error' : 'completed',
      startedAt: 0,
      completedAt: Date.now(),
      filePath: meta.filePath,
      lineRange: meta.lineRange,
      operationType: meta.operationType
    }
    if (toolInputSummary) toolActivity.input = toolInputSummary
    // Override result summary for permission denials with a clear label
    if (isPermissionDenial) {
      toolActivity.result = 'Permission denied'
    } else if (resultSummary) {
      toolActivity.result = resultSummary
    }
    if (resultDetail) toolActivity.resultDetail = resultDetail

    return { type: 'tool_activity', toolActivity }
  }

  // tool_progress
  return {
    type: 'tool_activity',
    toolActivity: {
      id: generateToolId(chunk.toolId),
      toolName: chunk.toolName ?? 'Unknown',
      status: 'running',
      startedAt: 0,
      elapsedSeconds: chunk.elapsedSeconds
    }
  }
}

// ── Helpers ──

function generateToolId(toolId?: string): string {
  return toolId ?? `tool-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`
}

function safelySummarizeInput(
  toolInput: string | undefined,
  toolName: string | undefined,
  workspacePath?: string
): string | undefined {
  if (!toolInput) return undefined
  try {
    const parsed = JSON.parse(toolInput) as Record<string, unknown>
    return summarizeToolInput(toolName ?? '', parsed, workspacePath)
  } catch {
    return toolInput.slice(0, 120)
  }
}

/**
 * ToolResultSummarizer — registry-based tool result summarization.
 * Replaces the 257-line extractResultSummary function with focused per-tool handlers.
 */

import { MCP_TOOLS } from '../../shared/constants'

/** Return type — short summary + optional expanded detail */
export interface ToolResultSummary {
  result: string
  resultDetail?: string
}

/** Cap for resultDetail content — ~8K chars */
const DETAIL_CAP = 8192

/** Cap detail content, appending an explicit marker when truncating. */
function capDetail(content: string): string {
  if (content.length <= DETAIL_CAP) return content
  return (
    content.slice(0, DETAIL_CAP) + `\n… (truncated — ${content.length - DETAIL_CAP} more chars)`
  )
}

type Summarizer = (content: string) => ToolResultSummary | undefined

// ── Helper: pluralize a count ──

function pluralize(n: number, singular: string, plural?: string): string {
  return `${n} ${n === 1 ? singular : (plural ?? singular + 's')}`
}

// ── Global pre-checks (run before tool-specific handlers) ──

function checkPersistedOutput(content: string): ToolResultSummary | undefined {
  if (content.includes('<persisted-output>') || content.includes('persisted-output')) {
    return {
      result: 'Result too large to display',
      resultDetail: 'Output was persisted by the SDK. Check .claude/ directory for the full result.'
    }
  }
  return undefined
}

function checkToolUseError(content: string): ToolResultSummary | undefined {
  if (!content.includes('<tool_use_error>')) return undefined

  const match = content.match(/<tool_use_error>([\s\S]*?)(?:<\/tool_use_error>|$)/)
  const inner = (match?.[1] ?? content).trim()

  if (/modified since read/i.test(inner))
    return { result: 'Stale read — re-read needed', resultDetail: capDetail(inner) }
  if (/string to replace not found/i.test(inner))
    return { result: 'String not found — re-read needed', resultDetail: capDetail(inner) }
  if (/permission denied|EACCES|operation not permitted/i.test(inner))
    return { result: 'Permission denied', resultDetail: capDetail(inner) }
  if (/could not be parsed as JSON|InputValidationError/i.test(inner))
    return { result: 'Malformed input — will retry', resultDetail: capDetail(inner) }

  const oneLine = inner.split('\n')[0]?.trim() ?? 'Tool error'
  const shortResult = oneLine.length > 80 ? `Error: ${oneLine.slice(0, 77)}…` : `Error: ${oneLine}`
  return { result: shortResult, resultDetail: capDetail(inner) }
}

// ── SDK builtin tool handlers ──

const summarizeWrite: Summarizer = (content) => {
  if (!content || content.length < 10) return { result: 'Done' }
  return {
    result: 'Done',
    resultDetail: capDetail(content)
  }
}

const summarizeBash: Summarizer = (content) => {
  const lines = content.split('\n').filter((l) => l.trim())
  if (lines.length === 0) return { result: 'No output' }

  if (content.includes('exit code')) {
    const exitMatch = content.match(/exit code[:\s]*(\d+)/i)
    if (exitMatch) {
      const shortResult =
        exitMatch[1] === '0' ? 'Success (exit 0)' : `Failed (exit ${exitMatch[1]})`
      return {
        result: shortResult,
        resultDetail: lines.length > 1 ? capDetail(content) : undefined
      }
    }
  }

  const firstLine = lines[0].trim()
  const shortResult = firstLine.length > 80 ? firstLine.slice(0, 77) + '...' : firstLine
  return {
    result: shortResult,
    resultDetail: lines.length > 1 || firstLine.length > 80 ? capDetail(content) : undefined
  }
}

const summarizeRead: Summarizer = (content) => {
  const lineCount = content.split('\n').length
  return {
    result: `${lineCount} line${lineCount !== 1 ? 's' : ''} read`,
    resultDetail: content.length > 40 ? capDetail(content) : undefined
  }
}

const summarizeGrep: Summarizer = (content) => {
  const matchLines = content.split('\n').filter((l) => l.trim())
  const detail = matchLines.slice(0, 30).join('\n')
  return {
    result: pluralize(matchLines.length, 'match', 'matches'),
    resultDetail: detail.length > 0 ? capDetail(detail) : undefined
  }
}

const summarizeGlob: Summarizer = (content) => {
  const fileLines = content.split('\n').filter((l) => l.trim())
  const detail = fileLines.slice(0, 50).join('\n')
  return {
    result: `${fileLines.length} file${fileLines.length !== 1 ? 's' : ''} found`,
    resultDetail: detail.length > 0 ? capDetail(detail) : undefined
  }
}

// ── Exact-name handler registry ──

const EXACT_HANDLERS: Record<string, Summarizer> = {
  Write: summarizeWrite,
  Edit: summarizeWrite,
  Bash: summarizeBash,
  Read: summarizeRead,
  Grep: summarizeGrep,
  Glob: summarizeGlob
}

// ── MCP prefix-based handlers ──

function summarizeCodeGraph(content: string): ToolResultSummary | undefined {
  try {
    const parsed = JSON.parse(content)
    const detail = capDetail(content)

    if (parsed.symbols?.length !== undefined)
      return { result: pluralize(parsed.symbols.length, 'symbol'), resultDetail: detail }
    if (parsed.callers?.length !== undefined)
      return { result: pluralize(parsed.callers.length, 'caller'), resultDetail: detail }
    if (parsed.references?.length !== undefined)
      return { result: pluralize(parsed.references.length, 'reference'), resultDetail: detail }
    if (parsed.callees?.length !== undefined)
      return { result: pluralize(parsed.callees.length, 'callee'), resultDetail: detail }
    if (parsed.outline?.length !== undefined)
      return {
        result: `${parsed.outline.length} symbol${parsed.outline.length !== 1 ? 's' : ''} in outline`,
        resultDetail: detail
      }
    if (parsed.coupledPairs?.length !== undefined)
      return { result: pluralize(parsed.coupledPairs.length, 'coupled pair'), resultDetail: detail }
    if (parsed.cycles?.length !== undefined)
      return { result: pluralize(parsed.cycles.length, 'cycle'), resultDetail: detail }
    if (parsed.boundaries?.length !== undefined)
      return {
        result: `${parsed.boundaries.length} module boundar${parsed.boundaries.length !== 1 ? 'ies' : 'y'}`,
        resultDetail: detail
      }
    if (parsed.count !== undefined)
      return { result: pluralize(parsed.count, 'result'), resultDetail: detail }
    if (parsed.definitions?.length !== undefined)
      return { result: pluralize(parsed.definitions.length, 'definition'), resultDetail: detail }
    if (parsed.report)
      return { result: `${parsed.report.filesIncluded ?? '?'} files mapped`, resultDetail: detail }

    // Generic fallback — find the first top-level array
    const firstArr = Object.entries(parsed).find(([, v]) => Array.isArray(v)) as
      | [string, unknown[]]
      | undefined
    if (firstArr) return { result: `${firstArr[1].length} ${firstArr[0]}`, resultDetail: detail }
  } catch {
    /* fall through to default */
  }
  return undefined
}

function summarizeCodeAnalysis(content: string): ToolResultSummary | undefined {
  try {
    const parsed = JSON.parse(content)
    const detail = capDetail(content)

    if (parsed.totalCount !== undefined) {
      const mode = parsed.mode === 'overview' ? ' (overview)' : ''
      return {
        result: `${parsed.totalCount} marker${parsed.totalCount !== 1 ? 's' : ''} found${mode}`,
        resultDetail: detail
      }
    }
    if (parsed.summary?.totalSourceFiles !== undefined) {
      const s = parsed.summary
      const mode = parsed.mode === 'overview' ? ' (overview)' : ''
      return {
        result: `${s.filesWithTests}/${s.totalSourceFiles} covered (${Math.round(s.coverageRatio * 100)}%)${mode}`,
        resultDetail: detail
      }
    }
    if (parsed.counts?.total !== undefined) {
      const c = parsed.counts
      const outdated = c.outdated > 0 ? `, ${c.outdated} outdated` : ''
      return {
        result: `${c.total} deps (${c.production} prod, ${c.dev} dev${outdated})`,
        resultDetail: detail
      }
    }
    if (parsed.count !== undefined) {
      return { result: pluralize(parsed.count, 'result'), resultDetail: detail }
    }
  } catch {
    /* fall through */
  }
  return undefined
}

function summarizeGitContext(content: string): ToolResultSummary | undefined {
  try {
    const parsed = JSON.parse(content)
    const detail = capDetail(content)

    if (parsed.commits?.length !== undefined)
      return { result: pluralize(parsed.commits.length, 'commit'), resultDetail: detail }
    if (parsed.hunks?.length !== undefined)
      return { result: pluralize(parsed.hunks.length, 'diff hunk'), resultDetail: detail }
    if (parsed.lines?.length !== undefined)
      return { result: pluralize(parsed.lines.length, 'blame line'), resultDetail: detail }
  } catch {
    /* fall through */
  }
  return undefined
}

function summarizeSemanticSearch(content: string): ToolResultSummary | undefined {
  try {
    const parsed = JSON.parse(content)
    const detail = capDetail(content)

    if (parsed.results?.length !== undefined)
      return { result: pluralize(parsed.results.length, 'result'), resultDetail: detail }
    if (parsed.concepts?.length !== undefined)
      return { result: pluralize(parsed.concepts.length, 'concept'), resultDetail: detail }
  } catch {
    /* fall through */
  }
  return undefined
}

// ── Prefix-handler pairs (checked in order) ──

const PREFIX_HANDLERS: Array<{ prefix: string; handler: Summarizer }> = [
  { prefix: MCP_TOOLS.CODE_GRAPH._PREFIX, handler: summarizeCodeGraph },
  { prefix: MCP_TOOLS.CODE_ANALYSIS._PREFIX, handler: summarizeCodeAnalysis },
  { prefix: MCP_TOOLS.GIT_CONTEXT._PREFIX, handler: summarizeGitContext },
  { prefix: MCP_TOOLS.SEMANTIC_SEARCH._PREFIX, handler: summarizeSemanticSearch }
]

// ── Default fallback ──

function defaultSummary(content: string): ToolResultSummary | undefined {
  const firstLine = content.split('\n')[0]?.trim()
  if (!firstLine) return undefined
  const shortResult = firstLine.length > 80 ? firstLine.slice(0, 77) + '...' : firstLine
  const truncated = shortResult !== firstLine || content.length > firstLine.length + 1
  return { result: shortResult, resultDetail: truncated ? capDetail(content) : undefined }
}

// ── Public API ──

/**
 * Extracts a brief human-readable result summary from a tool result.
 * Returns both a short `result` (one-line) and an optional `resultDetail`
 * (expanded text, up to ~8K chars) for the expand panel in ToolActivityBlock.
 */
export function extractResultSummary(
  toolName: string,
  content: string | undefined
): ToolResultSummary | undefined {
  if (!content) return undefined
  try {
    // Global pre-checks
    const persisted = checkPersistedOutput(content)
    if (persisted) return persisted

    const toolError = checkToolUseError(content)
    if (toolError) return toolError

    // Exact name match (SDK built-in tools)
    const exactHandler = EXACT_HANDLERS[toolName]
    if (exactHandler) return exactHandler(content)

    // Prefix match (MCP tools)
    for (const { prefix, handler } of PREFIX_HANDLERS) {
      if (toolName.startsWith(prefix)) {
        const result = handler(content)
        if (result) return result
      }
    }

    // Default fallback
    return defaultSummary(content)
  } catch {
    return undefined
  }
}

/**
 * Tool error reporting — captures MCP tool errors to the bug tracker.
 * Extracted to avoid circular imports between chat-shared and chunk-router.
 */

import { app } from 'electron'
import { bugRepository } from '../db/repositories/bug.repository'
import { chatIpcLogger } from '../logger'

const log = chatIpcLogger

/**
 * Auto-capture MCP tool errors to the bug tracker.
 * Called when `isToolError` is true in any pipeline (Specialist, Grill, Audit).
 */
export function reportToolError(
  toolName: string,
  errorContent: string,
  context: { agentType: string; workspaceId?: string; agentId?: string }
): void {
  try {
    // Skip expected safety-guard rejections — these aren't real bugs
    if (toolName === 'Bash' && errorContent.includes('Blocked:')) {
      log.debug(`Suppressed expected Bash safety rejection: ${errorContent.slice(0, 100)}`)
      return
    }

    const firstLine = errorContent.split('\n')[0]?.trim() ?? 'Unknown error'
    const SDK_BUILTIN_TOOLS = new Set(['Read', 'Write', 'Edit', 'Bash', 'Grep', 'Glob'])
    const prefix = SDK_BUILTIN_TOOLS.has(toolName) ? 'Tool error' : 'MCP tool error'
    bugRepository.upsertBug({
      process: 'main',
      severity: 'error',
      errorMessage: `${prefix}: ${toolName} — ${firstLine}`,
      stackTrace: errorContent.slice(0, 2048),
      componentName: context.agentType,
      agentId: context.agentId,
      workspaceId: context.workspaceId,
      appVersion: app.getVersion()
    })
  } catch (e) {
    log.warn('Failed to report tool error to bug tracker:', e)
  }
}

import { BaseRepository } from '../base-repository'
import { randomUUID, createHash } from 'node:crypto'

export interface BugRecord {
  id: string
  fingerprint: string
  timestamp: string
  lastSeenAt: string
  process: 'main' | 'renderer' | 'preload'
  severity: 'error' | 'fatal'
  errorMessage: string
  stackTrace: string | null
  sourceFile: string | null
  sourceLine: number | null
  sourceColumn: number | null
  componentName: string | null
  activeView: string | null
  workspaceId: string | null
  agentId: string | null
  appVersion: string
  osInfo: string | null
  isResolved: boolean
  occurrenceCount: number
  note: string | null
  createdAt: string
}

export interface CreateBugInput {
  process: 'main' | 'renderer' | 'preload'
  severity: 'error' | 'fatal'
  errorMessage: string
  stackTrace?: string
  sourceFile?: string
  sourceLine?: number
  sourceColumn?: number
  componentName?: string
  activeView?: string
  workspaceId?: string
  agentId?: string
  appVersion: string
  osInfo?: string
}

export interface BugFilters {
  process?: 'main' | 'renderer' | 'preload'
  isResolved?: boolean
  workspaceId?: string
  sortBy?: 'last_seen_at' | 'occurrence_count' | 'severity'
  sortDir?: 'asc' | 'desc'
}

interface BugRow {
  id: string
  fingerprint: string
  timestamp: string
  last_seen_at: string
  process: string
  severity: string
  error_message: string
  stack_trace: string | null
  source_file: string | null
  source_line: number | null
  source_column: number | null
  component_name: string | null
  active_view: string | null
  workspace_id: string | null
  agent_id: string | null
  app_version: string
  os_info: string | null
  is_resolved: number
  occurrence_count: number
  note: string | null
  created_at: string
}

function toModel(row: BugRow): BugRecord {
  return {
    id: row.id,
    fingerprint: row.fingerprint,
    timestamp: row.timestamp,
    lastSeenAt: row.last_seen_at,
    process: row.process as BugRecord['process'],
    severity: row.severity as BugRecord['severity'],
    errorMessage: row.error_message,
    stackTrace: row.stack_trace,
    sourceFile: row.source_file,
    sourceLine: row.source_line,
    sourceColumn: row.source_column,
    componentName: row.component_name,
    activeView: row.active_view,
    workspaceId: row.workspace_id,
    agentId: row.agent_id,
    appVersion: row.app_version,
    osInfo: row.os_info,
    isResolved: row.is_resolved === 1,
    occurrenceCount: row.occurrence_count,
    note: row.note,
    createdAt: row.created_at
  }
}

function computeFingerprint(
  errorMessage: string,
  sourceFile?: string,
  sourceLine?: number
): string {
  const raw = `${errorMessage}|${sourceFile ?? ''}|${sourceLine ?? ''}`
  return createHash('sha256').update(raw).digest('hex').slice(0, 16)
}

export class BugRepository extends BaseRepository<BugRow, BugRecord> {
  protected readonly tableName = 'bugs'
  protected mapRow(row: BugRow): BugRecord {
    return toModel(row)
  }

  /**
   * Insert or update a bug based on fingerprint deduplication.
   * Returns { isNew: true } when a toast should fire (new bug or regression).
   */
  upsertBug(input: CreateBugInput): { isNew: boolean; bugId: string } {
    const fingerprint = computeFingerprint(input.errorMessage, input.sourceFile, input.sourceLine)
    const now = new Date().toISOString()

    const existing = this.db()
      .prepare('SELECT id, is_resolved FROM bugs WHERE fingerprint = ?')
      .get(fingerprint) as { id: string; is_resolved: number } | undefined

    if (existing) {
      if (existing.is_resolved === 0) {
        this.db()
          .prepare(
            'UPDATE bugs SET occurrence_count = occurrence_count + 1, last_seen_at = ? WHERE id = ?'
          )
          .run(now, existing.id)
        return { isNew: false, bugId: existing.id }
      } else {
        this.db()
          .prepare(
            'UPDATE bugs SET is_resolved = 0, occurrence_count = occurrence_count + 1, last_seen_at = ? WHERE id = ?'
          )
          .run(now, existing.id)
        return { isNew: true, bugId: existing.id }
      }
    }

    const id = randomUUID()
    this.db()
      .prepare(
        `INSERT INTO bugs (id, fingerprint, timestamp, last_seen_at, process, severity, error_message, stack_trace, source_file, source_line, source_column, component_name, active_view, workspace_id, agent_id, app_version, os_info)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`
      )
      .run(
        id,
        fingerprint,
        now,
        now,
        input.process,
        input.severity,
        input.errorMessage,
        input.stackTrace ?? null,
        input.sourceFile ?? null,
        input.sourceLine ?? null,
        input.sourceColumn ?? null,
        input.componentName ?? null,
        input.activeView ?? null,
        input.workspaceId ?? null,
        input.agentId ?? null,
        input.appVersion,
        input.osInfo ?? null
      )
    return { isNew: true, bugId: id }
  }

  /** Get all bugs with optional filters and sorting */
  getAll(filters?: BugFilters): BugRecord[] {
    const conditions: string[] = []
    const params: unknown[] = []

    if (filters?.process) {
      conditions.push('process = ?')
      params.push(filters.process)
    }
    if (filters?.isResolved !== undefined) {
      conditions.push('is_resolved = ?')
      params.push(filters.isResolved ? 1 : 0)
    }
    if (filters?.workspaceId) {
      conditions.push('workspace_id = ?')
      params.push(filters.workspaceId)
    }

    const where = conditions.length > 0 ? `WHERE ${conditions.join(' AND ')}` : ''
    const sortCol = filters?.sortBy ?? 'last_seen_at'
    const sortDir = filters?.sortDir ?? 'desc'
    const validSorts = ['last_seen_at', 'occurrence_count', 'severity']
    const safeSortCol = validSorts.includes(sortCol) ? sortCol : 'last_seen_at'
    const safeSortDir = sortDir === 'asc' ? 'ASC' : 'DESC'

    const rows = this.db()
      .prepare(`SELECT * FROM bugs ${where} ORDER BY ${safeSortCol} ${safeSortDir}`)
      .all(...params) as BugRow[]
    return rows.map(toModel)
  }

  /** Get a single bug by ID */
  getById(id: string): BugRecord | null {
    const result = this.findOneBy('id', id)
    return result ?? null
  }

  /** Mark a bug as resolved */
  markResolved(id: string): void {
    this.db().prepare('UPDATE bugs SET is_resolved = 1 WHERE id = ?').run(id)
  }

  markUnresolved(id: string): void {
    this.db().prepare('UPDATE bugs SET is_resolved = 0 WHERE id = ?').run(id)
  }

  deleteBug(id: string): void {
    this.deleteById(id)
  }

  updateNote(id: string, note: string): void {
    this.db().prepare('UPDATE bugs SET note = ? WHERE id = ?').run(note, id)
  }

  getUnresolvedCount(): number {
    const result = this.db()
      .prepare('SELECT COUNT(*) as count FROM bugs WHERE is_resolved = 0')
      .get() as {
      count: number
    }
    return result.count
  }
}

export const bugRepository = new BugRepository()

/**
 * TextDeltaBatcher — coalesces streaming text deltas and flushes them at ~30fps.
 *
 * Shared by every streaming surface (Chat via chunk-router, Grill, Council) so
 * the renderer receives smooth sentence-cadence text instead of a burst of tiny
 * IPC sends. Reduces IPC calls from ~15/sec to ~3-5/sec during fast streaming.
 *
 * Generic by design: the caller supplies a `key` (to keep concurrent streams —
 * conversations, workspaces, advisors — from mixing) and a `flush` callback that
 * actually delivers the accumulated text. The batcher owns only the timing.
 */

/** One frame at 30fps. */
export const TEXT_BATCH_INTERVAL_MS = 33

export class TextDeltaBatcher {
  private buffers = new Map<string, string>()
  private timers = new Map<string, ReturnType<typeof setTimeout>>()
  private flushers = new Map<string, (text: string) => void>()
  /** Per-key active interval — tracks what interval each key's timer was armed with. */
  private activeIntervals = new Map<string, number>()
  private readonly intervalMs: number

  constructor(intervalMs: number = TEXT_BATCH_INTERVAL_MS) {
    this.intervalMs = intervalMs
  }

  /**
   * Buffer `text` under `key`. The most recent `flush` callback for a key wins
   * (closures may capture fresh per-chunk context). A timer is armed once per
   * key and fires `flush(buffer)` after the batch interval.
   *
   * @param intervalOverride — optional per-push interval override (ms). When the
   *   recommended interval changes (e.g. due to backpressure), the pending timer
   *   is rescheduled to the new interval. Omit to use the constructor default.
   */
  push(key: string, text: string, flush: (text: string) => void, intervalOverride?: number): void {
    this.flushers.set(key, flush)
    this.buffers.set(key, (this.buffers.get(key) ?? '') + text)
    const interval = intervalOverride ?? this.intervalMs
    const activeInterval = this.activeIntervals.get(key)

    if (!this.timers.has(key)) {
      // No pending timer — arm a new one
      this.activeIntervals.set(key, interval)
      this.timers.set(
        key,
        setTimeout(() => this.flushKey(key), interval)
      )
    } else if (activeInterval !== undefined && interval > activeInterval) {
      // IPC-BACKPRESSURE: Backpressure increased — reschedule with longer interval.
      // Only reschedule when slowing down (interval > active), not when speeding up,
      // to avoid cancelling a timer that's about to fire.
      clearTimeout(this.timers.get(key)!)
      this.activeIntervals.set(key, interval)
      this.timers.set(
        key,
        setTimeout(() => this.flushKey(key), interval)
      )
    }
  }

  /** Flush a single key, or all keys when `key` is omitted. */
  flush(key?: string): void {
    if (key !== undefined) {
      this.flushKey(key)
      // BATCHER-FLUSH-RETAINS-FLUSHER-01: Clear flusher after flush to prevent
      // stale callbacks (capturing old ctx/mainWindow) from firing on reuse.
      this.flushers.delete(key)
      return
    }
    for (const k of [...this.buffers.keys()]) {
      this.flushKey(k)
    }
  }

  /**
   * Flush and forget the flusher(s) — call at stream end so a key doesn't retain
   * a stale callback. With no `key`, resets everything.
   */
  reset(key?: string): void {
    if (key !== undefined) {
      this.flushKey(key)
      this.flushers.delete(key)
      return
    }
    this.flush()
    this.flushers.clear()
  }

  private flushKey(key: string): void {
    const timer = this.timers.get(key)
    if (timer) {
      clearTimeout(timer)
      this.timers.delete(key)
    }
    this.activeIntervals.delete(key)
    const buffer = this.buffers.get(key)
    const flusher = this.flushers.get(key)
    if (buffer && flusher) {
      try {
        flusher(buffer)
      } catch (err) {
        // All current callers use safeSend-wrapped callbacks, but the batcher
        // is a shared primitive — guard against future flusher regressions.
        if (typeof console !== 'undefined') console.warn('[TextDeltaBatcher] Flush error:', err)
      }
      this.buffers.delete(key)
    }
  }
}

/**
 * ChunkAckTracker — adaptive interval tracker for IPC backpressure.
 *
 * Monitors how quickly the renderer processes IPC chunks by tracking
 * pending (sent but un-ACKed) chunk counts per conversation. When the
 * pending count exceeds HIGH_WATER_MARK, recommends a slower batch
 * interval to give the renderer breathing room.
 *
 * Used by TextDeltaBatcher via chunk-router to dynamically adjust the
 * IPC send cadence based on renderer feedback.
 */

import { chatIpcLogger } from '../logger'

export class ChunkAckTracker {
  private pendingCounts = new Map<string, number>()
  private lastAckTimestamps = new Map<string, number>()
  private isBackpressured = new Map<string, boolean>()

  // ── Backpressure metrics ──────────────────────────────────
  private _backpressureActivations = new Map<string, number>()
  private _ackLatencies = new Map<string, number[]>()
  private _maxPendingChunks = new Map<string, number>()

  /** Chunks pending before slowdown triggers (~5 frames at 60fps = ~80ms buffer) */
  static readonly HIGH_WATER_MARK = 15
  /** Chunks pending to return to normal speed */
  static readonly LOW_WATER_MARK = 5
  /** Normal batch interval (~30fps) */
  static readonly NORMAL_INTERVAL_MS = 33
  /** Slow batch interval (~10fps, backpressure active) */
  static readonly SLOW_INTERVAL_MS = 100

  /** Record that we sent a batch to the renderer. */
  recordSend(conversationId: string): void {
    const current = this.pendingCounts.get(conversationId) ?? 0
    const next = current + 1
    this.pendingCounts.set(conversationId, next)

    // Track peak pending count
    const maxPending = this._maxPendingChunks.get(conversationId) ?? 0
    if (next > maxPending) {
      this._maxPendingChunks.set(conversationId, next)
    }

    // Track backpressure activations
    if (next === ChunkAckTracker.HIGH_WATER_MARK) {
      const activations = this._backpressureActivations.get(conversationId) ?? 0
      this._backpressureActivations.set(conversationId, activations + 1)
      chatIpcLogger.debug(
        `[ChunkAckTracker] Backpressure activated: pending=${next} conv=${conversationId.slice(0, 8)}`
      )
    }
  }

  /** Record renderer ACK — reduces pending count. */
  recordAck(conversationId: string, batchSize: number): void {
    const pending = this.pendingCounts.get(conversationId) ?? 0
    this.pendingCounts.set(conversationId, Math.max(0, pending - batchSize))

    const now = Date.now()
    const lastAck = this.lastAckTimestamps.get(conversationId)
    this.lastAckTimestamps.set(conversationId, now)

    // Track ACK latency (time between consecutive ACKs)
    if (lastAck) {
      const latency = now - lastAck
      const latencies = this._ackLatencies.get(conversationId) ?? []
      latencies.push(latency)
      // Keep last 50 latencies
      if (latencies.length > 50) latencies.shift()
      this._ackLatencies.set(conversationId, latencies)
    }
  }

  /** Get recommended batch interval based on backpressure state with hysteresis. */
  getRecommendedInterval(conversationId: string): number {
    const pending = this.pendingCounts.get(conversationId) ?? 0
    const wasBackpressured = this.isBackpressured.get(conversationId) ?? false

    if (pending >= ChunkAckTracker.HIGH_WATER_MARK) {
      this.isBackpressured.set(conversationId, true)
      return ChunkAckTracker.SLOW_INTERVAL_MS
    }
    if (wasBackpressured && pending > ChunkAckTracker.LOW_WATER_MARK) {
      return ChunkAckTracker.SLOW_INTERVAL_MS  // Stay slow until below LWM
    }
    this.isBackpressured.set(conversationId, false)
    return ChunkAckTracker.NORMAL_INTERVAL_MS
  }

  /** Clean up tracking state for a completed conversation. */
  cleanup(conversationId: string): void {
    this.pendingCounts.delete(conversationId)
    this.lastAckTimestamps.delete(conversationId)
    this.isBackpressured.delete(conversationId)
  }

  /** Get metrics for a conversation's stream (for logging on stream complete). */
  getMetrics(conversationId: string): {
    backpressureActivations: number
    avgAckLatency: number | null
    maxPendingChunks: number
  } {
    const activations = this._backpressureActivations.get(conversationId) ?? 0
    const latencies = this._ackLatencies.get(conversationId) ?? []
    const avgAckLatency = latencies.length > 0
      ? Math.round(latencies.reduce((a, b) => a + b, 0) / latencies.length)
      : null
    const maxPending = this._maxPendingChunks.get(conversationId) ?? 0

    return { backpressureActivations: activations, avgAckLatency, maxPendingChunks: maxPending }
  }

  /** Clear metrics for a conversation (call after logging on stream complete). */
  clearMetrics(conversationId: string): void {
    this._backpressureActivations.delete(conversationId)
    this._ackLatencies.delete(conversationId)
    this._maxPendingChunks.delete(conversationId)
  }
}

/** Singleton instance shared by chunk-router and ACK handler. */
export const chunkAckTracker = new ChunkAckTracker()

/**
 * plan-tasks — single source of truth for deriving a task manifest from a
 * StructuredPlan's phases.
 *
 * Both the renderer (plan-execution.store, via ChatExecutionPanel) and the
 * build-kickoff prompt sent to the model MUST derive taskIds the same way —
 * otherwise the model reports progress against IDs the UI never created
 * (or vice versa) and task-level tracking silently no-ops.
 *
 * taskId scheme: `${phaseId}-${index}`, 0-based index into phase.files[].
 */

import type { StructuredPlan } from './types'

export interface DerivedPlanTask {
  taskId: string
  title: string
  files: string[]
}

export interface DerivedPlanPhase {
  id: number
  title: string
  tasks: DerivedPlanTask[]
}

/** Derive per-phase task lists from a StructuredPlan. */
export function derivePlanTasks(
  plan: Pick<StructuredPlan, 'phases'> | null | undefined
): DerivedPlanPhase[] {
  return (plan?.phases ?? []).map((p) => ({
    id: p.id,
    title: p.title,
    tasks: (p.files ?? []).map((f, i) => ({
      taskId: `${p.id}-${i}`,
      title: f.change || f.file,
      files: [f.file]
    }))
  }))
}

/** Derive a phaseId -> files[] map, used for file-activity-based fallback inference. */
export function derivePhaseFiles(
  plan: Pick<StructuredPlan, 'phases'> | null | undefined
): Record<number, string[]> {
  return Object.fromEntries(
    (plan?.phases ?? []).map((p) => [p.id, (p.files ?? []).map((f) => f.file)])
  )
}

export interface MatchedPlanTask {
  phaseId: number
  phaseTitle: string
  taskId: string
  taskTitle: string
  /** Total task count in the matched phase (for totalTasks reporting). */
  totalTasksInPhase: number
  /** Normalized (forward-slash) path that was matched. */
  touchedFile: string
}

/**
 * Match a written/edited file path against a plan's derived task manifest.
 * Used to derive task completion from OBSERVED tool activity (write/edit)
 * rather than relying solely on the model self-reporting via
 * emit_phase_progress — this is what makes chat's task tracking work even
 * when the model never calls the tool for a given task.
 *
 * Matches on the longest declared file suffix and requires a UNIQUE longest
 * match — on a length tie between two candidate tasks, returns null rather
 * than guessing (a wrong auto-completion is worse than a missed one).
 */
export function matchPlanTaskForFile(
  plan: Pick<StructuredPlan, 'phases'> | null | undefined,
  filePath: string
): MatchedPlanTask | null {
  const normalizedPath = filePath.replace(/\\/g, '/')
  const phases = derivePlanTasks(plan)

  type Candidate = {
    phaseId: number
    phaseTitle: string
    taskId: string
    taskTitle: string
    totalTasksInPhase: number
    matchedFile: string
  }
  const candidates: Candidate[] = []

  for (const phase of phases) {
    for (const task of phase.tasks) {
      for (const f of task.files) {
        const normalizedF = f.replace(/\\/g, '/')
        // Exact match, or a path-BOUNDARY suffix match (preceded by '/').
        // A bare endsWith(normalizedF) with no boundary check would match
        // declared "store.ts" against written "my-store.ts" — a different
        // file that merely shares a substring. Condition 2 already covers
        // every legitimate case (including a bare declared filename like
        // "store.ts", matched via "/store.ts").
        if (normalizedPath === normalizedF || normalizedPath.endsWith('/' + normalizedF)) {
          candidates.push({
            phaseId: phase.id,
            phaseTitle: phase.title,
            taskId: task.taskId,
            taskTitle: task.title,
            totalTasksInPhase: phase.tasks.length,
            matchedFile: normalizedF
          })
        }
      }
    }
  }

  if (candidates.length === 0) return null

  candidates.sort((a, b) => b.matchedFile.length - a.matchedFile.length)
  const [best, second] = candidates
  if (second && second.matchedFile.length === best.matchedFile.length) {
    // Ambiguous — two equally-specific matches. Don't guess.
    return null
  }

  return {
    phaseId: best.phaseId,
    phaseTitle: best.phaseTitle,
    taskId: best.taskId,
    taskTitle: best.taskTitle,
    totalTasksInPhase: best.totalTasksInPhase,
    touchedFile: normalizedPath
  }
}

const TERMINAL_TASK_STATUSES = new Set(['complete', 'skipped', 'failed'])

/**
 * Whether every task DECLARED for a phase (via derivePlanTasks — the full
 * manifest, not just whatever happens to be persisted so far) has reached a
 * terminal status in the persisted task list. Used to auto-finalize a phase
 * from observed tool activity alone, without requiring the model to call
 * emit_phase_progress with status: 'completed'.
 *
 * Comparing against the full derived manifest (not the persisted subset) is
 * the important part — a phase with 4 declared tasks where only 1 has ever
 * been recorded must NOT be finalized just because that 1 task is done.
 * A phase with zero declared tasks (no files[]) is never auto-finalized here
 * — it stays dependent on the model's own phase-level report.
 */
export function isPhaseTaskSetComplete(
  plan: Pick<StructuredPlan, 'phases'> | null | undefined,
  phaseId: number,
  persistedTasks: Array<{ taskId: string; status: string }>
): boolean {
  const phase = derivePlanTasks(plan).find((p) => p.id === phaseId)
  if (!phase || phase.tasks.length === 0) return false

  const statusByTaskId = new Map(persistedTasks.map((t) => [t.taskId, t.status]))
  return phase.tasks.every((t) => {
    const status = statusByTaskId.get(t.taskId)
    return status !== undefined && TERMINAL_TASK_STATUSES.has(status)
  })
}

/**
 * Render a human-readable task manifest for injection into the build-kickoff
 * message, so the model reports emit_phase_progress task fields against the
 * exact taskIds the UI is already tracking (instead of inventing its own).
 */
export function renderTaskManifest(
  plan: Pick<StructuredPlan, 'phases'> | null | undefined
): string {
  const phases = derivePlanTasks(plan)
  if (!phases.length) return ''

  const lines: string[] = []
  for (const phase of phases) {
    lines.push(`Phase ${phase.id}: ${phase.title}`)
    if (!phase.tasks.length) {
      lines.push('  (no file-level tasks — report phase-level progress only)')
      continue
    }
    for (const task of phase.tasks) {
      lines.push(
        `  - taskId="${task.taskId}" title="${task.title}" files=[${task.files.join(', ')}]`
      )
    }
  }
  return lines.join('\n')
}

/**
 * Validates that an IPC message comes from a trusted sender.
 * Prevents rogue webviews or injected frames from calling IPC handlers.
 */
export function validateSender(event: Electron.IpcMainInvokeEvent): void {
  if (!event.senderFrame) {
    throw new Error('Unauthorized IPC sender: no sender frame')
  }

  const url = event.senderFrame.url

  // Allow file:// protocol (production) and localhost (dev with HMR)
  if (url.startsWith('file://') || url.startsWith('http://localhost')) {
    return
  }

  throw new Error(`Unauthorized IPC sender: ${url}`)
}

/**
 * SessionEventRouter — single point of IPC dispatch for multi-workspace sessions.
 *
 * Intercepts session events and forwards them to the renderer with workspaceId
 * tagging. Ensures all IPC payloads carry the workspace context so the renderer
 * can route events to the correct UI components (active workspace chat panel,
 * background status indicators, or cross-workspace permission toasts).
 */

import type { BrowserWindow } from 'electron'
import { IPC_CHANNELS } from '../../shared/constants'
import type { PendingPermission } from '../../shared/types'

export interface TaggedEvent {
  workspaceId: string
  [key: string]: unknown
}

export class SessionEventRouter {
  private mainWindow: BrowserWindow

  constructor(mainWindow: BrowserWindow) {
    this.mainWindow = mainWindow
  }

  // ROUTER-NOGUARD-01: Guard all IPC sends against destroyed window.
  // Matches the pattern used by ChatStreamService.safeWindowSend()
  // and chunk-router.ts safeSend().
  private safeSend(channel: string, ...args: unknown[]): void {
    try {
      if (!this.mainWindow.isDestroyed()) {
        this.mainWindow.webContents.send(channel, ...args)
      }
    } catch {
      // Non-fatal: window may have been destroyed between check and send
    }
  }

  /** Send a tagged event to the renderer on any IPC channel. */
  send(channel: string, payload: TaggedEvent): void {
    this.safeSend(channel, payload)
  }

  /**
   * Send a workspace-scoped event to the renderer.
   * Enforces workspaceId is always present in the payload.
   */
  sendWorkspaceEvent(channel: string, workspaceId: string, payload: Record<string, unknown>): void {
    this.safeSend(channel, { workspaceId, ...payload })
  }

  /** Send a permission/blocking event from a background workspace. */
  sendPermissionRequest(permission: PendingPermission): void {
    this.send(IPC_CHANNELS.PERMISSION_REQUEST, {
      ...permission
    })
  }
}

// ── Singleton ──

let _sessionEventRouter: SessionEventRouter | null = null

export function initSessionEventRouter(mainWindow: BrowserWindow): void {
  _sessionEventRouter = new SessionEventRouter(mainWindow)
}

export function getSessionEventRouter(): SessionEventRouter {
  if (!_sessionEventRouter) {
    throw new Error('SessionEventRouter not initialized — call initSessionEventRouter() first')
  }
  return _sessionEventRouter
}

import { spawnSync, spawn } from 'node:child_process'
import { EventEmitter } from 'node:events'
import { readFile } from 'node:fs/promises'
import { join } from 'node:path'
import log from 'electron-log/main'

const hookLog = log.scope('HookEngine')

export type HookEvent =
  | 'specialist_start'
  | 'specialist_complete'
  | 'specialist_failed'
  | 'gate_passed'
  | 'gate_failed'
  | 'escalation'
  | 'pre_merge'
  | 'post_merge'
  | 'plan_created'
  | 'checkpoint_approved'
  | 'checkpoint_rejected'
  | 'abandonment_detected'
  | 'task_loop_complete'
  // MPA (Multi-Phased Agent) lifecycle events
  | 'mpa_plan_complete'
  | 'mpa_build_start'
  | 'mpa_build_complete'
  | 'mpa_verify_complete'
  | 'mpa_goal_achieved'
  | 'mpa_goal_failed'

export interface HookDefinition {
  event: HookEvent
  name: string
  command: string
  blocking: boolean
  condition?: { mode?: 'plan' | 'build' | 'danger'; model?: string; agent?: string }
  timeout?: number // default 30000
}

export interface HookResult {
  hook: string
  event: HookEvent
  exitCode: number | null
  stdout: string
  stderr: string
  durationMs: number
}

/**
 * Declarative hook engine — loads user-defined hooks from workspace config
 * and executes them at lifecycle events (specialist start/complete, gates, merges, etc.).
 *
 * Hooks are defined in `.agentstudio/hooks.json` at the workspace root.
 * Blocking hooks run synchronously and can gate operations; non-blocking hooks fire-and-forget.
 */
class HookEngine extends EventEmitter {
  private hooks: HookDefinition[] = []
  private workspacePath: string | null = null

  constructor() {
    super()
  }

  async loadHooks(workspacePath: string): Promise<void> {
    this.workspacePath = workspacePath
    const hookFile = join(workspacePath, '.agentstudio', 'hooks.json')
    try {
      const raw = await readFile(hookFile, 'utf-8')
      const parsed = JSON.parse(raw) as { hooks?: HookDefinition[] }
      this.hooks = parsed.hooks ?? []
      if (this.hooks.length > 0) {
        hookLog.info(`Loaded ${this.hooks.length} hook(s) from ${hookFile}`)
      }
    } catch {
      this.hooks = [] // No hooks file — that's fine
    }
  }

  async executeHooks(
    event: HookEvent,
    context: Record<string, string> = {}
  ): Promise<HookResult[]> {
    // F8: Filter by event AND evaluate condition fields (mode, model, agent).
    // Previously only filtered by event, ignoring condition — hooks defined with
    // condition: { mode: 'build' } would incorrectly execute during plan mode.
    const matching = this.hooks.filter((h) => {
      if (h.event !== event) return false
      if (!h.condition) return true
      if (h.condition.mode && context.mode !== h.condition.mode) return false
      if (h.condition.model && context.model !== h.condition.model) return false
      if (h.condition.agent && context.agent !== h.condition.agent) return false
      return true
    })
    if (matching.length === 0) return []

    const results: HookResult[] = []
    for (const hook of matching) {
      const hookId = `${hook.name}-${Date.now()}`

      // Emit lifecycle: started
      // HOOK-EMIT-UNGUARDED-01: Wrap emit in try-catch so listener errors
      // don't abort hook execution before it even starts.
      try {
        this.emit('hookLifecycle', {
          hookId,
          hookName: hook.name,
          hookEvent: event,
          phase: 'started' as const,
          output: undefined
        })
      } catch (emitErr) {
        hookLog.warn(`Hook "${hook.name}" lifecycle emit (started) failed:`, emitErr)
      }

      // SVC-16: Escape context values to prevent shell metacharacter injection.
      // Context values (workspaceId, mode, etc.) may contain shell-special chars.
      let cmd = hook.command
      for (const [key, val] of Object.entries(context)) {
        // Escape single quotes in value, then wrap in single quotes for POSIX shell safety
        const escaped = "'" + val.replace(/'/g, "'\\''") + "'"
        cmd = cmd.replaceAll(`\${${key}}`, escaped)
      }

      const start = Date.now()
      if (hook.blocking) {
        // Synchronous — blocks until complete
        try {
          const spawnResult = spawnSync('sh', ['-c', cmd], {
            cwd: this.workspacePath ?? undefined,
            encoding: 'utf-8',
            timeout: hook.timeout ?? 30000
          })
          if (spawnResult.error) throw spawnResult.error
          if (spawnResult.status !== 0) {
            throw new Error(spawnResult.stderr || `Hook exited with code ${spawnResult.status}`)
          }
          const stdout = spawnResult.stdout ?? ''
          hookLog.info(`Hook "${hook.name}" completed (${Date.now() - start}ms)`)
          const hookResult: HookResult = {
            hook: hook.name,
            event,
            exitCode: 0,
            stdout,
            stderr: '',
            durationMs: Date.now() - start
          }
          results.push(hookResult)

          // Emit lifecycle: response
          try {
            this.emit('hookLifecycle', {
              hookId,
              hookName: hook.name,
              hookEvent: event,
              phase: 'response' as const,
              output: stdout.slice(0, 500),
              outcome: 'success'
            })
          } catch (emitErr) {
            hookLog.warn(`Hook "${hook.name}" lifecycle emit (response) failed:`, emitErr)
          }
        } catch (err: unknown) {
          const stderr = err instanceof Error ? err.message : String(err)
          hookLog.warn(`Hook "${hook.name}" failed: ${stderr.slice(0, 200)}`)
          results.push({
            hook: hook.name,
            event,
            exitCode: 1,
            stdout: '',
            stderr,
            durationMs: Date.now() - start
          })

          // Emit lifecycle: response (failure)
          try {
            this.emit('hookLifecycle', {
              hookId,
              hookName: hook.name,
              hookEvent: event,
              phase: 'response' as const,
              output: stderr.slice(0, 500),
              outcome: 'failure'
            })
          } catch (emitErr) {
            hookLog.warn(`Hook "${hook.name}" lifecycle emit (failure) failed:`, emitErr)
          }
        }
      } else {
        // Fire-and-forget
        try {
          const child = spawn('sh', ['-c', cmd], {
            cwd: this.workspacePath ?? undefined,
            stdio: 'ignore',
            detached: true
          })
          child.unref()
          hookLog.info(`Hook "${hook.name}" fired (non-blocking)`)
        } catch (err) {
          hookLog.warn(`Failed to spawn hook "${hook.name}":`, err)
        }
        results.push({
          hook: hook.name,
          event,
          exitCode: null,
          stdout: '',
          stderr: '',
          durationMs: 0
        })

        // Emit lifecycle: response (fire-and-forget — no stdout)
        try {
          this.emit('hookLifecycle', {
            hookId,
            hookName: hook.name,
            hookEvent: event,
            phase: 'response' as const,
            output: undefined,
            outcome: 'fired'
          })
        } catch (emitErr) {
          hookLog.warn(`Hook "${hook.name}" lifecycle emit (fired) failed:`, emitErr)
        }
      }
    }
    return results
  }

  getLoadedHooks(): HookDefinition[] {
    return [...this.hooks]
  }
}

export const hookEngine = new HookEngine()

/**
 * plan-registry.service — Single entry point for plan registration in the
 * unified Plan Hub registry.
 *
 * Each source (Chat, Grill, Audit, Council) calls a dedicated `register*`
 * method. The service normalizes all plan types to StructuredPlan, derives
 * metrics, and writes to the `plans` table via PlanRepository.
 *
 * Design principles:
 *   - Non-critical: all register methods wrap in try-catch so existing features
 *     never break if the registry fails.
 *   - Idempotent: duplicate source registrations are skipped via findBySource().
 *   - Pure normalization: mappers are side-effect free.
 */

import log from 'electron-log'
import { planRepository } from '../db/repositories/plan.repository'
import { grillPlanToStructuredPlan } from './grill-plan-mapper'
import { auditPlanToStructuredPlan } from './audit-plan-mapper'
import type {
  StructuredPlan,
  GrillStructuredPlan,
  AuditPlan,
  CouncilVerdict,
  PlanRecord
} from '../../shared/types'

const svcLog = log.scope('plan-registry')

class PlanRegistryService {
  // ── Chat plans ──

  registerChatPlan(params: {
    workspaceId: string
    conversationId: string
    messageId: string
    plan: StructuredPlan
    rawContent: string
  }): PlanRecord | null {
    try {
      // Deduplicate: one plan per message
      const existing = planRepository.findBySource('chat', params.messageId)
      if (existing) {
        svcLog.info(`[register-chat] Skipped duplicate for message=${params.messageId}`)
        return existing
      }

      const record = planRepository.savePlan({
        workspaceId: params.workspaceId,
        source: 'chat',
        sourceId: params.messageId,
        title: params.plan.title || 'Untitled Plan',
        summary: params.plan.summary || '',
        planType: params.plan.type ?? null,
        structuredPlan: params.plan,
        linkedConversationId: params.conversationId
      })

      svcLog.info(`[register-chat] ✓ Plan registered: id=${record.id}, title="${record.title}"`)
      return record
    } catch (err) {
      svcLog.warn('[register-chat] Failed (non-critical):', err)
      return null
    }
  }

  // ── Grill plans ──

  registerGrillPlan(params: {
    workspaceId: string
    grillSessionId: string
    plan: GrillStructuredPlan
  }): PlanRecord | null {
    try {
      const existing = planRepository.findBySource('grill', params.grillSessionId)
      if (existing) {
        svcLog.info(`[register-grill] Skipped duplicate for session=${params.grillSessionId}`)
        return existing
      }

      const structuredPlan = grillPlanToStructuredPlan(params.plan)

      const record = planRepository.savePlan({
        workspaceId: params.workspaceId,
        source: 'grill',
        sourceId: params.grillSessionId,
        title: params.plan.title || 'Untitled Grill Plan',
        summary: params.plan.summary || '',
        planType: structuredPlan.type ?? null,
        structuredPlan,
        sourcePlanJson: JSON.stringify(params.plan),
        requirementDocument: params.plan.requirementDocument || null
      })

      svcLog.info(
        `[register-grill] ✓ Plan registered: id=${record.id}, items=${params.plan.items.length}`
      )
      return record
    } catch (err) {
      svcLog.warn('[register-grill] Failed (non-critical):', err)
      return null
    }
  }

  // ── Audit plans ──

  registerAuditPlan(params: {
    workspaceId: string
    auditPlanId: string
    plan: AuditPlan
  }): PlanRecord | null {
    try {
      const existing = planRepository.findBySource('audit', params.auditPlanId)
      if (existing) {
        svcLog.info(`[register-audit] Skipped duplicate for plan=${params.auditPlanId}`)
        return existing
      }

      const structuredPlan = auditPlanToStructuredPlan(params.plan)

      const record = planRepository.savePlan({
        workspaceId: params.workspaceId,
        source: 'audit',
        sourceId: params.auditPlanId,
        title: params.plan.title || 'Untitled Audit Plan',
        summary: params.plan.summary || '',
        planType: 'audit',
        structuredPlan,
        sourcePlanJson: JSON.stringify(params.plan),
        requirementDocument: params.plan.requirementDocument || null
      })

      svcLog.info(
        `[register-audit] ✓ Plan registered: id=${record.id}, items=${params.plan.items.length}`
      )
      return record
    } catch (err) {
      svcLog.warn('[register-audit] Failed (non-critical):', err)
      return null
    }
  }

  // ── Council verdicts (registers the original plan with council link) ──

  registerCouncilVerdict(params: {
    workspaceId: string
    councilSessionId: string
    verdict: CouncilVerdict
    originalPlan: StructuredPlan
  }): PlanRecord | null {
    try {
      const existing = planRepository.findBySource('council', params.councilSessionId)
      if (existing) {
        svcLog.info(`[register-council] Skipped duplicate for session=${params.councilSessionId}`)
        return existing
      }

      const record = planRepository.savePlan({
        workspaceId: params.workspaceId,
        source: 'council',
        sourceId: params.councilSessionId,
        title: params.originalPlan.title || 'Council-Reviewed Plan',
        summary: params.verdict.sections.recommendation || params.originalPlan.summary || '',
        planType: params.originalPlan.type ?? null,
        structuredPlan: params.originalPlan,
        sourcePlanJson: JSON.stringify(params.verdict),
        linkedCouncilSessionId: params.councilSessionId
      })

      svcLog.info(
        `[register-council] ✓ Plan registered: id=${record.id}, score=${params.verdict.overallScore}`
      )
      return record
    } catch (err) {
      svcLog.warn('[register-council] Failed (non-critical):', err)
      return null
    }
  }
}

