/**
 * PromptOptimizerService — rewrites user chat prompts for clarity before dispatch.
 *
 * A cheap one-shot Haiku call makes the prompt more explicit and unambiguous while
 * preserving the user's core intent and language. The optimizer:
 *  - Skips short prompts (<80 chars), slash commands, disabled setting, local-LLM
 *  - Wraps the original in <original_prompt> tags to prevent injection
 *  - Parses a ```optimized-prompt fenced block or NO_CHANGES sentinel
 *  - Rejects oversize output (>max(4× original, 2000) chars)
 *  - Rejects keyword drift (<40% of original keywords preserved, with stemming)
 *  - Falls back to the original prompt on any error
 *
 * Follows the GoalDecomposerService singleton pattern.
 */

import log from 'electron-log'
import { runOneShotClaude, type OneShotClaudeOptions } from './one-shot-claude'
import { runOneShotLocal } from './one-shot-local'
import { modelConfigService, resolveAssignment, buildResolveOpts } from './model-config.service'
import { workspaceRepository } from '../db/repositories'
import { backgroundCliSession } from './background-cli-session'
import { usageTrackerService } from './usage-tracker.service'

const optimizerLog = log.scope('prompt-optimizer')

// ── Meta-prompt ──────────────────────────────────────────────────────────

const META_PROMPT = `You are a prompt optimizer. Your job is to rewrite a user's chat prompt so it is clearer, more actionable, and less ambiguous for a coding assistant — while preserving the user's core intent, language, and tone.

Rules:
- Make instructions explicit and unambiguous.
- Add structure (numbered steps, bullet points) only when it genuinely helps clarity.
- Preserve the user's terminology and phrasing where possible.
- Stay self-contained — don't reference prior conversation context you don't have.
- Never answer the prompt — only rewrite it.
- Never invent requirements, constraints, or technologies the user didn't mention.
- Keep the rewritten prompt roughly the same length as the original (±50%). Do NOT expand a short sentence into a detailed specification.
- Do NOT decompose a single request into numbered sub-tasks unless the original already lists multiple steps.
- Do NOT add examples, technologies, or file formats the user didn't mention.
- If the prompt is already clear and actionable, output the literal text NO_CHANGES.
- You MUST output ONLY a single fenced block with the optimized prompt, or the literal NO_CHANGES. No explanation, no commentary.

Output format (when changes are made):
\`\`\`optimized-prompt
<your rewritten prompt here>
\`\`\`

Or, if the prompt is already good:
NO_CHANGES`

const STOP_WORDS = new Set([
  'this', 'that', 'with', 'from', 'have', 'been', 'were', 'will',
  'would', 'could', 'should', 'their', 'there', 'about', 'which',
  'when', 'what', 'your', 'also', 'more', 'some', 'make', 'like',
  'them', 'then', 'than', 'each', 'into', 'only', 'very', 'just',
  'does', 'here', 'much', 'well', 'back', 'even', 'most', 'made',
  'after', 'those', 'these', 'other', 'being', 'over', 'such',
  'before', 'between', 'under', 'using', 'based', 'please',
  'ensure', 'include', 'following', 'currently',
])

// ── Result types ─────────────────────────────────────────────────────────

export interface PromptOptimizeResult {
  /** The text to dispatch — either optimized or original */
  optimizedText: string
  /** Whether the text was actually changed */
  changed: boolean
  /** If skipped or fell back, the reason */
  skippedReason?: string
  /** Human-readable error detail when skippedReason is 'error' */
  errorDetail?: string
}

// ── Service ──────────────────────────────────────────────────────────────

class PromptOptimizerService {
  /** Test seam — overrides the CLI runner when set. Defaults to undefined (uses runOneShotClaude). */
  _runner?: OneShotClaudeOptions['_runner']
  /** R6-B1: Test seam for the local LLM path — overrides runOneShotLocal when set. */
  _localRunner?: (opts: { systemPrompt: string; userMessage: string }) => Promise<{ text: string }>

  /**
   * Resolve the local model id for prompt optimization.
   * Only honors the assignment when it explicitly targets a local provider —
   * default assignments resolve to Claude models, which oMLX 404s on.
   */
  resolveLocalModel(
    workspaceId: string,
    localCfg: { localModel?: string }
  ): string {
    const assignment = resolveAssignment({
      action: 'prompt:optimize',
      ...buildResolveOpts(workspaceId)
    })
    return (assignment.provider === 'local-llm' && assignment.modelId)
      ? assignment.modelId
      : (localCfg.localModel ?? 'qwen3-coder')
  }

  /**
   * Check whether the optimizer should run for this prompt.
   * Returns null if the optimizer should proceed, or a skip reason string if not.
   * Call this BEFORE emitting a running card so guarded prompts produce no card.
   */
  checkGuards(params: {
    text: string
    workspaceId: string
  }): string | null {
    const { text, workspaceId } = params

    const settings = workspaceRepository.getSettings(workspaceId)
    if (settings.promptOptimizationEnabled === false) return 'disabled'

    // R6-B1: Removed local-llm guard — optimizer now runs via runOneShotLocal for local providers

    if (text.length < 80) return 'short'
    if (text.trimStart().startsWith('/')) return 'slash-command'
    // NOTE: Grill mode never reaches stream() — it uses GrillAgentService + grill.ipc.ts
    // (intent-router.ts routes grill prompts away from chat). No guard needed here.

    return null // guards pass — proceed with optimization
  }

  /**
   * Pre-warm the background CLI session for prompt optimization.
   * Call at app startup to eliminate cold-start latency on the first optimize() call.
   * If the user has a custom model override, the first optimize() call will
   * kill and respawn with the correct model (via setModel's change detection).
   */
  async warmup(): Promise<void> {
    backgroundCliSession.setSystemPrompt(META_PROMPT)
    backgroundCliSession.setModel('claude-haiku-4-5-20251001')
    await backgroundCliSession.warmup()
  }

  /**
   * Optimize a user prompt for clarity before dispatch.
   * Returns the original text unchanged when any guard triggers or on error.
   */
  async optimize(params: {
    text: string
    workspaceId: string
    conversationId: string
    mode: 'plan' | 'build'
  }): Promise<PromptOptimizeResult> {
    const { text, workspaceId, mode } = params

    // ── Guard check (also callable externally via checkGuards) ──
    const guardReason = this.checkGuards({ text, workspaceId })
    if (guardReason) {
      return { optimizedText: text, changed: false, skippedReason: guardReason }
    }

    const modeHint = mode === 'plan'
      ? 'The user is in Plan mode (thinking, planning, Q&A — no code execution).'
      : 'The user is in Build mode (code writing, execution, and tool use).'
    const wrappedPrompt = `<original_prompt>\n${text}\n</original_prompt>\n\n${modeHint}`

    // ── R6-B1: Local LLM path via runOneShotLocal ──
    const settings = workspaceRepository.getSettings(workspaceId)
    const provider = settings.llmProvider ?? 'claude'

    if (provider === 'local-llm') {
      return this.optimizeLocal({ text, workspaceId, wrappedPrompt })
    }

    // ── Claude path ──
    const model = modelConfigService.getModelById(workspaceId, 'prompt:optimize')
    try {
      let responseText: string

      if (this._runner) {
        // Test seam — bypass warm session, use one-shot path
        const { text: t } = await runOneShotClaude({
          feature: 'prompt_optimize',
          model,
          workspaceId,
          conversationId: params.conversationId,
          args: [
            '-p', wrappedPrompt,
            '--model', model,
            '--system-prompt', META_PROMPT,
            '--permission-mode', 'plan',
            '--max-turns', '1',
            '--tools', '',
            '--no-session-persistence'
          ],
          cli: { timeout: 60_000 },
          _runner: this._runner
        })
        responseText = t
      } else {
        // Warm session path — persistent interactive CLI process
        try {
          backgroundCliSession.setSystemPrompt(META_PROMPT)
          backgroundCliSession.setModel(model)
          const { text: t, usage } = await backgroundCliSession.run({
            userMessage: wrappedPrompt,
            timeoutMs: 45_000
          })
          responseText = t

          // Record usage (previously handled inside runOneShotClaude)
          usageTrackerService.recordUsage({
            feature: 'prompt_optimize',
            model,
            workspaceId,
            conversationId: params.conversationId,
            tokens: usage
          })
        } catch (warmErr) {
          optimizerLog.warn('[optimize] Warm session failed, falling back to one-shot:',
            (warmErr as Error).message)
          // Fallback: fresh one-shot `claude -p` call
          const { text: t } = await runOneShotClaude({
            feature: 'prompt_optimize',
            model,
            workspaceId,
            conversationId: params.conversationId,
            args: [
              '-p', wrappedPrompt,
              '--model', model,
              '--system-prompt', META_PROMPT,
              '--permission-mode', 'plan',
              '--max-turns', '1',
              '--tools', '',
              '--no-session-persistence'
            ],
            cli: { timeout: 60_000 }
          })
          responseText = t
        }
      }

      return this.parseResponse(responseText, text)
    } catch (err) {
      const rawMsg = err instanceof Error ? err.message : String(err)
      // Truncate "Command failed: claude -p <...500+ chars of system prompt...>" to something readable
      const msg = rawMsg.startsWith('Command failed:')
        ? rawMsg.slice(0, 120) + (rawMsg.length > 120 ? '…' : '')
        : rawMsg
      optimizerLog.warn('[optimize] Claude CLI call failed, using original:', rawMsg)
      return { optimizedText: text, changed: false, skippedReason: 'error', errorDetail: msg }
    }
  }

  // ── R6-B1: Local LLM optimization path ──────────────────────────────

  private async optimizeLocal(params: {
    text: string
    workspaceId: string
    wrappedPrompt: string
  }): Promise<PromptOptimizeResult> {
    const { text, workspaceId, wrappedPrompt } = params

    try {
      let responseText: string

      if (this._localRunner) {
        // Test seam
        const r = await this._localRunner({ systemPrompt: META_PROMPT, userMessage: wrappedPrompt })
        responseText = r.text
      } else {
        const ws = workspaceRepository.findById(workspaceId)
        const workspacePath = ws?.repoPath
        if (!workspacePath) {
          optimizerLog.warn('[optimize] No workspace path found, using original')
          return { optimizedText: text, changed: false, skippedReason: 'error', errorDetail: 'No workspace path found' }
        }

        const localCfg = modelConfigService.getLocalLLMConfig(workspacePath)
        const baseUrl = modelConfigService.getLocalBaseUrl(localCfg)
        const model = this.resolveLocalModel(workspaceId, localCfg)

        const result = await runOneShotLocal({
          systemPrompt: META_PROMPT,
          userMessage: wrappedPrompt,
          baseUrl,
          model,
          apiKey: localCfg.localApiKey,
          feature: 'prompt_optimize',
          workspaceId,
          maxTokens: Math.min(Math.max(Math.ceil(text.length / 2), 512), 4096),
          timeoutMs: 30_000
          // No claudeFallbackArgs — empty response → skippedReason: 'error' → original prompt used
        })

        responseText = result.text
      }

      if (!responseText) {
        optimizerLog.warn('[optimize] Empty local LLM response, using original')
        return { optimizedText: text, changed: false, skippedReason: 'error', errorDetail: 'Empty response from local LLM' }
      }

      // R6-B1: Strip <think>…</think> blocks from local model reasoning leakage
      responseText = this.stripThinkingBlocks(responseText)

      return this.parseResponse(responseText, text)
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err)
      optimizerLog.warn('[optimize] Local LLM call failed, using original:', msg)
      return { optimizedText: text, changed: false, skippedReason: 'error', errorDetail: msg }
    }
  }

  // ── Response parsing ─────────────────────────────────────────────────

  /** Strip <think>…</think> blocks that local reasoning models sometimes emit */
  private stripThinkingBlocks(text: string): string {
    return text.replace(/<think>[\s\S]*?<\/think>/g, '').trim()
  }

  /**
   * Basic suffix stripping — covers 80% of false positives from morphological
   * variations ("processing" → "process" matches "processed").
   */
  private stemWord(word: string): string {
    return word
      .replace(/(ation|tion|sion|ment|ness|ence|ance|ity|ous|ive|ing|ied|ies|ers|est|ful|less|able|ible)$/, '')
      .replace(/(ed|ly|er|al)$/, '')
  }

  /**
   * Extract significant words (≥4 chars, lowercased, stemmed, deduplicated) from text.
   * Filters out common English stop words, then applies basic stemming.
   */
  private extractKeywords(text: string): Set<string> {
    const words = text.toLowerCase().match(/[a-z]{4,}/g) ?? []
    return new Set(
      words
        .filter(w => !STOP_WORDS.has(w))
        .map(w => this.stemWord(w))
        .filter(w => w.length >= 3)
    )
  }

  /**
   * Check that the optimized prompt preserves ≥40% of the original's keywords.
   * Returns the preservation ratio (0–1).
   */
  private keywordPreservation(original: string, optimized: string): number {
    const origKeywords = this.extractKeywords(original)
    if (origKeywords.size < 3) return 1 // too few keywords to judge
    const optKeywords = this.extractKeywords(optimized)
    let preserved = 0
    for (const kw of origKeywords) {
      if (optKeywords.has(kw)) preserved++
    }
    return preserved / origKeywords.size
  }

  private parseResponse(response: string, original: string): PromptOptimizeResult {
    const trimmed = response.trim()

    // NO_CHANGES sentinel — exact match or starts-with (model may append whitespace)
    if (trimmed === 'NO_CHANGES' || trimmed.startsWith('NO_CHANGES')) {
      return { optimizedText: original, changed: false }
    }

    // Parse fenced block: prefer ```optimized-prompt ... ```, fallback to a single generic ``` fence
    let fenceMatch = trimmed.match(/```optimized-prompt\s*\n([\s\S]*?)```/)
    if (!fenceMatch || fenceMatch[1] === undefined) {
      // Fallback: accept a single generic fenced block (any or no info string)
      // — local models (qwen, llama) often emit plain ``` fences instead of the requested tag
      const genericFences = [...trimmed.matchAll(/```[^\n]*\n([\s\S]*?)```/g)]
      if (genericFences.length === 1 && genericFences[0][1] !== undefined) {
        fenceMatch = genericFences[0]
        optimizerLog.info('[optimize] Accepted single generic fence block (local-model fallback)')
      } else {
        optimizerLog.warn('[optimize] Failed to parse fenced block, using original')
        return { optimizedText: original, changed: false, skippedReason: 'parse-error' }
      }
    }

    const optimized = fenceMatch[1].trim()

    // Guard: empty
    if (!optimized) {
      optimizerLog.warn('[optimize] Empty optimized prompt, using original')
      return { optimizedText: original, changed: false, skippedReason: 'empty-output' }
    }

    // Guard: oversize — reject output > max(4× original, 2000 chars)
    // Floor of 2000 lets short prompts (~250 chars) expand into structured rewrites.
    // The 4× ratio is the proportional safety net at every scale.
    const maxLen = Math.max(original.length * 4, 2000)
    if (optimized.length > maxLen) {
      optimizerLog.warn(
        `[optimize] Oversize output (${optimized.length} > ${maxLen}), using original`
      )
      return { optimizedText: original, changed: false, skippedReason: 'oversize' }
    }

    // Guard: keyword drift — reject if <40% of original keywords survive (with stemming)
    const preservation = this.keywordPreservation(original, optimized)
    if (preservation < 0.4) {
      optimizerLog.warn(
        `[optimize] Keyword drift (${(preservation * 100).toFixed(0)}% preserved), using original`
      )
      return { optimizedText: original, changed: false, skippedReason: 'keyword-drift' }
    }

    // Guard: no actual change
    if (optimized === original) {
      return { optimizedText: original, changed: false }
    }

    return { optimizedText: optimized, changed: true }
  }
}

export const promptOptimizerService = new PromptOptimizerService()

/**
 * BackgroundCliSession — persistent interactive Claude CLI process for lightweight
 * one-shot tasks (prompt optimization).
 *
 * Instead of spawning a fresh `claude -p` process per call (~3-5s overhead), this
 * keeps a warm interactive process alive and sends user messages via NDJSON stdin.
 * Before each new call, `/clear` resets the conversation context while preserving
 * the system prompt.
 *
 * Key design:
 *  - Scoped to the prompt optimizer's META_PROMPT (system prompt locked at spawn)
 *  - Promise-based mutex serializes concurrent callers
 *  - 5-minute idle timeout kills the process; respawns on next demand
 *  - Per-call 15s default timeout
 *  - Process crash → marks dead → next call respawns
 */

import { spawn, type ChildProcess } from 'node:child_process'
import log from 'electron-log'
import { writeFileSync, unlinkSync, mkdirSync } from 'node:fs'
import { join } from 'node:path'
import { tmpdir } from 'node:os'
import { randomUUID } from 'node:crypto'
import { parseNdjsonStream, writeNdjsonMessage, buildUserMessage } from './cli-executor/ndjson-parser'
import type { OneShotUsage } from './one-shot-claude'
import { buildEnvWithPath } from './env-utils'

const sessionLog = log.scope('bg-cli-session')

const IDLE_TIMEOUT_MS = 5 * 60 * 1000 // 5 minutes
const DEFAULT_CALL_TIMEOUT_MS = 45_000 // 45 seconds — first call after spawn needs time for cold API cache

export interface BackgroundCliRunResult {
  text: string
  usage: OneShotUsage
}

type Spawner = (args: string[], opts: { stdio: string[]; env: NodeJS.ProcessEnv }) => ChildProcess

/**
 * Race a promise against a timeout, returning a cleanup function for the timer.
 * Prevents unhandled rejections from dangling timeout promises.
 */
function raceWithTimeout<T>(
  promise: Promise<T>,
  timeoutMs: number,
  message: string
): { result: Promise<T>; cancel: () => void } {
  let timer: ReturnType<typeof setTimeout> | null = null

  const timeoutPromise = new Promise<never>((_, reject) => {
    timer = setTimeout(() => reject(new Error(message)), timeoutMs)
    if (timer.unref) timer.unref()
  })

  return {
    result: Promise.race([promise, timeoutPromise]),
    cancel: () => {
      if (timer) clearTimeout(timer)
      // Swallow the timeout promise to prevent unhandled rejection
      timeoutPromise.catch(() => {})
    }
  }
}

/**
 * Reads NDJSON events from the iterator until a `result` event is found.
 * Returns the result text and usage. Ignores all other event types.
 */
async function readOneShotResult(
  iterator: AsyncGenerator<Record<string, unknown>>,
  timeoutMs: number
): Promise<BackgroundCliRunResult> {
  const deadline = Date.now() + timeoutMs
  let text = ''
  let usage: OneShotUsage = { input: 0, output: 0, cacheRead: 0, cacheCreation: 0 }

  while (true) {
    const remaining = deadline - Date.now()
    if (remaining <= 0) {
      throw new Error(`Background CLI session timed out after ${timeoutMs}ms`)
    }

    const race = raceWithTimeout(
      iterator.next(),
      remaining,
      `Background CLI session timed out after ${timeoutMs}ms`
    )

    let iterResult: IteratorResult<Record<string, unknown>>
    try {
      iterResult = await race.result
    } finally {
      race.cancel()
    }

    if (iterResult.done) {
      throw new Error('Background CLI stream ended before result event')
    }

    const event = iterResult.value
    const type = event.type as string | undefined

    if (type === 'result') {
      const resultText = typeof event.result === 'string'
        ? event.result
        : ''
      const usageObj = (event.usage ?? {}) as Record<string, unknown>
      const num = (v: unknown): number => (typeof v === 'number' && Number.isFinite(v) ? v : 0)
      usage = {
        input: num(usageObj.input_tokens),
        output: num(usageObj.output_tokens),
        cacheRead: num(usageObj.cache_read_input_tokens),
        cacheCreation: num(usageObj.cache_creation_input_tokens)
      }
      text = resultText
      break
    }
  }

  return { text, usage }
}

export class BackgroundCliSession {
  private process: ChildProcess | null = null
  private ndjsonIterator: AsyncGenerator<Record<string, unknown>> | null = null
  private alive = false
  private idleTimer: ReturnType<typeof setTimeout> | null = null
  private systemPromptFile: string | null = null
  private mutexTail: Promise<void> = Promise.resolve()
  private needsClear = false
  private model: string = 'claude-haiku-4-5-20251001'
  private stderrBuffer = ''

  /** Test seam — overrides spawn('claude', ...) for tests */
  _spawner?: Spawner

  /** System prompt to use for spawning (set externally) */
  private systemPrompt: string = ''

  /**
   * Configure the system prompt for this session.
   * Must be called before the first `run()` call.
   */
  setSystemPrompt(prompt: string): void {
    if (this.systemPrompt !== prompt) {
      this.systemPrompt = prompt
      // If the prompt changed and we have a warm process, kill it
      // so the next call spawns with the new prompt.
      if (this.alive) {
        sessionLog.info('[bg-cli] System prompt changed — disposing warm process')
        this.killProcess()
      }
    }
  }

  /**
   * Configure the model for this session.
   * If the model changes while a process is alive, the process is killed
   * so the next call spawns with the new model.
   */
  setModel(model: string): void {
    if (this.model !== model) {
      this.model = model
      if (this.alive) {
        sessionLog.info('[bg-cli] Model changed — disposing warm process')
        this.killProcess()
      }
    }
  }

  /**
   * Send a user message to the warm CLI session and return the response.
   * Serializes concurrent callers via mutex.
   */
  async run(params: {
    userMessage: string
    timeoutMs?: number
  }): Promise<BackgroundCliRunResult> {
    const { userMessage, timeoutMs = DEFAULT_CALL_TIMEOUT_MS } = params

    // Mutex: serialize concurrent callers
    const release = this.acquireMutex()
    try {
      await release.acquired
      return await this.runInner(userMessage, timeoutMs)
    } finally {
      release.release()
    }
  }

  /**
   * Kill the warm process and clean up resources.
   * Safe to call multiple times.
   *
   * Intentionally lockless — does NOT acquire the mutex. If a `run()` is
   * in-flight, killing the process causes `readOneShotResult()` to throw
   * a stream-closed error, which `runInner()` catches and rethrows.
   * The caller (prompt optimizer) then falls back to the original prompt.
   */
  dispose(): void {
    this.clearIdleTimer()
    this.killProcess()
    sessionLog.info('[bg-cli] Session disposed')
  }

  /** Check if the process is alive */
  get isAlive(): boolean {
    return this.alive && this.process !== null && !this.process.killed
  }

  /**
   * Pre-spawn the CLI process so the first run() call avoids cold start.
   * Requires systemPrompt to be set via setSystemPrompt() beforehand.
   * Serialized via mutex — safe to call concurrently with run().
   * Errors are caught and logged (non-fatal).
   */
  async warmup(): Promise<void> {
    if (this.isAlive) return // already warm
    if (!this.systemPrompt) {
      sessionLog.info('[bg-cli] warmup skipped — no system prompt configured')
      return
    }

    const release = this.acquireMutex()
    try {
      await release.acquired
      if (this.isAlive) return // re-check under mutex (another caller may have spawned)
      sessionLog.info('[bg-cli] Warming up CLI process...')
      await this.spawnProcess()
      this.resetIdleTimer()
      sessionLog.info('[bg-cli] Warmup complete — process ready')
    } catch (err) {
      sessionLog.warn('[bg-cli] Warmup failed (non-fatal):', (err as Error).message)
      this.killProcess() // Clean up half-initialized state
    } finally {
      release.release()
    }
  }

  // ── Private implementation ──

  private acquireMutex(): { acquired: Promise<void>; release: () => void } {
    const acquired = new Promise<void>((resolve) => {
      // Chain onto the tail: our turn starts when the previous finishes
      this.mutexTail = this.mutexTail.then(() => resolve())
    })
    let resolveRelease: () => void
    const releasePromise = new Promise<void>((resolve) => {
      resolveRelease = resolve
    })
    // Extend the tail: the NEXT caller's turn starts when we release
    this.mutexTail = releasePromise

    return {
      acquired,
      release: () => resolveRelease!()
    }
  }

  private async runInner(userMessage: string, timeoutMs: number): Promise<BackgroundCliRunResult> {
    this.resetIdleTimer()

    // Ensure process is alive
    if (!this.isAlive) {
      await this.spawnProcess()
    }

    if (!this.process?.stdin || !this.ndjsonIterator) {
      throw new Error('Background CLI session: process or iterator not available')
    }

    // Clear stale context from the previous call before sending the new message.
    // Sending /clear HERE (start of next run) instead of at the end of the
    // previous run avoids the stale-event poisoning problem: the /clear response
    // events are drained before the user message is sent.
    if (this.needsClear) {
      this.sendClear()
      await this.drainClearResponse()
      this.needsClear = false
    }

    // Write user message to stdin as NDJSON
    const msg = buildUserMessage(userMessage)
    const written = writeNdjsonMessage(this.process.stdin, msg)
    if (!written) {
      sessionLog.warn('[bg-cli] stdin backpressure on write — continuing anyway')
    }

    try {
      // Read NDJSON events until result
      const result = await readOneShotResult(this.ndjsonIterator, timeoutMs)

      // Mark that the next call needs to clear context first
      this.needsClear = true

      return result
    } catch (err) {
      // On any error (timeout, stream closed), kill the process
      // so the next call gets a fresh one
      sessionLog.warn(`[bg-cli] Error during run, killing process: ${(err as Error).message}`)
      this.killProcess()
      throw err
    }
  }

  private async spawnProcess(): Promise<void> {
    // Clean up any previous state
    this.killProcess()

    // Write system prompt to temp file
    this.systemPromptFile = this.writeSystemPromptFile(this.systemPrompt)

    const args = [
      '--output-format', 'stream-json',
      '--input-format', 'stream-json',
      '--system-prompt-file', this.systemPromptFile,
      '--model', this.model,
      '--permission-mode', 'plan',
      '--verbose',
      '--tools', ''
    ]

    sessionLog.info(`[bg-cli] Spawning warm process: claude ${args.join(' ')}`)

    const env = buildEnvWithPath()

    try {
      if (this._spawner) {
        this.process = this._spawner(args, { stdio: ['pipe', 'pipe', 'pipe'], env })
      } else {
        this.process = spawn('claude', args, {
          stdio: ['pipe', 'pipe', 'pipe'],
          env,
          detached: false
        })
      }
    } catch (err) {
      this.process = null
      this.cleanupSystemPromptFile()
      throw new Error(`Failed to spawn background claude CLI: ${(err as Error).message}`)
    }

    this.alive = true

    // Wire exit handler
    this.process.on('exit', (code, signal) => {
      sessionLog.info(`[bg-cli] Process exited: code=${code}, signal=${signal}`)
      this.alive = false
      this.process = null
      this.ndjsonIterator = null
      this.cleanupSystemPromptFile()
    })

    // Wire stderr logging + buffering for diagnostics
    if (this.process.stderr) {
      this.process.stderr.on('data', (chunk: Buffer) => {
        const text = chunk.toString('utf-8').trim()
        if (text) {
          sessionLog.warn(`[bg-cli:stderr] ${text}`)
          this.stderrBuffer += text + '\n'
        }
      })
    }

    // Create NDJSON iterator from stdout
    if (!this.process.stdout) {
      throw new Error('Background CLI session: no stdout stream')
    }

    this.ndjsonIterator = parseNdjsonStream(this.process.stdout, sessionLog)

    // Wait for the system/init event to confirm the session is ready
    await this.waitForInit()
  }

  /**
   * Wait for the `system` init event from the CLI.
   * The CLI emits a `{"type":"system","subtype":"init",...}` event when ready.
   */
  private async waitForInit(): Promise<void> {
    if (!this.ndjsonIterator) return

    const INIT_TIMEOUT_MS = 30_000 // 30s for initial spawn + bootstrap
    const deadline = Date.now() + INIT_TIMEOUT_MS

    while (true) {
      const remaining = deadline - Date.now()
      if (remaining <= 0) {
        throw new Error('Background CLI session: init timeout (30s)')
      }

      const race = raceWithTimeout(
        this.ndjsonIterator.next(),
        remaining,
        'Background CLI session: init timeout (30s)'
      )

      let iterResult: IteratorResult<Record<string, unknown>>
      try {
        iterResult = await race.result
      } finally {
        race.cancel()
      }

      if (iterResult.done) {
        const detail = this.stderrBuffer.trim()
        throw new Error(
          'Background CLI session: stream ended during init' +
          (detail ? ` — stderr: ${detail.slice(0, 500)}` : '')
        )
      }

      const event = iterResult.value
      if (event.type === 'system' && event.subtype === 'init') {
        const sessionId = event.session_id ?? event.sessionId ?? 'unknown'
        sessionLog.info(`[bg-cli] Session initialized: ${sessionId}`)
        return
      }

      // Log and skip unexpected pre-init events
      sessionLog.info(`[bg-cli] Pre-init event: type=${event.type}`)
    }
  }

  /**
   * Send /clear as raw text to reset conversation context.
   * Slash commands must be sent as raw `"/clear\n"`, NOT wrapped in NDJSON —
   * the CLI auto-detects raw text vs NDJSON per-line when `--input-format stream-json`
   * is active. Wrapping in NDJSON would send "/clear" as a regular user prompt.
   */
  private sendClear(): void {
    if (!this.process?.stdin || !this.alive) return
    try {
      this.process.stdin.write('/clear\n')
    } catch {
      // Pipe may already be closed
    }
    sessionLog.info('[bg-cli] Sent /clear to reset context')
  }

  /**
   * Drain events emitted by `/clear` so they don't poison the next `readOneShotResult()`.
   * Reads until a `result` event is found or the timeout expires.
   */
  private async drainClearResponse(timeoutMs: number = 5000): Promise<void> {
    if (!this.ndjsonIterator) return
    const deadline = Date.now() + timeoutMs
    while (true) {
      const remaining = deadline - Date.now()
      if (remaining <= 0) {
        sessionLog.info('[bg-cli] Drain timeout — continuing')
        return
      }
      const race = raceWithTimeout(
        this.ndjsonIterator.next(),
        remaining,
        'drain timeout'
      )
      try {
        const iterResult = await race.result
        if (iterResult.done) return
        const event = iterResult.value
        if ((event.type as string) === 'result') {
          sessionLog.info('[bg-cli] Drained /clear result event')
          return
        }
        // Skip non-result events (assistant messages, content blocks, etc.)
      } catch {
        // Timeout — no more events pending, safe to continue
        return
      } finally {
        race.cancel()
      }
    }
  }

  private killProcess(): void {
    this.alive = false
    this.ndjsonIterator = null
    this.needsClear = false
    this.stderrBuffer = ''

    if (this.process) {
      try {
        this.process.kill('SIGTERM')
      } catch {
        // Process may have already exited
      }
      this.process = null
    }

    this.cleanupSystemPromptFile()
  }

  private resetIdleTimer(): void {
    this.clearIdleTimer()
    this.idleTimer = setTimeout(() => {
      sessionLog.info('[bg-cli] Idle timeout reached — killing warm process')
      this.killProcess()
    }, IDLE_TIMEOUT_MS)
    // Don't keep Node alive just for the idle timer
    if (this.idleTimer.unref) this.idleTimer.unref()
  }

  private clearIdleTimer(): void {
    if (this.idleTimer) {
      clearTimeout(this.idleTimer)
      this.idleTimer = null
    }
  }

  private writeSystemPromptFile(prompt: string): string {
    const dir = join(tmpdir(), 'agentstudio-bg-cli')
    mkdirSync(dir, { recursive: true })
    const filePath = join(dir, `system-prompt-${randomUUID()}.txt`)
    writeFileSync(filePath, prompt, 'utf-8')
    return filePath
  }

  private cleanupSystemPromptFile(): void {
    if (this.systemPromptFile) {
      try {
        unlinkSync(this.systemPromptFile)
      } catch {
        // File may have already been deleted
      }
      this.systemPromptFile = null
    }
  }
}

export const backgroundCliSession = new BackgroundCliSession()

/**
 * OpenCode CLI Path Utilities
 * 
 * NOTE: This is MAIN PROCESS ONLY. While located in shared/,
 * the functions that use child_process (spawn, execSync) cannot
 * be used from the renderer process.
 * 
 * Use this for:
 * - PATH augmentation early in index.ts
 * - Locating binaries for child_process.spawn
 * 
 * Do NOT import in renderer or preload scripts.
 */

import { execSync, spawnSync } from 'node:child_process'
import { existsSync } from 'node:fs'
import { join, dirname } from 'node:path'

// Module-level cache - resolved once at startup
let cachedOpencodePath: string | null = null
let cachedOpencodeDir: string | null = null

export interface OpenCodeCliCheckResult {
  /** Whether the OpenCode CLI is installed and available */
  available: boolean
  /** Absolute path to the CLI binary (if found) */
  path?: string
  /** CLI version output (if retrieved) */
  version?: string
  /** Human-readable error message (if not available) */
  error?: string
  /** How the path was located (direct, exists, which, etc) */
  source?: string
}

/**
 * Resolve opencode path using npm config detection.
 * This is more robust than hardcoded paths because it uses npm's actual
 * configuration to determine where global packages are installed.
 * 
 * Cached after first resolution - try once, keep result.
 */
export function resolveOpencodePath(): string | null {
  if (cachedOpencodePath) {
    return cachedOpencodePath
  }

  // Method 1: Try 'which opencode' first (fastest, relies on system PATH)
  try {
    const whichResult = spawnSync('which', ['opencode'], {
      encoding: 'utf-8',
      timeout: 5000,
    })

    if (whichResult.stdout?.trim()) {
      const path = whichResult.stdout.trim()
      cachedOpencodePath = path
      cachedOpencodeDir = dirname(path)
      return path
    }
  } catch {
    // Continue to fallback
  }

  // Method 2: Use npm config to get prefix (most robust)
  try {
    const npmPrefixResult = spawnSync('npm', ['config', 'get', 'prefix'], {
      encoding: 'utf-8',
      timeout: 5000,
    })

    if (npmPrefixResult.stdout?.trim()) {
      const npmPrefix = npmPrefixResult.stdout.trim()
      const candidate = join(npmPrefix, 'bin', 'opencode')

      if (existsSync(candidate)) {
        cachedOpencodePath = candidate
        cachedOpencodeDir = dirname(candidate)
        return candidate
      }
    }
  } catch {
    // npm command failed
  }

  return null
}

/**
 * Get the cached opencode path (null if not yet resolved)
 */
export function getOpencodePath(): string | null {
  return cachedOpencodePath
}

/**
 * Get the cached opencode directory (null if not yet resolved)
 */
export function getOpencodeDir(): string | null {
  return cachedOpencodeDir
}

/**
 * Ensure opencode directory is in PATH
 * Returns true if path was added, false if already present
 */
export function ensureOpencodePathInEnv(): boolean {
  if (!cachedOpencodeDir) {
    resolveOpencodePath()
  }

  if (cachedOpencodeDir) {
    const currentPath = process.env.PATH || ''
    if (!currentPath.includes(cachedOpencodeDir)) {
      process.env.PATH = `${cachedOpencodeDir}:${currentPath}`
      return true
    }
  }
  return false
}

/**
 * Augment process.env.PATH with Homebrew and npm global bin directories.
 * Must be called early in Electron main process to ensure child_process.spawn()
 * can locate binaries like 'opencode'.
 */
export function augmentOpenCodeCliPath(): void {
  const HOME = process.env.HOME || ''

  const CLI_PATHS = {
    darwin: [
      '/opt/homebrew/bin',                    // Apple Silicon Homebrew
      '/usr/local/bin',                       // Intel Mac Homebrew
      join(HOME, '.npm-global', 'bin'),       // npm global on macOS
    ],
    win32: [
      join(HOME, 'AppData', 'Roaming', 'npm'),  // Windows npm global
    ],
    linux: [
      '/snap/bin',                             // Snap packages
      '/usr/local/bin',                        // System-wide
      join(HOME, '.local', 'bin'),             // ~/.local (pip, cargo, etc.)
      join(HOME, '.npm-global', 'bin'),        // npm global on Linux
    ],
  }

  const paths = CLI_PATHS[process.platform as keyof typeof CLI_PATHS] || []

  for (const binPath of paths) {
    // Avoid duplicate entries in PATH
    if (binPath && !process.env.PATH?.includes(binPath)) {
      process.env.PATH = `${binPath}${process.env.PATH ? ':' + process.env.PATH : ''}`
    }
  }
}

/**
 * Locate the OpenCode CLI binary by using npm config detection.
 * @returns Result indicating availability, path, and/or error message
 */
export async function locateOpenCodeCli(): Promise<OpenCodeCliCheckResult> {
  // Use the new resolution method that uses npm config
  const opencodePath = resolveOpencodePath()

  if (opencodePath) {
    // Try to get version (confirms it's executable)
    try {
      const version = execSync('opencode --version', { timeout: 5000, encoding: 'utf-8' }).trim()
      return {
        available: true,
        path: opencodePath,
        version,
        source: cachedOpencodeDir ? 'resolved' : 'direct',
      }
    } catch {
      // File exists but may not be executable
      return {
        available: true,
        path: opencodePath,
        source: 'exists',
        error: 'exists but not executable',
      }
    }
  }

  return {
    available: false,
    error:
      'OpenCode CLI not found. Install it by running:\n' +
      '  npm install -g @opencode-ai/cli\n' +
      'Or download from: https://opencode.ai/getting-started',
  }
}

/**
 * Synchronous check for CLI availability (quick, no version fetch).
 * Useful for early bootstrap where async isn't available.
 */
export function checkOpenCodeCliSync(): { available: boolean; path?: string; error?: string } {
  // Use the new resolution method that uses npm config
  const opencodePath = resolveOpencodePath()

  if (opencodePath) {
    // Quick test - verify executable
    const result = spawnSync(opencodePath, ['--version'], { timeout: 3000, stdio: 'pipe' })
    if (!result.error) {
      // Also ensure path is in PATH
      ensureOpencodePathInEnv()
      return { available: true, path: opencodePath }
    }
  }

  return {
    available: false,
    error: 'OpenCode CLI not found in PATH',
  }
}

/**
 * OpenCode Config Writer — generates opencode.json for workspace sessions.
 *
 * When using the OpenCode executor backend, this module generates the
 * opencode.json configuration file that OpenCode reads for:
 *   - Provider selection (Claude, Ollama, oMLX, OpenAI, etc.)
 *   - MCP server connections (same servers as CLI backend)
 *   - Plugin loading (.opencode/plugins/code-atelier.ts)
 *   - Tool permissions and shell settings
 *
 * The generated config is placed in the workspace root (OpenCode reads
 * from the cwd). It reuses the same McpConfigWriter logic to determine
 * which servers to mount based on workspace feature flags.
 *
 * Phase 4B — OpenCode Evaluation: MCP server wiring.
 */

import { writeFileSync, existsSync, mkdirSync, unlinkSync } from 'node:fs'
import { join } from 'node:path'
import { tmpdir } from 'node:os'
import { app } from 'electron'
import log from 'electron-log/main'
import type { ConversationMode } from '../../shared/types'
import type { ContextWindowTier } from './context-management'
import type { OpenCodeProviderConfig } from './opencode-executor'
import { EXTERNAL_MCP_INTEGRATIONS } from '../../shared/constants'
import {
  LOCAL_MCP_SERVER_DEFS,
  FORMATTER_DEFS,
  buildLocalMcpServersFromRegistry
} from './opencode-config-writer/opencode-config-data'
import { appPreferenceRepository } from '../db/repositories/app-preference.repository'

const configLog = log.scope('OpenCodeConfigWriter')

// ── Types ──

/**
 * OpenCode config file structure — comprehensive coverage of all OpenCode fields.
 * Reference: https://opencode.ai/docs/config/
 */
interface OpenCodeConfig {
  $schema: string
  model: string
  /** Lightweight model for housekeeping tasks (title generation, summarization) */
  small_model?: string
  /** Default agent to use (name from .opencode/agents/) */
  default_agent?: string
  provider: Record<
    string,
    {
      /** npm package for custom providers (e.g. '@ai-sdk/openai-compatible') */
      npm?: string
      /** Provider options — per OpenCode schema, all config goes here */
      options?: {
        baseURL?: string
        apiKey?: string
        /** Request timeout in ms — cloud: 300000, local: 600000 */
        timeout?: number
        /** Chunk timeout in ms — detects stalled streams */
        chunkTimeout?: number
        /** C-1: Ensure prompt cache keys are always set (Anthropic) — up to 90% cost reduction */
        setCacheKey?: boolean
      }
      /** C-5: Per-model overrides — context/output limits + capabilities */
      models?: Record<
        string,
        {
          name?: string
          limit?: { context: number; output: number }
          /** Capability flags — required for custom models not in models.dev */
          tool_call?: boolean
          attachment?: boolean
          reasoning?: boolean
          /** Input/output modalities — required for OpenCode to send images to VLMs */
          modalities?: {
            input: string[]
            output: string[]
          }
        }
      >
    }
  >
  mcp: Record<
    string,
    {
      type: 'local' | 'remote'
      command?: string[]
      /** GAP-22: OpenCode uses `environment` (not `env`) per MCP docs */
      environment?: Record<string, string>
      /** 6D-1: Per-server request timeout in ms */
      timeout?: number
      /** 6D-2: Explicitly disable a server without deleting its config */
      enabled?: boolean
      /** GAP-8: Remote MCP server URL */
      url?: string
      /** GAP-8: Remote MCP server headers (auth tokens, API keys) */
      headers?: Record<string, string>
      /** GAP-8: Remote MCP OAuth configuration */
      oauth?: {
        client_id: string
        authorization_url: string
        token_url: string
        scope?: string
      }
    }
  >
  plugin: string[]
  instructions: string[]
  tools: Record<string, unknown>
  /** Glob-based permission patterns per tool (e.g. { Bash: { '*': 'ask', 'git status *': 'allow' } }) */
  permission: Record<string, string | Record<string, string>>
  compaction: {
    enabled: boolean
    /** Auto-compact when context window is full */
    auto?: boolean
    /** Remove old tool outputs before summarizing */
    prune?: boolean
    /** Token buffer reserved for safety headroom */
    reserved?: number
  }
  snapshot: boolean
  /** Automatic code formatting after file edits */
  formatter?: {
    enabled: boolean
    /** B-6: Explicit formatter command (e.g. ["npx", "prettier", "--write"]) */
    command?: string[]
    /** B-6: File extensions to format */
    extensions?: string[]
  }
  /** LSP integration for compiler diagnostics */
  lsp?: {
    enabled: boolean
    /** Disable for specific languages */
    disabled?: string[]
  }
  /** Image attachment configuration */
  attachment?: {
    image?: {
      auto_resize?: boolean
      max_width?: number
      max_height?: number
      max_base64_bytes?: number
    }
  }
  /** File watcher configuration */
  watcher?: {
    enabled: boolean
    /** Glob patterns to ignore from file watching */
    ignore?: string[]
  }
  /** C-6/A-3: Shell path — OpenCode ≤1.17.x expects a string, not an object */
  shell?: string
  /** Server configuration — CORS origins, mDNS, etc. */
  server?: {
    cors?: string[]
    mdns?: boolean
  }
  /** Session sharing mode */
  share?: 'manual' | 'auto' | 'disabled'
  /** C-4: Control automatic updates — we manage SDK version via package.json */
  autoupdate?: boolean | 'notify'
  /** C-2: Allowlist for provider loading */
  enabled_providers?: string[]
  /** C-2: Denylist for provider loading */
  disabled_providers?: string[]
  /** GAP-19: Experimental features */
  experimental?: {
    /** Enable background subagents (v1.14.51+) — tasks continue while agent works */
    backgroundSubagents?: boolean
  }
}

export interface OpenCodeConfigWriterOptions {
  workspacePath: string
  workspaceId: string | null
  conversationId: string | null
  mode: ConversationMode
  provider: OpenCodeProviderConfig
  featureFlags: {
    repomapEnabled: boolean
    semanticSearchEnabled: boolean
    githubConfigured: boolean
    localMcpActive: Record<string, boolean>
    /** External MCPs active for this chat (e.g. { maestro: true }) */
    externalMcpActive?: Record<string, boolean>
  }
  contextTier?: ContextWindowTier
  /** Whether the context window was resolved from a confident source (user override or backend API).
   *  When false/undefined, OpenCode resolves limits via its own models.dev registry. */
  contextWindowConfident?: boolean
  /** IPC socket path for control-actions server */
  ipcSocketPath?: string
  /** Enable LSP diagnostics integration */
  lspEnabled?: boolean
  /** Enable automatic code formatting after agent edits */
  formatterEnabled?: boolean
  /** Whether the provider is a local LLM (Ollama/oMLX) — drives timeout selection */
  isLocalProvider?: boolean
  /** D-1: System prompt for injection via experimental.chat.system.transform hook */
  systemPrompt?: string
  /** E-9: Enable web search/fetch tools (requires Exa AI or equivalent) */
  webSearchEnabled?: boolean
  /** GAP-8: Remote MCP server configurations from workspace settings */
  remoteMcpServers?: Record<
    string,
    {
      url: string
      headers?: Record<string, string>
      oauth?: {
        client_id: string
        authorization_url: string
        token_url: string
        scope?: string
      }
      enabled?: boolean
    }
  >
}

// ── Writer ──

export class OpenCodeConfigWriter {
  /**
   * Generate an opencode.json config for the workspace.
   * Returns the path to the generated config file.
   */
  writeConfig(opts: OpenCodeConfigWriterOptions): string {
    const config = this.buildConfig(opts)

    // Write to a temp directory to avoid polluting the workspace with
    // untracked files that would show in `git status` and potentially
    // get committed accidentally.
    const tempDir = join(
      tmpdir(),
      'code-atelier-opencode',
      Buffer.from(opts.workspacePath).toString('base64url').slice(0, 32)
    )
    if (!existsSync(tempDir)) {
      // OC-02: Restrict permissions — config may contain plaintext API keys
      mkdirSync(tempDir, { recursive: true, mode: 0o700 })
    }
    const configPath = join(tempDir, 'opencode.json')

    // OC-02: Owner-only read/write — prevents other users from reading API keys
    writeFileSync(configPath, JSON.stringify(config, null, 2), { encoding: 'utf-8', mode: 0o600 })
    configLog.info(
      `[opencode-config] Wrote: ${configPath} (${Object.keys(config.mcp).length} MCP servers)`
    )

    // Store the config path for cleanup
    this.configPaths.set(opts.workspacePath, configPath)

    return configPath
  }

  /** Track generated config paths for cleanup */
  private readonly configPaths = new Map<string, string>()

  /**
   * Get the config path for a workspace.
   */
  getConfigPath(workspacePath: string): string | undefined {
    return this.configPaths.get(workspacePath)
  }

  /**
   * Clean up the generated config file.
   */
  dispose(workspacePath: string): void {
    const configPath = this.configPaths.get(workspacePath)
    if (!configPath) return

    try {
      unlinkSync(configPath)
      this.configPaths.delete(workspacePath)
    } catch {
      /* non-fatal — file may not exist */
    }
  }

  // ── Private ──

  private buildConfig(opts: OpenCodeConfigWriterOptions): OpenCodeConfig {
    const { provider, workspacePath, contextTier, contextWindowConfident } = opts
    const isLocal = opts.isLocalProvider ?? false

    // Resolve the model string in OpenCode format: provider/model
    const modelString = `${provider.providerId}/${provider.modelId}`

    // ── #5: Small model for housekeeping (title gen, summarization) ──
    const smallModel = this.resolveSmallModel(provider.providerId)

    // Build provider config with timeouts (#15)
    const providers = this.buildProviderConfig(provider, isLocal, contextTier, contextWindowConfident)

    // Build MCP server config
    const mcp = this.buildMcpServers(opts)

    // Resolve plugin path
    const pluginDir = join(workspacePath, '.opencode', 'plugins')
    const plugins: string[] = []
    if (existsSync(join(pluginDir, 'code-atelier.ts'))) {
      plugins.push('.opencode/plugins/code-atelier.ts')
    }

    // C-7: Build instructions from workspace instruction files.
    const instructions = this.buildInstructions(workspacePath)

    // ── #19: Glob-based permissions for plan mode ──
    const permission = this.buildPermissions(opts.mode)

    // ── #7: Tier-aware compaction config ──
    const compaction = this.buildCompactionConfig(contextTier)

    // ── #8: Shell environment injection ──
    // OpenCode ≤1.17.x doesn't support shell.env objects — inject env vars
    // into process.env so the OpenCode server (and its Bash tool calls) inherit them.
    const shellEnv = this.buildShellEnvironment(opts)
    for (const [key, value] of Object.entries(shellEnv)) {
      process.env[key] = value
    }

    const config: OpenCodeConfig = {
      $schema: 'https://opencode.ai/config.json',
      model: modelString,
      ...(smallModel ? { small_model: smallModel } : {}),
      // A-4: Always set default_agent so DaVinci is the active agent after server start
      default_agent: 'davinci',
      // C-4: Disable autoupdate — we bundle @opencode-ai/sdk as a dependency;
      // a server-side update would create a version mismatch.
      autoupdate: false,
      provider: providers,
      // C-2: Provider allowlist/denylist based on workspace configuration.
      // When using local LLMs only, disable cloud providers to prevent
      // accidental API cost and reduce startup time.
      ...(isLocal
        ? { disabled_providers: ['anthropic', 'openai', 'google', 'aws'] }
        : { enabled_providers: [provider.providerId] }),
      mcp,
      plugin: plugins,
      instructions,
      // C-3: Configure built-in tool availability.
      // - `question: false` — disable OpenCode's built-in ask-user tool since we have
      //   our own more integrated ask_user flow via the control-actions MCP server.
      //   Having both would confuse the agent with duplicate ask-user capabilities.
      // - `skill: true` — keep enabled; our 22+ skills in .claude/skills/ are natively
      //   discoverable by OpenCode.
      // - `todowrite: true` — keep enabled for plan tracking integration.
      // E-9: websearch/webfetch enabled via workspace feature flag.
      tools: {
        question: false,
        // B-5: skill must be a boolean in OpenCode ≤1.17.x schema.
        // Cannot selectively disable individual skills via config — use
        // instructions to tell the agent not to run customize-opencode.
        skill: true,
        ...(opts.webSearchEnabled ? { websearch: true, webfetch: true } : {})
      },
      permission,
      compaction,
      snapshot: true,
      // A-3: Shell path — OpenCode ≤1.17.x expects a string, not an object.
      // Env vars for Bash tool calls are inherited from the server process
      // environment (set in buildShellEnvironment → process.env injection).
      shell: process.platform === 'win32' ? 'pwsh' : '/bin/bash'
    }

    // ── #18/B-6: Formatter config with auto-detection ──
    if (opts.formatterEnabled) {
      config.formatter = this.detectFormatter(opts.workspacePath)
    }

    // ── #13: LSP integration ──
    if (opts.lspEnabled) {
      config.lsp = { enabled: true }
    }

    // ── #16: Image attachment configuration ──
    config.attachment = {
      image: {
        auto_resize: true,
        max_width: 1920,
        max_height: 1080,
        max_base64_bytes: 5_242_880 // 5 MB
      }
    }

    // ── ENH-4: File watcher ignore patterns ──
    config.watcher = {
      enabled: true,
      ignore: [
        'node_modules/**',
        '.git/**',
        'dist/**',
        'build/**',
        '.opencode/**',
        'coverage/**',
        '.next/**',
        '.nuxt/**',
        'out/**',
        '*.lock'
      ]
    }

    // ── ENH-12: Restrict CORS/mDNS for in-process server ──
    // We run the server in-process — no need for network discovery or broad CORS.
    config.server = {
      cors: ['http://localhost:*'],
      mdns: false
    }

    // ── ENH-11: Session sharing defaults (privacy-safe) ──
    config.share = 'disabled'

    // GAP-19: Enable background subagents in build mode (v1.14.51+)
    // Allows subagents to continue research while the primary agent works.
    if (opts.mode === 'build') {
      config.experimental = { backgroundSubagents: true }
    }

    return config
  }

  /**
   * #5: Resolve a lightweight small model for housekeeping tasks.
   * Avoids burning expensive model tokens on title generation, summarization.
   */
  private resolveSmallModel(providerId: string): string | undefined {
    switch (providerId) {
      case 'anthropic':
        return 'anthropic/claude-haiku-3-5'
      case 'openai':
        // D-4: GPT-4o-mini for lightweight housekeeping tasks
        return 'openai/gpt-4o-mini'
      case 'google':
        // D-4: Gemini Flash Lite for fast, cheap housekeeping
        return 'google/gemini-2.0-flash-lite'
      case 'ollama':
        return 'ollama/qwen3:8b'
      case 'omlx':
        return undefined // oMLX models are already small
      default:
        return undefined
    }
  }

  /**
   * #19: Build glob-based permission config.
   * In plan mode, auto-approve safe Bash commands while requiring
   * confirmation for mutations. In build mode, allow everything.
   */
  private buildPermissions(mode: ConversationMode): OpenCodeConfig['permission'] {
    if (mode === 'build' || mode === 'danger') {
      return {
        Write: 'allow',
        Edit: 'allow',
        Bash: 'allow',
        Read: 'allow',
        Glob: 'allow',
        Grep: 'allow',
        // B-7: Subagent invocation allowed in build mode
        task: 'allow',
        // C-3: Allow doom loop detection to prevent token waste
        doom_loop: 'allow',
        // Allow web tools when configured
        websearch: 'allow',
        webfetch: 'allow',
        // LSP and skill always allowed
        lsp: 'allow',
        skill: 'allow',
        todowrite: 'allow'
      }
    }

    // Plan mode: granular Bash permissions via glob patterns
    return {
      Write: 'ask',
      Edit: 'ask',
      Bash: {
        '*': 'ask',
        // Safe read-only commands auto-approved in plan mode
        'git status *': 'allow',
        'git log *': 'allow',
        'git diff *': 'allow',
        'git branch *': 'allow',
        'npm test *': 'allow',
        'npm run typecheck *': 'allow',
        'npm run lint *': 'allow',
        'npx tsc --noEmit *': 'allow',
        'ls *': 'allow',
        'cat *': 'allow',
        'head *': 'allow',
        'tail *': 'allow',
        'wc *': 'allow',
        'find *': 'allow'
      },
      Read: 'allow',
      Glob: 'allow',
      Grep: 'allow',
      // B-7: Block subagent invocation in plan mode — prevents bypassing
      // Write/Edit/Bash restrictions via a subagent with full permissions.
      task: 'deny',
      // B-7: Block access outside workspace in plan mode
      external_directory: 'deny',
      // C-3: Allow doom loop detection in plan mode too
      doom_loop: 'allow',
      // Allow planning tools
      todowrite: 'allow',
      skill: 'allow',
      lsp: 'allow'
    }
  }

  /**
   * B-6: Auto-detect the project's code formatter.
   * Uses FORMATTER_DEFS registry — adding a new formatter is a data entry.
   */
  private detectFormatter(workspacePath: string): NonNullable<OpenCodeConfig['formatter']> {
    for (const def of FORMATTER_DEFS) {
      if (def.configFiles.some((f) => existsSync(join(workspacePath, f)))) {
        return { enabled: true, command: def.command, extensions: def.extensions }
      }
    }
    // No specific formatter detected — use enabled-only (OpenCode default formatter)
    return { enabled: true }
  }

  /**
   * #7: Build tier-aware compaction configuration.
   * Small context windows get aggressive compaction; large windows are conservative.
   */
  private buildCompactionConfig(tier?: ContextWindowTier): OpenCodeConfig['compaction'] {
    switch (tier) {
      case 'small':
        return { enabled: true, auto: true, prune: true, reserved: 4096 }
      case 'medium':
        return { enabled: true, auto: true, prune: true, reserved: 8192 }
      case 'large':
        return { enabled: true, auto: true, prune: true, reserved: 16384 }
      default:
        // Cloud providers (Anthropic) — large context, conservative
        return { enabled: true, auto: true, prune: true, reserved: 8192 }
    }
  }

  /**
   * #15: Build provider entry with tier-aware timeouts and caching.
   *
   * Per the OpenCode config schema (https://opencode.ai/config.json),
   * provider config uses:
   *   - `npm` — npm package for custom/OpenAI-compatible providers
   *   - `options.baseURL` — provider endpoint (note uppercase URL)
   *   - `options.apiKey` — API key
   *   - `options.timeout` / `options.chunkTimeout` — timeouts
   *   - `options.setCacheKey` — Anthropic prompt caching
   *   - `models.<id>.limit` — per-model context/output limits
   *
   * Built-in providers (anthropic, openai, google, aws) don't need `npm`.
   * Custom providers (omlx, ollama, etc.) need `npm: '@ai-sdk/openai-compatible'`.
   */
  private buildProviderConfig(
    provider: OpenCodeConfigWriterOptions['provider'],
    isLocal: boolean,
    contextTier?: ContextWindowTier,
    contextWindowConfident?: boolean
  ): OpenCodeConfig['provider'] {
    const providers: OpenCodeConfig['provider'] = {}
    if (provider.baseUrl || provider.apiKey || isLocal || provider.providerId === 'anthropic') {
      // Providers that aren't built into OpenCode need the npm package specifier
      const builtInProviders = new Set(['anthropic', 'openai', 'google', 'aws', 'copilot'])
      const needsNpm = !builtInProviders.has(provider.providerId) && provider.baseUrl

      // OpenAI-compatible providers expect baseURL to include /v1 (e.g. http://host:8000/v1)
      // because the SDK appends /chat/completions, /models, etc. to it.
      // The app stores base URLs without /v1 (used by health checks), so append it here.
      let resolvedBaseURL = provider.baseUrl
      if (resolvedBaseURL && needsNpm && !resolvedBaseURL.endsWith('/v1')) {
        resolvedBaseURL = resolvedBaseURL.replace(/\/$/, '') + '/v1'
      }

      const options: NonNullable<OpenCodeConfig['provider'][string]['options']> = {
        ...(resolvedBaseURL ? { baseURL: resolvedBaseURL } : {}),
        ...(provider.apiKey ? { apiKey: provider.apiKey } : {}),
        // #15: Tier-aware timeouts — local models are slower
        timeout: isLocal ? 600_000 : 300_000,
        chunkTimeout: isLocal ? 30_000 : 15_000,
        // C-1: Enable prompt caching for Anthropic
        ...(provider.providerId === 'anthropic' ? { setCacheKey: true } : {})
      }

      // C-5: Context/output limits for custom providers.
      // Custom providers (omlx, ollama) MUST declare their models —
      // OpenCode's models.dev registry only covers built-in providers.
      // Use confident limits when available, fall back to sensible defaults.
      const models: OpenCodeConfig['provider'][string]['models'] =
        isLocal && needsNpm
          ? {
              [provider.modelId]: {
                // Custom models aren't in models.dev — declare capabilities explicitly
                // so OpenCode advertises tools and accepts image attachments.
                tool_call: true,
                attachment: true,
                reasoning: true,
                // Declare vision modalities so OpenCode sends image parts to VLMs
                // instead of stripping them or converting to text placeholders.
                modalities: {
                  input: ['text', 'image'],
                  output: ['text']
                },
                limit:
                  contextTier && contextWindowConfident
                    ? {
                        context:
                          contextTier === 'small'
                            ? 8192
                            : contextTier === 'medium'
                              ? 32768
                              : 131072,
                        output: contextTier === 'small' ? 4096 : 32768
                      }
                    : {
                        // Defaults when context window isn't confidently resolved.
                        // 131072 matches the ContextWindow module's default fallback.
                        context: 131072,
                        output: 32768
                      }
              }
            }
          : undefined

      providers[provider.providerId] = {
        ...(needsNpm ? { npm: '@ai-sdk/openai-compatible' } : {}),
        options,
        ...(models ? { models } : {})
      }
    }
    return providers
  }

  /** C-7: Discover workspace instruction files and glob patterns. */
  private buildInstructions(workspacePath: string): string[] {
    const instructions: string[] = []
    const instructionFiles = [
      'CLAUDE.md',
      'AGENTS.md',
      '.github/CONTRIBUTING.md',
      'CONTRIBUTING.md'
    ]
    for (const file of instructionFiles) {
      if (existsSync(join(workspacePath, file))) {
        instructions.push(`{file:${file}}`)
      }
    }

    // 6D-4: Add glob patterns for broader context discovery.
    // Only add globs whose parent directories exist in the workspace
    // to avoid ConfigInvalidError when opencode resolves {file:} refs.
    const instructionGlobs = [
      { glob: 'docs/architecture/*.md', dir: 'docs/architecture' },
      { glob: '.cursor/rules/*.md', dir: '.cursor/rules' }
    ]
    for (const { glob, dir } of instructionGlobs) {
      if (existsSync(join(workspacePath, dir))) {
        instructions.push(`{file:${glob}}`)
      }
    }
    return instructions
  }

  /** #8: Build shell environment vars for the agent subprocess. */
  private buildShellEnvironment(opts: OpenCodeConfigWriterOptions): Record<string, string> {
    const { workspacePath, workspaceId } = opts
    const shellEnv: Record<string, string> = {
      WORKSPACE_PATH: workspacePath,
      GIT_TERMINAL_PROMPT: '0'
    }
    if (workspaceId) shellEnv.WORKSPACE_ID = workspaceId
    // Pass IPC socket path so the plugin can send events to the main process
    if (opts.ipcSocketPath) shellEnv.IPC_SOCKET_PATH = opts.ipcSocketPath
    // Prevent OOM in heavy Node.js tasks spawned by the agent
    shellEnv.NODE_OPTIONS = '--max-old-space-size=4096'

    // D-1: Write system prompt to a temp file and pass its path via env var.
    // This avoids env var size limits (system prompts can be 10KB+).
    if (opts.systemPrompt) {
      const promptFilePath = join(
        tmpdir(),
        'code-atelier-opencode',
        Buffer.from(opts.workspacePath).toString('base64url').slice(0, 32),
        'system-prompt.txt'
      )
      writeFileSync(promptFilePath, opts.systemPrompt, 'utf-8')
      shellEnv.CODE_ATELIER_SYSTEM_PROMPT_FILE = promptFilePath
    }
    return shellEnv
  }

  /**
   * Build MCP server declarations for OpenCode.
   * Same servers as CLI, different format.
   */
  private buildMcpServers(opts: OpenCodeConfigWriterOptions): OpenCodeConfig['mcp'] {
    const servers: OpenCodeConfig['mcp'] = {}

    // Compose from 3 focused sub-builders
    Object.assign(servers, this.buildLocalMcpServers(opts))
    this.buildExternalMcpServers(opts, servers)
    this.buildRemoteMcpServers(opts, servers)

    // 6D-2: Apply per-chat MCP toggles — use enabled:false instead of deleting.
    // This preserves the config for re-enabling without regeneration.
    const { featureFlags } = opts
    for (const [serverId, enabled] of Object.entries(featureFlags.localMcpActive)) {
      if (enabled === false && servers[serverId]) {
        servers[serverId].enabled = false
        configLog.info(`[opencode-config] Disabled MCP: ${serverId}`)
      }
    }

    return servers
  }

  /** Local MCP servers bundled with the app — built from declarative registry. */
  private buildLocalMcpServers(opts: OpenCodeConfigWriterOptions): OpenCodeConfig['mcp'] {
    // Resolve server script base path
    const serverBasePath = app.isPackaged
      ? join(
          app.getAppPath().replace('app.asar', 'app.asar.unpacked'),
          'out',
          'main',
          'mcp-servers'
        )
      : join(__dirname, 'mcp-servers')

    // DB-backed servers (code-graph, semantic-search, code-analysis) run as plain `node`
    // and can't call app.getPath() — pass the userData dir as DB_PATH so they locate the DB.
    const servers = buildLocalMcpServersFromRegistry(
      LOCAL_MCP_SERVER_DEFS,
      opts,
      serverBasePath,
      app.getPath('userData')
    )

    // Inject CONTEXT7_API_KEY for library documentation fallback
    const context7Key = appPreferenceRepository.get('context7_api_key')
    if (context7Key && servers['code-analysis']) {
      servers['code-analysis'].environment = {
        ...servers['code-analysis'].environment,
        CONTEXT7_API_KEY: context7Key
      }
    }

    return servers
  }

  /** External MCP integrations (Maestro, etc.) registered via feature flags. */
  private buildExternalMcpServers(
    opts: OpenCodeConfigWriterOptions,
    servers: OpenCodeConfig['mcp']
  ): void {
    const externalActive = opts.featureFlags.externalMcpActive ?? {}
    for (const integration of EXTERNAL_MCP_INTEGRATIONS) {
      if (externalActive[integration.id]) {
        // Build env from the integration's envKeys
        const env: Record<string, string> = {}
        for (const key of integration.envKeys ?? []) {
          if (process.env[key]) {
            env[key] = process.env[key]!
          }
        }
        // Add any performance env overrides
        if (integration.performanceEnv) {
          Object.assign(env, integration.performanceEnv)
        }

        // Resolve the command — try commandPaths first, then bare command
        let resolvedCommand = integration.command
        if (integration.commandPaths) {
          for (const cmdPath of integration.commandPaths) {
            const expanded = cmdPath.replace('~', process.env.HOME ?? '')
            if (existsSync(expanded)) {
              resolvedCommand = expanded
              break
            }
          }
        }

        servers[integration.id] = {
          type: 'local',
          command: [resolvedCommand, ...integration.args],
          environment: Object.keys(env).length > 0 ? env : undefined
        }
        configLog.info(`[opencode-config] Mounted external MCP: ${integration.id}`)
      }
    }
  }

  /** GAP-8: Remote MCP servers (cloud code analysis, team indexes, CI/CD endpoints). */
  private buildRemoteMcpServers(
    opts: OpenCodeConfigWriterOptions,
    servers: OpenCodeConfig['mcp']
  ): void {
    if (!opts.remoteMcpServers) return
    for (const [serverId, remote] of Object.entries(opts.remoteMcpServers)) {
      servers[serverId] = {
        type: 'remote',
        url: remote.url,
        ...(remote.headers ? { headers: remote.headers } : {}),
        ...(remote.oauth ? { oauth: remote.oauth } : {}),
        ...(remote.enabled === false ? { enabled: false } : {})
      }
      configLog.info(`[opencode-config] Mounted remote MCP: ${serverId} (${remote.url})`)
    }
  }
}

