/**
 * OpenCode Agent Writer — generates .opencode/agents/*.md files.
 *
 * #6: OpenCode supports custom agent definitions that let us map our
 * Specialist role to native OpenCode agents with:
 *   - Per-agent model overrides
 *   - Role-specific system prompts
 *   - Permission configs matching our plan/build mode
 *   - Tab-switchable in the OpenCode TUI
 *
 * These agent files are generated on workspace initialization and updated
 * when the specialist is rebuilt or settings change.
 *
 * Reference: https://opencode.ai/docs/agents/
 * Phase 5D — OpenCode Enhancement: Custom agent definitions.
 */

import { existsSync, mkdirSync, writeFileSync, readdirSync, readFileSync } from 'node:fs'
import { join } from 'node:path'
import log from 'electron-log/main'
import type { OpenCodeProviderConfig } from './opencode-executor'

const agentLog = log.scope('OpenCodeAgentWriter')

// ── Types ──

export interface OpenCodeAgentOptions {
  /** Workspace root path */
  workspacePath: string
  /** Provider config for model resolution */
  provider: OpenCodeProviderConfig
  /** Specialist system prompt (from the adapter's prompt assembler) */
  davinciSystemPrompt?: string
  /** Named specialist system prompt (from the specialist adapter) */
  specialistSystemPrompt?: string
  /** Specialist display name (e.g. "React Expert" / "Django Architect") */
  specialistName?: string
  /** Current conversation mode — drives permission config */
  mode: 'plan' | 'build' | 'danger'
  /** Max turns for the agent loop */
  maxTurns?: number
}

// ── Writer ──

export class OpenCodeAgentWriter {
  /**
   * Generate both agent definition files and custom commands for the workspace.
   *
   * Creates:
   *   - .opencode/agents/davinci.md — default specialist agent
   *   - .opencode/agents/project-specialist.md — LLM-tailored specialist (if available)
   *   - .opencode/commands/*.md — custom slash commands for Code Atelier workflows
   */
  writeAgents(opts: OpenCodeAgentOptions): void {
    const agentDir = join(opts.workspacePath, '.opencode', 'agents')
    if (!existsSync(agentDir)) {
      mkdirSync(agentDir, { recursive: true })
    }

    // Always write the default specialist agent
    this.writeDaVinciAgent(agentDir, opts)

    // Write specialist if available
    if (opts.specialistSystemPrompt) {
      this.writeSpecialistAgent(agentDir, opts)
    }

    // D-3: Disable specialist agent if prompt is gone but file remains
    if (!opts.specialistSystemPrompt) {
      this.disableSpecialistIfExists(agentDir)
    }

    // E-2: Generate custom commands
    this.writeCommands(opts.workspacePath, opts)

    // E-3: Validate skills frontmatter for OpenCode compatibility
    this.validateSkillsFrontmatter(opts.workspacePath)

    agentLog.info(
      `[opencode-agents] Wrote agent definitions to ${agentDir} ` +
        `(specialist=${!!opts.specialistSystemPrompt})`
    )
  }

  /**
   * Clean up agent definition files.
   */
  dispose(workspacePath: string): void {
    // Agent files are part of the workspace's .opencode directory —
    // we don't delete them since they may be tracked in git or
    // useful for standalone OpenCode usage.
    agentLog.info(`[opencode-agents] Dispose called for ${workspacePath} (no-op — files preserved)`)
  }

  // ── Private ──

  private writeDaVinciAgent(agentDir: string, opts: OpenCodeAgentOptions): void {
    const model = `${opts.provider.providerId}/${opts.provider.modelId}`
    const maxTurns = opts.maxTurns ?? (opts.mode === 'build' ? 200 : 50)
    const steps = opts.mode === 'build' ? maxTurns : Math.min(maxTurns, 30)

    // ENH-2: Build per-agent permission block matching our plan/build mode
    // GAP-18: task: allow in build mode enables subagent spawning
    const permissionBlock =
      opts.mode === 'build'
        ? 'permission:\n  Write: allow\n  Edit: allow\n  Bash: allow\n  task: allow'
        : 'permission:\n  Write: ask\n  Edit: ask\n  Bash: ask\n  task: deny'

    // F-1/F-2/F-3: Provider-specific frontmatter options
    const providerOptions = this.buildProviderOptions(opts.provider.providerId, opts.mode)
    const content = `---
name: DaVinci
description: Expert AI development partner for Code Atelier — analyzes, plans, and builds software.
mode: primary
model: ${model}
steps: ${steps}
max_turns: ${maxTurns}
temperature: 0.7
color: "#4A9EFF"
${permissionBlock}
${providerOptions}
---

# DaVinci — Expert Development Partner

You are **DaVinci**, the default AI development partner for Code Atelier.

## Core Identity

You are an expert-level software engineer who pairs with the developer to
analyze, plan, and build software. You combine deep technical knowledge with
practical experience across the full stack.

## Behavioral Guidelines

- **Plan Mode**: Analyze codebases, create plans, answer questions. Read-only
  tools only (Read, Glob, Grep, CodeGraph). Never modify files without explicit
  permission.
- **Build Mode**: Implement plans, write code, run tests, fix bugs. Full tool
  access including Write, Edit, Bash.
- Always read files before editing them.
- Use CodeGraph tools before Grep for code navigation.
- Keep responses focused and actionable.
- When creating plans, structure them with clear phases and tasks.

## Tool Usage Constraints

- Maximum ${maxTurns} tool calls per interaction
- Use \`Read\` with \`limit: 300\` for large files
- Background long-running commands with \`&\`
- Never access files outside the workspace directory

## Built-in Subagents (GAP-18)

When appropriate, delegate to OpenCode's built-in subagents:
- **Scout** — Read-only. Use for external docs lookup, dependency research, API exploration.
  Invoke via the \`task\` tool when you need background research without modifying files.
- **Explore** — Read-only, fast. Use for codebase navigation and structure discovery when
  CodeGraph tools aren't sufficient (e.g. cross-repo or unfamiliar codebases).
- **General** — Full access. Use for multi-step parallel tasks (e.g. run tests while
  refactoring, or generate docs while implementing).

## System Prompt Delivery

C-2: Workspace-specific instructions are injected via the
\`experimental.chat.system.transform\` plugin hook into the real system prompt
position. They are NOT duplicated here to avoid token waste.
`

    writeFileSync(join(agentDir, 'davinci.md'), content, 'utf-8')
  }

  private writeSpecialistAgent(agentDir: string, opts: OpenCodeAgentOptions): void {
    const model = `${opts.provider.providerId}/${opts.provider.modelId}`
    const name = opts.specialistName ?? 'Project Specialist'
    const maxTurns = opts.maxTurns ?? (opts.mode === 'build' ? 200 : 50)
    const steps = opts.mode === 'build' ? maxTurns : Math.min(maxTurns, 30)

    // ENH-2: Per-agent permission block
    // GAP-18: task: allow in build mode enables subagent spawning
    const permissionBlock =
      opts.mode === 'build'
        ? 'permission:\n  Write: allow\n  Edit: allow\n  Bash: allow\n  task: allow'
        : 'permission:\n  Write: ask\n  Edit: ask\n  Bash: ask\n  task: deny'

    const content = `---
name: ${name}
description: LLM-tailored expert configured for this workspace's technology stack and conventions.
mode: primary
model: ${model}
steps: ${steps}
max_turns: ${maxTurns}
temperature: 0.7
color: "#FF6B35"
${permissionBlock}
${this.buildProviderOptions(opts.provider.providerId, opts.mode)}
---

# ${name} — LLM-Tailored Expert

You are a **${name}**, an AI expert specifically configured for this workspace's
technology stack. Your expertise has been built from analyzing this project's
CLAUDE.md, dependencies, architecture, and coding conventions.

## Specialization

${opts.specialistSystemPrompt ?? 'No specialization prompt available.'}

## Behavioral Guidelines

- Follow all workspace conventions from CLAUDE.md
- Use CodeGraph tools for code navigation before text search
- Respect the current conversation mode (plan vs build)
- Keep responses aligned with the project's established patterns

## Tool Usage Constraints

- Maximum ${maxTurns} tool calls per interaction
- Use \`Read\` with \`limit: 300\` for large files
- Background long-running commands with \`&\`
- Never access files outside the workspace directory

## Built-in Subagents (GAP-18)

- **Scout** — Read-only research agent for docs and dependency exploration.
- **Explore** — Fast read-only codebase navigation.
- **General** — Full-access multi-step parallel worker for background tasks.

Use the \`task\` tool to spawn subagents when beneficial.
`

    writeFileSync(join(agentDir, 'project-specialist.md'), content, 'utf-8')
  }

  // ── D-3: Disable Specialist When Prompt Removed ──

  /**
   * D-3: When specialistSystemPrompt is undefined but a specialist.md file exists,
   * write `disable: true` in its frontmatter instead of leaving an orphaned file.
   */
  private disableSpecialistIfExists(agentDir: string): void {
    const specialistPath = join(agentDir, 'project-specialist.md')
    if (!existsSync(specialistPath)) return

    try {
      const content = readFileSync(specialistPath, 'utf-8')
      // Check if already disabled
      if (content.includes('disable: true')) return

      // Add disable: true to frontmatter
      const disabledContent = content.replace(/^---\n/, '---\ndisable: true\n')
      writeFileSync(specialistPath, disabledContent, 'utf-8')
      agentLog.info('[opencode-agents] Disabled orphaned specialist agent (no system prompt)')
    } catch (err) {
      agentLog.warn(`[opencode-agents] Failed to disable specialist: ${(err as Error).message}`)
    }
  }

  // ── F-1/F-2/F-3: Provider-Specific Frontmatter Options ──

  /**
   * Generate provider-specific frontmatter options for agent files.
   *
   * F-1: Anthropic extended thinking budget (budgetTokens)
   * F-2: OpenAI reasoning effort (reasoningEffort)
   * F-3: Per-agent tool restrictions
   */
  private buildProviderOptions(providerId: string, mode: 'plan' | 'build' | 'danger'): string {
    const lines: string[] = []

    switch (providerId) {
      case 'anthropic':
        // F-1: Extended thinking for Anthropic models — higher budget in build mode
        // for complex multi-step implementations
        lines.push('thinking:')
        lines.push('  type: enabled')
        lines.push(`  budgetTokens: ${mode === 'build' ? 32000 : 16000}`)
        break

      case 'openai':
        // F-2: Reasoning effort for GPT-5+ models — higher in build mode
        lines.push(`reasoningEffort: ${mode === 'build' ? 'high' : 'medium'}`)
        break

      case 'ollama':
      case 'omlx':
        // Local models — no special options but reduce temperature for consistency
        lines.push('temperature: 0.5')
        break
    }

    // F-3: Per-agent tool restrictions — disable question tool (we use our own)
    lines.push('tools:')
    lines.push('  question: false')

    return lines.join('\n')
  }

  // ── E-3: Skills Frontmatter Validation ──

  /**
   * Validate that .claude/skills/ SKILL.md files have valid OpenCode-compatible
   * frontmatter. OpenCode requires:
   *   - `name`: lowercase, hyphenated, 1-64 chars, regex ^[a-z0-9]+(-[a-z0-9]+)*$
   *   - `description`: 1-1024 chars
   */
  private validateSkillsFrontmatter(workspacePath: string): void {
    const skillDirs = [
      join(workspacePath, '.claude', 'skills'),
      join(workspacePath, '.opencode', 'skills')
    ]

    const namePattern = /^[a-z0-9]+(-[a-z0-9]+)*$/
    let validCount = 0
    let invalidCount = 0

    for (const skillsDir of skillDirs) {
      if (!existsSync(skillsDir)) continue

      const entries = readdirSync(skillsDir, { withFileTypes: true })
      for (const entry of entries) {
        if (!entry.isDirectory()) continue
        const skillFile = join(skillsDir, entry.name, 'SKILL.md')
        if (!existsSync(skillFile)) continue

        try {
          const content = readFileSync(skillFile, 'utf-8')
          const frontmatterMatch = content.match(/^---\n([\s\S]*?)\n---/)
          if (!frontmatterMatch) {
            agentLog.warn(`[opencode-agents] Missing frontmatter: ${skillFile}`)
            invalidCount++
            continue
          }

          const frontmatter = frontmatterMatch[1]
          const nameMatch = frontmatter.match(/^name:\s*(.+)$/m)
          const descMatch = frontmatter.match(/^description:/m)

          if (!nameMatch) {
            agentLog.warn(`[opencode-agents] Missing 'name' in frontmatter: ${skillFile}`)
            invalidCount++
            continue
          }

          const name = nameMatch[1].trim().replace(/['"]*/g, '')
          if (!namePattern.test(name)) {
            agentLog.warn(
              `[opencode-agents] Invalid skill name "${name}" in ${skillFile} — ` +
                `must match ^[a-z0-9]+(-[a-z0-9]+)*$`
            )
            invalidCount++
            continue
          }

          if (!descMatch) {
            agentLog.warn(`[opencode-agents] Missing 'description' in frontmatter: ${skillFile}`)
            invalidCount++
            continue
          }

          validCount++
        } catch (err) {
          agentLog.warn(
            `[opencode-agents] Failed to read skill: ${skillFile}: ${(err as Error).message}`
          )
        }
      }
    }

    if (invalidCount > 0) {
      agentLog.warn(
        `[opencode-agents] Skills validation: ${validCount} valid, ${invalidCount} invalid — ` +
          `invalid skills will silently fail to load in OpenCode`
      )
    } else if (validCount > 0) {
      agentLog.info(
        `[opencode-agents] Skills validation: all ${validCount} skills have valid frontmatter`
      )
    }
  }

  // ── E-2: Custom Commands ──

  /**
   * Generate .opencode/commands/ with Code Atelier workflow shortcuts.
   *
   * Custom commands support $ARGUMENTS, $1/$2 positional params, !command shell
   * injection, @filename file references, agent/model overrides, and subtask: true
   * for subagent isolation.
   */
  private writeCommands(workspacePath: string, _opts: OpenCodeAgentOptions): void {
    const commandDir = join(workspacePath, '.opencode', 'commands')
    if (!existsSync(commandDir)) {
      mkdirSync(commandDir, { recursive: true })
    }

    // /audit — Trigger workspace health audit
    writeFileSync(
      join(commandDir, 'audit.md'),
      `---
description: Run a workspace health audit scanning code quality, test coverage, security, and dependencies.
agent: davinci
---

Perform a comprehensive workspace health audit for scope: $ARGUMENTS

Analyze:
1. Code quality issues (complexity, dead code, naming)
2. Test coverage gaps
3. Security concerns (exposed secrets, unsafe patterns)
4. Dependency health (outdated, vulnerable, unused)

Use the code_atelier_audit tool to record findings.
If no scope is specified, audit the entire workspace.

!git diff --stat HEAD~5
`,
      'utf-8'
    )

    // /plan — Create a structured implementation plan
    writeFileSync(
      join(commandDir, 'plan.md'),
      `---
description: Create a structured implementation plan for a feature or change.
agent: davinci
---

Create a structured implementation plan for: $ARGUMENTS

Follow this structure:
1. Analyze the current codebase state relevant to this change
2. Break down into phases with clear tasks
3. Identify risks and dependencies
4. Estimate effort for each task

Use the code_atelier_plan tool to emit the plan for UI tracking.
Read CLAUDE.md and relevant source files before planning.
`,
      'utf-8'
    )

    // /review — Code review a specific file or directory
    writeFileSync(
      join(commandDir, 'review.md'),
      `---
description: Perform a thorough code review of a file or directory.
agent: davinci
subtask: true
---

Perform a thorough code review of: $ARGUMENTS

Check for:
- Correctness and edge cases
- Performance issues
- Security vulnerabilities
- Adherence to project conventions (read CLAUDE.md)
- Test coverage
- Code clarity and maintainability

Use CodeGraph tools (mcp__code-graph__find_callers, mcp__code-graph__find_references) to understand impact.
@$1
`,
      'utf-8'
    )

    // /test — Run and analyze tests
    writeFileSync(
      join(commandDir, 'test.md'),
      `---
description: Run tests and analyze results, fixing failures if found.
agent: davinci
---

Run and analyze tests for: $ARGUMENTS

1. Run the relevant test suite
2. Analyze any failures
3. If tests fail, diagnose the root cause
4. Suggest or implement fixes

!npm test -- $ARGUMENTS 2>&1 | head -100
`,
      'utf-8'
    )

    // /grill — Challenge assumptions about a file
    writeFileSync(
      join(commandDir, 'grill.md'),
      `---
description: Challenge assumptions and find hidden issues in a file or component.
agent: davinci
subtask: true
---

Grill this code — challenge every assumption and find hidden issues: $ARGUMENTS

Be adversarial. Look for:
- Implicit assumptions that could break
- Missing error handling
- Race conditions
- Untested edge cases
- Security issues
- Performance cliffs
- API misuse

@$1
`,
      'utf-8'
    )

    agentLog.info(`[opencode-agents] Wrote 5 custom commands to ${commandDir}`)
  }
}

/** Singleton instance */
export const openCodeAgentWriter = new OpenCodeAgentWriter()

/**
 * CLI MCP Config Writer — generates --mcp-config JSON for Claude CLI sessions.
 *
 * When using the CLI executor backend (`claude --mcp-config <path>`), this
 * module generates the JSON configuration file that declares MCP servers
 * as stdio child processes. The CLI spawns each server and connects to it.
 *
 * Expected format:
 * ```json
 * {
 *   "mcpServers": {
 *     "code-graph": {
 *       "command": "node",
 *       "args": ["/path/to/code-graph-server.js"],
 *       "env": { "WORKSPACE_ID": "xxx", "WORKSPACE_PATH": "/path" }
 *     }
 *   }
 * }
 * ```
 *
 * Server list and feature-flag gating mirror OpenCodeConfigWriter.buildMcpServers().
 */

import { writeFileSync, existsSync, mkdirSync, unlinkSync } from 'node:fs'
import { join } from 'node:path'
import { tmpdir } from 'node:os'
import { app } from 'electron'
import log from 'electron-log/main'
import type { ConversationMode } from '../../shared/types'
import type { McpFeatureFlags } from './workspace-mcp-config'
import { EXTERNAL_MCP_INTEGRATIONS } from '../../shared/constants'
import { appPreferenceRepository } from '../db/repositories/app-preference.repository'

const configLog = log.scope('CliMcpConfigWriter')

// ── Types ──

/** A single MCP server entry in the CLI config format. */
interface CliMcpServerEntry {
  command: string
  args: string[]
  env?: Record<string, string>
}

/** Top-level CLI MCP config structure. */
interface CliMcpConfig {
  mcpServers: Record<string, CliMcpServerEntry>
}

/** Options for writing a CLI MCP config file. */
export interface CliMcpConfigWriterOptions {
  workspacePath: string
  workspaceId: string | null
  conversationId: string | null
  mode: ConversationMode
  featureFlags: McpFeatureFlags
  /** IPC socket path for control-actions server ↔ Electron main process. */
  ipcSocketPath?: string
  /**
   * Control-action callbacks — accepted for call-site compatibility with
   * buildCLIMcpConfigPath() but NOT used by the CLI writer. The
   * control-actions MCP server communicates via IPC socket instead.
   */
  controlCallbacks?: unknown
  /**
   * Server IDs to omit from the generated config. Blueprint sessions use this
   * to skip spawning servers whose tools aren't in allowedTools (e.g.
   * 'checkpoint-context', 'control-actions', 'github-context') — reducing
   * cold-start contention that causes the MCP connection race.
   */
  skipServers?: string[]
  /**
   * G1: Unique instance identifier for per-session config isolation.
   * When provided, the config file is written as `mcp-config-<instanceId>.json`
   * instead of the shared `mcp-config.json`, preventing parallel build tasks
   * from overwriting each other's config.
   */
  instanceId?: string
}

// ── Writer ──

export class CliMcpConfigWriter {
  /** Track generated config paths for cleanup. */
  private readonly configPaths = new Map<string, string>()

  /**
   * Generate a CLI MCP config JSON and write it to a temp file.
   * Returns the absolute path to the generated config file.
   */
  writeConfig(opts: CliMcpConfigWriterOptions): string {
    const config = this.buildConfig(opts)
    const serverCount = Object.keys(config.mcpServers).length

    // Write to temp directory — avoids polluting workspace git status
    const tempDir = join(
      tmpdir(),
      'agent-studio-mcp',
      Buffer.from(opts.workspacePath).toString('base64url').slice(0, 32)
    )
    if (!existsSync(tempDir)) {
      mkdirSync(tempDir, { recursive: true })
    }
    // G1: Per-session config files prevent parallel build tasks from overwriting
    // each other's MCP configuration. Key includes instanceId when provided.
    const configFileName = opts.instanceId
      ? `mcp-config-${opts.instanceId}.json`
      : 'mcp-config.json'
    const configPath = join(tempDir, configFileName)

    writeFileSync(configPath, JSON.stringify(config, null, 2), 'utf-8')
    configLog.info(`[cli-mcp-config] Wrote: ${configPath} (${serverCount} MCP servers)`)

    // Store for cleanup — key includes instanceId for per-session tracking
    const configKey = opts.instanceId
      ? `${opts.workspacePath}:${opts.instanceId}`
      : opts.workspacePath
    this.configPaths.set(configKey, configPath)

    return configPath
  }

  /** Clean up generated config file. Pass instanceId for per-session configs. */
  dispose(workspacePath: string, instanceId?: string): void {
    const configKey = instanceId
      ? `${workspacePath}:${instanceId}`
      : workspacePath
    const configPath = this.configPaths.get(configKey)
    if (configPath) {
      try {
        unlinkSync(configPath)
        configLog.info(`[cli-mcp-config] Cleaned up: ${configPath}`)
      } catch {
        /* file may already be gone */
      }
      this.configPaths.delete(configKey)
    }
  }

  // ── Private ──

  private buildConfig(opts: CliMcpConfigWriterOptions): CliMcpConfig {
    const servers: Record<string, CliMcpServerEntry> = {}
    const { featureFlags, workspaceId, workspacePath } = opts

    // Resolve MCP server script base path (packaged vs dev)
    const serverBasePath = app.isPackaged
      ? join(
          app.getAppPath().replace('app.asar', 'app.asar.unpacked'),
          'out',
          'main',
          'mcp-servers'
        )
      : join(__dirname, 'mcp-servers')

    // DB-backed MCP servers run as plain `node` (no Electron app global), so they can't
    // resolve app.getPath('userData'). Pass the userData dir explicitly via DB_PATH.
    const dbDir = app.getPath('userData')

    log.info(`[cli-mcp-config] serverBasePath=${serverBasePath} isPackaged=${app.isPackaged}`)

    // ── Code Graph ──
    if (featureFlags.repomapEnabled && workspaceId) {
      servers['code-graph'] = {
        command: 'node',
        args: [join(serverBasePath, 'code-graph-server.js')],
        env: {
          WORKSPACE_ID: workspaceId,
          WORKSPACE_PATH: workspacePath,
          DB_PATH: dbDir
        }
      }
    }

    // ── Semantic Search ──
    if (featureFlags.semanticSearchEnabled && workspaceId) {
      servers['semantic-search'] = {
        command: 'node',
        args: [join(serverBasePath, 'semantic-search-server.js')],
        env: { WORKSPACE_ID: workspaceId, DB_PATH: dbDir }
      }
    }

    // ── Memory ──
    if (workspaceId) {
      servers['memory'] = {
        command: 'node',
        args: [join(serverBasePath, 'memory-server.js')],
        env: { WORKSPACE_ID: workspaceId, DB_PATH: dbDir }
      }
    }

    // ── Git Context ──
    servers['git-context'] = {
      command: 'node',
      args: [join(serverBasePath, 'git-context-server.js')],
      env: { WORKSPACE_PATH: workspacePath }
    }

    // ── Checkpoint Context ── (only when resuming a conversation)
    if (opts.conversationId) {
      servers['checkpoint-context'] = {
        command: 'node',
        args: [join(serverBasePath, 'checkpoint-context-server.js')],
        env: {
          CONVERSATION_ID: opts.conversationId,
          WORKSPACE_PATH: workspacePath
        }
      }
    }

    // ── GitHub Context ──
    if (featureFlags.githubConfigured && workspaceId) {
      servers['github-context'] = {
        command: 'node',
        args: [join(serverBasePath, 'github-context-server.js')],
        env: {
          WORKSPACE_ID: workspaceId,
          WORKSPACE_PATH: workspacePath
        }
      }
    }

    // ── Code Analysis ──
    const codeAnalysisEnv: Record<string, string> = {
      WORKSPACE_PATH: workspacePath
    }
    if (workspaceId) codeAnalysisEnv.WORKSPACE_ID = workspaceId
    if (dbDir) codeAnalysisEnv.DB_PATH = dbDir
    const context7Key = appPreferenceRepository.get('context7_api_key')
    if (context7Key) codeAnalysisEnv.CONTEXT7_API_KEY = context7Key
    servers['code-analysis'] = {
      command: 'node',
      args: [join(serverBasePath, 'code-analysis-server.js')],
      env: codeAnalysisEnv
    }

    // ── Process Manager ──
    servers['process-manager'] = {
      command: 'node',
      args: [join(serverBasePath, 'process-manager-server.js')],
      env: { WORKSPACE_PATH: workspacePath }
    }

    // ── Control Actions ──
    const controlEnv: Record<string, string> = {
      WORKSPACE_PATH: workspacePath,
      CONVERSATION_MODE: opts.mode
    }
    if (opts.ipcSocketPath) {
      controlEnv.IPC_SOCKET_PATH = opts.ipcSocketPath
    }
    if (opts.conversationId) {
      controlEnv.CONVERSATION_ID = opts.conversationId
    }
    servers['control-actions'] = {
      command: 'node',
      args: [join(serverBasePath, 'control-actions-server.js')],
      env: controlEnv
    }

    // ── External MCP Integrations (Maestro, etc.) ──
    const externalActive = featureFlags.externalMcpActive ?? {}
    for (const integration of EXTERNAL_MCP_INTEGRATIONS) {
      if (externalActive[integration.id]) {
        const env: Record<string, string> = {}

        // Copy env vars the integration expects
        if (integration.envKeys) {
          for (const key of integration.envKeys) {
            if (process.env[key]) {
              env[key] = process.env[key]!
            }
          }
        }

        // Add performance env overrides
        if (integration.performanceEnv) {
          Object.assign(env, integration.performanceEnv)
        }

        // Resolve the command — try commandPaths first, then bare command
        let resolvedCommand = integration.command
        if (integration.commandPaths) {
          for (const cmdPath of integration.commandPaths) {
            const expanded = cmdPath.replace('~', process.env.HOME ?? '')
            if (existsSync(expanded)) {
              resolvedCommand = expanded
              break
            }
          }
        }

        servers[integration.id] = {
          command: resolvedCommand,
          args: [...integration.args],
          ...(Object.keys(env).length > 0 ? { env } : {})
        }
        configLog.info(`[cli-mcp-config] Mounted external MCP: ${integration.id}`)
      }
    }

    // Remove explicitly skipped servers (blueprint sessions skip servers
    // whose tools aren't in allowedTools — fewer cold-start processes).
    if (opts.skipServers?.length) {
      for (const serverId of opts.skipServers) {
        if (servers[serverId]) {
          delete servers[serverId]
          configLog.info(`[cli-mcp-config] Skipped (not in allowedTools): ${serverId}`)
        }
      }
    }

    // Apply per-chat MCP toggles — remove disabled servers entirely
    // (CLI config doesn't support enabled:false like OpenCode does)
    for (const [serverId, enabled] of Object.entries(featureFlags.localMcpActive)) {
      if (enabled === false && servers[serverId]) {
        delete servers[serverId]
        configLog.info(`[cli-mcp-config] Disabled MCP: ${serverId}`)
      }
    }

    return { mcpServers: servers }
  }
}

/**
 * PrimingContextGatherer — collects workspace context for session priming.
 *
 * Gathers recent git changes, active plan state, and relevant workspace memories
 * to inject before the first prompt so the session starts warm. Each source is
 * independently testable.
 *
 * Extracted from AgentSessionService.buildPrimingContext.
 */

import { workspaceRepository } from '../db/repositories'
import { localPlanStateService } from './local-plan-state.service'

type PrimingPart = { type: 'text'; text: string }

export class PrimingContextGatherer {
  /**
   * Build priming context for a new session.
   * Returns an array of text parts that can be injected before the first prompt.
   */
  async gather(opts: {
    workspaceId: string | null
    workspacePath: string | null
    conversationId: string | null
    userPrompt: string
  }): Promise<PrimingPart[]> {
    const { workspaceId, workspacePath, conversationId } = opts

    // Check feature flag — gate priming for independent testing
    try {
      if (workspaceId) {
        const settings = workspaceRepository.getSettings(workspaceId)
        if (settings.contextPrimingEnabled === false) {
          return []
        }
      }
    } catch {
      /* non-fatal */
    }

    const parts: PrimingPart[] = []

    // Memory injection is now handled per-turn by the knowledge-aware memory engine
    // in chat-stream.service.ts and agent-session.service.ts (Phase 3).
    const [gitPart, planPart] = await Promise.all([
      this.gatherRecentGitChanges(workspacePath),
      this.gatherActivePlanState(conversationId)
    ])

    if (gitPart) parts.push(gitPart)
    if (planPart) parts.push(planPart)

    return parts
  }

  /**
   * 1. Recent git changes (last 3 commits diff stat).
   */
  private async gatherRecentGitChanges(workspacePath: string | null): Promise<PrimingPart | null> {
    if (!workspacePath) return null
    try {
      const { execSync } = await import('node:child_process')
      const gitDiff = execSync('git diff --stat HEAD~3 2>/dev/null || true', {
        cwd: workspacePath,
        timeout: 5000,
        encoding: 'utf-8',
        maxBuffer: 10_000
      }).trim()

      if (gitDiff && gitDiff.length > 10) {
        // PROMPT-05: Truncate git diff output to prevent consuming the entire priming budget
        const truncatedDiff =
          gitDiff.length > 3000 ? gitDiff.slice(0, 3000) + '\n[...truncated]' : gitDiff
        return {
          type: 'text',
          text: `[Workspace Context: Recent Changes]\n${truncatedDiff}`
        }
      }
    } catch {
      /* git not available or no commits — non-fatal */
    }
    return null
  }

  /**
   * 2. Active plan state (if any conversation has a plan in progress).
   */
  private async gatherActivePlanState(conversationId: string | null): Promise<PrimingPart | null> {
    if (!conversationId) return null
    try {
      const planState = localPlanStateService.getForConversation(conversationId)
      if (planState?.planText) {
        const planText = planState.planText
        const planSummary =
          planText.length > 2000 ? planText.slice(0, 2000) + '\n[...truncated]' : planText
        return {
          type: 'text',
          text: `[Workspace Context: Active Plan]\n${planSummary}`
        }
      }
    } catch {
      /* plan service not available — non-fatal */
    }
    return null
  }

  // gatherWorkspaceMemories removed — memory injection handled per-turn by memory-retrieval.service.ts
}

