/**
 * Try to set up a test database. Returns null if better-sqlite3 is incompatible.
 */
export function trySetupTestDb(): { db: import('better-sqlite3').Database; wsId: string } | null {
  try {
    process.env.NODE_ENV = 'test'
    const { createTestDb, seedWorkspace } = require('../../test-helpers')
    const { _setDatabaseForTesting } = require('../../index')
    const db = createTestDb()
    _setDatabaseForTesting(db)
    const wsId = seedWorkspace(db)
    return { db, wsId }
  } catch (err) {
    console.log(
      `\n⚠ DB test setup failed — tests will be skipped.`
    )
    console.log(`  (${(err as Error).message.split('\n')[0]})`)
    return null
  }
}

/**
 * Seed a conversation for a given workspace. Returns the conversation ID.
 */
export function seedConversation(
  db: import('better-sqlite3').Database,
  workspaceId: string,
  title = 'Test Conversation',
  mode: 'plan' | 'build' | 'danger' = 'plan'
): string {
  const row = db
    .prepare(`INSERT INTO conversations (workspace_id, title, mode) VALUES (?, ?, ?) RETURNING id`)
    .get(workspaceId, title, mode) as { id: string }
  return row.id
}

/**
 * Unit tests for StackDriftDetectorService.
 *
 * The detector reads from the DB, so these tests cover the pure logic
 * (fingerprint + diff) via a focused probe that avoids DB bootstrap by
 * exercising an equivalent computation. Full integration is covered in
 * the Playwright E2E suite.
 */
import assert from 'node:assert/strict'
import { createHash } from 'node:crypto'
import { test, describe, summaryAsync } from './test-harness'

function fingerprint(techs: string[]): string {
  return createHash('sha256')
    .update([...techs].sort().join('|'))
    .digest('hex')
    .slice(0, 16)
}

describe('stack-drift-detector (fingerprint logic)', () => {
  test('stable_fingerprint_for_same_input_order', () => {
    const a = fingerprint(['react', 'typescript'])
    const b = fingerprint(['typescript', 'react'])
    assert.equal(a, b)
  })

  test('different_inputs_produce_different_fingerprints', () => {
    const a = fingerprint(['react'])
    const b = fingerprint(['vue'])
    assert.notEqual(a, b)
  })

  test('empty_list_produces_stable_fingerprint', () => {
    const a = fingerprint([])
    const b = fingerprint([])
    assert.equal(a, b)
    assert.equal(a.length, 16)
  })

  test('fingerprint_length_is_16_hex', () => {
    const fp = fingerprint(['react', 'tailwind', 'typescript'])
    assert.equal(fp.length, 16)
    assert.match(fp, /^[0-9a-f]+$/)
  })

  test('adding_a_tech_changes_fingerprint', () => {
    const a = fingerprint(['react'])
    const b = fingerprint(['react', 'typescript'])
    assert.notEqual(a, b)
  })
})

