// ── Candidate-directory scanning (monorepo-aware) ──────────────────

/** Convention dirs we always probe at depth 1 when present. */
const CONVENTION_DIRS = [
  'frontend',
  'backend',
  'web',
  'api',
  'client',
  'server',
  'src',
  'app',
  'electron',
  'services',
  'ui',
  'desktop',
  'mobile'
] as const

/** Container dirs whose direct children are individually scanned (monorepo apps/packages). */
const MONOREPO_CONTAINER_DIRS = ['apps', 'packages'] as const

/** Directory names that must NEVER be scanned, even at the workspace root. */
const DIR_DENYLIST = new Set([
  'node_modules',
  '.git',
  'dist',
  'build',
  'bin',
  'obj',
  '.next',
  '.cache',
  '.output',
  'coverage',
  'target',
  'vendor'
])

/** Hard cap on total candidate dirs scanned per workspace — keeps detection fast. */
const MAX_CANDIDATE_DIRS = 30
/** Cap per monorepo container (apps/, packages/) — protects against gigantic monorepos. */
const MAX_PER_CONTAINER = 12

/**
 * Build the list of candidate directories to probe for tech-stack markers.
 *
 * - Always includes the workspace root.
 * - Includes one-level convention dirs (frontend, backend, web, …) when present.
 * - Includes each direct child of monorepo containers (apps/, packages/), capped at 12 per container.
 * - Skips anything in DIR_DENYLIST (node_modules, dist, .git, …).
 * - Hard-caps the returned list at 30 dirs.
 *
 * Exported for unit-test inspection.
 */
export function collectCandidateDirs(workspacePath: string): string[] {
  const root = resolve(workspacePath)
  const dirs: string[] = [root]

  const isUsableDir = (abs: string, name: string): boolean => {
    if (DIR_DENYLIST.has(name)) return false
    try {
      return statSync(abs).isDirectory()
    } catch {
      return false
    }
  }

  // 1. Convention dirs at depth 1.
  for (const name of CONVENTION_DIRS) {
    const abs = join(root, name)
    if (isUsableDir(abs, name)) dirs.push(abs)
  }

  // 2. Monorepo containers (apps/, packages/) — include each direct child.
  for (const container of MONOREPO_CONTAINER_DIRS) {
    const containerAbs = join(root, container)
    if (!isUsableDir(containerAbs, container)) continue
    let children: string[]
    try {
      children = readdirSync(containerAbs)
    } catch {
      continue
    }
    let added = 0
    for (const child of children) {
      if (added >= MAX_PER_CONTAINER) break
      const childAbs = join(containerAbs, child)
      if (isUsableDir(childAbs, child)) {
        dirs.push(childAbs)
        added++
      }
    }
  }

  // 3. Hard cap.
  if (dirs.length > MAX_CANDIDATE_DIRS) {
    detectLogger.info(
      `Candidate dirs capped: ${dirs.length} → ${MAX_CANDIDATE_DIRS} (workspace=${root})`
    )
    return dirs.slice(0, MAX_CANDIDATE_DIRS)
  }
  return dirs
}

function filePatternExists(dirPath: string, pattern: string): boolean {
  if (pattern.includes('*')) {
    // Glob pattern — check if any matching files exist in this dir.
    const ext = pattern.replace('*', '')
    try {
      const entries = readdirSync(dirPath)
      return entries.some((e) => e.endsWith(ext))
    } catch {
      return false
    }
  }

  // Check file or directory directly under this dir.
  return existsSync(join(dirPath, pattern))
}

/** Per-dir cache for package.json deps so each dir is parsed at most once per detection. */
function readPackageJsonDeps(dirPath: string, cache: Map<string, Set<string>>): Set<string> {
  const cached = cache.get(dirPath)
  if (cached) return cached

  const pkgPath = join(dirPath, 'package.json')
  if (!existsSync(pkgPath)) {
    const empty = new Set<string>()
    cache.set(dirPath, empty)
    return empty
  }

  try {
    const raw = readFileSync(pkgPath, 'utf-8')
    const pkg = JSON.parse(raw) as {
      dependencies?: Record<string, string>
      devDependencies?: Record<string, string>
    }
    const allDeps = new Set<string>()
    for (const dep of Object.keys(pkg.dependencies ?? {})) allDeps.add(dep)
    for (const dep of Object.keys(pkg.devDependencies ?? {})) allDeps.add(dep)
    cache.set(dirPath, allDeps)
    return allDeps
  } catch {
    const empty = new Set<string>()
    cache.set(dirPath, empty)
    return empty
  }
}

export function detectTechStack(workspacePath: string): TechStackResult {
  const detected = new Map<string, number>()
  const depsCache = new Map<string, Set<string>>()
  const candidates = collectCandidateDirs(workspacePath)

  for (const dir of candidates) {
    const perDirHits: string[] = []
    for (const marker of TECH_MARKERS) {
      let fileMatch = false
      for (const filePattern of marker.files) {
        if (filePatternExists(dir, filePattern)) {
          fileMatch = true
          break
        }
      }

      if (!fileMatch) continue

      // If marker requires checking deps inside package.json
      if (marker.deps && marker.deps.length > 0) {
        const deps = readPackageJsonDeps(dir, depsCache)
        const matchedDep = marker.deps.some((dep) => deps.has(dep))
        if (!matchedDep) continue
        // Higher confidence if dep explicitly found
        detected.set(marker.tech, Math.max(detected.get(marker.tech) ?? 0, 0.9))
        perDirHits.push(marker.tech)
      } else {
        // File marker only — slightly lower confidence
        detected.set(marker.tech, Math.max(detected.get(marker.tech) ?? 0, 0.7))
        perDirHits.push(marker.tech)
      }
    }
    if (perDirHits.length > 0) {
      detectLogger.debug(`[detect] ${dir} → ${perDirHits.join(', ')}`)
    }
  }

  const detectedTechs = Array.from(detected.keys())
  const confidence: Record<string, number> = {}
  for (const [tech, conf] of detected) {
    confidence[tech] = conf
  }

  // Project-Specialist world: recommend skills + MCPs scoped to the detected tech stack.
  const skillSet = new Set<string>()
  const mcpSet = new Set<string>()
  for (const tech of detectedTechs) {
    for (const s of TECH_TO_SKILL[tech] ?? []) skillSet.add(s)
    for (const m of TECH_TO_MCP[tech] ?? []) mcpSet.add(m)
  }

  const result: TechStackResult = {
    detectedTechs,
    recommendedSkills: Array.from(skillSet),
    recommendedMcps: Array.from(mcpSet),
    confidence
  }

  detectLogger.info(
    `Detected techs: ${detectedTechs.join(', ')} → skills: [${result.recommendedSkills.join(', ')}] mcps: [${result.recommendedMcps.join(', ')}] (scanned ${candidates.length} dirs)`
  )

  return result
}

/**
 * Regression guard for the SpecialistBuilder meta-prompt.
 *
 * After the v3 rewrite, the meta-prompt sent to `claude -p` must be a
 * "judgment layer" persona builder — first-person, under 400 words,
 * with explicit DETECTED STACK, REFERENCE-only CLAUDE.md, anti-redundancy
 * instructions (CRITICAL LAYERING CONTEXT), and a HARD RULES block.
 * This test pins those requirements so the prompt can't silently drift
 * back to fact-repeating or CLAUDE.md-duplicating patterns.
 */
import assert from 'node:assert/strict'
import { test, describe, summaryAsync } from './test-harness'
import { SpecialistBuilderService } from '../specialist-builder.service'

describe('SpecialistBuilder meta-prompt', () => {
  const builder = new SpecialistBuilderService()
  const sample = builder.buildMetaPrompt({
    workspaceName: 'Acme',
    detectedTechs: ['react', 'typescript'],
    claudeMdReference: '# Project: Acme\n\nReference content here.',
    skeleton:
      'You are the **Acme Specialist** — a senior engineer embedded in this codebase.\n\n## Your identity\n…'
  })

  test('contains_distillation_directives', () => {
    assert.ok(
      sample.includes('DO NOT quote'),
      'meta-prompt must instruct the LLM not to quote the reference'
    )
    assert.ok(
      sample.includes('FIRST PERSON'),
      'meta-prompt must require FIRST PERSON identity wording'
    )
    assert.ok(sample.includes('Under 400 words'), 'meta-prompt must impose the 400-word cap')
    assert.ok(sample.includes('HARD RULES'), 'meta-prompt must include the HARD RULES block')
    assert.ok(
      sample.includes('DETECTED STACK'),
      'meta-prompt must surface the detected stack to the LLM'
    )
    assert.ok(
      sample.includes('REFERENCE'),
      'meta-prompt must label the CLAUDE.md excerpt as REFERENCE'
    )
  })

  test('contains_anti_redundancy_instruction', () => {
    assert.ok(
      sample.includes('CRITICAL LAYERING CONTEXT'),
      'meta-prompt must explain the runtime layering to the LLM'
    )
    assert.ok(
      sample.includes('MUST NOT repeat'),
      'meta-prompt must explicitly forbid repeating CLAUDE.md facts'
    )
    assert.ok(
      sample.includes('JUDGMENT layer'),
      'meta-prompt must frame the job as writing the judgment layer'
    )
  })

  test('rejects_legacy_enriches_vocabulary', () => {
    // The previous meta-prompt told the LLM to "Enrich the project-specific sections" —
    // that wording produced bloated, structure-mirroring outputs and is now banned.
    assert.ok(
      !/Enriches the project-specific sections/i.test(sample),
      'legacy "Enriches the project-specific sections" wording must be gone'
    )
    assert.ok(
      !/SKELETON prompt for a workspace/i.test(sample),
      'legacy "SKELETON prompt for a workspace" wording must be gone'
    )
  })

  test('substitutes_workspace_name_and_techs', () => {
    assert.ok(sample.includes('Acme'), 'must include the workspace name')
    assert.ok(sample.includes('react, typescript'), 'must include detected techs joined')
  })

  test('falls_back_to_none_detected_when_techs_empty', () => {
    const empty = builder.buildMetaPrompt({
      workspaceName: 'Acme',
      detectedTechs: [],
      claudeMdReference: '',
      skeleton: 'skeleton'
    })
    assert.ok(
      empty.includes('(none detected)'),
      'must produce "(none detected)" when no techs are detected'
    )
  })

  test('mandatory_section_list_is_in_order', () => {
    // The meta-prompt asks for EXACTLY these sections, in order. Pin them so the
    // shape can't drift without an explicit test update.
    const idxIdentity = sample.indexOf('## Your identity')
    const idxHeuristics = sample.indexOf('## Decision heuristics')
    const idxInstincts = sample.indexOf('## Architecture instincts')
    const idxOutput = sample.indexOf('## Output style')
    assert.ok(idxIdentity >= 0, 'must mention ## Your identity')
    assert.ok(idxHeuristics > idxIdentity, '## Decision heuristics must come after identity')
    assert.ok(idxInstincts > idxHeuristics, '## Architecture instincts must come after heuristics')
    assert.ok(idxOutput > idxInstincts, '## Output style must come after instincts')
  })
})

