/**
 * Lightweight runtime validation for IPC handler arguments.
 *
 * Electron IPC hands us `unknown` from the renderer. TypeScript types at the
 * call site give us compile-time guarantees, but the main process is still a
 * security boundary — a malformed renderer call (or an attacker with access to
 * DevTools) would previously forward garbage directly into the SDK and produce
 * obscure failures.
 *
 * These helpers surface clear errors the moment a required field is missing or
 * has the wrong type, and they live in one place so every IPC module validates
 * the same way.
 */

/**
 * Narrow `unknown` to a non-null plain object, throwing otherwise.
 * Use this as the entry gate before calling field-level validators.
 */
export function requireObject(args: unknown, channel: string): Record<string, unknown> {
  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
    throw new Error(`${channel}: expected an object argument, got ${describe(args)}`)
  }
  return args as Record<string, unknown>
}

/**
 * Assert that `obj` has `field` as a non-empty string and return it.
 */
export function requireString(
  obj: Record<string, unknown>,
  field: string,
  channel: string
): string {
  const value = obj[field]
  if (typeof value !== 'string' || value.length === 0) {
    throw new Error(`${channel}: field '${field}' must be a non-empty string`)
  }
  return value
}

/**
 * Assert that `obj[field]` is either a string or absent. Returns `undefined`
 * when the field is missing. Throws if present but not a string.
 */
export function optionalString(
  obj: Record<string, unknown>,
  field: string,
  channel: string
): string | undefined {
  const value = obj[field]
  if (value === undefined) return undefined
  if (typeof value !== 'string') {
    throw new Error(`${channel}: field '${field}' must be a string when provided`)
  }
  return value
}

/**
 * Assert that `obj[field]` is either a finite number or absent.
 */
export function optionalNumber(
  obj: Record<string, unknown>,
  field: string,
  channel: string
): number | undefined {
  const value = obj[field]
  if (value === undefined) return undefined
  if (typeof value !== 'number' || !Number.isFinite(value)) {
    throw new Error(`${channel}: field '${field}' must be a finite number when provided`)
  }
  return value
}

/**
 * Assert that `obj[field]` is either a boolean or absent.
 */
export function optionalBoolean(
  obj: Record<string, unknown>,
  field: string,
  channel: string
): boolean | undefined {
  const value = obj[field]
  if (value === undefined) return undefined
  if (typeof value !== 'boolean') {
    throw new Error(`${channel}: field '${field}' must be a boolean when provided`)
  }
  return value
}

/**
 * Assert that `obj[field]` is a string, null, or absent. Returns the value
 * (including null) when present.
 */
export function optionalNullableString(
  obj: Record<string, unknown>,
  field: string,
  channel: string
): string | null | undefined {
  const value = obj[field]
  if (value === undefined) return undefined
  if (value === null) return null
  if (typeof value !== 'string') {
    throw new Error(`${channel}: field '${field}' must be a string, null, or omitted`)
  }
  return value
}

/**
 * Assert that `obj[field]` is a non-empty array of strings.
 */
export function requireStringArray(
  obj: Record<string, unknown>,
  field: string,
  channel: string
): string[] {
  const value = obj[field]
  if (!Array.isArray(value) || value.length === 0) {
    throw new Error(`${channel}: field '${field}' must be a non-empty array`)
  }
  for (let i = 0; i < value.length; i++) {
    if (typeof value[i] !== 'string') {
      throw new Error(`${channel}: field '${field}[${i}]' must be a string`)
    }
  }
  return value as string[]
}

/**
 * Assert that `obj[field]` is a plain object (not array, not null).
 * Returns the value narrowed to `Record<string, unknown>`.
 */
export function requirePlainObject(
  obj: Record<string, unknown>,
  field: string,
  channel: string
): Record<string, unknown> {
  const value = obj[field]
  if (value === null || value === undefined || typeof value !== 'object' || Array.isArray(value)) {
    throw new Error(`${channel}: field '${field}' must be a plain object`)
  }
  return value as Record<string, unknown>
}

function describe(value: unknown): string {
  if (value === null) return 'null'
  if (Array.isArray(value)) return 'array'
  return typeof value
}

/**
 * Role-tagging guard for ChatStreamService persistence.
 *
 * The plan ("Fix bubble identity drift + auto-swap + role-tagging alignment")
 * required chat-stream.service to write the active adapter's role + agentId to
 * messageRepository.create() instead of hardcoding a role. This test pins
 * the contract by:
 *
 *   1. Verifying the ChatAgentService accessors return the correct
 *      (messageRole, agentId) for each adapter type.
 *   2. Verifying the DB schema accepts and round-trips role='specialist' rows
 *      with a workspace-specialist-<wsId> agent_id (the values chat-stream
 *      now passes through).
 */
import assert from 'node:assert/strict'
import { test, describe, summaryAsync } from './test-harness'
import { chatAgentService } from '../chat-agent.service'
import { ProjectSpecialistRoleAdapter } from '../role-adapters/project-specialist.adapter'
import { trySetupTestDb } from '../../db/repositories/__tests__/db-test-helper'

describe('ChatStreamService role tagging', () => {
  test('getActiveMessageRole_returns_specialist_when_no_session', () => {
    // When no workspace session is active, getActiveMessageRole() returns 'specialist'.
    const svc = chatAgentService as unknown as { _activeWorkspaceId: string | null }
    const originalActiveId = svc._activeWorkspaceId
    svc._activeWorkspaceId = null
    try {
      assert.equal(chatAgentService.getActiveMessageRole(), 'specialist')
      assert.equal(chatAgentService.getActiveAgentId(), 'specialist')
    } finally {
      svc._activeWorkspaceId = originalActiveId
    }
  })

  test('getActiveMessageRole_returns_specialist_for_ProjectSpecialistRoleAdapter', () => {
    const adapter = new ProjectSpecialistRoleAdapter({ workspaceId: 'ws-xyz' })
    // Inject via the sessions map + _activeWorkspaceId so getActiveAdapter() resolves it.
    const svc = chatAgentService as unknown as {
      sessions: Map<
        string,
        { adapter: unknown; session: unknown; forwarderCleanups: unknown[]; workspacePath: string }
      >
      _activeWorkspaceId: string | null
    }
    const originalActiveId = svc._activeWorkspaceId
