describe('Lean Conditional Gating', () => {
  test('lean mode includes unified memory protocol prompt on turn 1', () => {
    const out = buildConditionalPrefix({
      message: 'remember this preference for future sessions',
      hasImages: false,
      mode: 'plan',
      turnCount: 1,
      model: 'claude-opus-4-8'
    })
    // W2: full and lean unified — both include the same type taxonomy prompt
    assert.ok(out.includes('mcp__memory__memory_search'), 'Lean mode should include memory tools prompt on turn 1')
  })

  test('full mode includes memory protocol prompt', () => {
    const out = buildConditionalPrefix({
      message: 'remember this preference for future sessions',
      hasImages: false,
      mode: 'plan',
      turnCount: 1,
      model: 'claude-haiku-4-5-20251001'
    })
    // W2: full and lean are now unified — check for content present in the unified prompt
    assert.ok(out.includes('mcp__memory__memory_search'), 'Full mode should include memory tools prompt')
  })

  test('lean mode uses compressed direct-answer boost on turn 3+', () => {
    const out = buildConditionalPrefix({
      message: 'what does this function do?',
      hasImages: false,
      mode: 'build',
      turnCount: 3,
      model: 'claude-opus-4-8'
    })
    // Lean should use the compressed variant
    assert.ok(out.includes('Answer from context'), 'Lean should use compressed direct-answer boost')
    assert.ok(
      !out.includes('Answer-Complete Rule'),
      'Lean should not contain verbose Answer-Complete section'
    )
  })

  test('full mode uses compressed direct-answer boost on turn 3+', () => {
    const out = buildConditionalPrefix({
      message: 'what does this function do?',
      hasImages: false,
      mode: 'build',
      turnCount: 3,
      model: 'claude-haiku-4-5-20251001'
    })
    // W2: full variant compressed — no more verbose "Answer-Complete Rule" subsection
    assert.ok(
      out.includes('STOP'),
      'Full mode should contain STOP rule for direct answers'
    )
  })

  test('lean mode tightens ask-question regex', () => {
    // "which file" should NOT trigger ask_user in lean mode (too broad)
    const leanSections = promptBuilder.getGeneralistConditionalSections(
      'which file has the bug?',
      false,
      'lean'
    )
    assert.ok(
      !leanSections.includeAskQuestionPrompt,
      'Lean should not trigger ask_user for broad "which" queries'
    )

    // But "choose between" should still trigger
    const leanSections2 = promptBuilder.getGeneralistConditionalSections(
      'should I choose between React and Vue?',
      false,
      'lean'
    )
    assert.ok(
      leanSections2.includeAskQuestionPrompt,
      'Lean should trigger ask_user for explicit "choose between"'
    )
  })

  test('full mode keeps broad ask-question regex', () => {
    const fullSections = promptBuilder.getGeneralistConditionalSections(
      'which file has the bug?',
      false,
      'full'
    )
    assert.ok(
      fullSections.includeAskQuestionPrompt,
      'Full should trigger ask_user for broad "which" queries'
    )
  })
})

/**
 * Lean Identity Prompt — verifies the compressed specialist identity prompt
 * for Opus 4.8+ models preserves key structure while being significantly shorter.
 *
 * Pure logic: no filesystem, no network, no real Electron dependencies.
 */
import assert from 'node:assert/strict'
import { test, describe } from './test-harness'
import { buildSpecialistIdentityPrompt, buildSpecialistIdentityPromptLean } from '../default-prompts'

describe('Lean Identity Prompt', () => {
  test('lean prompt length is within 25% of full prompt', () => {
    const full = buildSpecialistIdentityPrompt('default')
    const lean = buildSpecialistIdentityPromptLean('default')
    // After trimming, the "full" prompt became very compact. Lean retains
    // slightly more detail for small-context models (including inline Code
    // Exploration guidance with fully-qualified MCP tool names). Either being
    // shorter is acceptable — the important invariant is they stay close.
    const ratio = lean.length / full.length
    assert.ok(
      ratio < 1.45,
      `Lean/full ratio (${ratio.toFixed(2)}) exceeds 45% — lean=${lean.length} full=${full.length}`
    )
  })

  test('lean prompt includes all structural sections', () => {
    const lean = buildSpecialistIdentityPromptLean('default')
    assert.ok(lean.includes('## Style'), 'Missing ## Style section')
    assert.ok(lean.includes('## Tool Usage'), 'Missing ## Tool Usage section')
    assert.ok(lean.includes('## Code Exploration'), 'Missing ## Code Exploration section')
    assert.ok(lean.includes('## Structured Actions'), 'Missing ## Structured Actions section')
    assert.ok(lean.includes('emit_plan'), 'Missing emit_plan reference')
    assert.ok(lean.includes('ask_user'), 'Missing ask_user reference')
    assert.ok(lean.includes('mcp__memory__memory_search'), 'Missing memory_search reference')
  })

  test('lean prompt preserves all 5 tones', () => {
    const tones = ['default', 'calm', 'optimistic', 'brutal', 'caveman'] as const
    for (const tone of tones) {
      const lean = buildSpecialistIdentityPromptLean(tone)
      assert.ok(lean.includes('## Style'), `Missing ## Style for tone=${tone}`)
      // Each tone should produce a different style directive
      assert.ok(lean.length > 200, `Lean prompt too short for tone=${tone}`)
    }
  })

  test('lean prompt omits verbose labels present in full prompt', () => {
    const lean = buildSpecialistIdentityPromptLean('default')
    // Lean should NOT have the verbose MANDATORY/CRITICAL labels
    assert.ok(!lean.includes('(MANDATORY)'), 'Lean prompt should not contain (MANDATORY)')
    assert.ok(!lean.includes('(CRITICAL)'), 'Lean prompt should not contain (CRITICAL)')
    assert.ok(!lean.includes('(IMPORTANT)'), 'Lean prompt should not contain (IMPORTANT)')
  })

  test('full prompt retains verbose labels', () => {
    const full = buildSpecialistIdentityPrompt('default')
    assert.ok(full.includes('(MANDATORY)'), 'Full prompt should contain (MANDATORY)')
  })

  test('lean identity includes Code Exploration rules from repomap merge', () => {
    const lean = buildSpecialistIdentityPromptLean('default')
    assert.ok(lean.includes('file_outline'), 'Missing file_outline guidance (merged from repomap)')
    assert.ok(
      lean.includes('coupling_analysis'),
      'Missing coupling_analysis guidance (merged from repomap)'
    )
    assert.ok(lean.includes('find_callers'), 'Missing find_callers guidance')
    assert.ok(lean.includes('file_dependents'), 'Missing file_dependents guidance')
  })

  test('full prompt does NOT include ## Tool Priority (injected separately via appendMcpToolGuidance)', () => {
    const full = buildSpecialistIdentityPrompt('default')
    assert.ok(
      !full.includes('## Tool Priority'),
      'Full prompt should NOT include ## Tool Priority — it is injected by appendMcpToolGuidance'
    )
  })
})

/**
 * Lean Mode Blocks — verifies compressed per-message mode context blocks
 * for Opus 4.8+ preserve key behavioral rules while being significantly shorter.
 *
 * Pure logic: no filesystem, no network, no real Electron dependencies.
 */
import assert from 'node:assert/strict'
import { test, describe } from './test-harness'
import {
  PLAN_MODE_SECTION,
  PLAN_MODE_SECTION_LEAN,
  BUILD_MODE_SECTION,
  BUILD_MODE_SECTION_LEAN,
  DANGER_MODE_SECTION,
  DANGER_MODE_SECTION_LEAN
} from '../default-prompts'

describe('Lean Mode Blocks', () => {
  test('lean plan is shorter than full plan', () => {
    assert.ok(PLAN_MODE_SECTION_LEAN.length < PLAN_MODE_SECTION.length)
    assert.ok(
      PLAN_MODE_SECTION_LEAN.length < PLAN_MODE_SECTION.length * 0.90,
      `Lean plan (${PLAN_MODE_SECTION_LEAN.length}) should be <90% of full (${PLAN_MODE_SECTION.length})`
    )
  })

  test('lean build is shorter than full build', () => {
    assert.ok(
      BUILD_MODE_SECTION_LEAN.length < BUILD_MODE_SECTION.length,
      `Lean build (${BUILD_MODE_SECTION_LEAN.length}) should be shorter than full (${BUILD_MODE_SECTION.length})`
    )
  })

  test('lean danger is shorter than full danger', () => {
    assert.ok(DANGER_MODE_SECTION_LEAN.length < DANGER_MODE_SECTION.length)
    assert.ok(
      DANGER_MODE_SECTION_LEAN.length < DANGER_MODE_SECTION.length * 0.7,
      `Lean danger (${DANGER_MODE_SECTION_LEAN.length}) should be <70% of full (${DANGER_MODE_SECTION.length})`
    )
  })

  test('lean plan preserves key structural sections', () => {
    assert.ok(PLAN_MODE_SECTION_LEAN.includes('emit_plan'), 'Missing emit_plan reference')
    assert.ok(PLAN_MODE_SECTION_LEAN.includes('type'), 'Missing type field reference')
    assert.ok(PLAN_MODE_SECTION_LEAN.includes('diagrams'), 'Missing diagrams reference')
    assert.ok(
      PLAN_MODE_SECTION_LEAN.includes('Operational Requests'),
      'Missing Operational Requests'
    )
    assert.ok(PLAN_MODE_SECTION_LEAN.includes('read-only'), 'Missing read-only indicator')
    assert.ok(PLAN_MODE_SECTION_LEAN.includes('Phased Plans'), 'Missing Phased Plans section')
  })

  test('lean build preserves safety rules', () => {
    assert.ok(BUILD_MODE_SECTION_LEAN.includes('STOP'), 'Missing STOP rules')
    assert.ok(BUILD_MODE_SECTION_LEAN.includes('Destructive'), 'Missing Destructive command rule')
    assert.ok(BUILD_MODE_SECTION_LEAN.includes('approval'), 'Missing approval requirement')
    assert.ok(BUILD_MODE_SECTION_LEAN.includes('Tool Errors'), 'Missing Tool Errors section')
    assert.ok(BUILD_MODE_SECTION_LEAN.includes('typecheck'), 'Missing typecheck requirement')
    assert.ok(BUILD_MODE_SECTION_LEAN.includes('ask_user'), 'Missing ask_user for ambiguity')
  })

  test('lean danger preserves safety boundaries', () => {
    assert.ok(DANGER_MODE_SECTION_LEAN.includes('isolated'), 'Missing isolation caveat')
    assert.ok(DANGER_MODE_SECTION_LEAN.includes('STOP'), 'Missing STOP rules reference')
    assert.ok(DANGER_MODE_SECTION_LEAN.includes('typecheck'), 'Missing typecheck requirement')
  })

  test('lean build preserves error recovery guidance', () => {
    assert.ok(
      BUILD_MODE_SECTION_LEAN.includes('re-read'),
      'Missing re-read guidance for stale file errors'
    )
    assert.ok(
      BUILD_MODE_SECTION_LEAN.includes('EACCES'),
      'Missing EACCES permission check reference'
    )
  })

  test('full plan forbids Write/Edit for authoring a plan', () => {
    assert.ok(
      /never\s+call\s+write\s+or\s+edit/i.test(PLAN_MODE_SECTION),
      'Full plan should forbid Write/Edit for authoring a plan'
    )
    assert.ok(
      PLAN_MODE_SECTION.includes('emit_plan'),
      'Full plan should point to emit_plan as the only plan output path'
    )
  })

  test('lean plan forbids Write/Edit for a plan', () => {
    assert.ok(
      /write\/edit/i.test(PLAN_MODE_SECTION_LEAN),
      'Lean plan should mention Write/Edit are blocked for plans'
    )
    assert.ok(PLAN_MODE_SECTION_LEAN.includes('emit_plan'), 'Lean plan should point to emit_plan')
  })

  test('lean plan preserves all plan types', () => {
    assert.ok(PLAN_MODE_SECTION_LEAN.includes('bug'), 'Missing bug plan type')
    assert.ok(PLAN_MODE_SECTION_LEAN.includes('feature'), 'Missing feature plan type')
    assert.ok(PLAN_MODE_SECTION_LEAN.includes('refactor'), 'Missing refactor plan type')
    assert.ok(PLAN_MODE_SECTION_LEAN.includes('audit'), 'Missing audit plan type')
    assert.ok(PLAN_MODE_SECTION_LEAN.includes('investigation'), 'Missing investigation plan type')
  })
})

