  })

  test('uses last block when multiple blocks are emitted', () => {
    const text = `First attempt:
\`\`\`grill-plan
{
  "version": 1,
  "title": "Old Plan",
  "summary": "Old",
  "goalType": "feature",
  "decisions": [],
  "items": [{"id": "x", "title": "x", "description": "x", "scope": "backend", "files": [], "dependsOn": [], "includesTests": false}],
