describe('AgentStreamProcessor.processContentChunk', () => {
  const ctx = { conversationId: 'c1', isBuildMode: true, streamState: {} as never }

  test('text chunk accumulates and returns next', () => {
    const host = makeHost()
    const proc = new AgentStreamProcessor(host)
