/**
 * GrillAgentService — multi-workspace standalone evaluator for the Grill feature.
 *
 * Maintains a Map<workspaceId, GrillSession> so evaluations can run concurrently
 * across different workspaces. Single-shot per workspace: one evaluation per
 * invocation, streams directly to the renderer via events.
 *
 * Events are tagged with workspaceId so the IPC layer can route them correctly.
 */

import { EventEmitter } from 'node:events'
import log from 'electron-log'
import type { GrillTrackId, GrillEvaluation, AgentStatus } from '../../shared/types'
import type { StreamChunk } from './agent-base.service'
import { AgentSessionService } from './agent-session.service'
import { GrillRoleAdapter } from './role-adapters/grill.adapter'
import { GreenfieldGrillRoleAdapter } from './role-adapters/greenfield-grill.adapter'

const grillLog = log.scope('grill-agent')

interface GrillSession {
  session: AgentSessionService
  running: boolean
  /** GRILL-GREENFIELD-CANCEL-ALWAYS-01: Track workspaceId for targeted cancel of greenfield sessions. */
  workspaceId?: string
  /** Per-conversation cancel: track the syntheticConvId used for send(). */
  lastConversationId?: string
}

// ── Service ────────────────────────────────────────────────────────────────

export class GrillAgentService extends EventEmitter {
  private sessions = new Map<string, GrillSession>()
  /** Greenfield evaluations don't have a workspace — use a synthetic key. */
  private greenfieldSession: GrillSession | null = null

  /** Check if ANY evaluation is running (backward compat). */
  get isRunning(): boolean {
    if (this.greenfieldSession?.running) return true
    for (const entry of this.sessions.values()) {
      if (entry.running) return true
    }
    return false
  }

  /** Check if a specific workspace has a running evaluation. */
  isRunningForWorkspace(workspaceId: string): boolean {
    return this.sessions.get(workspaceId)?.running ?? false
  }

  /**
   * Run a single grill evaluation for a workspace.
   * Emits: 'stream' (chunk), 'evaluation' (parsed result), 'complete' — all tagged with workspaceId.
   */
  async evaluate(params: {
    workspaceId: string
    workspacePath: string
    trackId: GrillTrackId
    ideaTitle: string
    ideaDescription: string
    iterationHistory?: string
    previousScore?: number
    llmProvider?: import('../../shared/types').LLMProvider
  }): Promise<void> {
    grillLog.info(
      `[grill] evaluate called — track=${params.trackId} workspace=${params.workspaceId}`
    )

    if (this.sessions.get(params.workspaceId)?.running) {
      grillLog.warn(`[grill] Already running for workspace ${params.workspaceId} — ignoring`)
      return
    }

    const adapter = new GrillRoleAdapter({
      workspaceId: params.workspaceId,
      trackId: params.trackId,
      ideaTitle: params.ideaTitle,
      ideaDescription: params.ideaDescription,
      iterationHistory: params.iterationHistory,
      previousScore: params.previousScore,
      llmProvider: params.llmProvider
    })

    const session = new AgentSessionService(adapter)
    const entry: GrillSession = { session, running: true }
    this.sessions.set(params.workspaceId, entry)

    // Wire streaming events for live output — tagged with workspaceId
    session.on('chunk', (chunk: StreamChunk) => {
      // GRILL-CANCEL-STREAM-LEAK-01: Skip chunks after cancel. The CLI process
      // may still emit events for up to 5s after cancelCurrentQuery() sends SIGTERM.
      if (!entry.running) return
      this.emit('stream', { workspaceId: params.workspaceId, chunk })
    })

    // Re-emit inner-session status (token/context counters) so the live token
    // usage modal reflects grill activity, not just chat.
    session.on('statusUpdate', (status: AgentStatus) => {
      if (!entry.running) return
      this.emit('status', { workspaceId: params.workspaceId, status })
    })

    try {
      // Start session in plan mode (read-only)
      await session.start(params.workspacePath, 'plan')

      // Single-shot: send the evaluation trigger
      const syntheticConvId = `grill-${params.trackId}-${Date.now()}`
      entry.lastConversationId = syntheticConvId
      const effectiveMessage = params.iterationHistory
        ? `Re-evaluate based on updated decisions:\n\n${params.iterationHistory}`
        : 'Begin your evaluation.'
      await session.send(effectiveMessage, syntheticConvId, [])

      // Collect the full response and parse evaluation
      const responseText = session.getStreamedContent(syntheticConvId)
      const evaluation = this.parseGrillEvaluation(responseText)

      // GRILL-CANCEL-RACE-01: Only emit evaluation if not cancelled during send()
      if (evaluation && entry.running) {
        grillLog.info(`[grill:${params.trackId}] completed — score=${evaluation.score}`)
        this.emit('evaluation', { workspaceId: params.workspaceId, ...evaluation })
      } else if (!entry.running) {
        grillLog.info(`[grill:${params.trackId}] cancelled — skipping evaluation emit`)
      } else {
        grillLog.warn(`[grill:${params.trackId}] completed but no grill-evaluation block found`)
      }
    } catch (err) {
      grillLog.error(`[grill:${params.trackId}] failed:`, err)
    } finally {
      try {
        await session.stop()
      } catch (e) {
        grillLog.debug('[grill] session.stop() cleanup failed (non-fatal):', e)
      }
      // GRILL-EVAL-NOCOMPL-01: Always emit 'complete' so the persistence controller
      // can clean up tracking state (flush timers, active session map). Pass cancelled
      // flag so listeners can distinguish normal completion from cancellation.
      const wasCancelled = !entry.running
      entry.running = false
      this.sessions.delete(params.workspaceId)
      this.emit('complete', { workspaceId: params.workspaceId, cancelled: wasCancelled })
    }
  }

  /**
   * Run a greenfield grill evaluation (for new project ideas — no workspace/code).
   * Emits: 'stream' (chunk), 'evaluation' (parsed result), 'complete'
   */
  async evaluateGreenfield(params: {
    trackId: GrillTrackId
    projectName: string
    projectDescription: string
    iterationHistory?: string
    previousScore?: number
    llmProvider?: import('../../shared/types').LLMProvider
    /** GRILL-04: Synthetic workspaceId for event routing in multi-window mode. */
    workspaceId?: string
  }): Promise<void> {
    grillLog.info(
      `[grill] evaluateGreenfield called — track=${params.trackId} project="${params.projectName}"`
    )

    if (this.greenfieldSession?.running) {
      grillLog.warn('[grill] Greenfield already running — ignoring duplicate start')
      return
    }

    const adapter = new GreenfieldGrillRoleAdapter({
      trackId: params.trackId,
      projectName: params.projectName,
      projectDescription: params.projectDescription,
      iterationHistory: params.iterationHistory,
      previousScore: params.previousScore,
      llmProvider: params.llmProvider
    })

    const session = new AgentSessionService(adapter)
    // GRILL-04: Include workspaceId in all greenfield events for correct routing
    const wsId = params.workspaceId

    // GRILL-GREENFIELD-CANCEL-ALWAYS-01: Store workspaceId so cancel(wsId) can
    // verify it matches before cancelling an unrelated greenfield evaluation.
    const greenfieldEntry: GrillSession = { session, running: true, workspaceId: wsId }
    this.greenfieldSession = greenfieldEntry

    // Wire streaming events for live output
    session.on('chunk', (chunk: StreamChunk) => {
      // GRILL-CANCEL-STREAM-LEAK-01: Skip chunks after cancel.
      if (!greenfieldEntry.running) return
      this.emit('stream', { workspaceId: wsId, chunk })
    })

    // Wire status updates so the modal's live counters move during a greenfield grill.
    session.on('statusUpdate', (status: AgentStatus) => {
      if (!greenfieldEntry.running) return
      this.emit('status', { workspaceId: wsId, status })
    })

    try {
      // Use OS temp dir as working directory (no workspace exists yet)
      const os = await import('node:os')
      const workDir = os.tmpdir()

      await session.start(workDir, 'plan')

      const syntheticConvId = `greenfield-grill-${params.trackId}-${Date.now()}`
      greenfieldEntry.lastConversationId = syntheticConvId
      const effectiveMessage = params.iterationHistory
        ? `Re-evaluate based on updated decisions:\n\n${params.iterationHistory}`
        : 'Begin your evaluation.'
      await session.send(effectiveMessage, syntheticConvId, [])

      const responseText = session.getStreamedContent(syntheticConvId)
      const evaluation = this.parseGrillEvaluation(responseText)

      // GRILL-CANCEL-RACE-01: Only emit evaluation if not cancelled during send()
      if (evaluation && greenfieldEntry.running) {
        grillLog.info(`[grill:greenfield:${params.trackId}] completed — score=${evaluation.score}`)
        this.emit('evaluation', { workspaceId: wsId, ...evaluation })
      } else if (!greenfieldEntry.running) {
        grillLog.info(`[grill:greenfield:${params.trackId}] cancelled — skipping evaluation emit`)
      } else {
        grillLog.warn(
          `[grill:greenfield:${params.trackId}] completed but no grill-evaluation block found`
        )
      }
    } catch (err) {
      grillLog.error(`[grill:greenfield:${params.trackId}] failed:`, err)
    } finally {
      try {
        await this.greenfieldSession.session.stop()
      } catch (e) {
        grillLog.debug('[grill:greenfield] session.stop() cleanup failed (non-fatal):', e)
      }
      // GRILL-EVAL-NOCOMPL-01: Always emit 'complete' so persistence controller cleans up.
      const wasCancelled = !greenfieldEntry.running
      this.greenfieldSession = null
      this.emit('complete', { workspaceId: wsId, cancelled: wasCancelled })
    }
  }

  /** Cancel the running evaluation for a specific workspace. */
  cancel(workspaceId?: string): void {
    grillLog.info(`[grill] Cancel requested${workspaceId ? ` for workspace ${workspaceId}` : ''}`)

    if (workspaceId) {
      const entry = this.sessions.get(workspaceId)
      if (entry?.session) {
        try {
          entry.session.cancelCurrentQuery(entry.lastConversationId)
        } catch (e) {
          grillLog.debug('[grill] cancelCurrentQuery() failed (non-fatal):', e)
        }
        entry.running = false
      }
      // GRILL-GREENFIELD-CANCEL-ALWAYS-01: Only cancel greenfield if its workspaceId
      // matches the cancel target. Previously, any workspace cancel would kill an
      // unrelated greenfield evaluation.
      if (this.greenfieldSession?.running && this.greenfieldSession.workspaceId === workspaceId) {
        try {
          this.greenfieldSession.session.cancelCurrentQuery(this.greenfieldSession.lastConversationId)
        } catch (e) {
          grillLog.debug('[grill:greenfield] cancelCurrentQuery() failed (non-fatal):', e)
        }
        this.greenfieldSession.running = false
      }
    } else {
      // Cancel all (backward compat)
      for (const [, entry] of this.sessions) {
        try {
          entry.session.cancelCurrentQuery(entry.lastConversationId)
        } catch (e) {
          grillLog.debug('[grill] cancelCurrentQuery() failed (non-fatal):', e)
        }
        entry.running = false
      }
      if (this.greenfieldSession?.session) {
        try {
          this.greenfieldSession.session.cancelCurrentQuery(this.greenfieldSession.lastConversationId)
        } catch (e) {
          grillLog.debug('[grill:greenfield] cancelCurrentQuery() failed (non-fatal):', e)
        }
        this.greenfieldSession.running = false
      }
    }
  }

  // ── Private: parse grill-evaluation from response ──────────────────

  private parseGrillEvaluation(text: string): GrillEvaluation | null {
    const regex = /```grill-evaluation\n([\s\S]*?)```/g
    let lastMatch: RegExpExecArray | null = null
    let match: RegExpExecArray | null

    // Use the last match in case the agent emits multiple blocks
    while ((match = regex.exec(text)) !== null) {
      lastMatch = match
    }

    if (!lastMatch) return null

    try {
      const parsed = JSON.parse(lastMatch[1]) as GrillEvaluation
      // GRILL-SCORE-RANGE-01: Validate required fields AND score range (0–10, finite)
      if (
        typeof parsed.score !== 'number' ||
        !Number.isFinite(parsed.score) ||
        parsed.score < 0 ||
        parsed.score > 10 ||
        !Array.isArray(parsed.questions) ||
        parsed.questions.length === 0
      ) {
        grillLog.warn('[grill] Parsed grill-evaluation has invalid structure or out-of-range score')
        return null
      }
      return parsed
    } catch (err) {
      grillLog.error('[grill] Failed to parse grill-evaluation JSON:', err)
      return null
    }
  }
  /** Graceful shutdown — cancel all evaluations and clear sessions. Called on app quit. */
  async shutdown(): Promise<void> {
    grillLog.info(`[grill] Shutdown initiated — ${this.sessions.size} active sessions`)
    this.cancel() // Cancels all sessions
    this.sessions.clear()
    this.greenfieldSession = null
  }
}

export const grillAgentService = new GrillAgentService()

/**
 * GrillRoleAdapter — drives AgentSessionService for a single grill evaluation.
 *
 * Key differences vs. chat adapters:
 *   - Single-shot: one message ("Begin your evaluation.") → one response → done.
 *   - Read-only: write tools are explicitly disallowed.
 *   - No personas, no control-tool callbacks.
 *   - Always runs in 'plan' mode (no build mode).
 *   - Longer interaction timeout (10 min per evaluation).
 *   - MCP servers mounted: code-graph + semantic-search + git-context + code-analysis (NO control-actions).
 *   - Uses intentDetector.detectAll() to find grill-evaluation regex blocks.
 */

import type { GrillTrackId } from '../../../shared/types'
import type {
  AdapterPromptContext,
  AdapterPromptResult,
  AdapterSessionLifecycleCtx
} from '../agent-session.types'
import { GRILL_TRACKS } from '../../../shared/constants'
import { BaseRoleAdapter, type McpStrategy } from './base.adapter'
import {
  buildReEvalBlock,
  buildGrillEvaluationSchema,
  buildGrillEvaluationSchemaLean,
  GRILL_QUESTION_QUALITY_RULES,
  GRILL_QUESTION_QUALITY_RULES_LEAN,
  GRILL_SCORING_RULES,
  GRILL_SCORING_RULES_LEAN,
  isGrillLean
} from './grill-prompt-blocks'
import { sanitizePromptInput } from '../sanitize-prompt-input'

export class GrillRoleAdapter extends BaseRoleAdapter {
  readonly role = 'grill' as const
  readonly agentId: string
  interactionTimeoutMs = 10 * 60_000 // 10 min per evaluation (adjusted for local LLMs in onSessionStart)

  private readonly workspaceId: string
  private readonly trackId: GrillTrackId
  private readonly ideaTitle: string
  private readonly ideaDescription: string
  private readonly iterationHistory?: string
  private readonly previousScore?: number

  private readonly llmProvider: import('../../../shared/types').LLMProvider

  private systemPrompt: string | null = null

  constructor(params: {
    workspaceId: string
    trackId: GrillTrackId
    ideaTitle: string
    ideaDescription: string
    iterationHistory?: string
    previousScore?: number
    llmProvider?: import('../../../shared/types').LLMProvider
  }) {
    super()
    this.workspaceId = params.workspaceId
    this.trackId = params.trackId
    this.ideaTitle = params.ideaTitle
    this.ideaDescription = params.ideaDescription
    this.iterationHistory = params.iterationHistory
    this.previousScore = params.previousScore
    this.llmProvider = params.llmProvider ?? 'claude'
    this.agentId = `grill-${params.trackId}-${params.workspaceId}`
  }

  override async onSessionStart(ctx: AdapterSessionLifecycleCtx): Promise<void> {
    // Pattern 2: Centralized workspace feature flag refresh
    this.refreshWorkspaceFeatureFlags(this.workspaceId)

    // Pattern 3: Centralized local LLM timeout
    this.applyLocalLlmTimeout(this.llmProvider)

    const track = GRILL_TRACKS[this.trackId]

    // Pattern 1: Centralized model resolution
    const resolvedModel = this.resolveModel(ctx.workspacePath, 'grill')

    this.systemPrompt = this.buildSystemPrompt(track, resolvedModel)

    // Append MCP tool guidance via base class helper
    this.systemPrompt = this.appendToolGuidance(this.systemPrompt, 1, resolvedModel)

    this.log.info(`[grill-adapter] ${this.trackId} grill started for workspace=${this.workspaceId}`)
  }

  buildPrompts(_ctx: AdapterPromptContext): AdapterPromptResult {
    if (!this.systemPrompt) {
      throw new Error(
        `GrillRoleAdapter.buildPrompts() called before onSessionStart() for track=${this.trackId}`
      )
    }

    let effectiveMessage: string
    if (this.iterationHistory) {
      effectiveMessage = `Re-evaluate based on updated decisions:\n\n${this.iterationHistory}`
    } else {
      effectiveMessage = 'Begin your evaluation.'
    }

    return {
      systemPrompt: this.systemPrompt,
      effectiveMessage
    }
  }

  protected override getMcpStrategy(): McpStrategy {
    return 'readonly'
  }
  protected override getIncludeGitContext(): boolean {
    return this.llmProvider !== 'local-llm'
  }


  override onSessionStop(): void {
    this.systemPrompt = null
    this.repomapEnabled = true
    this.semanticSearchEnabled = true
  }

  // ── Private: prompt construction ───────────────────────────────────

  private buildSystemPrompt(track: (typeof GRILL_TRACKS)[GrillTrackId], model?: string): string {
    const lean = isGrillLean(model)
    const reEvalBlock = buildReEvalBlock(this.previousScore)

    const evaluationSchema = lean
      ? buildGrillEvaluationSchemaLean(this.trackId)
      : buildGrillEvaluationSchema(this.trackId)

    const questionRules = lean ? GRILL_QUESTION_QUALITY_RULES_LEAN : GRILL_QUESTION_QUALITY_RULES

    const scoringRules = lean ? GRILL_SCORING_RULES_LEAN : GRILL_SCORING_RULES

    // Lean: compressed instructions — Opus narrates naturally and uses tools-first from schema
    const instructions = lean
      ? `## Instructions
0. Narrate your process — explain what you're checking and why before each tool call.
1. Use Code Graph + Code Analysis tools FIRST (≥1 each) before Read/Grep.
2. No broad codebase scans or documentation reads.
3. Analyze the requirement against each criterion.
4. Provide markdown analysis of gaps.
5. ${evaluationSchema}`
      : `## Instructions
0. **Narrate your process.** Before each tool call, write a brief sentence explaining what you're about to look at and why (e.g., "Let me check the authentication module to assess error handling…"). This helps the user follow along in real time.

1. Use structured tools (Code Graph, Code Analysis) FIRST — see tool guidance sections below. Call at least one Code Graph tool AND one Code Analysis tool before falling back to Read or Grep.
2. Do NOT perform a broad codebase scan or read documentation files (README, Roadmap, etc.).
3. Analyze the requirement against each scoring criterion above.
4. Provide your analysis as markdown text — explain what is well-defined and what is missing.
5. After your analysis, emit EXACTLY ONE structured evaluation block in this format:

${evaluationSchema}`

    return `You are a Grill Analyst — a requirement completeness evaluator.${reEvalBlock}

## Your Task
Evaluate the completeness of a software requirement for the **${track.name}** track.

## Evaluation Criteria
${track.scoringFocus.map((f) => `- ${f}`).join('\n')}

## Requirement
**${sanitizePromptInput(this.ideaTitle)}**

${sanitizePromptInput(this.ideaDescription || 'No description provided.')}

${instructions}

${questionRules}

${scoringRules}`
  }
}

/**
 * Shared prompt blocks for grill and greenfield-grill adapters.
 *
 * Both adapters use the same evaluation schema, question quality rules,
 * and scoring bands. Centralizing them here:
 * - Eliminates ~600 tokens of duplication
 * - Enables single-place lean variants
 * - Ensures consistent schema evolution
 */

import type { GrillTrackId } from '../../../shared/types'
import { resolvePromptVerbosity } from '../../../shared/constants'

// ── Re-evaluation Context ──

export function buildReEvalBlock(previousScore: number | undefined): string {
  if (previousScore == null) return ''
  return `\n## Re-evaluation Context
- Previous score: ${previousScore}/100
- ANCHOR your new score to the previous one. Only change when decisions materially fill or reveal gaps.
- Do NOT re-ask questions the user already answered — focus on REMAINING gaps.
- In your analysis, explicitly credit which previous decisions address which criteria.\n`
}

// ── Grill Evaluation JSON Schema ──

export function buildGrillEvaluationSchema(trackId: GrillTrackId): string {
  return `\`\`\`grill-evaluation
{
  "trackId": "${trackId}",
  "score": <number 1-100>,
  "scoreLabel": "<label: Raw | Warming Up | Medium Rare | Well Done | Perfectly Grilled>",
  "feedback": "<2-3 sentence summary of gaps>",
  "questions": [
    {
      "id": "q1",
      "question": "<2-3 sentence question explaining the gap and WHY it matters for implementation>",
      "header": "<short 3-5 word label>",
      "options": [
        { "label": "<concise choice>", "description": "<1-2 sentences: trade-offs, constraints, implications>", "recommended": true, "recommendedReason": "<1 sentence: why this is safest/best given trade-offs>" },
        { "label": "<alternative>", "description": "<trade-offs>" },
        { "label": "<another alternative>", "description": "<trade-offs>" }
      ]
    }
  ],
  "suggestedNextTrack": { "trackId": "<next-track-id>", "reason": "<why>" }
}
\`\`\``
}

/**
 * Lean grill-evaluation schema — Opus can follow the format from a concise description
 * instead of a full JSON example (~250 tokens saved).
 */
export function buildGrillEvaluationSchemaLean(trackId: GrillTrackId): string {
  return `Emit one \`grill-evaluation\` JSON block: { trackId: "${trackId}", score: 1-100, scoreLabel: "Raw|Warming Up|Medium Rare|Well Done|Perfectly Grilled", feedback: "2-3 sentence gap summary", questions: [{ id, question (2-3 sentences: gap + impact), header (3-5 words), options: [{ label, description (trade-offs), recommended?: true, recommendedReason }] }], suggestedNextTrack?: { trackId, reason } }`
}

// ── Question Quality Rules ──

export const GRILL_QUESTION_QUALITY_RULES = `## Question Quality Rules
- Each question MUST target a specific implementation decision, not just "what approach?"
- The "question" field must explain the GAP and its IMPACT (2-3 sentences, not just a label)
- Each option's "description" field is REQUIRED — explain trade-offs, constraints, or implications
- At least 2 of the 5 questions must probe EDGE CASES or FAILURE MODES
- Do NOT ask vague questions like "How should this work?" — ask "What happens when X fails/overflows/conflicts?"
- The recommended option's "recommendedReason" must reference concrete trade-offs (risk, complexity, reversibility) — not just "this is better"`

/** Extra rule appended for greenfield evaluations (no codebase exists) */
export const GRILL_QUESTION_QUALITY_RULES_GREENFIELD_EXTRA = `- Since there is NO existing codebase, focus questions on DESIGN CHOICES the user needs to make before building`

/**
 * Lean question quality rules — compressed to essentials.
 * Opus 4.8+ follows question structure from schema example + these reminders.
 */
export const GRILL_QUESTION_QUALITY_RULES_LEAN = `## Question Quality
Questions: specific implementation decisions with gap + impact (2-3 sentences). Options: required descriptions with trade-offs. ≥2 of 5 must probe edge cases/failure modes. recommendedReason: cite trade-offs (risk, complexity, reversibility).`

// ── Scoring Rules ──

export const GRILL_SCORING_RULES = `## Rules
- Score 1-20: Raw — fundamental gaps. Score 21-40: Warming Up. Score 41-60: Medium Rare. Score 61-80: Well Done. Score 81-100: Perfectly Grilled.
- Include exactly 5 questions targeting the weakest areas.
- Each question must have 3-4 options with at most 1 recommended. The recommended option MUST include a "recommendedReason" field — a single sentence explaining WHY (e.g. "Lower risk with the same outcome — refactoring can happen in phase 2").
- suggestedNextTrack is optional — only include if another track would benefit.
- Do NOT emit any other code blocks with the grill-evaluation language tag.`

/**
 * Lean scoring rules — compressed score bands + output constraints.
 */
export const GRILL_SCORING_RULES_LEAN = `## Rules
Score bands: 1-20 Raw, 21-40 Warming Up, 41-60 Medium Rare, 61-80 Well Done, 81-100 Perfectly Grilled.
5 questions, 3-4 options each, ≤1 recommended with recommendedReason. suggestedNextTrack optional. One grill-evaluation block only.`

// ── Composed Prompt Builders ──

/**
 * Determines whether the grill prompt should use lean variants.
 * Accepts optional model string — returns true for Opus 4.8+ models.
 */
export function isGrillLean(model?: string): boolean {
  return resolvePromptVerbosity(model ?? '') === 'lean'
}

/**
 * GreenfieldGrillRoleAdapter — drives grill evaluations for NEW project ideas.
 *
 * Key differences vs. GrillRoleAdapter:
 *   - No MCP tools — evaluates an IDEA, not an existing codebase.
 *   - No workspace settings lookup — no workspace exists yet.
 *   - Greenfield prompt focuses on requirements elicitation for a new project.
 *   - Same scoring scale, same grill-evaluation JSON output format.
 */

import type { GrillTrackId } from '../../../shared/types'
import type {
  AdapterMcpContext,
  AdapterMcpResult,
  AdapterPromptContext,
  AdapterPromptResult,
  AdapterSessionLifecycleCtx
} from '../agent-session.types'
import { GRILL_TRACKS } from '../../../shared/constants'
import {
  buildReEvalBlock,
  buildGrillEvaluationSchema,
  buildGrillEvaluationSchemaLean,
  GRILL_QUESTION_QUALITY_RULES,
  GRILL_QUESTION_QUALITY_RULES_GREENFIELD_EXTRA,
  GRILL_QUESTION_QUALITY_RULES_LEAN,
  GRILL_SCORING_RULES,
  GRILL_SCORING_RULES_LEAN,
  isGrillLean
} from './grill-prompt-blocks'
import { sanitizePromptInput } from '../sanitize-prompt-input'
import { BaseRoleAdapter } from './base.adapter'

export class GreenfieldGrillRoleAdapter extends BaseRoleAdapter {
  readonly role = 'grill' as const
  readonly agentId: string
  interactionTimeoutMs = 10 * 60_000 // 10 min per evaluation

  private readonly trackId: GrillTrackId
  private readonly projectName: string
  private readonly projectDescription: string
  private readonly iterationHistory?: string
  private readonly previousScore?: number
  private readonly llmProvider: import('../../../shared/types').LLMProvider

  private systemPrompt: string | null = null

  constructor(params: {
    trackId: GrillTrackId
    projectName: string
    projectDescription: string
    iterationHistory?: string
    previousScore?: number
    llmProvider?: import('../../../shared/types').LLMProvider
  }) {
    super()
    this.trackId = params.trackId
    this.projectName = params.projectName
    this.projectDescription = params.projectDescription
    this.iterationHistory = params.iterationHistory
    this.previousScore = params.previousScore
    this.llmProvider = params.llmProvider ?? 'claude'
    this.agentId = `greenfield-grill-${params.trackId}-${Date.now()}`
  }

  override async onSessionStart(ctx: AdapterSessionLifecycleCtx): Promise<void> {
    // Pattern 3: Centralized local LLM timeout
    this.applyLocalLlmTimeout(this.llmProvider)

    const track = GRILL_TRACKS[this.trackId]
    // Pattern 1: Centralized model resolution
    const resolvedModel = this.resolveModel(ctx.workspacePath, 'grill')
    this.systemPrompt = this.buildSystemPrompt(track, resolvedModel)

    this.log.info(
      `[greenfield-grill-adapter] ${this.trackId} grill started for project="${this.projectName}"`
    )
  }

  buildPrompts(_ctx: AdapterPromptContext): AdapterPromptResult {
    if (!this.systemPrompt) {
      throw new Error(
        `GreenfieldGrillRoleAdapter.buildPrompts() called before onSessionStart() for track=${this.trackId}`
      )
    }

    let effectiveMessage: string
    if (this.iterationHistory) {
      effectiveMessage = `Re-evaluate based on updated decisions:\n\n${this.iterationHistory}`
    } else {
      effectiveMessage = 'Begin your evaluation.'
    }

    return {
      systemPrompt: this.systemPrompt,
      effectiveMessage
    }
  }

  /** Custom MCP: greenfield only gets WebSearch + WebFetch (no codebase). */
  override buildMcpConfig(_ctx: AdapterMcpContext): AdapterMcpResult {
    return {
      allowedTools: ['WebSearch', 'WebFetch'],
      disallowedTools: [
        'Read',
        'Write',
        'Edit',
        'Bash',
        'Glob',
        'Grep',
        'Agent',
        'ToolSearch',
        'ExitPlanMode',
        'AskUserQuestion',
        'TodoWrite',
        'TaskCreate',
        'TaskUpdate'
      ]
    }
  }


  override onSessionStop(): void {
    this.systemPrompt = null
  }

  // ── Private: prompt construction ────────────────────────────────────

  private buildSystemPrompt(track: (typeof GRILL_TRACKS)[GrillTrackId], model?: string): string {
    const lean = isGrillLean(model)
    const reEvalBlock = buildReEvalBlock(this.previousScore)

    const evaluationSchema = lean
      ? buildGrillEvaluationSchemaLean(this.trackId)
      : buildGrillEvaluationSchema(this.trackId)

    const questionRules = lean
      ? GRILL_QUESTION_QUALITY_RULES_LEAN
      : `${GRILL_QUESTION_QUALITY_RULES}\n${GRILL_QUESTION_QUALITY_RULES_GREENFIELD_EXTRA}`

    const scoringRules = lean ? GRILL_SCORING_RULES_LEAN : GRILL_SCORING_RULES

    // Lean: compressed instructions — Opus narrates naturally
    const instructions = lean
      ? `## Instructions
0. Narrate your reasoning — explain what’s well-defined and what gaps remain.
1. Analyze the project idea against each criterion.
2. Identify decisions made vs. undefined.
3. Provide markdown analysis of gaps.
4. ${evaluationSchema}`
      : `## Instructions
0. **Narrate your reasoning.** Before each scoring decision, explain what aspects are well-defined and what gaps remain. Help the user understand what makes a well-prepared project brief.
1. Analyze the project idea against each scoring criterion above.
2. Identify what decisions have been made and what remains undefined.
3. Provide your analysis as markdown text — explain what is well-defined and what is missing.
4. After your analysis, emit EXACTLY ONE structured evaluation block in this format:

${evaluationSchema}`

    return `You are a Grill Analyst — a requirement completeness evaluator for a NEW project idea.${reEvalBlock}

## Context
You are evaluating a project IDEA, not an existing codebase. There is no code to analyze yet.
Focus on eliciting concrete decisions about scope, tech stack, architecture, user flows,
constraints, and trade-offs that will guide the project's creation.

## Your Task
Evaluate the completeness of a new project idea for the **${track.name}** track.

## Evaluation Criteria
${track.scoringFocus.map((f) => `- ${f}`).join('\n')}

## Project Idea
**${sanitizePromptInput(this.projectName)}**

${sanitizePromptInput(this.projectDescription || 'No description provided.')}

${instructions}

${questionRules}

${scoringRules}`
  }
}

/**
 * Unit tests for audit-response-parser.ts — extraction strategies, coverage
 * gate, score inference, severity normalization, inline-score extraction, and
 * analysis-preview building.
 *
 * Pure logic, no external deps (randomUUID + electron-log only). Each public
 * function is exercised across its branches; the four parse strategies are
 * covered end-to-end via parseAuditResponse.
 */
import assert from 'node:assert/strict'
import { test, describe, summaryAsync } from './test-harness'
import {
  parseAuditResponse,
  applyCoverageGate,
  inferScoreFromFindings,
  type ParsedAuditResponse
} from '../audit-response-parser'
import type { AuditFinding, AuditCoverageStats } from '../../../shared/types'

function finding(
  severity: AuditFinding['severity'],
  overrides: Partial<AuditFinding> = {}
): AuditFinding {
  return {
    id: 'x',
    severity,
    title: 'T',
    description: 'D',
    ...overrides
  }
}

describe('audit-response-parser › parseAuditResponse — Strategy 1: progressive blocks', () => {
  test('parses audit-finding blocks + audit-score block', () => {
    const text = [
      '```audit-finding',
      '{"severity":"high","title":"SQL injection","description":"unsanitized input","filePath":"db.ts","recommendation":"use params"}',
      '```',
      '```audit-finding',
      '{"severity":"low","title":"Style nit","description":"spacing"}',
      '```',
      '```audit-score',
      '{"score":72,"summary":"Two issues found"}',
      '```'
    ].join('\n')

    const result = parseAuditResponse(text)
    assert.equal(result.score, 72)
    assert.equal(result.summary, 'Two issues found')
    assert.equal(result.findings.length, 2)
    assert.equal(result.findings[0].severity, 'high')
    assert.equal(result.findings[0].title, 'SQL injection')
    assert.equal(result.findings[0].filePath, 'db.ts')
    assert.equal(result.findings[0].recommendation, 'use params')
    // Each finding gets a generated UUID
    assert.ok(result.findings[0].id && result.findings[0].id !== result.findings[1].id)
  })

  test('infers score from findings when audit-score block is absent', () => {
    const text = ['```audit-finding', '{"severity":"critical","title":"RCE"}', '```'].join('\n')

    const result = parseAuditResponse(text)
    // critical penalty = 25 → 100 - 25 = 75
    assert.equal(result.score, 75)
    assert.match(result.summary, /Partial audit: 1 finding discovered/)
    assert.equal(result.findings.length, 1)
  })

  test('pluralizes the partial-audit summary for multiple findings', () => {
    const text = [
      '```audit-finding',
      '{"severity":"low","title":"a"}',
      '```',
      '```audit-finding',
      '{"severity":"low","title":"b"}',
      '```'
    ].join('\n')
    const result = parseAuditResponse(text)
    assert.match(result.summary, /2 findings discovered/)
  })

  test('falls back to inferred score when audit-score JSON is malformed', () => {
    const text = [
      '```audit-finding',
      '{"severity":"medium","title":"x"}',
      '```',
      '```audit-score',
      '{ not valid json',
      '```'
    ].join('\n')
    const result = parseAuditResponse(text)
    // medium penalty = 8 → 92, and summary is the partial-audit message
    assert.equal(result.score, 92)
    assert.match(result.summary, /Partial audit/)
  })

  test('skips malformed individual findings but keeps valid ones', () => {
    const text = [
      '```audit-finding',
      '{ broken',
      '```',
      '```audit-finding',
      '{"severity":"high","title":"ok"}',
      '```'
    ].join('\n')
    const result = parseAuditResponse(text)
    assert.equal(result.findings.length, 1)
    assert.equal(result.findings[0].title, 'ok')
  })

  test('matches inline-format finding blocks (tag + JSON on same line)', () => {
    const text = '```audit-finding {"severity":"low","title":"inline"} ```'
    const result = parseAuditResponse(text)
    assert.equal(result.findings.length, 1)
    assert.equal(result.findings[0].title, 'inline')
  })

  test('defaults missing finding fields (title/description/severity)', () => {
    const text = ['```audit-finding', '{}', '```'].join('\n')
    const result = parseAuditResponse(text)
    assert.equal(result.findings[0].title, 'Untitled finding')
    assert.equal(result.findings[0].description, '')
    assert.equal(result.findings[0].severity, 'info')
    assert.equal(result.findings[0].filePath, undefined)
    assert.equal(result.findings[0].recommendation, undefined)
  })
})

describe('audit-response-parser › parseAuditResponse — Strategy 2: legacy JSON block', () => {
  test('parses a single ```json block', () => {
    const text = [
      'Here is the audit:',
      '```json',
      '{"score":88,"summary":"Looks good","findings":[{"severity":"low","title":"nit","description":"d","filePath":"a.ts","recommendation":"r"}]}',
      '```'
