            workspacePath: '/tmp/ws',
            title: 'C',
            originalPlanMd: '',
            goals: [
              {
                id: 'g1',
                title: 'Goal 1',
                outcome: 'do it',
                successCriteria: [],
                goalType: 'feature',
                phases: ['plan', 'execute', 'verify']
              }
            ]
          }),
        /already running/i
      )
    })

    test('isRunningForWorkspace is false for an unknown workspace', () => {
      const svc = new MpaCampaignService()
      assert.equal(svc.isRunningForWorkspace('nope'), false)
    })
  }
})

