/**
 * MPA Planner Adapter — read-only architect that produces implementation plans.
 *
 * CLI config: --permission-mode plan, --effort high, --goal "condition"
 */
export class MpaPlannerAdapter extends MpaBaseAdapter {
  readonly role: AgentRole = 'mpa-planner'
  readonly agentId: string

  private readonly goal: string
  private readonly grillDecisions?: GrillDecision[]
  private readonly previousPlan?: { contentJson: MpaPlanArtifact }
  private readonly userFeedback?: string

  constructor(params: {
    workspaceId: string
    goal: string
    grillDecisions?: GrillDecision[]
    previousPlan?: { contentJson: MpaPlanArtifact }
    userFeedback?: string
  }) {
    super({ workspaceId: params.workspaceId })
    this.goal = params.goal
    this.grillDecisions = params.grillDecisions
    this.previousPlan = params.previousPlan
    this.userFeedback = params.userFeedback
    this.agentId = `mpa-planner-${params.workspaceId}`
  }

  protected buildPhaseSystemPrompt(): string {
    return buildPlannerSystemPrompt({
      goal: this.goal,
      workspaceName: this.workspaceName,
      detectedTechs: this.detectedTechs,
      grillDecisions: this.grillDecisions,
      previousPlan: this.previousPlan,
      userFeedback: this.userFeedback,
      model: this.resolvedModel
    })
  }

  protected getPhaseMessage(): string {
    if (this.previousPlan && this.userFeedback) {
      return 'Revise the plan based on the feedback above.'
    }
    return 'Investigate the codebase and produce your implementation plan.'
  }
}

import type {
  AdapterSessionLifecycleCtx,
  AdapterPromptContext,
  AdapterPromptResult,
  AdapterMcpContext,
  AdapterMcpResult,
  AdapterIntentContext
} from '../../agent-session.types'
import type { AgentRole } from '../../../../shared/types'
import { workspaceRepository } from '../../../db/repositories'
import { detectTechStack } from '../../tech-stack-detector.service'
import { MCP_TOOLS } from '../../../../shared/constants'
import { BaseRoleAdapter } from '../base.adapter'

/**
 * Base adapter for MPA (Multi-Phased Agent) pipeline phases.
 *
 * Provides common plumbing for all three MPA roles:
 * - Read-only MCP tool config (plan/verify) vs full access (builder)
 * - Single-shot lifecycle (no conversation switching, no persona)
 * - Goal condition support for /goal-based completion
 */
export abstract class MpaBaseAdapter extends BaseRoleAdapter {
  abstract readonly role: AgentRole
  abstract readonly agentId: string
  interactionTimeoutMs = 30 * 60_000 // 30 min hard cap per phase

  protected workspaceId: string
  protected systemPrompt: string | null = null
  protected goalCondition: string | null = null
  protected goalMode: 'advisory' | 'enforce' = 'advisory'
  protected workspaceName = ''
  protected detectedTechs: string[] = []
  /** Resolved model ID for lean prompt gating (undefined for local LLMs) */
  protected resolvedModel: string | undefined

  constructor(params: { workspaceId: string }) {
    super()
    this.workspaceId = params.workspaceId
  }

  /** Set the /goal completion condition before starting the phase. */
  setGoalCondition(condition: string, mode: 'advisory' | 'enforce' = 'advisory'): void {
    this.goalCondition = condition
    this.goalMode = mode
  }

  /** Read the /goal completion condition — used by executor factory. */
  getGoalCondition(): string | null {
    return this.goalCondition
  }

  /** Read the goal delivery mode — 'advisory' (system prompt only) or 'enforce' (/goal stdin). */
  getGoalMode(): 'advisory' | 'enforce' {
    return this.goalMode
  }

  override async onSessionStart(ctx: AdapterSessionLifecycleCtx): Promise<void> {
    // Resolve workspace name
    try {
      const ws = workspaceRepository.findById(this.workspaceId)
      this.workspaceName = ws?.name ?? 'Unknown'
    } catch {
      this.workspaceName = 'Unknown'
    }

    // Pattern 2: Centralized workspace feature flag refresh
    this.refreshWorkspaceFeatureFlags(this.workspaceId)

    // Detect tech stack
    this.detectedTechs = ctx.workspacePath ? detectTechStack(ctx.workspacePath).detectedTechs : []

    // Pattern 1: Centralized model resolution
    this.resolvedModel = this.resolveModel(ctx.workspacePath, this.getModelAction())

    // Build the phase-specific system prompt
    this.systemPrompt = this.buildPhaseSystemPrompt()

    // Append tool guidance (Tool Priority + MCP guidance) — centralized in base class
    this.systemPrompt = this.appendToolGuidance(this.systemPrompt, 1, this.resolvedModel)
  }

  /** Return the ModelAction to use for model resolution (overridden by builder). */
  protected getModelAction(): import('../../../../shared/types').ModelAction {
    return 'specialist:plan' // Planner/verifier share plan-tier model
  }

  /** Subclasses implement to build phase-specific prompts. */
  protected abstract buildPhaseSystemPrompt(): string

  /** Subclasses provide the initial message for the phase. */
  protected abstract getPhaseMessage(): string

  buildPrompts(_ctx: AdapterPromptContext): AdapterPromptResult {
    if (!this.systemPrompt) {
      throw new Error(`${this.role} adapter: buildPrompts() called before onSessionStart()`)
    }
    return {
      systemPrompt: this.systemPrompt,
      effectiveMessage: this.getPhaseMessage()
    }
  }

  /** Read-only MCP config for plan/verify phases. Builder overrides this. */
  override buildMcpConfig(ctx: AdapterMcpContext): AdapterMcpResult {
    return {
      allowedTools: [
        'Read',
        'Glob',
        'Grep',
        'WebSearch',
        'WebFetch',
        ...(this.repomapEnabled && ctx.workspaceId ? MCP_TOOLS.CODE_GRAPH._ALL_NAMES : []),
        ...(this.semanticSearchEnabled && ctx.workspaceId
          ? MCP_TOOLS.SEMANTIC_SEARCH._ALL_NAMES
          : []),
        ...MCP_TOOLS.GIT_CONTEXT._ALL_NAMES,
        ...MCP_TOOLS.CODE_ANALYSIS._ALL_NAMES,
        // Memory tools — let MPA phases search/record workspace knowledge (parity with blueprints)
        ...(ctx.workspaceId ? MCP_TOOLS.MEMORY._ALL_NAMES : [])
      ],
      disallowedTools: [
        'Write',
        'Edit',
        'Bash',
        'ListDir',
        'Agent',
        'ToolSearch',
        'ExitPlanMode',
        'AskUserQuestion',
        'TodoWrite',
        'TaskCreate',
        'TaskUpdate'
      ]
    }
  }

  /** MPA phases don't emit conversational intents. */
  override emitDetectedIntents(_ctx: AdapterIntentContext): void {
    /* no-op */
  }


  override onSessionStop(): void {
    this.systemPrompt = null
    this.goalCondition = null
    this.goalMode = 'advisory'
  }
}

import { MpaBaseAdapter } from './mpa-base.adapter'
import { buildBuilderSystemPrompt } from '../../mpa-prompts'
import { TOOL_PRIORITY_DIRECTIVE_BUILDER } from '../../default-prompts'
import type { AgentRole } from '../../../../shared/types'
import type { AdapterMcpContext, AdapterMcpResult } from '../../agent-session.types'
import type { MpaPlanArtifact, MpaVerifyReport } from '../../../../shared/mpa-types'
import { MCP_TOOLS } from '../../../../shared/constants'

/**
 * MPA Builder Adapter — implements the approved plan with full write access.
 *
 * CLI config: --permission-mode auto, --effort high, --goal "condition", --max-turns 50
 */
export class MpaBuilderAdapter extends MpaBaseAdapter {
  readonly role: AgentRole = 'mpa-builder'
  readonly agentId: string

  private readonly goal: string
  private readonly plan: MpaPlanArtifact
  private readonly verifierFeedback?: MpaVerifyReport

  constructor(params: {
    workspaceId: string
    goal: string
    plan: MpaPlanArtifact
    verifierFeedback?: MpaVerifyReport
  }) {
    super({ workspaceId: params.workspaceId })
    this.goal = params.goal
    this.plan = params.plan
    this.verifierFeedback = params.verifierFeedback
    this.agentId = `mpa-builder-${params.workspaceId}`
  }

  protected getModelAction(): import('../../../../shared/types').ModelAction {
    return 'specialist:build' // Builder uses build-tier model
  }

  protected buildPhaseSystemPrompt(): string {
    // Builder uses TOOL_PRIORITY_DIRECTIVE_BUILDER (write-mode variant).
    // Embedding it here means the base class's appendToolGuidance() skips
    // the generic directive (it checks for '## Tool Priority' already present).
    return (
      buildBuilderSystemPrompt({
        goal: this.goal,
        plan: this.plan,
        workspaceName: this.workspaceName,
        detectedTechs: this.detectedTechs,
        verifierFeedback: this.verifierFeedback,
        model: this.resolvedModel
      }) + TOOL_PRIORITY_DIRECTIVE_BUILDER
    )
  }

  protected getPhaseMessage(): string {
    if (this.verifierFeedback) {
      return 'Fix all issues reported by the verifier, then re-run tests.'
    }
    return 'Begin implementation. Follow the plan in dependency order.'
  }

  /**
   * Builder gets full write access — overrides the read-only base config.
   */
  buildMcpConfig(ctx: AdapterMcpContext): AdapterMcpResult {
    return {
      allowedTools: [
        // Full read/write
        'Read',
        'Write',
        'Edit',
        'Glob',
        'Grep',
        'Bash',
        'WebSearch',
        'WebFetch',
        'ListDir',
        // Code graph tools
        ...(this.repomapEnabled && ctx.workspaceId ? MCP_TOOLS.CODE_GRAPH._ALL_NAMES : []),
        // Semantic search
        ...(this.semanticSearchEnabled && ctx.workspaceId
          ? MCP_TOOLS.SEMANTIC_SEARCH._ALL_NAMES
          : []),
        // Git context
        ...MCP_TOOLS.GIT_CONTEXT._ALL_NAMES,
        // Code analysis
        ...MCP_TOOLS.CODE_ANALYSIS._ALL_NAMES,
        // Memory tools — let builder search/record workspace knowledge (parity with blueprints)
        ...(ctx.workspaceId ? MCP_TOOLS.MEMORY._ALL_NAMES : [])
      ],
      disallowedTools: ['Agent', 'ToolSearch', 'AskUserQuestion', 'TodoWrite']
    }
  }
}

import { BaseRepository } from '../base-repository'
import { safeParseJSON } from '../json-utils'
import type { MpaArtifact, MpaArtifactType } from '../../../shared/mpa-types'

// ── Row interface ──

interface MpaArtifactRow {
  id: string
  run_id: string
  phase_id: string | null
  artifact_type: string
  content_json: string
  content_md: string | null
  version: number
  created_at: string
}

// ── Mapper ──

function mapRow(row: MpaArtifactRow): MpaArtifact {
  // DB-07: Use safeParseJSON for logged fallback on corrupted JSON
  const contentJson = safeParseJSON<Record<string, unknown>>(row.content_json, {})
  return {
    id: row.id,
    runId: row.run_id,
    phaseId: row.phase_id,
    artifactType: row.artifact_type as MpaArtifactType,
    contentJson,
    contentMd: row.content_md,
    version: row.version,
    createdAt: row.created_at
  }
}

// ── Repository ──

export class MpaArtifactRepository extends BaseRepository<MpaArtifactRow, MpaArtifact> {
  protected readonly tableName = 'mpa_artifacts'
  protected mapRow(row: MpaArtifactRow): MpaArtifact {
    return mapRow(row)
  }

  create(params: {
    runId: string
    phaseId?: string
    artifactType: MpaArtifactType
    contentJson: Record<string, unknown>
    contentMd?: string
    version?: number
  }): MpaArtifact {
    const row = this.db()
      .prepare(
        `INSERT INTO mpa_artifacts (run_id, phase_id, artifact_type, content_json, content_md, version)
         VALUES (?, ?, ?, ?, ?, ?)
         RETURNING *`
      )
      .get(
        params.runId,
        params.phaseId ?? null,
        params.artifactType,
        JSON.stringify(params.contentJson),
        params.contentMd ?? null,
        params.version ?? 1
      ) as MpaArtifactRow
    return mapRow(row)
  }

  override findById(id: string): MpaArtifact | undefined {
    return this.findOneBy('id', id)
  }

  findByRun(runId: string): MpaArtifact[] {
    return this.findManyBy('run_id', runId, { orderBy: 'created_at ASC' })
  }
}

export const mpaArtifactRepository = new MpaArtifactRepository()

import { BaseRepository } from '../base-repository'
import type { MpaCampaign, MpaCampaignStatus } from '../../../shared/mpa-types'

// ── Row interface ──

interface MpaCampaignRow {
  id: string
  workspace_id: string
  title: string
  original_plan_md: string
  status: string
  created_at: string
  completed_at: string | null
}

// ── Mapper ──

function mapRow(row: MpaCampaignRow): MpaCampaign {
  return {
    id: row.id,
    workspaceId: row.workspace_id,
    title: row.title,
    originalPlanMd: row.original_plan_md,
    status: row.status as MpaCampaignStatus,
    createdAt: row.created_at,
    completedAt: row.completed_at
  }
}

// ── Repository ──

export class MpaCampaignRepository extends BaseRepository<MpaCampaignRow, MpaCampaign> {
  protected readonly tableName = 'mpa_campaigns'
  protected mapRow(row: MpaCampaignRow): MpaCampaign {
    return mapRow(row)
  }

  create(params: { workspaceId: string; title: string; originalPlanMd: string }): MpaCampaign {
    const row = this.db()
      .prepare(
        `INSERT INTO mpa_campaigns (workspace_id, title, original_plan_md)
         VALUES (?, ?, ?)
         RETURNING *`
      )
      .get(params.workspaceId, params.title, params.originalPlanMd) as MpaCampaignRow
    return mapRow(row)
  }

  override findById(id: string): MpaCampaign | undefined {
    return this.findOneBy('id', id)
  }

  findByWorkspace(workspaceId: string, limit = 20): MpaCampaign[] {
    const rows = this.db()
      .prepare(
        `SELECT * FROM mpa_campaigns
         WHERE workspace_id = ?
         ORDER BY created_at DESC
         LIMIT ?`
      )
      .all(workspaceId, limit) as MpaCampaignRow[]
    return rows.map(mapRow)
  }

  updateStatus(id: string, status: MpaCampaignStatus): MpaCampaign | undefined {
    const completedAt =
      status === 'completed' || status === 'failed' || status === 'cancelled'
        ? new Date().toISOString()
        : null
    const row = this.db()
      .prepare(
        `UPDATE mpa_campaigns
         SET status = ?, completed_at = COALESCE(?, completed_at)
         WHERE id = ?
         RETURNING *`
      )
      .get(status, completedAt, id) as MpaCampaignRow | undefined
    return row ? mapRow(row) : undefined
  }

  /** Mark all 'running'/'paused' campaigns as failed (stale detection on restart). */
  markStaleAsFailed(): number {
    return this.db()
      .prepare(
        `UPDATE mpa_campaigns SET status = 'failed', completed_at = datetime('now')
         WHERE status IN ('running', 'paused')`
      )
      .run().changes
  }
}

export const mpaCampaignRepository = new MpaCampaignRepository()

/**
 * Unit tests for ipc/text-delta-batcher.ts — coalescing, manual flush (single
 * key + all keys), reset semantics, most-recent-flusher-wins, multi-key
 * isolation, and timer-driven auto-flush.
 *
 * Pure logic + a single real-timer test (small interval). No electron deps.
 */
import assert from 'node:assert/strict'
import { test, describe, summaryAsync, createSpy } from './../../services/__tests__/test-harness'
import { TextDeltaBatcher, TEXT_BATCH_INTERVAL_MS } from '../text-delta-batcher'

const delay = (ms: number): Promise<void> => new Promise((r) => setTimeout(r, ms))

describe('TextDeltaBatcher › coalescing + manual flush', () => {
  test('coalesces multiple pushes under one key into a single flush', () => {
    const batcher = new TextDeltaBatcher(10_000)
    const flush = createSpy<[string], void>()
    batcher.push('c1', 'Hello ', flush)
    batcher.push('c1', 'world', flush)
    assert.equal(flush.callCount, 0, 'no flush before timer/manual')

    batcher.flush('c1')
    assert.equal(flush.callCount, 1)
    assert.deepEqual(flush.lastCall, ['Hello world'])
  })

  test('flush(key) clears the buffer — a second flush is a no-op', () => {
    const batcher = new TextDeltaBatcher(10_000)
    const flush = createSpy<[string], void>()
    batcher.push('c1', 'abc', flush)
    batcher.flush('c1')
    batcher.flush('c1')
    assert.equal(flush.callCount, 1)
  })

  test('flush() with no key flushes every key', () => {
    const batcher = new TextDeltaBatcher(10_000)
    const f1 = createSpy<[string], void>()
    const f2 = createSpy<[string], void>()
    batcher.push('a', 'one', f1)
    batcher.push('b', 'two', f2)
    batcher.flush()
    assert.deepEqual(f1.lastCall, ['one'])
    assert.deepEqual(f2.lastCall, ['two'])
  })

  test('does not flush a key with no buffered text', () => {
    const batcher = new TextDeltaBatcher(10_000)
    const flush = createSpy<[string], void>()
    batcher.flush('never-pushed')
    assert.equal(flush.callCount, 0)
  })
})

describe('TextDeltaBatcher › flusher semantics', () => {
  test('most-recent flusher for a key wins', () => {
    const batcher = new TextDeltaBatcher(10_000)
    const oldFlush = createSpy<[string], void>()
    const newFlush = createSpy<[string], void>()
    batcher.push('c1', 'a', oldFlush)
    batcher.push('c1', 'b', newFlush)
    batcher.flush('c1')
    assert.equal(oldFlush.callCount, 0)
    assert.equal(newFlush.callCount, 1)
    assert.deepEqual(newFlush.lastCall, ['ab'])
  })

  test('multi-key isolation — no cross-stream mixing', () => {
    const batcher = new TextDeltaBatcher(10_000)
    const fa = createSpy<[string], void>()
    const fb = createSpy<[string], void>()
    batcher.push('conv-a', 'AAA', fa)
    batcher.push('conv-b', 'BBB', fb)
    batcher.push('conv-a', '111', fa)
    batcher.flush()
    assert.deepEqual(fa.lastCall, ['AAA111'])
    assert.deepEqual(fb.lastCall, ['BBB'])
  })
})

describe('TextDeltaBatcher › reset', () => {
  test('reset(key) flushes then drops the flusher so it cannot fire again', () => {
    const batcher = new TextDeltaBatcher(10_000)
    const flush = createSpy<[string], void>()
    batcher.push('c1', 'final', flush)
    batcher.reset('c1')
    assert.equal(flush.callCount, 1, 'reset flushes pending buffer')

    // After reset the flusher is gone — a fresh push needs a new flusher.
    batcher.push('c1', 'more', flush)
    batcher.flush('c1')
    assert.equal(flush.callCount, 2)
  })

  test('reset() with no key flushes all and clears every flusher', () => {
    const batcher = new TextDeltaBatcher(10_000)
    const f1 = createSpy<[string], void>()
    const f2 = createSpy<[string], void>()
    batcher.push('a', 'x', f1)
    batcher.push('b', 'y', f2)
    batcher.reset()
    assert.equal(f1.callCount, 1)
    assert.equal(f2.callCount, 1)
  })
})

describe('TextDeltaBatcher › timer auto-flush', () => {
  test('default interval constant is one 30fps frame', () => {
    assert.equal(TEXT_BATCH_INTERVAL_MS, 33)
  })

  test('auto-flushes after the batch interval elapses', async () => {
    const batcher = new TextDeltaBatcher(5)
    const flush = createSpy<[string], void>()
    batcher.push('c1', 'auto', flush)
    assert.equal(flush.callCount, 0)
    await delay(25)
    assert.equal(flush.callCount, 1)
    assert.deepEqual(flush.lastCall, ['auto'])
  })

  test('only one timer is armed per key across rapid pushes', async () => {
    const batcher = new TextDeltaBatcher(5)
    const flush = createSpy<[string], void>()
    batcher.push('c1', 'a', flush)
    batcher.push('c1', 'b', flush)
    batcher.push('c1', 'c', flush)
    await delay(25)
    assert.equal(flush.callCount, 1, 'coalesced into a single timer-driven flush')
    assert.deepEqual(flush.lastCall, ['abc'])
  })
})

