/**
 * Blueprint Artifact Parsers — shared between BlueprintSpecService and tests.
 *
 * Plan and tasks parsers are now in the shared module (importable by renderer).
 * This file re-exports them for backward compatibility and keeps the main-only
 * parsePhaseCompletionBlock (which uses electron-log).
 */

import log from 'electron-log'
import type { BlueprintPhaseCompletion, BlueprintPhaseType } from '../../shared/blueprint-types'

// Re-export shared parsers so existing main-process imports keep working
export { parseBlueprintPlan, parseBlueprintTasks } from '../../shared/blueprint-artifact-parsers'

/** Coerce an unknown LLM value to a string array, discarding non-string elements. */
export function asStringArray(v: unknown): string[] {
  return Array.isArray(v) ? v.filter((p): p is string => typeof p === 'string') : []
}

const bpLog = log.scope('blueprint-parsers')

/**
 * Parse a blueprint-phase-complete block from streamed text.
 * Primary: ```blueprint-phase-complete ... ```
 * Fallback: any JSON with "phase" and "status" keys.
 */
/**
 * Parse a ```blueprint-discoveries``` block from streamed text.
 * Returns an array of discovery strings (max 10, each truncated to 250 chars),
 * or null if the block is absent or malformed.
 */
export function parseDiscoveriesBlock(text: string): string[] | null {
  try {
    const match = text.match(/```blueprint-discoveries\s*\n([\s\S]*?)\n```/)
    if (!match?.[1]) return null

    const parsed: unknown = JSON.parse(match[1])
    if (!Array.isArray(parsed)) return null

    const entries = parsed
      .filter((entry): entry is string => typeof entry === 'string' && entry.trim().length > 0)
      .slice(0, 10)
      .map((entry) => (entry.length > 250 ? entry.slice(0, 250) : entry))

    return entries.length > 0 ? entries : null
  } catch {
    return null
  }
}

export function parsePhaseCompletionBlock(
  text: string,
  expectedPhase?: BlueprintPhaseType
): BlueprintPhaseCompletion | null {
  // BP-PARSER-GUARD: Reject oversized inputs before hitting regex.
  // LLM outputs shouldn't exceed 500KB; anything larger is likely corrupted.
  if (text.length > 500_000) {
    bpLog.warn(`[parsePhaseCompletionBlock] Input too large (${text.length} chars) — skipping`)
    return null
  }

  try {
    // Look for ```blueprint-phase-complete ... ``` tagged block
    const match = text.match(/```blueprint-phase-complete\s*\n([\s\S]*?)\n```/)
    if (match?.[1]) {
      const parsed = JSON.parse(match[1])
      if (parsed.phase && parsed.status) {
        return parsed as BlueprintPhaseCompletion
      }
    }

    // Fallback 1: look for any JSON with "phase" and "status" keys.
    // BP-REDOS-01: Use indexOf to locate keys first, then extract the smallest
    // enclosing JSON object via brace-counting — avoids catastrophic backtracking
    // from the previous [\s\S]* regex on large inputs.
    const phaseIdx = text.indexOf('"phase"')
    const statusIdx = text.indexOf('"status"')
    if (phaseIdx > -1 && statusIdx > -1) {
      const startBrace = text.lastIndexOf('{', Math.min(phaseIdx, statusIdx))
      if (startBrace > -1) {
        // Find matching closing brace via counting
        let depth = 0
        let endBrace = -1
        for (let i = startBrace; i < text.length; i++) {
          if (text[i] === '{') depth++
          else if (text[i] === '}') {
            depth--
            if (depth === 0) { endBrace = i; break }
          }
        }
        if (endBrace > -1) {
          try {
            const parsed = JSON.parse(text.substring(startBrace, endBrace + 1))
            if (parsed.phase && parsed.status) {
              return parsed as BlueprintPhaseCompletion
            }
          } catch {
            /* not valid JSON — continue to next fallback */
          }
        }
      }
    }

    // Fallback 2: verify-style JSON with "overallStatus" but missing "phase"/"status".
    // Only activates for verify phase (or when caller doesn't specify a phase).
    // The verify agent sometimes omits the tagged block or the phase/status keys.
    if (expectedPhase === 'verify' || expectedPhase === undefined) {
      // BP-NESTED-JSON-01: Use brace-counting to extract the full JSON object
      // from inside a fenced code block. The old non-greedy regex stopped at the
      // first '}', breaking on nested objects like { artifacts: { missing: 0 } }.
      const fenceMatch = text.match(/```(?:json)?\s*\n(\{)/)
      if (fenceMatch?.index != null) {
        const jsonStart = fenceMatch.index + fenceMatch[0].length - 1
        let depth = 0
        let jsonEnd = -1
        for (let i = jsonStart; i < text.length; i++) {
          if (text[i] === '{') depth++
          else if (text[i] === '}') {
            depth--
            if (depth === 0) { jsonEnd = i; break }
          }
        }
        if (jsonEnd > -1) {
          const jsonStr = text.substring(jsonStart, jsonEnd + 1)
          try {
            const parsed = JSON.parse(jsonStr)
            if (parsed.overallStatus) {
              bpLog.info(
                `[parsePhaseCompletionBlock] Used verify-style fallback — overallStatus: ${parsed.overallStatus}`
              )
              return {
                ...parsed,
                phase: expectedPhase ?? 'verify',
                status: 'complete'
              } as BlueprintPhaseCompletion
            }
          } catch {
            /* malformed JSON — continue */
          }
        }
      }
    }

    // BP-PARSE-OBSERVABILITY: Log when all fallback paths fail on non-trivial output.
    // Helps distinguish "agent didn't emit completion" from "parsing failed silently".
    if (text.length > 200) {
      bpLog.warn(
        `[parsePhaseCompletionBlock] No completion block found in ${text.length}-char output` +
        (expectedPhase ? ` (expectedPhase: ${expectedPhase})` : '')
      )
    }
  } catch (err) {
    bpLog.warn('[parsePhaseCompletionBlock] Failed to parse completion:', err)
  }
  return null
}

/**
 * Shared Blueprint Artifact Parsers — plan and tasks block extraction.
 * Pure functions — no electron-log dependency. Importable by both main and renderer.
 *
 * Main process re-exports these to keep its existing API.
 */

// ── Plan block ──

const PLAN_REGEX = /```blueprint-plan\s*\n([\s\S]*?)```/g

/**
 * Parse the last blueprint-plan block from streamed text.
 * Returns null if no block found or parsing fails.
 */
export function parseBlueprintPlan(text: string): Record<string, unknown> | null {
  const matches = [...text.matchAll(PLAN_REGEX)]
  if (matches.length === 0) return null

  const lastMatch = matches[matches.length - 1]
  const jsonStr = lastMatch[1].trim()

  try {
    return JSON.parse(jsonStr) as Record<string, unknown>
  } catch {
    return null
  }
}

// ── Tasks block ──

const TASKS_REGEX = /```blueprint-tasks\s*\n([\s\S]*?)```/g

/**
 * Parse the last blueprint-tasks block from streamed text.
 * Returns null if no block found or parsing fails.
 */
export function parseBlueprintTasks(text: string): Record<string, unknown> | null {
  const matches = [...text.matchAll(TASKS_REGEX)]
  if (matches.length === 0) return null

  const lastMatch = matches[matches.length - 1]
  const jsonStr = lastMatch[1].trim()

  try {
    return JSON.parse(jsonStr) as Record<string, unknown>
  } catch {
    return null
  }
}

/**
* Blueprint Goal Conditions — /goal completion conditions for all blueprint phases.
 *
 * Following the mpa-goal-conditions.ts pattern: pure functions that build
 * goal condition strings delivered via /goal stdin command (goalMode: enforce).
 */

/**
 * Build the /goal completion condition for the SPECIFY phase.
 * The CLI evaluates this condition to decide when the phase is done.
 */
export function buildSpecifyGoalCondition(title: string): string {
  return [
    `A comprehensive specification is produced for: "${title.slice(0, 150)}"`,
    'The spec is emitted as a fenced code block tagged blueprint-phase-complete',
    'The JSON has phase: "specify" and status: "complete"',
    'At least 2 user stories with acceptance scenarios are defined',
    'Requirements have unique IDs (FR-xxx) and use MUST/SHOULD/MAY language'
  ].join('. ')
}

/**
 * Build the /goal completion condition for the CLARIFY phase.
 */
export function buildClarifyGoalCondition(): string {
  return [
    'All identified specification gaps have been addressed through Q&A',
    'The completion block is emitted as blueprint-phase-complete with phase: "clarify"',
    'The coverage summary shows resolved count >= outstanding count'
  ].join('. ')
}

/**
 * Build the /goal completion condition for the PLAN phase.
 */
export function buildPlanGoalCondition(title: string): string {
  return [
    `A detailed implementation plan is produced for: "${title.slice(0, 150)}"`,
    'The plan is emitted as a fenced code block tagged blueprint-plan',
    'The plan contains at least 2 plan items with unique IDs (P1, P2, etc.)',
    'Each item has files, scope, and dependency information',
    'A blueprint-phase-complete block is emitted with phase: "plan" and status: "complete"',
    'The mustHaves section includes truths, artifacts, and keyLinks'
  ].join('. ')
}

/**
 * Build the /goal completion condition for the TASKS phase.
 */
export function buildTasksGoalCondition(title: string): string {
  return [
    `Implementation tasks are decomposed from the plan for: "${title.slice(0, 150)}"`,
    'Tasks are emitted as a fenced code block tagged blueprint-tasks',
    'Each task has a taskId (T001 format), description, files array, and wave assignment',
    'Wave dependencies are acyclic and same-wave tasks have no file overlap',
    'A blueprint-phase-complete block is emitted with phase: "tasks" and status: "complete"'
  ].join('. ')
}

/**
 * Build the /goal completion condition for the REVIEW phase.
 */
export function buildReviewGoalCondition(title: string): string {
  return [
    `Cross-artifact review is completed for: "${title.slice(0, 150)}"`,
    'Coverage analysis traces spec requirements → plan items → tasks',
    'File paths are validated against actual codebase structure',
    'Findings are classified by severity (critical/high/medium/low)',
    'A blueprint-phase-complete block is emitted with phase: "review", status: "complete", findings counts, and recommendation'
  ].join('. ')
}

/**
 * Build the /goal completion condition for a single BUILD task.
 * Unlike other goal conditions which are per-phase, BUILD goals are per-task
 * because each task gets its own agent session.
 */
export function buildBuildGoalCondition(taskId: string, description: string): string {
  return [
    `Task ${taskId} is fully implemented: "${description.slice(0, 150)}"`,
    'All files listed in the task exist with correct content',
    'No placeholder or stub code is left behind',
    'Changes are staged individually (never git add .)',
    'A blueprint-phase-complete block is emitted with phase: "build", status: "complete"'
  ].join('. ')
}

/**
 * Build the /goal completion condition for the VERIFY phase.
 * Adversarial verification — prove implementation matches spec.
 */
export function buildVerifyGoalCondition(title: string): string {
  return [
    `Adversarial verification is complete for: "${title.slice(0, 150)}"`,
    'All artifacts are verified using the 4-level methodology (EXISTS → SUBSTANTIVE → WIRED → DATA FLOWING)',
    'Key links from the plan are traced and validated',
    'Anti-pattern scan is complete (TODO/FIXME/empty bodies/hardcoded data)',
    'Each spec requirement is traced to implemented code',
    'Human verification items are listed if applicable',
    'A blueprint-phase-complete block is emitted with phase: "verify", overallStatus, and recommendation'
  ].join('. ')
}

