/**
 * BlueprintReviewService — orchestrates the REVIEW phase of the Blueprint pipeline.
 *
 * One-shot: creates a fresh AgentSessionService, sends the review request,
 * parses the completion block with findings/recommendation, saves the artifact,
 * and emits an approval gate event. Does NOT auto-advance to BUILD.
 *
 * Advancement to BUILD happens via BLUEPRINT_APPROVAL_RESPOND handler.
 */

import { EventEmitter } from 'node:events'
import log from 'electron-log'
import type { StreamChunk } from './agent-base.service'
import type { AgentStatus } from '../../shared/types'
import { forwardBlueprintChunk } from './blueprint-chunk-forwarder'
import { PhaseActivityWatchdog, STALL_TIMEOUT_MS, wireAskUserAutoResponder } from './blueprint-phase-watchdog'
import { AgentSessionService } from './agent-session.service'
import { BlueprintReviewAdapter } from './role-adapters/blueprint/blueprint-review.adapter'
import { buildReviewGoalCondition } from './blueprint-goal-conditions'
import { parsePhaseCompletionBlock, parseDiscoveriesBlock } from './blueprint-artifact-parsers'
import { blueprintService } from './blueprint.service'
import { modelConfigService } from './model-config.service'
import {
  blueprintRepository,
  blueprintPhaseRepository,
  blueprintTaskRepository
} from '../db/repositories/blueprint.repository'
import { conversationRepository } from '../db/repositories'
import type {
  BlueprintPhaseStartPayload,
  BlueprintPhaseCompletePayload,
  BlueprintPhaseArtifactPayload,
  BlueprintApprovalNeededPayload
} from '../../shared/blueprint-types'
import { runPreflightChecks } from './blueprint-preflight.service'
import type { ApprovalPreflightData } from '../../shared/preflight-types'

const bpLog = log.scope('blueprint-review')

const PHASE_TIMEOUT_MS = 30 * 60_000 // 30 min

export class BlueprintReviewService extends EventEmitter {
  // BP-PHASE-RAW-EMIT-01: Error-isolated emit prevents listener throws from
  // crashing the pipeline. Mirrors safeEmit() in BlueprintBuildService/VerifyService.
  private safeEmit(event: string, payload: unknown): boolean {
    try {
      return this.emit(event, payload)
    } catch (err) {
      bpLog.error(`[safeEmit] Event '${event}' listener threw:`, err)
      return false
    }
  }

  async startReviewPhase(params: {
    blueprintId: string
    workspaceId: string
    workspacePath: string
  }): Promise<void> {
    const { blueprintId, workspaceId, workspacePath } = params

    bpLog.info(`[startReviewPhase] Blueprint ${blueprintId} — starting REVIEW`)

    // BP-PHASE-TRYCATCH-SCOPE-01: All initialization inside try so
    // finally's markPipelineStopped() is guaranteed to run.
    let reviewPhase: ReturnType<typeof blueprintPhaseRepository.findByBlueprintAndPhase> = undefined
    let session: AgentSessionService | null = null
    let onChunk: ((chunk: StreamChunk) => void) | null = null
    let onStatus: ((status: AgentStatus) => void) | null = null
    let cleanupAskUser: (() => void) | undefined

    try {
      // 1. Pipeline + DB state
      blueprintService.markPipelineRunning(workspaceId, blueprintId, 'review')

      reviewPhase = blueprintPhaseRepository.findByBlueprintAndPhase(blueprintId, 'review')
      if (reviewPhase) {
        blueprintPhaseRepository.updateStatus(reviewPhase.id, 'active')
      }

      blueprintRepository.updateStatus(blueprintId, 'reviewing')
      blueprintRepository.update(blueprintId, { currentPhase: 'review' })

      // 2. Assemble context (includes spec + clarify + plan + tasks artifacts + workspace docs)
      const phaseContext = await blueprintService.assemblePhaseContext(blueprintId, 'review', workspacePath)

      // 3. Create adapter + session
      const adapter = new BlueprintReviewAdapter({ workspaceId, blueprintId, phaseContext })

      const blueprint = blueprintService.getBlueprint(blueprintId)
      adapter.setGoalCondition(buildReviewGoalCondition(blueprint?.title ?? 'Unknown'), 'enforce')

      session = new AgentSessionService(adapter)

      // 4. Emit phaseStart
      this.safeEmit('phaseStart', {
        blueprintId,
        workspaceId,
        phase: 'review',
        goal: buildReviewGoalCondition(blueprint?.title ?? 'Unknown')
      } satisfies BlueprintPhaseStartPayload)

      // 5. Wire streaming — named handlers for cleanup + stall watchdog
      const stallWatchdog = new PhaseActivityWatchdog(STALL_TIMEOUT_MS, 'REVIEW')

      onChunk = (chunk: StreamChunk): void => {
        stallWatchdog.touch()
        forwardBlueprintChunk(
          (event, payload) => this.safeEmit(event, payload),
          chunk,
          { blueprintId, workspaceId, phase: 'review', workspacePath, mode: 'plan' }
        )
      }
      onStatus = (status: AgentStatus): void => {
        this.safeEmit('status', { workspaceId, status })
      }
      session.on('chunk', onChunk)
      session.on('statusUpdate', onStatus)

      // B4-FIX: Auto-respond to ask_user calls — review is non-interactive
      cleanupAskUser = wireAskUserAutoResponder(session, 'REVIEW')

      // 6. Start session + send with timeout + stall watchdog + abort race
      await session.start(workspacePath, 'plan')

      // BP-RETRY-CONV-REUSE: Check for prior conversation from failed attempt
      const reviewPhaseRec = blueprintPhaseRepository.findByBlueprintAndPhase(blueprintId, 'review')
      const priorConvId = reviewPhaseRec?.conversationId
      let syntheticConvId: string
      if (priorConvId && conversationRepository.getSessionId(priorConvId)) {
        const priorConv = conversationRepository.findById(priorConvId)
        const currentProvider = modelConfigService.getProvider(workspacePath)
        if (priorConv?.llmProvider === currentProvider) {
          syntheticConvId = priorConvId
          bpLog.info(`[startReviewPhase] Resuming conversation ${priorConvId} from failed attempt`)
        } else {
          syntheticConvId = `blueprint-review-${blueprintId}-${Date.now()}`
          bpLog.info(`[startReviewPhase] Provider changed — falling back to fresh conversation`)
        }
      } else {
        syntheticConvId = `blueprint-review-${blueprintId}-${Date.now()}`
      }

      // Persist conversation ID early so retries can find it
      if (reviewPhaseRec) {
        try { blueprintPhaseRepository.setConversation(reviewPhaseRec.id, syntheticConvId) }
        catch { /* conversation may not exist yet in DB */ }
      }

      let timeoutId: NodeJS.Timeout | undefined
      const timeoutPromise = new Promise<void>((_, reject) => {
        timeoutId = setTimeout(() => reject(new Error('REVIEW phase timeout')), PHASE_TIMEOUT_MS)
      })

      const abortSignal = blueprintService.getAbortSignal(workspaceId)
      // BP-ABORT-TOCTOU-02: Attach listener BEFORE checking aborted status to
      // close the race window where the signal fires between check and addEventListener.
      const abortPromise = new Promise<void>((_, reject) => {
        const onAbort = (): void => reject(new Error('Phase cancelled'))
        abortSignal?.addEventListener('abort', onAbort, { once: true })
        if (abortSignal?.aborted) {
          onAbort()
        }
      })

      const sendPromise = session.send(adapter.getPhaseMessage(), syntheticConvId)

      try {
        await Promise.race([sendPromise, timeoutPromise, abortPromise, stallWatchdog.promise])
      } finally {
        if (timeoutId) clearTimeout(timeoutId)
        stallWatchdog.dispose()
      }

      // 7. Parse output
      const text = session.getStreamedContent(syntheticConvId)
      const completion = parsePhaseCompletionBlock(text, 'review') ?? undefined

      // 8. Save phase artifact
      if (reviewPhase) {
        blueprintPhaseRepository.appendArtifact(reviewPhase.id, {
          type: 'review',
          contentMd: text,
          contentJson: completion ?? undefined
        })
        blueprintPhaseRepository.setConversation(reviewPhase.id, syntheticConvId)

        // 8b. Save discoveries artifact (if emitted)
        const discoveries = parseDiscoveriesBlock(text)
        if (discoveries?.length) {
          blueprintPhaseRepository.appendArtifact(reviewPhase.id, {
            type: 'discoveries',
            contentJson: { phase: 'review', entries: discoveries }
          })
        }

        blueprintPhaseRepository.updateStatus(reviewPhase.id, 'complete')
        // BP-RETRY-CONTEXT-CLEAR: Clear retry context on successful completion
        if (reviewPhase.contextSnapshot) {
          blueprintPhaseRepository.saveContextSnapshot(reviewPhase.id, null)
        }
      }

      bpLog.info(
        `[startReviewPhase] Blueprint ${blueprintId} — review complete, recommendation: ${completion?.recommendation ?? 'unknown'}`
      )

      // 9. Emit phaseComplete
      this.safeEmit('phaseComplete', {
        blueprintId,
        workspaceId,
        phase: 'review',
        status: 'complete',
        completion
      } satisfies BlueprintPhaseCompletePayload)

      if (reviewPhase) {
        this.safeEmit('phaseArtifact', {
          blueprintId,
          workspaceId,
          phase: 'review',
          artifact: { type: 'review', contentMd: text }
        } satisfies BlueprintPhaseArtifactPayload)
      }

      // 10. Run environment preflight checks (cheap, <5s — G5: no new machine states)
      let preflightData: ApprovalPreflightData | undefined
      try {
        const tasks = blueprintTaskRepository.findByBlueprint(blueprintId)
        const taskDescriptions = tasks.map((t) => t.description)
        const preflightResult = await runPreflightChecks(workspacePath, taskDescriptions)

        // A6+R2-2 fix: atomic replace — avoids stale-read hazard from step 1
        if (reviewPhase) {
          blueprintPhaseRepository.replaceArtifactOfType(reviewPhase.id, 'preflight', {
            type: 'preflight',
            contentJson: preflightResult as unknown as Record<string, unknown>
          })
        }

        preflightData = { result: preflightResult, overridden: false }
        this.safeEmit('preflightResult', { blueprintId, workspaceId, result: preflightResult })
        bpLog.info(
          `[startReviewPhase] Preflight: ${preflightResult.checks.length} checks — ` +
          `${preflightResult.hasBlockers ? 'HAS BLOCKERS' : 'no blockers'}`
        )
      } catch (preflightErr) {
        // Preflight failure should never block the approval gate (premortem #4)
        bpLog.warn(`[startReviewPhase] Preflight failed (non-fatal):`, preflightErr)
      }

      // 11. Emit approval gate — human must approve before BUILD
      // Drive state machine: phase-running → awaiting-approval
      const machine = blueprintService.getMachine(workspaceId)
      machine.transition('approvalNeeded')

      const planSummary = this.buildApprovalSummary(completion ?? null)
      // M2: Track approval state for snapshot sync
      blueprintService.setPendingApproval(workspaceId, {
        planSummary,
        completion: completion ? (completion as Record<string, unknown>) : undefined,
        reviewMarkdown: text || undefined,
        ...(preflightData ? { preflight: { result: preflightData.result as unknown as Record<string, unknown>, overridden: preflightData.overridden } } : {})
      })
      this.safeEmit('approvalNeeded', {
        blueprintId,
        workspaceId,
        phase: 'review',
        planSummary,
        completion: completion ?? undefined,
        reviewMarkdown: text || undefined,
        ...(preflightData ? { preflight: preflightData } : {})
      } as BlueprintApprovalNeededPayload & { preflight?: ApprovalPreflightData })

      // NOTE: Does NOT advance to BUILD. That happens in BLUEPRINT_APPROVAL_RESPOND handler.
    } catch (err) {
      bpLog.error(`[startReviewPhase] REVIEW phase failed:`, err)

      // Guard: don't overwrite 'cancelled' status
      const currentStatus = blueprintRepository.findById(blueprintId)?.status
      if (currentStatus !== 'cancelled') {
        if (reviewPhase) {
          blueprintPhaseRepository.updateStatus(reviewPhase.id, 'failed')
        }
        blueprintRepository.updateStatus(blueprintId, 'failed')
      }

      const partialText = session?.getStreamedContent(syntheticConvId)
      if (partialText && reviewPhase) {
        blueprintPhaseRepository.appendArtifact(reviewPhase.id, {
          type: 'review-partial',
          contentMd: partialText
        })
      }

      // M5: Use failPipeline to properly transition machine to 'failed' state
      const errorMsg = err instanceof Error ? err.message : String(err)
      blueprintService.failPipeline(workspaceId, errorMsg)

      // BP-RETRY-CONTEXT: Save structured retry context for next attempt
      try { blueprintService.saveRetryContext(blueprintId, 'review', { error: errorMsg }) }
      catch { /* best effort */ }

      const autoRetrying = blueprintService.scheduleAutoRetry({
        blueprintId, workspaceId, workspacePath, phase: 'review', error: errorMsg
      })

      this.safeEmit('phaseComplete', {
        blueprintId,
        workspaceId,
        phase: 'review',
        status: 'failed',
        error: errorMsg,
        ...(autoRetrying ? { autoRetry: true } : {})
      } satisfies BlueprintPhaseCompletePayload)
    } finally {
      cleanupAskUser?.()
      if (session) {
        if (onChunk) session.removeListener('chunk', onChunk)
        if (onStatus) session.removeListener('statusUpdate', onStatus)
        await session.stop()
      }
      blueprintService.markPipelineStopped(workspaceId)
    }
  }

  // ── Approval Summary Builder ──

  /**
   * Build a human-readable summary for the approval gate from the completion payload.
   */
  private buildApprovalSummary(completion: Record<string, unknown> | null): string {
    if (!completion) return 'Review completed — no structured findings available.'

    const findings = completion.findings as
      | { critical?: number; high?: number; medium?: number; low?: number }
      | undefined
    const recommendation = typeof completion.recommendation === 'string' ? completion.recommendation : 'unknown'
    const coverage = completion.coveragePercent as number | undefined

    const lines: string[] = []
    if (coverage !== undefined) {
      lines.push(`Coverage: ${coverage}% of requirements have implementation tasks`)
    }
    if (findings) {
      const parts: string[] = []
      if (findings.critical) parts.push(`${findings.critical} critical`)
      if (findings.high) parts.push(`${findings.high} high`)
      if (findings.medium) parts.push(`${findings.medium} medium`)
      if (findings.low) parts.push(`${findings.low} low`)
      lines.push(`Findings: ${parts.join(', ') || 'none'}`)
    }
    lines.push(`Recommendation: ${recommendation.replace(/_/g, ' ')}`)

    return lines.join('\n')
  }

  /** Cancel (one-shot — handled by AbortController in blueprintService.cancel()). */
  async cancelBlueprint(_blueprintId: string): Promise<void> {
    // One-shot — no session map to clean up.
  }

  async shutdown(): Promise<void> {
    // One-shot — no persistent sessions to clean up.
  }
}

export const blueprintReviewService = new BlueprintReviewService()

/**
 * Blueprint Chunk Forwarder — shared helper that replaces the 7 duplicated
 * inline chunk handlers across blueprint phase services.
 *
 * Delegates tool chunk processing to `processToolChunk()` from the
 * tool-chunk-processor module so blueprint sessions get the same rich
 * ToolActivity objects (input, result, resultDetail, filePath, lineRange,
 * operationType) that regular chat sessions enjoy — enabling expandable
 * tool details in the Blueprint chat UI.
 */

import type { StreamChunk } from './agent-base.service'
import type { BlueprintPhaseProgressPayload } from '../../shared/blueprint-types'
import type { BlueprintPhaseType } from '../../shared/blueprint-types'
import type { ConversationMode } from '../../shared/types'
import { processToolChunk } from '../ipc/tool-chunk-processor'

// ── Public types ──

export interface BlueprintChunkForwarderCtx {
  blueprintId: string
  workspaceId: string
  phase: BlueprintPhaseType
  workspacePath?: string
  /** Conversation mode — 'plan' for plan-mode phases suppresses false-positive
   *  bug reports for blocked Write/Edit calls. */
  mode?: ConversationMode
  /** Build-phase task ID — routes progress into the correct per-task lane. */
  taskId?: string
}

export type BlueprintEmitFn = (
  event: 'phaseProgress',
  payload: BlueprintPhaseProgressPayload
) => void

// ── Core forwarder ──

/**
 * Forward a StreamChunk from a blueprint phase session, producing a
 * `phaseProgress` emission.
 *
 * - `text` chunks → emit text progress (unchanged from the old inline handlers)
 * - `tool_use` / `tool_result` / `tool_progress` → run through `processToolChunk`
 *   to produce a full ToolActivity, then emit with `kind: 'tool'` and the
 *   `toolActivity` payload.  Falls back to tool-name-only when processing fails.
 * - All other chunk types are silently ignored.
 */
export function forwardBlueprintChunk(
  emit: BlueprintEmitFn,
  chunk: StreamChunk,
  ctx: BlueprintChunkForwarderCtx
): void {
  // ── Text chunks ──
  if (chunk.type === 'text' && chunk.content) {
    emit('phaseProgress', {
      blueprintId: ctx.blueprintId,
      workspaceId: ctx.workspaceId,
      phase: ctx.phase,
      text: chunk.content,
      ...(ctx.taskId ? { taskId: ctx.taskId } : {})
    })
    return
  }

  // ── Tool chunks (tool_use / tool_result / tool_progress) ──
  if (
    chunk.type === 'tool_use' ||
    chunk.type === 'tool_result' ||
    chunk.type === 'tool_progress'
  ) {
    const processed = processToolChunk(chunk, {
      agentType: 'blueprint',
      workspacePath: ctx.workspacePath,
      workspaceId: ctx.workspaceId,
      mode: ctx.mode
    })

    if (processed) {
      emit('phaseProgress', {
        blueprintId: ctx.blueprintId,
        workspaceId: ctx.workspaceId,
        phase: ctx.phase,
        text: processed.toolActivity.toolName,
        kind: 'tool',
        toolActivity: {
          id: processed.toolActivity.id,
          toolName: processed.toolActivity.toolName,
          status: processed.toolActivity.status,
          input: processed.toolActivity.input,
          result: processed.toolActivity.result,
          resultDetail: processed.toolActivity.resultDetail,
          startedAt: processed.toolActivity.startedAt,
          completedAt: processed.toolActivity.completedAt,
          elapsedSeconds: processed.toolActivity.elapsedSeconds,
          filePath: processed.toolActivity.filePath,
          lineRange: processed.toolActivity.lineRange,
          operationType: processed.toolActivity.operationType
        },
        ...(ctx.taskId ? { taskId: ctx.taskId } : {})
      })
    }
    // If processToolChunk returns null (control tools), silently drop — same
    // behaviour as the regular chat pipeline.
  }
}

/**
 * Blueprint Phase Activity Watchdog — detects stalled blueprint phases.
 *
 * Unlike the flat 30-minute PHASE_TIMEOUT_MS wall-clock cap, this watchdog
 * monitors *activity* (chunk arrival). If no chunk arrives for 5 minutes,
 * the phase is presumed stalled and the race promise rejects — surfacing
 * the error to the user in ~5 minutes instead of ~30.
 *
 * Usage in phase services:
 * ```ts
 * const stallWatchdog = new PhaseActivityWatchdog(STALL_TIMEOUT_MS, 'PLAN')
 * session.on('chunk', () => stallWatchdog.touch())
 * try {
 *   await Promise.race([sendPromise, timeoutPromise, abortPromise, stallWatchdog.promise])
 * } finally {
 *   stallWatchdog.dispose()
 * }
 * ```
 *
 * The 30-min absolute cap remains as the outer bound.
 */

import log from 'electron-log'

const bpLog = log.scope('blueprint-watchdog')

/** Default stall threshold: 5 minutes of no chunk activity. */
export const STALL_TIMEOUT_MS = 5 * 60_000

export class PhaseActivityWatchdog {
  private timer: ReturnType<typeof setTimeout> | null = null
  private rejectFn: ((err: Error) => void) | null = null
  private _stalled = false
  private _paused = false

  constructor(
    private readonly stallTimeoutMs: number,
    private readonly phaseName: string
  ) {}

  /** Whether the watchdog has detected a stall. */
  get stalled(): boolean {
    return this._stalled
  }

  /**
   * Create a promise that rejects when no touch() is received within
   * stallTimeoutMs. Must only be called once per watchdog instance.
   * The timer starts immediately on first access.
   */
  get promise(): Promise<void> {
    return new Promise<void>((_, reject) => {
      this.rejectFn = reject
      this.resetTimer()
    })
  }

  /** Whether the watchdog is currently paused (e.g. awaiting user input). */
  get paused(): boolean {
    return this._paused
  }

  /**
   * Pause the watchdog — stops the stall timer without disposing.
   * Used when awaiting user input (ask_user bridge) to prevent false stalls.
   */
  pause(): void {
    if (this._paused) return
    this._paused = true
    if (this.timer) {
      clearTimeout(this.timer)
      this.timer = null
    }
    bpLog.info(`[stall-watchdog] ${this.phaseName} paused — awaiting user input`)
  }

  /**
   * Resume the watchdog — restarts the stall timer.
   * Called after the user answers the ask_user question.
   */
  resume(): void {
    if (!this._paused) return
    this._paused = false
    if (this.rejectFn) {
      this.resetTimer()
    }
    bpLog.info(`[stall-watchdog] ${this.phaseName} resumed`)
  }

  /**
   * Record activity — call on each chunk to reset the stall timer.
   * Safe to call after dispose() (no-op). No-op while paused.
   */
  touch(): void {
    if (!this.rejectFn || this._paused) return // disposed, not started, or paused
    this.resetTimer()
  }

  /**
   * Clean up the timer. Call in finally block.
   * Idempotent — safe to call multiple times.
   */
  dispose(): void {
    if (this.timer) {
      clearTimeout(this.timer)
      this.timer = null
    }
    this.rejectFn = null
  }

  private resetTimer(): void {
    if (this.timer) clearTimeout(this.timer)
    this.timer = setTimeout(() => {
      this._stalled = true
      const minuteStr = Math.round(this.stallTimeoutMs / 60_000)
      const msg = `${this.phaseName} phase stalled — no activity for ${minuteStr}m`
      bpLog.warn(`[stall-watchdog] ${msg}`)
      this.rejectFn?.(new Error(msg))
    }, this.stallTimeoutMs)
  }
}

// ── Non-interactive phase ask_user auto-responder ──

/**
 * Wire an auto-responder to a session's askQuestion event for non-interactive phases
 * (specify, plan, tasks, review, verify). If the model calls ask_user during these
 * phases, immediately respond so the turn doesn't deadlock waiting for user input.
 *
 * Returns a cleanup function to remove the listener.
 */
export function wireAskUserAutoResponder(
  session: { on: (event: string, handler: (...args: unknown[]) => void) => void; off: (event: string, handler: (...args: unknown[]) => void) => void; respondToAskUser: (requestId: string, response: string) => void },
  phaseName: string
): () => void {
  const handler = (data: unknown): void => {
    const { requestId } = data as { requestId?: string }
    if (!requestId) return
    bpLog.info(`[askUser-auto-responder] ${phaseName} phase — auto-responding to ask_user (non-interactive phase)`)
    session.respondToAskUser(
      requestId,
      `Non-interactive phase (${phaseName}) — proceed with best judgment and emit the required fenced block.`
    )
  }
  session.on('askQuestion', handler)
  return () => session.off('askQuestion', handler)
}

/**
 * Blueprint Review Adapter — read-only quality gate that validates cross-artifact consistency.
 *
 * CLI config: --permission-mode plan, --effort high, goalMode: enforce (/goal via stdin)
 *
 * One-shot phase: agent reads spec + plan + tasks artifacts, investigates codebase
 * for path validation, and produces a review report with findings and recommendation.
 */

import { BlueprintBaseAdapter } from './blueprint-base.adapter'
import { buildPhaseSystemPrompt } from '../../blueprint-prompt-loader'
import type { AgentRole, ModelAction } from '../../../../shared/types'
import type { PhaseContext } from '../../../../shared/blueprint-types'

export class BlueprintReviewAdapter extends BlueprintBaseAdapter {
  readonly role: AgentRole = 'blueprint-review'
  readonly agentId: string

  private readonly phaseContext: PhaseContext

  constructor(params: { workspaceId: string; blueprintId: string; phaseContext: PhaseContext }) {
    super({ workspaceId: params.workspaceId, blueprintId: params.blueprintId })
    this.phaseContext = params.phaseContext
    this.agentId = `blueprint-review-${params.blueprintId}`
  }

  protected getModelAction(): ModelAction {
    return 'blueprint:review'
  }

  protected buildPhaseSystemPrompt(): string {
    return buildPhaseSystemPrompt('review', this.phaseContext)
  }

  getPhaseMessage(): string {
    return [
      'Perform a comprehensive review of the blueprint artifacts before BUILD begins.',
      '',
      'Analyze: spec ↔ plan coverage, plan ↔ tasks decomposition, end-to-end traceability,',
      'constitution compliance, risk assessment, and quality checks.',
      '',
      'Validate file paths against the actual codebase structure.',
      '',
      'Produce a structured review report and emit a `blueprint-phase-complete` block',
      'with findings counts and your recommendation (proceed / fix_critical / re_specify).'
    ].join('\n')
  }
}

/**
 * Base adapter for Blueprint pipeline phases (Specify, Clarify, Plan, etc.).
 *
 * Following the MpaBaseAdapter pattern: read-only MCP config, single-shot lifecycle,
 * goal condition support, and centralized prompt/model resolution.
 *
 * Key difference from MPA: Blueprint adapters carry a blueprintId and use
 * buildPhaseSystemPrompt() from the blueprint prompt loader.
 */

import type {
  AdapterSessionLifecycleCtx,
  AdapterPromptContext,
  AdapterPromptResult,
  AdapterMcpContext,
  AdapterMcpResult,
  AdapterIntentContext
} from '../../agent-session.types'
import type { AgentRole, ModelAction } from '../../../../shared/types'
import { workspaceRepository } from '../../../db/repositories'
import { detectTechStack } from '../../tech-stack-detector.service'
import { MCP_TOOLS } from '../../../../shared/constants'
import { BaseRoleAdapter } from '../base.adapter'

/**
 * Base adapter for Blueprint pipeline phases.
 *
 * Provides common plumbing for all Blueprint roles:
 * - Read-only MCP tool config (all phases are read-only for now)
 * - Single-shot lifecycle (no conversation switching, no persona)
 * - Goal condition support for /goal-based completion
 * - Blueprint-specific context (blueprintId, phaseContext)
 */
export abstract class BlueprintBaseAdapter extends BaseRoleAdapter {
  abstract readonly role: AgentRole
  abstract readonly agentId: string
  interactionTimeoutMs = 30 * 60_000 // 30 min hard cap per phase

  protected workspaceId: string
  protected blueprintId: string
  protected systemPrompt: string | null = null
  protected goalCondition: string | null = null
  protected goalMode: 'advisory' | 'enforce' = 'advisory'
  protected workspaceName = ''
  protected detectedTechs: string[] = []
  /** Resolved model ID for lean prompt gating (undefined for local LLMs) */
  protected resolvedModel: string | undefined

  constructor(params: { workspaceId: string; blueprintId: string }) {
    super()
    this.workspaceId = params.workspaceId
    this.blueprintId = params.blueprintId
  }

  /** Set the /goal completion condition before starting the phase. */
  setGoalCondition(condition: string, mode: 'advisory' | 'enforce' = 'advisory'): void {
    this.goalCondition = condition
    this.goalMode = mode
  }

  /** Read the /goal completion condition — used by executor factory. */
  getGoalCondition(): string | null {
    return this.goalCondition
  }

  /** Read the goal delivery mode — 'advisory' (system prompt only) or 'enforce' (/goal stdin). */
  getGoalMode(): 'advisory' | 'enforce' {
    return this.goalMode
  }

  override async onSessionStart(ctx: AdapterSessionLifecycleCtx): Promise<void> {
    // Resolve workspace name
    try {
      const ws = workspaceRepository.findById(this.workspaceId)
      this.workspaceName = ws?.name ?? 'Unknown'
    } catch {
      this.workspaceName = 'Unknown'
    }

    // Pattern 2: Centralized workspace feature flag refresh
    this.refreshWorkspaceFeatureFlags(this.workspaceId)

    // Detect tech stack
    this.detectedTechs = ctx.workspacePath ? detectTechStack(ctx.workspacePath).detectedTechs : []

    // Pattern 1: Centralized model resolution
    this.resolvedModel = this.resolveModel(ctx.workspacePath, this.getModelAction())

    // Build the phase-specific system prompt
    this.systemPrompt = this.buildPhaseSystemPrompt()

    // Append tool guidance (Tool Priority + MCP guidance) — centralized in base class
    this.systemPrompt = this.appendToolGuidance(this.systemPrompt, 1, this.resolvedModel)
  }

  /** Return the ModelAction to use for model resolution. */
  protected abstract getModelAction(): ModelAction

  /** Subclasses implement to build phase-specific prompts. */
  protected abstract buildPhaseSystemPrompt(): string

  /** Subclasses provide the initial message for the phase. */
  abstract getPhaseMessage(): string

  buildPrompts(ctx: AdapterPromptContext): AdapterPromptResult {
    if (!this.systemPrompt) {
      throw new Error(`${this.role} adapter: buildPrompts() called before onSessionStart()`)
    }
    return {
      systemPrompt: this.systemPrompt,
      // Interactive phases (clarify) send follow-up user messages — pass them
      // through. Fall back to the phase kickoff message when empty (initial send).
      effectiveMessage: ctx.message?.trim() ? ctx.message : this.getPhaseMessage()
    }
  }

  /** Read-only MCP config for all Blueprint phases (read-only investigation). */
  override buildMcpConfig(ctx: AdapterMcpContext): AdapterMcpResult {
    return {
      allowedTools: [
        'Read',
        'Glob',
        'Grep',
        'WebSearch',
        'WebFetch',
        ...(this.repomapEnabled && ctx.workspaceId ? MCP_TOOLS.CODE_GRAPH._ALL_NAMES : []),
        ...(this.semanticSearchEnabled && ctx.workspaceId
          ? MCP_TOOLS.SEMANTIC_SEARCH._ALL_NAMES
          : []),
        ...MCP_TOOLS.GIT_CONTEXT._ALL_NAMES,
        ...MCP_TOOLS.CODE_ANALYSIS._ALL_NAMES,
        // Memory tools let phases search/record workspace knowledge across the pipeline
        ...(ctx.workspaceId ? MCP_TOOLS.MEMORY._ALL_NAMES : [])
      ],
      disallowedTools: [
        'Write',
        'Edit',
        'Bash',
        'ListDir',
        'Agent',
        'ToolSearch',
        'ExitPlanMode',
        'AskUserQuestion',
        'TodoWrite',
        'TaskCreate',
        'TaskUpdate'
      ]
    }
  }

  /** Blueprint phases don't emit conversational intents. */
  override emitDetectedIntents(_ctx: AdapterIntentContext): void {
    /* no-op */
  }


  override onSessionStop(): void {
    this.systemPrompt = null
    this.goalCondition = null
    this.goalMode = 'advisory'
  }
}

/**
 * Blueprint Prompt Loader — reads .md prompt/template files and injects context variables.
 *
 * Each Blueprint phase has:
 *  - A system prompt file (`prompts/<phase>-phase.md`)
 *  - An optional template file (`templates/<templateName>.md`)
 *  - Optional agent enhancement files (`agents/<role>-enhancement.md`)
 *
 * The loader reads these files, replaces {{VARIABLE}} placeholders with actual content,
 * and assembles the full system prompt for the agent session.
 */

import { readFileSync, readdirSync, existsSync } from 'fs'
import { join } from 'path'
import log from 'electron-log'
import type {
  BlueprintPhaseType,
  PhaseContext,
  BlueprintArtifact
} from '../../shared/blueprint-types'

const promptLog = log.scope('blueprint-prompt-loader')

// ── Path Resolution ──

/** Root of the blueprints directory (relative to compiled output). */
function getBlueprintsDir(): string {
  // In dev: src/main/blueprints/
  // In prod: out/main/blueprints/ (copied by Vite)
  const candidates = [
    join(__dirname, '..', 'blueprints'), // out/main/blueprints (prod)
    join(__dirname, 'blueprints'), // alternate structure
    join(__dirname, '..', '..', 'src', 'main', 'blueprints') // dev fallback
  ]
  for (const candidate of candidates) {
    if (existsSync(candidate)) return candidate
  }
  // Default — will error on read if not found
  return join(__dirname, '..', 'blueprints')
}

/** Read a file from the blueprints directory. Returns empty string if not found. */
function readBlueprintFile(relativePath: string): string {
  const fullPath = join(getBlueprintsDir(), relativePath)
  try {
    return readFileSync(fullPath, 'utf-8')
  } catch (err) {
    promptLog.warn(`Blueprint file not found: ${relativePath}`, err)
    return ''
  }
}

// ── Phase → Prompt/Template Mapping ──

const PHASE_PROMPT_FILES: Record<BlueprintPhaseType, string> = {
  specify: 'prompts/specify-phase.md',
  clarify: 'prompts/clarify-phase.md',
  plan: 'prompts/plan-phase.md',
  tasks: 'prompts/tasks-phase.md',
  review: 'prompts/review-phase.md',
  build: 'prompts/build-phase.md',
  verify: 'prompts/verify-phase.md'
}

/** Templates are optional per-phase — some phases don't have output templates. */
const PHASE_TEMPLATE_FILES: Partial<Record<BlueprintPhaseType, string>> = {
  specify: 'templates/spec.md',
  plan: 'templates/plan.md',
  tasks: 'templates/tasks.md'
}

/** Agent enhancement files (injected into BUILD/VERIFY phases). */
const AGENT_ENHANCEMENT_FILES: Partial<Record<BlueprintPhaseType, string>> = {
  plan: 'agents/planner-enhancement.md',
  build: 'agents/executor-enhancement.md',
  verify: 'agents/verifier-enhancement.md'
}

// ── Artifact Formatting ──

// Fields to keep when projecting plan JSON (drops verbose description prose)
const PLAN_PROJECTION_KEYS = new Set([
  'summary', 'techStack', 'mustHaves', 'existingPatterns', 'keyLinks',
  'phases', 'items', 'id', 'title', 'name', 'files', 'scope'
])

// Fields to keep when projecting tasks JSON
const TASKS_PROJECTION_KEYS = new Set([
  'id', 'title', 'wave', 'files', 'scope', 'status', 'taskId',
  'userStory', 'filePathsJson', 'description'
])

/** Per-phase char budget for the formatted artifacts block. */
export const ARTIFACT_BUDGET_CHARS = 30_000

/** Max number of consolidated discovery entries before truncation. */
const MAX_DISCOVERY_ENTRIES = 30

/**
 * Project only the allowed keys from an object (shallow, one level + recurse into arrays).
 * Returns a new object with only the allowed fields.
 */
function projectFields(obj: Record<string, unknown>, allowed: Set<string>): Record<string, unknown> {
  const result: Record<string, unknown> = {}
  for (const key of Object.keys(obj)) {
    if (allowed.has(key)) {
      const val = obj[key]
      // Recurse into arrays of objects (e.g. plan.items[], tasks[])
      if (Array.isArray(val)) {
        result[key] = val.map((item) =>
          typeof item === 'object' && item !== null && !Array.isArray(item)
            ? projectFields(item as Record<string, unknown>, allowed)
            : item
        )
      } else {
        result[key] = val
      }
    }
  }
  return result
}

/**
 * Format a list of artifacts into a markdown string for prompt injection.
 *
 * Design principles (context compaction):
 *   1. Prefer contentMd over contentJson — skip JSON dump when markdown exists
 *   2. Use compact JSON (no pretty-printing) for ~30-40% savings
 *   3. Project only needed fields for plan/tasks JSON
 *   4. Consolidate all discovery entries into one deduplicated list
 *   5. Enforce a char budget with graceful truncation
 */
export function formatArtifacts(
  artifacts: BlueprintArtifact[],
  budgetChars: number = ARTIFACT_BUDGET_CHARS
): string {
  if (!artifacts.length) return '(No previous artifacts available.)'

  // Stage 3: Consolidate all discovery entries into one merged block
  const nonDiscoveryArtifacts: BlueprintArtifact[] = []
  const allDiscoveryEntries: string[] = []

  for (const a of artifacts) {
    if (a.type === 'discoveries' && a.contentJson) {
      const { entries } = a.contentJson as { entries?: string[] }
      if (Array.isArray(entries)) {
        for (const e of entries) {
          if (!allDiscoveryEntries.includes(e)) {
            allDiscoveryEntries.push(e)
          }
        }
      }
    } else {
      nonDiscoveryArtifacts.push(a)
    }
  }

  // Render non-discovery artifacts
  const rendered: string[] = []
  for (const a of nonDiscoveryArtifacts) {
    rendered.push(renderSingleArtifact(a))
  }

  // Render consolidated discoveries block
  if (allDiscoveryEntries.length > 0) {
    const capped = allDiscoveryEntries.length > MAX_DISCOVERY_ENTRIES
    const entries = capped
      ? allDiscoveryEntries.slice(-MAX_DISCOVERY_ENTRIES)
      : allDiscoveryEntries
    const bullets = entries.map((e) => `- ${e}`).join('\n')
    const omitted = allDiscoveryEntries.length - entries.length
    const suffix = capped
      ? `\n\n_(${omitted} older discoveries omitted — use mcp__memory__memory_search to retrieve)_`
      : ''
    rendered.push(`### Discoveries (consolidated)\n${bullets}${suffix}`)
  }

  const filtered = rendered.filter((s) => s.length > 0)

  // Stage 4: Budget cap with graceful truncation
  let total = 0
  const budgeted: string[] = []
  for (let i = 0; i < filtered.length; i++) {
    const entry = filtered[i]
    if (total + entry.length > budgetChars && budgeted.length > 0) {
      const remaining = filtered.length - i
      budgeted.push(
        `_(${remaining} artifact(s) truncated to stay within context budget — use Read or mcp__memory__memory_search for full content)_`
      )
      break
    }
    budgeted.push(entry)
    total += entry.length
  }

  return budgeted.join('\n\n---\n\n')
}

/** Render a single non-discovery artifact to markdown. */
function renderSingleArtifact(a: BlueprintArtifact): string {
  const parts: string[] = [`### Artifact: ${a.type}`]
  if (a.filePath) parts.push(`**Path**: ${a.filePath}`)

  // Prefer contentMd — skip JSON dump when markdown summary exists
  if (a.contentMd) {
    parts.push(a.contentMd)
  } else if (a.contentJson) {
    // Field projection for known large artifact types
    let json = a.contentJson
    if (a.type === 'plan') {
      json = projectFields(json, PLAN_PROJECTION_KEYS)
    } else if (a.type === 'tasks') {
      json = projectFields(json, TASKS_PROJECTION_KEYS)
    }
    // Compact JSON (no pretty-printing) for ~30-40% savings
    parts.push('```json\n' + JSON.stringify(json) + '\n```')
  }
  return parts.join('\n')
}

// ── Main Prompt Builder ──

/**
 * Build the complete system prompt for a Blueprint phase.
 *
 * Reads the phase prompt file, injects context variables, and assembles
 * the full prompt including constitution, previous artifacts, and templates.
 */
export function buildPhaseSystemPrompt(phase: BlueprintPhaseType, context: PhaseContext): string {
  // 1. Load the phase prompt
  const promptFile = PHASE_PROMPT_FILES[phase]
  let prompt = readBlueprintFile(promptFile)

  if (!prompt) {
    promptLog.warn(`No prompt file found for phase: ${phase}, using minimal fallback`)
    prompt = buildFallbackPrompt(phase)
  }

  // 2. Load optional template
  const templateFile = PHASE_TEMPLATE_FILES[phase]
  const template = templateFile ? readBlueprintFile(templateFile) : ''

  // 3. Load optional agent enhancement
  const enhancementFile = AGENT_ENHANCEMENT_FILES[phase]
  const enhancement = enhancementFile ? readBlueprintFile(enhancementFile) : ''

  // 4. Replace context variables
  prompt = replaceVariables(prompt, context, template, enhancement)

  return prompt
}

/**
 * Build the system prompt for the Constitution editor.
 */
export function buildConstitutionEditorPrompt(
  existingConstitution: string | null,
  workspaceInfo: { name: string; path: string }
): string {
  let prompt = readBlueprintFile('prompts/constitution-editor.md')

  if (!prompt) {
    prompt = buildFallbackConstitutionPrompt()
  }

  prompt = prompt
    .replace('{{EXISTING_CONSTITUTION}}', existingConstitution || '(No existing constitution.)')
    .replace('{{WORKSPACE_NAME}}', workspaceInfo.name)
    .replace('{{WORKSPACE_PATH}}', workspaceInfo.path)

  return prompt
}

// ── Retry Context Formatter ──

function formatRetryContext(ctx: NonNullable<PhaseContext['retryContext']>): string {
  const lines = [
    `\n<retry_context>`,
    `## ⚠️ This is Retry Attempt #${ctx.attempt}`,
    '',
    `The previous attempt of this ${ctx.previousPhase} phase FAILED.`,
    `**Error:** ${ctx.previousError}`,
    ''
  ]

  if (ctx.filesModified.length > 0) {
    lines.push(`**Files modified before failure:** ${ctx.filesModified.join(', ')}`)
    lines.push('⚠️ These files may be in an inconsistent state — re-read them before making further changes.')
    lines.push('')
  }
  if (ctx.filesCreated.length > 0) {
    lines.push(`**Files created before failure:** ${ctx.filesCreated.join(', ')}`)
    lines.push('')
  }
  if (ctx.totalTasks > 0) {
    lines.push(`**Progress:** ${ctx.tasksCompleted}/${ctx.totalTasks} tasks completed before failure`)
    lines.push('')
  }

  lines.push(
    'The partial output from the previous attempt is included in <previous_artifacts>.',
    'Build on what was already accomplished — do NOT start from scratch.',
    'Re-read any modified files to verify their current state before continuing.',
    '</retry_context>'
  )

  return lines.join('\n')
}

// ── Variable Replacement ──

function replaceVariables(
  prompt: string,
  context: PhaseContext,
  template: string,
  enhancement: string
): string {
  return (
    prompt
      // Blueprint context JSON (injected as structured data)
      .replace('{{BLUEPRINT_CONTEXT_JSON}}', JSON.stringify(context.blueprint, null, 2))
      // Constitution content
      .replace('{{CONSTITUTION_CONTENT}}', context.constitution || '(No constitution defined.)')
      // Previous phase artifacts
      .replace('{{PREVIOUS_PHASE_ARTIFACTS}}', formatArtifacts(context.previousArtifacts))
      // File paths
      .replace(/\{\{SPEC_FILE_PATH\}\}/g, context.specFilePath)
      .replace(/\{\{BLUEPRINT_DIR\}\}/g, context.blueprintDir)
      // Template injection
      .replace('{{TEMPLATE_CONTENT}}', template || '(No template available.)')
      // Agent enhancement injection
      .replace('{{AGENT_ENHANCEMENT}}', enhancement)
      // Grill decisions (if available)
      .replace(
        '{{GRILL_DECISIONS}}',
        context.grillDecisions?.length
          ? context.grillDecisions
              .map((d) => `- **${d.header}**: ${d.selectedOption}\n  _Reason_: ${d.reason}`)
              .join('\n')
          : '(No grill decisions available.)'
      )
      // Pre-loaded workspace documentation (CLAUDE.md, README.md, package.json, PLAN.md)
      .replace(
        '{{WORKSPACE_DOCS}}',
        context.workspaceDocs || '(No workspace documentation found — use Read to check for CLAUDE.md, README.md, package.json)'
      )
      // Retry context (populated only on retry — guides the agent to build on prior work)
      .replace(
        '{{RETRY_CONTEXT}}',
        context.retryContext
          ? formatRetryContext(context.retryContext)
          : ''
      )
  )
}

// ── Fallback Prompts (used when .md files aren't found yet) ──

function buildFallbackPrompt(phase: BlueprintPhaseType): string {
