    )
  })

  test('dot_path_resolves_correctly', () => {
    const result = assertWithinRepo(REPO, 'src/./file.ts')
    assert.equal(result, resolve(REPO, 'src/file.ts'))
  })

  test('deeply_nested_valid_path_resolves', () => {
