describe('formatArtifacts — compact JSON (no pretty-printing)', () => {
  test('json_is_compact_not_pretty_printed', () => {
    const result = formatArtifacts([{
      type: 'plan',
      contentJson: { summary: 'Build login', techStack: ['React', 'Node'] }
    }])
