    assert.ok(result.includes('Setup auth'), 'Should keep title')
    assert.ok(!result.includes('longAnalysis'), 'Should drop longAnalysis')
  })

  test('non_plan_non_tasks_json_keeps_all_fields', () => {
    const result = formatArtifacts([{
      type: 'review',
