import type { RawChunk } from '../preprocessing.service'

// ── Helper ──

function makeChunk(overrides: Partial<RawChunk> = {}): RawChunk {
  return {
    id: 'chunk-1',
    filePath: 'src/app.ts',
    symbolName: 'myFunction',
    symbolKind: 'function',
    body: 'function myFunction() {}',
    startLine: 1,
    endLine: 1,
    signature: 'function myFunction(): void',
    isPublic: true,
    isAsync: false,
    isStatic: false,
    isAbstract: false,
    language: 'typescript',
    ...overrides
  }
}

