const makeChunkMetadata = (overrides: Partial<ChunkMetadata> = {}): ChunkMetadata => ({
  filePath: 'src/utils.ts',
  fileName: 'utils.ts',
  directory: 'src',
  projectName: 'test-project',
  symbolName: 'helper',
  symbolKind: 'function',
  className: null,
  signature: 'function helper(): void',
  startLine: 10,
  endLine: 20,
  language: 'typescript',
  isPublic: true,
  isAsync: false,
  isStatic: false,
  isAbstract: false,
  hasTests: false,
  importedBy: [],
  pageRank: 0,
  hasDocstring: false,
  lineCount: 11,
  hasDescription: false,
  lastModified: 0,
  indexedAt: 0,
  ...overrides
})

const makeRawChunk = (overrides: Partial<RawChunk> = {}): RawChunk => ({
  id: 'chunk-1',
  filePath: 'src/app.ts',
  symbolName: 'myFunction',
  symbolKind: 'function',
  body: 'function myFunction() { return 42; }',
  startLine: 1,
  endLine: 10,
  signature: 'function myFunction(): number',
  isPublic: true,
  isAsync: false,
  isStatic: false,
  isAbstract: false,
  language: 'typescript',
  ...overrides
})

/** Extended chunk for buildChunkHeader */
const makeHeaderChunk = (overrides: Record<string, unknown> = {}) => ({
  ...makeRawChunk(),
  imports: [] as string[],
  className: null as string | null,
  ...overrides
})

describe('buildChunkHeader', () => {
  test('formats function header correctly', () => {
    const chunk = makeHeaderChunk({ filePath: 'src/utils.ts', symbolName: 'helper', symbolKind: 'function' })
