export interface AgentSessionStatusInput {
  role: AgentRole
  agentId: string
  currentStatus: 'idle' | 'thinking' | 'writing' | 'reviewing' | 'failed'
  tokenUsage: number
  contextTokens?: number
  elapsedMs: number
  activeMcpTools?: string[]
}

