import { ipcMain, type BrowserWindow } from 'electron'
import log from 'electron-log/main'
import { IPC_CHANNELS } from '../../shared/constants'
import { validateSender } from './validate-sender'
import { safeWindowSend } from './safe-send'

const MIN_ZOOM = 0.5
const MAX_ZOOM = 2.0
const ZOOM_STEP = 0.1

export function registerZoomIpc(mainWindow: BrowserWindow): void {
  const clamp = (val: number): number => {
    const snapped = Math.round(val / ZOOM_STEP) * ZOOM_STEP
    return Math.round(Math.max(MIN_ZOOM, Math.min(MAX_ZOOM, snapped)) * 100) / 100
  }

  const notifyRenderer = (factor: number): void => {
    safeWindowSend(mainWindow, IPC_CHANNELS.ZOOM_CHANGED, factor)
  }

  ipcMain.handle(IPC_CHANNELS.ZOOM_GET, (event) => {
    validateSender(event)
    return clamp(mainWindow.webContents.getZoomFactor())
  })

  ipcMain.handle(IPC_CHANNELS.ZOOM_IN, (event) => {
    validateSender(event)
    const current = mainWindow.webContents.getZoomFactor()
    const next = clamp(current + ZOOM_STEP)
    mainWindow.webContents.setZoomFactor(next)
    notifyRenderer(next)
    return next
  })

  ipcMain.handle(IPC_CHANNELS.ZOOM_OUT, (event) => {
    validateSender(event)
    const current = mainWindow.webContents.getZoomFactor()
    const next = clamp(current - ZOOM_STEP)
    mainWindow.webContents.setZoomFactor(next)
    notifyRenderer(next)
    return next
  })

  ipcMain.handle(IPC_CHANNELS.ZOOM_RESET, (event) => {
    validateSender(event)
    mainWindow.webContents.setZoomFactor(1.0)
    notifyRenderer(1.0)
    return 1.0
  })

  ipcMain.handle(IPC_CHANNELS.ZOOM_SET, (event, factor: number) => {
    validateSender(event)
    const clamped = clamp(factor)
    mainWindow.webContents.setZoomFactor(clamped)
    notifyRenderer(clamped)
    return clamped
  })

  // Sync UI when zoom changes via native menu (⌘+, ⌘-, ⌘0) or trackpad pinch
  mainWindow.webContents.on('zoom-changed', () => {
    const factor = mainWindow.webContents.getZoomFactor()
    notifyRenderer(clamp(factor))
  })

  log.info('[Zoom] IPC handlers registered')
}

import { ipcMain } from 'electron'
import { IPC_CHANNELS } from '../../shared/constants'
import { repoService } from '../services/repo.service'
import { workspaceRepository } from '../db/repositories'
import { validateSender } from './validate-sender'
import { requireObject, requireString } from './validate-args'

export function registerRepoIpc(): void {
  // Initialize a git repo at the workspace path
  ipcMain.handle(IPC_CHANNELS.REPO_INIT, async (event, rawArgs: unknown) => {
    validateSender(event)
    const args = requireObject(rawArgs, IPC_CHANNELS.REPO_INIT)
    const workspaceId = requireString(args, 'workspaceId', IPC_CHANNELS.REPO_INIT)

    const workspace = workspaceRepository.findById(workspaceId)
    if (!workspace) throw new Error('Workspace not found')

    await repoService.initRepo(workspace.repoPath)

    // Update workspace record
    const settings = workspaceRepository.getSettings(workspaceId)
    workspaceRepository.updateSettings(workspaceId, { ...settings })
  })

  // Set or update the origin remote URL
  ipcMain.handle(IPC_CHANNELS.REPO_SET_REMOTE, async (event, rawArgs: unknown) => {
    validateSender(event)
    const args = requireObject(rawArgs, IPC_CHANNELS.REPO_SET_REMOTE)
    const workspaceId = requireString(args, 'workspaceId', IPC_CHANNELS.REPO_SET_REMOTE)
    const remoteUrl = requireString(args, 'remoteUrl', IPC_CHANNELS.REPO_SET_REMOTE)

    const workspace = workspaceRepository.findById(workspaceId)
    if (!workspace) throw new Error('Workspace not found')

    await repoService.setRemote(workspace.repoPath, remoteUrl)
  })

  // Get repo info (isRepo, hasRemote, remoteUrl, currentBranch)
  ipcMain.handle(IPC_CHANNELS.REPO_GET_INFO, async (event, rawArgs: unknown) => {
    validateSender(event)
    const args = requireObject(rawArgs, IPC_CHANNELS.REPO_GET_INFO)
    const workspaceId = requireString(args, 'workspaceId', IPC_CHANNELS.REPO_GET_INFO)

    const workspace = workspaceRepository.findById(workspaceId)
    if (!workspace) throw new Error('Workspace not found')

    return repoService.getRepoInfo(workspace.repoPath)
  })

  // List local and remote branches
  ipcMain.handle(IPC_CHANNELS.REPO_LIST_BRANCHES, async (event, rawArgs: unknown) => {
    validateSender(event)
    const args = requireObject(rawArgs, IPC_CHANNELS.REPO_LIST_BRANCHES)
    const workspaceId = requireString(args, 'workspaceId', IPC_CHANNELS.REPO_LIST_BRANCHES)

    const workspace = workspaceRepository.findById(workspaceId)
    if (!workspace) throw new Error('Workspace not found')

    return repoService.listBranches(workspace.repoPath)
  })
}

