import { readFileSync } from 'node:fs'
import { join } from 'node:path'
import { dbLogger } from '../logger'
import { specialistRepository } from '../db/repositories/specialist.repository'
import { skillRepository } from '../db/repositories/skill.repository'
import { workspaceDeployService } from './workspace-deploy.service'
import { skillSummaryService } from './skill-summary.service'
import type {
  SyncDiff,
  SyncResult,
  DiscoveredAgent,
  DiscoveredSkill,
  Specialist,
  Skill
} from '../../shared/types'

/**
 * AgentSyncService — bridges workspace YAML files with the SQLite database.
 *
 * The DB is the primary source of truth for specialist definitions.
 * Workspace YAMLs (if present) are synced into the DB on workspace open.
 * Sync is workspace-scoped — triggered on workspace open or via Settings UI.
 */
export class AgentSyncService {
  /** Core agent IDs that are managed via DB prompts, not YAML sync */
  private readonly CORE_AGENT_IDS = new Set(['specialist', 'generalist', 'generalist-agent'])

  /**
   * Compare workspace YAMLs against DB state.
   * Does NOT mutate anything — pure read + diff.
   */
  computeDiff(workspacePath: string): SyncDiff {
    // 1. Scan workspace YAMLs (only deployed agents in the workspace, excluding core agents)
    const yamlAgents = this.getDeployedWorkspaceAgents(workspacePath).filter(
      (a) => !this.CORE_AGENT_IDS.has(a.parsed.name)
    )
    const yamlSkills = this.getDeployedWorkspaceSkills(workspacePath)

    // 2. Load all specialists from DB
    const dbSpecialists = specialistRepository.findAll()
    const dbSkills = skillRepository.findAll()

    // 3. Build lookup maps
    const dbByAgentId = new Map<string, Specialist>()
    for (const sp of dbSpecialists) {
      dbByAgentId.set(sp.agentId, sp)
    }

    const yamlByName = new Map<string, DiscoveredAgent>()
    for (const agent of yamlAgents) {
      yamlByName.set(agent.parsed.name, agent)
    }

    const dbSkillsByFilename = new Map<string, Skill>()
    for (const sk of dbSkills) {
      dbSkillsByFilename.set(sk.filename, sk)
    }

    // 4. Classify specialists
    const newSpecialists: DiscoveredAgent[] = []
    const updatedSpecialists: SyncDiff['updatedSpecialists'] = []
    const unchangedSpecialists: Specialist[] = []
    const matchedAgentIds = new Set<string>()

    for (const agent of yamlAgents) {
      const agentId = agent.parsed.name
      const dbRecord = dbByAgentId.get(agentId)

      if (!dbRecord) {
        newSpecialists.push(agent)
      } else {
        matchedAgentIds.add(agentId)
        const changes = this.detectChanges(agent, dbRecord)
        if (changes.length > 0) {
          updatedSpecialists.push({ agent, dbRecord, changes })
        } else {
          unchangedSpecialists.push(dbRecord)
        }
      }
    }

    // DB records not matched by any YAML and originally synced from YAML
    const removedSpecialists = dbSpecialists.filter(
      (sp) => !matchedAgentIds.has(sp.agentId) && sp.sourceYaml !== null
    )

    // 5. Classify skills
    const allReferencedSkillNames = new Set<string>()
    for (const agent of yamlAgents) {
      for (const skillRef of agent.parsed.skills) {
        allReferencedSkillNames.add(skillRef)
      }
    }

    const newSkills: DiscoveredSkill[] = []
    const unchangedSkills: Skill[] = []
    const matchedSkillFilenames = new Set<string>()

    for (const skillName of allReferencedSkillNames) {
      // Skills are stored in DB by their filename (e.g. "electron-pro.md")
      // But YAML references use the directory name (e.g. "electron-pro")
      // The file_path in DB points to the SKILL.md location
      const matchingDbSkill = dbSkills.find(
        (sk) =>
          sk.filename === `${skillName}.md` ||
          sk.name.toLowerCase().replace(/\s+/g, '-') === skillName
      )

      if (matchingDbSkill) {
        matchedSkillFilenames.add(matchingDbSkill.filename)
        unchangedSkills.push(matchingDbSkill)
      } else {
        // Check if skill directory exists in workspace
        const discoveredSkill = yamlSkills.find((s) => s.name === skillName)
        if (discoveredSkill && discoveredSkill.hasSkillMd) {
          newSkills.push(discoveredSkill)
        }
      }
    }

    // Skills in DB but no longer referenced by any YAML
    const removedSkills = dbSkills.filter((sk) => !matchedSkillFilenames.has(sk.filename))

    const hasChanges =
      newSpecialists.length > 0 ||
      updatedSpecialists.length > 0 ||
      removedSpecialists.length > 0 ||
      newSkills.length > 0

    return {
      newSpecialists,
      updatedSpecialists,
      removedSpecialists,
      unchangedSpecialists,
      newSkills,
      removedSkills,
      unchangedSkills,
      hasChanges
    }
  }

  /**
   * Apply the full sync: create/update/deactivate specialists + skills.
   * Called after user confirms the sync report.
   */
  applySync(workspacePath: string, _options?: { skipRemoved?: boolean }): SyncResult {
    const result: SyncResult = {
      imported: 0,
      updated: 0,
      deactivated: 0,
      skillsImported: 0,
      errors: []
    }

    // ── Step 1: Wipe all YAML-sourced specialists ──
    const dbSpecialists = specialistRepository.findAll()
    for (const sp of dbSpecialists) {
      if (sp.sourceYaml) {
        try {
          specialistRepository.delete(sp.id) // CASCADE removes specialist_skills
          result.deactivated++
        } catch (e) {
          result.errors.push(`Failed to delete specialist "${sp.agentId}": ${(e as Error).message}`)
        }
      }
    }

    // ── Step 2: Import all skills from workspace ──
    const yamlSkills = this.getDeployedWorkspaceSkills(workspacePath)
    for (const discoveredSkill of yamlSkills) {
      if (!discoveredSkill.hasSkillMd) continue
      try {
        this.importSkillFromDiscovered(discoveredSkill)
        result.skillsImported++
        dbLogger.info(`Sync: imported skill "${discoveredSkill.name}"`)
      } catch (e) {
        const msg = `Failed to import skill "${discoveredSkill.name}": ${(e as Error).message}`
        result.errors.push(msg)
        dbLogger.warn(`Sync: ${msg}`)
      }
    }

    // ── Step 3: Re-create all specialists from YAML ──
    const yamlAgents = this.getDeployedWorkspaceAgents(workspacePath)
    for (const agent of yamlAgents) {
      try {
        this.createSpecialistFromAgent(agent)
        result.imported++
        dbLogger.info(`Sync: imported specialist "${agent.parsed.name}"`)
      } catch (e) {
        const msg = `Failed to import specialist "${agent.parsed.name}": ${(e as Error).message}`
        result.errors.push(msg)
        dbLogger.warn(`Sync: ${msg}`)
      }
    }

    // ── Step 4: Link specialists to skills ──
    this.syncSkillAssignments(workspacePath)

    dbLogger.info(
      `Fresh sync complete: ${result.imported} imported, ${result.deactivated} wiped, ${result.skillsImported} skills`
    )

    return result
  }

  /**
   * Auto-sync: computeDiff + apply only NEW items (safe).
   * Used on workspace open — only adds, never removes or overwrites.
   */
  autoSyncNewEntries(workspacePath: string): SyncResult {
    const diff = this.computeDiff(workspacePath)
    const result: SyncResult = {
      imported: 0,
      updated: 0,
      deactivated: 0,
      skillsImported: 0,
      errors: []
    }

    if (!diff.hasChanges) return result

    // Only import NEW skills
    for (const discoveredSkill of diff.newSkills) {
      try {
        this.importSkillFromDiscovered(discoveredSkill)
        result.skillsImported++
        dbLogger.info(`Auto-sync: imported new skill "${discoveredSkill.name}"`)
      } catch (e) {
        const msg = `Failed to auto-import skill "${discoveredSkill.name}": ${(e as Error).message}`
        result.errors.push(msg)
        dbLogger.warn(`Auto-sync: ${msg}`)
      }
    }

    // Only import NEW specialists
    for (const agent of diff.newSpecialists) {
      try {
        this.createSpecialistFromAgent(agent)
        result.imported++
        dbLogger.info(`Auto-sync: imported new specialist "${agent.parsed.name}"`)
      } catch (e) {
        const msg = `Failed to auto-import specialist "${agent.parsed.name}": ${(e as Error).message}`
        result.errors.push(msg)
        dbLogger.warn(`Auto-sync: ${msg}`)
      }
    }

    // Link specialists to skills for new entries
    if (result.imported > 0 || result.skillsImported > 0) {
      this.syncSkillAssignments(workspacePath)
    }

    return result
  }

  // ── Private Helpers ──

  /** Get deployed workspace agents */
  private getDeployedWorkspaceAgents(workspacePath: string): DiscoveredAgent[] {
    const allAgents = workspaceDeployService.scanWorkspaceAgents(workspacePath)
    return allAgents.filter((a) => a.isDeployed)
  }

  /** Get only deployed workspace skills */
  private getDeployedWorkspaceSkills(workspacePath: string): DiscoveredSkill[] {
    return workspaceDeployService.scanWorkspaceSkills(workspacePath)
  }

  /** Compare a YAML agent against its DB record and return list of changes */
  private detectChanges(agent: DiscoveredAgent, dbRecord: Specialist): string[] {
    const changes: string[] = []

    // Compare prompt/body content
    const yamlPrompt = agent.bodyContent.trim()
    const dbPrompt = (dbRecord.prompt ?? '').trim()
    if (yamlPrompt && dbPrompt && yamlPrompt !== dbPrompt) {
      changes.push('prompt changed')
    } else if (yamlPrompt && !dbPrompt) {
      changes.push('prompt added')
    }

    // Compare display name (YAML description → DB displayName is not a 1:1 mapping,
    // but if the source_yaml matches, we can detect display name drift)
    // We skip display name comparison since it's user-customizable

    // Compare skill assignments
    const yamlSkillNames = new Set(agent.parsed.skills)
    const dbSkills = specialistRepository.getAllSkills(dbRecord.id)
    const dbSkillNames = new Set(
      dbSkills.map((sk) => {
        // Reverse-map DB skill filename to YAML skill reference
        const name = sk.filename.replace(/\.md$/, '')
        return name
      })
    )

    const addedSkills = [...yamlSkillNames].filter((s) => !dbSkillNames.has(s))
    const removedSkills = [...dbSkillNames].filter((s) => !yamlSkillNames.has(s))

    if (addedSkills.length > 0 || removedSkills.length > 0) {
      changes.push('skills changed')
    }

    return changes
  }

  /** Create a new specialist from a discovered YAML agent */
  private createSpecialistFromAgent(agent: DiscoveredAgent): Specialist {
    // Check if specialist already exists in DB (from prior sync) for icon/color defaults
    const meta = this.getAgentMeta(agent.parsed.name)

    return specialistRepository.create({
      agentId: agent.parsed.name,
      displayName: meta?.displayName ?? this.formatDisplayName(agent.parsed.name),
      description: agent.parsed.description || '',
      icon: meta?.icon ?? '🔧',
      color: meta?.color ?? '#6366F1',
      prompt: agent.bodyContent || agent.parsed.description || '',
      priority: meta?.priority ?? 100,
      sourceYaml: agent.filename,
      isActive: false
    })
  }

  /** Import a discovered skill into the DB and generate semantic summaries */
  private importSkillFromDiscovered(discovered: DiscoveredSkill): Skill {
    const filename = `${discovered.name}.md`

    // Check if already exists
    const existing = skillRepository.findByFilename(filename)
    if (existing) {
      // Regenerate summaries if stale
      this.generateSkillSummaries(existing)
      return existing
    }

    const skill = skillRepository.create({
      name: discovered.frontmatter?.name ?? this.formatDisplayName(discovered.name),
      description: discovered.frontmatter?.description ?? '',
      filename,
      filePath: join(discovered.dirPath, 'SKILL.md'),
      isActive: false,
      lastUpdatedDate: discovered.lastUpdated ?? undefined
    })

    // Generate semantic summaries for the new skill
    this.generateSkillSummaries(skill)

    return skill
  }

  /** Generate and store semantic summaries for a skill if stale or missing */
  private generateSkillSummaries(skill: Skill): void {
    try {
      const content = readFileSync(skill.filePath, 'utf-8')
      if (!skillSummaryService.isStale(skill, content)) return

      const summaries = skillSummaryService.generateSummaries(content)
      const hash = skillSummaryService.contentHash(content)

      skillRepository.updateSummaries(skill.id, {
        full: summaries.full,
        standard: summaries.standard,
        minimal: summaries.minimal,
        hash
      })

      dbLogger.info(
        `Generated semantic summaries for skill "${skill.name}" ` +
          `(full: ${summaries.full.length}, standard: ${summaries.standard.length}, minimal: ${summaries.minimal.length} chars)`
      )
    } catch (e) {
      dbLogger.warn(
        `Could not generate summaries for skill "${skill.name}": ${(e as Error).message}`
      )
    }
  }

  /** Sync specialist-skill junction table based on YAML skill references */
  private syncSkillAssignments(workspacePath: string): void {
    const yamlAgents = this.getDeployedWorkspaceAgents(workspacePath)
    const dbSkills = skillRepository.findAll()
    const skillByName = new Map<string, Skill>()
    for (const sk of dbSkills) {
      // Map by directory name (filename without .md extension)
      skillByName.set(sk.filename.replace(/\.md$/, ''), sk)
    }

    for (const agent of yamlAgents) {
      const specialist = specialistRepository.findByAgentId(agent.parsed.name)
      if (!specialist) continue

      const currentSkills = specialistRepository.getAllSkills(specialist.id)
      const currentSkillIds = new Set(currentSkills.map((s) => s.id))

      // Build the set of skill IDs that YAML expects
      const expectedSkillIds = new Set<string>()
      for (const skillRef of agent.parsed.skills) {
        const skill = skillByName.get(skillRef)
        if (skill) {
          expectedSkillIds.add(skill.id)
        }
      }

      // Add missing skill assignments
      for (const skillId of expectedSkillIds) {
        if (!currentSkillIds.has(skillId)) {
          try {
            specialistRepository.assignSkill(specialist.id, skillId)
          } catch {
            // Already assigned or constraint issue — ignore
          }
        }
      }

      // Remove stale skill assignments no longer in YAML
      for (const existingSkill of currentSkills) {
        if (!expectedSkillIds.has(existingSkill.id)) {
          try {
            specialistRepository.removeSkill(specialist.id, existingSkill.id)
          } catch {
            // Already removed or constraint issue — ignore
          }
        }
      }
    }
  }

  /**
   * Get agent meta for icon/color/displayName defaults.
   * First checks if the specialist already exists in DB (from a prior sync),
   * preserving user customizations. Falls back to generic defaults for first-time imports.
   */
  private getAgentMeta(
    agentId: string
  ): { icon: string; color: string; displayName: string; priority: number } | null {
    // Check if specialist already exists in DB (from prior sync)
    const existing = specialistRepository.findByAgentId(agentId)
    if (existing) {
      return {
        icon: existing.icon,
        color: existing.color,
        displayName: existing.displayName,
        priority: existing.priority
      }
    }
    // Fallback for first-time import — generic defaults
    return null
  }

  /** Convert kebab-case agent ID to display name */
  private formatDisplayName(agentId: string): string {
    return agentId
      .split('-')
      .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
      .join(' ')
  }
}

export const agentSyncService = new AgentSyncService()

import type { BrowserWindow } from 'electron'
import { ipcMain } from 'electron'
import { IPC_CHANNELS } from '../../shared/constants'
import { ollamaManager } from '../services/ollama-manager.service'
import { omlxManager } from '../services/omlx-manager.service'
import { validateSender } from './validate-sender'
import { safeWindowSend } from './safe-send'
import type { PullProgress } from '../../shared/types'

export function registerOllamaIpc(mainWindow: BrowserWindow): void {
  // Forward pull progress events to the renderer
  ollamaManager.on('pullProgress', (progress: PullProgress) => {
    safeWindowSend(mainWindow, IPC_CHANNELS.OLLAMA_PULL_PROGRESS, progress)
  })
  ollamaManager.on('pullComplete', (model: string) => {
    safeWindowSend(mainWindow, IPC_CHANNELS.OLLAMA_PULL_COMPLETE, model)
  })
  ollamaManager.on('pullError', (error: string) => {
    safeWindowSend(mainWindow, IPC_CHANNELS.OLLAMA_PULL_ERROR, error)
  })

  // ── Ollama handlers ──

  ipcMain.handle(IPC_CHANNELS.OLLAMA_CHECK_STATUS, async (event, args?: { baseUrl?: string }) => {
    validateSender(event)
    return ollamaManager.checkStatus(args?.baseUrl)
  })

  ipcMain.handle(
    IPC_CHANNELS.OLLAMA_PULL_MODEL,
    async (event, args: { model: string; baseUrl?: string }) => {
      validateSender(event)
      await ollamaManager.pullModel(args.model, args.baseUrl)
    }
  )

  ipcMain.handle(IPC_CHANNELS.OLLAMA_CANCEL_PULL, (event) => {
    validateSender(event)
    ollamaManager.cancelPull()
  })

  ipcMain.handle(
    IPC_CHANNELS.OLLAMA_REMOVE_MODEL,
    async (event, args: { model: string; baseUrl?: string }) => {
      validateSender(event)
      await ollamaManager.removeModel(args.model, args.baseUrl)
    }
  )

  ipcMain.handle(IPC_CHANNELS.OLLAMA_START, async (event) => {
    validateSender(event)
    return ollamaManager.startOllama()
  })

  // ── oMLX handlers ──

  ipcMain.handle(
    IPC_CHANNELS.OMLX_CHECK_STATUS,
    async (event, args?: { baseUrl?: string; apiKey?: string }) => {
      validateSender(event)
      return omlxManager.checkStatus(args?.baseUrl, args?.apiKey)
    }
  )

  ipcMain.handle(IPC_CHANNELS.OMLX_START, async (event) => {
    validateSender(event)
    return omlxManager.startOmlx()
  })

  ipcMain.handle(IPC_CHANNELS.OMLX_ADMIN_URL, (event, args?: { baseUrl?: string }) => {
    validateSender(event)
    return omlxManager.getAdminUrl(args?.baseUrl)
  })

  ipcMain.handle(
    IPC_CHANNELS.OMLX_LOAD_MODEL,
    async (event, args: { modelId: string; baseUrl?: string; apiKey?: string }) => {
      validateSender(event)
      await omlxManager.loadModel(args.modelId, args.baseUrl, args.apiKey)
    }
  )

  ipcMain.handle(
    IPC_CHANNELS.OMLX_UNLOAD_MODEL,
    async (event, args: { modelId: string; baseUrl?: string; apiKey?: string }) => {
      validateSender(event)
      await omlxManager.unloadModel(args.modelId, args.baseUrl, args.apiKey)
    }
  )
}

import type { BrowserWindow } from 'electron'
import { ipcMain } from 'electron'
import log from 'electron-log/main'
import { IPC_CHANNELS } from '../../shared/constants'
import { codeGraphService } from '../services/code-graph.service'
import { validateSender } from './validate-sender'
import { safeWindowSend } from './safe-send'
import { workspaceRepository } from '../db/repositories'
import type { CodeGraphIndexingState } from '../../shared/types'
import { libraryDocService } from '../services/library-doc.service'

export function registerCodeGraphIpc(mainWindow: BrowserWindow): void {
  // Forward progress events to renderer
  codeGraphService.on('progress', (state: CodeGraphIndexingState) => {
    safeWindowSend(mainWindow, IPC_CHANNELS.CODE_GRAPH_PROGRESS, state)
  })

  ipcMain.handle(
    IPC_CHANNELS.CODE_GRAPH_INDEX_START,
    async (event, args: { workspaceId: string }) => {
      validateSender(event)

      const workspace = workspaceRepository.findById(args.workspaceId)
      if (!workspace) throw new Error('Workspace not found')

      const state = codeGraphService.getIndexingState(args.workspaceId)
      if (state.status !== 'idle' && state.status !== 'complete' && state.status !== 'error') {
        throw new Error('Code graph indexing is already in progress')
      }

      // Fire-and-forget — progress events stream to renderer
      codeGraphService
        .indexWorkspace(args.workspaceId, workspace.repoPath)
        .then(() => {
          // Index library documentation in the background after code graph completes
          try {
            const result = libraryDocService.indexWorkspaceDependencies(
              args.workspaceId,
              workspace.repoPath
            )
            log.info(
              `[library-docs] Indexed ${result.indexed}, skipped ${result.skipped}` +
                (result.errors.length > 0 ? `, errors: ${result.errors.length}` : '')
            )
          } catch (e) {
            log.warn(
              `[library-docs] Indexing failed: ${e instanceof Error ? e.message : String(e)}`
            )
          }
        })
        .catch((err) => log.error('[CodeGraph] Indexing pipeline failed:', err))
    }
  )

  ipcMain.handle(IPC_CHANNELS.CODE_GRAPH_GET_STATUS, (event, args: { workspaceId: string }) => {
    validateSender(event)
    return codeGraphService.getIndexingState(args.workspaceId)
  })

  ipcMain.handle(IPC_CHANNELS.CODE_GRAPH_HAS_INDEX, (event, args: { workspaceId: string }) => {
    validateSender(event)
    return codeGraphService.hasPersistedIndex(args.workspaceId)
  })
}

import type { BrowserWindow } from 'electron'
import { ipcMain } from 'electron'
import { IPC_CHANNELS, OMLX_DEFAULT_PORT, OLLAMA_DEFAULT_PORT } from '../../shared/constants'
import { localEmbeddingProvider } from '../services/local-embedding.provider'
import { omlxManager } from '../services/omlx-manager.service'
import { ollamaManager } from '../services/ollama-manager.service'
import { workspaceRepository } from '../db/repositories'
import { validateSender } from './validate-sender'
import type { EmbeddingModelStatus, LocalLLMBackend } from '../../shared/types'

export function registerEmbeddingIpc(mainWindow: BrowserWindow): void {
  // Forward oMLX embedding events to the renderer
  localEmbeddingProvider.on('modelReady', () => {
    mainWindow.webContents.send(IPC_CHANNELS.EMBEDDING_MODEL_READY)
  })
  localEmbeddingProvider.on('modelError', (error: string) => {
    mainWindow.webContents.send(IPC_CHANNELS.EMBEDDING_MODEL_ERROR, error)
  })

  ipcMain.handle(
    IPC_CHANNELS.EMBEDDING_CHECK_STATUS,
    async (event, args?: { baseUrl?: string; apiKey?: string; workspaceId?: string }): Promise<EmbeddingModelStatus> => {
      validateSender(event)

      // Align facade backend with workspace preferences before probing status
      if (args?.workspaceId) {
        localEmbeddingProvider.configureForWorkspace(args.workspaceId)
      }

      // Resolve config: explicit args → workspace settings → defaults
      let resolvedBaseUrl = args?.baseUrl
      let resolvedApiKey = args?.apiKey
      let activeBackend: LocalLLMBackend = 'omlx'
      let ollamaEmbModel: string | null = null

      if (args?.workspaceId) {
        try {
          const settings = workspaceRepository.getSettings(args.workspaceId)
          activeBackend = (settings?.localLlmBackend as LocalLLMBackend) ?? 'omlx'
          ollamaEmbModel = (settings?.ollamaEmbeddingModel as string) ?? null
          if (!resolvedBaseUrl) {
            const host = (settings?.localHost as string) ?? '127.0.0.1'
            const defaultPort = activeBackend === 'ollama' ? OLLAMA_DEFAULT_PORT : OMLX_DEFAULT_PORT
            const port = (settings?.localPort as number) ?? defaultPort
            resolvedBaseUrl = `http://${host}:${port}`
          }
          if (!resolvedApiKey && settings?.localApiKey) {
            resolvedApiKey = settings.localApiKey as string
          }
        } catch {
          // Fall through to defaults
        }
      }

      // ── Ollama branch ──
      if (activeBackend === 'ollama') {
        const ollamaUrl = resolvedBaseUrl ?? 'http://127.0.0.1:11434'
        const ollamaStatus = await ollamaManager.checkStatus(ollamaUrl)

        // Auto-initialize when Ollama + embedding model are available
        if (ollamaStatus.running && ollamaEmbModel && !localEmbeddingProvider.isReady) {
          localEmbeddingProvider
            .initialize(ollamaUrl)
            .catch(() => { /* non-fatal */ })
        }

        return {
          ready: localEmbeddingProvider.isReady,
          backend: 'ollama',
          // oMLX fields — zeroed out so renderer doesn't show stale oMLX data
          omlxRunning: false,
          omlxInstalled: false,
          omlxEmbeddingModelId: null,
          omlxEmbeddingModelLoaded: false,
          omlxAdminApiAvailable: false,
          // Ollama fields
          ollamaRunning: ollamaStatus.running,
          ollamaEmbeddingModel: ollamaEmbModel
        }
      }

      // ── oMLX branch (default) ──
      const status = await omlxManager.checkStatus(resolvedBaseUrl, resolvedApiKey)
      const embeddingModel = status.allModels?.find(
        (m) => m.loaded && m.modelType === 'embedding'
      )

      // When admin API is unavailable, synthesize allModels from /v1/models
      const allModels = status.allModels ?? []

      // Auto-initialize embedding provider when a loaded embedding model is found
      // but the provider hasn't been initialized yet
      if (embeddingModel?.loaded && !localEmbeddingProvider.isReady) {
        localEmbeddingProvider
          .initialize(resolvedBaseUrl, resolvedApiKey)
          .catch(() => { /* non-fatal — UI will show the model status regardless */ })
      }

      return {
        ready: localEmbeddingProvider.isReady,
        backend: 'omlx',
        omlxRunning: status.running,
        omlxInstalled: status.installed,
        omlxEmbeddingModelId: embeddingModel?.id ?? null,
        omlxEmbeddingModelLoaded: !!embeddingModel?.loaded,
        omlxAllModels: allModels.length > 0 ? allModels : undefined,
        omlxAdminApiAvailable: !!status.allModels
      }
    }
  )

  ipcMain.handle(IPC_CHANNELS.EMBEDDING_INITIALIZE, async (event, args?: { baseUrl?: string; apiKey?: string }) => {
    validateSender(event)
    await localEmbeddingProvider.initialize(args?.baseUrl, args?.apiKey)
  })
}

import { app, ipcMain } from 'electron'
import { rmSync } from 'node:fs'
import { join } from 'node:path'
import simpleGit from 'simple-git'
import {
  conversationRepository,
  conversationSpecialistRepository,
  messageRepository,
  workspaceRepository,
  specialistRepository
} from '../db/repositories'
import { todoRepository } from '../db/repositories/todo.repository'
import { chatAgentService } from '../services'
import { lifecycleRegistry } from '../services/conversation-lifecycle'
import { chatStreamService } from '../services/chat-stream.service'
import { repoService } from '../services/repo.service'
import { IPC_CHANNELS, VALID_COMMUNICATION_TONES } from '../../shared/constants'
import type { CommunicationTone, ConversationMode, LLMProvider, ModelRoleMap, ConversationModelSnapshot } from '../../shared/types'
import { buildConversationModelSnapshot } from '../services/model-config.service'
import { chatIpcLogger } from '../logger'
import { validateSender } from './validate-sender'
import { completeStreamMetrics } from './chunk-router'
import {
  requireObject,
  requireString,
  optionalString,
  requireStringArray,
  requirePlainObject
} from './validate-args'

const log = chatIpcLogger

// ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
// Extracted handlers
// ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

async function handleCreateConversation(args: {
  workspaceId: string
  title?: string
  mode?: ConversationMode
  personaSpecialistId?: string
  /** @deprecated Use routingOverrides — kept as fallback */
  llmProvider?: LLMProvider
  /** Per-conversation routing overrides (Phase 1 addition) */
  routingOverrides?: Partial<ModelRoleMap>
  mcpOverrides?: Record<string, boolean>
  communicationTone?: CommunicationTone | null
  /** Audit run ID that sourced this conversation (Audit → Chat handoff) */
  sourceAuditRunId?: string
  /** Explicit branch name override — user-selected from branch picker at creation */
  branchName?: string
  /** When true, auto-create a branch from the title (overrides workspace gitAutoBranch setting) */
  autoBranch?: boolean
}): Promise<ReturnType<typeof conversationRepository.create>> {
  const ch = IPC_CHANNELS.CHAT_CREATE_CONVERSATION
  const {
    workspaceId,
    title,
    mode,
    personaSpecialistId,
    llmProvider,
    routingOverrides,
    mcpOverrides,
    communicationTone,
    sourceAuditRunId,
    branchName: explicitBranchName,
    autoBranch
  } = args

  if (title !== undefined && title.length > 500) {
    throw new Error(`${ch}: title too long (max 500 chars)`)
  }

  const validModes = ['plan', 'build', 'danger']
  if (mode !== undefined && !validModes.includes(mode)) {
    throw new Error(`${ch}: mode must be 'plan', 'build', or 'danger'`)
  }

  if (
    communicationTone !== undefined &&
    communicationTone !== null &&
    !VALID_COMMUNICATION_TONES.includes(
      communicationTone as (typeof VALID_COMMUNICATION_TONES)[number]
    )
  ) {
    throw new Error(`${ch}: invalid communication tone`)
  }

  if (personaSpecialistId) {
    const specialist = specialistRepository.findById(personaSpecialistId)
    if (!specialist) throw new Error(`${ch}: invalid persona specialist ID`)
  }

  // Build model config snapshot — frozen at creation time
  const settings = workspaceRepository.getSettings(workspaceId)
  const snapshot = buildConversationModelSnapshot(workspaceId, llmProvider, routingOverrides)

  // Per-conversation LLM provider: derived from snapshot's plan action provider.
  // snapshot.plan.provider is always defined (resolveAssignment always returns a provider).
  const resolvedProvider: LLMProvider = snapshot.plan.provider

  const conversation = conversationRepository.create(
    workspaceId,
    title,
    mode,
    personaSpecialistId,
    resolvedProvider,
    mcpOverrides,
    communicationTone,
    undefined, // type
    snapshot,
    sourceAuditRunId
  )
  conversationSpecialistRepository.initFromWorkspaceDefaults(conversation.id)

  // Auto-attach the workspace's Project Specialist (if one exists).
  try {
    const projectSpecialist = specialistRepository.findByAgentId(
      `workspace-specialist-${workspaceId}`
    )
    if (projectSpecialist) {
      conversationSpecialistRepository.upsert(conversation.id, projectSpecialist.id, {
        isActive: true
      })
    }
  } catch (e) {
    log.warn('Project Specialist auto-attach failed:', e)
  }

  // Git setup: capture source branch + optionally create auto-branch
  const wsRow = workspaceRepository.findById(workspaceId)
  if (wsRow?.repoPath) {
    try {
      const git = simpleGit(wsRow.repoPath)
      const isRepo = await git.checkIsRepo()
      if (isRepo) {
        // Capture the source branch at conversation creation time (always, not just gitAutoBranch)
        try {
          const sourceBranch = await git.revparse(['--abbrev-ref', 'HEAD'])
          conversationRepository.updateSourceBranch(conversation.id, sourceBranch)
          conversation.sourceBranch = sourceBranch
        } catch (e) {
          log.warn('Source branch capture failed (non-fatal):', e)
        }

        // Branch-per-conversation: create/checkout branch if explicitly requested, auto-branch selected, or gitAutoBranch enabled
        if (explicitBranchName || autoBranch === true || (autoBranch !== false && settings.gitAutoBranch)) {
          try {
            let branchName: string
            if (explicitBranchName) {
              // User provided an explicit branch name from the branch picker
              branchName = explicitBranchName
            } else {
              // Auto-generate branch name from conversation title
              const branchTitle = conversation.title || 'new-conversation'
              const slug = branchTitle
                .toLowerCase()
                .replace(/[^a-z0-9]+/g, '-')
                .replace(/^-|-$/g, '')
                .slice(0, 50)
              branchName = `chat/${slug}-${conversation.id.slice(0, 8)}`
            }

            // Smart checkout: check if branch exists, then checkout vs create
            const localBranches = await git.branchLocal()
            if (localBranches.all.includes(branchName)) {
              await git.checkout(branchName)
              log.info(`Checked out existing branch: ${branchName}`)
            } else {
              await git.checkoutLocalBranch(branchName)
              log.info(`Created and checked out new branch: ${branchName}`)
            }

            conversationRepository.updateBranchName(conversation.id, branchName)
            conversation.branchName = branchName
          } catch (e) {
            log.warn('Branch creation/checkout failed (non-fatal):', e)
          }
        }
      }
    } catch (e) {
      log.warn('Git initialization for conversation failed (non-fatal):', e)
    }
  }

  return conversation
}

async function handleSwitchBranch(
  conversationId: string
): Promise<{ switched: boolean; branch: string | null }> {
  const conversation = conversationRepository.findById(conversationId)
  if (!conversation?.branchName) return { switched: false, branch: null }

  const workspace = workspaceRepository.findById(conversation.workspaceId)
  if (!workspace) throw new Error('Workspace not found')

  const git = simpleGit(workspace.repoPath)
  const currentBranch = await git.revparse(['--abbrev-ref', 'HEAD'])

  // Already on the right branch
  if (currentBranch === conversation.branchName) {
    return { switched: false, branch: conversation.branchName }
  }

  // Auto-WIP-commit uncommitted changes on current branch
  const status = await git.status()
  const dirtyFiles = [
    ...status.modified,
    ...status.created,
    ...status.not_added,
    ...status.deleted,
    ...status.renamed.map((r) => r.to)
  ]
  if (dirtyFiles.length > 0) {
    try {
      await git.add(dirtyFiles)
      await git.commit('WIP: auto-save from conversation switch')
      log.info(`WIP commit on ${currentBranch} (${dirtyFiles.length} files)`)
    } catch (e) {
      log.warn('WIP auto-commit failed (proceeding with checkout):', e)
    }
  }

  // Switch to conversation's branch
  try {
    await git.checkout(conversation.branchName)
    log.info(`Switched to branch: ${conversation.branchName}`)
    return { switched: true, branch: conversation.branchName }
  } catch (e) {
    log.warn(`Failed to switch to branch ${conversation.branchName}:`, e)
    throw new Error(`Failed to switch to branch: ${conversation.branchName}`)
  }
}

// ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
// Conversation CRUD — create, delete, rename, reorder, list, get messages
// ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

export function registerConversationCrudIpc(): void {
  ipcMain.handle(IPC_CHANNELS.CHAT_GET_CONVERSATIONS, async (event, rawArgs: unknown) => {
    validateSender(event)
    const ch = IPC_CHANNELS.CHAT_GET_CONVERSATIONS
    const args = requireObject(rawArgs, ch)
    const workspaceId = requireString(args, 'workspaceId', ch)

    return conversationRepository.findByWorkspace(workspaceId)
  })

  ipcMain.handle(IPC_CHANNELS.CHAT_CREATE_CONVERSATION, async (event, rawArgs: unknown) => {
    validateSender(event)
    const ch = IPC_CHANNELS.CHAT_CREATE_CONVERSATION
    const args = requireObject(rawArgs, ch)
    return handleCreateConversation({
      workspaceId: requireString(args, 'workspaceId', ch),
      title: optionalString(args, 'title', ch),
      mode: optionalString(args, 'mode', ch) as ConversationMode | undefined,
      personaSpecialistId: optionalString(args, 'personaSpecialistId', ch),
      llmProvider: optionalString(args, 'llmProvider', ch) as LLMProvider | undefined,
      routingOverrides: args.routingOverrides as Partial<ModelRoleMap> | undefined,
      mcpOverrides: args.mcpOverrides as Record<string, boolean> | undefined,
      communicationTone: args.communicationTone as CommunicationTone | null | undefined,
      sourceAuditRunId: optionalString(args, 'sourceAuditRunId', ch),
      branchName: optionalString(args, 'branchName', ch),
      autoBranch: typeof args.autoBranch === 'boolean' ? args.autoBranch : undefined
    })
  })

  ipcMain.handle(IPC_CHANNELS.CHAT_GET_MESSAGES, async (event, rawArgs: unknown) => {
    validateSender(event)
    const ch = IPC_CHANNELS.CHAT_GET_MESSAGES
    const args = requireObject(rawArgs, ch)
    const conversationId = requireString(args, 'conversationId', ch)

    return messageRepository.findByConversation(conversationId)
  })

  ipcMain.handle(IPC_CHANNELS.CHAT_GET_TODOS, async (event, rawArgs: unknown) => {
    validateSender(event)
    const ch = IPC_CHANNELS.CHAT_GET_TODOS
    const args = requireObject(rawArgs, ch)
    const conversationId = requireString(args, 'conversationId', ch)
    return todoRepository.findByConversation(conversationId)
  })

  ipcMain.handle(IPC_CHANNELS.CHAT_SET_PLAN_ACTION, (event, rawArgs: unknown) => {
    validateSender(event)
    const ch = IPC_CHANNELS.CHAT_SET_PLAN_ACTION
    const args = requireObject(rawArgs, ch)
    const messageId = requireString(args, 'messageId', ch)
    const action = requireString(args, 'action', ch)
    messageRepository.updatePlanAction(messageId, action)
    return { success: true }
  })

  ipcMain.handle(IPC_CHANNELS.CHAT_DELETE_CONVERSATION, async (event, rawArgs: unknown) => {
    validateSender(event)
    const ch = IPC_CHANNELS.CHAT_DELETE_CONVERSATION
    const args = requireObject(rawArgs, ch)
    const conversationId = requireString(args, 'conversationId', ch)

    // CONV-DEL-RACE-01: Abort active stream before cascade-delete to prevent
    // FK violations when finalizeStreamMessage() races with conversation deletion.
    if (lifecycleRegistry.isStreaming(conversationId)) {
      // CHAT-METRICS-ABORT-ORPHAN-01: Clean up metrics before abort to prevent leak.
      completeStreamMetrics(conversationId, 'aborted')
      lifecycleRegistry.abort(conversationId, 'conversation-deleted')
    }

    chatAgentService.clearSession(conversationId)
    // N1-FIX: Clear per-conversation memory dedupe state so facts can be
    // re-injected in future conversations about the same topics.
    chatStreamService.clearConversationMemoryState(conversationId)

    conversationRepository.delete(conversationId)

    // Clean up clipboard images for this conversation
    try {
      const imageDir = join(app.getPath('userData'), 'chat-images', conversationId)
      rmSync(imageDir, { recursive: true, force: true })
    } catch {
      /* best effort — directory may not exist */
    }
  })

  ipcMain.handle(IPC_CHANNELS.CHAT_RENAME, async (event, rawArgs: unknown) => {
    validateSender(event)
    const ch = IPC_CHANNELS.CHAT_RENAME
    const args = requireObject(rawArgs, ch)
    const conversationId = requireString(args, 'conversationId', ch)
    const title = requireString(args, 'title', ch)

    if (title.length > 500) {
      throw new Error(`${ch}: title too long (max 500 chars)`)
    }

    const updated = conversationRepository.updateTitle(conversationId, title.trim())
    if (!updated) throw new Error('Conversation not found')
    return updated
  })

  // ── Get file changes from git status for a conversation's workspace ──
  ipcMain.handle(IPC_CHANNELS.CHAT_GET_FILE_CHANGES, async (event, rawArgs: unknown) => {
    validateSender(event)
    const ch = IPC_CHANNELS.CHAT_GET_FILE_CHANGES
    const args = requireObject(rawArgs, ch)
    const conversationId = requireString(args, 'conversationId', ch)

    const conversation = conversationRepository.findById(conversationId)
    if (!conversation) throw new Error('Conversation not found')
    const workspace = workspaceRepository.findById(conversation.workspaceId)
    if (!workspace) throw new Error('Workspace not found')

    return repoService.getUncommittedFileDetails(workspace.repoPath)
  })

  // ── Switch git branch for a conversation ──
  ipcMain.handle(IPC_CHANNELS.CHAT_SWITCH_BRANCH, async (event, rawArgs: unknown) => {
    validateSender(event)
    const ch = IPC_CHANNELS.CHAT_SWITCH_BRANCH
    const args = requireObject(rawArgs, ch)
    return handleSwitchBranch(requireString(args, 'conversationId', ch))
  })

  // ── Reorder conversations ──
  ipcMain.handle(IPC_CHANNELS.CONVERSATION_REORDER, async (event, rawArgs: unknown) => {
    validateSender(event)
    const ch = IPC_CHANNELS.CONVERSATION_REORDER
    const args = requireObject(rawArgs, ch)
    const orderedIds = requireStringArray(args, 'orderedIds', ch)
    conversationRepository.reorderConversations(orderedIds)
  })

  // ── Resume at checkpoint — undo to a specific message point ──
  ipcMain.handle(IPC_CHANNELS.CHAT_RESUME_AT, async (event, rawArgs: unknown) => {
    validateSender(event)
    const ch = IPC_CHANNELS.CHAT_RESUME_AT
    const args = requireObject(rawArgs, ch)
    const messageId = requireString(args, 'messageId', ch)
    const conversationId = requireString(args, 'conversationId', ch)

    // RESUME-ORPHAN-01: Look up the message to get its timestamp for truncation
    const message = messageRepository.findById(messageId)
    if (!message) throw new Error(`${ch}: message not found`)

    await chatAgentService.resumeAt(messageId)

    // Clean up all post-resume database state (mirroring CHECKPOINT_REWIND)
    try {
      messageRepository.truncateAfterTimestamp(conversationId, message.createdAt)
    } catch (err) {
      log.error(`[resumeAt] Message truncation failed:`, err)
    }

    // RESUME-PENDING-STATE-01: Clear pending compaction/context and stale session ID
    chatAgentService.clearConversationPendingState(conversationId)
    try {
      conversationRepository.updateSessionId(conversationId, '')
    } catch (err) {
      log.error(`[resumeAt] Session ID clear failed:`, err)
    }
  })

  // ── Update per-conversation external MCP overrides ──
  ipcMain.handle(IPC_CHANNELS.CHAT_UPDATE_MCP_OVERRIDES, async (event, rawArgs: unknown) => {
    validateSender(event)
    const ch = IPC_CHANNELS.CHAT_UPDATE_MCP_OVERRIDES
    const args = requireObject(rawArgs, ch)
    const conversationId = requireString(args, 'conversationId', ch)
    const overrides = requirePlainObject(args, 'overrides', ch) as Record<string, boolean>
    const updated = conversationRepository.updateMcpOverrides(conversationId, overrides)
    if (!updated) throw new Error('Conversation not found')
    return updated
  })

  // ── Update per-conversation model routing (per-chat model switching) ──
  ipcMain.handle(IPC_CHANNELS.CHAT_UPDATE_ROUTING, async (event, rawArgs: unknown) => {
    validateSender(event)
    const ch = IPC_CHANNELS.CHAT_UPDATE_ROUTING
    const args = requireObject(rawArgs, ch)
    const conversationId = requireString(args, 'conversationId', ch)
    const workspaceId = requireString(args, 'workspaceId', ch)

    // Optional: explicit provider override; otherwise uses workspace default.
    // NOTE (audit finding #2): Passing llmProvider alone (without routingOverrides)
    // is a no-op when the conversation already has a snapshot — the seeded role
    // entries below have highest resolution priority and mask the provider switch.
    // To change the provider, callers must also send explicit routingOverrides.
    const llmProvider = optionalString(args, 'llmProvider', ch) as LLMProvider | undefined
    const routingOverrides = args.routingOverrides as Partial<ModelRoleMap> | undefined

    // Seed overrides from the existing snapshot so untouched roles are preserved
    // (prevents silent re-resolution if workspace defaults changed since creation)
    const existing = conversationRepository.findById(conversationId)?.modelConfigSnapshot
    const seeded: Partial<ModelRoleMap> = existing
      ? {
          'specialist:plan': {
            provider: existing.plan.provider,
            modelId: existing.plan.modelId,
            localBackend: existing.plan.localBackend
          },
          'specialist:build': {
            provider: existing.build.provider,
            modelId: existing.build.modelId,
            localBackend: existing.build.localBackend
          },
          haiku: {
            provider: existing.background.provider,
            modelId: existing.background.modelId,
            localBackend: existing.background.localBackend
          }
        }
      : {}

    // Build a new snapshot seeded from existing + user overrides (does NOT affect other chats)
    const snapshot: ConversationModelSnapshot = buildConversationModelSnapshot(
      workspaceId,
      llmProvider,
      { ...seeded, ...routingOverrides }
    )

    // Persist snapshot + derived provider to this conversation only
    const resolvedProvider: LLMProvider = snapshot.plan.provider
    const updated = conversationRepository.updateModelSnapshot(
      conversationId,
      snapshot,
      resolvedProvider
    )
    if (!updated) throw new Error('Conversation not found')

    log.info(
      `[CHAT_UPDATE_ROUTING] conversationId=${conversationId} ` +
        `provider=${resolvedProvider} plan=${snapshot.plan.modelId} build=${snapshot.build.modelId}`
    )
    return updated
  })

  // ── Update per-conversation communication tone ──
  ipcMain.handle(IPC_CHANNELS.CHAT_UPDATE_TONE, async (event, rawArgs: unknown) => {
    validateSender(event)
    const ch = IPC_CHANNELS.CHAT_UPDATE_TONE
    const args = requireObject(rawArgs, ch)
    const conversationId = requireString(args, 'conversationId', ch)
    // Validate tone: must be a valid tone or null (use workspace default)
    const communicationTone = args.communicationTone as CommunicationTone | null
    if (
      communicationTone !== null &&
      !VALID_COMMUNICATION_TONES.includes(
        communicationTone as (typeof VALID_COMMUNICATION_TONES)[number]
      )
    ) {
      throw new Error(`${ch}: invalid communication tone`)
    }
    const updated = conversationRepository.updateTone(conversationId, communicationTone)
    if (!updated) throw new Error('Conversation not found')
    return updated
  })
}

import { ipcMain } from 'electron'
import {
  conversationRepository,
  workspaceRepository,
  turnUsageRepository
} from '../db/repositories'
import { modelConfigService } from '../services/model-config.service'
import { contextWindowResolver } from '../services/context-window-resolver'
import {
  CLAUDE_DEFAULT_CONTEXT_WINDOW,
  CLAUDE_1M_CONTEXT_WINDOW,
  IPC_CHANNELS,
  supportsContext1M
} from '../../shared/constants'
import type { ConversationMode, ThinkingEffort } from '../../shared/types'
import { chatIpcLogger } from '../logger'
import { validateSender } from './validate-sender'
import { requireObject, requireString } from './validate-args'
import { resolveContextLevel } from './context-usage-level'
import { lifecycleRegistry } from '../services/conversation-lifecycle'
import { planRepository } from '../db/repositories/plan.repository'

const log = chatIpcLogger

// ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
// Chat Mode — mode switching, effort, context usage
// ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

export function registerChatModeIpc(): void {
  ipcMain.handle(IPC_CHANNELS.CHAT_UPDATE_MODE, async (event, rawArgs: unknown) => {
    validateSender(event)
    const args = requireObject(rawArgs, IPC_CHANNELS.CHAT_UPDATE_MODE)
    const conversationId = requireString(args, 'conversationId', IPC_CHANNELS.CHAT_UPDATE_MODE)
    const mode = requireString(args, 'mode', IPC_CHANNELS.CHAT_UPDATE_MODE)

    // CONV-MODIFY-RACE-01: Prevent mode changes during active streaming
    if (lifecycleRegistry.isStreaming(conversationId)) {
      throw new Error('Cannot change mode while streaming — stop or wait for completion')
    }

    const validModes = ['plan', 'build', 'danger']
    if (!validModes.includes(mode)) {
      throw new Error(`${IPC_CHANNELS.CHAT_UPDATE_MODE}: mode must be "plan", "build", or "danger"`)
    }

    const updated = conversationRepository.updateMode(conversationId, mode as ConversationMode)
    if (!updated) throw new Error('Conversation not found')

    // When switching to build mode, mark any linked plan as in_progress
    if (mode === 'build') {
      try {
        const plans = planRepository.getForWorkspace(
          updated.workspaceId,
          { status: 'saved' }
        )
        const linkedPlan = plans.find(
          (p) => p.linkedConversationId === conversationId
        )
        if (linkedPlan) {
          planRepository.markInProgress(linkedPlan.id)
          log.info(`Plan ${linkedPlan.id} marked in_progress (build mode activated)`)
        }
      } catch (err) {
        log.warn('[mode-switch] Failed to update plan status (non-critical):', err)
      }
    }

    log.info(`Mode updated to "${mode}" in DB (CLI restart deferred until next send)`)

    return updated
  })

  // ── Update thinking effort ──
  ipcMain.handle(IPC_CHANNELS.CHAT_UPDATE_EFFORT, async (event, rawArgs: unknown) => {
    validateSender(event)
    const args = requireObject(rawArgs, IPC_CHANNELS.CHAT_UPDATE_EFFORT)
    const conversationId = requireString(args, 'conversationId', IPC_CHANNELS.CHAT_UPDATE_EFFORT)
    const effort = requireString(args, 'effort', IPC_CHANNELS.CHAT_UPDATE_EFFORT)

    // CONV-MODIFY-RACE-01: Prevent effort changes during active streaming
    if (lifecycleRegistry.isStreaming(conversationId)) {
      throw new Error('Cannot change effort while streaming — stop or wait for completion')
    }

    const validEfforts: ThinkingEffort[] = ['low', 'medium', 'high', 'xhigh', 'max']
    if (!validEfforts.includes(effort as ThinkingEffort)) {
      throw new Error(
        `${IPC_CHANNELS.CHAT_UPDATE_EFFORT}: effort must be "low", "medium", "high", "xhigh", or "max"`
      )
    }

    const updated = conversationRepository.updateEffort(conversationId, effort as ThinkingEffort)
    if (!updated) throw new Error('Conversation not found')

    log.info(`Effort updated to "${effort}" for conversation ${conversationId}`)

    return { effort }
  })

  // ── Context usage: return token consumption for a conversation ──
  // Computed from the last persisted turn's tokens vs. the resolved context
  // window. (The former SDK getContextUsage() "Strategy 1" was removed: the CLI
  // and OpenCode backends don't expose a Query object — getActiveQuery() always
  // returned null — so this DB-backed computation is the single source of truth.
  // Live per-turn updates are pushed separately via the context_usage_update
  // chunk in agent-stream-processor.processMetaChunk.)
  ipcMain.handle(IPC_CHANNELS.CONVERSATION_GET_CONTEXT_USAGE, async (event, rawArgs: unknown) => {
    validateSender(event)
    const args = requireObject(rawArgs, IPC_CHANNELS.CONVERSATION_GET_CONTEXT_USAGE)
    const conversationId = requireString(
      args,
      'conversationId',
      IPC_CHANNELS.CONVERSATION_GET_CONTEXT_USAGE
    )

    const lastTurn = turnUsageRepository.getLastTurn(conversationId)
    // Prefer context_tokens (SDK-reported, accounts for post-compaction state)
    // over summing raw API fields (which reflect pre-compaction totals).
    const inputTokens =
      lastTurn?.contextTokens && lastTurn.contextTokens > 0
        ? lastTurn.contextTokens
        : (lastTurn?.inputTokens ?? 0) +
          (lastTurn?.cacheReadTokens ?? 0) +
          (lastTurn?.cacheCreationTokens ?? 0)

    // Resolve context window — model-aware for Claude, full resolution chain for local LLMs
    let contextWindowSize = CLAUDE_DEFAULT_CONTEXT_WINDOW
    const dbConversation = conversationRepository.findById(conversationId)
    if (dbConversation) {
      const dbWorkspace = workspaceRepository.findById(dbConversation.workspaceId)
      if (dbWorkspace) {
        if (modelConfigService.isLocalProvider(dbWorkspace.repoPath)) {
          const llmConfig = modelConfigService.getLocalLLMConfig(dbWorkspace.repoPath)
          const ctxSettings = workspaceRepository.getSettings(dbWorkspace.id)
          const userOverride = ctxSettings.localContextWindow
          contextWindowSize = await contextWindowResolver.resolve(llmConfig, userOverride)
        } else {
          // Resolve whether the model used in this workspace supports the 1M beta
          const model = modelConfigService.getModel(dbWorkspace.repoPath, 'specialist:plan')
          contextWindowSize = supportsContext1M(model)
            ? CLAUDE_1M_CONTEXT_WINDOW
            : CLAUDE_DEFAULT_CONTEXT_WINDOW
        }
      }
    }
    const percentage = Math.round((inputTokens / contextWindowSize) * 100)
    const { level, qualityLevel } = resolveContextLevel(percentage, contextWindowSize)

    return {
      conversationId,
      inputTokens,
      contextWindowSize,
      percentage,
      level,
      qualityLevel,
      source: 'db' as const
    }
  })
}

import { ipcMain, app } from 'electron'
import { join, resolve, sep } from 'node:path'
import { writeFileSync, mkdirSync, rmSync } from 'node:fs'
import simpleGit from 'simple-git'
import { conversationRepository, messageRepository, workspaceRepository } from '../db/repositories'
import { chatAgentService, fileService } from '../services'
import { lifecycleRegistry } from '../services/conversation-lifecycle'
import { chatStreamService } from '../services/chat-stream.service'
import { IPC_CHANNELS, COMMIT_ATTRIBUTION, DEFAULT_MODEL_CONFIG } from '../../shared/constants'
import { runOneShotClaude } from '../services/one-shot-claude'
import { modelConfigService } from '../services/model-config.service'
import { repoService } from '../services/repo.service'
import { githubService } from '../services/github.service'
import { chatIpcLogger } from '../logger'
import { validateSender } from './validate-sender'
import { requireObject, requireString, optionalString } from './validate-args'
import { completeStreamMetrics } from './chunk-router'

const log = chatIpcLogger

// ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
// Chat Completion & Images — close, complete, clipboard images, image reading
// ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

/** Clean up clipboard images for a conversation (best-effort). */
function cleanupChatImages(conversationId: string): void {
  try {
    const imageDir = join(app.getPath('userData'), 'chat-images', conversationId)
    rmSync(imageDir, { recursive: true, force: true })
  } catch {
    /* best effort — directory may not exist */
  }
}

/**
 * Handle CHAT_CLOSE: abort streams, clean up branches, delete conversation.
 */
async function handleChatClose(conversationId: string): Promise<void> {
  // CONV-DEL-01: Abort active stream if it's for this conversation.
  if (lifecycleRegistry.isStreaming(conversationId)) {
    // CHAT-METRICS-ABORT-ORPHAN-01: Clean up metrics before abort to prevent leak.
    completeStreamMetrics(conversationId, 'aborted')
    lifecycleRegistry.abort(conversationId, 'conversation-deleted')
  }

  chatAgentService.clearSession(conversationId)
  // N1-FIX: Clear per-conversation memory dedupe state
  chatStreamService.clearConversationMemoryState(conversationId)

  // Clean up branches (local + remote if PR was merged)
  const workspacePath = chatAgentService.getWorkspacePath()
  try {
    const conv = conversationRepository.findById(conversationId)
    if (conv?.branchName && workspacePath) {
      const git = simpleGit(workspacePath)
      const allWs = workspaceRepository.findAll()
      const ws = allWs.find((w) => w.repoPath === workspacePath)

      // Delete remote branch if PR was merged/closed
      if (conv.prNumber && ws && githubService.isConfigured(ws.id)) {
        try {
          const status = await githubService.getPullRequestStatus(
            ws.id,
            workspacePath,
            conv.prNumber
          )
          if (status === 'merged' || status === 'closed') {
            await githubService.deleteRemoteBranch(ws.id, workspacePath, conv.branchName)
          }
        } catch (e) {
          log.warn('Remote branch cleanup failed:', e)
        }
      }

      // Always clean up local branch
      try {
        await git.deleteLocalBranch(conv.branchName, true)
      } catch {
        /* branch may already be deleted */
      }
    }
  } catch (e) {
    log.warn('Branch cleanup failed:', e)
  }

  conversationRepository.delete(conversationId)
  cleanupChatImages(conversationId)
}

/**
 * Handle CHAT_COMPLETE: commit changes, push, create PR, and clean up.
 */
async function handleChatComplete(args: {
  conversationId: string
  commitMessage: string
  description: string
  branchNameArg?: string
  baseBranch?: string
}): Promise<{ branch: string; commitHash: string; prUrl?: string }> {
  const { conversationId, commitMessage, description, branchNameArg } = args

  const conversation = conversationRepository.findById(conversationId)
  if (!conversation) throw new Error('Conversation not found')
  const workspace = workspaceRepository.findById(conversation.workspaceId)
  if (!workspace) throw new Error('Workspace not found')

  const git = simpleGit(workspace.repoPath)

  // Post-migration-66: no worktrees to merge (specialist-pool deleted).
  try {
    log.debug(`No worktrees to merge for conversation ${conversationId}`)
  } catch (error) {
    if ((error as Error).message.includes('Merge conflict')) {
      throw error
    }
    log.warn('Worktree merge during /complete encountered an issue:', error)
  }

  const status = await git.status()
  const changedPaths = [
    ...status.modified,
    ...status.created,
    ...status.not_added,
    ...status.deleted,
    ...status.renamed.map((r) => r.to)
  ]
  if (changedPaths.length === 0) throw new Error('No uncommitted changes in workspace')

  const branchName =
    branchNameArg ||
    conversation.branchName ||
    `chat/${conversation.title
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/^-|-$/g, '')
      .slice(0, 50)}-${conversationId.slice(0, 8)}`

  const currentBranch = await git.revparse(['--abbrev-ref', 'HEAD'])

  // Resolve the base branch for the PR (priority: explicit arg > stored source > current)
  const prBaseBranch = args.baseBranch || conversation.sourceBranch || currentBranch

  // Smart branch checkout — handle all scenarios
  let branchCreatedHere = false
  if (currentBranch === branchName) {
    // S1: Already on the target branch (gitAutoBranch case) — no checkout needed
    log.debug(`[chat:complete] Already on branch ${branchName}, skipping checkout`)
  } else {
    const localBranches = await git.branchLocal()
    if (localBranches.all.includes(branchName)) {
      // S2/S4: Branch exists but we're not on it — checkout without -b
      await git.checkout(branchName)
      log.debug(`[chat:complete] Switched to existing branch ${branchName}`)
    } else {
      // S3: Normal case — create and checkout new branch
      await git.checkoutLocalBranch(branchName)
      branchCreatedHere = true
      log.debug(`[chat:complete] Created and switched to new branch ${branchName}`)
    }
  }

  try {
    await git.add(changedPaths)

    const body = description ? `${description}\n\n${COMMIT_ATTRIBUTION}` : COMMIT_ATTRIBUTION
    const fullMessage = `${commitMessage}\n\n${body}`
    await git.commit(fullMessage)
    const commitHash = await git.revparse(['HEAD'])

    // Push if remote exists
    let prUrl: string | undefined
    try {
      const remotes = await git.getRemotes(true)
      if (remotes.length > 0) {
        await git.push('origin', branchName, ['--set-upstream'])
      }
    } catch (e) {
      log.warn('Push failed (no remote or auth issue):', e)
    }

    // Auto-create PR if GitHub is configured
    if (githubService.isConfigured(workspace.id)) {
      try {
        const prResult = await githubService.createPullRequest({
          workspaceId: workspace.id,
          repoPath: workspace.repoPath,
          head: branchName,
          base: prBaseBranch,
          title: commitMessage,
          body: description
        })
        log.info(`[chat:complete] PR created: ${prResult.prUrl} (pr#${prResult.prNumber})`)
        prUrl = prResult.prUrl
        conversationRepository.updatePrInfo(
          conversationId,
          prResult.prUrl,
          prResult.prNumber,
          branchName
        )
      } catch (e) {
        log.warn('GitHub PR creation/persistence failed (push succeeded):', e)
      }
    }

    // CHAT-COMPLETE-PUSH-DELETE-RACE-01: Isolate post-push cleanup so failures
    // don't trigger the catch handler's branch-deletion recovery. The commit and
    // push already succeeded — cleanup errors are non-fatal.
    if (lifecycleRegistry.isStreaming(conversationId)) {
      // CHAT-METRICS-ABORT-ORPHAN-01: Clean up metrics before abort to prevent leak.
      completeStreamMetrics(conversationId, 'completed')
      lifecycleRegistry.abort(conversationId, 'conversation-completed')
    }
    chatAgentService.clearSession(conversationId)
    // N1-FIX: Clear per-conversation memory dedupe state
    chatStreamService.clearConversationMemoryState(conversationId)
    try {
      conversationRepository.delete(conversationId)
    } catch (deleteErr) {
      log.error('[chat:complete] Failed to delete conversation after successful push — non-fatal:', deleteErr)
    }
    cleanupChatImages(conversationId)

    return { branch: branchName, commitHash, prUrl }
  } catch (error) {
    try {
      // Rollback: return to the base branch (not necessarily where we started)
      const rollbackBranch = prBaseBranch !== branchName ? prBaseBranch : currentBranch
      await git.checkout(rollbackBranch)
      // Only delete the branch if we created it in this call — never delete pre-existing branches
      if (branchCreatedHere) {
        await git.deleteLocalBranch(branchName, true)
      }
    } catch {
      /* best effort */
    }
    throw error
  }
}

export function registerChatCompletionIpc(): void {
  ipcMain.handle(IPC_CHANNELS.CHAT_CLOSE, async (event, rawArgs: unknown) => {
    validateSender(event)
    const closeArgs = requireObject(rawArgs, IPC_CHANNELS.CHAT_CLOSE)
    const conversationId = requireString(closeArgs, 'conversationId', IPC_CHANNELS.CHAT_CLOSE)
    return handleChatClose(conversationId)
  })

  ipcMain.handle(IPC_CHANNELS.CHAT_COMPLETE, async (event, rawArgs: unknown) => {
    validateSender(event)
    const args = requireObject(rawArgs, IPC_CHANNELS.CHAT_COMPLETE)
    const conversationId = requireString(args, 'conversationId', IPC_CHANNELS.CHAT_COMPLETE)
    const commitMessage = requireString(args, 'commitMessage', IPC_CHANNELS.CHAT_COMPLETE)
    const description = optionalString(args, 'description', IPC_CHANNELS.CHAT_COMPLETE) ?? ''
    const branchNameArg = optionalString(args, 'branchName', IPC_CHANNELS.CHAT_COMPLETE)
    const baseBranch = optionalString(args, 'baseBranch', IPC_CHANNELS.CHAT_COMPLETE)
    return handleChatComplete({ conversationId, commitMessage, description, branchNameArg, baseBranch })
  })

  ipcMain.handle(IPC_CHANNELS.CHAT_GENERATE_PR_DESCRIPTION, async (event, rawArgs: unknown) => {
    validateSender(event)
    const args = requireObject(rawArgs, IPC_CHANNELS.CHAT_GENERATE_PR_DESCRIPTION)
    const conversationId = requireString(args, 'conversationId', IPC_CHANNELS.CHAT_GENERATE_PR_DESCRIPTION)

    const conversation = conversationRepository.findById(conversationId)
    if (!conversation) throw new Error('Conversation not found')

    const workspace = workspaceRepository.findById(conversation.workspaceId)
    const messages = messageRepository
      .findByConversation(conversationId)
      .filter((m) => !m.hidden)

    if (messages.length === 0) {
      return { description: '' }
    }

    // Truncate to last 15 messages, 500 chars each — keeps prompt small for Haiku
    const recentMessages = messages
      .slice(-15)
      .map((m) => `[${m.role}]: ${m.contentMd.slice(0, 500)}`)
      .join('\n')

    // Get file changes for context (best-effort)
    let fileChangesContext = ''
    try {
      const fileChanges = await repoService.getUncommittedFileDetails(workspace?.repoPath ?? '')
      if (fileChanges.length > 0) {
        fileChangesContext = `\n\n## Changed files (${fileChanges.length}):\n${fileChanges
          .map((fc) => `- ${fc.changeType}: ${fc.filePath}`)
          .join('\n')}`
      }
    } catch {
      /* best effort */
    }

    const prompt = `You are generating a concise PR description for a GitHub pull request.

Based on this conversation and file changes, write a clear PR description with:
1. A one-line summary of what changed and why
2. A bullet list of key changes (max 8 items)
3. Any notable decisions or trade-offs

Keep it under 500 words. Use markdown formatting.

## Conversation title: ${conversation.title}

## Recent conversation (last ${Math.min(messages.length, 15)} messages):
${recentMessages}${fileChangesContext}

Respond with ONLY the PR description, no preamble.`

    const resolvedModel = workspace?.id
      ? modelConfigService.getModelById(workspace.id, 'pr-description')
      : DEFAULT_MODEL_CONFIG['pr-description']

    const { text } = await runOneShotClaude({
      feature: 'pr_description',
      model: resolvedModel,
      workspaceId: workspace?.id ?? null,
      conversationId,
      args: ['-p', prompt, '--model', resolvedModel],
      cli: { timeout: 15_000 }
    })

    return { description: text.trim() }
  })

  ipcMain.handle(IPC_CHANNELS.SAVE_CLIPBOARD_IMAGE, async (event, rawArgs: unknown) => {
    validateSender(event)
    const args = requireObject(rawArgs, IPC_CHANNELS.SAVE_CLIPBOARD_IMAGE)
    const dataUrl = requireString(args, 'dataUrl', IPC_CHANNELS.SAVE_CLIPBOARD_IMAGE)
    const conversationId = optionalString(args, 'conversationId', IPC_CHANNELS.SAVE_CLIPBOARD_IMAGE)

    // Sanitize conversationId — must be alphanumeric/dashes (UUID-like), no path traversal
    if (conversationId && !/^[\w-]+$/.test(conversationId)) {
      throw new Error(`${IPC_CHANNELS.SAVE_CLIPBOARD_IMAGE}: invalid conversationId format`)
    }

    // Extract base64 data from data URL
    const matches = dataUrl.match(/^data:image\/(png|jpeg|gif|webp);base64,(.+)$/)
    if (!matches) {
      throw new Error('Invalid image data URL format')
    }

    const ext = matches[1]
    const base64Data = matches[2]
    const buffer = Buffer.from(base64Data, 'base64')

    // Save to conversation-scoped directory
    const imageDir = join(app.getPath('userData'), 'chat-images', conversationId || 'unsorted')
    mkdirSync(imageDir, { recursive: true })

    const filename = `clipboard-${Date.now()}.${ext}`
    const filePath = join(imageDir, filename)
    writeFileSync(filePath, buffer)

    return filePath
  })

  ipcMain.handle(IPC_CHANNELS.READ_IMAGE_BASE64, async (event, rawArgs: unknown) => {
    validateSender(event)
    const args = requireObject(rawArgs, IPC_CHANNELS.READ_IMAGE_BASE64)
    const filePath = requireString(args, 'filePath', IPC_CHANNELS.READ_IMAGE_BASE64)

    // Security: only allow reading from chat-images directory
    const chatImagesDir = join(app.getPath('userData'), 'chat-images')
    const resolved = resolve(filePath)
    if (!resolved.startsWith(chatImagesDir + sep) && resolved !== chatImagesDir) {
      throw new Error('Access denied: file is outside chat-images directory')
    }

    const { base64, mimeType } = fileService.readImageAsBase64(resolved)
    return `data:${mimeType};base64,${base64}`
  })
}

import { ipcMain, type BrowserWindow } from 'electron'
import { extname } from 'node:path'
import { IPC_CHANNELS } from '../../shared/constants'
import { chatStreamService } from '../services/chat-stream.service'
import { chatAgentService } from '../services/chat-agent.service'
import { conversationStateMachine } from '../services/conversation-state-machine'
import { lifecycleRegistry } from '../services/conversation-lifecycle'
import type { ProjectSpecialistRoleAdapter } from '../services/role-adapters/project-specialist.adapter'
import { conversationRepository } from '../db/repositories/conversation.repository'

import { chatIpcLogger } from '../logger'
import { validateSender } from './validate-sender'
import { requireObject, requireString } from './validate-args'

const log = chatIpcLogger

/** Maximum message text length (1MB) */
const MAX_MESSAGE_LENGTH = 1_000_000
/** Maximum number of attachments per message */
const MAX_ATTACHMENTS = 20
/** Maximum number of image attachments per message */
const MAX_IMAGE_ATTACHMENTS = 5

export function registerChatMessageIpc(_mainWindow: BrowserWindow): void {
  ipcMain.handle(IPC_CHANNELS.CHAT_SEND, async (event, rawArgs: unknown) => {
    validateSender(event)

    // ── Input validation (IPC boundary concern) ──
    const ch = IPC_CHANNELS.CHAT_SEND
    const args = requireObject(rawArgs, ch)
    const conversationId = requireString(args, 'conversationId', ch)
    const text = requireString(args, 'text', ch)
    const attachments = args.attachments as string[] | undefined
    const skipOptimizer = args.skipOptimizer === true
    const hidden = args.hidden === true

    if (text.length > MAX_MESSAGE_LENGTH) {
      throw new Error(`Message too long: ${text.length} chars (max ${MAX_MESSAGE_LENGTH})`)
    }

    if (attachments !== undefined) {
      if (!Array.isArray(attachments)) {
        throw new Error('Attachments must be an array')
      }
      if (attachments.length > MAX_ATTACHMENTS) {
        throw new Error(`Too many attachments: ${attachments.length} (max ${MAX_ATTACHMENTS})`)
      }
      for (const filePath of attachments) {
        if (typeof filePath !== 'string') {
          throw new Error('Each attachment must be a file path string')
        }
      }
      const imageExtensions = new Set(['.png', '.jpg', '.jpeg', '.gif', '.webp'])
      const imageCount = attachments.filter((p) =>
        imageExtensions.has(extname(p).toLowerCase())
      ).length
      if (imageCount > MAX_IMAGE_ATTACHMENTS) {
        throw new Error(`Too many image attachments: ${imageCount} (max ${MAX_IMAGE_ATTACHMENTS})`)
      }
    }

    log.info('SEND received:', {
      conversationId,
      textLen: text.length,
      attachments: attachments?.length ?? 0
    })

    // ── Delegate to stream service ──
    // stream() returns a StreamHandle. We await it to get the handle (validates inputs,
    // starts streaming), but let the `done` promise run in the background — the renderer
    // receives progress via IPC events, not via this handler's return value.
    const handle = await chatStreamService.stream(conversationId, text, attachments, {
      optimizePrompt: !skipOptimizer,
      hidden
    })

    // Fire-and-forget: let pipeline complete asynchronously.
    // Errors are surfaced to the renderer via CHAT_MESSAGE_CHUNK error events.
    handle.done.catch((err) => {
      log.warn('[CHAT_SEND] Stream pipeline error (already surfaced via IPC):', err)
    })

    // Return the backend-generated requestId so the renderer can correlate
    // streaming chunks. This is the SINGLE SOURCE OF TRUTH for requestId —
    // the renderer must NOT generate its own.
    return { requestId: handle.requestId }
  })

  // ── Set goal for next execution ──
  ipcMain.handle(IPC_CHANNELS.CHAT_SET_GOAL, (event, rawArgs: unknown) => {
    validateSender(event)
    const args = requireObject(rawArgs, IPC_CHANNELS.CHAT_SET_GOAL)
    const conversationId = requireString(args, 'conversationId', IPC_CHANNELS.CHAT_SET_GOAL)
    const goal = requireString(args, 'goal', IPC_CHANNELS.CHAT_SET_GOAL)
    const goalMode = (args.goalMode === 'advisory' ? 'advisory' : 'enforce') as 'advisory' | 'enforce'

    // Validate goal length (CLI caps at 4000 chars)
    if (goal.length > 4000) {
      throw new Error(`Goal too long: ${goal.length} chars (max 4000)`)
    }

    // Resolve workspace from the conversation, not from activeWorkspaceId
    // (prevents goal landing on wrong adapter during rapid workspace switches)
    const workspaceId = conversationRepository.getWorkspaceId(conversationId)
    if (!workspaceId) {
      log.warn('[CHAT_SET_GOAL] Conversation not found, cannot resolve workspace:', conversationId)
      return
    }

    const adapter = chatAgentService.getAdapterForWorkspace(workspaceId)
    if (adapter && 'setGoalCondition' in adapter) {
      ;(adapter as ProjectSpecialistRoleAdapter).setGoalCondition(conversationId, goal, goalMode)
    } else {
      log.warn('[CHAT_SET_GOAL] Adapter not found or missing setGoalCondition for workspace:', workspaceId)
    }

    log.info('SET_GOAL received:', { conversationId, goalLen: goal.length, goalMode, workspaceId })
  })

  // ── Compact conversation context ──
  ipcMain.handle(IPC_CHANNELS.CHAT_COMPACT, async (event, args?: { extractNuance?: boolean }) => {
    validateSender(event)
    const extractNuance = args?.extractNuance ?? false
    await chatStreamService.compact(extractNuance)
  })

  // ── Stop generation (accepts optional conversationId — bare call stops ALL, fixes P6) ──
  ipcMain.handle(IPC_CHANNELS.CHAT_STOP, async (event, rawArgs?: unknown) => {
    validateSender(event)
    let conversationId: string | undefined
    if (rawArgs && typeof rawArgs === 'object' && 'conversationId' in rawArgs) {
      conversationId = (rawArgs as { conversationId?: string }).conversationId ?? undefined
    }
    await chatStreamService.stop(conversationId)
    // Specialist pool removed in migration 66 — nothing else to stop.
  })

  // ── Query streaming state (for conversation switch restore) ──
  ipcMain.handle(IPC_CHANNELS.CHAT_GET_STREAMING_STATE, (event) => {
    validateSender(event)
    const streams = lifecycleRegistry.active()
    return {
      // Per-conversation stream list (new)
      streams,
      // Backward compat: legacy single-stream fields (deprecated)
      isStreaming: conversationStateMachine.isStreaming(),
      conversationId: conversationStateMachine.activeConversationId,
      state: conversationStateMachine.currentState,
      requestId: streams[0]?.requestId ?? null
    }
  })
}

import { ipcMain, dialog, safeStorage } from 'electron'
import { existsSync } from 'node:fs'
import { execSync } from 'node:child_process'
import { resolve, basename } from 'node:path'
import simpleGit from 'simple-git'
import { IPC_CHANNELS } from '../../shared/constants'
import { workspaceRepository } from '../db/repositories'
import { repoService } from '../services/repo.service'
import { validateSender } from './validate-sender'
import { requireObject, requireString, requirePlainObject, optionalString } from './validate-args'
import { agentSyncService } from '../services/agent-sync.service'
import { fileWatcherService } from '../services/file-watcher.service'
import { chatAgentService } from '../services/chat-agent.service'
import { dbLogger } from '../logger'
