// ── Extracted handler functions ───────────────────────────────────────────

async function handleWorkspaceCreate(
  name: string,
  repoPath: string
): Promise<ReturnType<typeof workspaceRepository.create>> {
  const ch = IPC_CHANNELS.WORKSPACE_CREATE

  if (name.length > 255) {
    throw new Error(`${ch}: workspace name too long (max 255 chars)`)
  }

  const normalizedPath = resolve(repoPath)

  if (!existsSync(normalizedPath)) {
    throw new Error(`${ch}: the specified directory does not exist`)
  }

  let isGitRepo = false
  let gitRemoteUrl: string | undefined
  try {
    const git = simpleGit(normalizedPath)
    const top = (await git.revparse(['--show-toplevel'])).trim()
    isGitRepo = resolve(top) === normalizedPath
    if (isGitRepo) {
      const remotes = await git.getRemotes(true)
      gitRemoteUrl = remotes.find((r) => r.name === 'origin')?.refs?.fetch
    }
  } catch {
    /* not a repo / not the root — auto-init below */
  }

  if (!isGitRepo) {
    try {
      await repoService.initRepo(normalizedPath)
      isGitRepo = true
      dbLogger.info(`Auto-initialized git repo at ${normalizedPath}`)
    } catch (err) {
      dbLogger.warn('Auto-init git failed (non-fatal):', err)
    }
  }

  const workspace = workspaceRepository.create(
    name.trim() || basename(normalizedPath),
    normalizedPath,
    gitRemoteUrl,
    isGitRepo
  )



  try {
    const db = getDatabase()
    const existing = db
      .prepare(`SELECT id FROM specialists WHERE workspace_id = ?`)
      .get(workspace.id) as { id: string } | undefined
    if (!existing) {
      db.prepare(
        `INSERT INTO specialists (workspace_id, agent_id, display_name, icon, color,
             prompt, priority, is_active, build_status, created_at, updated_at)
           VALUES (?, ?, ?, '🔧', '#6366F1', '', 1, 1, 'pending', datetime('now'), datetime('now'))`
      ).run(workspace.id, `workspace-specialist-${workspace.id}`, `${workspace.name} Specialist`)
      dbLogger.info(`Seeded pending Project Specialist for workspace ${workspace.id}`)

      // Auto-trigger specialist generation in the background.
      // The agent works immediately with DEFAULT_ARCHITECT_PROMPT,
      // then seamlessly upgrades when generation completes.
      specialistBuilderService.buildProjectSpecialist(workspace.id).catch((err) => {
        dbLogger.warn('Auto-build specialist failed (non-fatal):', err)
      })
    }
  } catch (err) {
    dbLogger.warn('Failed to seed Project Specialist on workspace create:', err)
  }

  return workspace
}

async function handleWorkspaceOpen(
  id: string
): Promise<ReturnType<typeof workspaceRepository.updateLastOpened>> {
  const workspace = workspaceRepository.updateLastOpened(id)
  if (!workspace) {
    throw new Error(`Workspace not found: ${id}`)
  }

  try {
    await repoService.ensureOwnRepo(workspace.repoPath)
  } catch (e) {
    dbLogger.warn('ensureOwnRepo on workspace open failed (non-fatal):', e)
  }

  try {
    const syncResult = agentSyncService.autoSyncNewEntries(workspace.repoPath)
    if (syncResult.imported > 0 || syncResult.skillsImported > 0) {
      dbLogger.info(
        `Workspace open auto-sync: imported ${syncResult.imported} specialists, ${syncResult.skillsImported} skills`
      )
    }
  } catch (e) {
    dbLogger.warn('Auto-sync on workspace open failed:', e)
  }

  try {
    const { authProvider } = await import('../services/auth-provider')
    authProvider.loadFromWorkspace(workspace.repoPath)
  } catch (e) {
    dbLogger.warn('Failed to load auth settings:', e)
  }

  try {
    const wsSettings = workspaceRepository.getSettings(workspace.id)
    if (wsSettings.repomapEnabled || wsSettings.semanticSearchEnabled) {
      fileWatcherService.start(workspace.id, workspace.repoPath, {
        codeGraphEnabled: !!wsSettings.repomapEnabled,
        semanticSearchEnabled: !!wsSettings.semanticSearchEnabled
      })
    }
  } catch (e) {
    dbLogger.warn('Failed to start file watcher on workspace open:', e)
  }

  // Restart idle consolidation for the newly-opened workspace
  try {
    memoryConsolidationService.stopIdleJob()
    memoryConsolidationService.startIdleJob(workspace.id)
  } catch (e) {
    dbLogger.warn('Failed to start memory consolidation idle job:', e)
  }

  return workspace
}

async function handleSettingsUpdate(
  workspaceId: string,
  settings: Record<string, unknown>
): Promise<ReturnType<typeof workspaceRepository.updateSettings>> {
  const existing = workspaceRepository.getSettings(workspaceId)
  const encrypted = encryptSettingsKeys({ ...existing, ...settings })
  const merged = encrypted
  const result = workspaceRepository.updateSettings(workspaceId, merged)

  try {
    const ws = workspaceRepository.findById(workspaceId)
    if (ws) {
      const s = merged as Record<string, unknown>
      if (s.repomapEnabled || s.semanticSearchEnabled) {
        fileWatcherService.start(workspaceId, ws.repoPath, {
          codeGraphEnabled: !!s.repomapEnabled,
          semanticSearchEnabled: !!s.semanticSearchEnabled
        })
      } else {
        fileWatcherService.stop(workspaceId)
      }
    }
  } catch (e) {
    dbLogger.warn('Failed to update file watcher on settings change:', e)
  }

  try {
    const oldProvider = (existing.llmProvider as string) ?? 'claude'
    const newProvider = (merged.llmProvider as string) ?? 'claude'

    if (oldProvider !== newProvider && chatAgentService.isRunning()) {
      const ws = workspaceRepository.findById(workspaceId)
      if (ws && chatAgentService.getWorkspacePath() === ws.repoPath) {
        dbLogger.info(
          `[workspace:settings] LLM provider changed: ${oldProvider} → ${newProvider} — restarting agent session`
        )
        await chatAgentService.start(ws.repoPath)
      }
    }
  } catch (e) {
    dbLogger.warn('Failed to restart agent after LLM provider change:', e)
  }

  return result
}

// ── IPC registration ─────────────────────────────────────────────────────

export function registerWorkspaceIpc(): void {
  ipcMain.handle(IPC_CHANNELS.WORKSPACE_LIST, async (event) => {
    validateSender(event)
    return workspaceRepository.findAll()
  })

  ipcMain.handle(IPC_CHANNELS.WORKSPACE_CREATE, async (event, rawArgs: unknown) => {
    validateSender(event)
    const ch = IPC_CHANNELS.WORKSPACE_CREATE
    const args = requireObject(rawArgs, ch)
    const name = requireString(args, 'name', ch)
    const repoPath = requireString(args, 'repoPath', ch)
    return handleWorkspaceCreate(name, repoPath)
  })

  ipcMain.handle(IPC_CHANNELS.WORKSPACE_OPEN, async (event, rawArgs: unknown) => {
    validateSender(event)
    const ch = IPC_CHANNELS.WORKSPACE_OPEN
    const args = requireObject(rawArgs, ch)
    const id = requireString(args, 'id', ch)
    return handleWorkspaceOpen(id)
  })

  ipcMain.handle(IPC_CHANNELS.WORKSPACE_DELETE, async (event, rawArgs: unknown) => {
    validateSender(event)
    const ch = IPC_CHANNELS.WORKSPACE_DELETE
    const args = requireObject(rawArgs, ch)
    const id = requireString(args, 'id', ch)

    // Stop any running sessions for this workspace before deleting
    const { chatAgentService } = await import('../services')
    await chatAgentService.stopForWorkspace(id).catch(() => {
      /* non-fatal: workspace being deleted — session stop is best-effort */
    })

    fileWatcherService.stop(id)
    memoryConsolidationService.stopIdleJobIfWorkspace(id)
    workspaceRepository.delete(id)
  })

  ipcMain.handle(IPC_CHANNELS.WORKSPACE_GET_SETTINGS, async (event, rawArgs: unknown) => {
    validateSender(event)
    const ch = IPC_CHANNELS.WORKSPACE_GET_SETTINGS
    const args = requireObject(rawArgs, ch)
    const workspaceId = requireString(args, 'workspaceId', ch)
    return workspaceRepository.getSettings(workspaceId)
  })

  ipcMain.handle(IPC_CHANNELS.WORKSPACE_UPDATE_SETTINGS, async (event, rawArgs: unknown) => {
    validateSender(event)
    const ch = IPC_CHANNELS.WORKSPACE_UPDATE_SETTINGS
    const args = requireObject(rawArgs, ch)
    const workspaceId = requireString(args, 'workspaceId', ch)
    const settings = requirePlainObject(args, 'settings', ch)
    return handleSettingsUpdate(workspaceId, settings)
  })

  ipcMain.handle(IPC_CHANNELS.WORKSPACE_UPDATE_AUTH, async (event, rawArgs: unknown) => {
    validateSender(event)
    const ch = IPC_CHANNELS.WORKSPACE_UPDATE_AUTH
    const args = requireObject(rawArgs, ch)
    const workspaceId = requireString(args, 'workspaceId', ch)
    const authMode = requireString(args, 'authMode', ch)
    const anthropicApiKey = optionalString(args, 'anthropicApiKey', ch)

    if (authMode !== 'claude-max' && authMode !== 'api-key') {
      throw new Error(`${ch}: authMode must be 'claude-max' or 'api-key'`)
    }

    // IPC-04: Wrap core logic in try-catch to prevent internal details from leaking
    try {
      // Merge auth settings with existing workspace settings
      const existing = workspaceRepository.getSettings(workspaceId)
      const merged: Record<string, unknown> = {
        ...existing,
        authMode
      }

      // IPC-01: Encrypt API key with safeStorage (OS keychain) before DB storage
      // — matches the pattern established in github.service.ts:69
      if (authMode === 'api-key' && anthropicApiKey) {
        const encrypted = safeStorage.encryptString(anthropicApiKey)
        merged.anthropicApiKey = encrypted.toString('base64')
        merged.anthropicApiKeyEncrypted = true
      } else {
        merged.anthropicApiKey = undefined
        merged.anthropicApiKeyEncrypted = false
      }
      workspaceRepository.updateSettings(workspaceId, merged)

      // Reload auth provider for the active workspace
      const workspace = workspaceRepository.findAll().find((w) => w.id === workspaceId)
      if (workspace) {
        const { authProvider } = await import('../services/auth-provider')
        authProvider.loadFromWorkspace(workspace.repoPath)
      }

      return { success: true }
    } catch (err) {
      dbLogger.error('WORKSPACE_UPDATE_AUTH failed:', err)
      throw new Error('Failed to update authentication settings')
    }
  })

  // ── External MCP prerequisite check ──
  ipcMain.handle(IPC_CHANNELS.WORKSPACE_CHECK_EXTERNAL_MCP, async (event, rawArgs: unknown) => {
    validateSender(event)
    const ch = IPC_CHANNELS.WORKSPACE_CHECK_EXTERNAL_MCP
    const args = requireObject(rawArgs, ch)
    const command = requireString(args, 'command', ch)
    // Sanitize: only allow simple command names (no slashes, spaces, or shell metacharacters)
    if (!/^[a-zA-Z0-9_-]+$/.test(command)) {
      throw new Error(`${ch}: invalid command name`)
    }
    try {
      execSync(`which ${command}`, { stdio: 'pipe', timeout: 3000 })
      // IPC-03: Don't expose filesystem path to renderer
      return { available: true }
    } catch {
      return { available: false }
    }
  })

  ipcMain.handle(IPC_CHANNELS.DIALOG_SELECT_DIRECTORY, async (event) => {
    validateSender(event)

    const result = await dialog.showOpenDialog({
      properties: ['openDirectory'],
      title: 'Select Project Directory'
    })

    if (result.canceled || result.filePaths.length === 0) {
      return null
    }

    return result.filePaths[0]
  })
}

import { watch } from 'node:fs'
import type { FSWatcher } from 'node:fs'
import { EventEmitter } from 'node:events'
import log from 'electron-log/main'
import { ATELIERIGNORE_FILENAME, invalidateIgnoreCache } from './workspace-ignore'

const DEBOUNCE_MS = 3000

/** Directories to ignore — never trigger re-indexing */
const IGNORED_DIRS = new Set([
  'node_modules',
  '.git',
  'dist',
  'build',
  'out',
  '.next',
  '.output',
  '__pycache__',
  '.cache',
  '.turbo',
  'coverage',
  '.svn',
  '.hg',
  'vendor',
  '.repomap.tags.cache'
])

interface WatcherState {
  watcher: FSWatcher
  workspacePath: string
  pendingChanges: Set<string>
  debounceTimer: ReturnType<typeof setTimeout> | null
  codeGraphEnabled: boolean
  semanticSearchEnabled: boolean
}

export interface FilesChangedEvent {
  workspaceId: string
  workspacePath: string
  changedFiles: string[]
  codeGraphEnabled: boolean
  semanticSearchEnabled: boolean
}

class FileWatcherService extends EventEmitter {
  private watchers = new Map<string, WatcherState>()

  /**
   * Start watching a workspace directory.
   * If already watching, updates the feature flags without restarting.
   */
  start(
    workspaceId: string,
    workspacePath: string,
    options: {
      codeGraphEnabled: boolean
      semanticSearchEnabled: boolean
    }
  ): void {
    const existing = this.watchers.get(workspaceId)
    if (existing) {
      existing.codeGraphEnabled = options.codeGraphEnabled
      existing.semanticSearchEnabled = options.semanticSearchEnabled
      if (!options.codeGraphEnabled && !options.semanticSearchEnabled) {
        this.stop(workspaceId)
      }
      return
    }

    if (!options.codeGraphEnabled && !options.semanticSearchEnabled) return

    try {
      const watcher = watch(workspacePath, { recursive: true }, (_eventType, filename) => {
        if (!filename) return
        // Editing .atelierignore changes what is indexable — drop the cached
        // rules immediately so the next re-index honors the new exclusions
        // without requiring an app restart.
        const normalized = filename.replace(/\\/g, '/')
        if (
          normalized === ATELIERIGNORE_FILENAME ||
          normalized.endsWith(`/${ATELIERIGNORE_FILENAME}`)
        ) {
          invalidateIgnoreCache(workspacePath)
          log.info('[FileWatcher] .atelierignore changed — exclusion cache invalidated')
          return
        }
        this.handleFileEvent(workspaceId, filename)
      })

      watcher.on('error', (err) => {
        log.warn(`[FileWatcher] Error for workspace ${workspaceId}:`, err)
      })

      this.watchers.set(workspaceId, {
        watcher,
        workspacePath,
        pendingChanges: new Set(),
        debounceTimer: null,
        ...options
      })
      log.info(`[FileWatcher] Watching: ${workspacePath}`)
    } catch (err) {
      log.error(`[FileWatcher] Failed to start:`, err)
    }
  }

  /**
   * Stop watching a workspace.
   */
  stop(workspaceId: string): void {
    const state = this.watchers.get(workspaceId)
    if (!state) return
    state.watcher.close()
    if (state.debounceTimer) clearTimeout(state.debounceTimer)
    this.watchers.delete(workspaceId)
    log.info(`[FileWatcher] Stopped watching workspace ${workspaceId}`)
  }

  private handleFileEvent(workspaceId: string, filename: string): void {
    // Skip ignored directories
    // Split on both forward and backslash separators for Windows compatibility.
    // On Windows, fs.watch returns paths with native backslash separators,
    // so split('/') would produce one unsplit segment and never match IGNORED_DIRS.
    const parts = filename.split(/[/\\]/)
    if (parts.some((p) => IGNORED_DIRS.has(p.toLowerCase()))) return

    const state = this.watchers.get(workspaceId)
    if (!state) return

    state.pendingChanges.add(filename)

    // Reset debounce timer
    if (state.debounceTimer) clearTimeout(state.debounceTimer)
    state.debounceTimer = setTimeout(() => this.flush(workspaceId), DEBOUNCE_MS)
  }

  private flush(workspaceId: string): void {
    const state = this.watchers.get(workspaceId)
    if (!state || state.pendingChanges.size === 0) return

    const changedFiles = [...state.pendingChanges]
    state.pendingChanges.clear()
    state.debounceTimer = null

    this.emit('files-changed', {
      workspaceId,
      workspacePath: state.workspacePath,
      changedFiles,
      codeGraphEnabled: state.codeGraphEnabled,
      semanticSearchEnabled: state.semanticSearchEnabled
    } satisfies FilesChangedEvent)
  }

  /** Stop all watchers — called on app quit */
  stopAll(): void {
    for (const id of [...this.watchers.keys()]) this.stop(id)
  }

  /**
   * Snapshot currently-active watchers (workspaceId + settings).
   * Used by power management to capture state before stopAll(),
   * so watchers can be recreated after wake.
   */
  getActiveWatchers(): {
    workspaceId: string
    workspacePath: string
    codeGraphEnabled: boolean
    semanticSearchEnabled: boolean
  }[] {
    return [...this.watchers.entries()].map(([id, state]) => ({
      workspaceId: id,
      workspacePath: state.workspacePath,
      codeGraphEnabled: state.codeGraphEnabled,
      semanticSearchEnabled: state.semanticSearchEnabled
    }))
  }
}

export const fileWatcherService = new FileWatcherService()

/**
 * MemoryConsolidationService — Background consolidation for the memory system.
 *
 * Responsibilities:
 *   1. One-time consolidation pass: cluster all active facts at ≥0.85 similarity,
 *      auto-merge ≥0.95 clusters, queue 0.85–0.95 clusters as single review items.
 *   2. Idle/daily job: auto-merge ≥0.95 duplicates, archive stale T0 facts,
 *      prune old contradiction records, cap the review queue.
 *
 * Inspired by Letta's sleep-time compute pattern: background consolidation
 * during idle time produces clean, compact memories.
 */

import { dbLogger } from '../logger'
import { memoryFactRepository } from '../db/repositories/memory-fact.repository'
import { memoryEngineService, cosineSimilarity } from './memory-engine.service'
import type { MemoryFact } from '../../shared/types'

const log = dbLogger

// ── Thresholds ──────────────────────────────────────────────────────────────
const CLUSTER_THRESHOLD = 0.85
const AUTO_MERGE_THRESHOLD = 0.95
const STALE_T0_DAYS = 30
const CONTRADICTION_PRUNE_DAYS = 30
const MAX_REVIEW_QUEUE = 100

// ── Idle job settings ───────────────────────────────────────────────────────
const IDLE_JOB_INTERVAL_MS = 6 * 60 * 60 * 1000 // 6 hours
const IDLE_JOB_DELAY_MS = 5 * 60 * 1000 // 5 minutes after startup

// ── Helpers ────────────────────────────────────────────────────────────────

/**
 * True when at least one confirmation is non-auto_dedup (real evidence).
 * Pure variant exported for testing; the DB-backed wrapper is used internally.
 */
function hasRealEvidencePure(confirmations: Array<{ sourceType: string }>): boolean {
  return confirmations.some((c) => c.sourceType !== 'auto_dedup')
}

/** DB-backed wrapper — exported so integration tests can exercise production wiring. */
function hasRealEvidence(factId: string): boolean {
  return hasRealEvidencePure(memoryFactRepository.getConfirmations(factId))
}

/** Facts eligible for stale-T0 archival: tier 0, never accessed,
 *  workspace-owned, older than STALE_T0_DAYS, and no real evidence. */
function selectStaleT0Facts(
  facts: MemoryFact[],
  workspaceId: string,
  hasEvidence: (factId: string) => boolean
): MemoryFact[] {
  return facts.filter((f) =>
    f.tier === 0 &&
    !f.lastAccessedAt &&
    f.workspaceId === workspaceId &&
    daysSince(f.createdAt) > STALE_T0_DAYS &&
    !hasEvidence(f.id)
  )
}

interface ConsolidationResult {
  clustersFound: number
  autoMerged: number
  reviewItemsCreated: number
  staleArchived: number
  contradictionsPruned: number
  reviewQueueCapped: number
}

class MemoryConsolidationService {
  private startupTimer: ReturnType<typeof setTimeout> | null = null
  private idleTimer: ReturnType<typeof setInterval> | null = null
  private running = false
  private _boundWorkspaceId: string | null = null

  /** The workspace currently bound to the idle consolidation job, or null. */
  get boundWorkspaceId(): string | null {
    return this._boundWorkspaceId
  }

  // ── One-time consolidation pass ──────────────────────────────────────

  /**
   * Full consolidation: cluster all active facts at ≥0.85 similarity,
   * auto-merge ≥0.95, queue 0.85–0.95 for review.
   * Target: reduce active facts from 668 to ~250–350.
   */
  async runFullConsolidation(workspaceId: string): Promise<ConsolidationResult> {
    if (this.running) {
      log.warn('[Consolidation] Already running, skipping')
      return emptyResult()
    }

    this.running = true
    try {
      log.info('[Consolidation] Starting full consolidation pass')
      return this.consolidate(workspaceId)
    } finally {
      this.running = false
    }
  }

  /** Core consolidation logic — builds clusters and processes them. */
  private consolidate(workspaceId: string): ConsolidationResult {
    const embedded = memoryFactRepository.findWithEmbeddings(workspaceId)
    if (embedded.length < 2) {
      log.info(`[Consolidation] Only ${embedded.length} facts with embeddings, nothing to consolidate`)
      return emptyResult()
    }

    log.info(`[Consolidation] Processing ${embedded.length} embedded facts`)

    // Build adjacency list for connected components at CLUSTER_THRESHOLD
    const adjacency = new Map<number, Set<number>>()
    const pairSimilarities = new Map<string, number>()

    for (let i = 0; i < embedded.length; i++) {
      for (let j = i + 1; j < embedded.length; j++) {
        const sim = cosineSimilarity(embedded[i].embedding, embedded[j].embedding)
        if (sim >= CLUSTER_THRESHOLD) {
          if (!adjacency.has(i)) adjacency.set(i, new Set())
          if (!adjacency.has(j)) adjacency.set(j, new Set())
          adjacency.get(i)!.add(j)
          adjacency.get(j)!.add(i)
          pairSimilarities.set(`${Math.min(i, j)}-${Math.max(i, j)}`, sim)
        }
      }
    }

    // Find connected components
    const visited = new Set<number>()
    const clusters: number[][] = []

    for (const node of adjacency.keys()) {
      if (visited.has(node)) continue
      const cluster: number[] = []
      const stack = [node]
      while (stack.length > 0) {
        const current = stack.pop()!
        if (visited.has(current)) continue
        visited.add(current)
        cluster.push(current)
        for (const neighbor of adjacency.get(current) ?? []) {
          if (!visited.has(neighbor)) stack.push(neighbor)
        }
      }
      if (cluster.length >= 2) clusters.push(cluster)
    }

    let autoMerged = 0
    let reviewItemsCreated = 0

    for (const cluster of clusters) {
      const clusterFacts = cluster.map((idx) => embedded[idx].fact)

      // Check if all pairs in cluster are ≥ AUTO_MERGE_THRESHOLD
      let allAutoMergeable = true
      for (let i = 0; i < cluster.length && allAutoMergeable; i++) {
        for (let j = i + 1; j < cluster.length && allAutoMergeable; j++) {
          const a = Math.min(cluster[i], cluster[j])
          const b = Math.max(cluster[i], cluster[j])
          const sim = pairSimilarities.get(`${a}-${b}`) ?? 0
          if (sim < AUTO_MERGE_THRESHOLD) allAutoMergeable = false
        }
      }

      if (allAutoMergeable) {
        // Auto-merge: keep highest-tier, most-confirmed fact as canonical
        autoMerged += this.mergeCluster(clusterFacts)
      } else {
        // Queue one review item per cluster
        reviewItemsCreated += this.queueClusterReview(clusterFacts, cluster, embedded, pairSimilarities)
      }
    }

    // Run cleanup tasks
    const staleArchived = this.archiveStaleT0Facts(workspaceId)
    const contradictionsPruned = this.pruneOldContradictions()
    const reviewQueueCapped = this.capReviewQueue()

    const result: ConsolidationResult = {
      clustersFound: clusters.length,
      autoMerged,
      reviewItemsCreated,
      staleArchived,
      contradictionsPruned,
      reviewQueueCapped
    }

    log.info(
      `[Consolidation] Complete: ${clusters.length} clusters, ${autoMerged} merged, ` +
      `${reviewItemsCreated} review items, ${staleArchived} stale archived, ` +
      `${contradictionsPruned} contradictions pruned`
    )

    return result
  }

  /** Merge a cluster of highly-similar facts into one canonical fact. */
  private mergeCluster(facts: MemoryFact[]): number {
    // Sort: highest tier first, then most confirmations, then most recent
    facts.sort((a, b) =>
      b.tier !== a.tier ? b.tier - a.tier :
      b.confirmationCount !== a.confirmationCount ? b.confirmationCount - a.confirmationCount :
      new Date(b.updatedAt).getTime() - new Date(a.updatedAt).getTime()
    )

    const canonical = facts[0]
    let merged = 0

    // Merge scope paths and tags from all members into canonical
    const allScopePaths = new Set(canonical.scopePaths)
    const allTags = new Set(canonical.tags)

    for (let i = 1; i < facts.length; i++) {
      facts[i].scopePaths.forEach((p) => allScopePaths.add(p))
      facts[i].tags.forEach((t) => allTags.add(t))
      // Transfer confirmation events to the canonical fact (summed evidence)
      memoryFactRepository.reparentConfirmations(facts[i].id, canonical.id)
      memoryFactRepository.mergeFact(facts[i].id, canonical.id)
      merged++
    }

    // Update canonical with merged scope paths/tags
    if (allScopePaths.size > canonical.scopePaths.length || allTags.size > canonical.tags.length) {
      memoryFactRepository.updateFact(canonical.id, {
        scopePaths: Array.from(allScopePaths),
        tags: Array.from(allTags)
      })
    }

    log.debug(`[Consolidation] Merged ${merged} facts into canonical ${canonical.id}: "${canonical.title}"`)
    return merged
  }

  /** Queue a single review item for a cluster that needs human review. */
  private queueClusterReview(
    facts: MemoryFact[],
    clusterIndices: number[],
    embedded: Array<{ fact: MemoryFact; embedding: Float32Array }>,
    pairSimilarities: Map<string, number>
  ): number {
    // Use the pair with highest similarity as the representative
    let bestI = clusterIndices[0]
    let bestJ = clusterIndices[1]
    let bestSim = 0

    for (let i = 0; i < clusterIndices.length; i++) {
      for (let j = i + 1; j < clusterIndices.length; j++) {
        const a = Math.min(clusterIndices[i], clusterIndices[j])
        const b = Math.max(clusterIndices[i], clusterIndices[j])
        const sim = pairSimilarities.get(`${a}-${b}`) ?? 0
        if (sim > bestSim) {
          bestSim = sim
          bestI = clusterIndices[i]
          bestJ = clusterIndices[j]
        }
      }
    }

    const created = memoryFactRepository.createContradiction({
      oldFactId: embedded[bestI].fact.id,
      newFactId: embedded[bestJ].fact.id,
      status: 'pending',
      resolution: `review cluster (${facts.length} facts, best cosine: ${bestSim.toFixed(3)})`
    })
    // ON CONFLICT DO NOTHING returns null when the pair already exists
    return created ? 1 : 0
  }

  // ── Cleanup tasks ──────────────────────────────────────────────────────

  /** Archive T0 facts never accessed or confirmed (with real evidence) in STALE_T0_DAYS days. */
  private archiveStaleT0Facts(workspaceId: string): number {
    try {
      const active = memoryFactRepository.findByWorkspace(workspaceId, 'active')
      const stale = selectStaleT0Facts(active, workspaceId, (id) => hasRealEvidence(id))

      for (const fact of stale) {
        memoryFactRepository.archiveFact(fact.id)
      }

      if (stale.length > 0) {
        log.info(`[Consolidation] Archived ${stale.length} stale T0 facts`)
      }
      return stale.length
    } catch (err) {
      log.warn('[Consolidation] Archive stale T0 failed:', err)
      return 0
    }
  }

  /** Prune resolved contradiction records older than threshold. */
  private pruneOldContradictions(): number {
    try {
      return memoryFactRepository.pruneOldContradictions(CONTRADICTION_PRUNE_DAYS)
    } catch (err) {
      log.warn('[Consolidation] Prune contradictions failed:', err)
      return 0
    }
  }

  /** Cap the review queue by expiring oldest items beyond MAX_REVIEW_QUEUE. */
  private capReviewQueue(): number {
    try {
      const pendingCount = memoryFactRepository.countPendingContradictions()
      if (pendingCount <= MAX_REVIEW_QUEUE) return 0

      // Resolve the oldest excess as 'auto_resolved'
      const excess = pendingCount - MAX_REVIEW_QUEUE
      const pending = memoryFactRepository.findContradictions('pending')
      const toResolve = pending.slice(-excess) // oldest are at the end (DESC order)

      for (const c of toResolve) {
        memoryFactRepository.resolveContradiction(c.id, 'auto-expired (queue cap)', 'auto_resolved')
      }

      log.info(`[Consolidation] Capped review queue: resolved ${toResolve.length} oldest items`)
      return toResolve.length
    } catch (err) {
      log.warn('[Consolidation] Cap review queue failed:', err)
      return 0
    }
  }

  // ── Idle job ──────────────────────────────────────────────────────────

  /** Start the periodic idle consolidation job. */
  startIdleJob(workspaceId: string): void {
    if (this.idleTimer || this.startupTimer) return

    this._boundWorkspaceId = workspaceId

    // Delay first run — store handle so stopIdleJob can cancel
    this.startupTimer = setTimeout(() => {
      this.startupTimer = null
      this.runIdleConsolidation(workspaceId)

      // Then run periodically
      this.idleTimer = setInterval(
        () => this.runIdleConsolidation(workspaceId),
        IDLE_JOB_INTERVAL_MS
      )
    }, IDLE_JOB_DELAY_MS)

    log.info('[Consolidation] Idle job scheduled (6h interval, 5min initial delay)')
  }

  /** Stop the idle job for a specific workspace (no-op if different workspace is bound). */
  stopIdleJobIfWorkspace(workspaceId: string): void {
    if (this._boundWorkspaceId === workspaceId) this.stopIdleJob()
  }

  /** Stop the idle job (cancels both startup timer and interval). */
  stopIdleJob(): void {
    if (this.startupTimer) {
      clearTimeout(this.startupTimer)
      this.startupTimer = null
    }
    if (this.idleTimer) {
      clearInterval(this.idleTimer)
      this.idleTimer = null
    }
    this._boundWorkspaceId = null
  }

  /** Run a lightweight consolidation pass (subset of full). */
  private async runIdleConsolidation(workspaceId: string): Promise<void> {
    if (this.running) return

    this.running = true
    try {
      log.info('[Consolidation] Running idle consolidation')

      // 1. Cluster & auto-merge ≥0.95 duplicates
      memoryEngineService.scanForDuplicates(workspaceId)

      // 2. Archive stale T0 facts
      this.archiveStaleT0Facts(workspaceId)

      // 3. Prune old contradiction records
      this.pruneOldContradictions()

      // 4. Cap review queue
      this.capReviewQueue()

      // 5. Run decay sweep
      memoryEngineService.runDecaySweepIfDue()

      log.info('[Consolidation] Idle consolidation complete')
    } catch (err) {
      log.warn('[Consolidation] Idle consolidation failed:', err)
    } finally {
      this.running = false
    }
  }
}

// ── Helpers ─────────────────────────────────────────────────────────────────

function daysSince(dateStr: string): number {
  return Math.floor((Date.now() - new Date(dateStr).getTime()) / (24 * 60 * 60 * 1000))
}

function emptyResult(): ConsolidationResult {
  return {
    clustersFound: 0,
    autoMerged: 0,
    reviewItemsCreated: 0,
    staleArchived: 0,
    contradictionsPruned: 0,
    reviewQueueCapped: 0
  }
}

export { hasRealEvidencePure, hasRealEvidence, selectStaleT0Facts }
export const memoryConsolidationService = new MemoryConsolidationService()

/**
 * IPC handlers for project creation (Create New Project wizard).
 *
 * Handles creating a new project directory, generating CLAUDE.md via AI,
 * and registering the workspace in the database.
 *
 * The wizard creates the workspace EARLY (before the grill step) so the
 * greenfield grill runs workspace-backed. Creation is therefore split:
 *   - `createShell`     — folder + attachments + workspace/specialist rows (no CLAUDE.md)
 *   - `writeBlueprint`  — generate + write CLAUDE.md (deferred until grill decisions exist)
 *   - `discardShell`    — undo a shell on wizard abandon (DB cascade + on-disk folder)
 * `PROJECT_CREATE` remains a thin shell+blueprint wrapper for the skip-grill path.
 */

import { ipcMain } from 'electron'
import { existsSync, mkdirSync, writeFileSync, copyFileSync, rmSync } from 'node:fs'
import { join, resolve, basename } from 'node:path'
import { IPC_CHANNELS } from '../../shared/constants'
import type { GrillDecision, GrillTrackScore, Workspace } from '../../shared/types'
import { workspaceRepository } from '../db/repositories'
import { grillSessionRepository } from '../db/repositories/grill-session.repository'
import { generateClaudeMd } from '../services/claude-md-generator'
import { validateSender } from './validate-sender'
import { getDatabase } from '../db/index'
import log from 'electron-log'

const projectLog = log.scope('project-ipc')

interface CreateShellArgs {
  name: string
  parentFolder: string
  description?: string
  attachments?: string[]
  tempGrillSessionId?: string
}

interface BlueprintArgs {
  projectName: string
  description?: string
  grillDecisions?: GrillDecision[]
  trackScores?: GrillTrackScore[]
}

// ── Shared helpers ──────────────────────────────────────────────────────────

/**
 * Create the project directory + workspace/specialist DB rows. Does NOT generate
 * CLAUDE.md — that's deferred to `writeBlueprint` so grill decisions can be folded in.
 */
function createShell(args: CreateShellArgs): Workspace {
  const { name, parentFolder, description, attachments, tempGrillSessionId } = args

  // ── Validate inputs ──
  if (!name || typeof name !== 'string' || name.trim().length === 0 || name.length > 255) {
    throw new Error('Invalid project name: must be a non-empty string (max 255 chars)')
  }
  if (!parentFolder || typeof parentFolder !== 'string' || parentFolder.trim().length === 0) {
    throw new Error('Invalid parent folder path')
  }

  const normalizedParent = resolve(parentFolder)
  if (!existsSync(normalizedParent)) {
    throw new Error(`Parent folder does not exist: ${normalizedParent}`)
  }

  const projectPath = join(normalizedParent, name.trim())
  if (existsSync(projectPath)) {
    throw new Error(`A folder named "${name.trim()}" already exists at ${normalizedParent}`)
  }

  projectLog.info(`[project:shell] Creating project "${name}" at ${projectPath}`)

  // ── Create the project directory ──
  try {
    mkdirSync(projectPath, { recursive: true })
    projectLog.info(`[project:shell] Directory created: ${projectPath}`)
  } catch (err) {
    throw new Error(
      `Failed to create project directory: ${err instanceof Error ? err.message : String(err)}`
    )
  }

  // ── Copy attachments into project ──
  if (attachments && attachments.length > 0) {
    const contextDir = join(projectPath, '.context')
    try {
      mkdirSync(contextDir, { recursive: true })
      for (const srcPath of attachments) {
        if (existsSync(srcPath)) {
          const fileName = basename(srcPath)
          copyFileSync(srcPath, join(contextDir, fileName))
        }
      }
      projectLog.info(`[project:shell] ${attachments.length} attachment(s) copied to .context/`)
    } catch (err) {
      projectLog.error('[project:shell] Failed to copy attachments:', err)
      // Non-fatal — project still usable
    }
  }

  // ── Register workspace in DB ──
  const workspace = workspaceRepository.create(
    name.trim() || basename(projectPath),
    projectPath,
    undefined, // no git remote
    false // not a git repo
  )
  projectLog.info(`[project:shell] Workspace registered: ${workspace.id}`)



  // ── Seed Project Specialist row ──
  try {
    const db = getDatabase()
    const existing = db
      .prepare(`SELECT id FROM specialists WHERE workspace_id = ?`)
      .get(workspace.id) as { id: string } | undefined
    if (!existing) {
      db.prepare(
        `INSERT INTO specialists (workspace_id, agent_id, display_name, icon, color,
           prompt, priority, is_active, build_status, created_at, updated_at)
         VALUES (?, ?, ?, '🔧', '#6366F1', '', 1, 1, 'pending', datetime('now'), datetime('now'))`
      ).run(workspace.id, `workspace-specialist-${workspace.id}`, `${workspace.name} Specialist`)
      projectLog.info(`[project:shell] Seeded Project Specialist for workspace ${workspace.id}`)
    }
  } catch (err) {
    projectLog.warn('[project:shell] Failed to seed Project Specialist:', err)
  }

  // ── Link temporary grill session (if applicable) ──
  if (tempGrillSessionId) {
    try {
      grillSessionRepository.linkToWorkspace(tempGrillSessionId, workspace.id)
      projectLog.info(
        `[project:shell] Linked grill session ${tempGrillSessionId} to workspace ${workspace.id}`
      )
    } catch (err) {
      projectLog.warn('[project:shell] Failed to link grill session:', err)
    }
  }

  // Best-effort: avoid orphaning the description until the blueprint runs.
  void description
  return workspace
}

/**
 * Generate CLAUDE.md (AI, folding in grill decisions) and write it to the project
 * root. Falls back to a minimal template if generation fails. Idempotent — safe
 * to call once the grill has produced decisions.
 */
async function writeBlueprint(projectPath: string, args: BlueprintArgs): Promise<void> {
  const { projectName, description, grillDecisions, trackScores } = args

  let claudeMdContent: string
  try {
    claudeMdContent = await generateClaudeMd({
      projectName: projectName.trim(),
      description: description || '',
      grillDecisions: grillDecisions ?? [],
      trackScores: trackScores ?? []
    })
    projectLog.info(`[project:blueprint] CLAUDE.md generated (${claudeMdContent.length} chars)`)
  } catch (err) {
    projectLog.error('[project:blueprint] CLAUDE.md generation failed:', err)
    claudeMdContent = `# Project: ${projectName.trim()}\n\n## Overview\n\n${description || 'No description provided.'}\n`
  }

  try {
    writeFileSync(join(projectPath, 'CLAUDE.md'), claudeMdContent, 'utf-8')
    projectLog.info(`[project:blueprint] CLAUDE.md written to ${projectPath}`)
  } catch (err) {
    projectLog.error('[project:blueprint] Failed to write CLAUDE.md:', err)
    // Non-fatal — workspace can still be used
  }
}

// ── Registration ─────────────────────────────────────────────────────────────

export function registerProjectIpc(): void {
  // Full create (shell + blueprint) — used by the skip-grill path / backward compat.
  ipcMain.handle(
    IPC_CHANNELS.PROJECT_CREATE,
    async (
      event,
      args: {
        name: string
        parentFolder: string
        description: string
        attachments?: string[]
        grillDecisions?: GrillDecision[]
        trackScores?: GrillTrackScore[]
        tempGrillSessionId?: string
      }
    ) => {
      validateSender(event)
      const workspace = createShell(args)
      await writeBlueprint(workspace.repoPath, {
        projectName: args.name,
        description: args.description,
        grillDecisions: args.grillDecisions,
        trackScores: args.trackScores
      })
      return workspace
    }
  )

  // Shell only — create the workspace BEFORE the grill step (no CLAUDE.md yet).
  ipcMain.handle(
    IPC_CHANNELS.PROJECT_CREATE_SHELL,
    async (event, args: CreateShellArgs): Promise<Workspace> => {
      validateSender(event)
      return createShell(args)
    }
  )

  // Finalize — generate + write CLAUDE.md for an already-created workspace.
  ipcMain.handle(
    IPC_CHANNELS.PROJECT_FINALIZE_BLUEPRINT,
    async (
      event,
      args: {
        workspaceId: string
        projectName: string
        description?: string
        grillDecisions?: GrillDecision[]
        trackScores?: GrillTrackScore[]
      }
    ): Promise<void> => {
      validateSender(event)
      const workspace = workspaceRepository.findById(args.workspaceId)
      if (!workspace) {
        throw new Error(`Workspace not found: ${args.workspaceId}`)
      }
      await writeBlueprint(workspace.repoPath, {
        projectName: args.projectName,
        description: args.description,
        grillDecisions: args.grillDecisions,
        trackScores: args.trackScores
      })
    }
  )

  // Discard a shell on wizard abandon — DB cascade + remove the on-disk folder.
  ipcMain.handle(
    IPC_CHANNELS.PROJECT_DISCARD_SHELL,
    async (event, args: { workspaceId: string }): Promise<void> => {
      validateSender(event)
      const workspace = workspaceRepository.findById(args.workspaceId)
      if (!workspace) {
        projectLog.warn(
          `[project:discard] Workspace not found (already gone?): ${args.workspaceId}`
        )
        return
      }
      const repoPath = workspace.repoPath

      // DB cascade (conversations, ideas, grill sessions, specialists, …).
      try {
        workspaceRepository.delete(args.workspaceId)
      } catch (err) {
        projectLog.error('[project:discard] Failed to delete workspace row:', err)
      }

      // Remove the on-disk folder we created. Guard against deleting a root /
      // non-existent path; only remove a real, nested project directory.
      try {
        const normalized = resolve(repoPath)
        if (normalized && normalized !== resolve('/') && existsSync(normalized)) {
          rmSync(normalized, { recursive: true, force: true })
          projectLog.info(`[project:discard] Removed project folder: ${normalized}`)
        }
      } catch (err) {
        projectLog.error('[project:discard] Failed to remove project folder:', err)
      }
    }
  )
}

/**
 * IPC handlers for Project Specialist management.
 *
 * Surfaces:
 *   - Get / List (one per workspace, plus a list call for Settings)
 *   - Build / Rebuild prompt / Rebuild skills (LLM-driven + fast paths)
 *   - Update prompt (manual edit from the slide-over Prompt tab)
 *   - Toggle skill enabled/disabled + attach/detach skill
 *   - Get stack drift (non-blocking banner)
 *
 * MCP tool availability is a workspace-level concern (configured from the
 * workspace settings UI) and is NOT per-specialist — there is no toggle-MCP
 * handler here.
 *
 * The BUILD_PROGRESS channel is an event channel (main → renderer) used to
 * stream build status updates into the inline BuildProgress UI.
 */

import { ipcMain, BrowserWindow } from 'electron'
import { IPC_CHANNELS } from '../../shared/constants'
import { getDatabase } from '../db/index'
import { specialistRepository } from '../db/repositories'
import { specialistBuilderService } from '../services/specialist-builder.service'
import { stackDriftDetectorService } from '../services/stack-drift-detector.service'
import { validateSender } from './validate-sender'
import { safeWindowSend } from './safe-send'
import { requireObject, requireString, optionalBoolean } from './validate-args'
import log from 'electron-log'

const psLog = log.scope('project-specialist-ipc')

interface ProjectSpecialistRow {
  id: string
  workspace_id: string
  agent_id: string
  display_name: string
  icon: string
  color: string
  prompt: string
  build_status: 'pending' | 'building' | 'ready' | 'failed'
  stack_fingerprint: string | null
  detected_techs: string
  last_built_at: string | null
  created_at: string
  updated_at: string
  skill_recommendations_json: string | null
}

function emitProgress(specialistId: string, phase: string, message: string): void {
  for (const win of BrowserWindow.getAllWindows()) {
    safeWindowSend(win, IPC_CHANNELS.PROJECT_SPECIALIST_BUILD_PROGRESS, {
      specialistId,
      phase,
      message,
      at: new Date().toISOString()
    })
  }
}

function loadRow(workspaceId: string): ProjectSpecialistRow | undefined {
  const db = getDatabase()
  return db
    .prepare(
      `SELECT id, workspace_id, agent_id, display_name, icon, color, prompt, build_status,
              stack_fingerprint, detected_techs, last_built_at,
              skill_recommendations_json,
              created_at, updated_at
         FROM specialists WHERE workspace_id = ?`
    )
    .get(workspaceId) as ProjectSpecialistRow | undefined
}

function serializeRow(row: ProjectSpecialistRow): Record<string, unknown> {
  let detectedTechs: string[] = []
  try {
    detectedTechs = JSON.parse(row.detected_techs || '[]')
  } catch {
    detectedTechs = []
  }
  let skillRecommendations: Array<{
    skillId: string
    relevance: number
    rationale: string
  }> | null = null
  try {
    if (row.skill_recommendations_json) {
      const parsed = JSON.parse(row.skill_recommendations_json)
      skillRecommendations = parsed.recommendations ?? null
    }
  } catch {
    skillRecommendations = null
  }
  return {
    id: row.id,
    workspaceId: row.workspace_id,
    agentId: row.agent_id,
    displayName: row.display_name,
    icon: row.icon,
    color: row.color,
    prompt: row.prompt,
    buildStatus: row.build_status,
    stackFingerprint: row.stack_fingerprint,
    detectedTechs,
    skillRecommendations,
    lastBuiltAt: row.last_built_at,
    createdAt: row.created_at,
    updatedAt: row.updated_at
  }
}

function loadSkillsForSpecialist(specialistId: string): Array<{
  id: string
  name: string
  description: string | null
  filename: string
  isEnabled: boolean
}> {
  const db = getDatabase()
  const rows = db
    .prepare(
      `SELECT s.id, s.name, s.description, s.filename, ss.is_enabled
         FROM specialist_skills ss
         JOIN skills s ON s.id = ss.skill_id
        WHERE ss.specialist_id = ?
        ORDER BY s.name`
    )
    .all(specialistId) as Array<{
    id: string
    name: string
    description: string | null
    filename: string
    is_enabled: number
  }>
  return rows.map((r) => ({
    id: r.id,
    name: r.name,
    description: r.description,
    filename: r.filename,
    isEnabled: r.is_enabled === 1
  }))
}

