const planLog = log.scope('plan-ipc')

export function registerPlanIpc(): void {
  // ── plan:getAll — List plans for a workspace with optional filters ──
  ipcMain.handle(
    IPC_CHANNELS.PLAN_GET_ALL,
    (event, args: { workspaceId: string; filters?: PlanFilters }) => {
      validateSender(event)
      return planRepository.getForWorkspace(args.workspaceId, args.filters)
    }
  )

  // ── plan:getById — Fetch a single plan ──
  ipcMain.handle(IPC_CHANNELS.PLAN_GET_BY_ID, (event, args: { planId: string }) => {
    validateSender(event)
    return planRepository.getById(args.planId)
  })

  // ── plan:updateStatus — Update plan lifecycle status ──
  ipcMain.handle(
    IPC_CHANNELS.PLAN_UPDATE_STATUS,
    (
      event,
      args: {
        planId: string
        status: PlanStatus
        linkedConversationId?: string
        linkedMpaRunId?: string
        linkedCouncilSessionId?: string
      }
    ) => {
      validateSender(event)
      planRepository.updateStatus(args.planId, args.status, {
        conversationId: args.linkedConversationId,
        mpaRunId: args.linkedMpaRunId,
        councilSessionId: args.linkedCouncilSessionId
      })
      planLog.info(`[plan:updateStatus] ${args.planId} → ${args.status}`)
      return { success: true }
    }
  )

  // ── plan:delete — Delete a plan from the registry ──
  ipcMain.handle(IPC_CHANNELS.PLAN_DELETE, (event, args: { planId: string }) => {
    validateSender(event)
    const deleted = planRepository.deletePlan(args.planId)
    planLog.info(`[plan:delete] ${args.planId} deleted=${deleted}`)
    return { deleted }
  })

  // ── plan:getStatusHistory — Fetch plan status timeline ──
  ipcMain.handle(
    IPC_CHANNELS.PLAN_GET_STATUS_HISTORY,
    (event, args: { planId: string }) => {
      validateSender(event)
      return planRepository.getStatusHistory(args.planId)
    }
  )

  // ── plan:getPhaseProgress — Retrieve phase progress for a conversation's active plan ──
  ipcMain.handle(
    IPC_CHANNELS.PLAN_GET_PHASE_PROGRESS,
    (event, args: { conversationId: string }) => {
      validateSender(event)
      const plan = planRepository.findActiveByConversationId(args.conversationId)
      if (!plan) return null
      // Return the FULL derived task manifest (not just {id, title}) so
      // rehydration restores the complete task denominator (e.g. "3/8"),
      // not just whichever tasks happened to have recorded progress —
      // otherwise a reload makes finished work look forgotten.
      return {
        planId: plan.id,
        planTitle: plan.title,
        planGoal: plan.structuredPlan.goal,
        phases: derivePlanTasks(plan.structuredPlan),
        phaseFiles: derivePhaseFiles(plan.structuredPlan),
        progress: planRepository.getPhaseProgress(plan.id)
      }
    }
  )

  // ── plan:findBySource — Look up a plan by its source type + sourceId ──
  ipcMain.handle(
    IPC_CHANNELS.PLAN_FIND_BY_SOURCE,
    (event, args: { source: PlanSource; sourceId: string }) => {
      validateSender(event)
      return planRepository.findBySource(args.source, args.sourceId)
    }
  )

  // ── plan:import — Create new conversation pre-loaded with plan content ──
  ipcMain.handle(
    IPC_CHANNELS.PLAN_IMPORT,
    (event, args: { planId: string; workspaceId: string }) => {
      validateSender(event)

      const plan = planRepository.getById(args.planId)
      if (!plan) {
        throw new Error(`Plan not found: ${args.planId}`)
      }

      // Build the message content from requirementDocument or structured plan
      const planContent =
        plan.requirementDocument ||
        `# ${plan.title}\n\n${plan.summary}\n\n${JSON.stringify(plan.structuredPlan, null, 2)}`

      const messageContent = `I have a plan I'd like to implement:\n\n${planContent}`

      // ATOM-03: Wrap all three writes in a transaction so partial failure
      // doesn't leave an orphaned conversation or un-linked plan.
      const db = getDatabase()
      // Resolve workspace provider and snapshot for the new conversation
      const wsSettings = workspaceRepository.getSettings(args.workspaceId)
      const llmProvider: LLMProvider = (wsSettings.llmProvider as LLMProvider) ?? 'claude'
      const snapshot = buildConversationModelSnapshot(args.workspaceId, llmProvider)

      const result = db.transaction(() => {
        const conversation = conversationRepository.create(
          args.workspaceId,
          plan.title,
          'plan',
          undefined,
          llmProvider,
          undefined,
          undefined,
          undefined,
          snapshot
        )
        messageRepository.create(conversation.id, 'user', messageContent)
        planRepository.markHandedOff(plan.id, conversation.id)
        return { conversationId: conversation.id, planId: plan.id }
      })()

      planLog.info(`[plan:import] Plan ${result.planId} imported into conversation ${result.conversationId}`)

      return result
    }
  )
}

import { ipcMain } from 'electron'
import { execFileSync } from 'node:child_process'
import { IPC_CHANNELS } from '../../shared/constants'
import { validateSender } from './validate-sender'
import {
  requireObject,
  requireString,
  optionalString,
  optionalNumber,
  optionalBoolean,
  optionalNullableString
} from './validate-args'
import log from 'electron-log/main'

const sessionLog = log.scope('SessionIPC')

/**
 * Execute a Claude CLI command and return parsed JSON output.
 * Uses `claude` in print mode with JSON output for session operations.
 */
function claudeExec(args: string[], cwd?: string): unknown {
  const result = execFileSync('claude', [...args, '--output-format', 'json'], {
    encoding: 'utf-8',
    timeout: 10_000,
    cwd
  })
  return JSON.parse(result.trim())
}

/**
 * Session Management IPC handlers — bridges renderer requests to CLI
 * session management commands.
 *
 * These do NOT require an active session — they operate on persisted sessions.
 *
 * Every handler runs `validateSender` first, then performs field-level runtime
 * validation on its args.
 *
 * Note: Some operations (rename, tag, fork) previously used SDK functions.
 * They now use the `claude` CLI or direct file operations where available.
 */
export function registerSessionIpc(): void {
  ipcMain.handle(IPC_CHANNELS.SESSION_LIST, async (event, args?: unknown) => {
    validateSender(event)
    const channel = IPC_CHANNELS.SESSION_LIST
    let parsed: { dir?: string; limit?: number; offset?: number } | undefined
    if (args !== undefined) {
      const obj = requireObject(args, channel)
      parsed = {
        dir: optionalString(obj, 'dir', channel),
        limit: optionalNumber(obj, 'limit', channel),
        offset: optionalNumber(obj, 'offset', channel)
      }
    }
    try {
      const cliArgs = ['-p', 'list sessions', '--print']
      if (parsed?.dir) cliArgs.push('--add-dir', parsed.dir)
      return claudeExec(cliArgs, parsed?.dir)
    } catch (err) {
      sessionLog.warn('[SESSION_LIST] CLI fallback failed, returning empty:', err)
      return []
    }
  })

  ipcMain.handle(IPC_CHANNELS.SESSION_GET_INFO, async (event, args: unknown) => {
    validateSender(event)
    const channel = IPC_CHANNELS.SESSION_GET_INFO
    const obj = requireObject(args, channel)
    const sessionId = requireString(obj, 'sessionId', channel)
    const dir = optionalString(obj, 'dir', channel)
    try {
      return claudeExec(['--resume', sessionId, '-p', '--print', 'session info'], dir)
    } catch (err) {
      sessionLog.warn(`[SESSION_GET_INFO] Failed for ${sessionId}:`, err)
      return null
    }
  })

  ipcMain.handle(IPC_CHANNELS.SESSION_GET_MESSAGES, async (event, args: unknown) => {
    validateSender(event)
    const channel = IPC_CHANNELS.SESSION_GET_MESSAGES
    const obj = requireObject(args, channel)
    const sessionId = requireString(obj, 'sessionId', channel)
    optionalString(obj, 'dir', channel)
    optionalBoolean(obj, 'includeSystemMessages', channel)
    // Not yet implemented — requires CLI support or direct session file reader.
    // Return a typed error so the renderer can surface "Not yet available" to the user.
    sessionLog.warn(`[NOT_IMPLEMENTED] SESSION_GET_MESSAGES called for ${sessionId}`)
    return {
      error: 'not_implemented',
      message: 'Session message inspection requires CLI implementation'
    }
  })

  ipcMain.handle(IPC_CHANNELS.SESSION_RENAME, async (event, args: unknown) => {
    validateSender(event)
    const channel = IPC_CHANNELS.SESSION_RENAME
    const obj = requireObject(args, channel)
    const sessionId = requireString(obj, 'sessionId', channel)
    const title = requireString(obj, 'title', channel)
    const _dir = optionalString(obj, 'dir', channel)
    try {
      // CLI supports --name flag for naming sessions
      return claudeExec(['--resume', sessionId, '-p', '--name', title, '--print', 'renamed'], _dir)
    } catch (err) {
      sessionLog.warn(`[SESSION_RENAME] Failed for ${sessionId}:`, err)
      return { success: false, error: 'Session rename not available without SDK' }
    }
  })

  ipcMain.handle(IPC_CHANNELS.SESSION_TAG, async (event, args: unknown) => {
    validateSender(event)
    const channel = IPC_CHANNELS.SESSION_TAG
    const obj = requireObject(args, channel)
    const _sessionId = requireString(obj, 'sessionId', channel)
    const tagRaw = optionalNullableString(obj, 'tag', channel)
    if (tagRaw === undefined) {
      throw new Error(`${channel}: field 'tag' is required (use null to clear)`)
    }
    optionalString(obj, 'dir', channel)
    // Not yet implemented — requires CLI support or direct session file modification.
    sessionLog.warn(`[NOT_IMPLEMENTED] SESSION_TAG called for ${_sessionId}`)
    return {
      success: false,
      error: 'not_implemented',
      message: 'Session tagging not yet available'
    }
  })

  ipcMain.handle(IPC_CHANNELS.SESSION_FORK, async (event, args: unknown) => {
    validateSender(event)
    const channel = IPC_CHANNELS.SESSION_FORK
    const obj = requireObject(args, channel)
    const sessionId = requireString(obj, 'sessionId', channel)
    optionalString(obj, 'upToMessageId', channel)
    const _title = optionalString(obj, 'title', channel)
    const dir = optionalString(obj, 'dir', channel)
    try {
      // CLI supports --fork-session with --resume
      const cliArgs = ['--resume', sessionId, '--fork-session', '-p', '--print', 'forked']
      if (_title) cliArgs.push('--name', _title)
      return claudeExec(cliArgs, dir)
    } catch (err) {
      sessionLog.warn(`[SESSION_FORK] Failed for ${sessionId}:`, err)
      return { success: false, error: 'Session fork failed' }
    }
  })
}

import { ipcMain } from 'electron'
import log from 'electron-log'
import { IPC_CHANNELS } from '../../shared/constants'
import { checkpointService } from '../services/checkpoint.service'
import { chatAgentService } from '../services'
import { messageRepository } from '../db/repositories'
import { validateSender } from './validate-sender'
import { requireObject, requireString, optionalBoolean } from './validate-args'

const cpLog = log.scope('checkpoint-ipc')

export function registerCheckpointIpc(): void {
  ipcMain.handle(IPC_CHANNELS.CHECKPOINT_LIST, (event, rawArgs: unknown) => {
    validateSender(event)
    const args = requireObject(rawArgs, IPC_CHANNELS.CHECKPOINT_LIST)
    const conversationId = requireString(args, 'conversationId', IPC_CHANNELS.CHECKPOINT_LIST)
    return checkpointService.listCheckpoints(conversationId)
  })

  ipcMain.handle(IPC_CHANNELS.CHECKPOINT_RESTORE, (event, rawArgs: unknown) => {
    validateSender(event)
    const args = requireObject(rawArgs, IPC_CHANNELS.CHECKPOINT_RESTORE)
    const checkpointId = requireString(args, 'checkpointId', IPC_CHANNELS.CHECKPOINT_RESTORE)

    const workspacePath = chatAgentService.getWorkspacePath()
    if (!workspacePath) {
      throw new Error('No workspace path — agent not started')
    }

    return checkpointService.restoreGitState(checkpointId, workspacePath)
  })

  ipcMain.handle(IPC_CHANNELS.CHECKPOINT_REWIND, (event, rawArgs: unknown) => {
    validateSender(event)
    const args = requireObject(rawArgs, IPC_CHANNELS.CHECKPOINT_REWIND)
    const checkpointId = requireString(args, 'checkpointId', IPC_CHANNELS.CHECKPOINT_REWIND)
    const conversationId = requireString(args, 'conversationId', IPC_CHANNELS.CHECKPOINT_REWIND)

    const workspacePath = chatAgentService.getWorkspacePath()
    if (!workspacePath) {
      throw new Error('No workspace path — agent not started')
    }

    // 1) Restore git state
    const gitResult = checkpointService.restoreGitState(checkpointId, workspacePath)
    if (!gitResult.success) {
      return { success: false, message: gitResult.message, messagesRemoved: 0 }
    }

    // 2) Truncate messages after checkpoint timestamp
    // ATOM-04: If message truncation fails, log the error but don't leave
    // the user in an inconsistent state — git was already restored.
    const checkpoints = checkpointService.listCheckpoints(conversationId)
    const checkpoint = checkpoints.find((c) => c.id === checkpointId)
    let messagesRemoved = 0
    if (checkpoint) {
      try {
        messagesRemoved = messageRepository.truncateAfterTimestamp(
          conversationId,
          checkpoint.createdAt
        )
      } catch (err) {
        cpLog.error(
          `[checkpoint:rewind] Message truncation failed after git restore (checkpoint=${checkpointId}):`,
          err
        )
        return {
          success: false,
          message: `Git state restored but message truncation failed: ${(err as Error).message}`,
          messagesRemoved: 0
        }
      }
    }

    return {
      success: true,
      message: `${gitResult.message}. Removed ${messagesRemoved} message(s).`,
      messagesRemoved
    }
  })

  ipcMain.handle(IPC_CHANNELS.CHECKPOINT_APPROVAL_RESPONSE, (event, rawArgs: unknown) => {
    validateSender(event)
    const args = requireObject(rawArgs, IPC_CHANNELS.CHECKPOINT_APPROVAL_RESPONSE)
    const checkpointId = requireString(
      args,
      'checkpointId',
      IPC_CHANNELS.CHECKPOINT_APPROVAL_RESPONSE
    )
    const approved =
      optionalBoolean(args, 'approved', IPC_CHANNELS.CHECKPOINT_APPROVAL_RESPONSE) ?? false
    checkpointService.resolveApproval(checkpointId, approved)
  })
}

/**
 * Memory IPC handlers — knowledge-aware memory engine.
 *
 * All handlers validate sender first (security convention).
 * Replaces old CRUD-based memory IPC with fact-based engine API.
 */

import type { BrowserWindow } from 'electron'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
import { ipcMain, dialog } from 'electron'
import { IPC_CHANNELS } from '../../shared/constants'
import type {
  MemoryFactCategory,
  MemoryFactStatus,
  MemoryFactTier,
  ContradictionStatus,
  MemoryCaptureSettings
} from '../../shared/types'
import { memoryFactRepository } from '../db/repositories/memory-fact.repository'
import { memoryRetrievalService } from '../services/memory-retrieval.service'
import { memoryEngineService } from '../services/memory-engine.service'
import { memoryExtractionService } from '../services/memory-extraction.service'
import { localEmbeddingProvider } from '../services/local-embedding.provider'
import { workspaceRepository } from '../db/repositories'
import { memoryDocWatcherService } from '../services/memory-doc-watcher.service'
import { buildMemoryGraph } from '../services/memory-graph'
import { memoryIngestionService } from '../services/memory-ingestion.service'
import { memoryBootstrapService } from '../services/memory-bootstrap.service'
import { memoryConsolidationService } from '../services/memory-consolidation.service'
import { validateSender } from './validate-sender'
import { safeWindowSend } from './safe-send'

export function registerMemoryIpc(mainWindow: BrowserWindow): void {
  // ── Facts CRUD ──

  ipcMain.handle(
    IPC_CHANNELS.MEMORY_FACTS_LIST,
    (event, args: { workspaceId: string; status?: MemoryFactStatus }) => {
      validateSender(event)
      if (args.status) {
        return memoryFactRepository.findByWorkspace(args.workspaceId, args.status)
      }
      return memoryFactRepository.findAllByWorkspace(args.workspaceId)
    }
  )

  ipcMain.handle(
    IPC_CHANNELS.MEMORY_FACTS_SEARCH,
    async (event, args: { workspaceId: string; query: string; category?: MemoryFactCategory }) => {
      validateSender(event)
      if (!args.query || args.query.trim().length === 0) {
        return memoryFactRepository.findByWorkspace(args.workspaceId)
      }
      const results = await memoryRetrievalService.retrieve(
        args.workspaceId,
        args.query.trim(),
        20,
        args.category
      )
      const facts = results.map((r) => r.fact)
      const evidence = memoryFactRepository.getEvidenceCounts(facts.map((f) => f.id))
      return results.map((r) => ({
        ...r.fact,
        evidenceCount: evidence.get(r.fact.id) ?? 0,
        _score: r.score,
        _matchType: r.matchType
      }))
    }
  )

  ipcMain.handle(
    IPC_CHANNELS.MEMORY_FACTS_GET,
    (event, args: { id: string }) => {
      validateSender(event)
      return memoryFactRepository.findById(args.id)
    }
  )

  ipcMain.handle(
    IPC_CHANNELS.MEMORY_FACTS_UPDATE,
    (
      event,
      args: {
        id: string
        title?: string
        content?: string
        tags?: string[]
        scopePaths?: string[]
        category?: MemoryFactCategory
      }
    ) => {
      validateSender(event)
      if (!args.id) throw new Error('Fact id is required')
      return memoryFactRepository.updateFact(args.id, args)
    }
  )

  ipcMain.handle(
    IPC_CHANNELS.MEMORY_FACTS_ARCHIVE,
    (event, args: { id: string }) => {
      validateSender(event)
      memoryFactRepository.archiveFact(args.id)
    }
  )

  ipcMain.handle(
    IPC_CHANNELS.MEMORY_FACTS_CONFIRM,
    (event, args: { id: string }) => {
      validateSender(event)
      return memoryEngineService.confirmFactWithPromotion(args.id)
    }
  )

  ipcMain.handle(
    IPC_CHANNELS.MEMORY_FACTS_PROMOTE,
    (event, args: { id: string; tier: MemoryFactTier }) => {
      validateSender(event)
      return memoryFactRepository.updateFact(args.id, { tier: args.tier })
    }
  )

  ipcMain.handle(
    IPC_CHANNELS.MEMORY_FACTS_SCOPE_TOGGLE,
    (event, args: { id: string; global: boolean; workspaceId?: string }) => {
      validateSender(event)
      const fact = memoryFactRepository.findById(args.id)
      if (!fact) throw new Error(`Fact not found: ${args.id}`)
      // Toggle workspace scope: global (null) ↔ workspace-scoped
      const newWorkspaceId = args.global ? null : (args.workspaceId ?? fact.workspaceId ?? null)
      return memoryFactRepository.setWorkspaceScope(args.id, newWorkspaceId)
    }
  )

  ipcMain.handle(
    IPC_CHANNELS.MEMORY_FACTS_DELETE,
    (event, args: { id: string }) => {
      validateSender(event)
      memoryFactRepository.deleteById(args.id)
    }
  )

  // ── Save from message (hover action) ──

  ipcMain.handle(
    IPC_CHANNELS.MEMORY_SAVE_MESSAGE,
    async (event, args: { workspaceId: string; messageContent: string; workspacePath?: string }) => {
      validateSender(event)
      const { memoryExtractionService } = await import('../services/memory-extraction.service')
      const created = await memoryExtractionService.extractFromMessage(
        args.workspaceId,
        args.messageContent,
        args.workspacePath
      )
      return { created }
    }
  )

  // ── Save from plan execution completion ──

  ipcMain.handle(
    IPC_CHANNELS.MEMORY_SAVE_PLAN_EXECUTION,
    async (event, args: {
      workspaceId: string
      workspacePath: string
      conversationId: string
      planTitle: string
      planGoal?: string
      status: 'completed' | 'partial' | 'failed'
      phases: Array<{
        phaseTitle: string
        status: string
        touchedFiles: string[]
        tasks: Array<{ title: string; status: string }>
      }>
      durationMs: number
    }) => {
      validateSender(event)

      // Gate on capturePlans setting
      const settings = workspaceRepository.getSettings(args.workspaceId) as Record<string, unknown>
      if (settings.memoryCapturePlans === false) return { enqueued: false }

      const { memoryExtractionService } = await import('../services/memory-extraction.service')
      memoryExtractionService.enqueuePlanExecutionExtraction(args)
      return { enqueued: true }
    }
  )

  // ── Contradictions ──

  ipcMain.handle(
    IPC_CHANNELS.MEMORY_CONTRADICTIONS_LIST,
    (event, args?: { status?: ContradictionStatus; limit?: number; offset?: number }) => {
      validateSender(event)
      const limit = args?.limit ?? 25
      const offset = args?.offset ?? 0
      const items = memoryFactRepository.findContradictionsPaged(args?.status, limit, offset)
      const total = memoryFactRepository.countContradictions(args?.status)
      const pendingCount = memoryFactRepository.countContradictions('pending')
      return { items, total, pendingCount }
    }
  )

  ipcMain.handle(
    IPC_CHANNELS.MEMORY_CONTRADICTIONS_RESOLVE,
    (
      event,
      args: { id: string; resolution: string; keepFactId: string; archiveFactId?: string }
    ) => {
      validateSender(event)
      const resolved = memoryFactRepository.resolveContradiction(args.id, args.resolution)
      // Optionally archive the losing fact
      if (args.archiveFactId) {
        memoryFactRepository.archiveFact(args.archiveFactId)
      }
      return resolved
    }
  )

  // ── Capture Settings ──

  ipcMain.handle(
    IPC_CHANNELS.MEMORY_CAPTURE_SETTINGS_GET,
    (event, args: { workspaceId: string }) => {
      validateSender(event)
      const settings = workspaceRepository.getSettings(args.workspaceId)
      const memSettings: MemoryCaptureSettings = {
        sessionCapture: (settings as any).memorySessionCapture !== false,
        commitCapture: (settings as any).memoryCommitCapture !== false,
        docCapture: (settings as any).memoryDocCapture !== false,
        captureBlueprints: (settings as any).memoryCaptureBlueprints !== false,
        capturePlans: (settings as any).memoryCapturePlans !== false,
        captureGrill: (settings as any).memoryCaptureGrill !== false,
        captureDocumentsOnAttach: (settings as any).memoryCaptureDocumentsOnAttach !== false,
        watcherGlobs: (settings as any).memoryWatcherGlobs ?? ['docs/**/*.md', 'README.md', 'CLAUDE.md']
      }
      return memSettings
    }
  )

  ipcMain.handle(
    IPC_CHANNELS.MEMORY_CAPTURE_SETTINGS_SET,
    (event, args: { workspaceId: string; settings: Partial<MemoryCaptureSettings> }) => {
      validateSender(event)
      const current = workspaceRepository.getSettings(args.workspaceId)
      const updated = {
        ...current,
        ...(args.settings.sessionCapture !== undefined && { memorySessionCapture: args.settings.sessionCapture }),
        ...(args.settings.commitCapture !== undefined && { memoryCommitCapture: args.settings.commitCapture }),
        ...(args.settings.docCapture !== undefined && { memoryDocCapture: args.settings.docCapture }),
        ...(args.settings.captureBlueprints !== undefined && { memoryCaptureBlueprints: args.settings.captureBlueprints }),
        ...(args.settings.capturePlans !== undefined && { memoryCapturePlans: args.settings.capturePlans }),
        ...(args.settings.captureGrill !== undefined && { memoryCaptureGrill: args.settings.captureGrill }),
        ...(args.settings.captureDocumentsOnAttach !== undefined && { memoryCaptureDocumentsOnAttach: args.settings.captureDocumentsOnAttach }),
        ...(args.settings.watcherGlobs !== undefined && { memoryWatcherGlobs: args.settings.watcherGlobs })
      }
      workspaceRepository.updateSettings(args.workspaceId, updated)

      // L3-FIX: Start/stop the doc watcher when docCapture changes for the
      // currently-watched workspace. Without this, toggling docCapture off in
      // settings only persists the flag — the watcher keeps running until the
      // next workspace switch.
      if (args.settings.docCapture !== undefined &&
          memoryDocWatcherService.activeWorkspace === args.workspaceId) {
        if (args.settings.docCapture === false) {
          memoryDocWatcherService.stop()
        } else {
          const ws = workspaceRepository.findById(args.workspaceId)
          if (ws?.repoPath) {
            memoryDocWatcherService.start(args.workspaceId, ws.repoPath, (updated as any).memoryWatcherGlobs)
          }
        }
      }
    }
  )

  // ── Embedding Status ──

  ipcMain.handle(
    IPC_CHANNELS.MEMORY_EMBEDDING_STATUS,
    (event, args?: { workspaceId?: string }) => {
      validateSender(event)
      const counts = args?.workspaceId
        ? memoryFactRepository.countByWorkspace(args.workspaceId)
        : { active: 0, superseded: 0, archived: 0, pendingEmbedding: 0 }
      return {
        isReady: localEmbeddingProvider.isReady,
        pendingCount: counts.pendingEmbedding,
        totalCount: counts.active + counts.superseded + counts.archived,
        modelName: localEmbeddingProvider.isReady ? localEmbeddingProvider.activeModelName : null
      }
    }
  )

  ipcMain.handle(
    IPC_CHANNELS.MEMORY_EMBEDDING_BACKFILL,
    async (event) => {
      validateSender(event)

      // Attempt full provider ready (auto-start oMLX, auto-load model) if offline
      if (!localEmbeddingProvider.isReady) {
        const ready = await localEmbeddingProvider.ensureEmbeddingReady()
        if (!ready) {
          const errorMsg = 'Embedding model could not be initialized. ' +
            'Please ensure oMLX is running with an embedding model downloaded and loaded.'
          // Send done+error so the renderer clears the spinner and shows the real message
          safeWindowSend(mainWindow, IPC_CHANNELS.MEMORY_EMBEDDING_PROGRESS, {
            processed: 0,
            total: 0,
            done: true,
            error: errorMsg
          })
          return { backfilled: 0, error: errorMsg }
        }
      }

      const count = await memoryEngineService.backfillAllPendingEmbeddings(
        (processed, total) => {
          safeWindowSend(mainWindow, IPC_CHANNELS.MEMORY_EMBEDDING_PROGRESS, {
            processed,
            total,
            done: false
          })
        }
      )

      // Send final done signal
      safeWindowSend(mainWindow, IPC_CHANNELS.MEMORY_EMBEDDING_PROGRESS, {
        processed: count,
        total: count,
        done: true
      })

      return { backfilled: count }
    }
  )

  // ── Feed + CLAUDE.md (retained from old system) ──

  ipcMain.handle(
    IPC_CHANNELS.MEMORY_FEED_DOCUMENT,
    async (event, args: { workspacePath: string; filePath: string; workspaceId?: string }) => {
      validateSender(event)
      if (!args.filePath) throw new Error('File path is required')
      const wsId = args.workspaceId ?? workspaceRepository.findByPath(args.workspacePath)?.id
      if (!wsId) throw new Error('Workspace not found')
      const created = await memoryExtractionService.extractFromDocument(
        wsId,
        args.workspacePath,
        args.filePath,
        (progress) => safeWindowSend(mainWindow, IPC_CHANNELS.MEMORY_FEED_PROGRESS, progress)
      )
      return { success: true, source: 'document' as const, memoriesCreated: created }
    }
  )

  ipcMain.handle(IPC_CHANNELS.MEMORY_FEED_CANCEL, (event) => {
    validateSender(event)
    memoryExtractionService.shutdown()
  })

  ipcMain.handle(
    IPC_CHANNELS.MEMORY_REGENERATE_CLAUDE_MD,
    async (event, args: { workspacePath: string; workspaceId: string }) => {
      validateSender(event)
      if (!args.workspacePath) throw new Error('Workspace path is required')
      if (!args.workspaceId) throw new Error('Workspace ID is required')
      let existing: string | null = null
      try {
        existing = readFileSync(join(args.workspacePath, 'CLAUDE.md'), 'utf-8')
      } catch { /* none */ }
      const result = await memoryExtractionService.regenerateClaudeMdAgentic(
        args.workspacePath,
        args.workspaceId,
        (progress) => safeWindowSend(mainWindow, IPC_CHANNELS.MEMORY_FEED_PROGRESS, progress)
      )
      return { ...result, existing }
    }
  )

  ipcMain.handle(IPC_CHANNELS.MEMORY_SELECT_DOCUMENT, async (event) => {
    validateSender(event)
    const result = await dialog.showOpenDialog(mainWindow, {
      title: 'Select a document to extract facts from',
      properties: ['openFile'],
      filters: [
        { name: 'Documents', extensions: ['md', 'txt', 'json', 'yaml', 'yml', 'toml'] },
        { name: 'All Files', extensions: ['*'] }
      ]
    })
    return result.canceled ? null : (result.filePaths[0] ?? null)
  })

  // ── Dedup Scan ──

  ipcMain.handle(
    IPC_CHANNELS.MEMORY_DEDUP_SCAN,
    (event, args: { workspaceId: string }) => {
      validateSender(event)
      return memoryEngineService.scanForDuplicates(args.workspaceId)
    }
  )

  ipcMain.handle(
    IPC_CHANNELS.MEMORY_DEDUP_AUTORESOLVE,
    (event, args: { workspaceId: string; minCosine?: number }) => {
      validateSender(event)
      const resolvedCount = memoryFactRepository.bulkAutoResolveDuplicates(args.minCosine ?? 0.95)
      return { resolvedCount }
    }
  )

  // ── Read CLAUDE.md ──

  ipcMain.handle(
    IPC_CHANNELS.MEMORY_READ_CLAUDE_MD,
    (event, args: { workspacePath: string }) => {
      validateSender(event)
      const filePath = join(args.workspacePath, 'CLAUDE.md')
      let content: string | null = null
      try {
        content = readFileSync(filePath, 'utf-8')
      } catch { /* file doesn't exist */ }
      return { content, path: filePath }
    }
  )

  // ── Consolidation ──

  ipcMain.handle(
    IPC_CHANNELS.MEMORY_CONSOLIDATE,
    async (event, args: { workspaceId: string }) => {
      validateSender(event)
      return memoryConsolidationService.runFullConsolidation(args.workspaceId)
    }
  )

  // ── Knowledge Graph ──

  ipcMain.handle(
    IPC_CHANNELS.MEMORY_GRAPH_GET,
    (event, args: { workspaceId: string }) => {
      validateSender(event)
      return buildMemoryGraph(args.workspaceId)
    }
  )

  // ── Document Ingestion ──

  // Select files via native dialog
  ipcMain.handle(IPC_CHANNELS.MEMORY_INGEST_SELECT_FILES, async (event) => {
    validateSender(event)
    const result = await dialog.showOpenDialog(mainWindow, {
      title: 'Select documents to ingest into memory',
      properties: ['openFile', 'multiSelections'],
      filters: [
        { name: 'Documents', extensions: ['md', 'txt', 'pdf', 'docx', 'rst', 'adoc'] },
        { name: 'Code', extensions: ['ts', 'tsx', 'js', 'jsx', 'py', 'go', 'rs', 'java', 'cs', 'rb'] },
        { name: 'Config', extensions: ['json', 'yaml', 'yml', 'toml', 'xml', 'sql'] },
        { name: 'All Files', extensions: ['*'] }
      ]
    })
    return result.canceled ? null : result.filePaths
  })

  // Select folder via native dialog
  ipcMain.handle(IPC_CHANNELS.MEMORY_INGEST_SELECT_FOLDER, async (event) => {
    validateSender(event)
    const result = await dialog.showOpenDialog(mainWindow, {
      title: 'Select a folder to ingest into memory',
      properties: ['openDirectory']
    })
    return result.canceled ? null : (result.filePaths[0] ?? null)
  })

  // Discover files in a folder (returns counts for confirmation)
  ipcMain.handle(
    IPC_CHANNELS.MEMORY_INGEST_DISCOVER,
    (event, args: { folderPath: string }) => {
      validateSender(event)
      return memoryIngestionService.discoverFiles(args.folderPath)
    }
  )

  // Start document ingestion (files or folder)
  ipcMain.handle(
    IPC_CHANNELS.MEMORY_INGEST_DOCUMENTS,
    async (event, args: { files: string[]; workspaceId: string; workspacePath: string }) => {
      validateSender(event)
      const { files, workspaceId, workspacePath } = args
      return memoryIngestionService.ingestFiles(
        files,
        workspaceId,
        workspacePath,
        (progress) => safeWindowSend(mainWindow, IPC_CHANNELS.MEMORY_INGEST_PROGRESS, progress)
      )
    }
  )

  // Cancel ingestion job
  ipcMain.handle(
    IPC_CHANNELS.MEMORY_INGEST_CANCEL,
    (event, args: { jobId: string }) => {
      validateSender(event)
      return memoryIngestionService.cancel(args.jobId)
    }
  )

  // ── Bootstrap Service ──

  ipcMain.handle(
    IPC_CHANNELS.MEMORY_BOOTSTRAP_START,
    async (
      event,
      args: {
        workspaceId: string
        workspacePath: string
        mode?: import('../../shared/types').BootstrapMode
      }
    ) => {
      validateSender(event)
      return memoryBootstrapService.startBootstrap(
        args.workspaceId,
        args.workspacePath,
        args.mode ?? 'full',
        (progress) => safeWindowSend(mainWindow, IPC_CHANNELS.MEMORY_BOOTSTRAP_PROGRESS, progress)
      )
    }
  )

  ipcMain.handle(
    IPC_CHANNELS.MEMORY_BOOTSTRAP_CANCEL,
    (event, args: { jobId: string }) => {
      validateSender(event)
      return memoryBootstrapService.cancel(args.jobId)
    }
  )
}

/**
 * memory-graph.ts — Pure edge-derivation logic for the memory knowledge graph.
 *
 * Extracted from memory.ipc.ts so the graph-building algorithm is:
 *   1. Unit-testable without repository or IPC mocks
 *   2. Workspace-scoped — contradiction/supersede edges are filtered against
 *      the node set, preventing cross-workspace edge leaks over IPC
 *
 * The IPC handler calls `buildMemoryGraph` which reads from repositories,
 * then delegates to `deriveGraphEdges` (pure, exported for tests).
 */

import type {
  MemoryFact,
  MemoryContradiction,
  MemoryGraphData,
  MemoryGraphEdge,
  MemoryGraphNode
} from '../../shared/types'
import { memoryFactRepository } from '../db/repositories/memory-fact.repository'
import { cosineSimilarity } from './memory-engine.service'

// ── Constants ─────────────────────────────────────────────────────────────────

/** Similarity threshold for graph edges — lower than dedup (0.90) to show related-but-distinct facts. */
export const GRAPH_SIMILARITY_THRESHOLD = 0.65
/** Max similarity edges per node to keep the graph readable. */
export const GRAPH_MAX_EDGES_PER_NODE = 3

// ── Pure edge derivation ──────────────────────────────────────────────────────

export interface DeriveGraphEdgesInput {
  facts: MemoryFact[]
  embeddings: Array<{ factId: string; embedding: Float32Array }>
  contradictions: MemoryContradiction[]
}

/**
 * Derive graph edges from facts, embeddings, and contradictions.
 *
 * Pure function — no side effects, no repository calls.
 * Edges are workspace-scoped: only edges where both source and target
 * exist in the node set are included.
 */
export function deriveGraphEdges(input: DeriveGraphEdgesInput): MemoryGraphData {
  const { facts, embeddings, contradictions } = input

  // Build node list
  const nodes: MemoryGraphNode[] = facts.map((f) => ({
    id: f.id,
    title: f.title,
    category: f.category,
    tier: f.tier,
    status: f.status,
    confidence: f.confidence
  }))

  const nodeIds = new Set(nodes.map((n) => n.id))
  const edges: MemoryGraphEdge[] = []
  const edgeSet = new Set<string>() // dedup "a-b" / "b-a"

  // 1. Similarity edges from embeddings
  const embeddingMap = new Map(embeddings.map(({ factId, embedding }) => [factId, embedding]))
  const embeddedIds = [...embeddingMap.keys()].filter((id) => nodeIds.has(id))

  for (let i = 0; i < embeddedIds.length; i++) {
    const idA = embeddedIds[i]
    const vecA = embeddingMap.get(idA)!
    const scored: Array<{ id: string; sim: number }> = []

    for (let j = i + 1; j < embeddedIds.length; j++) {
      const idB = embeddedIds[j]
      const sim = cosineSimilarity(vecA, embeddingMap.get(idB)!)
      if (sim >= GRAPH_SIMILARITY_THRESHOLD) {
        scored.push({ id: idB, sim })
      }
    }

    // Keep top-N per node
    scored.sort((a, b) => b.sim - a.sim)
    for (const { id: idB, sim } of scored.slice(0, GRAPH_MAX_EDGES_PER_NODE)) {
      const key = [idA, idB].sort().join('-')
      if (!edgeSet.has(key)) {
        edgeSet.add(key)
        edges.push({ source: idA, target: idB, kind: 'similarity', weight: sim })
      }
    }
  }

  // 2. Supersede edges — scoped to nodeIds
  for (const fact of facts) {
    if (fact.supersededBy && nodeIds.has(fact.supersededBy)) {
      const key = [fact.id, fact.supersededBy].sort().join('-')
      if (!edgeSet.has(key)) {
        edgeSet.add(key)
        edges.push({ source: fact.id, target: fact.supersededBy, kind: 'superseded', weight: 1.0 })
      }
    }
  }

  // 3. Contradiction edges — scoped to nodeIds
  for (const c of contradictions) {
    if (!nodeIds.has(c.oldFactId) || !nodeIds.has(c.newFactId)) continue
    const key = [c.oldFactId, c.newFactId].sort().join('-')
    if (!edgeSet.has(key)) {
      edgeSet.add(key)
      edges.push({ source: c.oldFactId, target: c.newFactId, kind: 'contradiction', weight: 1.0 })
    }
  }

  return { nodes, edges }
}

// ── Orchestrator (reads from repositories) ────────────────────────────────────

/**
 * Build a knowledge graph from the workspace's memory facts.
 * Reads from repositories, delegates to `deriveGraphEdges` for pure logic.
 */
export function buildMemoryGraph(workspaceId: string): MemoryGraphData {
  const allFacts = memoryFactRepository.findAllByWorkspace(workspaceId)
  const withEmbeddings = memoryFactRepository.findWithEmbeddings(workspaceId)
  const contradictions = memoryFactRepository.findContradictions()

  return deriveGraphEdges({
    facts: allFacts,
    embeddings: withEmbeddings.map(({ fact, embedding }) => ({
      factId: fact.id,
      embedding
    })),
    contradictions
  })
}

/**
 * memory-ingestion.service.ts — Orchestrates manual document ingestion into memory.
 *
 * Flow:
 *   Select files/folder → discovery + filter → format-specific text extraction
 *   → structure-aware chunking → per-chunk Haiku fact extraction (serialized queue)
 *   → writeFact (embed → dedup → classify) → per-doc progress → summary
 *
 * Incremental re-ingestion: uses memory_doc_state (workspace_id, file_path, content_hash)
 * to skip unchanged files on re-ingest.
 *
 * Singleton: memoryIngestionService
 */

import { readdirSync, statSync } from 'node:fs'
import { createHash } from 'node:crypto'
import { join, extname, relative } from 'node:path'
import log from 'electron-log'
import type { IngestionProgress } from '../../shared/types'
import { readDocument, isSupportedExtension } from './document-reader'
import { chunkDocument, detectStrategy } from './document-chunker'
import { memoryExtractionService } from './memory-extraction.service'
import { memoryFactRepository } from '../db/repositories/memory-fact.repository'

const ingestionLog = log.scope('memory-ingestion')

// Re-export for convenience
export type { IngestionProgress }
export type IngestionProgressCallback = (progress: IngestionProgress) => void

// ── Configuration ────────────────────────────────────────────────────────────

/** Directories to skip during folder walk */
const IGNORE_DIRS = new Set([
  'node_modules', '.git', 'dist', 'out', 'build', 'coverage',
  '.next', '.nuxt', '.cache', '__pycache__', '.tox', '.venv',
  'vendor', 'target', 'bin', 'obj', '.gradle', '.idea',
  '.vscode', '.vs'
])

/** Max files per folder ingestion (guard against accidental huge repo scans) */
const MAX_FILES_PER_FOLDER = 200

// ── Discovery result ─────────────────────────────────────────────────────────

export interface DiscoveryResult {
  files: string[]
  counts: Record<string, number>
  truncated: boolean
}

// ── Service ──────────────────────────────────────────────────────────────────

class MemoryIngestionService {
  private activeJobs = new Map<string, AbortController>()
  private jobCounter = 0

  /**
   * Discover files in a directory, applying filters and the file cap.
   * Returns the list + counts by extension for pre-start confirmation.
   */
  discoverFiles(dirPath: string): DiscoveryResult {
    const files: string[] = []
    const counts: Record<string, number> = {}

    this.walkDir(dirPath, files, 0)

    // Count by extension
    for (const f of files) {
      const ext = extname(f).toLowerCase() || '(no ext)'
      counts[ext] = (counts[ext] ?? 0) + 1
    }

    const truncated = files.length > MAX_FILES_PER_FOLDER
    return {
      files: files.slice(0, MAX_FILES_PER_FOLDER),
      counts,
      truncated
    }
  }

  /**
   * Start ingesting a list of files. Returns a jobId for tracking/cancellation.
   *
   * @param files - Absolute paths to files to ingest
   * @param workspaceId - Workspace to associate facts with
   * @param workspacePath - Workspace root for relative path computation
   * @param onProgress - Progress callback (called on each state change)
   */
  async ingestFiles(
    files: string[],
    workspaceId: string,
    workspacePath: string,
    onProgress?: IngestionProgressCallback
  ): Promise<{ jobId: string; factsCreated: number }> {
    const jobId = `ingest-${++this.jobCounter}-${Date.now()}`
    const controller = new AbortController()
    this.activeJobs.set(jobId, controller)

    let totalFacts = 0

    const emit = (partial: Partial<IngestionProgress> & { docIndex: number; docName: string }): void => {
      onProgress?.({
        jobId,
        docCount: files.length,
        chunkIndex: 0,
        chunkCount: 0,
        factsCreated: totalFacts,
        docStatus: 'queued',
        message: '',
        jobStatus: 'running',
        ...partial
      })
    }

    try {
      for (let i = 0; i < files.length; i++) {
        if (controller.signal.aborted) {
          emit({
            docIndex: i + 1,
            docName: files[i].split('/').pop() ?? '',
            jobStatus: 'cancelled',
            message: 'Ingestion cancelled'
          })
          break
        }

        const filePath = files[i]
        const docName = relative(workspacePath, filePath) || (filePath.split('/').pop() ?? filePath)

        try {
          const facts = await this.ingestSingleFile(
            filePath,
            workspaceId,
            workspacePath,
            docName,
            i,
            files.length,
            jobId,
            controller.signal,
            emit
          )
          totalFacts += facts
        } catch (err) {
          const msg = err instanceof Error ? err.message : String(err)
          ingestionLog.warn(`[ingestFiles] Error on ${docName}: ${msg}`)
          emit({
            docIndex: i + 1,
            docName,
            docStatus: 'error',
            message: `Error: ${msg}`
          })
        }
      }

      const jobStatus = controller.signal.aborted ? 'cancelled' : 'done'
      emit({
        docIndex: files.length,
        docName: '',
        jobStatus,
        docStatus: 'done',
        message: `Ingestion ${jobStatus}: ${totalFacts} memories created from ${files.length} files`
      })

      return { jobId, factsCreated: totalFacts }
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err)
      ingestionLog.error(`[ingestFiles] Job ${jobId} failed:`, err)
      emit({
        docIndex: 0,
        docName: '',
        jobStatus: 'error',
        docStatus: 'error',
        message: `Job failed: ${msg}`
      })
      return { jobId, factsCreated: totalFacts }
    } finally {
      this.activeJobs.delete(jobId)
    }
  }

  /**
   * Cancel an active ingestion job.
   */
  cancel(jobId: string): boolean {
    const controller = this.activeJobs.get(jobId)
    if (controller) {
      controller.abort()
      ingestionLog.info(`[cancel] Job ${jobId} cancelled`)
      return true
    }
    return false
  }

  /**
   * Cancel all active ingestion jobs.
   */
  cancelAll(): void {
    for (const [jobId, controller] of this.activeJobs) {
      controller.abort()
      ingestionLog.info(`[cancelAll] Job ${jobId} cancelled`)
    }
    this.activeJobs.clear()
  }

  /**
   * Check if any ingestion job is currently running.
   */
  get isRunning(): boolean {
    return this.activeJobs.size > 0
  }

  // ── Private ────────────────────────────────────────────────────────────

  private async ingestSingleFile(
    filePath: string,
    workspaceId: string,
    workspacePath: string,
    docName: string,
    fileIndex: number,
    _fileCount: number,
    _jobId: string,
    signal: AbortSignal,
    emit: (partial: Partial<IngestionProgress> & { docIndex: number; docName: string }) => void
  ): Promise<number> {
    const docIndex = fileIndex + 1

    // 1. Check hash gate — skip unchanged files
    emit({ docIndex, docName, docStatus: 'reading', message: `Reading ${docName}...` })

    const readResult = await readDocument(filePath)
    if (!readResult.ok) {
      emit({
        docIndex,
        docName,
        docStatus: readResult.reason === 'binary_skip' ? 'skipped' : 'error',
        message: readResult.message
      })
      return 0
    }

    // Image files skip chunking — extraction is handled differently
    if (readResult.isImage) {
      emit({ docIndex, docName, docStatus: 'skipped', message: 'Image files — use vision extraction (not yet supported in batch)' })
      return 0
    }

    // Compute content hash
    const contentHash = createHash('sha256').update(readResult.content).digest('hex')

    // Check if already extracted with same hash
    const existingState = memoryFactRepository.getDocState(workspaceId, filePath)
    if (existingState && existingState.contentHash === contentHash) {
      emit({ docIndex, docName, docStatus: 'skipped', message: 'Unchanged since last ingestion' })
      return 0
    }

    // 2. Chunk the content
    if (signal.aborted) return 0

    emit({ docIndex, docName, docStatus: 'chunking', message: `Chunking ${docName}...` })

    const strategy = detectStrategy(filePath)
    const chunks = chunkDocument(readResult.content, strategy, docName)

    if (chunks.length === 0) {
      emit({ docIndex, docName, docStatus: 'skipped', message: 'No content to extract' })
      return 0
    }

    // 3. Extract facts from each chunk
    let factsFromDoc = 0

    for (let ci = 0; ci < chunks.length; ci++) {
      if (signal.aborted) break

      const chunk = chunks[ci]
      emit({
        docIndex,
        docName,
        docStatus: 'extracting',
        chunkIndex: ci + 1,
        chunkCount: chunks.length,
        message: `Extracting chunk ${ci + 1}/${chunks.length}${chunk.breadcrumb ? ` (${chunk.breadcrumb})` : ''}`
      })

      try {
        // Prepend breadcrumb context to chunk content for better fact quality
        const contentWithContext = chunk.breadcrumb
          ? `[Context: ${chunk.breadcrumb}]\n\n${chunk.content}`
          : chunk.content

        const created = await memoryExtractionService.extractFromContent(
          workspaceId,
          workspacePath,
          docName,
          contentWithContext,
          undefined,
          { sourceType: 'document', tags: ['ingested'] }
        )
        factsFromDoc += created
      } catch (err) {
        ingestionLog.warn(`[ingestSingleFile] Chunk ${ci + 1} extraction failed for ${docName}:`, err)
      }
    }

    // 4. Update doc state hash
    memoryFactRepository.upsertDocState(workspaceId, filePath, contentHash)

    emit({
      docIndex,
      docName,
      docStatus: 'done',
      chunkIndex: chunks.length,
      chunkCount: chunks.length,
      message: `Done — ${factsFromDoc} memories from ${chunks.length} chunks`
    })

    ingestionLog.info(`[ingestSingleFile] ${docName}: ${factsFromDoc} facts from ${chunks.length} chunks`)
    return factsFromDoc
  }

  /**
   * Recursive directory walk with ignore list.
   */
  private walkDir(dirPath: string, files: string[], depth: number): void {
    if (depth > 10) return // prevent infinite recursion
    if (files.length >= MAX_FILES_PER_FOLDER * 2) return // stop early, will be truncated

    let entries: string[]
    try {
      entries = readdirSync(dirPath)
    } catch {
      return // permission denied, etc.
    }

    for (const entry of entries) {
      const entryLower = entry.toLowerCase()
      if (entry.startsWith('.') && IGNORE_DIRS.has(entryLower)) continue
      if (IGNORE_DIRS.has(entryLower)) continue

      const fullPath = join(dirPath, entry)
      let stat
      try {
        stat = statSync(fullPath)
      } catch {
        continue
      }

      if (stat.isDirectory()) {
        this.walkDir(fullPath, files, depth + 1)
      } else if (stat.isFile() && isSupportedExtension(fullPath)) {
        files.push(fullPath)
      }
    }
  }
}

export const memoryIngestionService = new MemoryIngestionService()

/**
 * document-reader.ts — Format-specific text extraction for document ingestion.
 *
 * Routes files to the appropriate reader based on extension:
 * - .md, .txt, code files → readFileSync (zero deps)
 * - .pdf → pdf-parse (pure JS)
 * - .docx → mammoth extractRawText (pure JS)
 * - images (.png/.jpg/.webp/.gif) → placeholder (vision extraction handled upstream)
 * - Other binaries → skipped
 *
 * All functions are pure/stateless — no singletons, no side effects.
 */

import { readFileSync, statSync } from 'node:fs'
import { extname } from 'node:path'
import log from 'electron-log'

const docReaderLog = log.scope('document-reader')

// ── Size caps ────────────────────────────────────────────────────────────────

/** Max file size for PDF/DOCX (20 MB) */
const MAX_DOC_SIZE_BYTES = 20 * 1024 * 1024

/** Max file size for images (8 MB) */
const MAX_IMAGE_SIZE_BYTES = 8 * 1024 * 1024

/** Min content length to bother extracting */
const MIN_CONTENT_CHARS = 20

// ── Extension sets ───────────────────────────────────────────────────────────

/** Text-readable code/config extensions (read as UTF-8) */
const TEXT_EXTENSIONS = new Set([
  '.md', '.txt', '.rst', '.adoc',
  '.ts', '.tsx', '.js', '.jsx', '.mjs', '.cjs',
  '.py', '.pyi', '.rb', '.go', '.rs', '.java', '.kt', '.kts',
  '.c', '.cpp', '.h', '.hpp', '.cs', '.swift',
  '.sh', '.bash', '.zsh', '.fish', '.ps1',
  '.json', '.yaml', '.yml', '.toml', '.ini', '.cfg', '.env',
  '.xml', '.html', '.htm', '.css', '.scss', '.less',
  '.sql', '.graphql', '.gql', '.prisma',
  '.dockerfile', '.makefile', '.cmake',
  '.csv', '.tsv', '.log'
])

/** Image extensions supported for vision-based extraction */
const IMAGE_EXTENSIONS = new Set(['.png', '.jpg', '.jpeg', '.webp', '.gif'])

/** Binary extensions that are always skipped */
const SKIP_EXTENSIONS = new Set([
  '.zip', '.tar', '.gz', '.bz2', '.7z', '.rar',
  '.dmg', '.exe', '.msi', '.deb', '.rpm',
  '.mp3', '.mp4', '.wav', '.avi', '.mov', '.mkv',
  '.ico', '.bmp', '.tiff', '.svg',
  '.woff', '.woff2', '.ttf', '.eot', '.otf',
  '.sqlite', '.db', '.dat', '.bin',
  '.psd', '.ai', '.sketch', '.fig',
  '.doc', // .doc (legacy Word) is not supported — only .docx
  '.xls', '.xlsx', '.ppt', '.pptx'
])

// ── Result type ──────────────────────────────────────────────────────────────

export type DocumentReadResult =
  | { ok: true; content: string; format: 'text' | 'pdf' | 'docx' | 'image'; isImage: boolean }
  | { ok: false; reason: 'too_large' | 'too_short' | 'binary_skip' | 'not_found' | 'read_error'; message: string }

// ── Public API ───────────────────────────────────────────────────────────────

/**
 * Read a file and extract its text content based on format.
 *
 * For images, returns the raw file content as base64 with `isImage: true` —
 * callers use this to send to Claude Vision for fact extraction.
 */
export async function readDocument(filePath: string): Promise<DocumentReadResult> {
  const ext = extname(filePath).toLowerCase()

  // Handle extensionless files (Dockerfile, Makefile, etc.)
  const basename = filePath.split('/').pop() ?? ''
  const isKnownExtensionless = ['dockerfile', 'makefile', 'rakefile', 'gemfile', 'procfile'].includes(
    basename.toLowerCase()
  )

  // 1. Check if binary/skip
  if (SKIP_EXTENSIONS.has(ext)) {
    return { ok: false, reason: 'binary_skip', message: `Unsupported binary format: ${ext}` }
  }

  // 2. Check file size
  let fileSize: number
  try {
    fileSize = statSync(filePath).size
  } catch {
    return { ok: false, reason: 'not_found', message: `File not found or inaccessible: ${filePath}` }
  }

  // 3. Route by format
  if (ext === '.pdf') {
    if (fileSize > MAX_DOC_SIZE_BYTES) {
      return { ok: false, reason: 'too_large', message: `PDF exceeds ${MAX_DOC_SIZE_BYTES / 1024 / 1024}MB limit` }
    }
    return readPdf(filePath)
  }

  if (ext === '.docx') {
    if (fileSize > MAX_DOC_SIZE_BYTES) {
      return { ok: false, reason: 'too_large', message: `DOCX exceeds ${MAX_DOC_SIZE_BYTES / 1024 / 1024}MB limit` }
    }
    return readDocx(filePath)
  }

  if (IMAGE_EXTENSIONS.has(ext)) {
    if (fileSize > MAX_IMAGE_SIZE_BYTES) {
      return { ok: false, reason: 'too_large', message: `Image exceeds ${MAX_IMAGE_SIZE_BYTES / 1024 / 1024}MB limit` }
    }
    return readImage(filePath)
  }

  if (TEXT_EXTENSIONS.has(ext) || isKnownExtensionless) {
    return readTextFile(filePath)
  }

  // Unknown extension — try as text, fail gracefully
  return readTextFile(filePath)
}

/**
 * Check if a file extension is supported for reading.
 */
export function isSupportedExtension(filePath: string): boolean {
  const ext = extname(filePath).toLowerCase()
  const basename = filePath.split('/').pop() ?? ''
  const isKnownExtensionless = ['dockerfile', 'makefile', 'rakefile', 'gemfile', 'procfile'].includes(
    basename.toLowerCase()
  )
  return (
    TEXT_EXTENSIONS.has(ext) ||
    IMAGE_EXTENSIONS.has(ext) ||
    ext === '.pdf' ||
    ext === '.docx' ||
    isKnownExtensionless
  )
}

/**
 * Check if a file is an image (for vision-based extraction).
 */
export function isImageFile(filePath: string): boolean {
  return IMAGE_EXTENSIONS.has(extname(filePath).toLowerCase())
}

// ── Internal readers ─────────────────────────────────────────────────────────

function readTextFile(filePath: string): DocumentReadResult {
  try {
    const content = readFileSync(filePath, 'utf-8')
    if (content.length < MIN_CONTENT_CHARS) {
      return { ok: false, reason: 'too_short', message: `File content too short (${content.length} chars)` }
    }
    return { ok: true, content, format: 'text', isImage: false }
  } catch (err) {
    return {
      ok: false,
      reason: 'read_error',
      message: `Failed to read as text: ${err instanceof Error ? err.message : String(err)}`
    }
  }
}

async function readPdf(filePath: string): Promise<DocumentReadResult> {
  try {
    // Dynamic import to keep cold-start fast when not ingesting PDFs
    const { PDFParse } = await import('pdf-parse')
    const buffer = readFileSync(filePath)
    const parser = new PDFParse({ data: buffer })
    const result = await parser.getText()
    const text = result.text?.trim()

    if (!text || text.length < MIN_CONTENT_CHARS) {
      return { ok: false, reason: 'too_short', message: `PDF extracted text too short (${text?.length ?? 0} chars)` }
    }

    return { ok: true, content: text, format: 'pdf', isImage: false }
  } catch (err) {
    docReaderLog.warn(`[readPdf] Failed to parse ${filePath}:`, err)
    return {
      ok: false,
      reason: 'read_error',
      message: `PDF parse failed: ${err instanceof Error ? err.message : String(err)}`
    }
  }
}

async function readDocx(filePath: string): Promise<DocumentReadResult> {
  try {
    const mammoth = await import('mammoth')
    const buffer = readFileSync(filePath)
    const result = await mammoth.extractRawText({ buffer })
    const text = result.value?.trim()

    if (!text || text.length < MIN_CONTENT_CHARS) {
      return { ok: false, reason: 'too_short', message: `DOCX extracted text too short (${text?.length ?? 0} chars)` }
    }

    return { ok: true, content: text, format: 'docx', isImage: false }
  } catch (err) {
    docReaderLog.warn(`[readDocx] Failed to parse ${filePath}:`, err)
    return {
      ok: false,
      reason: 'read_error',
      message: `DOCX parse failed: ${err instanceof Error ? err.message : String(err)}`
    }
  }
}

function readImage(filePath: string): DocumentReadResult {
  try {
    const buffer = readFileSync(filePath)
    const base64 = buffer.toString('base64')
    const ext = extname(filePath).toLowerCase()
    const mimeMap: Record<string, string> = {
      '.png': 'image/png',
      '.jpg': 'image/jpeg',
      '.jpeg': 'image/jpeg',
      '.webp': 'image/webp',
      '.gif': 'image/gif'
    }
    const mime = mimeMap[ext] ?? 'image/png'
    // Return base64 data URL — callers send this to Claude Vision
    return { ok: true, content: `data:${mime};base64,${base64}`, format: 'image', isImage: true }
  } catch (err) {
    return {
      ok: false,
      reason: 'read_error',
      message: `Image read failed: ${err instanceof Error ? err.message : String(err)}`
    }
  }
}

/**
 * document-chunker.ts — Structure-aware text chunking for document ingestion.
 *
 * Splits document content into chunks suitable for LLM fact extraction.
 * Three strategies based on content type:
 *
 * 1. **Markdown** — split on heading boundaries (H1→H2→H3), each chunk carries
 *    its heading breadcrumb ("Doc > Section > Subsection") for context.
 * 2. **Code files** — split on top-level declaration boundaries (blank-line
 *    heuristic), ~10K chars/chunk.
 * 3. **Plain text / PDF / DOCX** — paragraph-based packing to ~10K chars,
 *    10% overlap to avoid boundary fact loss.
 *
 * All functions are pure — no I/O, no side effects.
 */

// ── Configuration ────────────────────────────────────────────────────────────

/** Target chunk size in characters */
const TARGET_CHUNK_CHARS = 10_000

/** Max chunks per document (caps at ~250K chars total) */
const MAX_CHUNKS_PER_DOC = 25

/** Overlap fraction for plain-text chunking */
const OVERLAP_FRACTION = 0.1

// ── Types ────────────────────────────────────────────────────────────────────

export interface DocumentChunk {
  /** Chunk index (0-based) within the document */
  index: number
  /** Total chunks for this document */
  total: number
  /** The chunk text content */
  content: string
  /** Heading breadcrumb for markdown chunks (e.g. "Doc > API > Authentication") */
  breadcrumb?: string
}

export type ChunkStrategy = 'markdown' | 'code' | 'plain'

// ── Public API ───────────────────────────────────────────────────────────────

/**
 * Chunk a document's text content using the appropriate strategy.
 *
 * @param content - Full text content of the document
 * @param strategy - Chunking strategy to use
 * @param docName - Document name for breadcrumb context (optional)
 * @returns Array of chunks, capped at MAX_CHUNKS_PER_DOC
 */
export function chunkDocument(
  content: string,
  strategy: ChunkStrategy,
  docName?: string
): DocumentChunk[] {
  if (!content || content.length === 0) return []

  let chunks: DocumentChunk[]

  switch (strategy) {
    case 'markdown':
      chunks = chunkMarkdown(content, docName)
      break
    case 'code':
      chunks = chunkCode(content)
      break
    case 'plain':
      chunks = chunkPlainText(content)
      break
  }

  // Cap total chunks
  if (chunks.length > MAX_CHUNKS_PER_DOC) {
    chunks = chunks.slice(0, MAX_CHUNKS_PER_DOC)
    // Update totals on capped chunks
    for (const chunk of chunks) {
      chunk.total = MAX_CHUNKS_PER_DOC
    }
  }

  // Update totals
  const total = chunks.length
  for (const chunk of chunks) {
    chunk.total = total
  }

  return chunks
}

/**
 * Detect the appropriate chunking strategy for a file.
 */
export function detectStrategy(filePath: string): ChunkStrategy {
  const ext = filePath.split('.').pop()?.toLowerCase() ?? ''

  if (['md', 'mdx', 'markdown'].includes(ext)) return 'markdown'

  if ([
    'ts', 'tsx', 'js', 'jsx', 'mjs', 'cjs',
    'py', 'pyi', 'rb', 'go', 'rs', 'java', 'kt', 'kts',
    'c', 'cpp', 'h', 'hpp', 'cs', 'swift',
    'sh', 'bash', 'zsh',
    'sql', 'graphql', 'gql', 'prisma'
  ].includes(ext)) return 'code'

  return 'plain'
}

// ── Markdown chunking ────────────────────────────────────────────────────────

interface HeadingSection {
  level: number
  title: string
  startLine: number
  content: string
}

/**
 * Split markdown on heading boundaries with breadcrumb context.
 * Each chunk carries its heading path (e.g. "Doc > API > Authentication").
 */
function chunkMarkdown(content: string, docName?: string): DocumentChunk[] {
  const lines = content.split('\n')
  const sections: HeadingSection[] = []
  let currentSection: HeadingSection | null = null
  const contentLines: string[] = []

  for (let i = 0; i < lines.length; i++) {
    const headingMatch = lines[i].match(/^(#{1,6})\s+(.+)/)

    if (headingMatch) {
      // Flush previous section
      if (currentSection) {
        currentSection.content = contentLines.join('\n').trim()
        if (currentSection.content.length > 0) {
          sections.push(currentSection)
        }
        contentLines.length = 0
      }

      currentSection = {
        level: headingMatch[1].length,
        title: headingMatch[2].trim(),
        startLine: i,
        content: ''
      }
    } else {
      contentLines.push(lines[i])
    }
  }

  // Flush last section
  if (currentSection) {
    currentSection.content = contentLines.join('\n').trim()
    if (currentSection.content.length > 0) {
      sections.push(currentSection)
    }
  }

  // If no headings found, treat as plain text
  if (sections.length === 0) {
    return chunkPlainText(content)
  }

  // Build breadcrumbs and pack sections into chunks
  const chunks: DocumentChunk[] = []
  const headingStack: string[] = docName ? [docName] : []

  let currentChunkContent = ''
  let currentBreadcrumb = docName ?? ''

  for (const section of sections) {
    // Update heading stack
    while (headingStack.length > section.level) {
      headingStack.pop()
    }
    // Pad stack if we jumped levels
    while (headingStack.length < section.level) {
      headingStack.push('')
    }
    headingStack[section.level - 1] = section.title
    // Ensure stack doesn't extend beyond current level
    headingStack.length = section.level

    const breadcrumb = (docName ? [docName, ...headingStack] : headingStack)
      .filter(Boolean)
      .join(' > ')

    const sectionText = `## ${section.title}\n\n${section.content}`

    // If adding this section would exceed target, flush current chunk
    if (currentChunkContent.length + sectionText.length > TARGET_CHUNK_CHARS && currentChunkContent.length > 0) {
      chunks.push({
        index: chunks.length,
        total: 0, // set later
        content: currentChunkContent.trim(),
        breadcrumb: currentBreadcrumb
      })
      currentChunkContent = ''
    }

    // If a single section exceeds target, split it into sub-chunks
    if (sectionText.length > TARGET_CHUNK_CHARS) {
      // Flush any accumulated content first
      if (currentChunkContent.length > 0) {
        chunks.push({
          index: chunks.length,
          total: 0,
          content: currentChunkContent.trim(),
          breadcrumb: currentBreadcrumb
        })
        currentChunkContent = ''
      }

      const subChunks = splitLongText(sectionText, TARGET_CHUNK_CHARS)
      for (const sub of subChunks) {
        chunks.push({
          index: chunks.length,
          total: 0,
          content: sub.trim(),
          breadcrumb
        })
      }
    } else {
      currentChunkContent += (currentChunkContent ? '\n\n' : '') + sectionText
      currentBreadcrumb = breadcrumb
    }
  }

  // Flush remaining
  if (currentChunkContent.trim().length > 0) {
    chunks.push({
      index: chunks.length,
      total: 0,
      content: currentChunkContent.trim(),
      breadcrumb: currentBreadcrumb
    })
  }

  return chunks
}

// ── Code chunking ────────────────────────────────────────────────────────────

/**
 * Split code files on blank-line boundaries between top-level declarations.
 * Two or more consecutive blank lines signal a declaration boundary.
 */
function chunkCode(content: string): DocumentChunk[] {
  // Split on double blank lines (common declaration separator)
  const blocks = content.split(/\n{3,}/)

  const chunks: DocumentChunk[] = []
  let currentChunk = ''

  for (const block of blocks) {
    if (currentChunk.length + block.length + 2 > TARGET_CHUNK_CHARS && currentChunk.length > 0) {
      chunks.push({
        index: chunks.length,
        total: 0,
        content: currentChunk.trim()
      })
      currentChunk = ''
    }

    // If a single block exceeds target, split it
    if (block.length > TARGET_CHUNK_CHARS) {
      if (currentChunk.length > 0) {
        chunks.push({
          index: chunks.length,
          total: 0,
          content: currentChunk.trim()
        })
        currentChunk = ''
      }

      const subChunks = splitLongText(block, TARGET_CHUNK_CHARS)
      for (const sub of subChunks) {
        chunks.push({
          index: chunks.length,
          total: 0,
          content: sub.trim()
        })
      }
    } else {
      currentChunk += (currentChunk ? '\n\n\n' : '') + block
    }
  }

  if (currentChunk.trim().length > 0) {
    chunks.push({
      index: chunks.length,
      total: 0,
      content: currentChunk.trim()
    })
  }

  // If everything fit in one chunk, just return it
  if (chunks.length === 0 && content.trim().length > 0) {
    chunks.push({ index: 0, total: 1, content: content.trim() })
  }

  return chunks
}

// ── Plain text chunking ──────────────────────────────────────────────────────

/**
 * Split plain text on paragraph boundaries with overlap.
 * Paragraphs are separated by one or more blank lines.
 */
function chunkPlainText(content: string): DocumentChunk[] {
  const paragraphs = content.split(/\n\s*\n/).filter((p) => p.trim().length > 0)

  if (paragraphs.length === 0) return []

  // If content fits in one chunk, return as-is
  if (content.length <= TARGET_CHUNK_CHARS) {
    return [{ index: 0, total: 1, content: content.trim() }]
  }

  const chunks: DocumentChunk[] = []
  let currentChunk = ''
  let overlapBuffer = '' // trailing paragraphs from previous chunk for overlap

  for (let i = 0; i < paragraphs.length; i++) {
    const para = paragraphs[i].trim()

    if (currentChunk.length + para.length + 2 > TARGET_CHUNK_CHARS && currentChunk.length > 0) {
      chunks.push({
        index: chunks.length,
        total: 0,
        content: currentChunk.trim()
      })

      // Build overlap from tail of current chunk
      const overlapChars = Math.floor(TARGET_CHUNK_CHARS * OVERLAP_FRACTION)
      overlapBuffer = currentChunk.slice(-overlapChars)
      currentChunk = overlapBuffer
    }

    currentChunk += (currentChunk ? '\n\n' : '') + para
  }

  if (currentChunk.trim().length > 0) {
    chunks.push({
      index: chunks.length,
      total: 0,
      content: currentChunk.trim()
    })
  }

  return chunks
}

// ── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Split a long text into roughly equal parts, breaking on line boundaries.
 */
function splitLongText(text: string, maxChars: number): string[] {
  const lines = text.split('\n')
  const parts: string[] = []
  let current = ''

  for (const line of lines) {
    if (current.length + line.length + 1 > maxChars && current.length > 0) {
      parts.push(current)
      current = ''
    }
    current += (current ? '\n' : '') + line
  }

  if (current.length > 0) {
    parts.push(current)
  }

  return parts
}

/**
 * memory-bootstrap.service.ts — Orchestrates project knowledge bootstrapping.
 *
 * Two modes:
 *   1. "Feed Brain" (full/incremental): deterministic 6-phase pipeline
 *      Preflight → Docs → Stack → Architecture → History → Structure → Finalize
 *   2. "Deep Scan" (deep-scan): Phases 0–2 + agent-driven exploration via Claude CLI
 *
 * Every fact tagged ['bootstrap', <phase>]; the write pipeline's cosine-dedup
 * makes re-runs confirm (not duplicate).
 *
 * Singleton: memoryBootstrapService
 */

import { readFileSync, existsSync, readdirSync, statSync } from 'node:fs'
import { execSync } from 'node:child_process'
import { join, relative, basename } from 'node:path'
import { createHash } from 'node:crypto'
import log from 'electron-log'
import type { BootstrapProgress, BootstrapMode, BootstrapPhaseLabel } from '../../shared/types'
import { memoryExtractionService } from './memory-extraction.service'
import { memoryEngineService } from './memory-engine.service'
import { memoryFactRepository } from '../db/repositories/memory-fact.repository'
import { codeGraphService } from './code-graph.service'
import { localEmbeddingProvider } from './local-embedding.provider'
import { workspaceRepository } from '../db/repositories'
import { readDocument } from './document-reader'
import { chunkDocument, detectStrategy } from './document-chunker'
import { runAgenticClaude } from './agentic-claude-runner'
import { MCP_TOOLS } from '../../shared/constants'

const bsLog = log.scope('memory-bootstrap')

// ── Configuration ────────────────────────────────────────────────────────────

/** Directories to skip during discovery */
const IGNORE_DIRS = new Set([
  'node_modules', '.git', 'dist', 'out', 'build', 'coverage',
  '.next', '.nuxt', '.cache', '__pycache__', '.tox', '.venv',
  'vendor', 'target', 'bin', 'obj', '.gradle', '.idea',
  '.vscode', '.vs'
])

/** Max files to read per phase for safety */
const MAX_ARCHITECTURE_FILES = 40
const MAX_CHUNKS_PER_FILE = 25
const MAX_HOTSPOT_FACTS = 15
const MAX_COCHANGE_RESULTS = 15
const MAX_COMMIT_SUBJECTS = 50
const DEEP_SCAN_TIMEOUT_MS = 10 * 60 * 1000 // 10 minutes

/** Doc patterns for Phase 1 */
const DOC_PATTERNS = [
  'README.md', 'README.txt', 'README.rst', 'README',
  'CLAUDE.md', 'AGENTS.md',
  'ARCHITECTURE.md', 'ARCHITECTURE.txt',
  'CONTRIBUTING.md', 'CONTRIBUTING.txt',
  'CHANGELOG.md', 'CHANGELOG.txt',
  'SECURITY.md', 'LICENSE.md'
]

/** Globs for doc directories */
const DOC_DIRS = ['docs', 'doc', 'documentation', '.github']

/** Manifest files for Phase 2 */
const MANIFEST_FILES = [
  'package.json', 'tsconfig.json', 'tsconfig.base.json',
  'requirements.txt', 'pyproject.toml', 'setup.py', 'setup.cfg',
  'go.mod', 'go.sum',
  'Cargo.toml',
  'Gemfile',
