import { ipcMain } from 'electron'
import log from 'electron-log/main'
import { IPC_CHANNELS } from '../../shared/constants'
import { chatAgentService } from '../services'
import { validateSender } from './validate-sender'
import { requireObject, requireString, optionalString } from './validate-args'

/**
 * SDK Control IPC handlers — bridges renderer requests to session management.
 *
 * Previously used @anthropic-ai/claude-agent-sdk functions. Now uses CLI
 * equivalents where available, or returns graceful errors for unimplemented ops.
 *
 * ─── Active handlers (wired to renderer) ───────────────────────────────────
 *
 *   ELICITATION_RESPONSE       — agent MCP elicitation flow
 *   SDK_ELICITATION_RESPONSE   — elicitation.service enriched flow
 *   CHAT_ASK_USER_RESPOND      — ask_user response routing
 *   SDK_STOP_TASK              — stop a SubAgent (not available without SDK)
 *   SDK_SUPPORTED_MODELS       — list available models (returns static list)
 *   SDK_LIST_SUBAGENTS         — enumerate SubAgents (not available without SDK)
 *   SDK_GET_SUBAGENT_MESSAGES  — fetch a SubAgent transcript (not available)
 *   SDK_FORK_SESSION           — branch a conversation
 */
export function registerSdkControlIpc(): void {
  // ── Elicitation ────────────────────────────────────────────────────────

  // Agent MCP elicitation response — forwarded to the agent's
  // active session via an event emitter.
  ipcMain.handle(IPC_CHANNELS.ELICITATION_RESPONSE, async (event, args: unknown) => {
    validateSender(event)
    const channel = IPC_CHANNELS.ELICITATION_RESPONSE
    const obj = requireObject(args, channel)
    const action = requireString(obj, 'action', channel)
    if (action !== 'accept' && action !== 'decline' && action !== 'cancel') {
      throw new Error(`${channel}: field 'action' must be 'accept' | 'decline' | 'cancel'`)
    }
    const content =
      obj.content === undefined
        ? undefined
        : (() => {
            if (
              obj.content === null ||
              typeof obj.content !== 'object' ||
              Array.isArray(obj.content)
            ) {
              throw new Error(`${channel}: field 'content' must be an object when provided`)
            }
            return obj.content as Record<string, unknown>
          })()
    chatAgentService.emit('elicitationResponse', { action, content })
  })

  // Enriched elicitation response — routed through ElicitationService
  ipcMain.handle(IPC_CHANNELS.SDK_ELICITATION_RESPONSE, async (event, args: unknown) => {
    validateSender(event)
    const channel = IPC_CHANNELS.SDK_ELICITATION_RESPONSE
    const obj = requireObject(args, channel)
    const requestId = requireString(obj, 'requestId', channel)
    const action = requireString(obj, 'action', channel)
    if (action !== 'accept' && action !== 'decline' && action !== 'cancel') {
      throw new Error(`${channel}: field 'action' must be 'accept' | 'decline' | 'cancel'`)
    }
    const content =
      obj.content === undefined
        ? undefined
        : (() => {
            if (
              obj.content === null ||
              typeof obj.content !== 'object' ||
              Array.isArray(obj.content)
            ) {
              throw new Error(`${channel}: field 'content' must be an object when provided`)
            }
            return obj.content as Record<string, unknown>
          })()
    const { elicitationService } = await import('../services/elicitation.service')
    elicitationService.resolveElicitation(requestId, { action, content })
  })

  // ── Active Query controls ───────────────────────────────────────────────

  // Stop task — not available without SDK Query reference
  ipcMain.handle(IPC_CHANNELS.SDK_STOP_TASK, async (event, args: unknown) => {
    validateSender(event)
    const channel = IPC_CHANNELS.SDK_STOP_TASK
    const obj = requireObject(args, channel)
    requireString(obj, 'taskId', channel)
    // SDK Query object no longer available — CLI abort handles full session stop
    log.warn(`[${channel}] Individual task stop not available without SDK Query`)
    return { success: false, error: 'Task stop requires SDK (removed)' }
  })

  // Supported-models list — return via CLI or static config
  ipcMain.handle(IPC_CHANNELS.SDK_SUPPORTED_MODELS, async (event) => {
    validateSender(event)
    // Return static model list — the CLI doesn't expose supportedModels()
    return ['claude-sonnet-4-6', 'claude-sonnet-4-20250514', 'claude-opus-4-0', 'claude-haiku-3-5']
  })

  // ── SubAgent inspection — not available without SDK ────────────────────

  ipcMain.handle(IPC_CHANNELS.SDK_LIST_SUBAGENTS, async (event, args: unknown) => {
    validateSender(event)
    const channel = IPC_CHANNELS.SDK_LIST_SUBAGENTS
    const obj = requireObject(args, channel)
    requireString(obj, 'sessionId', channel)
    log.info(`[${channel}] SubAgent listing not available — SDK removed`)
    return []
  })

  ipcMain.handle(IPC_CHANNELS.SDK_GET_SUBAGENT_MESSAGES, async (event, args: unknown) => {
    validateSender(event)
    const channel = IPC_CHANNELS.SDK_GET_SUBAGENT_MESSAGES
    const obj = requireObject(args, channel)
    requireString(obj, 'sessionId', channel)
    requireString(obj, 'subagentId', channel)
    log.info(`[${channel}] SubAgent messages not available — SDK removed`)
    return []
  })

  // ── SDK Diagnostics ──────────────────────────────────────────────────────

  ipcMain.handle(IPC_CHANNELS.SDK_RESOLVE_SETTINGS, async (event) => {
    validateSender(event)
    return { success: false, error: 'resolveSettings not available — SDK removed' }
  })

  // ── ask_user response ──────────────────────────────────────────────────────

  ipcMain.handle(IPC_CHANNELS.CHAT_ASK_USER_RESPOND, async (event, args: unknown) => {
    validateSender(event)
    const channel = IPC_CHANNELS.CHAT_ASK_USER_RESPOND
    const obj = requireObject(args, channel)
    const requestId = requireString(obj, 'requestId', channel)
    const response = requireString(obj, 'response', channel)
    chatAgentService.respondToAskUser(requestId, response)
  })

  // ── Session branching ────────────────────────────────────────────────────

  ipcMain.handle(IPC_CHANNELS.SDK_FORK_SESSION, async (event, args: unknown) => {
    validateSender(event)
    const channel = IPC_CHANNELS.SDK_FORK_SESSION
    const obj = requireObject(args, channel)
    const sessionId = requireString(obj, 'sessionId', channel)
    optionalString(obj, 'upToMessageId', channel)
    // CLI supports --fork-session with --resume
    try {
      const { execFileSync } = await import('node:child_process')
      const cliArgs = [
        '--resume',
        sessionId,
        '--fork-session',
        '-p',
        '--print',
        'forked',
        '--output-format',
        'json'
      ]
      const result = execFileSync('claude', cliArgs, { encoding: 'utf-8', timeout: 10_000 })
      return JSON.parse(result.trim())
    } catch (err) {
      log.warn(`[${channel}] Fork failed for ${sessionId}:`, err)
      return { success: false, error: 'Session fork failed' }
    }
  })
}

import type { BrowserWindow } from 'electron'
import { ipcMain } from 'electron'
import { statSync } from 'node:fs'
import log from 'electron-log/main'
import { IPC_CHANNELS } from '../../shared/constants'
import { vectorSearchService } from '../services/vector-search.service'
import { validateSender } from './validate-sender'
import { safeWindowSend } from './safe-send'
import { workspaceRepository, codeChunkRepository } from '../db/repositories'
import { convertTagsToChunks } from '../services/tag-to-chunk-adapter'
import type { IndexingState } from '../../shared/types'

export function registerIndexingIpc(mainWindow: BrowserWindow): void {
  // Forward indexing progress events to the renderer
  vectorSearchService.on('progress', (state: IndexingState) => {
    safeWindowSend(mainWindow, IPC_CHANNELS.INDEXING_PROGRESS, state)
  })

  ipcMain.handle(IPC_CHANNELS.INDEXING_START, async (event, args: { workspaceId: string }) => {
    validateSender(event)

    const state = vectorSearchService.getIndexingState(args.workspaceId)
    if (state.status !== 'idle' && state.status !== 'complete' && state.status !== 'error') {
      throw new Error('Indexing is already in progress')
    }

    // Get workspace path
    const workspace = workspaceRepository.findById(args.workspaceId)
    if (!workspace) throw new Error('Workspace not found')

    const settings = workspaceRepository.getSettings(workspace.id)

    // Get repomap tags via tree-sitter (dynamic import for lazy loading)
    const { getTags, initParser } =
      (await import('repomap-mcp/dist/tags.js')) as typeof import('repomap-mcp/dist/tags.js')
    const { findSrcFiles } =
      (await import('repomap-mcp/dist/file-discovery.js')) as typeof import('repomap-mcp/dist/file-discovery.js')

    await initParser()

    log.info(`[Indexing] Scanning workspace: ${workspace.repoPath}`)
    const files = findSrcFiles(workspace.repoPath)
    log.info(`[Indexing] Found ${files.length} source files`)

    // Load existing file mtimes from persisted chunks for incremental skip
    const existingMtimes = codeChunkRepository.getFileMtimes(args.workspaceId)

    const allTags: Array<{
      relFname: string
      fname: string
      line: number
      name: string
      kind: 'def' | 'ref'
    }> = []

    let skippedFiles = 0
    const currentFiles = new Set<string>()

    for (const file of files) {
      const relPath = file.replace(workspace.repoPath + '/', '')
      currentFiles.add(relPath)

      try {
        const stat = statSync(file)
        const existingMtime = existingMtimes.get(relPath)

        // Skip files that haven't changed since last index
        if (existingMtime && stat.mtimeMs === existingMtime) {
          skippedFiles++
          continue
        }

        const tags = await getTags(file, relPath, null, false)
        allTags.push(...tags)
      } catch (err) {
        log.warn(`[Indexing] Failed to get tags for ${relPath}:`, err)
      }
    }

    // Delete stale chunks for files that no longer exist
    for (const [existingFile] of existingMtimes) {
      if (!currentFiles.has(existingFile)) {
        codeChunkRepository.deleteByFile(args.workspaceId, existingFile)
      }
    }

    log.info(
      `[Indexing] Extracted ${allTags.length} tags from ${files.length} files (${skippedFiles} unchanged, skipped)`
    )

    // Convert to RawChunks
    const { chunks, fileContents } = convertTagsToChunks(allTags, workspace.repoPath)

    log.info(`[Indexing] Starting indexing pipeline with ${chunks.length} chunks`)

    // Start indexing (async — fires progress events via EventEmitter)
    const indexingOptions = {
      generateDescriptions: !!settings.semanticSearchDescriptions,
      descriptionModel: (settings.descriptionModel as string) || 'claude-haiku-4-5-20251001'
    }
    vectorSearchService
      .indexProject(args.workspaceId, workspace.repoPath, chunks, fileContents, indexingOptions)
      .catch((err) => {
        log.error('[Indexing] Pipeline failed:', err)
      })
  })

  ipcMain.handle(IPC_CHANNELS.INDEXING_PAUSE, (event, args: { workspaceId: string }) => {
    validateSender(event)
    vectorSearchService.pauseIndexing(args.workspaceId)
  })

  ipcMain.handle(IPC_CHANNELS.INDEXING_RESUME, (event, args: { workspaceId: string }) => {
    validateSender(event)
    vectorSearchService.resumeIndexing(args.workspaceId)
  })

  ipcMain.handle(IPC_CHANNELS.INDEXING_CANCEL, (event, args: { workspaceId: string }) => {
    validateSender(event)
    vectorSearchService.cancelIndexing(args.workspaceId)
  })

  ipcMain.handle(IPC_CHANNELS.INDEXING_GET_STATUS, (event, args: { workspaceId: string }) => {
    validateSender(event)
    return vectorSearchService.getIndexingState(args.workspaceId)
  })

  ipcMain.handle(
    IPC_CHANNELS.SEMANTIC_SEARCH_QUERY,
    async (event, args: { workspaceId: string; query: string; nResults?: number }) => {
      validateSender(event)
      return vectorSearchService.search(args.workspaceId, args.query, {
        nResults: args.nResults ?? 5
      })
    }
  )

  ipcMain.handle(
    IPC_CHANNELS.INDEXING_LOAD_PERSISTED,
    async (event, args: { workspaceId: string }) => {
      validateSender(event)
      const hasPersisted = vectorSearchService.hasPersistedIndex(args.workspaceId)
      if (hasPersisted) {
        const { symbolCount } = await vectorSearchService.loadPersistedIndex(args.workspaceId)
        return { loaded: true, status: 'complete', symbolCount }
      }
      return { loaded: false, status: 'idle' }
    }
  )
}

/**
 * Permission IPC — handles cross-workspace permission responses.
 *
 * When a background workspace session needs user input (elicitation, askQuestion,
 * MPA approval), the renderer shows a toast. The user's response flows back here
 * and is routed to the correct session.
 */

import { ipcMain } from 'electron'
import { IPC_CHANNELS } from '../../shared/constants'
import log from 'electron-log/main'
import { chatAgentService } from '../services'
import { mpaOrchestrationService } from '../services/mpa-orchestration.service'
import { validateSender } from './validate-sender'
import { requireObject, requireString } from './validate-args'

const permLog = log.scope('permission-ipc')

export function registerPermissionIpc(): void {
  ipcMain.handle(IPC_CHANNELS.PERMISSION_RESPONSE, async (event, rawArgs: unknown) => {
    validateSender(event)
    const ch = IPC_CHANNELS.PERMISSION_RESPONSE

    try {
      // IPC-02: Runtime validation — matches pattern used by 27+ other handlers
      const args = requireObject(rawArgs, ch)
      const workspaceId = requireString(args, 'workspaceId', ch)
      const type = requireString(args, 'type', ch)

      if (!['elicitation', 'askQuestion', 'mpaApproval', 'toolPermission'].includes(type)) {
        throw new Error(
          `${ch}: type must be one of: elicitation, askQuestion, mpaApproval, toolPermission`
        )
      }

      const response = args.response

      permLog.info(`[permission] Response received — workspace=${workspaceId} type=${type}`)

      switch (type) {
        case 'elicitation': {
          // Route elicitation response to the workspace's session
          const session = chatAgentService.getSessionForWorkspace(workspaceId)
          if (session) {
            session.emit('elicitationResponse', response)
          } else {
            permLog.warn(
              `[permission] No session for workspace ${workspaceId} — elicitation response dropped`
            )
          }
          break
        }

        case 'askQuestion': {
          // Route askQuestion response — extract requestId and answer from response
          const resp = requireObject(response, `${ch}.response`) as {
            requestId?: string
            answer?: string
          }
          if (resp.requestId && resp.answer) {
            chatAgentService.respondToAskUserForWorkspace(
              workspaceId,
              resp.requestId as string,
              resp.answer as string
            )
          } else {
            permLog.warn(`[permission] askQuestion response missing requestId or answer`)
          }
          break
        }

        case 'mpaApproval': {
          // Route MPA gate response
          const resp = requireObject(response, `${ch}.response`) as {
            approved: boolean
            feedback?: string
            runId?: string
          }
          if (typeof resp.approved !== 'boolean') {
            throw new Error(`${ch}: field 'approved' must be a boolean`)
          }
          const runId = resp.runId ?? mpaOrchestrationService.currentRunId
          if (runId) {
            mpaOrchestrationService.respondToGate(runId, resp.approved, resp.feedback)
          } else {
            permLog.warn(`[permission] MPA approval response has no runId`)
          }
          break
        }

        case 'toolPermission': {
          // Route tool permission response — approve/deny from toast UI
          const approved = response === 'approve'
          // Extract requestId from the payload (stashed when the toast was created)
          const payload = (args as Record<string, unknown>).payload as
            | { requestId?: string }
            | undefined
          const requestId = payload?.requestId
          if (requestId) {
            chatAgentService.respondToPermissionForWorkspace(workspaceId, requestId, approved)
          } else {
            permLog.warn(`[permission] toolPermission response missing requestId`)
          }
          break
        }

        default:
          permLog.warn(`[permission] Unknown permission type: ${type}`)
      }
    } catch (err) {
      permLog.error('[permission] Handler error:', err)
      throw err
    }
  })
}

import path from 'node:path'
import { ipcMain, BrowserWindow } from 'electron'
import { IPC_CHANNELS } from '../../shared/constants'
import type { ActivationProgressEvent } from '../../shared/types'
import { workspaceDeployService } from '../services/workspace-deploy.service'
import { validateSender } from './validate-sender'
import { safeWindowSend } from './safe-send'

/** Allowed file patterns for workspace read/write — relative to workspace root */
const ALLOWED_FILE_PATTERNS = ['.claude/', 'CLAUDE.md', 'skills/']

/**
 * Validates that a file path is within the workspace boundary and matches
 * allowed patterns. Prevents arbitrary file read/write via IPC.
 */
function validateWorkspaceFilePath(filePath: string): void {
  const resolved = path.resolve(filePath)

  // The file must be within a directory that contains one of the allowed patterns
  const hasAllowedPattern = ALLOWED_FILE_PATTERNS.some((pattern) => {
    const sep = path.sep
    return resolved.includes(`${sep}${pattern.replace(/\//g, sep)}`)
  })

  if (!hasAllowedPattern) {
    throw new Error(
      `Access denied: file path must be within allowed workspace directories (.claude/, skills/, or CLAUDE.md). Got: ${filePath}`
    )
  }
}

export function registerWorkspaceDeployIpc(): void {
  ipcMain.handle(IPC_CHANNELS.WORKSPACE_SCAN_CLAUDE, (event, args: { workspacePath: string }) => {
    validateSender(event)
    return workspaceDeployService.scanWorkspaceClaude(args.workspacePath)
  })

  ipcMain.handle(
    IPC_CHANNELS.WORKSPACE_ACTIVATE_AGENTS,
    async (event, args: { workspacePath: string }) => {
      validateSender(event)
      const win = BrowserWindow.fromWebContents(event.sender)

      const onProgress = (progressEvent: ActivationProgressEvent): void => {
        if (win) safeWindowSend(win, IPC_CHANNELS.WORKSPACE_ACTIVATION_PROGRESS, progressEvent)
      }

      return workspaceDeployService.activateAgents(args.workspacePath, onProgress)
    }
  )

  ipcMain.handle(IPC_CHANNELS.WORKSPACE_CANCEL_ACTIVATION, (event) => {
    validateSender(event)
    workspaceDeployService.shutdown()
  })

  ipcMain.handle(
    IPC_CHANNELS.WORKSPACE_CLEAN_ACTIVATION,
    (event, args: { workspacePath: string; removeClaudeMd?: boolean }) => {
      validateSender(event)
      workspaceDeployService.cleanActivation(args.workspacePath, args.removeClaudeMd)
    }
  )

  ipcMain.handle(IPC_CHANNELS.WORKSPACE_READ_FILE, (event, args: { filePath: string }) => {
    validateSender(event)
    validateWorkspaceFilePath(args.filePath)
    return workspaceDeployService.readWorkspaceFile(args.filePath)
  })

  ipcMain.handle(
    IPC_CHANNELS.WORKSPACE_WRITE_FILE,
    (event, args: { filePath: string; content: string }) => {
      validateSender(event)
      validateWorkspaceFilePath(args.filePath)
      workspaceDeployService.writeWorkspaceFile(args.filePath, args.content)
    }
  )

  ipcMain.handle(IPC_CHANNELS.WORKSPACE_SCAN_SKILLS, (event, args: { workspacePath: string }) => {
    validateSender(event)
    return workspaceDeployService.scanWorkspaceSkills(args.workspacePath)
  })

  ipcMain.handle(IPC_CHANNELS.WORKSPACE_SCAN_AGENTS, (event, args: { workspacePath: string }) => {
    validateSender(event)
    return workspaceDeployService.scanWorkspaceAgents(args.workspacePath)
  })

  ipcMain.handle(
