import { readFileSync, existsSync } from 'node:fs'
import { ipcMain } from 'electron'
import { IPC_CHANNELS } from '../../shared/constants'
import { conversationSpecialistRepository } from '../db/repositories'
import { getDatabase } from '../db/index'
import { validateSender } from './validate-sender'
import { requireObject, requireString, optionalBoolean } from './validate-args'

export function registerConversationSpecialistIpc(): void {
  ipcMain.handle(IPC_CHANNELS.CONV_SPECIALIST_LIST, async (event, rawArgs: unknown) => {
    validateSender(event)
    const ch = IPC_CHANNELS.CONV_SPECIALIST_LIST
    const args = requireObject(rawArgs, ch)
    const conversationId = requireString(args, 'conversationId', ch)

    return conversationSpecialistRepository.findByConversation(conversationId)
  })

  ipcMain.handle(IPC_CHANNELS.CONV_SPECIALIST_UPSERT, async (event, rawArgs: unknown) => {
    validateSender(event)
    const ch = IPC_CHANNELS.CONV_SPECIALIST_UPSERT
    const args = requireObject(rawArgs, ch)
    const conversationId = requireString(args, 'conversationId', ch)
    const specialistId = requireString(args, 'specialistId', ch)
    const isActive = optionalBoolean(args, 'isActive', ch)

    conversationSpecialistRepository.upsert(conversationId, specialistId, {
      isActive
    })
  })

  ipcMain.handle(IPC_CHANNELS.CONV_SPECIALIST_REMOVE, async (event, rawArgs: unknown) => {
    validateSender(event)
    const ch = IPC_CHANNELS.CONV_SPECIALIST_REMOVE
    const args = requireObject(rawArgs, ch)
    const conversationId = requireString(args, 'conversationId', ch)
    const specialistId = requireString(args, 'specialistId', ch)

    conversationSpecialistRepository.remove(conversationId, specialistId)
  })

  ipcMain.handle(IPC_CHANNELS.CONV_SPECIALIST_RESET, async (event, rawArgs: unknown) => {
    validateSender(event)
    const ch = IPC_CHANNELS.CONV_SPECIALIST_RESET
    const args = requireObject(rawArgs, ch)
    const conversationId = requireString(args, 'conversationId', ch)

    // ATOM-02: Wrap in transaction so removeAll + initFromWorkspaceDefaults
    // are atomic — if init fails, removeAll is rolled back.
    const db = getDatabase()
    db.transaction(() => {
      conversationSpecialistRepository.removeAll(conversationId)
      conversationSpecialistRepository.initFromWorkspaceDefaults(conversationId)
    })()
  })

  ipcMain.handle(IPC_CHANNELS.CONV_SPECIALIST_ESTIMATE, async (event, rawArgs: unknown) => {
    validateSender(event)
    const ch = IPC_CHANNELS.CONV_SPECIALIST_ESTIMATE
    const args = requireObject(rawArgs, ch)
    const conversationId = requireString(args, 'conversationId', ch)

    // Get active specialists for this conversation
    const overrides = conversationSpecialistRepository.findByConversation(conversationId)
    const activeWithSkills = overrides.filter((o) => o.isActive)

    // Calculate real token estimates from actual skill file content
    const { specialistRepository } = await import('../db/repositories')
    const estimates = activeWithSkills.map((override) => {
      const specialist = specialistRepository.findById(override.specialistId)
      const skills = specialist ? specialistRepository.getSkills(override.specialistId) : []
      const activeSkills = skills

      // Estimate tokens from specialist prompt (~3.5 chars per token)
      const promptTokens = specialist?.prompt ? Math.ceil(specialist.prompt.length / 3.5) : 0

      let skillTokens = 0
      const skillBreakdown: { name: string; tokens: number }[] = []
      for (const skill of activeSkills) {
        try {
          if (skill.filePath && existsSync(skill.filePath)) {
            const content = readFileSync(skill.filePath, 'utf-8')
            const tokens = Math.ceil(content.length / 3.5)
            skillTokens += tokens
            skillBreakdown.push({ name: skill.name, tokens })
          } else {
            skillTokens += 500
            skillBreakdown.push({ name: skill.name, tokens: 500 })
          }
        } catch {
          // File not found — use fallback estimate
          skillTokens += 500
          skillBreakdown.push({ name: skill.name, tokens: 500 })
        }
      }

      return {
        specialistId: override.specialistId,
        displayName: specialist?.displayName ?? 'Unknown',
        skillCount: activeSkills.length,
        promptTokens,
        skillTokens,
        skillBreakdown,
        estimatedTokens: promptTokens + skillTokens
      }
    })

    return estimates
  })
}

import { ipcMain, type BrowserWindow } from 'electron'
import { chatAgentService } from '../services'
import { IPC_CHANNELS } from '../../shared/constants'
import type { AgentStatus } from '../../shared/types'
import { agentIpcLogger } from '../logger'
import { validateSender } from './validate-sender'
import { safeWindowSend } from './safe-send'
import { notificationService } from '../services/notification.service'

const log = agentIpcLogger

export function registerAgentIpc(mainWindow: BrowserWindow): void {
  ipcMain.handle(IPC_CHANNELS.AGENT_GET_STATUSES, async (event) => {
    validateSender(event)

    return [chatAgentService.getStatus()]
  })

  ipcMain.handle(IPC_CHANNELS.AGENT_STOP_ALL, async (event) => {
    validateSender(event)

    log.info('Stopping all agents...')

    const results: string[] = []

    // Stop ALL workspace sessions (not just active)
    try {
      const sessionCount = chatAgentService.activeSessionCount
      if (sessionCount > 0) {
        await chatAgentService.stopAll()
        results.push(`${sessionCount} session(s) stopped`)
      }
    } catch (error) {
      log.error('Failed to stop sessions:', error)
      results.push(`Session stop failed: ${(error as Error).message}`)
    }

    // Broadcast updated statuses to renderer
    safeWindowSend(mainWindow, IPC_CHANNELS.AGENT_STATUS_UPDATE, chatAgentService.getStatus())

    log.info('Stop all results:', results)
    return results
  })

  // Strategy M: Cache efficiency metrics for dashboard
  ipcMain.handle(IPC_CHANNELS.AGENT_CACHE_EFFICIENCY, async (event) => {
    validateSender(event)
    return chatAgentService.getCacheEfficiency()
  })

  // Forward status updates from active workspace session
  chatAgentService.on('statusUpdate', (status: AgentStatus) => {
    // Tag with workspaceId for multi-workspace routing
    const workspaceId = chatAgentService.activeWorkspaceId
    safeWindowSend(mainWindow, IPC_CHANNELS.AGENT_STATUS_UPDATE, {
      ...status,
      workspaceId: workspaceId ?? undefined
    })
  })

  // Forward workspace-tagged status updates (from any workspace, not just active)
  // Single merged listener — forwards IPC AND detects completion/failure transitions
  const previousStatuses = new Map<string, string>()

  chatAgentService.on('statusUpdate:ws', (workspaceId: string, status: AgentStatus) => {
    // Forward to renderer
    safeWindowSend(mainWindow, IPC_CHANNELS.AGENT_STATUS_UPDATE, {
      ...status,
      workspaceId
    })

    // Track for completion detection
    const prevStatus = previousStatuses.get(workspaceId)
    previousStatuses.set(workspaceId, status.status)

    // Only send completion notifications for background workspaces
    if (workspaceId === chatAgentService.activeWorkspaceId) return

    // Detect transitions to completed or failed
    if (
      (status.status === 'completed' || status.status === 'failed') &&
      prevStatus !== status.status
    ) {
      // Resolve workspace name
      let workspaceName = workspaceId.slice(0, 8)
      try {
        // eslint-disable-next-line @typescript-eslint/no-require-imports -- lazy load avoids db/repositories circular dependency
        const { workspaceRepository } = require('../db/repositories')
        const ws = workspaceRepository.findById(workspaceId)
        if (ws) workspaceName = ws.name
      } catch {
        /* non-fatal */
      }

      notificationService.dispatch({
        workspaceId,
        workspaceName,
        service: 'chat',
        status: status.status as 'completed' | 'failed',
        summary:
          status.status === 'completed'
            ? 'Chat session completed'
            : `Chat session failed: ${status.currentTask ?? 'unknown error'}`,
        targetPage: 'chat'
      })
    }
  })
}

import { ipcMain, type BrowserWindow } from 'electron'
import { IPC_CHANNELS } from '../../shared/constants'
import { mainLogger } from '../logger'
import { chatAgentService } from '../services'
import { chatStreamService } from '../services/chat-stream.service'
import { validateSender } from './validate-sender'
import { safeWindowSend } from './safe-send'
import { workspaceRepository } from '../db/repositories'

const log = mainLogger

export function registerAgentLifecycleIpc(mainWindow: BrowserWindow): void {
  let startingWorkspace: string | null = null // guard against double-start (React strict mode)

  /**
   * AGENT_START — start or re-activate a session for a workspace.
   *
   * Accepts either a workspacePath string (backward compat) or an object
   * { workspaceId, workspacePath }. Does NOT kill sessions for other workspaces.
   */
  ipcMain.handle(
    IPC_CHANNELS.AGENT_START,
    async (event, args: string | { workspaceId: string; workspacePath: string }) => {
      validateSender(event)

      // Normalize args — support both old (string) and new (object) shapes
      let workspaceId: string
      let workspacePath: string

      if (typeof args === 'string') {
        // Backward compat: resolve workspaceId from path
        workspacePath = args
        const workspace = workspaceRepository.findByPath(workspacePath)
        workspaceId = workspace?.id ?? workspacePath
      } else {
        workspaceId = args.workspaceId
        workspacePath = args.workspacePath
      }

      if (!workspacePath || workspacePath.trim().length === 0) {
        throw new Error('Invalid workspace path')
      }

      // Skip if already starting for this workspace
      if (startingWorkspace === workspacePath) {
        log.info('Agent already starting for:', workspacePath, '— skipping')
        return
      }

      // Already running for this workspace — re-send ready event so the renderer
      // transitions out of 'starting' state (fixes Home → re-select same workspace,
      // HMR double-mounts, and auto-open refreshes that would otherwise abort an active stream)
      if (chatAgentService.hasSessionForWorkspace(workspaceId)) {
        log.info(
          'Chat agent already running for workspace:',
          workspaceId,
          '— re-sending ready (role=' + chatAgentService.getActiveRole() + ')'
        )
        // Force-reset any stuck streaming state from the previous workspace
        chatStreamService.forceResetIfStuck()
        chatAgentService.setActiveWorkspace(workspaceId)
        safeWindowSend(mainWindow, IPC_CHANNELS.AGENT_READY, { workspaceId })
        return
      }

      startingWorkspace = workspacePath
      try {
        // Force-reset any stuck streaming state before starting a new workspace session
        chatStreamService.forceResetIfStuck()
        // Start a NEW session for this workspace (does NOT kill existing sessions)
        await chatAgentService.startForWorkspace(workspaceId, workspacePath)
        log.info(
          'Chat agent ready for workspace:',
          workspaceId,
          '— role=' + chatAgentService.getActiveRole()
        )
        safeWindowSend(mainWindow, IPC_CHANNELS.AGENT_READY, { workspaceId })
      } catch (error) {
        log.error('Failed to start services:', error)
        throw error
      } finally {
        startingWorkspace = null
      }
    }
  )

  /**
   * WORKSPACE_ALL_STATUSES — get statuses of all running workspace sessions.
   */
  ipcMain.handle(IPC_CHANNELS.WORKSPACE_ALL_STATUSES, async (event) => {
    validateSender(event)

    const statuses: Record<string, unknown> = {}
    for (const [wsId, status] of chatAgentService.getAllStatuses()) {
      statuses[wsId] = status
    }
    // TODO Phase 3: merge grill, audit, MPA statuses
    return statuses
  })
}

import { ipcMain } from 'electron'
import log from 'electron-log'
import { IPC_CHANNELS } from '../../shared/constants'
import { repoService } from '../services/repo.service'
import { githubService } from '../services/github.service'
import { workspaceRepository, conversationRepository, messageRepository } from '../db/repositories'
import { runOneShotClaude } from '../services/one-shot-claude'
import { modelConfigService } from '../services/model-config.service'
import { DEFAULT_MODEL_CONFIG } from '../../shared/constants'
import { validateSender } from './validate-sender'
import { requireObject, requireString, optionalString } from './validate-args'

const logger = log.scope('CodeChangesIpc')

/**
 * Enqueue commit-based memory extraction if gated settings allow it.
 * Extracted to keep the REPO_COMMIT_FILES handler below complexity threshold.
 */
async function maybeEnqueueCommitExtraction(
  workspaceId: string,
  repoPath: string,
  headBefore: string | null,
  commitHash: string | undefined
): Promise<void> {
  if (!headBefore || !commitHash) return

  const settings = workspaceRepository.getSettings(workspaceId) as Record<string, unknown>
  if (settings.memoryCommitCapture === false) return

  const { memoryExtractionService } = await import('../services/memory-extraction.service')
  memoryExtractionService.enqueueCommitExtraction({
    workspaceId,
    workspacePath: repoPath,
    startSha: headBefore,
    endSha: commitHash
  })
}

/** Resolve workspace repoPath from conversationId */
function resolveRepoPath(conversationId: string): { repoPath: string; workspaceId: string } {
  const conversation = conversationRepository.findById(conversationId)
  if (!conversation) throw new Error('Conversation not found')

  const workspace = workspaceRepository.findById(conversation.workspaceId)
  if (!workspace) throw new Error('Workspace not found')

  return { repoPath: workspace.repoPath, workspaceId: workspace.id }
}

export function registerCodeChangesIpc(): void {
  // Get detailed file status for uncommitted changes
  ipcMain.handle(IPC_CHANNELS.REPO_GET_FILE_DETAILS, async (event, rawArgs: unknown) => {
    validateSender(event)
    const args = requireObject(rawArgs, IPC_CHANNELS.REPO_GET_FILE_DETAILS)
    const conversationId = requireString(args, 'conversationId', IPC_CHANNELS.REPO_GET_FILE_DETAILS)

    const { repoPath } = resolveRepoPath(conversationId)
    return repoService.getUncommittedFileDetails(repoPath)
  })

  // Get old/new content for side-by-side diff
  ipcMain.handle(IPC_CHANNELS.REPO_GET_FILE_DIFF, async (event, rawArgs: unknown) => {
    validateSender(event)
    const args = requireObject(rawArgs, IPC_CHANNELS.REPO_GET_FILE_DIFF)
    const conversationId = requireString(args, 'conversationId', IPC_CHANNELS.REPO_GET_FILE_DIFF)
    const filePath = requireString(args, 'filePath', IPC_CHANNELS.REPO_GET_FILE_DIFF)

    const { repoPath } = resolveRepoPath(conversationId)
    return repoService.getFileDiff(repoPath, filePath)
  })

  // Stage specific files and commit
  ipcMain.handle(IPC_CHANNELS.REPO_COMMIT_FILES, async (event, rawArgs: unknown) => {
    validateSender(event)
    const args = requireObject(rawArgs, IPC_CHANNELS.REPO_COMMIT_FILES)
    const conversationId = requireString(args, 'conversationId', IPC_CHANNELS.REPO_COMMIT_FILES)
    const message = requireString(args, 'message', IPC_CHANNELS.REPO_COMMIT_FILES)
    const filePaths = args.filePaths as string[]
    if (!Array.isArray(filePaths) || filePaths.length === 0) {
      throw new Error(`${IPC_CHANNELS.REPO_COMMIT_FILES}: filePaths must be a non-empty array`)
    }

    const { repoPath, workspaceId } = resolveRepoPath(conversationId)

    // Capture HEAD before commit for memory extraction
    const headBefore = await repoService.getHeadSha(repoPath).catch(() => null)

    const result = await repoService.commitFiles(repoPath, filePaths, message)

    // G3-FIX: Wire commit extraction, gated by memoryCommitCapture setting
    maybeEnqueueCommitExtraction(workspaceId, repoPath, headBefore, result.commitHash).catch(
      (err) => logger.debug('Commit memory extraction failed (non-fatal):', err)
    )

    return result
  })

  // Push current branch to origin
  ipcMain.handle(IPC_CHANNELS.REPO_PUSH, async (event, rawArgs: unknown) => {
    validateSender(event)
    const args = requireObject(rawArgs, IPC_CHANNELS.REPO_PUSH)
    const conversationId = requireString(args, 'conversationId', IPC_CHANNELS.REPO_PUSH)

    const { repoPath } = resolveRepoPath(conversationId)
    return repoService.push(repoPath)
  })

  // Get push status (commits ahead, branch, hasRemote)
  ipcMain.handle(IPC_CHANNELS.REPO_GET_PUSH_STATUS, async (event, rawArgs: unknown) => {
    validateSender(event)
    const args = requireObject(rawArgs, IPC_CHANNELS.REPO_GET_PUSH_STATUS)
    const conversationId = requireString(args, 'conversationId', IPC_CHANNELS.REPO_GET_PUSH_STATUS)

    const { repoPath } = resolveRepoPath(conversationId)
    return repoService.getPushStatus(repoPath)
  })

  // Generate commit message from conversation context + changed files
  ipcMain.handle(IPC_CHANNELS.REPO_GENERATE_COMMIT_MESSAGE, async (event, rawArgs: unknown) => {
    validateSender(event)
    const args = requireObject(rawArgs, IPC_CHANNELS.REPO_GENERATE_COMMIT_MESSAGE)
    const conversationId = requireString(
      args,
      'conversationId',
      IPC_CHANNELS.REPO_GENERATE_COMMIT_MESSAGE
    )
    const filePaths = args.filePaths as string[]
    if (!Array.isArray(filePaths) || filePaths.length === 0) {
      throw new Error(
        `${IPC_CHANNELS.REPO_GENERATE_COMMIT_MESSAGE}: filePaths must be a non-empty array`
      )
    }

    const messages = messageRepository
      .findByConversation(conversationId)
      .filter((m) => !m.hidden)

    const prompt = `You are generating a concise git commit message. Follow conventional commit style.

Based on this conversation context and file changes, generate a single-line commit message (max 72 chars) followed by optionally a blank line and a body (max 3 lines).

## Recent conversation (last ${Math.min(messages.length, 10)} messages):
${messages
  .slice(-10)
  .map((m) => `[${m.role}]: ${m.contentMd.slice(0, 300)}`)
  .join('\n')}

## Files to commit (${filePaths.length}):
${filePaths.map((fp) => `- ${fp}`).join('\n')}

Respond with ONLY the commit message, no preamble or explanation.`

    try {
      let workspaceId: string | null = null
      try {
        workspaceId = resolveRepoPath(conversationId).workspaceId
      } catch {
        /* best-effort attribution */
      }

      // Resolve model from workspace settings (respects user overrides)
      const resolvedModel = workspaceId
        ? modelConfigService.getModelById(workspaceId, 'commit-message')
        : DEFAULT_MODEL_CONFIG['commit-message']

      const { text: result } = await runOneShotClaude({
        feature: 'commit_message',
        model: resolvedModel,
        workspaceId,
        conversationId,
        args: ['-p', prompt, '--model', resolvedModel],
        cli: {
          timeout: 30_000
        }
      })

      return { message: result.trim() }
    } catch (e) {
      logger.warn('AI commit message generation failed, falling back to simple message:', e)
      // Fallback: generate a simple message from file paths
      const fileNames = filePaths.map((fp) => fp.split('/').pop()).join(', ')
      return {
        message:
          `update ${filePaths.length} file${filePaths.length > 1 ? 's' : ''}: ${fileNames}`.slice(
            0,
            72
          )
      }
    }
  })

  // Create a pull request via GitHub API
  ipcMain.handle(IPC_CHANNELS.REPO_CREATE_PR, async (event, rawArgs: unknown) => {
    validateSender(event)
    const args = requireObject(rawArgs, IPC_CHANNELS.REPO_CREATE_PR)
    const conversationId = requireString(args, 'conversationId', IPC_CHANNELS.REPO_CREATE_PR)
    const title = requireString(args, 'title', IPC_CHANNELS.REPO_CREATE_PR)
    const head = requireString(args, 'head', IPC_CHANNELS.REPO_CREATE_PR)
    const base = requireString(args, 'base', IPC_CHANNELS.REPO_CREATE_PR)
    const body = optionalString(args, 'body', IPC_CHANNELS.REPO_CREATE_PR) ?? ''

    const { repoPath, workspaceId } = resolveRepoPath(conversationId)

    if (!githubService.isConfigured(workspaceId)) {
      throw new Error(
        'GitHub is not configured for this workspace. Please add a GitHub token in workspace settings.'
      )
    }

    const result = await githubService.createPullRequest({
      workspaceId,
      repoPath,
      head,
      base,
      title,
      body
    })

    // Store PR info on conversation
    conversationRepository.updatePrInfo(conversationId, result.prUrl, result.prNumber, head)

    return { url: result.prUrl, number: result.prNumber }
  })
}

