}

/**
 * Phase 5.1: Copy file-type reference docs with absolute paths outside the workspace
 * into a managed directory under userData. Returns the (possibly rewritten) docs array.
 */
function copyOnAttach(
  workspaceId: string,
  blueprintId: string,
  docs: Array<{ type: string; path: string; name?: string }>,
  workspacePath?: string
): Array<{ type: string; path: string; name?: string }> {
  return docs.map((doc, i) => {
    if (doc.type !== 'file' || !isAbsolute(doc.path)) return doc

    // Check if the path is inside the workspace — if so, no copy needed
    // MINOR-FIX: Normalize paths + trailing-separator check to avoid
    // false positives (e.g. /ws2 matching /ws prefix)
    if (workspacePath) {
      const normDoc = normalize(doc.path)
      const normWs = normalize(workspacePath) + (normalize(workspacePath).endsWith(sep) ? '' : sep)
      if (normDoc.startsWith(normWs) || normDoc === normalize(workspacePath)) return doc
    }

    try {
      const stat = statSync(doc.path)
      if (stat.size > COPY_ON_ATTACH_MAX_BYTES) {
        bpLog.warn(`[copy-on-attach] File too large (${stat.size} bytes), keeping original: ${doc.path}`)
        return doc
      }

      const managedDir = getManagedDocsDir(workspaceId, blueprintId)
      mkdirSync(managedDir, { recursive: true })
      // BASENAME-COLLISION-FIX: Prefix with map index to prevent two docs
      // with the same basename (e.g. both named spec.pdf) from silently
      // overwriting each other in the managed directory.
      const destPath = join(managedDir, `${i}-${basename(doc.path)}`)
      copyFileSync(doc.path, destPath)
      bpLog.info(`[copy-on-attach] Copied "${doc.path}" → "${destPath}"`)
      return { ...doc, path: destPath }
    } catch (err) {
      bpLog.warn(`[copy-on-attach] Failed to copy "${doc.path}": ${err} — keeping original`)
      return doc
    }
  })
}

/**
 * Clean up managed docs when a blueprint is deleted.
 */
function cleanupManagedDocs(workspaceId: string, blueprintId: string): void {
  try {
    const dir = getManagedDocsDir(workspaceId, blueprintId)
    if (existsSync(dir)) {
      rmSync(dir, { recursive: true, force: true })
      bpLog.info(`[managed-docs] Cleaned up ${dir}`)
    }
  } catch (err) {
    bpLog.warn(`[managed-docs] Cleanup failed: ${err}`)
  }
}

// ── Main Registration ──

// GAP-6: Module-level deferred reference to accumulator cleanup.
// Assigned in wireOnceEventForwarding (where accumulators live),
// called from the cancel handler in registerBlueprintIpc.
let accumulatorCleanup: ((blueprintId: string) => void) | null = null

export function registerBlueprintIpc(_mainWindow: BrowserWindow): void {
  // Phase 5.2: Register managed docs root for loader whitelist
  setManagedDocsRoot(getManagedDocsRoot())

  // ── blueprint:create — Create a new blueprint ──

  ipcMain.handle(
    IPC_CHANNELS.BLUEPRINT_CREATE,
    (event, rawArgs: unknown) => {
      validateSender(event)
      // BP-IPC-NO-VALIDATION-01: Runtime validation matching grill/chat pattern.
      const ch = IPC_CHANNELS.BLUEPRINT_CREATE
      const args = requireObject(rawArgs, ch)
      const workspaceId = requireString(args, 'workspaceId', ch)
      const title = requireString(args, 'title', ch)
      const description = optionalString(args, 'description', ch)
      const priority = optionalString(args, 'priority', ch) as BlueprintPriority | undefined
      const settingsJson = args.settingsJson as Record<string, unknown> | undefined
      const blueprint = blueprintService.create({ workspaceId, title, description, priority, settingsJson })

      // Phase 5.1: Copy-on-attach — copy external file docs into managed dir,
      // then update the stored settingsJson with rewritten paths.
      const refDocs = settingsJson?.referenceDocuments as Array<{ type: string; path: string; name?: string }> | undefined
      if (refDocs?.length && blueprint.id) {
        const ws = workspaceRepository.findById(workspaceId)
        const rewritten = copyOnAttach(workspaceId, blueprint.id, refDocs, ws?.repoPath)
        // Check if any paths were rewritten
        const anyRewritten = rewritten.some((d, i) => d.path !== refDocs[i].path)
        if (anyRewritten) {
          const updatedSettings = { ...(settingsJson ?? {}), referenceDocuments: rewritten }
          blueprintRepository.update(blueprint.id, { settingsJson: updatedSettings })
          bpLog.info(`[copy-on-attach] Updated settingsJson for ${blueprint.id} with managed doc paths`)
        }
      }

      // MEM-DOC-SPECIFY-01: Doc extraction moved to startSpecifyPhase() —
      // covers create, createFromIdea, resume, and retry paths in one place.

      return blueprint
    }
  )

  // ── blueprint:createFromIdea — Graduate an Idea to a Blueprint ──

  ipcMain.handle(
    IPC_CHANNELS.BLUEPRINT_CREATE_FROM_IDEA,
    (event, rawArgs: unknown) => {
      validateSender(event)
      const ch = IPC_CHANNELS.BLUEPRINT_CREATE_FROM_IDEA
      const args = requireObject(rawArgs, ch)
      const ideaId = requireString(args, 'ideaId', ch)
      const workspaceId = requireString(args, 'workspaceId', ch)
      return blueprintService.createFromIdea(ideaId, workspaceId)
    }
  )

  // ── blueprint:get — Get a blueprint with phases ──

  ipcMain.handle(IPC_CHANNELS.BLUEPRINT_GET, (event, rawArgs: unknown) => {
    validateSender(event)
    const args = requireObject(rawArgs, IPC_CHANNELS.BLUEPRINT_GET)
    const id = requireString(args, 'id', IPC_CHANNELS.BLUEPRINT_GET)
    return blueprintService.getBlueprint(id)
  })

  // ── blueprint:getDetails — Get a blueprint with phases + tasks ──

  ipcMain.handle(IPC_CHANNELS.BLUEPRINT_GET_DETAILS, (event, rawArgs: unknown) => {
    validateSender(event)
    const args = requireObject(rawArgs, IPC_CHANNELS.BLUEPRINT_GET_DETAILS)
    const id = requireString(args, 'id', IPC_CHANNELS.BLUEPRINT_GET_DETAILS)
    return blueprintService.getBlueprintWithDetails(id)
  })

  // ── blueprint:list — List blueprints for a workspace ──

  ipcMain.handle(
    IPC_CHANNELS.BLUEPRINT_LIST,
    (event, rawArgs: unknown) => {
      validateSender(event)
      const ch = IPC_CHANNELS.BLUEPRINT_LIST
      const args = requireObject(rawArgs, ch)
      const workspaceId = requireString(args, 'workspaceId', ch)
      const limit = optionalNumber(args, 'limit', ch)
      return blueprintService.listBlueprints(workspaceId, limit)
    }
  )

  // ── blueprint:delete — Delete a blueprint ──

  ipcMain.handle(IPC_CHANNELS.BLUEPRINT_DELETE, (event, rawArgs: unknown) => {
    validateSender(event)
    const args = requireObject(rawArgs, IPC_CHANNELS.BLUEPRINT_DELETE)
    const id = requireString(args, 'id', IPC_CHANNELS.BLUEPRINT_DELETE)
    // Phase 5.1: Look up workspaceId before delete for managed-docs cleanup
    const bp = blueprintRepository.findById(id)
    blueprintService.delete(id)
    // Phase 5.1: Clean up managed docs directory
    if (bp?.workspaceId) cleanupManagedDocs(bp.workspaceId, id)
    return { deleted: true }
  })

  // ── blueprint:cancel — Cancel an active blueprint pipeline ──

  ipcMain.handle(IPC_CHANNELS.BLUEPRINT_CANCEL, async (event, rawArgs: unknown) => {
    validateSender(event)
    const args = requireObject(rawArgs, IPC_CHANNELS.BLUEPRINT_CANCEL)
    const workspaceId = requireString(args, 'workspaceId', IPC_CHANNELS.BLUEPRINT_CANCEL)

    // BP-CANCEL-LOCK-01: Wrap in try/finally to guarantee blueprintService.cancel()
    // always runs — even if a phase cancel throws. Without this, a single phase
    // cancel failure orphans the startLock and permanently blocks new blueprints.
    try {
      const activeBlueprintId = blueprintService.getActiveBlueprintId(workspaceId)
      if (activeBlueprintId) {
        // GAP-6 FIX: Flush + clean up agent accumulators before cancel
        // (cancel doesn't emit phaseComplete, so accumulators would leak).
        // Uses the deferred reference assigned later in the accumulator section.
        accumulatorCleanup?.(activeBlueprintId)

        // Best-effort cancel each phase service — don't let one failure block others
        const phaseServices = [
          blueprintSpecService, blueprintPlanService, blueprintTasksService,
          blueprintReviewService, blueprintBuildService, blueprintVerifyService
        ]
        for (const svc of phaseServices) {
          try { await svc.cancelBlueprint(activeBlueprintId) }
          catch (e) { bpLog.error(`[cancel] Phase cancel failed:`, e) }
        }
      }
    } finally {
      // ALWAYS release the lock, even if phase cancels threw
      blueprintService.cancel(workspaceId)
    }
    return { cancelled: true }
  })

  // ── blueprint:advancePhase — Advance to next phase ──

  ipcMain.handle(IPC_CHANNELS.BLUEPRINT_ADVANCE_PHASE, (event, rawArgs: unknown) => {
    validateSender(event)
    const args = requireObject(rawArgs, IPC_CHANNELS.BLUEPRINT_ADVANCE_PHASE)
    const blueprintId = requireString(args, 'blueprintId', IPC_CHANNELS.BLUEPRINT_ADVANCE_PHASE)
    return blueprintService.advancePhase(blueprintId)
  })

  // ── blueprint:skipPhase — Skip a phase ──

  ipcMain.handle(
    IPC_CHANNELS.BLUEPRINT_SKIP_PHASE,
    (event, rawArgs: unknown) => {
      validateSender(event)
      const ch = IPC_CHANNELS.BLUEPRINT_SKIP_PHASE
      const args = requireObject(rawArgs, ch)
      const blueprintId = requireString(args, 'blueprintId', ch)
      const phase = requireString(args, 'phase', ch) as BlueprintPhaseType
      blueprintService.skipPhase(blueprintId, phase)
      return { skipped: true }
    }
  )

  // ── blueprint:rewindPhase — Rewind to a previous phase ──

  ipcMain.handle(
    IPC_CHANNELS.BLUEPRINT_REWIND_PHASE,
    (event, rawArgs: unknown) => {
      validateSender(event)
      const ch = IPC_CHANNELS.BLUEPRINT_REWIND_PHASE
      const args = requireObject(rawArgs, ch)
      const blueprintId = requireString(args, 'blueprintId', ch)
      const phase = requireString(args, 'phase', ch) as BlueprintPhaseType
      blueprintService.rewindToPhase(blueprintId, phase)
      return { rewound: true }
    }
  )

  // ── blueprint:buildPrompt — Build system prompt for a phase ──

  ipcMain.handle(
    IPC_CHANNELS.BLUEPRINT_BUILD_PROMPT,
    async (event, rawArgs: unknown) => {
      validateSender(event)
      const ch = IPC_CHANNELS.BLUEPRINT_BUILD_PROMPT
      const args = requireObject(rawArgs, ch)
      const blueprintId = requireString(args, 'blueprintId', ch)
      const phase = requireString(args, 'phase', ch) as BlueprintPhaseType
      return { prompt: await blueprintService.buildSystemPrompt(blueprintId, phase) }
    }
  )

  // ── blueprint:saveArtifact — Save a phase artifact ──

  ipcMain.handle(
    IPC_CHANNELS.BLUEPRINT_SAVE_ARTIFACT,
    (event, rawArgs: unknown) => {
      validateSender(event)
      const ch = IPC_CHANNELS.BLUEPRINT_SAVE_ARTIFACT
      const args = requireObject(rawArgs, ch)
      const blueprintId = requireString(args, 'blueprintId', ch)
      const phase = requireString(args, 'phase', ch) as BlueprintPhaseType
      if (!args.artifact || typeof args.artifact !== 'object') {
        throw new Error(`${ch}: field 'artifact' must be an object`)
      }
      blueprintService.savePhaseArtifact(blueprintId, phase, args.artifact as BlueprintArtifact)
      return { saved: true }
    }
  )

  // ── blueprint:getArtifacts — Get all artifacts for a blueprint ──

  ipcMain.handle(IPC_CHANNELS.BLUEPRINT_GET_ARTIFACTS, (event, rawArgs: unknown) => {
    validateSender(event)
    const args = requireObject(rawArgs, IPC_CHANNELS.BLUEPRINT_GET_ARTIFACTS)
    const blueprintId = requireString(args, 'blueprintId', IPC_CHANNELS.BLUEPRINT_GET_ARTIFACTS)
    return blueprintService.getAllArtifacts(blueprintId)
  })

  // ── blueprint:populateTasks — Parse and store tasks from blueprint-tasks JSON ──

  ipcMain.handle(
    IPC_CHANNELS.BLUEPRINT_POPULATE_TASKS,
    (event, rawArgs: unknown) => {
      validateSender(event)
      const ch = IPC_CHANNELS.BLUEPRINT_POPULATE_TASKS
      // BP-IPC-NO-VALIDATION-01: Use requireObject/requireString pattern.
      const args = requireObject(rawArgs, ch)
      const blueprintId = requireString(args, 'blueprintId', ch)

      // TASK-02: Validate input bounds before passing to service
      if (!Array.isArray(args.tasks)) {
        throw new Error(`${ch}: tasks must be an array`)
      }
      if (args.tasks.length > 500) {
        throw new Error(`${ch}: tasks array too large (${args.tasks.length}, max 500)`)
      }

      return blueprintService.populateTasks(blueprintId, args.tasks as Array<{
        taskId: string
        wave: number
        description: string
        userStory?: string
        files?: string[]
        isParallel?: boolean
        dependsOn?: string[]
      }>)
    }
  )

  // ── blueprint:getPipelineStatus — Get pipeline status for a workspace ──

  ipcMain.handle(
    IPC_CHANNELS.BLUEPRINT_GET_PIPELINE_STATUS,
    (event, args: { workspaceId: string }) => {
      validateSender(event)
      const status = blueprintService.getPipelineStatus(args.workspaceId)

      // B2-FIX: Enrich with clarify UI state for renderer reload hydration
      if (status.running && status.blueprintId && status.currentPhase === 'clarify') {
        const clarifyState = blueprintSpecService.getClarifyUiState(status.blueprintId)
        return { ...status, clarifyState }
      }

      // BP-RESUME-02: When pipeline is idle, check for crash-orphaned blueprints
      // so the renderer can show a resume banner on startup.
      if (!status.running) {
        const orphan = blueprintService.findOrphanedBlueprint(args.workspaceId)
        if (orphan) {
          return { ...status, orphanedBlueprint: orphan }
        }
      }

      return status
    }
  )

  // ── blueprint:approvalRespond — Respond to an approval gate ──

  ipcMain.handle(
    IPC_CHANNELS.BLUEPRINT_APPROVAL_RESPOND,
    (event, rawArgs: unknown) => {
      validateSender(event)
      const ch = IPC_CHANNELS.BLUEPRINT_APPROVAL_RESPOND
      const args = requireObject(rawArgs, ch)
      const blueprintId = requireString(args, 'blueprintId', ch)
      if (typeof args.approved !== 'boolean') {
        throw new Error(`${ch}: field 'approved' must be a boolean`)
      }
      const approved = args.approved

      if (approved) {
        // Drive state machine: awaiting-approval → idle
        const blueprint = blueprintService.getBlueprint(blueprintId)
        if (blueprint) {
          // G9: If preflight had blockers, persist preflightOverride in settingsJson
          // so remediation/retry paths inherit the override
          const pendingApproval = blueprintService.getPendingApproval(blueprint.workspaceId)
          if (pendingApproval?.preflight) {
            const pfResult = pendingApproval.preflight.result as Record<string, unknown>
            if (pfResult.hasBlockers) {
              blueprintRepository.update(blueprintId, {
                settingsJson: {
                  ...blueprint.settingsJson,
                  preflightOverride: true
                }
              })
              bpLog.info(`[blueprint:approvalRespond] Preflight override persisted for ${blueprintId}`)
            }
          }

          // M2: Clear approval state before machine transition (snapshot publishes on transition)
          blueprintService.setPendingApproval(blueprint.workspaceId, null)
          const machine = blueprintService.getMachine(blueprint.workspaceId)
          machine.transition('approvalResponded')
        }

        // Advance to BUILD phase — DB state is set by blueprintBuildService.startBuildPhase()
        bpLog.info(
          `[blueprint:approvalRespond] Blueprint ${blueprintId} — approved, triggering BUILD`
        )

        // Look up workspace for the repo path
        // (blueprint already fetched above for machine transition)
        if (blueprint) {
          const workspace = workspaceRepository.findById(blueprint.workspaceId)
          if (workspace) {
            // Start the BUILD phase (non-blocking)
            blueprintBuildService
              .startBuildPhase({
                blueprintId,
                workspaceId: blueprint.workspaceId,
                workspacePath: workspace.repoPath
              })
              .catch((err) => {
                bpLog.error('[blueprint:approvalRespond] BUILD phase failed:', err)
              })
          } else {
            bpLog.error(
              `[blueprint:approvalRespond] Workspace not found for blueprint ${blueprintId}`
            )
          }
        } else {
          bpLog.error(`[blueprint:approvalRespond] Blueprint not found: ${blueprintId}`)
        }
      } else {
        // Not approved — rewind to plan phase for iteration
        // Drive state machine: awaiting-approval → idle (so rewind can start fresh)
        const rejBlueprint = blueprintService.getBlueprint(blueprintId)
        if (rejBlueprint) {
          // M2: Clear approval state
          blueprintService.setPendingApproval(rejBlueprint.workspaceId, null)
          const machine = blueprintService.getMachine(rejBlueprint.workspaceId)
          machine.transition('approvalResponded')
        }
        blueprintService.rewindToPhase(blueprintId, 'plan')
        bpLog.info(
          `[blueprint:approvalRespond] Blueprint ${blueprintId} — rejected, rewound to plan`
        )
      }

      // MEM-BP-APPROVAL-01: Write approval/rejection as a direct decision fact.
      // Human approval is the highest-value memory — captured verbatim, no LLM needed.
      const bpForFact = blueprintService.getBlueprint(blueprintId)
      if (bpForFact) {
        const bpSettings = workspaceRepository.getSettings(bpForFact.workspaceId)
        const bpCaptureEnabled = (bpSettings as any).memoryCaptureBlueprints !== false
        if (bpCaptureEnabled) {
          const decision = approved ? 'approved' : 'rejected'
          // Assemble a plan summary from the plan phase artifact
          const planPhase = bpForFact.phases?.find((p: any) => p.phase === 'plan')
          const planArtifact = planPhase?.artifactsJson?.find((a: any) => a.type === 'plan')
          const planSummary = planArtifact?.contentMd
            ? planArtifact.contentMd.substring(0, 2000)
            : bpForFact.description ?? ''

          memoryEngineService.writeFact({
            workspaceId: bpForFact.workspaceId,
            category: 'decision',
            title: `Blueprint ${decision}: ${bpForFact.title}`,
            content: `Plan was ${decision} by the user.\n\n### Plan Summary\n${planSummary}`,
            tags: ['blueprint', `blueprint:${blueprintId}`, decision],
            sourceType: 'blueprint',
            sourceRef: blueprintId,
            workspacePath: workspaceRepository.findById(bpForFact.workspaceId)?.repoPath
          }).catch((err) => {
            bpLog.warn(`[blueprint:approvalRespond] Failed to write approval fact: ${err}`)
          })
        }
      }

      return { responded: true }
    }
  )

  // ── blueprint:preflightRun — Re-run preflight checks (G6: manual re-run) ──

  ipcMain.handle(
    IPC_CHANNELS.BLUEPRINT_PREFLIGHT_RUN,
    async (event, rawArgs: unknown) => {
      validateSender(event)
      const ch = IPC_CHANNELS.BLUEPRINT_PREFLIGHT_RUN
      const args = requireObject(rawArgs, ch)
      const blueprintId = requireString(args, 'blueprintId', ch)
      const workspaceId = requireString(args, 'workspaceId', ch)

      // A5 fix: derive workspacePath server-side from workspaceId (don't trust renderer)
      const workspace = workspaceRepository.findById(workspaceId)
      if (!workspace?.repoPath) {
        bpLog.warn(`[blueprint:preflightRun] No workspace found for ${workspaceId}`)
        return null
      }
      const workspacePath = workspace.repoPath

      bpLog.info(`[blueprint:preflightRun] Re-running preflight for ${blueprintId}`)

      // Gather task descriptions for keyword detection (G10)
      const tasks = blueprintTaskRepository.findByBlueprint(blueprintId)
      const taskDescriptions = tasks.map((t: { description: string }) => t.description)

      const result = await runPreflightChecks(workspacePath, taskDescriptions)

      // A6+R2-2 fix: atomic replace — fresh read inside repo avoids stale artifacts
      const reviewPhase = blueprintPhaseRepository.findByBlueprintAndPhase(blueprintId, 'review')
      if (reviewPhase) {
        blueprintPhaseRepository.replaceArtifactOfType(reviewPhase.id, 'preflight', {
          type: 'preflight',
          contentJson: result as unknown as Record<string, unknown>
        })
      }

      // Update pending approval with new preflight data
      const pendingApproval = blueprintService.getPendingApproval(workspaceId)
      if (pendingApproval) {
        blueprintService.setPendingApproval(workspaceId, {
          ...pendingApproval,
          preflight: { result: result as unknown as Record<string, unknown>, overridden: false }
        })
      }

      // Broadcast result to renderer
      try {
        const windows = BrowserWindow.getAllWindows()
        for (const win of windows) {
          win.webContents.send(IPC_CHANNELS.BLUEPRINT_PREFLIGHT_RESULT, {
            blueprintId,
            workspaceId,
            result
          })
        }
      } catch { /* non-fatal */ }

      return result
    }
  )

  // ── blueprint:getConstitution — Get workspace constitution ──

  ipcMain.handle(
    IPC_CHANNELS.BLUEPRINT_GET_CONSTITUTION,
    (event, rawArgs: unknown) => {
      validateSender(event)
      const args = requireObject(rawArgs, IPC_CHANNELS.BLUEPRINT_GET_CONSTITUTION)
      const workspaceId = requireString(args, 'workspaceId', IPC_CHANNELS.BLUEPRINT_GET_CONSTITUTION)
      const workspace = workspaceRepository.findById(workspaceId)
      if (!workspace) return null
      return {
        constitutionMd: workspace.constitutionMd ?? null,
        constitutionVersion: workspace.constitutionVersion ?? '1.0.0'
      }
    }
  )

  // ── blueprint:saveConstitution — Save workspace constitution ──

  ipcMain.handle(
    IPC_CHANNELS.BLUEPRINT_SAVE_CONSTITUTION,
    (event, rawArgs: unknown) => {
      validateSender(event)
      const ch = IPC_CHANNELS.BLUEPRINT_SAVE_CONSTITUTION
      const args = requireObject(rawArgs, ch)
      const workspaceId = requireString(args, 'workspaceId', ch)
      const constitutionMd = requireString(args, 'constitutionMd', ch)
      const version = optionalString(args, 'version', ch)
      workspaceRepository.updateConstitution(
        workspaceId,
        constitutionMd,
        version ?? '1.0.0'
      )
      return { saved: true }
    }
  )

  // ═══════════════════════════════════════════════════════════════════════════
  //  Phase 2: Specify + Clarify Pipeline Handlers
  // ═══════════════════════════════════════════════════════════════════════════

  // ── blueprint:startSpecify — Start the SPECIFY phase ──

  ipcMain.handle(
    IPC_CHANNELS.BLUEPRINT_START_SPECIFY,
    (event, rawArgs: unknown) => {
      validateSender(event)
      const ch = IPC_CHANNELS.BLUEPRINT_START_SPECIFY
      const args = requireObject(rawArgs, ch)
      const blueprintId = requireString(args, 'blueprintId', ch)
      const workspaceId = requireString(args, 'workspaceId', ch)

      const workspace = workspaceRepository.findById(workspaceId)
      if (!workspace) {
        throw new Error(`Workspace not found: ${workspaceId}`)
      }

      const blueprint = blueprintService.getBlueprint(blueprintId)
      if (!blueprint) {
        throw new Error(`Blueprint not found: ${blueprintId}`)
      }

      // Extract grill decisions and reference documents from settings (validated)
      const grillDecisions = extractGrillDecisions(blueprint.settingsJson as Record<string, unknown> | null)
      const referenceDocuments = extractReferenceDocuments(blueprint.settingsJson as Record<string, unknown> | null)

      // Start the SPECIFY phase (non-blocking)
      blueprintSpecService
        .startSpecifyPhase({
          blueprintId,
          workspaceId,
          workspacePath: workspace.repoPath,
          description: blueprint.description,
          grillDecisions,
          referenceDocuments
        })
        .catch((err) => {
          bpLog.error('[blueprint:startSpecify] Phase failed:', err)
        })

      return { started: true }
    }
  )

  // ── blueprint:startClarify — Start the CLARIFY phase ──

  ipcMain.handle(
    IPC_CHANNELS.BLUEPRINT_START_CLARIFY,
    (event, rawArgs: unknown) => {
      validateSender(event)
      const ch = IPC_CHANNELS.BLUEPRINT_START_CLARIFY
      const args = requireObject(rawArgs, ch)
      const blueprintId = requireString(args, 'blueprintId', ch)
      const workspaceId = requireString(args, 'workspaceId', ch)

      const workspace = workspaceRepository.findById(workspaceId)
      if (!workspace) {
        throw new Error(`Workspace not found: ${workspaceId}`)
      }

      // Start the CLARIFY phase (non-blocking)
      blueprintSpecService
        .startClarifyPhase({
          blueprintId,
          workspaceId,
          workspacePath: workspace.repoPath
        })
        .catch((err) => {
          bpLog.error('[blueprint:startClarify] Phase failed:', err)
        })

      return { started: true }
    }
  )

  // ── blueprint:clarifyAnswer — Send a user answer during CLARIFY ──

  ipcMain.handle(
    IPC_CHANNELS.BLUEPRINT_CLARIFY_ANSWER,
    async (event, rawArgs: unknown) => {
      validateSender(event)
      const ch = IPC_CHANNELS.BLUEPRINT_CLARIFY_ANSWER
      const args = requireObject(rawArgs, ch)
      const blueprintId = requireString(args, 'blueprintId', ch)
      const workspaceId = requireString(args, 'workspaceId', ch)
      const message = requireString(args, 'message', ch)

      // M8: Journal user answer before sending (append is best-effort)
      try {
        blueprintEventRepository.append(blueprintId, 'user', { message })
      } catch { /* best effort */ }

      await blueprintSpecService.sendClarifyAnswer({
        blueprintId,
        workspaceId,
        message
      })

      return { sent: true }
    }
  )

  // ── blueprint:skipClarify — Skip the CLARIFY phase ──

  ipcMain.handle(
    IPC_CHANNELS.BLUEPRINT_SKIP_CLARIFY,
    async (event, rawArgs: unknown) => {
      validateSender(event)
      const args = requireObject(rawArgs, IPC_CHANNELS.BLUEPRINT_SKIP_CLARIFY)
      const blueprintId = requireString(args, 'blueprintId', IPC_CHANNELS.BLUEPRINT_SKIP_CLARIFY)

      await blueprintSpecService.skipClarifyPhase(blueprintId)
      return { skipped: true }
    }
  )

  // ── blueprint:clarifyProceed — User proceeds through the clarify gate ──

  ipcMain.handle(
    IPC_CHANNELS.BLUEPRINT_CLARIFY_PROCEED,
    async (event, rawArgs: unknown) => {
      validateSender(event)
      const ch = IPC_CHANNELS.BLUEPRINT_CLARIFY_PROCEED
      const args = requireObject(rawArgs, ch)
      const blueprintId = requireString(args, 'blueprintId', ch)
      requireString(args, 'workspaceId', ch)

      await blueprintSpecService.proceedClarifyGate(blueprintId)
      return { proceeded: true }
    }
  )

  // ── blueprint:clarifyIterate — User requests more clarification rounds ──

  ipcMain.handle(
    IPC_CHANNELS.BLUEPRINT_CLARIFY_ITERATE,
    async (event, rawArgs: unknown) => {
      validateSender(event)
      const ch = IPC_CHANNELS.BLUEPRINT_CLARIFY_ITERATE
      const args = requireObject(rawArgs, ch)
      const blueprintId = requireString(args, 'blueprintId', ch)
      requireString(args, 'workspaceId', ch)

      await blueprintSpecService.iterateClarify(blueprintId)
      return { iterated: true }
    }
  )

  // ═══════════════════════════════════════════════════════════════════════════
  //  Phase 3: Plan Pipeline Handler
  // ═══════════════════════════════════════════════════════════════════════════

  // ── blueprint:startPlan — Start the PLAN phase ──

  ipcMain.handle(
    IPC_CHANNELS.BLUEPRINT_START_PLAN,
    (event, rawArgs: unknown) => {
      validateSender(event)
      const ch = IPC_CHANNELS.BLUEPRINT_START_PLAN
      const args = requireObject(rawArgs, ch)
      const blueprintId = requireString(args, 'blueprintId', ch)
      const workspaceId = requireString(args, 'workspaceId', ch)

      const workspace = workspaceRepository.findById(workspaceId)
      if (!workspace) {
        throw new Error(`Workspace not found: ${workspaceId}`)
      }

      // Start the PLAN phase (non-blocking)
      blueprintPlanService
        .startPlanPhase({
          blueprintId,
          workspaceId,
          workspacePath: workspace.repoPath
        })
        .catch((err) => {
          bpLog.error('[blueprint:startPlan] Phase failed:', err)
        })

      return { started: true }
    }
  )

  // ═══════════════════════════════════════════════════════════════════════════
  //  Phase 4: Tasks Pipeline Handler
  // ═══════════════════════════════════════════════════════════════════════════

  // ── blueprint:startTasks — Start the TASKS phase ──

  ipcMain.handle(
    IPC_CHANNELS.BLUEPRINT_START_TASKS,
    (event, rawArgs: unknown) => {
      validateSender(event)
      const ch = IPC_CHANNELS.BLUEPRINT_START_TASKS
      const args = requireObject(rawArgs, ch)
      const blueprintId = requireString(args, 'blueprintId', ch)
      const workspaceId = requireString(args, 'workspaceId', ch)

      const workspace = workspaceRepository.findById(workspaceId)
      if (!workspace) {
        throw new Error(`Workspace not found: ${workspaceId}`)
      }

      // Start the TASKS phase (non-blocking)
      blueprintTasksService
        .startTasksPhase({
          blueprintId,
          workspaceId,
          workspacePath: workspace.repoPath
        })
        .catch((err) => {
          bpLog.error('[blueprint:startTasks] Phase failed:', err)
        })

      return { started: true }
    }
  )

  // ═══════════════════════════════════════════════════════════════════════
  //  Phase 5: Review Pipeline Handler
  // ═══════════════════════════════════════════════════════════════════════

  // ── blueprint:startReview — Start the REVIEW phase ──

  ipcMain.handle(
    IPC_CHANNELS.BLUEPRINT_START_REVIEW,
    (event, rawArgs: unknown) => {
      validateSender(event)
      const ch = IPC_CHANNELS.BLUEPRINT_START_REVIEW
      const args = requireObject(rawArgs, ch)
      const blueprintId = requireString(args, 'blueprintId', ch)
      const workspaceId = requireString(args, 'workspaceId', ch)

      const workspace = workspaceRepository.findById(workspaceId)
      if (!workspace) {
        throw new Error(`Workspace not found: ${workspaceId}`)
      }

      // Start the REVIEW phase (non-blocking)
      blueprintReviewService
        .startReviewPhase({
          blueprintId,
          workspaceId,
          workspacePath: workspace.repoPath
        })
        .catch((err) => {
          bpLog.error('[blueprint:startReview] Phase failed:', err)
        })

      return { started: true }
    }
  )

  // ═══════════════════════════════════════════════════════════════════════
  //  Phase 6: Build Pipeline Handler
  // ═══════════════════════════════════════════════════════════════════════

  // ── blueprint:startBuild — Start the BUILD phase (manual trigger) ──

  ipcMain.handle(
    IPC_CHANNELS.BLUEPRINT_START_BUILD,
    (event, rawArgs: unknown) => {
      validateSender(event)
      const ch = IPC_CHANNELS.BLUEPRINT_START_BUILD
      const args = requireObject(rawArgs, ch)
      const blueprintId = requireString(args, 'blueprintId', ch)
      const workspaceId = requireString(args, 'workspaceId', ch)

      const workspace = workspaceRepository.findById(workspaceId)
      if (!workspace) {
        throw new Error(`Workspace not found: ${workspaceId}`)
      }

      // Start the BUILD phase (non-blocking)
      blueprintBuildService
        .startBuildPhase({
          blueprintId,
          workspaceId,
          workspacePath: workspace.repoPath
        })
        .catch((err) => {
          bpLog.error('[blueprint:startBuild] Phase failed:', err)
        })

      return { started: true }
    }
  )

  // ═══════════════════════════════════════════════════════════════════════
  //  Phase 7: Verify Pipeline Handler
  // ═══════════════════════════════════════════════════════════════════════

  // ── blueprint:startVerify — Start the VERIFY phase (manual trigger or auto from BUILD) ──

  ipcMain.handle(
    IPC_CHANNELS.BLUEPRINT_START_VERIFY,
    (event, rawArgs: unknown) => {
      validateSender(event)
      const ch = IPC_CHANNELS.BLUEPRINT_START_VERIFY
      const args = requireObject(rawArgs, ch)
      const blueprintId = requireString(args, 'blueprintId', ch)
      const workspaceId = requireString(args, 'workspaceId', ch)

      const workspace = workspaceRepository.findById(workspaceId)
      if (!workspace) {
        throw new Error(`Workspace not found: ${workspaceId}`)
      }

      // Start the VERIFY phase (non-blocking)
      blueprintVerifyService
        .startVerifyPhase({
          blueprintId,
          workspaceId,
          workspacePath: workspace.repoPath
        })
        .catch((err) => {
          bpLog.error('[blueprint:startVerify] Phase failed:', err)
        })

      return { started: true }
    }
  )

  // ── blueprint:retryPhase — Retry the failed phase of a blueprint ──

  ipcMain.handle(
    IPC_CHANNELS.BLUEPRINT_RETRY_PHASE,
    (event, rawArgs: unknown) => {
      validateSender(event)
      const ch = IPC_CHANNELS.BLUEPRINT_RETRY_PHASE
      const args = requireObject(rawArgs, ch)
      const blueprintId = requireString(args, 'blueprintId', ch)
      const workspaceId = requireString(args, 'workspaceId', ch)

      // retryPhase resets the failed phase → pending and returns the phase type
      const { phase } = blueprintService.retryPhase(blueprintId)

      // RETRY-JOURNAL: Record retry dispatch in journal so hydrated transcripts
      // show a divider explaining why a phase started again.
      try {
        blueprintEventRepository.append(blueprintId, 'system', {
          event: 'retryPhase',
          message: `Retrying ${phase} phase`
        })
      } catch { /* best effort */ }

      const workspace = workspaceRepository.findById(workspaceId)
      if (!workspace) {
        throw new Error(`Workspace not found: ${workspaceId}`)
      }

      const blueprint = blueprintService.getBlueprint(blueprintId)
      if (!blueprint) throw new Error(`Blueprint not found: ${blueprintId}`)

      // Extract grill decisions and reference documents from settings (for specify retry)
      const grillDecisions = extractGrillDecisions(blueprint.settingsJson as Record<string, unknown> | null)
      const referenceDocuments = extractReferenceDocuments(blueprint.settingsJson as Record<string, unknown> | null)

      // Dispatch to the matching sub-service (non-blocking)
      const phaseDispatch: Record<string, () => Promise<void>> = {
        specify: () =>
          blueprintSpecService.startSpecifyPhase({
            blueprintId,
            workspaceId,
            workspacePath: workspace.repoPath,
            description: blueprint.description,
            grillDecisions,
            referenceDocuments
          }),
        clarify: () =>
          blueprintSpecService.startClarifyPhase({
            blueprintId,
            workspaceId,
            workspacePath: workspace.repoPath
          }),
        plan: () =>
          blueprintPlanService.startPlanPhase({
            blueprintId,
            workspaceId,
            workspacePath: workspace.repoPath
          }),
        tasks: () =>
          blueprintTasksService.startTasksPhase({
            blueprintId,
            workspaceId,
            workspacePath: workspace.repoPath
          }),
        review: () =>
          blueprintReviewService.startReviewPhase({
            blueprintId,
            workspaceId,
            workspacePath: workspace.repoPath
          }),
        build: () =>
          blueprintBuildService.startBuildPhase({
            blueprintId,
            workspaceId,
            workspacePath: workspace.repoPath
          }),
        verify: () =>
          blueprintVerifyService.startVerifyPhase({
            blueprintId,
            workspaceId,
            workspacePath: workspace.repoPath
          })
      }

      const dispatch = phaseDispatch[phase]
      if (dispatch) {
        dispatch().catch((err) => {
          bpLog.error(`[blueprint:retryPhase] ${phase} phase retry failed:`, err)
        })
      } else {
        bpLog.error(`[blueprint:retryPhase] Unknown phase: ${phase}`)
      }

      return { retrying: true, phase }
    }
  )

  // ── blueprint:acknowledgeReview — Mark human-needed verify as reviewed ──

  ipcMain.handle(
    IPC_CHANNELS.BLUEPRINT_ACKNOWLEDGE_REVIEW,
    (event, rawArgs: unknown) => {
      validateSender(event)
      const ch = IPC_CHANNELS.BLUEPRINT_ACKNOWLEDGE_REVIEW
      const args = requireObject(rawArgs, ch)
      const blueprintId = requireString(args, 'blueprintId', ch)

      const phase = blueprintPhaseRepository.findByBlueprintAndPhase(blueprintId, 'verify')
      if (!phase) {
        throw new Error(`Verify phase not found for blueprint: ${blueprintId}`)
      }

      // Find verify artifact and stamp acknowledgement on its contentJson
      const artifacts = [...phase.artifactsJson]
      const artIdx = artifacts.findIndex(
        (a) => a.type === 'verify' || a.type === 'verification'
      )
      if (artIdx >= 0) {
        const art = artifacts[artIdx]
        const contentJson = (art.contentJson ?? {}) as Record<string, unknown>
        contentJson.humanReviewAcknowledged = true
        contentJson.acknowledgedAt = new Date().toISOString()
        artifacts[artIdx] = { ...art, contentJson }
      }

      blueprintPhaseRepository.saveArtifacts(phase.id, artifacts)

      // Journal beat for transcript audit trail
      try {
        blueprintEventRepository.append(blueprintId, 'system', {
          event: 'humanReviewAcknowledged',
          message: 'Human review completed — verification acknowledged by user'
        })
      } catch { /* best effort */ }

      return { acknowledged: true }
    }
  )

  // ── M3: blueprint:getTranscript — Retrieve journal entries for a blueprint ──

  ipcMain.handle(
    IPC_CHANNELS.BLUEPRINT_GET_TRANSCRIPT,
    (event, rawArgs: unknown) => {
      validateSender(event)
      const ch = IPC_CHANNELS.BLUEPRINT_GET_TRANSCRIPT
      const args = requireObject(rawArgs, ch)
      const blueprintId = requireString(args, 'blueprintId', ch)
      const afterSeq = optionalNumber(args, 'afterSeq', ch)

      if (afterSeq !== undefined && afterSeq !== null) {
        return blueprintEventRepository.findByBlueprintAfterSeq(blueprintId, afterSeq)
      }
      return blueprintEventRepository.findByBlueprint(blueprintId)
    }
  )

  // ── M7: blueprint:getSnapshot — Pull-based snapshot seed ──

  ipcMain.handle(
    IPC_CHANNELS.BLUEPRINT_GET_SNAPSHOT,
    (event, rawArgs: unknown) => {
      validateSender(event)
      const ch = IPC_CHANNELS.BLUEPRINT_GET_SNAPSHOT
      const args = requireObject(rawArgs, ch)
      const workspaceId = requireString(args, 'workspaceId', ch)
      return blueprintService.getSnapshot(workspaceId)
    }
  )

  // ── Stale blueprint detection on registration ──
  blueprintService.reconcileStaleBlueprints()

  // M6: Wire-once event forwarding — registered once, routes by payload.workspaceId.
  // Eliminates 13 wireBlueprintEvents call sites + 180-min TTL cleanup.
  wireOnceEventForwarding()
}

// ── M6: Wire-Once Event Forwarding ──
// Registered once during IPC registration. Routes by payload.workspaceId.
// No TTL, no per-workspace cleanup, no re-wire dance.

let wireOnceEventForwardingCalled = false
function wireOnceEventForwarding(): void {
  // Guard: prevent double-registration if called more than once.
  // EventEmitter.on stacks handlers, so a second call would duplicate
  // every journal append and event forward.
  if (wireOnceEventForwardingCalled) {
    bpLog.warn('[wireOnceEventForwarding] Already called — skipping duplicate registration')
    return
  }
  wireOnceEventForwardingCalled = true

  // Helper: safe event forwarding with error isolation
  function forward(emitter: EventEmitterLike, event: string, channel: string, logPrefix?: string): void {
    emitter.on(event, (...args: unknown[]) => {
      try {
        const payload = args[0] as Record<string, unknown>
        const wsId = payload?.workspaceId as string | undefined
        if (!wsId) return
        if (logPrefix) bpLog.info(`[${logPrefix}] ${event}: ${payload.phase ?? ''}`)
        getSessionEventRouter().sendWorkspaceEvent(channel, wsId, payload)
      } catch (err) {
        bpLog.error(`[event-forward] '${event}' handler threw:`, err)
      }
    })
  }

  // Helper: forward status events (different shape: { workspaceId?, status })
  function forwardStatus(emitter: EventEmitterLike): void {
    emitter.on('status', (...args: unknown[]) => {
      try {
        const data = args[0] as { workspaceId?: string; status: AgentStatus }
        if (!data?.workspaceId) return
        getSessionEventRouter().sendWorkspaceEvent(IPC_CHANNELS.AGENT_STATUS_UPDATE, data.workspaceId, { ...data.status })
      } catch (err) {
        bpLog.error(`[event-forward] 'status' handler threw:`, err)
      }
    })
  }

  type EventEmitterLike = { on: (event: string, handler: (...args: unknown[]) => void) => void }

  // ── BlueprintService (orchestrator) ──

  // M2: Forward whole-state snapshot on every state mutation
  blueprintService.on('stateSync', (...args: unknown[]) => {
    try {
      const snapshot = args[0] as Record<string, unknown>
      const wsId = snapshot?.workspaceId as string | undefined
      if (!wsId) return
      getSessionEventRouter().sendWorkspaceEvent(IPC_CHANNELS.BLUEPRINT_STATE_SYNC, wsId, snapshot)
    } catch (err) {
      bpLog.error('[event-forward] stateSync handler threw:', err)
    }
  })

  forward(blueprintService, 'phaseStart', IPC_CHANNELS.BLUEPRINT_PHASE_START, 'event')
  forward(blueprintService, 'phaseProgress', IPC_CHANNELS.BLUEPRINT_PHASE_PROGRESS)

  forward(blueprintService, 'phaseComplete', IPC_CHANNELS.BLUEPRINT_PHASE_COMPLETE, 'event')
  forward(blueprintService, 'phaseArtifact', IPC_CHANNELS.BLUEPRINT_PHASE_ARTIFACT, 'event')

  // ── BlueprintBuildService events (Phase 6: Build) ──
  forward(blueprintBuildService as unknown as EventEmitterLike, 'phaseStart', IPC_CHANNELS.BLUEPRINT_PHASE_START, 'build-event')
  forward(blueprintBuildService as unknown as EventEmitterLike, 'phaseProgress', IPC_CHANNELS.BLUEPRINT_PHASE_PROGRESS)
  forward(blueprintBuildService as unknown as EventEmitterLike, 'phaseComplete', IPC_CHANNELS.BLUEPRINT_PHASE_COMPLETE, 'build-event')
  forward(blueprintBuildService as unknown as EventEmitterLike, 'phaseArtifact', IPC_CHANNELS.BLUEPRINT_PHASE_ARTIFACT, 'build-event')
  forwardStatus(blueprintBuildService as unknown as EventEmitterLike)

  // Wave execution events
  forward(blueprintBuildService as unknown as EventEmitterLike, 'waveStart', IPC_CHANNELS.BLUEPRINT_WAVE_START, 'build-event')
  forward(blueprintBuildService as unknown as EventEmitterLike, 'waveTaskStart', IPC_CHANNELS.BLUEPRINT_WAVE_TASK_START)
  forward(blueprintBuildService as unknown as EventEmitterLike, 'waveTaskComplete', IPC_CHANNELS.BLUEPRINT_WAVE_TASK_COMPLETE, 'build-event')
  forward(blueprintBuildService as unknown as EventEmitterLike, 'waveComplete', IPC_CHANNELS.BLUEPRINT_WAVE_COMPLETE, 'build-event')

  // ── BlueprintSpecService events (Phase 2: Specify + Clarify) ──
  forward(blueprintSpecService as unknown as EventEmitterLike, 'phaseStart', IPC_CHANNELS.BLUEPRINT_PHASE_START, 'spec-event')
  forward(blueprintSpecService as unknown as EventEmitterLike, 'phaseProgress', IPC_CHANNELS.BLUEPRINT_PHASE_PROGRESS)
  forward(blueprintSpecService as unknown as EventEmitterLike, 'phaseComplete', IPC_CHANNELS.BLUEPRINT_PHASE_COMPLETE, 'spec-event')
  forward(blueprintSpecService as unknown as EventEmitterLike, 'phaseArtifact', IPC_CHANNELS.BLUEPRINT_PHASE_ARTIFACT, 'spec-event')
  forward(blueprintSpecService as unknown as EventEmitterLike, 'clarifyAwaitingInput', IPC_CHANNELS.BLUEPRINT_CLARIFY_AWAITING_INPUT, 'spec-event')
  forward(blueprintSpecService as unknown as EventEmitterLike, 'clarifyFindings', IPC_CHANNELS.BLUEPRINT_CLARIFY_FINDINGS, 'spec-event')
  forward(blueprintSpecService as unknown as EventEmitterLike, 'clarifyQuestions', IPC_CHANNELS.BLUEPRINT_CLARIFY_QUESTIONS, 'spec-event')

  // OS notification: Blueprint needs user input (clarify phase)
  ;(blueprintSpecService as unknown as EventEmitterLike).on('clarifyAwaitingInput', (...args: unknown[]) => {
    try {
      const payload = args[0] as Record<string, unknown>
      const wsId = payload?.workspaceId as string | undefined
      if (!wsId) return
      notificationService.dispatch({
        workspaceId: wsId,
        workspaceName: resolveWorkspaceName(wsId),
        service: 'blueprint',
        status: 'needs_input',
        summary: 'Blueprint has questions — your input shapes the spec',
        targetPage: 'blueprints',
        entityId: payload.blueprintId as string | undefined
      })
    } catch { /* non-fatal */ }
  })
  forward(blueprintSpecService as unknown as EventEmitterLike, 'clarifyGateReady', IPC_CHANNELS.BLUEPRINT_CLARIFY_GATE, 'spec-event')
  forwardStatus(blueprintSpecService as unknown as EventEmitterLike)

  // ── BlueprintPlanService events (Phase 3: Plan) ──
  forward(blueprintPlanService as unknown as EventEmitterLike, 'phaseStart', IPC_CHANNELS.BLUEPRINT_PHASE_START, 'plan-event')
  forward(blueprintPlanService as unknown as EventEmitterLike, 'phaseProgress', IPC_CHANNELS.BLUEPRINT_PHASE_PROGRESS)
  forward(blueprintPlanService as unknown as EventEmitterLike, 'phaseComplete', IPC_CHANNELS.BLUEPRINT_PHASE_COMPLETE, 'plan-event')
  forward(blueprintPlanService as unknown as EventEmitterLike, 'phaseArtifact', IPC_CHANNELS.BLUEPRINT_PHASE_ARTIFACT, 'plan-event')
  forwardStatus(blueprintPlanService as unknown as EventEmitterLike)

  // ── BlueprintTasksService events (Phase 4: Tasks) ──
  forward(blueprintTasksService as unknown as EventEmitterLike, 'phaseStart', IPC_CHANNELS.BLUEPRINT_PHASE_START, 'tasks-event')
  forward(blueprintTasksService as unknown as EventEmitterLike, 'phaseProgress', IPC_CHANNELS.BLUEPRINT_PHASE_PROGRESS)
  forward(blueprintTasksService as unknown as EventEmitterLike, 'phaseComplete', IPC_CHANNELS.BLUEPRINT_PHASE_COMPLETE, 'tasks-event')
  forward(blueprintTasksService as unknown as EventEmitterLike, 'phaseArtifact', IPC_CHANNELS.BLUEPRINT_PHASE_ARTIFACT, 'tasks-event')
  forwardStatus(blueprintTasksService as unknown as EventEmitterLike)

  // ── BlueprintReviewService events (Phase 5: Review) ──
  forward(blueprintReviewService as unknown as EventEmitterLike, 'phaseStart', IPC_CHANNELS.BLUEPRINT_PHASE_START, 'review-event')
  forward(blueprintReviewService as unknown as EventEmitterLike, 'phaseProgress', IPC_CHANNELS.BLUEPRINT_PHASE_PROGRESS)
  forward(blueprintReviewService as unknown as EventEmitterLike, 'phaseComplete', IPC_CHANNELS.BLUEPRINT_PHASE_COMPLETE, 'review-event')
  forward(blueprintReviewService as unknown as EventEmitterLike, 'phaseArtifact', IPC_CHANNELS.BLUEPRINT_PHASE_ARTIFACT, 'review-event')
  forwardStatus(blueprintReviewService as unknown as EventEmitterLike)
  forward(blueprintReviewService as unknown as EventEmitterLike, 'approvalNeeded', IPC_CHANNELS.BLUEPRINT_APPROVAL_NEEDED, 'review-event')
  forward(blueprintReviewService as unknown as EventEmitterLike, 'preflightResult', IPC_CHANNELS.BLUEPRINT_PREFLIGHT_RESULT, 'review-event')

  // OS notification: Blueprint review complete — needs approval
  ;(blueprintReviewService as unknown as EventEmitterLike).on('approvalNeeded', (...args: unknown[]) => {
    try {
      const payload = args[0] as Record<string, unknown>
      const wsId = payload?.workspaceId as string | undefined
      if (!wsId) return
      notificationService.dispatch({
        workspaceId: wsId,
        workspaceName: resolveWorkspaceName(wsId),
        service: 'blueprint',
        status: 'needs_input',
        summary: 'Blueprint review complete — approve to start build',
        targetPage: 'blueprints',
        entityId: payload.blueprintId as string | undefined
      })
    } catch { /* non-fatal */ }
  })

  // ── BlueprintVerifyService events (Phase 7: Verify) ──
  forward(blueprintVerifyService as unknown as EventEmitterLike, 'phaseStart', IPC_CHANNELS.BLUEPRINT_PHASE_START, 'verify-event')
  forward(blueprintVerifyService as unknown as EventEmitterLike, 'phaseProgress', IPC_CHANNELS.BLUEPRINT_PHASE_PROGRESS)
  forward(blueprintVerifyService as unknown as EventEmitterLike, 'phaseComplete', IPC_CHANNELS.BLUEPRINT_PHASE_COMPLETE, 'verify-event')
  forward(blueprintVerifyService as unknown as EventEmitterLike, 'phaseArtifact', IPC_CHANNELS.BLUEPRINT_PHASE_ARTIFACT, 'verify-event')
  forwardStatus(blueprintVerifyService as unknown as EventEmitterLike)

  // OS notification: Blueprint phase completed or failed
  // Fires for all phases — summary is phase-aware.
  function buildBlueprintPhaseSummary(phase: string, status: string, payload: Record<string, unknown>): string {
    if (status !== 'complete') return `Blueprint ${phase} phase failed`
    switch (phase) {
      case 'specify': return 'Specification complete — moving to clarification'
      case 'clarify': return 'Clarification complete — moving to planning'
      case 'plan': return 'Plan complete — moving to task decomposition'
      case 'tasks': return 'Tasks generated — moving to review'
      case 'review': return 'Review complete — ready for build'
      case 'build': return `Build complete: ${(payload.completion as Record<string, unknown>)?.tasksCompleted ?? 0} tasks done`
      case 'verify': return 'Blueprint finished — all phases complete'
      default: return `Blueprint ${phase} phase complete`
    }
  }

  for (const svc of [
    blueprintSpecService as unknown as EventEmitterLike,
    blueprintPlanService as unknown as EventEmitterLike,
    blueprintTasksService as unknown as EventEmitterLike,
    blueprintReviewService as unknown as EventEmitterLike,
    blueprintBuildService as unknown as EventEmitterLike,
    blueprintVerifyService as unknown as EventEmitterLike
  ]) {
    svc.on('phaseComplete', (...args: unknown[]) => {
      try {
        const payload = args[0] as Record<string, unknown>
        const wsId = payload?.workspaceId as string | undefined
        if (!wsId) return
        // AUDIT-R2: remediation handoff is not a terminal completion — no notification
        if (payload.remediationTriggered === true) return
        // Skip 'skipped' status (e.g. clarify skip) — not interesting to notify
        if (payload.status === 'skipped') return
        const phase = payload.phase as string
        const status = payload.status as string
        notificationService.dispatch({
          workspaceId: wsId,
          workspaceName: resolveWorkspaceName(wsId),
          service: 'blueprint',
          status: status === 'complete' ? 'completed' : 'failed',
          summary: buildBlueprintPhaseSummary(phase, status, payload),
          targetPage: 'blueprints',
          entityId: payload.blueprintId as string | undefined
        })
      } catch { /* non-fatal */ }
    })
  }

  // ───────────────────────────────────────────────────────────────────────
  // M8: Journal writers — append events to blueprint_events table.
  // Best-effort: failures are logged but don't block the pipeline.
  // ───────────────────────────────────────────────────────────────────────

  function journalAppend(blueprintId: string, type: string, payload: Record<string, unknown>): void {
    try {
      blueprintEventRepository.append(
        blueprintId,
        type as 'system' | 'agent' | 'user' | 'findings' | 'qa' | 'plan' | 'tasks',
        payload
      )
    } catch (err) {
      bpLog.warn(`[journal] Failed to append ${type} event for ${blueprintId}:`, err)
    }
  }

  // Journal: phaseStart / phaseComplete → 'system' entries
  // Listen on all phase service emitters that emit phaseStart/phaseComplete
  const allPhaseEmitters = [
    blueprintService, blueprintSpecService, blueprintPlanService,
    blueprintTasksService, blueprintReviewService, blueprintBuildService,
    blueprintVerifyService
  ] as unknown as EventEmitterLike[]

  for (const emitter of allPhaseEmitters) {
    emitter.on('phaseStart', (...args: unknown[]) => {
      const payload = args[0] as Record<string, unknown>
      const bpId = payload?.blueprintId as string | undefined
      if (bpId) journalAppend(bpId, 'system', { event: 'phaseStart', phase: payload.phase })
    })
    emitter.on('phaseComplete', (...args: unknown[]) => {
      const payload = args[0] as Record<string, unknown>
      const bpId = payload?.blueprintId as string | undefined
      if (bpId) journalAppend(bpId, 'system', { event: 'phaseComplete', phase: payload.phase, status: payload.status, error: payload.error })
    })
  }

  // Journal: phaseArtifact → type-specific entries (plan, tasks, agent)
  for (const emitter of allPhaseEmitters) {
    emitter.on('phaseArtifact', (...args: unknown[]) => {
      const payload = args[0] as Record<string, unknown>
      const bpId = payload?.blueprintId as string | undefined
      const artifact = payload?.artifact as { type?: string; contentMd?: string } | undefined
      if (!bpId || !artifact) return
      const journalType = artifact.type === 'plan' ? 'plan'
        : artifact.type === 'tasks' ? 'tasks'
        : 'agent'
      // Phase 2: Include contentJson for plan/tasks so hydration avoids re-parsing
      const journalPayload: Record<string, unknown> = {
        phase: payload.phase,
        artifactType: artifact.type,
        contentMd: artifact.contentMd
      }
      if (artifact.type === 'plan' && artifact.contentMd) {
        try {
          const parsed = parseBlueprintPlan(artifact.contentMd)
          if (parsed) journalPayload.contentJson = parsed
        } catch { /* best effort */ }
      }
      if (artifact.type === 'tasks' && artifact.contentMd) {
        try {
          const parsed = parseBlueprintTasks(artifact.contentMd)
          if (parsed) journalPayload.contentJson = parsed
        } catch { /* best effort */ }
      }
      journalAppend(bpId, journalType, journalPayload)
    })
  }

  // Journal: clarify findings → 'findings' entries
  ;(blueprintSpecService as unknown as EventEmitterLike).on('clarifyFindings', (...args: unknown[]) => {
    const payload = args[0] as Record<string, unknown>
    const bpId = payload?.blueprintId as string | undefined
    if (bpId) journalAppend(bpId, 'findings', { findings: payload.findings })
  })

  // Journal: clarify questions → 'qa' entries
  ;(blueprintSpecService as unknown as EventEmitterLike).on('clarifyQuestions', (...args: unknown[]) => {
    const payload = args[0] as Record<string, unknown>
    const bpId = payload?.blueprintId as string | undefined
    if (bpId) journalAppend(bpId, 'qa', { questions: payload.questions })
  })

  // Journal: clarify gate → 'qa' entry
  ;(blueprintSpecService as unknown as EventEmitterLike).on('clarifyGateReady', (...args: unknown[]) => {
    const payload = args[0] as Record<string, unknown>
    const bpId = payload?.blueprintId as string | undefined
    if (bpId) journalAppend(bpId, 'qa', { event: 'gateReady', findings: payload.findings })
  })

  // Journal: wave markers → 'system' entries
  ;(blueprintBuildService as unknown as EventEmitterLike).on('waveStart', (...args: unknown[]) => {
    const payload = args[0] as Record<string, unknown>
    const bpId = payload?.blueprintId as string | undefined
    if (bpId) journalAppend(bpId, 'system', { event: 'waveStart', wave: payload.wave, taskCount: payload.taskCount })
  })
  ;(blueprintBuildService as unknown as EventEmitterLike).on('waveComplete', (...args: unknown[]) => {
    const payload = args[0] as Record<string, unknown>
    const bpId = payload?.blueprintId as string | undefined
    if (bpId) journalAppend(bpId, 'system', { event: 'waveComplete', wave: payload.wave, status: payload.status })
  })

  // ───────────────────────────────────────────────────────────────────────
  // M8b: Agent stream accumulator — extracted to blueprint-agent-accumulator.ts.
  // Buffers phaseProgress chunks into 'agent' journal entries.
  // Flushes at tool-activity boundaries and on phaseComplete.
  // Caps: 32KB per entry, ~1MB per (blueprintId, phase).
  // ───────────────────────────────────────────────────────────────────────

  const accumulator = createAccumulator(journalAppend)

  /** GAP-6 FIX: Flush + delete ALL accumulator entries for a given blueprintId. */
  accumulatorCleanup = (blueprintId: string): void => {
    accumulator.flushAllForBlueprint(blueprintId)
  }

  // Tap phaseProgress on all emitters for agent journaling
  for (const emitter of allPhaseEmitters) {
    emitter.on('phaseProgress', (...args: unknown[]) => {
      const payload = args[0] as Record<string, unknown>
      const bpId = payload?.blueprintId as string | undefined
      const phase = payload?.phase as string | undefined
      if (!bpId || !phase) return

      accumulator.handleChunk(
        bpId,
        phase,
        payload.kind as string | undefined,
        payload.text as string | undefined,
        payload.toolActivity as Record<string, unknown> | undefined,
        payload.taskId as string | undefined
      )
    })
  }

  // Flush accumulator on phaseComplete (including cancel/failure)
  for (const emitter of allPhaseEmitters) {
    emitter.on('phaseComplete', (...args: unknown[]) => {
      const payload = args[0] as Record<string, unknown>
      const bpId = payload?.blueprintId as string | undefined
      const phase = payload?.phase as string | undefined
      if (!bpId || !phase) return

      accumulator.flushAllForPhase(bpId, phase)
    })
  }

  // ── Auto-retry dispatch for transient phase failures ──
  // blueprintService.scheduleAutoRetry() emits 'autoRetry' after a 5s delay.
  // The IPC layer dispatches the phase start — same logic as the manual retry handler.
  blueprintService.on('autoRetry', (payload: {
    blueprintId: string
    workspaceId: string
    workspacePath: string
    phase: BlueprintPhaseType
  }) => {
    const { blueprintId, workspaceId, workspacePath, phase } = payload
    bpLog.info(`[auto-retry] Dispatching ${phase} for blueprint ${blueprintId}`)

    const phaseDispatch: Record<string, () => Promise<void>> = {
      specify: () => {
        const bp = blueprintService.getBlueprint(blueprintId)
        const grillDecisions = extractGrillDecisions(bp?.settingsJson as Record<string, unknown> | null)
        const referenceDocuments = extractReferenceDocuments(bp?.settingsJson as Record<string, unknown> | null)
        return blueprintSpecService.startSpecifyPhase({
          blueprintId, workspaceId, workspacePath,
          description: bp?.description ?? '',
          grillDecisions,
          referenceDocuments
        })
      },
      clarify: () => blueprintSpecService.startClarifyPhase({ blueprintId, workspaceId, workspacePath }),
      plan: () => blueprintPlanService.startPlanPhase({ blueprintId, workspaceId, workspacePath }),
      tasks: () => blueprintTasksService.startTasksPhase({ blueprintId, workspaceId, workspacePath }),
      review: () => blueprintReviewService.startReviewPhase({ blueprintId, workspaceId, workspacePath }),
      build: () => blueprintBuildService.startBuildPhase({ blueprintId, workspaceId, workspacePath }),
      verify: () => blueprintVerifyService.startVerifyPhase({ blueprintId, workspaceId, workspacePath })
    }

    const dispatch = phaseDispatch[phase]
    if (dispatch) {
      dispatch().catch((err) => {
        bpLog.error(`[auto-retry] ${phase} phase auto-retry failed:`, err)
      })
    } else {
      bpLog.error(`[auto-retry] Unknown phase: ${phase}`)
    }
  })

  // ── Remediation dispatch (gaps_found → rebuild → re-verify) ──
  // BP-REMEDIATION-01: blueprintVerifyService emits 'remediationNeeded' via deferred
  // dispatch (setImmediate after finally) when verification finds gaps and remediation
  // tasks are appended. Same dispatch pattern as autoRetry — build phase re-runs,
  // BP-RESUME-01 skips all complete tasks, only new remediation waves execute.
  ;(blueprintVerifyService as unknown as EventEmitterLike).on('remediationNeeded', (...args: unknown[]) => {
    const payload = args[0] as { blueprintId: string; workspaceId: string; workspacePath: string }
    const { blueprintId, workspaceId, workspacePath } = payload

    // BP-REMEDIATION-CANCEL-GUARD: Verify blueprint wasn't cancelled during
    // the deferred dispatch window before dispatching build.
    const blueprint = blueprintRepository.findById(blueprintId)
    if (!blueprint || blueprint.status === 'cancelled' || blueprint.status === 'failed') {
      bpLog.info(
        `[remediation] Skipping build dispatch — blueprint ${blueprintId} is ${blueprint?.status ?? 'missing'}`
      )
      return
    }

    // BP-REMEDIATION-PIPELINE-GUARD: If the pipeline is occupied, decide
    // based on WHICH blueprint owns it.
    if (blueprintService.isRunning(workspaceId)) {
      // Same blueprint already running (e.g. user clicked Resume during the
      // dispatch window) → skip silently. Do NOT mark it failed while it runs.
      if (blueprintService.getActiveBlueprintId(workspaceId) === blueprintId) {
        bpLog.info(`[remediation] Blueprint ${blueprintId} already running — skipping duplicate dispatch`)
        return
      }
      // A DIFFERENT blueprint took the pipeline → mark this one failed
      bpLog.warn(
        `[remediation] Pipeline occupied for workspace ${workspaceId} — ` +
        `cannot dispatch remediation build for blueprint ${blueprintId}. Marking failed.`
      )
      // Reset orphaned phase statuses from remediation setup
      // (verify set build='active', verify='pending' before releasing the pipeline)
      const buildPhase = blueprintPhaseRepository.findByBlueprintAndPhase(blueprintId, 'build')
      if (buildPhase?.status === 'active') {
        blueprintPhaseRepository.updateStatus(buildPhase.id, 'failed')
      }
      blueprintRepository.updateStatus(blueprintId, 'failed')
      return
    }

    bpLog.info(`[remediation] Dispatching build for remediation tasks — blueprint ${blueprintId}`)

    // REMEDIATION-JOURNAL: Record remediation dispatch in journal so hydrated
    // transcripts explain why a build phase restarted after verify.
    journalAppend(blueprintId, 'system', {
      event: 'remediationStart',
      message: 'Verification found gaps — dispatching remediation build'
    })

    blueprintBuildService.startBuildPhase({ blueprintId, workspaceId, workspacePath })
      .catch((err) => {
        bpLog.error(`[remediation] Build phase for remediation failed:`, err)
      })
  })
}

/**
 * Pure-logic functions extracted from blueprint.ipc.ts for testability.
 *
 * No Electron, no I/O, no service references — only computation over plain data.
 */

import type {
  BlueprintPhaseType,
  BlueprintPhase,
  GrillDecisionForBlueprint
} from '../../shared/blueprint-types'

// ── Valid Phase Set ──────────────────────────────────────────────────────────

/** The ordered set of valid blueprint phases. */
export const VALID_BLUEPRINT_PHASES: readonly BlueprintPhaseType[] = [
  'specify',
  'clarify',
  'plan',
  'tasks',
  'review',
  'build',
  'verify'
] as const

/**
 * Validate that a string is a valid BlueprintPhaseType.
 * Returns the typed value on success, null on failure.
 */
export function validateBlueprintPhase(phase: string): BlueprintPhaseType | null {
  return (VALID_BLUEPRINT_PHASES as readonly string[]).includes(phase)
    ? (phase as BlueprintPhaseType)
    : null
}

// ── Phase-to-Retry Selection ─────────────────────────────────────────────────

/**
 * Determine which phase to retry when a blueprint is in failed state.
 *
 * Priority: failed phase > active phase > currentPhase fallback.
 * Returns null if no candidate is found.
 */
export function selectPhaseToRetry(
  phases: BlueprintPhase[],
  currentPhase: BlueprintPhaseType | null
): BlueprintPhaseType | null {
  const failedPhase =
    phases.find((p) => p.status === 'failed') ?? phases.find((p) => p.status === 'active')
  return (failedPhase?.phase ?? currentPhase) as BlueprintPhaseType | null
}

// ── Grill Decision Extraction ────────────────────────────────────────────────

/**
 * Safely extract grill decisions from a blueprint's settingsJson.
 * Returns undefined when settingsJson is null/missing or has no grillDecisions.
 */
export function extractGrillDecisions(
  settingsJson: Record<string, unknown> | null | undefined
): GrillDecisionForBlueprint[] | undefined {
  if (!settingsJson) return undefined
  const decisions = settingsJson.grillDecisions
  if (!Array.isArray(decisions)) return undefined
  return decisions as GrillDecisionForBlueprint[]
}

// ── Reference Document Extraction ───────────────────────────────────────────

/** Inline type — matches the shape stored in settingsJson.referenceDocuments */
interface ReferenceDocument {
  type: string
  path: string
  name?: string
}

/**
 * Safely extract reference documents from a blueprint's settingsJson.
 * Validates each entry has a `path` string. Returns undefined when
 * settingsJson is null/missing or contains no valid documents.
 */
export function extractReferenceDocuments(
  settingsJson: Record<string, unknown> | null | undefined
): ReferenceDocument[] | undefined {
  if (!settingsJson) return undefined
  const docs = settingsJson.referenceDocuments
  if (!Array.isArray(docs)) return undefined
  const valid = docs.filter(
    (d) => d && typeof d === 'object' && typeof (d as { path?: unknown }).path === 'string'
  )
  return valid.length > 0 ? (valid as ReferenceDocument[]) : undefined
}

// ── Approval Response Action ─────────────────────────────────────────────────

export type ApprovalAction =
  | { kind: 'build' }
  | { kind: 'rewind'; toPhase: BlueprintPhaseType }

/**
 * Determine the action to take based on an approval response.
 * Approved → trigger build. Rejected → rewind to plan phase.
 */
export function determineApprovalAction(approved: boolean): ApprovalAction {
  return approved ? { kind: 'build' } : { kind: 'rewind', toPhase: 'plan' }
}

/**
 * Shared utility for resolving a workspace name from its ID.
 *
 * Uses lazy require() to avoid circular dependency with db/repositories.
 * Falls back to the first 8 characters of the workspace ID.
 */

export function resolveWorkspaceName(workspaceId: string): string {
  try {
    // eslint-disable-next-line @typescript-eslint/no-require-imports
    const { workspaceRepository } = require('../db/repositories')
    const ws = workspaceRepository.findById(workspaceId)
    return ws?.name ?? workspaceId.slice(0, 8)
  } catch {
    return workspaceId.slice(0, 8)
  }
}

/**
 * Blueprint Agent Accumulator — buffers phaseProgress stream chunks into
 * agent journal entries. Extracted from blueprint.ipc.ts for testability.
 *
 * Flushes at:
 * - Tool-activity boundaries (text → tool transition)
 * - phaseComplete events (flushAllForPhase)
 * - Cancel events (flushAllForBlueprint)
 *
 * Caps:
 * - 32KB per journal entry (AGENT_ENTRY_CHAR_CAP)
 * - ~1MB per (blueprintId, phase, taskId) lane (AGENT_PHASE_CHAR_CAP)
 *   NOTE: The cap is per-lane, not per-phase. With N parallel build agents,
 *   the total per build phase can reach ~N×1MB. This is bounded and accepted
 *   (6 agents ≈ 6MB worst case for one build phase).
 */

// ── Constants (exported for tests) ──

export const AGENT_ENTRY_CHAR_CAP = 32_768
export const AGENT_PHASE_CHAR_CAP = 1_048_576

// ── Types ──

export interface AgentAccumulator {
  text: string
  toolActivities: Array<Record<string, unknown>>
  phaseTotal: number
}

/** Callback shape for persisting flushed entries */
export type JournalAppendFn = (
  blueprintId: string,
  type: string,
  payload: Record<string, unknown>
) => void

// ── Factory ──

export interface AccumulatorInstance {
  /** Get or create the accumulator for a given key */
  getAccumulator(blueprintId: string, phase: string, taskId?: string): AgentAccumulator
  /** Flush the accumulator for a given key to the journal */
  flush(blueprintId: string, phase: string, taskId?: string): void
  /** Flush all keys matching blueprintId:phase (including taskId variants) */
  flushAllForPhase(blueprintId: string, phase: string): void
  /** Flush + delete ALL accumulator entries for a given blueprintId */
  flushAllForBlueprint(blueprintId: string): void
  /** Handle a phaseProgress event (text or tool chunk) */
  handleChunk(blueprintId: string, phase: string, kind: string | undefined, text?: string, toolActivity?: Record<string, unknown>, taskId?: string): void
}

/** Extended interface exposing internals for tests only */
export interface AccumulatorTestInstance extends AccumulatorInstance {
  readonly _accumulators: ReadonlyMap<string, AgentAccumulator>
}

/**
 * Create an accumulator instance wired to a journal-append function.
 * The IPC layer calls this once and wires the returned methods into
 * event handlers.
 */
export function createAccumulator(journalAppend: JournalAppendFn): AccumulatorInstance {
  const accumulators = new Map<string, AgentAccumulator>()

  function accKey(blueprintId: string, phase: string, taskId?: string): string {
    return taskId ? `${blueprintId}:${phase}:${taskId}` : `${blueprintId}:${phase}`
  }

  function getAccumulator(blueprintId: string, phase: string, taskId?: string): AgentAccumulator {
    const key = accKey(blueprintId, phase, taskId)
    let acc = accumulators.get(key)
    if (!acc) {
      acc = { text: '', toolActivities: [], phaseTotal: 0 }
      accumulators.set(key, acc)
    }
    return acc
  }

  function flush(blueprintId: string, phase: string, taskId?: string): void {
    const key = accKey(blueprintId, phase, taskId)
    const acc = accumulators.get(key)
    if (!acc || (!acc.text.trim() && acc.toolActivities.length === 0)) return

    // Cap per-entry text
    let content = acc.text
    if (content.length > AGENT_ENTRY_CHAR_CAP) {
      content = content.slice(0, AGENT_ENTRY_CHAR_CAP) + '\n\n[… truncated at 32KB]'
    }

    // Check per-phase cap
    if (acc.phaseTotal < AGENT_PHASE_CHAR_CAP) {
      journalAppend(blueprintId, 'agent', {
        phase,
        content,
        contentMd: content,
        toolActivities: acc.toolActivities,
        // Include taskId in payload so hydrated parallel-lane
        // bubbles retain lane identity.
        ...(taskId ? { taskId } : {})
      })
      acc.phaseTotal += content.length
    }

    // Reset accumulator text/tools but keep phaseTotal
    acc.text = ''
    acc.toolActivities = []
  }

  function flushAllForPhase(blueprintId: string, phase: string): void {
    for (const key of [...accumulators.keys()]) {
      if (key === `${blueprintId}:${phase}` || key.startsWith(`${blueprintId}:${phase}:`)) {
        const parts = key.split(':')
        flush(blueprintId, phase, parts[2])
        accumulators.delete(key)
      }
    }
  }

  function flushAllForBlueprint(blueprintId: string): void {
    for (const key of [...accumulators.keys()]) {
      if (key.startsWith(`${blueprintId}:`)) {
        const parts = key.split(':')
        const phase = parts[1]
        const taskId = parts[2] // may be undefined
        flush(blueprintId, phase, taskId)
        accumulators.delete(key)
      }
    }
  }

  function handleChunk(
    blueprintId: string,
    phase: string,
    kind: string | undefined,
    text?: string,
    toolActivity?: Record<string, unknown>,
    taskId?: string
  ): void {
    const acc = getAccumulator(blueprintId, phase, taskId)

    if (kind === 'tool') {
      // Tool event = boundary — flush text accumulated so far, then record tool
      if (acc.text.trim()) {
        flush(blueprintId, phase, taskId)
      }
      if (toolActivity) {
        acc.toolActivities.push(toolActivity)
      }
    } else {
      // Text chunk — accumulate
      if (text) acc.text += text
    }
  }

  return {
    getAccumulator,
    flush,
    flushAllForPhase,
    flushAllForBlueprint,
    handleChunk
  }
}

/**
 * IPC handlers for Workspace Health audits.
 *
 * Bridges the renderer ↔ AuditAgentService, persists results to the DB,
 * and forwards streaming events to the renderer via webContents.send().
 */

import type { BrowserWindow } from 'electron'
import { ipcMain, dialog } from 'electron'
import { writeFile } from 'node:fs/promises'
import { IPC_CHANNELS, AUDIT_TRACKS } from '../../shared/constants'
import type {
  AuditMode,
  AuditTrackId,
  AuditFinding,
  AuditRun,
  AuditPlanRecord,
  AuditSelectedSkills,
  LLMProvider,
  AgentStatus
} from '../../shared/types'
import type { StreamChunk } from '../services/agent-base.service'
import {
  formatDirectFindings,
  formatConsolidatedPlan,
  buildHandoffTitle
} from '../services/audit-handoff.service'
import { processToolChunk } from './tool-chunk-processor'
import { randomUUID } from 'node:crypto'
import { createTimedCleanupMap } from './listener-cleanup'
import {
  auditRepository,
  auditPlanRepository,
  conversationRepository,
  conversationSpecialistRepository,
  messageRepository,
  handoffRepository,
  specialistRepository
} from '../db/repositories'
import { workspaceRepository } from '../db/repositories'
import type { HandoffEnvelope } from '../../shared/handoff-types'
import { buildConversationModelSnapshot } from '../services/model-config.service'
import { auditPlanGeneratorService } from '../services/audit-plan-generator.service'
import { detectTechStack } from '../services/tech-stack-detector.service'
import {
  auditAgentService,
  type AuditProgressPayload,
  type AuditResultPayload,
  type AuditCompletePayload,
  type AuditIntermediateFindingsPayload
} from '../services/audit-agent.service'
import { getSessionEventRouter } from '../services/session-event-router'
import { validateSender } from './validate-sender'
import { notificationService } from '../services/notification.service'
import { resolveWorkspaceName } from './resolve-workspace-name'
import log from 'electron-log'

const auditLog = log.scope('audit-ipc')

// ── Public entry point ──────────────────────────────────────────────────────

export function registerAuditIpc(mainWindow: BrowserWindow): void {
  registerAuditLifecycleHandlers(mainWindow)
  registerAuditQueryHandlers(mainWindow)
  registerAuditExportHandlers(mainWindow)
  registerAuditHandoffHandlers(mainWindow)
}

// ── Lifecycle Handlers ──────────────────────────────────────────────────────

function registerAuditLifecycleHandlers(_mainWindow: BrowserWindow): void {
  // ── audit:start — start a new audit run ─────────────────────────────

  ipcMain.handle(
    IPC_CHANNELS.AUDIT_START,
    async (
      event,
      args: {
        workspaceId: string
        mode: AuditMode
        tracks: AuditTrackId[]
        llmProvider?: LLMProvider
        selectedSkills?: AuditSelectedSkills
      }
    ): Promise<AuditRun> => {
      validateSender(event)

      const { workspaceId, mode, tracks, llmProvider: explicitProvider, selectedSkills } = args

      if (auditAgentService.isRunning) {
        throw new Error('An audit is already running. Cancel it first.')
      }

      // Resolve workspace path
      const workspace = workspaceRepository.findById(workspaceId)
      if (!workspace) throw new Error(`Workspace ${workspaceId} not found`)
      if (!workspace.repoPath) throw new Error(`Workspace ${workspaceId} has no repo path`)

      // Detect tech stack
      const techResult = detectTechStack(workspace.repoPath)
      const detectedTechs = techResult.detectedTechs

      // Resolve LLM provider: explicit selection → workspace setting → 'claude'
      const settings = workspaceRepository.getSettings(workspaceId)
      const llmProvider: LLMProvider = explicitProvider ?? settings.llmProvider ?? 'claude'

      // Create new run in DB (deletes previous for this workspace)
      const run = auditRepository.createRun(
        workspaceId,
        mode,
        tracks,
        detectedTechs,
        selectedSkills ?? {}
      )
      const results = auditRepository.createResults(run.id, tracks)
      run.results = results

      auditLog.info(
        `[audit:start] workspaceId=${workspaceId} mode=${mode} tracks=${tracks.join(',')} provider=${llmProvider} runId=${run.id}`
      )

      // Wire event forwarding: auditAgentService → renderer + DB
      wireAuditEvents(run.id, workspaceId, workspace.repoPath)

      // Start the audit (non-blocking — runs in background)
      auditAgentService
        .runAudit({
          workspaceId,
          workspacePath: workspace.repoPath,
          mode,
          selectedTracks: tracks,
          auditRunId: run.id,
          llmProvider
        })
        .catch((err) => {
          auditLog.error('[audit:start] runAudit failed:', err)
        })

      // Update run status to 'running'
      auditRepository.updateRun(run.id, { status: 'running' })
      run.status = 'running'

      return run
    }
  )

  // ── audit:cancel — abort running audit ──────────────────────────────

  ipcMain.handle(IPC_CHANNELS.AUDIT_CANCEL, (event): void => {
    validateSender(event)
    auditAgentService.cancel()
  })

  // ── audit:rerunTrack — re-run a single auditor ──────────────────────

  ipcMain.handle(
    IPC_CHANNELS.AUDIT_RERUN_TRACK,
    async (
      event,
      args: { workspaceId: string; trackId: AuditTrackId; mode: AuditMode }
    ): Promise<void> => {
      validateSender(event)

      const { workspaceId, trackId, mode } = args

      if (auditAgentService.isRunning) {
        throw new Error('An audit is already running. Cancel it first.')
      }

      const workspace = workspaceRepository.findById(workspaceId)
      if (!workspace) throw new Error(`Workspace ${workspaceId} not found`)
      if (!workspace.repoPath) throw new Error(`Workspace ${workspaceId} has no repo path`)

      // Find the latest run for this workspace
      const latestRun = auditRepository.getLatestForWorkspace(workspaceId)
      if (!latestRun) throw new Error('No audit run found for workspace')

      auditLog.info(`[audit:rerunTrack] trackId=${trackId} mode=${mode} runId=${latestRun.id}`)

      // Wire event forwarding for this single-track run
      wireAuditEvents(latestRun.id, workspaceId, workspace.repoPath)

      auditAgentService
        .runSingleTrack({
          workspaceId,
          workspacePath: workspace.repoPath,
          trackId,
          mode
        })
        .then(() => {
          // Recalculate overall score after single track re-run
          const results = auditRepository.findResultsByRunId(latestRun.id)
          // Exclude insufficient-coverage tracks — mirrors calculateOverallScore.
          const completed = results.filter(
            (r) => r.status === 'completed' && r.score !== null && r.coverageSufficient !== false
          )
          const hasFailed = results.some((r) => r.status === 'failed')

          let newOverall: number | null = null
          if (completed.length > 0) {
            let weightedSum = 0
            let totalWeight = 0
            for (const r of completed) {
              const w = AUDIT_TRACKS[r.trackId]?.weight ?? 1.0
              weightedSum += (r.score ?? 0) * w
              totalWeight += w
            }
            newOverall = Math.round(weightedSum / totalWeight)
          }

          // Update status — 'partial' if any track failed, 'completed' if all succeeded
          const newStatus = hasFailed ? 'partial' : 'completed'
          const updatedRun = auditRepository.updateRun(latestRun.id, {
            overallScore: newOverall ?? undefined,
            status: newStatus
          })
          if (updatedRun) {
            try {
              const router = getSessionEventRouter()
              router.sendWorkspaceEvent(
                IPC_CHANNELS.AUDIT_COMPLETE,
                workspaceId,
                updatedRun as unknown as Record<string, unknown>
              )
            } catch {
              /* router may not be initialized */
            }
          }
        })
        .catch((err) => {
          auditLog.error('[audit:rerunTrack] failed:', err)
        })
    }
  )

  // ── audit:resume — resume an interrupted audit (re-run only incomplete tracks) ──

  ipcMain.handle(
    IPC_CHANNELS.AUDIT_RESUME,
    async (event, args: { workspaceId: string }): Promise<AuditRun | null> => {
      validateSender(event)

      if (auditAgentService.isRunning) {
        throw new Error('An audit is already running.')
      }

      const workspace = workspaceRepository.findById(args.workspaceId)
      if (!workspace) throw new Error(`Workspace ${args.workspaceId} not found`)
      if (!workspace.repoPath) throw new Error(`Workspace ${args.workspaceId} has no repo path`)

      const run = auditRepository.getLatestForWorkspace(args.workspaceId)
      if (!run) throw new Error('No audit run found to resume')

      // Only tracks that didn't complete successfully are resumable
      const resumableTracks = run.results
        .filter((r) => r.status === 'cancelled' || r.status === 'pending' || r.status === 'failed')
        .map((r) => r.trackId)

      if (resumableTracks.length === 0) {
        throw new Error('All tracks are already completed — nothing to resume')
      }

      auditLog.info(
        `[audit:resume] runId=${run.id} resuming ${resumableTracks.length} tracks: ${resumableTracks.join(',')}`
      )

      // Reset resumable track results back to 'pending'
      for (const result of run.results) {
        if (resumableTracks.includes(result.trackId)) {
          auditRepository.updateResult(result.id, { status: 'pending' })
          result.status = 'pending' as typeof result.status
        }
      }

      // Update run status back to 'running'
      auditRepository.updateRun(run.id, { status: 'running' })
      run.status = 'running'

      // Wire events and start — same as audit:start but targeting only incomplete tracks
      wireAuditEvents(run.id, args.workspaceId, workspace.repoPath)

      auditAgentService
        .runAudit({
          workspaceId: args.workspaceId,
          workspacePath: workspace.repoPath,
          mode: run.mode,
          selectedTracks: resumableTracks,
          auditRunId: run.id
        })
        .catch((err) => {
          auditLog.error('[audit:resume] runAudit failed:', err)
        })

      return run
    }
  )
}

// ── Query Handlers ──────────────────────────────────────────────────────────

function registerAuditQueryHandlers(mainWindow: BrowserWindow): void {
  void mainWindow // used by lifecycle/export groups — kept for signature consistency

  // ── audit:getLatest — load latest audit results ─────────────────────

  ipcMain.handle(
    IPC_CHANNELS.AUDIT_GET_LATEST,
    (event, args: { workspaceId: string }): AuditRun | null => {
      validateSender(event)
      const run = auditRepository.getLatestForWorkspace(args.workspaceId)

      // Reconcile stale "running" state after app restart.
      // If the DB says the audit is running but the agent process isn't,
      // the previous run was interrupted — mark incomplete tracks as cancelled.
      if (run && run.status === 'running' && !auditAgentService.isRunning) {
        auditLog.warn(
          `[audit:getLatest] Stale running audit detected (runId=${run.id}) — reconciling`
        )

        for (const result of run.results) {
          if (result.status === 'running' || result.status === 'pending') {
            auditRepository.updateResult(result.id, { status: 'cancelled' })
            result.status = 'cancelled' as typeof result.status
          }
        }

        const hasCompleted = run.results.some((r) => r.status === 'completed')
        const finalStatus = hasCompleted ? 'partial' : 'cancelled'
        const updated = auditRepository.updateRun(run.id, {
          status: finalStatus as 'completed' | 'partial' | 'cancelled'
        })
        return updated ?? run
      }

      return run
    }
  )

  // ── audit:getHistory — get recent audit runs ──────────────────────

  ipcMain.handle(
    IPC_CHANNELS.AUDIT_GET_HISTORY,
    (event, args: { workspaceId: string; limit?: number }): AuditRun[] => {
      validateSender(event)
      return auditRepository.getHistoryForWorkspace(args.workspaceId, args.limit ?? 10)
    }
  )

  // ── audit:deleteRun — delete a single past run ──────────────────────

  ipcMain.handle(
    IPC_CHANNELS.AUDIT_DELETE_RUN,
    (event, args: { runId: string }): { deleted: boolean } => {
      validateSender(event)
      const deleted = auditRepository.deleteRun(args.runId)
      auditLog.info(`[audit:deleteRun] runId=${args.runId} deleted=${deleted}`)
      return { deleted }
    }
  )

  // ── audit:generatePlan — synthesize a remediation plan from findings ──

  ipcMain.handle(
    IPC_CHANNELS.AUDIT_GENERATE_PLAN,
    async (
      event,
      args: { workspaceId: string; runId: string; findings: AuditFinding[] }
    ): Promise<AuditPlanRecord> => {
      validateSender(event)
      auditLog.info(`[audit:generatePlan] runId=${args.runId} findings=${args.findings.length}`)
      return auditPlanGeneratorService.generate({
        workspaceId: args.workspaceId,
        runId: args.runId,
        findings: args.findings
      })
    }
  )

  // ── audit:getPlans — list plans persisted for a run ──

  ipcMain.handle(
    IPC_CHANNELS.AUDIT_GET_PLANS,
    (event, args: { runId: string }): AuditPlanRecord[] => {
      validateSender(event)
      return auditPlanRepository.getPlansForRun(args.runId)
    }
  )
}

// ── Export Helpers ──────────────────────────────────────────────────────────

async function saveMarkdownFile(
  mainWindow: BrowserWindow,
  markdown: string,
  defaultPath: string,
  title: string,
  logLabel: string
): Promise<void> {
  const { canceled, filePath } = await dialog.showSaveDialog(mainWindow, {
    title,
    defaultPath,
    filters: [{ name: 'Markdown', extensions: ['md'] }]
  })
  if (canceled || !filePath) return
  await writeFile(filePath, markdown, 'utf-8')
  auditLog.info(`[${logLabel}] Exported to ${filePath}`)
}

// ── Export Handlers ─────────────────────────────────────────────────────────

function registerAuditExportHandlers(mainWindow: BrowserWindow): void {
  // ── audit:convertFindings — create plan-mode conversation from findings

  ipcMain.handle(
    IPC_CHANNELS.AUDIT_CONVERT_FINDINGS,
    (
      event,
      args: { workspaceId: string; findings: AuditFinding[] }
    ): { conversationId: string } => {
      validateSender(event)

      const { workspaceId, findings } = args

      // Read workspace LLM provider for conversation creation
      const wsSettings = workspaceRepository.getSettings(workspaceId)
      const llmProvider: LLMProvider = wsSettings.llmProvider ?? 'claude'

      // Create conversation in plan mode with frozen model snapshot
      const title = `🔍 Audit: Fix ${findings.length} finding${findings.length > 1 ? 's' : ''}`
      const snapshot = buildConversationModelSnapshot(workspaceId, llmProvider)
      const conv = conversationRepository.create(
        workspaceId,
        title,
        'plan',
        undefined,
        llmProvider,
        undefined,
        undefined,
        undefined,
        snapshot
      )

      // Build a structured first message with all findings as context
      const findingsContext = findings
        .map(
          (f, i) =>
            `### ${i + 1}. [${f.severity.toUpperCase()}] ${f.title}\n${f.description}` +
            (f.filePath ? `\n**File:** \`${f.filePath}\`` : '') +
            (f.recommendation ? `\n**Recommendation:** ${f.recommendation}` : '')
        )
        .join('\n\n')

      const contextMessage = `The following audit findings need to be addressed:\n\n${findingsContext}\n\nPlease analyze these findings and propose a plan to fix them.`

      // Insert as first user message
      messageRepository.create(conv.id, 'user', contextMessage)

      auditLog.info(
        `[audit:convert] Created conversation ${conv.id} with ${findings.length} findings`
      )

      return { conversationId: conv.id }
    }
  )

  // ── audit:handoffToChat — create conversation(s) from audit findings ──
  // (Moved to registerAuditHandoffHandlers below)

  // ── audit:exportMarkdown — export latest audit as Markdown ─────────

  ipcMain.handle(
    IPC_CHANNELS.AUDIT_EXPORT_MARKDOWN,
    async (event, args: { workspaceId: string }): Promise<void> => {
      validateSender(event)

      const run = auditRepository.getLatestForWorkspace(args.workspaceId)
      if (!run) throw new Error('No audit run found for this workspace')

      const workspace = workspaceRepository.findById(args.workspaceId)
      const workspaceName = workspace?.name ?? 'Unknown Workspace'

      // Build Markdown
      const date = new Date(run.createdAt).toLocaleDateString('en-US', {
        month: 'long',
        day: 'numeric',
        year: 'numeric'
      })

      const lines: string[] = [
        `# Workspace Health Report`,
        `**Workspace:** ${workspaceName} | **Mode:** ${run.mode === 'light' ? 'Light' : 'Deep'} | **Date:** ${date} | **Overall Score:** ${run.overallScore ?? '—'}/100`,
        ''
      ]

      for (const trackId of run.selectedTracks) {
        const track = AUDIT_TRACKS[trackId]
        const result = run.results.find((r) => r.trackId === trackId)
        if (!track || !result) continue

        lines.push(`## ${track.name} — ${result.score ?? '—'}/100`)
        if (result.summary) {
          lines.push(result.summary)
        }
        lines.push('')

        if (result.findings.length > 0) {
          lines.push('### Findings')
          lines.push('| Severity | Title | File | Recommendation |')
          lines.push('|----------|-------|------|----------------|')
          for (const f of result.findings) {
            lines.push(
              `| ${f.severity.toUpperCase()} | ${f.title} | ${f.filePath ?? '—'} | ${f.recommendation ?? '—'} |`
            )
          }
          lines.push('')
        }
      }

      const markdown = lines.join('\n')

      await saveMarkdownFile(
        mainWindow,
        markdown,
        `health-report-${new Date().toISOString().slice(0, 10)}.md`,
        'Export Audit Report',
        'audit:export'
      )
    }
  )

  // ── audit:exportPlanMarkdown — export the remediation plan as Markdown ───

  ipcMain.handle(
    IPC_CHANNELS.AUDIT_EXPORT_PLAN_MARKDOWN,
    async (event, args: { workspaceId: string }): Promise<void> => {
      validateSender(event)

      const run = auditRepository.getLatestForWorkspace(args.workspaceId)
      if (!run) throw new Error('No audit run found for this workspace')

      const plans = auditPlanRepository.getPlansForRun(run.id)
      if (plans.length === 0) throw new Error('No remediation plan found for this audit run')

      const planRecord = plans[0]
      const plan = planRecord.plan

      // If the plan has a requirementDocument, export that directly
      if (plan.requirementDocument?.trim()) {
        await saveMarkdownFile(
          mainWindow,
          plan.requirementDocument,
          `remediation-plan-${new Date().toISOString().slice(0, 10)}.md`,
          'Export Remediation Plan',
          'audit:exportPlan'
        )
        return
      }

      // Fallback: build structured markdown from plan items
      const workspace = workspaceRepository.findById(args.workspaceId)
      const workspaceName = workspace?.name ?? 'Unknown Workspace'
      const date = new Date(planRecord.createdAt).toLocaleDateString('en-US', {
        month: 'long',
        day: 'numeric',
        year: 'numeric'
      })

      const lines: string[] = [
        `# ${plan.title}`,
        '',
        `**Workspace:** ${workspaceName} | **Date:** ${date} | **Items:** ${plan.items.length} | **Findings addressed:** ${plan.sourceFindingIds.length}`,
        '',
        plan.summary,
        ''
      ]

      for (let i = 0; i < plan.items.length; i++) {
        const item = plan.items[i]
        const severity = item.severity ? ` \`${item.severity.toUpperCase()}\`` : ''
        lines.push(`## ${i + 1}. ${item.title}${severity}`)
        lines.push('')
        lines.push(`**Scope:** ${item.scope}`)
        lines.push('')
        lines.push(item.description)
        lines.push('')
        if (item.recommendation) {
          lines.push(`> 💡 ${item.recommendation}`)
          lines.push('')
        }
        if (item.files.length > 0) {
          lines.push(`**Files:** ${item.files.map((f) => '`' + f + '`').join(', ')}`)
          lines.push('')
        }
        if (item.dependsOn && item.dependsOn.length > 0) {
          lines.push(`**Depends on:** ${item.dependsOn.join(', ')}`)
          lines.push('')
        }
      }

      if (plan.risks.length > 0) {
        lines.push('## ⚠️ Risks')
        lines.push('')
        for (const risk of plan.risks) {
          lines.push(`- ${risk}`)
        }
        lines.push('')
      }

      const markdown = lines.join('\n')

      await saveMarkdownFile(
        mainWindow,
        markdown,
        `remediation-plan-${new Date().toISOString().slice(0, 10)}.md`,
        'Export Remediation Plan',
        'audit:exportPlan'
      )
    }
  )
}

// ── Handoff Handlers (Audit → Chat) ─────────────────────────────────────────

function registerAuditHandoffHandlers(_mainWindow: BrowserWindow): void {
  ipcMain.handle(
    IPC_CHANNELS.AUDIT_HANDOFF_TO_CHAT,
    (
      event,
      args: {
        workspaceId: string
        auditRunId: string
        trackIds?: AuditTrackId[]
        mode: 'consolidated' | 'split'
      }
    ): { conversationIds: string[]; count: number } => {
      validateSender(event)

      const { workspaceId, auditRunId, trackIds, mode } = args

      // Load the audit run with results
      const run = auditRepository.findRunById(auditRunId)
      if (!run || run.workspaceId !== workspaceId) {
        throw new Error(`Audit run ${auditRunId} not found for workspace ${workspaceId}`)
      }

      // Filter to requested tracks (or all completed with actionable findings)
      const completedResults = run.results.filter(
        (r) =>
          r.status === 'completed' &&
          r.findings.some((f) => f.severity !== 'info') &&
          (!trackIds || trackIds.includes(r.trackId))
      )

      if (completedResults.length === 0) {
        throw new Error('No completed results with actionable findings')
      }

      const wsSettings = workspaceRepository.getSettings(workspaceId)
      const llmProvider: LLMProvider = wsSettings.llmProvider ?? 'claude'
      const conversationIds: string[] = []

      if (mode === 'split') {
        // Create one conversation per track.
        // NOTE: Split-flow conversations are created with the findings as a user message
        // but do NOT auto-trigger an LLM response. The user clicks into a conversation
        // and sends a follow-up message (e.g. "Fix these") to engage the LLM.
        for (const result of completedResults) {
          const actionableCount = result.findings.filter((f) => f.severity !== 'info').length
          const title = buildHandoffTitle('split', result.trackId, actionableCount)
          const contextMessage = formatDirectFindings(result)
          const snapshot = buildConversationModelSnapshot(workspaceId, llmProvider)

          const conv = conversationRepository.create(
            workspaceId,
            title,
            'plan',
            undefined,
            llmProvider,
            undefined,
            undefined,
            undefined,
            snapshot,
            auditRunId
          )

          // Initialize specialist defaults (mirrors conversation-crud.ipc.ts)
          conversationSpecialistRepository.initFromWorkspaceDefaults(conv.id)
          try {
            const projectSpecialist = specialistRepository.findByAgentId(
              `workspace-specialist-${workspaceId}`
            )
            if (projectSpecialist) {
              conversationSpecialistRepository.upsert(conv.id, projectSpecialist.id, {
                isActive: true
              })
            }
          } catch (e) {
            auditLog.warn('Project Specialist auto-attach failed:', e)
          }

          messageRepository.create(conv.id, 'user', contextMessage)
          conversationIds.push(conv.id)

          // Record handoff event
          const envelope: HandoffEnvelope = {
            id: randomUUID(),
            version: 1,
            source: 'audit',
            target: 'chat',
            workspaceId,
            intent: `Fix ${actionableCount} ${result.trackId} audit finding(s)`,
            originalGoal: title,
            contextSummary: `Audit findings from ${result.trackId} track (score: ${result.score ?? 'N/A'}/100)`,
            completedWork: [],
            remainingWork: result.findings
              .filter((f) => f.severity !== 'info')
              .map((f) => ({
                title: f.title,
                description: f.description,
                priority: f.severity === 'critical' ? 'critical' : f.severity === 'high' ? 'high' : 'medium'
              })),
            decisions: [],
            constraints: [],
            risks: [],
            artifacts: [{ type: 'finding', path: auditRunId, description: `Audit run ${auditRunId}` }],
            suggestedTools: [],
            suggestedSkills: [],
            filesToReadFirst: result.findings
              .filter((f) => f.filePath)
              .map((f) => f.filePath!)
              .slice(0, 10),
            commandsToRunFirst: [],
            sourceSessionId: auditRunId,
            confidence: 0.8,
            priority: 'medium',
            createdAt: new Date().toISOString(),
            createdBy: 'user'
          }
          handoffRepository.create(envelope)
        }

        auditLog.info(
          `[audit:handoff] Split: created ${conversationIds.length} conversations from run ${auditRunId}`
        )
      } else {
        // Consolidated: single conversation with all findings
        const totalIssues = completedResults.flatMap((r) =>
          r.findings.filter((f) => f.severity !== 'info')
        ).length
        const title = buildHandoffTitle('consolidated', undefined, totalIssues)
        const contextMessage = formatConsolidatedPlan(run)
        const snapshot = buildConversationModelSnapshot(workspaceId, llmProvider)

        const conv = conversationRepository.create(
          workspaceId,
          title,
          'plan',
          undefined,
          llmProvider,
          undefined,
          undefined,
          undefined,
          snapshot,
          auditRunId
        )

        // Initialize specialist defaults (mirrors conversation-crud.ipc.ts)
        conversationSpecialistRepository.initFromWorkspaceDefaults(conv.id)
        try {
          const projectSpecialist = specialistRepository.findByAgentId(
            `workspace-specialist-${workspaceId}`
          )
          if (projectSpecialist) {
            conversationSpecialistRepository.upsert(conv.id, projectSpecialist.id, {
              isActive: true
            })
          }
        } catch (e) {
          auditLog.warn('Project Specialist auto-attach failed:', e)
        }

        messageRepository.create(conv.id, 'user', contextMessage)
        conversationIds.push(conv.id)

        // Record handoff event
        const envelope: HandoffEnvelope = {
          id: randomUUID(),
          version: 1,
          source: 'audit',
          target: 'chat',
          workspaceId,
          intent: `Fix ${totalIssues} audit finding(s) across ${completedResults.length} auditor(s)`,
          originalGoal: title,
          contextSummary: `Consolidated audit health report (overall score: ${run.overallScore ?? 'N/A'}/100)`,
          completedWork: [],
          remainingWork: completedResults.flatMap((r) =>
            r.findings
              .filter((f) => f.severity !== 'info')
              .map((f) => ({
                title: f.title,
                description: f.description,
                priority: f.severity === 'critical' ? 'critical' : f.severity === 'high' ? 'high' : 'medium' as const
              }))
          ),
          decisions: [],
          constraints: [],
          risks: [],
          artifacts: [{ type: 'finding', path: auditRunId, description: `Audit run ${auditRunId}` }],
          suggestedTools: [],
          suggestedSkills: [],
          filesToReadFirst: completedResults
            .flatMap((r) => r.findings.filter((f) => f.filePath).map((f) => f.filePath!))
            .slice(0, 10),
          commandsToRunFirst: [],
          sourceSessionId: auditRunId,
          confidence: 0.8,
          priority: 'medium',
          createdAt: new Date().toISOString(),
          createdBy: 'user'
        }
        handoffRepository.create(envelope)

        auditLog.info(
          `[audit:handoff] Consolidated: created conversation ${conv.id} from run ${auditRunId}`
        )
      }

      return { conversationIds, count: conversationIds.length }
    }
  )
}

// ── Event Forwarding ────────────────────────────────────────────────────────

/**
 * Wire one-time event listeners for the current audit run.
 * Forwards progress/result/complete to the renderer and persists to DB.
 */
/** Per-workspace listener cleanup functions. */
const auditCleanup = createTimedCleanupMap('audit')

function wireAuditEvents(runId: string, workspaceId: string, workspacePath: string): void {
  const cleanups = auditCleanup.prepareCleanups(workspaceId)
  // Lazy router resolution

  // ── progress ──
  auditCleanup.addListener<AuditProgressPayload>(
    cleanups,
    auditAgentService,
    'progress',
    (data) => {
      // Update result row status when it transitions to 'running' or 'cancelled'
      if (data.status === 'running' || data.status === 'cancelled') {
        const resultRow = auditRepository.findResultByTrack(runId, data.trackId)
        if (resultRow) {
          auditRepository.updateResult(resultRow.id, {
            status: data.status,
            ...(data.status === 'running' ? { startedAt: new Date().toISOString() } : {})
          })
        }
      }

      getSessionEventRouter().sendWorkspaceEvent(
        IPC_CHANNELS.AUDIT_PROGRESS,
        workspaceId,
        data as unknown as Record<string, unknown>
      )
    }
  )

  // ── result ──
  auditCleanup.addListener<AuditResultPayload>(cleanups, auditAgentService, 'result', (data) => {
    // Persist to DB (including coverage data)
    const resultRow = auditRepository.findResultByTrack(runId, data.trackId)
    if (resultRow) {
      auditRepository.updateResult(resultRow.id, {
        status: data.status,
        score: data.score,
        findings: data.findings,
        summary: data.summary,
        skillsUsed: data.skillsUsed,
        completedAt: new Date().toISOString(),
        coverageStats: data.coverageStats,
        coverageSufficient: data.coverageSufficient
      })
    }

    // Forward to renderer
    const updatedResult = resultRow ? auditRepository.findResultById(resultRow.id) : null
    if (updatedResult) {
      getSessionEventRouter().sendWorkspaceEvent(
        IPC_CHANNELS.AUDIT_RESULT,
        workspaceId,
        updatedResult as unknown as Record<string, unknown>
      )
    }
  })

  // ── intermediate findings — live accumulation during multi-round ──
  auditCleanup.addListener<AuditIntermediateFindingsPayload>(
    cleanups,
    auditAgentService,
    'intermediate_findings',
    (data) => {
      // Persist partial findings to DB for crash resilience
      const resultRow = auditRepository.findResultByTrack(runId, data.trackId)
      if (resultRow) {
        auditRepository.updateResult(resultRow.id, {
          findings: data.findings,
          summary: `Round ${data.roundNumber}: ${data.findings.length} finding(s), ${data.coverageStats.fileCount} files inspected`,
          coverageStats: data.coverageStats
        })
      }

      // Forward to renderer for live display
      getSessionEventRouter().sendWorkspaceEvent(IPC_CHANNELS.AUDIT_INTERMEDIATE, workspaceId, {
        trackId: data.trackId,
        findings: data.findings,
        coverageStats: data.coverageStats,
        roundNumber: data.roundNumber,
        totalRounds: data.totalRounds,
        totalFiles: data.totalFiles,
        batchSize: data.batchSize
      })
    }
  )

  // ── complete ──
  auditCleanup.addListener<AuditCompletePayload>(
    cleanups,
    auditAgentService,
    'complete',
    (data) => {
      // Determine final run status
      const results = auditRepository.findResultsByRunId(runId)
      const hasFailed = results.some((r) => r.status === 'failed')
      const hasCancelled = results.some((r) => r.status === 'cancelled')

      let finalStatus: 'completed' | 'partial' | 'cancelled' = 'completed'
      if (hasCancelled && !results.some((r) => r.status === 'completed')) {
        finalStatus = 'cancelled'
      } else if (hasFailed || hasCancelled) {
        finalStatus = 'partial'
      }

      const updatedRun = auditRepository.updateRun(runId, {
        status: finalStatus,
        overallScore: data.overallScore
      })

      if (updatedRun) {
        getSessionEventRouter().sendWorkspaceEvent(
          IPC_CHANNELS.AUDIT_COMPLETE,
          workspaceId,
          updatedRun as unknown as Record<string, unknown>
        )
      }

      // Skip user-initiated cancellations — no notification needed
      if (finalStatus !== 'cancelled') {
        notificationService.dispatch({
          workspaceId,
          workspaceName: resolveWorkspaceName(workspaceId),
          service: 'audit',
          status: 'completed',
          summary: finalStatus === 'partial'
            ? `Audit finished (partial) — overall score: ${data.overallScore ?? 'N/A'}`
            : `Audit completed — overall score: ${data.overallScore ?? 'N/A'}`,
          targetPage: 'audit'
        })
      }

      auditLog.info(
        `[audit:complete] runId=${runId} status=${finalStatus} overallScore=${data.overallScore}`
      )

      auditCleanup.runCleanup(workspaceId)
    }
  )

  // ── stream — rich chunk forwarding for chat-like audit view ──
  auditCleanup.addListener<{ trackId: AuditTrackId; chunk: StreamChunk }>(
    cleanups,
    auditAgentService,
    'stream',
    (data) => {
      processAuditStreamChunk(getSessionEventRouter(), workspaceId, workspacePath, data.trackId, data.chunk)
    }
  )

  // ── status — forward live token/context counters to the renderer ──
  auditCleanup.addListener<{ workspaceId?: string; status: AgentStatus }>(
    cleanups,
    auditAgentService,
    'status',
    (data) => {
      if (data.workspaceId && data.workspaceId !== workspaceId) return
      getSessionEventRouter().sendWorkspaceEvent(IPC_CHANNELS.AGENT_STATUS_UPDATE, workspaceId, { ...data.status })
    }
  )

  // Safety net: auto-clean listeners after 90 min (multi-track sequential execution)
  auditCleanup.scheduleAutoCleanup(workspaceId, cleanups, 90 * 60_000)
}

// ── Stream chunk processing ─────────────────────────────────────────────────

/**
 * Process a single stream chunk from the audit agent and forward it to the renderer.
 * Handles text, tool_use, tool_result, and tool_progress chunk types.
 */
import type { SessionEventRouter } from '../services/session-event-router'

function processAuditStreamChunk(
  router: SessionEventRouter,
  workspaceId: string,
  workspacePath: string,
  trackId: AuditTrackId,
  chunk: StreamChunk
): void {
  if (chunk.type === 'text' && chunk.content) {
    router.sendWorkspaceEvent(IPC_CHANNELS.AUDIT_STREAM_CHUNK, workspaceId, {
      trackId,
      type: 'text',
      content: chunk.content
    })
    return
  }

  if (chunk.type === 'tool_use' || chunk.type === 'tool_result' || chunk.type === 'tool_progress') {
    const result = processToolChunk(chunk, {
      workspacePath,
      agentType: 'audit',
      workspaceId,
      formatTagsToSkip: ['audit-finding', 'audit-score']
    })
    if (result) {
      router.sendWorkspaceEvent(IPC_CHANNELS.AUDIT_STREAM_CHUNK, workspaceId, {
        trackId,
        ...result
      })
    }
  }
}

/**
 * audit-handoff.service — Formats audit findings into markdown context
 * for Audit → Chat handoff conversations.
 *
 * Two formatters:
 *  - formatDirectFindings: single-track with full detail (direct mode)
 *  - formatConsolidatedPlan: multi-track overview (plan mode)
 */

import { AUDIT_TRACKS } from '../../shared/constants'
import type { AuditRun, AuditTrackId, AuditFinding, AuditResult } from '../../shared/types'

const SEVERITY_ORDER: Record<string, number> = {
  critical: 0,
  high: 1,
  medium: 2,
  low: 3,
  info: 4
}

/** Maximum findings to include inline per track to avoid oversized messages. */
const MAX_FINDINGS_PER_TRACK = 30

function sortBySeverity(findings: AuditFinding[]): AuditFinding[] {
  return [...findings].sort(
    (a, b) => (SEVERITY_ORDER[a.severity] ?? 5) - (SEVERITY_ORDER[b.severity] ?? 5)
  )
}

/**
 * Format findings from a single track with full detail.
 * Used when the handoff is for one auditor — gives the LLM
 * direct actionable context.
 */
export function formatDirectFindings(result: AuditResult): string {
  const track = AUDIT_TRACKS[result.trackId]
  const trackName = track?.name ?? result.trackId
  const actionable = result.findings.filter((f) => f.severity !== 'info')
  const sorted = sortBySeverity(actionable)

  const lines: string[] = [
    `# 🔍 Audit Findings: ${trackName}`,
    '',
    `**Score:** ${result.score != null ? `${result.score}/100` : 'N/A'} | **${sorted.length} issue${sorted.length !== 1 ? 's' : ''} found**`,
    '',
    '## Issues to Fix',
    ''
  ]

  const capped = sorted.slice(0, MAX_FINDINGS_PER_TRACK)
  for (let i = 0; i < capped.length; i++) {
    const f = capped[i]
    lines.push(`### ${i + 1}. [${f.severity.toUpperCase()}] ${f.title}`)
    lines.push(f.description)
    if (f.filePath) lines.push(`**File:** \`${f.filePath}\``)
    if (f.recommendation) lines.push(`**Recommendation:** ${f.recommendation}`)
    lines.push('')
  }
  if (sorted.length > MAX_FINDINGS_PER_TRACK) {
    lines.push(
      `*…and ${sorted.length - MAX_FINDINGS_PER_TRACK} more findings omitted for brevity.*`
    )
    lines.push('')
  }

  lines.push('---')
  lines.push(
    'Please analyze these findings and create an implementation plan with ordered steps to fix them.'
  )

  return lines.join('\n')
}

/**
 * Format findings from multiple tracks into a consolidated overview.
 * Used for "Send All to Chat" when multiple auditors have results —
 * gives the LLM a big-picture synthesis prompt.
 */
export function formatConsolidatedPlan(run: AuditRun): string {
  const completedResults = run.results.filter((r) => r.status === 'completed')
  const allFindings = completedResults.flatMap((r) =>
    r.findings.filter((f) => f.severity !== 'info')
  )
  const totalIssues = allFindings.length

  const lines: string[] = [
    `# 🔍 Audit Health Report — ${run.overallScore != null ? `${run.overallScore}/100` : 'N/A'}`,
    '',
    `**${totalIssues} total issue${totalIssues !== 1 ? 's' : ''}** across ${completedResults.length} auditor${completedResults.length !== 1 ? 's' : ''}`,
    ''
  ]

  // Per-track sections
  for (const result of completedResults) {
    const track = AUDIT_TRACKS[result.trackId]
    const trackName = track?.name ?? result.trackId
    const actionable = result.findings.filter((f) => f.severity !== 'info')
    if (actionable.length === 0) continue

    const sorted = sortBySeverity(actionable)
    const scoreLabel = result.score != null ? `${result.score}/100` : 'N/A'
    lines.push(
      `## ${trackName} (${scoreLabel}) — ${sorted.length} issue${sorted.length !== 1 ? 's' : ''}`
    )

    const capped = sorted.slice(0, MAX_FINDINGS_PER_TRACK)
    for (const f of capped) {
      const fileSuffix = f.filePath ? ` — \`${f.filePath}\`` : ''
      lines.push(`- [${f.severity.toUpperCase()}] ${f.title}: ${f.description}${fileSuffix}`)
    }
    if (sorted.length > MAX_FINDINGS_PER_TRACK) {
      lines.push(
        `- …and ${sorted.length - MAX_FINDINGS_PER_TRACK} more findings (omitted for brevity)`
      )
    }
    lines.push('')
  }

  // Key recommendations from highest-severity findings
  const topFindings = sortBySeverity(allFindings).slice(0, 5)
  if (topFindings.length > 0) {
    lines.push('## Key Recommendations')
    for (let i = 0; i < topFindings.length; i++) {
      const f = topFindings[i]
      lines.push(`${i + 1}. ${f.recommendation ?? f.title}`)
    }
    lines.push('')
  }

  lines.push('---')
  lines.push(
    'Please synthesize an implementation plan that addresses these findings in priority order. Group related fixes, identify dependencies between them, and estimate relative effort.'
  )

  return lines.join('\n')
}

/**
 * Build the title for a handoff conversation.
 */
export function buildHandoffTitle(
  mode: 'consolidated' | 'split',
  trackId?: AuditTrackId,
  issueCount?: number
): string {
  if (mode === 'split' && trackId) {
    const track = AUDIT_TRACKS[trackId]
    const trackName = track?.name ?? trackId
    return `🔍 Audit: ${trackName} — Fix ${issueCount ?? 0} issue${issueCount !== 1 ? 's' : ''}`
  }
  return `🔍 Audit Health Report — Fix ${issueCount ?? 0} issue${issueCount !== 1 ? 's' : ''}`
}

/**
 * AuditPlanGeneratorService — synthesizes a structured remediation plan from a
 * set of selected audit findings via a one-shot Claude CLI call.
 *
 * Mirrors GrillPlanGeneratorService: build a prompt → call the model → parse a
 * fenced JSON block → persist. The resulting AuditPlan can be routed to Chat,
 * Grill, Goals, Council, or exported.
 */

import log from 'electron-log'
import { runOneShotClaude } from './one-shot-claude'
import { modelConfigService } from './model-config.service'
import { auditPlanRepository } from '../db/repositories/audit-plan.repository'
import { planRegistryService } from './plan-registry.service'
import type { AuditPlan, AuditPlanRecord, AuditFinding } from '../../shared/types'

const planLog = log.scope('audit-plan-generator')

// ── System Prompt ───────────────────────────────────────────────────────────

const PLAN_GENERATION_SYSTEM_PROMPT = `You are a senior engineer synthesizing workspace-health audit findings into a structured, actionable remediation plan.

You receive a set of audit findings (severity, title, description, file, recommendation).
Your job is to produce a comprehensive AuditPlan JSON document.

RULES:
- Group related findings into coherent remediation items; do not emit one item per finding blindly.
- Order items by dependency and severity — critical/high first, items with no dependsOn first.
- Each item has a unique short id (e.g., "fix-1", "fix-2").
- Set scope to one of: backend | frontend | database | shared | tests.
- Populate files[] from the findings' file paths where available.
- sourceFindingIds must list the finding ids this plan addresses.
- Include a complete, standalone remediation document as markdown in requirementDocument.
- Produce the AuditPlan JSON inside a single fenced \`\`\`audit-plan block.

OUTPUT FORMAT:
\`\`\`audit-plan
{
  "version": 1,
  "title": "...",
  "summary": "...",
  "items": [
    {
      "id": "fix-1",
      "title": "...",
      "description": "...",
      "scope": "backend",
      "severity": "high",
      "files": ["..."],
      "recommendation": "...",
      "dependsOn": []
    }
  ],
  "risks": ["..."],
  "sourceFindingIds": ["..."],
  "requirementDocument": "# Remediation Plan\\n..."
}
\`\`\`

The JSON must be valid and complete. Do not truncate or abbreviate.`

// ── Service ─────────────────────────────────────────────────────────────────

class AuditPlanGeneratorService {
  /**
   * Generate a structured plan from selected audit findings, persist it, and
   * return the saved record.
   */
  async generate(params: {
    workspaceId: string
    runId: string
    findings: AuditFinding[]
  }): Promise<AuditPlanRecord> {
    planLog.info(
      `[audit-plan] Generating plan for run=${params.runId} from ${params.findings.length} findings`
    )

    if (params.findings.length === 0) {
      throw new Error('No findings provided for plan generation')
    }

    // 1. Build the prompt from the selected findings
    const prompt = this.buildPrompt(params.findings)

    // 2. Resolve model — reuse the plan-synthesis model action.
    const model = modelConfigService.getModelById(params.workspaceId, 'grill:plan')

    // 3. Call Claude via CLI one-shot
    const responseText = await this.callClaude(prompt, model, params.workspaceId)

    // 4. Parse the structured plan
    const plan = this.parsePlan(responseText, params.findings)
    if (!plan) {
      throw new Error('Failed to parse structured plan from model response')
    }

    // 5. Persist
    const record = auditPlanRepository.savePlan(params.runId, plan)

    // 6. Dual-write: register in Plan Hub registry (non-critical)
    try {
      planRegistryService.registerAuditPlan({
        workspaceId: params.workspaceId,
        auditPlanId: record.id,
        plan
      })
    } catch (err) {
      planLog.warn('[audit-plan] Plan registry write failed (non-critical):', err)
    }

    planLog.info(`[audit-plan] ✓ Plan generated: ${plan.items.length} items, id=${record.id}`)
    return record
  }

  /** Build the user prompt from the selected findings. */
  private buildPrompt(findings: AuditFinding[]): string {
    const sections: string[] = []
    sections.push(`# Audit Findings → Remediation Plan\n`)
    sections.push(`You are given ${findings.length} selected audit finding(s):\n`)

    findings.forEach((f, i) => {
      sections.push(`## ${i + 1}. [${f.severity.toUpperCase()}] ${f.title}`)
      sections.push(`- **id**: ${f.id}`)
      sections.push(`- **description**: ${f.description}`)
      if (f.filePath) sections.push(`- **file**: ${f.filePath}`)
      if (f.recommendation) sections.push(`- **recommendation**: ${f.recommendation}`)
      sections.push('')
    })

    sections.push(
      `\n---\nGenerate a comprehensive AuditPlan that addresses these findings, grouped into actionable remediation items.`
    )
    return sections.join('\n')
  }

  /** Call Claude CLI in one-shot mode. */
  private async callClaude(prompt: string, model: string, workspaceId?: string): Promise<string> {
    try {
      const { text } = await runOneShotClaude({
        feature: 'audit_plan',
        model,
        workspaceId: workspaceId || null,
        args: [
          '-p',
          prompt,
          '--model',
          model,
          '--system-prompt',
          PLAN_GENERATION_SYSTEM_PROMPT,
          '--permission-mode',
          'plan',
          '--max-turns',
          '1'
        ],
        cli: {
          timeout: 180_000, // 3 minutes — plan generation is heavier
          maxBuffer: 1024 * 1024 * 10 // 10MB buffer for large plans
        }
      })
      return text
    } catch (err) {
      planLog.error('[audit-plan] Claude CLI call failed:', err)
      throw new Error(`Plan generation failed: ${err instanceof Error ? err.message : String(err)}`)
    }
  }

  /** Parse the audit-plan JSON block from the model response. */
  private parsePlan(text: string, findings: AuditFinding[]): AuditPlan | null {
    const regex = /```audit-plan\n([\s\S]*?)```/g
    let lastMatch: RegExpExecArray | null = null
    let match: RegExpExecArray | null
    while ((match = regex.exec(text)) !== null) {
      lastMatch = match
    }
    if (!lastMatch) {
      planLog.error('[audit-plan] No ```audit-plan``` block found in response')
      return null
    }

    try {
      const parsed = JSON.parse(lastMatch[1]) as AuditPlan
      if (!parsed.title || !Array.isArray(parsed.items)) {
        planLog.error('[audit-plan] Parsed plan missing required fields')
        return null
      }
      parsed.version = 1
      parsed.summary = parsed.summary ?? ''
      parsed.risks = Array.isArray(parsed.risks) ? parsed.risks : []
      // Default sourceFindingIds to the provided findings if the model omitted them.
      if (!Array.isArray(parsed.sourceFindingIds) || parsed.sourceFindingIds.length === 0) {
        parsed.sourceFindingIds = findings.map((f) => f.id)
      }
      parsed.requirementDocument = parsed.requirementDocument ?? ''
      return parsed
    } catch (err) {
      planLog.error('[audit-plan] Failed to parse audit-plan JSON:', err)
      return null
    }
  }
}

export const auditPlanGeneratorService = new AuditPlanGeneratorService()

/**
 * AuditAgentService — multi-workspace orchestrator for workspace health audits.
 *
 * Maintains per-workspace state so audits can run concurrently across different
 * workspaces. Each workspace gets its own running flag, abort controller, and
 * active session. Events are tagged with workspaceId for IPC routing.
 *
 * Runs auditors sequentially within a workspace (one at a time), each with
 * multi-round coverage-tracked sessions. Emits 'progress', 'result',
 * 'intermediate_findings', 'stream', and 'complete' events for the IPC layer.
 */

import { EventEmitter } from 'node:events'
import { randomUUID } from 'node:crypto'
import log from 'electron-log'
import type {
  AuditMode,
  AuditTrackId,
  AuditFinding,
  AuditorStatus,
  AuditTrack,
  AuditApplicability,
  AuditCoverageStats,
  LLMProvider,
  AgentStatus
} from '../../shared/types'
import type { StreamChunk } from './agent-base.service'
import { AUDIT_TRACKS } from '../../shared/constants'
import { AgentSessionService } from './agent-session.service'
import { runOneShotClaude } from './one-shot-claude'
import { AuditRoleAdapter } from './role-adapters/audit.adapter'
import {
  parseAuditResponse,
  inferScoreFromFindings,
  applyCoverageGate
} from './audit-response-parser'
import { modelConfigService } from './model-config.service'
import { AuditCoverageTracker } from './audit-coverage-tracker'
import { discoverAuditableFiles } from './audit-discovery.service'

const auditLog = log.scope('audit-agent')

// ── Constants ─────────────────────────────────────────────────────────────

const MAX_RETRIES = 1
const RETRY_DELAY_MS = 2000

// ── Event payloads ─────────────────────────────────────────────────────────

export interface AuditProgressPayload {
  trackId: AuditTrackId
  status: AuditorStatus
  score?: number
  streamChunk?: string
}

export interface AuditResultPayload {
  trackId: AuditTrackId
  score: number
  status: AuditorStatus
  findings: AuditFinding[]
  summary: string
  skillsUsed: string[]
  coverageStats?: AuditCoverageStats
  coverageSufficient?: boolean
  applicability?: AuditApplicability
}

export interface AuditIntermediateFindingsPayload {
  trackId: AuditTrackId
  findings: AuditFinding[]
  coverageStats: AuditCoverageStats
  roundNumber: number
  totalRounds: number
  totalFiles: number
  batchSize: number
}

export interface AuditCompletePayload {
  overallScore: number | null
}

// ── Per-workspace state ───────────────────────────────────────────────────

interface AuditWorkspaceState {
  running: boolean
  abortController: AbortController | null
  session: AgentSessionService | null
  /** Per-conversation cancel: track the syntheticConvId used for send(). */
  lastConversationId?: string
}

// ── Service ────────────────────────────────────────────────────────────────

export class AuditAgentService extends EventEmitter {
  private workspaceStates = new Map<string, AuditWorkspaceState>()

  /** Check if ANY audit is running (backward compat). */
  get isRunning(): boolean {
    for (const state of this.workspaceStates.values()) {
      if (state.running) return true
    }
    return false
  }

  /** Check if a specific workspace has a running audit. */
  isRunningForWorkspace(workspaceId: string): boolean {
    return this.workspaceStates.get(workspaceId)?.running ?? false
  }

  private getOrCreateState(workspaceId: string): AuditWorkspaceState {
    let state = this.workspaceStates.get(workspaceId)
    if (!state) {
      state = { running: false, abortController: null, session: null }
      this.workspaceStates.set(workspaceId, state)
    }
    return state
  }

  /**
   * Run a full audit: iterate selected tracks sequentially.
   * Emits: 'progress', 'result', 'complete'
   */
  async runAudit(params: {
    workspaceId: string
    workspacePath: string
    mode: AuditMode
    selectedTracks: AuditTrackId[]
    auditRunId: string
    llmProvider?: LLMProvider
  }): Promise<void> {
    const state = this.getOrCreateState(params.workspaceId)

    if (state.running) {
      auditLog.warn(`[audit] Already running for workspace ${params.workspaceId} — ignoring`)
      return
    }

    state.running = true
    state.abortController = new AbortController()

    const completedResults: AuditResultPayload[] = []

    for (const trackId of params.selectedTracks) {
      if (state.abortController.signal.aborted) {
        this.emit('progress', {
          trackId,
          status: 'cancelled'
        } satisfies AuditProgressPayload)
        continue
      }

      // Signal: running
      this.emit('progress', {
        trackId,
        status: 'running'
      } satisfies AuditProgressPayload)

      try {
        const result = await this.runSingleAuditor({
          workspaceId: params.workspaceId,
          workspacePath: params.workspacePath,
          trackId,
          mode: params.mode,
          llmProvider: params.llmProvider
        })

        completedResults.push(result)
        this.emit('result', result)
      } catch (err) {
        const failResult: AuditResultPayload = {
          trackId,
          score: 0,
          status: 'failed',
          findings: [],
          summary: err instanceof Error ? err.message : String(err),
          skillsUsed: []
        }
        this.emit('result', failResult)
      }
    }

    // Calculate overall score
    const overallScore = calculateOverallScore(completedResults, AUDIT_TRACKS)

    state.running = false
    state.abortController = null
    this.emit('complete', { overallScore } satisfies AuditCompletePayload)

    // MEM-AUDIT-01: Write high/critical findings as gotcha facts.
    // Non-blocking — import and write in background.
    try {
      const highFindings = completedResults.flatMap((r) =>
        r.findings.filter((f) => f.severity === 'high' || f.severity === 'critical')
      )
      if (highFindings.length > 0) {
        const { memoryEngineService } = await import('./memory-engine.service')
        const { workspaceRepository } = await import('../db/repositories')
        const wsSettings = workspaceRepository.getSettings(params.workspaceId)
        if ((wsSettings as any).memoryCaptureBlueprints !== false) {
          for (const finding of highFindings.slice(0, 10)) {
            await memoryEngineService.writeFact({
              workspaceId: params.workspaceId,
              category: 'gotcha',
              title: `Audit: ${finding.title}`,
              content: `${finding.description}${finding.recommendation ? `\n\n**Recommendation**: ${finding.recommendation}` : ''}`,
              tags: ['audit', finding.severity],
              scopePaths: finding.filePath ? [finding.filePath] : [],
              sourceType: 'blueprint',
              sourceRef: `audit:${params.workspaceId}`,
              workspacePath: params.workspacePath
            }).catch((err) => {
              auditLog.warn(`[audit] Failed to write finding fact: ${err}`)
            })
          }
        }
      }
    } catch (memErr) {
      auditLog.warn('[audit] Failed to write audit memory facts:', memErr)
    }
  }

  /** Cancel the running audit for a specific workspace (or all if no workspaceId). */
  cancel(workspaceId?: string): void {
    if (workspaceId) {
      auditLog.info(`[audit] Cancel requested for workspace ${workspaceId}`)
      const state = this.workspaceStates.get(workspaceId)
      if (state) {
        state.abortController?.abort()
        if (state.session) {
          try {
            state.session.cancelCurrentQuery(state.lastConversationId)
          } catch {
            /* non-fatal */
          }
        }
      }
    } else {
      // Cancel all (backward compat)
      auditLog.info('[audit] Cancel all requested')
      for (const [, state] of this.workspaceStates) {
        state.abortController?.abort()
        if (state.session) {
          try {
            state.session.cancelCurrentQuery(state.lastConversationId)
          } catch {
            /* non-fatal */
          }
        }
      }
    }
  }

  /**
   * Run a single track re-run. Emits 'progress', 'result' (no 'complete').
   */
  async runSingleTrack(params: {
    workspaceId: string
    workspacePath: string
    trackId: AuditTrackId
    mode: AuditMode
    llmProvider?: LLMProvider
  }): Promise<void> {
    const state = this.getOrCreateState(params.workspaceId)

    if (state.running) {
      auditLog.warn(`[audit:rerun] Already running for workspace ${params.workspaceId} — ignoring`)
      return
    }

    state.running = true
    state.abortController = new AbortController()

    this.emit('progress', {
      trackId: params.trackId,
      status: 'running'
    } satisfies AuditProgressPayload)

    try {
      const result = await this.runSingleAuditor(params)
      this.emit('result', result)
    } catch (err) {
      const failResult: AuditResultPayload = {
        trackId: params.trackId,
        score: 0,
        status: 'failed',
        findings: [],
        summary: err instanceof Error ? err.message : String(err),
        skillsUsed: []
      }
      this.emit('result', failResult)
    } finally {
      state.running = false
      state.abortController = null
    }
  }

  // ── Private: single auditor execution with retry ──────────────────────

  private async runSingleAuditor(params: {
    workspaceId: string
    workspacePath: string
    trackId: AuditTrackId
    mode: AuditMode
    llmProvider?: LLMProvider
  }): Promise<AuditResultPayload> {
    const state = this.getOrCreateState(params.workspaceId)
    let lastError: Error | null = null

    for (let attempt = 0; attempt <= MAX_RETRIES; attempt++) {
      if (attempt > 0) {
        auditLog.info(`[audit:${params.trackId}] Retry attempt ${attempt}/${MAX_RETRIES}`)
        this.emit('progress', {
          trackId: params.trackId,
          status: 'running',
          streamChunk: `\n\n---\n⚡ Retrying after API error (attempt ${attempt + 1})...\n\n`
        } satisfies AuditProgressPayload)
      }

      try {
        return await this.executeMultiRoundAudit(params, state)
      } catch (err) {
        lastError = err instanceof Error ? err : new Error(String(err))
        const isRetryable = this.isRetryableError(lastError)
        if (!isRetryable || attempt >= MAX_RETRIES) {
          auditLog.error(
            `[audit:${params.trackId}] failed (non-retryable or max retries):`,
            lastError
          )
          throw lastError
        }
        auditLog.warn(`[audit:${params.trackId}] Retryable error: ${lastError.message}`)
        await new Promise((r) => setTimeout(r, RETRY_DELAY_MS))
      }
    }

    throw lastError!
  }

  private isRetryableError(err: Error): boolean {
    const msg = err.message.toLowerCase()
    return (
      msg.includes('400') ||
      msg.includes('empty thinking') ||
      msg.includes('invalid_request_error') ||
      msg.includes('overloaded') ||
      msg.includes('529') ||
      msg.includes('rate_limit') ||
      msg.includes('timeout')
    )
  }

  // ── Private: multi-round audit orchestration ──────────────────────────

  private async executeMultiRoundAudit(
    params: {
      workspaceId: string
      workspacePath: string
      trackId: AuditTrackId
      mode: AuditMode
      llmProvider?: LLMProvider
    },
    state: AuditWorkspaceState
  ): Promise<AuditResultPayload> {
    const isLocal = params.llmProvider === 'local-llm'
    const batchSize = this.getBatchSize(isLocal)
    const maxRounds = this.getMaxRounds(isLocal)

    const discovery = discoverAuditableFiles(params.workspacePath, params.trackId)
    const coverageTracker = new AuditCoverageTracker()
    const allFindings: AuditFinding[] = []
    let modelScore: number | null = null
    let modelSummary = ''

    auditLog.info(
      `[audit:${params.trackId}] Discovery found ${discovery.totalFiles} files, batch=${batchSize}, maxRounds=${maxRounds}`
    )

    this.emit('progress', {
      trackId: params.trackId,
      status: 'running',
      streamChunk: `📂 Discovered ${discovery.totalFiles} relevant files (${discovery.priorityFiles.length} priority). Starting multi-round inspection...\n\n`
    } satisfies AuditProgressPayload)

    let remainingFiles = [...discovery.filePaths]
    let roundNumber = 0

    while (
      remainingFiles.length > 0 &&
      roundNumber < maxRounds &&
      !state.abortController?.signal.aborted
    ) {
      roundNumber++
      const batch = remainingFiles.slice(0, batchSize)

      this.emit('progress', {
        trackId: params.trackId,
        status: 'running',
        streamChunk:
          roundNumber === 1
            ? `\n---\n\n🔍 **Round ${roundNumber}/${maxRounds}** — Inspecting ${batch.length} files...\n\n`
            : `\n\n---\n\n🔄 **Round ${roundNumber}/${maxRounds}** — Inspecting next ${batch.length} files (${remainingFiles.length - batch.length} remaining)...\n\n`
      } satisfies AuditProgressPayload)

      try {
        const roundResult = await this.runAuditRound(
          {
            workspaceId: params.workspaceId,
            workspacePath: params.workspacePath,
            trackId: params.trackId,
            mode: params.mode,
            batch,
            roundNumber,
            previousFindings: allFindings,
            remainingFileCount: remainingFiles.length - batch.length,
            coverageTracker,
            isFirstRound: roundNumber === 1,
            llmProvider: params.llmProvider
          },
          state
        )

        allFindings.push(...roundResult.findings)

        const inspected = new Set(coverageTracker.getStats().filesInspected)
        remainingFiles = remainingFiles.filter((f) => !inspected.has(f))

        if (roundResult.score !== null) {
          modelScore = roundResult.score
          modelSummary = roundResult.summary
        }

        const stats = coverageTracker.getStats()
        this.emit('progress', {
          trackId: params.trackId,
          status: 'running',
          streamChunk:
            `\n\n📊 Round ${roundNumber}: ${roundResult.findings.length} finding(s), ${stats.fileCount}/${discovery.totalFiles} files covered` +
            (roundResult.findings.length === 0 && stats.toolCallCount === 0
              ? ` ⚠️ No tool calls detected — the LLM may not have responded properly.\n\n`
              : `\n\n`)
        } satisfies AuditProgressPayload)

        this.emit('intermediate_findings', {
          trackId: params.trackId,
          findings: allFindings,
          coverageStats: stats,
          roundNumber,
          totalRounds: maxRounds,
          totalFiles: discovery.totalFiles,
          batchSize
        } satisfies AuditIntermediateFindingsPayload)

        if (this.hasAdequateCoverage(allFindings, stats, discovery.totalFiles)) {
          auditLog.info(
            `[audit:${params.trackId}] Adequate coverage reached after round ${roundNumber}`
          )
          break
        }
      } catch (roundErr) {
        auditLog.warn(
          `[audit:${params.trackId}] Round ${roundNumber} failed:`,
          roundErr instanceof Error ? roundErr.message : roundErr
        )

        if (state.abortController?.signal.aborted) {
          auditLog.info(`[audit:${params.trackId}] Aborted — stopping multi-round loop`)
          break
        }

        const inspected = new Set(coverageTracker.getStats().filesInspected)
        const uninspectedFromBatch = batch.filter((f) => !inspected.has(f))
        remainingFiles = [...uninspectedFromBatch, ...remainingFiles.slice(batch.length)]

        if (allFindings.length === 0 && roundNumber === 1) {
          throw roundErr
        }

        this.emit('progress', {
          trackId: params.trackId,
          status: 'running',
          streamChunk: `\n\n⚠️ Round ${roundNumber} encountered an error. Continuing with next batch...\n\n`
        } satisfies AuditProgressPayload)
      }
    }

    // Phase 3: Compute final result with coverage gate
    return this.computeFinalAuditResult(
      params.trackId,
      allFindings,
      modelScore,
      modelSummary,
      coverageTracker,
      discovery,
      roundNumber
    )
  }

  // ── Private: final result computation ────────────────────────────────

  /** Compute the final gated score, summary, and applicability for an audit track. */
  private computeFinalAuditResult(
    trackId: AuditTrackId,
    allFindings: AuditFinding[],
    modelScore: number | null,
    modelSummary: string,
    coverageTracker: AuditCoverageTracker,
    discovery: { totalFiles: number },
    roundNumber: number
  ): AuditResultPayload {
    const stats = coverageTracker.getStats()
    let finalScore: number
    if (modelScore != null) {
      finalScore = modelScore
    } else {
      const inferred = inferScoreFromFindings(allFindings)
      const hasRealFindings = allFindings.some((f) => f.severity !== 'info')
      finalScore = hasRealFindings ? inferred : Math.min(inferred, 50)
    }

    const parsed = {
      score: finalScore,
      summary:
        modelSummary ||
        `Audit completed in ${roundNumber} round(s). ${allFindings.length} finding(s) across ${stats.fileCount} files.`,
      findings: allFindings
    }

    const gated = applyCoverageGate(parsed, stats)
    gated.coveragePercent =
      discovery.totalFiles > 0 ? Math.round((stats.fileCount / discovery.totalFiles) * 100) : null

    // Derive applicability: no files discovered for this track ⇒ not-applicable;
    // failed coverage gate ⇒ insufficient; otherwise the score is trustworthy.
    const applicability: AuditApplicability =
      discovery.totalFiles === 0 || stats.fileCount === 0
        ? 'not-applicable'
        : gated.isSufficient
          ? 'ok'
          : 'insufficient'

    return {
      trackId,
      score: gated.score,
      status: 'completed',
      findings: gated.findings,
      summary: gated.summary,
      skillsUsed: [],
      coverageStats: gated.coverageStats,
      coverageSufficient: gated.isSufficient,
      applicability
    }
  }

  // ── Private: single round execution ───────────────────────────────────

  private async runAuditRound(
    params: {
      workspaceId: string
      workspacePath: string
      trackId: AuditTrackId
      mode: AuditMode
      batch: string[]
      roundNumber: number
      previousFindings: AuditFinding[]
      remainingFileCount: number
      coverageTracker: AuditCoverageTracker
      isFirstRound: boolean
      llmProvider?: LLMProvider
    },
    state: AuditWorkspaceState
  ): Promise<{ findings: AuditFinding[]; score: number | null; summary: string }> {
    const roundContext = params.isFirstRound
      ? undefined
      : {
          roundNumber: params.roundNumber,
          fileBatch: params.batch,
          previousFindingsSummary: this.summarizePreviousFindings(params.previousFindings),
          remainingFileCount: params.remainingFileCount
        }

    const adapter = new AuditRoleAdapter({
      workspaceId: params.workspaceId,
      trackId: params.trackId,
      mode: params.mode,
      roundContext,
      llmProvider: params.llmProvider
    })

    const session = new AgentSessionService(adapter)
    state.session = session

    session.on('chunk', (chunk: StreamChunk) => {
      params.coverageTracker.onChunk(chunk)

      // Surface error chunks — CLI auth failures, API issues, invalid flags
      if (chunk.type === 'error' && chunk.error) {
        auditLog.error(`[audit:${params.trackId}] Error chunk: ${chunk.error.slice(0, 300)}`)
        this.emit('progress', {
          trackId: params.trackId,
          status: 'running',
          streamChunk: `\n⚠️ Error: ${chunk.error.slice(0, 200)}\n`
        } satisfies AuditProgressPayload)
        return
      }

      // Surface auth issues so the user knows to fix credentials
      if (chunk.type === 'auth_status' && chunk.content) {
        auditLog.warn(`[audit:${params.trackId}] Auth status: ${chunk.content}`)
        this.emit('progress', {
          trackId: params.trackId,
          status: 'running',
          streamChunk: `\n🔑 ${chunk.content}\n`
        } satisfies AuditProgressPayload)
        return
      }

      if (chunk.type === 'text' && chunk.content && this.isApiErrorText(chunk.content)) {
        auditLog.warn(
          `[audit:${params.trackId}] Suppressed API error from stream: ${chunk.content.slice(0, 150)}`
        )
        this.emit('progress', {
          trackId: params.trackId,
          status: 'running',
          streamChunk: '\n⚡ Encountered a transient API issue — retrying automatically...\n'
        } satisfies AuditProgressPayload)
        return
      }

      if (chunk.type === 'text' && chunk.content) {
        this.emit('progress', {
          trackId: params.trackId,
          status: 'running',
          streamChunk: chunk.content
        } satisfies AuditProgressPayload)
      }
      this.emit('stream', { trackId: params.trackId, chunk })
    })

    // Re-emit inner-session status so the live token usage modal reflects audit activity.
    session.on('statusUpdate', (status: AgentStatus) => {
      this.emit('status', { workspaceId: params.workspaceId, status })
    })

    try {
      await session.start(params.workspacePath, 'plan')

      const message = params.isFirstRound
        ? 'Begin your audit.'
        : this.buildContinuationPrompt(params)

      const syntheticConvId = `audit-${params.trackId}-r${params.roundNumber}-${Date.now()}`
      state.lastConversationId = syntheticConvId
      await session.send(message, syntheticConvId, [])

      if (session.wasTimedOut()) {
        auditLog.warn(`[audit:${params.trackId}] Round ${params.roundNumber} timed out`)
      }

      const responseText = session.getStreamedContent(syntheticConvId)

      // Detect empty/very short responses — likely CLI or API failure
      if (responseText.length < 50) {
        auditLog.error(
          `[audit:${params.trackId}] Round ${params.roundNumber} produced near-empty response ` +
            `(${responseText.length} chars). Possible CLI/API issue. ` +
            `Response: "${responseText.slice(0, 100)}"`
        )
      }

      const parsed = parseAuditResponse(responseText)

      if (params.isFirstRound && parsed.score === 0 && parsed.findings.length === 0) {
        if (responseText.length > 100) {
          // Model responded but didn't emit structured blocks — try recovery
          return this.attemptToolFreeRecovery(params, responseText)
        }
        // Near-empty response — emit diagnostic finding so the user sees WHY it failed
        auditLog.error(
          `[audit:${params.trackId}] Round 1 produced ${responseText.length}-char response with 0 findings`
        )
        return {
          findings: [
            {
              id: randomUUID(),
              severity: 'info' as const,
              title: `${params.trackId} audit could not complete`,
              description:
                `The auditor received an empty or very short response (${responseText.length} chars) from the LLM. ` +
                `This usually indicates a CLI authentication issue, API rate limit, or invalid CLI flags. ` +
                `Check that the "claude" CLI is working by running "claude -p hello" in your terminal.`,
              recommendation:
                'Verify Claude CLI access: run "claude --version" and "claude -p hello" in your terminal.'
            }
          ],
          score: null,
          summary: 'Audit could not complete — empty LLM response. Check Claude CLI configuration.'
        }
      }

      return {
        findings: parsed.findings,
        score: parsed.score > 0 ? parsed.score : null,
        summary: parsed.summary
      }
    } finally {
      try {
        await session.stop()
      } catch {
        /* best-effort cleanup */
      }
      state.session = null
    }
  }

  // ── Private: tool-free recovery nudge ─────────────────────────────────

  private async attemptToolFreeRecovery(
    params: { trackId: AuditTrackId; workspacePath: string; workspaceId?: string },
    responseText: string
  ): Promise<{ findings: AuditFinding[]; score: number | null; summary: string }> {
    auditLog.warn(
      `[audit:${params.trackId}] No findings extracted from ${responseText.length}-char response — tool-free recovery`
    )

    try {
      const nudgePrompt =
        `Your previous audit analysis is below. You investigated the codebase but did not emit any finding blocks.\n\n` +
        `--- ANALYSIS ---\n${responseText.slice(0, 8000)}\n--- END ---\n\n` +
        `Based on what you found above, output a JSON code block with this exact shape:\n\n` +
        '```json\n{"score": <0-100>, "summary": "<2-3 sentences>", "findings": [{"severity": "...", "title": "...", "description": "...", "filePath": "...", "recommendation": "..."}]}\n```\n\n' +
        `Score conservatively. Include findings for what you DID inspect. Output ONLY the JSON block.`

      const recoveryModel = modelConfigService.getModel(params.workspacePath, 'specialist:plan')
      const { text: nudgeText } = await runOneShotClaude({
        feature: 'audit_recovery',
        model: recoveryModel,
        workspaceId: params.workspaceId ?? null,
        args: [
          '-p',
          nudgePrompt,
          '--model',
          recoveryModel,
          '--system-prompt',
          'You are an audit result formatter. Output only the requested JSON block.',
          '--permission-mode',
          'plan',
          '--max-turns',
          '1'
        ],
        cli: {
          timeout: 60_000,
          cwd: params.workspacePath
        }
      })

      const nudgeParsed = parseAuditResponse(nudgeText)

      if (nudgeParsed.score > 0 || nudgeParsed.findings.length > 0) {
        auditLog.info(
          `[audit:${params.trackId}] Tool-free recovery succeeded — score=${nudgeParsed.score}, findings=${nudgeParsed.findings.length}`
        )
        return {
          findings: nudgeParsed.findings,
          score: nudgeParsed.score > 0 ? nudgeParsed.score : null,
          summary: nudgeParsed.summary
        }
      }
    } catch (nudgeErr) {
      auditLog.warn(`[audit:${params.trackId}] Tool-free recovery failed:`, nudgeErr)
    }

    const analysisText = responseText.trim()
    const preservedSummary =
      analysisText.length > 1500 ? analysisText.slice(-1500).trim() : analysisText

    const syntheticFinding: AuditFinding = {
      id: randomUUID(),
      severity: 'info',
      title: `${params.trackId} audit analysis completed`,
      description:
        preservedSummary ||
        'The auditor completed its analysis but did not emit structured findings. Review the stream output above for details.',
      recommendation:
        'Re-run this audit track to attempt structured extraction. If the issue persists, the codebase may use patterns the auditor cannot parse into discrete findings.'
    }

    return {
      findings: [syntheticFinding],
      score: null,
      summary:
        preservedSummary || 'Audit analysis completed — structured findings could not be extracted.'
    }
  }

  // ── Private: helpers ──────────────────────────────────────────────────

  private isApiErrorText(text: string): boolean {
    return (
      text.includes('API Error:') ||
      text.includes('"type":"error"') ||
      text.includes('invalid_request_error') ||
      text.includes('each thinking block must contain')
    )
  }

  private getBatchSize(isLocal: boolean): number {
    return isLocal ? 3 : 12
  }

  private getMaxRounds(isLocal: boolean): number {
    return isLocal ? 15 : 5
  }

  private buildContinuationPrompt(params: {
    trackId: AuditTrackId
    batch: string[]
    roundNumber: number
    previousFindings: AuditFinding[]
    remainingFileCount: number
  }): string {
    return (
      `Continue your ${params.trackId} audit.\n\n` +
      `## Already Reviewed\n` +
      `${params.previousFindings.length} finding(s) discovered so far:\n` +
      `${this.summarizePreviousFindings(params.previousFindings)}\n\n` +
      `## Remaining Work\n` +
      `${params.remainingFileCount} files still to inspect. Focus on these files in this round:\n` +
      `${params.batch.map((f) => `- ${f}`).join('\n')}\n\n` +
      `Emit audit-finding blocks for each file you inspect. After reviewing all files above, emit an audit-score block.`
    )
  }

  private summarizePreviousFindings(findings: AuditFinding[]): string {
    if (findings.length === 0) return 'No findings yet.'
    return findings
      .slice(-10)
      .map(
        (f) => `- [${f.severity.toUpperCase()}] ${f.title}${f.filePath ? ` (${f.filePath})` : ''}`
      )
      .join('\n')
  }

  private hasAdequateCoverage(
    findings: AuditFinding[],
    stats: AuditCoverageStats,
    totalFiles: number
  ): boolean {
    const coveragePercent = totalFiles > 0 ? stats.fileCount / totalFiles : 0
    const hasEnoughFindings = findings.length >= 8
    const hasEnoughCoverage = coveragePercent >= 0.6

    return hasEnoughFindings && hasEnoughCoverage
  }

  /** Graceful shutdown — cancel all audits and clear state. Called on app quit. */
  async shutdown(): Promise<void> {
    auditLog.info(`[audit] Shutdown initiated — ${this.workspaceStates.size} active states`)
    this.cancel() // Cancels all workspace audits
    this.workspaceStates.clear()
  }
}

// ── Weighted average calculation ───────────────────────────────────────────

function calculateOverallScore(
  results: AuditResultPayload[],
  tracks: Record<AuditTrackId, AuditTrack>
): number | null {
  // Exclude tracks whose coverage was insufficient (or not-applicable) — a
  // hallucinated 0 from an empty audit must not drag down the overall score.
  const completed = results.filter(
    (r) => r.status === 'completed' && r.coverageSufficient !== false
  )
  if (completed.length === 0) return null

  let weightedSum = 0
  let totalWeight = 0
  for (const r of completed) {
    const weight = tracks[r.trackId]?.weight ?? 1.0
    weightedSum += r.score * weight
    totalWeight += weight
  }
  return Math.round(weightedSum / totalWeight)
}

export const auditAgentService = new AuditAgentService()

/**
 * Audit Discovery Service — enumerates auditable files per track.
 *
 * Before running the actual audit, discovers all relevant files for a
 * given audit track using pattern matching and heuristics. This provides:
 *   - The denominator for coverage percent (filesInspected / totalFiles)
 *   - Priority ordering (critical files first)
 *   - File batches for multi-round audit orchestration
 *
 * Pure file-system enumeration — no LLM calls. Uses Node.js built-in
 * readdirSync + extname + pattern matching (no glob dependency).
 */

import { readdirSync, statSync } from 'node:fs'
import { join, relative, extname } from 'node:path'
import log from 'electron-log'
import type { AuditTrackId } from '../../shared/types'

const discoveryLog = log.scope('audit-discovery')

export interface AuditDiscoveryResult {
  totalFiles: number
  filePaths: string[] // All relevant files (workspace-relative)
  priorityFiles: string[] // Critical files to inspect first
}

/** Directories to always skip. */
const SKIP_DIRS = new Set([
  'node_modules',
  '.git',
  'dist',
  'build',
  'coverage',
  '.next',
  '.nuxt',
  'vendor',
  '__pycache__',
  'target',
  '.cache',
  '.output',
  '.svelte-kit',
  '.turbo'
])

/** Max files to return per track (avoid overwhelming the auditor). */
const MAX_FILES_PER_TRACK = 100

/** Max directory depth to recurse. */
const MAX_DEPTH = 10

/**
 * Discover all auditable files for a given track in the workspace.
 * Returns workspace-relative paths sorted with priority files first.
 */
export function discoverAuditableFiles(
  workspacePath: string,
  trackId: AuditTrackId
): AuditDiscoveryResult {
  const config = TRACK_FILE_CONFIG[trackId]
  if (!config) {
    return { totalFiles: 0, filePaths: [], priorityFiles: [] }
  }

  const allFiles: string[] = []

  try {
    walkDirectory(workspacePath, workspacePath, 0, (relPath) => {
      if (matchesTrack(relPath, config)) {
        allFiles.push(relPath)
      }
    })
  } catch (err) {
    discoveryLog.warn(`[audit-discovery] Error scanning workspace: ${err}`)
  }

  // Identify priority files
  const priorityFiles: string[] = []
  if (config.priorityPatterns) {
    for (const f of allFiles) {
      if (config.priorityPatterns.some((p) => f.toLowerCase().includes(p.toLowerCase()))) {
        priorityFiles.push(f)
      }
    }
  }

  // Sort: priority files first, then alphabetical
  const prioritySet = new Set(priorityFiles)
  const sorted = [...priorityFiles, ...allFiles.filter((f) => !prioritySet.has(f)).sort()]

  // Cap total files
  const capped = sorted.slice(0, MAX_FILES_PER_TRACK)

  discoveryLog.info(
    `[audit-discovery] Track=${trackId}: ${allFiles.length} total files, ${priorityFiles.length} priority, returning ${capped.length}`
  )

  return {
    totalFiles: allFiles.length,
    filePaths: capped,
    priorityFiles
  }
}

// ── Recursive directory walker ───────────────────────────────────────────

function walkDirectory(
  rootPath: string,
  currentPath: string,
  depth: number,
  callback: (relPath: string) => void
): void {
  if (depth > MAX_DEPTH) return

  let entries: string[]
  try {
    entries = readdirSync(currentPath) as unknown as string[]
  } catch {
    return // Permission denied or similar
  }

  for (const entryName of entries) {
    const name = String(entryName)
    const fullPath = join(currentPath, name)

    // Check if directory
    let isDir = false
    try {
      isDir = statSync(fullPath).isDirectory()
    } catch {
      continue // inaccessible entry
    }

    if (isDir) {
      if (SKIP_DIRS.has(name.toLowerCase()) || name.startsWith('.')) continue
      walkDirectory(rootPath, fullPath, depth + 1, callback)
    } else {
      const relPath = relative(rootPath, fullPath)
      callback(relPath)
    }
  }
}

// ── Pattern matching ─────────────────────────────────────────────────────

interface TrackFileConfig {
  /** File extensions to include (e.g. ['.ts', '.tsx']) */
  extensions: string[]
  /** Path substrings that must match (OR logic). Empty = match all with matching extension. */
  pathIncludes?: string[]
  /** Path substrings to exclude (any match = skip). */
  pathExcludes?: string[]
  /** Basename patterns for priority ordering. */
  priorityPatterns?: string[]
}

function matchesTrack(relPath: string, config: TrackFileConfig): boolean {
  const ext = extname(relPath).toLowerCase()

  // Must match at least one extension
  if (!config.extensions.includes(ext)) return false

  // Check exclusions
  if (config.pathExcludes) {
    const lower = relPath.toLowerCase()
    if (config.pathExcludes.some((ex) => lower.includes(ex.toLowerCase()))) return false
  }

  // Check path includes (if specified, at least one must match)
  if (config.pathIncludes && config.pathIncludes.length > 0) {
    const lower = relPath.toLowerCase()
    if (!config.pathIncludes.some((inc) => lower.includes(inc.toLowerCase()))) return false
  }

  return true
}

// ── Per-track file configuration ─────────────────────────────────────────

const TRACK_FILE_CONFIG: Record<AuditTrackId, TrackFileConfig> = {
  database: {
    extensions: ['.sql', '.ts', '.js', '.prisma'],
    pathIncludes: [
      'migration',
      'repository',
      'repositories',
      'model',
      'models',
      'entity',
      'entities',
      'schema',
      'prisma',
      'drizzle',
      'db/',
      'database'
    ],
    priorityPatterns: ['schema', 'migration', 'index.ts']
  },

  code: {
    extensions: ['.ts', '.tsx', '.js', '.jsx'],
    pathExcludes: ['.test.', '.spec.', '__tests__', '/test/', '/tests/', '.d.ts', '.config.'],
    priorityPatterns: ['index.ts', 'index.tsx', 'main.ts', 'app.ts', 'server.ts']
  },

  testing: {
    extensions: ['.ts', '.tsx', '.js', '.jsx', '.json', '.mjs', '.cjs'],
    pathIncludes: [
      '.test.',
      '.spec.',
      '__tests__',
      '/test/',
      '/tests/',
      'jest.config',
      'vitest.config',
      'playwright.config',
      'cypress.config'
    ],
    priorityPatterns: ['config', 'setup', 'helper', 'fixture']
  },

  architecture: {
    extensions: ['.ts', '.js', '.json', '.mjs', '.cjs'],
    pathIncludes: [
      'package.json',
      'tsconfig',
      'index.ts',
      'index.js',
      '/routes/',
      '/ipc/',
      '/services/',
      'types.ts',
      'constants.ts',
      '.config.'
    ],
    priorityPatterns: ['package.json', 'tsconfig', 'index.ts', 'types.ts', 'constants.ts']
  },

  security: {
    extensions: ['.ts', '.tsx', '.js', '.jsx', '.env', '.yml', '.yaml'],
    pathIncludes: [
      'auth',
      'security',
      'csp',
      'preload',
      'sanitize',
      'validate',
      '.env',
      'middleware',
      'Dockerfile',
      'docker-compose'
    ],
    priorityPatterns: ['auth', 'security', 'csp', 'preload', '.env', 'middleware']
  },

  documentation: {
    extensions: ['.md', '.mdx', '.yml', '.yaml'],
    pathExcludes: ['node_modules', 'CHANGELOG'],
    priorityPatterns: ['README', 'CLAUDE.md', 'docs/', 'CONTRIBUTING']
  },

  'ui-ux': {
    extensions: ['.tsx', '.jsx', '.css', '.scss'],
    pathIncludes: ['component', 'page', 'layout', 'style', 'theme'],
    pathExcludes: ['.test.', '.spec.', '__tests__'],
    priorityPatterns: ['App.tsx', 'Layout', 'index.tsx', 'theme', 'global']
  }
}

/**
 * IPC handlers for Grill evaluations.
 *
 * Bridges the renderer ↔ GrillAgentService and forwards streaming events
 * to the renderer via webContents.send().
 */

import type { BrowserWindow } from 'electron'
import { ipcMain } from 'electron'
import { IPC_CHANNELS } from '../../shared/constants'
import type {
  GrillTrackId,
  GrillEvaluation,
  LLMProvider,
  GrillStructuredPlan,
  GrillDecision,
  GrillTrackScore,
  AgentStatus
} from '../../shared/types'
import type { StreamChunk } from '../services/agent-base.service'
import { processToolChunk } from './tool-chunk-processor'
import { createTimedCleanupMap } from './listener-cleanup'
import {
  workspaceRepository,
  grillSessionRepository,
  ideaRepository,
  messageRepository
} from '../db/repositories'
import { grillAgentService } from '../services/grill-agent.service'
import { grillPersistenceController } from '../services/grill-persistence.controller'
import { grillPlanGeneratorService } from '../services/grill-plan-generator.service'
import { runOneShotClaude } from '../services/one-shot-claude'
import { modelConfigService } from '../services/model-config.service'
import { DEFAULT_MODEL_CONFIG } from '../../shared/constants'
import { grillPlanToStructuredPlan } from '../services/grill-plan-mapper'
import { getSessionEventRouter } from '../services/session-event-router'
import { validateSender } from './validate-sender'
import { requireObject, requireString, optionalString } from './validate-args'
import { notificationService } from '../services/notification.service'
import { resolveWorkspaceName } from './resolve-workspace-name'
import log from 'electron-log'

const grillLog = log.scope('grill-ipc')

// GRILL-DUALSTART-01: Per-workspace start lock prevents the TOCTOU race between
// the isRunning check and evaluate() registering the session in the Map. The lock
// is set synchronously before setup and released in evaluate()'s .finally().
const grillStartLocks = new Set<string>()

export function registerGrillIpc(_mainWindow: BrowserWindow): void {
  // ── grill:evaluate — start a grill evaluation ──────────────────────

  ipcMain.handle(IPC_CHANNELS.GRILL_EVALUATE, async (event, rawArgs: unknown): Promise<void> => {
    validateSender(event)
    // MCP-05 / IPC-08: Runtime validation for all fields
    const ch = IPC_CHANNELS.GRILL_EVALUATE
    const args = requireObject(rawArgs, ch)
    const workspaceId = requireString(args, 'workspaceId', ch)
    const trackId = requireString(args, 'trackId', ch) as GrillTrackId
    const ideaTitle = requireString(args, 'ideaTitle', ch)
    const ideaDescription = requireString(args, 'ideaDescription', ch)
    const iterationHistory = args.iterationHistory as string | undefined
    const previousScore = args.previousScore as number | undefined
    const ideaId = args.ideaId as string | undefined
    const explicitProvider = args.llmProvider as LLMProvider | undefined
    const greenfield = args.greenfield as boolean | undefined
    const projectName = args.projectName as string | undefined

    grillLog.info('[grill:evaluate] Handler invoked', {
      workspaceId,
      trackId,
      greenfield
    })

    // GRILL-DUALSTART-01 + GRILL-ISRUNNING-GLOBAL-01: Per-workspace start lock
    // prevents the TOCTOU race between isRunning check and evaluate() setting
    // session.running. Uses isRunningForWorkspace instead of global isRunning
    // to allow cross-workspace concurrent evaluations.
    if (grillStartLocks.has(workspaceId) || grillAgentService.isRunningForWorkspace(workspaceId)) {
      throw new Error('A grill evaluation is already running for this workspace.')
    }
    grillStartLocks.add(workspaceId)

    try {
    // ── Greenfield path: no workspace lookup needed ──
    if (greenfield) {
      grillLog.info(
        `[grill:evaluate:greenfield] track=${trackId} project="${(projectName ?? ideaTitle).slice(0, 40)}"`
      )

      const llmProvider: LLMProvider = explicitProvider ?? 'claude'

      // Wire event forwarding (no persistence controller for greenfield)
      wireGrillEvents(workspaceId, '')

      // Emit transient 'evaluating' status so the bottom bar shows "Grilling…"
      // immediately. The standard path gets this from startTracking, but
      // greenfield skips the persistence controller.
      try {
        getSessionEventRouter().sendWorkspaceEvent(IPC_CHANNELS.GRILL_STATUS_CHANGED, workspaceId, {
          status: 'evaluating',
          ideaId: '',
          trackId,
          score: null
        })
      } catch {
        /* router not initialized */
      }

      grillAgentService
        .evaluateGreenfield({
          trackId,
          projectName: projectName ?? ideaTitle,
          projectDescription: ideaDescription,
          iterationHistory,
          previousScore,
          llmProvider,
          workspaceId  // GRILL-04: pass for event routing
        })
        .catch((err) => {
          grillLog.error('[grill:evaluate:greenfield] evaluate failed:', err)
        })
        .finally(() => {
          grillStartLocks.delete(workspaceId)
        })
      return
    }

    // ── Standard path: existing workspace ──
    // Resolve workspace path
    const workspace = workspaceRepository.findById(workspaceId)
    if (!workspace) throw new Error(`Workspace ${workspaceId} not found`)
    if (!workspace.repoPath) throw new Error(`Workspace ${workspaceId} has no repo path`)

    grillLog.info(
      `[grill:evaluate] workspaceId=${workspaceId} track=${trackId} title="${ideaTitle.slice(0, 40)}"`
    )

    // Start persistence tracking (if ideaId is provided)
    if (ideaId) {
      await grillPersistenceController.startTracking(ideaId, workspaceId, trackId)
    }

    // Resolve LLM provider: explicit selection → workspace setting → 'claude'
    const settings = workspaceRepository.getSettings(workspace.id)
    const llmProvider: LLMProvider = explicitProvider ?? settings.llmProvider ?? 'claude'

    // Wire event forwarding (through persistence controller)
    wireGrillEvents(workspaceId, workspace.repoPath)

    // Start the evaluation (non-blocking — runs in background)
    grillAgentService
      .evaluate({
        workspaceId,
        workspacePath: workspace.repoPath,
        trackId,
        ideaTitle,
        ideaDescription,
        iterationHistory,
        previousScore,
        llmProvider
      })
      .catch((err) => {
        grillLog.error('[grill:evaluate] evaluate failed:', err)
      })
      .finally(() => {
        grillStartLocks.delete(workspaceId)
      })
    } catch (e) {
      // GRILL-DUALSTART-01: Release lock if synchronous setup fails
      // (e.g. workspace not found, startTracking throws)
      grillStartLocks.delete(workspaceId)
      throw e
    }
  })

  // ── grill:cancel — abort running evaluation ────────────────────────

  // GRILL-02: Accept workspaceId so cancel targets the correct workspace
  ipcMain.handle(IPC_CHANNELS.GRILL_CANCEL, (event, rawArgs?: unknown): void => {
    validateSender(event)
    const workspaceId = rawArgs && typeof rawArgs === 'object'
      ? optionalString(rawArgs as Record<string, unknown>, 'workspaceId', IPC_CHANNELS.GRILL_CANCEL)
      : undefined
    grillAgentService.cancel(workspaceId ?? undefined)
    grillPersistenceController.clearTracking(workspaceId ?? undefined)
  })

  // ── grill:getStatus — current grill status for a workspace ────────

  ipcMain.handle(IPC_CHANNELS.GRILL_GET_STATUS, (event, rawArgs: unknown) => {
    validateSender(event)
    const args = requireObject(rawArgs, IPC_CHANNELS.GRILL_GET_STATUS)
    const wId = requireString(args, 'workspaceId', IPC_CHANNELS.GRILL_GET_STATUS)
    const status = grillPersistenceController.getStatusForWorkspace(wId)
    grillLog.info(`[grill:getStatus] workspace=${wId} status=${status?.status ?? 'null'}`)
    return status
  })

  // ── grill:getSession — full session state from DB ─────────────────

  ipcMain.handle(IPC_CHANNELS.GRILL_GET_SESSION, (event, rawArgs: unknown) => {
    validateSender(event)
    const args = requireObject(rawArgs, IPC_CHANNELS.GRILL_GET_SESSION)
    const ideaId = requireString(args, 'ideaId', IPC_CHANNELS.GRILL_GET_SESSION)
    const session = grillPersistenceController.getSessionState(ideaId)
    grillLog.info(`[grill:getSession] idea=${ideaId} reconnect status=${session?.status ?? 'null'}`)
    return session
  })

  // ── grill:saveAnswers — persist question states to DB session ─────

  ipcMain.handle(IPC_CHANNELS.GRILL_SAVE_ANSWERS, (event, rawArgs: unknown): void => {
    validateSender(event)
    const ch = IPC_CHANNELS.GRILL_SAVE_ANSWERS
    const args = requireObject(rawArgs, ch)
    const sessionId = requireString(args, 'sessionId', ch)
    if (!args.questionStates || typeof args.questionStates !== 'object') {
      throw new Error(`${ch}: field 'questionStates' must be an object`)
    }
    grillPersistenceController.saveAnswers(
      sessionId,
      args.questionStates as Record<string, unknown>
    )
  })

  // ── grill:generatePlan — Generate structured plan from grill session ──

  ipcMain.handle(
    IPC_CHANNELS.GRILL_GENERATE_PLAN,
    async (event, rawArgs: unknown): Promise<GrillStructuredPlan> => {
      validateSender(event)
      const ch = IPC_CHANNELS.GRILL_GENERATE_PLAN
      const args = requireObject(rawArgs, ch)
      const sessionId = requireString(args, 'sessionId', ch)
      const workspaceId = requireString(args, 'workspaceId', ch)
      const ideaId = args.ideaId as string | undefined

      grillLog.info(
        `[grill:generatePlan] Generating plan for idea=${ideaId ?? 'n/a'} session=${sessionId}`
      )

      const workspace = workspaceRepository.findById(workspaceId)
      const workspacePath = workspace?.repoPath

      const plan = await grillPlanGeneratorService.generate({
        sessionId,
        ideaId,
        workspaceId,
        workspacePath
      })

      grillLog.info(`[grill:generatePlan] ✓ Plan generated: ${plan.items.length} items`)
      return plan
    }
  )

  // ── grill:generatePlanFromDecisions — session-less plan from decisions ──

  ipcMain.handle(
    IPC_CHANNELS.GRILL_GENERATE_PLAN_FROM_DECISIONS,
    async (event, rawArgs: unknown): Promise<GrillStructuredPlan> => {
      validateSender(event)
      const ch = IPC_CHANNELS.GRILL_GENERATE_PLAN_FROM_DECISIONS
      const args = requireObject(rawArgs, ch)
      const workspaceId = requireString(args, 'workspaceId', ch)
      const projectName = ((args.projectName as string) ?? '').slice(0, 10_000)
      const description = ((args.description as string) ?? '').slice(0, 50_000)

      // PLAN-GEN-02 + GRILL-IPC-01: Validate grillDecisions is actually an array with bounded size
      if (args.grillDecisions != null && !Array.isArray(args.grillDecisions)) {
        throw new Error(`${ch}: grillDecisions must be an array`)
      }
      const grillDecisions = (Array.isArray(args.grillDecisions) ? args.grillDecisions : []).slice(
        0,
        200
      ) as GrillDecision[]

      // Validate trackScores if present
      const rawTrackScores = args.trackScores
      const trackScores =
        Array.isArray(rawTrackScores)
          ? (rawTrackScores.slice(0, 100) as GrillTrackScore[])
          : undefined

      grillLog.info(
        `[grill:generatePlanFromDecisions] Generating plan for project="${projectName}" (${grillDecisions?.length ?? 0} decisions)`
      )

      const plan = await grillPlanGeneratorService.generateFromDecisions({
        projectName: projectName ?? '',
        description: description ?? '',
        grillDecisions: grillDecisions ?? [],
        trackScores,
        workspaceId
      })

      grillLog.info(
        `[grill:generatePlanFromDecisions] ✓ Plan generated: ${plan.items.length} items`
      )
      return plan
    }
  )

  // ── grill:seedPlanCard — seed an already-generated plan as a chat card ──
  // Maps the GrillStructuredPlan to the chat StructuredPlan shape and writes it
  // as a `specialist` message containing a ```plan block. Deterministic — no LLM
  // round-trip — so the grill→chat handoff renders the existing plan instantly.

  ipcMain.handle(IPC_CHANNELS.GRILL_SEED_PLAN_CARD, (event, rawArgs: unknown) => {
    validateSender(event)
    const args = requireObject(rawArgs, IPC_CHANNELS.GRILL_SEED_PLAN_CARD)
    const conversationId = requireString(args, 'conversationId', IPC_CHANNELS.GRILL_SEED_PLAN_CARD)
    const plan = (args as { plan?: GrillStructuredPlan }).plan
    if (!plan || typeof plan !== 'object') {
      throw new Error(`${IPC_CHANNELS.GRILL_SEED_PLAN_CARD}: field 'plan' must be an object`)
    }

    const structured = grillPlanToStructuredPlan(plan)
    const leadIn = 'Here’s the implementation plan synthesized from your grill session.'
    const contentMd = `${leadIn}\n\n\`\`\`plan\n${JSON.stringify(structured)}\n\`\`\``

    grillLog.info(
      `[grill:seedPlanCard] Seeding plan card into conversation=${conversationId} (${structured.phases?.length ?? 0} phases)`
    )
    return messageRepository.create(conversationId, 'specialist', contentMd)
  })

  // ── grill:complete — strip transient state at final handoff, keep plan ──

  ipcMain.handle(IPC_CHANNELS.GRILL_COMPLETE, (event, rawArgs: unknown): void => {
    validateSender(event)
    const args = requireObject(rawArgs, IPC_CHANNELS.GRILL_COMPLETE)
    const ideaId = requireString(args, 'ideaId', IPC_CHANNELS.GRILL_COMPLETE)

    grillLog.info(`[grill:complete] Completing + stripping transient state for idea=${ideaId}`)
    // GRILL-COMPLETE-DISCARD-NOTRYCATCH-01: Wrap DB ops in try-catch so a failure
    // doesn't prevent the terminal status emission below.
    try {
      grillSessionRepository.completeAndStrip(ideaId)
      ideaRepository.clearGrillDecisions(ideaId)
    } catch (err) {
      grillLog.error('[grill:complete] DB operation failed:', err)
    }
    // Always emit terminal status — even if DB ops failed
    const workspace = ideaRepository.findById(ideaId)?.workspaceId
    if (workspace) grillPersistenceController.notifyTerminal(workspace, ideaId, 'completed')
  })

  // ── grill:discard — delete the session row + snapshot entirely ──────

  ipcMain.handle(IPC_CHANNELS.GRILL_DISCARD, (event, rawArgs: unknown): void => {
    validateSender(event)
    const args = requireObject(rawArgs, IPC_CHANNELS.GRILL_DISCARD)
    const ideaId = requireString(args, 'ideaId', IPC_CHANNELS.GRILL_DISCARD)

    grillLog.info(`[grill:discard] Discarding grill session + snapshot for idea=${ideaId}`)
    // Capture workspaceId BEFORE deleting the session/idea data
    const workspace = ideaRepository.findById(ideaId)?.workspaceId
    // GRILL-COMPLETE-DISCARD-NOTRYCATCH-01: Wrap DB ops in try-catch so a failure
    // doesn't prevent the terminal status emission below.
    try {
      grillSessionRepository.deleteByIdeaId(ideaId)
      ideaRepository.clearGrillDecisions(ideaId)
    } catch (err) {
      grillLog.error('[grill:discard] DB operation failed:', err)
    }
    // Always emit terminal status — even if DB ops failed
    if (workspace) grillPersistenceController.notifyTerminal(workspace, ideaId, 'cancelled')
  })

  // ── grill:listPlannedIdeas — idea IDs in a workspace that have a saved plan ──

  ipcMain.handle(IPC_CHANNELS.GRILL_LIST_PLANNED_IDEAS, (event, rawArgs: unknown): string[] => {
    validateSender(event)
    const args = requireObject(rawArgs, IPC_CHANNELS.GRILL_LIST_PLANNED_IDEAS)
    const workspaceId = requireString(args, 'workspaceId', IPC_CHANNELS.GRILL_LIST_PLANNED_IDEAS)
    return grillSessionRepository.findIdeaIdsWithPlan(workspaceId)
  })

  // ── grill:condenseRequirement — Haiku summarization of long docs ───

  ipcMain.handle(
    IPC_CHANNELS.GRILL_CONDENSE_REQUIREMENT,
    async (event, rawArgs: unknown): Promise<{ condensed: string }> => {
      validateSender(event)
      const args = requireObject(rawArgs, IPC_CHANNELS.GRILL_CONDENSE_REQUIREMENT)
      const text = requireString(args, 'text', IPC_CHANNELS.GRILL_CONDENSE_REQUIREMENT)
      const workspaceId = optionalString(args, 'workspaceId', IPC_CHANNELS.GRILL_CONDENSE_REQUIREMENT)
      if (text.length < 1000) {
        return { condensed: text }
      }

      grillLog.info(`[grill:condense] Condensing requirement document (${text.length} chars)`)

      try {
        const systemPrompt = [
          'You are a technical requirement condensation assistant.',
          'Condense the following requirement document into a clear, structured summary.',
          'RULES:',
          '- Preserve ALL decisions, constraints, and acceptance criteria',
          '- Remove redundant phrasing, repeated context, and verbose explanations',
          '- Keep the iteration/track structure but merge similar decisions',
          '- Use concise bullet points instead of full paragraphs',
          '- Target roughly 40-60% of the original length',
          '- Do NOT add new information or opinions',
          '- Output plain markdown — no code fences around the result'
        ].join('\n')

        const resolvedCondenseModel = workspaceId
          ? modelConfigService.getModelById(workspaceId, 'condense')
          : DEFAULT_MODEL_CONFIG['condense']

        const { text: condensed } = await runOneShotClaude({
          feature: 'condense',
          model: resolvedCondenseModel,
          args: [
            '-p',
            text,
            '--model',
            resolvedCondenseModel,
            '--system-prompt',
            systemPrompt,
            '--permission-mode',
            'plan',
            '--max-turns',
            '1'
          ],
          cli: {
            timeout: 60_000
          }
        })

        grillLog.info(
          `[grill:condense] Done — ${text.length} → ${condensed.length} chars (${Math.round((condensed.length / text.length) * 100)}%)`
        )

        return { condensed: condensed.trim() || text }
      } catch (err) {
        grillLog.error('[grill:condense] Failed:', err)
        throw new Error(`Condensation failed: ${err instanceof Error ? err.message : String(err)}`)
      }
    }
  )
}

// ── Event forwarding ─────────────────────────────────────────────────────

const grillCleanup = createTimedCleanupMap('grill')

/**
 * Wire per-workspace event listeners for the current grill evaluation.
 * Transforms stream chunks, then routes through the persistence controller
 * which both persists to DB and forwards to the renderer via SessionEventRouter.
 */
function wireGrillEvents(workspaceId: string, workspacePath: string): void {
  const cleanups = grillCleanup.prepareCleanups(workspaceId)
  const router = getSessionEventRouter()

  // ── stream — transform chunk + route through persistence ──
  grillCleanup.addListener<{ workspaceId?: string; chunk: StreamChunk }>(
    cleanups,
    grillAgentService,
    'stream',
    (data) => {
      const { chunk } = data

      if (chunk.type === 'text' && chunk.content) {
        grillPersistenceController.handleStreamChunk(
          { type: 'text', content: chunk.content },
          workspaceId,
          router
        )
      } else if (
        chunk.type === 'tool_use' ||
        chunk.type === 'tool_result' ||
        chunk.type === 'tool_progress'
      ) {
        const result = processToolChunk(chunk, {
          workspacePath,
          agentType: 'grill',
          formatTagsToSkip: ['grill-evaluation']
        })
        if (result) {
          grillPersistenceController.handleStreamChunk(result, workspaceId, router)
        }
      }
    }
  )

  // ── status — forward live token/context counters to the renderer ──
  grillCleanup.addListener<{ workspaceId?: string; status: AgentStatus }>(
    cleanups,
    grillAgentService,
    'status',
    (data) => {
      if (data.workspaceId && data.workspaceId !== workspaceId) return
      router.sendWorkspaceEvent(IPC_CHANNELS.AGENT_STATUS_UPDATE, workspaceId, { ...data.status })
    }
  )

  // ── evaluation — through persistence controller ──
  grillCleanup.addListener<GrillEvaluation & { workspaceId?: string }>(
    cleanups,
    grillAgentService,
    'evaluation',
    (data) => {
      grillPersistenceController.handleEvaluationResult(data, workspaceId, router)
    }
  )

  // ── complete — through persistence controller ──
  grillCleanup.addListener<{ workspaceId?: string } | undefined>(
    cleanups,
    grillAgentService,
    'complete',
    () => {
      // GRILL-DEDUP-NOTIF-01: Read evaluationHandled BEFORE handleComplete()
      // clears tracking state. The normal path dispatches 'needs_input' from
      // handleEvaluationResult — only fire the 'completed' notification when
      // no evaluation was parsed (recovery/empty-evaluation path).
      const tracking = grillPersistenceController.getTrackingForWorkspace(workspaceId)
      const evaluationWasHandled = tracking?.evaluationHandled ?? false

      grillPersistenceController.handleComplete(workspaceId, router)

      if (!evaluationWasHandled) {
        notificationService.dispatch({
          workspaceId,
          workspaceName: resolveWorkspaceName(workspaceId),
          service: 'grill',
          status: 'completed',
          summary: 'Grill evaluation complete — review your score and questions',
          targetPage: 'grill'
        })
      }

      grillCleanup.runCleanup(workspaceId)
    }
  )

  // Safety net: auto-clean listeners after 60 min (max adapter timeout is 45 min)
  grillCleanup.scheduleAutoCleanup(workspaceId, cleanups, 60 * 60_000)
}

/**
 * GrillPersistenceController — sits between GrillAgentService events and the renderer.
 *
 * Responsibilities:
 *   1. Persist messages to DB as chunks arrive (buffered — flush every 2 seconds or on boundaries)
 *   2. Forward events to renderer (same as current wireGrillEvents)
 *   3. Update session status on state transitions
 *   4. Handle reconnect — when renderer mounts, serve full state from DB + attach to live events
 */

import log from 'electron-log'
import type { GrillTrackId, GrillEvaluation, ToolActivity } from '../../shared/types'
import type { GrillSession, GrillSessionStatus } from '../db/repositories/grill-session.repository'
import { grillSessionRepository } from '../db/repositories'
import { getDatabase } from '../db/index'
import { IPC_CHANNELS } from '../../shared/constants'
import { getSessionEventRouter, type SessionEventRouter } from './session-event-router'
import { TextDeltaBatcher } from '../ipc/text-delta-batcher'
import { notificationService } from './notification.service'
import { resolveWorkspaceName } from '../ipc/resolve-workspace-name'

const ctrlLog = log.scope('grill-persistence')

/** Lightweight chat message shape for DB persistence */
interface PersistableMessage {
  type: string
  content?: string
  toolActivities?: unknown[]
  score?: number
  scoreLabel?: string
  feedback?: string
  trackName?: string
  questions?: unknown[]
  questionStates?: Record<string, unknown>
}

/** Status payload sent to the renderer */
export interface GrillStatusPayload {
  status: GrillSessionStatus
  ideaId: string
  trackId: GrillTrackId | null
  score: number | null
}

// GRILL-01 + GRILL-06: Per-workspace tracking state to prevent concurrent
// evaluations from overwriting each other's session/idea/track IDs.
interface WorkspaceTrackingState {
  sessionId: string
  ideaId: string
  trackId: GrillTrackId
  workspaceId: string
  evaluationHandled: boolean
  messageBuffer: PersistableMessage[]
  flushTimer: NodeJS.Timeout | null
}

export class GrillPersistenceController {
  /** Per-workspace tracking state — keyed by workspaceId. */
  private activeSessions = new Map<string, WorkspaceTrackingState>()
  /** Batches renderer-bound text at ~30fps so grill streams as smoothly as chat. */
  private textBatcher = new TextDeltaBatcher()

  /** Buffer flush interval in ms */
  private static readonly FLUSH_INTERVAL_MS = 2000

  /** Get tracking state for a workspace (returns null if not tracking). */
  private getTracking(workspaceId: string): WorkspaceTrackingState | null {
    return this.activeSessions.get(workspaceId) ?? null
  }

  /** Public read-only access to tracking state (used by grill.ipc.ts to check evaluationHandled). */
  getTrackingForWorkspace(workspaceId: string): { evaluationHandled: boolean } | null {
    const tracking = this.activeSessions.get(workspaceId)
    if (!tracking) return null
    return { evaluationHandled: tracking.evaluationHandled }
  }

  // ── Public API ────────────────────────────────────────────────────────

  /** Start tracking a grill evaluation — creates/updates DB session */
  async startTracking(ideaId: string, workspaceId: string, trackId: GrillTrackId): Promise<string> {
    // Check for existing session for this idea
    let session = grillSessionRepository.findByIdeaId(ideaId)

    if (session) {
      // Re-use existing session — update track + status
      grillSessionRepository.updateTrackId(session.id, trackId)
      grillSessionRepository.updateStatus(session.id, 'evaluating')
    } else {
      // Create new session
      session = grillSessionRepository.create(ideaId, workspaceId, trackId)
      grillSessionRepository.updateStatus(session.id, 'evaluating')
    }

    // GRILL-TIMER-RACE-01 + GRILL-BUFFER-ORPHAN-01: Clear old flush timer and
    // flush buffered messages before overwriting tracking state to prevent
    // dangling timers and orphaned message data.
    const oldTracking = this.activeSessions.get(workspaceId)
    if (oldTracking) {
      if (oldTracking.flushTimer) {
        clearTimeout(oldTracking.flushTimer)
      }
      this.flushToDb(workspaceId)
    }

    // GRILL-01: Store per-workspace tracking state
    this.activeSessions.set(workspaceId, {
      sessionId: session.id,
      ideaId,
      trackId,
      workspaceId,
      evaluationHandled: false,
      messageBuffer: [],
      flushTimer: null
    })

    // Emit status change so the bottom status bar shows the active "Grilling…"
    // pill immediately. Mirrors the markEvaluating / clearTracking pattern.
    try {
      const router = getSessionEventRouter()
      this.emitStatusChange(workspaceId, router, 'evaluating')
    } catch {
      /* router may not be initialized yet */
    }

    ctrlLog.info(
      `[grill-persistence] Tracking session=${session.id} idea=${ideaId} track=${trackId}`
    )
    return session.id
  }

  /** Handle stream chunk — buffer and forward to renderer */
  handleStreamChunk(
    chunkData: { type: string; content?: string; toolActivity?: ToolActivity },
    workspaceId: string,
    router: SessionEventRouter
  ): void {
    // Forward to renderer — text is batched at ~30fps (matching chat), tool
    // activities flush pending text first then forward immediately so ordering
    // is preserved. DB buffering below still accumulates per-chunk.
    if (chunkData.type === 'text' && chunkData.content) {
      this.textBatcher.push(workspaceId, chunkData.content, (text) => {
        router.sendWorkspaceEvent(IPC_CHANNELS.GRILL_STREAM_CHUNK, workspaceId, {
          type: 'text',
          content: text
        })
      })
    } else if (chunkData.type === 'tool_activity' && chunkData.toolActivity) {
      this.textBatcher.flush(workspaceId)
      router.sendWorkspaceEvent(IPC_CHANNELS.GRILL_STREAM_CHUNK, workspaceId, chunkData)
    } else {
      router.sendWorkspaceEvent(IPC_CHANNELS.GRILL_STREAM_CHUNK, workspaceId, chunkData)
    }

    // Buffer agent content for DB persistence (per-workspace buffer)
    const tracking = this.getTracking(workspaceId)
    if (tracking) {
      const buffer = tracking.messageBuffer
      if (chunkData.type === 'text' && chunkData.content) {
        // Accumulate text into buffer — will be flushed as agent message
        const lastMsg = buffer[buffer.length - 1]
        if (lastMsg && lastMsg.type === 'agent') {
          lastMsg.content = (lastMsg.content ?? '') + chunkData.content
        } else {
          buffer.push({ type: 'agent', content: chunkData.content, toolActivities: [] })
        }
      } else if (chunkData.type === 'tool_activity' && chunkData.toolActivity) {
        // Append tool activity to the current agent message
        const lastMsg = buffer[buffer.length - 1]
        if (lastMsg && lastMsg.type === 'agent') {
          if (!lastMsg.toolActivities) lastMsg.toolActivities = []
          // Merge tool_use → tool_result by ID
          const existingIdx = lastMsg.toolActivities.findIndex(
            (ta: unknown) => (ta as Record<string, unknown>).id === chunkData.toolActivity!.id
          )
          if (existingIdx >= 0) {
            lastMsg.toolActivities[existingIdx] = {
              ...(lastMsg.toolActivities[existingIdx] as Record<string, unknown>),
              ...chunkData.toolActivity
            }
          } else {
            lastMsg.toolActivities.push(chunkData.toolActivity)
          }
        } else {
          buffer.push({
            type: 'agent',
            content: '',
            toolActivities: [chunkData.toolActivity]
          })
        }
      }

      // Schedule flush if not already pending
      this.scheduleFlush(workspaceId)
    }
  }

  /** Handle evaluation result — persist score + questions, update status */
  handleEvaluationResult(
    evaluation: GrillEvaluation,
    workspaceId: string,
    router: SessionEventRouter
  ): void {
    // Flush any buffered narration before the evaluation result so text ordering
    // is preserved on the renderer.
    this.textBatcher.flush(workspaceId)

    const tracking = this.getTracking(workspaceId)
    if (!tracking) {
      // GRILL-EVAL-RENDER-BEFORE-DB-01: For greenfield (no tracking), send directly.
      router.sendWorkspaceEvent(
        IPC_CHANNELS.GRILL_EVALUATION_RESULT,
        workspaceId,
        evaluation as unknown as Record<string, unknown>
      )
      return
    }

    // Flush any pending text/tool messages first
    this.flushToDb(workspaceId)

    // GRILL-EVAL-RENDER-BEFORE-DB-01: Persist to DB FIRST, then notify renderer.
    // If the transaction fails, don't send stale data to the renderer.
    // GRILL-TX-NOERRHANDLING-01: Wrap transaction in try-catch so a DB failure
    // doesn't crash the event listener. If it fails, evaluationHandled stays false
    // and handleComplete() recovery logic will kick in.
    try {
      const db = getDatabase()
      db.transaction(() => {
        grillSessionRepository.updateScore(
          tracking.sessionId,
          evaluation.score,
          evaluation.scoreLabel,
          evaluation.feedback
        )
        grillSessionRepository.updateQuestionStates(
          tracking.sessionId,
          null, // question states will be set by user answers
          evaluation
        )
        grillSessionRepository.updateStatus(tracking.sessionId, 'awaiting_answers')
      })()

      // GRILL-EVAL-01: Set flag AFTER transaction succeeds so recovery logic in
      // handleComplete() can detect and handle DB failures.
      tracking.evaluationHandled = true
    } catch (err) {
      ctrlLog.error('[grill-persistence] Evaluation transaction failed:', err)
      // evaluationHandled stays false — handleComplete() will recover gracefully.
      // Don't send to renderer if DB persistence failed.
      return
    }

    // GRILL-EVAL-RENDER-BEFORE-DB-01: Send to renderer ONLY after DB succeeds.
    router.sendWorkspaceEvent(
      IPC_CHANNELS.GRILL_EVALUATION_RESULT,
      workspaceId,
      evaluation as unknown as Record<string, unknown>
    )

    // GRILL-HANDLEEVAL-EMIT-UNGUARDED-01: Wrap in try-catch matching
    // startTracking/clearTracking pattern. If router throws here,
    // evaluationHandled is already set — recovery in handleComplete() is safe.
    try {
      this.emitStatusChange(workspaceId, router, 'awaiting_answers')
    } catch {
      /* router may not be initialized or window destroyed */
    }

    notificationService.dispatch({
      workspaceId,
      workspaceName: resolveWorkspaceName(workspaceId),
      service: 'grill',
      status: 'needs_input',
      summary: 'Grill Me has questions — your answers improve the plan',
      targetPage: 'grill'
    })

    ctrlLog.info(
      `[grill-persistence] Evaluation complete — session=${tracking.sessionId} score=${evaluation.score}`
    )
  }

  /** Handle stream complete — flush buffer, finalize */
  handleComplete(workspaceId: string, router: SessionEventRouter): void {
    // Flush trailing narration before the complete event, then forget the flusher.
    this.textBatcher.reset(workspaceId)

    // Forward to renderer via router
    router.sendWorkspaceEvent(IPC_CHANNELS.GRILL_STREAM_COMPLETE, workspaceId, {})

    const tracking = this.getTracking(workspaceId)

    // GRILL-FLUSH-UNWAITED-01: Flush remaining buffer using a local reference
    // instead of going through flushToDb() → getTracking(). If flushToDb()
    // fails and schedules a retry via scheduleFlush(), the retry fires after
    // tracking is deleted — permanently orphaning the buffer. By flushing
    // directly here, we fail-fast on the final flush and avoid dangling retries.
    if (tracking && tracking.messageBuffer.length > 0) {
      if (tracking.flushTimer) {
        clearTimeout(tracking.flushTimer)
        tracking.flushTimer = null
      }
      try {
        grillSessionRepository.appendMessages(tracking.sessionId, tracking.messageBuffer)
        tracking.messageBuffer = []
      } catch (err) {
        ctrlLog.error('[grill-persistence] Final flush failed — messages lost:', err)
      }
    }

    // GRILL-06: Guard uses per-workspace evaluationHandled flag
    // Guard against the empty-evaluation dead-end: if the stream ended without
    // a parseable evaluation block (handleEvaluationResult never fired), the
    // session is still pinned at 'evaluating' and nothing will ever move it.
    // Revert it to a recoverable state so the UI doesn't get stuck "Grilling…".
    if (tracking && !tracking.evaluationHandled) {
      const session = grillSessionRepository.findById(tracking.sessionId)
      if (session && session.status === 'evaluating') {
        const recovered: GrillSessionStatus =
          session.currentScore !== null ? 'awaiting_answers' : 'failed'
        grillSessionRepository.updateStatus(tracking.sessionId, recovered)
        this.emitStatusChange(workspaceId, router, recovered)
        ctrlLog.warn(
          `[grill-persistence] Stream ended with no evaluation — reverting session=${tracking.sessionId} evaluating→${recovered}`
        )
      }
    }

    // GRILL-TRACK-01: Clean up tracking state to prevent memory leaks and
    // potential message corruption if a new evaluation starts in the same workspace.
    if (tracking) {
      if (tracking.flushTimer) {
        clearTimeout(tracking.flushTimer)
        tracking.flushTimer = null
      }
      this.activeSessions.delete(workspaceId)
    }

    ctrlLog.info(`[grill-persistence] Stream complete — session=${tracking?.sessionId ?? 'none'}`)
  }

  /** Save user's question answers to DB */
  saveAnswers(sessionId: string, questionStates: Record<string, unknown>): void {
    const session = grillSessionRepository.findById(sessionId)
    if (!session) return

    // GRILL-SAVEANSWERS-NOGUARD-01: Wrap in try-catch to prevent a DB error
    // from propagating to the IPC handler as an unhandled exception.
    try {
      grillSessionRepository.updateQuestionStates(sessionId, questionStates, session.currentIteration)
    } catch (err) {
      ctrlLog.error(`[grill-persistence] saveAnswers failed for session=${sessionId}:`, err)
    }
  }

  /** Mark session as evaluating (re-evaluation after answers) */
  markEvaluating(sessionId: string, workspaceId: string): void {
    grillSessionRepository.updateStatus(sessionId, 'evaluating')

    const session = grillSessionRepository.findById(sessionId)
    if (session && session.trackId) {
      // GRILL-TIMER-RACE-01 + GRILL-BUFFER-ORPHAN-01: Clear old timer and flush
      // buffer before overwriting to prevent dangling timers and data loss.
      const oldTracking = this.activeSessions.get(workspaceId)
      if (oldTracking) {
        if (oldTracking.flushTimer) {
          clearTimeout(oldTracking.flushTimer)
        }
        this.flushToDb(workspaceId)
      }

      // GRILL-01: Update per-workspace tracking state
      this.activeSessions.set(workspaceId, {
        sessionId,
        ideaId: session.ideaId,
        trackId: session.trackId,
        workspaceId,
        evaluationHandled: false,
        messageBuffer: [],
        flushTimer: null
      })
    }

    // GRILL-MARKEVALUATING-EMIT-UNGUARDED-01: Wrap router calls in try-catch
    // matching the pattern in startTracking/clearTracking.
    try {
      const router = getSessionEventRouter()
      this.emitStatusChange(workspaceId, router, 'evaluating')
    } catch {
      /* router may not be initialized during re-evaluation */
    }
  }

  /** Get the current grill status for a workspace (for status bar + icons) */
  getStatusForWorkspace(workspaceId: string): GrillStatusPayload | null {
    const sessions = grillSessionRepository.getActiveForWorkspace(workspaceId)
    if (sessions.length === 0) return null

    const active = sessions[0]
    return {
      status: active.status,
      ideaId: active.ideaId,
      trackId: active.trackId,
      score: active.currentScore
    }
  }

  /** Get full session state for reconnect */
  getSessionState(ideaId: string): GrillSession | null {
    return grillSessionRepository.findByIdeaId(ideaId)
  }

  /** Get the currently active session ID (first active session, for backward compat) */
  get currentSessionId(): string | null {
    for (const state of this.activeSessions.values()) {
      return state.sessionId
    }
    return null
  }

  /**
   * Emit a terminal status event (completed/cancelled) so the renderer badge
   * clears immediately. Called from GRILL_COMPLETE and GRILL_DISCARD handlers.
   */
  notifyTerminal(workspaceId: string, ideaId: string, status: GrillSessionStatus): void {
    try {
      getSessionEventRouter().sendWorkspaceEvent(IPC_CHANNELS.GRILL_STATUS_CHANGED, workspaceId, {
        status,
        ideaId,
        trackId: null,
        score: null
      })
    } catch {
      /* router may not be initialized */
    }
    const tracking = this.getTracking(workspaceId)
    if (tracking && tracking.ideaId === ideaId) {
      // GRILL-FLUSH-ORPHAN-01: Inline flush instead of flushToDb() to prevent
      // the retry-then-delete race. flushToDb() schedules a retry on failure,
      // but the next line deletes the tracking state — the retry finds nothing.
      if (tracking.flushTimer) { clearTimeout(tracking.flushTimer); tracking.flushTimer = null }
      if (tracking.messageBuffer.length > 0) {
        try {
          grillSessionRepository.appendMessages(tracking.sessionId, tracking.messageBuffer)
        } catch (err) {
          ctrlLog.error('[grill-persistence] Terminal flush failed — messages lost:', err)
        }
      }
      this.activeSessions.delete(workspaceId)
    }
  }

  /** Clear active tracking (on cancel). Optionally scoped to a workspace. */
  clearTracking(workspaceId?: string): void {
    // GRILL-02 + GRILL-03: Accept workspaceId so cancel targets the right workspace
    // and status emission uses the correct workspaceId instead of empty string.
    if (workspaceId) {
      const tracking = this.getTracking(workspaceId)
      if (tracking) {
        // GRILL-TIMER-01: Clear flush timer before cleanup to prevent
        // dangling setTimeout callbacks accessing deleted tracking state.
        if (tracking.flushTimer) {
          clearTimeout(tracking.flushTimer)
          tracking.flushTimer = null
        }
        this.textBatcher.reset(workspaceId)
        grillSessionRepository.updateStatus(tracking.sessionId, 'cancelled')
        try {
          const router = getSessionEventRouter()
          this.emitStatusChange(workspaceId, router, 'cancelled')
        } catch {
          /* router may not be initialized during early cancellation */
        }
        // GRILL-FLUSH-ORPHAN-01: Inline flush — same pattern as notifyTerminal().
        if (tracking.messageBuffer.length > 0) {
          try {
            grillSessionRepository.appendMessages(tracking.sessionId, tracking.messageBuffer)
          } catch (err) {
            ctrlLog.error('[grill-persistence] Cancel flush failed — messages lost:', err)
          }
        }
        this.activeSessions.delete(workspaceId)
      }
    } else {
      // Cancel ALL active sessions (backward compat)
      for (const [wsId, tracking] of this.activeSessions) {
        // GRILL-TIMER-01: Clear flush timer before cleanup
        if (tracking.flushTimer) {
          clearTimeout(tracking.flushTimer)
          tracking.flushTimer = null
        }
        this.textBatcher.reset(wsId)
        grillSessionRepository.updateStatus(tracking.sessionId, 'cancelled')
        try {
          const router = getSessionEventRouter()
          this.emitStatusChange(wsId, router, 'cancelled')
        } catch {
          /* router may not be initialized during early cancellation */
        }
        // GRILL-FLUSH-ORPHAN-01: Inline flush for cancel-all branch.
        if (tracking.messageBuffer.length > 0) {
          try {
            grillSessionRepository.appendMessages(tracking.sessionId, tracking.messageBuffer)
          } catch (err) {
            ctrlLog.error('[grill-persistence] Cancel-all flush failed — messages lost:', err)
          }
        }
      }
      this.activeSessions.clear()
    }
  }

  // ── Private ───────────────────────────────────────────────────────────

  /** Schedule a deferred flush to DB for a specific workspace */
  private scheduleFlush(workspaceId: string): void {
    const tracking = this.getTracking(workspaceId)
    if (!tracking || tracking.flushTimer) return
    tracking.flushTimer = setTimeout(() => {
      tracking.flushTimer = null
      this.flushToDb(workspaceId)
    }, GrillPersistenceController.FLUSH_INTERVAL_MS)
  }

  /** Flush buffered messages to DB for a specific workspace */
  private flushToDb(workspaceId: string): void {
    const tracking = this.getTracking(workspaceId)
    if (!tracking) return

    if (tracking.flushTimer) {
      clearTimeout(tracking.flushTimer)
      tracking.flushTimer = null
    }

    if (tracking.messageBuffer.length === 0) return

    try {
      grillSessionRepository.appendMessages(tracking.sessionId, tracking.messageBuffer)
      // GRILL-MSG-LOSS-01: Only clear buffer on successful write.
      // Previously, buffer was always cleared — even on DB failure — causing
      // permanent data loss. Now we retain and retry on next flush.
      tracking.messageBuffer = []
    } catch (err) {
      ctrlLog.error('[grill-persistence] Failed to flush messages — will retry:', err)
      this.scheduleFlush(workspaceId)
    }
  }

  /** Emit status change event to renderer */
  private emitStatusChange(
    workspaceId: string,
    router: SessionEventRouter,
    status: GrillSessionStatus
  ): void {
    const tracking = this.getTracking(workspaceId)
    const payload: GrillStatusPayload = {
      status,
      ideaId: tracking?.ideaId ?? '',
      trackId: tracking?.trackId ?? null,
      score: null
    }

    // Fetch current score from DB for accuracy
    if (tracking) {
      const session = grillSessionRepository.findById(tracking.sessionId)
      if (session) {
        payload.score = session.currentScore
      }
    }

    router.sendWorkspaceEvent(
      IPC_CHANNELS.GRILL_STATUS_CHANGED,
      workspaceId,
      payload as unknown as Record<string, unknown>
    )
  }
}

export const grillPersistenceController = new GrillPersistenceController()

/**
 * MPA (Multi-Phased Agent) IPC handlers.
 *
 * Follows the audit.ipc.ts pattern:
 * - ipcMain.handle for request/response (start, cancel, getStatus, getRun, getHistory)
 * - webContents.send for event forwarding (phaseStart, phaseProgress, phaseComplete, etc.)
 */

import { ipcMain, type BrowserWindow } from 'electron'
import log from 'electron-log'
import { IPC_CHANNELS } from '../../shared/constants'
import { validateSender } from './validate-sender'
import { createTimedCleanupMap } from './listener-cleanup'
import { mpaOrchestrationService } from '../services/mpa-orchestration.service'
import { mpaCampaignService } from '../services/mpa-campaign.service'
import { goalDecomposerService } from '../services/goal-decomposer.service'
import { mpaRunRepository } from '../db/repositories/mpa-run.repository'
import { mpaArtifactRepository } from '../db/repositories/mpa-artifact.repository'
import { mpaCampaignRepository } from '../db/repositories/mpa-campaign.repository'
import { workspaceRepository } from '../db/repositories'
import { getSessionEventRouter } from '../services/session-event-router'
import { notificationService } from '../services/notification.service'
import { resolveWorkspaceName } from './resolve-workspace-name'
import type {
  MpaPhaseType,
  MpaPhaseStartPayload,
  MpaPhaseProgressPayload,
  MpaPhaseCompletePayload,
  MpaFeedbackLoopPayload,
  MpaApprovalNeededPayload,
  MpaPipelineCompletePayload,
  MpaStatus,
  MeasurableGoal,
  MpaCampaignPauseAction,
  MpaCampaignStartedPayload,
  MpaCampaignGoalStartPayload,
  MpaCampaignGoalCompletePayload,
  MpaCampaignPausedPayload,
  MpaCampaignCompletePayload
} from '../../shared/mpa-types'
import type { AgentStatus } from '../../shared/types'

const mpaLog = log.scope('mpa-ipc')

export function registerMpaIpc(_mainWindow: BrowserWindow): void {
  // ── mpa:cancel — Cancel running pipeline ──

  ipcMain.handle(IPC_CHANNELS.MPA_CANCEL, (event, args?: { workspaceId?: string }) => {
    validateSender(event)
    mpaOrchestrationService.cancel(args?.workspaceId)
    return { cancelled: true }
  })

  // ── mpa:getStatus — Get current pipeline status ──

  ipcMain.handle(IPC_CHANNELS.MPA_GET_STATUS, (event, args: { workspaceId: string }) => {
    validateSender(event)

    const { running, runId } = mpaOrchestrationService.getStatus(args.workspaceId)
    if (!running || !runId) {
      return {
        status: 'idle',
        runId: null,
        currentPhase: null,
        phaseIndex: 0,
        totalPhases: 0,
        iteration: 0,
        awaitingApproval: false
      } satisfies MpaStatus
    }

    const run = mpaRunRepository.findById(runId)
    const phases = run ? mpaRunRepository.findPhasesByRun(runId) : []
    const currentPhaseIdx = phases.findIndex((p) => p.status === 'running')
    const currentPhase = phases[currentPhaseIdx]

    return {
      status: run?.status ?? 'running',
      runId,
      currentPhase: (currentPhase?.phaseType ?? run?.currentPhase ?? null) as MpaPhaseType | null,
      phaseIndex: currentPhaseIdx >= 0 ? currentPhaseIdx + 1 : phases.length,
      totalPhases: phases.length || 3,
      iteration: currentPhase?.iteration ?? 1,
      awaitingApproval: run?.status === 'paused'
    } satisfies MpaStatus
  })

  // ── mpa:getRun — Get a specific run with phases and artifacts ──

  ipcMain.handle(IPC_CHANNELS.MPA_GET_RUN, (event, args: { runId: string }) => {
    validateSender(event)

    const run = mpaRunRepository.findById(args.runId)
    if (!run) return null

    const phases = mpaRunRepository.findPhasesByRun(args.runId)
    const artifacts = mpaArtifactRepository.findByRun(args.runId)

    return { run, phases, artifacts }
  })

  // ── mpa:getHistory — Get recent runs for a workspace ──

  ipcMain.handle(
    IPC_CHANNELS.MPA_GET_HISTORY,
    (event, args: { workspaceId: string; limit?: number }) => {
      validateSender(event)
      return mpaRunRepository.findByWorkspace(args.workspaceId, args.limit ?? 20)
    }
  )

  // ── mpa:approvalRespond — User gate response ──

  ipcMain.handle(
    IPC_CHANNELS.MPA_APPROVAL_RESPOND,
    (event, args: { runId: string; approved: boolean; feedback?: string }) => {
      validateSender(event)
      mpaOrchestrationService.respondToGate(args.runId, args.approved, args.feedback)
      return { responded: true }
    }
  )

  // ── mpa:resume — Resume a failed/stale run ──

  ipcMain.handle(
    IPC_CHANNELS.MPA_RESUME,
    async (event, args: { runId: string; workspaceId: string }) => {
      validateSender(event)

      const workspace = workspaceRepository.findById(args.workspaceId)
      if (!workspace) {
        throw new Error(`Workspace not found: ${args.workspaceId}`)
      }

      // Wire event forwarding for this workspace
      wireMpaEvents(args.workspaceId)

      // Resume orchestration (non-blocking)
      mpaOrchestrationService.resumeRun(args.runId).catch((err) => {
        mpaLog.error('[mpa:resume] Resume failed:', err)
      })

      return { resumed: true }
    }
  )

  // ── mpa:decomposeGoals — decompose plan/text into measurable goals ──

  ipcMain.handle(
    IPC_CHANNELS.MPA_DECOMPOSE_GOALS,
    async (event, args: { workspaceId: string; input: string }) => {
      validateSender(event)
      if (!args.workspaceId || !args.input?.trim()) {
        throw new Error('workspaceId and input are required')
      }
      return goalDecomposerService.decompose({
        workspaceId: args.workspaceId,
        input: args.input
      })
    }
  )

  // ── mpa:campaignStart — run measurable goals sequentially ──

  ipcMain.handle(
    IPC_CHANNELS.MPA_CAMPAIGN_START,
    (
      event,
      args: { workspaceId: string; title: string; originalPlanMd: string; goals: MeasurableGoal[] }
    ) => {
      validateSender(event)

      const workspace = workspaceRepository.findById(args.workspaceId)
      if (!workspace) {
        throw new Error(`Workspace not found: ${args.workspaceId}`)
      }
      if (!Array.isArray(args.goals) || args.goals.length === 0) {
        throw new Error('At least one goal is required')
      }
      // Reject if a standalone MPA pipeline is already running for this workspace
      // — otherwise the campaign's first goal would throw "pipeline already
      // running" inside the loop and immediately pause. (mpaCampaignService.start
      // already guards against a second concurrent campaign.)
      if (mpaOrchestrationService.isRunningForWorkspace(args.workspaceId)) {
        throw new Error(
          'A goal pipeline is already running for this workspace. Wait for it to finish before starting a campaign.'
        )
      }

      // Forward campaign + per-goal MPA events to the renderer. Must be wired
      // BEFORE start() — start() emits campaignStarted/campaignGoalStart
      // synchronously as the loop kicks off.
      wireCampaignEvents(args.workspaceId)

      return mpaCampaignService.start({
        workspaceId: args.workspaceId,
        workspacePath: workspace.repoPath,
        title: args.title,
        originalPlanMd: args.originalPlanMd,
        goals: args.goals
      })
    }
  )

  // ── mpa:campaignRespond — resolve a paused campaign (retry/skip/stop) ──

  ipcMain.handle(
    IPC_CHANNELS.MPA_CAMPAIGN_RESPOND,
    (event, args: { workspaceId: string; action: MpaCampaignPauseAction }) => {
      validateSender(event)
      mpaCampaignService.respond(args.workspaceId, args.action)
      return { responded: true }
    }
  )

  // ── mpa:campaignCancel — cancel the active campaign ──

  ipcMain.handle(IPC_CHANNELS.MPA_CAMPAIGN_CANCEL, (event, args: { workspaceId: string }) => {
    validateSender(event)
    mpaCampaignService.cancel(args.workspaceId)
    return { cancelled: true }
  })

  // ── mpa:campaignGetHistory — persisted campaigns for a workspace ──

  ipcMain.handle(
    IPC_CHANNELS.MPA_CAMPAIGN_GET_HISTORY,
    (event, args: { workspaceId: string; limit?: number }) => {
      validateSender(event)
      return mpaCampaignRepository.findByWorkspace(args.workspaceId, args.limit ?? 20)
    }
  )

  // ── mpa:campaignGetDetail — a campaign + its runs (grouped history) ──

  ipcMain.handle(IPC_CHANNELS.MPA_CAMPAIGN_GET_DETAIL, (event, args: { campaignId: string }) => {
    validateSender(event)
    const campaign = mpaCampaignRepository.findById(args.campaignId)
    if (!campaign) return null
    const runs = mpaRunRepository.findByCampaign(args.campaignId)
    return { campaign, runs }
  })

  // ── Stale run + campaign detection on registration ──
  // Mark any runs/campaigns that were active when the app last quit as 'failed'
  mpaOrchestrationService.reconcileStaleRuns()
  mpaCampaignService.reconcileStale()
}

// ── Event Forwarding (per-workspace, tagged with workspaceId) ──

const mpaCleanup = createTimedCleanupMap('mpa')

function wireMpaEvents(workspaceId: string): void {
  const cleanups = mpaCleanup.prepareCleanups(workspaceId)
  // Lazy router resolution

  mpaCleanup.addListener<MpaPhaseStartPayload>(
    cleanups,
    mpaOrchestrationService,
    'phaseStart',
    (payload) => {
      mpaLog.info(`[event] phaseStart: ${payload.phaseType} (iteration ${payload.iteration})`)
      getSessionEventRouter().sendWorkspaceEvent(
        IPC_CHANNELS.MPA_PHASE_START,
        workspaceId,
        payload as unknown as Record<string, unknown>
      )
    }
  )

  mpaCleanup.addListener<MpaPhaseProgressPayload>(
    cleanups,
    mpaOrchestrationService,
    'phaseProgress',
    (payload) => {
      getSessionEventRouter().sendWorkspaceEvent(
        IPC_CHANNELS.MPA_PHASE_PROGRESS,
        workspaceId,
        payload as unknown as Record<string, unknown>
      )
    }
  )

  // Forward live token/context counters so the usage modal reflects MPA activity.
  mpaCleanup.addListener<{ workspaceId?: string; status: AgentStatus }>(
    cleanups,
    mpaOrchestrationService,
    'status',
    (data) => {
      if (data.workspaceId && data.workspaceId !== workspaceId) return
      getSessionEventRouter().sendWorkspaceEvent(IPC_CHANNELS.AGENT_STATUS_UPDATE, workspaceId, { ...data.status })
    }
  )

  mpaCleanup.addListener<MpaPhaseCompletePayload>(
    cleanups,
    mpaOrchestrationService,
    'phaseComplete',
    (payload) => {
      mpaLog.info(`[event] phaseComplete: ${payload.phaseType} — ${payload.status}`)
      getSessionEventRouter().sendWorkspaceEvent(
        IPC_CHANNELS.MPA_PHASE_COMPLETE,
        workspaceId,
        payload as unknown as Record<string, unknown>
      )
    }
  )

  mpaCleanup.addListener<MpaFeedbackLoopPayload>(
    cleanups,
    mpaOrchestrationService,
    'feedbackLoop',
    (payload) => {
      mpaLog.info(
        `[event] feedbackLoop: ${payload.fromPhase} → ${payload.toPhase} (iteration ${payload.iteration})`
      )
      getSessionEventRouter().sendWorkspaceEvent(
        IPC_CHANNELS.MPA_FEEDBACK_LOOP,
        workspaceId,
        payload as unknown as Record<string, unknown>
      )
    }
  )

  mpaCleanup.addListener<MpaApprovalNeededPayload>(
    cleanups,
    mpaOrchestrationService,
    'approvalNeeded',
    (payload) => {
      mpaLog.info(`[event] approvalNeeded for run ${payload.runId}`)
      getSessionEventRouter().sendWorkspaceEvent(
        IPC_CHANNELS.MPA_APPROVAL_NEEDED,
        workspaceId,
        payload as unknown as Record<string, unknown>
      )

      notificationService.dispatch({
        workspaceId,
        workspaceName: resolveWorkspaceName(workspaceId),
        service: 'mpa',
        status: 'needs_input',
        summary: 'Pipeline gate reached — approval needed to continue',
        targetPage: 'mpa'
      })
    }
  )

  mpaCleanup.addListener<MpaPipelineCompletePayload>(
    cleanups,
    mpaOrchestrationService,
    'pipelineComplete',
    (payload) => {
      mpaLog.info(`[event] pipelineComplete: ${payload.status}`)
      getSessionEventRouter().sendWorkspaceEvent(
        IPC_CHANNELS.MPA_PIPELINE_COMPLETE,
        workspaceId,
        payload as unknown as Record<string, unknown>
      )

      // Skip user-initiated cancellations — no notification needed
      if (payload.status !== 'cancelled') {
        notificationService.dispatch({
          workspaceId,
          workspaceName: resolveWorkspaceName(workspaceId),
          service: 'mpa',
          status:
            payload.status === 'completed'
              ? 'completed'
              : payload.status === 'paused'
                ? 'needs_input'
                : 'failed',
          summary:
            payload.status === 'paused'
              ? 'Pipeline paused — action may be needed'
              : `Pipeline ${payload.status}`,
          targetPage: 'mpa'
        })
      }

      mpaCleanup.runCleanup(workspaceId)
    }
  )

  // Safety net: auto-clean listeners after 120 min (3 phases + approval gate + retry)
  mpaCleanup.scheduleAutoCleanup(workspaceId, cleanups, 120 * 60_000)
}

// ── Campaign Event Forwarding (per-workspace) ──

const mpaCampaignCleanup = createTimedCleanupMap('mpa-campaign')

function wireCampaignEvents(workspaceId: string): void {
  const cleanups = mpaCampaignCleanup.prepareCleanups(workspaceId)
  // Lazy router resolution

  mpaCampaignCleanup.addListener<MpaCampaignStartedPayload>(
