    const duplicates = parsedTasks.filter((t, i) =>
      parsedTasks.findIndex((x) => x.taskId === t.taskId) !== i
    )
    assert.equal(duplicates.length, 1)
    assert.equal(duplicates[0].taskId, 'R001')
  })
})

