    assert.equal(goalQueued, false)
  })

  test('enforce mode → /goal queued', () => {
    const { goalQueued, goalCmd } = simulateGoalQueueing('All tests pass', 'enforce')
    assert.equal(goalQueued, true)
    assert.equal(goalCmd, '/goal All tests pass')
  })

