{"questions": [{"header": "H", "question": "Q?", "multiSelect": false, "options": [{"label": "A", "recommended": true}]}]}
\`\`\``
      const result = parseClarifyQuestions(text)
      assert.ok(result)
      assert.equal(result.questions[0].id, 'q1')
    })
  })

  // ── parseClarifyCompletion ──

  describe('parseClarifyCompletion', () => {
    test('parses valid completion block', () => {
      const text = `\`\`\`blueprint-phase-complete
{"phase": "clarify", "status": "complete", "questionsAsked": 3, "questionsAnswered": 3}
\`\`\``
      const result = parseClarifyCompletion(text)
      assert.ok(result)
      assert.equal(result.phase, 'clarify')
      assert.equal(result.status, 'complete')
      assert.equal(result.questionsAsked, 3)
    })

    test('returns null for non-clarify completion', () => {
      const text = `\`\`\`blueprint-phase-complete
{"phase": "specify", "status": "complete"}
\`\`\``
      assert.equal(parseClarifyCompletion(text), null)
    })

    test('returns null when no block', () => {
      assert.equal(parseClarifyCompletion('no completion'), null)
    })
  })

  // ── stripBlueprintBlocks ──

  describe('stripBlueprintBlocks', () => {
    test('removes all three block types', () => {
      const text = `Intro.

\`\`\`blueprint-clarify-findings
{"findings": [], "summary": ""}
\`\`\`

Middle.

\`\`\`blueprint-clarify-questions
{"questions": []}
\`\`\`

End.

\`\`\`blueprint-phase-complete
{"phase": "clarify", "status": "complete"}
\`\`\``

      const result = stripBlueprintBlocks(text)
      assert.ok(!result.includes('blueprint-clarify-findings'))
      assert.ok(!result.includes('blueprint-clarify-questions'))
      assert.ok(!result.includes('blueprint-phase-complete'))
      assert.ok(result.includes('Intro.'))
      assert.ok(result.includes('Middle.'))
      assert.ok(result.includes('End.'))
    })

    test('returns trimmed text when no blocks present', () => {
      const result = stripBlueprintBlocks('  Hello world  ')
      assert.equal(result, 'Hello world')
    })

    test('strips partial/unterminated fence (mid-stream)', () => {
      const text = `Here is my analysis of the requirements.

\`\`\`blueprint-clarify-findings
{"findings": [{"id": "f1", "category": "sec`

      const result = stripBlueprintBlocks(text)
      assert.ok(!result.includes('blueprint-clarify-findings'))
      assert.ok(!result.includes('{"findings"'))
      assert.ok(result.includes('Here is my analysis'))
    })

    test('strips 4-backtick fences', () => {
      const text = `Intro text.

\`\`\`\`blueprint-clarify-findings
{"findings": [], "summary": "none"}
\`\`\`\`

After.`

      const result = stripBlueprintBlocks(text)
      assert.ok(!result.includes('blueprint-clarify-findings'))
      assert.ok(!result.includes('{"findings"'))
      assert.ok(result.includes('Intro text.'))
      assert.ok(result.includes('After.'))
    })

    test('strips any blueprint-* fence name', () => {
      const text = `Before.

\`\`\`blueprint-plan-tasks
{"tasks": []}
\`\`\`

After.`

      const result = stripBlueprintBlocks(text)
      assert.ok(!result.includes('blueprint-plan-tasks'))
      assert.ok(!result.includes('{"tasks"'))
      assert.ok(result.includes('Before.'))
      assert.ok(result.includes('After.'))
    })

    test('preserves prose when partial fence is at end', () => {
      const text = `This is important context that the user should see.

I found several issues:
1. Missing auth
2. No error handling

\`\`\`blueprint-clarify-findings
{"findings": [{"id":`

      const result = stripBlueprintBlocks(text)
      assert.ok(result.includes('This is important context'))
      assert.ok(result.includes('Missing auth'))
      assert.ok(result.includes('No error handling'))
      assert.ok(!result.includes('blueprint-clarify-findings'))
      assert.ok(!result.includes('{"findings"'))
    })
  })

  // ── parseBlueprintPlan ──

  describe('parseBlueprintPlan', () => {
    test('parses valid plan block', () => {
      const text = `Here is the plan.

\`\`\`blueprint-plan
{"items": [{"id": 1, "title": "Setup auth", "description": "Add OAuth2", "files": ["auth.ts"]}]}
\`\`\`

Done.`
      const result = parseBlueprintPlan(text)
      assert.ok(result)
      assert.equal((result.items as unknown[]).length, 1)
    })

    test('returns null when no plan block', () => {
      assert.equal(parseBlueprintPlan('no plan here'), null)
    })

    test('uses last block when multiple present', () => {
      const text = `\`\`\`blueprint-plan
{"items": [{"id": "old"}]}
\`\`\`
\`\`\`blueprint-plan
{"items": [{"id": "new"}]}
\`\`\``
      const result = parseBlueprintPlan(text)
      assert.ok(result)
      assert.equal((result.items as Array<{id:string}>)[0].id, 'new')
    })
  })

  // ── parseBlueprintTasks ──

  describe('parseBlueprintTasks', () => {
    test('parses valid tasks block', () => {
      const text = `\`\`\`blueprint-tasks
{"tasks": [{"id": "t1", "description": "Build login", "wave": 1}]}
\`\`\``
      const result = parseBlueprintTasks(text)
      assert.ok(result)
      assert.equal((result.tasks as unknown[]).length, 1)
    })

    test('returns null when no tasks block', () => {
      assert.equal(parseBlueprintTasks('nothing'), null)
    })
  })

  // ── clarifyQuestionToGrillQuestion ──

  describe('clarifyQuestionToGrillQuestion', () => {
    test('maps fields correctly with allowOther=true', () => {
      const q: ClarifyQuestion = {
        id: 'q1',
        header: 'Auth Strategy',
        question: 'Which auth?',
        multiSelect: false,
        options: [
          { label: 'OAuth2', recommended: true, recommendedReason: 'Standard' },
          { label: 'API keys', recommended: false }
        ]
      }
      const gq = clarifyQuestionToGrillQuestion(q)
      assert.equal(gq.id, 'q1')
      assert.equal(gq.question, 'Which auth?')
      assert.equal(gq.header, 'Auth Strategy')
      assert.equal(gq.multiSelect, false)
      assert.equal(gq.allowOther, true)
      assert.equal(gq.options.length, 2)
      assert.equal(gq.options[0].recommended, true)
      assert.equal(gq.options[0].recommendedReason, 'Standard')
    })
  })

  // ── formatClarifyAnswerMessage ──

  describe('formatClarifyAnswerMessage', () => {
    const questions: ClarifyQuestion[] = [
      { id: 'q1', header: 'Auth', question: 'Which?', multiSelect: false, options: [{ label: 'OAuth2', recommended: true }] },
      { id: 'q2', header: 'DB', question: 'Which?', multiSelect: true, options: [{ label: 'Postgres', recommended: true }] }
    ]

    test('formats selected options with question IDs', () => {
      const states: Record<string, QuestionAnswerState> = {
        q1: { selectedOptions: ['OAuth2'], otherText: '', otherSelected: false, skipped: false },
        q2: { selectedOptions: ['Postgres', 'Redis'], otherText: '', otherSelected: false, skipped: false }
      }
      const result = formatClarifyAnswerMessage(questions, states)
      assert.ok(result.includes('**q1 — Auth**: OAuth2'))
      assert.ok(result.includes('**q2 — DB**: Postgres, Redis'))
    })

    test('marks skipped questions with question IDs', () => {
      const states: Record<string, QuestionAnswerState> = {
        q1: { selectedOptions: [], otherText: '', otherSelected: false, skipped: true },
        q2: { selectedOptions: ['Postgres'], otherText: '', otherSelected: false, skipped: false }
      }
      const result = formatClarifyAnswerMessage(questions, states)
      assert.ok(result.includes('**q1 — Auth**: _(skipped)_'))
      assert.ok(result.includes('**q2 — DB**: Postgres'))
    })

    test('includes Other text with question IDs', () => {
      const states: Record<string, QuestionAnswerState> = {
        q1: { selectedOptions: [], otherText: 'Custom JWT', otherSelected: true, skipped: false },
        q2: { selectedOptions: ['Postgres'], otherText: 'DynamoDB', otherSelected: true, skipped: false }
      }
      const result = formatClarifyAnswerMessage(questions, states)
      assert.ok(result.includes('**q1 — Auth**: Custom JWT'))
      assert.ok(result.includes('**q2 — DB**: Postgres, DynamoDB'))
    })

    test('handles missing state as skipped', () => {
      const result = formatClarifyAnswerMessage(questions, {})
      assert.ok(result.includes('_(skipped)_'))
    })
  })

  // ── deduplicateClarifyQuestions ──

  describe('deduplicateClarifyQuestions', () => {
    const q1: ClarifyQuestion = { id: 'q1', header: 'Auth', question: 'Which auth?', multiSelect: false, options: [] }
    const q2: ClarifyQuestion = { id: 'q2', header: 'DB', question: 'Which DB?', multiSelect: false, options: [] }
    const q3: ClarifyQuestion = { id: 'q3', header: 'Cache', question: 'Which cache?', multiSelect: false, options: [] }

    test('removes exact duplicates (same id + question)', () => {
      const result = deduplicateClarifyQuestions([q1, q2, q3], [q1, q2])
      assert.equal(result.length, 1)
      assert.equal(result[0].id, 'q3')
    })

    test('keeps all when no overlap', () => {
      const result = deduplicateClarifyQuestions([q2, q3], [q1])
      assert.equal(result.length, 2)
    })

    test('returns empty when all are duplicates', () => {
      const result = deduplicateClarifyQuestions([q1, q2], [q1, q2])
      assert.equal(result.length, 0)
    })

    test('returns all when no previous', () => {
      const result = deduplicateClarifyQuestions([q1, q2], [])
      assert.equal(result.length, 2)
    })
  })
})

/**
 * Tests for blueprint-spec.service.ts gate logic.
 * Verifies: completion → gate (not finalize); proceed → finalize+dispatch; iterate; cancelled guard.
 */

import assert from 'node:assert/strict'
import { test, describe } from './test-harness'

// We test the parsers-level logic directly (service requires too many dependencies for unit test)
import {
  parseClarifyFindings,
  parseClarifyQuestions,
  parseClarifyCompletion,
  stripBlueprintBlocks
} from '../../../shared/blueprint-clarify-parsers'

describe('blueprint-clarify-gate-logic', () => {
  describe('turn-end resolution logic', () => {
    // Simulates the handleClarifyTurnEnd decision tree

    test('completion block → gate signal (not finalize)', () => {
      const text = `Some analysis.

\`\`\`blueprint-clarify-findings
{"findings": [{"id": "f1", "category": "security_gaps", "severity": "high", "status": "resolved", "title": "T", "description": "D", "specRefs": [], "recommendation": "R"}], "summary": "All clear"}
\`\`\`

\`\`\`blueprint-phase-complete
{"phase": "clarify", "status": "complete", "questionsAsked": 2, "questionsAnswered": 2, "coverageSummary": {"resolved": 1, "deferred": 0, "outstanding": 0, "clear": 8}}
\`\`\``

      const findings = parseClarifyFindings(text)
      const questions = parseClarifyQuestions(text)
      const completion = parseClarifyCompletion(text)

      assert.ok(findings, 'findings should be parsed')
      assert.equal(questions, null, 'no questions when completion present')
      assert.ok(completion, 'completion should be parsed')
      assert.equal(completion.status, 'complete')

      // Decision: completion present → store in gate, don't finalize immediately
      // This is the key distinction from the old flow
    })

    test('questions block → question signal (not awaitingInput)', () => {
      const text = `Analysis found gaps.

\`\`\`blueprint-clarify-findings
{"findings": [{"id": "f1", "category": "missing_requirements", "severity": "critical", "status": "outstanding", "title": "No auth", "description": "D", "specRefs": [], "recommendation": "R"}], "summary": "1 critical"}
\`\`\`

\`\`\`blueprint-clarify-questions
{"questions": [{"id": "q1", "header": "Auth", "question": "Which auth?", "multiSelect": false, "options": [{"label": "OAuth2", "recommended": true, "recommendedReason": "Standard"}]}]}
\`\`\``

      const findings = parseClarifyFindings(text)
      const questions = parseClarifyQuestions(text)
      const completion = parseClarifyCompletion(text)

      assert.ok(findings, 'findings should be parsed')
      assert.ok(questions, 'questions should be parsed')
      assert.equal(questions.questions.length, 1)
      assert.equal(completion, null, 'no completion yet')

      // Decision: questions present & no completion → emit questions (not awaitingInput)
    })

    test('no structured blocks → fallback awaitingInput', () => {
      const text = `The agent produced only prose without structured blocks.
Some analysis text here but no fenced JSON.`

      const findings = parseClarifyFindings(text)
      const questions = parseClarifyQuestions(text)
      const completion = parseClarifyCompletion(text)

      assert.equal(findings, null)
      assert.equal(questions, null)
      assert.equal(completion, null)

      // Decision: nothing parsed → emit clarifyAwaitingInput as fallback
    })

    test('questions beat awaitingInput regardless of event order', () => {
      // If both could arrive (shouldn't happen, but guard):
      // The presence of questions should override awaitingInput
      const text = `\`\`\`blueprint-clarify-questions
{"questions": [{"id": "q1", "header": "H", "question": "Q?", "multiSelect": false, "options": [{"label": "A", "recommended": true}]}]}
\`\`\``

      const questions = parseClarifyQuestions(text)
      assert.ok(questions)
      assert.equal(questions.questions.length, 1)
      // In the store: setting clarifyQuestions also sets clarifyAwaitingInput = false
    })
  })

  describe('findings status tracking', () => {
    test('findings status updates across rounds', () => {
      // Round 1: one outstanding
      const round1 = `\`\`\`blueprint-clarify-findings
{"findings": [{"id": "f1", "category": "security_gaps", "severity": "high", "status": "outstanding", "title": "Auth", "description": "D", "specRefs": [], "recommendation": "R"}], "summary": "1 outstanding"}
\`\`\``

      // Round 2: resolved
      const round2 = `\`\`\`blueprint-clarify-findings
{"findings": [{"id": "f1", "category": "security_gaps", "severity": "high", "status": "resolved", "title": "Auth", "description": "D", "specRefs": [], "recommendation": "R"}], "summary": "0 outstanding"}
\`\`\``

      const r1 = parseClarifyFindings(round1)
      const r2 = parseClarifyFindings(round2)

      assert.ok(r1)
      assert.equal(r1.findings[0].status, 'outstanding')

      assert.ok(r2)
      assert.equal(r2.findings[0].status, 'resolved')
      assert.equal(r2.findings[0].id, 'f1') // Same ID across rounds
    })
  })

  describe('race-fix regression', () => {
    test('method-local variables prevent cross-workspace dispatch', () => {
      // Simulate the pattern: two concurrent calls should not share state
      // This tests the conceptual fix — method-local vars are scoped to the call.
      let dispatch1: string | null = null
      let dispatch2: string | null = null

      // Simulate call 1
      ;(async () => {
        let pending: { id: string } | null = null
        // success path sets it
        pending = { id: 'workspace-A' }
        // finally reads it
        dispatch1 = pending?.id ?? null
      })()

      // Simulate call 2
      ;(async () => {
        let pending: { id: string } | null = null
        // success path sets it
        pending = { id: 'workspace-B' }
        // finally reads it
        dispatch2 = pending?.id ?? null
      })()

      // Each call has its own variable — no cross-contamination
      assert.equal(dispatch1, 'workspace-A')
      assert.equal(dispatch2, 'workspace-B')
    })
  })

  describe('B1-FIX: completion-only turn preserves prior-round findings', () => {
    test('completion turn without findings uses cached findings from prior round', () => {
      // Round 1: findings emitted (would be cached by service)
      const round1Text = `Analysis found gaps.

\`\`\`blueprint-clarify-findings
{"findings": [{"id": "f1", "category": "security_gaps", "severity": "high", "status": "outstanding", "title": "Auth missing", "description": "D", "specRefs": [], "recommendation": "R"}], "summary": "1 outstanding"}
\`\`\`

\`\`\`blueprint-clarify-questions
{"questions": [{"id": "q1", "header": "Auth", "question": "Which auth?", "multiSelect": false, "options": [{"label": "OAuth2", "recommended": true}]}]}
\`\`\``

      const r1Findings = parseClarifyFindings(round1Text)
      assert.ok(r1Findings, 'Round 1 should have findings')
      assert.equal(r1Findings.findings.length, 1)

      // Round 2: completion turn — model omits findings block
      const round2Text = `All questions answered. Proceeding.

\`\`\`blueprint-phase-complete
{"phase": "clarify", "status": "complete", "questionsAsked": 1, "questionsAnswered": 1}
\`\`\``

      const r2Findings = parseClarifyFindings(round2Text)
      const r2Completion = parseClarifyCompletion(round2Text)

      assert.equal(r2Findings, null, 'Round 2 should have NO findings in text')
      assert.ok(r2Completion, 'Round 2 should have completion')

      // Simulate B1-FIX logic: use cached findings when current round has none
      const gateFindings = r2Findings ?? r1Findings ?? null
      assert.ok(gateFindings, 'Gate should use cached findings from round 1')
      assert.equal(gateFindings!.findings[0].id, 'f1')
      assert.equal(gateFindings!.findings[0].title, 'Auth missing')
    })

    test('null findings in gate payload should not wipe existing findings (store guard)', () => {
      // Simulates the B1-FIX store logic:
      // clarifyFindings: (incomingFindings ?? existingFindings)
      const existingFindings = {
        findings: [{
          id: 'f1',
          category: 'security_gaps' as const,
          severity: 'high' as const,
          status: 'resolved' as const,
          title: 'Auth',
          description: 'D',
          specRefs: [],
          recommendation: 'R'
        }],
        summary: 'All resolved'
      }

      const incomingFindings = null
      const result = incomingFindings ?? existingFindings

      assert.ok(result, 'Result should preserve existing findings')
      assert.equal(result.findings.length, 1)
      assert.equal(result.findings[0].id, 'f1')
    })
  })

  describe('strip function preserves prose', () => {
    test('strips blocks but keeps surrounding prose intact', () => {
      const text = `Here is my analysis.

\`\`\`blueprint-clarify-findings
{"findings": [], "summary": "none"}
\`\`\`

Based on the above, I have questions.

\`\`\`blueprint-clarify-questions
{"questions": []}
\`\`\`

That concludes the round.`

      const stripped = stripBlueprintBlocks(text)
      assert.ok(stripped.includes('Here is my analysis.'))
      assert.ok(stripped.includes('Based on the above, I have questions.'))
      assert.ok(stripped.includes('That concludes the round.'))
      assert.ok(!stripped.includes('blueprint-clarify-findings'))
      assert.ok(!stripped.includes('blueprint-clarify-questions'))
    })
  })
})

/**
 * BlueprintStateMachine — transition table unit tests.
 *
 * Validates: valid transitions, invalid transitions (rejected),
 * idempotent-when-idle, forceReset, context management, and
 * stateChange event emission.
 */

import assert from 'node:assert/strict'
import { describe, test } from './test-harness'
import {
  BlueprintStateMachine,
  type BlueprintStateChangePayload
} from '../blueprint-state-machine'

/** Fresh machine per test — avoids async test runner clobbering. */
function make(wsId = 'ws-test'): BlueprintStateMachine {
  return new BlueprintStateMachine(wsId)
}

describe('BlueprintStateMachine', () => {
  // ── Initial State ──

  test('starts in idle state', () => {
    const sm = make()
    assert.equal(sm.currentState, 'idle')
    assert.equal(sm.blueprintId, null)
    assert.equal(sm.phase, null)
    assert.equal(sm.workspaceId, 'ws-test')
  })

  test('isIdle() returns true initially', () => {
    const sm = make()
    assert.equal(sm.isIdle(), true)
    assert.equal(sm.isRunning(), false)
    assert.equal(sm.isAwaitingInput(), false)
    assert.equal(sm.isTerminal(), false)
  })

  // ── Valid Transitions: Happy Path ──

  test('idle → startPhase → phase-running', () => {
    const sm = make()
    const result = sm.transition('startPhase', { blueprintId: 'bp-1', phase: 'specify' })
    assert.equal(result, true)
    assert.equal(sm.currentState, 'phase-running')
    assert.equal(sm.blueprintId, 'bp-1')
    assert.equal(sm.phase, 'specify')
    assert.equal(sm.isRunning(), true)
  })

  test('phase-running → phaseComplete → idle', () => {
    const sm = make()
    sm.transition('startPhase', { blueprintId: 'bp-1', phase: 'specify' })
    const result = sm.transition('phaseComplete')
    assert.equal(result, true)
    assert.equal(sm.currentState, 'idle')
    assert.equal(sm.blueprintId, null)
    assert.equal(sm.phase, null)
  })

  test('full specify → clarify → plan phase chain', () => {
    const sm = make()
    // specify starts
    sm.transition('startPhase', { blueprintId: 'bp-1', phase: 'specify' })
    assert.equal(sm.currentState, 'phase-running')

    // specify completes
    sm.transition('phaseComplete')
    assert.equal(sm.currentState, 'idle')

    // clarify starts
    sm.transition('startPhase', { blueprintId: 'bp-1', phase: 'clarify' })
    assert.equal(sm.currentState, 'phase-running')
    assert.equal(sm.phase, 'clarify')

    // questions parsed
    sm.transition('questionsParsed')
    assert.equal(sm.currentState, 'awaiting-clarify-questions')

    // answer received
    sm.transition('answerReceived')
    assert.equal(sm.currentState, 'phase-running')

    // gate parsed (completion)
    sm.transition('gateParsed')
    assert.equal(sm.currentState, 'awaiting-clarify-gate')

    // proceed to plan
    sm.transition('proceedGate')
    assert.equal(sm.currentState, 'idle')

    // plan starts
    sm.transition('startPhase', { blueprintId: 'bp-1', phase: 'plan' })
    assert.equal(sm.currentState, 'phase-running')
    assert.equal(sm.phase, 'plan')
  })

  // ── Clarify Sub-States ──

  test('phase-running → questionsParsed → awaiting-clarify-questions', () => {
    const sm = make()
    sm.transition('startPhase', { blueprintId: 'bp-1', phase: 'clarify' })
    const result = sm.transition('questionsParsed')
    assert.equal(result, true)
    assert.equal(sm.currentState, 'awaiting-clarify-questions')
    assert.equal(sm.isClarifyState(), true)
    assert.equal(sm.isAwaitingInput(), true)
  })

  test('phase-running → awaitingInput → awaiting-clarify-input', () => {
    const sm = make()
    sm.transition('startPhase', { blueprintId: 'bp-1', phase: 'clarify' })
    const result = sm.transition('awaitingInput')
    assert.equal(result, true)
    assert.equal(sm.currentState, 'awaiting-clarify-input')
    assert.equal(sm.isClarifyState(), true)
  })

  test('phase-running → gateParsed → awaiting-clarify-gate', () => {
    const sm = make()
    sm.transition('startPhase', { blueprintId: 'bp-1', phase: 'clarify' })
    const result = sm.transition('gateParsed')
    assert.equal(result, true)
    assert.equal(sm.currentState, 'awaiting-clarify-gate')
    assert.equal(sm.isClarifyState(), true)
  })

  test('awaiting-clarify-gate → iterate → phase-running (more clarify)', () => {
    const sm = make()
    sm.transition('startPhase', { blueprintId: 'bp-1', phase: 'clarify' })
    sm.transition('gateParsed')
    const result = sm.transition('iterate')
    assert.equal(result, true)
    assert.equal(sm.currentState, 'phase-running')
  })

  test('awaiting-clarify-gate → proceedGate → idle', () => {
    const sm = make()
    sm.transition('startPhase', { blueprintId: 'bp-1', phase: 'clarify' })
    sm.transition('gateParsed')
    const result = sm.transition('proceedGate')
    assert.equal(result, true)
    assert.equal(sm.currentState, 'idle')
    assert.equal(sm.blueprintId, null)
  })

  // ── Approval Flow ──

  test('phase-running → approvalNeeded → awaiting-approval', () => {
    const sm = make()
    sm.transition('startPhase', { blueprintId: 'bp-1', phase: 'review' })
    const result = sm.transition('approvalNeeded')
    assert.equal(result, true)
    assert.equal(sm.currentState, 'awaiting-approval')
    assert.equal(sm.isAwaitingInput(), true)
    assert.equal(sm.isClarifyState(), false)
  })

  test('awaiting-approval → approvalResponded → idle', () => {
    const sm = make()
    sm.transition('startPhase', { blueprintId: 'bp-1', phase: 'review' })
    sm.transition('approvalNeeded')
