/**
 * Blueprint Journal → Chat Message mapper.
 *
 * Converts journal events from the blueprint_events table into
 * BlueprintChatMessage-compatible records for transcript hydration.
 *
 * This module is shared between main and renderer processes.
 * It's pure — no DOM, Electron, or store dependencies.
 */

import { stripBlueprintBlocks } from './blueprint-clarify-parsers'
import type {
  ClarifyFindingsBlock,
  ClarifyQuestion,
  QuestionAnswerState
} from './blueprint-clarify-parsers'
import { parseBlueprintPlan, parseBlueprintTasks } from './blueprint-artifact-parsers'
import type { ToolActivity } from './types'

// ── Types ──

/** Event shape from blueprint_events table (matches BlueprintEvent) */
export interface JournalEvent {
  id: string
  blueprintId: string
  seq: number
  type: string // 'system' | 'agent' | 'user' | 'findings' | 'qa' | 'plan' | 'tasks'
  payload: Record<string, unknown>
  createdAt: string
}

// Uses the real ToolActivity type from shared/types so HydratedChatMessage
// is directly assignable to BlueprintChatMessage (matching status union).

/**
 * Chat message types matching BlueprintChatMessage from blueprint.store.ts.
 * Reproduced here to avoid circular dependency with renderer store.
 */
export type HydratedChatMessage =
  | { type: 'agent'; content: string; toolActivities: ToolActivity[]; timestamp: number }
  | { type: 'user'; content: string; timestamp: number }
  | { type: 'system'; content: string; timestamp: number }
  | { type: 'findings'; findings: ClarifyFindingsBlock; round: number; timestamp: number }
  | { type: 'qa'; questions: ClarifyQuestion[]; answers: Record<string, QuestionAnswerState>; timestamp: number }
  | { type: 'plan'; plan: Record<string, unknown>; timestamp: number }
  | { type: 'tasks'; tasks: Record<string, unknown>; timestamp: number }

// ── Mapper ──

/**
 * Pure mapper: converts journal events into chat messages for transcript display.
 *
 * Handles:
 * - system events (phaseStart, phaseComplete, waveStart, waveComplete)
 * - findings events (derives round from count of prior findings)
 * - qa events (questions paired with immediately-following user answers)
 * - plan/tasks events (parses contentMd or uses contentJson)
 * - agent events (with toolActivities when present)
 * - user events (free-text clarify answers)
 *
 * Exported and pure for unit testing.
 */
/** Maximum events to hydrate — prevents huge transcripts from freezing the renderer. */
export const HYDRATION_EVENT_CAP = 2000

export function journalEventsToChatMessages(events: JournalEvent[]): HydratedChatMessage[] {
  // Hydration cap: take only the last N events + prepend truncation marker
  let truncated = false
  let capped = events
  if (events.length > HYDRATION_EVENT_CAP) {
    truncated = true
    capped = events.slice(events.length - HYDRATION_EVENT_CAP)
  }

  const messages: HydratedChatMessage[] = []
  if (truncated) {
    // MINOR-FIX: Apply same isNaN guard as the main event loop to prevent
    // NaN timestamp on the truncation marker from unparseable createdAt.
    const markerTs = capped.length > 0 ? new Date(capped[0].createdAt).getTime() : Date.now()
    messages.push({
      type: 'system',
      content: `… ${events.length - HYDRATION_EVENT_CAP} earlier events omitted`,
      timestamp: isNaN(markerTs) ? Date.now() : markerTs
    })
  }
  let findingsRound = 0

  // GAP-7: Pre-index phases that have accumulator-style agent entries
  // (those with toolActivities key). When present, skip non-accumulator
  // agent events (artifactType-bearing) to avoid duplicate bubbles.
  const phasesWithAccumulatorAgents = new Set<string>()
  for (const ev of capped) {
    if (ev.type === 'agent' && ev.payload.toolActivities) {
      const phase = ev.payload.phase as string | undefined
      if (phase) phasesWithAccumulatorAgents.add(phase)
    }
  }

  // Pre-index: build a map of qa-seq → next-user-events for answer pairing
  const userAnswersByQaSeq = new Map<number, JournalEvent[]>()
  for (let i = 0; i < capped.length; i++) {
    if (capped[i].type === 'qa' && capped[i].payload.questions) {
      // Collect immediately-following 'user' events as answers
      const answers: JournalEvent[] = []
      for (let j = i + 1; j < capped.length; j++) {
        if (capped[j].type === 'user') {
          answers.push(capped[j])
        } else {
          break // stop at first non-user event
        }
      }
      if (answers.length > 0) {
        userAnswersByQaSeq.set(capped[i].seq, answers)
      }
    }
  }

  // Track which user events were consumed as qa answers (skip them in main loop)
  const consumedUserSeqs = new Set<number>()
  for (const answers of userAnswersByQaSeq.values()) {
    for (const a of answers) consumedUserSeqs.add(a.seq)
  }

  for (const event of capped) {
    // MINOR-FIX: Guard against unparseable SQLite created_at formats
    const parsed = new Date(event.createdAt).getTime()
    const ts = isNaN(parsed) ? Date.now() : parsed
    const p = event.payload

    switch (event.type) {
      case 'system': {
        const ev = p.event as string | undefined
        if (ev === 'phaseStart') {
          const phase = (p.phase as string) ?? 'unknown'
          const phaseLabel = phase.charAt(0).toUpperCase() + phase.slice(1)
          messages.push({ type: 'system', content: `${phaseLabel} phase started`, timestamp: ts })
        } else if (ev === 'phaseComplete') {
          const phase = (p.phase as string) ?? 'unknown'
          const phaseLabel = phase.charAt(0).toUpperCase() + phase.slice(1)
          const status = (p.status as string) ?? 'complete'
          messages.push({ type: 'system', content: `${phaseLabel} phase ${status}`, timestamp: ts })
        } else if (ev === 'waveStart') {
          const wave = p.wave as number ?? 0
          const taskCount = p.taskCount as number ?? 0
          messages.push({ type: 'system', content: `Wave ${wave} started — ${taskCount} tasks`, timestamp: ts })
        } else if (ev === 'waveComplete') {
          const wave = p.wave as number ?? 0
          messages.push({ type: 'system', content: `Wave ${wave} complete`, timestamp: ts })
        } else {
          // Generic system message (e.g. future event types)
          messages.push({ type: 'system', content: String(p.message ?? p.event ?? 'System event'), timestamp: ts })
        }
        break
      }

      case 'findings': {
        findingsRound++
        const findings = p.findings as ClarifyFindingsBlock
        if (findings) {
          messages.push({ type: 'findings', findings, round: findingsRound, timestamp: ts })
        }
        break
      }

      case 'qa': {
        const questions = p.questions as ClarifyQuestion[] | undefined
        if (questions) {
          // Try to pair with user answers
          const pairedAnswers = userAnswersByQaSeq.get(event.seq)
          const answersRecord: Record<string, QuestionAnswerState> = {}
          if (pairedAnswers?.length) {
            // Best-effort: if single user message, map it as free-text for all questions
            // If multiple, pair by index
            for (let qi = 0; qi < questions.length; qi++) {
              const q = questions[qi]
              const qId = q.id ?? `q-${qi}`
              const answerEvent = pairedAnswers[Math.min(qi, pairedAnswers.length - 1)]
              const message = (answerEvent.payload.message as string) ?? ''
              answersRecord[qId] = {
                selectedOptions: [],
                otherText: message,
                otherSelected: true,
                skipped: false
              }
            }
          }
          messages.push({ type: 'qa', questions, answers: answersRecord, timestamp: ts })
        } else if (p.event === 'gateReady') {
          // Gate-ready marker — render as system message
          messages.push({ type: 'system', content: 'Clarify gate ready — review findings before proceeding', timestamp: ts })
        }
        break
      }

      case 'plan': {
        const contentJson = p.contentJson as Record<string, unknown> | undefined
        const contentMd = p.contentMd as string | undefined
        const plan = contentJson ?? (contentMd ? parseBlueprintPlan(contentMd) : null) ?? {}
        messages.push({ type: 'plan', plan, timestamp: ts })
        break
      }

      case 'tasks': {
        const contentJson = p.contentJson as Record<string, unknown> | undefined
        const contentMd = p.contentMd as string | undefined
        const tasks = contentJson ?? (contentMd ? parseBlueprintTasks(contentMd) : null) ?? {}
        messages.push({ type: 'tasks', tasks, timestamp: ts })
        break
      }

      case 'agent': {
        // GAP-7: Skip artifact-type agent entries when same phase has
        // accumulator-style entries (which already carry the same content).
        const agentPhase = p.phase as string | undefined
        if (p.artifactType && agentPhase && phasesWithAccumulatorAgents.has(agentPhase)) {
          break // duplicate — accumulator entry already journals this content
        }
        const content = (p.contentMd as string) || (p.content as string) || ''
        const toolActivities = (p.toolActivities as ToolActivity[]) ?? []
        if (content.trim() || toolActivities.length > 0) {
          messages.push({ type: 'agent', content: stripBlueprintBlocks(content), toolActivities, timestamp: ts })
        }
        break
      }

      case 'user': {
        // Skip user events that were consumed as qa answers
        if (consumedUserSeqs.has(event.seq)) break
        const message = (p.message as string) ?? ''
        if (message.trim()) {
          messages.push({ type: 'user', content: message, timestamp: ts })
        }
        break
      }

      default:
        // Unknown event type — skip silently (forward compat)
        break
    }
  }

  return messages
}

/**
 * Pure helpers for blueprint transcript hydration decisions.
 *
 * Extracted from blueprint.store.ts for unit testing.
 * No store, DOM, or Electron dependencies.
 */

/**
 * Possible pre-fetch actions for hydrateTranscript to take.
 *
 * - 'skip'              — already hydrated (with messages) or in-flight, do nothing
 * - 'clear-then-apply'  — chatMessages belong to a different BP, clear first then fetch
 * - 'apply'             — no live messages present, fetch and apply
 *
 * Post-fetch merge/apply is handled by `resolvePostFetchAction`.
 */
export type HydrationAction = 'skip' | 'clear-then-apply' | 'apply'

/**
 * Determine what hydrateTranscript should do given the current state.
 *
 * @param liveCount      - current chatMessages.length
 * @param currentBpId    - currentBlueprint?.id (may be null)
 * @param targetBpId     - the blueprintId being hydrated
 * @param hydratedBpId   - module-level sentinel (which BP was last hydrated)
 * @param inFlight       - whether a hydration fetch is already in progress for targetBpId
 */
export function resolveHydrationAction(
  liveCount: number,
  currentBpId: string | null,
  targetBpId: string,
  hydratedBpId: string | null,
  inFlight: boolean
): HydrationAction {
  // Another hydration for this BP is already in-flight (StrictMode / race guard)
  if (inFlight) return 'skip'

  // Already hydrated for this exact blueprint AND messages still present.
  // If liveCount is 0 despite sentinel match, the transcript was blown away
  // by startBlueprint/cancelBlueprint/retryPhase — must re-hydrate.
  if (hydratedBpId === targetBpId && liveCount > 0) return 'skip'

  // CRITICAL-1: chatMessages belong to a different blueprint (live-watched or
  // previously hydrated) — must clear before applying new data.
  if (liveCount > 0 && currentBpId !== targetBpId) return 'clear-then-apply'

  // Live messages exist for THIS blueprint (IPC events arrived first) — skip
  // (the live stream is authoritative; hydration is unnecessary).
  if (liveCount > 0 && currentBpId === targetBpId) return 'skip'

  // No live messages — clean apply (normal historical view path, or
  // re-hydrate after transcript was cleared with sentinel still set).
  return 'apply'
}

/**
 * After-fetch decision: should we merge or clean-apply?
 * Called after the async fetch completes — liveMessages may have arrived
 * during the fetch (restart-during-active-run race).
 *
 * @param liveCountAfterFetch - chatMessages.length after the fetch
 */
export function resolvePostFetchAction(
  liveCountAfterFetch: number
): 'apply' | 'merge' {
  return liveCountAfterFetch === 0 ? 'apply' : 'merge'
}

/**
 * Pure helper for resolving human-review banner state.
 *
 * Extracted to src/shared/ so it's testable from the main test harness
 * (same pattern as blueprint-hydration-helpers).
 */

export type VerifyBannerState = 'human-review' | 'acknowledged' | 'none'

/**
 * Determines what the verify banner should display:
 * - 'human-review': unacknowledged human_needed → show banner with Mark as Verified button
 * - 'acknowledged': human_needed + acknowledged → show slim success note
 * - 'none': any other verify status (passed, gaps_found, null) → no human-review banner
 */
export function resolveVerifyBannerState(
  verifyStatus: string | null | undefined,
  humanReviewAcknowledged: boolean
): VerifyBannerState {
  if (verifyStatus !== 'human_needed') return 'none'
  return humanReviewAcknowledged ? 'acknowledged' : 'human-review'
}

/**
 * Blueprint Agent Accumulator tests — flush boundaries, caps, cancel cleanup,
 * taskId key isolation.
 *
 * Run: npx tsx src/main/services/__tests__/blueprint-agent-accumulator.test.ts
 */

import assert from 'node:assert/strict'
import { test, describe, summaryAsync } from './test-harness'
import {
  createAccumulator,
  AGENT_ENTRY_CHAR_CAP,
  AGENT_PHASE_CHAR_CAP,
  type JournalAppendFn
} from '../blueprint-agent-accumulator'

// ── Helpers ──

interface JournalEntry {
  blueprintId: string
  type: string
  payload: Record<string, unknown>
}

function createTestAccumulator() {
  const journal: JournalEntry[] = []
  const appendFn: JournalAppendFn = (blueprintId, type, payload) => {
    journal.push({ blueprintId, type, payload })
  }
  const acc = createAccumulator(appendFn)
  return { acc, journal }
}

// ── Tests ──

describe('createAccumulator', () => {
  // ── Text accumulation + flush ──

  test('text chunks accumulate until flush', () => {
    const { acc, journal } = createTestAccumulator()
    acc.handleChunk('bp-1', 'specify', undefined, 'Hello ')
    acc.handleChunk('bp-1', 'specify', undefined, 'world')
    assert.equal(journal.length, 0, 'No flush yet')

    acc.flush('bp-1', 'specify')
    assert.equal(journal.length, 1)
    assert.equal(journal[0].payload.content, 'Hello world')
    assert.equal(journal[0].payload.phase, 'specify')
    assert.equal(journal[0].type, 'agent')
  })

  // ── Text-boundary flush on tool event ──

  test('tool event flushes accumulated text first', () => {
    const { acc, journal } = createTestAccumulator()
    acc.handleChunk('bp-1', 'build', undefined, 'Some analysis...')
    acc.handleChunk('bp-1', 'build', 'tool', undefined, { toolName: 'Read', id: 't1' })

    // Text should have been flushed
    assert.equal(journal.length, 1)
    assert.equal(journal[0].payload.content, 'Some analysis...')
    // Tool activity should be in the accumulator (not yet flushed)
    const accState = acc.getAccumulator('bp-1', 'build')
    assert.equal(accState.toolActivities.length, 1)
  })

  test('tool event with no prior text does not flush', () => {
    const { acc, journal } = createTestAccumulator()
    acc.handleChunk('bp-1', 'build', 'tool', undefined, { toolName: 'Read', id: 't1' })
    assert.equal(journal.length, 0, 'No flush for tool-only')
    // But tool activity is recorded
    const accState = acc.getAccumulator('bp-1', 'build')
    assert.equal(accState.toolActivities.length, 1)
  })

  test('flush includes tool activities accumulated after text flush', () => {
    const { acc, journal } = createTestAccumulator()
    // Text → tool (flushes text) → more text → flush
    acc.handleChunk('bp-1', 'build', undefined, 'Analysis text')
    acc.handleChunk('bp-1', 'build', 'tool', undefined, { toolName: 'Read', id: 't1' })
    // journal[0] = text flush
    acc.handleChunk('bp-1', 'build', undefined, 'More analysis')
    acc.flush('bp-1', 'build')
    // journal[1] = second flush with tool activity from prior boundary
    assert.equal(journal.length, 2)
    assert.equal(journal[1].payload.content, 'More analysis')
    assert.deepEqual(journal[1].payload.toolActivities, [{ toolName: 'Read', id: 't1' }])
  })

  // ── 32KB entry cap ──

  test('entry text is capped at AGENT_ENTRY_CHAR_CAP', () => {
    const { acc, journal } = createTestAccumulator()
    const bigText = 'X'.repeat(AGENT_ENTRY_CHAR_CAP + 1000)
    acc.handleChunk('bp-1', 'specify', undefined, bigText)
    acc.flush('bp-1', 'specify')
    assert.equal(journal.length, 1)
    const content = journal[0].payload.content as string
    assert.ok(content.length <= AGENT_ENTRY_CHAR_CAP + 100, 'Content should be capped near entry limit')
    assert.ok(content.includes('[… truncated at 32KB]'), 'Should include truncation marker')
  })

  // ── 1MB phase cap ──

  test('entries exceeding phase cap are silently dropped', () => {
    const { acc, journal } = createTestAccumulator()
    // Fill up to phase cap
    const chunkSize = AGENT_ENTRY_CHAR_CAP // 32KB per flush
    const numFlushes = Math.ceil(AGENT_PHASE_CHAR_CAP / chunkSize) + 5 // exceed cap
    for (let i = 0; i < numFlushes; i++) {
      acc.handleChunk('bp-1', 'build', undefined, 'A'.repeat(chunkSize))
      acc.flush('bp-1', 'build')
    }
    // Should have fewer entries than numFlushes (some dropped by cap)
    const totalChars = journal.reduce((sum, e) => sum + ((e.payload.content as string)?.length ?? 0), 0)
    assert.ok(totalChars <= AGENT_PHASE_CHAR_CAP + AGENT_ENTRY_CHAR_CAP,
      `Total chars (${totalChars}) should not greatly exceed phase cap`)
  })

  // ── flushAllForBlueprint (cancel cleanup) ──

  test('flushAllForBlueprint flushes all keys for a blueprint', () => {
    const { acc, journal } = createTestAccumulator()
    acc.handleChunk('bp-1', 'build', undefined, 'text-1', undefined, 'task-A')
    acc.handleChunk('bp-1', 'build', undefined, 'text-2', undefined, 'task-B')
    acc.handleChunk('bp-1', 'verify', undefined, 'verify-text')
    acc.handleChunk('bp-2', 'build', undefined, 'other-bp') // different blueprint

    acc.flushAllForBlueprint('bp-1')
    // Should flush 3 entries for bp-1
    assert.equal(journal.length, 3)
    assert.ok(journal.every(e => e.blueprintId === 'bp-1'), 'All entries should be for bp-1')
    // bp-2 accumulator should still exist
    const bp2Acc = acc.getAccumulator('bp-2', 'build')
    assert.equal(bp2Acc.text, 'other-bp')
  })

  // ── taskId key isolation ──

  test('different taskIds maintain separate accumulators', () => {
    const { acc, journal } = createTestAccumulator()
    acc.handleChunk('bp-1', 'build', undefined, 'task-A content', undefined, 'task-A')
    acc.handleChunk('bp-1', 'build', undefined, 'task-B content', undefined, 'task-B')

    acc.flush('bp-1', 'build', 'task-A')
    assert.equal(journal.length, 1)
    assert.equal(journal[0].payload.content, 'task-A content')
    assert.equal(journal[0].payload.taskId, 'task-A')

    acc.flush('bp-1', 'build', 'task-B')
    assert.equal(journal.length, 2)
    assert.equal(journal[1].payload.content, 'task-B content')
    assert.equal(journal[1].payload.taskId, 'task-B')
  })

  test('flush without taskId does not include taskId in payload', () => {
    const { acc, journal } = createTestAccumulator()
    acc.handleChunk('bp-1', 'specify', undefined, 'no-task content')
    acc.flush('bp-1', 'specify')
    assert.equal(journal.length, 1)
    assert.equal(journal[0].payload.taskId, undefined)
  })

  // ── flushAllForPhase ──

  test('flushAllForPhase flushes all taskId variants for a phase', () => {
    const { acc, journal } = createTestAccumulator()
    acc.handleChunk('bp-1', 'build', undefined, 'lane-1', undefined, 'task-1')
    acc.handleChunk('bp-1', 'build', undefined, 'lane-2', undefined, 'task-2')
    acc.handleChunk('bp-1', 'build', undefined, 'no-task')
    acc.handleChunk('bp-1', 'verify', undefined, 'verify-text') // different phase

    acc.flushAllForPhase('bp-1', 'build')
    assert.equal(journal.length, 3) // 3 build entries
    assert.ok(journal.every(e => e.payload.phase === 'build'))

    // verify accumulator should still have content
    const verifyAcc = acc.getAccumulator('bp-1', 'verify')
    assert.equal(verifyAcc.text, 'verify-text')
  })

  // ── Empty accumulator flush is a no-op ──

  test('flushing empty accumulator produces no journal entry', () => {
    const { acc, journal } = createTestAccumulator()
    acc.flush('bp-1', 'specify')
    assert.equal(journal.length, 0)
  })

  test('flushing whitespace-only text with no tools produces no journal entry', () => {
    const { acc, journal } = createTestAccumulator()
    acc.handleChunk('bp-1', 'specify', undefined, '   \n  ')
    acc.flush('bp-1', 'specify')
    assert.equal(journal.length, 0)
  })

  test('flushing whitespace-only text WITH tools DOES produce journal entry', () => {
    const { acc, journal } = createTestAccumulator()
    acc.handleChunk('bp-1', 'specify', 'tool', undefined, { toolName: 'Read', id: 't1' })
    acc.flush('bp-1', 'specify')
    assert.equal(journal.length, 1)
    assert.deepEqual(journal[0].payload.toolActivities, [{ toolName: 'Read', id: 't1' }])
  })
})

