describe('code-analysis-server — rule severity resolution', () => {
  function resolveRuleSeverity(raw: unknown): 'error' | 'warn' | 'off' {
    return raw === 2 || raw === 'error'
      ? 'error'
      : raw === 1 || raw === 'warn'
        ? 'warn'
        : 'off'
  }

  test('numeric_2_is_error', () => {
