      GRILL_SCORING_RULES = mod.GRILL_SCORING_RULES
      GRILL_SCORING_RULES_LEAN = mod.GRILL_SCORING_RULES_LEAN
      assert.equal(typeof buildReEvalBlock, 'function')
    } catch {
      // skip
    }
  })

  test('buildReEvalBlock_returns_empty_when_no_previous_score', () => {
