// ─────────────────────────────────────────────────────────────────────────────
// §2: CouncilChairmanRoleAdapter — lifecycle deep coverage
// ─────────────────────────────────────────────────────────────────────────────

describe('CouncilChairmanRoleAdapter — lifecycle deep', () => {
